local config = {
  ui_story_1011_10110101_1_dialog_content = "Sesuai permintaan Illumina, kami telah mengantarkan Reinhardt ke Safe Line.",
  ui_story_1011_10110101_2_dialog_content = "Tidak lama kemudian, seorang penyelidik utusan Illumina mendatangiku dan Vice...",
  ui_story_1011_10110101_3_dialog_content = "Hai, Caelestite PlayerName. Aku Intelligence Officer Esien.",
  ui_story_1011_10110101_4_dialog_content = "Aku ingat kau. Kita pernah berbicara lewat Communicator.",
  ui_story_1011_10110101_5_dialog_content = "Ya.",
  ui_story_1011_10110101_6_dialog_content = "Aku datang untuk mengonfirmasi beberapa detail mengenai pengalamanmu di Undercity 80.",
  ui_story_1011_10110101_7_dialog_content = "Semoga kau bisa memberikan informasi yang diminta.",
  ui_story_1011_10110101_8_dialog_content = "Kalau mereka menanyaimu tentang apa yang terjadi di Undercity 80, jawab saja sejujurnya.",
  ui_story_1011_10110101_9_dialog_content = "Aku akan memberitahumu segalanya.",
  ui_story_1011_10110101_10_dialog_content = "Tindakan yang bijak.",
