  ui_story_1011_10110101_12_dialog_content = "Aku pergi ke sana untuk mencari solusi memperbaiki Echo Template Soroz...",
  ui_story_1011_10110101_13_dialog_content = "Aku memberi tahu Esien segalanya.",
  ui_story_1011_10110101_14_dialog_content = "Kukira kau tidak tahu apa pun soal High-Level Eclipsite di dalam Undercity 80?",
  ui_story_1011_10110101_15_dialog_content = "Benar.",
  ui_story_1011_10110101_16_dialog_content = "Bagus. Cukup itu saja untuk saat ini.",
  ui_story_1011_10110101_17_dialog_content = "Terima kasih atas kerja samamu. Kau boleh pergi sekarang.",
  ui_story_1011_10110101_18_dialog_content = "Oke.",
  ui_story_1011_10110101_19_dialog_content = "Ah, satu hal lagi...",
  ui_story_1011_10110101_20_dialog_content = "Ya?",
  ui_story_1011_10110101_21_dialog_content = "Apa yang akan terjadi pada Vice?",
  ui_story_1011_10110101_22_dialog_content = "Konsekuensi atas tindakan Lieutenant Vice akan diputuskan nanti oleh Committee dan Grand Marshal.",
  ui_story_1011_10110101_23_dialog_content = "Sementara dia diskors untuk saat ini.",
  ui_story_1011_10110101_24_dialog_content = "Oh, begitu…",
  ui_story_1011_10110101_25_dialog_content = "Ada lagi?",
  ui_story_1011_10110101_26_dialog_content = "Tidak ada. Itu saja.",
  ui_story_1011_10110101_27_dialog_content = "Kalau begitu, kau boleh pergi.",
  ui_story_1011_10110101_28_dialog_content = "Fiuh, akhirnya...",
  ui_story_1011_10110101_29_dialog_content = "Apakah sudah selesai, PlayerName?",
  ui_story_1011_10110101_30_dialog_content = "Ya. Aku memberi tahu mereka semua yang kuketahui soal Undercity 80.",
  ui_story_1011_10110101_31_dialog_content = "Illumina sangat khawatir dengan masalah ini. Tadi itu hampir seperti interogasi.",
  ui_story_1011_10110101_32_dialog_content = "Prosedur tetaplah prosedur. Maklumi saja.",
  ui_story_1011_10110101_33_dialog_content = "Bagaimana denganmu? Apakah mereka merepotkanmu?",
  ui_story_1011_10110101_34_dialog_content = "Kritik, peringatan... sesuai dugaan.",
  ui_story_1011_10110101_35_dialog_content = "Tapi, belum ada hukuman yang sebenarnya selain skors sementara.",
  ui_story_1011_10110101_36_dialog_content = "Mungkin karena Reinhardt mengeklaim bahwa dia menyetujui operasi ini.",
  ui_story_1011_10110101_37_dialog_content = "Jadi, dia mengaku bertanggung jawab sepenuhnya...",
  ui_story_1011_10110101_38_dialog_content = "Ya...",
  ui_story_1011_10110101_39_dialog_content = "Aku harus berterima kasih kepadanya kalau kami bertemu lagi lain kali.",
  ui_story_1011_10110101_40_dialog_content = "Aku masih mengkhawatirkan cederanya.",
  ui_story_1011_10110101_41_dialog_content = "Baginya, kehilangan kesempatan lain untuk menyelamatkan temannya mungkin lebih tak tertahankan ketimbang cederanya.",
  ui_story_1011_10110101_42_dialog_content = "...",
  ui_story_1011_10110101_43_dialog_content = "Omong-omong, aku ingat Reinhardt bilang...",
