  ui_story_1011_10110101_45_dialog_content = "Dan orang yang memberikan intel itu adalah...",
  ui_story_1011_10110101_46_option_content = "Committee.",
  ui_story_1011_10110101_47_dialog_content = "Dan orang-orang yang mencegahnya untuk kembali demi teman-temannya juga adalah Committee.",
  ui_story_1011_10110101_48_dialog_content = "Committee juga yang melatih mereka untuk menjadi kandidat Grand Marshal.",
  ui_story_1011_10110101_49_dialog_content = "Itu...",
  ui_story_1011_10110101_50_dialog_content = "Rasanya terlalu kebetulan bagiku. Mungkinkah...",
  ui_story_1011_10110101_51_dialog_content = "PlayerName, Vice!",
  ui_story_1011_10110101_52_dialog_content = "Carleen? Kenapa kau di sini?",
  ui_story_1011_10110101_53_dialog_content = "Kudengar kau dalam masalah, jadi aku segera meninggalkan Lumopolis untuk bergabung denganmu.",
  ui_story_1011_10110101_54_dialog_content = "Aku tidak menyangka krisis itu berhasil diredam sebelum aku tiba di sini.",
  ui_story_1011_10110101_55_dialog_content = "Ini semua berkat Reinhardt.",
  ui_story_1011_10110101_56_dialog_content = "Omong-omong...",
  ui_story_1011_10110101_57_dialog_content = "Selamat datang kembali, Carleen!",
  ui_story_1011_10110101_58_dialog_content = "Selamat datang kembali!",
  ui_story_1011_10110101_59_dialog_content = "Terima kasih. Senang rasanya bisa kembali.",
  ui_story_1011_10110101_60_dialog_content = "Jadi, setelah terhambat oleh semua masalah ini, bagaimana kelanjutannya?",
  ui_story_1011_10110101_61_dialog_content = "Kau berhasil memperbaiki Soroz?",
  ui_story_1011_10110101_62_dialog_content = "Belum.",
  ui_story_1011_10110101_63_dialog_content = "Kami hanya menemukan fragmen yang kami butuhkan untuk memperbaiki Soroz.",
  ui_story_1011_10110101_64_dialog_content = "Jadi, selanjutnya kami berencana untuk pergi ke Eraveil untuk menemukan potongan yang tersisa.",
  ui_story_1011_10110101_65_dialog_content = "Eraveil?",
  ui_story_1011_10110101_66_dialog_content = "Kukira tempat itu sudah...",
  ui_story_1011_10110101_67_dialog_content = "Ya. Kupikir juga begitu. Seharusnya tidak ada yang tersisa.",
  ui_story_1011_10110101_68_dialog_content = "Tapi, informasi baru terungkap setelah Soroz dipasangi modul perbaikan.",
  ui_story_1011_10110101_69_dialog_content = "Sepertinya masih ada reruntuhan yang belum ditemukan di dalam Eraveil.",
  ui_story_1011_10110101_70_dialog_content = "Aneh.",
  ui_story_1011_10110101_71_dialog_content = "Database Lumopolis tidak menunjukkan hal itu.",
  ui_story_1011_10110101_72_dialog_content = "Begitu pula database Illumina.",
  ui_story_1011_10110101_73_dialog_content = "Sebaiknya kita kembali ke Gannon untuk memasok ulang persediaan sebelum menjelajahi wilayah yang asing seperti ini.",
  ui_story_1011_10110101_74_dialog_content = "Jika kau mencari pasokan, aku sudah menyediakannya.",
  ui_story_1011_10110101_75_dialog_content = "Siapa itu?",
  ui_story_1011_10110101_76_dialog_content = "PlayerName, dilihat dari pakaian budaya Caelestite, seharusnya kaulah orangnya.",
  ui_story_1011_10110101_77_dialog_content = "Aku Anatori, Illumina Intelligence. Aku telah ditugaskan untuk menjabat sebagai wakil komandan Grand Marshal Reinhardt. Segera berlaku.",
  ui_story_1011_10110101_78_dialog_content = "Ini baru saja terjadi...?",
  ui_story_1011_10110101_79_dialog_content = "Benar. Atas permintaan Grand Marshal, aku datang untuk memberimu persediaan apa pun yang kauperlukan.",
  ui_story_1011_10110101_80_dialog_content = "Harap konfirmasi isi dalam daftar ini.",
  ui_story_1011_10110101_81_dialog_content = "Alat perawatan Colossus, detektor logam, dan bahan peledak?!",
  ui_story_1011_10110101_82_dialog_content = "Grand Marshal berkata untuk sedia payung sebelum hujan.",
  ui_story_1011_10110101_83_dialog_content = "Menurut Grand Marshal, kau akan menjelajahi reruntuhan bawah tanah di Eraveil.",
  ui_story_1011_10110101_84_dialog_content = "Intel kami saat ini menunjukkan sebagian besar reruntuhan di Eraveil berada dalam kondisi buruk dan rentan runtuh.",
  ui_story_1011_10110101_85_dialog_content = "Bahan peledak akan berguna jika kau menemukan halangan seperti itu.",
  ui_story_1011_10110101_86_dialog_content = "Dia memikirkan ini dengan matang...",
  ui_story_1011_10110101_87_dialog_content = "Kalau begitu, sampaikan terima kasihku kepada Reinhardt.",
  ui_story_1011_10110101_88_dialog_content = "Oh, ada juga pesan dari Grand Marshal untukmu.",
  ui_story_1011_10110101_89_dialog_content = "Ada apa?",
  ui_story_1011_10110101_90_dialog_content = "\"Jangan khawatirkan masalah Illumina dan jangan bilang siapa-siapa soal itu.\"",
  ui_story_1011_10110101_91_dialog_content = "…!",
  ui_story_1011_10110101_92_dialog_content = "Itu bukan masalah Anda atau kekuatan Anda untuk menyelesaikannya.",
  ui_story_1011_10110101_93_dialog_content = "Dia lebih suka kau merasa tidak terbebani.",
  ui_story_1011_10110101_94_dialog_content = "Kuharap kau bisa memahami situasi sulit yang dialaminya dan membuat keputusan yang bijaksana.",
  ui_story_1011_10110101_95_dialog_content = "...",
  ui_story_1011_10110101_96_dialog_content = "Aku mengerti.",
  ui_story_1011_10110101_97_dialog_content = "Baiklah. Semoga berhasil.",
  ui_story_1011_10110101_98_dialog_content = "Selamat tinggal.",
  ui_story_1011_10110101_99_dialog_content = "Kita mungkin harus menjauhi perkara Illumina karena bahkan dia percaya itu adalah hal terbaik yang harus kita lakukan.",
  ui_story_1011_10110101_100_dialog_content = "Ya... Prioritas kita sekarang adalah kembali ke Eraveil dan menemukan cara untuk memperbaiki Soroz.",
  ui_story_1011_10110101_101_dialog_content = "Karena kini pasokan kita sudah tersedia, kami siap untuk berangkat.",
  ui_story_1011_10110101_102_dialog_content = "Reruntuhan bawah tanah Eraveil, kami datang!",
  ui_story_1011_10110101_103_dialog_content = "Peluangnya memang kecil, sih...",
  ui_story_1011_10110101_104_dialog_content = "Tapi, aku takkan pernah melewatkan kesempatan.",
  ui_story_1011_10110101_105_dialog_content = "Ayo jalan.",
  ui_story_1011_10110101_106_dialog_content = "Bagian dari dirimu ini benar-benar tak pernah berubah. Ayo lakukan.",
  ui_story_1011_10110101_107_dialog_content = "Berangkat!",
  ui_story_1011_10110101_108_dialog_content = "(Bahasa Eclipsian) Colossus kembali ke garis pertahanan dan akan pergi ke Eraveil.",
  ui_story_1011_10110101_109_dialog_content = "(Bahasa Eclipsian) Terus pantau.",
  ui_story_1011_10110101_110_dialog_content = "(Bahasa Eclipsian) Mereka sedang bergerak, sesuai dugaan.",
  ui_story_1011_10110101_111_dialog_content = "(Bahasa Eclipsian) Jangan lupa. Kamilah yang membereskan kekacauan yang kaubuat akibat kecerobohanmu.",
  ui_story_1011_10110101_112_dialog_content = "(Bahasa Eclipsian) Kau membawa pulang sampah tak berguna, tetapi mengabaikan barang yang bernilai nyata...",
  ui_story_1011_10110101_113_dialog_content = "(Bahasa Eclipsian) Ini adalah kunci untuk sesuatu yang hanya bisa diakses oleh Caelestite yang memiloti Colossus.",
  ui_story_1011_10110101_114_dialog_content = "(Bahasa Eclipsian) Tanpanya, itu hanyalah seonggok sampah.",
  ui_story_1011_10110101_115_dialog_content = "(Bahasa Eclipsian) Putar otakmu dan buat Caelestite itu menuntun kita ke sana. Seharusnya itu terbukti lebih sederhana ketimbang menangkap Caelestite.",
  ui_story_1011_10110101_116_dialog_content = "(Bahasa Eclipsian) Andai sesederhana itu.",
  ui_story_1011_10110101_117_dialog_content = "(Bahasa Eclipsian) Eksperimenku tidak akan salah.",
  ui_story_1011_10110101_118_dialog_content = "...",
  ui_story_1011_10110101_119_dialog_content = "(Bahasa Eclipsian) Lagi pula, kalian hanyalah Aurorian yang kehilangan induknya.",
  ui_story_1011_10110101_120_dialog_content = "(Bahasa Eclipsian) Kau—",
  ui_story_1011_10110101_121_dialog_content = "(Bahasa Eclipsian) Ya.",
  ui_story_1011_10110101_122_dialog_content = "(Bahasa Eclipsian) Sergap mereka dalam perjalanan ke Eraveil.",
  ui_story_1011_10110101_123_dialog_content = "(Bahasa Eclipsian) Tangkap Colossus dan Caelestite itu.",
  ui_story_1011_10110101_124_dialog_content = "(Bahasa Eclipsian) Baik.",
  ui_story_1011_10110101_125_dialog_content = "Aku akan segera memberikan perintah kepada semua Legion Commander.",
  ui_story_1011_10110101_126_dialog_content = "Karena cedera parah Grand Marshal Reinhardt...",
  ui_story_1011_10110101_127_dialog_content = "Sementara ini, Committee akan bertindak atas nama Grand Marshal sampai Reinhardt cukup sehat.",
  ui_story_1011_10110101_128_dialog_content = "Apa yang terjadi? Bagaimana dia bisa terluka begitu parah?",
  ui_story_1011_10110101_129_dialog_content = "Kami sedang menyelidikinya. Harap bersabar, Legion Commander Wrath.",
  ui_story_1011_10110101_130_dialog_content = "Semua legiun harus tetap dalam posisi bertahan. Kalian tidak diizinkan untuk berubah ke posisi menyerang.",
  ui_story_1011_10110101_131_dialog_content = "Bertahan? Jangan gila, dong?",
  ui_story_1011_10110101_132_dialog_content = "Eclipsite hampir di atas kita, dan kau ingin kita duduk dan menunggu?",
  ui_story_1011_10110101_133_dialog_content = "Commander Barton, aku mengerti kekhawatiranmu.",
  ui_story_1011_10110101_134_dialog_content = "Takkan kita biarkan Eclipsite melenggang dengan mudah, terlebih lagi mereka hampir membunuh Grand Marshal kita.",
  ui_story_1011_10110101_135_dialog_content = "Tapi, situasinya masih abu-abu.",
  ui_story_1011_10110101_136_dialog_content = "Intel terbaru kita menunjukkan bahwa Eclipsite bergerak menuju Eraveil untuk alasan yang tidak diketahui.",
  ui_story_1011_10110101_137_dialog_content = "Committee memutuskan bahwa jika Illumina Federation bukanlah target utama mereka saat ini, kita bisa menghirup napas untuk sejenak.",
  ui_story_1011_10110101_138_dialog_content = "Tidaklah bijak menyerang tanpa intel yang solid. Untuk alasan ini, tetap bertahan adalah tindakan terbaik.",
  ui_story_1011_10110101_139_dialog_content = "Kau tidak mengerti apa-apa!",
  ui_story_1011_10110101_140_dialog_content = "Di medan perang, setiap kesempatan harus diambil.",
  ui_story_1011_10110101_141_dialog_content = "Para Eclipsite ini harus dimusnahkan sebelum mereka makin diuntungkan!",
  ui_story_1011_10110101_142_dialog_content = "Kalau tidak, kita tidak akan bisa mengantisipasi perubahan situasi dan mereka akan menghabisi kita!",
  ui_story_1011_10110101_143_dialog_content = "Tindakan dan taktik pengecutmu hanya akan membuat Illumina jatuh!",
  ui_story_1011_10110101_144_dialog_content = "Commander Barton, perhatikan nada bicaramu.",
  ui_story_1011_10110101_145_dialog_content = "Keputusan Committee sudah bulat.",
  ui_story_1011_10110101_146_dialog_content = "Siapa pun yang tidak patuh akan ditangkap dan diadili di pengadilan militer.",
  ui_story_1011_10110101_147_dialog_content = "Kau diberhentikan.",
  ui_story_1011_10110101_148_dialog_content = "Cih...",
  ui_story_1011_10110101_150_dialog_content = "Eclipsite ada di depan kita, tetapi mereka ingin kita menahan diri?",
  ui_story_1011_10110101_151_dialog_content = "Kelihatannya aneh, memang.",
  ui_story_1011_10110101_154_dialog_content = "Menurutku, kita lawan dan hancurkan para Eclipsite itu.",
  ui_story_1011_10110101_155_dialog_content = "Tidak. Aku tidak akan melawan mereka.",
  ui_story_1011_10110101_156_dialog_content = "Apa?",
  ui_story_1011_10110101_157_dialog_content = "Grand Marshal Reinhardt adalah anggota Committee. Aku harus mematuhi keputusannya.",
  ui_story_1011_10110101_158_dialog_content = "Terlepas dari bagaimana perasaan kita tentang posisi bertahan, Grand Marshal pasti sudah memikirkannya.",
  ui_story_1011_10110101_159_dialog_content = "Reinhardt masih manusia, dan manusia tidaklah sempurna. Dia mungkin salah menilai situasi.",
  ui_story_1011_10110101_160_dialog_content = "Bukan begitu, Wrath?",
  ui_story_1011_10110101_161_dialog_content = "Tidak masalah bagiku.",
  ui_story_1011_10110101_162_dialog_content = "Yang kuinginkan hanyalah mengalahkan Reinhardt dengan jujur dan adil dan menjadi Grand Marshal Illumina.",
  ui_story_1011_10110101_163_dialog_content = "Aku tidak peduli dengan hal lain.",
  ui_story_1011_10110101_164_dialog_content = "Itu kekhawatiran Reinhardt.",
  ui_story_1011_10110101_165_dialog_content = "Jadi... Kalian semua hanya akan bersembunyi di Undercity layaknya pengecut?",
  ui_story_1011_10110101_166_dialog_content = "Aku akan membalas jika mereka menyerang terlebih dulu.",
  ui_story_1011_10110101_167_dialog_content = "Tapi, aku takkan mengompromikan strategi Illumina karena kecerobohan.",
  ui_story_1011_10110101_168_dialog_content = "Jangan biarkan emosimu menguasaimu, Barton.",
  ui_story_1011_10110101_169_dialog_content = "...",
  ui_story_1011_10110101_170_dialog_content = "Mereka memikirkan apa, sih?",
  ui_story_1011_10110101_171_dialog_content = "Terlalu nyaman di menara gading membuat orang-orang bodoh itu melupakan perbuatan Eclipsite pada Illumina!",
  ui_story_1011_10110101_173_dialog_content = "Segera setelah aku kembali, aku akan—",
  ui_story_1011_10110101_174_dialog_content = "Tidak. Tidak...",
  ui_story_1011_10110101_175_dialog_content = "Bahkan jika anak buahku bersedia mengikutiku, mereka semua akan diadili di pengadilan militer...",
  ui_story_1011_10110101_176_dialog_content = "Sialan... Satu-satunya pilihan hanyalah bertahan.",
  ui_story_1011_10110101_177_dialog_content = "Jika ada Eclipsite yang berani mendekati wilayah 2nd Legion, kupastikan mereka akan menyesal.",
  ui_story_1011_10110201_1_dialog_content = "PlayerName, tidakkah jalur penerbangan Soroz terlihat aneh bagimu?",
  ui_story_1011_10110201_15X1_dialog_content = "Ini bukan arah ke lahan terbuka tempat kita mendarat sebelumnya?",
  ui_story_1011_10110201_15X2_dialog_content = "Kau benar.",
  ui_story_1011_10110201_15X3_dialog_content = "Aku telah memeriksa sistem autopilot. Tujuannya diatur ke White Tower di sisi lain Eraveil.",
  ui_story_1011_10110201_15X4_dialog_content = "White Tower?",
  ui_story_1011_10110201_15X5_dialog_content = "Apakah di sana lokasi Colossus Maintenance Base?",
  ui_story_1011_10110201_15X6_dialog_content = "Menimbang autopilot sendiri yang menentukan rutenya, sangat mungkin.",
  ui_story_1011_10110201_15X7_dialog_content = "Apa yang kautahu tentang White Tower ini?",
  ui_story_1011_10110201_15X8_dialog_content = "Hmm... Sama sekali tidak banyak. Catatan Illumina tentang Eraveil sangat terbatas.",
  ui_story_1011_10110201_15X9_dialog_content = "Sejauh pengetahuanku, bangunan-bangunan White Tower dibuat dari batuan putih biasa.",
  ui_story_1011_10110201_15X10_dialog_content = "Selain itu, tidak ada informasi tambahan dariku.",
  ui_story_1011_10110201_15X11_dialog_content = "Data Soroz tentang Eraveil hanya sebatas pengenalan tingkat permulaan saja...",
  ui_story_1011_10110201_15X12_dialog_content = "Pikirkan lebih keras!",
  ui_story_1011_10110201_15X13_dialog_content = "Pasti ada sesuatu tentang tempat ini yang diketahui oleh Caelestite, tetapi tak diketahui oleh Illumina.",
  ui_story_1011_10110201_15X14_dialog_content = "Akan… akan kucoba!",
  ui_story_1011_10110201_16_dialog_content = "Aku memang ingat White Tower itu!",
  ui_story_1011_10110201_17_dialog_content = "Ada sesuatu di database Soroz...",
  ui_story_1011_10110201_18_dialog_content = "Sekarang aku ingat!",
  ui_story_1011_10110201_19_dialog_content = "Tempat ini pernah dihuni sekelompok Caelestite yang kemudian pindah ke habitat saat ini.",
  ui_story_1011_10110201_20_dialog_content = "Yang paling khas di sana adalah sebuah White Tower kosong yang terabaikan.",
  ui_story_1011_10110201_21_dialog_content = "Tidak ada yang lain selain menara itu.",
  ui_story_1011_10110201_22_dialog_content = "Tidak ada apa-apa sama sekali? Kedengarannya ada yang tidak beres...",
  ui_story_1011_10110201_22X1_dialog_content = "Colossus Maintenance Base sendiri kedengarannya seperti suatu tempat yang sangat besar.",
  ui_story_1011_10110201_22X2_dialog_content = "Mungkinkah tempat itu sengaja disembunyikan?",
  ui_story_1011_10110201_22X3_dialog_content = "Argh...!",
  ui_story_1011_10110201_23_dialog_content = "Ada apa?",
  ui_story_1011_10110201_24_dialog_content = "Apa yang terjadi?",
  ui_story_1011_10110201_25_dialog_content = "<color=#e8d9bb>\"Peringatan Penyusup: Eclipsite terdeteksi.\"</color>",
  ui_story_1011_10110201_26_dialog_content = "Eclipsite?!",
  ui_story_1011_10110201_27_dialog_content = "Mustahil. Eclipsite biasa tidak dapat mengimbangi Soroz.",
  ui_story_1011_10110201_28_dialog_content = "Jumlah sebanyak ini... Ini pasti penyergapan!",
  ui_story_1011_10110201_29_dialog_content = "Groar!!!",
  ui_story_1011_10110201_30_dialog_content = "Mereka ada di Bridge!",
  ui_story_1011_10110201_31_dialog_content = "Hentikan mereka!",
  ui_story_1011_10110201_32_dialog_content = "Jauhkan mereka!",
  ui_story_1011_10110201_33_dialog_content = "Hati-hati! Eclipsite biasanya tidak mampu melakukan taktik penyergapan!",
  ui_story_1011_10110201_34_dialog_content = "Pasti ada komandan di antara mereka!",
  ui_story_1011_10110201_35_dialog_content = "Aku akan mengurus sisi kiri. Vice, kuserahkan sisanya padamu.",
  ui_story_1011_10110201_36_dialog_content = "Aku butuh dukunganmu, PlayerName!",
  ui_story_1011_10110201_37_dialog_content = "Beres!",
  ui_story_1011_10110202_1_dialog_content = "Groar!!!",
  ui_story_1011_10110202_2_dialog_content = "Coba lewati aku kalau bisa!",
  ui_story_1011_10110202_3_dialog_content = "Groar!",
  ui_story_1011_10110202_4_dialog_content = "Mereka ada berapa banyak?!",
  ui_story_1011_10110202_5_dialog_content = "Mereka terus berdatangan!",
  ui_story_1011_10110202_6_dialog_content = "Kita terpojok!",
  ui_story_1011_10110202_7_dialog_content = "Stasiun kendali tepat di belakang kita!",
  ui_story_1011_10110202_8_dialog_content = "Groar!",
  ui_story_1011_10110202_9_dialog_content = "Vice, awas!",
  ui_story_1011_10110202_10_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1011_10110202_11_dialog_content = "Sial! Mereka telah mencapai stasiun kendali!",
  ui_story_1011_10110202_12_dialog_content = "Eh?",
  ui_story_1011_10110202_13_dialog_content = "Kita akan jatuh!",
  ui_story_1011_10110202_14_dialog_content = "Aduh! Tolong aku!",
  ui_story_1011_10110202_15_dialog_content = "Berpegangan pada sesuatu!",
  ui_story_1011_10110202_16_dialog_content = "PlayerName, jangan lepaskan tanganku!",
  ui_story_1011_10110202_17_dialog_content = "(Bahasa Eclipsian) Colossus jatuh...",
  ui_story_1011_10110202_18_dialog_content = "(Bahasa Eclipsian) Dasar orang-orang bodoh!",
  ui_story_1011_10110202_19_dialog_content = "(Bahasa Eclipsian) K-kami minta maaf!",
  ui_story_1011_10110202_20_dialog_content = "(Bahasa Eclipsian) Aku memerintahkan kalian untuk menangkap Colossus dan si Caelestite itu.",
  ui_story_1011_10110202_21_dialog_content = "(Bahasa Eclipsian) Aku tidak meminta kalian untuk menghancurkan mereka!",
  ui_story_1011_10110202_22_dialog_content = "(Bahasa Eclipsian) Kami akan mencoba menyelamatkan situasi!",
  ui_story_1011_10110202_23_dialog_content = "(Bahasa Eclipsian) Kejar mereka. Jangan sampai mereka lolos.",
  ui_story_1011_10110202_24_dialog_content = "(Bahasa Eclipsian) Ini kesempatan terakhirmu.",
  ui_story_1011_10110202_25_dialog_content = "(Bahasa Eclipsian) Baik.",
  ui_story_1011_10110202_26_dialog_content = "(Bahasa Eclipsian) Kalian terlalu bodoh untuk menjadi pemimpin.",
  ui_story_1011_10110202_27_dialog_content = "(Bahasa Eclipsian) Forsakin. Jangan ikut campur.",
  ui_story_1011_10110202_28_dialog_content = "(Bahasa Eclipsian) Sudah kubilang. Ini eksperimenku. Kau jangan ikut-ikut.",
  ui_story_1011_10110202_29_dialog_content = "(Bahasa Eclipsian) Sekarang, kau dan Eclipsite idiotmu telah menjadi elemen yang tidak stabil dalam eksperimen.",
  ui_story_1011_10110202_30_dialog_content = "(Bahasa Eclipsian) Tetaplah di area luar dan tunggu.",
  ui_story_1011_10110202_31_dialog_content = "(Bahasa Eclipsian) Satu unit Illumina dalam perjalanan. Tahan mereka.",
  ui_story_1011_10110202_32_dialog_content = "(Bahasa Eclipsian) Minggir sana.",
  ui_story_1011_10110202_33_dialog_content = "(Bahasa Eclipsian) Forsakin...",
  ui_story_1011_10110202_34_dialog_content = "(Bahasa Eclipsian) Kau harus membayar kesombonganmu.",
  ui_story_1011_10110202_40X1_dialog_content = "Prajurit! Reinhardt telah memerintahkan 2nd Legion kita untuk tetap di tempat...",
  ui_story_1011_10110202_40X2_dialog_content = "Akan kita perlihatkan pada dirinya betapa kokohnya pertahanan kita!",
  ui_story_1011_10110202_40X3_dialog_content = "Kau! Periksa semua benteng, perbaiki setiap kerusakan, dan perkuat bangunan-bangunan kunci.",
  ui_story_1011_10110202_40X4_dialog_content = "Tak peduli berapa banyak Eclipsite yang kita hadapi, kita akan mempertahankan tempat ini!",
  ui_story_1011_10110202_40X5_dialog_content = "Siap!",
  ui_story_1011_10110202_40X6_dialog_content = "Dan kau! Ganti penjaga yang bertugas.",
  ui_story_1011_10110202_40X7_dialog_content = "Pastikan semua penjaga diganti setiap 6 jam. Mereka perlu beristirahat dengan baik.",
  ui_story_1011_10110202_40X8_dialog_content = "Buka mata kalian lebar-lebar! Awasi pergerakan Eclipsite!",
  ui_story_1011_10110202_40X9_dialog_content = "Siap!",
  ui_story_1011_10110202_40X10_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_1011_10110202_40X11_dialog_content = "Ada apa?",
  ui_story_1011_10110202_40X12_dialog_content = "Itu... Soroz?",
  ui_story_1011_10110202_40X13_dialog_content = "Mengapa terbang begitu rendah?",
  ui_story_1011_10110202_40X14_dialog_content = "Lalu, semua titik hitam di Colossus itu... Eclipsite?",
  ui_story_1011_10110202_40X15_dialog_content = "Apa-apaan! Anak itu sedang diserang!",
  ui_story_1011_10110202_40X16_dialog_content = "Pak!",
  ui_story_1011_10110202_40X17_dialog_content = "Bicaralah!",
  ui_story_1011_10110202_40X18_dialog_content = "Mata-mata kita melihat pergerakan Eclipsite yang tak biasa. Mereka berkumpul ke arah Eraveil sekarang!",
  ui_story_1011_10110202_40X19_dialog_content = "Selain sejumlah besar Eclipsite biasa, juga ada beberapa High-Level Eclipsite!",
  ui_story_1011_10110202_40X20_dialog_content = "Termasuk Forsakin dan satu High-Level Eclipsite lain!",
  ui_story_1011_10110202_40X21_dialog_content = "Forsakin…",
  ui_story_1011_10110202_40X22_dialog_content = "Mengapa dia menuju ke arah itu sekarang?",
  ui_story_1011_10110202_40X23_dialog_content = "Ini tidak beres.",
  ui_story_1011_10110202_40X24_dialog_content = "Anak Caelestite itu, Eclipsite, dan Forsakin...",
  ui_story_1011_10110202_40X25_dialog_content = "Mereka semua bergegas ke Eraveil. Hal besar akan segera terjadi.",
  ui_story_1011_10110202_40X26_dialog_content = "Berikan perintahku. Semua pos 2nd Legion memasuki status siaga.",
  ui_story_1011_10110202_40X27_dialog_content = "Tugaskan satu unit mata-mata untuk mengawasi Eraveil.",
  ui_story_1011_10110202_40X28_dialog_content = "Siap!",
  ui_story_1011_10110202_40X29_dialog_content = "Dan…",
  ui_story_1011_10110202_40X30_dialog_content = "<color=#e8d9bb>Ta… ta… ta…</color>",
  ui_story_1011_10110202_40X31_dialog_content = "Itu... Eraveil?",
  ui_story_1011_10110202_40X32_dialog_content = "Orang-orang kita sedang melawan Eclipsite?",
  ui_story_1011_10110202_40X33_dialog_content = "Y-Ya!",
  ui_story_1011_10110202_40X34_dialog_content = "Kami baru saja bertemu dengan sepasukan Eclipsite di bawah komando Forsakin!",
  ui_story_1011_10110202_40X35_dialog_content = "Pasukan kita bertempur melawan musuh itu tetapi Forsakin sepertinya pergi sendiri ke Eraveil!",
  ui_story_1011_10110202_40X36_dialog_content = "Apa pun yang sedang direncanakan oleh Eclipsite, pasti tidak baik.",
  ui_story_1011_10110202_40X37_dialog_content = "Sudah kubilang, hal buruk akan segera terjadi.",
  ui_story_1011_10110202_40X38_dialog_content = "Tahan mereka!",
  ui_story_1011_10110202_40X39_dialog_content = "Informasikan pada semua unit untuk bertahan di posisi mereka. Jangan sampai mundur!",
  ui_story_1011_10110202_40X40_dialog_content = "Aku akan menangkap Forsakin, sang pengkhianat Illumina, kali ini!",
  ui_story_1011_10110202_40X41_dialog_content = "Tapi, Pak, kita diperintahkan untuk...",
  ui_story_1011_10110202_40X42_dialog_content = "Dengar! Di medan perang, setiap kesempatan harus segera dimanfaatkan.",
  ui_story_1011_10110202_40X43_dialog_content = "Forsakin berniat jahat. Kita harus menghentikannya sekarang.",
  ui_story_1011_10110202_40X44_dialog_content = "Kita harus bertindak selagi bisa.",
  ui_story_1011_10110202_40X45_dialog_content = "Aku bertanggung jawab penuh atas tindakanku. Katakanlah pada Reinhardt dan Committee...",
  ui_story_1011_10110202_40X46_dialog_content = "Mereka dapat meminta 2nd Legion Commander Barton sendiri untuk bertanggung jawab atas semua konsekuensinya!",
  ui_story_1011_10110202_40X47_dialog_content = "Kau paham?",
  ui_story_1011_10110202_40X48_dialog_content = "Siap, Pak!",
  ui_story_1011_10110202_40X49_dialog_content = "Aku penasaran bagaimana cara Navigator bertahan...",
  ui_story_1011_10110202_40X50_dialog_content = "Dia seperti kucing bernyawa sembilan. Dia akan baik-baik saja.",
  ui_story_1011_10110202_40X51_dialog_content = "Ayo, kita bantu dia.",
  ui_story_1011_10110401_1_dialog_content = "<anim type=Shake><size=50>Ahhhhhhh!</size></anim>",
  ui_story_1011_10110401_2_dialog_content = "KITA JATUH!!!",
  ui_story_1011_10110401_3_dialog_content = "PlayerName, pertahankan ketinggian dan arah!",
  ui_story_1011_10110401_4_dialog_content = "Ada ruang di bawah menara. Luncurkan Soroz masuk!",
  ui_story_1011_10110401_7X1_dialog_content = "Aku tak bisa melakukannya!",
  ui_story_1011_10110401_7X2_dialog_content = "Pengendalinya rusak. Soroz lepas kendali!",
  ui_story_1011_10110401_7X3_dialog_content = "Cari apa pun buat pegangan!",
  ui_story_1011_10110401_7X4_dialog_content = "Sekarang...",
  ui_story_1011_10110401_7X5_dialog_content = "Berdoalah semoga kita tak menabrak menara itu!",
  ui_story_1011_10110401_7X6_dialog_content = "Ahhh!",
  ui_story_1011_10110401_8_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1011_10110401_9_dialog_content = "<color=#e8d9bb>*gemuruh*</color>",
  ui_story_1011_10110401_10_dialog_content = "*Uhuk-uhuk* Mulutku berdebu...",
  ui_story_1011_10110401_11_dialog_content = "Apakah kita... masih hidup?",
  ui_story_1011_10110401_12_dialog_content = "Umm... Pasti.",
  ui_story_1011_10110401_13_dialog_content = "Kita telah mendarat.",
  ui_story_1011_10110401_14_dialog_content = "Apakah semua orang baik-baik saja? Ada yang terluka?",
  ui_story_1011_10110401_15_dialog_content = "Aku baik-baik saja, cuma merasa mual.",
  ui_story_1011_10110401_16_dialog_content = "Aku... Aku juga baik-baik saja.",
  ui_story_1011_10110401_17_dialog_content = "*Uhuk-uhuk* Apakah kita di bagian bawah menara?",
  ui_story_1011_10110401_18_dialog_content = "Ya, kita masuk ke ruang tepat di bawah White Tower.",
  ui_story_1011_10110401_19_dialog_content = "<color=#e8d9bb>\"Tujuan tercapai: Landasan Colossus Maintenance Base.\"</color>",
  ui_story_1011_10110401_20_dialog_content = "<color=#e8d9bb>\"Membuat koneksi ke sistem kontrol dasar.\"</color>",
  ui_story_1011_10110401_21_option_content = "Landasan?",
  ui_story_1011_10110401_22_dialog_content = "Seluruh ruang ini... adalah landasan?",
  ui_story_1011_10110401_23_dialog_content = "Pantas saja ukurannya besar sekali... Bisa memuat beberapa Colossus lagi.",
  ui_story_1011_10110401_24_dialog_content = "Kita berhasil sampai di lapangan pendaratan. Ini sama sekali bukan pendaratan darurat...",
  ui_story_1011_10110401_25_dialog_content = "Graah! Groar!",
  ui_story_1011_10110401_26_dialog_content = "...",
  ui_story_1011_10110401_27_dialog_content = "...",
  ui_story_1011_10110401_28_dialog_content = "Lagi-lagi Eclipsite!",
  ui_story_1011_10110401_29_dialog_content = "Grrrr!",
  ui_story_1011_10110401_30_dialog_content = "Lawan!",
  ui_story_1011_10110401_31_dialog_content = "Pasti ada lebih banyak Eclipsite di Soroz!",
  ui_story_1011_10110401_32_dialog_content = "Jangan sampai mereka membuat kerusakan lebih banyak lagi!",
  ui_story_1011_10110402_1_dialog_content = "Fyuh... Ini pasti yang terakhir.",
  ui_story_1011_10110402_2_dialog_content = "Tidak ada lagi Eclipsite yang terlihat.",
  ui_story_1011_10110402_3_dialog_content = "Aku tidak merasakan ada musuh lagi. Kita bisa beristirahat.",
  ui_story_1011_10110402_4_dialog_content = "Akan kuperiksa dulu Soroz.",
  ui_story_1011_10110402_5_dialog_content = "<color=#e8d9bb>\"Mencoba terhubung ke sistem kontrol Colossus Maintenance Base.\"</color>",
  ui_story_1011_10110402_6_dialog_content = "<color=#e8d9bb>\"Kesalahan: Landasan terputus dari sistem kontrol pusat.\"</color>",
  ui_story_1011_10110402_7_dialog_content = "<color=#e8d9bb>\"Lanjutkan ke Central Control Room dan hubungkan kembali secara manual.\"</color>",
  ui_story_1011_10110402_8_dialog_content = "Central Control Room?",
  ui_story_1011_10110402_9_dialog_content = "Ada hal semacam itu di White Tower?",
  ui_story_1011_10110402_10_dialog_content = "Apakah database kita berisi sesuatu soal itu?",
  ui_story_1011_10110402_11_dialog_content = "Aku rasa tidak...",
  ui_story_1011_10110402_12_dialog_content = "Aku tidak keberatan memeriksa semua file, tetapi itu akan memakan waktu.",
  ui_story_1011_10110402_13_dialog_content = "Memeriksa file saja tidak akan membantu. Kita perlu melakukan investigasi langsung.",
  ui_story_1011_10110402_14_dialog_content = "Benar juga. Ayo kita turun ke sana dan lihat.",
  ui_story_1011_10110402_15_dialog_content = "Kalau begitu, ayo pergi.",
  ui_story_1011_10110402_16_dialog_content = "Di sini kosong sekali...",
  ui_story_1011_10110402_17_dialog_content = "Semua yang kita katakan bergema kembali...",
  ui_story_1011_10110402_18_dialog_content = "Menurut data, ini dulunya habitat Caelestite.",
  ui_story_1011_10110402_19_dialog_content = "Tapi, kau hampir tidak bisa menemukan ruangan sekarang. Jika seseorang pernah tinggal di sini, itu sudah lama.",
  ui_story_1011_10110402_20_dialog_content = "Dan mereka sudah pergi sejak lama.",
  ui_story_1011_10110402_21_dialog_content = "Bahkan jika mereka meninggalkan sesuatu, waktu akan menghapus semuanya.",
  ui_story_1011_10110402_22_dialog_content = "Kurasa Caelestite tidak pernah tinggal di landasan.",
  ui_story_1011_10110402_23_dialog_content = "Apakah mereka hanya mendaratkan Colossus mereka ke sini dan tinggal bersama mereka?",
  ui_story_1011_10110402_24_dialog_content = "Terdengar mirip-mirip berkemah.",
  ui_story_1011_10110402_25_dialog_content = "Mungkin itulah alasan kau tidak melihat rumah di sini, Caelestite tinggal di Colossus mereka.",
  ui_story_1011_10110402_26_dialog_content = "Ketika pergi, mereka membawa Colossus mereka.",
  ui_story_1011_10110402_27_dialog_content = "Jika mereka mendaratkan Colossus mereka di sini, mereka tahu ini adalah landasan.",
  ui_story_1011_10110402_28_dialog_content = "Jika memang begitu, mereka akan tahu tentang <color=#FFB400>Colossus Maintenance Base</color>.",
  ui_story_1011_10110402_29_dialog_content = "Jadi, kenapa tidak ada catatan soal itu?",
  ui_story_1011_10110402_30_dialog_content = "Ini aneh. Coba kita lihat apakah nanti kita bisa tahu lebih banyak.",
  ui_story_1011_10110402_31_dialog_content = "Ya.",
  ui_story_1011_10110402_32_dialog_content = "Pangkalan yang tidak tercatat dan tidak dikenal dunia... Seolah muncul begitu saja.",
  ui_story_1011_10110402_33_dialog_content = "Aku tidak melihat apa pun yang menyerupai stasiun pemeliharaan atau ruang untuk Colossus.",
  ui_story_1011_10110402_34_dialog_content = "Hanya ada debu yang tebal.",
  ui_story_1011_10110402_35_dialog_content = "Sepertinya Central Control Room juga tidak ada di sini.",
  ui_story_1011_10110402_36_dialog_content = "Mungkinkah... ada di atas sana?",
  ui_story_1011_10110402_37_dialog_content = "PlayerName, sebenarnya ada apa di menara?",
  ui_story_1011_10110402_38_dialog_content = "Coba kuingat...",
  ui_story_1011_10110402_39_dialog_content = "Menurut database Soroz, Caelestite pernah tinggal di menara ini selama beberapa waktu.",
  ui_story_1011_10110402_40_dialog_content = "Tapi, kemudian mereka pindah ke habitat saat ini.",
  ui_story_1011_10110402_41_dialog_content = "Dulu, Caelestite menjelajahi tempat ini, termasuk puncak menara...",
  ui_story_1011_10110402_42_dialog_content = "Tapi, tidak menemukan apa pun selain bebatuan putih dengan pola-pola seperti yang terlihat dari luar.",
  ui_story_1011_10110402_43_dialog_content = "Tidak ada apa-apa di atas sana...?",
  ui_story_1011_10110402_44_dialog_content = "Apakah kita berada di koordinat yang salah?",
  ui_story_1011_10110402_45_dialog_content = "Kurasa tidak. Jika struktur bergerak karena pergerakan lempeng, seharusnya tidak terlalu jauh dari posisi semula.",
  ui_story_1011_10110402_46_dialog_content = "Jika tidak ada apa-apa di atas menara...",
  ui_story_1011_10110402_47_dialog_content = "Bagaimana dengan di bawahnya?",
  ui_story_1011_10110402_48_dialog_content = "Di bawahnya?",
  ui_story_1011_10110402_49_dialog_content = "Maksudmu, ruang bawah tanah yang tersembunyi, seperti Gannon?",
  ui_story_1011_10110402_50_dialog_content = "Ada benarnya juga!",
  ui_story_1011_10110402_51_dialog_content = "Namun, White Tower telah runtuh. Bagaimana kita bisa menemukan pintu masuknya tanpa peta?",
  ui_story_1011_10110402_52_dialog_content = "Kecuali jika kau siap untuk menggali seluruh tempat ini.",
  ui_story_1011_10110402_53_dialog_content = "Mungkin akan memakan waktu bertahun-tahun sebelum menemukan jalan.",
  ui_story_1011_10110402_54_dialog_content = "Jalan... Undercity... Menemukannya...",
  ui_story_1011_10110402_55_dialog_content = "Aku tahu!",
  ui_story_1011_10110402_56_dialog_content = "Grand Marshal menyertakan detektor logam dalam pasokan kita.",
  ui_story_1011_10110402_57_dialog_content = "Jika memang ada markas bawah tanah, besar kemungkinan material bangunan yang digunakan berasal dari logam.",
  ui_story_1011_10110402_58_dialog_content = "Kita dapat memeriksa titik-titik yang mungkin menggunakan detektor logam terlebih dahulu sebelum menggali.",
  ui_story_1011_10110402_59_dialog_content = "Kalau dipikir-pikir Grand Marshal bahkan memperkirakan ini...",
  ui_story_1011_10110402_60_dialog_content = "Seperti rumor yang beredar, dia benar-benar sosok pemimpin yang visioner.",
  ui_story_1011_10110402_60X1_dialog_content = "Bawa persediaan lain serta bahan peledak.",
  ui_story_1011_10110402_60X2_dialog_content = "Semua itu mungkin berguna.",
  ui_story_1011_10110402_61_dialog_content = "Kurasa itulah yang akan kita lakukan nanti.",
  ui_story_1011_10110402_62_dialog_content = "Kita hanya bisa berharap kita cukup beruntung untuk menemukan pintu masuk pada percobaan pertama.",
  ui_story_1011_10110402_63_dialog_content = "<color=#e8d9bb>Di suatu tempat di luar White Tower</color>",
  ui_story_1011_10110402_64_dialog_content = "White Tower itu tidak sesederhana kelihatannya.",
  ui_story_1011_10110402_65_dialog_content = "Jika bukan karena kunci dari Caelestite, rahasia di dalamnya mungkin akan tersembunyi selamanya.",
  ui_story_1011_10110402_66_dialog_content = "Saatnya menjadikan rahasia itu sebagai bagian dari data pengujianku.",
  ui_story_1011_10110402_66X1_dialog_content = "Kau tidak akan bisa kabur!",
  ui_story_1011_10110402_66X2_dialog_content = "Graaahh—",
  ui_story_1011_10110402_66X3_dialog_content = "Legion Commander, kami telah menghabisi sebagian besar Eclipsite di wilayah ini!",
  ui_story_1011_10110402_66X4_dialog_content = "Bagus! Sekarang waktunya untuk membangun kembali pertahanan kita.",
  ui_story_1011_10110402_66X5_dialog_content = "Siap!",
  ui_story_1011_10110402_66X6_dialog_content = "Semua Eclipsite ini memang tak berguna.",
  ui_story_1011_10110402_66X7_dialog_content = "Di mana Forsakin?",
  ui_story_1011_10110402_66X8_dialog_content = "Apakah dia berhasil sampai ke Eraveil?",
  ui_story_1011_10110402_66X9_dialog_content = "Semua Eclipsite dan Forsakin ini kemari demi PlayerName?",
  ui_story_1011_10110402_66X10_dialog_content = "Manuvernya besar juga.",
  ui_story_1011_10110402_66X11_dialog_content = "Mari kita lihat hal apa yang akan dia lakukan selanjutnya.",
  ui_story_1011_10110501_1_dialog_content = "Kotak kosong tak berguna...",
  ui_story_1011_10110501_2_dialog_content = "Buang.",
  ui_story_1011_10110501_3_dialog_content = "Buku-buku yang nyaris tak terbaca...",
  ui_story_1011_10110501_4_dialog_content = "Buang.",
  ui_story_1011_10110501_5_dialog_content = "Ada kaleng apa ini...",
  ui_story_1011_10110501_6_dialog_content = "Buang.",
  ui_story_1011_10110501_7_dialog_content = "Tunggu! Jangan dibuang!",
  ui_story_1011_10110501_8_dialog_content = "Tapi... kau tak tahu itu sudah kedaluwarsa berapa lama.",
  ui_story_1011_10110501_9_dialog_content = "Lebih baik dibuang saja.",
  ui_story_1011_10110501_10_dialog_content = "Huh...",
  ui_story_1011_10110501_11_dialog_content = "Setelah sekian lama bekerja, hanya dapat banyak sampah...",
  ui_story_1011_10110501_12_dialog_content = "Mari kita periksa setiap sudut lagi untuk memastikan tidak ada yang terlewatkan.",
  ui_story_1011_10110501_13_dialog_content = "Bagus. Aku akan mencari lagi.",
  ui_story_1011_10110501_14_dialog_content = "Kurasa kita belum memeriksa area itu.",
  ui_story_1011_10110501_15_dialog_content = "Bebatuan putih itu berserakan di sekitar sini... Apakah bebatuan itu jatuh dari White Tower?",
  ui_story_1011_10110501_16_dialog_content = "Aku ingin tahu apakah ada sesuatu di dalam...",
  ui_story_1011_10110501_17_dialog_content = "Biar kuperiksa dengan detektor logam!",
  ui_story_1011_10110501_18_dialog_content = "<color=#e8d9bb>*bip bip bip*</color>",
  ui_story_1011_10110501_19_dialog_content = "Ini... bereaksi!",
  ui_story_1011_10110501_20_dialog_content = "Tapi, itu di dalam batu?",
  ui_story_1011_10110501_21_option_content = "Ketuk batu",
  ui_story_1011_10110501_22_dialog_content = "<color=#e8d9bb>Tok, tok...</color>",
  ui_story_1011_10110501_23_dialog_content = "Sama sekali tidak terdengar hampa. Mungkinkah di belakangnya?",
  ui_story_1011_10110501_24_dialog_content = "Pencahayaan di sini sangat redup. Tidak bisa membedakan dengan jelas.",
  ui_story_1011_10110501_25_dialog_content = "Sepertinya ada sesuatu di balik bayangan, tetapi aku tidak bisa melihatnya dengan jelas.",
  ui_story_1011_10110501_26_dialog_content = "Lebih dekat dan... Sebentar. Apakah itu...",
  ui_story_1011_10110501_27_dialog_content = "Eclipsite dengan kaleng di kepalanya, mencoba menyamar sebagai berbagai macam barang?!",
  ui_story_1011_10110501_28_dialog_content = "Groooaaar!",
  ui_story_1011_10110501_29_dialog_content = "Ehhhh?!",
  ui_story_1011_10110501_30_dialog_content = "PlayerName!",
  ui_story_1011_10110501_31_dialog_content = "Graah! Groar!",
  ui_story_1011_10110501_32_dialog_content = "H-Hampir saja!",
  ui_story_1011_10110501_33_dialog_content = "Bagaimana bisa mereka sampai di sini?!",
  ui_story_1011_10110501_34_dialog_content = "Ini adalah ruang terbuka lebar dengan banyak bayangan untuk bersembunyi.",
  ui_story_1011_10110501_35_dialog_content = "Eclipsite pasti telah menyelinap masuk ketika kita sedang mencari pintu masuk.",
  ui_story_1011_10110501_36_dialog_content = "Grooooar!",
  ui_story_1011_10110501_37_dialog_content = "Sialan. Kita terkepung.",
  ui_story_1011_10110501_38_dialog_content = "Lebih banyak Eclipsite datang dari pintu masuk!",
  ui_story_1011_10110501_39_dialog_content = "Kita harus mencari cara untuk menerobos!",
  ui_story_1011_10110501_40_dialog_content = "Tidak!",
  ui_story_1011_10110501_41_dialog_content = "Itu berarti kita menyerahkan Menara Putih dan Soroz kepada mereka!",
  ui_story_1011_10110501_42_dialog_content = "Kita harus mencegah Eclipsite masuk jika kita ingin menjaga tempat ini.",
  ui_story_1011_10110501_43_dialog_content = "Tapi, itu seperti gua tanpa apa pun yang menyerupai pintu!",
  ui_story_1011_10110501_44_dialog_content = "Tidak ada pintu...",
  ui_story_1011_10110501_45_dialog_content = "Kalau begitu, kita buat saja pintunya!",
  ui_story_1011_10110501_46_dialog_content = "Gunakan bahan peledak saja!",
  ui_story_1011_10110501_47_dialog_content = "Kau ingin meledakkan pintu masuk?",
  ui_story_1011_10110501_48_dialog_content = "Benar sekali!",
  ui_story_1011_10110501_49_dialog_content = "Tidak masalah jika pintu masuknya runtuh. Kita masih bisa keluar dari bagian atas menara.",
  ui_story_1011_10110501_49X1_dialog_content = "Kita pasti dapat menemukan pintu keluar lain dalam reruntuhan bawah tanah itu kalau perlu.",
  ui_story_1011_10110501_50_dialog_content = "Tapi kita harus menghentikan Eclipsite di sini dan sekarang juga untuk melindungi Soroz serta reruntuhan bawah tanah!",
  ui_story_1011_10110501_51_dialog_content = "Vice dan aku akan melindungimu. PlayerName, gunakan kesempatan ini dan ledakkan bahan peledak di pintu masuknya!",
  ui_story_1011_10110501_52_dialog_content = "Baiklah!",
  ui_story_1011_10110501_53_dialog_content = "Aku mengandalkanmu!",
  ui_story_1011_10110502_1_dialog_content = "Graah! Groar!",
  ui_story_1011_10110502_2_dialog_content = "Minggir!",
  ui_story_1011_10110502_3_dialog_content = "Grooooar!",
  ui_story_1011_10110502_4_dialog_content = "Makin banyak Eclipsite menyerbu masuk... Kalau begini, mendekati pintu masuk saja aku tak bisa...",
  ui_story_1011_10110502_5_dialog_content = "Apalagi meletakkan bahan peledak!",
  ui_story_1011_10110502_6_dialog_content = "Aku harus mencoba menerobos mereka terlebih dahulu.",
  ui_story_1011_10110502_7_dialog_content = "Kita tak boleh terjebak di sini!",
  ui_story_1011_10110502_9_dialog_content = "Rasakan ini!",
  ui_story_1011_10110502_10_dialog_content = "Pintu masuk, lihat! Bukankah itu...",
  ui_story_1011_10110502_11_dialog_content = "Barton?!",
  ui_story_1011_10110502_12_dialog_content = "Sedang apa kau di sini?!",
  ui_story_1011_10110502_12X1_dialog_content = "Hah! Kutahu kau akan baik-baik saja.",
  ui_story_1011_10110502_12X2_dialog_content = "Tadi aku melihat banyak Eclipsite pergi ke arah sini jadi aku kemari untuk memeriksanya.",
  ui_story_1011_10110502_13_dialog_content = "Oh, hanya menumpang lewat, dan melakukan olahraga harianku dengan Eclipsite.",
  ui_story_1011_10110502_14_dialog_content = "Lakukan apa yang perlu kaulakukan. Aku akan melindungimu.",
  ui_story_1011_10110502_15_dialog_content = "Commander Barton menahan Eclipsite! PlayerName, inilah kesempatanmu!",
  ui_story_1011_10110502_16_dialog_content = "Barton, kembalilah! Kita akan menyegel pintu masuknya!",
  ui_story_1011_10110502_17_dialog_content = "Segel? Bagaimana caranya?",
  ui_story_1011_10110502_18_dialog_content = "Kita akan meledakkannya!",
  ui_story_1011_10110502_19_dialog_content = "Meledakkannya?!",
  ui_story_1011_10110502_20_dialog_content = "Kukira kau tidak sanggup melakukannya, Nak!",
  ui_story_1011_10110502_21_dialog_content = "Biar kuurus yang sebelah sini. Cepat ledakkan.",
  ui_story_1011_10110502_22_dialog_content = "Eclipsite mundur. PlayerName, maju!",
  ui_story_1011_10110502_23_dialog_content = "Siap!",
  ui_story_1011_10110502_24_dialog_content = "Bahan peledak sudah terpasang. Vice, Carleen, mundur!",
  ui_story_1011_10110502_25_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1011_10110502_26_dialog_content = "Apa kita berhasil?",
  ui_story_1011_10110502_27_dialog_content = "Sepertinya berhasil!",
  ui_story_1011_10110502_28_dialog_content = "Tapi, Barton masih di luar...",
  ui_story_1011_10110502_29_dialog_content = "Mindlink!",
  ui_story_1011_10110502_30_dialog_content = "Barton, kau baik-baik saja?",
  ui_story_1011_10110502_31_dialog_content = "Jangan khawatir. Aku baik-baik saja.",
  ui_story_1011_10110502_32_dialog_content = "Bagaimana situasi kalian?",
  ui_story_1011_10110502_33_dialog_content = "Pintu masuk terblokir. Jangan khawatirkan kami!",
  ui_story_1011_10110502_34_dialog_content = "Bagus. Sekarang aku bisa mengerahkan seluruh kemampuanku!",
  ui_story_1011_10110502_35_dialog_content = "Berhati-hatilah!",
  ui_story_1011_10110502_36_dialog_content = "Sekarang, ini semua di tangan kita.",
  ui_story_1011_10110502_37_dialog_content = "Cepat cari reruntuhannya.",
  ui_story_1011_10110502_38_dialog_content = "Pintu masuk yang dibarikade hanya bisa menahan mereka untuk sementara.",
  ui_story_1011_10110502_39_dialog_content = "Eclipsite punya cukup pasukan untuk menggali atau memanjat menara dan masuk dengan cara itu.",
  ui_story_1011_10110502_40_dialog_content = "Ayo berpencar.",
  ui_story_1011_10110502_41_dialog_content = "Kami mencari di setiap penjuru di sekitar sini.",
  ui_story_1011_10110502_42_dialog_content = "Hanya ada barang-barang biasa...",
  ui_story_1011_10110502_43_dialog_content = "Apakah ada cara lain?",
  ui_story_1011_10110502_44_dialog_content = "Sesuatu yang hanya diketahui oleh seorang Caelestite?",
  ui_story_1011_10110502_45_dialog_content = "Maksudmu, kemampuan psikisku?",
  ui_story_1011_10110502_46_dialog_content = "Ya.",
  ui_story_1011_10110502_47_dialog_content = "Bisakah kau menggunakan kemampuan psikismu dan mencari petunjuk?",
  ui_story_1011_10110502_48_dialog_content = "Akan kucoba.",
  ui_story_1011_10110502_49_option_content = "Mindlink!",
  ui_story_1011_10110502_50_dialog_content = "Aduh!",
  ui_story_1011_10110502_51_dialog_content = "Kepalaku!",
  ui_story_1011_10110502_52_dialog_content = "PlayerName?!",
  ui_story_1011_10110502_53_dialog_content = "Tempat ini sangat aneh.",
  ui_story_1011_10110502_54_dialog_content = "Ada yang menghentikan kemampuanku untuk menjelajah.",
  ui_story_1011_10110502_55_dialog_content = "Mengganggu kemampuan psikis Caelestite...",
  ui_story_1011_10110502_56_dialog_content = "Apakah ia mencoba menyembunyikan sesuatu?",
  ui_story_1011_10110502_57_dialog_content = "Itu berarti kita berada di jalan yang benar.",
  ui_story_1011_10110502_58_dialog_content = "Tapi, jika PlayerName tidak bisa menggunakan kemampuan psikis, kita tidak punya petunjuk untuk melanjutkan pencarian.",
  ui_story_1011_10110502_59_dialog_content = "Tidak juga. Masih ada jalan.",
  ui_story_1011_10110502_60_dialog_content = "Aku menemukan Echo Template untuk Soroz dengan menggunakan kemampuanku di Think Tank Module.",
  ui_story_1011_10110502_61_dialog_content = "Dan data Repair Module itulah yang mengarahkan kita ke sini.",
  ui_story_1011_10110502_62_dialog_content = "Aku bisa mencoba menggunakan kemampuanku pada Repair Module dan mencari solusi.",
  ui_story_1011_10110502_62X1_dialog_content = "Sebelumnya baik-baik saja saat aku mencoba merasakan Barton.",
  ui_story_1011_10110502_62X2_dialog_content = "Kurasa aku hanya perlu suatu target khusus.",
  ui_story_1011_10110502_63_dialog_content = "Terdengar boleh juga.",
  ui_story_1011_10110502_64_dialog_content = "Meski begitu...",
  ui_story_1011_10110502_65_dialog_content = "Kau harus segera memutuskan Mindlink setelah merasakan ada yang tidak beres. Kau dengar, PlayerName?",
  ui_story_1011_10110502_66_dialog_content = "Jangan terlalu memaksakan diri.",
  ui_story_1011_10110502_67_dialog_content = "Aku paham. Jangan khawatir.",
  ui_story_1011_10110502_68_option_content = "Forced Control!",
  ui_story_1011_10110502_69_dialog_content = "...",
  ui_story_1011_10110502_70_dialog_content = "Katakan padaku cara menuju ke Central Control Room!",
  ui_story_1011_10110502_71_dialog_content = "\"Perintah diterima. Memeriksa...\"",
  ui_story_1011_10110502_72_dialog_content = "\"Sistem kontrol akses sedang offline.\"",
  ui_story_1011_10110502_73_dialog_content = "\"Mengirim Firefly untuk tugas pemeliharaan.\"",
  ui_story_1011_10110502_74_dialog_content = "Firefly... dari Soroz?",
  ui_story_1011_10110502_75_dialog_content = "\"Bip!\"",
  ui_story_1011_10110502_76_dialog_content = "<color=#e8d9bb>Klik.</color>",
  ui_story_1011_10110502_77_dialog_content = "\"Kontrol akses unit daya cadangan terhubung. Mengaktifkan sistem kontrol akses.\"",
  ui_story_1011_10110502_78_dialog_content = "\"Masukkan kata sandi untuk verifikasi identitas.\"",
  ui_story_1011_10110502_79_dialog_content = "Apa?",
  ui_story_1011_10110502_80_dialog_content = "Dari mana asal suara itu?",
  ui_story_1011_10110502_81_dialog_content = "\"Ini adalah Colossus Maintenance Base Access Control System.\"",
  ui_story_1011_10110502_82_dialog_content = "\"Peringatan: Access Control System telah terputus dari Central Control System selama ■■■■■■■ hari.\"",
  ui_story_1011_10110502_83_dialog_content = "\"Buat kembali koneksi atau gunakan kata sandi reset.\"",
  ui_story_1011_10110502_84_dialog_content = "Kedengarannya seperti sesuatu yang mampu mengontrol pintu.",
  ui_story_1011_10110502_85_dialog_content = "Juga dikontrol dengan suara!",
  ui_story_1011_10110502_86_dialog_content = "\"Kata sandi tidak valid. Tersisa 3 upaya.\"",
  ui_story_1011_10110502_87_dialog_content = "Eh? Tidak! Bukan aku yang mencoba...",
  ui_story_1011_10110502_88_dialog_content = "\"Kata sandi tidak valid. Tersisa 2 upaya.\"",
  ui_story_1011_10110502_89_dialog_content = "Hei, tunggu!",
  ui_story_1011_10110502_90_dialog_content = "\"Kata sandi tidak valid. Tersisa 1 upaya.\"",
  ui_story_1011_10110502_91_dialog_content = "\"Perhatian: Kesalahan lebih lanjut akan mengunci Access Control System.\"",
  ui_story_1011_10110502_92_dialog_content = "Berhenti bicara!",
  ui_story_1011_10110502_93_dialog_content = "Mm! Mmm!",
  ui_story_1011_10110502_94_dialog_content = "Bisakah kita mereset kata sandi?!",
  ui_story_1011_10110502_95_dialog_content = "\"Peringatan: Jenis gen tidak cocok. Perintah tidak dikenali.\"",
  ui_story_1011_10110502_96_dialog_content = "...",
  ui_story_1011_10110502_97_dialog_content = "(Kau ingin aku mencoba?)",
  ui_story_1011_10110502_98_dialog_content = "Ini kesempatan terakhir. PlayerName, lakukanlah.",
  ui_story_1011_10110502_99_dialog_content = "Pastikan kau berpikir sebelum berbicara.",
  ui_story_1011_10110502_100_dialog_content = "(Baiklah...)",
  ui_story_1011_10110502_101_dialog_content = "...",
  ui_story_1011_10110502_102_option_content = "Access Control, reset kata sandi.",
  ui_story_1011_10110502_103_dialog_content = "\"Jenis gen diautentikasi. Mereset kata sandi.\"",
  ui_story_1011_10110502_104_dialog_content = "\"Jawab 3 pertanyaan berikut untuk verifikasi identitas.\"",
  ui_story_1011_10110502_105_dialog_content = "Pertanyaan keamanan?",
  ui_story_1011_10110502_106_dialog_content = "Kurasa aku tidak punya pilihan.",
  ui_story_1011_10110502_107_dialog_content = "Jangan khawatir, PlayerName. Kau pasti bisa.",
  ui_story_1011_10110502_108_dialog_content = "Aku mempertaruhkan reputasiku sebagai pelajar dengan nilai A semua!",
  ui_story_1011_10110502_109_dialog_content = "\"Apakah kau seorang Eclipsite?\"",
  ui_story_1011_10110502_110_dialog_content = "Eh...?",
  ui_story_1011_10110502_111_dialog_content = "Bagaimana mungkin aku seorang Eclipsite?!",
  ui_story_1011_10110502_112_dialog_content = "\"Respons tidak sah.\"",
  ui_story_1011_10110502_113_dialog_content = "\"Ulangi: Apakah kau seorang Eclipsite?\"",
  ui_story_1011_10110502_114_dialog_content = "Um... Bukan!",
  ui_story_1011_10110502_115_dialog_content = "\"Respons diterima.\"",
  ui_story_1011_10110502_116_dialog_content = "\"Apakah kau seorang Aurorian?\"",
  ui_story_1011_10110502_117_dialog_content = "Aku bukan seorang Aurorian.",
  ui_story_1011_10110502_118_dialog_content = "\"Respons diterima.\"",
  ui_story_1011_10110502_119_dialog_content = "\"Pilih Firefly dari pilihan berikut.\"",
  ui_story_1011_10110502_120_dialog_content = "Ini... proyeksi?",
  ui_story_1011_10110502_121_dialog_content = "Terlihat sangat nyata!",
  ui_story_1011_10110502_122_option_content = "Sentuh proyeksi Firefly",
  ui_story_1011_10110502_123_dialog_content = "\"Respons diterima.\"",
  ui_story_1011_10110502_124_dialog_content = "\"Identitas terverifikasi: Caelestite.\"",
  ui_story_1011_10110502_125_dialog_content = "\"Masukkan kata sandi baru.\"",
  ui_story_1011_10110502_126_dialog_content = "Emm... Abrakadabra!",
  ui_story_1011_10110502_127_dialog_content = "\"Kata sandi direset. Kata sandi baru: Emm... Abrakadabra.\"",
  ui_story_1011_10110502_128_dialog_content = "Infleksi bukan bagian dari kata sandi!",
  ui_story_1011_10110502_129_dialog_content = "\"Membuka pintu.\"",
  ui_story_1011_10110502_130_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_1011_10110502_131_dialog_content = "Woah!",
  ui_story_1011_10110502_132_dialog_content = "<color=#e8d9bb>*Gemuruh*</color>",
  ui_story_1011_10110502_133_dialog_content = "Dindingnya pecah! Hah...? Ada pintu di belakangnya?",
  ui_story_1011_10110502_134_dialog_content = "Itu sih raksasa!",
  ui_story_1011_10110502_135_dialog_content = "Tapi... Tadi itu apa?!",
  ui_story_1011_10110502_136_dialog_content = "Verifikasi identitas itu konyol!",
  ui_story_1011_10110502_137_dialog_content = "Makhluk cerdas mana pun bisa berbohong!",
  ui_story_1011_10110502_137X1_dialog_content = "Pertanyaan tersebut mungkin bukanlah kuncinya.",
  ui_story_1011_10110502_137X2_dialog_content = "Lalu apa?",
  ui_story_1011_10110502_137X3_dialog_content = "Bagaimana kau dapat memverifikasi seorang Caelestite melalui serangkaian pertanyaan sederhana?",
  ui_story_1011_10110502_137X4_dialog_content = "Sebelumnya saat aku mengajukan pertanyaan, ia merespons, \"Tipe gen tidak cocok.\"",
  ui_story_1011_10110502_137X5_dialog_content = "Entah bagaimana, aku percaya ia telah mengonfirmasi bahwa kau adalah keturunan Caelestite.",
  ui_story_1011_10110502_137X6_dialog_content = "Ia mengajukan semua pertanyaan itu hanya untuk membuatmu berkata, \"Aku seorang Caelestite.\"",
  ui_story_1011_10110502_137X7_dialog_content = "Jawaban afirmatif lebih penting daripada bukti lain?",
  ui_story_1011_10110502_137X8_dialog_content = "Kurasa beginilah cara kerja mesin.",
  ui_story_1011_10110502_137X9_dialog_content = "Maksudmu... reruntuhan ini memiliki teknologi untuk pelaksanaan tes gen jarak jauh?",
  ui_story_1011_10110502_137X10_dialog_content = "Aneh rasanya diterawang langsung begitu.",
  ui_story_1011_10110502_137X11_dialog_content = "Lupakan saja. Kita sudah mendapatkan hal yang kita perlukan.",
  ui_story_1011_10110502_137X12_dialog_content = "Pintunya terbuka. Tidak penting bagaimana itu terjadi.",
  ui_story_1011_10110502_138_dialog_content = "Tapi, berkat desainnya yang bodoh, kita bisa melewatinya.",
  ui_story_1011_10110502_139_dialog_content = "Pintu yang mengarah turun ini, pasti pintu masuk menuju reruntuhan bawah tanah.",
  ui_story_1011_10110502_140_dialog_content = "Namun, jika pintu macam ini memang selalu ada di sini, bagaimana Caelestite dapat melewatkannya selama bertahun-tahun?",
  ui_story_1011_10110502_141_dialog_content = "Entahlah... Semuanya di sini diselimuti misteri.",
  ui_story_1011_10110502_142_dialog_content = "Omong-omong, jalan ini berarti ada area di bawah tanah untuk kita jelajahi.",
  ui_story_1011_10110502_143_dialog_content = "Prioritas kita sekarang adalah menemukan cara untuk memperbaiki Soroz, melewati Eclipsite, dan menemukan jalan keluar dari sini.",
  ui_story_1011_10110502_144_dialog_content = "Kau benar. Kita tidak punya waktu untuk disia-siakan.",
  ui_story_1011_10110502_145_dialog_content = "Kalau begitu, ayo kita mulai!",
  ui_story_1011_10110601_1_dialog_content = "Graah!",
  ui_story_1011_10110601_2_dialog_content = "Bahkan tidak bisa melakukan penyergapan yang ampuh? Kau hanya umpan!",
  ui_story_1011_10110601_3_dialog_content = "Siapa yang mengirimmu? Eclipsite berukuran lebih besar? Atau ilmuwan gila?",
  ui_story_1011_10110601_4_dialog_content = "Hampir lupa bahwa kau bahkan tidak bisa berbicara.",
  ui_story_1011_10110601_5_dialog_content = "Gaar…",
  ui_story_1011_10110601_6_dialog_content = "Hahaha! Dasar sampah!",
  ui_story_1011_10110601_7_dialog_content = "Tidak ada gunanya membunuhmu. Segitu saja kemampuan Eclipsite?",
  ui_story_1011_10110601_8_dialog_content = "...",
  ui_story_1011_10110601_10_dialog_content = "Siapa di sana?",
  ui_story_1011_10110601_11_dialog_content = "...",
  ui_story_1011_10110601_12_dialog_content = "Jadi, itu benar-benar kau. <color=#FFB400>Denier</color>, pengkhianat Illumina.",
  ui_story_1011_10110601_13_dialog_content = "... Sebenarnya tidak. Kau bukan lagi bagian dari kami.",
  ui_story_1011_10110601_14_dialog_content = "Cih.",
  ui_story_1011_10110601_15_dialog_content = "Harus kubilang, jika kau ingin mengorbankan pasukanmu untuk membuat pengalihan, sebaiknya kau tidak ditangkap.",
  ui_story_1011_10110601_16_dialog_content = "(Pasukan...? Apakah mereka itu kaki tangan Figerald?)",
  ui_story_1011_10110601_17_dialog_content = "(Mereka itu selalu tak berguna...)",
  ui_story_1011_10110601_18_dialog_content = "Aku tidak mau berselisih dengan kalian, dan aku tidak mengirim para Eclipsite itu.",
  ui_story_1011_10110601_19_dialog_content = "Perang bodoh yang hanya akan mengubur rahasia yang tersembunyi di White Tower.",
  ui_story_1011_10110601_20_dialog_content = "(White Tower? Dia melacak PlayerName...?)",
  ui_story_1011_10110601_21_dialog_content = "Ha! Medan perang bukanlah tempat untuk berbasa-basi!",
  ui_story_1011_10110601_22_dialog_content = "Mau masuk? Lewati aku dulu.",
  ui_story_1011_10110601_23_dialog_content = "Aku sudah selesai berbicara denganmu. Terimalah, Forsakin!",
  ui_story_1011_10110601_24_dialog_content = "Rasakan kekuatan Ironjaw!",
  ui_story_1011_10110601_25_dialog_content = "<color=#e8d9bb>Duar!!!</color>",
  ui_story_1011_10110601_26_dialog_content = "Sungguh merepotkan. Ini tidak ada hubungannya denganmu.",
  ui_story_1011_10110601_27_dialog_content = "Aku benci situasi yang rumit.",
  ui_story_1011_10110601_28_dialog_content = "Tapi, jika hanya dengan membunuhmu membuatku terhindar masalah lebih lanjut... Akan kulakukan.",
  ui_story_1011_10110601_29_dialog_content = "Hahahaha! Itulah yang ingin kudengar!",
  ui_story_1011_10110601_30_dialog_content = "Mari, kita habiskan waktu bersama!",
  ui_story_1011_10110601_31_dialog_content = "<color=#e8d9bb>Lorong Masuk, Menara Utama</color>",
  ui_story_1011_10110601_32_dialog_content = "<color=#e8d9bb>*Gema jejak kaki*</color>",
  ui_story_1011_10110601_33_dialog_content = "(Betapa panjang dan sempitnya koridor yang tampak tiada akhirnya ini...)",
  ui_story_1011_10110601_34_dialog_content = "(Aku hampir tidak bisa melihat cahaya dari pintu masuk sekarang.)",
  ui_story_1011_10110601_35_dialog_content = "<color=#e8d9bb>Klang, klang...</color>",
  ui_story_1011_10110601_36_dialog_content = "Vice, awas!",
  ui_story_1011_10110601_37_dialog_content = "Apa?!",
  ui_story_1011_10110601_38_dialog_content = "<color=#e8d9bb>Duarr...</color>",
  ui_story_1011_10110601_39_dialog_content = "Hati-hati!",
  ui_story_1011_10110601_40_dialog_content = "*Batuk-batuk*",
  ui_story_1011_10110601_41_dialog_content = "Di sini sangat berdebu!",
  ui_story_1011_10110601_42_dialog_content = "<color=#e8d9bb><size=35>sini... sini... sini...</size></color>",
  ui_story_1011_10110601_43_dialog_content = "Hmm?",
  ui_story_1011_10110601_44_dialog_content = "Ssst. Jangan berisik.",
  ui_story_1011_10110601_45_dialog_content = "Sepertinya perjalanan kita masih panjang.",
  ui_story_1011_10110601_46_dialog_content = "Jika sesuatu mendatangi kita di koridor sempit seperti ini, kita tidak punya tempat untuk bersembunyi.",
  ui_story_1011_10110601_47_dialog_content = "Omong-omong, PlayerName...",
  ui_story_1011_10110601_48_dialog_content = "Kau benar-benar tidak tahu tempat ini ada sebelumnya?",
  ui_story_1011_10110601_49_dialog_content = "Ya... Bahkan Soroz tidak pernah menyebutkan tempat ini sebelumnya.",
  ui_story_1011_10110601_50_dialog_content = "Lagi pula, Soroz tidak tahu segalanya.",
  ui_story_1011_10110601_51_dialog_content = "...",
  ui_story_1011_10110601_52_dialog_content = "(Soroz...)",
  ui_story_1011_10110601_53_dialog_content = "Karena kita semua dipandu oleh Echo Template Plugin itu...",
  ui_story_1011_10110601_54_dialog_content = "Yang kita butuhkan hanyalah menemukan \"Central Control System\", 'kan?",
  ui_story_1011_10110601_55_dialog_content = "Akan kita temukan apa yang kita butuhkan untuk memperbaiki Soroz di sana, PlayerName.",
  ui_story_1011_10110601_56_dialog_content = "Terima kasih, Vice.",
  ui_story_1011_10110601_57_dialog_content = "Hah?",
  ui_story_1011_10110601_58_dialog_content = "Ada apa?",
  ui_story_1011_10110601_59_dialog_content = "Yang kita injak ini bukan kerikil atau batu putih biasa.",
  ui_story_1011_10110601_60_dialog_content = "Hmm... Coba kulihat.",
  ui_story_1011_10110601_61_dialog_content = "Warna dan teksturnya cukup unik. Dari yang kupelajari di Academy...",
  ui_story_1011_10110601_62_dialog_content = "Bahan batu ini hanya ada di Astra kuno...",
  ui_story_1011_10110601_63_dialog_content = "(Apa...?)",
  ui_story_1011_10110601_64_dialog_content = "Artinya bebatuan ini...",
  ui_story_1011_10110601_65_dialog_content = "<color=#FFB400>Colossus Patch</color>?",
  ui_story_1011_10110601_66_dialog_content = "?!",
  ui_story_1011_10110601_67_dialog_content = "(Jalan di depan ditutupi dengan remukan batu...)",
  ui_story_1011_10110601_68_dialog_content = "(Mungkinkah ini semua... <color=#FFB400>sisa-sisa</color>Colossus?)",
  ui_story_1011_10110601_69_dialog_content = "Artinya, kita berada di dalam Colossus Maintenance Base!",
  ui_story_1011_10110601_70_dialog_content = "Dilihat dari jumlahnya, Colossus pastilah kendaraan umum saat itu, seperti yang disebutkan legenda dan sejarah!",
  ui_story_1011_10110601_71_dialog_content = "Hei, PlayerName. Apakah itu ujung koridor?",
  ui_story_1011_10110601_72_dialog_content = "Umm... PlayerName. Kau baik-baik saja?",
  ui_story_1011_10110601_73_dialog_content = "...",
  ui_story_1011_10110601_74_option_content = "Merasa cemas",
  ui_story_1011_10110601_75_dialog_content = "Aku... Aku belum pernah melihat yang seperti ini.",
  ui_story_1011_10110601_76_dialog_content = "Soroz selalu menjadi keluargaku, temanku, dan mentorku...",
  ui_story_1011_10110601_77_dialog_content = "Ia telah melalui banyak hal dan tempat bersamaku...",
  ui_story_1011_10110601_78_dialog_content = "Tapi, aku tidak pernah menyangka bahwa suatu hari ia akan berakhir seperti ini.",
  ui_story_1011_10110601_79_option_content = "Aku merasa senang.",
  ui_story_1011_10110601_80_dialog_content = "Jumlah Colossus di Astra sedikit.",
  ui_story_1011_10110601_81_dialog_content = "Memikirkan kuburan besar Colossus yang ditinggalkan oleh leluhurku...",
  ui_story_1011_10110601_82_dialog_content = "Tepat di bawah Soroz dan kakiku di Eraveil yang telah kosong selama 17 tahun terakhir...",
  ui_story_1011_10110601_83_dialog_content = "Rasanya aku menjadi bagian dari tempat ini.",
  ui_story_1011_10110601_84_dialog_content = "Begitu, ya.",
  ui_story_1011_10110601_85_dialog_content = "Kalau begitu, ayo kita bergerak maju.",
  ui_story_1011_10110601_86_dialog_content = "Kita lihat dari mana asal semua sisa-sisa Colossus ini.",
  ui_story_1011_10110601_87_dialog_content = "Akhirnya, suatu tempat yang lebih terbuka.",
  ui_story_1011_10110601_88_dialog_content = "Kusangka di sini akan gelap, tetapi ternyata cukup terang juga.",
  ui_story_1011_10110601_89_dialog_content = "Tapi, bayangan Colossus yang kabur itu menghalangi pandanganku...",
  ui_story_1011_10110601_90_dialog_content = "Meskipun kita tak tahu dari mana cahaya ini berasal, setidaknya ini membuktikan bahwa kita tidak benar-benar di tempat tertutup.",
  ui_story_1011_10110601_91_dialog_content = "Lihatlah Colossus yang berjejer rapi...",
  ui_story_1011_10110601_92_dialog_content = "Padahal kondisinya bisa sangat terawat jika tempat ini tidak runtuh.",
  ui_story_1011_10110601_93_dialog_content = "PlayerName, kau harus mencoba kemampuan psikismu.",
  ui_story_1011_10110601_94_dialog_content = "Jika masih ada Colossus yang berfungsi, kau akan bisa membuat koneksi.",
  ui_story_1011_10110601_95_dialog_content = "Benar juga. Kalau begitu—",
  ui_story_1011_10110601_96_option_content = "Forced Control!",
  ui_story_1011_10110601_97_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1011_10110601_98_dialog_content = "Tidak. Tidak ada respons sama sekali.",
  ui_story_1011_10110601_99_dialog_content = "(Apa-apaan aku ini? Menemukan makhluk berkesadaran di dalam reruntuhan seperti ini hanya ada dalam mimpi...)",
  ui_story_1011_10110601_100_dialog_content = "S-Setidaknya kita pernah melihat Colossus ada di sini sebelumnya!",
  ui_story_1011_10110601_101_dialog_content = "Sekarang, mari kita periksa semuanya dari pintu ke pintu!",
  ui_story_1011_10110601_102_dialog_content = "Ayo, PlayerName.",
  ui_story_1011_10110601_103_dialog_content = "Benar. Kalau begitu...",
  ui_story_1011_10110601_104_option_content = "Periksa lingkungan sekitar",
  ui_story_1011_10110601_105_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1011_10110601_106_dialog_content = "Umm...?",
  ui_story_1011_10110601_107_dialog_content = "Tanganku sakit... Bahkan tidak bisa digerakkan!",
  ui_story_1011_10110601_108_dialog_content = "Dilihat dari kerusakan yang terjadi pada Colossus, aku ragu ruangannya masih utuh.",
  ui_story_1011_10110601_109_dialog_content = "Pintu-pintunya terhalang bebatuan yang runtuh. Sepertinya hanya ada satu jalan ke depan.",
  ui_story_1011_10110601_110_option_content = "Maju ke depan",
  ui_story_1011_10110601_111_dialog_content = "Hmm... Jalan ke depan sepertinya adalah tangga menuju ke lantai yang lebih rendah!",
  ui_story_1011_10110601_112_dialog_content = "I-Ini aman... Bukan? Maksudku, jika mereka masih ada setelah bertahun-tahun...",
  ui_story_1011_10110601_113_dialog_content = "Karena ada begitu banyak Colossus yang mendarat di dekat pintu masuk...",
  ui_story_1011_10110601_114_dialog_content = "Ruangan di bawah pasti penuh peralatan untuk melayani semua Colossus itu.",
  ui_story_1011_10110601_115_dialog_content = "Ayo lanjutkan, PlayerName.",
  ui_story_1011_10110601_116_dialog_content = "<color=#e8d9bb>*Gema jejak kaki*</color>",
  ui_story_1011_10110601_117_dialog_content = "(Pencahayaan tangganya sangat redup. Kaui ada Firefly di sini.)",
  ui_story_1011_10110601_118_dialog_content = "(Aku ingin tahu jenis teknologi apa yang ada di bawah sana, dan apakah itu bisa digunakan untuk Soroz...)",
  ui_story_1011_10110601_119_dialog_content = "(Kami akhirnya mencapai bagian bawah. Aku tidak sabar untuk memeriksanya—)",
  ui_story_1011_10110601_120_dialog_content = "Eh...?",
  ui_story_1011_10110601_121_dialog_content = "Ba-Bagaimana bisa...",
  ui_story_1011_10110601_122_dialog_content = "Tempat ini lega dan terbuka, tetapi tidak terlihat peralatan besar apa pun...",
  ui_story_1011_10110601_123_dialog_content = "Reruntuhan ini sepertinya jauh lebih luas dari yang kukira.",
  ui_story_1011_10110601_124_dialog_content = "Tapi, untuk apa lantai ini?",
  ui_story_1011_10110601_125_dialog_content = "Meja berdebu, rak batu dengan barang-barang yang tidak bisa lagi dikenali, dan kasur entah untuk apa...",
  ui_story_1011_10110601_126_dialog_content = "Mungkinkah ini ruang penyimpanan?",
  ui_story_1011_10110601_127_dialog_content = "Pfft... Hahaha! Setelah kau bilang begitu, sepertinya aku punya ide.",
  ui_story_1011_10110601_128_dialog_content = "Kuyakin ini bekas <color=#FFB400>tempat tinggal</color> Caelestite kuno.",
  ui_story_1011_10110601_129_dialog_content = "Fasilitas dasar serupa juga dapat dilihat di area pemukiman Undercity Illumina.",
  ui_story_1011_10110601_130_dialog_content = "Meskipun sebagian besar benda di sini telah hancur berkeping-keping, kau masih dapat mengenalinya...",
  ui_story_1011_10110601_131_dialog_content = "Meja makan, meja kerja, lemari makanan, rak, kasur...",
  ui_story_1011_10110601_132_dialog_content = "Barang-barang ini bukan barang biasa, Carleen.",
  ui_story_1011_10110601_133_dialog_content = "A-Aku paham sekarang!",
  ui_story_1011_10110601_134_dialog_content = "Hmm?",
  ui_story_1011_10110601_135_dialog_content = "Hei, Vice. Apa yang ada di cangkir itu?",
  ui_story_1011_10110601_136_dialog_content = "Hm? Di mana?",
  ui_story_1011_10110601_137_dialog_content = "Itu terlihat seperti noda biasa bagiku!",
  ui_story_1011_10110601_138_dialog_content = "Tidak, maksudku bagian dasar cangkirnya. PlayerName, coba lihat ini.",
  ui_story_1011_10110601_139_dialog_content = "Huh... Ini benar-benar terlihat seperti semacam simbol.",
  ui_story_1011_10110601_140_dialog_content = "Eh, benar juga!",
  ui_story_1011_10110601_141_dialog_content = "Mungkinkah simbol ini berkaitan dengan Caelestite...?",
  ui_story_1011_10110601_142_dialog_content = "Kurasa tidak. Lihatlah benda-benda di sekitarnya.",
  ui_story_1011_10110601_143_dialog_content = "Hanya cangkir ini yang punya tanda.",
  ui_story_1011_10110601_144_dialog_content = "Benar. Jika simbol ini benar-benar mewakili Caelestite, seharusnya ada di semua barang.",
  ui_story_1011_10110601_145_dialog_content = "Jadi, apa itu? Aku sungguh tidak tahu...",
  ui_story_1011_10110601_146_dialog_content = "Kurasa simbol ini menyerupai... inisial nama, tetapi...",
  ui_story_1011_10110601_147_dialog_content = "Tak bisa terbaca, tulisannya terlalu pudar.",
  ui_story_1011_10110601_148_dialog_content = "Kalau begitu, jangan buang waktu untuk itu.",
  ui_story_1011_10110601_149_dialog_content = "Hmm…",
  ui_story_1011_10110601_150_dialog_content = "(Bahkan jika PlayerName mengatakan itu, aku tidak bisa melupakannya begitu saja...)",
  ui_story_1011_10110601_151_dialog_content = "(Menemukan nama penghuni kuno di sini pasti adalah takdir.)",
  ui_story_1011_10110601_152_dialog_content = "(Aku akan memperhatikan apa pun yang terkait dengannya.)",
  ui_story_1011_10110601_153_dialog_content = "Hmm? Ada apa ini di atas meja?",
  ui_story_1011_10110601_154_dialog_content = "Luar biasa! Ini kan...",
  ui_story_1011_10110601_155_dialog_content = "Cangkang nautilus?",
  ui_story_1011_10110601_156_dialog_content = "Bukan satu, melainkan banyak.",
  ui_story_1011_10110601_157_dialog_content = "Um... Apakah itu kebutuhan dasar Caelestite, PlayerName?",
  ui_story_1011_10110601_158_dialog_content = "Eh? Apakah kau... baru saja menemukannya?",
  ui_story_1011_10110601_159_dialog_content = "Aku belum pernah melihat yang seperti itu. Mana mungkin aku tahu untuk apa itu.",
  ui_story_1011_10110601_160_dialog_content = "Nautilus? Bukankah ini makhluk laut?",
  ui_story_1011_10110601_161_dialog_content = "Mungkinkah... Eraveil dulunya adalah lautan? Atau orang Caelestite kuno memanfaatkannya untuk makanan?",
  ui_story_1011_10110601_162_dialog_content = "Semua yang baru saja kaukatakan terdengar konyol...",
  ui_story_1011_10110601_163_dialog_content = "Yah, cangkang nautilus ini tidak seperti yang kita tahu.",
  ui_story_1011_10110601_164_dialog_content = "Kecil dan halus, bobotnya sangat ringan, tetapi kondisinya masih sempurna setelah sekian tahun.",
  ui_story_1011_10110601_165_dialog_content = "Mungkin itu dirancang agar mudah dibawa dan disimpan.",
  ui_story_1011_10110601_166_dialog_content = "Juga... AAAAAH!",
  ui_story_1011_10110601_167_dialog_content = "Ada sesuatu di dalam!",
  ui_story_1011_10110601_168_dialog_content = "Apa?!",
  ui_story_1011_10110601_169_dialog_content = "Kau tak apa-apa? Tumpahkah?",
  ui_story_1011_10110601_170_dialog_content = "Aku tidak apa-apa, kok. Kelihatannya tidak sakit.",
  ui_story_1011_10110601_171_dialog_content = "*Endus endus*",
  ui_story_1011_10110601_172_dialog_content = "Tidak berbau, tidak berasa, tetapi mengalir cukup baik. Aku tidak tahu cairan apa itu.",
  ui_story_1011_10110601_173_dialog_content = "(Hah? Cangkang? Mengalir dengan baik?)",
  ui_story_1011_10110601_174_dialog_content = "(Jangan-jangan...)",
  ui_story_1011_10110601_175_dialog_content = "Hm... Tetap saja, lebih baik berhati-hati dan tidak menyentuh apa pun.",
  ui_story_1011_10110601_176_dialog_content = "Kau benar.",
  ui_story_1011_10110601_177_dialog_content = "(Lebih baik aku tutup mulut untuk saat ini sampai aku punya bukti.)",
  ui_story_1011_10110601_178_dialog_content = "(Tetapi, jika aku benar, buktinya seharusnya ada di sekitar sini di suatu tempat di reruntuhan.)",
  ui_story_1011_10110601_179_dialog_content = "(Aku akan memasukkannya ke dalam sakuku untuk saat ini...)",
  ui_story_1011_10110601_180_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1011_10110601_181_dialog_content = "Hah?!",
  ui_story_1011_10110601_182_dialog_content = "PlayerName, Carleen, sesuatu terjadi?",
  ui_story_1011_10110601_183_dialog_content = "Hm? Kupikir suara itu datang dari situ. Tunggu sebentar!",
  ui_story_1011_10110601_184_dialog_content = "... Ada yang tidak beres!",
  ui_story_1011_10110601_185_dialog_content = "Mungkinkah ada orang lain di sini?",
  ui_story_1011_10110601_186_dialog_content = "Jika itu masalahnya, mereka pasti sudah muncul. Kecuali itu—",
  ui_story_1011_10110601_187_dialog_content = "Gaar…",
  ui_story_1011_10110601_188_dialog_content = "Groar! Groar!!!",
  ui_story_1011_10110601_189_dialog_content = "Yang benar saja. Ada Eclipsite di sini?!",
  ui_story_1011_10110601_190_dialog_content = "Mereka masih berhasil mengikuti kita masuk?",
  ui_story_1011_10110601_191_dialog_content = "PlayerName, kau siap bertarung?",
  ui_story_1011_10110601_192_dialog_content = "Selalu!",
  ui_story_1011_10110702_1_dialog_content = "PlayerName, PlayerName!",
  ui_story_1011_10110702_2_dialog_content = "A-Apa yang terjadi...?",
  ui_story_1011_10110702_3_dialog_content = "Bangun, PlayerName!",
  ui_story_1011_10110702_4_dialog_content = "(Umm...)",
  ui_story_1011_10110702_5_dialog_content = "(Aku... Aku tidak bisa bernapas...)",
  ui_story_1011_10110702_6_dialog_content = "(Vice dan Carleen memanggilku? Kedengarannya sangat jauh...)",
  ui_story_1011_10110702_7_dialog_content = "(Aku...)",
  ui_story_1011_10110702_8_dialog_content = "Target Terdeteksi: Bentuk kehidupan supersensor. Identitas dikonfirmasi: Caelestite.)",
  ui_story_1011_10110702_9_dialog_content = "Mindlink ditetapkan.",
  ui_story_1011_10110702_10_dialog_content = "Peringatan: Kadar O2 turun di sistem pernapasan target. Sistem ventilasi area permukiman diaktifkan.",
  ui_story_1011_10110702_11_dialog_content = "<color=#e8d9bb>Wuush, wuush...</color>",
  ui_story_1011_10110702_12_dialog_content = "(S-Suara apa itu?)",
  ui_story_1011_10110702_13_dialog_content = "Hmm…?",
  ui_story_1011_10110702_14_dialog_content = "Oh, PlayerName!",
  ui_story_1011_10110702_15_dialog_content = "PlayerName! Kau sudah bangun!",
  ui_story_1011_10110702_16_dialog_content = "Bagaimana keadaanmu?",
  ui_story_1011_10110702_17_dialog_content = "Aku... Aku baik-baik saja sekarang.",
  ui_story_1011_10110702_18_dialog_content = "Pertarungan sengit menghabiskan energiku, dan perjalanan panjang di sini melelahkan... dan aku...",
  ui_story_1011_10110702_19_dialog_content = "Aku tidak bisa mengatur napasku barusan, jadi...",
  ui_story_1011_10110702_20_dialog_content = "Pertempuran sengit...?",
  ui_story_1011_10110702_21_dialog_content = "Melelahkan?",
  ui_story_1011_10110702_22_dialog_content = "...",
  ui_story_1011_10110702_23_dialog_content = "(Kenapa kau menatapku seperti itu...?!)",
  ui_story_1011_10110702_24_dialog_content = "Analisis target kondisi fisik...",
  ui_story_1011_10110702_25_dialog_content = "Status: Normal. Peringkat Fisik: A-.",
  ui_story_1011_10110702_26_dialog_content = "Hah?",
  ui_story_1011_10110702_27_dialog_content = "S-Siapa yang bilang itu?",
  ui_story_1011_10110702_28_dialog_content = "Itu tidak salah, tapi...",
  ui_story_1011_10110702_29_dialog_content = "Arahan utama Neural Aux adalah membantu Caelestite dengan segala cara yang mungkin.",
  ui_story_1011_10110702_30_dialog_content = "Diterima... Menganalisis pertanyaan...",
  ui_story_1011_10110702_31_dialog_content = "Jawaban Ditemukan: Bantuan dibutuhkan oleh Caelestite. Neural Aux berbicara kepada Caelestite.",
  ui_story_1011_10110702_32_dialog_content = "(Bahkan menjawab pertanyaan semudah itu butuh waktu lama?!)",
  ui_story_1011_10110702_33_dialog_content = "Tapi, setelah dipikir-pikir, ketika aku pingsan...",
  ui_story_1011_10110702_34_dialog_content = "Peringatan: Kadar O2 turun di sistem pernapasan target. Sistem ventilasi area permukiman diaktifkan.",
  ui_story_1011_10110702_35_dialog_content = "Jadi, ia mengaktifkan sistem ventilasi di sini untuk membantuku.",
  ui_story_1011_10110702_36_dialog_content = "Oh... Tidak heran aku merasakan... angin segar menerpa kulitku.",
  ui_story_1011_10110702_36X_dialog_content = "Apa itu? Tampak seperti hologram.",
  ui_story_1011_10110702_37_dialog_content = "Teknologi Caelestite kuno? Terbukti cukup andal pada saat darurat.",
  ui_story_1011_10110702_38_dialog_content = "Wah! Coba kulihat. Bagaimana bisa kita memiliki AI yang masih berfungsi!",
  ui_story_1011_10110702_39_dialog_content = "Hmm…",
  ui_story_1011_10110702_40_dialog_content = "...",
  ui_story_1011_10110702_41_dialog_content = "Subjek Terdeteksi: Bentuk Kehidupan Luminatic. Identitas Dikonfirmasi: Aurorian. Jumlah: 2.",
  ui_story_1011_10110702_42_dialog_content = "\"Neural Aux\"... Kau teknologi Caelestite kuno?",
  ui_story_1011_10110702_43_dialog_content = "Diterima... Menganalisis pertanyaan. Kesalahan. Arahan utama Neural Aux adalah untuk membantu Caelestite dengan segala cara yang mungkin.",
  ui_story_1011_10110702_44_dialog_content = "A-Apa?! Jadi, Aurorian tidak bisa menggunakan instrumen Caelestite?",
  ui_story_1011_10110702_45_dialog_content = "Diterima... Menganalisis pertanyaan. Kesalahan. Arahan utama Neural Aux adalah untuk membantu Caelestite dengan segala cara yang mungkin.",
  ui_story_1011_10110702_46_dialog_content = "Astaga. Itu bukan pertanyaan!",
  ui_story_1011_10110702_47_dialog_content = "Apakah ada Aurorian yang memberitahumu bahwa kau memiliki kepribadian yang buruk?",
  ui_story_1011_10110702_48_dialog_content = "Tenanglah, Vice. Biar kutanyakan pertanyaanmu.",
  ui_story_1011_10110702_49_dialog_content = "N-Neural Aux, aku punya beberapa pertanyaan—",
  ui_story_1011_10110702_50_dialog_content = "Permintaan diterima. Memodifikasi sistem... Konfirmasi nama sistem baru: N-Neural Aux.",
  ui_story_1011_10110702_51_dialog_content = "Hah? Tunggu! Tidak! Batalkan permintaan! Batalkan permintaan!",
  ui_story_1011_10110702_52_dialog_content = "Permintaan dibatalkan.",
  ui_story_1011_10110702_53_dialog_content = "(Sekarang aku mengerti. Meskipun AI ini dari zaman kuno...)",
  ui_story_1011_10110702_54_dialog_content = "(Ia tidak terlalu pintar...)",
  ui_story_1011_10110702_55_dialog_content = "(Aku harus memecah pertanyaan agar ia bisa memahamiku lebih baik...)",
  ui_story_1011_10110702_56_dialog_content = "Ehem... Pertanyaan pertama: Beri tahu aku tentang menara ini.",
  ui_story_1011_10110702_57_dialog_content = "Diterima... Menganalisis pertanyaan...",
  ui_story_1011_10110702_58_dialog_content = "Jawaban Ditemukan: Ini adalah <color=#FFB400>Obelisk of Return</color>.",
  ui_story_1011_10110702_59_dialog_content = "(Obelisk of Return? Terdengar seperti semacam struktur panduan navigasi... seperti mercusuar.)",
  ui_story_1011_10110702_60_dialog_content = "Return... Apa artinya? Apakah Soroz membawa kita ke sini... untuk kembali ke tempat ini?",
  ui_story_1011_10110702_61_dialog_content = "Maaf. Aku tidak tahu.",
  ui_story_1011_10110702_62_dialog_content = "(J-Jadi, dia hanya memberitahuku bahwa dia tidak tahu. Begitu saja?!)",
  ui_story_1011_10110702_63_dialog_content = "Bagus. Pertanyaan kedua: Seperti apa struktur internal menara ini?",
  ui_story_1011_10110702_64_dialog_content = "Di mana posisi kita di menara?",
  ui_story_1011_10110702_65_dialog_content = "Memutar rekaman pengantar Neural Aux: Unit Neural Aux adalah asisten AI yang dirancang untuk Obelisk of Return...",
  ui_story_1011_10110702_66_dialog_content = "Unit Neural Aux menyediakan bantuan kepada Caelestite berdasarkan level akses dan perintah mereka.",
  ui_story_1011_10110702_67_dialog_content = "Mengonfirmasi level akses Caelestite...",
  ui_story_1011_10110702_68_dialog_content = "Level akses dikonfirmasi. Neural Aux dapat memberimu peta Obelisk of Return.",
  ui_story_1011_10110702_69_dialog_content = "(Peta itu akan sangat membantu!)",
  ui_story_1011_10110702_70_dialog_content = "Bagus! Sekarang kita tahu ke mana tujuan kita!",
  ui_story_1011_10110702_71_dialog_content = "Ayo cepat temukan tempat itu untuk memperbaiki Soroz.",
  ui_story_1011_10110702_72_dialog_content = "(Hmm... Aku tidak akan terlalu berharap, tetapi tidak ada salahnya mencoba...)",
  ui_story_1011_10110702_73_dialog_content = "Pertanyaan terakhir. Beri tahu aku cara masuk ke Central Control System.",
  ui_story_1011_10110702_74_dialog_content = "...",
  ui_story_1011_10110702_75_dialog_content = "Maaf. Aku tidak tahu.",
  ui_story_1011_10110702_76_dialog_content = "Beeboo... Beeboo....",
  ui_story_1011_10110702_77_dialog_content = "(Kenapa ia tiba-tiba menyenandungkan sebuah lagu?!)",
  ui_story_1011_10110702_78_dialog_content = "Lupakan saja, PlayerName. Mari, kita lanjutkan. Ini lebih baik daripada tidak sama sekali.",
  ui_story_1011_10110702_79_dialog_content = "Karena kini kita sudah punya peta menara, kita konfirmasi lokasinya dengan Neural Aux.",
  ui_story_1011_10110702_80_dialog_content = "Baiklah. Coba kulihat.",
  ui_story_1011_10110702_81_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1011_10110702_82_dialog_content = "Begitu, ya. Lantai yang berbeda dari menara ini memilik fungsi yang berbeda. Kita masih di lantai yang lebih tinggi.",
  ui_story_1011_10110702_83_dialog_content = "Lantai tempat kita pertama masuk ke menara adalah Colossus Maintenance Base.",
  ui_story_1011_10110702_84_dialog_content = "Kondisinya, seperti yang baru saja kita lihat, hampir hancur total.",
  ui_story_1011_10110702_85_dialog_content = "Lantai tempat kita berada sekarang, adalah Caelestite Residential, seperti yang diperkirakan Vice...",
  ui_story_1011_10110702_86_dialog_content = "Kita juga telah melewatinya.",
  ui_story_1011_10110702_87_dialog_content = "Sayang, banyak ruangan yang terhalang puing...",
  ui_story_1011_10110702_88_dialog_content = "Colossus Component Storage, Resource Production Room, Waste Disposal Facility... Semuanya terkubur.",
  ui_story_1011_10110702_89_dialog_content = "Soroz...",
  ui_story_1011_10110702_90_dialog_content = "Jangan menyerah dulu. Masih banyak sekali lantai yang bisa dijelajahi.",
  ui_story_1011_10110702_91_dialog_content = "Aku mungkin terlalu optimistis, tetapi, hei, kita makin banyak mengumpulkan intel seiring berjalannya waktu, bukan?",
  ui_story_1011_10110702_92_dialog_content = "Ya, jangan menyerah, PlayerName. Kita akan menemukan jalannya.",
  ui_story_1011_10110702_93_dialog_content = "Ya. Cepat lanjutkan ke area berikutnya.",
  ui_story_1011_10110702_94_dialog_content = "Lantai selanjutnya adalah... <color=#FFB400>Exile Zone</color>?",
  ui_story_1011_10110702_95_dialog_content = "Exiled? Terasing?",
  ui_story_1011_10110702_96_dialog_content = "Aku tidak mengerti... Caelestite adalah ras pencinta damai. Mengapa mereka memiliki area yang dikhususkan untuk hal semacam ini...?",
  ui_story_1011_10110702_97_dialog_content = "Yah, masuk akal jika ia mengacu pada Eclipsites kuno.",
  ui_story_1011_10110702_98_dialog_content = "Omong-omong, bagiku sepertinya itu bukan tempat bagus untuk ditinggali. Sebaiknya kita berhati-hati.",
  ui_story_1011_10110901_1_dialog_content = "<color=#e8d9bb>Obelisk of Return: Exile Zone</color>",
  ui_story_1011_10110901_2_dialog_content = "Fyuh... Fyuh...",
  ui_story_1011_10110901_3_dialog_content = "(Karena ini aku tahu untuk apa lantai ini... Aku bahkan lebih gugup...)",
  ui_story_1011_10110901_4_dialog_content = "(Jika ada Eclipsite yang berani menyergap, aku pasti akan murka besar!)",
  ui_story_1011_10110901_5_dialog_content = "Beeboo... Beeboo.... ♪",
  ui_story_1011_10110901_6_dialog_content = "Bip bip bip... bip bip bip... ♪",
  ui_story_1011_10110901_7_dialog_content = "\"Masa lalu tetaplah masa lalu. Yang tersisa tetaplah tersisa... ♪\"",
  ui_story_1011_10110901_8_dialog_content = "Ugh! Berisik sekali!",
  ui_story_1011_10110901_9_dialog_content = "PlayerName, minta dia agar jangan berisik. Terlebih lagi di tempat yang menakutkan seperti ini.",
  ui_story_1011_10110901_10_dialog_content = "Biar kucoba untuk terhubung dengannya...",
  ui_story_1011_10110901_11_dialog_content = "Mindlink ditetapkan.",
  ui_story_1011_10110901_12_dialog_content = "Neural Aux akan memutar musik acak ketika tidak ada ancaman yang terdeteksi.",
  ui_story_1011_10110901_13_dialog_content = "Apakah kau menikmati musik dari masa lalu ini?",
  ui_story_1011_10110901_14_dialog_content = "Anggap saja barang sejenak bahwa melodi dan nada yang rusak dianggap sebagai \"musik\"...",
  ui_story_1011_10110901_15_dialog_content = "Caelestite diizinkan untuk mengedit daftar putar Neural Aux...",
  ui_story_1011_10110901_16_dialog_content = "Kau juga bisa mengaktifkan fungsi pembelajaran otomatis Neural Aux untuk mengakomodasi preferensi pribadimu. Aktifkan sekarang?",
  ui_story_1011_10110901_17_dialog_content = "Tidak perlu...",
  ui_story_1011_10110901_18_dialog_content = "(Maksudku, musik ini layaknya gema dari masa lalu.)",
  ui_story_1011_10110901_19_dialog_content = "Namun, karena Neural Aux dapat mendeteksi apakah suatu area aman atau tidak...",
  ui_story_1011_10110901_20_dialog_content = "Kita bisa sedikit bersantai.",
  ui_story_1011_10110901_21_dialog_content = "Meski begitu, lantai ini masih membuatku tidak nyaman.",
  ui_story_1011_10110901_22_dialog_content = "...meskipun tidak ada tanda-tanda kehidupan...",
  ui_story_1011_10110901_23_dialog_content = "Hei, lihat bagian belakang pintu.",
  ui_story_1011_10110901_24_dialog_content = "B-Bekas cakaran...?",
  ui_story_1011_10110901_25_dialog_content = "Dilihat dari konstruksi ruangan-ruangan yang begitu rapat, kurasa tempat ini...",
  ui_story_1011_10110901_26_dialog_content = "Seperti itulah penjara Lumopolis.",
  ui_story_1011_10110901_27_dialog_content = "...",
  ui_story_1011_10110901_28_dialog_content = "Tapi, kenapa mereka bersusah payah mengurung Eclipsite? Membunuh mereka akan lebih mudah.",
  ui_story_1011_10110901_29_dialog_content = "Mungkinkah Caelestite kuno tidak memiliki kemampuan tempur yang baik?",
  ui_story_1011_10110901_30_dialog_content = "Sepertinya tidak. Bahkan jika tidak, tingkat teknologi mereka...",
  ui_story_1011_10110901_31_dialog_content = "Itu sudah cukup untuk membuat senjata pertempuran dan pertahanan yang kuat.",
  ui_story_1011_10110901_32_dialog_content = "<color=#e8d9bb>Ding!</color>",
  ui_story_1011_10110901_33_dialog_content = "Hah?",
  ui_story_1011_10110901_34_dialog_content = "Kau menendang sesuatu?",
  ui_story_1011_10110901_35_dialog_content = "Biar kulihat...",
  ui_story_1011_10110901_36_dialog_content = "Eh?!",
  ui_story_1011_10110901_37_dialog_content = "Tanda nama logam?!",
  ui_story_1011_10110901_38_dialog_content = "\"Nama: Tenoki. Identitas: Caelestite.\"",
  ui_story_1011_10110901_39_dialog_content = "\"<color=#FFB400>Masa Pengasingan</color>: 14 tahun.\"",
  ui_story_1011_10110901_40_dialog_content = "Lalu yang ini: \"Nama: Lanti. Identitas: Caelestite. Masa Pengasingan: 12 tahun.\"",
  ui_story_1011_10110901_41_dialog_content = "Sel-sel ini mengurung Caelestite sepertimu, PlayerName.",
  ui_story_1011_10110901_42_dialog_content = "Artinya, Exile Zone mengurung Caelestite yang diasingkan?!",
  ui_story_1011_10110901_43_dialog_content = "Namun,... mengapa mereka mengurung rakyat mereka sendiri?",
  ui_story_1011_10110901_44_dialog_content = "Apakah \"cinta damai\" itu sekadar ilusi?",
  ui_story_1011_10110901_45_dialog_content = "Tenang, PlayerName. Kita tidak punya cukup informasi untuk menarik kesimpulan.",
  ui_story_1011_10110901_46_dialog_content = "Pikirkan saja. Jika Caelestite kuno terdiri dari sekelompok besar orang...",
  ui_story_1011_10110901_47_dialog_content = "Bagaimanapun, ketertiban harus ditegakkan.",
  ui_story_1011_10110901_48_dialog_content = "Bahkan jika itu benar, Caelestite bisa mencapai tujuan yang sama melalui Mindlink kita.",
  ui_story_1011_10110901_49_dialog_content = "Tidak masuk akal menghukum mereka begitu lama dalam pengasingan.",
  ui_story_1011_10110901_50_dialog_content = "Neural Aux, jawab aku.",
  ui_story_1011_10110901_51_dialog_content = "Diterima... Menganalisis pertanyaan... Kata kunci diperoleh. Menjawab:",
  ui_story_1011_10110901_52_dialog_content = "<color=#FFB400>Master Francis</color> pernah berkata, \"Sejak saat itu, kami bukan lagi kerabat mereka.\"",
  ui_story_1011_10110901_53_dialog_content = "?!",
  ui_story_1011_10110901_54_dialog_content = "Apa artinya, \"kami bukan lagi kerabat mereka\"?",
  ui_story_1011_10110901_55_dialog_content = "Dan siapa \"mereka\" itu?",
  ui_story_1011_10110901_56_dialog_content = "Apakah Caelestite terpecah oleh <color=#FFB400>konflik internal yang tidak dapat didamaikan</color> ribuan tahun lalu?",
  ui_story_1011_10110901_57_dialog_content = "(Apakah ini awal dari perang saudara mereka?)",
  ui_story_1011_10110901_57X1_dialog_content = "Diterima... Menganalisis pertanyaan...",
  ui_story_1011_10110901_57X2_dialog_content = "Berdasarkan data yang kita miliki, dulu sebagian besar Caelestite tidak berhubungan baik dengan Master Francis.",
  ui_story_1011_10110901_57X3_dialog_content = "Dia memang menjalani hukuman di Exile Zone.",
  ui_story_1011_10110901_57X3X1_dialog_content = "Omong-omong, tempat ini dibangun untuk menahan para Caelestite yang sesat.",
  ui_story_1011_10110901_57X3X2_dialog_content = "Master Francis dan semua peneliti bawahannya diasingkan berdasarkan tuduhan yang sama...",
  ui_story_1011_10110901_57X3X3_dialog_content = "Tuduhannya adalah penghasutan dan penyebaran ide-ide progresif.",
  ui_story_1011_10110901_57X4_dialog_content = "Semua kata yang terkait dengan Francis tidak layak dilihat... Kau akan mendengar kata-kata seperti:",
  ui_story_1011_10110901_57X5_dialog_content = "Orang aneh, orang gila, ahli pengendali pikiran, kolektor otak...",
  ui_story_1011_10110901_57X6_dialog_content = "Err... PlayerName, tolong hentikan...",
  ui_story_1011_10110901_57X7_dialog_content = "Kedengarannya seperti... periset yang tak lazim?",
  ui_story_1011_10110901_57X8_dialog_content = "Master Francis mendedikasikan dirinya untuk mempelajari teknologi baru.",
  ui_story_1011_10110901_57X9_dialog_content = "Dia pernah berkata, \"Perjalanan riset itu panjang dan berbatu. Disalahpahami adalah hal biasa.\"",
  ui_story_1011_10110901_57X10_dialog_content = "Master Francis juga merupakan otak di balik penemuan besar lainnya.",
  ui_story_1011_10110901_57X11_dialog_content = "Caelestite, kalau dinilai dari identitas rekanmu, penemuan besar ini pasti telah mengubah dunia.",
  ui_story_1011_10110901_57X12_dialog_content = "Mengubah dunia?",
  ui_story_1011_10110901_57X13_dialog_content = "Kau jelas menunjukkan perubahan sikap dan kebiasaan dibandingkan dengan Caelestite kuno.",
  ui_story_1011_10110901_57X14_dialog_content = "Sekarang kau punya musuh dan kebencian yang sama dengan Aurorian dan Demi-human.",
  ui_story_1011_10110901_57X15_dialog_content = "Master Francis akan sangat bersyukur melihat ini.",
  ui_story_1011_10110901_57X16_dialog_content = "Sikap dan kebiasaan? Jadi... Caelestite kuno punya sikap dan kebiasaan apa?",
  ui_story_1011_10110901_57X17_dialog_content = "Apa persisnya \"penemuan terhebat\" ini?",
  ui_story_1011_10110901_58_dialog_content = "Mengonfirmasi level akses Caelestite...",
  ui_story_1011_10110901_59_dialog_content = "Level akses tidak memadai. Maaf, aku tidak bisa menjawab pertanyaanmu.",
  ui_story_1011_10110901_60_dialog_content = "Baiklah. Aku akan menanyakan sesuatu yang lain kalau begitu.",
  ui_story_1011_10110901_61_dialog_content = "Mari, kita kembali ke kalimat ini...",
  ui_story_1011_10110901_61X1_dialog_content = "\"Sejak saat itu, kami bukan lagi kerabat mereka\".",
  ui_story_1011_10110901_63_dialog_content = "Apakah dia mengacu pada Caelestite ketika dia mengatakan \"kami\"?",
  ui_story_1011_10110901_64_dialog_content = "Jawaban: \"Kami\" adalah Caelestite.",
  ui_story_1011_10110901_65_dialog_content = "...",
  ui_story_1011_10110901_66_dialog_content = "Kesalahan. Kesalahan! Neural Aux bukan Caelestite.",
  ui_story_1011_10110901_67_dialog_content = "Memutar rekaman pengantar Neural Aux: Unit Neural Aux adalah asisten AI yang dirancang untuk Obelisk of Return...",
  ui_story_1011_10110901_68_dialog_content = "Dengarkan aku! Tidak ada yang bilang kau ini seorang Caelestite!",
  ui_story_1011_10110901_69_dialog_content = "Unit Neural Aux menyediakan bantuan kepada Caelestite berdasarkan level akses dan perintah mereka.",
  ui_story_1011_10110901_70_dialog_content = "Sudahlah. Sudah cukup...",
  ui_story_1011_10110901_71_dialog_content = "Francis?",
  ui_story_1011_10110901_72_dialog_content = "PlayerName, kau ingat cangkir yang kita lihat di lantai sebelumnya?",
  ui_story_1011_10110901_73_dialog_content = "Ya, ya, aku ingat, inisial buram di bagian dasar cangkir berbunyi...",
  ui_story_1011_10110901_74_dialog_content = "Itu cangkir Francis...?",
  ui_story_1011_10110901_75_dialog_content = "Diterima... Menganalisis pertanyaan... Jawaban ditemukan: Master Francis senang mengonsumsi minuman suplemen.",
  ui_story_1011_10110901_76_dialog_content = "Master Francis selalu terlihat memegang cangkir.",
  ui_story_1011_10110901_77_dialog_content = "(Jadi, tebakan kami benar...)",
  ui_story_1011_10110901_78_dialog_content = "Memutar rekaman iklan minuman energi: Minuman energi eksklusif untuk Obelisk of Return. Minuman ini memberikan—",
  ui_story_1011_10110901_79_dialog_content = "(Tidak perlu memberi kami intel yang tidak berguna seperti itu!)",
  ui_story_1011_10110901_80_dialog_content = "Minuman ini tersedia di Caelestite Residential, Resource Production Room, Exile Zone...",
  ui_story_1011_10110901_81_dialog_content = "Semua penduduk dapat membelinya langsung dari dispenser otomatis di area yang disebutkan.",
  ui_story_1011_10110901_82_dialog_content = "(Dispenser otomatis?)",
  ui_story_1011_10110901_83_dialog_content = "(Aku paham sekarang!)",
  ui_story_1011_10110901_84_dialog_content = "PlayerName, Carleen, ikuti aku!",
  ui_story_1011_10110901_85_dialog_content = "<color=#e8d9bb>Obelisk of Return: Exile Zone - Dispenser Otomatis</color>",
  ui_story_1011_10110901_86_dialog_content = "<color=#e8d9bb>Klang... Bang!</color>",
  ui_story_1011_10110901_87_dialog_content = "L-Luar biasa! Jadi, yang dibutuhkan hanyalah menendangnya agar kembali berfungsi!",
  ui_story_1011_10110901_88_dialog_content = "Apakah ini dispenser otomatis yang Neural Aux bicarakan?",
  ui_story_1011_10110901_89_dialog_content = "Ini... kelihatannya tidak asing.",
  ui_story_1011_10110901_90_dialog_content = "Benar. AI dan dispenser otomatis sepertinya merupakan pengaturan standar reruntuhan bawah tanah.",
  ui_story_1011_10110901_91_dialog_content = "Ha! Kalian berdua, lihat saja dan pelajari.",
  ui_story_1011_10110901_92_dialog_content = "Hmm... Ini dia!",
  ui_story_1011_10110901_93_dialog_content = "Hah? Kau mengambilnya?",
  ui_story_1011_10110901_94_dialog_content = "Yah, aku ingin menguji teoriku.",
  ui_story_1011_10110901_95_dialog_content = "Ketika kulihat bentuk cangkangnya dan cara ia menampung cairan di dalamnya, aku mulai bertanya-tanya...",
  ui_story_1011_10110901_96_dialog_content = "Caelestite memiliki cangkir untuk menampung air minum, tetapi mereka tidak benar-benar makan kerang.",
  ui_story_1011_10110901_97_dialog_content = "Jadi, apa yang dilakukan Caelestite kuno dengan benda seperti ini?",
  ui_story_1011_10110901_98_dialog_content = "Tapi, sekarang aku cukup yakin untuk apa. Lihat ini—",
  ui_story_1011_10110901_99_dialog_content = "Jika aku menuangkan cairan di dalam cangkang nautilus ke dalam dispenser otomatis...",
  ui_story_1011_10110901_100_dialog_content = "<color=#e8d9bb>Ding! Bang!</color>",
  ui_story_1011_10110901_101_dialog_content = "Voila!",
  ui_story_1011_10110901_102_dialog_content = "Ta ra! Satu minuman energi muncul. Bagaimanapun, sudah lama kedaluwarsa.",
  ui_story_1011_10110901_103_dialog_content = "Bagaimana bisa kau terpikirkan ide semacam ini?!",
  ui_story_1011_10110901_104_dialog_content = "Aku mulai memikirkannya ketika melihat cangkang itu.",
  ui_story_1011_10110901_105_dialog_content = "Kau lihat, garis-garis pada cangkang nautilus itu sebenarnya memiliki makna.",
  ui_story_1011_10110901_106_dialog_content = "Itu adalah konsep matematis yang umum ditemui di alam.",
  ui_story_1011_10110901_107_dialog_content = "Alam...? Aku tidak mengerti. Apa hubungannya garis dengan alam?",
  ui_story_1011_10110901_108_dialog_content = "Garis-garis itu tidak menyerupai pohon, bunga, atau apa pun.",
  ui_story_1011_10110901_109_dialog_content = "Tentu, pohon dan bunga adalah bagian dari Ibu Pertiwi.",
  ui_story_1011_10110901_110_dialog_content = "Tapi, garis menggambarkan filosofi di balik alam.",
  ui_story_1011_10110901_111_dialog_content = "Pola garis spiral di cangkang nautilus melambangkan hal-hal yang alami.",
  ui_story_1011_10110901_112_dialog_content = "Atau kau bisa menyebutnya sebagai \"perkembangan\".",
  ui_story_1011_10110901_113_dialog_content = "Perkembangan?",
  ui_story_1011_10110901_114_dialog_content = "Ya. Misalnya anak pohon. Ia tidak akan tumbuh tiba-tiba menjadi pohon besar.",
  ui_story_1011_10110901_115_dialog_content = "Ia tumbuh setiap detik setiap menit.",
  ui_story_1011_10110901_116_dialog_content = "Dan \"perkembangan\" mengacu pada evolusi ini.",
  ui_story_1011_10110901_117_dialog_content = "Benar. Aku mengerti sekarang, sepertinya.",
  ui_story_1011_10110901_118_dialog_content = "Sekarang, karena matematika Caelestite kuno didasarkan pada \"perkembangan\"...",
  ui_story_1011_10110901_119_dialog_content = "Kemudian, pasti ada sedikit perbedaan antara cara hidup mereka dan cara hidup kita.",
  ui_story_1011_10110901_120_dialog_content = "Perbedaan yang paling jelas adalah mata uang.",
  ui_story_1011_10110901_121_dialog_content = "Benar! Maksudmu, koin atau uang kertas kita tidak \"progresif\", bukan?",
  ui_story_1011_10110901_122_dialog_content = "Benar sekali. Dalam hal mata uang mereka, cangkang nautilus ini sudah memberitahumu banyak informasi.",
  ui_story_1011_10110901_123_dialog_content = "Mata uangnya... cairan?",
  ui_story_1011_10110901_124_dialog_content = "Begitu, ya. Jadi cangkang nautilus ini digunakan sebagai dompet mereka?",
  ui_story_1011_10110901_125_dialog_content = "Diterima... Menganalisis pertanyaan... Jawaban: Cangkang adalah wadah mata uang.",
  ui_story_1011_10110901_126_dialog_content = "Nilai barang di Obelisk of Return diukur dengan volume cairan.",
  ui_story_1011_10110901_127_dialog_content = "Transaksi dilakukan melalui pertukaran cairan yang ditampung di dalam cangkang.",
  ui_story_1011_10110901_128_dialog_content = "Aku paham sekarang, meskipun aku masih tidak mengerti hal semacam ini secara keseluruhan...",
  ui_story_1011_10110901_129_dialog_content = "Tapi, itu terdengar seperti sistem yang \"cukup\" bagus.",
  ui_story_1011_10110901_130_dialog_content = "Menyembah konsep \"alam\" dengan menguantifikasi \"perkembangan\"...",
  ui_story_1011_10110901_131_dialog_content = "Memang cocok dengan gambaran umum Caelestite.",
  ui_story_1011_10110901_132_dialog_content = "Kau luar biasa, Vice. Begitulah Neural Aux mengatakannya!",
  ui_story_1011_10110901_133_dialog_content = "K-Kau membuatku tersipu...",
  ui_story_1011_10110901_134_dialog_content = "Kita harus melanjutkan.",
  ui_story_1011_10110901_135_dialog_content = "Tapi, tidak ada tangga untuk turun.",
  ui_story_1011_10110901_136_dialog_content = "Apakah Exile Zone ada di bagian bawah menara?",
  ui_story_1011_10110901_137_dialog_content = "Kurasa tidak. Peta Neural Aux menunjukkan Exile Zone terletak di tengah.",
  ui_story_1011_10110901_138_dialog_content = "Neural Aux, bagaimana kami bisa turun ke lantai selanjutnya?",
  ui_story_1011_10110901_139_dialog_content = "Diterima... Menganalisis pertanyaan... Jawaban: Jalan turun ke lantai berikutnya telah runtuh.",
  ui_story_1011_10110901_140_dialog_content = "Jalan turun ke lantai berikutnya...",
  ui_story_1011_10110901_141_dialog_content = "...hanya bisa diakses melalui celah antara dua dispenser otomatis di belakangmu.",
  ui_story_1011_10110901_142_dialog_content = "<color=#e8d9bb>Obelisk of Return: Celah</color>",
  ui_story_1011_10110901_143_dialog_content = "Hmm... Di sini sangat gelap dan sempit, jauh lebih sempit daripada jalan masuk tadi.",
  ui_story_1011_10110901_144_dialog_content = "Pergerakan tubuhku juga sangat terbatas.",
  ui_story_1011_10110901_145_dialog_content = "(Kuharap kita tidak menyebabkan keruntuhan lagi dengan memaksa jalan kita lewat sini...)",
  ui_story_1011_10110901_146_dialog_content = "Ayo cepat, PlayerName.",
  ui_story_1011_10110901_147_dialog_content = "B-Baik...",
  ui_story_1011_10110901_148_dialog_content = "Bip!",
  ui_story_1011_10110901_149_dialog_content = "Peringatan: Tanda kehidupan terdeteksi 50 meter di depan.",
  ui_story_1011_10110901_150_dialog_content = "Peringatan: Tanda kehidupan mendekat. 50 meter di depan.",
  ui_story_1011_10110901_151_dialog_content = "A-Apa?! Kita terjebak di tempat yang sempit. Bagaimana ini?!",
  ui_story_1011_10110901_152_dialog_content = "Apakah ada Eclipsite yang terperangkap di sini sejak saat itu?",
  ui_story_1011_10110901_153_dialog_content = "Peringatan: Tanda kehidupan mendekat. 40 meter di depan.",
  ui_story_1011_10110901_154_dialog_content = "Peringatan: 30 meter...",
  ui_story_1011_10110901_155_dialog_content = "PlayerName, cari solusinya!",
  ui_story_1011_10110901_156_dialog_content = "Peringatan: Tanda kehidupan terdeteksi 10 meter di depan. Mengonfirmasi identitas...",
  ui_story_1011_10110901_157_dialog_content = "Aku tidak merasakan apa-apa. Itu bukan Caelestite.",
  ui_story_1011_10110901_158_dialog_content = "Semuanya, bersiaplah untuk bertarung.",
  ui_story_1011_10110901_159_dialog_content = "Identitas dikonfirmasi: Eclipsite.",
  ui_story_1011_10110901_160_dialog_content = "Gaar…",
  ui_story_1011_10110901_161_dialog_content = "Groar! Groar!!!",
  ui_story_1011_10110901_162_dialog_content = "Perhatikan medannya dan berhati-hatilah!",
  ui_story_1011_10110902_1_dialog_content = "Groar…",
  ui_story_1011_10110902_2_dialog_content = "Seharusnya kita lebih memperhatikan.",
  ui_story_1011_10110902_3_dialog_content = "Tanda-tanda pertempuran ada di sekitar kita. Seharusnya kita lebih siap.",
  ui_story_1011_10110902_4_dialog_content = "Itu adalah jalan masuk rahasia ke Exile Zone. Tak heran kalau bahaya sudah mengintai.",
  ui_story_1011_10110902_5_dialog_content = "Kita tidak bisa mundur sekarang.",
  ui_story_1011_10110902_6_dialog_content = "(Jika ini adalah <color=#FFB400>tanda-tanda pertempuran</color>...)",
  ui_story_1011_10110902_7_dialog_content = "Neural Aux, pindai trek di tanah dan beri aku laporan situasi yang lengkap.",
  ui_story_1011_10110902_8_dialog_content = "Diterima. Mengaktifkan pemindaian...",
  ui_story_1011_10110902_9_dialog_content = "Membandingkan hasil dengan database...",
  ui_story_1011_10110902_10_dialog_content = "Pemindaian selesai.",
  ui_story_1011_10110902_11_dialog_content = "Jadi?",
  ui_story_1011_10110902_12_dialog_content = "Menghasilkan laporan. Temuan awal menunjukkan pertempuran terjadi di sini antara Caelestite dan Eclipsite.",
  ui_story_1011_10110902_13_dialog_content = "200 Eclipsite tingkat rendah yang tersisa dan 40 Caelestite yang tersisa ditemukan dalam sampel tanah.",
  ui_story_1011_10110902_14_dialog_content = "Hmm…",
  ui_story_1011_10110902_15_dialog_content = "16 tanda nama Caelestite dan 2 <color=#FFB400>senjata</color> Caelestite terletak 10 meter di depan.",
  ui_story_1011_10110902_16_dialog_content = "Senjata?!",
  ui_story_1011_10110902_17_dialog_content = "Neural Aux benar. Coba lihat ini.",
  ui_story_1011_10110902_18_dialog_content = "Di sana. Dua senapan terletak di samping batu yang jatuh, sepertinya masih bagus.",
  ui_story_1011_10110902_19_dialog_content = "Membuat laporan tambahan...",
  ui_story_1011_10110902_20_dialog_content = "Koreksi hasil pemindaian: 1 senjata Caelestite tersisa. Klip energi hilang dari senapan kedua.",
  ui_story_1011_10110902_21_dialog_content = "Ini dia.",
  ui_story_1011_10110902_22_dialog_content = "Ternyata sangat ringan dan praktis.",
  ui_story_1011_10110902_23_dialog_content = "Jadi... senapan ini... berisi \"klip energi\" dan berfungsi?",
  ui_story_1011_10110902_24_dialog_content = "Diterima... Menganalisis pertanyaan... Memutar rekaman pengantar Laser Gun...",
  ui_story_1011_10110902_25_dialog_content = "Nama senjata: Laser Gun. Penemu: Master Francis.",
  ui_story_1011_10110902_26_dialog_content = "Skill Spesial: <color=#FFB400>Eclipsite Attack</color>. Kegunaan: Semua Caelestite.",
  ui_story_1011_10110902_27_dialog_content = "Tutorial: Buat Mindlink dengan Laser Gun untuk membalas semua serangan kecil Eclipsite.",
  ui_story_1011_10110902_28_dialog_content = "(Luar biasa! Mirip seperti senapan yang dilengkapi AI!)",
  ui_story_1011_10110902_29_dialog_content = "Hah?",
  ui_story_1011_10110902_30_dialog_content = "Ada beberapa tanda di gagangnya.",
  ui_story_1011_10110902_31_dialog_content = "Informasi Tambahan: Senjata ini milik Master Francis.",
  ui_story_1011_10110902_32_dialog_content = "P-Pria itu lagi?",
  ui_story_1011_10110902_33_dialog_content = "(Dari informasi yang kami kumpulkan, Master Francis ini tampaknya adalah seseorang yang luar biasa.)",
  ui_story_1011_10110902_34_dialog_content = "Peringatan: Tanda kehidupan mendekat dari belakang. 50 meter.",
  ui_story_1011_10110902_35_dialog_content = "Benarkah itu? Waktu yang tepat.",
  ui_story_1011_10110902_36_dialog_content = "Saatnya mencoba senjata itu, PlayerName. Carleen dan aku akan menjagamu.",
  ui_story_1011_10110902_37_dialog_content = "Siap!",
  ui_story_1011_10110902_38_dialog_content = "(Buk...Buk...)",
  ui_story_1011_10110902_39_dialog_content = "(Aku telah memimpin pertempuran yang tak terhitung jumlahnya, tetapi menjadi pemimpin tetaplah menegangkan.)",
  ui_story_1011_10110902_40_dialog_content = "Ahh...",
  ui_story_1011_10110902_41_dialog_content = "Graaagh!",
  ui_story_1011_10110902_42_dialog_content = "(Sekaranglah waktunya!)",
  ui_story_1011_10110902_43_dialog_content = "<color=#e8d9bb>Dor! Dor!</color>",
  ui_story_1011_10110902_44_dialog_content = "Gaar…",
  ui_story_1011_10110902_45_dialog_content = "B-Berhasil!",
  ui_story_1011_10110902_46_dialog_content = "Tidak mematikan, tetapi senjata ini benar-benar melumpuhkan Eclipsite!",
  ui_story_1011_10110902_47_dialog_content = "Sekali tembak, lumpuh. Senjata ini benar-benar efektif!",
  ui_story_1011_10110902_48_dialog_content = "PlayerName, kau cukup lihai juga menggunakan senapan pertamamu!",
  ui_story_1011_10110902_49_dialog_content = "Ya, terima kasih!",
  ui_story_1011_10110902_50_dialog_content = "Omong-omong, Laser Gun ini telah meningkatkan kekuatan tempur kita.",
  ui_story_1011_10110902_51_dialog_content = "Ayo lanjutkan.",
  ui_story_1011_10111001_1_dialog_content = "Graaagh!",
  ui_story_1011_10111001_2_dialog_content = "Groar!",
  ui_story_1011_10111001_3_dialog_content = "Grrr!",
  ui_story_1011_10111001_4_dialog_content = "<color=#e8d9bb>Dor! Dor! Dor!</color>",
  ui_story_1011_10111001_5_dialog_content = "Kau sudah cukup terbiasa bertarung sekarang, PlayerName...",
  ui_story_1011_10111001_6_dialog_content = "Meski kau memiliki senjata kuat seperti ini, jumlah mereka masih cukup menakutkan...",
  ui_story_1011_10111001_7_dialog_content = "Bagaimana bisa para Eclipsite ini sampai di sini?",
  ui_story_1011_10111001_8_dialog_content = "(Mungkinkah mereka benar-benar ada di sini selama ini...?)",
  ui_story_1011_10111001_9_dialog_content = "Selain itu, ada yang aneh dengan mereka. Mereka semua menuju ke arah yang sama.",
  ui_story_1011_10111001_10_dialog_content = "Jika Eclipsite tidak punya pikiran, mereka pasti menanggapi panggilan, 'kan?",
  ui_story_1011_10111001_11_dialog_content = "(Panggilan?)",
  ui_story_1011_10111001_12_dialog_content = "(Mungkinkah itu Eclipse atau ...?)",
  ui_story_1011_10111001_13_dialog_content = "<color=#e8d9bb>Gemuruh…</color>",
  ui_story_1011_10111001_14_dialog_content = "Sialan...",
  ui_story_1011_10111001_15_dialog_content = "Ada yang mendekat, cepat!",
  ui_story_1011_10111001_16_dialog_content = "Jadi, benar-benar ada pemimpin di antara mereka!",
  ui_story_1011_10111001_17_dialog_content = "Peringatan! Tanda kehidupan di depan. 30, 20, 10 meter!",
  ui_story_1011_10111001_18_dialog_content = "<color=#e8d9bb>Gemuruh…</color>",
  ui_story_1011_10111001_19_dialog_content = "Groooaaar!",
  ui_story_1011_10111001_20_dialog_content = "Groar…",
  ui_story_1011_10111001_21_dialog_content = "Bukankah itu. Eclipsite yang tadi?!",
  ui_story_1011_10111001_22_dialog_content = "Bukankah kita telah menghabisinya? Bagaimana bisa ia sekuat itu...",
  ui_story_1011_10111001_23_dialog_content = "Carleen, Vice, mundur!",
  ui_story_1011_10111001_24_dialog_content = "<color=#e8d9bb>Dor!!!</color>",
  ui_story_1011_10111001_25_dialog_content = "*terengah-engah*",
  ui_story_1011_10111001_26_dialog_content = "Syukurlah! Aku punya senapan ini.",
  ui_story_1011_10111001_27_dialog_content = "Gaar…",
  ui_story_1011_10111001_28_dialog_content = "Groar!",
  ui_story_1011_10111001_29_dialog_content = "Apa?!",
  ui_story_1011_10111001_30_dialog_content = "Itu tidak mempan terhadapnya?!",
  ui_story_1011_10111001_31_dialog_content = "Groar!",
  ui_story_1011_10111001_32_dialog_content = "PlayerName, jangan bengong! Cepat keluar dari sana!",
  ui_story_1011_10111001_33_dialog_content = "M-Maju? Namun... Namun, kita tidak tahu ada apa di depan—",
  ui_story_1011_10111001_34_dialog_content = "Jangan pikirkan itu!",
  ui_story_1011_10111001_35_dialog_content = "Neural Aux, aktifkan sistem peringatan!",
  ui_story_1011_10111001_36_dialog_content = "Diterima. Sistem peringatan diaktifkan secara manual. Peringatan: tanda kehidupan di depan. 5 meter di belakang.",
  ui_story_1011_10111001_37_dialog_content = "Peringatan: Tanda kehidupan terdeteksi. 10 meter di belakang.",
  ui_story_1011_10111001_38_dialog_content = "Peringatan: Tanda kehidupan terdeteksi. 15 meter di belakang. Mendekat...",
  ui_story_1011_10111001_39_dialog_content = "Peringatan: Tanda kehidupan terdeteksi. 10 meter di belakang. Mendekat...",
  ui_story_1011_10111001_40_dialog_content = "Hosh... Hosh... Mustahil melepaskan diri dari mereka!",
  ui_story_1011_10111001_41_dialog_content = "Cepat, PlayerName!",
  ui_story_1011_10111001_42_dialog_content = "Iya, iya!",
  ui_story_1011_10111001_43_dialog_content = "Peringatan: Tanda kehidupan terdeteksi. 30 meter di belakang. Mendekat...",
  ui_story_1011_10111001_44_dialog_content = "Jangan berhenti!",
  ui_story_1011_10111001_45_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1011_10111001_46_dialog_content = "Aduh! Sakit...",
  ui_story_1011_10111001_47_dialog_content = "Hmm? Apa itu?",
  ui_story_1011_10111001_48_dialog_content = "Hah?",
  ui_story_1011_10111001_49_dialog_content = "Vice? Ada apa?",
  ui_story_1011_10111001_50_dialog_content = "Sialan! Ada perangkat di tengah terowongan sempit seperti ini?!",
  ui_story_1011_10111001_51_dialog_content = "Sepertinya stasiun kendali dan tampak mirip dengan Neural Aux...",
  ui_story_1011_10111001_52_dialog_content = "Namun, bisa-bisanya diletakkan di tengah jalan begini!",
  ui_story_1011_10111001_53_dialog_content = "Sebenarnya... mungkin kita bisa memanfaatkannya.",
  ui_story_1011_10111001_54_dialog_content = "Peringatan: Tanda kehidupan terdeteksi. 25 meter di belakang.",
  ui_story_1011_10111001_55_dialog_content = "Neural Aux, bagaimana cara kerja perangkat ini?",
  ui_story_1011_10111001_56_dialog_content = "Neural Aux dalam mode peringatan manual. Saat ini mode tidak dapat diganti.",
  ui_story_1011_10111001_57_dialog_content = "Peringatan: Tanda kehidupan terdeteksi. 10 meter di belakang.",
  ui_story_1011_10111001_58_dialog_content = "Aduh, ayolah. Namun, ini tampak persis seperti konsol senjata Illumina.",
  ui_story_1011_10111001_59_dialog_content = "Sebaiknya dicoba saja!",
  ui_story_1011_10111001_60_dialog_content = "Kuserahkan verifikasi identitas padamu, PlayerName!",
  ui_story_1011_10111001_61_dialog_content = "Tolong urus itu!",
  ui_story_1011_10111001_62_option_content = "Forced Control!",
  ui_story_1011_10111001_63_dialog_content = "Baiklah... pertama, tutup gerbang pengunciannya dan aktifkan konsol...",
  ui_story_1011_10111001_64_dialog_content = "Kemudian...",
  ui_story_1011_10111001_65_dialog_content = "Konsol ini seharusnya menampilkan Eclipsite!",
  ui_story_1011_10111001_66_dialog_content = "<color=#e8d9bb>Fyuh! Plak!</color>",
  ui_story_1011_10111001_67_dialog_content = "(Ini... serangan terarah terhadap Eclipsite?)",
  ui_story_1011_10111001_68_dialog_content = "Groar!",
  ui_story_1011_10111001_69_dialog_content = "Gaar…",
  ui_story_1011_10111001_70_dialog_content = "(Kuat sekali!)",
  ui_story_1011_10111001_71_dialog_content = "Luar biasa...! PlayerName, persis seperti senapanmu!",
  ui_story_1011_10111001_72_dialog_content = "Tidak. Jauh lebih bagus dari senapan itu!",
  ui_story_1011_10111001_73_dialog_content = "Groar!",
  ui_story_1011_10111001_74_dialog_content = "Aahhhhhh!",
  ui_story_1011_10111001_75_dialog_content = "Groar!",
  ui_story_1011_10111001_76_dialog_content = "(Kematiannya membuat begitu banyak Eclipsite berang?!)",
  ui_story_1011_10111001_77_dialog_content = "Vice, awas!",
  ui_story_1011_10111001_78_dialog_content = "Ice Blossom! Menyebar!",
  ui_story_1011_10111001_79_dialog_content = "Ugh!",
  ui_story_1011_10111001_80_dialog_content = "Vice, jangan sok pahlawan! Kembali!",
  ui_story_1011_10111001_81_dialog_content = "(Sejauh ini kita berhasil, dan kita memiliki senjata kuat seperti ini...)",
  ui_story_1011_10111001_82_dialog_content = "(Tetap tenang. Pasti ada jalan.)",
  ui_story_1011_10111001_83_dialog_content = "(Ini dia! <color=#FFB400>Perintah Bunuh Semua Dalam Jangkauan</color>!)",
  ui_story_1011_10111001_84_dialog_content = "<color=#e8d9bb>Bip, bip, bip, bip... Dor!</color>",
  ui_story_1011_10111001_85_dialog_content = "<color=#e8d9bb>Brak! Duarr!</color>",
  ui_story_1011_10111001_86_dialog_content = "Fyuh... Fyuh... Vice?",
  ui_story_1011_10111001_87_dialog_content = "Vice!",
  ui_story_1011_10111001_88_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1011_10111001_89_dialog_content = "V-Vice!",
  ui_story_1011_10111001_90_dialog_content = "(Tidak mungkin... Kami masih terhubung. Vice tidak mungkin mati!)",
  ui_story_1011_10111001_91_dialog_content = "Vice!",
  ui_story_1011_10111001_92_dialog_content = "*uhuk, uhuk* Aku di sini... PlayerName, Carleen!",
  ui_story_1011_10111001_93_dialog_content = "Syukurlah!",
  ui_story_1011_10111001_94_dialog_content = "Vice! Kau membuatku takut. Kupikir kau telah...",
  ui_story_1011_10111001_95_dialog_content = "<color=#e8d9bb>Bip, Bip, Bip, Bip...</color>",
  ui_story_1011_10111001_96_dialog_content = "Hah?",
  ui_story_1011_10111001_97_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1011_10111001_98_dialog_content = "Ap⁠—",
  ui_story_1011_10111001_99_dialog_content = "<color=#e8d9bb>Bip, Bip, Bip, Bip...</color>",
  ui_story_1011_10111001_100_dialog_content = "Tak ada target yang tersisa. Perintah Bunuh Semua Dalam Jangkauan selesai.",
  ui_story_1011_10111001_101_dialog_content = "M-Mengapa...",
  ui_story_1011_10111001_102_dialog_content = "Bagaimana…",
  ui_story_1011_10111001_103_dialog_content = "<size=50>Vice!</size>",
  ui_story_1011_10111001_104_dialog_content = "Vice... Vice!",
  ui_story_1011_10111001_105_dialog_content = "(Tidak!)",
  ui_story_1011_10111001_106_dialog_content = "Carleen! Jangan mendekat!",
  ui_story_1011_10111001_107_dialog_content = "Ada yang tidak beres dengan mesin itu! Jangan sampai mesin itu mendeteksimu!",
  ui_story_1011_10111001_108_option_content = "Putuskan sambungannya!",
  ui_story_1011_10111001_109_option_content = "Putuskan sambungannya...?",
  ui_story_1011_10111001_110_dialog_content = "(Sialan! Perangkat tidak merespons!)",
  ui_story_1011_10111001_111_dialog_content = "Carleen, sembunyikan dirimu!",
  ui_story_1011_10111001_112_dialog_content = "Siap!",
  ui_story_1011_10111001_113_dialog_content = "<color=#e8d9bb>Bip, Bip, Bip, Bip...</color>",
  ui_story_1011_10111001_114_dialog_content = "Hmm?",
  ui_story_1011_10111001_115_dialog_content = "(Ia masih mendeteksiku?!)",
  ui_story_1011_10111001_116_dialog_content = "(Penasaran apakah Moon Cocoon milikku bisa menahan serangannya...)",
  ui_story_1011_10111001_117_dialog_content = "Groar!",
  ui_story_1011_10111001_118_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1011_10111001_119_dialog_content = "(Muncul Eclipsite lebih banyak lagi?!)",
  ui_story_1011_10111001_120_option_content = "Putuskan sambungannya!",
  ui_story_1011_10111001_121_dialog_content = "<color=#e8d9bb>Kriek...</color>",
  ui_story_1011_10111001_122_dialog_content = "(Akhirnya, operasinya terputus!)",
  ui_story_1011_10111001_123_dialog_content = "PlayerName, urus Eclipsite itu terlebih dahulu dan jauhkan mereka dari Vice!",
  ui_story_1011_10111001_124_dialog_content = "Kita tidak tahu keadaan Vice. Kita tidak boleh membuang-buang waktu!",
  ui_story_1011_10111002_1_dialog_content = "Memindai tanda kehidupan...",
  ui_story_1011_10111002_2_dialog_content = "Hasil pemindaian dihasilkan...",
  ui_story_1011_10111002_3_dialog_content = "Status fisik bentuk kehidupan: Detak jantung tidak terdeteksi. Tidak ada tanda kehidupan aktif.",
  ui_story_1011_10111002_4_dialog_content = "Laporan bentuk kehidupan: Status <color=#FFB400>Hibernasi</color> dikonfirmasi.",
  ui_story_1011_10111002_5_dialog_content = "Hibernasi?",
  ui_story_1011_10111002_6_dialog_content = "Buka matamu dan hadapi kenyataan, PlayerName.",
  ui_story_1011_10111002_7_dialog_content = "Kita harus mengeluarkan Vice dari kondisinya saat ini sekarang juga!",
  ui_story_1011_10111002_8_dialog_content = "B-Baik...",
  ui_story_1011_10111002_9_dialog_content = "A... Aku masih dibutuhkan untuk berkomunikasi dengan Neural Aux.",
  ui_story_1011_10111002_17_option_content = "Hibernasi?",
  ui_story_1011_10111002_18_dialog_content = "Bentuk kehidupan yang terkena serangan Special Attacker akan mengalami hibernasi.",
  ui_story_1011_10111002_19_dialog_content = "Aurorian yang mengalami hibernasi akan tetap dalam keadaan koma.",
  ui_story_1011_10111002_20_dialog_content = "Koma?",
  ui_story_1011_10111002_21_dialog_content = "Artinya, yang harus kita lakukan adalah membangunkan Vice!",
  ui_story_1011_10111002_22_dialog_content = "Tolong jelaskan lebih jauh tentang hibernasi ini dan cara mengatasinya.",
  ui_story_1011_10111002_23_dialog_content = "Diterima... Menganalisis pertanyaan...",
  ui_story_1011_10111002_24_dialog_content = "Jawaban ditemukan: Hibernasi berbeda dari kondisi koma.",
  ui_story_1011_10111002_25_dialog_content = "Detak jantung dan pernapasan Aurorian yang mengalami hibernasi akan ditangguhkan tanpa batas waktu.",
  ui_story_1011_10111002_26_dialog_content = "Begitu pula dengan energi fotonik di dalam tubuh mereka.",
  ui_story_1011_10111002_27_dialog_content = "Mencari cara untuk menghentikan hibernasi...",
  ui_story_1011_10111002_28_dialog_content = "Maaf. Pencarian gagal. Aku tidak tahu",
  ui_story_1011_10111002_29_dialog_content = "Pencarian gagal, maksudnya bagaimana?!",
  ui_story_1011_10111002_30_dialog_content = "Aku tak bisa memberimu solusi.",
  ui_story_1011_10111002_31_dialog_content = "A-apa?",
  ui_story_1011_10111002_32_dialog_content = "Lantas, bukankah itu berarti...",
  ui_story_1011_10111002_33_dialog_content = "(Dia tampak <color=#FFB400>mati</color>?)",
  ui_story_1011_10111002_34_dialog_content = "Bagaimana Caelestite bisa menciptakan hal semengerikan ini?",
  ui_story_1011_10111002_36_dialog_content = "Mustahil... Mustahil ini terjadi...",
  ui_story_1011_10111002_37_dialog_content = "Pasti ada cara untuk membangunkan Vice...",
  ui_story_1011_10111002_38_dialog_content = "Asalkan kita masih di sini dan mencari, kita akan menemukannya.",
  ui_story_1011_10111002_39_dialog_content = "Namun…",
  ui_story_1011_10111002_40_dialog_content = "Andai aku menghabisi semua Eclipsite tepat waktu...",
  ui_story_1011_10111002_41_dialog_content = "Andai kau memutuskan sambungan dari Vice dan menghentikannya...",
  ui_story_1011_10111002_41X1_dialog_content = "Dia tak akan jadi seperti ini!",
  ui_story_1011_10111002_41X2_dialog_content = "Tadi ada kesempatan buat kita.",
  ui_story_1011_10111002_42_dialog_content = "Carleen…",
  ui_story_1011_10111002_43_dialog_content = "...",
  ui_story_1011_10111002_44_dialog_content = "Maafkan aku. Aku terbawa emosi.",
  ui_story_1011_10111002_45_dialog_content = "(Aku penasaran... Mengapa perangkat itu melukai Vice?)",
  ui_story_1011_10111002_46_dialog_content = "(Mungkinkah Vice melakukan kesalahan? Tidak... Jika dia melakukannya, aku pasti merasakannya.)",
  ui_story_1011_10111002_47_dialog_content = "<color=#e8d9bb>Bip, Bip, Bip, Bip...</color>",
  ui_story_1011_10111002_48_dialog_content = "Tak ada target yang tersisa. Perintah Bunuh Semua Dalam Jangkauan selesai.",
  ui_story_1011_10111002_49_dialog_content = "Vice memulai \"Perintah Bunuh Semua Dalam Jangkauan.\"",
  ui_story_1011_10111002_50_dialog_content = "Neural Aux, bagaimana perangkat itu dapat menyasar Vice tanpa sengaja?",
  ui_story_1011_10111002_51_dialog_content = "Diterima... Menganalisis pertanyaan...",
  ui_story_1011_10111002_52_dialog_content = "Jawaban: Special Attacker melaksanakan perintah tanpa kesalahan. Setiap bentuk kehidupan memang disasar dengan sengaja.",
  ui_story_1011_10111002_53_dialog_content = "Apa?!",
  ui_story_1011_10111002_54_dialog_content = "Vice berbaring tak berdaya di sini... Jangan bercanda.",
  ui_story_1011_10111002_55_dialog_content = "Jawaban dikonfirmasi ulang. Ulangi: Special Attacker melaksanakan perintah tanpa kesalahan. Setiap bentuk kehidupan memang—",
  ui_story_1011_10111002_56_dialog_content = "Caelestite, tolong turunkan Lance Rifle milikmu. Efek melumpuhkannya tidak berfungsi pada Neural Aux.",
  ui_story_1011_10111002_57_dialog_content = "Ulangi: Special Attacker melaksanakan perintah tanpa kesalahan. Setiap bentuk kehidupan memang disasar dengan sengaja.",
  ui_story_1011_10111002_58_dialog_content = "...",
  ui_story_1011_10111002_59_dialog_content = "...",
  ui_story_1011_10111002_60_dialog_content = "Tenanglah, PlayerName. Tanyakan terus hingga kita mendapatkan jawabannya.",
  ui_story_1011_10111002_61_dialog_content = "Jangan biarkan logika mesin Neural Aux membuatmu bodoh.",
  ui_story_1011_10111002_62_dialog_content = "Vice menunggu kita untuk membangunkannya.",
  ui_story_1011_10111002_63_dialog_content = "Kau benar. Ada satu hal penting yang lupa kita tanyakan.",
  ui_story_1011_10111002_64_dialog_content = "Neural Aux, tolong jelaskan <color=#FFB400>fungsi utama</color> Special Attacker ini.",
  ui_story_1011_10111002_65_dialog_content = "Diterima... Menganalisis pertanyaan...",
  ui_story_1011_10111002_66_dialog_content = "Memutar rekaman pengantar Special Attacker...",
  ui_story_1011_10111002_67_dialog_content = "Pada mulanya, Caelestite menggunakan Special Attacker sebagai perangkat pertahanan diri.",
  ui_story_1011_10111002_68_dialog_content = "Perangkat tersebut menawarkan level serangan pada berbagai tipe musuh yang berbeda.",
  ui_story_1011_10111002_69_dialog_content = "Karena efektifitasnya, kemudian perangkat tersebut digunakan secara aktif dalam pertempuran. Rekaman selesai.",
  ui_story_1011_10111002_70_dialog_content = "Tak ada informasi yang berguna bagi kita.",
  ui_story_1011_10111002_71_dialog_content = "Tak masuk akal sama sekali. Jadi, mengapa ia menyerang Vice?",
  ui_story_1011_10111002_72_dialog_content = "PlayerName…",
  ui_story_1011_10111002_73_dialog_content = "Kurasa aku mulai mengerti, PlayerName.",
  ui_story_1011_10111002_74_dialog_content = "Jika Neural Aux telah memberi tahu semua info tentang perangkat ini.",
  ui_story_1011_10111002_74X1_dialog_content = "Sebagai alat pertahanan diri Caelestite, ia membidik Vice, seorang Aurorian, sesuai mode Perintah Bunuh Semua Dalam Jangkauan.",
  ui_story_1011_10111002_75_dialog_content = "Serangan hibernasi pada Aurorian mungkin...",
  ui_story_1011_10111002_76_dialog_content = "Suatu hal yang <color=#FFB400>lazim</color> pada masa lalu.",
  ui_story_1011_10111002_77_dialog_content = "Saat pertama kali aku belajar cara menggunakan Moon Cocoon...",
  ui_story_1011_10111002_78_dialog_content = "Instrukturku tidak bilang secara pasti mengapa aku harus mengarahkan benda ini pada Eclipsite.",
  ui_story_1011_10111002_79_dialog_content = "Karena itu tidak memerlukan penjelasan.",
  ui_story_1011_10111002_80_dialog_content = "?!",
  ui_story_1011_10111002_81_dialog_content = "Aku masih tidak memahami atau pun dapat menerimanya...",
  ui_story_1011_10111002_82_dialog_content = "Namun, tak bisa kusangkal bahwa hal yang kaukatakan itu memang logis dan bisa terjadi...",
  ui_story_1011_10111002_83_dialog_content = "Apakah pada masa lalu Aurorian juga dianggap sebagai <color=#FFB400>musuh</color> Caelestite?",
  ui_story_1011_10111101_1_dialog_content = "Ini sekarang makin membingungkan.",
  ui_story_1011_10111101_2_dialog_content = "Kita sedang di Eraveil, di bawah monumen terbesarnya, White Tower.",
  ui_story_1011_10111101_3_dialog_content = "Namun, aku berada dalam situasi yang tidak dapat kupahami.",
  ui_story_1011_10111101_4_dialog_content = "Aku tak tahu ini tempat apa. Aku juga tak mengerti orang-orang yang dulu tinggal di sini.",
  ui_story_1011_10111101_5_dialog_content = "Aku tak tahu bagaimana mereka binasa, dan mengapa mereka meninggalkan semua ini.",
  ui_story_1011_10111101_6_dialog_content = "Mungkin, kita telah mendapatkan jawabannya.",
  ui_story_1011_10111101_7_dialog_content = "Eclipsite adalah satu-satunya yang bertahan di tempat ini.",
  ui_story_1011_10111101_8_dialog_content = "...",
  ui_story_1011_10111101_9_dialog_content = "Persis seperti yang terjadi di Eraveil tujuh belas tahun yang lalu?",
  ui_story_1011_10111101_10_dialog_content = "Mungkin lebih buruk. Teriakan minta tolong mereka yang terakhir bahkan tak pernah terdengar.",
  ui_story_1011_10111101_11_dialog_content = "Binasa tanpa ada yang mengetahuinya.",
  ui_story_1011_10111101_12_dialog_content = "Mungkin kita satu-satunya dalam ratusan atau ribuan tahun yang pernah menginjakkan kaki di sini.",
  ui_story_1011_10111101_13_dialog_content = "Mencari, kurun waktu: seribu tahun.",
  ui_story_1011_10111101_14_dialog_content = "Tidak ada catatan tentang kedatangan pihak dari luar. Analisismu akurat.",
  ui_story_1011_10111101_15_dialog_content = "Aku tak bicara denganmu.",
  ui_story_1011_10111101_16_dialog_content = "Arahan utama Neural Aux adalah membantu Caelestite dengan segala cara yang mungkin.",
  ui_story_1011_10111101_17_dialog_content = "Andai saja kau benar-benar berguna dalam menyelesaikan masalahku yang sebenarnya...",
  ui_story_1011_10111101_18_dialog_content = "Kau tidak tahu cara membangunkan Vice atau mereparasi Soroz.",
  ui_story_1011_10111101_19_dialog_content = "Memformulasikan pertanyaan dengan parameter baru...",
  ui_story_1011_10111101_20_dialog_content = "Metode \"membangunkan Vice\" atau \"mereparasi Soroz\" tidak ada di database.",
  ui_story_1011_10111101_21_dialog_content = "Analisismu akurat. Aku tidak tahu.",
  ui_story_1011_10111101_22_dialog_content = "Baiklah, terima kasih telah mengonfirmasinya lagi.",
  ui_story_1011_10111101_23_dialog_content = "Aku sangat menyesal. Skor kepuasan rendah diterima. Penyesuaian akan dilakukan pada masa mendatang.",
  ui_story_1011_10111101_24_dialog_content = "Aku tak bermaksud menyalahkanmu...",
  ui_story_1011_10111101_25_dialog_content = "Jika menilai hal yang telah terjadi, masuk akal jika kau bingung bukan kepalang.",
  ui_story_1011_10111101_26_dialog_content = "Kami akan mencari jawabannya sendiri.",
  ui_story_1011_10111101_27_dialog_content = "Mari, Carleen, kita selidiki.",
  ui_story_1011_10111101_28_dialog_content = "Kita tak punya pilihan lain.",
  ui_story_1011_10111101_29_dialog_content = "Ya. Aku akan membawa Vice.",
  ui_story_1011_10111101_30_dialog_content = "(Kami akan mencari cara untuk membangunkanmu...)",
  ui_story_1011_10111101_31_dialog_content = "(Bertahanlah... Kumohon!)",
  ui_story_1011_10111101_32_dialog_content = "<color=#e8d9bb>*Gema jejak kaki*</color>",
  ui_story_1011_10111101_33_dialog_content = "Tidak ada apa-apa di sepanjang jalan, sungguh aku heran...",
  ui_story_1011_10111101_34_dialog_content = "Tidak ada Eclipsite atau apa pun yang berserakan.",
  ui_story_1011_10111101_35_dialog_content = "Ini mungkin tempat \"paling tertata\" yang pernah kita datangi sejak sampai di sini.",
  ui_story_1011_10111101_36_dialog_content = "Ya, tetapi kerapian yang luar biasa ini terlihat aneh bagiku.",
  ui_story_1011_10111101_37_dialog_content = "Rasanya tempat ini sama sekali terisolasi dari hal yang telah kita saksikan sebelumnya...",
  ui_story_1011_10111101_38_dialog_content = "Tanpa tanda-tanda keberadaan manusia dan noda perang.",
  ui_story_1011_10111101_39_dialog_content = "Hawanya dingin dan tanpa emosi, 'kan?",
  ui_story_1011_10111101_40_dialog_content = "Ya.",
  ui_story_1011_10111101_41_dialog_content = "Seorang instruktur di Dawn Academy suatu ketika berkata padaku:",
  ui_story_1011_10111101_42_dialog_content = "\"Emosi manusia berada di permukaan dunia.\"",
  ui_story_1011_10111101_43_dialog_content = "\"Makin dalam kaugali, makin sedikit yang kaurasakan.\"",
  ui_story_1011_10111101_44_dialog_content = "Kita benar-benar sedang mengalaminya, bukan begitu?",
  ui_story_1011_10111101_45_dialog_content = "Setiap langkah membawa kita makin dalam...",
  ui_story_1011_10111101_46_dialog_content = "Instrukturmu mungkin tidak pernah menyangka kau akan mengulang kata-katanya jauh di bawah tanah.",
  ui_story_1011_10111101_47_dialog_content = "Ya, sekarang aku punya pemahaman lebih dalam atas maksud instrukturku. Dia pasti senang.",
  ui_story_1011_10111101_48_dialog_content = "Caelestite terdeteksi di area terlarang. Memverifikasi identitas.",
  ui_story_1011_10111101_49_dialog_content = "Bip... Bip... Bip... Bip...",
  ui_story_1011_10111101_50_dialog_content = "Hm? Mengapa tiba-tiba kau begitu berisik, Neural Aux?",
  ui_story_1011_10111101_51_dialog_content = "Bip... Bip... Bip... Bip!",
  ui_story_1011_10111101_52_dialog_content = "Verifikasi gagal. Jangan lanjutkan. Ulangi: Jangan lanjutkan.",
  ui_story_1011_10111101_53_dialog_content = "Jangan lanjutkan? Mustahil aku akan menghadapi Eclipsite itu lagi.",
  ui_story_1011_10111101_54_dialog_content = "Lantas mengapa begitu tiba-tiba? Aku minta penjelasan.",
  ui_story_1011_10111101_55_dialog_content = "PlayerName, lihat ke depan.",
  ui_story_1011_10111101_56_dialog_content = "Bukankah itu... sebuah <color=#FFB400>pintu batu</color>?",
  ui_story_1011_10111101_57_dialog_content = "Benar, sepertinya begitu.",
  ui_story_1011_10111101_58_dialog_content = "Ukurannya begitu besar. Aku hampir mengiranya dinding.",
  ui_story_1011_10111101_59_dialog_content = "Bayangkan kekuatan yang diperlukan untuk membuka pintu seukuran ini.",
  ui_story_1011_10111101_60_dialog_content = "Pintu itu tidak akan bergerak sekalipun dihantam dengan palu terbesar.",
  ui_story_1011_10111101_61_dialog_content = "Tak terbayang pihak mana di dunia ini yang mampu membuat atau bahkan menggerakkan pintu batu sebesar itu.",
  ui_story_1011_10111101_62_dialog_content = "Aku setuju.",
  ui_story_1011_10111101_63_dialog_content = "Bahkan teknologi ajaib itu tidak mampu menyelamatkan diri mereka pada akhirnya?",
  ui_story_1011_10111101_64_dialog_content = "Jangan lanjutkan. Ulangi: Jangan lanjutkan.",
  ui_story_1011_10111101_65_dialog_content = "Identitasmu tidak memperoleh akses ke <color=#FFB400>Central Core</color>.",
  ui_story_1011_10111101_66_dialog_content = "Akses tidak diizinkan?",
  ui_story_1011_10111101_67_dialog_content = "Pintu hanya dapat dibuka oleh personel yang berwenang.",
  ui_story_1011_10111101_68_dialog_content = "Personel yang tidak berwenang akan ditolak masuk berdasarkan <color=#FFB400>perintah</color> yang diberikan.",
  ui_story_1011_10111101_69_dialog_content = "Aku harus cari tahu cara membuka pintu ini. Pasti pemandangannya luar biasa.",
  ui_story_1011_10111101_70_dialog_content = "Aku perlu sedikit bantuan, Neural Aux.",
  ui_story_1011_10111101_71_dialog_content = "Bagaimana aku bisa memperoleh aksesnya?",
  ui_story_1011_10111101_72_dialog_content = "Maaf. Aku tidak bisa membantumu.",
  ui_story_1011_10111101_73_dialog_content = "Hah? Bukankah katamu arahan utamamu adalah untuk membantuku dengan segala cara yang mungkin?",
  ui_story_1011_10111101_74_dialog_content = "Aksesmu ditolak oleh Highest Decree. Aturan pertama dan tertinggi yang ada.",
  ui_story_1011_10111101_75_dialog_content = "Caelestite atau Neural Aux harus patuh terhadap Highest Decree.",
  ui_story_1011_10111101_76_dialog_content = "Highest Decree... 'kan?",
  ui_story_1011_10111101_77_dialog_content = "Menggunakan pintu batu sebesar gunung hanya untuk menjaga agar tidak sembarang orang bisa masuk.",
  ui_story_1011_10111101_78_dialog_content = "Highest Decree itu benar-benar memainkan peranan besar.",
  ui_story_1011_10111101_79_dialog_content = "Pintu batu itu pastinya dapat memenuhi tujuannya.",
  ui_story_1011_10111101_80_dialog_content = "Tapi...",
  ui_story_1011_10111101_81_dialog_content = "Itu saat tempat ini sedang dalam masa kejayaannya.",
  ui_story_1011_10111101_82_dialog_content = "Sekarang hari-hari tersebut telah berlalu. Hanya ancaman kosong yang ada sekarang.",
  ui_story_1011_10111101_83_dialog_content = "Ya... Setelah mengalami proses pelapukan sekian tahun, celah-celah ini jadi cukup besar untuk dapat dimasuki.",
  ui_story_1011_10111101_84_dialog_content = "Sang singa telah ompong, tetapi masih belum mau menyerah.",
  ui_story_1011_10111101_85_dialog_content = "Ini agak menyedihkan, sebenarnya. Dengan gagah perkasa menolak siapa pun masuk, tetapi sudah lapuk.",
  ui_story_1011_10111101_86_dialog_content = "Jangan lanjutkan. Ulangi: Jangan lanjutkan.",
  ui_story_1011_10111101_87_dialog_content = "Ayo, kita masuk.",
  ui_story_1011_10111101_88_dialog_content = "Kita juga bisa melihat hal yang ada di balik pintu besar ini.",
  ui_story_1011_10111101_89_dialog_content = "Ya. Tak ada pilihan lain selain mengumpulkan info sebanyak yang kita bisa.",
  ui_story_1011_10111101_90_dialog_content = "Kau belum memperoleh izin akses. Kau tidak bisa masuk ke Central Core.",
  ui_story_1011_10111101_91_dialog_content = "Neural Aux, kau istirahat saja dulu.",
  ui_story_1011_10111101_92_dialog_content = "Highest Decree tidak mengizinkanmu masuk.",
  ui_story_1011_10111101_93_dialog_content = "Caelestite harus patuh terhadap Highest Decree...",
  ui_story_1011_10111101_94_dialog_content = "(Sekarang di dalam celah gelap, kurasakan ternyata pintu ini jauh lebih tebal dari yang kukira.)",
  ui_story_1011_10111101_95_dialog_content = "(Suara Neural Aux tak terdengar lagi. Aku ingin tahu apakah ia akhirnya menyerah atau terhalang pintu.)",
  ui_story_1011_10111101_96_dialog_content = "(Pikiranku dipenuhi imajinasi liar soal apa yang ada di balik ini dan menungguku...)",
  ui_story_1011_10111101_97_dialog_content = "(Namun, aku tahu bahkan imajinasiku yang paling liar pun tak dapat membuatku siap untuk menghadapi hal menakjubkan yang akan muncul.)",
  ui_story_1011_10111101_98_dialog_content = "(Aku mengerti makna dari hal yang akan kulihat.)",
  ui_story_1011_10111101_99_dialog_content = "(Ini adalah sisa suatu peradaban, seutuhnya.)",
  ui_story_1011_10111101_100_dialog_content = "Apa ini?",
  ui_story_1011_10111101_101_dialog_content = "Ini masih berfungsi...",
  ui_story_1011_10111101_102_dialog_content = "Neural Aux, kau baik-baik saja?",
  ui_story_1011_10111101_103_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1011_10111101_104_dialog_content = "Kurasa ia tidak akan merespons sejak gagal menghentikan kita masuk.",
  ui_story_1011_10111101_105_dialog_content = "Jadi, kita harus menyelesaikan ini sendiri.",
  ui_story_1011_10111101_106_dialog_content = "Tablet-tablet bundar yang mengambang itu.",
  ui_story_1011_10111101_107_dialog_content = "Apa fungsinya? Aku bahkan tak dapat membayangkannya.",
  ui_story_1011_10111101_108_dialog_content = "Pernahkah kau melihat hal seperti ini?",
  ui_story_1011_10111101_109_dialog_content = "Belum pernah sama sekali.",
  ui_story_1011_10111101_110_dialog_content = "Kita bahkan belum pernah menemukan hal serupa di reruntuhan kuno.",
  ui_story_1011_10111101_111_dialog_content = "Namun, itu tidak mengejutkan. Tempat ini berbeda dari tempat apa pun lainnya. Tempat ini milik Caelestite.",
  ui_story_1011_10111101_112_dialog_content = "Jadi, mungkin hanya Caelestite yang dapat mengoperasikannya.",
  ui_story_1011_10111101_113_dialog_content = "Apa maksudmu?",
  ui_story_1011_10111101_114_dialog_content = "Caramu memandang dunia berbeda dari cara Aurorian memandang dunia.",
  ui_story_1011_10111101_115_dialog_content = "Jika hal ini didesain untuk digunakan oleh Caelestite, mungkin hanya Caelestite yang mampu mengoperasikannya.",
  ui_story_1011_10111101_116_dialog_content = "Maksudmu... kemampuan cenayangku, bukan?",
  ui_story_1011_10111101_117_dialog_content = "Ini hanya dugaanku. Mengapa kita tidak mencobanya saja?",
  ui_story_1011_10111101_118_dialog_content = "Baiklah.",
  ui_story_1011_10111101_119_option_content = "Forced Control!",
  ui_story_1011_10111101_120_dialog_content = "<color=#e8d9bb>Ngungg!</color>",
  ui_story_1011_10111101_121_dialog_content = "Eh? Bukankah...",
  ui_story_1011_10111101_122_dialog_content = "Selamat datang, Newborn.",
  ui_story_1011_10111101_123_dialog_content = "Apakah ini kali pertama kau menggunakan <color=#FFB400>Circular System</color>?",
  ui_story_1011_10111101_124_dialog_content = "Circular System? Alat itu?",
  ui_story_1011_10111101_125_dialog_content = "Di mana aku? Siapa yang bicara?",
  ui_story_1011_10111101_126_dialog_content = "Circular System berisi memori seluruh Caelestite.",
  ui_story_1011_10111101_127_dialog_content = "Kau akan belajar dunia tersebut di sini.",
  ui_story_1011_10111101_128_dialog_content = "Tunggu... Ternyata tak ada orang yang sedang benar-benar \"bicara\" padaku.",
  ui_story_1011_10111101_129_dialog_content = "Informasi ini melampaui jangkauan bahasa itu sendiri dan disampaikan langsung padaku.",
  ui_story_1011_10111101_130_dialog_content = "Mari kita mulai dengan tempatmu berada saat ini.",
  ui_story_1011_10111101_131_dialog_content = "Ini adalah tempat peradaban Caelestite lahir, tempat semua Caelestite dilahirkan.",
  ui_story_1011_10111101_132_dialog_content = "Tidak peduli ke mana pun kau pergi, Caelestite akan selalu di sini.",
  ui_story_1011_10111101_133_dialog_content = "Ini adalah <color=#FFB400>Kota Obelisk</color>.",
  ui_story_1011_10111101_134_dialog_content = "Kota Obelisk...",
  ui_story_1011_10111101_135_dialog_content = "Bukankah Eraveil adalah tempat tinggal kaum Caelestite?",
  ui_story_1011_10111101_136_dialog_content = "Kota ini berisi menara yang tak terhitung jumlahnya.",
  ui_story_1011_10111101_137_dialog_content = "Kau sedang berdiri di pusat kota, yang pertama dan tertinggi dari semua menara.",
  ui_story_1011_10111101_138_dialog_content = "Obelisk of Return.",
  ui_story_1011_10111101_139_dialog_content = "Setiap Caelestite akan mendapat pendidikan di sini hingga mereka dewasa.",
  ui_story_1011_10111101_140_dialog_content = "Kau akan mendapat kesempatan untuk menjelajahi dunia dan melakukan perjalanan ke ujung dunia saat telah dewasa.",
  ui_story_1011_10111101_141_dialog_content = "Namun, rumahmu... Kota Obelisk... akan selalu menunggu...",
  ui_story_1011_10111101_142_dialog_content = "Untukmu... pada akhir... perjalananmu...",
  ui_story_1011_10111101_143_dialog_content = "!!!",
  ui_story_1011_10111101_144_dialog_content = "I-Itu saja?!",
  ui_story_1011_10111101_145_dialog_content = "Jadi? Apa yang tadi kaulihat?",
  ui_story_1011_10111101_146_dialog_content = "Aku mendengar suara... Tidak. Bukan suara. Aku menerima informasi.",
  ui_story_1011_10111101_147_dialog_content = "Informasi?",
  ui_story_1011_10111101_148_dialog_content = "Saat aku terhubung dengan alat itu, informasi itu disampaikan secara langsung padaku.",
  ui_story_1011_10111101_149_dialog_content = "Rasanya seperti... mendengarkan kuliah.",
  ui_story_1011_10111101_150_dialog_content = "Ia mengatakan padaku bahwa alat itu bernama Circular System, berisi memori seluruh Caelestite.",
  ui_story_1011_10111101_151_dialog_content = "Ia juga menyebutkan bahwa ini merupakan tanah kelahiran Caelestite, namanya Kota Obelisk.",
  ui_story_1011_10111101_152_dialog_content = "Obelisk of Return, tempat kita berada sekarang, adalah menara tertinggi dari semuanya.",
  ui_story_1011_10111101_153_dialog_content = "Ia tidak menyebutkan Eraveil?",
  ui_story_1011_10111101_154_dialog_content = "Tidak. Aku juga bingung soal itu.",
  ui_story_1011_10111101_155_dialog_content = "Apakah namanya berubah seiring waktu...?",
  ui_story_1011_10111101_156_dialog_content = "Mungkin saja. Tempat ini sangat kuno. Bahasa tertulis atau lisannya mungkin telah berubah.",
  ui_story_1011_10111101_157_dialog_content = "Jadi... Circular System ini semacam alat penyimpan informasi?",
  ui_story_1011_10111101_158_dialog_content = "Boleh dibilang begitu.",
  ui_story_1011_10111101_159_dialog_content = "Caelestite memperoleh informasi dengan menggunakan kemampuan cenayangnya terhadapnya.",
  ui_story_1011_10111101_160_dialog_content = "Mengapa didesain seperti ini?",
  ui_story_1011_10111101_161_dialog_content = "Aku masih tidak mengerti cara kerja tablet-tablet bundar itu.",
  ui_story_1011_10111101_162_dialog_content = "Selain itu, ukurannya terlalu besar sebagai alat penyimpan informasi.",
  ui_story_1011_10111101_163_dialog_content = "Jumlah informasinya akan sangat besar sekalipun tempat ini dulu diisi buku-buku.",
  ui_story_1011_10111101_164_dialog_content = "Buku...",
  ui_story_1011_10111101_165_dialog_content = "Sebentar. Carleen, masih ingat fosil cangkang nautilus yang kita ambil?",
  ui_story_1011_10111101_166_dialog_content = "Tentu.",
  ui_story_1011_10111101_167_dialog_content = "Vice mengatakan, bentuknya meniru prinsip matematika dari peradaban kuno ini.",
  ui_story_1011_10111101_168_dialog_content = "Mereka memuja alam, dan representasi matematikanya adalah \"progresi\".",
  ui_story_1011_10111101_169_dialog_content = "Konsep itu mungkin sangat berperan di sini.",
  ui_story_1011_10111101_170_dialog_content = "Maksudmu, bentuk-bentuk bundar ini juga melambangkan \"progresi\"?",
  ui_story_1011_10111101_171_dialog_content = "Ya. Aku memikirkan perkataanmu jika tempat ini mungkin saja telah diisi berbagai buku.",
  ui_story_1011_10111101_172_dialog_content = "Andai dulu kita ingin menyimpan dan menata buku, kita akan menumpuknya, tanpa memberi ruang sedikit pun.",
  ui_story_1011_10111101_173_dialog_content = "Akhirnya, akan ada tumpukan buku berbentuk persegi.",
  ui_story_1011_10111101_174_dialog_content = "Tapi persegi punya banyak sudut, jadi garis-garisnya tidak berkesinambungan.",
  ui_story_1011_10111101_175_dialog_content = "Akan tetapi, lingkaran tidak memiliki sudut.",
  ui_story_1011_10111101_176_dialog_content = "Jadi, tempat ini juga menerapkan konsep \"progresi\" untuk menyimpan informasi.",
  ui_story_1011_10111101_177_dialog_content = "Persis seperti yang kumaksudkan!",
  ui_story_1011_10111101_178_dialog_content = "Bahkan jika aku dapat... menjelaskannya seperti itu, aku masih tidak tahu cara kerja alat itu yang sebenarnya.",
  ui_story_1011_10111101_179_dialog_content = "Jika itu benar, peradaban kuno ini jauh lebih maju dari perkiraan kita sebelumnya.",
  ui_story_1011_10111101_180_dialog_content = "Prinsip dasar ilmiah mereka jauh berbeda dari prinsip kita.",
  ui_story_1011_10111101_181_dialog_content = "Di mata mereka, kita mungkin tampak seperti makhluk primitif yang bermain dengan tongkat.",
  ui_story_1011_10111101_182_dialog_content = "Itu... sukar sekali dibayangkan.",
  ui_story_1011_10111101_183_dialog_content = "Coba akses kembali, PlayerName.",
  ui_story_1011_10111101_184_dialog_content = "Seberapa besar informasi yang mungkin dapat disimpannya, mengingat teknologi mereka yang sangat maju?",
  ui_story_1011_10111101_185_dialog_content = "Mungkin jawaban bagi semua pertanyaan di dunia tersimpan di sini.",
  ui_story_1011_10111101_186_dialog_content = "Aku akan mencobanya lagi!",
  ui_story_1011_10111101_187_option_content = "Forced Control!",
  ui_story_1011_10111101_188_dialog_content = "<color=#e8d9bb>Ngungg!</color>",
  ui_story_1011_10111101_189_dialog_content = "Di sini lagi.",
  ui_story_1011_10111101_190_dialog_content = "Jika tempat ini menyimpan informasi... Aku seharusnya bisa menelusurinya.",
  ui_story_1011_10111101_191_dialog_content = "Namun, tak ada yang menyerupai rak buku.",
  ui_story_1011_10111101_192_dialog_content = "Benar... pikiranku. Biar kucoba membayangkannya dalam pikiranku.",
  ui_story_1011_10111101_193_dialog_content = "Hah?",
  ui_story_1011_10111101_194_dialog_content = "Tablet-tablet mengambang itu bergerak.",
  ui_story_1011_10111101_195_dialog_content = "PlayerName, apa yang kaulakukan?",
  ui_story_1011_10111101_196_dialog_content = "Wah! Astaga...",
  ui_story_1011_10111101_197_dialog_content = "Aku mual... apakah aku bergerak?",
  ui_story_1011_10111101_198_dialog_content = "Hentikan... Aku harus mencari cara untuk menghentikannya.",
  ui_story_1011_10111101_199_dialog_content = "<color=#e8d9bb>Ngungg!</color>",
  ui_story_1011_10111101_200_dialog_content = "Fyuh... Sudah berhenti?",
  ui_story_1011_10111101_201_dialog_content = "Colossus.",
  ui_story_1011_10111101_202_dialog_content = "Eh?!",
  ui_story_1011_10111101_203_dialog_content = "Colossus adalah fasilitas serbaguna yang ditenagai oleh Lumina.",
  ui_story_1011_10111101_204_dialog_content = "Ia merupakan benda yang paling dapat diandalkan bagi Caelestite.",
  ui_story_1011_10111101_205_dialog_content = "Caelestite kuat dalam pikiran, tetapi akibatnya fisiknya lemah.",
  ui_story_1011_10111101_206_dialog_content = "Colossus menutupi kelemahan Caelestite dan berfungsi sebagai perpanjangan tubuh, menyelaraskan gerakan dengan kecepatan pikiran Caelestite.",
  ui_story_1011_10111101_207_dialog_content = "Oleh karena itu, setiap Caelestite harus belajar mengendalikan Colossus, yang pertama dan utama.",
  ui_story_1011_10111101_208_dialog_content = "Ini pasti suatu program pendidikan...",
  ui_story_1011_10111101_209_dialog_content = "Kali ini ia mengajariku cara mengendalikan Colossus?",
  ui_story_1011_10111101_210_dialog_content = "Tidak ada kokpit di Colossus.",
  ui_story_1011_10111101_211_dialog_content = "Caelestite harus menghubungkan pikirannya dengan Colossus.",
  ui_story_1011_10111101_212_dialog_content = "Kekuatan resonansi yang cukup akan mengaktifkan Colossus.",
  ui_story_1011_10111101_213_dialog_content = "Itulah yang terjadi padaku.",
  ui_story_1011_10111101_214_dialog_content = "Suatu Colossus dapat dilengkapi berbagai modul dan plugin untuk memberikan fungsi yang berbeda bagi Caelestite.",
  ui_story_1011_10111101_215_dialog_content = "Dengan Colossus, Caelestite dapat menjadi lebih kuat daripada setiap makhluk di dunia.",
  ui_story_1011_10111101_216_dialog_content = "Namun, sebagai pemilik kekuatan luar biasa ini, setiap pilot Colossus harus selalu mengingat:",
  ui_story_1011_10111101_217_dialog_content = "Highest Decree terpatri di dalam dirimu begitu kau lahir.",
  ui_story_1011_10111101_218_dialog_content = "Caelestite dan Colossus akan selalu dan selamanya menjadi mesin perang.",
  ui_story_1011_10111101_219_dialog_content = "Mesin perang?!",
  ui_story_1011_10111101_220_dialog_content = "Bagaimana mungkin... Soroz dan aku... bahkan tidak dapat berkelahi...",
  ui_story_1011_10111101_221_dialog_content = "Mesin perang ini memiliki tubuh Colossus dan pikiran Caelestite.",
  ui_story_1011_10111101_222_dialog_content = "Mesin perang ini terikat pada Highest Decree dan siap menghadapi musuh...",
  ui_story_1011_10111101_223_dialog_content = "Semua selalu siap melayani.",
  ui_story_1011_10111101_224_dialog_content = "APA?!",
  ui_story_1011_10111101_225_dialog_content = "Semua ini... Eclipsite?!",
  ui_story_1011_10111101_226_dialog_content = "Selanjutnya, kau akan perlu meluangkan waktu yang cukup panjang untuk belajar tentang perang.",
  ui_story_1011_10111101_227_dialog_content = "Kau akan melihat medan perang di dalam data.",
  ui_story_1011_10111101_228_dialog_content = "Kau akan tahu sendiri betapa hidup tidak berarti, dan bagaimana sedikit sentuhan akan menghancurkan keseimbangan yang ada.",
  ui_story_1011_10111101_229_dialog_content = "Untungnya, medan perang ini bukan milik Caelestite.",
  ui_story_1011_10111101_230_dialog_content = "Ada prajurit yang terlahir untuk perang, dan yang mereka tahu hanyalah membunuh.",
  ui_story_1011_10111101_231_dialog_content = "Para prajurit memuakkan ini akan menyambut medan perang.",
  ui_story_1011_10111101_232_dialog_content = "Soal kau, kau hanya akan bertanggung jawab...",
  ui_story_1011_10111101_233_dialog_content = "Menciptakan perang bagi dunia.",
  ui_story_1011_10111201_1_dialog_content = "Hosh... Hosh...",
  ui_story_1011_10111201_2_dialog_content = "Kenapa, PlayerName?",
  ui_story_1011_10111201_3_dialog_content = "Keringatmu mengucur deras.",
  ui_story_1011_10111201_4_dialog_content = "Hah... Aku...",
  ui_story_1011_10111201_5_dialog_content = "Entahlah.",
  ui_story_1011_10111201_6_dialog_content = "Entah mengapa aku melihat hal barusan.",
  ui_story_1011_10111201_7_dialog_content = "Aku tidak tahu artinya... Aku tidak tahu.",
  ui_story_1011_10111201_8_dialog_content = "Apa yang tadi kaulihat?",
  ui_story_1011_10111201_9_dialog_content = "A-aku melihat Colossus.",
  ui_story_1011_10111201_10_dialog_content = "Circular System mengajariku cara mengoperasikan Colossus.",
  ui_story_1011_10111201_11_dialog_content = "Dan…",
  ui_story_1011_10111201_12_dialog_content = "Cara memberikan perintah kepada Eclipsite di dalam Colossus.",
  ui_story_1011_10111201_13_dialog_content = "Memberikan perintah kepada Eclipsite?!",
  ui_story_1011_10111201_13X1_dialog_content = "Ya... katanya dulu Caelestite dan Colossus adalah mesin perang...",
  ui_story_1011_10111201_14_dialog_content = "Bagaimana mungkin?",
  ui_story_1011_10111201_15_dialog_content = "Carleen, menurutmu itu...",
  ui_story_1011_10111201_16_dialog_content = "Aku terkejut juga, tetapi... Kita benar-benar tak memiliki cukup informasi untuk membuat penilaian apa pun.",
  ui_story_1011_10111201_17_dialog_content = "Maksudku, tempat ini kuno, saat itu dunia begitu berbeda.",
  ui_story_1011_10111201_18_dialog_content = "Kita tak tahu apa yang terjadi dulu, dan kita tidak dapat memastikan bahwa pesan tersebut asli.",
  ui_story_1011_10111201_19_dialog_content = "Benarkah?",
  ui_story_1011_10111201_20_dialog_content = "Namun, jika Caelestite benar-benar memerintah Eclipsite...",
  ui_story_1011_10111201_21_dialog_content = "Lantas aku ini apa? Bagaimana aku memandang diriku sendiri...",
  ui_story_1011_10111201_22_dialog_content = "Mungkinkah Schummer... benar?",
  ui_story_1011_10111201_23_dialog_content = "Kau boleh memikirkan pesan tersebut dan maknanya, tetapi jangan sampai kau terombang-ambing karenanya.",
  ui_story_1011_10111201_24_dialog_content = "Hal yang telah kaualami dan caramu menyikapinya adalah yang terpenting, bukan?",
  ui_story_1011_10111201_25_dialog_content = "Hal-hal yang telah kaualami dengan Soroz adalah nyata.",
  ui_story_1011_10111201_26_dialog_content = "Demikian pula setiap orang yang bertempur di sampingmu.",
  ui_story_1011_10111201_27_dialog_content = "Jangan khawatirkan bagaimana seharusnya kau memandang dirimu.",
  ui_story_1011_10111201_28_dialog_content = "Aku, Vice, dan setiap orang yang tidak hadir di sini...",
  ui_story_1011_10111201_29_dialog_content = "Selalu ada tempat bagimu bersama kami.",
  ui_story_1011_10111201_30_dialog_content = "Benar... Aku...",
  ui_story_1011_10111201_31_dialog_content = "Carleen... Terima kasih banyak...",
  ui_story_1011_10111201_32_dialog_content = "Emm... Kau jangan terlalu emosional.",
  ui_story_1011_10111201_33_dialog_content = "Kau benar. Kalian semua nyata.",
  ui_story_1011_10111201_34_dialog_content = "Selanjutnya, yang penting saat ini adalah mencari cara untuk membangunkan Vice.",
  ui_story_1011_10111201_35_dialog_content = "Aku perlu mencobanya lagi.",
  ui_story_1011_10111201_36_dialog_content = "Mengapa kau tidak beristirahat dulu?",
  ui_story_1011_10111201_37_dialog_content = "Terhubung dengan Circular System sepertinya sangat melelahkan.",
  ui_story_1011_10111201_38_dialog_content = "Aku baik-baik saja.",
  ui_story_1011_10111201_39_dialog_content = "Kurasa aku telah menemukan cara mengendalikannya.",
  ui_story_1011_10111201_40_option_content = "Forced Control!",
  ui_story_1011_10111201_41_dialog_content = "<color=#e8d9bb>Ngungg!</color>",
  ui_story_1011_10111201_42_dialog_content = "Aku dapat merasakan kesadaranku bergerak di sana.",
  ui_story_1011_10111201_43_dialog_content = "Menurutku, semua informasi yang disimpan di sini mungkin telah menciptakan suatu ruang maya.",
  ui_story_1011_10111201_44_dialog_content = "Aku juga dapat menjelajah ruang ini melalui kesadaranku.",
  ui_story_1011_10111201_45_dialog_content = "Dalam upayaku, aku masih memikirkan pengalaman sebelumnya, oleh itu aku masuk ke kuliah bagi Caelestite.",
  ui_story_1011_10111201_46_dialog_content = "Kali ini, aku akan mengendalikannya...",
  ui_story_1011_10111201_47_dialog_content = "Kemudian mengetahui cara untuk membangunkan Vice.",
  ui_story_1011_10111201_48_dialog_content = "Aku harus memfokuskan pikiranku pada hibernasi...",
  ui_story_1011_10111201_49_dialog_content = "<color=#e8d9bb>Ngungg!</color>",
  ui_story_1011_10111201_50_dialog_content = "A-apakah itu berhasil?",
  ui_story_1011_10111201_51_dialog_content = "Data uji, kode...",
  ui_story_1011_10111201_52_dialog_content = "Akses... diubah menjadi tidak terbatas. Dapat diakses semua...",
  ui_story_1011_10111201_53_dialog_content = "Pengubah: Francis.",
  ui_story_1011_10111201_54_dialog_content = "Francis... Nama ini lagi.",
  ui_story_1011_10111201_55_dialog_content = "Sepertinya pesan ini rusak parah. Semoga aku masih dapat menemukan sejumlah petunjuk.",
  ui_story_1011_10111201_56_dialog_content = "Subjek... Gagal pulih dari hibernasi. Fisik... Tanda kehidupan melemah.",
  ui_story_1011_10111201_57_dialog_content = "Subjek... Gagal pulih dari hibernasi. Memperlihatkan... Tanda kehidupan...",
  ui_story_1011_10111201_58_dialog_content = "Subjek... Gagal... Pulih... Eksperimen...",
  ui_story_1011_10111201_59_dialog_content = "Eksperimen macam apa ini?",
  ui_story_1011_10111201_60_dialog_content = "Data uji ini... Ini meresahkan.",
  ui_story_1011_10111201_61_dialog_content = "Subjek... Gagal... Pulih... Tidak ada abnormalitas lain.",
  ui_story_1011_10111201_62_dialog_content = "Subjek... Gagal pulih dari hibernasi. Memperlihatkan... Tidak ada...",
  ui_story_1011_10111201_63_dialog_content = "Subjek... Gagal...",
  ui_story_1011_10111201_64_dialog_content = "Mereka semua telah...",
  ui_story_1011_10111201_65_dialog_content = "Eksperimen...",
  ui_story_1011_10111201_66_dialog_content = "...",
  ui_story_1011_10111201_67_dialog_content = "Tetap saja, terlalu banyak data yang hilang...",
  ui_story_1011_10111201_68_dialog_content = "... Upaya terakhir... digabungkan dengan...",
  ui_story_1011_10111201_69_dialog_content = "Subjek...",
  ui_story_1011_10111201_70_dialog_content = "Diobservasi... perubahan fisik...",
  ui_story_1011_10111201_71_dialog_content = "...",
  ui_story_1011_10111201_72_dialog_content = "... berhasil pulih dari hibernasi.",
  ui_story_1011_10111201_73_dialog_content = "?!",
  ui_story_1011_10111201_74_dialog_content = "Berhasil!",
  ui_story_1011_10111201_75_dialog_content = "Eksperimen apa ini? Di mana ini?",
  ui_story_1011_10111201_76_dialog_content = "Aku butuh lebih banyak informasi. Aku harus menyelam lebih dalam.",
  ui_story_1011_10111201_77_dialog_content = "Perhatian: Informasi target... akses terbatas...",
  ui_story_1011_10111201_78_dialog_content = "Akses... terputus.",
  ui_story_1011_10111201_79_dialog_content = "Ah... Aku tak bisa memeriksanya...",
  ui_story_1011_10111201_80_dialog_content = "Jadi? Menemukan sesuatu?",
  ui_story_1011_10111201_81_dialog_content = "Ya. Aku menemukan satu set data uji.",
  ui_story_1011_10111201_82_dialog_content = "Di dalamnya ada riwayat subjek yang berhasil dipulihkan dari hibernasi.",
  ui_story_1011_10111201_83_dialog_content = "Namun, aku tidak tahu eksperimen apa itu dan tempat pengujiannya dulu.",
  ui_story_1011_10111201_84_dialog_content = "Selain itu, hanya ada satu kasus yang berhasil.",
  ui_story_1011_10111201_85_dialog_content = "Kita tak melihat ada peralatan uji yang masih utuh di sepanjang jalan.",
  ui_story_1011_10111201_86_dialog_content = "Kita hanya dapat berharap alat itu ada di suatu tempat yang lebih di dalam dan masih dapat berfungsi.",
  ui_story_1011_10111201_87_dialog_content = "Selanjutnya, kita hanya perlu memanfaatkan peluang yang ada.",
  ui_story_1011_10111201_88_dialog_content = "Kau benar. Hanya itu yang dapat kita lakukan.",
  ui_story_1011_10111201_89_dialog_content = "Ayolah. Mari masuk lebih dalam.",
  ui_story_1011_10111201_90_dialog_content = "Sekalipun kita tidak dapat menemukan peralatan ujinya, kita mungkin masih dapat menemukan sejumlah petunjuk lain.",
  ui_story_1011_10111201_91_dialog_content = "Tidak ada yang tahu berapa banyak rahasia tersembunyi di tempat ini.",
  ui_story_1011_10111201_92_dialog_content = "<color=#e8d9bb>*Gema jejak kaki*</color>",
  ui_story_1011_10111201_93_dialog_content = "\"Obelisk of Return\"...",
  ui_story_1011_10111201_94_dialog_content = "Kalau kita lihat kembali, baru sekarang kita sadar kita telah menjelajahi bagian dalam menara.",
  ui_story_1011_10111201_95_dialog_content = "Mustahil mengetahui apakah fasilitas bawah tanah dan menara di permukaan tanah berasal dari bangunan yang sama.",
  ui_story_1011_10111201_96_dialog_content = "Keduanya terasa seperti dua tempat yang berbeda.",
  ui_story_1011_10111201_97_dialog_content = "White Tower telah berdiri di Eraveil lama sekali. Kita semua akrab dengannya.",
  ui_story_1011_10111201_98_dialog_content = "Namun, tidak begitu dengan reruntuhan bawah tanah. Tempat ini sama sekali asing.",
  ui_story_1011_10111201_99_dialog_content = "Hubungan antara keduanya... adalah kalian...",
  ui_story_1011_10111201_100_dialog_content = "Bangsa Caelestite.",
  ui_story_1011_10111201_101_dialog_content = "...",
  ui_story_1011_10111201_102_dialog_content = "Sekalipun waktu berlalu dan budaya serta teknologi berubah, Caelestite akan selalu menghuni tempat ini.",
  ui_story_1011_10111201_103_dialog_content = "Tak diragukan lagi, itu adalah monumen itu sendiri.",
  ui_story_1011_10111201_104_dialog_content = "Aku tak pernah merasakan hal serupa saat aku dulu di Northland, tanah kelahiran bangsa Aurorian.",
  ui_story_1011_10111201_105_dialog_content = "\"Monumen\"... 'kan?",
  ui_story_1011_10111201_106_dialog_content = "Itu kata yang berat untuk dipikul...",
  ui_story_1011_10111201_107_dialog_content = "Hah?",
  ui_story_1011_10111201_108_dialog_content = "Aku adalah satu-satunya yang memikul beban \"monumen\" ini sekarang...",
  ui_story_1011_10111201_109_dialog_content = "PlayerName…",
  ui_story_1011_10111201_110_dialog_content = "Lupakan saja. Bukan waktunya memikirkan hal itu.",
  ui_story_1011_10111201_111_dialog_content = "Sisi baiknya, ini berarti aku adalah satu-satunya pewaris semua bangunan ini.",
  ui_story_1011_10111201_112_dialog_content = "Jadi... Semuanya milikku sekarang, 'kan?",
  ui_story_1011_10111201_113_dialog_content = "Heheh.",
  ui_story_1011_10111201_114_dialog_content = "Kau benar. Kau pemilik sahnya sekarang.",
  ui_story_1011_10111201_115_dialog_content = "Enak sekali. Aku tak perlu kelaparan lagi, dan punya begitu banyak barang antik dan relik yang dapat kugunakan.",
  ui_story_1011_10111201_116_dialog_content = "Aku akan merebut buku besar Vice!",
  ui_story_1011_10111201_117_dialog_content = "Aku akan pastikan Vice mendapat pesan itu.",
  ui_story_1011_10111201_118_dialog_content = "Hei... Jangan...",
  ui_story_1011_10111201_119_dialog_content = "<color=#e8d9bb>Grrkk... Grrkk...</color>",
  ui_story_1011_10111201_120_dialog_content = "Kurasa aku mendengar suara gesekan.",
  ui_story_1011_10111201_121_dialog_content = "Mungkinkah ada semacam mekanisme yang masih berfungsi di sini?",
  ui_story_1011_10111201_122_dialog_content = "Mungkin saja.",
  ui_story_1011_10111201_123_dialog_content = "Aku jadi penasaran, bagaimana itu bisa tetap berfungsi setelah terlantar sekian lama?",
  ui_story_1011_10111201_124_dialog_content = "Soalnya kurun waktunya beberapa milenium... Energi, keausan... Aku sama sekali tak dapat memahaminya.",
  ui_story_1011_10111201_125_dialog_content = "Mungkin itu masalah besar bagi kita, tetapi tidak begitu bagi siapa pun yang menciptakan tempat ini.",
  ui_story_1011_10111201_126_dialog_content = "Sepertinya mereka memiliki pendekatan yang berbeda untuk masalah yang ada.",
  ui_story_1011_10111201_127_dialog_content = "Itu benar.",
  ui_story_1011_10111201_128_dialog_content = "Mari kita dekati sumber suara itu.",
  ui_story_1011_10111201_129_dialog_content = "Ya.",
  ui_story_1011_10111201_130_dialog_content = "<color=#e8d9bb>Grrkk... Grrkk...</color>",
  ui_story_1011_10111201_131_dialog_content = "Tunggu!",
  ui_story_1011_10111201_132_dialog_content = "Ada apa?",
  ui_story_1011_10111201_133_dialog_content = "Kupikir aku merasakannya.",
  ui_story_1011_10111201_134_dialog_content = "<color=#e8d9bb>Grrkk... Grrkk...</color>",
  ui_story_1011_10111201_135_dialog_content = "...",
  ui_story_1011_10111201_136_dialog_content = "Eclipsite?!",
  ui_story_1011_10111201_137_dialog_content = "Di sini, juga?",
  ui_story_1011_10111201_138_dialog_content = "Aneh. Mereka pasti melihat kita. Namun, kenapa mereka tidak bereaksi?",
  ui_story_1011_10111201_139_dialog_content = "...",
  ui_story_1011_10111201_140_dialog_content = "Lihat! Apa yang sedang mereka lakukan?",
  ui_story_1011_10111201_141_dialog_content = "<color=#e8d9bb>Grrkk... Grrkk...</color>",
  ui_story_1011_10111201_142_dialog_content = "Apakah mereka sedang... mendorong tablet-tablet itu?",
  ui_story_1011_10111201_143_dialog_content = "Mengapa mereka melakukannya?",
  ui_story_1011_10111201_144_dialog_content = "Aku belum pernah melihat Eclipsite seperti ini.",
  ui_story_1011_10111201_145_dialog_content = "Sulit memahami hal yang sedang mereka lakukan...",
  ui_story_1011_10111201_145X1_dialog_content = "Apakah mereka mematuhi perintah High-Level Eclipsite?",
  ui_story_1011_10111201_145X2_dialog_content = "Tidak. Tak masuk akal Eclipsite mau mendorong tablet-tablet itu.",
  ui_story_1011_10111201_145X3_dialog_content = "Namun... itu kisah yang berbeda sama sekali bagi Caelestite...",
  ui_story_1011_10111201_147_dialog_content = "Maksudmu?",
  ui_story_1011_10111201_148_dialog_content = "Kita baru saja membahas bagaimana semua hal di sini tetap beroperasi, bukan?",
  ui_story_1011_10111201_149_dialog_content = "Kita telah mendapatkan jawabannya.",
  ui_story_1011_10111201_150_dialog_content = "Maksudmu, Eclipsite?",
  ui_story_1011_10111201_151_dialog_content = "Ini hanya dugaan.",
  ui_story_1011_10111201_152_dialog_content = "Lihat? Mereka terus menggerakkan tablet-tablet itu dan memilih untuk mengabaikan kita sama sekali.",
  ui_story_1011_10111201_153_dialog_content = "Mereka seperti rantai yang memutar roda gigi... Mereka bagian dari mekanisme yang ada.",
  ui_story_1011_10111201_154_dialog_content = "<color=#e8d9bb>Grrkk... Grrkk...</color>",
  ui_story_1011_10111201_155_dialog_content = "Bagaimana ini mungkin...",
  ui_story_1011_10111201_156_dialog_content = "Sepertinya hal yang kulihat di Circular System benar.",
  ui_story_1011_10111201_157_dialog_content = "Entah bagaimana dulu Caelestite dapat memerintah Eclipsite...",
  ui_story_1011_10111201_158_dialog_content = "Bagaimana dulu mereka melakukannya?",
  ui_story_1011_10111201_159_dialog_content = "Menggunakan telepati, mungkin?",
  ui_story_1011_10111201_160_dialog_content = "Tempat ini telah lama terlantar, tetapi Eclipsite masih mematuhi perintah mereka.",
  ui_story_1011_10111201_161_dialog_content = "Sebentar. Itu sepertinya jalan buntu.",
  ui_story_1011_10111201_162_dialog_content = "Kau benar. Itu ujungnya.",
  ui_story_1011_10111201_163_dialog_content = "Sepertinya tidak ada apa-apa di sana. Hanya ruang terbuka yang luas.",
  ui_story_1011_10111201_164_dialog_content = "Ada mimbar batu di tengahnya. Mari kita periksa.",
  ui_story_1011_10111201_165_dialog_content = "Para Eclipsite itu mungkin mendorong tablet tersebut untuk mengendalikan sesuatu.",
  ui_story_1011_10111201_166_dialog_content = "Namun, itu hanya mimbar batu.",
  ui_story_1011_10111201_167_dialog_content = "Adakah sakelar atau sejenisnya di sisi-sisinya?",
  ui_story_1011_10111201_168_dialog_content = "*Uhuk* Debunya banyak sekali...",
  ui_story_1011_10111201_169_dialog_content = "Bagaimana kalau kau memakai kemampuan psikismu?",
  ui_story_1011_10111201_170_dialog_content = "Sudah kuperiksa. Tidak ada sama sekali.",
  ui_story_1011_10111201_171_dialog_content = "Ini benar-benar hanya sebongkah batu.",
  ui_story_1011_10111201_172_dialog_content = "Bagaimana ini mungkin?",
  ui_story_1011_10111201_173_dialog_content = "Atau mungkin, dulu pernah ada sesuatu di sini.",
  ui_story_1011_10111201_174_dialog_content = "Namun, hal tersebut telah hancur dan hilang.",
  ui_story_1011_10111201_175_dialog_content = "Mungkin saja, karena segala yang ada di reruntuhan ini dalam keadaan hancur.",
  ui_story_1011_10111201_176_dialog_content = "Bahkan pintu batu besar itu pun rapuh dan retak. Benda-benda yang terbuat dari material lain pasti...",
  ui_story_1011_10111201_177_dialog_content = "<color=#e8d9bb>Ngungg!</color>",
  ui_story_1011_10111201_178_dialog_content = "Permintaan login terdeteksi.",
  ui_story_1011_10111201_179_dialog_content = "Itu Neural Aux!",
  ui_story_1011_10111201_180_dialog_content = "Ada yang diaktifkan. Apa yang telah kaulakukan, PlayerName?",
  ui_story_1011_10111201_181_dialog_content = "Aku... aku tidak melakukan apa pun!",
  ui_story_1011_10111201_182_dialog_content = "Aku malah baru mau menanyakan hal itu!",
  ui_story_1011_10111201_183_dialog_content = "Verifikasi identitas diperlukan.",
  ui_story_1011_10111201_184_dialog_content = "Silakan masukkan identitas pengguna.",
  ui_story_1011_10111201_185_dialog_content = "Identitas? Milikku?",
  ui_story_1011_10111201_186_dialog_content = "Namaku PlayerName.",
  ui_story_1011_10111201_187_dialog_content = "Verifikasi identitas diperlukan.",
  ui_story_1011_10111201_188_dialog_content = "Silakan masukkan identitas pengguna.",
  ui_story_1011_10111201_189_dialog_content = "Hah? Kubilang, namaku adalah PlayerName... Itu tidak cukup?",
  ui_story_1011_10111201_190_dialog_content = "Mungkin ia tidak dapat menemukanmu di database mereka, PlayerName.",
  ui_story_1011_10111201_191_dialog_content = "Lantas kita harus apa?",
  ui_story_1011_10111201_192_dialog_content = "Bukankah ada Caelestite yang bernama Francis?",
  ui_story_1011_10111201_193_dialog_content = "Coba gunakan namanya?",
  ui_story_1011_10111201_194_dialog_content = "Input identitas terdeteksi: Pa... la... pong.",
  ui_story_1011_10111201_195_dialog_content = "Eh? Nama macam apa itu? Aku tak mengucapkan kata seperti itu!",
  ui_story_1011_10111201_196_dialog_content = "Memverifikasi identitas.",
  ui_story_1011_10111201_197_dialog_content = "Bip... Bip... Bip...",
  ui_story_1011_10111201_198_dialog_content = "Memangnya ada orang yang punya nama konyol seperti itu?",
  ui_story_1011_10111201_199_dialog_content = "Sudahlah, Neural Aux. Dapatkah kau memberi tahu kami tempat apa ini?",
  ui_story_1011_10111201_200_dialog_content = "Tunggu, PlayerName!",
  ui_story_1011_10111201_201_dialog_content = "Lihat...",
  ui_story_1011_10111201_202_dialog_content = "Ada apa?",
  ui_story_1011_10111201_203_dialog_content = "...",
  ui_story_1011_10111201_204_dialog_content = "Emm... Mengapa Eclipsite berhenti mendorong tablet itu?",
  ui_story_1011_10111201_205_dialog_content = "Mana mungkin...",
  ui_story_1011_10111201_206_dialog_content = "Graaaah!!",
  ui_story_1011_10111201_207_dialog_content = "Carleen!",
  ui_story_1011_10111201_208_dialog_content = "Ice Blossom! Menyebar!",
  ui_story_1011_10111401_1_dialog_content = "Untungnya, jumlah mereka tidak banyak.",
  ui_story_1011_10111401_2_dialog_content = "Jika tidak, kita pasti kewalahan.",
  ui_story_1011_10111401_3_dialog_content = "Iya.",
  ui_story_1011_10111401_4_dialog_content = "Ada apa dengan Neural Aux? Ia tampak lebih bodoh dari sebelumnya.",
  ui_story_1011_10111401_5_dialog_content = "Hai, Neural Aux. Kau dapat mendengarku?",
  ui_story_1011_10111401_6_dialog_content = "Jawab! Ada apa?",
  ui_story_1011_10111401_7_dialog_content = "Verifikasi identitas gagal. Nama pengguna tidak sah: Palapong.",
  ui_story_1011_10111401_8_dialog_content = "Silakan masukkan nama yang valid atau batalkan login.",
  ui_story_1011_10111401_9_dialog_content = "Apa-apaan... Ia bahkan tidak mendengarkan kita!",
  ui_story_1011_10111401_10_dialog_content = "Tidakkah kau merasa ia memperlakukanmu secara berbeda sekarang...?",
  ui_story_1011_10111401_11_dialog_content = "Sebelumnya, ia mencoba menjawab pertanyaanmu...",
  ui_story_1011_10111401_12_dialog_content = "Namun sekarang, ia hanya menunggu input perintahmu.",
  ui_story_1011_10111401_13_dialog_content = "Sepertinya kau benar...",
  ui_story_1011_10111401_14_dialog_content = "Tapi, kenapa?",
  ui_story_1011_10111401_15_dialog_content = "Apakah ini karena tempat kita berada sekarang?",
  ui_story_1011_10111401_16_dialog_content = "Mungkin tempat ini merupakan lokasi input perintah-perintahnya.",
  ui_story_1011_10111401_17_dialog_content = "Menurutmu begitu, ya?",
  ui_story_1011_10111401_18_dialog_content = "Neural Aux, batalkan login.",
  ui_story_1011_10111401_19_dialog_content = "Permintaan pengaktifan kembali Obelisk of Return diterima.",
  ui_story_1011_10111401_20_dialog_content = "Permintaan dari: Palapong. Identitas tidak sah.",
  ui_story_1011_10111401_21_dialog_content = "Peringatan: Operasi lanjutan akan mengaktifkan <color=#FFB400>Guardian System</color>.",
  ui_story_1011_10111401_22_dialog_content = "Betul, 'kan! Ia melakukannya lagi!",
  ui_story_1011_10111401_23_dialog_content = "Apakah Palapong artinya adalah aku? Aku tidak meminta pengaktifan kembali apa pun!",
  ui_story_1011_10111401_24_dialog_content = "Kalau dipikirkan simpelnya saja...",
  ui_story_1011_10111401_25_dialog_content = "Jawaban yang paling mudah adalah: ia rusak.",
  ui_story_1011_10111401_26_dialog_content = "Rusak? Neural Aux?",
  ui_story_1011_10111401_27_dialog_content = "Tidak. Bagian penerima perintahnya rusak.",
  ui_story_1011_10111401_28_dialog_content = "Sudah coba menggunakan radio Illumina?",
  ui_story_1011_10111401_29_dialog_content = "Saat rusak, ada suara berisik \"Sesssss\".",
  ui_story_1011_10111401_30_dialog_content = "Kedengarannya mirip dengan nama yang terus diulang oleh Neural Aux.",
  ui_story_1011_10111401_31_dialog_content = "Maka, kita dalam masalah serius.",
  ui_story_1011_10111401_32_dialog_content = "Permintaan pengaktifan kembali Obelisk of Return dikonfirmasi.",
  ui_story_1011_10111401_33_dialog_content = "Peringatan: Guardian System akan diaktifkan. Silakan batalkan permintaan.",
  ui_story_1011_10111401_34_dialog_content = "Batalkan! Batalkan sekarang!",
  ui_story_1011_10111401_35_dialog_content = "Aku bahkan tak mengajukan permintaan itu!",
  ui_story_1011_10111401_36_dialog_content = "Peringatan: Pengguna yang tidak sah telah mengaktifkan rangkaian pengaktifan kembali Obelisk of Return secara paksa.",
  ui_story_1011_10111401_37_dialog_content = "Memperoleh rangkaian pengaktifan kembali Obelisk of Return dari Circular System.",
  ui_story_1011_10111401_38_dialog_content = "Bip... Bip... Bip...",
  ui_story_1011_10111401_39_dialog_content = "Aku merasa hal buruk akan terjadi.",
  ui_story_1011_10111401_40_dialog_content = "Aku juga. Adakah cara untuk menghentikannya sekarang?",
  ui_story_1011_10111401_41_dialog_content = "Bagaimana kalau kita hancurkan alat pemancar dan penerima sinyalnya?",
  ui_story_1011_10111401_42_dialog_content = "Tidak berfungsi seperti ini... Mending kita hancurkan saja.",
  ui_story_1011_10111401_43_dialog_content = "Tidak tahu di mana itu. Mimbar batu?",
  ui_story_1011_10111401_44_dialog_content = "Kurasa kita akan tahu sendiri... Ini dia!",
  ui_story_1011_10111401_45_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_1011_10111401_46_dialog_content = "Aduh! Sakit!",
  ui_story_1011_10111401_47_dialog_content = "Bahannya dari batu! Buat apa menendangnya?",
  ui_story_1011_10111401_48_dialog_content = "Peringatan: Pengguna yang tidak sah telah mengaktifkan rangkaian pengaktifan kembali Obelisk of Return secara paksa.",
  ui_story_1011_10111401_49_dialog_content = "Modul energi dipulihkan. Mulai mengisi modul pasokan daya tambahan.",
  ui_story_1011_10111401_50_dialog_content = "Bip... Bip... Bip...",
  ui_story_1011_10111401_51_dialog_content = "Carleen... Apakah kau merasakan gemuruh di bawah kita?",
  ui_story_1011_10111401_52_dialog_content = "Ya... Aku merasakannya...",
  ui_story_1011_10111401_53_dialog_content = "Ia menyebutkan \"Rangkaian pengaktifan kembali Obelisk of Return.\" Pasti ada hal yang sedang terjadi pada seluruh bangunan.",
  ui_story_1011_10111401_54_dialog_content = "Seluruh bangunan? Kedengarannya mengerikan.",
  ui_story_1011_10111401_55_dialog_content = "Itu bukan hal yang perlu kita khawatirkan sekarang.",
  ui_story_1011_10111401_56_dialog_content = "\"Peringatan\" itu terus memperingatkan kita terhadap... Kupikir kita tidak boleh mengabaikannya begitu saja.",
  ui_story_1011_10111401_57_dialog_content = "Peringatan: Pengguna yang tidak sah telah mengaktifkan rangkaian pengaktifan kembali Obelisk of Return secara paksa.",
  ui_story_1011_10111401_58_dialog_content = "Akses terbatas terdeteksi. Tindakan koreksi akan dilaksanakan.",
  ui_story_1011_10111401_59_dialog_content = "Ini peringatan terakhir. Segera batalkan permintaanmu.",
  ui_story_1011_10111401_60_dialog_content = "Sudah kubilang batalkan!",
  ui_story_1011_10111401_61_dialog_content = "Ayolah! Batalkan!",
  ui_story_1011_10111401_62_dialog_content = "Aku tak ingin punya masalah dengan teknologi kuno!",
  ui_story_1011_10111401_64_dialog_content = "Permintaan tidak sah masih dalam proses.",
  ui_story_1011_10111401_65_dialog_content = "Tindakan koreksi siap dilaksanakan.",
  ui_story_1011_10111401_66_dialog_content = "Persetan denganmu, Neural Aux!",
  ui_story_1011_10111401_67_dialog_content = "Mengaktifkan \"Guardian System.\" Melepaskan Claudia.",
  ui_story_1011_10111401_68_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1011_10111401_69_dialog_content = "Apa ini...?",
  ui_story_1011_10111401_70_dialog_content = "Patung? Mesin?",
  ui_story_1011_10111401_71_dialog_content = "Bisa bergerak...?",
  ui_story_1011_10111401_72_dialog_content = "Pasti... rusak...",
  ui_story_1011_10111401_73_dialog_content = "<color=#e8d9bb>Klik... Klik...</color>",
  ui_story_1011_10111401_74_dialog_content = "Sepertinya begitu.",
  ui_story_1011_10111401_75_dialog_content = "PlayerName, bersiap untuk bertarung!",
  ui_story_1011_10111401_76_dialog_content = "Hei, Neural Aux... Sudah terlambat atau belum untuk membahas hal ini?",
  ui_story_1011_10111401_77_dialog_content = "\"Guardian System\" telah memulai proses koreksi.",
  ui_story_1011_10111401_78_dialog_content = [[
Mengoreksi perintah tidak sah, atau 
pengguna tidak sah.]],
  ui_story_1011_10111402_1_dialog_content = "Sungguh tangguh.",
  ui_story_1011_10111402_2_dialog_content = "Ia dapat melawan Luminatics.",
  ui_story_1011_10111402_3_dialog_content = "Kita tidak dapat segera keluar dari situasi ini.",
  ui_story_1011_10111402_4_dialog_content = "Bisakah kau bertahan, Carleen?",
  ui_story_1011_10111402_5_dialog_content = "Aku baik-baik saja, tetapi...",
  ui_story_1011_10111402_6_dialog_content = "Vice tergeletak di sampingku. Aku mengkhawatirkannya.",
  ui_story_1011_10111402_7_dialog_content = "Adakah cara untuk mengakhiri pertempuran ini dengan cepat?",
  ui_story_1011_10111402_8_dialog_content = "Memulai swadiagnosis pada fasilitas Obelisk of Return.",
  ui_story_1011_10111402_9_dialog_content = "Peringatan: Kerusakan kritis. Sebagian besar area tidak berfungsi.",
  ui_story_1011_10111402_10_dialog_content = "Mengaktifkan \"Program Pengendalian Kerusakan\". Mencoba reparasi.",
  ui_story_1011_10111402_11_dialog_content = "!!!",
  ui_story_1011_10111402_12_dialog_content = "Carleen, ia berhenti!",
  ui_story_1011_10111402_13_dialog_content = "Sekarang! Ke belakangnya!",
  ui_story_1011_10111402_14_dialog_content = "Baik!",
  ui_story_1011_10111402_15_dialog_content = "Guardian System masih aktif.",
  ui_story_1011_10111402_16_dialog_content = "Lewati program. Lanjutkan perintah reparasi.",
  ui_story_1011_10111402_17_dialog_content = "Bip... Bip... Bip...",
  ui_story_1011_10111402_18_dialog_content = "<color=#e8d9bb>Klik!</color>",
  ui_story_1011_10111402_19_dialog_content = "Carleen, ia bergerak lagi! Berhati-hatilah!",
  ui_story_1011_10111402_20_dialog_content = "Hanya itu yang kubutuhkan.",
  ui_story_1011_10111402_21_dialog_content = "Teknologi kuno, hadapi Luminatics dari masa depan!",
  ui_story_1011_10111402_22_dialog_content = "Fyuh... Apakah kita berhasil?",
  ui_story_1011_10111402_23_dialog_content = "Ya, ia mati.",
  ui_story_1011_10111402_24_dialog_content = "Jangan sampai aktif kembali.",
  ui_story_1011_10111402_25_dialog_content = "Kita telah menyaksikan kemampuan pertahanan Obelisk of Return.",
  ui_story_1011_10111402_26_dialog_content = "Karena sekarang kita dianggap musuh, mungkin lebih banyak lagi yang akan datang.",
  ui_story_1011_10111402_27_dialog_content = "Kuharap tidak.",
  ui_story_1011_10111402_28_dialog_content = "Aku benar-benar berharap ia tidak menyimpan dendam.",
  ui_story_1011_10111402_29_dialog_content = "Ding! Dong...",
  ui_story_1011_10111402_30_dialog_content = "Reparasi Program Pengendalian Kerusakan selesai. Fungsi utama telah direparasi.",
  ui_story_1011_10111402_31_dialog_content = "Obelisk of Return kini diaktifkan kembali.",
  ui_story_1011_10111402_32_dialog_content = "Hmm? Apakah ada hal besar yang baru saja terjadi tanpa kita menyadarinya...?",
  ui_story_1011_10111402_33_dialog_content = "Sistem Daya Obelisk of Return: Dipulihkan.",
  ui_story_1011_10111402_34_dialog_content = "Sistem Transmisi Obelisk of Return: Dipulihkan.",
  ui_story_1011_10111402_35_dialog_content = "Sistem Pengindra Obelisk of Return: Dipulihkan.",
  ui_story_1011_10111402_36_dialog_content = "<color=#e8d9bb>Klik... klik... klik... klik...</color>",
  ui_story_1011_10111402_37_dialog_content = "Dengar, Carleen! Menara ini aktif kembali di mana pun di sekeliling kita!",
  ui_story_1011_10111402_38_dialog_content = "Berfungsi... Seluruh menara berfungsi sekarang!",
  ui_story_1011_10111402_39_dialog_content = "Ini menakjubkan.",
  ui_story_1011_10111402_40_dialog_content = "Ia tidak mati... Ia hanya...",
  ui_story_1011_10111402_41_dialog_content = "... hibernasi.",
  ui_story_1011_10111402_42_dialog_content = "Laporan situasi menara.",
  ui_story_1011_10111402_43_dialog_content = "Colossus Maintenance Zone - Jumlah Colossus: 1. Status: Perlu reparasi.",
  ui_story_1011_10111402_44_dialog_content = "Colossus Component Storage: Rusak. Reparasi gagal.",
  ui_story_1011_10111402_45_dialog_content = "Resource Production Room - Jumlah Personel: 0",
  ui_story_1011_10111402_46_dialog_content = "Waste Disposal Facility - Jumlah Personel: 0",
  ui_story_1011_10111402_47_dialog_content = "Caelestite Residential Area - Jumlah Personel: 0",
  ui_story_1011_10111402_48_dialog_content = "Exile Zone - Jumlah Personel: 0",
  ui_story_1011_10111402_49_dialog_content = "...",
  ui_story_1011_10111402_50_dialog_content = "Tidak ada Caelestite yang tersisa, kecuali...",
  ui_story_1011_10111402_51_dialog_content = "Central Core Area - Jumlah Personel: 1",
  ui_story_1011_10111402_52_dialog_content = "Ya. Aku.",
  ui_story_1011_10111402_53_dialog_content = "Ia telah bangun dari tidurnya.",
  ui_story_1011_10111402_54_dialog_content = "Namun,... dapatkah ia terbiasa dengan rasa kesepian?",
  ui_story_1011_10111402_55_dialog_content = "Rangkaian reset dimulai.",
  ui_story_1011_10111402_56_dialog_content = "Obelisk of Return akan bangkit sekali lagi.",
  ui_story_1011_10111402_57_dialog_content = "Belum puaskah kau?",
  ui_story_1011_10111402_58_dialog_content = "Hosh... Hosh...",
  ui_story_1011_10111402_59_dialog_content = "Hei! Jangan berpaling dariku!",
  ui_story_1011_10111402_60_dialog_content = "Bukanlah pertempuran sejati sampai salah satu dari kita kalah!",
  ui_story_1011_10111402_61_dialog_content = "Kau sendirian. Kau ditakdirkan untuk gagal.",
  ui_story_1011_10111402_62_dialog_content = "Ini bukan pertempuran. Kau hanya melampiaskan emosi.",
  ui_story_1011_10111402_63_dialog_content = "(Dia benar-benar pantang menyerah. Betapa kuat dirinya.)",
  ui_story_1011_10111402_64_dialog_content = "(Satu-satunya sebab aku dapat bertahan sejauh ini adalah karena dia sibuk.)",
  ui_story_1011_10111402_65_dialog_content = "(Namun, apa yang ada dalam benaknya? Apa yang sangat berarti baginya di menara ini?)",
  ui_story_1011_10111402_66_dialog_content = "(Sudahlah. Tidak mungkin aku akan segera menemukan jawabannya.)",
  ui_story_1011_10111402_67_dialog_content = "(Satu-satunya yang perlu kutahu adalah, aku harus mencegah lawanku melakukan hal yang mereka ingin lakukan.)",
  ui_story_1011_10111402_68_dialog_content = "(Seorang prajurit tidak boleh takut hanya karena musuhnya sangat kuat!)",
  ui_story_1011_10111402_69_dialog_content = "Di sini, Forsakin!",
  ui_story_1011_10111402_70_dialog_content = "Kau tidak akan dapat mengelabuiku dengan taktik seperti itu!",
  ui_story_1011_10111402_71_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_1011_10111402_72_dialog_content = "<color=#e8d9bb>*gemuruh*</color>",
  ui_story_1011_10111402_73_dialog_content = "Hei... Apa yang terjadi? Gempa bumi?",
  ui_story_1011_10111402_74_dialog_content = "Oh, ayolah! Kita sedang bertempur!",
  ui_story_1011_10111402_75_dialog_content = "Sebentar... Ini bukan gempa bumi biasa.",
  ui_story_1011_10111402_76_dialog_content = "Menara ini...",
  ui_story_1011_10111402_77_dialog_content = "Seluruh menara bergerak.",
  ui_story_1011_10111402_78_dialog_content = "Asapnya! *Uhuk, uhuk*",
  ui_story_1011_10111402_79_dialog_content = "<color=#e8d9bb>*gemuruh*</color>",
  ui_story_1011_10111402_80_dialog_content = "Asta...!",
  ui_story_1011_10111402_81_dialog_content = "Ini jauh lebih buruk dari gempa bumi!",
  ui_story_1011_10111402_82_dialog_content = "Tentu saja!",
  ui_story_1011_10111402_83_dialog_content = "Apa yang akan kita saksikan mungkin hanya terjadi sekali dalam seribu tahun atau lebih...",
  ui_story_1011_10111402_84_dialog_content = "White Tower ini tidak pernah dimaksudkan untuk berada di sini.",
  ui_story_1011_10111402_85_dialog_content = "Ia seharusnya... ada di suatu tempat yang jauh lebih tinggi.",
  ui_story_1011_10111402_86_dialog_content = "<color=#e8d9bb>*gemuruh*</color>",
  ui_story_1011_10111402_87_dialog_content = "APA?!",
  ui_story_1011_10111402_88_dialog_content = "Apakah ini khayalanku saja? Menara yang sangat besar itu... baru saja bangkit dari tanah?!",
  ui_story_1011_10111402_89_dialog_content = "PlayerName! Mereka masih di sana!",
  ui_story_1011_10111402_90_dialog_content = "Apa... yang telah mereka lakukan?",
  ui_story_1011_10111402_91_dialog_content = "Aku tak menyangka ia benar-benar ada. Sebuah bangunan kuno yang masih berfungsi.",
  ui_story_1011_10111402_92_dialog_content = "Di balik dinding... Aku menatap...",
  ui_story_1011_10111402_93_dialog_content = "Era lain?",
  ui_story_1011_10111402_94_dialog_content = "Jadi, apa sebenarnya benda ini? Sudahkah kau mempelajarinya?",
  ui_story_1011_10111402_95_dialog_content = "Aku tidak perlu menjawabmu.",
  ui_story_1011_10111402_96_dialog_content = "(Bahasa Eclipsian) Forsakin... Forsakin!",
  ui_story_1011_10111402_97_dialog_content = "(Bahasa Eclipsian) Ada celah di dinding luar White Tower.",
  ui_story_1011_10111402_98_dialog_content = "Celah... Baguslah.",
  ui_story_1011_10111402_99_dialog_content = "Aku tak perlu menghibur orang gila ini lagi.",
  ui_story_1011_10111402_100_dialog_content = "Hei! Kau tidak bisa meninggalkanku begitu saja!",
  ui_story_1011_10111402_101_dialog_content = "Kita belum selesai!",
  ui_story_1011_10111402_101X1_dialog_content = "(Aku yakin PlayerName sedang melakukan hal yang sangat penting.)",
  ui_story_1011_10111402_101X2_dialog_content = "(Aku tak akan membiarkan Forsakin mengganggu mereka. Pastinya!)",
  ui_story_1011_10111402_102_dialog_content = "Apa yang terjadi! Ini lebih serius dari getaran biasa!",
  ui_story_1011_10111402_103_dialog_content = "Cari pegangan! Hati-hati dengan puing-puing yang jatuh!",
  ui_story_1011_10111402_104_dialog_content = "Bagaimana dengan Vice?!",
  ui_story_1011_10111402_105_dialog_content = "Serahkan dia padaku. Aku akan menjaganya!",
  ui_story_1011_10111402_106_dialog_content = "<color=#e8d9bb>*gemuruh*</color>",
  ui_story_1011_10111402_107_dialog_content = "Fyuh... Fyuh... Akhirnya berhenti juga...",
  ui_story_1011_10111402_108_dialog_content = "Kau tidak apa-apa, Carleen?",
  ui_story_1011_10111402_109_dialog_content = "Aku baik-baik saja. Vice juga... Sementara kau...",
  ui_story_1011_10111402_110_dialog_content = "Kau bisa melepaskan peganganmu pada mimbar batu itu sekarang.",
  ui_story_1011_10111402_111_dialog_content = "Oke.",
  ui_story_1011_10111402_112_dialog_content = "Jadi, apa yang barusan terjadi?",
  ui_story_1011_10111402_113_dialog_content = "Kuyakin tadi kita bergerak ke atas.",
  ui_story_1011_10111402_114_dialog_content = "Iya, aku juga.",
  ui_story_1011_10111402_115_dialog_content = "Obelisk of Return, reset posisi.",
  ui_story_1011_10111402_116_dialog_content = "Melaporkan status kepada manajer...",
  ui_story_1011_10111402_117_dialog_content = "Menara ini berganti posisi? Itukah yang dimaksudkannya sebagai \"reset\"?",
  ui_story_1011_10111402_118_dialog_content = "Bagaimana mungkin itu dilakukan?",
  ui_story_1011_10111402_119_dialog_content = "Laporan gagal. Manajer tidak dapat ditemukan.",
  ui_story_1011_10111402_120_dialog_content = "Memulai prosedur pencadangan. Menemukan pengguna yang memulai perintah reset.",
  ui_story_1011_10111402_121_dialog_content = "Pengguna terkonfirmasi sebagai pengguna tidak sah, \"Palapong.\"",
  ui_story_1011_10111402_122_dialog_content = "Emm... Kau tak akan memberiku masalah lebih banyak lagi, 'kan?",
  ui_story_1011_10111402_123_dialog_content = "Prosedur pencadangan dimulai. Mempromosikan pengguna \"Palapong\" ke status manajer.",
  ui_story_1011_10111402_124_dialog_content = "Akses internal diberikan kepada \"Palapong.\"",
  ui_story_1011_10111402_125_dialog_content = "Hah?",
  ui_story_1011_10111402_126_dialog_content = "Kukira aku pengguna tidak sah, tapi sekarang aku jadi manajer?",
  ui_story_1011_10111402_127_dialog_content = "Apa yang dapat dilakukan oleh seorang manajer?",
  ui_story_1011_10111402_128_dialog_content = "Manajer dapat mengendalikan sebagian besar fungsi Obelisk of Return melalui unit Neural Aux.",
  ui_story_1011_10111402_129_dialog_content = "Oh, begitu…",
  ui_story_1011_10111402_130_dialog_content = "Sebentar! Kau berbicara normal lagi kepadaku!",
  ui_story_1011_10111402_131_dialog_content = "Baik.",
  ui_story_1011_10111402_132_dialog_content = "Jadi, barusan itu apa?",
  ui_story_1011_10111402_133_dialog_content = "Pengguna biasa hanya dapat memasukkan perintah di Central Core dan tidak dapat berinteraksi dengan Neural Aux.",
  ui_story_1011_10111402_134_dialog_content = "Hanya manajer yang memiliki akses ke Neural Aux kapan pun.",
  ui_story_1011_10111402_135_dialog_content = "Oh, kau suka orang yang berkuasa, ya.",
  ui_story_1011_10111402_136_dialog_content = "Aku tidak mengerti.",
  ui_story_1011_10111402_137_dialog_content = "Lupakan saja…",
  ui_story_1011_10111402_138_dialog_content = "Namun, perintah-perintah tadi itu... Perintah-perintah itu sama sekali tidak akurat!",
  ui_story_1011_10111402_139_dialog_content = "Maksudku, lihat saja nama penggunaku, Palapong? Pasti salah, 'kan?!",
  ui_story_1011_10111402_140_dialog_content = "Tadi sistem input perintah tidak berfungsi. Masalah tersebut sekarang telah diperbaiki.",
  ui_story_1011_10111402_141_dialog_content = "Aku mohon maaf atas ketidaknyamanannya.",
  ui_story_1011_10111402_142_dialog_content = "Itu tadi bukan sekadar \"ketidaknyamanan.\"",
  ui_story_1011_10111402_143_dialog_content = "Selain itu, apa maksudmu dengan \"akses internal\"?",
  ui_story_1011_10111402_144_dialog_content = "Informasi dan fungsi di Obelisk of Return dibagi menjadi tiga level akses.",
  ui_story_1011_10111402_145_dialog_content = "<color=#FFB400>Outer Ring</color> dapat diakses pengguna biasa.",
  ui_story_1011_10111402_146_dialog_content = "<color=#FFB400>Inner Ring</color> hanya dapat diakses manajer.",
  ui_story_1011_10111402_147_dialog_content = "<color=#FFB400>Core Ring</color> adalah level Highest Decree, tidak dapat diakses siapa pun.",
  ui_story_1011_10111402_148_dialog_content = "Dengan kata lain, sekarang aku memiliki semua akses kecuali Core Ring?",
  ui_story_1011_10111402_149_dialog_content = "Benar.",
  ui_story_1011_10111402_150_dialog_content = "Kau sekarang memiliki akses ke Inner Ring. Menyinkronkanmu dengan Obelisk of Return.",
  ui_story_1011_10111402_151_dialog_content = "Eh? Apa ini?",
  ui_story_1011_10111402_152_dialog_content = "Semua istilah ini membuatku bingung!",
  ui_story_1011_10111402_153_dialog_content = "Tidak perlu bingung. Buka pikiran dan hubungkan dirimu.",
  ui_story_1011_10111402_154_dialog_content = "Obelisk of Return akan berfungsi seperti matamu.",
  ui_story_1011_10111402_155_dialog_content = "Apa ini...?",
  ui_story_1011_10111402_156_dialog_content = "Itu menara yang sangat besar! Apakah itu seluruh Obelisk of Return?",
  ui_story_1011_10111402_157_dialog_content = "Itu... Itu pintu gua yang kita ledakkan.",
  ui_story_1011_10111402_158_dialog_content = "Jadi, itu tadinya bagian White Tower!",
  ui_story_1011_10111402_159_dialog_content = "PlayerName, dapatkah kau melihat bagian luar menara?",
  ui_story_1011_10111402_160_dialog_content = "Ya!",
  ui_story_1011_10111402_161_dialog_content = "Mengagumkan! Rasanya seperti terbang!",
  ui_story_1011_10111402_162_dialog_content = "Kau dapat melihat jauh.",
  ui_story_1011_10111402_163_dialog_content = "Jauh... Sangat jauh.",
  ui_story_1011_10111501_1_dialog_content = "Di sana! Di sana!",
  ui_story_1011_10111501_2_dialog_content = "Aku telah memeriksanya. Tak ada apa-apa!",
  ui_story_1011_10111501_3_dialog_content = "Lalu apa...",
  ui_story_1011_10111501_4_dialog_content = "Kita akan memerlukan seseorang!",
  ui_story_1011_10111501_5_dialog_content = "Ini bukan hal yang dapat kita selesaikan sendiri.",
  ui_story_1011_10111501_6_dialog_content = "Benar... Panggil Nightwatch! Panggil Nightwatch!",
  ui_story_1011_10111501_7_dialog_content = "Mereka pasti dapat menangani masalah seperti ini!",
  ui_story_1011_10111501_8_dialog_content = "Itu... Itu Damocles...",
  ui_story_1011_10111501_9_dialog_content = "Nadine, laporkan situasi.",
  ui_story_1011_10111501_10_dialog_content = "Siap, Lord.",
  ui_story_1011_10111501_11_dialog_content = "Penjaga kami melaporkan keanehan yang muncul dari arah Control Room sekitar sepuluh menit yang lalu.",
  ui_story_1011_10111501_12_dialog_content = "Mereka belum pernah menemui situasi serupa. Mereka panik setelah gagal mengidentifikasi masalah.",
  ui_story_1011_10111501_13_dialog_content = "Namun, mereka telah menarik kesimpulan.",
  ui_story_1011_10111501_14_dialog_content = "<color=#FFB400>Damocles</color> diaktifkan.",
  ui_story_1011_10111501_15_dialog_content = "Damocles lagi.",
  ui_story_1011_10111501_16_dialog_content = "Siapa yang mencoba mengaktifkannya kali ini?",
  ui_story_1011_10111501_17_dialog_content = "Tak ada.",
  ui_story_1011_10111501_18_dialog_content = "?!",
  ui_story_1011_10111501_19_dialog_content = "Penjaga melakukan pencarian dengan saksama. Mereka tidak menemukan siapa pun.",
  ui_story_1011_10111501_20_dialog_content = "Damocles teraktifkan sendiri.",
  ui_story_1011_10111501_21_dialog_content = "Kok bisa?",
  ui_story_1011_10111501_22_dialog_content = "Bagaimana situasi Damocles sekarang?",
  ui_story_1011_10111501_23_dialog_content = "Ia menjalankan prosedur penyalaan. Ia sedang mengisi daya Lumina.",
  ui_story_1011_10111501_24_dialog_content = "Baiklah. Siap.",
  ui_story_1011_10111501_25_dialog_content = "Nadine, putuskan sambungan Lumina antara Damocles dan Lumopolis, sekarang juga.",
  ui_story_1011_10111501_26_dialog_content = "Jangan khawatirkan akibatnya. Lakukan saja.",
  ui_story_1011_10111501_27_dialog_content = "Siap, Lord.",
  ui_story_1011_10111501_28_dialog_content = "Irridon, bawa orang-orangmu dan kunci tempat ini. Jangan biarkan siapa pun mendekati Control Room.",
  ui_story_1011_10111501_29_dialog_content = "Terutama Elder Council... Senang benar mereka membuat kita pusing pada saat-saat sulit...",
  ui_story_1011_10111501_30_dialog_content = "Siap, Lord.",
  ui_story_1011_10111501_31_dialog_content = "Namun, sepertinya kita harus memastikan akurasi info intelnya dulu.",
  ui_story_1011_10111501_32_dialog_content = "Memutus hubungan Damocles dan mengunci Control Room punya dampak sangat besar.",
  ui_story_1011_10111501_33_dialog_content = "Andai saja ini semudah menghukum sejumlah penjaga...",
  ui_story_1011_10111501_34_dialog_content = "Namun, aku ragu persoalannya semudah itu.",
  ui_story_1011_10111501_35_dialog_content = "Aku tak akan mengambil risiko Damocles dapat menembak setiap saat. Semua kekhawatiran lainnya tidak sepenting ini.",
  ui_story_1011_10111501_36_dialog_content = "Baik, Lord.",
  ui_story_1011_10111501_37_dialog_content = "Four Angels, ikut aku.",
  ui_story_1011_10111501_38_dialog_content = "Siap, Pak!",
  ui_story_1011_10111501_39_dialog_content = "<color=#e8d9bb>Ngungg!</color>",
  ui_story_1011_10111501_40_dialog_content = "Lagi-lagi denyutan Lumina!",
  ui_story_1011_10111501_41_dialog_content = "Namun,... energi level Damocles terus turun!",
  ui_story_1011_10111501_42_dialog_content = "Bagus. Bagaimana denganmu?",
  ui_story_1011_10111501_43_dialog_content = "Kami dapat bertahan... tetapi tidak lama!",
  ui_story_1011_10111501_44_dialog_content = "Kami memberikan semua yang kami miliki...",
  ui_story_1011_10111501_45_dialog_content = "Dadaku terasa seperti... terbakar...",
  ui_story_1011_10111501_46_dialog_content = "...",
  ui_story_1011_10111501_47_dialog_content = "Aku tahu.",
  ui_story_1011_10111501_48_dialog_content = "Kita akan mengakhirinya kali ini.",
  ui_story_1011_10111501_49_dialog_content = "Kalian semua, lepaskan Lumina untuk mengganggu transmisi Damocles!",
  ui_story_1011_10111501_50_dialog_content = "Lakukan segala yang dapat kaulakukan untuk membalikkan operasinya!",
  ui_story_1011_10111501_51_dialog_content = "Siap, Pak!",
  ui_story_1011_10111501_52_dialog_content = "<color=#e8d9bb>Ngungg!</color>",
  ui_story_1011_10111501_53_dialog_content = "<color=#e8d9bb>Brr...</color>",
  ui_story_1011_10111501_54_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1011_10111501_55_dialog_content = "Hosh... Hosh...",
  ui_story_1011_10111501_56_dialog_content = "Apakah kita... berhasil menghentikannya...?",
  ui_story_1011_10111501_57_dialog_content = "Kita... itu... semua terbakar...",
  ui_story_1011_10111501_58_dialog_content = "...",
  ui_story_1011_10111501_59_dialog_content = "Lord, apakah masalah telah teratasi?",
  ui_story_1011_10111501_60_dialog_content = "Ya. Urusan kita di ruangan ini sudah selesai.",
  ui_story_1011_10111501_61_dialog_content = "Kalau begitu...",
  ui_story_1011_10111501_62_dialog_content = "Damocles…",
  ui_story_1011_10111501_63_dialog_content = "Apa target yang kau tuju...?",
  ui_story_1011_10111501_64_dialog_content = "<color=#e8d9bb>Nguung, nguung, ngung...</color>",
  ui_story_1011_10111501_65_dialog_content = "Itu... begitu... BERISIK!",
  ui_story_1011_10111501_66_dialog_content = "*Hiks* Aku hanya ingin tidur siang...",
  ui_story_1011_10111501_67_dialog_content = "Hm? Philyshy?",
  ui_story_1011_10111501_68_dialog_content = "Kau tidur lagi saat kerja, 'kan?",
  ui_story_1011_10111501_69_dialog_content = "Apa yang kaukatakan, Pak? Aku tidak tidur!",
  ui_story_1011_10111501_70_dialog_content = "Sudahlah... Kali ini.",
  ui_story_1011_10111501_71_dialog_content = "Namun, suara berisik apa itu...?",
  ui_story_1011_10111501_72_dialog_content = "<color=#e8d9bb>Nguung, nguung, ngung...</color>",
  ui_story_1011_10111501_73_dialog_content = "Suara itu... sangat menggangguku! Apa itu?!",
  ui_story_1011_10111501_74_dialog_content = "Hei! Halo, semuanya!",
  ui_story_1011_10111501_75_dialog_content = "Oh, Commander Sharona.",
  ui_story_1011_10111501_76_dialog_content = "Kau juga...?",
  ui_story_1011_10111501_77_dialog_content = "Vivian, kau tahu apa yang sedang terjadi?",
  ui_story_1011_10111501_78_dialog_content = "Tidak sama sekali. Belum pernah mendengar hal seperti itu.",
  ui_story_1011_10111501_79_dialog_content = "Semuanya tidak ada yang tahu.",
  ui_story_1011_10111501_80_dialog_content = "Jangan bilang aku harus tersiksa oleh suara berisik dari Gannon seperti ini di luar medan perang...",
  ui_story_1011_10111501_81_dialog_content = "Pasti ada yang tidak berfungsi di suatu tempat. Aku akan meminta seseorang untuk segera memeriksanya!",
  ui_story_1011_10111501_82_dialog_content = "<color=#e8d9bb>Nguung, nguung, ngung...</color>",
  ui_story_1011_10111501_83_dialog_content = "Jadi, begitulah sekarang. Seluruh Gannon dapat mendengarnya.",
  ui_story_1011_10111501_84_dialog_content = "Em-hem...",
  ui_story_1011_10111501_85_dialog_content = "Petugas pemeliharaan kita mengatakan bahwa itu berasal dari sejumlah peralatan kuno di dalam dinding.",
  ui_story_1011_10111501_86_dialog_content = "Peralatan itu tercatat sebagai barang rusak dan rongsokan... Tak ada yang menyangka barang-barang itu dapat membuat kebisingan seperti itu.",
  ui_story_1011_10111501_87_dialog_content = "Em-hem...",
  ui_story_1011_10111501_88_dialog_content = "Gronru, kau dengar, tidak?",
  ui_story_1011_10111501_89_dialog_content = "Em-hem... Aku mendengarkan.",
  ui_story_1011_10111501_90_dialog_content = "Kau sedang membahas hal itu... Ya. Itu.",
  ui_story_1011_10111501_91_dialog_content = "Kau tidak mendengarkan sama sekali!",
  ui_story_1011_10111501_92_dialog_content = "Letakkan buku itu! Ini penting!",
  ui_story_1011_10111501_93_dialog_content = "Suara berisik itu telah menyebabkan kepanikan di kota!",
  ui_story_1011_10111501_94_dialog_content = "Tim teknologi kita tidak dapat berbuat apa-apa. Dapatkah kau...",
  ui_story_1011_10111501_95_dialog_content = "Hush!",
  ui_story_1011_10111501_96_dialog_content = "?!",
  ui_story_1011_10111501_97_dialog_content = "<color=#e8d9bb>Nguung, nguung, ngung...</color>",
  ui_story_1011_10111501_98_dialog_content = "Oh, begitu.",
  ui_story_1011_10111501_99_dialog_content = "Ya. Aku paham sekarang. Sungguh.",
  ui_story_1011_10111501_100_dialog_content = "Hm? Apa yang kaupahami?",
  ui_story_1011_10111501_101_dialog_content = "Jangan mematikannya hanya karena sakit didengarkan... tetapi DENGARKAN dengan saksama!",
  ui_story_1011_10111501_102_dialog_content = "Itu bukan sekadar suara berisik. Ada pesan tersembunyi...",
  ui_story_1011_10111501_103_dialog_content = "Pesan tersembunyi?",
  ui_story_1011_10111501_104_dialog_content = "Suatu bahasa yang sangat kuno, ya.",
  ui_story_1011_10111501_105_dialog_content = "Biar kulihat... Halaman 302... Halaman 564...",
  ui_story_1011_10111501_106_dialog_content = "Ini dia!",
  ui_story_1011_10111501_107_dialog_content = "Menurutku, paling jauh ini adalah dugaan paling berpendidikan atas bahasa kuno tersebut...",
  ui_story_1011_10111501_108_dialog_content = "Namun, menurutku, artinya adalah seperti...",
  ui_story_1011_10111501_109_dialog_content = "<color=#FFB400>\"Sembunyi. Sekarang.\"</color>",
  ui_story_1011_10111501_110_dialog_content = "Aku datang, Brock.",
  ui_story_1011_10111501_111_dialog_content = "Humph! Kau siap kalah?",
  ui_story_1011_10111501_112_dialog_content = "Mestinya aku yang mengatakannya padamu, Jenderal yang Selalu Kalah!",
  ui_story_1011_10111501_113_dialog_content = "Aku tak akan menanggung julukan memalukan itu lagi!",
  ui_story_1011_10111501_114_dialog_content = "Hari ini, setiap orang akan menyaksikanku mengalahkan Sinsa, dengan jujur dan adil!",
  ui_story_1011_10111501_115_dialog_content = "Oh! Senang melihatmu begitu percaya diri.",
  ui_story_1011_10111501_116_dialog_content = "Namun,... setiap orang?",
  ui_story_1011_10111501_117_dialog_content = "Benar. Aku mengundang setiap orang dari Rediesel Wrench untuk datang kemari.",
  ui_story_1011_10111501_118_dialog_content = "Apa? Apakah bertarung di depan setiap orang membuat kau takut?",
  ui_story_1011_10111501_119_dialog_content = "Katanya ada orang lain... Namun, di mana orang-orang?",
  ui_story_1011_10111501_120_dialog_content = "Tak seorang pun kulihat.",
  ui_story_1011_10111501_121_dialog_content = "Hei! Ayo, semuanya!",
  ui_story_1011_10111501_122_dialog_content = "Pertarungannya akan segera dimulai!",
  ui_story_1011_10111501_123_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1011_10111501_124_dialog_content = "Hei!",
  ui_story_1011_10111501_125_dialog_content = "Haruskah kami bersorak?",
  ui_story_1011_10111501_126_dialog_content = "Kami bersorak untuk kalian...",
  ui_story_1011_10111501_127_dialog_content = "Kakakku pasti akan menang!",
  ui_story_1011_10111501_128_dialog_content = "Eh? Hanya kalian bertiga?",
  ui_story_1011_10111501_129_dialog_content = "Tidak ada seorang pun yang menyukai kekalahan...",
  ui_story_1011_10111501_130_dialog_content = "Mengapa kau tidak menyerah saja, Brock?",
  ui_story_1011_10111501_131_dialog_content = "Bagaimana aku bisa?!",
  ui_story_1011_10111501_132_dialog_content = "Bro, kalahkan dia!",
  ui_story_1011_10111501_133_dialog_content = "Benar! Aku tak akan mengecewakanmu, Eve!",
  ui_story_1011_10111501_134_dialog_content = "Di mana kau ingin melihat dia keok?",
  ui_story_1011_10111501_135_dialog_content = "Emm... Sinsa, bisakah kau tidak bertarung di atas Lepidoz?",
  ui_story_1011_10111501_136_dialog_content = "Peduli amat dengan penonton... Lagi pula aku tak perlu pemeriah suasana!",
  ui_story_1011_10111501_137_dialog_content = "Aku hanya akan memberi tahu setiap orang tentang kemenangan mutlakku setelah pertarungan berakhir!",
  ui_story_1011_10111501_138_dialog_content = "Haha! Ayo majulah!",
  ui_story_1011_10111501_139_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_1011_10111501_140_dialog_content = "Ahhhhhhh!",
  ui_story_1011_10111501_141_dialog_content = "Ada apa?",
  ui_story_1011_10111501_142_dialog_content = "Bopper, jangan aktifkan Lepidoz tanpa perintahku!",
  ui_story_1011_10111501_143_dialog_content = "Boss, aku di sini, lo...",
  ui_story_1011_10111501_144_dialog_content = "Tidak ada siapa-siapa di Lepidoz kecuali kau sendiri.",
  ui_story_1011_10111501_145_dialog_content = "Eh? Jadi, apa ini?",
  ui_story_1011_10111501_146_dialog_content = "Hei, Sinsa, kau mau kabur?",
  ui_story_1011_10111501_147_dialog_content = "Diam kau! Ini bergerak sendiri⁠—",
  ui_story_1011_10111501_148_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_1011_10111501_149_dialog_content = "Waaaaaah! Ini bergerak makin cepat!",
  ui_story_1011_10111501_150_dialog_content = "Waow! Ini lebih seru dari bayanganku.",
  ui_story_1011_10111501_151_dialog_content = "Kakak kabur dari pertarungan... Kakak pengecut.",
  ui_story_1011_10111501_152_dialog_content = "Ini bukan aku! Sumpah! Ini Lepidoz!",
  ui_story_1011_10111501_153_dialog_content = "Jangan diam saja! Bantu aku!",
  ui_story_1011_10111501_154_dialog_content = "Hei!",
  ui_story_1011_10111501_155_dialog_content = "<color=#e8d9bb>Ta-tam... Ta-tam...</color>",
  ui_story_1011_10111501_156_dialog_content = "Halo. Aku membawa surat urgen untuk Istvan yang perlu kautandatangani.",
  ui_story_1011_10111501_157_dialog_content = "Akan kuterima.",
  ui_story_1011_10111501_158_dialog_content = "Tunggu. Siapa pengirimnya?",
  ui_story_1011_10111501_159_dialog_content = "Tidak tertulis di amplop.",
  ui_story_1011_10111501_160_dialog_content = "Oh, biar kujelaskan.",
  ui_story_1011_10111501_161_dialog_content = "Nama pengirim tidak diperlukan untuk surat urgen yang ditujukan untuk Istvan.",
  ui_story_1011_10111501_162_dialog_content = "Ini diminta oleh Istvan sendiri.",
  ui_story_1011_10111501_163_dialog_content = "Oh, begitu.",
  ui_story_1011_10111501_164_dialog_content = "Terima kasih.",
  ui_story_1011_10111501_165_dialog_content = "Terima kasih telah memilih Courier Union. Sampai jumpa!",
  ui_story_1011_10111501_166_dialog_content = "Hei! Ada surat urgen untuk Istvan. Tolong tanda tangani!",
  ui_story_1011_10111501_167_dialog_content = "Baik. Ada yang lain?",
  ui_story_1011_10111501_168_dialog_content = "Jadi... tidak ada nama pengirimnya karena...",
  ui_story_1011_10111501_169_dialog_content = "Diminta sendiri oleh Istvan sendiri, benar?",
  ui_story_1011_10111501_170_dialog_content = "Ya!",
  ui_story_1011_10111501_171_dialog_content = "Biar aku yang mengurusnya. Terima kasih.",
  ui_story_1011_10111501_172_dialog_content = "Baiklah! Sampai jumpa!",
  ui_story_1011_10111501_173_dialog_content = "Ahhhhh! Aku terlambat, terlambat!",
  ui_story_1011_10111501_174_dialog_content = "Semoga aku tidak terlalu terlambat dan gajiku tidak dipotong.",
  ui_story_1011_10111501_175_dialog_content = "Hei, kau di sini juga, Dove?",
  ui_story_1011_10111501_176_dialog_content = "Ya, Tweety! Kau...",
  ui_story_1011_10111501_177_dialog_content = "Kita mengobrol nanti, ya. Aku sudah terlambat.",
  ui_story_1011_10111501_178_dialog_content = "Halo. Aku membawa surat urgen untuk Istvan yang perlu kautandatangani.",
  ui_story_1011_10111501_179_dialog_content = "Ayah, aku baru saja menerima sejumlah surat urgen untukmu dari Courier Union.",
  ui_story_1011_10111501_180_dialog_content = "Surat urgen? Bawa ke sini.",
  ui_story_1011_10111501_181_dialog_content = "Ini dia.",
  ui_story_1011_10111501_182_dialog_content = "Sejumlah surat urgen sekaligus...",
  ui_story_1011_10111501_183_dialog_content = "Jadi, apa yang telah membuat burung-burung pipit itu panik seperti ini?",
  ui_story_1011_10111501_184_dialog_content = "...",
  ui_story_1011_10111501_185_dialog_content = "Sepertinya bukan burung pipit saja.",
  ui_story_1011_10111501_186_dialog_content = "Sheol, kirim sejumlah orang untuk melacak apa pun yang terjadi di Lumopolis.",
  ui_story_1011_10111501_187_dialog_content = "Aku ingin tahu setiap detailnya hingga info prajurit mana yang telah menghunuskan pedangnya.",
  ui_story_1011_10111501_188_dialog_content = "Siap, laksanakan.",
  ui_story_1011_10111501_189_dialog_content = "Namun, Bukankah kita perlu melakukan persiapan lain?",
  ui_story_1011_10111501_190_dialog_content = "Mungkin akan terlalu terlambat jika kita menunggu Lumopolis bertindak.",
  ui_story_1011_10111501_191_dialog_content = "Tindakan sekarang sudah cukup.",
  ui_story_1011_10111501_192_dialog_content = "Kita tinggal di bawah bayang-bayang Lumopolis.",
  ui_story_1011_10111501_193_dialog_content = "Bayangan harus tahu diri.",
  ui_story_1011_10111501_194_dialog_content = "<color=#e8d9bb>Dadada...</color>",
  ui_story_1011_10111501_195_dialog_content = "Victoria, kau baik-baik saja?",
  ui_story_1011_10111501_196_dialog_content = "...",
  ui_story_1011_10111501_197_dialog_content = "Masih tidak ada respons.",
  ui_story_1011_10111501_198_dialog_content = "Haruskah kita masuk?",
  ui_story_1011_10111501_199_dialog_content = "Tatapan Victoria tadi... membuatku khawatir.",
  ui_story_1011_10111501_200_dialog_content = "Tidak... Sama sekali tidak...",
  ui_story_1011_10111501_201_dialog_content = "Kita tidak boleh masuk kamar Victoria tanpa izin. Itu pelanggaran serius...",
  ui_story_1011_10111501_202_dialog_content = "Tidak perlu khawatir. Victoria mungkin hanya lelah.",
  ui_story_1011_10111501_203_dialog_content = "Kau tak punya pekerjaan lain yang lebih berguna selain mengkhawatirkannya?",
  ui_story_1011_10111501_204_dialog_content = "Aku akan coba mengetuk sekali lagi.",
  ui_story_1011_10111501_205_dialog_content = "<color=#e8d9bb>Tok, tok...</color>",
  ui_story_1011_10111501_206_dialog_content = "Victoria, kau baik-baik saja di dalam?",
  ui_story_1011_10111501_207_dialog_content = "...",
  ui_story_1011_10111501_208_dialog_content = "Sepertinya...",
  ui_story_1011_10111501_209_dialog_content = "Faust, kau masuk.",
  ui_story_1011_10111501_210_dialog_content = "!!!",
  ui_story_1011_10111501_211_dialog_content = "Kau sendiri. Aku tak ingin ada gangguan.",
  ui_story_1011_10111501_212_dialog_content = "Baik, nyonya...",
  ui_story_1011_10111501_213_dialog_content = "<color=#e8d9bb>*Kriek*</color>",
  ui_story_1011_10111501_214_dialog_content = "Victoria, kau...",
  ui_story_1011_10111501_215_dialog_content = "Lihat ini.",
  ui_story_1011_10111501_216_dialog_content = "Lihat darah mengalir dari Bloody Bible.",
  ui_story_1011_10111501_217_dialog_content = "Itu telah mengalir sejak beberapa saat lalu.",
  ui_story_1011_10111501_218_dialog_content = "Apakah itu artinya... wahyu baru akan terungkap?",
  ui_story_1011_10111501_219_dialog_content = "Perlu waktu lebih lama dari sebelumnya.",
  ui_story_1011_10111501_220_dialog_content = "Karpet telah digenangi darah, tetapi belum ada teks yang muncul di halamannya.",
  ui_story_1011_10111501_221_dialog_content = "Suatu hal yang bahkan \"Truth\" tidak berani mengatakannya?",
  ui_story_1011_10111501_222_dialog_content = "Bagaimana ini mungkin...?",
  ui_story_1011_10111501_223_dialog_content = "Apakah kau pernah mengalami hal seperti ini sepanjang hidupmu?",
  ui_story_1011_10111501_224_dialog_content = "Hush!",
  ui_story_1011_10111501_225_dialog_content = "Muncul.",
  ui_story_1011_10111501_226_dialog_content = "Akhirnya. Muncul.",
  ui_story_1011_10111501_227_dialog_content = "!!!",
  ui_story_1011_10111501_228_dialog_content = "\"■■\"",
  ui_story_1011_10111501_229_dialog_content = "\"■■■■■■■■■■\"",
  ui_story_1011_10111501_230_dialog_content = "Apa?!",
  ui_story_1011_10111501_231_dialog_content = "Aku belum pernah melihat bahasa ini. Victoria, ini artinya apa?",
  ui_story_1011_10111501_232_dialog_content = "Bloody Bible.",
  ui_story_1011_10111501_233_dialog_content = "Apa yang telah kauperlihatkan bukanlah untuk mata kami, bukan?",
  ui_story_1011_10111501_234_dialog_content = "Jadi, ini untuk siapa, untuk dia yang ditakdirkan untuk menerima wahyu...?",
  ui_story_1011_10111501_235_dialog_content = "Aduh... Terang sekali.",
  ui_story_1011_10111501_236_dialog_content = "Hah? Kupikir matahari baru saja tenggelam...",
  ui_story_1011_10111501_237_dialog_content = "Itu bukan matahari!",
  ui_story_1011_10111501_238_dialog_content = "Sepertinya... itu berasal dari mercusuar di tepi laut.",
  ui_story_1011_10111501_239_dialog_content = "Kau benar!",
  ui_story_1011_10111501_240_dialog_content = "Namun, seingatku, cahayanya tak seterang ini.",
  ui_story_1011_10111501_241_dialog_content = "Novio, apakah Yang Mulia Ratu ada di Winter Palace?",
  ui_story_1011_10111501_242_dialog_content = "Ya, betul.",
  ui_story_1011_10111501_243_dialog_content = "Keringatmu mengucur deras. Apa yang terjadi?",
  ui_story_1011_10111501_244_dialog_content = "Mercusuar bersinar lebih terang dari biasanya... Aku khawatir kalau...",
  ui_story_1011_10111501_245_dialog_content = "Mungkin ada yang tak beres dengan pasukan yang menjaga Northland.",
  ui_story_1011_10111501_246_dialog_content = "Begitu, ya. Ini masalah yang genting, sungguh.",
  ui_story_1011_10111501_247_dialog_content = "Ayo. Kita akan segera melakukan pertemuan dengan Yang Mulia Ratu.",
  ui_story_1011_10111501_248_dialog_content = "<color=#e8d9bb>Ta… ta… ta…</color>",
  ui_story_1011_10111501_249_dialog_content = "Yang Mulia Ratu, Nikinis memohon bertemu.",
  ui_story_1011_10111501_250_dialog_content = "Dia berkata...",
  ui_story_1011_10111501_251_dialog_content = "Ia menatap...",
  ui_story_1011_10111501_252_dialog_content = "Hmm? Ia...",
  ui_story_1011_10111501_253_dialog_content = "Ia menatap... Ia... menatap...",
  ui_story_1011_10111501_254_dialog_content = "Yang Mulia Ratu sedang tidur.",
  ui_story_1011_10111501_255_dialog_content = "Haruskah kita membangunkannya?",
  ui_story_1011_10111501_256_dialog_content = "Kuyakin Yang Mulia Ratu ingin tahu jika ada yang terjadi pada mercusuar.",
  ui_story_1011_10111501_257_dialog_content = "Dekati beliau dan bisikkan padanya.",
  ui_story_1011_10111501_258_dialog_content = "Oke.",
  ui_story_1011_10111501_259_dialog_content = "Yang Mulia.",
  ui_story_1011_10111501_260_dialog_content = "Mercusuar bersinar seterang matahari.",
  ui_story_1011_10111501_261_dialog_content = "Kami khawatir ada yang hadir untuk mengusir kedamaian malam di Northland.",
  ui_story_1011_10111501_262_dialog_content = "Ia menatap kita... dari langit...",
  ui_story_1011_10111501_263_dialog_content = "Obelisk... mata di langit...",
  ui_story_1011_10111501_264_dialog_content = "Yang Mulia?",
  ui_story_1011_10111501_265_dialog_content = "Lari... sembunyi... sejauh mungkin...",
  ui_story_1011_10111501_266_dialog_content = "Ke puncak gunung... pulau-pulau tak berpenghuni...",
  ui_story_1011_10111501_267_dialog_content = "Novio, ada yang tidak wajar dengan Yang Mulia Ratu.",
  ui_story_1011_10111501_268_dialog_content = "Iya.",
  ui_story_1011_10111501_269_dialog_content = "Yang Mulia Ratu, sudah waktunya bangun.",
  ui_story_1011_10111501_270_dialog_content = "Pergi dari tempat itu...",
  ui_story_1011_10111501_271_dialog_content = "Obelisk...",
  ui_story_1011_10111501_272_dialog_content = "Pergi... dari Kota Obelisk...",
  ui_story_1011_10111501_273_dialog_content = "Yang Mulia Ratu!",
  ui_story_1011_10111501_274_dialog_content = "YANG MULIA RATU!",
  ui_story_1011_10111501_275_dialog_content = "...",
  ui_story_1011_10111501_276_dialog_content = "Yang Mulia Ratu, kau...",
  ui_story_1011_10111501_277_dialog_content = "<color=#FFB400>Kau rupanya, PlayerName.</color>",
  ui_story_1011_10111501_278_dialog_content = "!!!",
  ui_story_1011_10111501_279_dialog_content = "Bukan, Yang Mulia Ratu! Aku...",
  ui_story_1011_10111501_280_dialog_content = "Hah?",
  ui_story_1011_10111501_281_dialog_content = "Mengapa... Mengapa ini terjadi...?",
  ui_story_1011_10111501_282_dialog_content = "Kenapa, PlayerName?",
  ui_story_1011_10111501_283_dialog_content = "Apa yang salah denganku? Aku...",
  ui_story_1011_10111501_284_dialog_content = "Kedengarannya aneh, tetapi...",
  ui_story_1011_10111501_285_dialog_content = "Aku baru saja melihat, begitu jelas...",
  ui_story_1011_10111501_286_dialog_content = "Apa yang tadi kaulihat?",
  ui_story_1011_10111501_287_dialog_content = "Aku melihat <color=#FFB400>seluruh dunia</color>.",
  ui_story_1012_10120101_1_dialog_content = "Saat itu juga, aku melihat seluruh dunia.",
  ui_story_1012_10120101_2_dialog_content = "Dari Illumina hingga ke Lumopolis.",
  ui_story_1012_10120101_3_dialog_content = "Northland hingga ke Rediesel Desert.",
  ui_story_1012_10120101_4_dialog_content = "Saat itu juga, aku menyaksikan segalanya.",
  ui_story_1012_10120101_5_dialog_content = "Seolah-olah aku bukan diriku lagi...",
  ui_story_1012_10120101_6_dialog_content = "Tapi, Obelisk of Return itu sendiri.",
  ui_story_1012_10120101_7_dialog_content = "Aneh sekali... Tak ada catatan bahwa kaum Caelestite memiliki teknologi semacam itu.",
  ui_story_1012_10120101_8_dialog_content = "Tidak, jangan pikirkan itu sekarang.",
  ui_story_1012_10120101_9_dialog_content = "Kalau mesin ini memang inti pangkalan, seharusnya ia tahu cara menyelamatkan Vice!",
  ui_story_1012_10120101_10_dialog_content = "Benar! Neural Aux, cari kasus-kasus tentang detail mengenai pemulihan dari kondisi Hibernasi!",
  ui_story_1012_10120101_11_dialog_content = "Akses diverifikasi. Membuat laporan.",
  ui_story_1012_10120101_12_dialog_content = "Memasuki subjek yang berisi Hibernasi di perangkat <color=#FFB400>Chord Link</color>. Mencoba kombinasi dengan fungsi Synchronization.",
  ui_story_1012_10120101_13_dialog_content = "Eksperimen menghasilkan efek terapeutik positif yang tak terduga.",
  ui_story_1012_10120101_14_dialog_content = "Tanda-tanda pemulihan kesadaran diamati pada subjek, bersama dengan perubahan fisik.",
  ui_story_1012_10120101_15_dialog_content = "Efek samping dari perubahan fisik tidak jelas.",
  ui_story_1012_10120101_16_dialog_content = "Pada akhirnya, Synchronization subjek berhasil dan mereka pulih dari Hibernasi.",
  ui_story_1012_10120101_17_dialog_content = "Chord Link...",
  ui_story_1012_10120101_18_dialog_content = "Apa itu?",
  ui_story_1012_10120101_19_dialog_content = "Mencari informasi mengenai Chord Link...",
  ui_story_1012_10120101_20_dialog_content = "...",
  ui_story_1012_10120101_21_dialog_content = "...",
  ui_story_1012_10120101_22_dialog_content = "#*%￥&￥#&*!",
  ui_story_1012_10120101_23_dialog_content = "Neural Aux?!",
  ui_story_1012_10120101_24_dialog_content = "Kegagalan proses berakhir.",
  ui_story_1012_10120101_25_dialog_content = "Data eksperimen di Chord Link telah disimpan dalam Chord Zone. Biasanya, ini terlarang untuk umum.",
  ui_story_1012_10120101_26_dialog_content = "Itu dirahasiakan?",
  ui_story_1012_10120101_27_dialog_content = "Kedengarannya seperti fasilitas yang sangat penting.",
  ui_story_1012_10120101_28_dialog_content = "Siapa tahu? Hal terpenting di White Tower ini mungkin bukan Circular System...",
  ui_story_1012_10120101_29_dialog_content = "Melainkan Chord Link ini.",
  ui_story_1012_10120101_30_dialog_content = "Neural Aux, ada detail mengenai Chord Zone?",
  ui_story_1012_10120101_31_dialog_content = "Sambungan antara Neural Aux dan Chord Zone rusak. Data tak bisa dibaca!",
  ui_story_1012_10120101_32_dialog_content = "Deskripsi database lokal pada perangkat menyebutkan bahwa—",
  ui_story_1012_10120101_33_dialog_content = "Chord Link bisa memulihkan luka, mengubah sebagian badan, dan juga mengaktifkan potensi Aurorian.",
  ui_story_1012_10120101_34_dialog_content = "Agar Aurorian dan Caelestite bisa berkoordinasi dengan lebih baik dalam pertempuran.",
  ui_story_1012_10120101_35_dialog_content = "Kedengarannya seperti... suatu perangkat transformasi.",
  ui_story_1012_10120101_36_dialog_content = "Tidak... Kalau kaum Caelestite pada masa lalu menganggap Aurorian sebagai musuh...",
  ui_story_1012_10120101_37_dialog_content = "Lalu kenapa di sini ada perangkat yang bisa mengubah Aurorian agar jadi lebih kompatibel dengan Caelestite dalam pertempuran?",
  ui_story_1012_10120101_38_dialog_content = "Kau benar. Ini memang sangat aneh.",
  ui_story_1012_10120101_39_dialog_content = "PlayerName, jangan telan mentah-mentah catatan di perangkat ini.",
  ui_story_1012_10120101_40_dialog_content = "Kita harus mencari tahu apa tepatnya fungsi Chord Link, dan apakah itu akan membahayakan nyawa Vice.",
  ui_story_1012_10120101_41_dialog_content = "Baik, aku paham.",
  ui_story_1012_10120101_42_dialog_content = "Neural Aux, apa ada efek samping dari penggunaan Chord Link?",
  ui_story_1012_10120101_43_dialog_content = "Apa itu akan berdampak buruk pada Vice?",
  ui_story_1012_10120101_44_dialog_content = "Sambungan antara Neural Aux dan Chord Zone rusak. Data tak bisa dibaca!",
  ui_story_1012_10120101_45_dialog_content = "Sambungannya sudah lama terputus. Kau tak berusaha memperbaikinya?",
  ui_story_1012_10120101_46_dialog_content = "Aku hanya sistem yang memberikan bantuan kepada Caelestite.",
  ui_story_1012_10120101_47_dialog_content = "Dilarang memaksa Neural Aux melakukan tugas pemeliharaan di luar fungsi pekerjaannya!",
  ui_story_1012_10120101_48_dialog_content = "Sepertinya aku tak bakal mendapat informasi yang relevan dari sini.",
  ui_story_1012_10120101_49_dialog_content = "Yah, sepertinya tidak ada pilihan lain.",
  ui_story_1012_10120101_50_dialog_content = "Sebaiknya kita coba saja walau berisiko.",
  ui_story_1012_10120101_51_dialog_content = "Vice jadi seperti ini gara-gara aku.",
  ui_story_1012_10120101_52_dialog_content = "Biar aku yang bertanggung jawab meski...",
  ui_story_1012_10120101_53_dialog_content = "...",
  ui_story_1012_10120101_54_dialog_content = "Saat waktunya tiba, akan kucoba menggunakan perangkat itu.",
  ui_story_1012_10120101_55_dialog_content = "Kalau tak ada masalah, aku akan memakainya untuk menyelamatkan Vice.",
  ui_story_1012_10120101_56_dialog_content = "Tapi, kalau tak berhasil... aku mengandalkanmu, Carleen. Bawa Vice kembali ke Illumina untuk mencari bantuan.",
  ui_story_1012_10120101_57_dialog_content = "Idemu bagus, tapi jangan lupa... Caelestite bukanlah Aurorian.",
  ui_story_1012_10120101_58_dialog_content = "Vice adalah temanku. Aku akan ikut berusaha menyelamatkannya.",
  ui_story_1012_10120101_59_dialog_content = "Kalau memang tak ada pilihan selain melakukannya, sebaiknya kucoba.",
  ui_story_1012_10120101_60_dialog_content = "Neural Aux, antar aku ke perangkat ini.",
  ui_story_1012_10120101_61_dialog_content = "Mengalkulasikan rute ke Chord Zone—",
  ui_story_1012_10120101_62_dialog_content = "Rute terdeteksi. Sebagian besar jalan dengan akses ke Chord Zone sudah runtuh. Manager pasti mengambil jalan memutar lewat Exile Zone untuk melanjutkan perjalanan.",
  ui_story_1012_10120101_63_dialog_content = "Sambungan antara Neural Aux dan Chord Zone rusak. Neural Aux tak bisa membuka gerbang secara langsung.",
  ui_story_1012_10120101_64_dialog_content = "Berdasarkan pengaturan terakhir, ada kunci rahasia yang dibuat bagi Supervisor untuk membuka Access Control.",
  ui_story_1012_10120101_65_dialog_content = "Modifikasi terakhir oleh: Master Francis.",
  ui_story_1012_10120101_66_dialog_content = "Lagi-lagi Master Francis?",
  ui_story_1012_10120101_67_dialog_content = "Apa sih yang pria ini rencanakan?",
  ui_story_1012_10120101_68_dialog_content = "Sepertinya dia tidak merencanakan apa pun.",
  ui_story_1012_10120101_69_dialog_content = "Kelihatannya dia justru mempermudah siapa pun yang datang setelahnya.",
  ui_story_1012_10120101_70_dialog_content = "Seperti... kita.",
  ui_story_1012_10120101_71_dialog_content = "Manager, tolong ikuti Neural Aux ke Chord Zone. Neural Aux akan memecahkan Access Control ke Chord Zone untukmu.",
  ui_story_1012_10120101_72_dialog_content = "Chord Zone dan Exile Zone berhubungan?",
  ui_story_1012_10120101_73_dialog_content = "Sepertinya kok bukan tempat yang bagus...",
  ui_story_1012_10120101_74_dialog_content = "Bagus atau tidak, itulah satu-satunya harapan kita.",
  ui_story_1012_10120101_75_dialog_content = "Ayo. Kita bawa Vice ke Chord Zone.",
  ui_story_1012_10120101_76_dialog_content = "Tunjukkan jalannya, Neural Aux.",
  ui_story_1012_10120101_77_dialog_content = "Baiklah! Neural Aux siap melayani!",
  ui_story_1012_10120101_78_dialog_content = "Chord Link...",
  ui_story_1012_10120101_79_dialog_content = "Inikah teknologi yang terkubur di pangkalan bawah tanah?",
  ui_story_1012_10120101_80_dialog_content = "Bisa mengubah tubuh Aurorian...",
  ui_story_1012_10120101_81_dialog_content = "Ini persis apa yang kuinginkan.",
  ui_story_1012_10120101_82_dialog_content = "(Bahasa Eclipsian) Forsakin, orang Illumina itu mengejar kita.",
  ui_story_1012_10120101_83_dialog_content = "(Bahasa Eclipsian) Dia sangat kuat. Kami tak bisa menghentikannya.",
  ui_story_1012_10120101_84_dialog_content = "Orang-orang Illumina memang monster.",
  ui_story_1012_10120101_85_dialog_content = "Kalau kita tak bisa menghentikannya, cari cara untuk memancingnya ke jalan yang salah.",
  ui_story_1012_10120101_86_dialog_content = "Jangan sampai orang nekat itu mendekati teknologi berharga kita.",
  ui_story_1012_10120101_87_dialog_content = "Yang dia inginkan hanyalah pertempuran dan kehancuran.",
  ui_story_1012_10120101_88_dialog_content = "(Bahasa Eclipsian) Dimengerti.",
  ui_story_1012_10120101_89_dialog_content = "Irridon, jangan hentikan aku.",
  ui_story_1012_10120101_90_dialog_content = "Elder Council berhak mengetahui alasan aktivasi Damocles.",
  ui_story_1012_10120101_91_dialog_content = "City Lord melarang siapa pun memasuki ruang kendali.",
  ui_story_1012_10120101_92_dialog_content = "Perintah City Lord adalah hukum yang berlaku di Lumopolis. Kau pasti sudah tahu itu.",
  ui_story_1012_10120101_93_dialog_content = "Lord Otto, kau tetap terikat pada hukum itu meski menjadi anggota Elder Council.",
  ui_story_1012_10120101_94_dialog_content = "Hak Elder Council juga merupakan bagian dari hukum Lumopolis.",
  ui_story_1012_10120101_95_dialog_content = "Chief Judge Irridon, harus kukatakan bahwa sekarang kau—",
  ui_story_1012_10120101_96_dialog_content = "Damocles berhenti?",
  ui_story_1012_10120101_97_dialog_content = "(City Lord dan Four Angels... Berhasil?)",
  ui_story_1012_10120101_98_dialog_content = "Lord Schwartz...",
  ui_story_1012_10120101_99_dialog_content = "Tolong katakan apa yang terjadi di ruang kendali. Kenapa Damocles tiba-tiba diaktifkan?",
  ui_story_1012_10120101_100_dialog_content = "Tenanglah, Otto.",
  ui_story_1012_10120101_101_dialog_content = "Damocles memang diaktifkan tanpa peringatan dan izin, tapi aku sudah menghentikannya.",
  ui_story_1012_10120101_102_dialog_content = "Sekarang senjata itu sudah kembali dalam kendali Lumopolis.",
  ui_story_1012_10120101_103_dialog_content = "Aktivasi tak berizin... Bagaimana mungkin?",
  ui_story_1012_10120101_104_dialog_content = "Damocles memang senjata yang kuat, tapi itu tetap senjata.",
  ui_story_1012_10120101_105_dialog_content = "Mana mungkin senjata itu bisa aktif sendiri tanpa ada yang mengoperasikannya?",
  ui_story_1012_10120101_106_dialog_content = "Ada satu hal yang harus aku koreksi, Otto.",
  ui_story_1012_10120101_107_dialog_content = "Damocles memang senjata Lumopolis, tapi...",
  ui_story_1012_10120101_108_dialog_content = "Itu bukan sepenuhnya milik Lumopolis.",
  ui_story_1012_10120101_109_dialog_content = "...",
  ui_story_1012_10120101_110_dialog_content = "Pada akhirnya, senjata itu tetap sisa peninggalan kaum Ancient yang belum pernah kita lihat, dan sesuatu yang ditolak keras oleh Lumopolis.",
  ui_story_1012_10120101_111_dialog_content = "Kekuatan misterius yang bukan miliknya berpotensi untuk lepas kendali.",
  ui_story_1012_10120101_112_dialog_content = "Akan kuminta para teknisi yang bertanggung jawab menjaga Damocles melakukan pemeriksaan menyeluruh untuk menemukan penyebab lepas kendalinya.",
  ui_story_1012_10120101_113_dialog_content = "Beri tahu aku hasilnya besok.",
  ui_story_1012_10120101_114_dialog_content = "Kuhargai kepedulianmu.",
  ui_story_1012_10120101_115_dialog_content = "Menjaga keamanan dan kemakmuran Lumopolis tentu saja jadi prioritas.",
  ui_story_1012_10120101_116_dialog_content = "...",
  ui_story_1012_10120101_117_dialog_content = "Damocles…",
  ui_story_1012_10120101_118_dialog_content = "Arah yang kautunjukkan adalah...",
  ui_story_1012_10120101_119_dialog_content = "...",
  ui_story_1012_10120101_120_dialog_content = "Raphael.",
  ui_story_1012_10120101_121_dialog_content = "Ah, y-ya!",
  ui_story_1012_10120101_122_dialog_content = "Apa City Lord memberi perintah?",
  ui_story_1012_10120101_123_dialog_content = "Temui Beretta dan minta dia menghimpun pasukan kesatria. Pergi ke Eraveil secepatnya.",
  ui_story_1012_10120101_124_dialog_content = "Baiklah, tapi kau ingin Beretta melakukan apa?",
  ui_story_1012_10120101_125_dialog_content = "Lakukan yang harus dilakukan.",
  ui_story_1012_10120101_126_dialog_content = "Apa?!",
  ui_story_1012_10120101_127_dialog_content = "Pergilah.",
  ui_story_1012_10120101_128_dialog_content = "Baiklah!",
  ui_story_1012_10120101_129_dialog_content = "Yang Mulia...",
  ui_story_1012_10120101_130_dialog_content = "Aku baik-baik saja.",
  ui_story_1012_10120101_131_dialog_content = "Maaf telah membuatmu cemas.",
  ui_story_1012_10120101_132_dialog_content = "Ada yang harus kulaporkan. Ada masalah dengan Beacon. Benda itu... memancarkan cahaya kuat yang berbeda dengan yang lain.",
  ui_story_1012_10120101_133_dialog_content = "Aku tahu.",
  ui_story_1012_10120101_134_dialog_content = "Biar kutangani masalah ini. Tak perlu khawatir.",
  ui_story_1012_10120101_135_dialog_content = "Aku mengerti…",
  ui_story_1012_10120101_136_dialog_content = "Yang Mulia, kau menyebut nama Caelestite itu saat setengah tertidur.",
  ui_story_1012_10120101_137_dialog_content = "Ini... bukan kebetulan, 'kan?",
  ui_story_1012_10120101_138_dialog_content = "...",
  ui_story_1012_10120101_139_dialog_content = "Aku melihatnya berdiri di Menara, menatap dunia.",
  ui_story_1012_10120101_140_dialog_content = "Menara itu adalah suatu wujud yang bahkan tak bisa kupahami.",
  ui_story_1012_10120101_141_dialog_content = "Menara itu dibangun pada zaman dulu kala, dan asal-usulnya tak diketahui.",
  ui_story_1012_10120101_142_dialog_content = "Menara dan Beacon itu melindungi Northland layaknya api dan air.",
  ui_story_1012_10120101_143_dialog_content = "Apa Caelestite... menjadi musuh kita?",
  ui_story_1012_10120101_144_dialog_content = "Tidak, aku tak merasakan kejahatan darinya.",
  ui_story_1012_10120101_145_dialog_content = "Dia tetap sama seperti dulu, penuh kebaikan sederhana.",
  ui_story_1012_10120101_146_dialog_content = "Tapi, kurasakan dia mengalami dilema yang belum pernah dia hadapi sebelumnya.",
  ui_story_1012_10120101_147_dialog_content = "Dan dilema ini akan memengaruhi takdir seluruh Astra.",
  ui_story_1012_10120101_148_dialog_content = "Northland harus membuat pilihan.",
  ui_story_1012_10120101_149_dialog_content = "Siapkan keretanya.",
  ui_story_1012_10120101_150_dialog_content = "Aku akan pergi ke Eraveil untuk mengubah dilema ini.",
  ui_story_1012_10120101_151_dialog_content = "Siap!",
  ui_story_1012_10120101_152_dialog_content = "Keretanya siap, Yang Mulia!",
  ui_story_1012_10120101_153_dialog_content = "Kita akan segera berangkat.",
  ui_story_1012_10120101_154_dialog_content = "Yang Mulia, izinkan aku ikut denganmu ke Eraveil.",
  ui_story_1012_10120101_155_dialog_content = "Tidak, kau harus tetap di sini.",
  ui_story_1012_10120101_156_dialog_content = "Kau harus menjalankan tugas jaga dengan baik dan mengawasi pergerakan Eclipsite saat aku sedang tak di Northland.",
  ui_story_1012_10120101_157_dialog_content = "Urusan lain akan berjalan seperti biasa, jadi tak perlu menundanya karena kepergianku.",
  ui_story_1012_10120101_158_dialog_content = "Tiare akan mendampingiku.",
  ui_story_1012_10120101_159_dialog_content = "...",
  ui_story_1012_10120101_160_dialog_content = "Tiare siap sedia.",
  ui_story_1012_10120101_161_dialog_content = "Kau rupanya...",
  ui_story_1012_10120101_162_dialog_content = "Baiklah, tolong lindungi Yang Mulia. Lindungi api harapan Northland.",
  ui_story_1012_10120101_163_dialog_content = "L-lapor, meong!",
  ui_story_1012_10120101_164_dialog_content = "Terdengar suara-suara keras dan aneh di berbagai bagian Gannon City.",
  ui_story_1012_10120101_165_dialog_content = "Tech Officer Gronru pikir itu adalah alarm yang berasal dari alat musik kuno di dinding Undercity, meong!",
  ui_story_1012_10120101_166_dialog_content = "Aku mengerti. Terus pantau situasi Gannon City.",
  ui_story_1012_10120101_167_dialog_content = "Selain itu, tanyakan pada Undercity lain apakah terjadi hal serupa di sana.",
  ui_story_1012_10120101_168_dialog_content = "Baik, meong!",
  ui_story_1012_10120101_169_dialog_content = "Grand Marshal, mata-mata kita melihat pergerakan Eclipsite yang tak biasa.",
  ui_story_1012_10120101_170_dialog_content = "Eclipsite dari Astra berkumpul di Eraveil.",
  ui_story_1012_10120101_171_dialog_content = "Begitu rupanya. Jaga pertahanan Undercity, dan terus amati.",
  ui_story_1012_10120101_172_dialog_content = "Ya.",
  ui_story_1012_10120101_173_dialog_content = "Eclipsite berkumpul di Eraveil, dan ada pergerakan tak biasa dari peralatan kuno di Gannon...",
  ui_story_1012_10120101_174_dialog_content = "Bocah itu... apa dia mengalami masalah lagi?",
  ui_story_1012_10120101_175_dialog_content = "Heh, bisa-bisanya dia memilih waktu seperti ini.",
  ui_story_1012_10120101_176_dialog_content = "Lapor, Pak!",
  ui_story_1012_10120101_177_dialog_content = "... Sudah kuduga ini belum berakhir.",
  ui_story_1012_10120101_178_dialog_content = "Katakan. Ada apa lagi sekarang?",
  ui_story_1012_10120101_179_dialog_content = "Komite menerima laporan bahwa White Tower di Eraveil tiba-tiba aktif.",
  ui_story_1012_10120101_180_dialog_content = "Setelah itu, teknologi Ancient di mana pun menimbulkan reaksi abnormal secara kolektif.",
  ui_story_1012_10120101_181_dialog_content = "Oh?",
  ui_story_1012_10120101_182_dialog_content = "Lokasinya meliputi Beacon di Northland, Damocles di Lumopolis, Lepidoz yang dimiliki Rediesel Wrench, dan sebagainya...",
  ui_story_1012_10120101_183_dialog_content = "Komite menduga kuat bahwa anomali di Gannon ada hubungannya dengan ini.",
  ui_story_1012_10120101_184_dialog_content = "Itu bisa membuat Beacon dan Damocles bereaksi...?",
  ui_story_1012_10120101_185_dialog_content = "Apa yang kaucari, PlayerName...?",
  ui_story_1012_10120101_186_dialog_content = "Grand Marshal, kami menunggu perintahmu.",
  ui_story_1012_10120101_187_dialog_content = "Biar kupikirkan dulu...",
  ui_story_1012_10120101_188_dialog_content = "Beri tahu semua tim di area Eraveil agar mereka maju ke White Tower yang diaktifkan.",
  ui_story_1012_10120101_189_dialog_content = "Kalau ada Eclipsite, pasang barikade dan cegah mereka berkumpul.",
  ui_story_1012_10120101_190_dialog_content = "Selain itu, segera terjunkan unit elite. Aku yang akan memimpin mereka ke Eraveil untuk mencari tahu apa yang terjadi.",
  ui_story_1012_10120101_191_dialog_content = "Baiklah, aku akan—",
  ui_story_1012_10120101_192_dialog_content = "Dengan segala hormat, Grand Marshal, kau belum pulih dari luka yang kauderita di Undercity 80, dan tidak tepat jika melakukan perang pribadi dalam kondisimu.",
  ui_story_1012_10120101_193_dialog_content = "...",
  ui_story_1012_10120101_194_dialog_content = "Anatoli, lakukan saja tugasmu.",
  ui_story_1012_10120101_195_dialog_content = "Siap.",
  ui_story_1012_10120101_196_dialog_content = "Grand Marshal Reinhardt, kuingatkan bahwa kau masih ditinjau oleh komite.",
  ui_story_1012_10120101_197_dialog_content = "Tindakan berisiko bisa memengaruhi evaluasi komite terhadapmu.",
  ui_story_1012_10120101_198_dialog_content = "Mana yang lebih penting—hasil evaluasi atau keamanan Illumina?",
  ui_story_1012_10120101_199_dialog_content = "... Keamanan Illumina lebih penting.",
  ui_story_1012_10120101_200_dialog_content = "Nah, karena kau sudah mengerti, lakukan saja tugasmu.",
  ui_story_1012_10120101_201_dialog_content = "Aku juga akan melakukan tugasku sebagai Grand Marshal.",
  ui_story_1012_10120101_202_dialog_content = "Aku akan mencatat tindakanmu dalam laporan investigasi.",
  ui_story_1012_10120101_203_dialog_content = "Tulis semaumu.",
  ui_story_1012_10120101_204_dialog_content = "Entah baik atau buruk hasil keputusanku nanti, biarlah rakyat Illumina yang mengevaluasinya.",
  ui_story_1012_10120201_1_dialog_content = "Graaahh—",
  ui_story_1012_10120201_2_dialog_content = "Itu yang terakhir?",
  ui_story_1012_10120201_3_dialog_content = "Ugh...",
  ui_story_1012_10120201_4_dialog_content = "Mereka semua hanya cecunguk yang menghalangi.",
  ui_story_1012_10120201_5_dialog_content = "Forsakin juga kabur entah ke mana.",
  ui_story_1012_10120201_6_dialog_content = "Cih... Aku harus segera menemukannya.",
  ui_story_1012_10120201_7_dialog_content = "Sepertinya aku pernah ke tempat ini.",
  ui_story_1012_10120201_8_dialog_content = "Kenapa benda-benda antik ini menutupi setiap sudut tempat dengan cara yang sama?",
  ui_story_1012_10120201_9_dialog_content = "Ini memang labirin.",
  ui_story_1012_10120201_10_dialog_content = "Jangan-jangan... kawanan Eclipsite itu sengaja memancingku kemari?",
  ui_story_1012_10120201_11_dialog_content = "... Ini pasti rencana Forsakin!",
  ui_story_1012_10120201_12_dialog_content = "Baiklah, karena kau memang ingin mengurungku di labirin ini, aku akan menghancurkannya.",
  ui_story_1012_10120201_13_dialog_content = "<color=#e8d9bb>Kriek—!</color>",
  ui_story_1012_10120201_14_dialog_content = "!!!",
  ui_story_1012_10120201_15_dialog_content = "Hiss—",
  ui_story_1012_10120201_16_dialog_content = "Adudududuh—!",
  ui_story_1012_10120201_17_dialog_content = "Terbuat dari apa sih tembok ini? Kenapa keras sekali?!",
  ui_story_1012_10120201_18_dialog_content = "Pedangku tak bisa menggoresnya, tapi tanganku sampai mati rasa begini.",
  ui_story_1012_10120201_19_dialog_content = "Kalau saja aku bisa merobohkannya dan memasangnya di dinding Undercity, atau mungkin aku akan memasangnya di tank dan menggunakannya untuk menangani Eclipsite. Aduh, betapa indahnya.",
  ui_story_1012_10120201_20_dialog_content = "Sepertinya taktik menusuk dinding tak akan mempan.",
  ui_story_1012_10120201_21_dialog_content = "Kita hanya bisa mengikuti lorong ini.",
  ui_story_1012_10120201_22_dialog_content = "Tapi, Forsakin adalah pemimpin kawanan Eclipsite itu. Kita hanya tinggal pergi ke tempat yang ada banyak Eclipsite. Ya, benar.",
  ui_story_1012_10120201_23_dialog_content = "Kita harus meluangkan waktu untuk membabat habis para cecunguk itu.",
  ui_story_1012_10120201_24_dialog_content = "<color=#e8d9bb>Eraveil, jauh di dalam Colossus Maintenance Base</color>",
  ui_story_1012_10120201_25_dialog_content = "Belok kanan di persimpangan di depan sana.",
  ui_story_1012_10120201_26_dialog_content = "Pangkalan ini sangat besar...",
  ui_story_1012_10120201_27_dialog_content = "Kita bakal tersesat selama berhari-hari dalam lorong rumit ini kalau Neural Aux tidak memandu kita.",
  ui_story_1012_10120201_28_dialog_content = "Kalau kita menyertakan area yang runtuh, cakupan pangkalan bawah tanah ini mungkin meliputi seluruh area Eraveil.",
  ui_story_1012_10120201_29_dialog_content = "Terutama tempat-tempat yang tampak seperti lorong.",
  ui_story_1012_10120201_30_dialog_content = "Lebar dan tingginya jelas menunjukkan bahwa tempat ini tak ditujukan untuk dilewati orang.",
  ui_story_1012_10120201_31_dialog_content = "Aku masih belum menemukan sesuatu saat tiba di sini, tapi sekarang aku sudah memikirkannya...",
  ui_story_1012_10120201_32_dialog_content = "Lorong-lorong ini mungkin untuk dilewati Colossus.",
  ui_story_1012_10120201_33_dialog_content = "...",
  ui_story_1012_10120201_34_dialog_content = "Soal kau, kau hanya akan bertanggung jawab...",
  ui_story_1012_10120201_35_dialog_content = "Menciptakan perang bagi dunia.",
  ui_story_1012_10120201_36_dialog_content = "Caelestite memiloti Colossus lewat lorong ini, tapi bukan untuk misi perdamaian...",
  ui_story_1012_10120201_37_dialog_content = "Siapa Caelestite itu?",
  ui_story_1012_10120201_38_dialog_content = "PlayerName.",
  ui_story_1012_10120201_39_dialog_content = "Sebelum menjadi Caelestite, kau adalah dirimu sendiri.",
  ui_story_1012_10120201_40_dialog_content = "Hah?",
  ui_story_1012_10120201_41_dialog_content = "Bagi kami sekarang, kau adalah kau.",
  ui_story_1012_10120201_42_dialog_content = "Kau adalah Caelestite Terakhir yang diselamatkan dari bawah tanah oleh Vice.",
  ui_story_1012_10120201_43_dialog_content = "Kau teman yang membantu Lumopolis dalam pertarungan melawan Schummer dan Black Colossus.",
  ui_story_1012_10120201_44_dialog_content = "Kau teman yang telah menghadapi petualangan tak terhitung banyaknya dengan kami.",
  ui_story_1012_10120201_45_dialog_content = "Selama kau tetaplah dirimu, dan kau mempertahankan kebaikan dan prinsipmu, kami tak peduli kau ini Caelestite atau Aurorian.",
  ui_story_1012_10120201_46_dialog_content = "Lagi pula kau tak bisa memilih asal-usulmu, jadi kau tak perlu merasa bersalah begitu.",
  ui_story_1012_10120201_47_dialog_content = "Carleen…",
  ui_story_1012_10120201_48_option_content = "Terima kasih sudah menghiburku.",
  ui_story_1012_10120201_49_dialog_content = "Tapi, aku harus mengurus masalah ini.",
  ui_story_1012_10120201_50_dialog_content = "Aku Caelestite Terakhir.",
  ui_story_1012_10120201_51_dialog_content = "Dan sepertinya akulah satu-satunya orang di dunia ini yang bisa mengungkap rahasia Eraveil.",
  ui_story_1012_10120201_52_dialog_content = "Kalau dulu kaum Caelestite memang petarung, maka...",
  ui_story_1012_10120201_53_dialog_content = "Entah Eraveil atau Caelestite, keduanya sama-sama bisa menjadi ancaman bagi dunia ini.",
  ui_story_1012_10120201_54_dialog_content = "Mungkin aku tak akan pernah bisa tidur nyenyak kalau tidak menyelidikinya dengan saksama dan memecahkan potensi bahaya ini.",
  ui_story_1012_10120201_55_dialog_content = "Karena aku tak mau jadi orang yang bakal mengancam keselamatan teman-temanku.",
  ui_story_1012_10120201_56_dialog_content = "...",
  ui_story_1012_10120201_57_dialog_content = "Jangan terlalu memaksakan diri.",
  ui_story_1012_10120201_58_dialog_content = "Aku tahu.",
  ui_story_1012_10120201_59_dialog_content = "Tenang saja, aku sangat memahami diriku.",
  ui_story_1012_10120201_60_dialog_content = "<size=30>Sembarang Eclipsite bisa membuatku terpental dengan sekali tinju...</size>",
  ui_story_1012_10120201_61_dialog_content = "Aku akan mengandalkan kalian kalau sudah waktunya bergantung pada pertolongan kalian.",
  ui_story_1012_10120201_62_dialog_content = "Bagus.",
  ui_story_1012_10120201_63_dialog_content = "<color=#e8d9bb>Kriek—!</color>",
  ui_story_1012_10120201_64_dialog_content = "...?! Apa yang terjadi?",
  ui_story_1012_10120201_65_dialog_content = "Jangan-jangan... ada Eclipsite besar yang masuk?",
  ui_story_1012_10120201_66_dialog_content = "Kedengarannya asal suaranya dari tempat yang dekat.",
  ui_story_1012_10120201_67_dialog_content = "Ayo cepat pergi dari sini dan terus bergerak.",
  ui_story_1012_10120201_68_dialog_content = "Sekarang Vice tak sadarkan diri, jadi kita bakal kesulitan kalau harus bertempur.",
  ui_story_1012_10120201_69_dialog_content = "Tunggu!",
  ui_story_1012_10120201_70_dialog_content = "Ada apa?",
  ui_story_1012_10120201_71_dialog_content = "Sepertinya... aku merasakan Eclipsite!",
  ui_story_1012_10120201_72_dialog_content = "Di belakang!",
  ui_story_1012_10120201_73_dialog_content = "Graaahh—",
  ui_story_1012_10120201_74_dialog_content = "!!!",
  ui_story_1012_10120201_75_dialog_content = "Dari mana datangnya mereka?!",
  ui_story_1012_10120201_76_dialog_content = "Aku butuh bantuanmu, PlayerName!",
  ui_story_1012_10120201_77_dialog_content = "Oke!",
  ui_story_1012_10120202_1_dialog_content = "Kenapa ada begitu banyak Eclipsite?",
  ui_story_1012_10120202_2_dialog_content = "Dan kenapa aku tak merasakan satu pun dari tadi?!",
  ui_story_1012_10120202_3_dialog_content = "Tempat ini sudah lama terbengkalai.",
  ui_story_1012_10120202_4_dialog_content = "Entah sudah ada sejak awal atau kemudian runtuh, ada terowongan gelap yang tak terhitung jumlahnya di pangkalan bawah tanah ini.",
  ui_story_1012_10120202_5_dialog_content = "Mungkin para Eclipsite itu berasal dari beberapa terowongan gelap yang tak kita ketahui.",
  ui_story_1012_10120202_6_dialog_content = "Kau benar…",
  ui_story_1012_10120202_7_dialog_content = "Di sini medannya terlalu rumit. Bahkan kemampuan psikisku tak bisa merasakan semua Eclipsite.",
  ui_story_1012_10120202_8_dialog_content = "Ayo cepat pergi dari sini. Aku tak mau berlama-lama di tempat ini!",
  ui_story_1012_10120202_9_dialog_content = "Bahkan tak ada persimpangan jalan di sini. Kita tak akan bisa lari kalau diserang dari depan dan belakang.",
  ui_story_1012_10120202_10_dialog_content = "...",
  ui_story_1012_10120202_11_dialog_content = "Kemampuan psikis Caelestite memang sulit ditangani.",
  ui_story_1012_10120202_12_dialog_content = "Tapi, jumlah Eclipsite itu sangat banyak.",
  ui_story_1012_10120202_13_dialog_content = "Hasil eksperimen itu juga merupakan hasil pengorbanan yang tak terhitung jumlahnya.",
  ui_story_1012_10120202_14_dialog_content = "Gangguan apa itu barusan?",
  ui_story_1012_10120202_15_dialog_content = "(Bahasa Eclipsian) Forsakin, gempa barusan adalah orang Illumina yang mencoba untuk menghancurkan tembok.",
  ui_story_1012_10120202_16_dialog_content = "(Bahasa Eclipsian) Gempa itu mengejutkan si Caelestite, dan dia menggunakan kemampuan psikisnya untuk merasakan keberadaan kita.",
  ui_story_1012_10120202_17_dialog_content = "Terus perdaya dia.",
  ui_story_1012_10120202_18_dialog_content = "Caelestite itu mendekati target.",
  ui_story_1012_10120202_19_dialog_content = "Jangan biarkan orang nekat itu merusak rencanaku.",
  ui_story_1012_10120202_20_dialog_content = "Halangi dia agar tak bisa mendekat, bahkan kalau harus menggunakan mayat.",
  ui_story_1012_10120202_21_dialog_content = "(Bahasa Eclipsian) Baik, Forsakin!",
  ui_story_1012_10120202_22_dialog_content = "Sialan, mereka terus berdatangan!",
  ui_story_1012_10120202_23_dialog_content = "Mau coba-coba menghentikanku di sini? Cuih, mimpi!",
  ui_story_1012_10120202_24_dialog_content = "Minggir—!",
  ui_story_1012_10120202_25_dialog_content = "Para Eclipsite itu berasal dari arah ini, berarti...",
  ui_story_1012_10120202_26_dialog_content = "Forsakin juga ada di sana, ya?",
  ui_story_1012_10120202_27_dialog_content = "Akhirnya tertangkap juga kau, Forsakin.",
  ui_story_1012_10120401_1_dialog_content = "(Bahasa Eclipsian) F-Forsakin!",
  ui_story_1012_10120401_2_dialog_content = "(Bahasa Eclipsian) Monster Illumina itu sangat kuat! Kami tak bisa menghentikannya!",
  ui_story_1012_10120401_3_dialog_content = "(Bahasa Eclipsian) Dia mengejar kita!",
  ui_story_1012_10120401_4_dialog_content = "Orang yang keras kepala dan tergesa-gesa pun pasti punya batas.",
  ui_story_1012_10120401_5_dialog_content = "Atau seharusnya aku tak berharap monster ini bakal memahaminya.",
  ui_story_1012_10120401_6_dialog_content = "Kalian semua, hentikan dia.",
  ui_story_1012_10120401_7_dialog_content = "(Bahasa Eclipsian) A-apa kami masih harus bertarung...?",
  ui_story_1012_10120401_8_dialog_content = "Jangan buat aku mengulangi perintah.",
  ui_story_1012_10120401_9_dialog_content = "(Bahasa Eclipsian) Baiklah....",
  ui_story_1012_10120401_10_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_1012_10120401_11_dialog_content = "Suara apa itu?",
  ui_story_1012_10120401_12_dialog_content = "<color=#e8d9bb>DUAR—!</color>",
  ui_story_1012_10120401_13_dialog_content = "For—sakin—!",
  ui_story_1012_10120401_14_dialog_content = "Dasar dungu dan keras kepala.",
  ui_story_1012_10120401_15_dialog_content = "Makhluk sepertimu bahkan tak bakal memenuhi standar untuk dijadikan bahan eksperimen.",
  ui_story_1012_10120401_16_dialog_content = "Apa pun rencanamu, pasti buruk!",
  ui_story_1012_10120401_17_dialog_content = "Kalau kau memang sangat ingin melakukan eksperimen, lakukan saja sana di sel penjara Gannon City.",
  ui_story_1012_10120401_18_dialog_content = "Pasukan, hentikan dia.",
  ui_story_1012_10120401_19_dialog_content = "Gaah—!",
  ui_story_1012_10120401_20_dialog_content = "Hanya ini kemampuan pasukan Eclipsite itu?",
  ui_story_1012_10120401_21_dialog_content = "Wah, kalau begitu kau memang tak terlalu becus, ya.",
  ui_story_1012_10120401_22_dialog_content = "Kau ini saudari Reinhardt, jadi seharusnya paling tidak kekuatanmu setengah dari kekuatannya, 'kan?",
  ui_story_1012_10120401_23_dialog_content = "...",
  ui_story_1012_10120401_24_dialog_content = "Jangan membandingkanku dengan orang gagal seperti itu.",
  ui_story_1012_10120401_25_dialog_content = "Oh? Kau marah, ya?",
  ui_story_1012_10120401_26_dialog_content = "Bagus. Ayo bertarung saja kalau kau marah!",
  ui_story_1012_10120401_27_dialog_content = "Sepertinya aku tak bisa fokus melakukan eksperimen kalau tidak menenangkanmu dengan benar.",
  ui_story_1012_10120401_28_dialog_content = "Kau membuatku kesal.",
  ui_story_1012_10120401_29_dialog_content = "Ini persis apa yang kuinginkan.",
  ui_story_1012_10120401_30_dialog_content = "Lagi-lagi kembali kemari...",
  ui_story_1012_10120401_31_dialog_content = "Aku masih belum terbiasa dengan atmosfer di tempat ini, entah berapa kali pun aku melihatnya.",
  ui_story_1012_10120401_32_dialog_content = "Aku juga tak suka tempat ini.",
  ui_story_1012_10120401_33_dialog_content = "Ayo cepat temukan jalan masuk ke Chord Zone.",
  ui_story_1012_10120401_34_dialog_content = "Mencapai jalan masuk Chord Zone.",
  ui_story_1012_10120401_35_dialog_content = "Memecahkan Access Control. Neural Aux tak akan bisa menerima perintah lain selama proses berlangsung. Mohon tunggu.",
  ui_story_1012_10120401_36_dialog_content = "1%... 2%... 5%...",
  ui_story_1012_10120401_37_dialog_content = "Sepertinya bakal butuh waktu lama.",
  ui_story_1012_10120401_38_dialog_content = "Iya, kalau begitu aku akan...",
  ui_story_1012_10120401_39_dialog_content = "Ini...",
  ui_story_1012_10120401_40_dialog_content = "Ada apa?",
  ui_story_1012_10120401_41_dialog_content = "Aku merasakan aura Forsakin... Dia memasuki menara!",
  ui_story_1012_10120401_42_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_1012_10120401_43_dialog_content = "Keributan apa ini?!",
  ui_story_1012_10120401_44_dialog_content = "Suara gemuruh ini sudah dari tadi...",
  ui_story_1012_10120401_45_dialog_content = "Itu Forsakin?",
  ui_story_1012_10120401_46_dialog_content = "Mungkinkah Forsakin memerintah para Eclipsite di menara untuk membuat kekacauan?",
  ui_story_1012_10120401_47_dialog_content = "Atau apa ada sesuatu di menara ini yang runtuh?",
  ui_story_1012_10120401_48_dialog_content = "<color=#e8d9bb>DUAR—!</color>",
  ui_story_1012_10120401_49_dialog_content = "Wah! Kenapa ada tanah?!",
  ui_story_1012_10120401_50_dialog_content = "Awas! Ada sesuatu yang menerjang dari tanah!",
  ui_story_1012_10120401_51_dialog_content = "<color=#e8d9bb>Klang—!</color>",
  ui_story_1012_10120401_52_dialog_content = "Kau menghalangi jalan.",
  ui_story_1012_10120401_53_dialog_content = "Jangan alihkan perhatianmu, Forsakin—!",
  ui_story_1012_10120401_54_dialog_content = "Akulah lawanmu.",
  ui_story_1012_10120401_55_dialog_content = "Barton?! Rupanya kau!",
  ui_story_1012_10120401_56_dialog_content = "Hei, PlayerName. Kau juga di sini?",
  ui_story_1012_10120401_57_dialog_content = "Kenapa Vice? Dia pingsan, ya?",
  ui_story_1012_10120401_58_dialog_content = "Vice terluka, kami harus membuka gerbang ini dan mencari cara untuk menyelamatkannya!",
  ui_story_1012_10120401_59_dialog_content = "Barton, bantu kami memperlambat Forsakin!",
  ui_story_1012_10120401_60_dialog_content = "Mengulur waktu...? Baiklah!",
  ui_story_1012_10120401_61_dialog_content = "Kalian, tetaplah di belakangku dan urus para minion itu!",
  ui_story_1012_10120401_62_dialog_content = "Wah, wah. Indah sekali kata-katamu.",
  ui_story_1012_10120401_63_dialog_content = "Lebih baik kauhentikan perlawanan.",
  ui_story_1012_10120401_64_dialog_content = "Seharusnya kaucemaskan saja jarak di antara kita.",
  ui_story_1012_10120401_65_dialog_content = "Aku tak mau buang-buang waktu untuk berurusan denganmu, dan kamu mungkin juga tak mau kehilangan nyawamu.",
  ui_story_1012_10120401_66_dialog_content = "Berikan saja akses mesin itu kepadaku, dan menyerah.",
  ui_story_1012_10120401_67_dialog_content = "Akan kubiarkan kau hidup.",
  ui_story_1012_10120401_68_dialog_content = "Wah, sebaiknya kautinju saja wajahmu agar terbangun dari khayalan!",
  ui_story_1012_10120401_69_dialog_content = "Bagaimana, Caelestite?",
  ui_story_1012_10120401_70_dialog_content = "Kau mau mati seperti orang Illumina yang nekat ini, ya?",
  ui_story_1012_10120401_71_dialog_content = "...",
  ui_story_1012_10120401_72_option_content = "Aku tak akan percaya padamu.",
  ui_story_1012_10120401_73_dialog_content = "Oh?",
  ui_story_1012_10120401_74_dialog_content = "Kau sudah mengelabui banyak orang.",
  ui_story_1012_10120401_75_dialog_content = "Gertzurde, Shelt, Schummer...",
  ui_story_1012_10120401_76_dialog_content = "Kau tak peduli apakah mereka hidup atau mati! Kau hanya memedulikan dirimu sendiri!",
  ui_story_1012_10120401_77_dialog_content = "Kau sama sekali tak bisa dipercaya!",
  ui_story_1012_10120401_78_dialog_content = "...",
  ui_story_1012_10120401_79_dialog_content = "Kesabaranku sudah habis.",
  ui_story_1012_10120401_80_dialog_content = "Serahkan aksesnya, dan akan kupercepat segalanya.",
  ui_story_1012_10120401_81_dialog_content = "Tak akan pernah kuserahkan kepadamu!",
  ui_story_1012_10120401_82_dialog_content = "Tak ada gunanya melawan.",
  ui_story_1012_10120401_83_dialog_content = "Jadi...",
  ui_story_1012_10120401_84_dialog_content = "Selamat tinggal.",
  ui_story_1012_10120402_1_dialog_content = "Awas, PlayerName!",
  ui_story_1012_10120402_2_dialog_content = "Aah—! Tolong!",
  ui_story_1012_10120402_3_dialog_content = "!!",
  ui_story_1012_10120402_4_dialog_content = "Aduh!",
  ui_story_1012_10120402_5_dialog_content = "Jangan sampai perhatianmu teralih kalau sedang bertarung.",
  ui_story_1012_10120402_6_dialog_content = "Kau bilang sendiri tadi.",
  ui_story_1012_10120402_7_dialog_content = "Barton!",
  ui_story_1012_10120402_8_dialog_content = "Ck...",
  ui_story_1012_10120402_9_dialog_content = "Hanya begini kekuatanmu? Kau makan sampai kenyang tidak, sih?",
  ui_story_1012_10120402_10_dialog_content = "Kau sudah menimbulkan masalah sejak di luar menara hingga ke sini.",
  ui_story_1012_10120402_11_dialog_content = "Sekarang kau pasti sudah kehilangan semangat.",
  ui_story_1012_10120402_12_dialog_content = "...",
  ui_story_1012_10120402_13_dialog_content = "Tak usah berjuang kalau tidak perlu.",
  ui_story_1012_10120402_14_dialog_content = "Bah! Hentikan omong kosongmu!",
  ui_story_1012_10120402_15_dialog_content = "Ayo, sini—!",
  ui_story_1012_10120402_16_dialog_content = "Lebih baik kauhabiskan setengah dari waktu yang kaugunakan untuk bertarung dengan belajar.",
  ui_story_1012_10120402_17_dialog_content = "Belajar?",
  ui_story_1012_10120402_18_dialog_content = "Orang seperti dirimu memang ada, ya—jenis orang yang minta langsung dihajar.",
  ui_story_1012_10120402_19_dialog_content = "Kapan aku bisa tenang untuk belajar?",
  ui_story_1012_10120402_20_dialog_content = "Kau harus membayar untuk kedunguanmu.",
  ui_story_1012_10120402_21_dialog_content = "Ugh!",
  ui_story_1012_10120402_22_dialog_content = "Sekarang pergelangan tangan kananmu patah.",
  ui_story_1012_10120402_23_dialog_content = "Aku mau lihat caramu mengambil pisau itu.",
  ui_story_1012_10120402_24_dialog_content = "Atau...",
  ui_story_1012_10120402_25_dialog_content = "Kau boleh berlutut padaku dan memohon agar aku berhenti.",
  ui_story_1012_10120402_26_dialog_content = "Hentikan, Forsakin!",
  ui_story_1012_10120402_27_dialog_content = "Diam.",
  ui_story_1012_10120402_28_dialog_content = "Kau tak berhak bicara, Caelestite lemah dan tak berguna.",
  ui_story_1012_10120402_29_dialog_content = "Tentara Illumina...",
  ui_story_1012_10120402_30_dialog_content = "Hmm?",
  ui_story_1012_10120402_31_dialog_content = "Tentara Illumina... tak akan menyerah pada orang sepertimu!",
  ui_story_1012_10120402_32_dialog_content = "!!!",
  ui_story_1012_10120402_33_dialog_content = "Meski tanganku hanya satu, ini sudah lebih dari cukup untuk menghabisimu!",
  ui_story_1012_10120402_34_dialog_content = "Barton! Kakimu!",
  ui_story_1012_10120402_35_dialog_content = "Bantu dia, Carleen!",
  ui_story_1012_10120402_36_dialog_content = "Ice Blossom! Menyebar!",
  ui_story_1012_10120402_37_dialog_content = "Mustahil! Jumlah mereka banyak sekali!",
  ui_story_1012_10120402_38_dialog_content = "Tak usah mengkhawatirkanku!",
  ui_story_1012_10120402_39_dialog_content = "Pokoknya buka saja gerbangnya! Biar kuurus Forsakin!",
  ui_story_1012_10120402_40_dialog_content = "Tapi, kau sudah...",
  ui_story_1012_10120402_41_dialog_content = "!!!",
  ui_story_1012_10120402_42_dialog_content = "Pergilah!",
  ui_story_1012_10120402_43_dialog_content = "Tapi...!",
  ui_story_1012_10120402_44_dialog_content = "Cari jalan keluar!",
  ui_story_1012_10120402_45_dialog_content = "Kalau aku gugur dalam pertempuran, tuliskan ini di pusaraku—",
  ui_story_1012_10120402_46_dialog_content = "Prajurit Illumina nan hebat yang melawan Eclipsite hingga akhir!",
  ui_story_1012_10120402_47_dialog_content = "PlayerName, kita butuh ruang untuk mundur!",
  ui_story_1012_10120402_48_dialog_content = "Kita bakal mati kalau terjebak di sini!",
  ui_story_1012_10120402_49_dialog_content = "…!",
  ui_story_1012_10120402_50_dialog_content = "Neural Aux, sudah seberapa jauh progres pembukaannya?!",
  ui_story_1012_10120402_51_dialog_content = "Pembukaan gerbang mencapai 96%, mohon tunggu.",
  ui_story_1012_10120402_52_dialog_content = "... Bertahanlah sebentar lagi!",
  ui_story_1012_10120402_53_dialog_content = "97%.",
  ui_story_1012_10120402_54_dialog_content = "98%.",
  ui_story_1012_10120402_55_dialog_content = "99%.",
  ui_story_1012_10120402_56_dialog_content = "100%, pembukaan selesai.",
  ui_story_1012_10120402_57_dialog_content = "<color=#e8d9bb>Gruk—</color>",
  ui_story_1012_10120402_58_dialog_content = "Gerbangnya... terbuka!",
  ui_story_1012_10120402_59_dialog_content = "Carleen, Barton, mundur!",
  ui_story_1012_10120501_1_dialog_content = "Ice Blossom!",
  ui_story_1012_10120501_2_dialog_content = "Cepat! Forsakin mengejar kita dan aku tak bisa berlama-lama menahannya!",
  ui_story_1012_10120501_3_dialog_content = "Kalian lewat sini. Barton, lindungi PlayerName.",
  ui_story_1012_10120501_4_dialog_content = "Tenang saja. Meskipun terluka begini, tak akan kubiarkan Forsakin menyakitinya!",
  ui_story_1012_10120501_5_dialog_content = "Berapa jauh lagi, Neural Aux?",
  ui_story_1012_10120501_6_dialog_content = "Jalan terus sejauh 200 meter untuk mencapai tempat tujuanmu.",
  ui_story_1012_10120501_7_dialog_content = "Hosh... Hosh... Hampir... sampai!",
  ui_story_1012_10120501_8_dialog_content = "Aku bisa lihat gerbangnya!",
  ui_story_1012_10120501_9_dialog_content = "A-aku tak bisa—",
  ui_story_1012_10120501_10_dialog_content = "Kenapa tanah di sini sangat tidak rata?!",
  ui_story_1012_10120501_11_dialog_content = "Menurutku, struktur jalan di Chord Zone sudah berubah karena perubahan medan.",
  ui_story_1012_10120501_12_dialog_content = "Tapi, percayalah bahwa rute yang Neural Aux berikan pasti akurat!",
  ui_story_1012_10120501_13_dialog_content = "Bersemangatlah, Manager! Maju terus!",
  ui_story_1012_10120501_14_dialog_content = "Aku... tak akan menyerah!",
  ui_story_1012_10120501_15_dialog_content = "PlayerName, jangan berhenti!",
  ui_story_1012_10120501_16_dialog_content = "Lari terus, Nak!",
  ui_story_1012_10120501_17_dialog_content = "Kalau sampai berani berhenti, aku akan menendangmu saat kupaksa kau lari 100 putaran mengelilingi Gannon City!",
  ui_story_1012_10120501_18_dialog_content = "Jangan terlalu kasar begitu dong kalau kau coba menghiburku!",
  ui_story_1012_10120501_19_dialog_content = "Aduh—!",
  ui_story_1012_10120501_20_dialog_content = "Neural Aux!",
  ui_story_1012_10120501_21_dialog_content = "Neural Aux Navigation, siap membantu!",
  ui_story_1012_10120501_22_dialog_content = "Tutup gerbangnya begitu kita masuk ke Chord Zone!",
  ui_story_1012_10120501_23_dialog_content = "Kunci para Eclipsite di luar!",
  ui_story_1012_10120501_24_dialog_content = "Paham!",
  ui_story_1012_10120501_25_dialog_content = "Tapi, Manager, hati-hatilah dengan jebakan di bawah kakimu!",
  ui_story_1012_10120501_26_option_content = "Jebakan?",
  ui_story_1012_10120501_27_dialog_content = "Kenapa ada jebakan di tempat ini?!",
  ui_story_1012_10120501_28_option_content = "Ada jebakan juga di sana?!",
  ui_story_1012_10120501_29_dialog_content = "Dari mana datangnya mereka?!",
  ui_story_1012_10120501_30_dialog_content = "Jebakan ini adalah alat pertahanan independen di Chord Zone.",
  ui_story_1012_10120501_31_dialog_content = "Hubungan antara Neural Aux dan Chord Zone telah terputus. Neural Aux tidak bisa mengontrol jebakan di Chord Zone.",
  ui_story_1012_10120501_32_dialog_content = "Jebakan ini sekarang diatur untuk menyerang setelah mendeteksi objek!",
  ui_story_1012_10120501_33_dialog_content = "Manager, lakukan yang menurutmu perlu... bukan, maksudku, menghindarlah kalau menurutmu perlu!",
  ui_story_1012_10120501_34_dialog_content = "Seharusnya kau bilang itu dari tadi!",
  ui_story_1012_10120501_35_dialog_content = "Fakta bahwa ada jebakan di Chord Zone telah resmi dicantumkan di buku pelajaran Caelestite.",
  ui_story_1012_10120501_36_dialog_content = "Kalau kau lupa, Manager, Neural Aux menyarankan untuk kembali ke sekolah dan belajar!",
  ui_story_1012_10120501_37_dialog_content = "Hati-hati melangkah, PlayerName!",
  ui_story_1012_10120501_38_dialog_content = "Hah?",
  ui_story_1012_10120501_39_dialog_content = "<color=#e8d9bb>Klik—</color>",
  ui_story_1012_10120501_40_dialog_content = "Minggir, PlayerName!",
  ui_story_1012_10120501_41_dialog_content = "Ahhh!",
  ui_story_1012_10120501_42_dialog_content = "...",
  ui_story_1012_10120501_43_dialog_content = "Manager, menghindarlah!",
  ui_story_1012_10120501_44_dialog_content = "Apa benda ini punya kemampuan bertempur?",
  ui_story_1012_10120501_45_dialog_content = "Kerahkan dia kalau punya! Setidaknya dia bisa menahan Forsakin sebentar!",
  ui_story_1012_10120501_46_dialog_content = "Aku hanya citra hasil proyeksi, dan tidak punya kemampuan bertempur.",
  ui_story_1012_10120501_47_dialog_content = "Memaksa Neural Aux melakukan tugas tempur di luar fungsi pekerjaannya adalah dilarang!",
  ui_story_1012_10120501_48_dialog_content = "Kalau begitu, beri tahu kami titik perangkapnya!",
  ui_story_1012_10120501_49_dialog_content = "A, aku sedang mencari data tentang jebakan di Chord Zone—",
  ui_story_1012_10120501_50_dialog_content = "Pencarian selesai!",
  ui_story_1012_10120501_51_dialog_content = "Menghindar ke kanan di depan!",
  ui_story_1012_10120501_52_dialog_content = "Oh tidak, para Eclipsite mengejar!",
  ui_story_1012_10120501_53_dialog_content = "Cari cara memanfaatkan jebakan agar mereka berhenti mengejar kita!",
  ui_story_1012_10120502_1_dialog_content = "Manager, kau akan segera sampai di destinasi.",
  ui_story_1012_10120502_2_dialog_content = "Menyiapkan penutupan gerbang Chord Zone.",
  ui_story_1012_10120502_3_dialog_content = "Manager, masuklah ke Chord Zone sebelum gerbang ditutup!",
  ui_story_1012_10120502_4_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_1012_10120502_5_dialog_content = "Tunggu! Itu terlalu cepat!",
  ui_story_1012_10120502_6_dialog_content = "Kita tidak akan berhasil!",
  ui_story_1012_10120502_7_dialog_content = "Hentikan mereka! Jangan sampai kawanan serangga itu merusak peralatan di dalam.",
  ui_story_1012_10120502_8_dialog_content = "PlayerName, cari solusinya!",
  ui_story_1012_10120502_9_dialog_content = "Kita harus membuat jarak dengan Eclipsite!",
  ui_story_1012_10120502_10_dialog_content = "Solusi... solusi... Di mana aku bisa mendapatkan solusi?!",
  ui_story_1012_10120502_11_dialog_content = "Ada jebakan peledak di depan! Awas, dan menghindarlah!",
  ui_story_1012_10120502_12_dialog_content = "Jebakan peledak?",
  ui_story_1012_10120502_13_dialog_content = "Bocah, injaklah jebakan peledak itu!",
  ui_story_1012_10120502_14_dialog_content = "Hah?!",
  ui_story_1012_10120502_15_dialog_content = "Percayalah, injaklah jebakan itu dan tugas kita selesai!",
  ui_story_1012_10120502_16_dialog_content = "Kau tidak akan bisa kabur.",
  ui_story_1012_10120502_17_dialog_content = "Aku akan percaya satu kali ini saja!",
  ui_story_1012_10120502_18_dialog_content = "<color=#e8d9bb>Klik!</color>",
  ui_story_1012_10120502_19_dialog_content = "Bertahanlah, Bocah!",
  ui_story_1012_10120502_20_dialog_content = "<color=#e8d9bb>Der, der!</color>",
  ui_story_1012_10120502_21_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_1012_10120502_22_dialog_content = "Ini—!",
  ui_story_1012_10120502_23_dialog_content = "Ahhh! Kita akan terpelanting ke langit—!",
  ui_story_1012_10120502_24_dialog_content = "<color=#e8d9bb>Duar—BLUG!</color>",
  ui_story_1012_10120502_25_dialog_content = "Kau benar-benar monster dari Illumina.",
  ui_story_1012_10120502_26_dialog_content = "Banyak sekali idemu yang harus membuatmu hampir kehilangan nyawa.",
  ui_story_1012_10120502_27_dialog_content = "Robohkan gerbang ini.",
  ui_story_1012_10120502_28_dialog_content = "(Bahasa Eclipsian) Baik, Forsakin!",
  ui_story_1012_10120502_29_dialog_content = "Apa kita... berhasil?",
  ui_story_1012_10120502_30_dialog_content = "Setidaknya aku masih hidup…",
  ui_story_1012_10120502_31_dialog_content = "Vice juga tidak terluka.",
  ui_story_1012_10120502_32_dialog_content = "Fyuh... Tunggu, di mana Barton?!",
  ui_story_1012_10120502_33_dialog_content = "A... aku baik-baik saja...",
  ui_story_1012_10120502_34_dialog_content = "Ck... Tapi bom buatan Caelestite itu cukup hebat.",
  ui_story_1012_10120502_35_dialog_content = "Kita sudah kalah kalau aku tidak meledakkannya lebih dulu.",
  ui_story_1012_10120502_36_dialog_content = "Kau jelas tidak baik-baik saja!",
  ui_story_1012_10120502_37_dialog_content = "Ehem... Tenang, Bocah...",
  ui_story_1012_10120502_38_dialog_content = "Semua orang di Illumina pernah melalui pertempuran sulit. Luka seperti ini... cuma perlu diperban dan tidak akan terasa lagi setelah aku tidur semalam.",
  ui_story_1012_10120502_39_dialog_content = "Kalau lari ke petugas medis dengan luka kecil saja, kita akan dijinjing dan dilempar keluar dari rumah sakit.",
  ui_story_1012_10120502_40_dialog_content = "Jangan khawatirkan aku... Itu benda yang kalian cari, 'kan?",
  ui_story_1012_10120502_41_dialog_content = "Neural Aux, apa ini Chord Link?",
  ui_story_1012_10120502_42_dialog_content = "Menurutku iya!",
  ui_story_1012_10120502_43_dialog_content = "Apa kesimpulanmu akurat?",
  ui_story_1012_10120502_44_dialog_content = "Apa ada catatan tentang sistem ini?",
  ui_story_1012_10120502_45_dialog_content = "Chord Link adalah sistem utama Chord Zone.",
  ui_story_1012_10120502_46_dialog_content = "Menurut informasi yang terkumpul, perangkat di depan Manager pastilah Chord Link.",
  ui_story_1012_10120502_47_dialog_content = "<color=#e8d9bb>Brak—!</color>",
  ui_story_1012_10120502_48_dialog_content = "Eclipsite itu coba mendobrak gerbang!",
  ui_story_1012_10120502_49_dialog_content = "Jangan cemaskan mereka untuk sementara ini.",
  ui_story_1012_10120502_50_dialog_content = "Dinding dan pintu di pangkalan ini kuat. Aku tidak akan bisa menembusnya walaupun mendobraknya berjam-jam.",
  ui_story_1012_10120502_51_dialog_content = "<color=#e8d9bb>BRAK—!</color>",
  ui_story_1012_10120502_52_dialog_content = "Eh... Gerbangnya penyok!",
  ui_story_1012_10120502_53_dialog_content = "Neural Aux, apa ada cara untuk memperkuat gerbang?",
  ui_story_1012_10120502_54_dialog_content = "Mengaktifkan fungsi penguatan Chord Zone Access Control!",
  ui_story_1012_10120502_55_dialog_content = "<color=#e8d9bb>Klik—Klik—</color>",
  ui_story_1012_10120502_56_dialog_content = "Ada lebih banyak lagi pintu yang terkunci.",
  ui_story_1012_10120502_57_dialog_content = "Sepertinya pintu-pintu itu bisa bertahan sedikit lebih lama.",
  ui_story_1012_10120502_58_dialog_content = "<color=#e8d9bb>Tok... Tok...</color>",
  ui_story_1012_10120502_59_dialog_content = "Serangannya berhenti?",
  ui_story_1012_10120502_60_dialog_content = "<color=#e8d9bb>Dharr!!!</color>",
  ui_story_1012_10120502_61_dialog_content = "Kenapa serangannya jadi lebih hebat?!",
  ui_story_1012_10120502_62_dialog_content = "Apa kepala Eclipsite itu terbuat dari baja?!",
  ui_story_1012_10120502_63_dialog_content = "Hah! Forsakin bilang aku keras kepala padahal kepalanya sendiri seperti kerbau!",
  ui_story_1012_10120502_64_dialog_content = "Membaliklah, kau sudah menabrak dinding!",
  ui_story_1012_10120502_65_dialog_content = "Mereka akan segera membuka pintu itu kalau seperti ini terus.",
  ui_story_1012_10120502_66_dialog_content = "PlayerName, cepatlah dan aktifkan Chord Link untuk menyembuhkan Vice.",
  ui_story_1012_10120502_67_dialog_content = "Kalau Vice bangkit, kita bisa keluar dari sini bersama-sama. Mungkin masih ada harapan!",
  ui_story_1012_10120502_68_dialog_content = "Neural Aux, bantu aku mengaktifkan Chord Link!",
  ui_story_1012_10120502_69_dialog_content = "Aktifkan Chord Link!",
  ui_story_1012_10120502_70_dialog_content = "Cari catatan eksperimen untuk mengonfirmasi efek dan efek samping Chord Link!",
  ui_story_1012_10120502_71_dialog_content = "Mencari... Gagal!",
  ui_story_1012_10120502_72_dialog_content = "Aku tidak bisa mengambil catatan eksperimen!",
  ui_story_1012_10120502_73_dialog_content = "Apa?!",
  ui_story_1012_10120502_74_dialog_content = "Bukannya kau bilang semua catatan eksperimen tersimpan di sini?",
  ui_story_1012_10120502_75_dialog_content = "Kenapa tidak bisa diambil?!",
  ui_story_1012_10120502_76_dialog_content = "Koneksiku dengan Chord Zone sudah lama terputus, jadi tidak banyak informasi tentang situasi Chord Zone.",
  ui_story_1012_10120502_77_dialog_content = "Aku mendeteksi catatan yang dihapus di arsip Chord Zone.",
  ui_story_1012_10120502_78_dialog_content = "Datanya sudah lama hilang dan tidak bisa diakses lagi.",
  ui_story_1012_10120502_79_dialog_content = "Jadi...",
  ui_story_1012_10120502_80_dialog_content = "Jadi, kalian akan menggunakan mainan yang belum diuji terhadap Vice?",
  ui_story_1012_10120502_81_dialog_content = "Tidak, aku ingin mencari catatan eksperimen terlebih dulu, tapi semua sudah hilang sekarang.",
  ui_story_1012_10120502_82_dialog_content = "Barton, Carleen, tunggu sebentar.",
  ui_story_1012_10120502_83_dialog_content = "Aku akan memastikan efek Chord Link!",
  ui_story_1012_10120502_84_dialog_content = "Tunggu, kau bukan Aurorian. Hasilnya lebih tidak jelas kalau kau menggunakannya.",
  ui_story_1012_10120502_85_dialog_content = "Tapi aku tidak bisa membuat Vice mengambil risiko.",
  ui_story_1012_10120502_86_dialog_content = "Forsakin akan coba mendobrak masuk segera. Kalian berdua tentu bisa bertarung.",
  ui_story_1012_10120502_87_dialog_content = "Aku Caelestite yang bahkan tidak bisa menggunakan Luminatics. Aku lebih cocok untuk eksperimentasi!",
  ui_story_1012_10120502_88_dialog_content = "Tahan di sana!",
  ui_story_1012_10120502_89_dialog_content = "Jangan hentikan aku!",
  ui_story_1012_10120502_90_dialog_content = "Tenanglah!",
  ui_story_1012_10120502_91_dialog_content = "Kau tahu benda itu bisa digunakan untuk apa?",
  ui_story_1012_10120502_92_dialog_content = "Chord Link bisa memulihkan luka, mengubah sebagian badan, dan juga mengaktifkan potensi Aurorian.",
  ui_story_1012_10120502_93_dialog_content = "Bisa menyembuhkan, 'kan?",
  ui_story_1012_10120502_94_dialog_content = "Kalau begitu, aku akan maju!",
  ui_story_1012_10120502_95_dialog_content = "Tapi aku bahkan tidak tahu efek sampingnya, rasio keberhasilannya, atau apakah ada yang akan mati!",
  ui_story_1012_10120502_96_dialog_content = "Kalau begitu, memang sebaiknya aku orangnya!",
  ui_story_1012_10120502_97_dialog_content = "Heh, kau cari subjek pengujian?",
  ui_story_1012_10120502_98_dialog_content = "Aku sudah terluka, jadi aku cuma bisa menangkis paling banyak satu atau dua serangan kalau melawan Forsakin.",
  ui_story_1012_10120502_99_dialog_content = "Kalau terus di luar dan berkoordinasi dengan Carleen, kau akan bisa bertahan sedikit lebih lama.",
  ui_story_1012_10120502_100_dialog_content = "Jadi, biar aku saja.",
  ui_story_1012_10120502_101_dialog_content = "Kalau mesin itu bisa menyembuhkanku, aku akan memberi Forsakin kejutan.",
  ui_story_1012_10120502_102_dialog_content = "Dan kau bisa tenang dan menggunakannya untuk menyelamatkan Vice.",
  ui_story_1012_10120502_103_dialog_content = "… Oke.",
  ui_story_1012_10120502_104_dialog_content = "Kalau begitu, kalian berdua tangani ini.",
  ui_story_1012_10120502_105_dialog_content = "Kunci para Eclipsite di luar dan jangan sampai mereka masuk!",
  ui_story_1012_10120502_106_dialog_content = "<color=#e8d9bb>Dharr!!!</color>",
  ui_story_1012_10120502_107_dialog_content = "Graaaaaagh!",
  ui_story_1012_10120502_108_dialog_content = "Lebih kuat dari material yang digunakan di Undercity, tapi lebih ringan.",
  ui_story_1012_10120502_109_dialog_content = "Material bangunan dan pintu yang digunakan lebih mirip dengan Colossus Patch.",
  ui_story_1012_10120502_110_dialog_content = "Colossus dan Caelestite, dan bahkan Eclipsite...",
  ui_story_1012_10120502_111_dialog_content = "Mungkin bahkan Eclipse tidak tahu rahasia ini.",
  ui_story_1012_10120502_112_dialog_content = "Membuatku berharap.",
  ui_story_1012_10120502_113_dialog_content = "(Bahasa Eclipsian) Forsakin, Lord Figerald memintaku mengirimkan pesan untukmu.",
  ui_story_1012_10120502_114_dialog_content = "(Bahasa Eclipsian) Pasukan telah selesai berkumpul di luar menara.",
  ui_story_1012_10120502_115_dialog_content = "(Bahasa Eclipsian) Tapi perubahan White Tower menarik perhatian Illumina, Lumopolis, dan Northland.",
  ui_story_1012_10120502_116_dialog_content = "(Bahasa Eclipsian) Bala bantuan telah menanggapi dari segala sisi.",
  ui_story_1012_10120502_117_dialog_content = "(Bahasa Eclipsian) Di antara mereka adalah Reinhardt dan Bethlehem.",
  ui_story_1012_10120502_118_dialog_content = "Mereka biasanya penakut, tapi sekarang keluar dari sarang.",
  ui_story_1012_10120502_119_dialog_content = "Mereka jelas punya telinga sensitif.",
  ui_story_1012_10120502_120_dialog_content = "Katakan kepada Figerald. Hentikan mereka.",
  ui_story_1012_10120502_121_dialog_content = "Eksperimenku masih butuh waktu.",
  ui_story_1012_10120502_122_dialog_content = "(Bahasa Eclipsian) Lord Figerald memintaku mengingatkan.",
  ui_story_1012_10120502_123_dialog_content = "(Bahasa Eclipsian) Jangan lakukan apa pun yang tidak perlu.",
  ui_story_1012_10120502_124_dialog_content = "Kalau benar-benar mau membantu, dia seharusnya tidak terus menggangguku.",
  ui_story_1012_10120502_125_dialog_content = "...",
  ui_story_1012_10120502_126_dialog_content = "(Bahasa Eclipsian) Itulah yang dikatakan Forsakin...",
  ui_story_1012_10120502_127_dialog_content = "(Bahasa Eclipsian) Forsakin sepertinya perlu sedikit diingatkan.",
  ui_story_1012_10120502_128_dialog_content = "(Bahasa Eclipsian) Belum waktunya.",
  ui_story_1012_10120502_129_dialog_content = "(Bahasa Eclipsian) Illumina, Lumopolis, dan bahkan Northland telah bergerak.",
  ui_story_1012_10120502_130_dialog_content = "(Bahasa Eclipsian) Lord Figerald, mau hentikan mereka?",
  ui_story_1012_10120502_131_dialog_content = "(Bahasa Eclipsian) Silakan kalau kau mau bersenang-senang.",
  ui_story_1012_10120502_132_dialog_content = "(Bahasa Eclipsian) Tapi tidak perlu bertarung sampai mati. Tidak apa-apa menyisakan satu atau dua nyawa.",
  ui_story_1012_10120502_133_dialog_content = "(Bahasa Eclipsian) Tekan Forsakin untuk memaksanya menunjukkan kemampuan.",
  ui_story_1012_10120502_134_dialog_content = "(Bahasa Eclipsian) Baik, Lord Figerald.",
  ui_story_1012_10120601_1_dialog_content = "<color=#e8d9bb>Peringatan Sistem: Chord Link sekarang aktif... Jangan mengganggu proses Synchronization...</color>",
  ui_story_1012_10120601_2_dialog_content = "<color=#e8d9bb>Duk... Duk... Duk... Duk...</color>",
  ui_story_1012_10120601_3_dialog_content = "Suara apa itu…?",
  ui_story_1012_10120601_4_dialog_content = "Sepertinya datang dari segala arah. Betul-betul suara yang membuat tidak nyaman.",
  ui_story_1012_10120601_5_dialog_content = "Bukan membuat tidak nyaman, tapi lebih ke membuat takut.",
  ui_story_1012_10120601_6_dialog_content = "Ini seperti suara...",
  ui_story_1012_10120601_7_option_content = "Suara Gempa Bumi.",
  ui_story_1012_10120601_8_dialog_content = "Intensitas getaran bahkan tidak sekuat saat Obelisk of Return muncul.",
  ui_story_1012_10120601_9_dialog_content = "Semua dinding Central Core dibuat bergetar...",
  ui_story_1012_10120601_10_dialog_content = "Seolah-olah tempat ini akan longsor.",
  ui_story_1012_10120601_11_option_content = "Suara Detak Jantung.",
  ui_story_1012_10120601_12_dialog_content = "Suaranya seperti irama yang stabil.",
  ui_story_1012_10120601_13_dialog_content = "Aku bisa merasakan energi yang sangat buruk dengan irama ini.",
  ui_story_1012_10120601_14_dialog_content = "Seperti bilik jantung seorang raksasa.",
  ui_story_1012_10120601_15_dialog_content = "Inikah kekuatan Chord Link...?",
  ui_story_1012_10120601_16_dialog_content = "Begitu rupanya... Suara yang sangat mencemaskan.",
  ui_story_1012_10120601_17_dialog_content = "Kita tidak tahu berapa lama ini akan berlangsung.",
  ui_story_1012_10120601_18_dialog_content = "Barton, dia...",
  ui_story_1012_10120601_19_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_1012_10120601_20_dialog_content = "?!",
  ui_story_1012_10120601_21_dialog_content = "Suara ini jelas tidak disebabkan Chord Link, 'kan?",
  ui_story_1012_10120601_22_dialog_content = "Peringatan: Penyusup ilegal terdeteksi 30 meter ke depan.",
  ui_story_1012_10120601_23_dialog_content = "Dia masih datang. Neural Aux, ubah strukturnya, dan tutup pintu di sini!",
  ui_story_1012_10120601_24_dialog_content = "Diterima... Gagal! Gagal!",
  ui_story_1012_10120601_25_dialog_content = "Organisme hidup terdeteksi di jalan masuk Chord Zone. Tidak bisa menutup.",
  ui_story_1012_10120601_26_dialog_content = "Kita tidak punya pilihan lain. Bersiaplah, PlayerName!",
  ui_story_1012_10120601_27_dialog_content = "Hm... Synchronization belum selesai. Kita harus melindungi Barton!",
  ui_story_1012_10120601_28_dialog_content = "(... Apa pun hasil Synchronization-nya)",
  ui_story_1012_10120601_29_dialog_content = "Peringatan: Penyusup ilegal terdeteksi 9 meter di depan.",
  ui_story_1012_10120601_30_dialog_content = "Ulangi! Penyusup ilegal terdeteksi 9 meter di depan.",
  ui_story_1012_10120601_31_dialog_content = "Ulangi! Penyusup ilegal terdeteksi 9 meter di depan...",
  ui_story_1012_10120601_32_dialog_content = "Ia berhenti?",
  ui_story_1012_10120601_33_dialog_content = "S-sungguh...?",
  ui_story_1012_10120601_34_dialog_content = "<color=#e8d9bb><size=45>DUAR!!!</size></color>",
  ui_story_1012_10120601_35_dialog_content = "Penyusup ilegal?",
  ui_story_1012_10120601_36_dialog_content = "Aku cuma melakukan hal yang sama dengan kalian.",
  ui_story_1012_10120601_37_dialog_content = "Bedanya hanyalah siapa yang datang lebih dulu dan siapa yang berikutnya.",
  ui_story_1012_10120601_38_dialog_content = "...Hah?",
  ui_story_1012_10120601_39_dialog_content = "Jadi, masih ada perangkat pengganggu seperti itu yang tersembunyi di lantai terdalam di permakaman ini.",
  ui_story_1012_10120601_40_dialog_content = "Kalian masih satu langkah di depanku dalam urusan \"habisi Barton\" ini.",
  ui_story_1012_10120601_41_dialog_content = "Jangan asal bicara!",
  ui_story_1012_10120601_42_dialog_content = "PlayerName, tak usah buang-buang waktu dengannya!",
  ui_story_1012_10120601_43_dialog_content = "Dia tidak boleh masuk lebih dalam lagi. Vice masih ada di sana!",
  ui_story_1012_10120601_44_dialog_content = "Banyak hal di dunia tidak terjadi sesuai keinginanmu.",
  ui_story_1012_10120601_45_dialog_content = "PlayerName, sebagai Caelestite, dan setelah lama meninggalkan Colossus, aku heran kau masih perlu kuberi tahu tentang kebenaran ini.",
  ui_story_1012_10120601_46_dialog_content = "Tidak perlu kujelaskan nasib Caelestite terakhir yang berani melawanku.",
  ui_story_1012_10120601_47_dialog_content = "Kau…!",
  ui_story_1012_10120601_48_dialog_content = "(Bahasa Eclipsian) Serang.",
  ui_story_1012_10120601_49_dialog_content = "(Bahasa Eclipsian) Baik!",
  ui_story_1012_10120702_1_dialog_content = "Gaaah!",
  ui_story_1012_10120702_2_dialog_content = "Ha.",
  ui_story_1012_10120702_3_dialog_content = "Ahh...",
  ui_story_1012_10120702_4_dialog_content = "Di belakangmu! Carleen!",
  ui_story_1012_10120702_5_dialog_content = "Apa...?!",
  ui_story_1012_10120702_6_dialog_content = "Aaaaaah!!!",
  ui_story_1012_10120702_7_dialog_content = "Ugh...",
  ui_story_1012_10120702_8_dialog_content = "(Ini tidak akan berhasil... Forsakin membawa terlalu banyak Eclipsite.)",
  ui_story_1012_10120702_9_dialog_content = "(Mungkin tembakan lebih efisien dibanding terhubung dengan kesadaran Carleen!)",
  ui_story_1012_10120702_10_dialog_content = "Hah?!",
  ui_story_1012_10120702_11_dialog_content = "Aku baru tahu. Sejak kapan kau belajar menggunakan senjata, PlayerName?",
  ui_story_1012_10120702_12_dialog_content = "Hmm... Itu memang tampaknya senapan Caelestite. Bisa dianggap benda kuno.",
  ui_story_1012_10120702_13_dialog_content = "Ini barang bagus.",
  ui_story_1012_10120702_14_dialog_content = "Biar kuambil. Terima kasih, PlayerName.",
  ui_story_1012_10120702_15_dialog_content = "Sial! Kembalikan!",
  ui_story_1012_10120702_16_dialog_content = "Aaaaaah!!!",
  ui_story_1012_10120702_17_dialog_content = "Hentikan mereka, PlayerName! Mereka tidak boleh terus datang!",
  ui_story_1012_10120702_18_dialog_content = "Proses Synchronization tidak mungkin gagal gara-gara ini!",
  ui_story_1012_10120702_19_dialog_content = "Ice Blossom! Menyebar!",
  ui_story_1012_10120702_20_dialog_content = "<size=45>Aaaaaah!</size>",
  ui_story_1012_10120702_21_dialog_content = "C-Carleen!",
  ui_story_1012_10120702_22_option_content = "Forced Control!",
  ui_story_1012_10120702_23_dialog_content = "Carleen... Tolong... Tolong jawab!",
  ui_story_1012_10120702_24_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1012_10120702_25_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1012_10120702_26_dialog_content = "(Bahasa Eclipsian) Bunuh Barton dan Vice. Jangan rusak perangkatnya.",
  ui_story_1012_10120702_27_dialog_content = "(Bahasa Eclipsian) Siap, laksanakan.",
  ui_story_1012_10120702_28_dialog_content = "<size=50><anim type=Shake>Hah—</anim></size>",
  ui_story_1012_10120702_29_dialog_content = "(Kenapa... Kenapa ini terjadi...?)",
  ui_story_1012_10120702_30_dialog_content = "(Perasaan tak berdaya ini... Aku merasakannya lagi...)",
  ui_story_1012_10120702_31_dialog_content = "(Kalau aku punya kekuatan seperti Luminatics, keadaan pasti berbeda mulai sekarang.)",
  ui_story_1012_10120702_32_dialog_content = "(Vice, Carleen, dan...)",
  ui_story_1012_10120702_33_dialog_content = "(Mereka…)",
  ui_story_1012_10120702_34_dialog_content = "Tolong! Ada yang bisa menyelamatkanku?!",
  ui_story_1012_10120702_35_dialog_content = "Jangan mendekatinya. Aku akan melawan kalian!",
  ui_story_1012_10120702_36_dialog_content = "Uh... Waaah... Waaah...",
  ui_story_1012_10120702_37_dialog_content = "Api pertempuran, Eclipsite... Jadi ini sambutan untukku saat aku membuka mata?",
  ui_story_1012_10120702_38_dialog_content = "(Apa?!)",
  ui_story_1012_10120702_39_dialog_content = "Apa tidak ada yang lebih bagus?!",
  ui_story_1012_10120702_40_dialog_content = "Aku hampir tidak tahan. Kekuatan ini seperti meluap-luap!",
  ui_story_1012_10120702_41_dialog_content = "Pertempuran pada saat yang tepat adalah latihan yang harus kita manfaatkan.",
  ui_story_1012_10120702_42_dialog_content = "Barton! Kau... Kau berhasil!",
  ui_story_1012_10120702_43_dialog_content = "Oh, PlayerName... Kau kenapa, Bocah?",
  ui_story_1012_10120702_44_dialog_content = "Usap air mata dari wajahmu. Jangan seperti anak kecil!",
  ui_story_1012_10120702_45_dialog_content = "Tunjukkan semangat tempurmu!",
  ui_story_1012_10120702_46_dialog_content = "T-Tentu saja!",
  ui_story_1012_10120702_47_dialog_content = "Ayo, akan kutunjukkan medan tempur yang sebenarnya.",
  ui_story_1012_10120702_48_dialog_content = "Menara ini milikmu. Jangan sampai jatuh ke tangan orang-orang Eclipse!",
  ui_story_1012_10120702_49_dialog_content = "(Bahasa Eclipsian) Mengejutkan sekali. Teknologi kuno Caelestite ternyata sangat maju.",
  ui_story_1012_10120702_50_dialog_content = "(Bahasa Eclipsian) Aku senang sekali... Mengejarnya ke sini adalah keputusan tepat.",
  ui_story_1012_10120702_51_dialog_content = "(Bahasa Eclipsian) Kau sungguh bijak, Forsakin.",
  ui_story_1012_10120702_52_dialog_content = "(Bahasa Eclipsian) Apa yang kau lakukan? Tangkap dia, tapi jangan bunuh! Aku butuh dia hidup-hidup.",
  ui_story_1012_10120702_53_dialog_content = "(Bahasa Eclipsian) Baik—",
  ui_story_1012_10120702_54_dialog_content = "<color=#e8d9bb><size=45>Duar!</size></color>",
  ui_story_1012_10120702_55_dialog_content = "Lama tak jumpa, Forsakin.",
  ui_story_1012_10120702_56_dialog_content = "Kukira kau punya kru yang lebih kuat sekarang.",
  ui_story_1012_10120702_57_dialog_content = "Celaka...",
  ui_story_1012_10120702_58_dialog_content = "(Bahasa Eclipsian) Semua! Serang!",
  ui_story_1012_10120702_59_dialog_content = "Aaaaaah!!!",
  ui_story_1012_10120702_60_dialog_content = "Panther's Prowl!",
  ui_story_1012_10120702_61_dialog_content = "PlayerName? Barton?!",
  ui_story_1012_10120702_62_dialog_content = "Tapi itu berarti... Chord Link berhasil!",
  ui_story_1012_10120702_63_dialog_content = "Hahaha! Betul!",
  ui_story_1012_10120702_64_dialog_content = "Cepatlah, selamatkan Vice. Timmu akan butuh dia, 'kan?",
  ui_story_1012_10120702_65_dialog_content = "Untuk yang di sini... aku bisa bereskan.",
  ui_story_1012_10120702_66_dialog_content = "...",
  ui_story_1012_10120702_67_dialog_content = "(Bahasa Eclipsian) Mundur dan bergabung kembali dengan pasukan Eclipse utama!",
  ui_story_1012_10120702_68_dialog_content = "(Bahasa Eclipsian) Siap... laksanakan.",
  ui_story_1012_10120702_69_dialog_content = "Jangan bergerak, berengsek!",
  ui_story_1012_10120702_70_dialog_content = "Sekelompok orang bodoh yang tak tahu malu!",
  ui_story_1012_10120702_71_dialog_content = "Kau baik-baik saja, Carleen? Hampir saja celaka, kau tidak apa-apa...?",
  ui_story_1012_10120702_72_dialog_content = "Tidak apa-apa. Kita tidak boleh buang-buang waktu, PlayerName...",
  ui_story_1012_10120702_73_dialog_content = "Kita harus selamatkan Vice, sekarang!",
  ui_story_1012_10120702_74_dialog_content = "Kau tidak salah. Kita selesaikan proses Synchronization.",
  ui_story_1012_10120702_75_dialog_content = "(Jadi... Kumohon berfungsilah, Chord Link.)",
  ui_story_1012_10120702_76_dialog_content = "(Kuharap kau bangun lagi, Vice...)",
  ui_story_1012_10120702_77_dialog_content = "<color=#e8d9bb>Peringatan Sistem: Chord Link sekarang beroperasi...</color>",
  ui_story_1012_10120801_1_dialog_content = "<color=#e8d9bb>Peringatan Sistem: Chord Link sekarang aktif... Jangan mengganggu proses Synchronization...</color>",
  ui_story_1012_10120801_2_dialog_content = "...",
  ui_story_1012_10120801_3_dialog_content = "...",
  ui_story_1012_10120801_4_dialog_content = "Sebelumnya ia selalu berfungsi normal! Ada apa?",
  ui_story_1012_10120801_5_dialog_content = "Tenanglah, PlayerName. Beri Vice waktu.",
  ui_story_1012_10120801_6_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1012_10120801_7_dialog_content = "Bagaimanapun, sepertinya Synchronization sudah berjalan terlalu lama?!",
  ui_story_1012_10120801_8_dialog_content = "Kalau kupikir-pikir, aku tidak perlu menunggu terlalu lama sampai Barton bangun.",
  ui_story_1012_10120801_9_dialog_content = "Kita harus bagaimana, PlayerName?",
  ui_story_1012_10120801_10_dialog_content = "(Carleen…)",
  ui_story_1012_10120801_11_dialog_content = "(Sebaiknya, aku berpikir dengan tenang.)",
  ui_story_1012_10120801_12_dialog_content = "Kita mengikuti petunjuk Chord Link sampai menemukan surat itu, 'kan? Kutaruh surat itu di bawah badan Vice.",
  ui_story_1012_10120801_13_dialog_content = "Semuanya sama dengan yang dilalui Barton.",
  ui_story_1012_10120801_14_dialog_content = "Kita tidak dapat peringatan malafungsi dari Chord Link maupun Neural Aux.",
  ui_story_1012_10120801_15_dialog_content = "Itulah yang membuatku berpikir bahwa mungkin masalahnya adalah...",
  ui_story_1012_10120801_16_option_content = "Hibernasi Vice.",
  ui_story_1012_10120801_17_dialog_content = "Begitu rupanya. Kurasa itu satu-satunya penjelasan.",
  ui_story_1012_10120801_18_dialog_content = "Bukannya General Illumina juga terluka, tapi tidak sampai pingsan?",
  ui_story_1012_10120801_19_dialog_content = "Jadi, walau terluka parah, dia bangun dengan badan yang bertambah kuat.",
  ui_story_1012_10120801_20_option_content = "Kehancuran Forsakin.",
  ui_story_1012_10120801_21_dialog_content = "Benarkah? Forsakin melakukan apa?",
  ui_story_1012_10120801_22_dialog_content = "Tapi... saat ini pasukan Eclipsite Forsakin bahkan tidak berada di dekat Chord Link.",
  ui_story_1012_10120801_23_dialog_content = "Dan mereka sudah dihajar oleh General Illumina.",
  ui_story_1012_10120801_24_dialog_content = "Ini membuatku berpikir bahwa... Masalahnya pasti terkait dengan Hibernasi.",
  ui_story_1012_10120801_25_dialog_content = "Pasti begitu. Coba ingat data yang tadi kita lihat di Circular System...",
  ui_story_1012_10120801_26_dialog_content = "Subjek... Gagal bangun dari Hibernasi... Fisik... Tanda kehidupan melemah.",
  ui_story_1012_10120801_27_dialog_content = "Subjek... Gagal bangun dari Hibernasi... Ditunjukkan... Tanda kehidupan...",
  ui_story_1012_10120801_28_dialog_content = "Subjek... Gagal bangun... Dalam eksperimen...",
  ui_story_1012_10120801_29_dialog_content = "Semua Caelestite yang akhirnya menjadi subjek pengujian memiliki suatu kesamaan—",
  ui_story_1012_10120801_30_dialog_content = "Hibernasi.",
  ui_story_1012_10120801_31_dialog_content = "Tapi kenapa? Bagaimana bisa?",
  ui_story_1012_10120801_32_dialog_content = "(Mungkinkah ini nasib mereka semua? Tidak bangun dari Hibernasi?)",
  ui_story_1012_10120801_33_dialog_content = "(Kalau ini benar, maka... Vice!)",
  ui_story_1012_10120801_34_dialog_content = "PlayerName…",
  ui_story_1012_10120801_35_dialog_content = "PlayerName?",
  ui_story_1012_10120801_36_dialog_content = "Re-Reinhardt?!",
  ui_story_1012_10120801_37_dialog_content = "Paling tidak sinyalmu tampak cukup jelas.",
  ui_story_1012_10120801_38_dialog_content = "Bagaimana situasi di sana? Apa kau sadar akan keributan yang terjadi karenamu?",
  ui_story_1012_10120801_39_dialog_content = "M-maaf…",
  ui_story_1012_10120801_40_dialog_content = "Hahahaha! Aku tidak menyalahkanmu.",
  ui_story_1012_10120801_41_dialog_content = "Aku cuma ingin mengingatkanmu, di tengah semua kekacauan di Eraveil akhir-akhir ini, Illumina bukan satu-satunya pihak yang menyimak.",
  ui_story_1012_10120801_42_dialog_content = "Pastikan semua inisiatif tidak berhenti...",
  ui_story_1012_10120801_43_dialog_content = "Bagaimanapun, kau satu-satunya yang bisa membawa perubahan ke Eraveil.",
  ui_story_1012_10120801_44_dialog_content = "Sekarang, aku pergi dulu.",
  ui_story_1012_10120801_45_dialog_content = "Ya, Reinhardt.",
  ui_story_1012_10120801_46_dialog_content = "Dia tidak salah.",
  ui_story_1012_10120801_47_dialog_content = "Saat ini, kita sama sekali tidak tahu situasi di luar menara. Ini buruk bagi kita.",
  ui_story_1012_10120801_48_dialog_content = "Jadi, bagaimana cara mencari tahu situasinya?",
  ui_story_1012_10120801_49_dialog_content = "Barton mungkin masih berusaha menangani Forsakin. Aku tidak ingin mengganggunya atau membuat masalah.",
  ui_story_1012_10120801_50_dialog_content = "Diterima... Menganalisis pertanyaan...",
  ui_story_1012_10120801_51_dialog_content = "Hah?!",
  ui_story_1012_10120801_52_dialog_content = "Ada solusi untuk masalah ini, Neural Aux?",
  ui_story_1012_10120801_53_dialog_content = "Mengaktifkan monitor eksternal menara.",
  ui_story_1012_10120801_54_dialog_content = "Heh, heh...",
  ui_story_1012_10120801_55_dialog_content = "Berhentilah berlari, Forsakin!",
  ui_story_1012_10120801_56_dialog_content = "Hadapi aku seperti prajurit sejati!",
  ui_story_1012_10120801_57_dialog_content = "Hah?",
  ui_story_1012_10120801_58_dialog_content = "Apa...?",
  ui_story_1012_10120801_59_dialog_content = "Aku tidak pernah... Aku sudah lama sekali tidak melihat hal seperti ini!",
  ui_story_1012_10120801_60_dialog_content = "(Lihat semua bala bantuan yang dikerahkan!)",
  ui_story_1012_10120801_61_dialog_content = "(Ini... mulai sangat mirip dengan Darkover Crisis sekitar sepuluh tahun lalu.)",
  ui_story_1012_10120801_62_dialog_content = "(Berapa lama aku bisa... menahan mereka untuk PlayerName dan orang-orang itu?)",
  ui_story_1012_10120801_63_dialog_content = "Oh?",
  ui_story_1012_10120801_64_dialog_content = "Sepertinya kau mengalami masalah sepele, Forsakin.",
  ui_story_1012_10120801_65_dialog_content = "Mungkin lain kali jangan terlalu keras kepala, hmm?",
  ui_story_1012_10120801_66_dialog_content = "Masalah seperti itu pasti membuat semua usahamu sia-sia.",
  ui_story_1012_10120801_67_dialog_content = "Menurutku, kau akan menganggap ini cukup memuaskan.",
  ui_story_1012_10120801_68_dialog_content = "Lagi pula, itu bukan urusanmu.",
  ui_story_1012_10120801_69_dialog_content = "Jangan coba jadi pahlawan padahal tak melakukan apa-apa.",
  ui_story_1012_10120801_70_dialog_content = "Cih. Sudahlah.",
  ui_story_1012_10120801_71_dialog_content = "Malang sekali. Kau meminta bantuan karena tak bisa mengalahkan mereka, Forsakin?",
  ui_story_1012_10120801_72_dialog_content = "(Itu dia! Ada celah di pertahanannya!)",
  ui_story_1012_10120801_73_dialog_content = "Leopard Strike!",
  ui_story_1012_10120801_74_dialog_content = "Aduh...",
  ui_story_1012_10120801_75_dialog_content = "Eclipse belum berkumpul untukmu, tahu.",
  ui_story_1012_10120801_76_dialog_content = "Menyerahlah, berhenti melawan.",
  ui_story_1012_10120801_77_dialog_content = "Kau sudah mengulur waktu untuk Caelestite itu sejak datang ke White Tower.",
  ui_story_1012_10120801_78_dialog_content = "Aku benar, 'kan?",
  ui_story_1012_10120801_79_dialog_content = "...",
  ui_story_1012_10120801_80_dialog_content = "(Bahasa Eclipsian) Tangkap dia.",
  ui_story_1012_10120801_81_dialog_content = "Aahhhhhh!!!",
  ui_story_1012_10120801_82_dialog_content = "<color=#e8d9bb>Duar! Duar!</color>",
  ui_story_1012_10120801_83_dialog_content = "Itu…",
  ui_story_1012_10120801_84_dialog_content = "Menara ini bahkan lebih menakjubkan dari dekat.",
  ui_story_1012_10120801_85_dialog_content = "Semuanya seperti yang diramalkan mimpiku...",
  ui_story_1012_10120801_86_dialog_content = "Entah ke mana arah yang dituju dunia ini, kehancuran atau kelahiran kembali, konfrontasi antara Eraveil dan Eclipsite tak terhindarkan.",
  ui_story_1012_10120801_87_dialog_content = "(Pemimpin Northland?)",
  ui_story_1012_10120801_88_dialog_content = "(Dia baru saja membantuku?)",
  ui_story_1012_10120801_89_dialog_content = "Commander Barton, aku yakin kau mengetahui Statuta 42 Illumina Military Regulations yang membahas tentang pembangkangan.",
  ui_story_1012_10120801_90_dialog_content = "Hah?!",
  ui_story_1012_10120801_91_dialog_content = "Illumina selalu mencari keadilan, sesuai dengan aturan yang ada. Pelanggar berat terutama akan diadili di pengadilan militer.",
  ui_story_1012_10120801_92_dialog_content = "—Tapi, tentu saja, ini harus ditunda sampai perang berakhir.",
  ui_story_1012_10120801_93_dialog_content = "Grand Marshal?",
  ui_story_1012_10120801_94_dialog_content = "Batalion bala bantuan garda depan hampir tiba, jadi berkumpullah bersama mereka.",
  ui_story_1012_10120801_95_dialog_content = "Oh? Ini... Apa kau menghadiri semacam pelatihan khusus darurat? Kau terlihat sedikit berbeda...",
  ui_story_1012_10120801_96_dialog_content = "Apa pun itu, bertarunglah sekuat tenaga untuk pertempuran ini, Commander Barton!",
  ui_story_1012_10120801_97_dialog_content = "Kita lihat apakah kau bisa menebus kesalahanmu di medan perang!",
  ui_story_1012_10120801_98_dialog_content = "...",
  ui_story_1012_10120801_99_dialog_content = "Dimengerti!",
  ui_story_1012_10120801_100_dialog_content = "Tunggu dan lihat saja, Grand Marshal.",
  ui_story_1012_10120801_101_dialog_content = "Pemantauan eksternal selesai.",
  ui_story_1012_10120801_102_dialog_content = "Yang Mulia... dan Reinhardt.",
  ui_story_1012_10120801_103_dialog_content = "Sepertinya Northland dan Illumina sudah menyiapkan pasukan mereka.",
  ui_story_1012_10120801_104_dialog_content = "Tapi, meskipun pasukan mereka sebanyak itu, apakah itu cukup untuk melawan Eclipse?",
  ui_story_1012_10120801_105_dialog_content = "Kita harus mencari solusinya, PlayerName!",
  ui_story_1012_10120801_106_dialog_content = "Aku tahu! Menurutku, upaya terbaik kita adalah memanfaatkan Obelisk of Return, mengingat posisinya yang berada di pusat.",
  ui_story_1012_10120801_107_dialog_content = "Neural Aux, seberapa bagus pertahanan menara ini?",
  ui_story_1012_10120801_108_dialog_content = "Diterima... Menganalisis pertanyaan...",
  ui_story_1012_10120801_109_dialog_content = "Di dalam Obelisk of Return terdapat sistem pertahanan utama:<color=#FFB400>Chord of the Law</color>.",
  ui_story_1012_10120801_110_dialog_content = "Ini adalah aset Eraveil yang paling kuat dan paling unik. Juga baris pertahanan terakhir.",
  ui_story_1012_10120801_111_dialog_content = "Jadi...",
  ui_story_1012_10120801_112_dialog_content = "Chord of the Law sulit untuk diaktifkan dan mahal untuk digunakan.",
  ui_story_1012_10120801_113_dialog_content = "Aku tidak bisa mengizinkan Caelestite mana pun untuk mengaktifkan Chord of the Law.",
  ui_story_1012_10120801_114_dialog_content = "Izin? Kenapa selalu ada masalah dengan izin?!",
  ui_story_1012_10120801_115_dialog_content = "Mengulangi: Chord of the Law sulit untuk diaktifkan dan mahal untuk digunakan.",
  ui_story_1012_10120801_116_dialog_content = "Aku tidak bisa mengizinkan Caelestite mana pun.",
  ui_story_1012_10120801_117_dialog_content = "Tak ada gunanya berdebat dengan mesin, PlayerName.",
  ui_story_1012_10120801_118_dialog_content = "Kita punya kehendak bebas dan jangan sampai dihalangi oleh mesin biasa!",
  ui_story_1012_10120801_119_dialog_content = "(Carleen benar. Lagi pula, aku tak mau mengalami itu lagi.)",
  ui_story_1012_10120801_120_dialog_content = "(Ketidakberdayaan di hadapan Eclipsite, saat Caelestite tak bisa melakukan apa pun.)",
  ui_story_1012_10120801_121_dialog_content = "Aku tak akan membiarkan ini terjadi! Akan kuhadapi Eclipse kali ini!",
  ui_story_1012_10120801_122_dialog_content = "Aku paham, PlayerName. Tapi...",
  ui_story_1012_10120801_123_dialog_content = "Vice…",
  ui_story_1012_10120801_124_dialog_content = "Karena Synchronization masih belum selesai, Vice harus terus bertahan menjalani proses ini.",
  ui_story_1012_10120801_125_dialog_content = "PlayerName, begitu kita meninggalkan Chord Zone, beri tahu Neural Aux untuk mengubah struktur pintu masuknya.",
  ui_story_1012_10120801_126_dialog_content = "Pastikan untuk menutup pintu masuk ke Chord Zone, dan mengubah struktur jalan rahasianya.",
  ui_story_1012_10120801_127_dialog_content = "Ayo kita buat <color=#FFB400>Cocoon</color> yang cukup kuat untuk Vice.",
  ui_story_1012_10120801_128_dialog_content = "Tentu saja!",
  ui_story_1012_10120801_129_dialog_content = "(Tolong, Vice, Chord Link HARUS membangunkanmu...)",
  ui_story_1012_10120801_130_dialog_content = "(Kami semua menunggu kelahiranmu kembali.)",
  ui_story_1012_10120801_131_dialog_content = "Sampai jumpa lagi, Vice.",
  ui_story_1012_10120901_1_dialog_content = "<color=#e8d9bb>Lorong Masuk, Menara Utama</color>",
  ui_story_1012_10120901_2_dialog_content = "<color=#e8d9bb>Tik-tik-tik... tik-tik-tik...</color>",
  ui_story_1012_10120901_3_dialog_content = "Pintu tempat kita masuk tadi agak jauh di depan.",
  ui_story_1012_10120901_4_dialog_content = "Aku tak bermaksud memberi ceramah, PlayerName, tapi...",
  ui_story_1012_10120901_5_dialog_content = "Jangan takut.",
  ui_story_1012_10120901_6_dialog_content = "C-Carleen?",
  ui_story_1012_10120901_7_dialog_content = "Jangan pernah lupa: kau berjuang untuk negerimu, rumahmu.",
  ui_story_1012_10120901_8_dialog_content = "Ini suatu kehormatan, dan jangan pernah takut karenanya.",
  ui_story_1012_10120901_9_dialog_content = "Yang Mulia Ratu... mengajariku tentang ini.",
  ui_story_1012_10120901_10_dialog_content = "Terima kasih, Carleen.",
  ui_story_1012_10120901_11_dialog_content = "Aku siap menghadapi apa pun yang akan datang.",
  ui_story_1012_10120901_12_dialog_content = "Baiklah. Mari kita menjelajah kembali ke dunia di luar menara, bersama-sama!",
  ui_story_1012_10120901_13_dialog_content = "I-Ini...",
  ui_story_1012_10120901_14_dialog_content = "<color=#e8d9bb>Kkkkkrak... Kkkkkrak...</color>",
  ui_story_1012_10120901_15_dialog_content = "<anim type=Shake><size=50>Ahh!!</size></anim>",
  ui_story_1012_10120901_16_dialog_content = "Bukankah Eraveil terlihat seperti ini... dahulu...",
  ui_story_1012_10120901_17_dialog_content = "PlayerName, awas!",
  ui_story_1012_10120901_18_dialog_content = "Gaah...",
  ui_story_1012_10120901_19_dialog_content = "Ck, ck, ck...",
  ui_story_1012_10120901_20_dialog_content = "Punya intel yang lebih baik jauh lebih berguna ketimbang daya tembak saja.",
  ui_story_1012_10120901_21_dialog_content = "Lagi pula, situasi saat ini sudah cukup aman.",
  ui_story_1012_10120901_22_dialog_content = "Pasukanmu tidak sebanding dengan pasukan Eclipse.",
  ui_story_1012_10120901_23_dialog_content = "Oh, apa ini semacam tradisi Eclipse aneh, mengucapkan omong kosong sebelum bertempur?",
  ui_story_1012_10120901_24_dialog_content = "Bualan tak akan membuatmu lebih kuat.",
  ui_story_1012_10120901_24X1_dialog_content = "(... Sekarang, kalau kupikir-pikir, Queen Bethlehem seharusnya sudah sampai.)",
  ui_story_1012_10120901_24X2_dialog_content = "PlayerName, aku akan menuju sisi lain Obelisk of Return untuk menyelidiki dan menyusul Queen Bethlehem.",
  ui_story_1012_10120901_24X3_dialog_content = "Kau tunggu di sini saja bersama bala bantuan Illumina ini, oke?",
  ui_story_1012_10120901_24X4_dialog_content = "Baiklah, tapi jangan lupa untuk saling bertukar kabar.",
  ui_story_1012_10120901_24X5_dialog_content = "Hati-hati, Carleen.",
  ui_story_1012_10120901_25_dialog_content = "Info intel terbaru untuk Grand Marshal: Bala bantuan dari 2nd Legion sudah berkumpul dengan Commander Barton.",
  ui_story_1012_10120901_26_dialog_content = "Menunggu perintahmu.",
  ui_story_1012_10120901_27_dialog_content = "Bagus. Perintahkan mereka untuk memusatkan kekuatan utama di garis depan, dan menyerang dalam formasi rapat.",
  ui_story_1012_10120901_28_dialog_content = "Bagi pasukan yang tersisa menjadi dua tim, dan kepung pasukan Eclipse cadangan dari belakang.",
  ui_story_1012_10120901_29_dialog_content = "Paham!",
  ui_story_1012_10120901_30_dialog_content = "Lalu kenapa kau masih di sini?",
  ui_story_1012_10120901_31_dialog_content = "Grand Marshal, kau belum menugaskan misi pertempuran.",
  ui_story_1012_10120901_32_dialog_content = "Hahaha! Baiklah kalau begitu. Kau mundur, pertahankan menara itu, dan bersiaga.",
  ui_story_1012_10120901_33_dialog_content = "Mempertahankan... Tower?",
  ui_story_1012_10120901_34_dialog_content = "Kau lihat White Tower yang sangat besar itu, 'kan?",
  ui_story_1012_10120901_35_dialog_content = "Ya, tapi...",
  ui_story_1012_10120901_36_dialog_content = "Menara itu adalah tujuan utama misi kita di sini.",
  ui_story_1012_10120901_37_dialog_content = "Meskipun misi ini mungkin tidak menyuruhmu berada di garis depan, ini sangatlah penting.",
  ui_story_1012_10120901_38_dialog_content = "Akan kulanjutkan lagi nanti, dan aku masih perlu bantuanmu untuk menyampaikan info intel, jadi jangan khawatir.",
  ui_story_1012_10120901_39_dialog_content = "Siap, Kapten!",
  ui_story_1012_10120901_40_dialog_content = "Sementara PlayerName, tetap bersamaku untuk saat ini.",
  ui_story_1012_10120901_41_dialog_content = "Eh... Bukankah kalian kekurangan orang?",
  ui_story_1012_10120901_42_dialog_content = "Reinhardt... Vice, dia...",
  ui_story_1012_10120901_43_dialog_content = "Commander Barton sudah memberitahuku tentang Lieutenant Vice.",
  ui_story_1012_10120901_44_dialog_content = "Kau harus percaya pada apa yang ada di dalam menara ini. Ini adalah harta karun besar yang ditinggalkan para leluhur untukmu.",
  ui_story_1012_10120901_45_dialog_content = "Selain itu, di tengah perang yang tak terelakkan ini, kita harus tetap bersikap positif.",
  ui_story_1012_10120901_46_dialog_content = "Tegakkan kepala dan moralmu!",
  ui_story_1012_10120901_47_dialog_content = "Siap!",
  ui_story_1012_10120901_48_dialog_content = "Bagus sekali!",
  ui_story_1012_10120901_49_dialog_content = "<color=#e8d9bb>Sementara itu, di sisi lain Tower</color>",
  ui_story_1012_10120901_50_dialog_content = "<size=45>Yang Mulia!!!</size>",
  ui_story_1012_10120901_51_dialog_content = "Aku lalai dalam tugasku sebagai pengawal Yang Mulia Ratu!",
  ui_story_1012_10120901_52_dialog_content = "Aku meminta Yang Mulia tidak lagi menghadapi Eclipsite sendirian tanpa aku!",
  ui_story_1012_10120901_53_dialog_content = "Izinkan aku menjadi garda depanmu yang pemberani, Yang Mulia!",
  ui_story_1012_10120901_54_dialog_content = "Tiare, kau sudah berada di alam liar bersalju selama bertahun-tahun. Kau paham keahlianmu adalah di bidang pengamatan dan penyusupan.",
  ui_story_1012_10120901_55_dialog_content = "Kekuatanmu ternyata menjadi strategi Northland untuk mendukung Eraveil.",
  ui_story_1012_10120901_56_dialog_content = "Kita serahkan saja garis depan kepada para Aurorian yang gila pertempuran itu. Kita akan mengambil pendekatan yang lebih konservatif, dan berjaga di samping White Tower ini.",
  ui_story_1012_10120901_57_dialog_content = "Aku sudah memanggil semua pasukan Northland kembali ke lingkungan White Tower dan memberi status siaga kepada mereka.",
  ui_story_1012_10120901_58_dialog_content = "Kecuali garis depan kita tumbang, para Eclipsite tak akan bisa dengan mudah menembus sejauh ini.",
  ui_story_1012_10120901_59_dialog_content = "Ya, Yang Mulia!",
  ui_story_1012_10120901_60_dialog_content = "Satu hal lagi. Tak usah terlalu formal saat kita berada di medan perang.",
  ui_story_1012_10120901_61_dialog_content = "Panggil aku Bethlehem.",
  ui_story_1012_10120901_62_dialog_content = "Sekarang kemarilah, berlindung di balik perisai ini.",
  ui_story_1012_10120901_63_dialog_content = "Ba-baik! Ya, Yang Mulia!",
  ui_story_1012_10120901_64_dialog_content = "Yang Mulia?! Aku tak menyangka kau datang begitu cepat!",
  ui_story_1012_10120901_65_dialog_content = "Lama tak jumpa, Carleen.",
  ui_story_1012_10120901_66_dialog_content = "Tentu saja, sekarang bukan waktunya untuk mengenang masa lalu. Anggap saja keadaan saat ini sebagai ujian.",
  ui_story_1012_10120901_67_dialog_content = "Biar kulihat seberapa kuat kemampuanmu saat sendiri.",
  ui_story_1012_10120901_68_dialog_content = "Carleen tidak sendiri!",
  ui_story_1012_10120901_69_dialog_content = "Beretta?",
  ui_story_1012_10120901_70_dialog_content = "Bukankah kau... Kenapa kau tidak bersama dengan Raphael?",
  ui_story_1012_10120901_71_dialog_content = "Yang Mulia, aku membawa Lumo Knights pemberani untuk membantumu.",
  ui_story_1012_10120901_72_dialog_content = "Kami menunggu perintahmu, <color=#FFB400>Captain Carleen</color>!",
  ui_story_1012_10120901_73_dialog_content = "(Begitu rupanya. Apa ini ulah ayahku?)",
  ui_story_1012_10120901_74_dialog_content = "(Aku terkejut Ayah begitu cepat mengirim pasukan dan memperjelas posisinya.)",
  ui_story_1012_10120901_75_dialog_content = "Demi White Night, angkat senjata kalian tinggi-tinggi dan majulah bersamaku!",
  ui_story_1012_10120901_76_dialog_content = "Saat siang menembus malam, kegelapan tak akan pernah bisa bersembunyi!",
  ui_story_1012_10120901_77_dialog_content = "Demi White Night!",
  ui_story_1012_10120901_78_dialog_content = "<color=#e8d9bb>Eclipse Garrison di Eraveil</color>",
  ui_story_1012_10120901_79_dialog_content = "(Bahasa Eclipsian) Bahkan Lumopolis mengirim pasukan? Orang tua kolot itu terlalu berlebihan.",
  ui_story_1012_10120901_80_dialog_content = "(Bahasa Eclipsian) Lumopolis akan membayar harga atas perlawanan mereka terhadap Eclipse.",
  ui_story_1012_10120901_81_dialog_content = "(Bahasa Eclipsian) Tak hanya itu. Begitu Eraveil berhasil direbut, tak ada yang bisa menghentikan kita untuk menguasai seluruh benua!",
  ui_story_1012_10120901_82_dialog_content = "(Bahasa Eclipsian) Ck, ck, ck...",
  ui_story_1012_10120901_83_dialog_content = "(Bahasa Eclipsian) Kawan-kawan, waktu kita hampir tiba.",
  ui_story_1012_10120901_84_dialog_content = "(Bahasa Eclipsian) Kemenangan akan kita raih.",
  ui_story_1012_10120901_85_dialog_content = "(Bahasa Eclipsian) Eraveil sekali lagi akan dibanjiri oleh darah!",
  ui_story_1012_10120901_86_dialog_content = "(Bahasa Eclipsian) Ke Eraveil! Kuasai White Tower! Basmi semua yang menentang kita!",
  ui_story_1012_10120901_87_dialog_content = "<size=45>(Bahasa Eclipsian) MAJU!!</size>",
  ui_story_1012_10120901_88_dialog_content = "<anim type=Shake><size=45>Ahhhhhh!!!</size></anim>",
  ui_story_1012_10120901_89_dialog_content = "(Bahasa Eclipsian) Ini adalah hari terakhir matahari terbit di Astra.",
  ui_story_1012_10121002_1_dialog_content = "Perintahmu tegas seperti biasa, PlayerName.",
  ui_story_1012_10121002_2_dialog_content = "Bisa tetap tenang dalam keadaan seperti itu... Aku harus menyebutmu tenang, atau sederhana?",
  ui_story_1012_10121002_3_dialog_content = "Kurasa aku mulai paham bagaimana kau bisa mendapat kepercayaan dari begitu banyak orang.",
  ui_story_1012_10121002_4_dialog_content = "Agak berlebihan, ya.",
  ui_story_1012_10121002_5_dialog_content = "Ada info intel baru: Gelombang pertama serangan Eclipse berhasil dimentahkan!",
  ui_story_1012_10121002_6_dialog_content = "Meskipun situasinya tak menentu, tampaknya baris bala bantuan bisa bertahan.",
  ui_story_1012_10121002_7_dialog_content = "Bagus sekali. Pastikan untuk bergerak cepat, Semuanya. Tadi itu baru permulaan.",
  ui_story_1012_10121002_8_dialog_content = "Beri tahu Commander Barton untuk memimpin bala bantuan dan berkoordinasi dengan sekutu kita.",
  ui_story_1012_10121002_9_dialog_content = "Ya.",
  ui_story_1012_10121002_10_dialog_content = "Meskipun Carleen bukan anak kecil lagi...",
  ui_story_1012_10121002_11_dialog_content = "Dia mungkin tidak akan terlalu suka bertarung bersama pasukanmu di garis depan.",
  ui_story_1012_10121002_12_dialog_content = "Haha! Prajurit yang menjalani hidup dengan mudah tak akan pernah menjadi jenderal.",
  ui_story_1012_10121002_13_dialog_content = "Kudengar kau yang membesarkan Carleen?",
  ui_story_1012_10121002_14_dialog_content = "Kau tampak lebih seperti ayah baginya ketimbang Schwartz, Yang Mulia!",
  ui_story_1012_10121002_15_dialog_content = "Jaga bicaramu, My Lady Reinhardt.",
  ui_story_1012_10121002_16_dialog_content = "Panggil Yang Mulia Ratu dengan hormat!",
  ui_story_1012_10121002_17_dialog_content = "Aaaaaah!!!",
  ui_story_1012_10121002_18_dialog_content = "Aduh...",
  ui_story_1012_10121002_19_dialog_content = "Saat es mencair!",
  ui_story_1012_10121002_20_dialog_content = "Aku tak ingin berbincang santai saat pertempuran sedang berkecamuk.",
  ui_story_1012_10121002_21_dialog_content = "Meski situasi masih terkendali, jangan sampai perhatianmu teralihkan.",
  ui_story_1012_10121002_22_dialog_content = "Kalau begitu, aku akan memimpin pasukan yang tersisa untuk menghadapi Eclipse di depan menara.",
  ui_story_1012_10121002_23_dialog_content = "Tampaknya semua berjalan dengan baik!",
  ui_story_1012_10121002_24_dialog_content = "<color=#e8d9bb>Battlefront, Eraveil</color>",
  ui_story_1012_10121002_25_dialog_content = "Apa?! Bekerja dengan orang-orang Lumopolis itu?",
  ui_story_1012_10121002_26_dialog_content = "Benar.",
  ui_story_1012_10121002_27_dialog_content = "Pff, ya sudah, terserah. Aku paham situasinya. Tak ada yang boleh mengancam utusan.",
  ui_story_1012_10121002_28_dialog_content = "Hah?!",
  ui_story_1012_10121002_29_dialog_content = "Aaaaaah!!!",
  ui_story_1012_10121002_30_dialog_content = "Gaah...",
  ui_story_1012_10121002_31_dialog_content = "Baiklah, sepertinya masih ada yang harus kita bereskan di sini. Sebaiknya kau kembali temui Grand Marshal. Jagalah Tower itu.",
  ui_story_1012_10121002_32_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_1012_10121002_33_dialog_content = "Ah!",
  ui_story_1012_10121002_34_dialog_content = "Hei!",
  ui_story_1012_10121002_35_dialog_content = "Demi Illumina... Sedang apa kau?!",
  ui_story_1012_10121002_36_dialog_content = "Aku tak sengaja! Tanahnya tiba-tiba bergetar barusan...",
  ui_story_1012_10121002_37_dialog_content = "Duh, jangan bikin masalah!",
  ui_story_1012_10121002_38_dialog_content = "<color=#e8d9bb>Duaar—!!</color>",
  ui_story_1012_10121002_39_dialog_content = "Hah... Hah...?!",
  ui_story_1012_10121002_40_dialog_content = "Sebentar. Mereka baru saja menembakkan Eclipsite ke arah kita?!",
  ui_story_1012_10121002_41_dialog_content = "Gampang sekali.",
  ui_story_1012_10121002_42_dialog_content = "Gaah...",
  ui_story_1012_10121002_43_dialog_content = "Ini garis depan, bukan taman bermain. Jika kau di sini tidak untuk bertempur...",
  ui_story_1012_10121002_44_dialog_content = "Lebih baik pulang saja.",
  ui_story_1012_10121002_45_dialog_content = "Siap!",
  ui_story_1012_10121002_46_dialog_content = "Pff... Siap untuk apa, tepatnya?",
  ui_story_1012_10121002_47_dialog_content = "M-maaf!",
  ui_story_1012_10121002_48_dialog_content = "<color=#e8d9bb>Duar!!!</color>",
  ui_story_1012_10121002_49_dialog_content = "Peluru ini...",
  ui_story_1012_10121002_50_dialog_content = "Aneh. Peluru ini tidak ditembakkan ke arah kita kali ini. Selain itu...",
  ui_story_1012_10121002_51_dialog_content = "Tampaknya peluru ini membuat bayangan yang tak menentu, yang hanya bisa berarti bahwa...",
  ui_story_1012_10121002_52_dialog_content = "Sial!",
  ui_story_1012_10121002_53_dialog_content = "Ini <color=#FFB400>Darkflow</color>!",
  ui_story_1012_10121002_54_dialog_content = "Peluru-peluru pertama itu hanya uji coba.",
  ui_story_1012_10121002_55_dialog_content = "Peluru <color=#FFB400>Darkflow</color> ini ditembakkan ke arah Obelisk of Return!",
  ui_story_1012_10121002_56_dialog_content = "(Obelisk of Return?!)",
  ui_story_1012_10121002_57_dialog_content = "Dengar, bala bantuan 2nd Legion! Pertempuran ini berpindah!",
  ui_story_1012_10121002_58_dialog_content = "Pergilah ke Obelisk of Return dan bantu Grand Marshal!",
  ui_story_1012_10121101_1_dialog_content = "<color=#e8d9bb>Obelisk of Return, Eraveil</color>",
  ui_story_1012_10121101_2_dialog_content = "<color=#e8d9bb>Duar!!!</color>",
  ui_story_1012_10121101_3_dialog_content = "(Hah? Ada yang meledak di atas!)",
  ui_story_1012_10121101_4_dialog_content = "(Ayolah, tenangkan dirimu demi melindungi Yang Mulia Ratu!)",
  ui_story_1012_10121101_5_dialog_content = "(Ada apa ini? Tiba-tiba aku merasa mual.)",
  ui_story_1012_10121101_6_dialog_content = "(Rasa mual yang tak asing.)",
  ui_story_1012_10121101_7_dialog_content = "?!",
  ui_story_1012_10121101_8_dialog_content = "Ini <color=#FFB400>Darkflow</color>!",
  ui_story_1012_10121101_9_dialog_content = "Instant Freeze!",
  ui_story_1012_10121101_10_dialog_content = "Perlindungan ini hanya bisa mencakup sedikit area. Tolong, bisakah semuanya merapat?",
  ui_story_1012_10121101_11_dialog_content = "Jangan sampai Darkflow memengaruhimu!",
  ui_story_1012_10121101_12_dialog_content = "*Uhuk* Hanya ini saja tak akan berpengaruh!",
  ui_story_1012_10121101_13_dialog_content = "Penghindaran bukanlah strategi jangka panjang yang baik.",
  ui_story_1012_10121101_14_dialog_content = "Kalau begini... kita harus mencari taktik baru, dan cepat.",
  ui_story_1012_10121101_15_dialog_content = "Grand Marshal!",
  ui_story_1012_10121101_16_dialog_content = "Pas sekali, Anatoli.",
  ui_story_1012_10121101_17_dialog_content = "Oh? Sepertinya kau juga membawa kembali pasukan utama.",
  ui_story_1012_10121101_18_dialog_content = "2nd Legion Commander Barton, melapor.",
  ui_story_1012_10121101_19_dialog_content = "Apa perintahmu, Grand Marshal?",
  ui_story_1012_10121101_20_dialog_content = "Ambil peluang singkat untuk pertempuran.",
  ui_story_1012_10121101_21_dialog_content = "Ah, kau tiba tepat waktu, Commander Barton.",
  ui_story_1012_10121101_22_dialog_content = "Oh! Eh, uh... Grand Marshal?",
  ui_story_1012_10121101_23_dialog_content = "Isi kepala prajurit ini dengan hal selain kecerdasan!",
  ui_story_1012_10121101_24_dialog_content = "Tetap di sini dan jauhkan daya tembak Eclipse dari White Tower. Bisakah kau melakukannya?",
  ui_story_1012_10121101_25_dialog_content = "Aku ingin mengajari mereka bukan hanya Eclipse yang bisa licik.",
  ui_story_1012_10121101_26_dialog_content = "Hmm, kau merencanakan serangan diam-diam? Aku setuju.",
  ui_story_1012_10121101_27_dialog_content = "Pergilah kalau begitu. Aku bisa menjaga tempat ini.",
  ui_story_1012_10121101_28_dialog_content = "(Melihat energi dan semangat Reinhardt, aku hampir bisa melupakan perasaan mengerikan dari Darkflow itu.)",
  ui_story_1012_10121101_29_dialog_content = "(Sementara Eclipse terus menembakkan meriam Darkflow menakutkan mereka tepat ke arah kami.)",
  ui_story_1012_10121101_30_dialog_content = "(Dia berlari ke dalam kegelapan dengan ekspresi seperti sedang menikmati jalan-jalan di musim semi.)",
  ui_story_1012_10121101_31_dialog_content = "(Seorang genius taktis, atau aspiran berbahaya? Pendapat di Illumina tentu saja terbagi.)",
  ui_story_1012_10121101_32_dialog_content = "(Tapi, siapa pun yang pernah melihatnya di medan perang akan mengerti arti sebenarnya dari Illumina.)",
  ui_story_1012_10121101_33_dialog_content = "(Dia bersinar dan berkilau bagaikan Phospherus dalam kegelapan tanpa harapan.)",
  ui_story_1012_10121101_34_dialog_content = "<size=33>Bisa tolong bantu aku, PlayerName?</size>",
  ui_story_1012_10121101_35_dialog_content = "<size=33>Ada suatu hal yang hanya bisa dibantu oleh Caelestite sepertimu.</size>",
  ui_story_1012_10121101_36_dialog_content = "Hah?!",
  ui_story_1012_10121101_37_dialog_content = "Hei, tunggu!",
  ui_story_1012_10121101_38_dialog_content = "Apa-apaan ini?! Kau tak bisa mengangkatku begitu saja!",
  ui_story_1012_10121101_39_dialog_content = "(Apa ini tradisi Illumina yang mengangkat orang kapan pun kau mau?!)",
  ui_story_1012_10121101_40_dialog_content = "Haha... Maafkan aku. Tolong, tahan sebentar!",
  ui_story_1012_10121101_41_dialog_content = "Konon katanya, Caelestite bisa melihat warna Lumina, jadi seharusnya kau juga bisa menemukan <color=#FFB400>sumber dari Darkflow</color>!",
  ui_story_1012_10121101_42_dialog_content = "Untuk saat ini, tolong jadilah navigatorku.",
  ui_story_1012_10121101_43_dialog_content = "Saat kita menghancurkan meriam Darkflow Eclipse itu!",
  ui_story_1012_10121101_44_dialog_content = "<color=#e8d9bb>Battlefront, Eraveil</color>",
  ui_story_1012_10121101_45_dialog_content = "Captain Carleen, ini Eclipsite terakhir dari serangan ini.",
  ui_story_1012_10121101_46_dialog_content = "Apa kita akan beralih garis pertempuran dengan orang-orang Illumina itu?",
  ui_story_1012_10121101_47_dialog_content = "Tidak. Jangan sampai ada celah di pertahanan kita.",
  ui_story_1012_10121101_48_dialog_content = "Jika kita mundur, kita hanya menyerahkan tempat ini kepada Eclipse.",
  ui_story_1012_10121101_49_dialog_content = "Aku penasaran!",
  ui_story_1012_10121101_50_dialog_content = "Lord of Lumopolis benar-benar bersedia mengirim putri kesayangannya untuk berperang.",
  ui_story_1012_10121101_51_dialog_content = "?!",
  ui_story_1012_10121101_52_dialog_content = "Aku sudah lama ingin tahu bagaimana rasanya berdansa tango dengan seorang putri.",
  ui_story_1012_10121101_53_dialog_content = "(Ini dia. Sudah kuduga.)",
  ui_story_1012_10121101_54_dialog_content = "Mirren Gautier... Kau hanyalah lawan Lumopolis yang kalah, bukan?",
  ui_story_1012_10121101_55_dialog_content = "Kau sedang dicari oleh Hall of Justice, dan masih berani menunjukkan mukamu di sini?",
  ui_story_1012_10121101_56_dialog_content = "Haha! Jadi, Yang Mulia, penampilanku harus memberikan kesan yang tak terlupakan, bukan?",
  ui_story_1012_10121101_57_dialog_content = "Yah, kalau begitu, sepertinya eksperimen \"Sight\" yang menyiksa diriku sendiri itu bukan tanpa alasan.",
  ui_story_1012_10121101_57X1_dialog_content = "Hanya ada kita dan beberapa minion milikmu...",
  ui_story_1012_10121101_57X2_dialog_content = "Jangan langsung menyimpulkan siapa yang terpancing.",
  ui_story_1012_10121101_58_dialog_content = "Kau menjijikkan. Bahkan suaramu membuatku merasa mual.",
  ui_story_1012_10121101_59_dialog_content = "Ah... Argh! Es!",
  ui_story_1012_10121101_60_dialog_content = "Apa ini?! Kenapa kau jadi seperti orang es aneh yang menunggangi naga itu?",
  ui_story_1012_10121101_61_dialog_content = "Orang es aneh... Maksudmu Queen Bethlehem?!",
  ui_story_1012_10121101_62_dialog_content = "Berani-beraninya kau menghina Yang Mulia Ratu seperti itu!",
  ui_story_1012_10121101_63_dialog_content = "TIDAK TERMAAFKAN!!",
  ui_story_1012_10121101_64_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_1012_10121101_65_dialog_content = "Sepertinya kau sedang berada dalam masalah.",
  ui_story_1012_10121101_66_dialog_content = "Berterimakasihlah kepada PlayerName, bukan aku. Dialah yang merasakan Darkflow Mirren Gautier.",
  ui_story_1012_10121101_67_dialog_content = "Dia bersikeras bahwa kami harus datang dan membantumu.",
  ui_story_1012_10121101_68_dialog_content = "Kau sudah di sini, PlayerName, jadi jangan buang waktu lagi.",
  ui_story_1012_10121101_69_dialog_content = "Meriam Eclipse itu berhenti! Ini kesempatan kita untuk mengakhiri trik licik mereka selamanya!",
  ui_story_1012_10121101_70_dialog_content = "Lalu Mirren...",
  ui_story_1012_10121101_71_dialog_content = "... Hah?!",
  ui_story_1012_10121101_72_dialog_content = "Pff... Dia cepat sekali, bisa kabur seperti itu.",
  ui_story_1012_10121101_73_dialog_content = "Kalau begitu, jangan buang-buang waktu. Kita harus terus maju!",
  ui_story_1012_10121101_74_dialog_content = "Aku akan menjaga barisan di sini. Pimpin Lumo Knights dan bergabunglah dengan pasukan utama.",
  ui_story_1012_10121101_75_dialog_content = "Eclipsite mendekat... Darkflow di mana-mana... Satu-satunya yang dibutuhkan White Tower sekarang, adalah pertahanan yang kuat.",
  ui_story_1012_10121101_76_dialog_content = "Baiklah, mari kita lakukan ini!",
  ui_story_1012_10121101_77_dialog_content = "Omong-omong, sepertinya kondisimu tak begitu baik, PlayerName... Kau baik-baik saja?",
  ui_story_1012_10121101_78_dialog_content = "(Darkflow ini terlalu pekat. Aku bisa merasakannya di mana-mana. Aku hampir bisa mengecapnya, menciumnya. Rasanya mual sekali...)",
  ui_story_1012_10121101_79_dialog_content = "(Tapi aku malu untuk mengakuinya!)",
  ui_story_1012_10121101_80_dialog_content = "Hmm... Jika aku sedikit pucat, artinya kita bergerak ke arah yang benar!",
  ui_story_1012_10121101_81_dialog_content = "Kita berpencar saja untuk saat ini. Tunggu kabar baik dariku, Carleen.",
  ui_story_1012_10121101_82_dialog_content = "Jaga dirimu.",
  ui_story_1012_10121101_83_dialog_content = "Bergeraklah, PlayerName.",
  ui_story_1012_10121101_84_dialog_content = "Meriam Darkflow berada tepat di depan. Ini mungkin akan jadi pertempuran yang sengit.",
  ui_story_1012_10121102_1_dialog_content = "Bagus sekali, PlayerName!",
  ui_story_1012_10121102_2_dialog_content = "Ini lebih seperti meriam kaca!",
  ui_story_1012_10121102_3_dialog_content = "Itu yang terakhir, 'kan?",
  ui_story_1012_10121102_4_dialog_content = "Biar kuperiksa…",
  ui_story_1012_10121102_5_option_content = "Force Boost!",
  ui_story_1012_10121102_6_dialog_content = "Sepertinya sudah tak ada lagi campuran Darkflow yang menyatu, tapi...",
  ui_story_1012_10121102_7_dialog_content = "Aaaaaah!!!",
  ui_story_1012_10121102_8_dialog_content = "Aahhhhhh!!!!!",
  ui_story_1012_10121102_9_dialog_content = "Makhluk-makhluk aneh ini sangat merepotkan.",
  ui_story_1012_10121102_10_dialog_content = "Apa Darkflow yang mereka pancarkan mengacaukan penilaianmu?",
  ui_story_1012_10121102_11_dialog_content = "Kalau begitu... Mari tusuk mereka dengan tombakku ini!",
  ui_story_1012_10121102_12_dialog_content = "Rasakan kekuatan yang sesungguhnya!",
  ui_story_1012_10121102_13_dialog_content = "Gaah...",
  ui_story_1012_10121102_14_dialog_content = "Rupanya kau masih haus darah seperti biasanya, Reinhardt.",
  ui_story_1012_10121102_15_dialog_content = "Suatu hari nanti, kegilaanmu ini yang akan jadi akhir hidupmu.",
  ui_story_1012_10121102_16_dialog_content = "Terima kasih atas perhatianmu.",
  ui_story_1012_10121102_17_dialog_content = "Tampaknya kau tak begitu terkejut melihatku masih bernapas, Forsakin.",
  ui_story_1012_10121102_18_dialog_content = "Kau sudah tahu, sejak <color=#FFB400>saat itu</color>...",
  ui_story_1012_10121102_19_dialog_content = "Bahwa monster sepertiku tak bisa dibunuh dengan mudah.",
  ui_story_1012_10121102_20_dialog_content = "Kau percaya diri sekali.",
  ui_story_1012_10121102_21_dialog_content = "Omong-omong, jika kau kemari untuk bertemu dengan Figerald, dia ada di depan.",
  ui_story_1012_10121102_22_dialog_content = "Sayangnya, aku tak bisa lama-lama di sini untuk bermain.",
  ui_story_1012_10121102_23_dialog_content = "(Bahasa Eclipsian) Ayo kita pergi.",
  ui_story_1012_10121102_24_dialog_content = "(Bahasa Eclipsian) Baik.",
  ui_story_1012_10121102_25_dialog_content = "(Aneh sekali... Kenapa Forsakin jadi ramah begitu?)",
  ui_story_1012_10121102_26_dialog_content = "(Dia bahkan menunjukkan ke mana harus pergi.)",
  ui_story_1012_10121102_27_dialog_content = "Re-Reinhardt... Ada yang aneh dengan Forsakin.",
  ui_story_1012_10121102_28_dialog_content = "...",
  ui_story_1012_10121102_29_dialog_content = "PlayerName, periksa situasi garis depan di dasar menara.",
  ui_story_1012_10121102_30_dialog_content = "Y-ya. Baik!",
  ui_story_1012_10121102_31_dialog_content = "Ck, ck, ck...",
  ui_story_1012_10121102_32_dialog_content = "Bahkan saudarimu sendiri tak bisa mengecohmu, ya?",
  ui_story_1012_10121102_33_dialog_content = "Kalian Aurorian biasanya jauh lebih tak berperasaan daripada Eclipsite.",
  ui_story_1012_10121102_34_dialog_content = "... Cih.",
  ui_story_1012_10121102_35_dialog_content = "(Sudah kuduga, mereka mengincarku.)",
  ui_story_1012_10121102_36_dialog_content = "(Jika aku tidak datang, mereka akan terus melemahkan kekuatan kami dengan meriam Darkflow itu.)",
  ui_story_1012_10121102_37_dialog_content = "(Tapi, jika aku datang untuk menghancurkan meriam itu, mereka akan menyerang White Tower.)",
  ui_story_1012_10121102_38_dialog_content = "(Jumlah kita... terlalu sedikit.)",
  ui_story_1012_10121102_39_dialog_content = "Ayo cepat, PlayerName!",
  ui_story_1012_10121102_40_dialog_content = "Menurutmu itu akan membantu menyelesaikan masalah?",
  ui_story_1012_10121102_41_dialog_content = "Kekalahan terakhirmu tak pernah diragukan, Aurorian.",
  ui_story_1012_10121102_42_dialog_content = "Semua yang kau lakukan ini hanyalah menunda hal yang tak terelakkan.",
  ui_story_1012_10121102_43_dialog_content = "Ya, pergi sana. Pulanglah, kelinci kecil, temui teman-temanmu yang sudah <color=#FFB400>babak belur dan kalah</color>!",
  ui_story_1012_10121102_44_dialog_content = "Lihat bagaimana mereka dibantai oleh para Eclipsite.",
  ui_story_1012_10121102_45_dialog_content = "Apa...?",
  ui_story_1012_10121102_46_dialog_content = "Ck, ck, ck... Membayangkannya saja membuatku berliur. Pertunjukan yang tak boleh dilewatkan!",
  ui_story_1012_10121102_47_dialog_content = "Kurasa aku akan mengambil kursiku.",
  ui_story_1012_10121102_48_dialog_content = "Nikmati rasa manis dari kekalahan, Reinhardt.",
  ui_story_1012_10121102_49_dialog_content = "Kejar dia, PlayerName, sekarang!",
  ui_story_1012_10121102_50_dialog_content = "Kita... Kita harus bagaimana, Reinhardt?",
  ui_story_1012_10121102_51_dialog_content = "Bagaimana menurutmu... Kita bertarung!",
  ui_story_1012_10121102_52_dialog_content = "Percayalah pada rekan-rekanmu, dan terus berjuang...",
  ui_story_1012_10121102_53_dialog_content = "Hingga akhir!",
  ui_story_1012_10121301_1_dialog_content = "Cih, adegan yang mengharukan sekali.",
  ui_story_1012_10121301_2_dialog_content = "Telur yang sudah kau lindungi dengan susah payah akhirnya retak.",
  ui_story_1012_10121301_3_dialog_content = "Seperti aku akan menemukan titik lemah dan dengan perlahan menekannya.",
  ui_story_1012_10121301_4_dialog_content = "Aku ingin merasakanmu pecah dan hancur di tanganku.",
  ui_story_1012_10121301_5_dialog_content = "Eclipsite! Kawan-kawanku yang haus darah!",
  ui_story_1012_10121301_6_dialog_content = "Apa bau darahnya sudah tercium?",
  ui_story_1012_10121301_7_dialog_content = "Pertajam penglihatan kalian pada titik lemah mereka!",
  ui_story_1012_10121301_8_dialog_content = "Padamkan semburat cahaya terakhir itu!",
  ui_story_1012_10121301_9_dialog_content = "Gaah!",
  ui_story_1012_10121301_10_dialog_content = "Pasukan utama Eclipsite terus bergerak maju!",
  ui_story_1012_10121301_11_dialog_content = "Apa kita masih... bisa menahan mereka?",
  ui_story_1012_10121301_12_dialog_content = "Secara strategis, baris pertahanan kita sudah runtuh. Akan sangat bodoh dan berisiko untuk mencoba mempertahankan posisi.",
  ui_story_1012_10121301_13_dialog_content = "Area yang sudah ditembus itu sendiri sangat rentan. Selain itu...",
  ui_story_1012_10121301_14_dialog_content = "Cukup. Aku tak mau tahu lagi!",
  ui_story_1012_10121301_15_dialog_content = "Tak ada yang ingin diceramahi di tengah medan perang!",
  ui_story_1012_10121301_16_dialog_content = "Justru KARENA kita sedang di tengah medan perang, pemikiran rasional seperti itu penting.",
  ui_story_1012_10121301_17_dialog_content = "Jadi, apa kesimpulan dari pemikiran rasionalmu?",
  ui_story_1012_10121301_18_dialog_content = "Jika terus bertahan, kita benar-benar akan dibantai.",
  ui_story_1012_10121301_19_dialog_content = "...",
  ui_story_1012_10121301_20_dialog_content = "Secara objektif, upaya terbaik kita adalah meninggalkan White Tower, berkumpul kembali, dan mencoba menerobos ke satu arah.",
  ui_story_1012_10121301_21_dialog_content = "Karena prajurit kita, secara keseluruhan, lebih kuat dari prajurit lawan, seharusnya kita bisa menerobos.",
  ui_story_1012_10121301_22_dialog_content = "Kenapa kau tak menerobos saja dengan mudah, kalau begitu?",
  ui_story_1012_10121301_23_dialog_content = "Aku tak bisa pergi.",
  ui_story_1012_10121301_24_dialog_content = "Grand Marshal memerintahkanku untuk tetap tinggal, jadi aku akan berada di sini dan terus berjuang.",
  ui_story_1012_10121301_25_dialog_content = "Hahaha! Sepertinya aku menemukan kekurangan dalam penilaian rasionalmu, Prajurit Kecil Illumina.",
  ui_story_1012_10121301_26_dialog_content = "Sudah tugas seorang prajurit untuk mematuhi perintah, yang pertama dan utama. Dengan kondisi seperti ini, aku...",
  ui_story_1012_10121301_27_dialog_content = "Aku tahu, aku tahu. Diamlah.",
  ui_story_1012_10121301_28_dialog_content = "Namun, melihat apa yang tak terelakkan...",
  ui_story_1012_10121301_29_dialog_content = "Bukankah lebih bagus mengistirahatkan kepala pintarmu itu dulu, dan menyiapkan tanganmu untuk bertarung?!",
  ui_story_1012_10121301_30_dialog_content = "Sudah, sudah, itu tidak akan berhasil, Nona cantik.",
  ui_story_1012_10121301_31_dialog_content = "Jika kau terus menimbulkan masalah di sini, Lord Figerald akan kesal.",
  ui_story_1012_10121301_32_dialog_content = "Siapa itu?!",
  ui_story_1012_10121301_33_dialog_content = "Apa-apaan ini?",
  ui_story_1012_10121301_34_dialog_content = "Awas!",
  ui_story_1012_10121301_35_dialog_content = "Kau... jangan ikut campur.",
  ui_story_1012_10121301_36_dialog_content = "Tadi, hanya ada aku dan si nona cantik di seluruh dunia ini, sebelum penyusup-penyusup bau ini merusak pesta kami.",
  ui_story_1012_10121301_37_dialog_content = "Kau…!",
  ui_story_1012_10121301_38_dialog_content = "Waspadalah karena Lumina di sekitar kita tampaknya dibatasi.",
  ui_story_1012_10121301_39_dialog_content = "Kekuatan kita ditahan di sini.",
  ui_story_1012_10121301_40_dialog_content = "Sungguh?",
  ui_story_1012_10121301_41_dialog_content = "Banyak sekali yang harus kupikirkan sekarang. Aku hanya ingin melontarkan tinjuku ke wajah pria itu!",
  ui_story_1012_10121301_42_dialog_content = "Oh! Kau mesra sekali, Nona!",
  ui_story_1012_10121301_43_dialog_content = "Pelan-pelan saja... Kita punya banyak waktu.",
  ui_story_1012_10121301_44_dialog_content = "Bagaimana kalau saling mengenal satu sama lain lebih dulu?",
  ui_story_1012_10121301_45_dialog_content = "Aaaaah!!",
  ui_story_1012_10121301_46_dialog_content = "...",
  ui_story_1012_10121301_47_dialog_content = "Kau yang di belakang! Kenapa kau menyingkir dari pertempuran?",
  ui_story_1012_10121301_48_dialog_content = "...",
  ui_story_1012_10121301_49_dialog_content = "Queen of the North...",
  ui_story_1012_10121301_49X1_dialog_content = "Aku ingat dirimu, si pemberontak di White Night Celebration.",
  ui_story_1012_10121301_49X2_dialog_content = "Dahulu, intuisimu jauh lebih tajam.",
  ui_story_1012_10121301_50_dialog_content = "Sekarang, kau berubah menjadi sosok yang ragu-ragu di medan pertempuran.",
  ui_story_1012_10121301_51_dialog_content = "...",
  ui_story_1012_10121301_52_dialog_content = "Oh Queen of the North yang perkasa, apakah kau tak dapat membaca arah angin?",
  ui_story_1012_10121301_53_dialog_content = "Kekalahan Aurorian tak bisa dihindari. Lantas, buat apa bertempur?",
  ui_story_1012_10121301_54_dialog_content = "Kekalahan Aurorian mungkin tak dapat dihindari. Namun, hanya pengecut yang takut bertempur.",
  ui_story_1012_10121301_55_dialog_content = "Aku…",
  ui_story_1012_10121301_56_dialog_content = "Berjuang dan bertempur untuk mempertahankan tanah airmu. Ini adalah hal yang seharusnya kaupertimbangkan sebelumnya.",
  ui_story_1012_10121301_57_dialog_content = "Seperti kau sekarang ini, kau tak akan bertahan sedetik pun di medan perang.",
  ui_story_1012_10121301_58_dialog_content = "Hmm... Kalau memang begitu...",
  ui_story_1012_10121301_59_dialog_content = "Jika kau mengizinkanku untuk mendapatkan kehormatan...",
  ui_story_1012_10121301_60_dialog_content = "Untuk melawanmu!",
  ui_story_1012_10121301_61_dialog_content = "Wow! Itu besar sekali!",
  ui_story_1012_10121301_62_dialog_content = "Apakah muncul dari... arah Yang Mulia Ratu?",
  ui_story_1012_10121301_63_dialog_content = "Yang Mulia Ratu!!!",
  ui_story_1012_10121301_64_dialog_content = "Gaaaah!!",
  ui_story_1012_10121301_65_dialog_content = "Minggir! Serangga sialan!",
  ui_story_1012_10121301_66_dialog_content = "Aku harus melindungi Yang Mulia Ratu.",
  ui_story_1012_10121301_67_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1012_10121301_68_dialog_content = "Ah! Apa itu tadi?!",
  ui_story_1012_10121301_69_dialog_content = "Yang Mulia! Oh, Yang Mulia!",
  ui_story_1012_10121301_70_dialog_content = "Kesetiaan yang kekanak-kanakan sekali.",
  ui_story_1012_10121301_71_dialog_content = "Kau…",
  ui_story_1012_10121301_72_dialog_content = "Wanita perkasa macam dia tak perlu perlindungan dari anjing ingusan sepertimu.",
  ui_story_1012_10121301_73_dialog_content = "Lebih baik kaukhawatirkan dirimu sendiri.",
  ui_story_1012_10121301_74_dialog_content = "Ayo kita berburu musuh! Sudah dimulai.",
  ui_story_1012_10121301_75_dialog_content = "!!!",
  ui_story_1012_10121301_76_dialog_content = "Aaaaah!",
  ui_story_1012_10121301_77_dialog_content = "Hosh... Hosh...",
  ui_story_1012_10121301_78_dialog_content = "(Aku terlalu lelah untuk ini.)",
  ui_story_1012_10121301_79_dialog_content = "(Bahkan setelah peningkatan Chord Link, tingkat intensitas ini... sedikit terlalu berlebihan.)",
  ui_story_1012_10121301_80_dialog_content = "(Tidak! Tenanglah Barton! Jangan biarkan yang lain tumbang!)",
  ui_story_1012_10121301_81_dialog_content = "Itu saja kemampuanmu, Barton?",
  ui_story_1012_10121301_82_dialog_content = "Apa?!",
  ui_story_1012_10121301_83_dialog_content = "Forsakin... Kau terkutuk.",
  ui_story_1012_10121301_84_dialog_content = "Perjuangan kita akhirnya telah tiba pada kesimpulan yang terlambat.",
  ui_story_1012_10121301_85_dialog_content = "Tapi jangan khawatir. Akan kuukir sendiri batu nisanmu: \"Aku mengagumi semangatmu\".",
  ui_story_1012_10121301_86_dialog_content = "Cih... Tak perlu repot-repot mengurusiku!",
  ui_story_1012_10121301_87_dialog_content = "Rasakan ini!",
  ui_story_1012_10121301_88_dialog_content = "Hah! Kau bahkan tak melakukan perlawanan?!",
  ui_story_1012_10121301_89_dialog_content = "Aku tidak tertarik dengan binatang yang terluka. Mereka akan mewakiliku untuk membereskanmu.",
  ui_story_1012_10121301_90_dialog_content = "Aku hanya tertarik pada menara di belakangmu.",
  ui_story_1012_10121301_91_dialog_content = "Gaah!",
  ui_story_1012_10121301_92_dialog_content = "Lelucon macam apa ini?",
  ui_story_1012_10121301_93_dialog_content = "Forsakin!",
  ui_story_1012_10121301_94_dialog_content = "Forsaaakiiiinnn!!",
  ui_story_1012_10121301_95_dialog_content = "<color=#e8d9bb>Dor! Dor! Dor!</color>",
  ui_story_1012_10121301_96_dialog_content = "Hah? Apa ini?",
  ui_story_1012_10121301_97_dialog_content = "(Barton, mundur!)",
  ui_story_1012_10121301_98_dialog_content = "PlayerName! Kau kembali!",
  ui_story_1012_10121301_99_dialog_content = "Celaka...",
  ui_story_1012_10121301_100_dialog_content = "Lebih baik terlambat daripada tidak sama sekali.",
  ui_story_1012_10121301_101_dialog_content = "Kelihatannya buruk. Mereka terlalu banyak.",
  ui_story_1012_10121301_102_dialog_content = "Kalian semua, buatlah diri kalian berguna di tempat lain!",
  ui_story_1012_10121301_103_dialog_content = "Mulai sekarang, aku akan mengurusnya.",
  ui_story_1012_10121301_104_dialog_content = "Ada hal yang ingin kubahas dengannya.",
  ui_story_1012_10121301_105_dialog_content = "Bahas? Bukankah sudah agak terlambat?",
  ui_story_1012_10121301_106_dialog_content = "Haha! Sekarang dengar, aku tahu tidak ada satu pun dari kita yang mau mendengar perkataan pihak lain.",
  ui_story_1012_10121301_107_dialog_content = "Jadi, kali ini aku akan menggunakan bahasa yang kalian mengerti.",
  ui_story_1012_10121301_108_dialog_content = "Kau sama sekali tak punya peluang menang saat berhadapan dengan kekuatan gabungan Eclipse!",
  ui_story_1012_10121301_109_dialog_content = "Aku tak peduli. Aku hanya ingin kau mendengar.",
  ui_story_1012_10121301_110_dialog_content = "Peringatan: Eclipsite tak terdaftar memasuki Colossus Maintenance Zone.",
  ui_story_1012_10121301_111_dialog_content = "Peringatan: Eclipsite tak terdaftar memasuki Colossus Component Storage.",
  ui_story_1012_10121301_112_dialog_content = "Peringatan: Eclipsite tak terdaftar memasuki Waste Disposal Facility.",
  ui_story_1012_10121301_113_dialog_content = "Hentikan sistem peringatan tak berguna itu! Adakah hal yang dapat kita lakukan?!",
  ui_story_1012_10121301_114_dialog_content = "Memeriksa pertahanan Obelisk of Return—",
  ui_story_1012_10121301_115_dialog_content = "Mohon maaf, terdapat kerusakan parah pada kemampuan pertahanan menara. Kemampuannya berkurang untuk menahan serangan.",
  ui_story_1012_10121301_116_dialog_content = "Kukira... Andai saja ada jalan, kita pasti sudah mencoba melakukannya pada Forsakin.",
  ui_story_1012_10121301_117_dialog_content = "PlayerName, apakah Neural Aux berkomunikasi denganmu lagi?",
  ui_story_1012_10121301_118_dialog_content = "Ya, mengabarkan Eclipsite yang sedang menyerbu menara.",
  ui_story_1012_10121301_119_dialog_content = "Sekalipun kita dapat mengatasi semua Eclipsite di menara itu, semuanya sudah terlambat.",
  ui_story_1012_10121301_120_dialog_content = "Jika kita tidak dapat membalikkan kondisi pertempuran di luar, tinggal tunggu waktu saja sampai mereka menguasai Obelisk of Return.",
  ui_story_1012_10121301_121_dialog_content = "Lantas, bagaimana kita membalikkannya?",
  ui_story_1012_10121301_122_dialog_content = "Bahkan dengan Aurorian yang kuat seperti Reinhardt dan Bethlehem di pihak kita...",
  ui_story_1012_10121301_122X1_dialog_content = "Situasi akan terus memburuk.",
  ui_story_1012_10121301_123_dialog_content = "Kita masih punya sejumlah siasat.",
  ui_story_1012_10121301_124_dialog_content = "Misalnya \"senjata pemungkas\" yang disebutkan Neural Aux, Chord of the Law.",
  ui_story_1012_10121301_125_dialog_content = "Peringatan: Eclipsite tak terdaftar memasuki Resource Production Room.",
  ui_story_1012_10121301_126_dialog_content = "Peringatan: Eclipsite tak terdaftar memasuki Caelestite Residential Quarters.",
  ui_story_1012_10121301_127_dialog_content = "Sudah kubilang hentikan sistem peringatan itu, Neural Aux! Lebih baik cepat beri tahu aku cara mengaktifkan Chord of the Law!",
  ui_story_1012_10121301_128_dialog_content = "Aku bahkan tak tahu fungsinya, tetapi kita kehabisan pilihan. Aku harus mencobanya!",
  ui_story_1012_10121301_129_dialog_content = "???",
  ui_story_1012_10121301_130_dialog_content = "Permintaan buruk terdeteksi.",
  ui_story_1012_10121301_131_dialog_content = "Tidak ada satu pun Caelestite yang diizinkan untuk menyentuh Chord of the Law. Ini disyaratkan oleh Highest Decree.",
  ui_story_1012_10121301_132_dialog_content = "Bagaimana kau bisa mengkhawatirkan hukum dan aturan pada saat seperti ini?!",
  ui_story_1012_10121301_133_dialog_content = "Jika Eclipse menang, bukan hanya kita yang akan terkena bencana! Obelisk of Return akan merasakan akibatnya juga!",
  ui_story_1012_10121301_134_dialog_content = "Kau ingin itu terjadi?!",
  ui_story_1012_10121301_135_dialog_content = "Mohon maaf. Aku tidak dapat menginginkan hasil yang spesifik.",
  ui_story_1012_10121301_136_dialog_content = "Yang kutahu hanyalah mematuhi Highest Decree.",
  ui_story_1012_10121301_137_dialog_content = "Kau…!",
  ui_story_1012_10121301_138_dialog_content = "Sudah habis kesabaranku buat meladeni mesin tak berguna, tak berjiwa, dan tak peduli apa pun itu!",
  ui_story_1012_10121301_139_dialog_content = "Tenang, PlayerName. Tak ada gunanya ribut dengan AI.",
  ui_story_1012_10121301_140_dialog_content = "Lakukan saja hal terbaik yang bisa kita lakukan. Kurasa semua kubu akan bentrok di sini.",
  ui_story_1012_10121301_141_dialog_content = "Aku hanya berharap... kita masih hidup saat mereka tiba.",
  ui_story_1012_10121301_142_dialog_content = "Ya, kau tidak salah. Satu-satunya hal yang harus dilakukan adalah mengerahkan upaya terbaik.",
  ui_story_1012_10121301_143_dialog_content = "Peringatan: Eclipsite tak terdaftar memasuki Central Core.",
  ui_story_1012_10121301_144_dialog_content = "Bip! Bip! Bip! Bip! Bip! Bip!",
  ui_story_1012_10121301_145_dialog_content = "TOLONG, bisakah kau diam?!",
  ui_story_1012_10121301_146_dialog_content = "Neural Aux, jika kau tak bisa membantu, tidak bisakah kau diam?",
  ui_story_1012_10121301_147_dialog_content = "Prakondisi dipicu. Perintah nonaktif dimulai.",
  ui_story_1012_10121301_148_dialog_content = "Perintah dari: Francis. Prioritas Perintah: Tertinggi.",
  ui_story_1012_10121301_149_dialog_content = "Memodifikasi sistem logika dasar Neural Aux.",
  ui_story_1012_10121301_150_dialog_content = "Francis? Dia lagi? Apa yang dia lakukan kali ini?",
  ui_story_1012_10121301_151_dialog_content = "Modifikasi sistem logika dasar telah selesai.",
  ui_story_1012_10121301_152_dialog_content = "Karena terdapat ancaman eksistensial, aku akan memberi tahu Caelestite tentang cara pengaktifan Chord of the Law.",
  ui_story_1012_10121301_153_dialog_content = "Apa?!",
  ui_story_1012_10121301_154_dialog_content = "Kau... Kau mau mengatakannya padaku sekarang? Bagaimana bisa?",
  ui_story_1012_10121301_155_dialog_content = "Benar. Perintah nonaktif memungkinkanku untuk melakukan operasi ini sekarang.",
  ui_story_1012_10121301_156_dialog_content = "Francis, aku tak tahu siapa dirimu, tapi terima kasih!",
  ui_story_1012_10121301_157_dialog_content = "Baiklah jika begitu, katakan. Apa yang harus kulakukan?",
  ui_story_1012_10121301_158_dialog_content = "Pergilah ke Central Core dan sambungkan kesadaranmu dengan Circular System.",
  ui_story_1012_10121301_159_dialog_content = "Di kedalaman Circular System, rebut Otorisasi Core Ring.",
  ui_story_1012_10121301_160_dialog_content = "Hanya Otorisasi Core Ring yang dapat mengaktifkan Chord of the Law.",
  ui_story_1012_10121301_161_dialog_content = "Otorisasi Core Ring? Bukankah itu otoritas tertinggi dan tak tersentuh?!",
  ui_story_1012_10121301_162_dialog_content = "Benar. Inilah alasanku menggunakan kata \"rebut.\"",
  ui_story_1012_10121301_163_dialog_content = "Tindakan ini berlawanan dengan semua aturan. Tindakan ini adalah hal tabu.",
  ui_story_1012_10121301_164_dialog_content = "Besar kemungkinan juga bahwa kau akan binasa saat melakukannya.",
  ui_story_1012_10121301_165_dialog_content = "Apa?!",
  ui_story_1012_10121301_166_dialog_content = "Mengapa? Apa risikonya?",
  ui_story_1012_10121301_167_dialog_content = "Aku mohon maaf. Aku tidak memiliki akses soal informasi Otorisasi Core Ring.",
  ui_story_1012_10121301_168_dialog_content = "Perintah menuntutku untuk memberi tahu Caelestite cara mengaktifkan Chord of the Law.",
  ui_story_1012_10121301_169_dialog_content = "Hanya Otorisasi Core Ring yang dapat mengaktifkan Chord of the Law.",
  ui_story_1012_10121301_170_dialog_content = "...",
  ui_story_1012_10121301_171_dialog_content = "Kau sama sekali tak memberiku pilihan, 'kan?",
  ui_story_1012_10121301_172_dialog_content = "Carleen, kurasa aku telah menemukan cara membalikkan situasi pertempuran.",
  ui_story_1012_10121301_173_dialog_content = "Ayo. Kita harus kembali ke Central Core. Aku akan mengaktifkan Chord of the Law.",
  ui_story_1012_10121301_174_dialog_content = "Chord of the Law?! Apakah Neural Aux akhirnya memberi tahumu apa yang harus kaulakukan?",
  ui_story_1012_10121301_175_dialog_content = "Eh, iya. Semacam itulah.",
  ui_story_1012_10121301_176_dialog_content = "Sulitkah? Apa yang dapat kubantu?",
  ui_story_1012_10121301_177_dialog_content = "Menara telah dipenuhi Eclipsite. Bantu aku sampai ke Central Core. Itu sudah cukup.",
  ui_story_1012_10121301_178_dialog_content = "Setelahnya, nasib ada di tanganku sendiri.",
  ui_story_1012_10121301_179_dialog_content = "Reinhardt, kau bisa mendengarku?",
  ui_story_1012_10121301_180_dialog_content = "Oh! Ya! Bagaimana situasi di sana? Kau perlu bantuan?",
  ui_story_1012_10121301_181_dialog_content = "Kurasa begitu. Aku sedang berupaya untuk mengaktifkan senjata pemungkas Obelisk of Return.",
  ui_story_1012_10121301_182_dialog_content = "Sepertinya aku harus meninggalkan pertempuran untuk sementara waktu.",
  ui_story_1012_10121301_183_dialog_content = "Selain itu, kalian perlu mengulur waktu buatku.",
  ui_story_1012_10121301_184_dialog_content = "Sampai aku mengaktifkan senjatanya, jangan biarkan siapa pun melewati kalian dan masuk ke Obelisk of Return.",
  ui_story_1012_10121301_185_dialog_content = "Senjata pemungkas? Kedengarannya itu bisa sangat membantu!",
  ui_story_1012_10121301_186_dialog_content = "Senjata-senjata menara besar ini didayai oleh rahasia peradaban kuno.",
  ui_story_1012_10121301_187_dialog_content = "Aku hanya perlu tahu senjata-senjata ini bisa apa, Caelestite!",
  ui_story_1012_10121301_188_dialog_content = "Ha! Aku bahkan tak tahu apakah aku akan berhasil.",
  ui_story_1012_10121301_189_dialog_content = "Biarkan aku yang mengurus pertempuran. Tak ada yang dapat melewatiku.",
  ui_story_1012_10121301_190_dialog_content = "Mereka harus memenuhi lembah ini dengan mayat sebelum dapat menguburku!",
  ui_story_1012_10121301_191_dialog_content = "...",
  ui_story_1012_10121301_192_dialog_content = "Kau dapat mendengarku, Yang Mulia?",
  ui_story_1012_10121301_193_dialog_content = "Aku...",
  ui_story_1012_10121301_194_dialog_content = "Lakukan hal yang harus kaulakukan.",
  ui_story_1012_10121301_195_dialog_content = "!!!",
  ui_story_1012_10121301_196_dialog_content = "Bintang-bintang berkumpul di sini, tempat mereka akan bersinar hingga fajar menyingsing.",
  ui_story_1012_10121301_197_dialog_content = "Kumohon, kalahkanlah kegelapan.",
  ui_story_1012_10121301_198_dialog_content = "Yang Mulia...",
  ui_story_1012_10121301_199_dialog_content = "Lalu…",
  ui_story_1012_10121301_200_dialog_content = "Pastikan kau kembali dengan selamat.",
  ui_story_1012_10121302_1_dialog_content = "Gaah...",
  ui_story_1012_10121302_2_dialog_content = "Central Core ada di depan! Cepat!",
  ui_story_1012_10121302_3_dialog_content = "Ya!",
  ui_story_1012_10121302_4_dialog_content = "Tapi, uh... Makin banyak Eclipsite di sini, ya?",
  ui_story_1012_10121302_5_dialog_content = "Benar. Mungkin pertempuran ini mengganggu mereka.",
  ui_story_1012_10121302_6_dialog_content = "Baiklah, skenario terburuknya adalah kita menarik perhatian semua Eclipsite di Obelisk of Return.",
  ui_story_1012_10121302_7_dialog_content = "Duh, sial. Central Core adalah jalan buntu.",
  ui_story_1012_10121302_8_dialog_content = "Tidak adakah hal lain yang dapat kita lakukan untuk mempertahankan diri, Neural Aux?",
  ui_story_1012_10121302_9_dialog_content = "Guardian System adalah mekanisme pertahanan Central Core.",
  ui_story_1012_10121302_10_dialog_content = "Namun, catatan menyatakan bahwa sistem tersebut rusak beberapa waktu lalu.",
  ui_story_1012_10121302_11_dialog_content = "Yah, salah kita. Maafkan.",
  ui_story_1012_10121302_12_dialog_content = "Makin banyak Eclipsite, tepat di belakang kita. Cepat!",
  ui_story_1012_10121302_13_dialog_content = "Oh, sial!",
  ui_story_1012_10121302_14_dialog_content = "<color=#e8d9bb>Tik-tik-tik... tik-tik-tik...</color>",
  ui_story_1012_10121302_15_dialog_content = "Kita berhasil!",
  ui_story_1012_10121302_16_dialog_content = "Ugh!",
  ui_story_1012_10121302_17_dialog_content = "Wow—",
  ui_story_1012_10121302_18_dialog_content = "Fiuh... Aku berutang budi padamu, Carleen.",
  ui_story_1012_10121302_19_dialog_content = "Lakukanlah hal yang harus kaulakukan.",
  ui_story_1012_10121302_20_dialog_content = "Aktifkan Chord of the Law.",
  ui_story_1012_10121302_21_dialog_content = "Sepertinya kita belum merontokkan semua Eclipsite itu.",
  ui_story_1012_10121302_22_dialog_content = "Bukankah kita harus membereskan mereka dulu?",
  ui_story_1012_10121302_23_dialog_content = "Kita tak tahu berapa banyak jumlah mereka. Kita tak dapat bertempur selamanya.",
  ui_story_1012_10121302_24_dialog_content = "Biar aku yang menghadapi mereka.",
  ui_story_1012_10121302_25_dialog_content = "Hah? Kau sendiri?",
  ui_story_1012_10121302_26_dialog_content = "Sebaiknya kau segera aktifkan senjata itu. Aku yang menghadapi Eclipsite.",
  ui_story_1012_10121302_27_dialog_content = "Seorang Caelestite dan seorang Aurorian, masing-masing memainkan perannya.",
  ui_story_1012_10121302_28_dialog_content = "Tapi jumlah mereka begitu banyak.",
  ui_story_1012_10121302_29_dialog_content = "Percayakan saja padaku.",
  ui_story_1012_10121302_30_dialog_content = "Seperti aku memercayaimu.",
  ui_story_1012_10121302_31_dialog_content = "Ice Blossom! Menyebar!",
  ui_story_1012_10121302_32_dialog_content = "...",
  ui_story_1012_10121302_33_dialog_content = "Ya. Aku percaya padamu, Carleen.",
  ui_story_1012_10121302_34_dialog_content = "Baiklah! Mari kita lakukan ini!",
  ui_story_1012_10121302_35_option_content = "Force Boost!",
  ui_story_1012_10121302_36_dialog_content = "<color=#e8d9bb>Ngungg!</color>",
  ui_story_1012_10121302_37_dialog_content = "Aku di sini lagi, Circular System.",
  ui_story_1012_10121302_38_dialog_content = "Terakhir kali, aku mendapati bahwa Circular System adalah ruang yang beroperasi pada suatu level kesadaran, suatu ruang pikiran.",
  ui_story_1012_10121302_39_dialog_content = "Kesadaranku dapat bergerak dan menyelidiki semua informasi yang disimpan di sini.",
  ui_story_1012_10121302_40_dialog_content = "Neural Aux menyebutkan sesuatu tentang pembagian fungsi Obelisk of Return menjadi tiga level: Outer Ring, Inner Ring, dan Core Ring.",
  ui_story_1012_10121302_41_dialog_content = "Karena ada kata \"ring\" pada nama semuanya, aku penasaran apakah proses otorisasi juga dibagi antara berbagai ring Circular System.",
  ui_story_1012_10121302_42_dialog_content = "Neural Aux juga menyebutkan bahwa Core Ring Authorization berada di bagian terdalam Circular System. Apakah artinya makin dekat kita dengan pusatnya, makin tinggi pula otorisasi yang diperlukan?",
  ui_story_1012_10121302_43_dialog_content = "Jika aku benar, itu sungguh... cara yang aneh tetapi runtut.",
  ui_story_1012_10121302_44_dialog_content = "Singkatnya, bagaimanapun, aku harus bisa sedekat mungkin dengan Circular System.",
  ui_story_1012_10121302_45_dialog_content = "Apa ini? Tak ada jalan ke sana?",
  ui_story_1012_10121302_46_dialog_content = "Kesadaranku kesulitan untuk masuk lebih jauh.",
  ui_story_1012_10121302_47_dialog_content = "Kau tak dapat masuk lebih dalam.",
  ui_story_1012_10121302_48_dialog_content = "!!!",
  ui_story_1012_10121302_49_dialog_content = "Caelestite tidak boleh berada di dekat Core Ring.",
  ui_story_1012_10121302_50_dialog_content = "Ini adalah <color=#FFB400>Highest Decree</color>.",
  ui_story_1012_10121302_51_dialog_content = "Aku sudah muak dengan Highest Decree ini.",
  ui_story_1012_10121302_52_dialog_content = "Sebenarnya Highest Decree itu apa, sih?",
  ui_story_1012_10121302_53_dialog_content = "Me-mengapa setiap orang mematuhinya?",
  ui_story_1012_10121302_54_dialog_content = "Eh...?",
  ui_story_1012_10121302_55_dialog_content = "Mengapa... aku menjadi takut?",
  ui_story_1012_10121302_56_dialog_content = "<color=#FFB400>Highest Decree</color> adalah petunjuk yang asli dan utama.",
  ui_story_1012_10121302_57_dialog_content = "Ia sudah ada jauh sebelum kau lahir, bahkan sebelum bangsa Caelestite ada.",
  ui_story_1012_10121302_58_dialog_content = "Ia adalah bagian dari dirimu, dari kesadaranmu, daging dan darahmu.",
  ui_story_1012_10121302_59_dialog_content = "Ia adalah keyakinan wajib bagi Caelestite dan alasan kemunculan mereka.",
  ui_story_1012_10121302_60_dialog_content = "Ia adalah sifat dasarmu yang telah ditentukan sejak lama.",
  ui_story_1012_10121302_61_dialog_content = "Kesadaranku jungkir balik.",
  ui_story_1012_10121302_62_dialog_content = "Apakah selama ini aku benar-benar mematuhi hal yang disebut Highest Decree ini?",
  ui_story_1012_10121302_63_dialog_content = "Kedengarannya hampir naluriah.",
  ui_story_1012_10121302_64_dialog_content = "Caelestite tidak boleh berada di dekat Core Ring.",
  ui_story_1012_10121302_65_dialog_content = "Ini adalah <color=#FFB400>Highest Decree</color>.",
  ui_story_1012_10121302_66_dialog_content = "(Kesadaranku mematuhi Highest Decree... Rasanya seperti ada pikiran yang lebih kuat sedang memanipulasi pikiranku.)",
  ui_story_1012_10121302_67_dialog_content = "(Perasaanku soal ini begitu kuat.)",
  ui_story_1012_10121302_68_dialog_content = "(Jika aku mematuhinya, bahkan walau sekejap, aku tak akan pernah bebas. Aku harus hidup dalam sistemnya untuk selama-lamanya.)",
  ui_story_1012_10121302_69_dialog_content = "(Tidak akan ada cara untuk melarikan diri dari ikatan bawaannya yang kuat.)",
  ui_story_1012_10121302_70_dialog_content = "(Semuanya akan selesai jika itu terjadi.)",
  ui_story_1012_10121302_71_dialog_content = "(Tak akan ada peluang lain untuk mengaktifkan Chord of the Law, atau membalikkan situasi pertempuran di luar sana.)",
  ui_story_1012_10121302_72_dialog_content = "(Aku hanya punya satu kesempatan, dan itu adalah sekarang.)",
  ui_story_1012_10121302_73_dialog_content = "Ayo, masuk... MASUK! Masuk lebih dalam!",
  ui_story_1012_10121302_74_dialog_content = "Lupakan Highest Decree. Jangan memercayainya!",
  ui_story_1012_10121302_75_dialog_content = "Sifat yang telah ditentukan? Terserah, deh. Aku bahkan belum pernah mendengarnya seumur hidupku!",
  ui_story_1012_10121302_76_dialog_content = "Maksudmu apa, tiba-tiba muncul untuk menahanku?",
  ui_story_1012_10121302_77_dialog_content = "Kau tak dapat masuk lebih dalam.",
  ui_story_1012_10121302_78_dialog_content = "Caelestite tidak boleh berada di dekat Core Ring.",
  ui_story_1012_10121302_79_dialog_content = "Ini adalah <color=#FFB400>Highest Decree</color>.",
  ui_story_1012_10121302_80_dialog_content = "Bukan Highest Decree yang membuatku hidup hingga sejauh ini! Orang tuakulah yang telah berkorban untukku! Itu Soroz...",
  ui_story_1012_10121302_81_dialog_content = "Vicelah yang telah menemukanku! Dan semua Aurorianlah yang telah bertempur bersamaku!",
  ui_story_1012_10121302_82_dialog_content = "Buatku, MEREKA adalah Highest Decree!",
  ui_story_1012_10121302_83_dialog_content = "Kau tak dapat masuk lebih dalam.",
  ui_story_1012_10121302_84_dialog_content = "Kau dapat masuk.",
  ui_story_1012_10121302_85_dialog_content = "Hah? Apa aku telah mengalahkannya?",
  ui_story_1012_10121302_86_dialog_content = "Apakah ini? Core Ring?",
  ui_story_1012_10121302_87_dialog_content = "Sebentar, ini adalah...",
  ui_story_1012_10121302_87X1_dialog_content = "Sepertinya, aku pernah melihatnya. Danau gletser yang sama seperti Lake Mirror dan Aurora di langit.",
  ui_story_1012_10121302_87X2_dialog_content = "Apakah ini khayalanku? Tapi, semuanya terasa begitu nyata. Embusan udara dingin dari danau membuatku merinding.",
  ui_story_1012_10121302_88_dialog_content = "Tempat ini tampak nyata, tidak seperti ruang pikiran.",
  ui_story_1012_10121302_89_dialog_content = "Entah bagaimana, kesadaranku menjadi solid! Luar biasa.",
  ui_story_1012_10121302_90_dialog_content = "Mungkin ini mirip dengan teknologi Battle Simulator.",
  ui_story_1012_10121302_91_dialog_content = "Jadi... Jadi, apa yang harus kulakukan sekarang setelah berada di dalam Core Ring ini? Sepertinya Neural Aux tak pernah mengatakan apa pun tentang itu.",
  ui_story_1012_10121302_92_dialog_content = "Hai, Neural Aux. Kau bisa mendengar?",
  ui_story_1012_10121302_93_dialog_content = "Aku, ah, berhasil masuk ke dalam Core Ring. Apa yang harus kulakukan sekarang?",
  ui_story_1012_10121302_94_dialog_content = "<color=#e8d9bb>Kriek...</color>",
  ui_story_1012_10121302_95_dialog_content = "Hah? Suara apa itu?",
  ui_story_1012_10121302_96_dialog_content = "<color=#e8d9bb>Klik... Klak...</color>",
  ui_story_1012_10121302_97_dialog_content = "...",
  ui_story_1012_10121302_98_dialog_content = "...",
  ui_story_1012_10121302_99_dialog_content = "Tahan! Apa ini... Guardian?",
  ui_story_1012_10121302_100_dialog_content = "Kenapa ia di sini?",
  ui_story_1012_10121302_101_dialog_content = "<color=#e8d9bb>Duk... Duk... Duk... Duk...</color>",
  ui_story_1012_10121302_102_dialog_content = "Kau telah melanggar tabu dengan menerobos ke dalam Core Ring, Caelestite.",
  ui_story_1012_10121302_103_dialog_content = "Otorisasi Core Ring adalah hak pihak tertinggi. Ia tak boleh disentuh.",
  ui_story_1012_10121302_104_dialog_content = "Anggapan seperti itu perlu dihentikan.",
  ui_story_1012_10121302_105_dialog_content = "Caelestite tak punya kemampuan untuk memiliki kekuatan. Dengan demikian, kekuatan adalah hal yang menegakkan dekret tersebut.",
  ui_story_1012_10121302_106_dialog_content = "Yang benar saja... sekarang ada DUA?",
  ui_story_1012_10121302_107_dialog_content = "Tindakan ini berlawanan dengan semua aturan. Tindakan ini adalah hal tabu.",
  ui_story_1012_10121302_108_dialog_content = "Besar kemungkinan juga bahwa kau akan binasa saat melakukannya.",
  ui_story_1012_10121302_109_dialog_content = "Apakah aku harus... melawan semua ini?",
  ui_story_1012_10121302_110_dialog_content = "<color=#e8d9bb>Bip...</color>",
  ui_story_1012_10121302_111_dialog_content = "<color=#e8d9bb>Bip...</color>",
  ui_story_1012_10121302_112_dialog_content = "<color=#e8d9bb>Bip...</color>",
  ui_story_1012_10121302_113_dialog_content = "<color=#e8d9bb>Bip—</color>",
  ui_story_1012_10121302_114_dialog_content = "...",
  ui_story_1012_10121401_1_dialog_content = "Hosh... Hosh...",
  ui_story_1012_10121401_2_dialog_content = "Orang ini...",
  ui_story_1012_10121401_3_dialog_content = "(Kekuatan seperti itu.)",
  ui_story_1012_10121401_4_dialog_content = "Oh mangsa kecil, mangsa kecil. Tak bisa lari lagi, hmm?",
  ui_story_1012_10121401_5_dialog_content = "Kau... Kau bisa terbang! Tentu saja kau tak lelah!",
  ui_story_1012_10121401_6_dialog_content = "Lantas siapa yang lari?!",
  ui_story_1012_10121401_7_dialog_content = "Ck, ck, ck... kau tampak lelah, dan itu bisa berbahaya.",
  ui_story_1012_10121401_8_dialog_content = "Momen perburuan yang paling menyenangkan adalah saat mangsanya mulai tampak kehabisan tenaga.",
  ui_story_1012_10121401_9_dialog_content = "Perasaan yang muncul saat sedikit lagi mendapatkan mangsamu. Ooh, menyenangkan sekali!",
  ui_story_1012_10121401_10_dialog_content = "Kau memuakkan... dasar gila!",
  ui_story_1012_10121401_11_dialog_content = "Argh...!",
  ui_story_1012_10121401_12_dialog_content = "Ck, ck, ck! Teruslah berlari! Oh ya...",
  ui_story_1012_10121401_13_dialog_content = "Habiskan sisa tenagamu untuk hidup sedikit lebih lama lagi!",
  ui_story_1012_10121401_14_dialog_content = "Aku harus berhenti berlari.",
  ui_story_1012_10121401_15_dialog_content = "Karena aku... adalah pengawal Ratu!",
  ui_story_1012_10121401_16_dialog_content = "<color=#e8d9bb>Klik... Pop... Krak...</color>",
  ui_story_1012_10121401_17_dialog_content = "Eh? Apa itu?",
  ui_story_1012_10121401_18_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_1012_10121401_19_dialog_content = "*Uhuk-uhuk*... Pff...",
  ui_story_1012_10121401_20_dialog_content = "*Terengah-engah*... Kau baik-baik saja, prajurit Illumina?",
  ui_story_1012_10121401_21_dialog_content = "Aku baik-baik saja. Akhirnya aku bisa keluar.",
  ui_story_1012_10121401_22_dialog_content = "Kita masih perlu waspada.",
  ui_story_1012_10121401_23_dialog_content = "Oh, itu memalukan, hihi! Permainannya tidak bisa dilanjutkan.",
  ui_story_1012_10121401_24_dialog_content = "Kau tidak menyukai dunia kecil kami, ya? Mengapa kau mempertaruhkan hidupmu dengan tergesa-gesa seperti itu?",
  ui_story_1012_10121401_25_dialog_content = "Hal yang kau lakukan saat ini hanyalah cara lain untuk menunggu akhir.",
  ui_story_1012_10121401_26_dialog_content = "Kau menjijikkan.",
  ui_story_1012_10121401_27_dialog_content = "Hei, bukankah itu... penjaga Queen of the North?",
  ui_story_1012_10121401_28_dialog_content = "Kalian rupanya.",
  ui_story_1012_10121401_29_dialog_content = "Kau masih bisa bertarung?",
  ui_story_1012_10121401_30_dialog_content = "Keadaan tidak tampak terlalu baik sekarang.",
  ui_story_1012_10121401_31_dialog_content = "Aku dapat melihatnya. Orang di langit itu adalah boss musuh, 'kan?",
  ui_story_1012_10121401_32_dialog_content = "Bagus sekali, Mirren.",
  ui_story_1012_10121401_33_dialog_content = "Kepung mangsa agar mereka bergerombol jadi satu! Perburuan ini akan mudah dan menyenangkan!",
  ui_story_1012_10121401_34_dialog_content = "Awas!",
  ui_story_1012_10121401_35_dialog_content = "Darkflow yang sangat pekat.",
  ui_story_1012_10121401_36_dialog_content = "Ayolah! Berikan segalanya untuk terakhir kalinya.",
  ui_story_1012_10121401_37_dialog_content = "Illumina! Di belakangmu!",
  ui_story_1012_10121401_38_dialog_content = "Ups! Kau menemukanku.",
  ui_story_1012_10121401_39_dialog_content = "Argh…",
  ui_story_1012_10121401_40_dialog_content = "(Sial. Aku tak bisa meloloskan diri.)",
  ui_story_1012_10121401_41_dialog_content = "Lihat ekspresimu yang tidak berdaya itu.",
  ui_story_1012_10121401_42_dialog_content = "Kau tampak seperti sedang menggoda.",
  ui_story_1012_10121401_43_dialog_content = "Dasar mesum!",
  ui_story_1012_10121401_44_dialog_content = "Di atas sana! Manusia terbang itu kembali!",
  ui_story_1012_10121401_45_dialog_content = "Apa?!",
  ui_story_1012_10121401_46_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1012_10121401_47_dialog_content = "Aduh...",
  ui_story_1012_10121401_48_dialog_content = "Tangan kiriku. Aku tak dapat menggerakkannya.",
  ui_story_1012_10121401_49_dialog_content = "Aduh. Sakit.",
  ui_story_1012_10121401_50_dialog_content = "*Batuk-batuk*",
  ui_story_1012_10121401_51_dialog_content = "Ck, ck... benar-benar menyedihkan... melihat kalian semua menderita.",
  ui_story_1012_10121401_52_dialog_content = "Lord Figerald! Mereka hanya Aurorian rendahan, tidak pantas untuk mendapatkan belas kasihanmu.",
  ui_story_1012_10121401_53_dialog_content = "Ah, tetapi itu yang kurasakan sekarang! Selalu tersentuh, menyaksikan kilatan cahaya terakhir dalam mata mereka akan padam.",
  ui_story_1012_10121401_54_dialog_content = "Belas kasihan terhadap musuh! Mengapa Lord Figerald terlalu bermurah hati?",
  ui_story_1012_10121401_55_dialog_content = "Murah hati? Jangan hina aku dengan istilah itu.",
  ui_story_1012_10121401_56_dialog_content = "Namun,... harus kuakui. Aku memang memiliki sedikit rasa kasihan pada mereka.",
  ui_story_1012_10121401_57_dialog_content = "Aku ingin mengakhiri penderitaan makhluk-makhluk malang itu sendiri.",
  ui_story_1012_10121401_58_dialog_content = "Sungguh?",
  ui_story_1012_10121401_59_dialog_content = "Hah? Itu...",
  ui_story_1012_10121401_60_dialog_content = "Memperlihatkan rasa belas kasihan berarti melampaui setiap orang lain.",
  ui_story_1012_10121401_61_dialog_content = "Namun, kau... kau pastinya tidak.",
  ui_story_1012_10121401_62_dialog_content = "Queen of the North!!! Kau...",
  ui_story_1012_10121401_63_dialog_content = "Di mana Michelangelo?",
  ui_story_1012_10121401_64_dialog_content = "Dia tak dapat menahanku.",
  ui_story_1012_10121401_65_dialog_content = "Kurang ajar!",
  ui_story_1012_10121401_66_dialog_content = "Ini merupakan pertempuran yang sulit. Bagi Aurorian, ya, tetapi juga bagi kalian.",
  ui_story_1012_10121401_67_dialog_content = "Kau telah terlalu lama melarikan diri.",
  ui_story_1012_10121401_68_dialog_content = "Bagaimanapun, kau akan menghadapiku sebelum ini berakhir.",
  ui_story_1012_10121401_69_dialog_content = "Ini adalah harga yang harus kau bayar untuk perang ini.",
  ui_story_1012_10121401_70_dialog_content = "Yang Mulia!!! Oh, Ratu kita telah datang untuk menyelamatkan kami!!!",
  ui_story_1012_10121401_71_dialog_content = "Queen of the North. Sungguh kekuatan yang mengesankan!",
  ui_story_1012_10121401_72_dialog_content = "Kalian semua! Aku tahu kalian telah terdesak.",
  ui_story_1012_10121401_73_dialog_content = "Tapi bertahanlah sebentar lagi. Perang belum berakhir.",
  ui_story_1012_10121401_74_dialog_content = "Caelestite sedang berusaha membalikkan keadaan, tetapi kita harus mengulur waktu dengan mempertahankan Obelisk of Return.",
  ui_story_1012_10121401_75_dialog_content = "Semua jalan mengarah pada kehancuran ini.",
  ui_story_1012_10121401_76_dialog_content = "Caelestite…",
  ui_story_1012_10121401_77_dialog_content = "Apakah sungguh bijaksana untuk mempertaruhkan perang ini seutuhnya pada anak muda lemah itu?",
  ui_story_1012_10121401_78_dialog_content = "Aku percaya padanya.",
  ui_story_1012_10121401_79_dialog_content = "Kuharap kalian semua juga.",
  ui_story_1012_10121401_80_dialog_content = "Aku juga! Jika Yang Mulia Ratu percaya, aku juga!",
  ui_story_1012_10121401_81_dialog_content = "...",
  ui_story_1012_10121401_82_dialog_content = "Hmm... Penilaian Queen of the North berharga. Jauh melebihi penilaianku.",
  ui_story_1012_10121401_83_dialog_content = "Lagi pula, kita tak akan menyerah.",
  ui_story_1012_10121401_84_dialog_content = "Tapi hal yang mengkhawatirkanku adalah...",
  ui_story_1012_10121401_85_dialog_content = "Apakah kita masih kuat untuk mempertahankan menara itu?",
  ui_story_1012_10121401_86_dialog_content = "Kau tak perlu khawatir tentang hal itu.",
  ui_story_1012_10121401_87_dialog_content = "Dia masih mengunci pintu masuknya. Lagi pula, dia terlahir untuk perang.",
  ui_story_1012_10121401_88_dialog_content = "(Bahasa Eclipsian) Mundur! Kembali!",
  ui_story_1012_10121401_89_dialog_content = "(Bahasa Eclipsian) Kecepatan tinggi! Mundur sejauh yang kalian bisa!",
  ui_story_1012_10121401_90_dialog_content = "(Bahasa Eclipsian) Forsakin, Lord Figerald memerintahkan kami untuk menghabisi semuanya tanpa sisa.",
  ui_story_1012_10121401_91_dialog_content = "(Bahasa Eclipsian) Jadi, kenapa?",
  ui_story_1012_10121401_92_dialog_content = "(Bahasa Eclipsian) Kuperintahkan kalian untuk mundur! LAKUKAN!!!",
  ui_story_1012_10121401_93_dialog_content = "(Bahasa Eclipsian) Forsakin?",
  ui_story_1012_10121401_94_dialog_content = "(Bahasa Eclipsian) Kalian mendapat perintah baru sekarang, jadi mundur!",
  ui_story_1012_10121401_95_dialog_content = "(Bahasa Eclipsian) Misi kalian adalah menyerang, bukan mengorbankan diri sia-sia!",
  ui_story_1012_10121401_96_dialog_content = "<color=#e8d9bb>DHUAR!!! DOR—KRAK—DHUAR!</color>",
  ui_story_1012_10121401_97_dialog_content = "Apa?!",
  ui_story_1012_10121401_98_dialog_content = "Apa yang terjadi di gerbang masuk White Tower?",
  ui_story_1012_10121401_99_dialog_content = "Apakah ada yang... meledak?",
  ui_story_1012_10121401_100_dialog_content = "...",
  ui_story_1012_10121401_101_dialog_content = "Seluruh lembah terguncang.",
  ui_story_1012_10121401_102_dialog_content = "Apa ITU?",
  ui_story_1012_10121401_103_dialog_content = "Itu senjata. Kau pernah melihatnya.",
  ui_story_1012_10121401_104_dialog_content = "Apa maksudmu, aku pernah melihatnya?!",
  ui_story_1012_10121401_105_dialog_content = "Tidak mungkin.",
  ui_story_1012_10121401_106_dialog_content = "Akhirnya! Aku menjadi saksi perjuangan akhir Grand Marshal yang heroik.",
  ui_story_1012_10121401_107_dialog_content = "Aku tak tahu apakah harus senang atau cemas.",
  ui_story_1012_10121401_108_dialog_content = "Hei, ke mana semua musuh pergi?",
  ui_story_1012_10121401_109_dialog_content = "Ada yang tidak beres. Bagaimana medan pertempuran bisa kosong seperti itu?",
  ui_story_1012_10121401_110_dialog_content = "Kau hanya bangsat yang menyedihkan.",
  ui_story_1012_10121401_111_dialog_content = "Bahkan monster sepertimu juga takut mati?",
  ui_story_1012_10121401_112_dialog_content = "...",
  ui_story_1012_10121401_113_dialog_content = "Hati-hati, Reinhardt. Kau dapat melukai dirimu sendiri jika menggunakan kekuatan seperti itu.",
  ui_story_1012_10121401_114_dialog_content = "Hahaha! Omong kosong. Ini bukan medan perang?",
  ui_story_1012_10121401_115_dialog_content = "Aku tak bermimpi dapat keluar dari sini tanpa lecet sedikit pun.",
  ui_story_1012_10121401_116_dialog_content = "Lebih baik kau gunakan kekuatan itu untuk menyelamatkan yang lain.",
  ui_story_1012_10121401_117_dialog_content = "Kau masih tak paham.",
  ui_story_1012_10121401_118_dialog_content = "Ini adalah pertarungan yang akan kita teruskan hingga akhir, menuju kemenangan atau kematian.",
  ui_story_1012_10121401_119_dialog_content = "Tak pernah terlintas di benakku untuk lari dari kenyataan ini!",
  ui_story_1012_10121401_120_dialog_content = "...",
  ui_story_1012_10121401_121_dialog_content = "Kelihatannya kita hanya tak mampu untuk saling memahami.",
  ui_story_1012_10121401_122_dialog_content = "Haha! Tak ada yang baru di sini.",
  ui_story_1012_10121401_123_dialog_content = "Kau yang menyiram bensin.",
  ui_story_1012_10121401_124_dialog_content = "Jadi, sekarang, biarkan aku melihatmu terbakar.",
  ui_story_1012_10121401_125_dialog_content = "Bagus, majulah.",
  ui_story_1012_10121401_126_dialog_content = "Ini mungkin menjadi pertarungan kita yang terakhir.",
  ui_story_1012_10121401_127_dialog_content = "...",
  ui_story_1012_10121401_128_dialog_content = "(Bahasa Eclipsian) Semua unit, serang Obelisk of Return.",
  ui_story_1012_10121401_129_dialog_content = "*Terkesiap*",
  ui_story_1012_10121401_130_dialog_content = "Gaaaah!!",
  ui_story_1012_10121401_131_dialog_content = "Masih ada.... begitu banyak Eclipsite.",
  ui_story_1012_10121401_132_dialog_content = "Menjauhlah... dari PlayerName!",
  ui_story_1012_10121401_133_dialog_content = "Aduh!",
  ui_story_1012_10121401_134_dialog_content = "Untung hanya tangan kiriku. Aku masih bisa menggunakan tombakku.",
  ui_story_1012_10121401_135_dialog_content = "Berapa banyak yang tersisa, PlayerName? Di mana mereka...",
  ui_story_1012_10121401_136_dialog_content = "Oh, aku lupa. Kau tak dapat mendengarkanku sekarang.",
  ui_story_1012_10121401_137_dialog_content = "Aku bahkan tak tahu bagaimana keadaanmu sekarang.",
  ui_story_1012_10121401_138_dialog_content = "Aku tak tahu berapa lama lagi aku dapat bertahan. Mungkin tidak begitu lama.",
  ui_story_1012_10121401_139_dialog_content = "Aaaahhhhhh!",
  ui_story_1012_10121401_140_dialog_content = "<color=#e8d9bb>Bukk!</color>",
  ui_story_1012_10121401_141_dialog_content = "Aduh! Tanganku!",
  ui_story_1012_10121401_142_dialog_content = "Apa orang lain memang... meninju dengan cara seperti itu?",
  ui_story_1012_10121401_143_dialog_content = "...",
  ui_story_1012_10121401_144_dialog_content = "Oh tidak, itu di kanan.",
  ui_story_1012_10121401_145_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1012_10121401_146_dialog_content = "*Batuk-batuk*",
  ui_story_1012_10121401_147_dialog_content = "Tidak! Aku belum selesai. Ah, bangsat itu kembali lagi.",
  ui_story_1012_10121401_148_dialog_content = "...",
  ui_story_1012_10121401_149_dialog_content = "Oh, aku tahu yang satu itu. Serangan cepat dan kuat.",
  ui_story_1012_10121401_150_dialog_content = "Ayolah, fokus! Konsentrasi.",
  ui_story_1012_10121401_151_dialog_content = "<color=#e8d9bb>Wush!</color>",
  ui_story_1012_10121401_152_dialog_content = "Fiuh! Luput...",
  ui_story_1012_10121401_153_dialog_content = "Tapi aku tak bisa apa-apa lagi.",
  ui_story_1012_10121401_154_dialog_content = "Aku kehabisan tenaga dan yang kulakukan hanyalah menghindari serangan. Aku sudah mencoba menunda hal yang tak terelakkan, tetapi...",
  ui_story_1012_10121401_155_dialog_content = "Aku tak dapat menundanya lebih lama lagi.",
  ui_story_1012_10121401_156_dialog_content = "Keadaan di luar menara tampak suram. Carleen tak dapat menahan begitu banyak Eclipsite lebih lama lagi.",
  ui_story_1012_10121401_157_dialog_content = "Aku harus menggunakan Chord of the Law, makin cepat makin baik.",
  ui_story_1012_10121401_158_dialog_content = "Tapi bagaimana?",
  ui_story_1012_10121401_159_dialog_content = "<color=#e8d9bb>Wush!</color>",
  ui_story_1012_10121401_160_dialog_content = "Jangan lagi!",
  ui_story_1012_10121401_161_dialog_content = "Aduh. Aku sudah tak mampu berdiri.",
  ui_story_1012_10121401_162_dialog_content = "Tapi aku tak dapat berbuat apa-apa hingga dua Guardian itu dibereskan.",
  ui_story_1012_10121401_163_dialog_content = "Aku harus menghabisi mereka.",
  ui_story_1012_10121401_164_dialog_content = "Akan kucoba lagi.",
  ui_story_1012_10121401_165_dialog_content = "Ahhhhhhhhhhhh!",
  ui_story_1012_10121401_166_dialog_content = "<color=#e8d9bb>Bukk!</color>",
  ui_story_1012_10121401_167_dialog_content = "Sakit sekali!",
  ui_story_1012_10121401_168_dialog_content = "Tapi... tunggu, ini adalah ruang pikiran!",
  ui_story_1012_10121401_169_dialog_content = "Tak peduli seberapa pun sakit yang disebabkannya, tak ada yang benar-benar bisa menyakitiku di sini.",
  ui_story_1012_10121401_170_dialog_content = "Ini semua ada di dalam pikiran. Yang dapat kulakukan adalah menahan rasa sakit ini!",
  ui_story_1012_10121401_171_dialog_content = "Jadi, itulah yang akan kulakukan.",
  ui_story_1012_10121401_172_dialog_content = "Satu pukulan tak akan merusak apa pun. Tapi bagaimana dengan seratus pukulan? Sejuta?",
  ui_story_1012_10121401_173_dialog_content = "Aku akan terus melakukannya hingga ia kalah!",
  ui_story_1012_10121401_174_option_content = "Pukul!",
  ui_story_1012_10121401_175_dialog_content = "<color=#e8d9bb>Bukk!</color>",
  ui_story_1012_10121401_176_dialog_content = "Aduh...",
  ui_story_1012_10121401_177_option_content = "Pukul!",
  ui_story_1012_10121401_178_dialog_content = "<color=#e8d9bb>Bukk!</color>",
  ui_story_1012_10121401_179_dialog_content = "Lawan rasa sakit...",
  ui_story_1012_10121401_180_option_content = "Pukul!",
  ui_story_1012_10121401_181_dialog_content = "<color=#e8d9bb>Bukk!</color>",
  ui_story_1012_10121401_182_dialog_content = "Jariku mati rasa. Parah. Kepalan tinju memerlukan jari.",
  ui_story_1012_10121401_183_dialog_content = "Mengapa mereka membuat ruang pikiran ini begitu meyakinkan?",
  ui_story_1012_10121401_184_dialog_content = "Tak apa-apa, aku masih dapat menggunakan tangan yang lain!",
  ui_story_1012_10121401_185_option_content = "Pukul!",
  ui_story_1012_10121401_186_dialog_content = "<color=#e8d9bb>Bukk!</color>",
  ui_story_1012_10121401_187_dialog_content = "Seberapa keras yang kau perlukan, hah?",
  ui_story_1012_10121401_188_option_content = "Pukul!",
  ui_story_1012_10121401_189_dialog_content = "<color=#e8d9bb>Bukk!</color>",
  ui_story_1012_10121401_190_dialog_content = "Jadi, ini berfungsi?",
  ui_story_1012_10121401_191_dialog_content = "!!!",
  ui_story_1012_10121401_192_dialog_content = "Tunggu, aku lupa dengan yang satu itu.",
  ui_story_1012_10121401_193_dialog_content = "<color=#e8d9bb>Bukk!</color>",
  ui_story_1012_10121401_194_dialog_content = "Argh... Ouw...",
  ui_story_1012_10121401_195_dialog_content = "Kekuatanku sudah habis. Tak bisa... bergerak.",
  ui_story_1012_10121401_196_dialog_content = "Tak peduli apa pun yang kulakukan, aku tak dapat mengalahkan mereka sendirian.",
  ui_story_1012_10121401_197_dialog_content = "(Selain itu, pada momen ini, aku memahami Highest Decree Obelisk of Return.)",
  ui_story_1012_10121401_198_dialog_content = "(Aku menyadari bahwa ia jauh melampaui pemahamanku, sangat jauh.)",
  ui_story_1012_10121401_199_dialog_content = "(Ia tidak hanya mengandalkan peringatan lisan saja untuk menjaga otoritasnya.)",
  ui_story_1012_10121401_200_dialog_content = "(Ia membidik titik terlemah Caelestite.)",
  ui_story_1012_10121401_201_dialog_content = "(Sekuat apa pun tekad dan kebijaksanaan tak akan berlaku di sini.)",
  ui_story_1012_10121401_202_dialog_content = "(Ia hanya menggunakan satu hal saja—kekuatan, kekuatan yang tak dapat dilawan. Kemudian, dengan kekuatan itu, ia akan mempertahankan diri dan Highest Decree miliknya.)",
  ui_story_1012_10121401_203_dialog_content = "(Caelestite belum pernah mampu melawannya, sejak mereka muncul.)",
  ui_story_1012_10121401_204_dialog_content = "(Ini adalah kekang bawaan terhadap seluruh bangsa Caelestite.)",
  ui_story_1012_10121401_205_dialog_content = "...",
  ui_story_1012_10121401_206_dialog_content = "Maaf semuanya, aku...",
  ui_story_1012_10121401_207_dialog_content = "Baiklah, siapa yang membuat pikiran negatif ini?",
  ui_story_1012_10121401_208_dialog_content = "!!!",
  ui_story_1012_10121401_209_dialog_content = "Vice?",
  ui_story_1012_10121401_210_dialog_content = "Orang-orang itu agak menyebalkan, ya?",
  ui_story_1012_10121401_211_dialog_content = "Lebih baik kau minggir, aku baru saja berkenalan dengan mainan baru ini. Tak ada jaminan kau akan aman.",
  ui_story_1012_10121401_212_dialog_content = "Vice, rupanya kau!!!",
  ui_story_1012_10121401_213_dialog_content = "Kau... sudah bangun? Kok bisa?",
  ui_story_1012_10121401_214_dialog_content = "Kenapa bertanya begitu? Bagaimana aku bahkan bisa tahu harus mulai dari mana?",
  ui_story_1012_10121401_215_dialog_content = "Mari kita mulai dari yang mudah. Orang-orang di depan itu —bunuh mereka, ya?",
  ui_story_1012_10121401_216_dialog_content = "Ya!",
  ui_story_1012_10121401_217_dialog_content = "Lantas, apa yang kita tunggu?",
  ui_story_1012_10121401_218_dialog_content = "PlayerName, siap menerima perintah.",
  ui_story_1012_10121402_1_dialog_content = "Baiklah, waktu bersenang-senangnya sudah selesai. Semuanya berakhir di sini!",
  ui_story_1012_10121402_2_dialog_content = "Kau duluan, pria besar!",
  ui_story_1012_10121402_3_dialog_content = "Ngungg...",
  ui_story_1012_10121402_4_dialog_content = "Harusnya belajar menghindar.",
  ui_story_1012_10121402_5_dialog_content = "Tak ada pertahanan yang cukup kuat untuk menahan anak panahku!",
  ui_story_1012_10121402_6_dialog_content = "Vice! Awas!",
  ui_story_1012_10121402_7_dialog_content = "Iya, iya, aku tahu. Di sisi kananku, 'kan?",
  ui_story_1012_10121402_8_dialog_content = "<color=#e8d9bb>Wush!</color>",
  ui_story_1012_10121402_9_dialog_content = "Tapi... Bagaimana kau tahu.",
  ui_story_1012_10121402_10_dialog_content = "Lalu sekarang tinggal tersisa satu, dan sisanya adalah persoalan mudah.",
  ui_story_1012_10121402_11_dialog_content = "Seberapa banyak anak panah yang dapat kautahan? Mari, kita cari tahu!",
  ui_story_1012_10121402_12_dialog_content = "Ngungg...",
  ui_story_1012_10121402_13_dialog_content = "Ya! Kita berhasil, kedua Guardian itu tumbang.",
  ui_story_1012_10121402_14_dialog_content = "Vice, luar biasa!!!",
  ui_story_1012_10121402_15_dialog_content = "Fiuh... Mereka cukup tangguh.",
  ui_story_1012_10121402_16_dialog_content = "Aku tak akan dapat menumbangkan mereka jika kondisi fisikku tidak berubah seperti ini.",
  ui_story_1012_10121402_17_dialog_content = "Jadi, bagaimana kau bisa ada di sini? Kukira ruang pikiran ini hanya dapat diakses oleh Caelestite.",
  ui_story_1012_10121402_18_dialog_content = "Atau mungkin... kau bukan benar-benar Vice? Kau hanya bagian dari...",
  ui_story_1012_10121402_19_dialog_content = "Tentu saja aku nyata!",
  ui_story_1012_10121402_20_dialog_content = "Kau pikir dirimu pahlawan super yang bisa mendatangkan Vice setiap kali kau perlu bantuan?",
  ui_story_1012_10121402_21_dialog_content = "Bukan begitu... Lantas bagaimana kau bisa berada di sini? Ini tidak masuk akal.",
  ui_story_1012_10121402_22_dialog_content = "Baiklah, sederhananya begini...",
  ui_story_1012_10121402_23_dialog_content = "Aku bangun dari komaku dan langsung merasakan bahwa kau membutuhkanku.",
  ui_story_1012_10121402_24_dialog_content = "Hah?",
  ui_story_1012_10121402_25_dialog_content = "Aku tahu, aku juga tak dapat menjelaskannya. Entah bagaimana, seolah tadi kesadaran kita terhubung.",
  ui_story_1012_10121402_26_dialog_content = "Aku dapat merasakan betapa khawatirnya dirimu. Lalu aku tahu kau ada di mana.",
  ui_story_1012_10121402_27_dialog_content = "Saat aku menemukanmu dan menyentuhmu, kesadaranku muncul di sini, seolah-olah aku tersedot masuk.",
  ui_story_1012_10121402_28_dialog_content = "Lalu, selanjutnya kau sudah tahu sendiri.",
  ui_story_1012_10121402_29_dialog_content = "Kesadaran kita tadi terhubung?",
  ui_story_1012_10121402_30_dialog_content = "Aku juga tak tahu bagaimana itu bisa terjadi.",
  ui_story_1012_10121402_31_dialog_content = "Tapi kita dapat membahas semuanya nanti!",
  ui_story_1012_10121402_32_dialog_content = "Carleen bilang kau perlu mengaktifkan semacam senjata pemungkas di menara, benarkah?",
  ui_story_1012_10121402_33_dialog_content = "Tunggu apa lagi!",
  ui_story_1012_10121402_34_dialog_content = "Ya, kau benar!",
  ui_story_1012_10121402_35_dialog_content = "Kita harus merebut Otorisasi Core Ring. Apakah ada di ruang ini?",
  ui_story_1012_10121402_36_option_content = "Force Boost",
  ui_story_1012_10121402_37_dialog_content = "<color=#e8d9bb>Ngungg!</color>",
  ui_story_1012_10121402_38_dialog_content = "Ah! Apa ini...?",
  ui_story_1012_10121402_39_dialog_content = "(Kesadaranku bertambah luas dan memenuhi setiap tempat.)",
  ui_story_1012_10121402_40_dialog_content = "(Kita... menjadi satu.)",
  ui_story_1012_10121402_41_dialog_content = "(Aku merasakan kedamaian yang belum pernah kurasakan sebelumnya. Seolah...)",
  ui_story_1012_10121402_42_dialog_content = "(Seolah aku mengambang di langit tak terbatas.)",
  ui_story_1012_10121402_43_dialog_content = "(Tak ada yang dapat menahanku. Semua makhluk berada di bawah kendaliku.)",
  ui_story_1012_10121402_44_dialog_content = "Apakah berfungsi? Apakah kau menemukan sesuatu?",
  ui_story_1012_10121402_45_dialog_content = "Sepertinya belum. Tak ada apa pun di sini, hanya kita dan dua Guardian yang tumbang itu.",
  ui_story_1012_10121402_46_dialog_content = "Namun, sejujurnya, aku bahkan tak tahu apa yang sedang kucari.",
  ui_story_1012_10121402_47_dialog_content = "Andai saja Neural Aux ada di sini.",
  ui_story_1012_10121402_48_dialog_content = "Apa yang bisa kubantu?",
  ui_story_1012_10121402_49_dialog_content = "Woah!",
  ui_story_1012_10121402_50_dialog_content = "Kau nyata?",
  ui_story_1012_10121402_51_dialog_content = "Kenapa kau tak menjawab saat aku membutuhkanmu sebelumnya?",
  ui_story_1012_10121402_52_dialog_content = "Karena aku tidak boleh menyentuh Core Ring.",
  ui_story_1012_10121402_53_dialog_content = "Jadi, kenapa sekarang kau bisa?",
  ui_story_1012_10121402_54_dialog_content = "Karena ini bagian dari Highest Decree.",
  ui_story_1012_10121402_55_dialog_content = "Highest Decree meminta Neural Aux datang kemari. Aku mematuhi perintah.",
  ui_story_1012_10121402_56_dialog_content = "Highest Decree?",
  ui_story_1012_10121402_57_dialog_content = "Kukira akulah yang ingin kau di sini?",
  ui_story_1012_10121402_58_dialog_content = "Benar.",
  ui_story_1012_10121402_59_dialog_content = "Kau, saat ini, adalah Highest Decree.",
  ui_story_1012_10121402_60_dialog_content = "Apa?!",
  ui_story_1012_10121402_61_dialog_content = "Kesadaranmu telah menyatu dengan Core Ring.",
  ui_story_1012_10121402_62_dialog_content = "Core Ring adalah pembawa Highest Decree. Oleh karena itu, kau adalah Highest Decree.",
  ui_story_1012_10121402_63_dialog_content = "Perintahmu harus dipatuhi, permintaanmu akan dituruti.",
  ui_story_1012_10121402_64_dialog_content = "Oleh karena itu, apa yang bisa kubantu?",
  ui_story_1012_10121402_65_dialog_content = "Tunggu, Highest Decree tadi menghalangiku, tetapi sekarang... aku Highest Decree?",
  ui_story_1012_10121402_66_dialog_content = "Baiklah, sekarang... aku ingin mengaktifkan Chord of the Law.",
  ui_story_1012_10121402_67_dialog_content = "Perintah diterima. Memulai Chord of the Law.",
  ui_story_1012_10121402_68_dialog_content = "Silakan masukkan parameter pembidik, dan Law yang ingin digunakan.",
  ui_story_1012_10121402_69_dialog_content = "Eh??? Apa maksudnya?",
  ui_story_1012_10121402_70_dialog_content = "Chord of the Law adalah senjata presisi.",
  ui_story_1012_10121402_71_dialog_content = "Penggunaannya membutuhkan waktu dan informasi target yang spesifik.",
  ui_story_1012_10121402_72_dialog_content = "Ini penting jika ingin mencapai hasil yang diharapkan.",
  ui_story_1012_10121402_73_dialog_content = "Tapi bagaimana aku tahu hal yang harus kumasukkan?",
  ui_story_1012_10121402_74_dialog_content = "Apakah ini angka-angka? Aku bahkan tak dapat membacanya!",
  ui_story_1012_10121402_75_dialog_content = "Ini langkah penting. Silakan masukkan parameter pembidik, dan Law yang ingin digunakan.",
  ui_story_1012_10121402_76_dialog_content = "Pokoknya... pokoknya serang semua Eclipsite di dekat Obelisk of Return, oke?",
  ui_story_1012_10121402_77_dialog_content = "Maaf, permintaanmu terlalu kabur. Chord of the Law adalah senjata presisi.",
  ui_story_1012_10121402_78_dialog_content = "Jadi, apa yang harus kulakukan?!",
  ui_story_1012_10121402_79_dialog_content = "Tentunya kau takkan mencegahku menggunakannya sekarang saat kita membutuhkannya, 'kan?",
  ui_story_1012_10121402_80_dialog_content = "Parameter yang ada telah ditemukan dan bisa digunakan untuk inisialisasi.",
  ui_story_1012_10121402_81_dialog_content = "Ingin melanjutkan?",
  ui_story_1012_10121402_82_dialog_content = "Parameter yang ada?",
  ui_story_1012_10121402_83_dialog_content = "Peringatan: Eclipsite tak terdaftar memasuki Obelisk of Return.",
  ui_story_1012_10121402_84_dialog_content = "Terlalu banyak untuk dihitung secara akurat.",
  ui_story_1012_10121402_85_dialog_content = "Gawat! Kita akan kalah dalam pertempuran di luar.",
  ui_story_1012_10121402_86_dialog_content = "Tidak ada waktu lagi untuk kusia-siakan.",
  ui_story_1012_10121402_87_dialog_content = "Neural Aux, bisakah kau memberi tahu kami siapa yang memasukkan parameter itu?",
  ui_story_1012_10121402_88_dialog_content = "Tentu.",
  ui_story_1012_10121402_89_dialog_content = "Seseorang yang masuk sebagai \"Francis\".",
  ui_story_1012_10121402_90_dialog_content = "Jadi, ternyata dia.",
  ui_story_1012_10121402_91_dialog_content = "Peringatan: Eclipsite tak terdaftar memasuki Obelisk of Return.",
  ui_story_1012_10121402_92_dialog_content = "Terlalu banyak untuk dihitung...",
  ui_story_1012_10121402_93_dialog_content = "Siapa targetnya?!",
  ui_story_1012_10121402_94_dialog_content = "Aku hanya perlu tahu satu hal itu, siapa yang diserang Francis menggunakan Chord of the Law?",
  ui_story_1012_10121402_95_dialog_content = "Memeriksa log data...",
  ui_story_1012_10121402_96_dialog_content = "Dikonfirmasi. Target terakhir: Eclipsite.",
  ui_story_1012_10121402_97_dialog_content = "Aku mengerti sekarang…",
  ui_story_1012_10121402_98_dialog_content = "(Master Francis, bisakah aku memercayaimu?)",
  ui_story_1012_10121402_99_dialog_content = "Neural Aux, luncurkan Chord of the Law menggunakan parameter yang ada!",
  ui_story_1012_10121402_100_dialog_content = "Siap.",
  ui_story_1012_10121402_101_dialog_content = "Menginisialisasi parameter peluncuran dari data historis.",
  ui_story_1012_10121402_102_dialog_content = "Menetapkan target: Eclipsite.",
  ui_story_1012_10121402_103_dialog_content = "Atur semua akses Eclipsites menjadi: Dihabisi.",
  ui_story_1012_10121402_104_dialog_content = "Menetapkan Law yang akan ditegakkan menjadi: <color=#FFB400>Menjauhi Obelisk of Return selamanya</color>",
  ui_story_1012_10121402_105_dialog_content = "Inisialisasi selesai.",
  ui_story_1012_10121402_106_dialog_content = "Meluncurkan Chord of the Law.",
  ui_story_1012_10121402_107_dialog_content = "Ada apa?",
  ui_story_1012_10121402_108_dialog_content = "Seluruh menara bersinar!",
  ui_story_1012_10121402_109_dialog_content = "Sudah fajar. Kita berhasil.",
  ui_story_1012_10121402_110_dialog_content = "Haha! Aku tahu dia pasti bisa!",
  ui_story_1012_10121402_111_dialog_content = "Bergerak, semuanya. Kita cari sudut pandang yang bagus.",
  ui_story_1012_10121402_112_dialog_content = "Di suatu tempat, kita bisa menikmati pertunjukannya.",
  ui_story_1012_10121402_113_dialog_content = "Hei, ada apa?",
  ui_story_1012_10121402_114_dialog_content = "Apa yang terjadi dengan menara itu?",
  ui_story_1012_10121402_115_dialog_content = "Tidak mungkin...",
  ui_story_1012_10121402_116_dialog_content = "Oh, tidak...",
  ui_story_1012_10121402_117_dialog_content = "...",
  ui_story_1012_10121402_118_dialog_content = "Gaah...",
  ui_story_1012_10121402_119_dialog_content = "Mengapa semua Eclipsite berhenti?",
  ui_story_1012_10121402_120_dialog_content = "Jangan mundur! Lanjutkan serangan!",
  ui_story_1012_10121402_121_dialog_content = "Musuh tidak bisa bertahan lebih lama lagi!",
  ui_story_1012_10121402_122_dialog_content = "Gaah...",
  ui_story_1012_10121402_123_dialog_content = "Sial!",
  ui_story_1012_10121402_124_dialog_content = "Lord Figerald, ini...",
  ui_story_1012_10121402_125_dialog_content = "Err... Ugh...",
  ui_story_1012_10121402_126_dialog_content = "Lord—Lord Figerald?",
  ui_story_1012_10121402_127_dialog_content = "Bagaimana ini... bisa...",
  ui_story_1012_10121402_128_dialog_content = "Lord Figerald, apakah pertarungan sudah selesai?",
  ui_story_1012_10121402_129_dialog_content = "...",
  ui_story_1012_10121402_130_dialog_content = "Mundur. Semuanya, mundur.",
  ui_story_1012_10121402_131_dialog_content = "Tapi, kenapa...?",
  ui_story_1012_10121402_132_dialog_content = "Karena aku bilang begitu! Mundur, paham?",
  ui_story_1012_10121402_133_dialog_content = "Ya, Lord.",
  ui_story_1012_10121402_134_dialog_content = "Mundur saja. Hanya itu yang bisa kita lakukan...",
  ui_story_1012_10121402_135_dialog_content = "Aku telah kehilangan semua hasrat untuk menyerang...",
  ui_story_1012_10121402_136_dialog_content = "Pikiranku terus memintaku untuk mundur.",
  ui_story_1012_10121402_137_dialog_content = "Apa pun yang kulakukan... Aku tidak bisa mengalahkan pikiranku sendiri.",
  ui_story_1012_10121402_138_dialog_content = "Mereka mundur. Para Eclipsite, mereka mundur!",
  ui_story_1012_10121402_139_dialog_content = "Aneh. Tidak masuk akal. Kenapa mereka berhenti, tepat ketika mereka akan menang?",
  ui_story_1012_10121402_140_dialog_content = "Apakah ada hubungannya dengan cahaya dari White Tower itu?",
  ui_story_1012_10121402_141_dialog_content = "Nanti kita tanya PlayerName, dia pasti tahu.",
  ui_story_1012_10121402_142_dialog_content = "Ahh. Pertempuran itu benar-benar melelahkan. Mungkin aku mau berbaring saja di rumput ini.",
  ui_story_1012_10121402_143_dialog_content = "Bukankah kita harus bersiap untuk serangan lain?",
  ui_story_1012_10121402_144_dialog_content = "Jumlah mereka masih banyak untuk membuat kita terkepung.",
  ui_story_1012_10121402_145_dialog_content = "Tenang saja. Kesempatan terbaik mereka adalah merebut menara sebelum semua tentara tiba di sini.",
  ui_story_1012_10121402_146_dialog_content = "Mereka hanya akan menjadi sasaran empuk jika bertahan, dan mereka tak sebodoh itu.",
  ui_story_1012_10121402_147_dialog_content = "Terima kasih atas pelajarannya, Grand Marshal.",
  ui_story_1012_10121402_148_dialog_content = "Beristirahatlah selagi bisa.",
  ui_story_1012_10121402_149_dialog_content = "Karena jika aku tidak salah, yang selanjutnya terjadi akan mempermudah pertempuran kita.",
  ui_story_1012_10121402_150_dialog_content = "Kita... Kita berhasil!",
  ui_story_1012_10121402_151_dialog_content = "Benarkah? Apa yang terjadi di luar?",
  ui_story_1012_10121402_152_dialog_content = "Semua Eclipsite mundur.",
  ui_story_1012_10121402_153_dialog_content = "Sepertinya mereka harus mematuhi hukum yang kita tegakkan:",
  ui_story_1012_10121402_154_dialog_content = "\"Menjauhi Obelisk of Return selamanya.\"",
  ui_story_1012_10121402_155_dialog_content = "Kau membuat Eclipsites mematuhi hukum yang kautetapkan?",
  ui_story_1012_10121402_156_dialog_content = "Itu... tidak bisa dipercaya!",
  ui_story_1012_10121402_157_dialog_content = "Aku bisa merasakan Chord of the Law bekerja. Benar-benar senjata yang cocok untuk Caelestite.",
  ui_story_1012_10121402_158_dialog_content = "Ia tidak menggunakan kekuatan. Ia hanya menanamkan ide tertentu di pikiran musuh.",
  ui_story_1012_10121402_159_dialog_content = "Ia mengubah pikiran orang, dan mencegah semua kekerasan.",
  ui_story_1012_10121402_160_dialog_content = "Kekuatan semacam itu... menakutkan.",
  ui_story_1012_10121402_161_dialog_content = "Hei, ada apa?",
  ui_story_1012_10121402_162_dialog_content = "Ruang pikiran ini mulai menjadi tidak stabil.",
  ui_story_1012_10121402_163_dialog_content = "Obelisk of Return kehabisan daya.",
  ui_story_1012_10121402_164_dialog_content = "Banyak komponen sekali pakai yang rusak akibat peluncuran Chord of the Law dan perlu segera diganti.",
  ui_story_1012_10121402_165_dialog_content = "Mencari staf pemeliharaan...",
  ui_story_1012_10121402_166_dialog_content = "Pencarian tidak berhasil.",
  ui_story_1012_10121402_167_dialog_content = "Jadi, dayanya sudah lemah.",
  ui_story_1012_10121402_168_dialog_content = "Kurasa kita cukup mujur ia bertahan cukup lama untuk menggunakan Chord of the Law.",
  ui_story_1012_10121402_169_dialog_content = "Kaui tidak demikian... Aku benci memikirkan tempat kita akan berada saat ini.",
  ui_story_1012_10121402_170_dialog_content = "Kurang energi untuk mempertahankan operasi.",
  ui_story_1012_10121402_171_dialog_content = "Obelisk of Return akan segera memasuki keheningan.",
  ui_story_1012_10121402_172_dialog_content = "Eh? Keheningan? Maksudmu?",
  ui_story_1012_10121402_173_dialog_content = "Semua peralatan akan berhenti beroperasi. Tidak ada fungsionalitas yang akan tersedia.",
  ui_story_1012_10121402_174_dialog_content = "Ia akan menjadi lebih hening daripada sebelum kedatanganmu.",
  ui_story_1012_10121402_175_dialog_content = "Aku tahu.",
  ui_story_1012_10121402_176_dialog_content = "Tunggu, Neural Aux, maksudmu kau tidak...",
  ui_story_1012_10121402_177_dialog_content = "Benar. Aku tidak akan bisa lagi melayani Caelestite.",
  ui_story_1012_10121402_178_dialog_content = "...",
  ui_story_1012_10121402_179_dialog_content = "Tapi, aku punya satu tugas terakhir untuk diselesaikan.",
  ui_story_1012_10121402_180_dialog_content = "Sebelum keheningan tiba, aku harus meneruskan pesan dari Master Francis.",
  ui_story_1012_10121402_181_dialog_content = "Master Francis?",
  ui_story_1012_10121402_182_dialog_content = "\"Untukmu, sesama Caelestite—\"",
  ui_story_1012_10121402_183_dialog_content = "\"Aku memilih untuk hanya mentransmisikan pesan ini pada saat-saat terakhir.\"",
  ui_story_1012_10121402_184_dialog_content = "\"Aku bukan orang yang menyukai petaka dan nestapa. Aku lebih memilih untuk merayakan kemenangan.\"",
  ui_story_1012_10121402_185_dialog_content = "\"Dan hanya mengetahui ada orang yang mendengarkan pesan ini membuatku senang.\"",
  ui_story_1012_10121402_186_dialog_content = "\"Sungguh ide yang aneh. Memikirkan bahwa seseorang yang jauh, seseorang yang bahkan belum ada, akan memenuhi keinginanku.\"",
  ui_story_1012_10121402_187_dialog_content = "\"Mungkin itu karena kita berada di jalan yang sama juga jarang dilalui.\"",
  ui_story_1012_10121402_188_dialog_content = "Kita berada di jalan yang sama? Bagaimana bisa?",
  ui_story_1012_10121402_189_dialog_content = "\"Mungkin kau tidak sepenuhnya memahami apa yang telah terjadi. Kau bahkan mungkin berpikir kau beruntung.\"",
  ui_story_1012_10121402_190_dialog_content = "\"Tapi, yang ingin kukatakan adalah: ingatlah, segala sesuatu terjadi karena suatu alasan.\"",
  ui_story_1012_10121402_191_dialog_content = "\"Energi habis tepat pada saat ini karena menara hanya bertahan hingga Chord of the Law berhasil diluncurkan.\"",
  ui_story_1012_10121402_192_dialog_content = "\"Itu adalah hadiahku untukmu.\"",
  ui_story_1012_10121402_193_dialog_content = "Hadiah?!",
  ui_story_1012_10121402_194_dialog_content = "\"Hadiah yang membantumu dalam pertarunganmu melawan Eclipsite.\"",
  ui_story_1012_10121402_195_dialog_content = "\"Hadiah yang membantumu terbebas dari batasan <color=#FFB400>dari lahir</color>.\"",
  ui_story_1012_10121402_196_dialog_content = "!!!",
  ui_story_1012_10121402_197_dialog_content = "\"Sudah waktunya.\"",
  ui_story_1012_10121402_198_dialog_content = "\"Jadi, akhirnya, aku berterima kasih kepadamu karena telah mengambil jalan ini.\"",
  ui_story_1012_10121402_199_dialog_content = "\"Masa lalu telah berlalu. Yang tersisa akan tetap ada...\"",
  ui_story_1012_10121402_200_dialog_content = "\"Selamat tinggal, Caelestite.\"",
  ui_story_1012_10121501_1_dialog_content = "Oh, sungguh melegakan—",
  ui_story_1012_10121501_2_dialog_content = "Eraveil, seperti yang kuingat.",
  ui_story_1012_10121501_3_dialog_content = "Selalu terlihat jauh lebih alami saat keadaan damai.",
  ui_story_1012_10121501_4_dialog_content = "Carleen, kau tampak lelah. Ini, pegang tanganku.",
  ui_story_1012_10121501_5_dialog_content = "Ah, aku tidak ingin dalam masalah...",
  ui_story_1012_10121501_6_dialog_content = "Ssst. PlayerName memberitahuku tentang kau yang membopongku saat aku kedinginan.",
  ui_story_1012_10121501_7_dialog_content = "Sekarang saatnya aku membalas budi!",
  ui_story_1012_10121501_8_dialog_content = "...",
  ui_story_1012_10121501_9_dialog_content = "Baiklah kalau begitu.",
  ui_story_1012_10121501_10_dialog_content = "Akhirnya, para pahlawan muncul!",
  ui_story_1012_10121501_11_dialog_content = "Pahlawan? Kau mengolok-olok aku?",
  ui_story_1012_10121501_12_dialog_content = "Haha, tentu saja tidak! Kalau dipikir—kau membalikkan alur pertempuran besar ini.",
  ui_story_1012_10121501_13_dialog_content = "Pertempuran yang tidak bisa dimenangkan oleh Grand Marshal Illumina dan Queen of the North sendiri.",
  ui_story_1012_10121501_14_dialog_content = "Tapi... itu bukan aku, 'kan?",
  ui_story_1012_10121501_15_dialog_content = "Yang kulakukan hanyalah...",
  ui_story_1012_10121501_16_dialog_content = "Itu adalah hadiahku untukmu.",
  ui_story_1012_10121501_17_dialog_content = "Yang kulakukan hanyalah menyelesaikan pekerjaan orang lain.",
  ui_story_1012_10121501_18_dialog_content = "Tidak usah terlalu berlebihan dalam sopan santun.",
  ui_story_1012_10121501_19_dialog_content = "Haha. Yah, kita semua berjuang keras, 'kan?",
  ui_story_1012_10121501_20_dialog_content = "Bukan aku. Melainkan kita. Kita semua membalikkan keadaan.",
  ui_story_1012_10121501_21_dialog_content = "Hmm... Aku tidak bisa menyangkalnya.",
  ui_story_1012_10121501_22_dialog_content = "Kemenangan milik kita semua. Kata-kata kesatria sejati!",
  ui_story_1012_10121501_23_dialog_content = "Ha, ya! Kemenangan milik kita semua.",
  ui_story_1012_10121501_24_dialog_content = "Aku suka caramu mengatakannya, Reinhardt.",
  ui_story_1012_10121501_25_dialog_content = "Tapi, ingat, kau tetap istimewa.",
  ui_story_1012_10121501_26_dialog_content = "Titik awal kita, kunci kita, panji kita. Hal yang membawa perubahan.",
  ui_story_1012_10121501_27_dialog_content = "Itu bukan pujian, melainkan peringatan.",
  ui_story_1012_10121501_28_dialog_content = "Jangan lupa, menjadi istimewa adalah hal yang menakutkan.",
  ui_story_1012_10121501_29_dialog_content = "Tidak akan.",
  ui_story_1012_10121501_30_dialog_content = "Kau kembali.",
  ui_story_1012_10121501_31_dialog_content = "Yang Mulia Ratu!",
  ui_story_1012_10121501_32_dialog_content = "Kau selalu begitu tenang, baik sekarang maupun di medan perang.",
  ui_story_1012_10121501_33_dialog_content = "Meskipun kukira kau melihat hasilnya lebih dulu.",
  ui_story_1012_10121501_34_dialog_content = "...",
  ui_story_1012_10121501_35_dialog_content = "Faktanya, kali ini aku tidak mengetahuinya.",
  ui_story_1012_10121501_36_dialog_content = "Oh?",
  ui_story_1012_10121501_37_dialog_content = "Aku tidak melihat masa depan kau membalikkan jalannya pertempuran.",
  ui_story_1012_10121501_38_dialog_content = "Aku hanya melihatmu pergi untuk melakukan sesuatu.",
  ui_story_1012_10121501_39_dialog_content = "Jadi, kau...",
  ui_story_1012_10121501_40_dialog_content = "...",
  ui_story_1012_10121501_41_dialog_content = "Dan aku yakin kau akan berhasil.",
  ui_story_1012_10121501_42_dialog_content = "Yang Mulia...",
  ui_story_1012_10121501_43_dialog_content = "Kuharap aku tidak mengecewakanmu!",
  ui_story_1012_10121501_44_dialog_content = "Perhatikan Eraveil. Di situlah jawabanmu.",
  ui_story_1012_10121501_45_dialog_content = "Masih ada satu pertanyaan yang harus kaujawab, PlayerName.",
  ui_story_1012_10121501_46_dialog_content = "Bagaimana kau melakukannya?",
  ui_story_1012_10121501_47_dialog_content = "Para Eclipsite tiba-tiba menghentikan serangan mereka di menara dan kabur seperti anjing.",
  ui_story_1012_10121501_48_dialog_content = "Kau bilang sesuatu tentang \"senjata pemungkas\", tetapi aku tidak melihat apa pun.",
  ui_story_1012_10121501_49_dialog_content = "Sejujurnya, aku sendiri tidak terlalu yakin.",
  ui_story_1012_10121501_50_dialog_content = "Rasanya itu lebih semacam senjata mental.",
  ui_story_1012_10121501_51_dialog_content = "Senjata ini tidak menyerang musuh secara fisik, tetapi secara pikiran.",
  ui_story_1012_10121501_52_dialog_content = "Ia memasukkan perintah ke dalam kepala mereka: menjauh dari Obelisk of Return. Nyatanya mereka melakukannya.",
  ui_story_1012_10121501_53_dialog_content = "Pengendali pikiran? Aku tidak pernah tahu kemungkinan adanya senjata seperti itu.",
  ui_story_1012_10121501_54_dialog_content = "Aku tahu. Bagiku juga aneh.",
  ui_story_1012_10121501_55_dialog_content = "Ini luar biasa. Apa arti senjata seperti itu bagi dunia? Bagaimana cara kerjanya, dan kekuatan apa yang dimilikinya?",
  ui_story_1012_10121501_56_dialog_content = "Ini bisa lebih buruk daripada Eclipse.",
  ui_story_1012_10121501_57_dialog_content = "Yah, soal itu... Kurasa kita tidak perlu terlalu khawatir.",
  ui_story_1012_10121501_58_dialog_content = "Senjata itu sudah tidak ada.",
  ui_story_1012_10121501_59_dialog_content = "Apa?",
  ui_story_1012_10121501_60_dialog_content = "Menara hanya menyimpan energi untuk mengaktifkan senjata satu kali.",
  ui_story_1012_10121501_61_dialog_content = "Kini, baik senjata maupun menara itu sendiri telah masuk ke dalam keheningan.",
  ui_story_1012_10121501_62_dialog_content = "Keduanya tidak pernah menjadi bagian dari masa kita. Keduanya ada di sini, untuk memenuhi sebuah keinginan.",
  ui_story_1012_10121501_63_dialog_content = "Ketika senjata itu ditembakkan, senjata dan menara kembali ke keadaan asal, tugasnya telah selesai.",
  ui_story_1012_10121501_64_dialog_content = "Kini keduanya akan tetap di sini, sebagai saksi bisu.",
  ui_story_1012_10121501_65_dialog_content = "Oh, begitu…",
  ui_story_1012_10121501_66_dialog_content = "Aneh. Aku hampir merasakan ketertarikan pada senjata itu.",
  ui_story_1012_10121501_67_dialog_content = "Mungkin karena itu bukan sekadar senjata.",
  ui_story_1012_10121501_68_dialog_content = "Itu adalah <color=#FFB400>hadiah</color>.",
  ui_story_1012_10121501_69_dialog_content = "<color=#e8d9bb>Gruduk... Gruduk... Gruduk...</color>",
  ui_story_1012_10121501_70_dialog_content = "Haa... haa... akhirnya, berhenti juga.",
  ui_story_1012_10121501_71_dialog_content = "Jadi, ini... Eraveil?",
  ui_story_1012_10121501_72_dialog_content = "Sekarang, kenapa Lepidoz datang ke Eraveil?",
  ui_story_1012_10121501_73_dialog_content = "Sebentar... sejak kapan Eraveil punya menara seperti itu?",
  ui_story_1012_10121501_74_dialog_content = "Ah-ha, sepertinya kita memiliki pendatang baru yang tampak meragukan.",
  ui_story_1012_10121501_75_dialog_content = "Tidak menyangka Rediesel Wrench muncul begitu cepat.",
  ui_story_1012_10121501_76_dialog_content = "Grand Marshal Illumina!",
  ui_story_1012_10121501_77_dialog_content = "Apa yang kaulakukan di Eraveil?",
  ui_story_1012_10121501_78_dialog_content = "Percaya atau tidak, kami baru saja bertempur.",
  ui_story_1012_10121501_79_dialog_content = "Bertempur?",
  ui_story_1012_10121501_80_dialog_content = "*Endus...*",
  ui_story_1012_10121501_81_dialog_content = "Benar juga, aku bisa mencium bau pertempuran.",
  ui_story_1012_10121501_82_dialog_content = "Tapi, sungguh, pertempuran?",
  ui_story_1012_10121501_83_dialog_content = "Apa? Kau tidak percaya kami?",
  ui_story_1012_10121501_84_dialog_content = "Yah, kau tahu apa yang mereka bilang soal memercayai Illumina...",
  ui_story_1012_10121501_85_dialog_content = "Tapi, di sini cukup ramai. Begitu banyak tokoh terkenal berkumpul di satu tempat.",
  ui_story_1012_10121501_86_dialog_content = "Queen of the North dan aku datang untuk bertarung.",
  ui_story_1012_10121501_87_dialog_content = "Begini, ketika PlayerName mengadakan pesta, semua orang datang.",
  ui_story_1012_10121501_88_dialog_content = "Jadi, di sini ada kau, Queen of the North, dan... siapa itu?",
  ui_story_1012_10121501_89_dialog_content = "Siapa itu?",
  ui_story_1012_10121501_90_dialog_content = "Yang tampangnya angkuh di belakangmu itu.",
  ui_story_1012_10121501_91_dialog_content = "!!!",
  ui_story_1012_10121501_92_dialog_content = "...",
  ui_story_1012_10121501_93_dialog_content = "Victoria! Kapan kau...",
  ui_story_1012_10121501_94_dialog_content = "Jangan pedulikan aku.",
  ui_story_1012_10121501_95_dialog_content = "Aku di sini hanya untuk menikmati pertunjukan.",
  ui_story_1012_10121501_96_dialog_content = "Sulit dipercaya bahkan kau muncul juga.",
  ui_story_1012_10121501_97_dialog_content = "<color=#e8d9bb>Drap, drap, drap</color>",
  ui_story_1012_10121501_98_dialog_content = "Berhenti!",
  ui_story_1012_10121501_99_dialog_content = "Bentuk perimeter!",
  ui_story_1012_10121501_100_dialog_content = "Siap, Pak!",
  ui_story_1012_10121501_101_dialog_content = "Esien, akhirnya.",
  ui_story_1012_10121501_102_dialog_content = "Tapi, secara tradisional, bala bantuan tiba selama pertempuran.",
  ui_story_1012_10121501_103_dialog_content = "Maafkan aku, Grand Marshal, tetapi kami tidak dikirim sebagai bala bantuan.",
  ui_story_1012_10121501_104_dialog_content = "Lalu... untuk apa kalian kemari?",
  ui_story_1012_10121501_105_dialog_content = "Maaf, Grand Marshal. Detail misi hanya diungkapkan kepada orang yang berhak tahu, dan kau tidak berhak.",
  ui_story_1012_10121501_106_dialog_content = "Aku tidak berhak tahu?!",
  ui_story_1012_10121501_107_dialog_content = "Terakhir kali kuperiksa, aku masih Grand Marshal Illumina, bukan?",
  ui_story_1012_10121501_108_dialog_content = "Benar, kau memang menjabat posisi militer itu.",
  ui_story_1012_10121501_109_dialog_content = "Tapi, kau tidak memiliki otoritas di luar medan perang.",
  ui_story_1012_10121501_110_dialog_content = "...",
  ui_story_1012_10121501_111_dialog_content = "Sekarang aku paham. Ini ulah Committee lagi, ya?",
  ui_story_1012_10121501_112_dialog_content = "Kami pamit dulu.",
  ui_story_1012_10121501_113_dialog_content = "Grand Marshal... Mereka...",
  ui_story_1012_10121501_114_dialog_content = "Jangan pedulikan mereka.",
  ui_story_1012_10121501_115_dialog_content = "Politisi memegang kekuasaan lebih dari Grand Marshal di dunia nyata.",
  ui_story_1012_10121501_116_dialog_content = "Haruskah aku memperhatikan itu?",
  ui_story_1012_10121501_117_dialog_content = "Tidak, aku hanya mengeluh.",
  ui_story_1012_10121501_118_dialog_content = "Di sana. Skuad lain datang kemari.",
  ui_story_1012_10121501_119_dialog_content = "Burung-burung bangkai itu... Mereka tidak tertarik pada pertempuran, tetapi bersedia saling bertarung sampai mati demi memperebutkan mayat.",
  ui_story_1012_10121501_120_dialog_content = "Lord, Illumina sedang bergerak.",
  ui_story_1012_10121501_121_dialog_content = "Apakah kita hanya akan duduk di sini dan menunggu?",
  ui_story_1012_10121501_122_dialog_content = "Bersabarlah.",
  ui_story_1012_10121501_123_dialog_content = "Ini masalah serius. Alangkah bijaksananya bagi kita untuk mempertimbangkan konsekuensi buruknya sebelum bertindak.",
  ui_story_1012_10121501_124_dialog_content = "Yang dibutuhkan Lumopolis adalah mempertahankan ketertiban, bukan masalah mencuat.",
  ui_story_1012_10121501_125_dialog_content = "Siap, Pak!",
  ui_story_1012_10121501_126_dialog_content = "Aku tahu Lord Schwartz telah tiba ketika kulihat semua orang ini datang membanjiri.",
  ui_story_1012_10121501_127_dialog_content = "Lumopolis benar-benar tahu cara menjadi pahlawan kesiangan.",
  ui_story_1012_10121501_128_dialog_content = "Reinhardt, Illumina dan Lumopolis melakukan hal yang berbeda. Kenapa kau sarkastis?",
  ui_story_1012_10121501_129_dialog_content = "Simpan tenagamu untuk masalah yang ada.",
  ui_story_1012_10121501_130_dialog_content = "Masalah yang ada? Kau tidak mencium bau asap di udara? Ini sudah selesai.",
  ui_story_1012_10121501_131_dialog_content = "Lihat, bahkan para pedagang sudah ada di sini. Bisnis adalah masalah yang ada saat ini, bukan? Hahaha!",
  ui_story_1012_10121501_132_dialog_content = "Pedagang mendapatkan lebih dari keuntungan di tangan mereka.",
  ui_story_1012_10121501_133_dialog_content = "Dan aku bukan pedagang biasa.",
  ui_story_1012_10121501_134_dialog_content = "Melainkan juga bayangan yang mengikuti Lumopolis, 'kan?",
  ui_story_1012_10121501_135_dialog_content = "Itulah cara hidup kami. Ada yang ingin kaukatakan, Grand Marshal?",
  ui_story_1012_10121501_136_dialog_content = "Cukup. Semua orang tahu kita berkumpul di sini karena kita semua merasakan guncangan dari peristiwa tersebut.",
  ui_story_1012_10121501_137_dialog_content = "Kita harus menyadari apa yang sedang terjadi dan apa artinya bagi masa depan.",
  ui_story_1012_10121501_138_dialog_content = "Grand Marshal, bersediakah kau menunjukkan jalannya kepada kami?",
  ui_story_1012_10121501_139_dialog_content = "Dengan senang hati. Silakan ikuti aku.",
  ui_story_1012_10121501_140_dialog_content = "Ada banyak tokoh besar... Apa yang mereka rencanakan?",
  ui_story_1012_10121501_141_dialog_content = "Sepertinya kebangkitan Obelisk of Return menimbulkan lebih banyak kekhawatiran daripada yang kita bayangkan.",
  ui_story_1012_10121501_142_dialog_content = "Mereka ingin tahu apa yang sebenarnya terjadi di sini, dan...",
  ui_story_1012_10121501_143_dialog_content = "Cara menangani menara ini.",
  ui_story_1012_10121501_144_dialog_content = "Menangani... menara ini...",
  ui_story_1012_10121501_145_dialog_content = "Maafkan aku. Aku tahu ini terdengar tidak menyenangkan.",
  ui_story_1012_10121501_146_dialog_content = "Menara ini... seharusnya menjadi milikmu.",
  ui_story_1012_10121501_147_dialog_content = "Tak apa. Aku paham.",
  ui_story_1012_10121501_148_dialog_content = "Kita harus mengesampingkan perasaan pribadi dalam hal-hal yang menyangkut dunia.",
  ui_story_1012_10121501_149_dialog_content = "PlayerName…",
  ui_story_1012_10121501_150_dialog_content = "PlayerName! Kenapa berdiri di samping?",
  ui_story_1012_10121501_151_dialog_content = "Umm... Anu...",
  ui_story_1012_10121501_152_dialog_content = "Kemarilah! Grand Marshal menanyakanmu.",
  ui_story_1012_10121501_153_dialog_content = "Menanyakan aku?",
  ui_story_1012_10121501_154_dialog_content = "Ya. Mereka semua menunggumu. Ayo!",
  ui_story_1012_10121501_155_dialog_content = "B-baiklah...",
  ui_story_1012_10121501_156_dialog_content = "Tunggu!",
  ui_story_1012_10121501_157_dialog_content = "PlayerName, hati-hati.",
  ui_story_1012_10121501_158_dialog_content = "Apa pun yang kaukatakan, jangan beri tahu mereka soal pandangan Caelestite kuno.",
  ui_story_1012_10121501_159_dialog_content = "Grand Marshal. PlayerName sudah datang.",
  ui_story_1012_10121501_160_dialog_content = "Bagus. Tower Master sudah ada di sini. Sekarang, kita akhirnya bisa mulai.",
  ui_story_1012_10121501_161_dialog_content = "Tower Master?!",
  ui_story_1012_10121501_162_dialog_content = "Kau adalah Caelestite terakhir, dan, logikanya, master dari Obelisk of Return.",
  ui_story_1012_10121501_163_dialog_content = "Baik Queen dan aku bersikeras agar kau hadir dalam pembicaraan ini.",
  ui_story_1012_10121501_164_dialog_content = "Dengan... semua penguasa?",
  ui_story_1012_10121501_165_dialog_content = "Tak ada yang perlu ditakutkan. Kau memang berpartisipasi dalam White Night Celebration, bukan?",
  ui_story_1012_10121501_166_dialog_content = "Kau memiliki lebih banyak otoritas dalam hal Obelisk of Return daripada siapa pun di sini.",
  ui_story_1012_10121501_167_dialog_content = "Katakan saja apa yang ada di pikiranmu. Jangan biarkan status atau jabatan siapa pun di sini menghentikanmu.",
  ui_story_1012_10121501_168_dialog_content = "Baiklah, oke…",
  ui_story_1012_10121501_169_dialog_content = "Kami adalah orang-orang yang tinggal dalam kegelapan.",
  ui_story_1012_10121501_170_dialog_content = "Mungkin kaulah satu-satunya orang yang bisa memandu kami menuju masa depan.",
  ui_story_1012_10121501_171_dialog_content = "Pertama-tama, bagaimana kalian semua memandang Tower ini?",
  ui_story_1012_10121501_172_dialog_content = "Bagi kami, tanpa diragukan lagi, ini adalah ancaman maut bagi Lumopolis.",
  ui_story_1012_10121501_173_dialog_content = "Damocles mengaktifkan dirinya sendiri... Ini tak terduga.",
  ui_story_1012_10121501_174_dialog_content = "Selain itu, ia menunjuk ke arah kita, jadi kami harus menghancurkan menara.",
  ui_story_1012_10121501_175_dialog_content = "(Damocles mengaktifkan dirinya sendiri. Ya, aku memang melihatnya.)",
  ui_story_1012_10121501_176_dialog_content = "Illumina setuju dengan itu.",
  ui_story_1012_10121501_177_dialog_content = "Relik kuno di Gannon juga membunyikan peringatan. Itu disebabkan oleh pergerakan di sini.",
  ui_story_1012_10121501_178_dialog_content = "Jelas, Obelisk of Return dianggap musuh oleh pembangun Gannon City.",
  ui_story_1012_10121501_179_dialog_content = "(Ini gawat. Mereka semua memperlakukanku sebagai musuh.)",
  ui_story_1012_10121501_180_dialog_content = "Aku setuju.",
  ui_story_1012_10121501_181_dialog_content = "Pada masa kuno, Obelisk of Return adalah sesuatu yang ditakuti para Aurorian.",
  ui_story_1012_10121501_182_dialog_content = "!!!",
  ui_story_1012_10121501_183_dialog_content = "Karena kita semua sudah sepakat, aku mengusulkan agar kita menghancurkan atau menguburnya.",
  ui_story_1012_10121501_184_dialog_content = "Sesuatu yang seharusnya tidak ada harus ditiadakan.",
  ui_story_1012_10121501_185_dialog_content = "Tidak mungkin! Yang kaubicarakan itu menara besar, lo!",
  ui_story_1012_10121501_186_dialog_content = "Relik kuno yang dimilikinya saja bisa menghasilkan banyak uang!",
  ui_story_1012_10121501_187_dialog_content = "Dan kita bisa belajar dan merekayasa balik teknologinya untuk membantu rakyat!",
  ui_story_1012_10121501_188_dialog_content = "Kalian para keluarga kerajaan benar-benar tidak tahu betapa sulitnya hidup bagi rakyat jelata di luar sana.",
  ui_story_1012_10121501_189_dialog_content = "Kita hadir di sini bukan untuk membicarakan kebutuhan sipil.",
  ui_story_1012_10121501_190_dialog_content = "Kami Illumina juga tidak percaya Obelisk of Return harus dihancurkan.",
  ui_story_1012_10121501_191_dialog_content = "Dengan mengesampingkan syak wasangka kita, menara ini adalah fasilitas dengan nilai militer yang hebat.",
  ui_story_1012_10121501_192_dialog_content = "Kita harus mempelajarinya, bukan menghancurkannya gara-gara takut.",
  ui_story_1012_10121501_193_dialog_content = "Untuk dipelajari oleh Illumina? Apa jaminannya kau akan memberikan hasil yang baik?",
  ui_story_1012_10121501_194_dialog_content = "Bolehkah aku mengingatkanmu bahwa catatanmu jauh dari kata bersih?",
  ui_story_1012_10121501_195_dialog_content = "Hei... Kalian tenang saja.",
  ui_story_1012_10121501_196_dialog_content = "Lihat di sekitarmu. Menara ini hanyalah tumpukan batu.",
  ui_story_1012_10121501_197_dialog_content = "Tidak ada alat yang berfungsi atau Lumina yang mengalir.",
  ui_story_1012_10121501_198_dialog_content = "Maksudmu, kalian semua takut bebatuan?",
  ui_story_1012_10121501_199_dialog_content = "Batu yang entah berfungsi untuk apa. Siapa bilang bebatuan itu tidak akan tiba-tiba mulai aktif lagi?",
  ui_story_1012_10121501_200_dialog_content = "A-anu...",
  ui_story_1012_10121501_201_dialog_content = "Aku bisa jamin energi Obelisk of Return sudah habis sepenuhnya.",
  ui_story_1012_10121501_202_dialog_content = "Seperti yang dikatakan Grand Marshal, kini itu hanyalah tumpukan batu.",
  ui_story_1012_10121501_203_dialog_content = "Batu yang menyimpan catatan sejarah kita.",
  ui_story_1012_10121501_204_dialog_content = "...",
  ui_story_1012_10121501_205_dialog_content = "Itu adalah jaminan besar atas namamu, Caelestite. Kau yakin bisa menjaminnya?",
  ui_story_1012_10121501_206_dialog_content = "Aku…",
  ui_story_1012_10121501_207_dialog_content = "Lord, aku bisa menjamin dia.",
  ui_story_1012_10121501_208_dialog_content = "Carleen?",
  ui_story_1012_10121501_209_dialog_content = "PlayerName dan aku telah sepenuhnya menjelajahi menara itu.",
  ui_story_1012_10121501_210_dialog_content = "Aku bisa jamin menara itu tidak lagi berfungsi.",
  ui_story_1012_10121501_211_dialog_content = "...",
  ui_story_1012_10121501_212_dialog_content = "Lihat? Tidak perlu tegang.",
  ui_story_1012_10121501_213_dialog_content = "Bagi dunia saat ini, menara ini bukan lagi ancaman, melainkan sebuah harta karun kuno.",
  ui_story_1012_10121501_214_dialog_content = "Dulunya milik Caelestite, dan seharusnya tetap begitu.",
  ui_story_1012_10121501_215_dialog_content = "Hm?",
  ui_story_1012_10121501_216_dialog_content = "Aku yakin PlayerName adalah pemilik sah menara itu sekarang.",
  ui_story_1012_10121501_217_dialog_content = "Kita membutuhkan izin dan persetujuan darinya tentang cara kita menangani barang-barang di menara.",
  ui_story_1012_10121501_218_dialog_content = "Aku yakin PlayerName akan setuju dengan penelitian apa pun yang bisa bermanfaat bagi kita semua.",
  ui_story_1012_10121501_219_dialog_content = "Dan PlayerName berhak untuk menolak penelitian apa pun yang dapat menyebabkan potensi berbahaya.",
  ui_story_1012_10121501_220_dialog_content = "Izinkan aku mengklarifikasi sesuatu terlebih dahulu.",
  ui_story_1012_10121501_221_dialog_content = "Grand Marshal berbicara untuk dirinya sendiri. Pendapatnya tidak mewakili pendapat Illumina dengan cara apa pun.",
  ui_story_1012_10121501_222_dialog_content = "Oh? Lalu apa sikap Illumina dalam hal ini?",
  ui_story_1012_10121501_223_dialog_content = "Illumina bersikeras untuk mempelajari semua hal di Obelisk of Return.",
  ui_story_1012_10121501_224_dialog_content = "Menara itu seharusnya bukan milik siapa pun.",
  ui_story_1012_10121501_225_dialog_content = "Duh... Kalian ini...",
  ui_story_1012_10121501_226_dialog_content = "Aku setuju dengan Reinhardt.",
  ui_story_1012_10121501_227_dialog_content = "PlayerName adalah pemilik sah Obelisk of Return.",
  ui_story_1012_10121501_228_dialog_content = "Queen Bethlehem...",
  ui_story_1012_10121501_229_dialog_content = "Kita semua pernah berjuang untuk melindungi negeri kita. Tidak ada alasan yang lebih layak untuk dihormati selain ini.",
  ui_story_1012_10121501_230_dialog_content = "Dan Caelestite berjuang untuk melindungi tempat ini sekarang, seperti halnya kita.",
  ui_story_1012_10121501_231_dialog_content = "Jika kepemilikan rumah leluhur mereka ditentukan oleh orang lain, perang akan kalah.",
  ui_story_1012_10121501_232_dialog_content = "Baik Aurorian maupun Eclipsite semuanya adalah orang luar bagi Caelestite.",
  ui_story_1012_10121501_233_dialog_content = "Jika kita menyebut Caelestite sekutu kita, kita sebagai Aurorian harus menghormati sekutu kita dengan tidak menyerang Eraveil.",
  ui_story_1012_10121501_234_dialog_content = "Yang Mulia...",
  ui_story_1012_10121501_235_dialog_content = "Sementara kekhawatiran Lord Schwartz, kuanggap itu tidak berdasar.",
  ui_story_1012_10121501_236_dialog_content = "Senjata pada dasarnya tidak baik atau buruk. Itu tergantung oleh orang yang memegang pelatuk.",
  ui_story_1012_10121501_237_dialog_content = "Seperti yang telah kita semua saksikan, PlayerName menggunakan Obelisk of Return untuk mencegah perang ini.",
  ui_story_1012_10121501_238_dialog_content = "Caelestite telah menunjukkan kepada kita semua posisi yang diambil Obelisk of Return.",
  ui_story_1012_10121501_239_dialog_content = "...",
  ui_story_1012_10121501_240_dialog_content = "Jarang melihatmu mengungkapkan pendapatmu seperti ini, Queen Bethlehem.",
  ui_story_1012_10121501_241_dialog_content = "Seberapa penting ini bagimu?",
  ui_story_1012_10121501_242_dialog_content = "Caelestite adalah sekutu penting bagi Aurorian.",
  ui_story_1012_10121501_243_dialog_content = "Oh, begitu…",
  ui_story_1012_10121501_244_dialog_content = "Lebih baik aku tidak berkata lebih banyak, atau seseorang akan menganggapku konservatif.",
  ui_story_1012_10121501_245_dialog_content = "Queen of the North telah membuat pendiriannya, dan aku menghormati keputusannya.",
  ui_story_1012_10121501_246_dialog_content = "Lumopolis tidak akan lagi mengganggu hal-hal yang berkaitan dengan penanganan Obelisk of Return.",
  ui_story_1012_10121501_247_dialog_content = "Apa kata kalian semua?",
  ui_story_1012_10121501_248_dialog_content = "Jika itu masalahnya, aku setuju.",
  ui_story_1012_10121501_249_dialog_content = "Sekarang, bukankah itu bagus? Aku tidak punya pendapat lain!",
  ui_story_1012_10121501_250_dialog_content = "...",
  ui_story_1012_10121501_251_dialog_content = "Aku telah menjelaskan posisi Illumina, dan aku tidak akan mengomentari semua keputusan kalian.",
  ui_story_1012_10121501_252_dialog_content = "Sepertinya kita sudah mencapai kesepakatan.",
  ui_story_1012_10121501_253_dialog_content = "Bagaimanapun, perang telah berakhir, dan kita semua bisa menikmati kedamaian sedikit lebih lama...",
  ui_story_1012_10121501_254_dialog_content = "Sampai perang berikutnya terjadi. Kedamaian tidak pernah bertahan lama, tetapi setidaknya kita bisa memanfaatkannya sebaik mungkin.",
  ui_story_1012_10121501_255_dialog_content = "Sementara kau, PlayerName, selamat atas trofimu.",
  ui_story_1012_10121501_256_dialog_content = "Sebuah rumah sejati.",
  ui_story_1012_10121501_257_dialog_content = "...",
  ui_story_1012_10121501_258_dialog_content = "Ehhh...",
  ui_story_1012_10121501_259_dialog_content = "Sebuah rumah sejati...",
  ui_story_1012_10121501_260_dialog_content = "Kenapa kau menarik napas dalam?",
  ui_story_1012_10121501_261_dialog_content = "Y-Yang Mulia!",
  ui_story_1012_10121501_262_dialog_content = "Kenapa kau di sini?",
  ui_story_1012_10121501_263_dialog_content = "Dari raut mukamu kau dalam masalah.",
  ui_story_1012_10121501_264_dialog_content = "Haha... Kau memang sangat jeli.",
  ui_story_1012_10121501_265_dialog_content = "Hmm…",
  ui_story_1012_10121501_266_dialog_content = "Aku sedikit bingung... Aku hanya tidak mengerti.",
  ui_story_1012_10121501_267_dialog_content = "Karena pertempuran?",
  ui_story_1012_10121501_268_dialog_content = "Tidak juga. Aku...",
  ui_story_1012_10121501_269_dialog_content = "Aku di sini jika kau membutuhkan teman untuk mendengarkan.",
  ui_story_1012_10121501_270_dialog_content = "Bukan sebagai Queen of the North, melainkan sebagai diriku.",
  ui_story_1012_10121501_271_dialog_content = "Sebagai... dirimu...",
  ui_story_1012_10121501_272_dialog_content = "Terima kasih... Aku benar-benar membutuhkan seseorang untuk diajak bicara.",
  ui_story_1012_10121501_273_dialog_content = "Lanjutkan. Aku tidak pergi ke mana-mana.",
  ui_story_1012_10121501_274_dialog_content = "Aku... Kami melihat sesuatu di bawah sana... Mengenai sejarah Caelestite.",
  ui_story_1012_10121501_275_dialog_content = "Catatan yang tersisa di Obelisk of Return hanya ada setengah-setengah, tetapi aku melihat...",
  ui_story_1012_10121501_276_dialog_content = "Aku melihat bagaimana Caelestite bertarung dengan Eclipsite...",
  ui_story_1012_10121501_277_dialog_content = "Artinya... Pada masa kuno, Caelestite mungkin bersekutu dengan Eclipsite.",
  ui_story_1012_10121501_278_dialog_content = "Caelestite dan Eclipsite?",
  ui_story_1012_10121501_279_dialog_content = "Ya... Aku melihat mereka bekerja sama.",
  ui_story_1012_10121501_280_dialog_content = "Aku tidak tahu cara menggambarkan apa yang kurasakan kepadamu...",
  ui_story_1012_10121501_281_dialog_content = "Aku tidak punya bukti nyata, tetapi aku yakin itu benar-benar terjadi.",
  ui_story_1012_10121501_282_dialog_content = "Bahkan setelah pertempuran, aku masih tidak bisa memercayainya... Aku...",
  ui_story_1012_10121501_283_dialog_content = "Kurasa aku tidak bisa menanganinya.",
  ui_story_1012_10121501_284_dialog_content = "Kau baik-baik saja, PlayerName?",
  ui_story_1012_10121501_285_dialog_content = "Rasanya kepalaku mau meledak. Aku menyesal tidak ada yang bisa kutunjukkan kepadamu.",
  ui_story_1012_10121501_286_dialog_content = "Apa yang kaulihat belum tentu sepenuhnya benar. Selain itu, kita tidak memiliki catatan aliansi antara Caelestite dan Eclipsite.",
  ui_story_1012_10121501_287_dialog_content = "Berani sumpah, aku melihat Caelestite dan Eclipsite menyerang Aurorian!",
  ui_story_1012_10121501_288_dialog_content = "Perasaan itu... bukan ilusi sederhana.",
  ui_story_1012_10121501_289_dialog_content = "Aku ingin itu menjadi ilusi... Aku benar-benar menginginkannya.",
  ui_story_1012_10121501_290_dialog_content = "Andai itu benar, bukankah Novio akan tahu? Dia sudah hidup untuk waktu yang lama, tetapi tidak pernah bilang apa-apa soal itu.",
  ui_story_1012_10121501_291_dialog_content = "Ya, dan aku tidak bisa menemukan apa pun yang berkaitan dengan apa yang kulihat di catatan sejarah di Soroz.",
  ui_story_1012_10121501_292_dialog_content = "Setahuku, baik Lumopolis maupun Illumina tidak memiliki bukti tentang ini... Jika tidak...",
  ui_story_1012_10121501_293_dialog_content = "Jika tidak, \"sekutu Eclipsite\" sepertiku pasti akan... Hehe...",
  ui_story_1012_10121501_294_dialog_content = "Biar kuberi tahu kau apa yang kami temukan, dari awal...",
  ui_story_1012_10121501_295_dialog_content = "... Itu saja.",
  ui_story_1012_10121501_296_dialog_content = "...",
  ui_story_1012_10121501_297_dialog_content = "Pertama-tama, terlepas dari semua yang telah kaulihat, fragmennya masih jauh dari kata cukup untuk menarik kesimpulan.",
  ui_story_1012_10121501_298_dialog_content = "Kedua, meski itu benar-benar terjadi, itu pasti pada masa kuno.",
  ui_story_1012_10121501_299_dialog_content = "Bahkan, mungkin sangat kuno sampai-sampai nenek moyangmu tidak menyadarinya.",
  ui_story_1012_10121501_300_dialog_content = "Maksudmu... jauh lebih kuno dari sejarah Northland?",
  ui_story_1012_10121501_301_dialog_content = "Aurorian juga hanya memiliki potongan-potongan sejarah kuno kita. Sebagian besarnya tidak kita ketahui.",
  ui_story_1012_10121501_302_dialog_content = "Tapi, dalam catatan sejarah apa pun yang kita miliki, Caelestite selalu menjadi teman Aurorian.",
  ui_story_1012_10121501_303_dialog_content = "Kedua kaum kita bertempur bersama melawan Eclipsite. Itu tidak pernah berubah.",
  ui_story_1012_10121501_304_dialog_content = "Bukankah orang-orangmu juga dihancurkan oleh Eclipsite?",
  ui_story_1012_10121501_305_dialog_content = "Ya... Itu sebabnya aku tidak bisa mengetahuinya. Aku hanya ingin tahu apa yang sebenarnya terjadi.",
  ui_story_1012_10121501_306_dialog_content = "Tapi... andai Caelestite dan Eclipsite benar-benar...",
  ui_story_1012_10121501_307_dialog_content = "Meski demikian, bagaimana sesuatu yang begitu jauh dan kuno memengaruhimu hari ini?",
  ui_story_1012_10121501_308_dialog_content = "Aku kepikiran... Jika Caelestite benar-benar bersekutu dengan Eclipsite...",
  ui_story_1012_10121501_309_dialog_content = "Lalu apa yang telah kupelajari sejak kecil, segala sesuatu tentang sejarah dan keyakinan kita... semuanya akan menjadi dusta.",
  ui_story_1012_10121501_310_dialog_content = "Apa yang akan orang-orangku pikirkan jika mereka melihat apa yang kulihat...?",
  ui_story_1012_10121501_311_dialog_content = "Andai itu benar... Caelestite... akan sangat hina.",
  ui_story_1012_10121501_312_dialog_content = "Meskipun Caelestite dan Aurorian berbagi pandangan yang berbeda dalam banyak hal, Caelestite selalu dikenal mendukung perdamaian dan merangkul alam.",
  ui_story_1012_10121501_313_dialog_content = "Tentu saja, ada hal-hal yang belum kita pahami, tetapi kau...",
  ui_story_1012_10121501_314_dialog_content = "Aku berpikir... Aku bisa sampai sejauh ini dengan memercayai Caelestite. Jika apa yang kuyakini adalah sebuah kebohongan...",
  ui_story_1012_10121501_315_dialog_content = "Lalu... apakah aku ini...?",
  ui_story_1012_10121501_316_dialog_content = "Kau Caelestite paling berani dan tangguh yang pernah kukenal, PlayerName.",
  ui_story_1012_10121501_317_dialog_content = "Eh... Kepalaku pusing kayak mau meledak.",
  ui_story_1012_10121501_318_dialog_content = "PlayerName, jika Caelestite benar-benar sekutu Eclipsite, apakah kau akan bersekutu dengan Eclipsite?",
  ui_story_1012_10121501_319_dialog_content = "Apa?! Tidak! Tidak pernah! Aku akan melawan Eclipsite apa pun yang terjadi!",
  ui_story_1012_10121501_320_dialog_content = "Mereka merenggut keluargaku dan menyakiti teman-temanku. Mana mungkin aku akan memaafkan mereka!",
  ui_story_1012_10121501_321_dialog_content = "Keyakinan dan kekuatanmu diturunkan dari orang-orang yang datang sebelummu, bukan?",
  ui_story_1012_10121501_322_dialog_content = "Sejarah persis seperti itu. Yang lebih penting adalah kau dan kebaikan serta keberanian orang-orangmu.",
  ui_story_1012_10121501_323_dialog_content = "Kurasa kau paham apa yang coba kaukatakan... tetapi aku pikir aku perlu beberapa saat sebelum bisa menerima... noda ini...",
  ui_story_1012_10121501_324_dialog_content = "Kau ingat bagaimana kau mengkritik semua pemimpin atas konspirasi mereka di White Night Celebration?",
  ui_story_1012_10121501_325_dialog_content = "Kau pasti bisa untuk selalu menjadi orang seperti itu.",
  ui_story_1012_10121501_326_dialog_content = "Tapi... itu sangat memalukan bagi Caelestite dan membuatku meragukan diriku sendiri...",
  ui_story_1012_10121501_327_dialog_content = "Lebih parahnya lagi, mungkin bahkan teman-temanku akan ragu untuk memercayaiku...",
  ui_story_1012_10121501_328_dialog_content = "Apakah mereka akan menganggapku sebagai ancaman potensial bagi dunia, seperti yang terjadi di sana?",
  ui_story_1012_10121501_329_dialog_content = "Aku... Aku tidak ingin mereka menatapku dengan curiga... Aku benci perasaan itu...",
  ui_story_1012_10121501_330_dialog_content = "Baik Lumopolis maupun Illumina memiliki masa lalu yang kelam, jadi kenapa kau masih menganggap Carleen dan Vice sebagai teman baikmu?",
  ui_story_1012_10121501_331_dialog_content = "Karena kami berjuang bersama, kami memercayai dan mengandalkan satu sama lain...",
  ui_story_1012_10121501_332_dialog_content = "Akankah mereka mengingkari kepercayaan itu hanya karena sesuatu yang terjadi pada kau Caelestite dulu sekali?",
  ui_story_1012_10121501_333_dialog_content = "Tentu tidak!",
  ui_story_1012_10121501_334_dialog_content = "Seperti yang kaulihat, ini sama sekali bukan pertanyaan rumit.",
  ui_story_1012_10121501_335_dialog_content = "Kau adalah PlayerName. Seorang Caelestite. Tapi, kau tidak mewakili seluruh kaum Caelestite.",
  ui_story_1012_10121501_336_dialog_content = "Tapi, Caelestite adalah segalanya bagiku... Sama seperti bagaimana Northland adalah segalanya bagimu.",
  ui_story_1012_10121501_337_dialog_content = "\"Caelestite tidak berguna dalam pertarungan, dan bahkan pada masa lalu mereka berpihak pada Eclipsite...\"",
  ui_story_1012_10121501_338_dialog_content = "Memikirkan seseorang mengatakan sesuatu seperti itu membuatku sakit.",
  ui_story_1012_10121501_339_dialog_content = "Aku mengerti.",
  ui_story_1012_10121501_340_dialog_content = "Kita belum mempelajari sejarah kaummu yang sebenarnya.",
  ui_story_1012_10121501_341_dialog_content = "Ada kemungkinan nenek moyangmu memilih untuk memberontak dan, oleh karena itu, mengubah nasib kaum Caelestite.",
  ui_story_1012_10121501_342_dialog_content = "Tapi, masa lalu tidak bisa diubah.",
  ui_story_1012_10121501_343_dialog_content = "Dan sekarang, masa depan Caelestite ada di tanganmu.",
  ui_story_1012_10121501_344_dialog_content = "Aku... Aku butuh waktu untuk memikirkan ini.",
  ui_story_1012_10121501_345_dialog_content = "Mungkin yang perlu kulakukan adalah mencari kebenaran.",
  ui_story_1012_10121501_346_dialog_content = "Apa yang akan kaulakukan jika itu adalah kebenaran yang buruk, PlayerName?",
  ui_story_1012_10121501_347_dialog_content = "Aku takut kebenaran mungkin lebih buruk dari yang kubayangkan.",
  ui_story_1012_10121501_348_dialog_content = "Dan bahwa mungkin aku harus menahan kecurigaan dan tatapan semua orang...",
  ui_story_1012_10121501_349_dialog_content = "Kau perlu waktu, PlayerName.",
  ui_story_1012_10121501_350_dialog_content = "Ya... Mungkin lama...",
  ui_story_1012_10121501_351_dialog_content = "<color=#e8d9bb>\"Kontrol Utama: Aktif.\"</color>",
  ui_story_1012_10121501_352_dialog_content = "<color=#e8d9bb>\"Modul Biologis: Aktif.\"</color>",
  ui_story_1012_10121501_353_dialog_content = "<color=#e8d9bb>\"Pendukung Kehidupan: Aktif.\"</color>",
  ui_story_1012_10121501_354_dialog_content = "<color=#e8d9bb>\"Mengaktifkan mesin...\"</color>",
  ui_story_1012_10121501_355_dialog_content = "<color=#e8d9bb>\"16%... 33%...\"</color>",
  ui_story_1012_10121501_356_dialog_content = "<color=#e8d9bb>\"89%... 97%...\"</color>",
  ui_story_1012_10121501_357_dialog_content = "<color=#e8d9bb>\"100%. Berhasil aktif.\"</color>",
  ui_story_1012_10121501_358_dialog_content = "Wah! Soroz pulih sepenuhnya!",
  ui_story_1012_10121501_359_dialog_content = "Hore, akhirnya!",
  ui_story_1012_10121501_360_dialog_content = "Meskipun kesadarannya belum terbangun, ini tetap merupakan kemenangan besar!",
  ui_story_1012_10121501_361_dialog_content = "Seperti kau mendapatkan kembali sesuatu yang hilang, bukan?",
  ui_story_1012_10121501_362_dialog_content = "Benar sekali!",
  ui_story_1012_10121501_363_dialog_content = "Fiuh... Aku lelah. Aku tidak percaya berapa banyak situasi hidup dan mati yang telah kita lalui beberapa hari terakhir ini.",
  ui_story_1012_10121501_364_dialog_content = "Ya, seolah hidup kita selalu di ujung tanduk...",
  ui_story_1012_10121501_365_dialog_content = "Tapi, kita bertahan dan berhasil melewatinya.",
  ui_story_1012_10121501_366_dialog_content = "Harus kukatakan... Kita benar-benar beruntung, haha!",
  ui_story_1012_10121501_367_dialog_content = "Kau benar.",
  ui_story_1012_10121501_368_dialog_content = "Tapi... mungkin itu bukan hanya keberuntungan.",
  ui_story_1012_10121501_369_dialog_content = "Mungkin semua terjadi karena suatu alasan... apa pun itu.",
  ui_story_1012_10121501_370_dialog_content = "Kau terdengar seperti memikirkannya matang-matang. Apakah sesuatu terjadi waktu di Obelisk of Return?",
  ui_story_1012_10121501_371_dialog_content = "Hanya saja kalau dipikir-pikir lagi, aku hampir bisa merasakan ada hubungan antara semua yang terjadi.",
  ui_story_1012_10121501_372_dialog_content = "Banyak hal terjadi pada orang-orang di Obelisk of Return.",
  ui_story_1012_10121501_373_dialog_content = "Meskipun mungkin kita tidak pernah tahu kisah mereka, kita melihat jejak yang ditinggalkannya.",
  ui_story_1012_10121501_374_dialog_content = "Dan sepertinya kita telah menelusuri kembali jejak-jejak itu.",
  ui_story_1012_10121501_375_dialog_content = "Entah jejak siapa itu atau apa yang ingin mereka lakukan...",
  ui_story_1012_10121501_376_dialog_content = "Kita hanya menyusun teka-teki besar selangkah demi selangkah.",
  ui_story_1012_10121501_377_dialog_content = "Maksudmu, Master Francis itu, ya?",
  ui_story_1012_10121501_378_dialog_content = "Sepertinya kau banyak memikirkan dia.",
  ui_story_1012_10121501_379_dialog_content = "Ya... Aku bertanya-tanya, bagaimana kisahnya?",
  ui_story_1012_10121501_380_dialog_content = "Senapan itu miliknya, dan dia melawan Eclipsite di menara...",
  ui_story_1012_10121501_381_dialog_content = "Dia bertanggung jawab atas eksperimen Chord Link, dan labnya tersembunyi di dalam Exile Zone.",
  ui_story_1012_10121501_382_dialog_content = "Entah apakah dia juga mengalami apa yang kita lalui dalam memperebutkan kontrol atas Core Ring Authorization, tetapi...",
  ui_story_1012_10121501_383_dialog_content = "Aurorian yang ditingkatkan Chord Link adalah kuncinya.",
  ui_story_1012_10121501_384_dialog_content = "Benar... Kalau dipikir-pikir, setelah kau bilang begitu, sepertinya kita telah mengikuti langkahnya selama ini.",
  ui_story_1012_10121501_385_dialog_content = "Kita bertarung melawan Eclipse. Bagaimana dengan dia?",
  ui_story_1012_10121501_386_dialog_content = "Apa yang dia lawan... mungkin lebih mengerikan.",
  ui_story_1012_10121501_387_dialog_content = "Aku tidak bisa menebak apa persisnya... tapi mungkin ia melawan takdir itu sendiri.",
  ui_story_1012_10121501_388_dialog_content = "Ia tidak menginginkan hidupmu, tetapi ia ingin mengendalikan hidupmu.",
  ui_story_1012_10121501_389_dialog_content = "Master Francis mencoba untuk melawannya... melawan \"sifatnya\".",
  ui_story_1012_10121501_390_dialog_content = "Melawan... sifatnya sendiri...",
  ui_story_1012_10121501_391_dialog_content = "Memangnya itu mungkin?",
  ui_story_1012_10121501_392_dialog_content = "Aku ingin tahu apakah dia berhasil atau tidak.",
  ui_story_1012_10121501_393_dialog_content = "Jawabannya jelas. Lihat saja ke luar jendela.",
  ui_story_1012_10121501_394_dialog_content = "Caelestite memiliki tempat untuk disebut rumah di bawah Obelisk of Return.",
  ui_story_1012_10121501_395_dialog_content = "Highest Decree tidak lagi mendikte hidup mereka, juga tidak terikat oleh Eclipsite.",
  ui_story_1012_10121501_396_dialog_content = "Impiannya telah mengubah nasib generasi masa depannya...",
  ui_story_1012_10121501_397_dialog_content = "Dia telah mengubah kehidupan semua kaum Caelestite.",
  ui_story_1013_10130101_1_dialog_content = "Hari tenang lainnya.",
  ui_story_1013_10130101_2_dialog_content = "Yap.",
  ui_story_1013_10130101_3_dialog_content = "Sepertinya selamanya sejak kami menggunakan Luminatics untuk melawan Eclipsites.",
  ui_story_1013_10130101_4_dialog_content = "Aku yakin bahkan keterampilan bertarungku sudah berkarat.",
  ui_story_1013_10130101_5_dialog_content = "Perdamaian adalah hal yang baik!",
  ui_story_1013_10130101_6_dialog_content = "Jika suatu hari nanti semua Eclipsites musnah, mungkin seperti inilah hidup ini nantinya.",
  ui_story_1013_10130101_7_dialog_content = "Kami tidak perlu khawatir diserang. Dan kita bisa menghabiskan hari-hari kita dengan berjalan kaki, memancing, atau memasak.",
  ui_story_1013_10130101_8_dialog_content = "Kedengarannya sangat bagus, sebenarnya.",
  ui_story_1013_10130101_9_dialog_content = "Apa yang Anda rencanakan saat itu tiba?",
  ui_story_1013_10130101_10_option_content = "Menanam pohon?",
  ui_story_1013_10130101_11_dialog_content = "Tanam banyak pohon langka untuk menjadikan Cloud Gardens indah.",
  ui_story_1013_10130101_12_dialog_content = "Meskipun itu tidak akan mudah. Mutasi itu gagal sembilan kali dari sepuluh!",
  ui_story_1013_10130101_13_dialog_content = "Menanam pohon membutuhkan ketekunan.",
  ui_story_1013_10130101_14_option_content = "Memancing?",
  ui_story_1013_10130101_15_dialog_content = "Saya ingin sekali memasukkan lebih banyak ikan hias ke Air Mancur Harapan.",
  ui_story_1013_10130101_16_dialog_content = "Aku lelah memancing sampah...",
  ui_story_1013_10130101_17_dialog_content = "Anda pasti akan berhasil dalam hal itu!",
  ui_story_1013_10130101_18_dialog_content = "Eraveil sedamai itu, semua berkat Chord of the Law.",
  ui_story_1013_10130101_19_dialog_content = "Saya tidak menyadari betapa kuatnya itu.",
  ui_story_1013_10130101_20_dialog_content = "Jika saya baru saja menembak sesuka hati, tanpa parameter yang telah ditetapkan oleh Master Francis sebelumnya ...",
  ui_story_1013_10130101_21_dialog_content = "Mungkin akan ada dampak yang serius.",
  ui_story_1013_10130101_22_dialog_content = "Aku masih bergidik saat memikirkannya sekarang.",
  ui_story_1013_10130101_23_dialog_content = "Krisis telah berlalu, jadi jangan buang energi untuk mengkhawatirkannya sekarang.",
  ui_story_1013_10130101_24_dialog_content = "Hidup di saat ini!",
  ui_story_1013_10130101_25_dialog_content = "Kamu benar! Kata baik.",
  ui_story_1013_10130101_26_dialog_content = "Ngomong-ngomong, Vice, kenapa kamu masih berpakaian seperti itu?",
  ui_story_1013_10130101_27_dialog_content = "Hah? Maksudnya hitam semua?",
  ui_story_1013_10130101_28_dialog_content = "Yah, aku jauh lebih terbiasa memakai pakaianku yang biasa, tapi kadang-kadang bahkan aku suka membumbuinya sedikit dengan sesuatu yang berbeda.",
  ui_story_1013_10130101_29_dialog_content = "Apakah ini aneh? Jika demikian, saya bisa ... berubah kembali menjadi putih saya yang biasa?",
  ui_story_1013_10130101_30_dialog_content = "Tidak tidak! Tidak dibutuhkan!",
  ui_story_1013_10130101_31_dialog_content = "Saya tidak peduli dengan apa yang Anda kenakan, selama Anda menyukainya!",
  ui_story_1013_10130101_32_dialog_content = "Omong-omong, ikan hias yang baru saja Anda tangkap masih ada di dalam ember.",
  ui_story_1013_10130101_33_dialog_content = "Cepat dan taruh mereka di Air Mancur Harapan!",
  ui_story_1013_10130101_34_dialog_content = "Betul sekali! Saya benar-benar lupa!",
  ui_story_1013_10130101_35_dialog_content = "Biarkan aku menjatuhkan mereka ke Air Mancur.",
  ui_story_1013_10130101_36_dialog_content = "Hah?!",
  ui_story_1013_10130101_37_dialog_content = "Vice, apakah Anda sudah berlatih Luminatics baru?",
  ui_story_1013_10130101_38_dialog_content = "Luminatics Baru? No I...",
  ui_story_1013_10130101_39_dialog_content = "Apa yang sebenarnya terjadi?!",
  ui_story_1013_10130101_40_dialog_content = "Saya tidak menggunakan Luminatics!",
  ui_story_1013_10130101_41_dialog_content = "Siapa yang main-main? Ayo keluar. Kami bisa melihatmu!",
  ui_story_1013_10130101_42_dialog_content = "Um... Tidak, sepertinya Lumina ini mengalir keluar dariku.",
  ui_story_1013_10130101_43_dialog_content = "Aku bisa merasakan Lumina perlahan menjauh dariku. Apa yang terjadi di sini?",
  ui_story_1013_10130101_44_dialog_content = "Apa mungkin...",
  ui_story_1013_10130101_45_dialog_content = "Efek samping penggunaan Chord Link?",
  ui_story_1013_10130101_46_dialog_content = "Apakah kamu baik-baik saja, Vice? Apakah Anda merasa baik-baik saja?",
  ui_story_1013_10130101_47_dialog_content = "Secara fisik, saya merasa baik-baik saja...",
  ui_story_1013_10130101_48_dialog_content = "Kecepatan kehilangan Lumina sangat lambat sehingga saya hampir tidak bisa merasakannya.",
  ui_story_1013_10130101_49_dialog_content = "Jika ini semua ada untuk itu, maka itu bukan masalah besar.",
  ui_story_1013_10130101_50_dialog_content = "Tetapi kami tidak tahu apakah Anda akan mendapatkan gejala lain.",
  ui_story_1013_10130101_51_dialog_content = "Kami hanya tahu sedikit tentang teknologi kuno, namun kami masih menggunakan perangkat itu dengan tergesa-gesa, saya...",
  ui_story_1013_10130101_52_dialog_content = "Santai saja, PlayerName.",
  ui_story_1013_10130101_53_dialog_content = "Sebaiknya kita kembali ke Gannon!",
  ui_story_1013_10130101_54_dialog_content = "Gannon memiliki ilmuwan dan fasilitas medis terbaik di Illumina. Kami pasti akan mencari tahu apa yang menyebabkan semua ini.",
  ui_story_1013_10130101_55_dialog_content = "Oh itu benar! Ayo segera pergi. Kita dapat menggunakan terminal komunikasi untuk menghubungi Vivian di jalan, dan dia pasti akan membantu kita!",
  ui_story_1013_10130101_56_dialog_content = "Tujuan autopilot dikonfirmasi: Kota Gannon.",
  ui_story_1013_10130101_57_dialog_content = "Baiklah, mari kita bergerak!",
  ui_story_1013_10130101_58_dialog_content = "Jangan khawatir, PlayerName, Saya baik-baik saja.",
  ui_story_1013_10130101_59_dialog_content = "Aku hanya, kau tahu, sedikit bersinar.",
  ui_story_1013_10130101_60_dialog_content = "Tapi kamu hanya terluka karena kamu membantuku menemukan cara untuk memperbaiki Soroz.",
  ui_story_1013_10130101_61_dialog_content = "Itu juga keputusan saya untuk menggunakan Chord Link untuk mentraktir Anda.",
  ui_story_1013_10130101_62_dialog_content = "Jadi... Saya harus memikul tanggung jawab atas apa pun gejala ini sekarang.",
  ui_story_1013_10130101_63_dialog_content = "Terutama karena saya memutuskan sendiri untuk mengoperasikan perangkat kuno itu tanpa mengetahui untuk apa perangkat itu dibuat!",
  ui_story_1013_10130101_64_dialog_content = "PlayerName…",
  ui_story_1013_10130101_65_dialog_content = "Tolong jangan khawatir. Sejujurnya aku merasa baik-baik saja.",
  ui_story_1013_10130101_66_dialog_content = "Namun tentunya hal ini tidak bisa kita abaikan begitu saja.",
  ui_story_1013_10130101_67_dialog_content = "Kamu benar. Taruhan terbaik kami adalah pergi dulu ke Gannon untuk pemeriksaan menyeluruh.",
  ui_story_1013_10130101_68_dialog_content = "Hubungi Petugas Vivian selagi kita dalam perjalanan, dan minta dia mengatur ujian.",
  ui_story_1013_10130101_69_dialog_content = "Akan melakukan.",
  ui_story_1013_10130101_70_dialog_content = "Vivian? Bisakah kamu mendengarku?",
  ui_story_1013_10130101_71_dialog_content = "PlayerName? Ya, aku bisa mendengarmu. Lanjutkan.",
  ui_story_1013_10130101_72_dialog_content = "Ada sedikit situasi mendesak dengan Vice, dan saya butuh bantuan!",
  ui_story_1013_10130101_73_dialog_content = "Situasi mendesak? Jangan bilang Vice juga mengalami salah satu episode itu.",
  ui_story_1013_10130101_74_dialog_content = "\"Juga\"?",
  ui_story_1013_10130101_75_dialog_content = "Apakah Barton juga secara acak mulai bersinar?!",
  ui_story_1013_10130101_76_dialog_content = "Ya, Komandan Barton diberi cuti agar dia bisa beristirahat tepat setelah pertempuran di Eraveil.",
  ui_story_1013_10130101_77_dialog_content = "Entah kenapa pagi ini, tubuhnya mulai memancarkan Lumina tanpa alasan.",
  ui_story_1013_10130101_78_dialog_content = "Saya akan menebak bahwa Vice mengalami hal yang sama.",
  ui_story_1013_10130101_79_dialog_content = "Betul sekali. Kami sedang dalam perjalanan ke Gannon saat kami berbicara. Apakah Anda dapat mengatur ujian ketika kami tiba di sana?",
  ui_story_1013_10130101_80_dialog_content = "Serahkan padaku.",
  ui_story_1013_10130101_81_dialog_content = "Illumina sudah berencana melakukan pemeriksaan menyeluruh terhadap Komandan Barton dan Wakil karena mereka menggunakan Chord Link.",
  ui_story_1013_10130101_82_dialog_content = "Benarkah? Baguslah kalau begitu!",
  ui_story_1013_10130101_83_dialog_content = "Datanglah ke pusat medis segera setelah Anda tiba di Kota Gannon. Aku akan menunggumu di sana.",
  ui_story_1013_10130101_84_dialog_content = "Mengerti. Terima kasih!",
  ui_story_1013_10130101_85_dialog_content = "<color=#e8d9bb>Kota Gannon, Pusat Medis</color>",
  ui_story_1013_10130101_86_dialog_content = "Ini pusat kesehatan.",
  ui_story_1013_10130101_87_dialog_content = "Terakhir kali saya di sini adalah untuk fisik wajib ketika saya mendaftar.",
  ui_story_1013_10130101_88_dialog_content = "Ini pertama kalinya bagiku. Saya tidak menyangka pusat medis Illumina akan sebesar ini!",
  ui_story_1013_10130101_89_dialog_content = "Tentu saja!",
  ui_story_1013_10130101_90_dialog_content = "Tidak ada yang bisa memprediksi jumlah korban yang mungkin ditimbulkan oleh pertempuran.",
  ui_story_1013_10130101_91_dialog_content = "Semakin besar pusatnya, semakin banyak tentara yang terluka yang dapat kami obati dengan segera.",
  ui_story_1013_10130101_92_dialog_content = "Perawatan cepat meningkatkan peluang mereka untuk bertahan hidup...",
  ui_story_1013_10130101_93_dialog_content = "Benar sekali...",
  ui_story_1013_10130101_94_dialog_content = "Oh, hei, Wakil, PlayerName!",
  ui_story_1013_10130101_95_dialog_content = "Anda sudah di sini.",
  ui_story_1013_10130101_96_dialog_content = "Komandan Barton! Petugas Vivian!",
  ui_story_1013_10130101_97_dialog_content = "Sepertinya Barton menderita fenomena yang sama...",
  ui_story_1013_10130101_98_dialog_content = "Hah? Oh, maksudmu bersinar?",
  ui_story_1013_10130101_99_dialog_content = "Saya tidak terganggu jika itu hanya bersinar. Ini tidak seperti menghabiskan banyak Lumina.",
  ui_story_1013_10130101_100_dialog_content = "Tentu, tetapi Anda tidak bisa mengabaikan potensi risikonya begitu saja!",
  ui_story_1013_10130101_101_dialog_content = "Ya, kuharap orang-orang pintar berjas putih itu segera menemukan cara untuk menghentikannya.",
  ui_story_1013_10130101_102_dialog_content = "Jika tidak, saya akan menjadi target yang terang dan bercahaya di malam hari. Dan aku tidak akan bisa menyergap musuh!",
  ui_story_1013_10130101_103_dialog_content = "I-Memang.",
  ui_story_1013_10130101_104_dialog_content = "Ada apa, Nak? Anda punya khawatir tertulis di seluruh wajah Anda.",
  ui_story_1013_10130101_105_dialog_content = "Oh? Yah... Tidak akan berbohong, aku sedikit khawatir.",
  ui_story_1013_10130101_106_dialog_content = "Jangan. Ini di sini adalah organisasi medis terbaik di seluruh Illumina. Mereka dapat membawa Anda kembali bahkan sebelum Anda tahu Anda sudah mati!",
  ui_story_1013_10130101_107_dialog_content = "Situasi bercahaya tanpa rasa sakit dan tidak berbahaya semacam ini adalah berjalan-jalan di taman.",
  ui_story_1013_10130101_108_dialog_content = "Ya!",
  ui_story_1013_10130101_109_dialog_content = "Kalau begitu, izinkan saya mengawal Komandan Barton dan Vice ke pemeriksaan mereka.",
  ui_story_1013_10130101_110_dialog_content = "Jika Anda bisa tolong tunggu di luar, PlayerName.",
  ui_story_1013_10130101_111_dialog_content = "Tentu saja.",
  ui_story_1013_10130101_112_dialog_content = "Sampai jumpa!",
  ui_story_1013_10130101_113_dialog_content = "Nanti, Nak.",
  ui_story_1013_10130101_114_dialog_content = "Dan keheningan menyelimuti koridor sekali lagi.",
  ui_story_1013_10130101_115_dialog_content = "Mudah-mudahan situasi ini hanya kebetulan saja.",
  ui_story_1013_10130101_116_dialog_content = "Adapun Anda, Anda sepenuhnya bertanggung jawab untuk—",
  ui_story_1013_10130101_117_dialog_content = "Menciptakan perang bagi dunia.",
  ui_story_1013_10130101_118_dialog_content = "...",
  ui_story_1013_10130101_119_dialog_content = "Tidak, saya tidak akan pernah melakukan itu.",
  ui_story_1013_10130101_120_dialog_content = "Tetapi apakah saya membuat pilihan yang tepat?",
  ui_story_1013_10130101_121_dialog_content = "Terlihat sama seperti terakhir kali, tapi jangan lengah.",
  ui_story_1013_10130101_122_dialog_content = "Tidak ada ruang untuk kelalaian atau kecelakaan dalam kondisi Anda.",
  ui_story_1013_10130101_123_dialog_content = "*Batuk*... Aku tahu, aku tahu.",
  ui_story_1013_10130101_124_dialog_content = "Saya sepenuhnya menyadari kondisi saya. Selalu begitu.",
  ui_story_1013_10130101_125_dialog_content = "Anda bisa datang untuk berlatih bersama kami.",
  ui_story_1013_10130101_126_dialog_content = "Percayalah padaku! Pelatihan membuat saya lebih kuat, mengubah saya dari buncis kecil yang lemah yang tidak bisa berbuat apa-apa!",
  ui_story_1013_10130101_127_dialog_content = "Ha ha ha. Kondisi saya bukanlah sesuatu yang bisa diperbaiki oleh pelatihan.",
  ui_story_1013_10130101_128_dialog_content = "(Apakah orang-orang ini juga ada di sini untuk pemeriksaan?)",
  ui_story_1013_10130101_129_dialog_content = "Hei kau! Apa yang kamu lihat?",
  ui_story_1013_10130101_130_dialog_content = "Hah?! Oh maafkan saya!",
  ui_story_1013_10130101_131_dialog_content = "Aku baru saja melihat beberapa orang asing, dan...",
  ui_story_1013_10130101_132_dialog_content = "Tunggu dulu, kamu...",
  ui_story_1013_10130101_133_dialog_content = "Kamu bukan Caelestite yang legendaris, kan?!",
  ui_story_1013_10130101_134_dialog_content = "Apa?",
  ui_story_1013_10130101_135_dialog_content = "Hah? Caelestite, benarkah?",
  ui_story_1013_10130101_136_dialog_content = "Anda tahu saya? Saya tidak berpikir kita pernah bertemu sebelumnya.",
  ui_story_1013_10130101_137_dialog_content = "Tentu saja! Anda terkenal dari mana kami berasal karena banyak hal.",
  ui_story_1013_10130101_138_dialog_content = "Menavigasi Colossus, melawan Eclipsites bersama Aurorians di Dunefire Line.",
  ui_story_1013_10130101_139_dialog_content = "Dan memukul mundur Eclipsites di Eraveil, bersekutu dengan Illumina, Lumopolis, dan Northland!",
  ui_story_1013_10130101_140_dialog_content = "Kami semua pengagum besar Anda dan perbuatan Anda.",
  ui_story_1013_10130101_141_option_content = "Saya hanya melakukan apa yang saya bisa.",
  ui_story_1013_10130101_142_dialog_content = "Lagipula, Eclipsites adalah musuh semua orang.",
  ui_story_1013_10130101_143_option_content = "Itu adalah upaya bersama.",
  ui_story_1013_10130101_144_dialog_content = "Tidak mungkin saya bisa melakukan semua itu tanpa bantuan semua orang.",
  ui_story_1013_10130101_145_dialog_content = "Dan Anda sama rendah hati seperti yang mereka katakan!",
  ui_story_1013_10130101_146_dialog_content = "Izinkan saya untuk memperkenalkan diri. Nama saya Zhao, dan saya melayani sebagai Kepala Staf di kota Twilight, di sebelah barat.",
  ui_story_1013_10130101_147_dialog_content = "Ini adalah asisten saya Crow, dan rekan saya Sean.",
  ui_story_1013_10130101_148_dialog_content = "Saya tidak akan pernah berpikir saya akan bertemu Anda di sini! Pasti hari keberuntunganku.",
  ui_story_1013_10130101_149_dialog_content = "Senang bertemu dengan kalian semua. aku PlayerName.",
  ui_story_1013_10130101_150_dialog_content = "Hai, PlayerName.",
  ui_story_1013_10130101_151_dialog_content = "Halo.",
  ui_story_1013_10130101_152_dialog_content = "Maaf jika aku sedikit kasar sekarang. Adalah tugasku untuk menjaga Zhao.",
  ui_story_1013_10130101_153_dialog_content = "Tidak apa-apa. Sungguh tidak sopan bagiku untuk menatap.",
  ui_story_1013_10130101_154_dialog_content = "Ketua Zhao selalu bercerita tentangmu!",
  ui_story_1013_10130101_155_dialog_content = "Aku sangat cemburu! Saya ingin menerbangkan Colossus ke mana-mana.",
  ui_story_1013_10130101_156_dialog_content = "Mungkin sangat nyaman untuk bepergian sangat jauh dengan Colossus, bukan?",
  ui_story_1013_10130101_157_dialog_content = "Tentunya! Ke mana pun saya pergi, Colossus saya dapat membawa saya ke sana dalam sekejap mata.",
  ui_story_1013_10130101_158_dialog_content = "Luar biasa! Saya berharap saya punya satu juga.",
  ui_story_1013_10130101_159_dialog_content = "Dengan begitu, kita bisa kembali ke Twilight lebih cepat!",
  ui_story_1013_10130101_160_dialog_content = "Apakah ada alasan mendesak Anda harus kembali?",
  ui_story_1013_10130101_161_dialog_content = "Ya!",
  ui_story_1013_10130101_162_dialog_content = "Anda tidak tahu apa yang terjadi di Twilight?",
  ui_story_1013_10130101_163_dialog_content = "Tidak terlalu. Dimana kotamu ini?",
  ui_story_1013_10130101_164_dialog_content = "Twilight berada di luar yurisdiksi Illumina. Itu cukup jauh dari Gannon.",
  ui_story_1013_10130101_165_dialog_content = "Sementara gangguan Eclipsite lebih sering terjadi di sana daripada pemukiman di dalam perbatasan, itu masih merupakan tempat yang cukup bagus untuk ditinggali.",
  ui_story_1013_10130101_166_dialog_content = "Saya ingin cepat kembali dan membantu teman-teman saya menangani pengacau Eclipsite itu!",
  ui_story_1013_10130101_167_dialog_content = "Sejujurnya, itu jelas hanya goresan, tetapi para dokter bersikeras mengirim saya jauh-jauh ke Gannon untuk perawatan.",
  ui_story_1013_10130101_168_dialog_content = "Saya kira itu baik-baik saja, meskipun. Kita semua sudah selesai sekarang dan bisa kembali ke Twilight sore ini!",
  ui_story_1013_10130101_169_dialog_content = "Lebih baik aman daripada menyesal.",
  ui_story_1013_10130101_170_dialog_content = "Anda harus menjaga diri sendiri, atau Anda tidak akan memiliki kekuatan untuk menghadapi lebih banyak musuh.",
  ui_story_1013_10130101_171_dialog_content = "Jangan seperti seseorang, dan selalu memaksakan diri terlalu keras.",
  ui_story_1013_10130101_172_dialog_content = "*Batuk*... Pokoknya, PlayerName, kita harus pergi.",
  ui_story_1013_10130101_173_dialog_content = "Jika Anda memiliki kesempatan untuk berkunjung, kami akan menyambut Anda dengan tangan terbuka.",
  ui_story_1013_10130101_174_dialog_content = "Saya akan menyukai kesempatan untuk bertarung bersama Caelestite.",
  ui_story_1013_10130101_175_dialog_content = "Jika ada kesempatan, saya pasti akan mengambilnya.",
  ui_story_1013_10130101_176_dialog_content = "Sampai jumpa jika takdir memang menginginkannya.",
  ui_story_1013_10130101_177_dialog_content = "Selamat tinggal.",
  ui_story_1013_10130101_178_dialog_content = "Dah!",
  ui_story_1013_10130101_179_dialog_content = "Senja? Kedengarannya seperti tempat yang cukup terpencil.",
  ui_story_1013_10130101_180_dialog_content = "Hah? Orang yang keluar dari ruang konsultasi disana, apa itu...?",
  ui_story_1013_10130101_181_dialog_content = "Reinhard?!",
  ui_story_1013_10130101_182_dialog_content = "Hah? PlayerName?",
  ui_story_1013_10130101_183_dialog_content = "Vivian menyebutkan bahwa Anda membawa Vice ke Gannon. Tapi aku tidak berpikir aku akan bertemu denganmu.",
  ui_story_1013_10130101_184_dialog_content = "Saya juga terkejut.",
  ui_story_1013_10130101_185_dialog_content = "Jadi apa yang membawamu ke sini?",
  ui_story_1013_10130101_186_dialog_content = "Apakah sesuatu yang aneh juga terjadi padamu setelah menggunakan sistem medis Soroz?",
  ui_story_1013_10130101_187_dialog_content = "Oh tidak. Tidak seperti yang dihadapi Barton dan Vice.",
  ui_story_1013_10130101_188_dialog_content = "Saya di sini hanya untuk pemeriksaan fisik rutin.",
  ui_story_1013_10130101_189_dialog_content = "Harus punya satu setiap enam bulan. Ini hanya tes kebugaran dan darah, sungguh, hal-hal standar.",
  ui_story_1013_10130101_190_dialog_content = "Hasil saya stabil seperti biasanya, jadi tidak perlu khawatir.",
  ui_story_1013_10130101_191_dialog_content = "Bagus, itu melegakan. Oh ya, bagaimana cedera yang kamu alami terakhir kali?",
  ui_story_1013_10130101_192_dialog_content = "Hahaha! Santai. Berkat peralatan medis terbaik Anda, sudah lama sembuh.",
  ui_story_1013_10130101_193_dialog_content = "Kalau saja Illumina memiliki peralatan semacam itu...",
  ui_story_1013_10130101_194_dialog_content = "Hei nak, kami kembali!",
  ui_story_1013_10130101_195_dialog_content = "Marsekal Agung Reinhardt? Anda di sini juga?",
  ui_story_1013_10130101_196_dialog_content = "Hai PlayerName... dan Marsekal Agung?!",
  ui_story_1013_10130101_197_dialog_content = "Apa mereka sudah selesai memeriksa kalian berdua? Bagaimana hasilnya?",
  ui_story_1013_10130101_198_dialog_content = "Bagaimana saya harus menempatkan ini ...",
  ui_story_1013_10130101_199_dialog_content = "Laporan itu mengatakan bahwa hasilnya—tidak ada!",
  ui_story_1013_10130101_200_dialog_content = "Hah?!",
  ui_story_1013_10130101_201_dialog_content = "Para dokter dan ilmuwan itu menyodok dan mendorong kami dengan segala macam instrumen untuk waktu yang terasa seperti selamanya, tetapi pada akhirnya tidak dapat mencapai kesimpulan.",
  ui_story_1013_10130101_202_dialog_content = "Semua tes yang biasa dilakukan selama pemeriksaan fisik rutin kembali normal.",
  ui_story_1013_10130101_203_dialog_content = "Jadi, tidak ada masalah sama sekali, setidaknya menurut hasil tes.",
  ui_story_1013_10130101_204_dialog_content = "Tapi sepertinya tidak ada lagi Lumina yang keluar dari kalian. Bagaimana Anda disembuhkan?",
  ui_story_1013_10130101_205_dialog_content = "Oh, tentang itu!",
  ui_story_1013_10130101_206_dialog_content = "Salah satu tes melibatkan penggunaan Luminatics untuk menyerang boneka pelatihan.",
  ui_story_1013_10130101_207_dialog_content = "Saya pikir para ilmuwan mungkin ingin melihat apakah penyebaran Lumina semacam ini akan mempengaruhi kemampuan kita untuk menggunakan Luminatics atau tidak.",
  ui_story_1013_10130101_208_dialog_content = "Ngomong-ngomong, setelah dengan senang hati menghajar boneka-boneka itu untuk beberapa saat, cahaya itu berhenti dengan sendirinya.",
  ui_story_1013_10130101_209_dialog_content = "Jika saya tahu itu adalah cara untuk menghentikan cahaya, saya akan pergi mencari beberapa Eclipsites!",
  ui_story_1013_10130101_210_dialog_content = "Saya mendengar beberapa ilmuwan mengatakan bahwa Komandan Barton benar-benar menghancurkan sepuluh boneka pelatihan yang bagus.",
  ui_story_1013_10130101_211_dialog_content = "Apakah begitu? Kalau begitu, biaya perbaikannya akan dipotong dari alokasi bulanan Komandan Legiun ke-2.",
  ui_story_1013_10130101_212_dialog_content = "Tunggu apa?!",
  ui_story_1013_10130101_213_dialog_content = "Hahaha, aku bercanda.",
  ui_story_1013_10130101_214_dialog_content = "Hal utama adalah kalian berdua baik-baik saja. Namun, jangan lengah hanya karena Anda baik-baik saja saat ini.",
  ui_story_1013_10130101_215_dialog_content = "Pastikan untuk melakukan pemeriksaan rutin, setidaknya untuk waktu yang singkat, untuk memastikan semuanya baik-baik saja.",
  ui_story_1013_10130101_216_dialog_content = "Siap, Kapten!",
  ui_story_1013_10130101_217_dialog_content = "Siap, Kapten!",
  ui_story_1013_10130101_218_dialog_content = "Secara keseluruhan, kesehatan saya normal secara keseluruhan.",
  ui_story_1013_10130101_219_dialog_content = "Anda tidak perlu terlalu khawatir.",
  ui_story_1013_10130101_220_dialog_content = "Saya kira untuk saat ini, bersinar tidak terlalu menjadi masalah.",
  ui_story_1013_10130101_221_dialog_content = "Namun saya masih khawatir apakah penggunaan Chord Link dapat menyebabkan gejala lain.",
  ui_story_1013_10130101_222_dialog_content = "Kami tidak tahu apa-apa, itulah yang membuat ini menakutkan.",
  ui_story_1013_10130101_223_dialog_content = "Itu juga yang dikatakan para dokter.",
  ui_story_1013_10130101_224_dialog_content = "Jadi mereka menyarankan saya untuk tetap aktif dan memberi perhatian khusus pada setiap perubahan kondisi fisik saya.",
  ui_story_1013_10130101_225_dialog_content = "Oke! Saya akan membantu mengawasi Anda juga!",
  ui_story_1013_10130101_226_dialog_content = "Omong-omong, saya punya proposal untuk Anda.",
  ui_story_1013_10130101_227_dialog_content = "Yah, tepatnya, itu lebih merupakan permintaan.",
  ui_story_1013_10130101_228_dialog_content = "PlayerName, Saya berharap Anda bersedia memberikan akses penelitian Illumina ke Soroz dan Obelisk of Return.",
  ui_story_1013_10130101_229_dialog_content = "Hah?!",
  ui_story_1013_10130101_230_dialog_content = "Bolehkah saya bertanya mengapa?",
  ui_story_1013_10130101_231_dialog_content = "Tentu saja.",
  ui_story_1013_10130101_232_dialog_content = "Bagaimanapun, seluruh komunitas ilmiah Illumina dan saya telah mengembangkan apresiasi yang mendalam terhadap kekuatan teknologi Caelestite.",
  ui_story_1013_10130101_233_dialog_content = "Khususnya mengenai Chord Link dan teknologi medis, jika kita bisa menggunakannya dalam pertempuran, kita bisa menyelamatkan nyawa begitu banyak Aurorian.",
  ui_story_1013_10130101_234_dialog_content = "Selain itu, Ruang Simulasi di Colossus juga memiliki potensi yang fenomenal.",
  ui_story_1013_10130101_235_dialog_content = "Jika kita bisa menggunakannya untuk melatih para komandan, kita pasti bisa mengurangi jumlah korban.",
  ui_story_1013_10130101_236_dialog_content = "Namun…",
  ui_story_1013_10130101_237_dialog_content = "(Jika teknologi Caelestite dibuat untuk menghasut perang, bolehkah menyerahkannya seperti ini?)",
  ui_story_1013_10130101_238_dialog_content = "Saya tahu apa yang mungkin Anda khawatirkan.",
  ui_story_1013_10130101_239_dialog_content = "Oleh karena itu, saya berjanji kepada Anda ini:",
  ui_story_1013_10130101_240_dialog_content = "Illumina tidak akan pernah menggunakan teknologi ini untuk tujuan yang tidak diinginkan.",
  ui_story_1013_10130101_241_dialog_content = "Dan kami akan, tentu saja, menawarkan kompensasi kepada Anda.",
  ui_story_1013_10130101_242_dialog_content = "Sebagai imbalannya, Illumina akan mengirimkan ilmuwan terbaik dan terpintar kami untuk membantu Anda memperbaiki Soroz.",
  ui_story_1013_10130101_243_dialog_content = "...",
  ui_story_1013_10130101_244_dialog_content = "Bagaimana menurutmu, Vice?",
  ui_story_1013_10130101_245_dialog_content = "Apa yang saya pikirkan?",
  ui_story_1013_10130101_246_dialog_content = "Yah, saya ingin Illumina memiliki teknologi medis terbaik.",
  ui_story_1013_10130101_247_dialog_content = "Tapi Eraveil adalah milikmu. Pilihan ada di tangan Anda.",
  ui_story_1013_10130101_248_dialog_content = "Jadi, apa pendapat Anda, PlayerName?",
  ui_story_1013_10130101_249_dialog_content = "Hei, tunggu sebentar, Grand Marshal.",
  ui_story_1013_10130101_250_dialog_content = "Bukankah agak terburu-buru untuk mengharapkan jawaban sekarang?",
  ui_story_1013_10130101_251_dialog_content = "Ini bukan keputusan kecil yang bisa Anda buat dengan seenaknya.",
  ui_story_1013_10130101_252_dialog_content = "Beri anak itu waktu untuk memikirkannya. Anda akan mendapatkan jawaban Anda.",
  ui_story_1013_10130101_253_dialog_content = "...",
  ui_story_1013_10130101_254_dialog_content = "Maafkan aku, aku agak terburu-buru.",
  ui_story_1013_10130101_255_dialog_content = "Jika Anda perlu waktu untuk mempertimbangkan, silakan, dengan segala cara. Saya bisa menunggu.",
  ui_story_1013_10130101_256_dialog_content = "Aku…",
  ui_story_1013_10130101_257_dialog_content = "Tak apa.",
  ui_story_1013_10130101_258_option_content = "Saya akan mengizinkannya.",
  ui_story_1013_10130101_259_dialog_content = "Bagus sekali. Terima kasih, PlayerName.",
  ui_story_1013_10130101_260_option_content = "Saya percaya kamu.",
  ui_story_1013_10130101_261_dialog_content = "…!",
  ui_story_1013_10130101_262_dialog_content = "Terima kasih, PlayerName.",
  ui_story_1013_10130101_263_dialog_content = "Yah, tidak ada waktu untuk kalah. Saya akan menghubungi tim sains di pusat penelitian dan memberi tahu mereka untuk bersiap-siap.",
  ui_story_1013_10130101_264_dialog_content = "Anda dan Vice juga harus datang, karena kami mungkin membutuhkan bantuan Anda. Mohon maaf sebelumnya atas kerumitannya.",
  ui_story_1013_10130101_265_dialog_content = "Tidak apa-apa. Jika kalian membantu saya memperbaiki Soroz, itu sama-sama menguntungkan.",
  ui_story_1013_10130101_266_dialog_content = "Jika itu untuk Illumina, maka itu menjadi tanggung jawabku. Saya tidak akan pernah menolak.",
  ui_story_1013_10130101_267_dialog_content = "Sepertinya aku tidak punya alasan lagi untuk berkeliaran di sini.",
  ui_story_1013_10130101_268_dialog_content = "Kalau begitu, aku akan kembali ke Legiun ke-2.",
  ui_story_1013_10130101_269_dialog_content = "Mampir untuk permainan catur jika Anda punya waktu sebentar, Nak.",
  ui_story_1013_10130101_270_dialog_content = "Tentu! Aku suka itu.",
  ui_story_1013_10130201_1_dialog_content = "Ini adalah wilayah administratif Illumina Research Center.",
  ui_story_1013_10130201_2_dialog_content = "Ini mungkin pertama kalinya Anda di sini.",
  ui_story_1013_10130201_3_dialog_content = "Y-Ya!",
  ui_story_1013_10130201_4_dialog_content = "Saya selalu mendengar bahwa tempat ini memiliki ilmuwan terbaik di seluruh Federasi Illumina.",
  ui_story_1013_10130201_5_dialog_content = "Saya tidak pernah berharap untuk melihatnya dengan mata kepala sendiri!",
  ui_story_1013_10130201_6_dialog_content = "Wah, sibuk!",
  ui_story_1013_10130201_7_dialog_content = "Tentu saja. Semua orang di sini bekerja keras atas nama Illumina, setiap hari.",
  ui_story_1013_10130201_8_dialog_content = "Keberhasilan Illumina sebagian besar berkat usaha mereka.",
  ui_story_1013_10130201_9_dialog_content = "Yo! Marsekal Agung! Dan Wakil! Dan pecundang!",
  ui_story_1013_10130201_10_option_content = "Gronru?!",
  ui_story_1013_10130201_11_dialog_content = "Sedang apa kau di sini?",
  ui_story_1013_10130201_12_dialog_content = "Grand Marshal meminta Migard dan saya untuk membantu beberapa eksperimen. Dia bilang aku akan bebas mempelajari fungsi baru Soroz.",
  ui_story_1013_10130201_13_dialog_content = "Kedengarannya jauh lebih menyenangkan daripada mengalahkan game lain pada tingkat kesulitan tertinggi! Saya menerimanya dalam sekejap.",
  ui_story_1013_10130201_14_dialog_content = "Harap bersikap lembut dengan Soroz ...",
  ui_story_1013_10130201_15_dialog_content = "Ah, santai! Saya akan merawat Soroz dengan tangan paling hati-hati!",
  ui_story_1013_10130201_16_dialog_content = "Sudah lama, anak muda.",
  ui_story_1013_10130201_17_dialog_content = "Nona... Migard...",
  ui_story_1013_10130201_18_dialog_content = "(Meskipun aku tahu dia tidak berbahaya, aku selalu merasa gugup setiap kali aku melihatnya...)",
  ui_story_1013_10130201_19_dialog_content = "Hmm? Ada apa dengan ekspresimu?",
  ui_story_1013_10130201_20_dialog_content = "Anda terlihat khawatir sejak Anda tiba di Illumina hari ini.",
  ui_story_1013_10130201_21_dialog_content = "Karena ada sesuatu yang terjadi dengan Vice...",
  ui_story_1013_10130201_22_dialog_content = "Tunggu, kau melihat kami? Kenapa aku tidak melihatmu? Saya harap saya tidak hanya mengabaikan Anda ?!",
  ui_story_1013_10130201_23_dialog_content = "Ahaha, kau lupa kalau Diving Spinesku mengawasi setiap sudut Illumina.",
  ui_story_1013_10130201_24_dialog_content = "Bahkan jika saya tidak ada di sana secara langsung, saya dapat melihat Anda melalui mereka.",
  ui_story_1013_10130201_25_dialog_content = "Eh... Baiklah...",
  ui_story_1013_10130201_26_dialog_content = "Baiklah, ayo pergi! Pusat penelitian menunggu!",
  ui_story_1013_10130201_27_dialog_content = "Mari berangkat, PlayerName!",
  ui_story_1013_10130201_28_dialog_content = "Setiap orang! Navigator ada di sini!",
  ui_story_1013_10130201_29_dialog_content = "Tunggu, apakah ini THE Navigator? Oh, saya sudah menjadi penggemar begitu lama!",
  ui_story_1013_10130201_30_dialog_content = "Hmm, dia masih kecil, tapi sebagai subjek tes... dia sudah cukup.",
  ui_story_1013_10130201_31_dialog_content = "Subjek tes?!",
  ui_story_1013_10130201_32_dialog_content = "PlayerName adalah teman saya, bukan subjek tes!",
  ui_story_1013_10130201_33_dialog_content = "Haha, jangan pedulikan mereka. Hampir semua peneliti di sini memiliki sesuatu yang sedikit aneh tentang mereka.",
  ui_story_1013_10130201_34_dialog_content = "Tapi jangan khawatir, mereka sama sekali tidak berbahaya.",
  ui_story_1013_10130201_35_dialog_content = "Grand Marshal, semua yang ada di sini telah disiapkan seperti yang diinstruksikan. Kami siap untuk memulai penelitian kami.",
  ui_story_1013_10130201_36_dialog_content = "Bagus. Tapi satu hal terakhir.",
  ui_story_1013_10130201_37_dialog_content = "Masih ada lagi?",
  ui_story_1013_10130201_38_dialog_content = "Ya. Saya perlu mengungkapkan rasa terima kasih saya kepada Anda.",
  ui_story_1013_10130201_39_dialog_content = "Hm?",
  ui_story_1013_10130201_40_dialog_content = "Bukankah kau baru saja berterima kasih padaku?",
  ui_story_1013_10130201_41_dialog_content = "Itu dalam kapasitas pribadi. Tapi kali ini, sebagai Marsekal Agung dari Federasi Illumina.",
  ui_story_1013_10130201_42_dialog_content = "Mengizinkan Illumina melakukan penelitian ini tidak diragukan lagi akan menyelamatkan nyawa Aurorian yang tak terhitung jumlahnya.",
  ui_story_1013_10130201_43_dialog_content = "Terima kasih, PlayerName!",
  ui_story_1013_10130201_44_dialog_content = "Terima kasih juga, anak muda, meskipun beban kerja meningkat.",
  ui_story_1013_10130201_45_dialog_content = "Terima kasih!",
  ui_story_1013_10130201_46_dialog_content = "Terima kasih atas kontribusi Anda, subjek tes.",
  ui_story_1013_10130201_47_dialog_content = "Tapi aku bahkan belum melakukan apa-apa?!",
  ui_story_1013_10130201_48_dialog_content = "Terima saja ucapan terima kasih mereka.",
  ui_story_1013_10130201_49_dialog_content = "Lagi pula, persetujuan Anda diperlukan agar semua ini terjadi.",
  ui_story_1013_10130201_50_dialog_content = "Hmm…",
  ui_story_1013_10130201_51_dialog_content = "Hei, bisakah kalian semua berhenti menatapku seperti itu? Ini sedikit canggung …",
  ui_story_1013_10130201_52_dialog_content = "Apakah kalian tidak memiliki penelitian untuk dilakukan atau sesuatu?",
  ui_story_1013_10130201_53_dialog_content = "Haha, kamu benar sekali.",
  ui_story_1013_10130201_54_dialog_content = "Kalian semua, mulai bekerja. Tetap pada agenda kita.",
  ui_story_1013_10130201_55_dialog_content = "Siap, Kapten.",
  ui_story_1013_10130201_56_dialog_content = "Semuanya, bagi menjadi tiga kelompok seperti yang dibicarakan oleh Grand Marshall.",
  ui_story_1013_10130201_57_dialog_content = "Grup A, menuju Obelisk of Return dan cari informasi tentang Chord Link.",
  ui_story_1013_10130201_58_dialog_content = "Grup B, dengan saya. Kami sedang mengumpulkan data tentang peralatan medis Soroz.",
  ui_story_1013_10130201_59_dialog_content = "Kalian semua, Grup C, tunggu perintahku, lalu sambungkan kabel transmisi data ke Ruang Simulasi Soroz.",
  ui_story_1013_10130201_60_dialog_content = "Lihat apakah kita bisa menggunakan Illumina Battle Simulator untuk menganalisis data dari Ruang Simulasi.",
  ui_story_1013_10130201_61_dialog_content = "Siap, Kapten!",
  ui_story_1013_10130201_62_dialog_content = "Illumina memiliki Simulator Pertempuran?",
  ui_story_1013_10130201_63_dialog_content = "Ya. Terakhir kali, ketika Gronru membantu Soroz memasang Ruang Simulasi, kami memperoleh banyak data penelitian.",
  ui_story_1013_10130201_64_dialog_content = "Setelah dia kembali ke Illumina, dia membuat mesin serupa yang dimodelkan dari yang ada di Soroz.",
  ui_story_1013_10130201_65_dialog_content = "Meskipun pada awalnya, yang ingin dia lakukan hanyalah membuat mesin game…",
  ui_story_1013_10130201_66_dialog_content = "Namun, pada akhirnya, ternyata menjadi sesuatu yang luar biasa!",
  ui_story_1013_10130201_67_dialog_content = "Itu mengesankan menakutkan ...",
  ui_story_1013_10130201_68_dialog_content = "Ya! Jika Anda tertarik, Anda dapat mencobanya sendiri selama percobaan nanti.",
  ui_story_1013_10130201_69_dialog_content = "Kedengarannya bagus!",
  ui_story_1013_10130201_70_dialog_content = "Saya harus berlatih sebelumnya dan membuatnya berpikir berbeda tentang saya!",
  ui_story_1013_10130201_71_dialog_content = "<color=#e8d9bb>Beberapa jam kemudian</color>",
  ui_story_1013_10130201_72_dialog_content = "Melaporkan, Marsekal Agung.",
  ui_story_1013_10130201_73_dialog_content = "Ada penemuan?",
  ui_story_1013_10130201_74_dialog_content = "Kabar baik, Bu. Kami berhasil mengekstrak informasi tentang metode pembuatan peralatan medis Soroz dari modul baru.",
  ui_story_1013_10130201_75_dialog_content = "Informasi ini akan memungkinkan kami untuk meningkatkan semua peralatan kami saat ini di pusat.",
  ui_story_1013_10130201_76_dialog_content = "Kerja bagus!",
  ui_story_1013_10130201_77_dialog_content = "Ikuti terus penelitian, dan lihat apakah Anda dapat membuat penemuan baru lainnya.",
  ui_story_1013_10130201_78_dialog_content = "Siap, Kapten.",
  ui_story_1013_10130201_79_dialog_content = "Peralatan medis…",
  ui_story_1013_10130201_80_dialog_content = "Pria Zhao itu tampaknya tidak dalam kondisi yang baik, secara fisik.",
  ui_story_1013_10130201_81_dialog_content = "Jika peralatan medis ditingkatkan, mungkin dia bisa dibantu?",
  ui_story_1013_10130201_82_dialog_content = "Oh? Anda tahu Zhao?",
  ui_story_1013_10130201_83_dialog_content = "Yah, semacam. Saya bertemu dengannya secara kebetulan di pusat medis, dan kami berbicara sedikit.",
  ui_story_1013_10130201_84_dialog_content = "Aku tahu.",
  ui_story_1013_10130201_85_dialog_content = "Zhao adalah Kepala Staf Illumina Garrison di Twilight. Dia memiliki pikiran yang luar biasa, tetapi tubuh yang lemah.",
  ui_story_1013_10130201_86_dialog_content = "Dia terluka parah ketika dia masih muda. Darkflow merusak organnya, membuatnya tidak bisa bertarung.",
  ui_story_1013_10130201_87_dialog_content = "Tidak heran dia mengeluarkan aura seseorang dengan penyakit kronis.",
  ui_story_1013_10130201_88_dialog_content = "Tak hanya itu, anak buahnya Sean juga dirundung masalah fisik.",
  ui_story_1013_10130201_89_dialog_content = "Sean? Tapi sepertinya dia bisa lari maraton tanpa berkeringat!",
  ui_story_1013_10130201_90_dialog_content = "Itu karena dia menempatkan dirinya melalui pelatihan yang konstan dan melelahkan.",
  ui_story_1013_10130201_91_dialog_content = "Ia memiliki cacat genetik yang agak rumit.",
  ui_story_1013_10130201_92_dialog_content = "Ini juga membuatnya diabaikan ketika pertama kali bergabung dengan tentara. Dia dikirim ke stasiun terpencil sebagai prajurit kaki.",
  ui_story_1013_10130201_93_dialog_content = "Kemauan dan tekad luar biasa anak itu adalah untuk berterima kasih atas semua yang telah dia capai.",
  ui_story_1013_10130201_94_dialog_content = "Ya, saya bisa merasakan sesuatu dalam dirinya yang jelas terasah selama bertahun-tahun kesulitan.",
  ui_story_1013_10130201_95_dialog_content = "Betul sekali. Dan itulah mengapa, saat pemutakhiran kami selesai, dia dan orang-orang seperti dia akan menjadi penerima manfaat pertama.",
  ui_story_1013_10130201_96_dialog_content = "Grand Marshal, kami telah membuat kemajuan dengan penelitian kami tentang Chord Link.",
  ui_story_1013_10130201_97_dialog_content = "Sangat cepat?!",
  ui_story_1013_10130201_98_dialog_content = "Jangan remehkan pengetahuan teknologi Illumina, subjek tes.",
  ui_story_1013_10130201_99_dialog_content = "Tapi bagaimanapun, Grand Marshall, kami pikir kami harus melapor padamu, tapi...",
  ui_story_1013_10130201_100_dialog_content = "(Apakah dia hanya melirikku?)",
  ui_story_1013_10130201_101_dialog_content = "PlayerName adalah penguasa Eraveil, dan Chord Link.",
  ui_story_1013_10130201_102_dialog_content = "Tidak ada tentang penelitian ini yang tidak bisa dikatakan di depannya.",
  ui_story_1013_10130201_103_dialog_content = "Sangat baik. Dalam hal ini, saya akan menjelaskannya dengan cukup sederhana sehingga subjek tes pun dapat mengikuti.",
  ui_story_1013_10130201_104_dialog_content = "Berdasarkan hasil pemeriksaan fisik yang dilakukan pada Komandan Barton dan Letnan Wakil, kita sudah dapat berhipotesis untuk apa perangkat itu mungkin digunakan.",
  ui_story_1013_10130201_105_dialog_content = "Kami menduga selain mampu memodifikasi tubuh Aurorian, Chord Link juga mampu mengeluarkan potensi terpendam mereka.",
  ui_story_1013_10130201_106_option_content = "Memodifikasi tubuh?",
  ui_story_1013_10130201_107_dialog_content = "Apakah kamu tidak memperhatikan? Penampilan Komandan Barton dan Wakil Letnan, sedikit banyak, telah berubah.",
  ui_story_1013_10130201_108_dialog_content = "Saya tahu itu, tetapi selain penampilan mereka, dapatkah modifikasi ini memengaruhi tubuh dengan cara lain?",
  ui_story_1013_10130201_109_dialog_content = "Kami harus melakukan lebih banyak penelitian sebelum sampai pada kesimpulan apa pun.",
  ui_story_1013_10130201_110_dialog_content = "Namun satu hal yang dapat kami simpulkan adalah bahwa perubahan ini berdampak pada Luminatics yang mereka gunakan.",
  ui_story_1013_10130201_111_option_content = "Potensi terpendam?",
  ui_story_1013_10130201_112_dialog_content = "Ya. Kami percaya bahwa modifikasi Chord Link juga memengaruhi cara mereka menggunakan Luminatics.",
  ui_story_1013_10130201_113_dialog_content = "Mengizinkan mereka melepaskan kekuatan yang sebelumnya tidak mungkin, atau setidaknya sulit, untuk dikendalikan.",
  ui_story_1013_10130201_114_dialog_content = "Dan itu membawa kita kembali ke teori Luminatics.",
  ui_story_1013_10130201_115_dialog_content = "Saya tidak keberatan menghabiskan sepanjang hari merinci setiap aspek Luminatics untuk subjek tes.",
  ui_story_1013_10130201_116_dialog_content = "Uh... Saya rasa itu tidak perlu.",
  ui_story_1013_10130201_117_dialog_content = "Tidak perlu terlalu khawatir, subjek tes.",
  ui_story_1013_10130201_118_dialog_content = "Bahkan setelah menggunakan Chord Link, mereka masih mempertahankan kemampuan untuk menggunakan Luminatics lama mereka.",
  ui_story_1013_10130201_119_dialog_content = "Ini membuat kita percaya bahwa sifat dasar mereka tetap tidak berubah.",
  ui_story_1013_10130201_120_dialog_content = "Benarkah…?",
  ui_story_1013_10130201_121_dialog_content = "Kalian membicarakan sesuatu yang serius?",
  ui_story_1013_10130201_122_dialog_content = "Apakah itu helm untuk Battle Simulator yang Anda pegang?",
  ui_story_1013_10130201_123_dialog_content = "Apakah Anda membuat kemajuan?",
  ui_story_1013_10130201_124_dialog_content = "Ya!",
  ui_story_1013_10130201_125_dialog_content = "Kami menghubungkan Battle Simulator ke database Soroz.",
  ui_story_1013_10130201_126_dialog_content = "Tepat di awal eksperimen kami, kami tampaknya telah memicu beberapa fungsi dalam komponen baru Soroz.",
  ui_story_1013_10130201_127_dialog_content = "Ruang Simulasi ditingkatkan sendiri, dan sekarang dapat sepenuhnya mensimulasikan kondisi medan perang nyata!",
  ui_story_1013_10130201_128_dialog_content = "Anda dapat mencobanya sekarang menggunakan Battle Simulator.",
  ui_story_1013_10130201_129_dialog_content = "Saya pikir saya baru saja mendengar PlayerName tertarik.",
  ui_story_1013_10130201_130_dialog_content = "Apa yang kamu katakan? Ingin mencobanya?",
  ui_story_1013_10130201_131_option_content = "Apakah itu sulit?",
  ui_story_1013_10130201_132_dialog_content = "Aku tidak akan memberimu waktu yang sulit! Karena ini game baru, kita akan mulai dengan tingkat kesulitan yang paling mudah.",
  ui_story_1013_10130201_133_dialog_content = "Baiklah, mari kita lakukan!",
  ui_story_1013_10130201_134_option_content = "Tentu saja!",
  ui_story_1013_10130201_135_dialog_content = "Kedengarannya mengagumkan!",
  ui_story_1013_10130201_136_dialog_content = "Baiklah kalau begitu! Duduklah di sana, PlayerName, dan kenakan helm ini.",
  ui_story_1013_10130201_137_dialog_content = "Selesai.",
  ui_story_1013_10130201_138_dialog_content = "Hah? Lingkungan berubah!",
  ui_story_1013_10130201_139_dialog_content = "Apa kamu bisa dengar aku, PlayerName?",
  ui_story_1013_10130201_140_dialog_content = "Keburukan?! Kamu ada di mana?",
  ui_story_1013_10130201_141_dialog_content = "Aku tepat di sampingmu!",
  ui_story_1013_10130201_142_dialog_content = "Ada layar di sini, jadi saya bisa melihat apa yang Anda lihat.",
  ui_story_1013_10130201_143_dialog_content = "Jadi, PlayerName, apa yang kamu lihat?",
  ui_story_1013_10130201_144_dialog_content = "Hutan belantara yang benar-benar sepi. Ada angin sepoi-sepoi dan cukup cerah.",
  ui_story_1013_10130201_145_dialog_content = "Kedengarannya akurat.",
  ui_story_1013_10130201_146_dialog_content = "Di situlah Battle Simulator memulai Anda.",
  ui_story_1013_10130201_147_dialog_content = "Sekarang, PlayerName, bayangkan teman Anda berdiri di samping Anda.",
  ui_story_1013_10130201_148_dialog_content = "Bayangkan seperti apa rupa mereka?",
  ui_story_1013_10130201_149_dialog_content = "Benar sekali!",
  ui_story_1013_10130201_150_dialog_content = "Simulator Pertempuran akan memproyeksikan gambar Aurorian yang sesuai menggunakan gambar yang Anda bayangkan dalam pikiran Anda dan data Illumina yang ada.",
  ui_story_1013_10130201_151_dialog_content = "Proyeksi Aurorian ini akan membantu Anda menyelesaikan ujian pertempuran.",
  ui_story_1013_10130201_152_option_content = "Pikirkan Wakil.",
  ui_story_1013_10130201_153_dialog_content = "Woah!",
  ui_story_1013_10130201_154_dialog_content = "Muncul!",
  ui_story_1013_10130201_155_dialog_content = "Itu luar biasa. Itu terlihat seperti saya!",
  ui_story_1013_10130201_156_dialog_content = "Bagus sekali! Semuanya berjalan lancar.",
  ui_story_1013_10130201_157_dialog_content = "Selanjutnya, izinkan saya memperkenalkan beberapa Eclipsites ke TKP.",
  ui_story_1013_10130201_158_dialog_content = "Gaaah!",
  ui_story_1013_10130201_159_dialog_content = "Wow! Eclipsites juga tampak nyata.",
  ui_story_1013_10130201_160_dialog_content = "Saya hampir bisa merasakan Aliran Gelap datang dari mereka!",
  ui_story_1013_10130201_161_dialog_content = "Jangan takut.",
  ui_story_1013_10130201_162_dialog_content = "Ini hanya tes paling dasar!",
  ui_story_1013_10130201_163_dialog_content = "Coba kalahkan Eclipsites itu dengan Aurorian virtual!",
  ui_story_1013_10130201_164_dialog_content = "Kau pasti bisa, PlayerName!",
  ui_story_1013_10130201_165_dialog_content = "Oke! Aku akan melakukan yang terbaik!",
  ui_story_1013_10130201_166_dialog_content = "Kesulitan: Mudah.",
  ui_story_1013_10130201_167_dialog_content = "Mode Default, nomor seri panggung: 01.",
  ui_story_1013_10130201_168_dialog_content = "Tujuan: Hilangkan semua Eclipsites.",
  ui_story_1013_10130201_169_dialog_content = "Inisialisasi simulator...",
  ui_story_1013_10130201_170_dialog_content = "<anim type=Shake><size=50>Keren!!!</size></anim>",
  ui_story_1013_10130302_1_dialog_content = "Fiuh... Eclipsites semua ditangani!",
  ui_story_1013_10130302_2_dialog_content = "Tujuan panggung selesai.",
  ui_story_1013_10130302_3_dialog_content = "Tes selesai. Nilai panggung: A.",
  ui_story_1013_10130302_4_dialog_content = "Menakjubkan, PlayerName! Anda mendapat nilai A pada percobaan pertama Anda di Battle Simulator!",
  ui_story_1013_10130302_5_dialog_content = "Beri saya waktu sebentar, saya harus memutuskan koneksi Anda dari simulator sebelum Anda dapat melepas helm Anda.",
  ui_story_1013_10130302_6_dialog_content = "Terputus. Aman untuk keluar sekarang.",
  ui_story_1013_10130302_7_dialog_content = "Nng...",
  ui_story_1013_10130302_8_dialog_content = "Bagaimana perasaanmu, PlayerName? Semuanya bagus?",
  ui_story_1013_10130302_9_dialog_content = "Oke, saya kira. Saya merasa seperti saya benar-benar baru saja melawan sekelompok Eclipsites. Saya lelah, secara fisik dan mental!",
  ui_story_1013_10130302_10_dialog_content = "Ha ha ha! Yah, bagaimanapun juga, kerja bagus, PlayerName.",
  ui_story_1013_10130302_11_dialog_content = "Namun, ini hanya membuktikan manfaat teknologi.",
  ui_story_1013_10130302_12_dialog_content = "Dengan hanya menggunakan beberapa fungsi ruang simulasi Soroz, kita dapat menciptakan kembali kondisi pertempuran yang sebenarnya dengan sempurna.",
  ui_story_1013_10130302_13_dialog_content = "Ini jauh lebih baik daripada teori dan simulasi militer yang membosankan!",
  ui_story_1013_10130302_14_dialog_content = "Itu membuat saya ingin mencobanya!",
  ui_story_1013_10130302_15_dialog_content = "Saya khawatir Anda harus menunggu lain kali.",
  ui_story_1013_10130302_16_dialog_content = "Ini adalah teknologi Caelestite, dan hanya dapat diuji oleh PlayerName sekarang juga.",
  ui_story_1013_10130302_17_dialog_content = "Setelah kami sepenuhnya memahami apa yang membuat teknologi ini tergerak, kami harus dapat memodifikasinya untuk Aurorian!",
  ui_story_1013_10130302_18_dialog_content = "Dengan penelitian Battle Simulator sebagai prioritas utama, apakah akan siap untuk latihan militer bersama kita?",
  ui_story_1013_10130302_19_dialog_content = "Saya rasa akan ada lebih banyak minat pada latihan ini jika kita dapat menggunakan teknologi ini!",
  ui_story_1013_10130302_20_dialog_content = "Seharusnya tidak masalah jika PlayerName ada untuk membantu!",
  ui_story_1013_10130302_21_dialog_content = "Latihan militer gabungan? Apa itu?",
  ui_story_1013_10130302_22_dialog_content = "Pelatihan yang terjadi setiap beberapa tahun!",
  ui_story_1013_10130302_23_dialog_content = "Bukan hanya Federasi Illumina yang ikut ambil bagian. Lumopolis, Northland, dan bahkan Umbraton bergabung.",
  ui_story_1013_10130302_24_dialog_content = "Selain kolaborasi militer berskala besar, masing-masing negara peserta juga mengirimkan yang terbaik dan terpandai untuk berkompetisi di ajang individu.",
  ui_story_1013_10130302_25_dialog_content = "Di akhir latihan, semua yang ambil bagian terlibat melawan Eclipsites yang sebenarnya dalam pertempuran sesungguhnya.",
  ui_story_1013_10130302_26_dialog_content = "Kedengarannya seperti acara yang meriah ...",
  ui_story_1013_10130302_27_dialog_content = "Suka sekali!",
  ui_story_1013_10130302_28_dialog_content = "Semua orang ingin menjadi yang pertama dalam kompetisi individu.",
  ui_story_1013_10130302_29_dialog_content = "Pemenang memenangkan kesempatan untuk bertanding satu lawan satu dengan Grand Marshal Reinhardt sendiri!",
  ui_story_1013_10130302_30_dialog_content = "Hah?!",
  ui_story_1013_10130302_31_dialog_content = "Awalnya itu hanya hal yang memacu-of-the-moment. Saya selalu bertanya kepada para pemenang apakah mereka ingin bertanding satu atau dua ronde.",
  ui_story_1013_10130302_32_dialog_content = "Tapi kemudian, itu tampaknya menjadi bagian dari program yang diterima.",
  ui_story_1013_10130302_33_dialog_content = "Yang mengatakan, saya tidak menyukainya.",
  ui_story_1013_10130302_34_option_content = "Apakah itu tidak mengganggu Anda?",
  ui_story_1013_10130302_35_dialog_content = "Tidak sedikit pun! Saya benar-benar menantikannya.",
  ui_story_1013_10130302_36_option_content = "Kedengarannya seperti Anda!",
  ui_story_1013_10130302_37_dialog_content = "Ha ha ha! Terima kasih, saya akan menganggap itu sebagai pujian.",
  ui_story_1013_10130302_38_dialog_content = "Mampu bersilangan pedang dengan yang terbaik dari generasi muda adalah kenikmatan nyata bagi saya.",
  ui_story_1013_10130302_39_dialog_content = "Menonton dengan mata kepala sendiri saat mereka tumbuh dan menjadi lebih kuat...",
  ui_story_1013_10130302_40_dialog_content = "Hingga tiba saatnya mereka melampaui kita, dan mengambil tempat yang selayaknya sebagai pemimpin baru di era baru.",
  ui_story_1013_10130302_41_dialog_content = "Saya menjadi emosional hanya dengan memikirkannya.",
  ui_story_1013_10130302_42_dialog_content = "Dengan siapa Reinhardt berdebat?",
  ui_story_1013_10130302_43_dialog_content = "Saya pikir pemenang terakhir dari acara individu adalah Carleen!",
  ui_story_1013_10130302_44_dialog_content = "Dia lebih dari sepuluh poin dari tempat kedua, dan membuatnya terlihat mudah!",
  ui_story_1013_10130302_45_dialog_content = "Carleen benar-benar yang terbaik dari generasi baru.",
  ui_story_1013_10130302_46_dialog_content = "Saat kami bertanding terakhir kali, dia bilang dia akan kembali ke tempat pertama juga di lain waktu.",
  ui_story_1013_10130302_47_dialog_content = "Saya berani bertaruh bahwa ketika hari itu tiba, dia bahkan mungkin cukup kuat untuk mengalahkan saya.",
  ui_story_1013_10130302_48_dialog_content = "Ha ha ha! Aku tak sabar untuk itu!",
  ui_story_1013_10130302_49_dialog_content = "Saya sangat cemburu...",
  ui_story_1013_10130302_50_dialog_content = "Saya ingin kesempatan untuk berdebat dengan Anda, Grand Marshal. Saya yakin saya akan belajar banyak!",
  ui_story_1013_10130302_51_dialog_content = "Kemudian berlatih keras, dan lakukan yang terbaik untuk mencapai tempat pertama.",
  ui_story_1013_10130302_52_dialog_content = "Ya!",
  ui_story_1013_10130302_53_dialog_content = "Kamu juga, PlayerName!",
  ui_story_1013_10130302_54_dialog_content = "Aku?!",
  ui_story_1013_10130302_55_dialog_content = "Tentu! Tidak ada peraturan yang mengatakan bahwa peserta harus Aurorian.",
  ui_story_1013_10130302_56_dialog_content = "Ketika masih ada Caelestite di Astra, mereka sering bertarung bersama Aurorian.",
  ui_story_1013_10130302_57_dialog_content = "Jika Anda dapat mengambil bagian, hampir seolah-olah Caelestites telah kembali.",
  ui_story_1013_10130302_58_dialog_content = "\"Kembali,\" hah...",
  ui_story_1013_10130302_59_dialog_content = "Dan jika Anda datang lebih dulu, saya akan berdebat dengan Anda juga.",
  ui_story_1013_10130302_60_dialog_content = "Tidak, tidak perlu!",
  ui_story_1013_10130302_61_dialog_content = "Jika aku melawanmu, aku ragu aku akan pergi hidup-hidup...",
  ui_story_1013_10130302_62_dialog_content = "Mengapa kita tidak menjadikannya simulasi militer?",
  ui_story_1013_10130302_63_dialog_content = "Jika ini hanya simulasi, saya siap untuk itu!",
  ui_story_1013_10130302_64_dialog_content = "Bagus sekali! Kalau begitu, aku menunggu penobatanmu sebagai juara!",
  ui_story_1013_10130302_65_dialog_content = "Maaf mengganggu pembicaraan Anda.",
  ui_story_1013_10130302_66_dialog_content = "Kami telah menyelesaikan percobaan hari ini!",
  ui_story_1013_10130302_67_dialog_content = "Tim saya dan saya perlu menganalisis hasil dan menyesuaikan simulator. Saya pikir besok kita harus dapat melanjutkan ke fase pengujian berikutnya.",
  ui_story_1013_10130302_68_dialog_content = "Serahkan pada kami!",
  ui_story_1013_10130302_69_dialog_content = "Masih ada tahap lainnya?",
  ui_story_1013_10130302_70_dialog_content = "Tentu saja! Hari ini hanya melibatkan pengujian pendahuluan dasar.",
  ui_story_1013_10130302_71_dialog_content = "Simulator Pertempuran masih memiliki banyak fungsi yang perlu dijelajahi!",
  ui_story_1013_10130302_72_dialog_content = "Tapi perawatan Soroz...",
  ui_story_1013_10130302_73_dialog_content = "Tenang, kami tidak akan melupakan itu.",
  ui_story_1013_10130302_74_dialog_content = "Pemeliharaan Soroz dan riset Battle Simulator dapat dilakukan pada saat yang bersamaan!",
  ui_story_1013_10130302_75_dialog_content = "Tapi Anda harus memberi kami waktu.",
  ui_story_1013_10130302_76_dialog_content = "Harap bersabar. Mengapa tidak pergi dan istirahat yang baik?",
  ui_story_1013_10130302_77_dialog_content = "Baiklah, saya kira hanya itu yang bisa saya lakukan untuk saat ini.",
  ui_story_1013_10130302_78_dialog_content = "Ya. Mari kita istirahat untuk saat ini.",
  ui_story_1013_10130302_79_dialog_content = "Segala sesuatu yang lain bisa menunggu sampai besok!",
  ui_story_1013_10130401_1_dialog_content = "<color=#e8d9bb>Menggeram-</color>",
  ui_story_1013_10130401_2_dialog_content = "Aku lapar...",
  ui_story_1013_10130401_3_dialog_content = "<color=#e8d9bb>Groar!</color>",
  ui_story_1013_10130401_4_dialog_content = "Aku sangat lapar!",
  ui_story_1013_10130401_5_dialog_content = "Setelah selesai di pusat penelitian kemarin, Vice mengajakku bermalam di Kota Gannon.",
  ui_story_1013_10130401_6_dialog_content = "Saya tidak berpikir saya akan bangun sangat terlambat hari ini!",
  ui_story_1013_10130401_7_dialog_content = "<color=#e8d9bb>*Perut keroncongan*</color>",
  ui_story_1013_10130401_8_dialog_content = "Itu dia. Harus menemukan sesuatu untuk dimakan.",
  ui_story_1013_10130401_9_dialog_content = "Kota ini sangat besar, saya yakin ada banyak tempat untuk mendapatkan makanan.",
  ui_story_1013_10130401_10_dialog_content = "Saya harap itu tidak terlalu mahal. Saya tidak punya banyak Nightium yang tersisa.",
  ui_story_1013_10130401_11_dialog_content = "Tidak.",
  ui_story_1013_10130401_12_dialog_content = "Lain tidak?",
  ui_story_1013_10130401_13_dialog_content = "Kenapa benar-benar tidak ada apa-apa?!",
  ui_story_1013_10130401_14_dialog_content = "Saya sudah berjalan bermil-mil, tidak menemukan makanan, dan sekarang saya bahkan lebih lapar!",
  ui_story_1013_10130401_15_dialog_content = "Aku bersumpah pandanganku sudah memudar...",
  ui_story_1013_10130401_16_dialog_content = "Tunggu! Apa itu... makanan yang aku cium?!",
  ui_story_1013_10130401_17_dialog_content = "PlayerName?!",
  ui_story_1013_10130401_18_dialog_content = "Bangun, PlayerName ! Anda tidak ingin tidur di sini!",
  ui_story_1013_10130401_19_option_content = "V-Wakil?!",
  ui_story_1013_10130401_20_dialog_content = "Apa kamu baik baik saja? Anda tidak terlihat begitu baik.",
  ui_story_1013_10130401_21_dialog_content = "Saya baik-baik saja. Yah, sebenarnya aku kelaparan, dan tidak bisa menemukan tempat makan dimanapun...",
  ui_story_1013_10130401_22_dialog_content = "Saya berkeliaran dengan sia-sia selama berabad-abad, hanya untuk kembali ke sini.",
  ui_story_1013_10130401_23_dialog_content = "Oh, aku sangat menyesal! Saya lupa menyebutkan.",
  ui_story_1013_10130401_24_dialog_content = "Illumina menjalankan sistem penjatahan, jadi tidak ada restoran atau apapun di Gannon.",
  ui_story_1013_10130401_25_dialog_content = "Jika pengunjung membutuhkan perbekalan, mereka harus pergi ke area yang ditentukan dan melewati semua rintangan birokrasi terlebih dahulu.",
  ui_story_1013_10130401_26_dialog_content = "Kami sangat sibuk dengan ujian kemarin sehingga saya benar-benar lupa mendaftar...",
  ui_story_1013_10130401_27_dialog_content = "Petugas Vivian sudah mengatur jatah untukmu, jadi ayo kita ambil setelah selesai hari ini!",
  ui_story_1013_10130401_28_dialog_content = "Sepertinya agak merepotkan.",
  ui_story_1013_10130401_29_dialog_content = "Ya, produktivitas Federasi Illumina terbatas. Bahkan memastikan semua orang bisa makan bukanlah tugas kecil.",
  ui_story_1013_10130401_30_dialog_content = "Jatah adalah cara terbaik untuk menghindari pemborosan dan memastikan bahwa setiap orang memiliki cukup.",
  ui_story_1013_10130401_31_dialog_content = "Bagaimanapun, lihat apa yang saya bawa! Sarapan!",
  ui_story_1013_10130401_32_dialog_content = "Ta-ra!",
  ui_story_1013_10130401_33_dialog_content = "Jadi itu makanan yang saya cium!",
  ui_story_1013_10130401_34_dialog_content = "Anda pasti kelaparan! Datang dan makan!",
  ui_story_1013_10130401_35_dialog_content = "Kita harus kembali ke pusat penelitian sebentar lagi!",
  ui_story_1013_10130401_36_dialog_content = "Saya sedang menggali!",
  ui_story_1013_10130401_37_dialog_content = "(Saya tidak tahu bahwa tempat yang tampaknya kuat seperti Illumina harus sangat berhati-hati dengan sumber dayanya.)",
  ui_story_1013_10130401_38_dialog_content = "Nyam nyam nyam...",
  ui_story_1013_10130401_39_dialog_content = "Itu lebih baik! Saya merasa hidup kembali sekarang setelah saya kenyang!",
  ui_story_1013_10130401_40_dialog_content = "Yap, saya selalu paling bahagia saat makan!",
  ui_story_1013_10130401_41_dialog_content = "Karena kita sudah diisi ulang, kita harus memulai pekerjaan hari itu.",
  ui_story_1013_10130401_42_dialog_content = "Kami seharusnya terus membantu dengan Battle Simulator, bukan?",
  ui_story_1013_10130401_43_dialog_content = "Ya. Menurut para ilmuwan yang bekerja sepanjang malam, mereka menemukan fungsi baru!",
  ui_story_1013_10130401_44_dialog_content = "Haruskah kita melihatnya?",
  ui_story_1013_10130401_45_dialog_content = "Tentu!",
  ui_story_1013_10130401_46_dialog_content = "<color=#e8d9bb>Pusat Penelitian Illumina</color>",
  ui_story_1013_10130401_47_dialog_content = "Selamat pagi! Kalian berdua akhirnya di sini.",
  ui_story_1013_10130401_48_dialog_content = "Marsekal Agung?!",
  ui_story_1013_10130401_49_dialog_content = "Apa kau menunggu kami selama ini?",
  ui_story_1013_10130401_50_dialog_content = "Ya. Saya ingin melihat sendiri bagaimana Battle Simulator bekerja.",
  ui_story_1013_10130401_51_dialog_content = "Jadi, kalian semua di sini?",
  ui_story_1013_10130401_52_dialog_content = "Kami telah berhasil meng-upgrade Battle Simulator!",
  ui_story_1013_10130401_53_dialog_content = "Betul sekali! Dan kami juga memiliki nama yang benar-benar ditingkatkan untuknya—Battlefield Simulator!",
  ui_story_1013_10130401_54_option_content = "Medan perang?",
  ui_story_1013_10130401_55_dialog_content = "Meskipun satu suku kata tambahan tidak terdengar banyak, perbedaannya sangat besar!",
  ui_story_1013_10130401_56_option_content = "Perbedaan apa?",
  ui_story_1013_10130401_57_dialog_content = "Yang besar!",
  ui_story_1013_10130401_58_dialog_content = "Battlefield Simulator memperbarui dirinya sendiri setelah membaca data yang diambil dari modul baru Soroz.",
  ui_story_1013_10130401_59_dialog_content = "Sekarang, simulasi pertempuran bersejarah yang akurat dapat dibuat ulang dari catatan pertempuran terperinci!",
  ui_story_1013_10130401_60_dialog_content = "Bukan hanya musuh, tetapi waktu setempat, medan, dan bahkan cuaca dapat dibuat ulang dengan sempurna.",
  ui_story_1013_10130401_61_dialog_content = "Luar biasa, bukan?",
  ui_story_1013_10130401_62_dialog_content = "Jadi maksudmu itu mampu menciptakan pertempuran yang lebih realistis?",
  ui_story_1013_10130401_63_dialog_content = "Secara teori, ya.",
  ui_story_1013_10130401_64_dialog_content = "Namun, karena kami belum sepenuhnya mengonfigurasinya, Anda masih satu-satunya yang dapat mencoba Battlefield Simulator.",
  ui_story_1013_10130401_65_dialog_content = "Sooo... kami akan mengandalkanmu lagi hari ini!",
  ui_story_1013_10130401_66_dialog_content = "Aku masih lelah dari kemarin. Semoga hari ini tidak terlalu sulit.",
  ui_story_1013_10130401_67_dialog_content = "Jangan khawatir. Kami menggunakan data pertempuran yang direkam dengan cermat dari masa lalu.",
  ui_story_1013_10130401_68_dialog_content = "Ini akan menjadi jalan-jalan di taman untuk seseorang dengan kemampuan Anda!",
  ui_story_1013_10130401_69_dialog_content = "Semoga beruntung, PlayerName. Aku akan mengawasi dari sini.",
  ui_story_1013_10130401_70_dialog_content = "B-baiklah!",
  ui_story_1013_10130401_71_dialog_content = "Sekarang, buka helmnya, seperti kemarin...",
  ui_story_1013_10130401_72_dialog_content = "Itu tidak terlihat sangat berbeda.",
  ui_story_1013_10130401_73_dialog_content = "Kesabaran! Kami sedang memuat data pertempuran sekarang.",
  ui_story_1013_10130401_74_dialog_content = "Biarku lihat. Mana yang harus saya pilih?",
  ui_story_1013_10130401_75_dialog_content = "Menarik. Bagaimana dengan yang ini?",
  ui_story_1013_10130401_76_dialog_content = "Eh? Apakah Anda yakin, Marsekal Agung?",
  ui_story_1013_10130401_77_dialog_content = "Bukankah itu sedikit...",
  ui_story_1013_10130401_78_dialog_content = "Siapa Takut. Ini tentu dalam kemampuannya.",
  ui_story_1013_10130401_79_dialog_content = "Dia memiliki pengalaman dalam lingkungan pertempuran semacam ini. Percayalah padanya!",
  ui_story_1013_10130401_80_dialog_content = "Siap, Kapten!",
  ui_story_1013_10130401_81_dialog_content = "Tunggu sebentar, Reinhardt!",
  ui_story_1013_10130401_82_dialog_content = "Apa sebenarnya yang kamu pilih?!",
  ui_story_1013_10130401_83_dialog_content = "Anda akan mengetahuinya hanya dalam satu detik.",
  ui_story_1013_10130401_84_dialog_content = "Memuat catatan pertempuran...",
  ui_story_1013_10130401_85_dialog_content = "Kampanye ditemukan: Perang Zona Gelap.",
  ui_story_1013_10130401_86_dialog_content = "Semuanya menjadi gelap seperti Malam Abadi!",
  ui_story_1013_10130401_87_dialog_content = "Urgh... Bahkan perasaan mengerikan dari Darkflow sedang disimulasikan.",
  ui_story_1013_10130401_88_dialog_content = "Bagaimana menurutmu, PlayerName?",
  ui_story_1013_10130401_89_dialog_content = "Ini tentu realistis!",
  ui_story_1013_10130401_90_dialog_content = "Saya bahkan mungkin mengatakan bahwa itu sedikit terlalu realistis!",
  ui_story_1013_10130401_91_dialog_content = "Ini benar-benar terasa seperti pertempuran Zona Gelap, hingga perasaan bingung dari Aliran Gelap!",
  ui_story_1013_10130401_92_dialog_content = "Benarkah? Baguslah kalau begitu!",
  ui_story_1013_10130401_93_option_content = "Apa sebenarnya yang hebat tentang ini?!",
  ui_story_1013_10130401_94_dialog_content = "Semakin realistis kita mendapatkan lingkungan simulasi, semakin berguna Battlefield Simulator.",
  ui_story_1013_10130401_95_dialog_content = "Ini akan memberi pengguna pengalaman paling realistis yang bisa mereka dapatkan dari pertempuran nyata tanpa benar-benar berada di dalamnya; untuk mengalami kenyataan perang yang suram dan keras secara pribadi.",
  ui_story_1013_10130401_96_dialog_content = "Ini juga akan memberi mereka kesempatan untuk mengenal medan perang dan mengasah keterampilan mereka di lingkungan yang kompleks.",
  ui_story_1013_10130401_97_dialog_content = "Kemudian ketika mereka benar-benar menemukan diri mereka dalam konflik yang sebenarnya, akan ada lebih sedikit korban.",
  ui_story_1013_10130401_98_dialog_content = "Masuk akal...",
  ui_story_1013_10130401_99_dialog_content = "Jadi tolong, jadilah orang pertama yang mengalaminya. Bertarunglah sebanyak yang Anda suka, dan cobalah semua simulator yang ditawarkan!",
  ui_story_1013_10130401_100_dialog_content = "Baiklah, saya sedang mengerjakannya.",
  ui_story_1013_10130401_101_dialog_content = "Oke. Bersiap untuk menginisialisasi pertempuran. Siap-siap, PlayerName.",
  ui_story_1013_10130401_102_dialog_content = "Mode Simulasi Medan Perang, nomor seri panggung: 11.328.",
  ui_story_1013_10130401_103_dialog_content = "Tujuan: Menerobos atau menghilangkan Eclipsites.",
  ui_story_1013_10130401_104_dialog_content = "Inisialisasi simulator...",
  ui_story_1013_10130401_105_dialog_content = "Graaaah—!",
  ui_story_1013_10130401_106_dialog_content = "Baiklah, mari kita mulai pesta ini.",
  ui_story_1013_10130502_1_dialog_content = "Menarik kembali! Gunakan batu besar untuk berlindung!",
  ui_story_1013_10130502_2_dialog_content = "...",
  ui_story_1013_10130502_3_dialog_content = "Grr—!",
  ui_story_1013_10130502_4_dialog_content = "Graagh!",
  ui_story_1013_10130502_5_dialog_content = "Dari mana mereka semua berasal?!",
  ui_story_1013_10130502_6_dialog_content = "…!",
  ui_story_1013_10130502_7_dialog_content = "Ini tidak baik. Satu pukulan lagi, dan Vice akan berhenti beraksi.",
  ui_story_1013_10130502_8_dialog_content = "Apa yang harus saya lakukan? Dengan banyak Eclipsites ini, sepertinya tidak bagus...",
  ui_story_1013_10130502_9_dialog_content = "Baiklah, tenang. Tenang aja.",
  ui_story_1013_10130502_10_dialog_content = "Lihat sekeliling. Pasti ada sesuatu.",
  ui_story_1013_10130502_11_dialog_content = "Keburukan! Tembak batu yang mencuat di sana!",
  ui_story_1013_10130502_12_dialog_content = "Roger.",
  ui_story_1013_10130502_13_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_1013_10130502_14_dialog_content = "Graaahh—",
  ui_story_1013_10130502_15_dialog_content = "Besar! Batu itu merobek kumpulan Eclipsites itu!",
  ui_story_1013_10130502_16_dialog_content = "Wakil, sekarang! Ayo dorong!",
  ui_story_1013_10130502_17_dialog_content = "Siap, laksanakan.",
  ui_story_1013_10130502_18_dialog_content = "Di sana! Kita bisa menembus titik lemah itu di sana!",
  ui_story_1013_10130502_19_dialog_content = "Berhasil!",
  ui_story_1013_10130502_20_dialog_content = "Tujuan panggung selesai.",
  ui_story_1013_10130502_21_dialog_content = "Tes selesai. Nilai panggung: C.",
  ui_story_1013_10130502_22_dialog_content = "Huff.. sip..",
  ui_story_1013_10130502_23_dialog_content = "Itu sangat melelahkan...",
  ui_story_1013_10130502_24_dialog_content = "Dan kami hanya mendapat C ?!",
  ui_story_1013_10130502_25_dialog_content = "Kerja yang baik, PlayerName.",
  ui_story_1013_10130502_26_dialog_content = "Sebentar, saya akan memutuskan koneksi Anda.",
  ui_story_1013_10130502_27_dialog_content = "Terputus. Aman untuk keluar sekarang.",
  ui_story_1013_10130502_28_dialog_content = "Dilakukan dengan baik memang, PlayerName!",
  ui_story_1013_10130502_29_dialog_content = "Apa pendapat Anda tentang simulasi Zona Gelap?",
  ui_story_1013_10130502_30_option_content = "Melelahkan...",
  ui_story_1013_10130502_31_dialog_content = "Meskipun saya hanya duduk di sana, pakaian saya masih basah oleh keringat.",
  ui_story_1013_10130502_32_option_content = "Sulit...",
  ui_story_1013_10130502_33_dialog_content = "Saya melakukan yang terbaik, dan menggunakan setiap strategi yang dapat saya pikirkan...",
  ui_story_1013_10130502_34_dialog_content = "Dan masih hanya mendapat C!",
  ui_story_1013_10130502_35_dialog_content = "Tapi kamu melakukannya dengan baik!",
  ui_story_1013_10130502_36_dialog_content = "Betul sekali! Dan tahukah Anda, ini adalah salah satu pertempuran Grand Marshal sendiri.",
  ui_story_1013_10130502_37_dialog_content = "Jadi mendapatkan skor yang Anda dapatkan sudah merupakan pencapaian besar.",
  ui_story_1013_10130502_38_dialog_content = "Tunggu, itu adalah pertempuran yang Reinhard lakukan?",
  ui_story_1013_10130502_39_dialog_content = "Apa hasil dari pertarungan yang sebenarnya?",
  ui_story_1013_10130502_40_dialog_content = "Biar saya cek saja catatannya...",
  ui_story_1013_10130502_41_dialog_content = "Mengerti! Dikatakan di sini bahwa dia berhasil mengalahkan 50 Eclipsites, DAN menerobos, hanya menerima luka ringan dalam prosesnya.",
  ui_story_1013_10130502_42_dialog_content = "Itu mungkin kriteria simulator untuk A atau lebih tinggi.",
  ui_story_1013_10130502_43_dialog_content = "Luar biasa!",
  ui_story_1013_10130502_44_dialog_content = "Untuk mencapai itu, terutama di Dark Zone.",
  ui_story_1013_10130502_45_dialog_content = "Seperti yang diharapkan dari Grand Marshal!",
  ui_story_1013_10130502_46_dialog_content = "Sigh ... Saya berjuang hanya untuk menyelesaikannya.",
  ui_story_1013_10130502_47_dialog_content = "Beri diri Anda beberapa kredit, PlayerName.",
  ui_story_1013_10130502_48_dialog_content = "Ini baru kedua kalinya Anda bertarung di dalam Zona Gelap. Apa yang telah Anda capai sudah sangat mengesankan.",
  ui_story_1013_10130502_49_dialog_content = "Dibandingkan dengan terakhir kali, Anda lebih memperhitungkan lingkungan dan menggunakannya untuk keuntungan Anda.",
  ui_story_1013_10130502_50_dialog_content = "Selain itu, Anda dapat menyelesaikan pertempuran tanpa dukungan tambahan.",
  ui_story_1013_10130502_51_dialog_content = "Anda telah meningkat pesat, yang patut dipuji!",
  ui_story_1013_10130502_52_dialog_content = "Th-terima kasih?",
  ui_story_1013_10130502_53_dialog_content = "Jika saja Federasi Illumina memiliki lebih banyak komandan sepertimu...",
  ui_story_1013_10130502_54_dialog_content = "Pertarungan kita melawan Eclipsites akan jauh lebih lancar.",
  ui_story_1013_10130502_55_dialog_content = "Sekarang aku memikirkannya, PlayerName memang sudah memiliki pemahaman yang kuat tentang perintah ketika kami pertama kali bertemu.",
  ui_story_1013_10130502_56_option_content = "Terima kasih kepada Soroz.",
  ui_story_1013_10130502_57_option_content = "Saya diajari sejak kecil.",
  ui_story_1013_10130502_58_dialog_content = "Hm?",
  ui_story_1013_10130502_59_dialog_content = "Soroz banyak mengajari saya selama 17 tahun saya habiskan di bawah tanah.",
  ui_story_1013_10130502_60_dialog_content = "Termasuk bagaimana menjadi komandan yang baik di medan perang.",
  ui_story_1013_10130502_61_dialog_content = "Caelestites memasukkan komando medan perang dalam silabus akademik mereka...?",
  ui_story_1013_10130502_62_dialog_content = "Tapi saya pikir Caelestites adalah ras yang cinta damai?",
  ui_story_1013_10130502_63_dialog_content = "Hmm. Kalau dipikir-pikir, pengetahuan itu mungkin berasal dari sumber yang sama dengan data di Obelisk of Return.",
  ui_story_1013_10130502_64_dialog_content = "Aku…",
  ui_story_1013_10130502_65_dialog_content = "Apakah Anda meragukan diri sendiri, PlayerName?",
  ui_story_1013_10130502_66_dialog_content = "... Tidak. Aku sudah memikirkannya.",
  ui_story_1013_10130502_67_dialog_content = "Oh?",
  ui_story_1013_10130502_68_dialog_content = "Di mana pun saya memperoleh pengetahuan ini, itu adalah milik saya.",
  ui_story_1013_10130502_69_dialog_content = "Saya hanya akan menggunakannya untuk melindungi rekan saya; bukan untuk tujuan jahat.",
  ui_story_1013_10130502_70_dialog_content = "Ahahaha! Kami hanya berpisah sebentar, tapi rasanya kamu sudah sangat dewasa!",
  ui_story_1013_10130502_71_dialog_content = "B-benarkah?",
  ui_story_1013_10130502_72_dialog_content = "Suka sekali!",
  ui_story_1013_10130502_73_dialog_content = "Setelah insiden Eraveil terakhir kali, saya pikir Anda terlihat sedikit lebih buruk. Saya sebenarnya khawatir untuk sementara waktu.",
  ui_story_1013_10130502_74_dialog_content = "Tapi sekarang tampaknya kekhawatiran seperti itu salah tempat.",
  ui_story_1013_10130502_75_dialog_content = "Jangan meremehkan saya!",
  ui_story_1013_10130502_76_dialog_content = "Tidak, saya pasti tidak akan.",
  ui_story_1013_10130502_77_dialog_content = "Ini sedikit memalukan, meskipun. Saya sudah menyiapkan pidato penghiburan saya, tetapi pada akhirnya, Anda bahkan tidak membutuhkannya.",
  ui_story_1013_10130502_78_dialog_content = "Hah? Pidato?",
  ui_story_1013_10130502_79_dialog_content = "Yah, lebih seperti pepatah lama Illumina:",
  ui_story_1013_10130502_80_dialog_content = "\"Tidak ada kebaikan atau kejahatan yang melekat dalam sains dan teknologi, tetapi hanya ada di hati para Aurorian yang menggunakannya.\"",
  ui_story_1013_10130502_81_dialog_content = "Um…",
  ui_story_1013_10130502_82_dialog_content = "Agak sulit membayangkan kata-kata itu keluar dari mulutmu.",
  ui_story_1013_10130502_83_dialog_content = "Yah, itu bukan kata-kataku! Saya hanya menyampaikan apa yang biasa dikatakan orang-orang tua itu kepada saya.",
  ui_story_1013_10130502_84_dialog_content = "Aku tahu.",
  ui_story_1013_10130502_85_dialog_content = "Terlepas dari itu, saya sangat senang melihat Anda dapat bergerak begitu cepat.",
  ui_story_1013_10130502_86_dialog_content = "Meskipun saya tidak dapat membantu Anda kali ini, jangan ragu untuk datang kepada saya jika ada sesuatu yang Anda butuhkan di masa mendatang.",
  ui_story_1013_10130502_87_dialog_content = "Saya akan membantu Anda dengan cara apa pun yang saya bisa.",
  ui_story_1013_10130502_88_dialog_content = "Tapi saya bukan orang yang paling fasih, jadi saya mungkin tidak memiliki saran yang berguna untuk Anda.",
  ui_story_1013_10130502_89_dialog_content = "Tawaranmu saja sudah sangat mengharukan.",
  ui_story_1013_10130502_90_dialog_content = "Ah, kalau dipikir-pikir, aku masih agak khawatir tentang Soroz...",
  ui_story_1013_10130502_91_dialog_content = "Ya. Kami melakukan semua yang seharusnya kami lakukan. Kami menemukan modulnya dan kembali ke Obelisk of Return untuk diperbaiki.",
  ui_story_1013_10130502_92_dialog_content = "Tapi kenapa Soroz belum juga bangun?",
  ui_story_1013_10130502_93_dialog_content = "Ini di luar kendali kita sekarang.",
  ui_story_1013_10130502_94_dialog_content = "Bahkan Federasi Illumina, yang terkenal dengan teknologi canggihnya, belum benar-benar meneliti kecerdasan buatan.",
  ui_story_1013_10130502_95_dialog_content = "Kesadaran Colossus juga sangat berbeda dari bentuk AI yang lebih umum",
  ui_story_1013_10130502_96_dialog_content = "Saya yakin kita akan menemukan lebih banyak saat kita melanjutkan penelitian kita!",
  ui_story_1013_10130502_97_dialog_content = "Bagaimanapun, mari kita lanjutkan sekarang, karena saya punya kabar baik jika Anda ingin mendengarnya.",
  ui_story_1013_10130502_98_dialog_content = "Ada apa?",
  ui_story_1013_10130502_99_dialog_content = "Kami menemukan beberapa catatan pertempuran di modul baru Soroz.",
  ui_story_1013_10130502_100_dialog_content = "Catatan-catatan ini mungkin setua Colossus dan Obelisk of Return.",
  ui_story_1013_10130502_101_dialog_content = "Hei, jangan mencuri dialogku!",
  ui_story_1013_10130502_102_dialog_content = "Kami yakin akan mungkin mengumpulkan intelijen tentang Colossi dari catatan ini.",
  ui_story_1013_10130502_103_dialog_content = "Saya berasumsi Anda ingin melihat Colossus Anda diperbaiki, subjek tes?",
  ui_story_1013_10130502_104_dialog_content = "... Katakan saja apa yang harus dilakukan.",
  ui_story_1013_10130502_105_dialog_content = "Kami akan memuat data kuno ini ke dalam Battlefield Simulator dan menjalankan sim.",
  ui_story_1013_10130502_106_dialog_content = "Yang perlu Anda lakukan hanyalah bertarung di sim itu.",
  ui_story_1013_10130502_107_dialog_content = "Kami akan mengamati dari luar dan mengumpulkan data yang kami butuhkan.",
  ui_story_1013_10130502_108_dialog_content = "Dan jelas, PlayerName, kami akan memberi Anda semua bantuan dan bimbingan yang kami bisa.",
  ui_story_1013_10130502_109_dialog_content = "Lagipula, kami tidak menguji keterampilan Anda di sini. Ini semua tentang mengumpulkan data.",
  ui_story_1013_10130502_110_dialog_content = "Namun, ini adalah pertama kalinya kami memuat data seperti ini ke dalam simulator.",
  ui_story_1013_10130502_111_dialog_content = "Saya sarankan ekstra hati-hati.",
  ui_story_1013_10130502_112_dialog_content = "Mengerti. Jika ini cara tercepat untuk memperbaiki Soroz, saya setuju.",
  ui_story_1013_10130502_113_dialog_content = "Ayo kita mulai.",
  ui_story_1013_10130502_114_dialog_content = "Hal yang pasti. Duduklah di kursi dan kenakan helm, seperti sebelumnya.",
  ui_story_1013_10130601_1_dialog_content = "Dimana... dimana ini?",
  ui_story_1013_10130601_2_dialog_content = "Sepertinya sebuah kota.",
  ui_story_1013_10130601_3_dialog_content = "Apa yang terjadi dengan padang gurun?",
  ui_story_1013_10130601_4_dialog_content = "Aneh.",
  ui_story_1013_10130601_5_dialog_content = "Hai! Vice, Reinhardt, bisakah kau mendengarku?",
  ui_story_1013_10130601_6_dialog_content = "...",
  ui_story_1013_10130601_7_dialog_content = "Kenapa mereka tidak menjawab?",
  ui_story_1013_10130601_8_dialog_content = "Tentunya simulator tidak dapat berfungsi?",
  ui_story_1013_10130601_9_dialog_content = "<color=#e8d9bb>Di luar sim</color>",
  ui_story_1013_10130601_10_dialog_content = "PlayerName?",
  ui_story_1013_10130601_11_dialog_content = "Hai, PlayerName! Bisakah kamu mendengarku?",
  ui_story_1013_10130601_12_dialog_content = "Apa yang sedang terjadi? Apakah kita kehilangan koneksi?",
  ui_story_1013_10130601_13_dialog_content = "Saya minta maaf. Kami juga tidak tahu!",
  ui_story_1013_10130601_14_dialog_content = "Simulator tidak melaporkan kesalahan apa pun. Dan kita bisa melihat apa PlayerName sedang mengalami.",
  ui_story_1013_10130601_15_dialog_content = "Tapi kita tidak bisa berkomunikasi dengannya.",
  ui_story_1013_10130601_16_dialog_content = "Tapi kenapa!?",
  ui_story_1013_10130601_17_dialog_content = "Cepat, tarik dia keluar dari sim!",
  ui_story_1013_10130601_18_dialog_content = "Kita tidak bisa membiarkannya dalam bahaya.",
  ui_story_1013_10130601_19_dialog_content = "Y-Ya!",
  ui_story_1013_10130601_20_dialog_content = "Hah?",
  ui_story_1013_10130601_21_dialog_content = "Saya tidak bisa memutuskan sambungan. Tapi kenapa?",
  ui_story_1013_10130601_22_dialog_content = "Ada apa lagi kali ini?",
  ui_story_1013_10130601_23_dialog_content = "aku minta maaf. Tapi saya tidak bisa menjelaskannya.",
  ui_story_1013_10130601_24_dialog_content = "Akan akan PlayerName baik-baik saja?",
  ui_story_1013_10130601_25_dialog_content = "Mengapa simulator gagal begitu tiba-tiba?",
  ui_story_1013_10130601_26_dialog_content = "Tidak ada yang seperti ini yang pernah terjadi sebelumnya.",
  ui_story_1013_10130601_27_dialog_content = "Mungkin karena kami menggunakan data pertarungan dari Soroz.",
  ui_story_1013_10130601_28_dialog_content = "Bisakah kita memaksa sim untuk mengakhiri dengan menarik helmnya?",
  ui_story_1013_10130601_29_dialog_content = "Itu tidak disarankan, Grand Marshal.",
  ui_story_1013_10130601_30_dialog_content = "Hah? Saya pikir Anda sedang melihat peralatan medis. Apa yang kamu lakukan di sini?",
  ui_story_1013_10130601_31_dialog_content = "Anda membutuhkan ahli biologi untuk mencari tahu apa yang terjadi pada anak itu. Jadi inilah saya.",
  ui_story_1013_10130601_32_dialog_content = "Kamu benar. Jadi apa yang bisa Anda ceritakan tentang apa yang terjadi PlayerName?",
  ui_story_1013_10130601_33_dialog_content = "Tidak ada, sampai saya melakukan pemeriksaan yang tepat.",
  ui_story_1013_10130601_34_dialog_content = "Tetapi saya dapat mengatakan bahwa semuanya tidak terlihat baik. Saat simulator berjalan, itu membentuk tautan dengan kesadaran pengguna.",
  ui_story_1013_10130601_35_dialog_content = "Jika kita memutuskan hubungan itu dengan paksa, dia akan menghabiskan sisa hidupnya di ranjang rumah sakit.",
  ui_story_1013_10130601_36_dialog_content = "Bagaimana bisa...",
  ui_story_1013_10130601_37_dialog_content = "Tapi kita juga tidak bisa meninggalkannya di sana.",
  ui_story_1013_10130601_38_dialog_content = "Apakah tidak ada yang bisa kita lakukan dari sini?",
  ui_story_1013_10130601_39_dialog_content = "Tetap tenang, Wakil Letnan.",
  ui_story_1013_10130601_40_dialog_content = "Yang dapat Anda lakukan untuk saat ini adalah menjauh dari kami sementara kami mencari cara untuk membantunya.",
  ui_story_1013_10130601_41_dialog_content = "Kemudian terus lakukan apa yang Anda bisa untuk membantu PlayerName.",
  ui_story_1013_10130601_42_dialog_content = "Keluarkan dia dari simulator dengan aman dan secepat mungkin.",
  ui_story_1013_10130601_43_dialog_content = "<color=#e8d9bb>Kembali ke sim</color>",
  ui_story_1013_10130601_44_dialog_content = "Apa yang terjadi di sini?",
  ui_story_1013_10130601_45_dialog_content = "Saya tidak bisa menghubungi peneliti di luar. Saya belum mendengar apa-apa untuk menunjukkan tahap dimulai.",
  ui_story_1013_10130601_46_dialog_content = "Dan dimana ini? Ini bukan Illumina atau Lumopolis.",
  ui_story_1013_10130601_47_dialog_content = "Saya ingat para peneliti mengatakan data berasal dari modul Soroz yang baru.",
  ui_story_1013_10130601_48_dialog_content = "Jadi, apakah itu berarti saya sedang melihat ...",
  ui_story_1013_10130601_49_option_content = "Sebuah kota kuno?",
  ui_story_1013_10130601_50_dialog_content = "Lari!",
  ui_story_1013_10130601_51_dialog_content = "Hah? Mengapa orang-orang itu berlari ke arahku?",
  ui_story_1013_10130601_52_dialog_content = "Lari sekarang! Jangan sampai tertangkap!",
  ui_story_1013_10130601_53_dialog_content = "Tunggu sebentar! Apa yang terjadi?",
  ui_story_1013_10130601_54_dialog_content = "Aaah! Mereka datang!",
  ui_story_1013_10130601_55_dialog_content = "Siapa yang datang? Apa yang sedang terjadi?",
  ui_story_1013_10130601_56_dialog_content = "Tunggu, apakah itu Darkflow?",
  ui_story_1013_10130601_57_dialog_content = "Graaaaaah!",
  ui_story_1013_10130601_58_dialog_content = "Eek! Keburukan!",
  ui_story_1013_10130601_59_dialog_content = "...",
  ui_story_1013_10130601_60_dialog_content = "Syukurlah alam bawah sadar saya menciptakan Wakil imajiner untuk saya tepat pada waktunya ...",
  ui_story_1013_10130601_61_dialog_content = "Lindungi warga sipil! Tetap dalam formasi!",
  ui_story_1013_10130601_62_dialog_content = "Kami tidak perlu takut dari Eclipsites.",
  ui_story_1013_10130601_63_dialog_content = "Angkat senjatamu dan tetap dekat!",
  ui_story_1013_10130601_64_dialog_content = "Serang!!!",
  ui_story_1013_10130601_65_dialog_content = "Grrr!",
  ui_story_1013_10130601_66_dialog_content = "Apakah itu Aurorian? Mereka melawan Eclipsites dengan Luminatics...",
  ui_story_1013_10130601_67_dialog_content = "Tapi sepertinya sangat lemah.",
  ui_story_1013_10130601_68_dialog_content = "Itu tidak merusak Eclipsites.",
  ui_story_1013_10130601_69_dialog_content = "Grrr!",
  ui_story_1013_10130601_70_dialog_content = "Argh!",
  ui_story_1013_10130601_71_option_content = "Kembali!",
  ui_story_1013_10130601_72_dialog_content = "Anda tidak bisa mengalahkan Eclipsites itu!",
  ui_story_1013_10130601_73_dialog_content = "Tidak ada tempat tersisa untuk kembali.",
  ui_story_1013_10130601_74_dialog_content = "Mereka sudah ada di depan pintu kita.",
  ui_story_1013_10130601_75_dialog_content = "Hai! Lari sebelum mereka membunuhmu!",
  ui_story_1013_10130601_76_dialog_content = "Serang!!!",
  ui_story_1013_10130601_77_dialog_content = "Keren!!!",
  ui_story_1013_10130601_78_dialog_content = "Wakil, bantu mereka!",
  ui_story_1013_10130601_79_dialog_content = "Akan melakukan!",
  ui_story_1013_10130602_1_dialog_content = "<color=#e8d9bb>Di luar sim</color>",
  ui_story_1013_10130602_2_dialog_content = "Bagaimana PlayerName sedang mengerjakan?",
  ui_story_1013_10130602_3_dialog_content = "Kami masih menganalisis situasinya.",
  ui_story_1013_10130602_4_dialog_content = "Subjek tetap stabil dan telah menyadari bahwa ada sesuatu yang salah.",
  ui_story_1013_10130602_5_dialog_content = "Dia bertarung dengan Eclipsites. Dan itu memberi kita waktu.",
  ui_story_1013_10130602_6_dialog_content = "Percayai Navigator untuk membantu dengan caranya sendiri!",
  ui_story_1013_10130602_7_dialog_content = "Jangan biarkan usahanya sia-sia. Teruslah bekerja menganalisis data!",
  ui_story_1013_10130602_8_dialog_content = "Paham!",
  ui_story_1013_10130602_9_dialog_content = "Grand Marshal, kami menemukan sesuatu selama analisis kami.",
  ui_story_1013_10130602_10_dialog_content = "Majulah.",
  ui_story_1013_10130602_11_dialog_content = "Kami menganalisis adegan yang sedang diputar di simulator.",
  ui_story_1013_10130602_12_dialog_content = "Bangunan di sana tidak cocok dengan gaya arsitektur Aurorian modern.",
  ui_story_1013_10130602_13_dialog_content = "Tapi mereka identik dengan yang ditemukan Siobhan di kota kuno.",
  ui_story_1013_10130602_14_dialog_content = "Kami pikir datanya sudah ada sebelum bangsa Aurorian.",
  ui_story_1013_10130602_15_dialog_content = "Ini mengingatkan kembali pada periode sejarah yang sudah lama terlupakan.",
  ui_story_1013_10130602_16_dialog_content = "Sejarah kuno, ya ...",
  ui_story_1013_10130602_17_dialog_content = "Terus merekam.",
  ui_story_1013_10130602_18_dialog_content = "Data dari sim kemungkinan akan bisa memberi kita potongan sejarah saat itu.",
  ui_story_1013_10130602_19_dialog_content = "Dan awasi apa yang terjadi pada Navigator. Mungkin kita bisa menemukan sesuatu yang akan membantu kita mengeluarkannya.",
  ui_story_1013_10130602_20_dialog_content = "<color=#e8d9bb>Kembali ke sim</color>",
  ui_story_1013_10130602_21_dialog_content = "Apa yang sedang terjadi? Panggungnya bahkan belum dimulai, namun Eclipsites sudah ada di sini...",
  ui_story_1013_10130602_22_dialog_content = "Ada yang salah. Saya kira simulator pasti tidak berfungsi.",
  ui_story_1013_10130602_23_dialog_content = "Aahhhhhh!",
  ui_story_1013_10130602_24_dialog_content = "...",
  ui_story_1013_10130602_25_dialog_content = "Mereka terus datang. Apakah ini akan pernah berakhir?",
  ui_story_1013_10130602_26_dialog_content = "Aku sendirian di sini dengan Wakil imajiner.",
  ui_story_1013_10130602_27_dialog_content = "Saya tidak bisa mendengar komunikasi apa pun dari teman saya. Bahkan Soroz tidak ada di sini bersamaku.",
  ui_story_1013_10130602_28_dialog_content = "Bagaimana aku bisa mengakhiri situasi aneh ini...",
  ui_story_1013_10130602_29_dialog_content = "Bagaimana jika saya membiarkan Eclipsites membunuh saya? Mungkin itu akan memicu kondisi kegagalan, dan simulasi akan berakhir?",
  ui_story_1013_10130602_30_dialog_content = "Namun, ini adalah pertama kalinya kami memuat data seperti ini ke dalam simulator.",
  ui_story_1013_10130602_31_dialog_content = "Saya sarankan ekstra hati-hati.",
  ui_story_1013_10130602_32_dialog_content = "Tidak, saya tidak bisa mengambil risiko melakukan sesuatu dengan gegabah.",
  ui_story_1013_10130602_33_dialog_content = "Ada sesuatu yang aneh terjadi dengan simulator. Apa pun yang saya lakukan dapat memiliki konsekuensi yang tidak terduga.",
  ui_story_1013_10130602_34_dialog_content = "Dan... yah, aku tidak sendirian, kan?",
  ui_story_1013_10130602_35_dialog_content = "Vice dan yang lainnya akan menyadari ada yang tidak beres. Mereka akan berusaha membantu.",
  ui_story_1013_10130602_36_dialog_content = "<color=#e8d9bb>Gruk!</color>",
  ui_story_1013_10130602_37_dialog_content = "Sekarang apa!?",
  ui_story_1013_10130602_38_dialog_content = "<color=#e8d9bb>DUARR!!!</color>",
  ui_story_1013_10130602_39_dialog_content = "Itu gempa, ya?",
  ui_story_1013_10130602_40_dialog_content = "Tunggu, semuanya... semuanya runtuh!?",
  ui_story_1013_10130602_41_dialog_content = "<color=#e8d9bb>LEDAKAN-!!</color>",
  ui_story_1013_10130602_42_dialog_content = "Mundur! Kembali, sekarang!",
  ui_story_1013_10130602_43_dialog_content = "Setan datang!",
  ui_story_1013_10130602_44_dialog_content = "Iblis?!",
  ui_story_1013_10130602_45_dialog_content = "Aduh! Kepalaku!",
  ui_story_1013_10130602_46_dialog_content = "Aku harus... keluar dari sini...",
  ui_story_1013_10130602_47_dialog_content = "PlayerName.",
  ui_story_1013_10130602_48_dialog_content = "Bangun.",
  ui_story_1013_10130602_49_dialog_content = "Anda belum bisa berhenti.",
  ui_story_1013_10130602_50_dialog_content = "Semuanya berubah lagi!",
  ui_story_1013_10130602_51_dialog_content = "Ada gerombolan Eclipsites di kejauhan!",
  ui_story_1013_10130602_52_dialog_content = "Dan bayangan di langit itu adalah... Colossi!",
  ui_story_1013_10130602_53_dialog_content = "Eclipsites mengendarai Colossi dan melawan Aurorians...",
  ui_story_1013_10130602_54_dialog_content = "Catatan di Obelisk of Return itu benar...",
  ui_story_1013_10130602_55_dialog_content = "Perhatian, semua pasukan tempur—",
  ui_story_1013_10130602_56_dialog_content = "Apakah itu siaran?",
  ui_story_1013_10130602_57_dialog_content = "Pegang garis dan pertahankan resistensi.",
  ui_story_1013_10130602_58_dialog_content = "Umat manusia harus mengalahkan iblis.",
  ui_story_1013_10130602_59_option_content = "\"Iblis\"?",
  ui_story_1013_10130602_60_dialog_content = "Seseorang berteriak tentang setan sebelumnya. Apakah yang mereka maksud adalah Eclipsites?",
  ui_story_1013_10130602_61_option_content = "\"Kemanusiaan\"?",
  ui_story_1013_10130602_62_dialog_content = "Apa itu \"kemanusiaan\"? Bukankah itu seharusnya \"Aurorians\"?",
  ui_story_1013_10130602_63_dialog_content = "Apakah Anda semua mendengarnya? Kita harus berdiri teguh!",
  ui_story_1013_10130602_64_dialog_content = "Tunggu sebentar! Untuk tanah air kita!",
  ui_story_1013_10130602_65_dialog_content = "Tidak, tunggu! Kembali!",
  ui_story_1013_10130602_66_dialog_content = "Anda tidak cukup kuat untuk melawan Eclipsites. Ini adalah misi bunuh diri!",
  ui_story_1013_10130602_67_dialog_content = "Jika Anda tidak berkelahi, menyingkirlah!",
  ui_story_1013_10130602_68_dialog_content = "Mengenakan biaya! Bunuh Eclipsites! Lenyapkan setan!",
  ui_story_1013_10130602_69_dialog_content = "Tetap ditempatmu. Tidak satu langkah mundur.",
  ui_story_1013_10130602_70_dialog_content = "Kemanusiaan harus menang.",
  ui_story_1013_10130602_71_dialog_content = "Keren!!!",
  ui_story_1013_10130602_72_dialog_content = "Argh...!",
  ui_story_1013_10130602_73_dialog_content = "Kita tidak bisa... mundur!",
  ui_story_1013_10130602_74_dialog_content = "Hentikan!!!",
  ui_story_1013_10130602_75_dialog_content = "Lanjutkan pertempuran. Bertekun!",
  ui_story_1013_10130602_76_dialog_content = "Apa sih yang coba dilakukan oleh penyiar itu? Bagaimana mereka bisa mengirim orang ke kematian mereka dengan begitu mudah?",
  ui_story_1013_10130602_77_dialog_content = "<color=#e8d9bb>Tzzst—</color>",
  ui_story_1013_10130602_78_dialog_content = "Memuat... merekam...",
  ui_story_1013_10130602_79_dialog_content = "Itulah Simulator Medan Perang!",
  ui_story_1013_10130602_80_dialog_content = "Apakah akhirnya pulih fungsinya?",
  ui_story_1013_10130602_81_dialog_content = "Kampanye...: ... segera.",
  ui_story_1013_10130602_82_dialog_content = "Pertempuran... nomor seri: Kesalahan.",
  ui_story_1013_10130602_83_dialog_content = "Tujuan: Mundur... tempat yang aman.",
  ui_story_1013_10130602_84_dialog_content = "Mundur? Ada Eclipsites di mana-mana. Ke mana saya harus mundur?",
  ui_story_1013_10130602_85_dialog_content = "Kau disana!",
  ui_story_1013_10130602_86_dialog_content = "Jalankan seperti itu. Di sana aman. Para prajurit akan melindungimu.",
  ui_story_1013_10130602_87_dialog_content = "Dan jangan menyerah. Kemanusiaan akan menang atas iblis!",
  ui_story_1013_10130602_88_dialog_content = "Saya kira saya harus berlari ke arah yang berlawanan dari tempat asal Eclipsites.",
  ui_story_1013_10130602_89_dialog_content = "Battlefield Simulator sangat realistis sehingga saya hampir lupa...",
  ui_story_1013_10130602_90_dialog_content = "bahwa semua yang saya lihat sekarang adalah catatan masa lalu.",
  ui_story_1013_10130602_91_dialog_content = "Dan itu berarti tidak mungkin saya bisa mengubah apa pun.",
  ui_story_1013_10130602_92_dialog_content = "Yang bisa saya lakukan adalah menyelesaikan panggung sehingga semuanya akan berakhir.",
  ui_story_1013_10130602_93_dialog_content = "Inisialisasi simulator...",
  ui_story_1013_10130701_1_dialog_content = "Heh, heh...",
  ui_story_1013_10130701_2_dialog_content = "(Saya tidak tahu ke arah mana saya harus berlari.)",
  ui_story_1013_10130701_3_dialog_content = "(Tapi mengikuti tentara ini seharusnya baik-baik saja.)",
  ui_story_1013_10130701_4_dialog_content = "Hei, kamu di sana! Berlindung di bawah sini.",
  ui_story_1013_10130701_5_dialog_content = "B-baiklah!",
  ui_story_1013_10130701_6_dialog_content = "Hah?",
  ui_story_1013_10130701_7_dialog_content = "(Ada beberapa orang di sana yang tidak berlari.)",
  ui_story_1013_10130701_8_dialog_content = "(Apakah mereka terluka?)",
  ui_story_1013_10130701_9_dialog_content = "Saya ulangi: Terus berjuang dan terus maju!",
  ui_story_1013_10130701_10_dialog_content = "Halo — apakah ada yang terluka? Ada yang butuh bantuan?",
  ui_story_1013_10130701_11_dialog_content = "Terlalu berbahaya di sini. Aku akan membawamu ke tempat yang aman!",
  ui_story_1013_10130701_12_dialog_content = "Hah? Apa...?",
  ui_story_1013_10130701_13_dialog_content = "(Aura pelangi aneh yang menyelimuti mereka memiliki warna yang sama dengan Lumina.)",
  ui_story_1013_10130701_14_dialog_content = "(Mungkinkah mereka... menjadi Aurorian?)",
  ui_story_1013_10130701_15_dialog_content = "Dewa Cahaya tidak memberi kita aurora aeterna: kehidupan yang bebas dari rasa sakit dan kekhawatiran.",
  ui_story_1013_10130701_16_dialog_content = "Dewa Cahaya tidak memberi kita hari-hari abadi: dunia yang bebas dari perang dan kekacauan.",
  ui_story_1013_10130701_17_dialog_content = "Dewa Cahaya memberi kita kekuatan dan keberanian, kebijaksanaan dan akal, dan kasih sayang untuk semua...",
  ui_story_1013_10130701_18_dialog_content = "sehingga kita dapat menghadapi kesulitan kita dengan keberanian tanpa akhir, kebijaksanaan tertinggi, dan cinta abadi.",
  ui_story_1013_10130701_19_dialog_content = "(Sepertinya mereka sedang berdoa—tetapi kepada siapa, dan untuk apa?)",
  ui_story_1013_10130701_20_dialog_content = "<color=#e8d9bb>Ledakan-!!!</color>",
  ui_story_1013_10130701_21_dialog_content = "Pertempuran berkembang pesat. Semua personel, ikuti instruksi dan mundur ke tempat aman.",
  ui_story_1013_10130701_22_dialog_content = "Ini adalah peringatan terakhir. Evakuasi semua area di mana setan mungkin muncul.",
  ui_story_1013_10130701_23_dialog_content = "Keren!!!",
  ui_story_1013_10130701_24_dialog_content = "Sial, aku harus cepat—",
  ui_story_1013_10130701_25_dialog_content = "Graah—!",
  ui_story_1013_10130701_26_dialog_content = "Utusan Cahaya tidak perlu takut akan kegelapan.",
  ui_story_1013_10130701_27_dialog_content = "Kami tetap di sini untuk memaksa iblis yang dibawa dari kegelapan mundur.",
  ui_story_1013_10130701_28_dialog_content = "Nak, pergi, cepat! Jangan biarkan mereka menangkapmu. Sudah terlalu banyak yang mati.",
  ui_story_1013_10130701_29_option_content = "Tidak, saya dapat membantu Anda.",
  ui_story_1013_10130701_30_dialog_content = "Jika Anda bersedia mempercayai saya dan mengizinkan saya melakukan kontak dengan kesadaran Anda ...",
  ui_story_1013_10130701_31_dialog_content = "Saya mampu menavigasi Aurorian dalam pertempuran. Biarkan saya membantu agar Anda dapat menggunakan kekuatan Anda dengan lebih baik dan meraih peluang kemenangan!",
  ui_story_1013_10130701_32_option_content = "Tidak, kau harus ikut denganku.",
  ui_story_1013_10130701_33_dialog_content = "Ini bukanlah pertarungan yang bisa dimenangkan oleh empat Aurorian sendirian.",
  ui_story_1013_10130701_34_dialog_content = "Ikutlah denganku untuk mencari tempat berlindung. Kami tidak punya pilihan lain.",
  ui_story_1013_10130701_35_dialog_content = "\"Aurorian\"? Saya tidak tahu apa yang Anda bicarakan ...",
  ui_story_1013_10130701_36_dialog_content = "Ini bukan tempat untuk seorang anak. Dapatkan keselamatan!",
  ui_story_1013_10130701_37_dialog_content = "Oh, dan kamu bukan anak kecil!?",
  ui_story_1013_10130701_38_dialog_content = "Anda tidak dapat menentukan usia Utusan Cahaya dari penampilan.",
  ui_story_1013_10130701_39_dialog_content = "Hanya mereka yang terampil menggunakan Lumina yang bisa berdiri dan bertarung di sini.",
  ui_story_1013_10130701_40_dialog_content = "Pada saat seperti ini, kita harus <color=#FFB400>taat mengikuti</color> ajaran Dewa Cahaya.",
  ui_story_1013_10130701_41_dialog_content = "Maksudmu…",
  ui_story_1013_10130701_42_dialog_content = "Sepakat. Kami tidak bisa lagi menggunakan kekhawatiran kami sebagai alasan untuk menahan diri dari menggunakan kekuatan di telapak tangan kami.",
  ui_story_1013_10130701_43_dialog_content = "Berdirilah dengan tenang, nak, jika kau tidak ingin tersapu oleh gelombang cahaya.",
  ui_story_1013_10130701_44_dialog_content = "Sangat baik. Saya khawatir kita akan menyesal jika tidak melakukannya.",
  ui_story_1013_10130701_45_dialog_content = "Setan mendekat dengan cepat dari sana.",
  ui_story_1013_10130701_46_dialog_content = "Mari kita raih sinar cahaya terakhir ini.",
  ui_story_1013_10130701_47_dialog_content = "Cahaya milik kita!",
  ui_story_1013_10130701_48_dialog_content = "S-Lumina yang sangat kuat!",
  ui_story_1013_10130701_49_dialog_content = "Graaah—",
  ui_story_1013_10130701_50_dialog_content = "Ahhhhhhhh!",
  ui_story_1013_10130701_51_dialog_content = "Apa-",
  ui_story_1013_10130701_52_dialog_content = "(Mereka seharusnya menang, tapi ini... yang saya lihat di hadapan saya adalah pemandangan dari mimpi buruk.)",
  ui_story_1013_10130701_53_dialog_content = "(Sinar cahaya membunuh semua orang, Eclipsites dan Aurorian!)",
  ui_story_1013_10130701_54_dialog_content = "(Aku tidak bisa bertahan. Apakah ini berarti... aku juga akan...)",
  ui_story_1013_10130701_55_dialog_content = "<color=#e8d9bb>DUAR!</color>",
  ui_story_1013_10130701_56_dialog_content = "Heh, heh...",
  ui_story_1013_10130701_57_dialog_content = "Buzz—Buzz—",
  ui_story_1013_10130701_58_dialog_content = "Apakah... Apakah sudah berakhir?",
  ui_story_1013_10130701_59_option_content = "Force Boost",
  ui_story_1013_10130701_60_dialog_content = "Saya tidak bisa merasakan Darkflow lagi. Hanya kesunyian yang mematikan.",
  ui_story_1013_10130701_61_dialog_content = "Apakah itu bagaimana dunia sebelum berakhir?",
  ui_story_1013_10130701_62_dialog_content = "Tunggu!",
  ui_story_1013_10130701_63_dialog_content = "Sesuatu merangkak keluar dari tanah!",
  ui_story_1013_10130701_64_dialog_content = "<color=#e8d9bb>Berdesir-</color>",
  ui_story_1013_10130701_65_dialog_content = "Mendesis-!!!",
  ui_story_1013_10130701_66_dialog_content = "Oh, tidak!",
  ui_story_1013_10130701_67_dialog_content = "(Apakah selalu ada di sana? Apakah itu memungkinkannya bertahan dari malapetaka?)",
  ui_story_1013_10130701_68_dialog_content = "(Saya akan menyelesaikannya!)",
  ui_story_1013_10130702_1_dialog_content = "Mendesis-!!!",
  ui_story_1013_10130702_2_dialog_content = "Aku tidak bisa mengalahkannya!",
  ui_story_1013_10130702_3_dialog_content = "Tubuhnya tampaknya semakin besar.",
  ui_story_1013_10130702_4_dialog_content = "Tapi Eclipsites tidak bisa beregenerasi di tempat seperti itu. Apakah ini kesalahan simulasi?",
  ui_story_1013_10130702_5_dialog_content = "Hiss—",
  ui_story_1013_10130702_6_dialog_content = "A-Apapun yang terjadi, aku harus menghubungi para peneliti.",
  ui_story_1013_10130702_7_dialog_content = "Aku tidak akan mati di sini!",
  ui_story_1013_10130702_8_dialog_content = "Peneliti! Apakah Anda menyalin? Mohon ditanggapi!",
  ui_story_1013_10130702_9_dialog_content = "Saya ulangi: Peneliti! Apakah Anda menyalin? Mohon ditanggapi!",
  ui_story_1013_10130702_10_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10130702_11_dialog_content = "A-Apa yang bisa saya lakukan ...",
  ui_story_1013_10130702_12_dialog_content = "Apa lagi yang bisa saya coba?",
  ui_story_1013_10130702_13_dialog_content = "<color=#e8d9bb>Retakan-</color>",
  ui_story_1013_10130702_14_dialog_content = "Apa aku... benar-benar akan mati di sini?",
  ui_story_1013_10130702_15_dialog_content = "Aku—",
  ui_story_1013_10130702_16_dialog_content = "<color=#e8d9bb>Wuuss!</color>",
  ui_story_1013_10130702_17_dialog_content = "\"Sistem Kontrol Utama... normal.\"",
  ui_story_1013_10130702_18_dialog_content = "\"Modul Biologis... normal.\"",
  ui_story_1013_10130702_19_dialog_content = "\"Penopang Hidup... operasional. Kapasitas saat ini: 1 orang.\"",
  ui_story_1013_10130702_20_dialog_content = "\"Generator… normal. Mencoba menyalakannya…\"",
  ui_story_1013_10130702_21_dialog_content = "Soroz!",
  ui_story_1013_10130702_22_dialog_content = "Saya disini, PlayerName. Aku selalu disini.",
  ui_story_1013_10130702_23_dialog_content = "\"Membuatmu tetap hidup dan aman adalah prioritas utamaku.\" Ingat?",
  ui_story_1013_10130702_24_dialog_content = "Ini mungkin dunia maya...",
  ui_story_1013_10130702_25_dialog_content = "tapi bukan berarti aku bisa membiarkanmu terluka.",
  ui_story_1013_10130702_26_dialog_content = "Coba dan putuskan hubunganmu denganku. Dan kemudian... percayalah padaku.",
  ui_story_1013_10130702_27_dialog_content = "\"Sistem Autopilot diluncurkan... Tujuan: Kembali ke kenyataan.\"",
  ui_story_1013_10130702_28_dialog_content = "Ngg...",
  ui_story_1013_10130702_29_dialog_content = "Apakah ... berhasil ... Soroz ...",
  ui_story_1013_10130702_30_dialog_content = "PlayerName... PlayerName sudah bangun!",
  ui_story_1013_10130702_31_dialog_content = "PlayerName, akhirnya kau bangun juga!",
  ui_story_1013_10130702_32_dialog_content = "Anak itu sadar lagi! Biarkan saluran udaranya tetap terbuka.",
  ui_story_1013_10130702_33_dialog_content = "Aktifkan pemindai pemeriksaan medis pusat penelitian.",
  ui_story_1013_10130702_34_dialog_content = "Apa yang kamu... Tunggu! Aku baik-baik saja, aku tidak terluka.",
  ui_story_1013_10130702_35_dialog_content = "Bagaimana dengan Sorozz?",
  ui_story_1013_10130702_36_dialog_content = "Kami tidak dapat mengandalkan kesadaran subjektif Anda untuk memberi tahu kami apakah Anda terluka atau tidak.",
  ui_story_1013_10130702_37_dialog_content = "Hasilnya akan keluar dalam waktu singkat. Harap diam selama lima menit.",
  ui_story_1013_10130702_38_dialog_content = "Kenapa kamu tidak pernah memberitahuku bahwa simulator bisa mengalami malfungsi seperti itu!?",
  ui_story_1013_10130702_39_dialog_content = "Saya tahu saya bercanda tentang membedah Anda, tetapi saya masih tahu batas antara lelucon dan kenyataan.",
  ui_story_1013_10130702_40_dialog_content = "Kami tidak berniat menempatkan Anda dalam bahaya. Pusat penelitian akan bertanggung jawab penuh atas kejadian ini.",
  ui_story_1013_10130702_41_dialog_content = "Saya akan menyelidiki para peneliti yang menyusun data medan perang kuno dan menjalankan serangkaian tes baru di simulator.",
  ui_story_1013_10130702_42_dialog_content = "Juga, sampaikan pesanan saya:",
  ui_story_1013_10130702_43_dialog_content = "Pusat Penelitian Illumina akan meliput PlayerNamebiaya pemeliharaan Colossus selama tiga bulan ke depan.",
  ui_story_1013_10130702_44_dialog_content = "Apa yang kamu katakan, PlayerName?",
  ui_story_1013_10130702_45_dialog_content = "Kurasa itu berhasil...",
  ui_story_1013_10130702_46_dialog_content = "Hmm, menurut saya masalahnya adalah teknologi yang kami gunakan untuk menghubungkan Colossus dan simulator masih belum matang.",
  ui_story_1013_10130702_47_dialog_content = "Jormungand yang beregenerasi itu menunjukkan fakta bahwa Anda terjebak dalam data yang rusak dari masa lalu.",
  ui_story_1013_10130702_48_dialog_content = "Jadi kalian bisa melihat semuanya seperti yang terjadi...",
  ui_story_1013_10130702_49_dialog_content = "Pada akhirnya, Soroz memutuskan hubungan dengan simulator dan mengeluarkan saya.",
  ui_story_1013_10130702_50_dialog_content = "Jadi, bagaimana Soroz?",
  ui_story_1013_10130702_51_dialog_content = "Hasilnya sudah masuk. Selamat, subjek tes! Semuanya terlihat normal.",
  ui_story_1013_10130702_52_dialog_content = "Apakah seseorang akan memberi tahu saya bagaimana Soroz ?!",
  ui_story_1013_10130702_53_dialog_content = "Soroz…",
  ui_story_1013_10130702_54_dialog_content = "Soroz membayar harga untuk memutus koneksi seperti itu.",
  ui_story_1013_10130702_55_dialog_content = "Kesadarannya tetap berada dalam sistem simulator medan perang.",
  ui_story_1013_10130702_56_dialog_content = "Aku tahu itu tampak kejam bagimu. Tapi situasi seperti ini biasa terjadi selama eksperimen.",
  ui_story_1013_10130702_57_dialog_content = "Kesadarannya saat ini berada dalam keadaan yang rumit — kepribadiannya telah dilucuti dari ingatannya.",
  ui_story_1013_10130702_58_dialog_content = "Ingatan Soroz kini berbentuk informasi murni. Kepribadiannya telah mundur kembali menjadi batu tulis kosong.",
  ui_story_1013_10130702_59_dialog_content = "Saat regresi itu terjadi, Soroz dapat mengeluarkan Anda dengan aman, tetapi kehilangan sebagian fungsinya.",
  ui_story_1013_10130702_60_dialog_content = "!!!",
  ui_story_1013_10130702_61_dialog_content = "Apa maksudmu... Apa artinya ini?",
  ui_story_1013_10130702_62_dialog_content = "Hanya apa yang akan Anda pikirkan.",
  ui_story_1013_10130702_63_dialog_content = "Kalian menyebut ini masalah kecil?!",
  ui_story_1013_10130702_64_option_content = "Force Boost!",
  ui_story_1013_10130702_65_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10130702_66_option_content = "Paksa Peningkatan!!",
  ui_story_1013_10130702_67_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10130702_68_option_content = "Dorong Paksa!!!",
  ui_story_1013_10130702_69_dialog_content = "Jangan sia-siakan kekuatanmu, PlayerName.",
  ui_story_1013_10130702_70_dialog_content = "Anda tidak akan dapat mengendalikannya saat ini.",
  ui_story_1013_10130702_71_dialog_content = "Kami akan terus berusaha memulihkan kesadarannya. Paling tidak kami akan berusaha mengembalikan fungsinya.",
  ui_story_1013_10130702_72_dialog_content = "Apa artinya itu?",
  ui_story_1013_10130702_73_dialog_content = "Bagaimana bisa \"berfungsi\" tanpa kepribadian atau ingatannya!?",
  ui_story_1013_10130702_74_dialog_content = "Apa yang Anda pikir Anda lakukan? Bukankah kalian seharusnya bertanggung jawab penuh untuk ini?!",
  ui_story_1013_10130702_75_dialog_content = "Ya, Marsekal Agung. Pusat penelitian akan bertanggung jawab penuh untuk memulihkan kesadaran Colossus.",
  ui_story_1013_10130702_76_dialog_content = "Namun, subjek ujian, kita harus ingat untuk tidak berteman dengan teknologi kita. Mereka hanyalah alat untuk melayani kita dan membantu kita dalam penelitian.",
  ui_story_1013_10130702_77_dialog_content = "Ketika Colossus kehilangan kesadaran, sistemnya kehilangan stabilitas...",
  ui_story_1013_10130702_78_dialog_content = "tetapi selama kita bisa menjalankannya, tidak masalah apakah kepribadiannya tidak aktif atau hilang.",
  ui_story_1013_10130702_79_dialog_content = "Jangan sentuh Soroz! Soroz adalah teman saya, mentor saya, dan satu-satunya keluarga saya!",
  ui_story_1013_10130702_80_dialog_content = "Harap tenang, PlayerName. Saya berjanji kepada Anda bahwa pekerjaan kami tidak akan merusaknya.",
  ui_story_1013_10130702_81_dialog_content = "Anda sudah merusaknya!",
  ui_story_1013_10130702_82_dialog_content = "<color=#e8d9bb>Ketuk, ketuk</color>",
  ui_story_1013_10130702_83_dialog_content = "Laboratorium harus tenang. Harap tidak berisik.",
  ui_story_1013_10130702_84_dialog_content = "Oh...?",
  ui_story_1013_10130702_85_dialog_content = "Grand Marshal, Petugas Intelijen Yingel dari <color=#FFB400>Dewan Sains</color>, pelaporan.",
  ui_story_1013_10130702_86_dialog_content = "Dewan Sains? Jadi mereka diam-diam merekrut beberapa pendatang baru yang menjanjikan lagi.",
  ui_story_1013_10130702_87_dialog_content = "Terima kasih, Marsekal Agung. Saya percaya ini adalah pertama kalinya kami bertemu.",
  ui_story_1013_10130702_88_dialog_content = "Tapi aku merasa seolah-olah aku mengenalmu dengan baik.",
  ui_story_1013_10130702_89_dialog_content = "Ha ha! Semua orang di Illumina mengenal saya.",
  ui_story_1013_10130702_90_dialog_content = "Jadi untuk apa Dewan Sains mengirim Anda? Untuk mempelajari Caelestite?",
  ui_story_1013_10130702_91_dialog_content = "Dewan akan mengadakan konferensi rahasia. Aku di sini hanya untuk menyampaikan perintah.",
  ui_story_1013_10130702_92_dialog_content = "Ha. Para kutu buku lab itu akhirnya memilih untuk menunjukkan diri, ya?",
  ui_story_1013_10130702_93_dialog_content = "Dewan Sains meminta, dengan niat tulus, untuk berbicara langsung dengan Caelestite.",
  ui_story_1013_10130702_94_dialog_content = "Bagaimana dengan saya?",
  ui_story_1013_10130702_95_dialog_content = "Anda dipersilakan untuk hadir, tentu saja.",
  ui_story_1013_10130702_96_dialog_content = "Sebaliknya, Anda sedang diperintahkan untuk. Harap hadiri pertemuan bersama Caelestite.",
  ui_story_1013_10130702_97_dialog_content = "Saya kira itu berarti saya bahkan kurang berhak untuk menolak.",
  ui_story_1013_10130702_98_dialog_content = "Tapi, Soro...",
  ui_story_1013_10130702_99_dialog_content = "Gronru dan saya akan memerintahkan para peneliti untuk menghentikan semua pekerjaan di Colossus sampai Anda kembali.",
  ui_story_1013_10130702_100_dialog_content = "Jangan khawatir, saya akan mengawasi mereka seperti elang!",
  ui_story_1013_10130702_101_dialog_content = "Jangan khawatir, PlayerName. Kami belum kehabisan solusi.",
  ui_story_1013_10130702_102_dialog_content = "Dewan Sains mungkin dapat memberi Anda lebih banyak info tentang Soroz.",
  ui_story_1013_10130702_103_dialog_content = "... Aku mengerti.",
  ui_story_1013_10130702_104_dialog_content = "Saya juga punya beberapa pertanyaan tentang pertempuran kuno yang saya saksikan.",
  ui_story_1013_10130702_105_dialog_content = "Kerja sama Anda dihargai. Saya yakin Dewan Sains akan menjawab pertanyaan Anda sebaik mungkin.",
  ui_story_1013_10130702_106_dialog_content = "Jika Anda berdua akan mengikuti saya?",
  ui_story_1013_10130801_1_dialog_content = "Dewan Sains?",
  ui_story_1013_10130801_2_dialog_content = "Ya. Mereka melapor langsung ke kekuatan tertinggi di Illumina...",
  ui_story_1013_10130801_3_dialog_content = "Anggota utamanya tersebar di seluruh Illumina. Hanya pada saat-saat krisis mereka berkumpul bersama untuk pertemuan rahasia.",
  ui_story_1013_10130801_4_dialog_content = "Aku tahu itu semua terdengar sedikit menakutkan. Tapi setiap anggota Dewan memiliki akses ke rahasia terbesar Illumina.",
  ui_story_1013_10130801_5_dialog_content = "Itu sebabnya mereka merahasiakan identitas mereka.",
  ui_story_1013_10130801_6_dialog_content = "Terakhir kali mereka menampakkan diri adalah untuk memberikan suara ketika pimpinan militer berganti.",
  ui_story_1013_10130801_7_dialog_content = "Tunggu, bukankah itu...",
  ui_story_1013_10130801_8_dialog_content = "Kapan saya dilantik? Ya sebenarnya.",
  ui_story_1013_10130801_9_dialog_content = "Kedengarannya sangat misterius. Yang menjelaskan mengapa saya belum pernah mendengarnya.",
  ui_story_1013_10130801_10_dialog_content = "Jika Anda mungkin bisa bergegas?",
  ui_story_1013_10130801_11_dialog_content = "Ha ha. Anda dengar itu, PlayerName? Ayo, mari kita menyusulnya.",
  ui_story_1013_10130801_12_dialog_content = "(Itu mengesankan. Bahkan hanya seorang perwira intelijen dari Dewan Sains memiliki keberanian untuk memerintah Grand Marshall.)",
  ui_story_1013_10130801_13_dialog_content = "Kamu masih terlihat gugup.",
  ui_story_1013_10130801_14_dialog_content = "Saya tidak akan mengatakan gugup. Saya lebih ... waspada.",
  ui_story_1013_10130801_15_dialog_content = "Tidak ada yang Anda ceritakan kepada saya yang membantu saya memahami mengapa mereka tiba-tiba perlu bertemu dengan saya.",
  ui_story_1013_10130801_16_dialog_content = "Apakah karena Vice dan Barton? Atau tentang Obelisk of Return?",
  ui_story_1013_10130801_17_dialog_content = "Anda hanya membuat diri Anda gila dengan membuat tebakan liar seperti itu.",
  ui_story_1013_10130801_18_dialog_content = "Anggota Dewan memiliki banyak kekuasaan, dan mereka tidak bertindak sewenang-wenang.",
  ui_story_1013_10130801_19_dialog_content = "Jika mereka mengundang Anda ke rapat, itu berarti mereka akan menjelaskan semuanya dan mencoba memenangkan kepercayaan Anda.",
  ui_story_1013_10130801_20_dialog_content = "Selain itu, mereka mungkin bertugas mengelola semua kecerdasan Illumina, tetapi pada akhirnya, mereka hanyalah sekelompok kutu buku sains.",
  ui_story_1013_10130801_21_dialog_content = "Mereka bahkan mungkin dapat membantu Anda menemukan cara untuk memulihkan kepribadian Soroz.",
  ui_story_1013_10130801_22_dialog_content = "—Jika semua itu membuatmu merasa lebih baik.",
  ui_story_1013_10130801_23_dialog_content = "... Terima kasih, Reinhardt.",
  ui_story_1013_10130801_24_dialog_content = "Kami telah tiba.",
  ui_story_1013_10130801_25_dialog_content = "Silakan mendaftar di pintu masuk.",
  ui_story_1013_10130801_26_dialog_content = "Dan jangan khawatir—informasi yang Anda berikan hanya akan digunakan untuk memeriksa Anda masuk dan keluar.",
  ui_story_1013_10130801_27_dialog_content = "(Wow, mereka benar-benar rahasia.)",
  ui_story_1013_10130801_28_dialog_content = "<color=#e8d9bb>Bip — Bip —</color>",
  ui_story_1013_10130801_29_dialog_content = "Saya telah memasukkan kode sandi untuk pintu. Silakan masuk.",
  ui_story_1013_10130801_30_dialog_content = "Mengapa kita tidak mengundang orang dari pusat penelitian atau Laboratorium Payung Hitam? Bahkan Lt. Vice akan menjadi pilihan yang lebih baik.",
  ui_story_1013_10130801_31_dialog_content = "Kami tidak tahu di mana Caelestite berdiri. Dan dia satu-satunya yang memiliki kemampuan psikis jenius di atas teknologi kuno.",
  ui_story_1013_10130801_32_dialog_content = "Jenius melebih-lebihkannya. Tapi dia satu-satunya Caelestite berdarah murni yang kami tahu.",
  ui_story_1013_10130801_33_dialog_content = "Nah, sampai saya melihatnya dengan mata kepala sendiri, saya berasumsi bahwa \"kemampuan psikis\" ini hanyalah tipuan belaka.",
  ui_story_1013_10130801_34_dialog_content = "Bahkan jam yang berhenti benar dua kali sehari.",
  ui_story_1013_10130801_35_dialog_content = "Saya akan mengingat pikiran Anda.",
  ui_story_1013_10130801_36_dialog_content = "Baiklah, mereka ada di sini.",
  ui_story_1013_10130801_37_dialog_content = "<color=#e8d9bb>* Suara ketukan *</color>",
  ui_story_1013_10130801_38_dialog_content = "Caelestite Terakhir, PlayerName, di sini.",
  ui_story_1013_10130801_39_dialog_content = "Didampingi oleh Grand Marshal Reinhardt.",
  ui_story_1013_10130801_40_dialog_content = "Jayalah Illumina.",
  ui_story_1013_10130801_41_dialog_content = "Jayalah Illumina.",
  ui_story_1013_10130801_42_dialog_content = "PlayerName, kamu bisa duduk di sebelahku.",
  ui_story_1013_10130801_43_dialog_content = "Tolong, bisakah Caelestite duduk di sebelah kiri Ulysses? Di depan layar.",
  ui_story_1013_10130801_44_dialog_content = "Dan Reinhardt, kamu bisa berdiri di sampingnya.",
  ui_story_1013_10130801_45_dialog_content = "Barrett, sepertinya Anda menikmati bertanggung jawab atas pengaturan tempat duduk hari ini.",
  ui_story_1013_10130801_46_dialog_content = "Yah, kami hanya bisa menampung sejumlah orang tertentu. Seseorang harus mengurus logistik.",
  ui_story_1013_10130801_47_dialog_content = "Terima kasih telah menghadiri pertemuan kami.",
  ui_story_1013_10130801_48_dialog_content = "Dengan mengikuti aturan ketat, kita dapat menghemat banyak waktu.",
  ui_story_1013_10130801_49_dialog_content = "Itu termasuk aturan tertulis dan yang tidak tertulis.",
  ui_story_1013_10130801_50_dialog_content = "Silakan duduk, Caelestite.",
  ui_story_1013_10130801_51_dialog_content = "Halo, Pak.",
  ui_story_1013_10130801_52_dialog_content = "Biarkan saya membuat beberapa perkenalan. Di sebelah kanan Anda adalah Profesor Ulysses, seorang ahli biologi.",
  ui_story_1013_10130801_53_dialog_content = "Di seberang profesor adalah Tuan Joyce, fisikawan kami.",
  ui_story_1013_10130801_54_dialog_content = "Di samping Grand Marshal Reinhardt adalah Nona Barrett, seorang insinyur.",
  ui_story_1013_10130801_55_dialog_content = "Kemudian...",
  ui_story_1013_10130801_56_dialog_content = "Nona Algol, tolong bangun...",
  ui_story_1013_10130801_57_dialog_content = "Hah—Oh, maaf. Waktuku terbatas, kau tahu.",
  ui_story_1013_10130801_58_dialog_content = "Mengejar tidur adalah penggunaan waktu yang jauh lebih efisien daripada mendengarkan pengaturan tempat duduk.",
  ui_story_1013_10130801_59_dialog_content = "Kau…",
  ui_story_1013_10130801_60_dialog_content = "Saya Algol, bertanggung jawab atas kecerdasan buatan. Robot di pundak saya adalah Bool.",
  ui_story_1013_10130801_61_dialog_content = "Saya yakin Anda dan saya akan senang berbicara, selama kita tidak membangunkan Bool.",
  ui_story_1013_10130801_62_dialog_content = "N-Senang bertemu denganmu.",
  ui_story_1013_10130801_63_dialog_content = "Jika tidak ada keberatan, akankah kita mulai?",
  ui_story_1013_10130801_64_dialog_content = "Sebelum kita masuk ke bisnis, mungkin lebih efisien untuk menangani pertanyaan Anda terlebih dahulu.",
  ui_story_1013_10130801_65_dialog_content = "Harap batasi maksimal tiga.",
  ui_story_1013_10130801_66_dialog_content = "PlayerName baru saja menyelesaikan sesi tes di simulator medan perang di pusat penelitian.",
  ui_story_1013_10130801_67_dialog_content = "Dia memiliki sejumlah pertanyaan untuk Anda.",
  ui_story_1013_10130801_68_dialog_content = "Terima kasih telah berkontribusi, Reinhardt.",
  ui_story_1013_10130801_69_dialog_content = "Jadi bolehkah saya mengundang Caelestite untuk berbicara sekarang?",
  ui_story_1013_10130801_70_dialog_content = "... Jadilah tamuku.",
  ui_story_1013_10130801_71_option_content = "Tanyakan tentang \"setan\".",
  ui_story_1013_10130801_72_dialog_content = "Apakah semua itu benar-benar terjadi? Maksud saya hal-hal yang saya lihat dalam simulasi.",
  ui_story_1013_10130801_73_dialog_content = "Saya melihat Aurorian menggunakan Luminatics dalam pertempuran kuno.",
  ui_story_1013_10130801_74_dialog_content = "Dan apa yang mereka sebut \"setan\"... apakah mereka...?",
  ui_story_1013_10130801_75_dialog_content = "Peristiwa-peristiwa itu memang terjadi.",
  ui_story_1013_10130801_76_dialog_content = "Sebelum Aurorian dan Caelestites, tanah ini dihuni oleh nenek moyang kita yang jauh.",
  ui_story_1013_10130801_77_dialog_content = "Dan mereka menyebut diri mereka \"kemanusiaan\", bukan?",
  ui_story_1013_10130801_78_dialog_content = "Tepat. Mereka terlihat seperti kita dan menggunakan teknologi seperti kita... dan beberapa dari mereka mengabdikan diri mereka pada iman seperti kita juga.",
  ui_story_1013_10130801_79_dialog_content = "Tetapi mereka tidak memiliki kekuatan khusus.",
  ui_story_1013_10130801_80_dialog_content = "(Jadi... itu sebabnya yang bisa mereka lakukan hanyalah lari dari \"setan\"?)",
  ui_story_1013_10130801_81_dialog_content = "Biarkan saya mencoba dan membuatnya mudah dimengerti.",
  ui_story_1013_10130801_82_dialog_content = "Nenek moyang kita yang paling berbakat berevolusi menjadi Aurorian.",
  ui_story_1013_10130801_83_dialog_content = "Tetapi yang lain menyerah pada godaan yang ditawarkan oleh \"setan\".",
  ui_story_1013_10130801_84_dialog_content = "Tapi apakah \"setan\" itu?",
  ui_story_1013_10130801_85_dialog_content = "Apakah mereka Eclipsites tingkat tinggi? Aurora? Atau Caelestites?",
  ui_story_1013_10130801_86_dialog_content = "Pusat penelitian masih mencari jawaban untuk pertanyaan itu, jadi saya tidak punya jawaban untuk Anda saat ini.",
  ui_story_1013_10130801_87_dialog_content = "Maksudmu kau tidak membuat kemajuan sejak pertemuan terakhir kita? Setelah sekian lama?",
  ui_story_1013_10130801_88_dialog_content = "Asal usul \"setan\"—bagaimana mereka berevolusi, pengaruhnya terhadap sejarah kita... kita perlu mempelajari masalah ini dengan sangat hati-hati.",
  ui_story_1013_10130801_89_dialog_content = "Ini bukanlah pertanyaan yang bisa dijawab dengan beberapa simulasi pertempuran.",
  ui_story_1013_10130801_90_dialog_content = "...",
  ui_story_1013_10130801_91_dialog_content = "Pada akhirnya, Caelestites dan Eclipsites, yang dikendalikan oleh iblis, melakukan pertempuran yang menentukan melawan Aurorian.",
  ui_story_1013_10130801_92_dialog_content = "Bagian sejarah ini bukanlah rahasia bagi mereka yang duduk di sekitar meja ini.",
  ui_story_1013_10130801_93_dialog_content = "Jadi setelah itu, dunia nenek moyang kita hancur. Eclipsites kembali ke Dark Zone, dan Caelestites menghilang.",
  ui_story_1013_10130801_94_dialog_content = "Bangsa Aurorian yang masih hidup membangun peradaban baru dan melawan Eclipsites yang ditinggalkan oleh para iblis.",
  ui_story_1013_10130801_95_dialog_content = "Benarkah?",
  ui_story_1013_10130801_96_dialog_content = "Kami belum mengkonfirmasi ini. Tapi pandangan kami saat ini secara luas sejalan dengan hipotesis Anda, ya.",
  ui_story_1013_10130801_96X1_dialog_content = "Mohon tunggu.",
  ui_story_1013_10130801_97_dialog_content = "<color=#e8d9bb>Serak—Kretak</color>",
  ui_story_1013_10130801_98_dialog_content = "(Minuman? Orang-orang ini tidak berubah sama sekali.)",
  ui_story_1013_10130801_99_dialog_content = "(Sinyal kecil yang mereka kirim satu sama lain hanya akan menipu pendatang baru PlayerName.)",
  ui_story_1013_10130801_100_dialog_content = "Apakah Anda ingin mencobanya, Caelestite? Ini adalah jenis minuman baru yang populer di Illumina.",
  ui_story_1013_10130801_100X1_dialog_content = "(K-Dari mana asalmu ?!)",
  ui_story_1013_10130801_100X2_dialog_content = "Barrett, saya melihat Anda telah memutuskan untuk muncul sekali.",
  ui_story_1013_10130801_100X3_dialog_content = "Ya, saya sedikit tertarik dengan Caelestite ini.",
  ui_story_1013_10130801_100X4_dialog_content = "Tapi yang lain mungkin tidak merasakan hal yang sama.",
  ui_story_1013_10130801_100X5_dialog_content = "Kami <color=#FFB400>mengamati</color> Anda, jadi lakukan yang terbaik, Caelestite.",
  ui_story_1013_10130801_101_dialog_content = "... Aku akan.",
  ui_story_1013_10130801_102_option_content = "Tanyakan tentang Aurorian kuno.",
  ui_story_1013_10130801_103_dialog_content = "Lantas bagaimana nenek moyang yang \"berbakat\" itu mengembangkan kekuatan Luminatics?",
  ui_story_1013_10130801_104_dialog_content = "Dalam adegan yang saya lihat, mereka hanya berdoa kepada cahaya.",
  ui_story_1013_10130801_105_dialog_content = "Apakah itu sumber iman Lumopolis?",
  ui_story_1013_10130801_106_dialog_content = "Ha, ini bukan tempat untuk menanyakan pertanyaan itu, anak muda.",
  ui_story_1013_10130801_107_dialog_content = "M-maaf!",
  ui_story_1013_10130801_108_dialog_content = "Ada banyak Aurorian di dunia kita. Tetapi hanya sedikit dari mereka yang mengetahui sifat sebenarnya dari Luminatics.",
  ui_story_1013_10130801_109_dialog_content = "Orang Aurorian lebih suka berpegang pada penjelasan yang lebih mudah dimengerti.",
  ui_story_1013_10130801_110_dialog_content = "Misalnya, hadiah dari dewa, atau sesuatu yang berasal dari tanah suci, atau kekuatan yang diperoleh dengan mewujudkan \"kebenaran\"...",
  ui_story_1013_10130801_111_dialog_content = "Namun pada intinya, ini adalah keterampilan, kemampuan untuk digunakan <color=#FFB400>daya hidup</color> untuk mengarahkan energi.",
  ui_story_1013_10130801_112_dialog_content = "Daya hidup? Tapi orang Caelest...",
  ui_story_1013_10130801_113_dialog_content = "Caelestites memiliki vitalitas. Tapi Anda tidak bisa menguasai penggunaan Luminatics.",
  ui_story_1013_10130801_114_dialog_content = "Apalagi Eclipsites. Mereka kekurangan vitalitas dan sama sekali tidak mampu mengarahkan energi.",
  ui_story_1013_10130801_115_dialog_content = "Tapi bagaimana tepatnya keterampilan ini bekerja?",
  ui_story_1013_10130801_116_dialog_content = "Heh. Sederhananya, ini adalah aplikasi praktis dari Luminatics. Ambil Federasi Illumina, misalnya.",
  ui_story_1013_10130801_117_dialog_content = "Kami biasanya menggunakan Luminatics <color=#FFB400>karena bertindak</color>, untuk menggerakkan mesin, dan menggunakan teknologi untuk mengontrol efeknya.",
  ui_story_1013_10130801_118_dialog_content = "Sedangkan di Lumopolis mereka menggunakan keyakinan murni untuk menggerakkan vitalitas mereka.",
  ui_story_1013_10130801_119_dialog_content = "Jadi mereka mengendalikan Luminatics <color=#FFB400>di sumbernya</color>.",
  ui_story_1013_10130801_120_dialog_content = "Itulah satu-satunya perbedaan antara Lumopolis dan Illumina.",
  ui_story_1013_10130801_121_dialog_content = "Satu-satunya perbedaan? Itu agak ekstrim.",
  ui_story_1013_10130801_122_dialog_content = "Dan tolong, jangan mengganggu saya.",
  ui_story_1013_10130801_123_dialog_content = "(Semua ilmuwan ini bertindak ramah di permukaan, tetapi mereka tampaknya memiliki agresivitas yang mendasarinya. Atau apakah saya hanya membayangkannya?)",
  ui_story_1013_10130801_124_dialog_content = "Kami sudah berbicara selama lebih dari sepuluh menit sekarang. Profesor Ulysses, jangan lupa kenapa kita disini.",
  ui_story_1013_10130801_125_dialog_content = "Terima kasih telah mengingatkan saya. Tapi seperti yang kita sepakati, Caelestite masih diperbolehkan mengajukan satu pertanyaan lagi.",
  ui_story_1013_10130801_126_dialog_content = "Sangat serius, Ulysses. Anda telah melatih nona muda itu untuk bersikap khusus tentang peraturan seperti Anda.",
  ui_story_1013_10130801_127_dialog_content = "Yingel adalah salah satu alumni yang menjanjikan dimodifikasi oleh program Phospherus. Itu hanya tugas saya untuk melatihnya dengan benar.",
  ui_story_1013_10130801_128_dialog_content = "(Diubah!?)",
  ui_story_1013_10130801_129_dialog_content = "(Apakah itu yang mereka lakukan? <color=#FFB400>Memodifikasi Aurorian</color>!?)",
  ui_story_1013_10130801_130_dialog_content = "... Apakah itu percobaan yang selama ini kamu rahasiakan?!",
  ui_story_1013_10130801_131_dialog_content = "Jelaskan dirimu! Bukankah program Phospherus ditutup bertahun-tahun yang lalu?",
  ui_story_1013_10130801_132_dialog_content = "Tepatnya, Komite mengadakan pemungutan suara untuk menutup program tersebut.",
  ui_story_1013_10130801_133_dialog_content = "Tapi hasilnya tidak seperti yang diharapkan, Reinhardt.",
  ui_story_1013_10130801_134_dialog_content = "Maka saya harus mengajukan proposal lain untuk menutupnya!",
  ui_story_1013_10130801_135_dialog_content = "Saya tidak akan membiarkan tentara dan warga negara saya menjalani modifikasi eksperimental apa pun!",
  ui_story_1013_10130801_136_dialog_content = "Tentu saja, Reinhardt. Anda dapat melakukan apa yang Anda inginkan.",
  ui_story_1013_10130801_137_dialog_content = "Kekuatan Anda sebagai Marsekal Agung diberikan kepada Anda oleh orang-orang Illumina. Itu benar bahwa Anda menggunakan kekuatan itu untuk keuntungan mereka.",
  ui_story_1013_10130801_138_dialog_content = "Tapi itu harus menunggu sampai kita menyelesaikan pertemuan ini. Jika Anda bisa membiarkan Caelestite berbicara?",
  ui_story_1013_10130801_139_dialog_content = "(Apa yang terjadi? Apakah ini menjelaskan apa yang terjadi pada Vice?)",
  ui_story_1013_10130801_140_dialog_content = "(Berapa banyak Aurorian yang diam-diam dimodifikasi tanpa sepengetahuan mereka? Berapa banyak dari mereka yang menjadi temanku?)",
  ui_story_1013_10130801_141_dialog_content = "(Peningkatan Kekuatan!)",
  ui_story_1013_10130801_142_dialog_content = "Jangan panik, PlayerName. Saya mengandalkan Anda untuk mengajukan pertanyaan kepada mereka.",
  ui_story_1013_10130801_143_dialog_content = "Tolong, tanyakan pada Ulysses apa sebenarnya yang ingin mereka capai dari eksperimen modifikasi mereka.",
  ui_story_1013_10130801_144_dialog_content = "Ini menyangkut masa depan Vice dan yang lainnya, dan petugas intelijen ini di sini dan rekan senegaranya.",
  ui_story_1013_10130801_145_dialog_content = "Dan mungkin juga... apa yang terjadi saat itu...",
  ui_story_1013_10130801_146_dialog_content = "... Aku mengerti.",
  ui_story_1013_10130801_147_dialog_content = "Dan saya mungkin terlalu memikirkan banyak hal, tapi saya curiga mereka sedang menguji Anda.",
  ui_story_1013_10130801_148_dialog_content = "Menguji saya?",
  ui_story_1013_10130801_149_dialog_content = "Saya menduga bahwa di antara barisan mereka, mereka belum mencapai konsensus tentang sesuatu.",
  ui_story_1013_10130801_150_dialog_content = "Mereka perlu bertemu dengan Anda terlebih dahulu sebelum diam-diam mencapai semacam keputusan.",
  ui_story_1013_10130801_151_dialog_content = "Itu salah satu trik lama mereka. Bagaimanapun, mereka saling memberi isyarat menggunakan minuman itu.",
  ui_story_1013_10130801_152_dialog_content = "Tapi jangan terlalu khawatir tentang itu. Lakukan saja apa yang harus Anda lakukan.",
  ui_story_1013_10130801_153_dialog_content = "B-baiklah.",
  ui_story_1013_10130801_154_dialog_content = "(Apakah dia menggunakan kemampuan psikisnya selama masa hening itu?)",
  ui_story_1013_10130801_155_dialog_content = "(Bagaimanapun, dia pasti seseorang yang perlu kita awasi.)",
  ui_story_1013_10130801_156_dialog_content = "<color=#e8d9bb>Serak—Kretak</color>",
  ui_story_1013_10130801_157_dialog_content = "(Heheh... jadi akhirnya kamu mengakui nilai Caelestite.)",
  ui_story_1013_10130801_158_option_content = "Tanyakan tentang percobaan modifikasi.",
  ui_story_1013_10130801_159_dialog_content = "Apakah Helios juga merupakan produk dari program Phospherus ini?",
  ui_story_1013_10130801_160_dialog_content = "Mengapa... Mengapa Illumina ingin memodifikasi Aurorian?",
  ui_story_1013_10130801_161_dialog_content = "Helios? Saya tidak berharap Anda mendapat informasi yang begitu baik.",
  ui_story_1013_10130801_162_dialog_content = "Mengingat hal ini, tidak ada gunanya menyesatkan Anda. Memang, saya telah melakukan percobaan seperti itu.",
  ui_story_1013_10130801_163_dialog_content = "Yingel, yang berdiri di sini sebelum Anda, adalah salah satu produk paling sukses di babak terakhir.",
  ui_story_1013_10130801_164_dialog_content = "Aurorian yang dimodifikasi memiliki genetika dan karakteristik yang sama dengan Aurorian biasa.",
  ui_story_1013_10130801_165_dialog_content = "Meski sejujurnya, kepribadiannya yang keras kepala terkadang sedikit merepotkan.",
  ui_story_1013_10130801_166_dialog_content = "Itu bukan intinya! Mengapa Anda melakukan hal seperti itu?",
  ui_story_1013_10130801_167_dialog_content = "Untuk Illumina.",
  ui_story_1013_10130801_168_dialog_content = "Jelas, itu untuk Illumina. Kita harus memiliki peralatan modifikasi sendiri.",
  ui_story_1013_10130801_169_dialog_content = "Sama seperti Lumopolis yang memiliki meriam, dan Eraveil memiliki perangkat kuno yang memperkuat bangsa Aurorian.",
  ui_story_1013_10130801_170_dialog_content = "Illumina pernah menjelajahi Zona Gelap untuk mencari peralatan serupa, tetapi tidak berhasil.",
  ui_story_1013_10130801_171_dialog_content = "Yang dimiliki Illumina hanyalah warganya yang setia. Dan pertahanan kita dibangun di atas tulang para pejuang itu.",
  ui_story_1013_10130801_172_dialog_content = "Penelitian kami di bidang ini mewakili keinginan orang-orang kami.",
  ui_story_1013_10130801_173_dialog_content = "Setiap subjek yang kami modifikasi berarti satu korban yang tidak bersalah.",
  ui_story_1013_10130801_174_dialog_content = "Omong kosong! Bagaimana dengan subjek percobaan? Bukankah mereka tidak bersalah? Apakah orang seperti Helios tidak dihitung sebagai pengorbanan?",
  ui_story_1013_10130801_175_dialog_content = "<color=#e8d9bb>Serak—Kretak</color>",
  ui_story_1013_10130801_176_dialog_content = "Pada topik Helios ...",
  ui_story_1013_10130801_177_dialog_content = "Kumpulan mata pelajaran itu sebenarnya bukan bagian dari program Phospherus.",
  ui_story_1013_10130801_178_dialog_content = "Dia milik usaha yang berbeda. Dia hanyalah produk gagal dari percobaan yang gagal.",
  ui_story_1013_10130801_179_dialog_content = "Sebuah kegagalan!?",
  ui_story_1013_10130801_180_dialog_content = "Menghancurkan hidup seorang Aurorian tidak lebih berarti bagimu selain kegagalan percobaan?",
  ui_story_1013_10130801_181_dialog_content = "Reinhardt, sebagai dermawan eksperimen kami, Anda benar-benar tidak berhak mengambil landasan moral yang tinggi.",
  ui_story_1013_10130801_182_dialog_content = "Anda hampir tidak bisa mengatakan kami menghancurkan hidupnya. Itu mungkin jalan yang lebih cocok untuknya, bukan?",
  ui_story_1013_10130801_183_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_1013_10130801_184_dialog_content = "Saya tidak dapat duduk melalui pertemuan ini lebih lama lagi. Dan Ulysses, saya khawatir Anda telah meninggalkan jalan nalar.",
  ui_story_1013_10130801_185_dialog_content = "Saya pikir kita sudah cukup mendengar. Tidak ada gunanya melanjutkan.",
  ui_story_1013_10130801_186_dialog_content = "Anda ingin mengakhiri rapat? Tapi Dewan Sains baru saja dimulai.",
  ui_story_1013_10130801_187_dialog_content = "Anda dapat pergi jika Anda baik-baik saja dengan meninggalkan Caelestite di sini sendirian.",
  ui_story_1013_10130801_188_dialog_content = "Apa...",
  ui_story_1013_10130801_189_dialog_content = "Kamu tidak akan berani.",
  ui_story_1013_10130801_190_dialog_content = "Santai. Kami orang terpelajar. Kami tidak berkomplot seperti yang Anda pikirkan.",
  ui_story_1013_10130801_191_dialog_content = "Caelestite akan aman bersama kita. Lagipula, selama ini kita bersahabat dengannya.",
  ui_story_1013_10130801_192_dialog_content = "Tapi kita butuh saksi yang berwibawa.",
  ui_story_1013_10130801_193_dialog_content = "Reinhardt, saya harap Anda tidak membutuhkan saya untuk membuat ini lebih jelas. Tolong, mainkan peranmu.",
  ui_story_1013_10130801_194_dialog_content = "...",
  ui_story_1013_10130801_195_dialog_content = "<color=#e8d9bb>*ketukan ringan*</color>",
  ui_story_1013_10130801_196_dialog_content = "Menguap.",
  ui_story_1013_10130801_197_dialog_content = "Tolong, semuanya. Jangan biarkan emosi kita terlalu tinggi.",
  ui_story_1013_10130801_198_dialog_content = "Anda semua telah memberikan sinyal rahasia kepada <color=#FFB400>menerima Caelestite</color>. Jadi setidaknya Anda bisa sedikit lebih ramah.",
  ui_story_1013_10130801_199_dialog_content = "Dan Yingel sayang benar. Jangan lupa mengapa kami memanggilnya ke sini.",
  ui_story_1013_10130801_200_dialog_content = "(Apakah mereka akhirnya akan memberi tahu kita apa yang sebenarnya terjadi?)",
  ui_story_1013_10130801_201_dialog_content = "Caelestite, mereka telah menjawab pertanyaan Anda secara lengkap.",
  ui_story_1013_10130801_202_dialog_content = "Mereka tidak menahan diri, bahkan ketika menyentuh subjek tentang rahasia Illumina yang paling dekat.",
  ui_story_1013_10130801_203_dialog_content = "Ini perdagangan yang adil, bukan? Rahasia kami untuk kerja sama Anda.",
  ui_story_1013_10130801_204_dialog_content = "?!",
  ui_story_1013_10130801_205_dialog_content = "Itu konyol! Saya tidak akan pernah mendukung program seperti itu!",
  ui_story_1013_10130801_206_dialog_content = "Pa. Kau satu-satunya Caelestite yang masih hidup. Kami tidak akan pernah mengubah Anda.",
  ui_story_1013_10130801_207_dialog_content = "Seperti yang baru saja kami katakan, kami tidak akan menyentuh sehelai rambut pun di kepala Anda.",
  ui_story_1013_10130801_208_dialog_content = "Saya hanya meminta Anda untuk membantu kami. Dan hal itu akan menguntungkan Anda, secara tidak langsung.",
  ui_story_1013_10130801_209_dialog_content = "Bisakah Anda berhenti berbelit-belit?",
  ui_story_1013_10130801_210_dialog_content = "Jangan marah. Saya tahu Anda ingin Vice kembali normal, dan Anda khawatir tentang Colossus Anda yang tidak berfungsi.",
  ui_story_1013_10130801_211_dialog_content = "(I-Itu benar...)",
  ui_story_1013_10130801_212_dialog_content = "Singkat cerita, Dewan Sains berharap menggunakan kekuatan psikis Anda untuk menjalin hubungan dengan <color=#FFB400>Wali Satu</color>.",
  ui_story_1013_10130801_213_dialog_content = "Sebelumnya, para ilmuwan Illumina sepakat bahwa Soroz adalah Colossus transportasi biasa.",
  ui_story_1013_10130801_214_dialog_content = "Tetapi mengingat perilakunya baru-baru ini dan cara sistemnya terus ditingkatkan...",
  ui_story_1013_10130801_215_dialog_content = "kemungkinan alternatif telah terbuka.",
  ui_story_1013_10130801_216_dialog_content = "Dan Anda, Caelestite yang mengendalikan Soroz, adalah bagian integral dari itu.",
  ui_story_1013_10130801_217_dialog_content = "Teknologi kuno yang mengikat Anda ke Soroz menyebabkan serangkaian peristiwa ajaib.",
  ui_story_1013_10130801_218_dialog_content = "Kami mencapai kesepakatan setelah percakapan kami sebelumnya. Kami dapat mempercayakan kesadaran Guardian One kepada Anda.",
  ui_story_1013_10130801_219_dialog_content = "Jadi, kami harap Anda akan menggunakan kekuatan Anda untuk menjangkau Guardian One.",
  ui_story_1013_10130801_220_dialog_content = "Wali Satu? Apa itu, robot lain yang perlu dipukuli?",
  ui_story_1013_10130801_221_dialog_content = "Itu adalah kecerdasan buatan kuno yang bertahan hingga hari ini. Ini mengelola perhitungan dan operasi harian untuk semua teknologi Illumina.",
  ui_story_1013_10130801_222_dialog_content = "Jadi apa yang Anda pikirkan? Ada kemiripan dengan Colossi, bukan?",
  ui_story_1013_10130801_223_dialog_content = "Itu benar…",
  ui_story_1013_10130801_224_dialog_content = "Dan jika kau bisa menghubungi Guardian One...",
  ui_story_1013_10130801_225_dialog_content = "Ada kemungkinan ingatan kuno dalam kesadarannya akan memberikan petunjuk tentang cara mengembalikan Vice ke keadaan normal.",
  ui_story_1013_10130801_226_dialog_content = "Dan jika Anda dapat menemukan bagian yang tepat dari ingatan itu, mungkin Anda akan dipertemukan kembali dengan Colossus Anda.",
  ui_story_1013_10130801_227_dialog_content = "?!",
  ui_story_1013_10130801_228_dialog_content = "(Jika apa yang dia katakan itu benar, maka Soroz...)",
  ui_story_1013_10130801_229_dialog_content = "Pilihan ada padamu. Saya hanya memberi Anda pilihan.",
  ui_story_1013_10130801_230_dialog_content = "PlayerName, apakah Anda tidak yakin?",
  ui_story_1013_10130801_231_dialog_content = "Setelah apa yang mereka katakan, saya harus mencobanya!",
  ui_story_1013_10130801_232_dialog_content = "Saya pikir Anda akan melakukannya. Dan saya menyetujui pilihan Anda.",
  ui_story_1013_10130801_233_dialog_content = "Sikap Dewan meninggalkan banyak hal yang diinginkan, tetapi Anda tidak dapat melewatkan kesempatan untuk membalikkan keadaan.",
  ui_story_1013_10130801_234_dialog_content = "Sepertinya kalian setuju.",
  ui_story_1013_10130801_235_dialog_content = "Saya akan segera membawa Guardian One.",
  ui_story_1013_10130901_1_dialog_content = "Itu adalah kecerdasan buatan kuno yang bertahan hingga hari ini. Ini mengelola perhitungan dan operasi harian untuk semua teknologi Illumina.",
  ui_story_1013_10130901_2_dialog_content = "Jadi apa yang Anda pikirkan? Ada kemiripan dengan Colossi, bukan?",
  ui_story_1013_10130901_3_dialog_content = "Kecerdasan buatan kuno yang mendukung semua yang dilakukan Illumina...",
  ui_story_1013_10130901_4_dialog_content = "Saya tentu tertarik. Kedengarannya luar biasa.",
  ui_story_1013_10130901_5_dialog_content = "Aku ingin tahu seperti apa rupanya. Pasti sangat besar untuk menampung kekuatan komputasi yang dibutuhkan Illumina.",
  ui_story_1013_10130901_6_dialog_content = "Sebesar Soroz.",
  ui_story_1013_10130901_7_dialog_content = "Dan jika terpelihara dengan sangat baik, ia harus mempertahankan semua program lamanya.",
  ui_story_1013_10130901_8_dialog_content = "Setidaknya dia harus lebih pintar dari Chubb.",
  ui_story_1013_10130901_9_dialog_content = "Dan itu harus memiliki semacam tampilan agar orang dapat berinteraksi dengannya.",
  ui_story_1013_10130901_10_dialog_content = "Seperti \"pelayan\" tua di Undercity itu.",
  ui_story_1013_10130901_11_dialog_content = "Halo, Caelestite!",
  ui_story_1013_10130901_12_dialog_content = "Anda tidak seperti yang diharapkan oleh akumulasi data yang diharapkan oleh Guardian One.",
  ui_story_1013_10130901_13_dialog_content = "A-Apa? Tentunya robot kecil ini tidak...",
  ui_story_1013_10130901_14_dialog_content = "Dia. Katakan halo kepada Guardian One.",
  ui_story_1013_10130901_15_dialog_content = "Ini tidak seperti yang saya bayangkan!",
  ui_story_1013_10130901_16_dialog_content = "Guardian One akan memanfaatkan keberadaan Anda untuk memperbarui data Guardian One di Caelestites.",
  ui_story_1013_10130901_17_dialog_content = "Terbukti, baik Anda maupun Guardian One berbagi sentimen itu.",
  ui_story_1013_10130901_18_dialog_content = "Caelestite, akankah kita memperkaya database satu sama lain?",
  ui_story_1013_10130901_19_dialog_content = "Itu... Apakah itu mencoba berteman?",
  ui_story_1013_10130901_20_dialog_content = "Ini menunjukkan kesediaannya untuk bekerja dengan Anda. Guardian One adalah jenis kecerdasan buatan yang ramah.",
  ui_story_1013_10130901_21_dialog_content = "Harap tunggu beberapa menit. Saya perlu memprogram Guardian One dengan protokol koneksi baru.",
  ui_story_1013_10130901_22_dialog_content = "Kesalahan. Kesalahan.",
  ui_story_1013_10130901_23_dialog_content = "Input protokol koneksi gagal. Guardian One tidak dapat terhubung dengan pengguna yang tidak dikenal.",
  ui_story_1013_10130901_24_dialog_content = "Apa artinya...?",
  ui_story_1013_10130901_25_dialog_content = "<size=30>Saya pikir kami setuju Anda membiarkan Caelestite yang tersisa mencoba terhubung ke kesadaran Anda. Saya menandatangani formulir persetujuan...</size>",
  ui_story_1013_10130901_26_dialog_content = "Kalian bahkan belum mencapai kesepakatan tentang ini?",
  ui_story_1013_10130901_27_dialog_content = "M-Maaf. Guardian One sangat patuh pada aturan.",
  ui_story_1013_10130901_28_dialog_content = "Tanpa pemindaian menyeluruh dan firewall yang ketat, itu tidak akan terhubung ke modul eksternal apa pun.",
  ui_story_1013_10130901_29_dialog_content = "Penjaga Satu harus memeriksa dan menganalisis semua objek yang dikenal dan tidak dikenal.",
  ui_story_1013_10130901_30_dialog_content = "Guardian One bersedia untuk memeriksa data Caelestite baru. Tapi menurut database yang ada di Caelestites...",
  ui_story_1013_10130901_31_dialog_content = "Berdasarkan analisis data sebelumnya, Guardian One tidak dapat memberikan izin kontrol Caelestites.",
  ui_story_1013_10130901_32_dialog_content = "Tapi bukankah ini kesempatan bagus untuk memperbarui database itu?",
  ui_story_1013_10130901_33_dialog_content = "Dipahami. Guardian One memang berjanji untuk saling memperbarui kerangka konseptual dengan Caelestite ini.",
  ui_story_1013_10130901_34_dialog_content = "Jadi itu ya?",
  ui_story_1013_10130901_35_dialog_content = "Guardian One akan melakukan uji lapangan yang ketat untuk merekam dan menganalisis data tentang kemampuan Caelestite.",
  ui_story_1013_10130901_36_dialog_content = "Temuan dari proses itu kemudian akan memberi tahu Guardian One apakah akan memberikan izin kontrol Caelestite tersebut atau tidak.",
  ui_story_1013_10130901_37_dialog_content = "Eh, tes lapangan? Di ruang pertemuan ini?",
  ui_story_1013_10130901_38_dialog_content = "Caelestite, harap tempatkan diri Anda dalam mode berpasangan.",
  ui_story_1013_10130901_39_dialog_content = "(Oh! Saya kira itu berarti ia menginginkan tautan psikis?)",
  ui_story_1013_10130901_40_option_content = "Force Boost!",
  ui_story_1013_10130901_41_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1013_10130901_42_dialog_content = "Tunggu!",
  ui_story_1013_10130901_43_dialog_content = "<color=#e8d9bb>Bzzz...</color>",
  ui_story_1013_10130901_44_dialog_content = "Bukan siapa-siapa...",
  ui_story_1013_10130901_45_dialog_content = "Tidak ada yang memberi tahu saya apa yang melibatkan uji lapangan ini!",
  ui_story_1013_10130901_46_dialog_content = "<color=#e8d9bb>Whoosh—Whoosh—</color>",
  ui_story_1013_10130901_47_dialog_content = "Apa ini... Tunggu! Ini adalah tempat dari simulator medan perang!",
  ui_story_1013_10130901_48_dialog_content = "Disinilah kita akan melakukan uji lapangan.",
  ui_story_1013_10130901_49_dialog_content = "Siapa itu?!",
  ui_story_1013_10130901_50_dialog_content = "Silakan cari, Caelestite.",
  ui_story_1013_10130901_51_dialog_content = "Guardian One ada di atas Anda.",
  ui_story_1013_10130901_52_dialog_content = "Apa?!",
  ui_story_1013_10130901_53_dialog_content = "(Ini luar biasa...)",
  ui_story_1013_10130901_54_dialog_content = "(Jika saya mengamati ruang di atas saya dengan hati-hati, saya dapat melihat di mana simulasi bertemu dengan kenyataan.)",
  ui_story_1013_10130901_55_dialog_content = "(Itu pasti sensornya yang bisa saya lihat di atas sana. Ukurannya kira-kira sama dengan matahari.)",
  ui_story_1013_10130901_56_dialog_content = "Selamat datang di medan perang kuno virtual. Guardian One akan merekam performa pengujian Anda secara real-time.",
  ui_story_1013_10130901_57_dialog_content = "Pastikan untuk menunjukkan apa yang dapat Anda lakukan, Caelestite.",
  ui_story_1013_10130901_58_dialog_content = "Lagi? Apa ini, metodologi pengujian standar baru Illumina!?",
  ui_story_1013_10130901_59_dialog_content = "(Tapi jika mereka semua menggunakan simulasi yang sama, maka kesadaran Soroz pasti...)",
  ui_story_1013_10130901_60_dialog_content = "(Luar biasa. Saya harus memanfaatkan kesempatan ini dengan baik.)",
  ui_story_1013_10130901_61_dialog_content = "Harap biasakan diri Anda dengan lingkungan sesegera mungkin. Guardian One akan menyuntikkan batch pertama dari data pertempuran.",
  ui_story_1013_10130901_62_dialog_content = "Mengerti. Tapi sebelum kita mulai, saya punya satu permintaan.",
  ui_story_1013_10130901_63_dialog_content = "Jika saya lulus ujian, saya ingin memeriksa sendiri data medan perang ini secara keseluruhan.",
  ui_story_1013_10130901_64_dialog_content = "Itu tidak biasa...",
  ui_story_1013_10130901_65_dialog_content = "Itu diperbolehkan. Permintaan dikabulkan.",
  ui_story_1013_10130901_66_dialog_content = "Sekarang untuk langkah selanjutnya. Apakah Anda siap, Caelestite?",
  ui_story_1013_10130901_67_dialog_content = "Biarkan pertempuran dimulai.",
  ui_story_1013_10130901_68_dialog_content = "Tujuan: Hilangkan semua Eclipsites.",
  ui_story_1013_10130901_69_dialog_content = "Guardian One menginisialisasi...",
  ui_story_1013_10130901_70_dialog_content = "Kalau begitu…",
  ui_story_1013_10130901_71_dialog_content = "Keburukan! Carleen! Aku mengandalkan mu!",
  ui_story_1013_10130901_72_dialog_content = "Serahkan ini padaku.",
  ui_story_1013_10130901_73_dialog_content = "Biar aku saja.",
  ui_story_1013_10131002_1_dialog_content = "Graah...",
  ui_story_1013_10131002_2_dialog_content = "Tujuan panggung selesai.",
  ui_story_1013_10131002_3_dialog_content = "Tes selesai. Nilai panggung: B.",
  ui_story_1013_10131002_4_dialog_content = "Merekam data baru...",
  ui_story_1013_10131002_5_dialog_content = "Keterampilan pertempuran Caelestite termasuk mengelola penyebaran taktis.",
  ui_story_1013_10131002_6_dialog_content = "Caelestite dapat mengontrol Aurorian dan menyelesaikan tugas pertempuran.",
  ui_story_1013_10131002_7_dialog_content = "Saya tahu ini mungkin konsep baru untuk Anda. Tetapi di zaman kita, itu sepenuhnya normal.",
  ui_story_1013_10131002_8_dialog_content = "Dipahami. Database Guardian One di Caelestites telah diperbarui.",
  ui_story_1013_10131002_9_dialog_content = "Anda telah lulus ujian, Caelestite.",
  ui_story_1013_10131002_10_dialog_content = "Dan sesuai kesepakatan, Guardian One akan membuat catatan data hari ini tersedia untuk Anda.",
  ui_story_1013_10131002_11_dialog_content = "Anda akan segera meninggalkan medan perang kuno. Ini akan dihancurkan setelah tidak digunakan lagi.",
  ui_story_1013_10131002_12_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1013_10131002_13_dialog_content = "Tunggu...",
  ui_story_1013_10131002_14_dialog_content = "Tolong jangan hancurkan!",
  ui_story_1013_10131002_15_option_content = "Force Boost!",
  ui_story_1013_10131002_16_dialog_content = "Untuk menggunakan istilah Aurorian, Caelestite, Anda sedang \"tidak sopan.\"",
  ui_story_1013_10131002_17_dialog_content = "Guardian One telah mengakui kemampuanmu. Namun bukan berarti Anda bisa terhubung dengan Guardian One sesuka hati.",
  ui_story_1013_10131002_18_dialog_content = "Saya akan menjelaskan kepada Algol nanti.",
  ui_story_1013_10131002_19_dialog_content = "Sangat baik. Tolong jelaskan mengapa Anda tidak ingin simulasi medan perang kuno dihancurkan.",
  ui_story_1013_10131002_20_dialog_content = "Ini tidak termasuk dalam permintaan awal Anda.",
  ui_story_1013_10131002_21_dialog_content = "Guardian One tidak mengerti mengapa Anda ingin memeriksa dan menyimpan data ini.",
  ui_story_1013_10131002_22_dialog_content = "Apa yang kamu rencanakan?",
  ui_story_1013_10131002_23_dialog_content = "Seperti ini...",
  ui_story_1013_10131002_24_dialog_content = "Colossus saya harus mengeluarkan saya dari simulasi pertempuran sebelumnya. Dengan melakukan itu, itu tidak berfungsi.",
  ui_story_1013_10131002_25_dialog_content = "Data kesadarannya masih ada di sini, di suatu tempat di tumpukan data yang sangat besar itu.",
  ui_story_1013_10131002_26_dialog_content = "Apakah ini sangat penting bagimu, Caelestite?",
  ui_story_1013_10131002_27_option_content = "Soroz adalah teman terdekat saya.",
  ui_story_1013_10131002_28_dialog_content = "Soroz lebih dari sepotong teknologi kesadaran diri kuno.",
  ui_story_1013_10131002_29_dialog_content = "Kenangannya berisi semua petualangan yang kita alami bersama.",
  ui_story_1013_10131002_30_dialog_content = "Wali Satu mengerti.",
  ui_story_1013_10131002_31_dialog_content = "Merekam data baru...",
  ui_story_1013_10131002_32_dialog_content = "Guardian One telah memperbarui basis datanya di Caelestites.",
  ui_story_1013_10131002_33_dialog_content = "Apa yang sedang terjadi? Saya mendapatkan perasaan samar bahwa Anda berdua telah menjadi ... teman.",
  ui_story_1013_10131002_34_dialog_content = "Laporan. Caelestite dan Guardian One baru saja menyelesaikan koneksi singkat dan menyinkronkan hasil tes.",
  ui_story_1013_10131002_35_dialog_content = "(Itu memilih untuk tidak mengungkapkan alasan saya secara paksa menghubungkannya...)",
  ui_story_1013_10131002_36_dialog_content = "Oke, jadi Anda memiliki perspektif yang benar-benar baru tentang Caelestite sekarang, bukan?",
  ui_story_1013_10131002_37_dialog_content = "Bisakah kita melanjutkan percobaan yang disebutkan sebelumnya?",
  ui_story_1013_10131002_38_dialog_content = "Ya, Guardian One mengizinkan.",
  ui_story_1013_10131002_39_dialog_content = "Caelestite, data medan perang kuno saat ini telah disinkronkan ke terminal Anda sesuai dengan perjanjian.",
  ui_story_1013_10131002_40_dialog_content = "Terima kasih, Wali Satu.",
  ui_story_1013_10131002_41_dialog_content = "Baik-baik saja maka. Mari kembali ke alasan utama kita ada di sini.",
  ui_story_1013_10131002_42_dialog_content = "Guardian One akan mempelajari penggunaan teknologi kuno Anda melalui tautan telepati dengan Anda.",
  ui_story_1013_10131002_43_dialog_content = "Umpan baliknya akan ditampilkan secara real-time di layar ruang konferensi.",
  ui_story_1013_10131002_44_dialog_content = "Ini akan luar biasa untuk munculnya teknologi Illumina.",
  ui_story_1013_10131002_45_dialog_content = "Akan kucoba semampuku.",
  ui_story_1013_10131002_46_dialog_content = "Anda pasti telah melalui banyak simulasi pertempuran hari ini.",
  ui_story_1013_10131002_47_dialog_content = "Saya tidak akan bisa menonton kali ini, tapi hati-hati.",
  ui_story_1013_10131002_48_dialog_content = "Tenang, Reinhardt. Dan secara teknis saya tidak sendiri.",
  ui_story_1013_10131002_49_dialog_content = "Guardian One siap ditautkan.",
  ui_story_1013_10131002_50_dialog_content = "(Perbedaan terbesar antara Caelestite dan ilmuwan kita adalah sikapnya terhadap teknologi.)",
  ui_story_1013_10131002_51_dialog_content = "(Meskipun kemampuan teknis lembaga penelitian telah meningkat dalam beberapa tahun terakhir...)",
  ui_story_1013_10131002_X51_dialog_content = "(Jika kita tidak memiliki mentalitas yang sama, kita tidak akan mampu menembus penghalang yang menahan kita dari puncak teknologi.)",
  ui_story_1013_10131002_52_dialog_content = "(Mudah-mudahan mereka akan belajar dari percobaan ini.)",
  ui_story_1013_10131002_53_dialog_content = "Guardian One, tolong buka diri Anda terhadap pemikiran yang saya kirimkan.",
  ui_story_1013_10131002_54_option_content = "Force Boost",
  ui_story_1013_10131002_55_dialog_content = "Seperti inikah mindscape Guardian One...?",
  ui_story_1013_10131002_56_dialog_content = "Guardian One hadir, Caelestite.",
  ui_story_1013_10131002_57_dialog_content = "Selamat datang!",
  ui_story_1013_10131002_58_dialog_content = "Jangan ragu untuk bertindak sesuka Anda, karena Profesor Algol tidak memegang komando di sini.",
  ui_story_1013_10131002_59_dialog_content = "Oke, maafkan saya sebelumnya.",
  ui_story_1013_10131002_60_dialog_content = "(Sepertinya kita sedang bermain pura-pura...)",
  ui_story_1013_10131002_61_dialog_content = "Pikiranmu berkelok-kelok, Caelestite. Anda masih mengkhawatirkan Colossus Anda.",
  ui_story_1013_10131002_62_dialog_content = "(Mengesankan... Saya seharusnya tidak berharap kurang dari AI yang menjalankan semua operasi di Illumina.)",
  ui_story_1013_10131002_63_dialog_content = "Apakah Anda cukup memercayai Guardian One untuk mengubah proses pembelajaran ini menjadi pengalaman yang lebih menantang, Caelestite?",
  ui_story_1013_10131002_64_dialog_content = "Yah, aku percaya padamu, itu sebabnya aku terhubung denganmu...",
  ui_story_1013_10131002_65_dialog_content = "Kepercayaan diverifikasi. Selanjutnya, Guardian One meminta untuk mencari sinyal Colossus untuk tujuan akses.",
  ui_story_1013_10131002_66_dialog_content = "Tunggu apa?!",
  ui_story_1013_10131002_67_dialog_content = "Jika Anda mempercayai Guardian One, Guardian One meminta untuk mencari sinyal Colossus untuk tujuan akses.",
  ui_story_1013_10131002_68_dialog_content = "(Apakah ini mencoba membantu saya menemukan solusi untuk Soroz?)",
  ui_story_1013_10131002_69_dialog_content = "(Haruskah saya melakukan apa yang dikatakan?)",
  ui_story_1013_10131002_70_dialog_content = "Anda ragu-ragu, Caelestite.",
  ui_story_1013_10131002_71_dialog_content = "Memulai analisis cerdas...",
  ui_story_1013_10131002_72_dialog_content = "Skenario 1: Guardian One berhasil terhubung dengan Colossus dan mendapatkan sinyalnya.",
  ui_story_1013_10131002_73_dialog_content = "Hasil: Data kesadaran Colossus pulih. Colossus sadar kembali.",
  ui_story_1013_10131002_74_dialog_content = "Skenario 2: Guardian One berhasil terhubung dengan Colossus, mendapatkan sinyalnya, dan mencoba mengubah datanya.",
  ui_story_1013_10131002_75_dialog_content = "Hasil: Caelestite mendeteksi upaya tersebut dan memutuskan hubungan antara Guardian One dan Colossus. Status Colossus tetap tidak berubah.",
  ui_story_1013_10131002_76_dialog_content = "Skenario 3—",
  ui_story_1013_10131002_77_dialog_content = "Baiklah, baiklah, Anda tidak perlu melalui semua kemungkinan...!",
  ui_story_1013_10131002_78_dialog_content = "Saya mengerti apa yang Anda maksud sekarang. Bukannya aku punya pilihan yang lebih baik.",
  ui_story_1013_10131002_79_dialog_content = "Terima kasih, Guardian One, untuk melakukan ini.",
  ui_story_1013_10131002_80_dialog_content = "Caelestite dan teknologi AI kuno adalah teman.",
  ui_story_1013_10131002_81_dialog_content = "Guardian One juga merupakan teknologi AI kuno.",
  ui_story_1013_10131002_82_dialog_content = "Oke, kalau begitu aku mengandalkanmu!",
  ui_story_1013_10131002_83_dialog_content = "Ayo kembali ke simulasi pertempuran kuno dan selamatkan kesadaran Soroz!",
  ui_story_1013_10131002_84_dialog_content = "Wali Satu sudah siap. Menghitung mundur...",
  ui_story_1013_10131002_85_dialog_content = "Tiga…",
  ui_story_1013_10131002_86_dialog_content = "Dua...",
  ui_story_1013_10131002_87_dialog_content = "Satu.",
  ui_story_1013_10131101_1_dialog_content = "Perhatian: Simulasi pertempuran tidak stabil.",
  ui_story_1013_10131101_2_dialog_content = "Bersiaplah untuk situasi yang tidak terduga.",
  ui_story_1013_10131101_3_dialog_content = "Tidak apa-apa, saya pernah ke sini sebelumnya.",
  ui_story_1013_10131101_4_dialog_content = "Meskipun itu berbeda dari terakhir kali.",
  ui_story_1013_10131101_5_dialog_content = "Simulasi dilakukan dengan autopilot. Waktu memang berkembang.",
  ui_story_1013_10131101_6_dialog_content = "Yang tidak saya mengerti adalah, jika ini simulasi, bagaimana kesadaran Soroz bisa terperangkap?",
  ui_story_1013_10131101_7_dialog_content = "Kesadaran Soroz adalah data murni, sama seperti simulasi.",
  ui_story_1013_10131101_8_dialog_content = "\"Pikiran\" -nya mengganggu simulasi, dan datanya tercampur menjadi satu.",
  ui_story_1013_10131101_9_dialog_content = "Anda harus sampai ke Soroz sebelum simulasi hancur sendiri.",
  ui_story_1013_10131101_10_dialog_content = "Jika tidak, data Soroz juga akan dimusnahkan.",
  ui_story_1013_10131101_11_dialog_content = "Maksudmu kesadaran Soroz akan hilang?",
  ui_story_1013_10131101_12_dialog_content = "Tidak, tapi itu tidak akan dapat diakses lagi.",
  ui_story_1013_10131101_13_dialog_content = "Dalam istilah dunia nyata, itu akan terkubur di reruntuhan simulasi ini.",
  ui_story_1013_10131101_14_dialog_content = "Itu akan tetap ada, tetapi tidak ada yang bisa menemukannya.",
  ui_story_1013_10131101_15_dialog_content = "Mengapa simulasi akan hancur sendiri?",
  ui_story_1013_10131101_16_dialog_content = "Simulasi untuk pertempuran khusus ini istimewa.",
  ui_story_1013_10131101_17_dialog_content = "Itu tidak berhenti pada titik yang ditentukan dan malah terus menghapus data ...",
  ui_story_1013_10131101_18_dialog_content = "sampai tidak ada yang tersisa, dan dengan demikian, ia hancur sendiri.",
  ui_story_1013_10131101_19_dialog_content = "Spesial... Orang-orang di luar sana mengatakan bahwa peradaban pernah dihancurkan.",
  ui_story_1013_10131101_20_dialog_content = "Simulasi ini adalah rekaman bencana itu, kan?",
  ui_story_1013_10131101_21_dialog_content = "Menurut perhitungan saya, hampir tidak ada makhluk hidup yang bisa bertahan. Oleh karena itu, itu adalah kesimpulan yang logis.",
  ui_story_1013_10131101_22_dialog_content = "Tidak heran saya menyaksikan apa yang saya lakukan ...",
  ui_story_1013_10131101_23_dialog_content = "Astaga!",
  ui_story_1013_10131101_24_dialog_content = "Ahhhhhhhh!",
  ui_story_1013_10131101_25_dialog_content = "Kemanusiaan sedang sekarat... Bahkan Eclipsites tidak akan selamat.",
  ui_story_1013_10131101_26_dialog_content = "Penghancuran total adalah akhir yang tak terelakkan untuk dunia seperti itu...",
  ui_story_1013_10131101_27_dialog_content = "<color=#e8d9bb>Kegentingan!</color>",
  ui_story_1013_10131101_28_dialog_content = "!!!",
  ui_story_1013_10131101_29_dialog_content = "<color=#e8d9bb>Remuk, remuk!</color>",
  ui_story_1013_10131101_30_dialog_content = "Grah, mengaum!",
  ui_story_1013_10131101_31_dialog_content = "Gerhana?! Saya pikir mereka semua akan binasa dalam peristiwa kiamat itu.",
  ui_story_1013_10131101_32_dialog_content = "Sulit dipercaya beberapa selamat.",
  ui_story_1013_10131101_33_dialog_content = "A-Apa yang dilakukannya?",
  ui_story_1013_10131101_34_dialog_content = "Eclipsite memakan tulangan.",
  ui_story_1013_10131101_35_dialog_content = "<color=#e8d9bb>Remuk, remuk!</color>",
  ui_story_1013_10131101_36_dialog_content = "Mengapa itu melakukan itu?",
  ui_story_1013_10131101_37_dialog_content = "Bahkan jika tidak ada yang bisa dimakan, ada hal yang lebih baik untuk dimakan daripada tulangan... seperti batu di tanah.",
  ui_story_1013_10131101_38_dialog_content = "Berdasarkan deduksi saya, Eclipsites mendambakan karakteristik tulangan.",
  ui_story_1013_10131101_39_dialog_content = "Karakteristik?",
  ui_story_1013_10131101_40_dialog_content = "Tulangan tidak hancur dalam bencana itu.",
  ui_story_1013_10131101_41_dialog_content = "Eclipsites ingin mendapatkan karakteristik yang mirip dengan tulangan dengan mengkonsumsinya.",
  ui_story_1013_10131101_42_dialog_content = "A-Apa itu mungkin?",
  ui_story_1013_10131101_43_dialog_content = "Itu hanya teori, tapi faktanya, Eclipsites selamat dari malapetaka.",
  ui_story_1013_10131101_44_dialog_content = "Dalam jumlah banyak.",
  ui_story_1013_10131101_45_dialog_content = "<color=#e8d9bb>Remuk, remuk!</color>",
  ui_story_1013_10131101_46_dialog_content = "<color=#e8d9bb>Kegentingan!</color>",
  ui_story_1013_10131101_47_dialog_content = "Graaagh!",
  ui_story_1013_10131101_48_dialog_content = "Wah, kanibalisme juga?",
  ui_story_1013_10131101_49_dialog_content = "Eclipsites melakukan lebih dari yang dilakukan umat manusia untuk bertahan hidup.",
  ui_story_1013_10131101_50_dialog_content = "Oleh karena itu, Eclipsites adalah satu-satunya kehadiran di kota manusia ini.",
  ui_story_1013_10131101_51_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131101_52_dialog_content = "Begitu banyak dari mereka ...",
  ui_story_1013_10131101_53_dialog_content = "Banyak Eclipsites mati masih di tanah. Mereka terus-menerus mati dan respawn.",
  ui_story_1013_10131101_54_dialog_content = "Ya. Evolusi tidak dapat dicapai hanya melalui satu individu, sehingga Eclipsites memilih alternatif yang cepat.",
  ui_story_1013_10131101_55_dialog_content = "Mereka menyempurnakan perbaikan genetik melalui kematian terus-menerus sebagai sebuah kelompok sampai mereka dapat beradaptasi dengan lingkungan yang tidak bersahabat.",
  ui_story_1013_10131101_56_dialog_content = "Tunggu, apakah Eclipsites ini berkumpul di suatu tempat?",
  ui_story_1013_10131101_57_dialog_content = "Ya. Mereka bergerak ke arah yang sama. Ada sesuatu yang menarik mereka.",
  ui_story_1013_10131101_58_dialog_content = "Menarik mereka? Mungkinkah...?",
  ui_story_1013_10131101_59_option_content = "Force Boost!",
  ui_story_1013_10131101_60_dialog_content = "Soroz! Itulah kesadaran Soroz!",
  ui_story_1013_10131101_61_dialog_content = "Itu akan menjelaskannya. Data yang tidak terafiliasi dengan simulasi cenderung sangat gamblang.",
  ui_story_1013_10131101_62_dialog_content = "Eclipsites akan berkumpul di sekitarnya.",
  ui_story_1013_10131101_63_dialog_content = "Temukan Soroz dan kami dapat memperbaiki masalahnya, bukan?",
  ui_story_1013_10131101_64_dialog_content = "Kami dapat terhubung ke Soroz dan melakukan diagnosa, meskipun tidak diketahui apakah perbaikan dapat dilakukan.",
  ui_story_1013_10131101_65_dialog_content = "Oke, oke, Anda tidak perlu terlalu bertele-tele. Bagaimanapun, ayo pergi ke Soroz!",
  ui_story_1013_10131101_66_dialog_content = "Untungnya ini hanyalah simulasi, jadi saya memiliki kemampuan untuk melawan Eclipsites.",
  ui_story_1013_10131101_67_dialog_content = "Rasakan ini!",
  ui_story_1013_10131101_68_dialog_content = "<color=#e8d9bb>Blam—Boom!</color>",
  ui_story_1013_10131101_69_dialog_content = "Apa itu tadi? Apakah ada sesuatu yang akan roboh?",
  ui_story_1013_10131101_70_dialog_content = "Bangunan di sebelah Anda runtuh.",
  ui_story_1013_10131101_71_dialog_content = "Perhatian, simulasi saat ini sangat tidak stabil. Serangan dapat menyebabkan dunia runtuh.",
  ui_story_1013_10131101_72_dialog_content = "Wah, itu benar-benar berantakan!",
  ui_story_1013_10131101_73_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_1013_10131101_74_dialog_content = "*Batuk* Begitu banyak debu...",
  ui_story_1013_10131101_75_dialog_content = "Aku bahkan hampir tidak melakukan apapun! Apakah dunia ini begitu rapuh?",
  ui_story_1013_10131101_76_dialog_content = "Kenapa hanya...",
  ui_story_1013_10131101_77_dialog_content = "Karena ketidakstabilan data pertempuran, pada akhirnya akan hancur sendiri bahkan tanpa ada yang melakukan apapun.",
  ui_story_1013_10131101_78_dialog_content = "Awas.",
  ui_story_1013_10131101_79_dialog_content = "!!!",
  ui_story_1013_10131101_80_dialog_content = "<color=#e8d9bb>Membanting!!!</color>",
  ui_story_1013_10131101_81_dialog_content = "Astaga, apakah ini ada akhirnya?",
  ui_story_1013_10131101_82_dialog_content = "Hati-hati, dunia runtuh merupakan indikasi penghancuran diri simulasi sedang berlangsung.",
  ui_story_1013_10131101_83_dialog_content = "Dan penghancuran data simulasi akan menyebabkan...",
  ui_story_1013_10131101_84_dialog_content = "Menyebabkan data Soroz terhapus, kan?",
  ui_story_1013_10131101_85_dialog_content = "Ya. Pemahaman Anda benar.",
  ui_story_1013_10131101_86_dialog_content = "Saya kira saya tidak punya waktu untuk mengeluh sekarang ...",
  ui_story_1013_10131101_87_dialog_content = "Aku harus mencapai Soroz sebelum dunia hancur berantakan!",
  ui_story_1013_10131202_1_dialog_content = "Tigapuluh.",
  ui_story_1013_10131202_2_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1013_10131202_3_dialog_content = "Woah!",
  ui_story_1013_10131202_4_dialog_content = "Hampir jatuh...",
  ui_story_1013_10131202_5_dialog_content = "Celah di tanah sepertinya mengejarku!",
  ui_story_1013_10131202_6_dialog_content = "Itu karena Anda adalah salah satu alasan keruntuhan.",
  ui_story_1013_10131202_7_dialog_content = "Dua puluh lima.",
  ui_story_1013_10131202_8_dialog_content = "A-Ada apa dengan angka-angka yang terus kau keluarkan dengan sangat menyeramkan?!",
  ui_story_1013_10131202_9_dialog_content = "Itulah waktu yang tersisa.",
  ui_story_1013_10131202_10_dialog_content = "Saya mensimulasikan pemusnahan melalui interpretasi data simulasi. Hitungan mundur ini benar-benar tepat.",
  ui_story_1013_10131202_11_dialog_content = "Tinggal dua puluh detik lagi? Itu bukan-",
  ui_story_1013_10131202_12_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_1013_10131202_13_dialog_content = "Dua puluh.",
  ui_story_1013_10131202_14_dialog_content = "Oke, saya harus bisa menempuh jarak tertentu dalam 20 detik.",
  ui_story_1013_10131202_15_dialog_content = "Soroz ada di depan, saya bisa merasakannya!",
  ui_story_1013_10131202_16_dialog_content = "Jangan lupa untuk tetap waspada terhadap Eclipsites.",
  ui_story_1013_10131202_17_dialog_content = "Oke, berhenti mengomel!",
  ui_story_1013_10131202_18_dialog_content = "Minggir—",
  ui_story_1013_10131202_19_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1013_10131202_20_dialog_content = "Aaaahhhh!",
  ui_story_1013_10131202_21_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1013_10131202_22_dialog_content = "*Batuk-batuk*",
  ui_story_1013_10131202_23_dialog_content = "Aduh...",
  ui_story_1013_10131202_24_dialog_content = "Berapa lama aku punya, Wali Satu...",
  ui_story_1013_10131202_25_dialog_content = "Sepuluh.",
  ui_story_1013_10131202_26_dialog_content = "Omong kosong. Saya harus cepat.",
  ui_story_1013_10131202_27_dialog_content = "aku hampir sampai...",
  ui_story_1013_10131202_28_dialog_content = "Itu ada di sana.",
  ui_story_1013_10131202_29_dialog_content = "Lima.",
  ui_story_1013_10131202_30_dialog_content = "*Batuk-batuk*",
  ui_story_1013_10131202_31_dialog_content = "Empat.",
  ui_story_1013_10131202_32_dialog_content = "Hampir, begitu dekat...",
  ui_story_1013_10131202_33_dialog_content = "Tiga.",
  ui_story_1013_10131202_34_dialog_content = "Hosh... Hosh...",
  ui_story_1013_10131202_35_dialog_content = "Dua.",
  ui_story_1013_10131202_36_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1013_10131202_37_dialog_content = "Satu.",
  ui_story_1013_10131202_38_dialog_content = "Force Boost!",
  ui_story_1013_10131202_39_dialog_content = "Itu kamu ya Soroz.",
  ui_story_1013_10131202_40_dialog_content = "...",
  ui_story_1013_10131202_41_dialog_content = "Menemukannya, saya menemukan Soroz!",
  ui_story_1013_10131202_42_dialog_content = "Apakah saya berhasil tepat waktu?",
  ui_story_1013_10131202_43_dialog_content = "Cepat, sambungkan, sekarang juga!",
  ui_story_1013_10131202_44_dialog_content = "Menghubungkan ke port data Soroz.",
  ui_story_1013_10131202_45_dialog_content = "Tidak ada respon. Memulai entri paksa.",
  ui_story_1013_10131202_46_dialog_content = "Siap-siap. Kesadaran Anda akan segera memasuki ruang data Soroz.",
  ui_story_1013_10131202_47_dialog_content = "Guardian One tidak dapat memprediksi situasi yang akan Anda hadapi.",
  ui_story_1013_10131202_48_dialog_content = "Tentu saja aku siap... Apapun itu tidak mungkin lebih buruk dari ini.",
  ui_story_1013_10131202_49_dialog_content = "Memulai transfer data.",
  ui_story_1013_10131202_50_dialog_content = "Masuk ke Soroz.",
  ui_story_1013_10131202_51_dialog_content = "Gelap... Apa kita sudah sampai?",
  ui_story_1013_10131202_52_dialog_content = "Ya. Mungkin Anda harus mencoba membuka mata Anda jika Anda tidak dapat melihat.",
  ui_story_1013_10131202_53_dialog_content = "Hah?",
  ui_story_1013_10131202_54_dialog_content = "Oh, aku bisa melihat sekarang! Tunggu, kenapa aku butuh pengingat untuk itu?",
  ui_story_1013_10131202_55_dialog_content = "Itu normal. Mata Anda terbuka saat simulasi berakhir.",
  ui_story_1013_10131202_56_dialog_content = "Di benak Anda, mata Anda sudah terbuka, jadi Anda tidak akan berpikir untuk membukanya lagi.",
  ui_story_1013_10131202_57_dialog_content = "Tapi saya mengunduh Anda ke tubuh baru di ruang baru ini, dan matanya tertutup.",
  ui_story_1013_10131202_58_dialog_content = "Disonansi kognitif antara pikiran dan tubuh Anda mengakibatkan hal ini.",
  ui_story_1013_10131202_59_dialog_content = "Baiklah…",
  ui_story_1013_10131202_60_dialog_content = "Apakah kamu mengerti? Haruskah saya ulangi—",
  ui_story_1013_10131202_61_dialog_content = "Saya mengerti, sangat!",
  ui_story_1013_10131202_62_dialog_content = "Apakah itu Sorozz?",
  ui_story_1013_10131202_X62_dialog_content = "Kami sangat dekat, namun aku tidak bisa menyentuhnya.",
  ui_story_1013_10131202_X63_dialog_content = "Di mana tempat ini?",
  ui_story_1013_10131202_63_dialog_content = "Dari sudut pandang visual, Anda sedang melihat interior Soroz.",
  ui_story_1013_10131202_64_dialog_content = "Tetapi lebih akurat untuk menyebut cache data sementara Soroz ini.",
  ui_story_1013_10131202_65_dialog_content = "Dengan kata lain, ingatan Soroz.",
  ui_story_1013_10131202_66_dialog_content = "Penyimpanan?",
  ui_story_1013_10131202_67_dialog_content = "Mengapa kita disini? Bukankah seharusnya kita memecahkan masalah Soroz?",
  ui_story_1013_10131202_68_dialog_content = "Ya. Penyebab kerusakan Soroz adalah kesalahan data di cache.",
  ui_story_1013_10131202_69_dialog_content = "Kita harus menemukan data tersebut di antara segudang data lain dan memperbaikinya.",
  ui_story_1013_10131202_70_dialog_content = "Prosesnya hanyalah masalah operasi data untuk Guardian One.",
  ui_story_1013_10131202_71_dialog_content = "Tetapi Anda tidak dapat melakukannya secara langsung dengan otak Anda. Oleh karena itu, Guardian One akan membantu Anda memvisualisasikan data melalui imajinasi Anda.",
  ui_story_1013_10131202_72_dialog_content = "Kenangan yang tersimpan akan berubah menjadi gambar, sedangkan gangguan akan bermanifestasi sebagai anomali.",
  ui_story_1013_10131202_73_dialog_content = "Guardian One akan memeriksa ingatan Soroz dengan Anda selama proses berlangsung.",
  ui_story_1013_10131202_74_dialog_content = "Kami akan memilah data yang rusak seperti itu.",
  ui_story_1013_10131202_75_dialog_content = "Apakah saya dapat mengenali gangguan?",
  ui_story_1013_10131202_76_dialog_content = "Mereka akan mengambil bentuk hal-hal yang Anda anggap menjijikkan menurut pikiran Anda; oleh karena itu, Anda akan mengenali mereka.",
  ui_story_1013_10131202_77_dialog_content = "Ah, begitu. Kedengarannya cukup mudah.",
  ui_story_1013_10131202_78_dialog_content = "Guardian One tidak dapat mengkonfirmasi pernyataan itu.",
  ui_story_1013_10131202_79_dialog_content = "Oke, kita akan mencari tahu sambil jalan.",
  ui_story_1013_10131202_X79_dialog_content = "Mengakses data... Pindah ke kabin Soroz.",
  ui_story_1013_10131202_X80_dialog_content = "Fiuh! Saya merasa jauh lebih nyaman di sini!",
  ui_story_1013_10131202_80_dialog_content = "Omong-omong, kami bahkan belum tahu bagian mana dari memori Soroz ini.",
  ui_story_1013_10131202_81_dialog_content = "Tidak ada yang terjadi dan sangat sunyi.",
  ui_story_1013_10131202_82_dialog_content = "Dimana kita sekarang? Maksud saya, di mana Soroz dalam ingatan ini?",
  ui_story_1013_10131202_83_dialog_content = "Guardian One tidak memiliki data itu.",
  ui_story_1013_10131202_84_dialog_content = "Benar, Anda tidak mungkin mengetahui segalanya.",
  ui_story_1013_10131202_85_dialog_content = "Saya tahu Soroz seperti punggung tangan saya. Aku akan keluar dan melihat-lihat.",
  ui_story_1013_10131202_86_dialog_content = "<color=#e8d9bb>*Langkah kaki*</color>",
  ui_story_1013_10131202_87_dialog_content = "Hei, kenapa semua pintu tertutup?",
  ui_story_1013_10131202_88_dialog_content = "Saya pikir saya bisa membuka ini ...",
  ui_story_1013_10131202_89_dialog_content = "<color=#e8d9bb>Berbunyi! Berbunyi! Berbunyi!</color>",
  ui_story_1013_10131202_90_dialog_content = "Sebuah peringatan?! Apa artinya ini?",
  ui_story_1013_10131202_91_dialog_content = "Apakah Anda mengunci saya di dalam, Soroz?",
  ui_story_1013_10131202_92_dialog_content = "Udara saat ini tidak bersirkulasi antara eksterior dan interior. Soroz telah menyegel kabin sepenuhnya.",
  ui_story_1013_10131202_93_dialog_content = "Apa yang sedang terjadi...",
  ui_story_1013_10131202_94_dialog_content = "Oh benar, seharusnya ada log di konsol kontrol...",
  ui_story_1013_10131202_95_dialog_content = "Coba saya lihat... Koordinat lokasi kita saat ini adalah...",
  ui_story_1013_10131202_96_dialog_content = "?!!",
  ui_story_1013_10131202_97_dialog_content = "Tidak ada koordinat...",
  ui_story_1013_10131202_98_dialog_content = "Tidak ada informasi lain juga!",
  ui_story_1013_10131202_99_dialog_content = "Mengapa hampir tidak ada apa pun di log?",
  ui_story_1013_10131202_100_dialog_content = "Ini adalah kenangan Soroz. Beberapa informasi sebelumnya pasti sudah dihapus.",
  ui_story_1013_10131202_101_dialog_content = "Tidak ada yang terjadi, dan tidak ada catatan. Tidak banyak kenangan dalam ingatan ini, ya?",
  ui_story_1013_10131202_102_dialog_content = "Mengapa Soroz menjadi seperti ini?",
  ui_story_1013_10131202_103_dialog_content = "Ingatan mesin berbeda dari ingatan makhluk biologis.",
  ui_story_1013_10131202_104_dialog_content = "Itu memiliki kenangan seperti itu bukan karena mudah diingat tetapi karena itu terjadi.",
  ui_story_1013_10131202_105_dialog_content = "Soroz bukan mesin! Nya...",
  ui_story_1013_10131202_106_dialog_content = "Oh tapi kamu—",
  ui_story_1013_10131202_107_dialog_content = "Maaf, saya tidak bermaksud mengatakan mesin itu buruk.",
  ui_story_1013_10131202_108_dialog_content = "Guardian One tidak mengerti mengapa Anda meminta maaf.",
  ui_story_1013_10131202_109_dialog_content = "Lebih baik Anda tidak melakukannya! Saya hanya suka minta maaf, ha... ha.",
  ui_story_1013_10131202_110_dialog_content = "?",
  ui_story_1013_10131202_111_dialog_content = "Ahem, saya ngelantur. Biarkan saya melihat apakah saya dapat menemukan informasi lebih lanjut.",
  ui_story_1013_10131202_112_dialog_content = "Guardian One menemukan beberapa informasi.",
  ui_story_1013_10131202_113_dialog_content = "Sungguh? Di mana?",
  ui_story_1013_10131202_114_dialog_content = "Dalam hal ini disebut \"Terminal.\"",
  ui_story_1013_10131202_115_dialog_content = "Apakah ini...",
  ui_story_1013_10131202_116_dialog_content = "■■■■■■■■■■■■",
  ui_story_1013_10131202_117_dialog_content = "Apa ini?",
  ui_story_1013_10131202_118_dialog_content = "Kemungkinan itu adalah teks kuno.",
  ui_story_1013_10131202_119_dialog_content = "Sesaat. Soroz mencatat prosedur penerjemahan.",
  ui_story_1013_10131202_120_dialog_content = "Saya akan mengubahnya menjadi tulisan yang dapat Anda pahami.",
  ui_story_1013_10131202_121_dialog_content = "\"Pesan yang diterima dari darat, mungkin untuk terakhir kalinya.\"",
  ui_story_1013_10131202_122_dialog_content = "\"Kota Obelisk hancur.\"",
  ui_story_1013_10131202_123_dialog_content = "Apa? Bagaimana... Bagaimana ini bisa terjadi?",
  ui_story_1013_10131202_124_dialog_content = "Itu hanya masalah waktu. Segala sesuatu di permukaan runtuh. Kota Obelisk tidak terkecuali.",
  ui_story_1013_10131202_125_dialog_content = "Itu ditakdirkan untuk terjadi sejak kepergian kami.",
  ui_story_1013_10131202_126_dialog_content = "Kemana kita akan kembali?",
  ui_story_1013_10131202_127_dialog_content = "Yakinlah, Tuan Francis berkata bahwa ketika saatnya bagi kita untuk kembali, kita akan diberi isyarat.",
  ui_story_1013_10131202_128_dialog_content = "Dia telah membuat semua pengaturan. Kita semua percaya padanya, kan?",
  ui_story_1013_10131202_129_dialog_content = "Ya, kita semua percaya padanya.",
  ui_story_1013_10131202_130_dialog_content = "Apakah kita punya pilihan lain? Mempercayai dia adalah satu-satunya yang bisa kita lakukan.",
  ui_story_1013_10131202_131_dialog_content = "Omong-omong, saya hanya ingin tahu, kapan kita bisa meninggalkan Colossi kita sendiri?",
  ui_story_1013_10131202_132_dialog_content = "Saya satu-satunya di Colossus ini dan saya akan gila.",
  ui_story_1013_10131202_133_dialog_content = "Saya ingin melihat orang lain, terutama ketika kita begitu dekat satu sama lain.",
  ui_story_1013_10131202_134_dialog_content = "Dan adik perempuanku juga. Aku sangat merindukannya. Dia ada di Colossus-mu, benar, uh...",
  ui_story_1013_10131202_135_dialog_content = "Maaf, lupa nama Anda, 217.",
  ui_story_1013_10131202_136_dialog_content = "Ya, dia baik-baik saja, jangan khawatir.",
  ui_story_1013_10131202_137_dialog_content = "Tapi belum ada yang bisa meninggalkan Colossi mereka... sama sekali tidak.",
  ui_story_1013_10131202_138_dialog_content = "Jika Anda melakukan hal-hal bodoh, Anda akan berakhir mati.",
  ui_story_1013_10131202_139_dialog_content = "Oke, tapi apakah ada hal lain yang harus kita lakukan?",
  ui_story_1013_10131202_140_dialog_content = "Aku sudah bosan makan. Jika aku juga lelah tidur, aku tidak tahu apa yang akan terjadi padaku.",
  ui_story_1013_10131202_141_dialog_content = "Tidak ada apa-apa di sini. Dan mulai sekarang, bahkan tidak akan ada berita dari luar.",
  ui_story_1013_10131202_142_dialog_content = "Yang bisa saya lakukan hanyalah menatap terminal sepanjang hari, berbicara dengan banyak nomor di layar.",
  ui_story_1013_10131202_143_dialog_content = "Cepat atau lambat, kita semua akan menjadi seperti 79 dan melupakan nama semua orang, hanya mengingat angkanya.",
  ui_story_1013_10131202_144_dialog_content = "Tidak mungkin, aku ingat namamu. Anda Parker!",
  ui_story_1013_10131202_145_dialog_content = "Saya tidak akan melupakan nama siapa pun! Caelestites tidak saling memanggil dengan nomor!",
  ui_story_1013_10131202_146_dialog_content = "Lupakan saja selagi bisa.",
  ui_story_1013_10131202_147_dialog_content = "Anda tidak akan mendapatkan apa-apa dari tetap melekat pada tradisi lama. Hanya akan lebih menyakitkan saat kau melupakannya.",
  ui_story_1013_10131202_148_dialog_content = "Anda mungkin ingat nama yang tidak Anda gunakan selama sehari, atau sebulan.",
  ui_story_1013_10131202_149_dialog_content = "Tapi bagaimana dengan setahun ke depan? Sepuluh tahun?",
  ui_story_1013_10131202_150_dialog_content = "Sepuluh tahun? Itu waktu yang lama ...",
  ui_story_1013_10131202_151_dialog_content = "Apakah ini cara kita menghabiskan dekade berikutnya?",
  ui_story_1013_10131202_152_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131202_153_dialog_content = "Kita akan kembali, kan?",
  ui_story_1013_10131202_154_dialog_content = "Ya, benar.",
  ui_story_1013_10131202_155_dialog_content = "Tuan Francis berkata kita akan mendapat sinyal untuk kembali.",
  ui_story_1013_10131202_156_dialog_content = "Kita semua percaya padanya, kan?",
  ui_story_1013_10131301_1_dialog_content = "Ini adalah rekaman percakapan Caelestite!",
  ui_story_1013_10131301_2_dialog_content = "Apakah ada Colossi lain di sekitar kita?",
  ui_story_1013_10131301_3_dialog_content = "Saat ini tidak dapat mengumpulkan informasi yang memadai.",
  ui_story_1013_10131301_4_dialog_content = "Tapi itu pasti mungkin.",
  ui_story_1013_10131301_5_dialog_content = "Dari perbincangan tersebut, Colossi lain juga tertutup rapat seperti Soroz.",
  ui_story_1013_10131301_6_dialog_content = "Semua orang menghabiskan hari demi hari hanya memutar-mutar ibu jari mereka...",
  ui_story_1013_10131301_7_dialog_content = "(Sungguh perasaan yang akrab.)",
  ui_story_1013_10131301_8_dialog_content = "(Bukankah seperti itu masa kecilku?)",
  ui_story_1013_10131301_9_dialog_content = "Guardian One mendalilkan alasan untuk itu adalah pengasingan atau perlindungan.",
  ui_story_1013_10131301_10_dialog_content = "Pengasingan: Seseorang mengurung Caelestites tertentu di Colossi untuk diasingkan ke lokasi yang ditentukan.",
  ui_story_1013_10131301_11_dialog_content = "Perlindungan: Lingkungan di luar Colossi benar-benar tidak dapat dihuni oleh Caelestites. Karena itu, mereka disegel untuk melindungi penumpangnya.",
  ui_story_1013_10131301_12_dialog_content = "Dari nada percakapan, saya lebih percaya itu untuk keadaan darurat.",
  ui_story_1013_10131301_13_dialog_content = "Mereka menyebutkan nama yang familiar... Francis.",
  ui_story_1013_10131301_14_dialog_content = "Anda tahu nama itu?",
  ui_story_1013_10131301_15_dialog_content = "Tidak terlalu. Saya mendapat kehormatan untuk melihat apa yang dia tinggalkan.",
  ui_story_1013_10131301_16_dialog_content = "Dia pasti meninggalkan kesan padamu, kalau begitu.",
  ui_story_1013_10131301_17_dialog_content = "Tentu saja. Dia adalah Caelestite yang sangat istimewa.",
  ui_story_1013_10131301_18_dialog_content = "Anda bahkan bisa menyebutnya antitesis dari Caelestites lain pada masanya.",
  ui_story_1013_10131301_19_dialog_content = "Dia tidak memilih untuk membawa perang ke dunia. Justru sebaliknya, dia berjuang melawan takdir yang dipaksakan pada Caelestites.",
  ui_story_1013_10131301_20_dialog_content = "Saya pernah sangat tersentuh oleh keinginannya pada saat saya pikir semua harapan hilang.",
  ui_story_1013_10131301_21_dialog_content = "Untungnya, sekarang menjadi jelas bahwa dia bukan satu-satunya yang memiliki tekad seperti itu.",
  ui_story_1013_10131301_22_dialog_content = "Apakah Anda mengacu pada mereka yang berbicara?",
  ui_story_1013_10131301_23_dialog_content = "Ya, Caelestites diidentikkan dengan angka.",
  ui_story_1013_10131301_24_dialog_content = "Sudah beberapa generasi, tapi kami berbagi kepercayaan yang sama untuk nama yang sama.",
  ui_story_1013_10131301_25_dialog_content = "Itu saja membuat saya merasa mereka memiliki iman.",
  ui_story_1013_10131301_26_dialog_content = "Mereka tidak dipaksa ke pengasingan, tetapi memilih jalan mereka sendiri.",
  ui_story_1013_10131301_27_dialog_content = "Mungkin itu adalah sesuatu yang mengerikan yang memaksa mereka mengambil tindakan ekstrim seperti itu.",
  ui_story_1013_10131301_28_dialog_content = "Itu adalah teori yang sangat aneh. Guardian One tidak mengerti, tetapi kesimpulan Anda telah dicatat.",
  ui_story_1013_10131301_29_dialog_content = "Anda tidak perlu keluar dari cara Anda untuk mencatatnya ...",
  ui_story_1013_10131301_30_dialog_content = "Percakapan berakhir di sana. Apakah ada informasi lain yang tersedia?",
  ui_story_1013_10131301_31_dialog_content = "Tidak. Itu saja.",
  ui_story_1013_10131301_32_dialog_content = "Jadi apa yang kita lakukan sekarang?",
  ui_story_1013_10131301_33_dialog_content = "Kami tidak menemukan gangguan apa pun dan kami tidak memiliki petunjuk apa pun.",
  ui_story_1013_10131301_34_dialog_content = "Apakah kita seharusnya duduk di sini dan mengalami kebosanan seperti orang Caelest lainnya?",
  ui_story_1013_10131301_35_dialog_content = "Itu tentu metode yang sangat tidak efisien untuk memeriksa data.",
  ui_story_1013_10131301_36_dialog_content = "Harap tunggu sementara saya melakukan pencarian yang lebih tepat.",
  ui_story_1013_10131301_37_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1013_10131301_38_dialog_content = "Apa itu tadi? Apa yang kamu lakukan?",
  ui_story_1013_10131301_39_dialog_content = "Ini mungkin memengaruhi gambar yang Anda lihat, tetapi jangan panik.",
  ui_story_1013_10131301_40_dialog_content = "Saya tidak panik, hanya bingung.",
  ui_story_1013_10131301_41_dialog_content = "Sederhananya, Guardian One memilah-milah ingatan.",
  ui_story_1013_10131301_42_dialog_content = "Kami mempercepat kenangan masa lalu tanpa gangguan.",
  ui_story_1013_10131301_43_dialog_content = "Kamu bisa melakukannya?",
  ui_story_1013_10131301_44_dialog_content = "Aaaaah!!",
  ui_story_1013_10131301_45_dialog_content = "Woah!",
  ui_story_1013_10131301_46_dialog_content = "Ada apa?!",
  ui_story_1013_10131301_47_dialog_content = "Mengabaikan semua data yang tidak rusak secara alami akan membuat kita berakhir—",
  ui_story_1013_10131301_48_dialog_content = "Graagh!",
  ui_story_1013_10131301_49_dialog_content = "Hei, kau baik-baik saja?",
  ui_story_1013_10131301_50_dialog_content = "—di mana gangguannya.",
  ui_story_1013_10131301_51_dialog_content = "Saat-saat seperti ini membutuhkan penjelasan langsung!",
  ui_story_1013_10131301_52_dialog_content = "Jadi Eclipsites adalah gangguannya?",
  ui_story_1013_10131301_53_dialog_content = "Ya. Gangguan akan bermanifestasi sebagai gambar yang tidak Anda sukai atau benci—",
  ui_story_1013_10131301_54_dialog_content = "Graagh!",
  ui_story_1013_10131301_55_dialog_content = "Anda-",
  ui_story_1013_10131301_56_dialog_content = "—Tidak apa-apa, struktur data saya sangat tahan lama. Itu tidak akan mudah hancur.",
  ui_story_1013_10131301_57_dialog_content = "Baiklah, aku mengerti, jangan jadikan dirimu samsak tinju lagi. Ini menakutkan.",
  ui_story_1013_10131301_58_dialog_content = "Saya tidak tahu apa-apa tentang data, saya juga tidak punya waktu untuk pelajaran.",
  ui_story_1013_10131301_59_dialog_content = "Tapi karena mereka dalam bentuk Eclipsite, aku akan memperlakukan mereka seperti Eclipsites!",
  ui_story_1013_10131302_1_dialog_content = "Rapid Torrent!",
  ui_story_1013_10131302_2_dialog_content = "Ice Blossom!",
  ui_story_1013_10131302_3_dialog_content = "Wah, rasanya luar biasa...",
  ui_story_1013_10131302_4_dialog_content = "Guardian One tidak jelas manfaat dari vokalisasi seperti itu dalam pertempuran.",
  ui_story_1013_10131302_5_dialog_content = "Sebenarnya, sama.",
  ui_story_1013_10131302_6_dialog_content = "Saya baru saja melihat Aurorian melakukannya sepanjang waktu dalam perkelahian, jadi saya pikir saya akan mencobanya.",
  ui_story_1013_10131302_7_dialog_content = "Mungkin keren memanggil gerakanmu saat bertarung?",
  ui_story_1013_10131302_8_dialog_content = "Lihat, musuh dihancurkan setelah aku berteriak, jadi itu berhasil.",
  ui_story_1013_10131302_9_dialog_content = "Hmm. Guardian One akan mencoba untuk memahami argumen yang sama sekali tidak masuk akal ini.",
  ui_story_1013_10131302_10_dialog_content = "Ha, mari kita kesampingkan itu untuk saat ini. Jadi, ada perubahan di Soroz?",
  ui_story_1013_10131302_11_dialog_content = "Sekitar 37% dari gangguan telah dihapus. Tindakan Anda efektif.",
  ui_story_1013_10131302_12_dialog_content = "Sebagian fungsi telah dipulihkan.",
  ui_story_1013_10131302_13_dialog_content = "37%! Apakah saya menyingkirkan sebanyak itu sekaligus?",
  ui_story_1013_10131302_14_dialog_content = "Soroz akan memperbaiki gangguan yang tersebar dan terisolasi itu sendiri.",
  ui_story_1013_10131302_15_dialog_content = "Oleh karena itu, gangguan yang masih menunggu kita akan menunjukkan kohesi yang lebih besar.",
  ui_story_1013_10131302_16_dialog_content = "Menurut perhitungan, hanya satu kumpulan gangguan yang tersisa.",
  ui_story_1013_10131302_17_dialog_content = "Baiklah, itu artinya kita hampir berhasil!",
  ui_story_1013_10131302_18_dialog_content = "Ya, tapi kumpulannya lebih kontroversial. Anda harus berhati-hati.",
  ui_story_1013_10131302_19_dialog_content = "Jika Anda siap, Guardian One akan memulai pencarian presisi dan maju cepat ke gangguan.",
  ui_story_1013_10131302_20_dialog_content = "Tunggu, segmen waktu kita sekarang berbeda dengan saat kita mulai, kan?",
  ui_story_1013_10131302_21_dialog_content = "Benar. Pencarian melewati periode yang sangat lama.",
  ui_story_1013_10131302_22_dialog_content = "Karena kurangnya titik referensi, rentang yang tepat tidak dapat dipastikan.",
  ui_story_1013_10131302_23_dialog_content = "Jika demikian, saya ingin memeriksa terminal lagi.",
  ui_story_1013_10131302_24_dialog_content = "Saya ingin tahu tentang apa yang dialami Caelestites saat ini.",
  ui_story_1013_10131302_25_dialog_content = "Dipahami. Guardian One akan mengekstrak pesan terminal untuk Anda.",
  ui_story_1013_10131302_26_dialog_content = "Ingatlah untuk menerjemahkannya untuk saya terlebih dahulu.",
  ui_story_1013_10131302_27_dialog_content = "Tentu saja. Optimalisasi dan efisiensi mendorong tindakan semua AI.",
  ui_story_1013_10131302_28_dialog_content = "Dan Guardian One adalah model yang paling optimal.",
  ui_story_1013_10131302_29_dialog_content = "Hai semuanya!",
  ui_story_1013_10131302_30_dialog_content = "Di sini!",
  ui_story_1013_10131302_31_dialog_content = "Ini agak mendadak, tapi hari ini sebenarnya adalah hari ulang tahunku.",
  ui_story_1013_10131302_32_dialog_content = "Ada yang mau dengar saya nyanyikan lagu?",
  ui_story_1013_10131302_33_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131302_34_dialog_content = "Baik, saya berubah pikiran.",
  ui_story_1013_10131302_35_dialog_content = "Tidak ada lagu. Aku akan menulis puisi untuk kalian!",
  ui_story_1013_10131302_36_dialog_content = "Saya menulis puisi yang bagus. Ayah berkata aku akan tumbuh menjadi seorang penyair!",
  ui_story_1013_10131302_37_dialog_content = "Saya ingat ulang tahun terakhir Anda, 35.",
  ui_story_1013_10131302_38_dialog_content = "Saya lupa sudah berapa lama, tapi yang pasti bukan setahun yang lalu hari ini.",
  ui_story_1013_10131302_39_dialog_content = "Anda memiliki ingatan yang bagus, 982. Dan di sini saya pikir saya bisa membodohi kalian semua...",
  ui_story_1013_10131302_40_dialog_content = "Ulang tahun itu penting, jangan gunakan itu sebagai lelucon.",
  ui_story_1013_10131302_41_dialog_content = "Sudahlah, lupakan hari ulang tahunnya.",
  ui_story_1013_10131302_42_dialog_content = "Biarkan saya berbagi tip dengan Anda semua!",
  ui_story_1013_10131302_43_dialog_content = "Panaskan kaleng #4 dan campur dengan kaleng beku #15.",
  ui_story_1013_10131302_44_dialog_content = "Ini sangat lezat! Kalian harus mencobanya!",
  ui_story_1013_10131302_45_dialog_content = "Berbuih seperti biasa, 35.",
  ui_story_1013_10131302_46_dialog_content = "79! Sudah lama!",
  ui_story_1013_10131302_47_dialog_content = "Ya, sudah. Saya jarang memeriksa terminal sekarang.",
  ui_story_1013_10131302_48_dialog_content = "Anda harus memeriksa lebih sering. Aku tidak suka berbicara sendiri.",
  ui_story_1013_10131302_49_dialog_content = "Yah, saya pikir 982 suka menjadi partner-in-crime Anda.",
  ui_story_1013_10131302_50_dialog_content = "Tidak mungkin, dia muncul bahkan lebih sedikit darimu, 79!",
  ui_story_1013_10131302_51_dialog_content = "Dia datang hari ini hanya untuk mempermalukanku!",
  ui_story_1013_10131302_52_dialog_content = "Haruskah saya meminta maaf?",
  ui_story_1013_10131302_53_dialog_content = "Yah, tidak. Aku salah berbohong.",
  ui_story_1013_10131302_54_dialog_content = "Sebenarnya, saya memutuskan untuk memeriksa terminal karena hari ini spesial bagi saya.",
  ui_story_1013_10131302_55_dialog_content = "Saya ingin memperingatinya.",
  ui_story_1013_10131302_56_dialog_content = "Oh, hari ini 982 ulang tahun?",
  ui_story_1013_10131302_57_dialog_content = "Tidak.",
  ui_story_1013_10131302_58_dialog_content = "Bisa dibilang hari ini kebalikan dari hari ulang tahun.",
  ui_story_1013_10131302_59_dialog_content = "982, jangan bilang...",
  ui_story_1013_10131302_60_dialog_content = "Oh, bukankah kamu menyebutkan menulis puisi? Bagaimana kalau menulis satu untukku?",
  ui_story_1013_10131302_61_dialog_content = "Tentu! Subjek apa pun yang ingin Anda minta?",
  ui_story_1013_10131302_62_dialog_content = "Tanah. Sebuah puisi yang berkaitan dengan permukaan di bawah kita.",
  ui_story_1013_10131302_63_dialog_content = "Oke, biarkan saya memikirkannya dan menulis yang akan Anda sukai!",
  ui_story_1013_10131302_64_dialog_content = "Berapa lama waktu yang dibutuhkan?",
  ui_story_1013_10131302_65_dialog_content = "Tidak yakin. Ide tidak datang kepada saya saat ini.",
  ui_story_1013_10131302_66_dialog_content = "Bisakah kamu menunggu? Saya akan menghubungi Anda segera setelah saya selesai!",
  ui_story_1013_10131302_67_dialog_content = "Anda harus mempercepatnya sebelum saya memutuskan saya tidak menginginkannya lagi.",
  ui_story_1013_10131302_68_dialog_content = "Anda tidak bisa melakukan itu! Tidak setiap hari saya bisa menulis puisi untuk orang lain!",
  ui_story_1013_10131302_69_dialog_content = "Anda harus mengambilnya!",
  ui_story_1013_10131302_70_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131302_71_dialog_content = "Puisimu sudah siap, 982!",
  ui_story_1013_10131302_72_dialog_content = "982?",
  ui_story_1013_10131302_73_dialog_content = "Hei, aku berusaha keras dan memikirkannya!",
  ui_story_1013_10131302_74_dialog_content = "Aku akan marah jika kamu tidak segera merespon!",
  ui_story_1013_10131302_75_dialog_content = "982! 982! 982!",
  ui_story_1013_10131302_76_dialog_content = "...",
  ui_story_1013_10131302_77_dialog_content = "Lupakan. Aku tidak akan melawanmu karena masalah sepele seperti itu.",
  ui_story_1013_10131302_78_dialog_content = "Beri tahu saya saat Anda aktif kembali. Saya di sini sepanjang waktu.",
  ui_story_1013_10131302_79_dialog_content = "Anda sangat awal hari ini, 35.",
  ui_story_1013_10131302_80_dialog_content = "Yeah, karena aku begadang semalaman menyelesaikan puisi untuk 982.",
  ui_story_1013_10131302_81_dialog_content = "Tapi dia...",
  ui_story_1013_10131302_82_dialog_content = "Wow, kamu bekerja keras, ya?",
  ui_story_1013_10131302_83_dialog_content = "Tapi Anda tahu betapa berubah-ubahnya 982.",
  ui_story_1013_10131302_84_dialog_content = "Apa yang dia inginkan kemarin, dia mungkin tidak menginginkannya hari ini.",
  ui_story_1013_10131302_85_dialog_content = "Itu benar, dia melakukan itu!",
  ui_story_1013_10131302_86_dialog_content = "Jadi jangan khawatir tentang itu. Kirim ke saya sebagai gantinya. Saya ingin melihat seberapa berbakat Anda.",
  ui_story_1013_10131302_87_dialog_content = "Tapi saya berharap 982 akan membacanya terlebih dahulu karena ini adalah hadiahnya.",
  ui_story_1013_10131302_88_dialog_content = "Jika Anda suka, saya juga bisa menulis satu untuk Anda, 79!",
  ui_story_1013_10131302_89_dialog_content = "Demi aku?",
  ui_story_1013_10131302_90_dialog_content = "Lebih baik tidak, saya tidak ingin Anda membakar minyak tengah malam lagi.",
  ui_story_1013_10131302_91_dialog_content = "Tidak, tidak apa-apa! Kami memiliki lebih dari cukup waktu untuk tidur akhir-akhir ini.",
  ui_story_1013_10131302_92_dialog_content = "Saya tidak bisa begitu saja membuat Anda menulis puisi di hari tua mana pun.",
  ui_story_1013_10131302_93_dialog_content = "Beri aku satu di masa depan.",
  ui_story_1013_10131302_94_dialog_content = "Tunggu hari yang spesial bagiku.",
  ui_story_1013_10131302_95_dialog_content = "Oh, sayang sekali.",
  ui_story_1013_10131302_96_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131302_97_dialog_content = "Saya menemukan piringan hitam yang belum dibuka di penyimpanan hari ini.",
  ui_story_1013_10131302_98_dialog_content = "Itu cukup bagus! Ada yang mau mendengarnya?",
  ui_story_1013_10131302_99_dialog_content = "Hei, ada orang di sana?",
  ui_story_1013_10131302_100_dialog_content = "Bagaimanapun, saya mengunggahnya ke terminal, jadi periksalah jika Anda tertarik!",
  ui_story_1013_10131302_101_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131302_102_dialog_content = "Alat mandi saya berhenti bekerja...",
  ui_story_1013_10131302_103_dialog_content = "Adakah yang tahu cara memperbaikinya?",
  ui_story_1013_10131302_104_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131302_105_dialog_content = "Suhu di sini sudah turun. Cobalah untuk tetap hangat dan berkumpul, semuanya.",
  ui_story_1013_10131302_106_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131302_107_dialog_content = "Uh, aku sudah lama tidak berbicara dengan siapa pun, jadi aku ingin mengobrol.",
  ui_story_1013_10131302_108_dialog_content = "Hari ini adalah hari ulang tahunku.",
  ui_story_1013_10131302_109_dialog_content = "Ini nyata, kali ini.",
  ui_story_1013_10131302_110_dialog_content = "Siapapun, tolong bicara padaku...",
  ui_story_1013_10131302_111_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131302_112_dialog_content = "Sudah lama aku tidak mendengar kabar darimu, Tuan 217.",
  ui_story_1013_10131302_113_dialog_content = "Anda tidak berbohong ketika Anda mengatakan kami akan kembali, kan?",
  ui_story_1013_10131302_114_dialog_content = "Apakah kamu tidak menginginkan puisimu lagi, bodoh 982?",
  ui_story_1013_10131302_115_dialog_content = "Kapan saya akan bertemu lagi di terminal, 79?",
  ui_story_1013_10131302_116_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131302_117_dialog_content = "Huh, tidak ada orang di sini.",
  ui_story_1013_10131302_118_dialog_content = "Sejarah hanya diisi dengan pesan saya.",
  ui_story_1013_10131302_119_dialog_content = "Aku merasa semua orang membenciku.",
  ui_story_1013_10131302_120_dialog_content = "Ini tidak bisa terus berlanjut.",
  ui_story_1013_10131302_121_dialog_content = "Akan kuatasi!",
  ui_story_1013_10131302_122_dialog_content = "Perintah: Periksa status semua Colossi!",
  ui_story_1013_10131302_123_dialog_content = "Colossus 217, sempurna, tidak ada kelainan.",
  ui_story_1013_10131302_124_dialog_content = "Colossus 982, sempurna, tidak ada kelainan.",
  ui_story_1013_10131302_125_dialog_content = "Colossus 79, sempurna, tidak ada kelainan.",
  ui_story_1013_10131302_126_dialog_content = "Colossus 35, sempurna, tidak ada kelainan.",
  ui_story_1013_10131302_127_dialog_content = "Di sana kita pergi! Itu sedikit lebih hidup!",
  ui_story_1013_10131401_1_dialog_content = "Baiklah, aku sudah selesai.",
  ui_story_1013_10131401_2_dialog_content = "Aku merasakan kesedihan yang tak terlukiskan.",
  ui_story_1013_10131401_3_dialog_content = "Guardian One tidak mengerti.",
  ui_story_1013_10131401_4_dialog_content = "Berdasarkan analisis, itu hanya dialog biasa dan tidak boleh menimbulkan kesedihan.",
  ui_story_1013_10131401_5_dialog_content = "Lihatlah catatan ini. Jumlah peserta terus menyusut seiring berjalannya waktu.",
  ui_story_1013_10131401_6_dialog_content = "Hingga hanya tersisa satu.",
  ui_story_1013_10131401_7_dialog_content = "Saya berempati dengan perasaan itu.",
  ui_story_1013_10131401_8_dialog_content = "Menyuarakan pikiran yang tidak masuk akal dengan lantang kepada siapa pun, hari demi hari...",
  ui_story_1013_10131401_9_dialog_content = "hanya untuk kesempatan mendapatkan tanggapan yang akan menghidupkan kembali harapan.",
  ui_story_1013_10131401_10_dialog_content = "Namun pada akhirnya, keinginan sederhana itu pun sia-sia.",
  ui_story_1013_10131401_11_dialog_content = "Dipahami. Anda tidak menyinggung konten sebenarnya tetapi jumlah peserta dan frekuensi pesan mereka.",
  ui_story_1013_10131401_12_dialog_content = "Guardian One telah mencatat ekspresi empatik ini.",
  ui_story_1013_10131401_13_dialog_content = "Saya tidak akan menyebutnya ... Anda tahu, sulit untuk dijelaskan.",
  ui_story_1013_10131401_14_dialog_content = "Saya merasakan keputusasaan mereka akan kontak sosial.",
  ui_story_1013_10131401_15_dialog_content = "Itulah keterpurukan yang saya rasakan. Anda bahkan bisa mengatakan saya takut.",
  ui_story_1013_10131401_16_dialog_content = "Takut. Apakah Anda takut ditempatkan di posisi mereka?",
  ui_story_1013_10131401_17_dialog_content = "Ya. Tetapi ketika saya memikirkannya, saya memiliki pengalaman serupa.",
  ui_story_1013_10131401_18_dialog_content = "Saya pernah tinggal sendiri di bawah tanah selama 17 tahun.",
  ui_story_1013_10131401_19_dialog_content = "Saya tidak tahu apakah itu lebih panjang atau lebih pendek dari apa yang mereka lalui.",
  ui_story_1013_10131401_20_dialog_content = "Tapi keputusasaan saya tidak sekuat mereka.",
  ui_story_1013_10131401_21_dialog_content = "Mungkin karena aku membawa Soroz sepanjang waktu.",
  ui_story_1013_10131401_22_dialog_content = "Tunggu, tapi mereka juga punya Colossi...",
  ui_story_1013_10131401_23_dialog_content = "Hanya saja mereka tampaknya tidak memiliki kepribadian apapun.",
  ui_story_1013_10131401_24_dialog_content = "Bagaimanapun juga, Anda tidak dapat memerangi isolasi hanya dengan respons mekanis.",
  ui_story_1013_10131401_25_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1013_10131401_26_dialog_content = "Hmm? Apa yang terjadi?",
  ui_story_1013_10131401_27_dialog_content = "Apakah Anda mempercepat lagi, Guardian One?",
  ui_story_1013_10131401_28_dialog_content = "Guardian One tidak menjalankan perintah apa pun.",
  ui_story_1013_10131401_29_dialog_content = "Jadi itu artinya ini...",
  ui_story_1013_10131401_30_dialog_content = "I-Itu berhenti.",
  ui_story_1013_10131401_31_dialog_content = "Kami baru saja menelusuri data yang disimpan Soroz dalam urutan kronologis.",
  ui_story_1013_10131401_32_dialog_content = "Fenomena tersebut mengindikasikan adanya masalah dengan data itu sendiri.",
  ui_story_1013_10131401_33_dialog_content = "Datanya rusak?!",
  ui_story_1013_10131401_34_dialog_content = "Ini aneh, tapi menurut penilaianku, malfungsi itu bukan karena penghapusan data.",
  ui_story_1013_10131401_35_dialog_content = "Saya tidak dapat menemukan kerusakan yang setara di basis data saya.",
  ui_story_1013_10131401_36_dialog_content = "Ada hal-hal yang bahkan Anda tidak tahu?",
  ui_story_1013_10131401_37_dialog_content = "Ini sangat aneh. Mungkin ini bukan kerusakan, tapi anomali.",
  ui_story_1013_10131401_38_dialog_content = "Anomali?",
  ui_story_1013_10131401_39_dialog_content = "Ya. Guardian One menemukan data serupa di log yang tidak terkait dengan mesin.",
  ui_story_1013_10131401_40_dialog_content = "Ini sangat mirip dengan \"kelupaan\" yang umum terjadi pada otak makhluk hidup.",
  ui_story_1013_10131401_41_dialog_content = "Kelupaan? Maksudmu Soroz melupakan ingatan tertentu, itulah sebabnya kita melewatkan momen-momen tertentu dalam waktu?",
  ui_story_1013_10131401_42_dialog_content = "Jika teori berlaku, itu adalah kesimpulan logis.",
  ui_story_1013_10131401_43_dialog_content = "Tetapi tidak masuk akal jika mesin lupa karena mereka mengikuti protokol yang lebih rumit untuk menghapus data.",
  ui_story_1013_10131401_44_dialog_content = "Itu sebenarnya menjelaskannya karena Soroz bukan mesin!",
  ui_story_1013_10131401_45_dialog_content = "Luncurkan ulang terminal lagi, Guardian One!",
  ui_story_1013_10131401_46_dialog_content = "Jika waktu telah berlalu, seharusnya ada catatan baru di terminal.",
  ui_story_1013_10131401_47_dialog_content = "Ya. Mohon tunggu.",
  ui_story_1013_10131401_48_dialog_content = "Perintah: Masuk, Colossus 35!",
  ui_story_1013_10131401_49_dialog_content = "Colossus 35 siap, menunggu pesanan.",
  ui_story_1013_10131401_50_dialog_content = "Baiklah, sekarang saya akan mengambil cerita dari terakhir kali.",
  ui_story_1013_10131401_51_dialog_content = "Ini tentang hari saya berangkat.",
  ui_story_1013_10131401_52_dialog_content = "Saya baru saja mendapatkan kredensial Navigator saya, dan ini adalah pertama kalinya saya mengemudikan Colossus.",
  ui_story_1013_10131401_53_dialog_content = "Saya menghabiskan sepanjang malam memikirkan semua kemungkinan skenario darurat dan bagaimana saya harus menanggapinya.",
  ui_story_1013_10131401_54_dialog_content = "Saya mengemasi tas saya penuh dengan pakaian yang menghabiskan setiap sen dari uang saku saya.",
  ui_story_1013_10131401_55_dialog_content = "Saya berencana untuk menyimpan pakaian terbaik untuk kepulangan kami. Saya ingin kembali seperti pahlawan.",
  ui_story_1013_10131401_56_dialog_content = "Ternyata, semua itu tidak ada gunanya.",
  ui_story_1013_10131401_57_dialog_content = "Kami tidak mengalami keadaan darurat. Bahkan tidak sekali. Akhirnya, saya bahkan tidak perlu pilot lagi.",
  ui_story_1013_10131401_58_dialog_content = "Baju itu masih terlipat rapi di dalam koper.",
  ui_story_1013_10131401_59_dialog_content = "Saya mencobanya kemarin dan menemukan bahwa itu terlalu kecil untuk saya sekarang.",
  ui_story_1013_10131401_60_dialog_content = "Huh, gaunnya sangat cantik... Apa kau masih mendengarkan, Colossus 35?",
  ui_story_1013_10131401_61_dialog_content = "Perintah: Masuk, Colossus 35!",
  ui_story_1013_10131401_62_dialog_content = "Colossus 35 siap, menunggu pesanan.",
  ui_story_1013_10131401_63_dialog_content = "Baguslah kau masih mendengarkan. aku akan terus berjalan...",
  ui_story_1013_10131401_64_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131401_65_dialog_content = "Komando: Masuk, Colossus 982!",
  ui_story_1013_10131401_66_dialog_content = "Colossus 982 siap, menunggu pesanan.",
  ui_story_1013_10131401_67_dialog_content = "Bagus! Hari ini, Anda akan menjadi orang yang mendengarkan cerita saya.",
  ui_story_1013_10131401_68_dialog_content = "Mengapa saya tidak membicarakannya setelah kita berangkat? Semua orang sudah mulai terbiasa untuk tidak bertemu dan hanya mengobrol melalui terminal.",
  ui_story_1013_10131401_69_dialog_content = "Colossi kami semua memiliki sebutan, jadi itulah yang biasa kami sapa satu sama lain.",
  ui_story_1013_10131401_70_dialog_content = "Itu membuat saya takut karena angka terasa impersonal dan dingin bagi saya.",
  ui_story_1013_10131401_71_dialog_content = "Jadi saya bersikeras memanggil yang lain dengan nama mereka.",
  ui_story_1013_10131401_72_dialog_content = "Berapa lama saya mempertahankannya? Beberapa bulan, mungkin setahun... Saya tidak ingat.",
  ui_story_1013_10131401_73_dialog_content = "Sampai saya lupa nama untuk pertama kalinya.",
  ui_story_1013_10131401_74_dialog_content = "Tidaklah sopan untuk memanggil hanya dia dan tidak ada orang lain dengan nomor.",
  ui_story_1013_10131401_75_dialog_content = "Saya tidak punya pilihan selain mulai memanggil semua orang dengan sebutan mereka.",
  ui_story_1013_10131401_76_dialog_content = "982 menghubungkannya dengan saya saat tumbuh dewasa, tetapi saya sebenarnya membencinya.",
  ui_story_1013_10131401_77_dialog_content = "Saya tidak ingin tumbuh dewasa, atau melupakan nama semua orang.",
  ui_story_1013_10131401_78_dialog_content = "...",
  ui_story_1013_10131401_79_dialog_content = "Yup, semua orang berhak mendapatkan nama. Bahkan Colossi.",
  ui_story_1013_10131401_80_dialog_content = "Saya tahu! Saya akan memberi nama Colossi, tidak ada lagi nomor!",
  ui_story_1013_10131401_81_dialog_content = "Pertama adalah Anda, 982. Coba saya lihat...",
  ui_story_1013_10131401_82_dialog_content = "Navigator Anda adalah orang yang menjengkelkan, tetapi \"Irritable\" bukanlah nama yang bagus, jadi itu harus nama lain.",
  ui_story_1013_10131401_83_dialog_content = "Saya akan memanggil Anda \"Solituz\"!",
  ui_story_1013_10131401_84_dialog_content = "Perintah: Merevisi tanda panggilan untuk Colossus 982 dari 982 menjadi Solituz.",
  ui_story_1013_10131401_85_dialog_content = "Perintah disalin. Tanda panggilan direvisi.",
  ui_story_1013_10131401_86_dialog_content = "Berikutnya adalah 217!",
  ui_story_1013_10131401_87_dialog_content = "Tuan 217 seperti pemimpin kami, jadi Naviduz akan menjadi namamu!",
  ui_story_1013_10131401_88_dialog_content = "Perintah: Revisi tanda panggilan untuk Colossus 217 dari 217 menjadi Naviduz.",
  ui_story_1013_10131401_89_dialog_content = "Perintah disalin. Tanda panggilan direvisi.",
  ui_story_1013_10131401_90_dialog_content = "Lalu kita punya Nona 79. Dia lembut dan perhatian, jadi kita butuh nama yang cantik untuk Colossus-nya!",
  ui_story_1013_10131401_91_dialog_content = "Nama yang cantik... Nama yang cantik...",
  ui_story_1013_10131401_92_dialog_content = "Apakah Anda memanggil saya, 35?",
  ui_story_1013_10131401_93_dialog_content = "79! Anda akhirnya berada di terminal!",
  ui_story_1013_10131401_94_dialog_content = "Ya. Saya terkesan, 35, bahwa Anda dapat melakukan percakapan sendiri.",
  ui_story_1013_10131401_95_dialog_content = "Hee. Saya menamai Colossi semua orang sekarang.",
  ui_story_1013_10131401_96_dialog_content = "Memberi nama Colossi? Kedengarannya menyenangkan, dan seperti sesuatu yang akan Anda lakukan.",
  ui_story_1013_10131401_97_dialog_content = "Ya, itu menyenangkan! Saya ingin memberi nama setiap Colossus!",
  ui_story_1013_10131401_98_dialog_content = "Itu tugas yang berat, mengingat berapa banyak Colossi yang kita miliki.",
  ui_story_1013_10131401_99_dialog_content = "Yah, kita tidak punya apa-apa selain waktu.",
  ui_story_1013_10131401_100_dialog_content = "Benar.",
  ui_story_1013_10131401_101_dialog_content = "Oh, saya baru saja akan memberi nama Colossus Anda. Ada ide?",
  ui_story_1013_10131401_102_dialog_content = "Sebenarnya 35, saya punya permintaan untuk Anda hari ini.",
  ui_story_1013_10131401_103_dialog_content = "Permintaan? Maksudmu sesuatu yang bisa kulakukan untukmu?",
  ui_story_1013_10131401_104_dialog_content = "Ya.",
  ui_story_1013_10131401_105_dialog_content = "Saya ingin Anda menulis puisi untuk saya.",
  ui_story_1013_10131401_106_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131401_107_dialog_content = "Maukah Anda melakukan itu untuk saya, 35?",
  ui_story_1013_10131401_108_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1013_10131401_109_dialog_content = "Apa yang terjadi? Saya belum selesai membacanya!",
  ui_story_1013_10131401_110_dialog_content = "Kami melewatkan waktu ?!",
  ui_story_1013_10131401_111_dialog_content = "Alokasi data jarang untuk segmen khusus ini.",
  ui_story_1013_10131401_112_dialog_content = "Tolong dengan bahasa yang bisa saya mengerti.",
  ui_story_1013_10131401_113_dialog_content = "Soroz tidak memiliki banyak kenangan tentang periode waktu ini.",
  ui_story_1013_10131401_114_dialog_content = "Agar adil, tidak banyak yang perlu diingat.",
  ui_story_1013_10131401_115_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_1013_10131401_116_dialog_content = "Wah! Itu muncul entah dari mana!",
  ui_story_1013_10131401_117_dialog_content = "Suara apa itu?",
  ui_story_1013_10131401_118_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_1013_10131401_119_dialog_content = "Pintu kabin ditabrak dari luar.",
  ui_story_1013_10131401_120_dialog_content = "Siapa yang melakukan itu? Tidak pernah ada orang lain di sini.",
  ui_story_1013_10131401_121_dialog_content = "Tunggu, kecuali...",
  ui_story_1013_10131401_122_dialog_content = "Penilaian: Kami sampai pada kesalahan yang disebabkan oleh anomali data.",
  ui_story_1013_10131401_123_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1013_10131401_124_dialog_content = "Anda bisa memperingatkan saya sebelumnya sehingga saya punya waktu untuk bersiap!",
  ui_story_1013_10131401_125_dialog_content = "Tunggu, saya tidak berpikir itu adalah Eclipsite... Apa itu?",
  ui_story_1013_10131401_126_dialog_content = "...",
  ui_story_1013_10131401_127_dialog_content = "Sebuah bunga? Tumbuh di lantai kabin?!",
  ui_story_1013_10131401_128_dialog_content = "Saya tidak perlu Anda memberi tahu saya kali ini untuk mengetahui bahwa ini adalah kesalahan.",
  ui_story_1013_10131401_129_dialog_content = "Ya itu. Tapi Guardian One tidak mengerti bagaimana Anda mencapai kesimpulan itu.",
  ui_story_1013_10131401_130_dialog_content = "Karena itu tidak logis! Bunga apa yang bisa tumbuh di sini?",
  ui_story_1013_10131401_131_dialog_content = "Tapi bukankah Anda mengatakan gangguan akan terjadi dalam bentuk hal-hal yang tidak saya sukai?",
  ui_story_1013_10131401_132_dialog_content = "Saya tidak bisa benar-benar membenci sesuatu yang belum pernah saya lihat sebelumnya.",
  ui_story_1013_10131401_133_dialog_content = "Analisis Guardian One adalah bahwa oposisi mengevaluasi upaya deteksi kesalahan Anda sebelumnya.",
  ui_story_1013_10131401_134_dialog_content = "Oleh karena itu, dilakukan penyesuaian terhadap glitch sebagai penanggulangan.",
  ui_story_1013_10131401_135_dialog_content = "Itu mengakses ingatan Soroz dan memanifestasikan dirinya sebagai entitas individu yang lebih cocok untuk pertempuran.",
  ui_story_1013_10131401_136_dialog_content = "Salah satunya yang Anda lihat saat ini.",
  ui_story_1013_10131401_137_dialog_content = "Bisakah benda ini bertarung sama sekali?",
  ui_story_1013_10131401_138_dialog_content = "Itu adalah Eclipsite yang disebut Diavola yang diambil dari ingatan Soroz.",
  ui_story_1013_10131401_139_dialog_content = "Itu gerhana? Terlihat seperti ini?",
  ui_story_1013_10131401_140_dialog_content = "Ya.",
  ui_story_1013_10131401_141_dialog_content = "Itu mengesankan, mengubah taktik secara langsung berdasarkan pertempuran sebelumnya.",
  ui_story_1013_10131401_142_dialog_content = "Saya akan dirugikan jika ini berlanjut selama beberapa putaran lagi.",
  ui_story_1013_10131401_143_dialog_content = "Guardian One, apakah ini angkatan terakhir?",
  ui_story_1013_10131401_144_dialog_content = "Ya. Hati-hati, ini mengandung lebih banyak gangguan daripada sebelumnya.",
  ui_story_1013_10131401_145_dialog_content = "Kemampuan tempurnya juga dioptimalkan.",
  ui_story_1013_10131401_146_dialog_content = "Aku mengerti, aku mengerti.",
  ui_story_1013_10131401_147_dialog_content = "Keberatan memberi tahu saya peluang saya untuk menang?",
  ui_story_1013_10131401_148_dialog_content = "10%.",
  ui_story_1013_10131401_149_dialog_content = "Itu saja?",
  ui_story_1013_10131401_150_dialog_content = "Yah, setidaknya itu bukan nol.",
  ui_story_1013_10131401_151_dialog_content = "Itu tidak penting. Tujuan kami adalah menghapus gangguan data, bukan memenangkan pertempuran.",
  ui_story_1013_10131401_152_dialog_content = "Anda juga akan mendapat bantuan saya.",
  ui_story_1013_10131401_153_dialog_content = "Betapa jarang, mendengar kata-kata yang menghibur darimu. Aku merasa lebih baik sekarang!",
  ui_story_1013_10131401_154_dialog_content = "Tapi saya masih menutup telepon tentang peluang 10%.",
  ui_story_1013_10131401_155_dialog_content = "Anda memang mengatakan bahwa Anda terus-menerus mengoptimalkan tindakan Anda, bukan?",
  ui_story_1013_10131401_156_dialog_content = "Ya.",
  ui_story_1013_10131401_157_dialog_content = "Kemudian perhatikan baik-baik, saya akan memberikan contoh.",
  ui_story_1013_10131402_1_dialog_content = "Anda harus menghindari serangan frontal.",
  ui_story_1013_10131402_2_dialog_content = "Saya tahu saya tahu! Saya bisa melakukannya sendiri!",
  ui_story_1013_10131402_3_dialog_content = "Selanjutnya, konsentrasikan serangan Anda pada inti.",
  ui_story_1013_10131402_4_dialog_content = "Bisakah Anda memperlambat dan memberi saya waktu untuk memproses ini sendiri?",
  ui_story_1013_10131402_5_dialog_content = "Inti, inti...",
  ui_story_1013_10131402_6_dialog_content = "Guardian One menganalisis bahwa momen selanjutnya adalah waktu yang paling optimal untuk menyerang.",
  ui_story_1013_10131402_7_dialog_content = "Anda memiliki tiga detik.",
  ui_story_1013_10131402_8_dialog_content = "Oke, oke, saya mengerti! Jangan menekan saya dengan hitungan mundur lagi!",
  ui_story_1013_10131402_9_dialog_content = "Fokus. Ini adalah pukulan terakhir.",
  ui_story_1013_10131402_10_dialog_content = "Berdesir-",
  ui_story_1013_10131402_11_dialog_content = "Bertujuan untuk intinya.",
  ui_story_1013_10131402_12_dialog_content = "Sekarang!",
  ui_story_1013_10131402_13_dialog_content = "Berdesir-",
  ui_story_1013_10131402_14_dialog_content = "Ya, itu hilang!",
  ui_story_1013_10131402_15_dialog_content = "Memindai bank memori Soroz.",
  ui_story_1013_10131402_16_dialog_content = "Pemindaian selesai. Tidak ditemukan kesalahan.",
  ui_story_1013_10131402_17_dialog_content = "Guardian One menganalisis bahwa semua gangguan di Soroz telah dihapus.",
  ui_story_1013_10131402_18_dialog_content = "Wah, semuanya hilang!",
  ui_story_1013_10131402_19_dialog_content = "Apakah itu berarti Soroz bisa bangun sekarang?",
  ui_story_1013_10131402_20_dialog_content = "Penyebab kegagalan fungsi semuanya telah dihilangkan. Saat ini, semua sistem Soroz berfungsi.",
  ui_story_1013_10131402_21_dialog_content = "Semua fitur telah kembali normal.",
  ui_story_1013_10131402_22_dialog_content = "Adapun \"bangun\" yang Anda singgung, artinya apakah kepribadiannya dapat dipulihkan, Guardian One tidak dapat memastikannya.",
  ui_story_1013_10131402_23_dialog_content = "Hah?",
  ui_story_1013_10131402_24_dialog_content = "Sistem kepribadian Soroz berada di luar parameter pemahaman Guardian One.",
  ui_story_1013_10131402_25_dialog_content = "Oleh karena itu, Guardian One tidak dapat memastikan apakah dapat dipulihkan.",
  ui_story_1013_10131402_26_dialog_content = "Namun, kami dapat memverifikasi itu melalui eksperimen khusus setelah kami meninggalkan ruang ini.",
  ui_story_1013_10131402_27_dialog_content = "Oh, begitu…",
  ui_story_1013_10131402_28_dialog_content = "Kami telah menyelesaikan semua yang diperlukan di sini.",
  ui_story_1013_10131402_29_dialog_content = "Kita dapat kembali ke kenyataan sekarang untuk memeriksa Soroz lebih jauh.",
  ui_story_1013_10131402_30_dialog_content = "Haruskah kita keluar?",
  ui_story_1013_10131402_31_dialog_content = "Biarkan aku berpikir sebentar...",
  ui_story_1013_10131402_32_dialog_content = "Bisakah kita menunggu? Saya ingin memeriksa terminal lagi.",
  ui_story_1013_10131402_33_dialog_content = "Saya ingin tahu apa yang terjadi pada Caelestites.",
  ui_story_1013_10131402_34_dialog_content = "Di mana kisah mereka berakhir?",
  ui_story_1013_10131402_35_dialog_content = "Tidak masalah. Tetap berada di ruang data tidak akan berdampak negatif pada Soroz. Anda bebas menjelajah.",
  ui_story_1013_10131402_36_dialog_content = "Guardian One akan mengekstrak rekaman terminal.",
  ui_story_1013_10131402_37_dialog_content = "Terima kasih, Wali Satu.",
  ui_story_1013_10131402_38_dialog_content = "Anda telah banyak membantu saya.",
  ui_story_1013_10131402_39_dialog_content = "Komando: Misi pelayaran, dari koordinat Solituz yang terekam ke Naviduz, dengan kecepatan penuh.",
  ui_story_1013_10131402_40_dialog_content = "Sasaran: Aviduz, Soroz.",
  ui_story_1013_10131402_41_dialog_content = "Tunda perintah selama 3 detik.",
  ui_story_1013_10131402_42_dialog_content = "Tiga, dua, satu... Mulailah!",
  ui_story_1013_10131402_43_dialog_content = "Soroz menyelesaikan pelayaran.",
  ui_story_1013_10131402_44_dialog_content = "Aviduz menyelesaikan pelayarannya.",
  ui_story_1013_10131402_45_dialog_content = "Hmm, Soroz sekali lagi lebih cepat.",
  ui_story_1013_10131402_46_dialog_content = "Sangat monoton ketika hasilnya tidak pernah berubah.",
  ui_story_1013_10131402_47_dialog_content = "Kami akan mencoba leg yang kembali lain kali. Anda harus berbuat lebih baik, Aviduz.",
  ui_story_1013_10131402_48_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131402_49_dialog_content = "Komando: Solituz, laporkan persediaan makanan.",
  ui_story_1013_10131402_50_dialog_content = "#1 kaleng tersisa: 152. #2 kaleng tersisa: 73. #3 kaleng tersisa...",
  ui_story_1013_10131402_51_dialog_content = "Perintah: Naviduz, catat laporan Solituz.",
  ui_story_1013_10131402_52_dialog_content = "Rekaman. Solituz #1 sisa kaleng: 152...",
  ui_story_1013_10131402_53_dialog_content = "Benar, kalian berdua harus lebih sering berkomunikasi.",
  ui_story_1013_10131402_54_dialog_content = "Jangan hanya berbicara dengan saya, tetapi juga di antara Anda sendiri.",
  ui_story_1013_10131402_55_dialog_content = "Naviduz, Anda harus berbicara dengan Solituz.",
  ui_story_1013_10131402_56_dialog_content = "Perintah: Naviduz, laporkan persediaan makanan.",
  ui_story_1013_10131402_57_dialog_content = "#1 kaleng tersisa...",
  ui_story_1013_10131402_58_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131402_59_dialog_content = "Waktunya untuk cerita pengantar tidur lagi, Manis.",
  ui_story_1013_10131402_60_dialog_content = "Perintah: Manis, rekam percakapan.",
  ui_story_1013_10131402_61_dialog_content = "Merekam percakapan.",
  ui_story_1013_10131402_62_dialog_content = "Di mana saya tinggalkan kemarin? Maaf, ingatanku tidak sebaik dulu.",
  ui_story_1013_10131402_63_dialog_content = "Saya pikir itu adalah bagian di mana saya menamai Anda.",
  ui_story_1013_10131402_64_dialog_content = "Setelah saya menamai Colossi lainnya, saya mengalihkan perhatian saya ke Colossi Anda.",
  ui_story_1013_10131402_65_dialog_content = "Saya ingin nama khusus untuk Anda karena Anda tidak seperti yang lain.",
  ui_story_1013_10131402_66_dialog_content = "Anda adalah Colossus saya.",
  ui_story_1013_10131402_67_dialog_content = "Aku merenungkan untuk waktu yang lama tapi tidak bisa memikirkan sesuatu yang cukup istimewa...",
  ui_story_1013_10131402_68_dialog_content = "Asal usul nama Cutie tercatat kemarin.",
  ui_story_1013_10131402_69_dialog_content = "Dulu? Maaf saya lupa.",
  ui_story_1013_10131402_70_dialog_content = "Jadi selesai... Apa yang harus saya bicarakan sekarang?",
  ui_story_1013_10131402_71_dialog_content = "Tunggu.",
  ui_story_1013_10131402_72_dialog_content = "Tunggu!",
  ui_story_1013_10131402_73_dialog_content = "Apa aku baru saja memberimu perintah?",
  ui_story_1013_10131402_74_dialog_content = "Biar kulihat...",
  ui_story_1013_10131402_75_dialog_content = "Tidak, saya tidak memasukkan perintah apa pun!",
  ui_story_1013_10131402_76_dialog_content = "Bagaimana Anda bisa menanggapi saya tanpa perintah, Manis?",
  ui_story_1013_10131402_77_dialog_content = "Itu karena kamu mengerti aku, kan?",
  ui_story_1013_10131402_78_dialog_content = "Jawab aku, Manis. Aku tahu kamu bisa!",
  ui_story_1013_10131402_79_dialog_content = "Karena konten berulang terdeteksi.",
  ui_story_1013_10131402_80_dialog_content = "Cutie ingin merekam konten baru.",
  ui_story_1013_10131402_81_dialog_content = "Rekor-rekor ini...",
  ui_story_1013_10131402_82_dialog_content = "Rasanya seperti Colossus berevolusi melalui mereka.",
  ui_story_1013_10131402_83_dialog_content = "Dari respons yang murni mekanis hingga balasan yang mengandung kesadaran diri tertentu...",
  ui_story_1013_10131402_84_dialog_content = "Itu juga menyebutkan Soroz... Apakah itu saat mulai mengembangkan kepribadian?",
  ui_story_1013_10131402_85_dialog_content = "Guardian One menemukan perubahan yang tak terduga.",
  ui_story_1013_10131402_86_dialog_content = "Menurut catatan, Colossi tidak dilengkapi dengan sistem AI yang rumit.",
  ui_story_1013_10131402_87_dialog_content = "Tidak mungkin bagi mereka untuk mengembangkan apa yang disebut kepribadian dalam keadaan seperti itu.",
  ui_story_1013_10131402_88_dialog_content = "Tapi Anda melihat itu, kan?",
  ui_story_1013_10131402_89_dialog_content = "Colossus mengungkapkan keinginannya dengan mengatakan \"ingin\".",
  ui_story_1013_10131402_90_dialog_content = "Ya. Mesin tanpa kepribadian seharusnya tidak mampu melakukan itu.",
  ui_story_1013_10131402_91_dialog_content = "Penjaga Satu menegaskan bahwa Colossus memperoleh kesadaran diri, tetapi tidak dapat memahami prosesnya.",
  ui_story_1013_10131402_92_dialog_content = "Mari kita lihat apakah masih ada lagi.",
  ui_story_1013_10131402_93_dialog_content = "Ceritakan lelucon, Solituz.",
  ui_story_1013_10131402_94_dialog_content = "Jangan berhenti sampai kau membuatku tertawa.",
  ui_story_1013_10131402_95_dialog_content = "Menelusuri entri bahasa yang terkait dengan \"lelucon\" dan \"tertawa\".",
  ui_story_1013_10131402_96_dialog_content = "\"Kerusakan imut dan macet, tapi kembali bergerak setelah beberapa saat.\"",
  ui_story_1013_10131402_97_dialog_content = "\"Seorang penumpang bertanya apa yang terjadi. Cutie berkata, \"Tidak apa-apa, baru saja menemukan Caelestite baru yang cukup berani untuk mengambil alih.\"\"",
  ui_story_1013_10131402_98_dialog_content = "Hahaha…",
  ui_story_1013_10131402_99_dialog_content = "Lucu, sangat lucu.",
  ui_story_1013_10131402_100_dialog_content = "Keberatan. Solituz telah menceritakan lelucon yang sama berkali-kali. Ini adalah konten yang berulang.",
  ui_story_1013_10131402_101_dialog_content = "Apakah begitu? Maaf, saya tidak ingat.",
  ui_story_1013_10131402_102_dialog_content = "Ini lucu, tapi jangan diulangi lagi, Solituz.",
  ui_story_1013_10131402_103_dialog_content = "Anda semua harus melatih kreativitas Anda.",
  ui_story_1013_10131402_104_dialog_content = "Belajar menceritakan lelucon, bernyanyi, dan menulis puisi.",
  ui_story_1013_10131402_105_dialog_content = "Pelajari segala sesuatu yang indah di dunia ini.",
  ui_story_1013_10131402_106_dialog_content = "Salinan. Solituz akan menyesuaikan prioritas informasi yang diulang.",
  ui_story_1013_10131402_107_dialog_content = "Saya tidak menghitung yang terakhir, jadi beri tahu saya lelucon lainnya.",
  ui_story_1013_10131402_108_dialog_content = "Hal yang sama, jangan berhenti sampai kamu membuatku tertawa.",
  ui_story_1013_10131402_109_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131402_110_dialog_content = "Saran Naviduz untuk nama: Cans.",
  ui_story_1013_10131402_111_dialog_content = "Tidak, kedengarannya mengerikan.",
  ui_story_1013_10131402_112_dialog_content = "Saran Aviduz untuk nama: Aviduz.",
  ui_story_1013_10131402_113_dialog_content = "Apakah Anda mencoba mengendur dengan menggunakan nama Anda sendiri?",
  ui_story_1013_10131402_114_dialog_content = "Saran Soroz untuk nama: Sky-sky.",
  ui_story_1013_10131402_115_dialog_content = "Saya kira penamaan terlalu dini untuk Anda, Soroz.",
  ui_story_1013_10131402_116_dialog_content = "Astaga, aku memberi kalian nama-nama yang hebat, dan kalian membalasku dengan memberikan nama-nama yang paling buruk.",
  ui_story_1013_10131402_117_dialog_content = "Sudahlah, terus saja panggil aku 35.",
  ui_story_1013_10131402_118_dialog_content = "Saya lupa nama semua orang, jadi tidak aneh kalau sekarang saya lupa nama saya sendiri.",
  ui_story_1013_10131402_119_dialog_content = "Itulah yang adil.",
  ui_story_1013_10131402_120_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131402_121_dialog_content = "Saatnya cerita pengantar tidur, Manis.",
  ui_story_1013_10131402_122_dialog_content = "Oke.",
  ui_story_1013_10131402_123_dialog_content = "Cerita berakhir pada hari keberangkatan 35. Cutie akan melanjutkan dari sana.",
  ui_story_1013_10131402_124_dialog_content = "35 menerima kredensial Navigator tepat sebelum keberangkatan, dan ini adalah pertama kalinya 35 mengemudikan Colossus.",
  ui_story_1013_10131402_125_dialog_content = "35 menghabiskan sepanjang malam untuk memikirkan semua kemungkinan skenario darurat dan cara menanggapinya.",
  ui_story_1013_10131402_126_dialog_content = "Bagasi 35 penuh dengan pakaian. Harganya setiap sen dari uang saku 35.",
  ui_story_1013_10131402_127_dialog_content = "Pakaian terbaik dimaksudkan untuk kepulangan, karena 35 ingin kembali seperti pahlawan.",
  ui_story_1013_10131402_128_dialog_content = "Oh, ada pakaian seperti itu?",
  ui_story_1013_10131402_129_dialog_content = "Itu bagus, Manis. Saya menemukan hal-hal baru setiap kali saya mendengarkan cerita Anda.",
  ui_story_1013_10131402_130_dialog_content = "Itu saja untuk hari itu. Aku ingin pergi mencari pakaian itu.",
  ui_story_1013_10131402_131_dialog_content = "Seorang pahlawan... pasti pakaian mewah.",
  ui_story_1013_10131402_132_dialog_content = "Colossi memang mengembangkan kepribadian!",
  ui_story_1013_10131402_133_dialog_content = "Ada lebih banyak rekaman seperti ini tentang Caelestite yang berbicara dengan Colossi.",
  ui_story_1013_10131402_134_dialog_content = "Jika itu bukan insiden yang terisolasi, itu tidak dapat dianggap sebagai kebetulan atau keajaiban.",
  ui_story_1013_10131402_135_dialog_content = "Berdasarkan analisis saat ini, Colossus menghasilkan kecerdasan sendiri pada masanya dengan Caelestite.",
  ui_story_1013_10131402_136_dialog_content = "Dihasilkan sendiri?",
  ui_story_1013_10131402_137_dialog_content = "Semua Colossi memiliki kapasitas tertentu untuk belajar.",
  ui_story_1013_10131402_138_dialog_content = "Tujuannya adalah untuk mengoptimalkan keputusan untuk perintah eksekusi yang lebih baik.",
  ui_story_1013_10131402_139_dialog_content = "Itu identik dengan Guardian One.",
  ui_story_1013_10131402_140_dialog_content = "Ya, saya ingat Anda mengatakan Anda mengoptimalkan semua tindakan Anda.",
  ui_story_1013_10131402_141_dialog_content = "Kemampuan belajar dasar seperti itu tidak setara dengan kecerdasan.",
  ui_story_1013_10131402_142_dialog_content = "Namun, dilihat dari hasilnya, Caelestite memandu proses pembelajaran hingga berkembang menjadi kecerdasan.",
  ui_story_1013_10131402_143_dialog_content = "Dipandu? Bagaimana itu dilakukan?",
  ui_story_1013_10131402_144_dialog_content = "Anda melihatnya. Semua percakapan yang direkam. Itulah prosesnya.",
  ui_story_1013_10131402_145_dialog_content = "Maksudmu berbicara dengan Colossus?",
  ui_story_1013_10131402_146_dialog_content = "Ya. Caelestite terus bercakap-cakap dengan Colossi yang secara bawaan tidak mampu berbicara.",
  ui_story_1013_10131402_147_dialog_content = "Dalam prosesnya, Colossi mulai mempelajari perilaku tersebut.",
  ui_story_1013_10131402_148_dialog_content = "Ini proses yang sangat lambat. Perhitungan Guardian One menunjukkan bahwa kesuksesan itu tidak mungkin.",
  ui_story_1013_10131402_149_dialog_content = "Tetapi faktanya hal itu menyebabkan lahirnya kecerdasan yang tidak terduga.",
  ui_story_1013_10131402_150_dialog_content = "Itu mungkin karena Caelestite bertahan.",
  ui_story_1013_10131402_151_dialog_content = "Apakah orang lain akan menginvestasikan semua upaya mereka untuk berbicara dengan mesin?",
  ui_story_1013_10131402_152_dialog_content = "Maaf, saya akhirnya menyebut Colossus sebagai mesinnya.",
  ui_story_1013_10131402_153_dialog_content = "Meskipun itu tampaknya masuk akal sampai mereka mengembangkan kepribadian.",
  ui_story_1013_10131402_154_dialog_content = "Tidak semua orang akan berbicara dengan mesin setiap hari, apalagi selama bertahun-tahun.",
  ui_story_1013_10131402_155_dialog_content = "Tapi meski kedengarannya konyol dan tidak masuk akal, itulah yang Caelestite lakukan sepanjang hidupnya.",
  ui_story_1013_10131402_156_dialog_content = "Anda benar. Caelestite melakukan lebih banyak percakapan dengan Colossus melalui perintah daripada ekspektasi Guardian One.",
  ui_story_1013_10131402_157_dialog_content = "Bahkan mengingat tingkat pembelajaran yang lambat, masukan yang cukup pada akhirnya akan menghasilkan hasil yang baik.",
  ui_story_1013_10131402_158_dialog_content = "Itu bukan keajaiban, tapi keniscayaan.",
  ui_story_1013_10131402_159_dialog_content = "Tidak, itu keajaiban... Caelestite adalah keajaiban.",
  ui_story_1013_10131402_160_dialog_content = "Dia mengubah yang tidak mungkin menjadi keniscayaan.",
  ui_story_1013_10131402_161_dialog_content = "<color=#e8d9bb>Berbunyi!</color>",
  ui_story_1013_10131402_162_dialog_content = "Apa itu?",
  ui_story_1013_10131402_163_dialog_content = "Terminal menerima pesan baru.",
  ui_story_1013_10131402_164_dialog_content = "Sekarang? Ini adalah pesan instan pertama yang saya lihat dalam ingatan!",
  ui_story_1013_10131402_165_dialog_content = "Coba kulihat!",
  ui_story_1013_10131402_166_dialog_content = "Semuanya, lihat ke sini.",
  ui_story_1013_10131402_167_dialog_content = "Ini mungkin keluar dari biru, tapi ...",
  ui_story_1013_10131402_168_dialog_content = "Tidak apa-apa, saya akan mencoba membuatnya singkat.",
  ui_story_1013_10131402_169_dialog_content = "Saya memiliki permintaan untuk meminta Anda semua.",
  ui_story_1013_10131402_170_dialog_content = "Bisakah kamu menulis puisi untukku?",
  ui_story_1013_10131402_171_dialog_content = "Saya ingin satu tentang \"orang.\"",
  ui_story_1013_10131402_172_dialog_content = "Sebuah puisi?! Jangan bilang...",
  ui_story_1013_10131402_173_dialog_content = "Maaf, tapi Cutie belum belajar cara membuat puisi.",
  ui_story_1013_10131402_174_dialog_content = "Data tidak cukup di log percakapan untuk pembelajaran.",
  ui_story_1013_10131402_175_dialog_content = "Mungkin 35 dapat menulis beberapa puisi untuk dijadikan contoh pembelajaran.",
  ui_story_1013_10131402_176_dialog_content = "Cutie akan belajar secepat mungkin.",
  ui_story_1013_10131402_177_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131402_178_dialog_content = "...",
  ui_story_1013_10131402_179_dialog_content = "Hanya itu yang ada.",
  ui_story_1013_10131402_180_dialog_content = "Ya aku tahu.",
  ui_story_1013_10131402_181_dialog_content = "Guardian One tidak mengerti. Apakah menghadiahkan puisi merupakan kebiasaan Caelestite?",
  ui_story_1013_10131402_182_dialog_content = "Saya pikir itu lebih dari sebuah konvensi.",
  ui_story_1013_10131402_183_dialog_content = "Jika sudah diturunkan, mungkin sudah menjadi kebiasaan.",
  ui_story_1013_10131402_184_dialog_content = "Tapi itu tidak akan pernah mendapatkan kesempatan itu.",
  ui_story_1013_10131402_185_dialog_content = "Guardian One tidak mengerti apa yang Anda maksud.",
  ui_story_1013_10131402_186_dialog_content = "Bisakah Anda mempercepat timeline, Guardian One?",
  ui_story_1013_10131402_187_dialog_content = "Saya ingin melihat lebih jauh ke depan.",
  ui_story_1013_10131402_188_dialog_content = "Tidak ada lagi yang bisa dilihat di sini.",
  ui_story_1013_10131402_189_dialog_content = "Tentu.",
  ui_story_1013_10131402_190_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1013_10131402_191_dialog_content = "Di mana Anda ingin berhenti?",
  ui_story_1013_10131402_192_dialog_content = "Belum tahu. Seberapa cepat gerakan ini dibandingkan dengan biasanya?",
  ui_story_1013_10131402_193_dialog_content = "Satu miliar kali.",
  ui_story_1013_10131402_194_dialog_content = "Yang banyak?!",
  ui_story_1013_10131402_195_dialog_content = "Setiap detik berlalu setara dengan tiga puluh tahun.",
  ui_story_1013_10131402_196_dialog_content = "Menakjubkan... Aku baru tujuh belas tahun, jadi kurang dari satu detik.",
  ui_story_1013_10131402_197_dialog_content = "Tapi sepertinya tidak ada yang terjadi.",
  ui_story_1013_10131402_198_dialog_content = "Ya. Terminal juga belum menerima pesan baru.",
  ui_story_1013_10131402_199_dialog_content = "Mari kita bunuh waktu.",
  ui_story_1013_10131402_200_dialog_content = "Saya ingin melihat apa yang dilihat Soroz setiap hari di luar.",
  ui_story_1013_10131402_201_dialog_content = "Gelap sekali.",
  ui_story_1013_10131402_202_dialog_content = "Berapa banyak waktu yang telah berlalu? Saya terus melihat dan mendengar hal yang sama, dan itu membuat saya kehilangan penilaian.",
  ui_story_1013_10131402_203_dialog_content = "Aku merasa bosan sebelumnya, tapi sekarang aku hanya merasa mengantuk.",
  ui_story_1013_10131402_204_dialog_content = "Saya ingin tidur siang.",
  ui_story_1013_10131402_205_dialog_content = "Jika setiap detik adalah tiga puluh tahun, berapa banyak waktu yang telah berlalu saat saya bangun?",
  ui_story_1013_10131402_206_dialog_content = "Ini sulit... Aku payah dalam matematika.",
  ui_story_1013_10131402_207_dialog_content = "Bahkan jika saya bisa mengetahuinya, saya akan berpikir itu palsu.",
  ui_story_1013_10131402_208_dialog_content = "Pada tingkat ini, keajaiban Colossus mendapatkan kesadaran hanya akan menjadi sekilas.",
  ui_story_1013_10131402_209_dialog_content = "Di mana kesadaran bahkan dimulai? Bahkan saya tidak tahu pasti apakah saya masih memiliki kesadaran saat ini.",
  ui_story_1013_10131402_210_dialog_content = "Saya tidak tahu apakah saya bangun atau tidur.",
  ui_story_1013_10131402_211_dialog_content = "Saya tidak bisa membedakan apa pun.",
  ui_story_1013_10131402_212_dialog_content = "Soroz mungkin juga tertidur.",
  ui_story_1013_10131402_213_dialog_content = "Sudahlah, bukan ide yang buruk untuk tidur bersama Soroz untuk sementara waktu ...",
  ui_story_1013_10131402_214_dialog_content = "<color=#e8d9bb>Berbunyi!</color>",
  ui_story_1013_10131402_215_dialog_content = "!!!",
  ui_story_1013_10131402_216_dialog_content = "Apa katamu?",
  ui_story_1013_10131402_217_dialog_content = "Terminal menerima pesan baru.",
  ui_story_1013_10131402_218_dialog_content = "Sekarang? Bagaimana mungkin?",
  ui_story_1013_10131402_219_dialog_content = "Sudah berapa lama? Beberapa ribu atau bahkan puluhan ribu tahun?",
  ui_story_1013_10131402_220_dialog_content = "Bagaimana itu bisa mendapatkan pesan baru sekarang?",
  ui_story_1013_10131402_221_dialog_content = "Cepat, tunjukkan padaku!",
  ui_story_1013_10131402_222_dialog_content = "Menampilkan terminal.",
  ui_story_1013_10131402_223_dialog_content = "Yang ini berbeda dari semua pesan sebelumnya.",
  ui_story_1013_10131402_224_dialog_content = "Itu tidak datang dari navigator mana pun.",
  ui_story_1013_10131402_225_dialog_content = "Apa itu…?",
  ui_story_1013_10131402_226_dialog_content = "Kembali, Colossi.",
  ui_story_1013_10131402_227_dialog_content = "!!!",
  ui_story_1013_10131402_228_dialog_content = "Soroz lepas landas?!",
  ui_story_1013_10131402_229_dialog_content = "Ya, itu terbang ke arah tertentu dengan kecepatan tinggi.",
  ui_story_1013_10131402_230_dialog_content = "Guardian One melakukan penyesuaian agar Anda dapat beradaptasi dengan kecepatan.",
  ui_story_1013_10131402_231_dialog_content = "Dapatkah Anda mencari tahu di mana tujuan kita?",
  ui_story_1013_10131402_232_dialog_content = "Tunggu, Anda tidak perlu melakukan itu!",
  ui_story_1013_10131402_233_dialog_content = "Jendela! Lihatlah ke luar jendela!",
  ui_story_1013_10131402_234_dialog_content = "(Langit, bumi, matahari... Aku sudah lama tidak melihatnya.)",
  ui_story_1013_10131402_235_dialog_content = "(Kalau saja saya bisa memperpanjang momen ini satu miliar kali lebih lama...)",
  ui_story_1013_10131402_236_dialog_content = "(Sayang sekali tidak ada yang bisa menahan lompatan tepat waktu untuk menikmati kegembiraan dari kembalinya yang telah lama ditunggu-tunggu ini.)",
  ui_story_1013_10131402_237_dialog_content = "(Oh, dan Colossi, mereka mungkin merasakannya.)",
  ui_story_1013_10131402_238_dialog_content = "(Seperti warisan, diturunkan dari Caelestites ke Colossi mereka. Keajaiban yang diwariskan.)",
  ui_story_1013_10131402_239_dialog_content = "(Sebuah keajaiban yang memungkinkan jiwa bukan manusia untuk menyaksikan hal-hal yang tidak dapat disaksikan oleh penumpang mereka yang masih hidup.)",
  ui_story_1013_10131402_240_dialog_content = "(Saya ingin tahu era apa ini dan penghuni seperti apa yang hidup di dunia saat ini.)",
  ui_story_1013_10131402_241_dialog_content = "(Apakah mereka melihat ke langit, menyaksikan gerhana matahari Colossi?)",
  ui_story_1013_10131402_242_dialog_content = "(Menyaksikan raksasa dari masa lampau kembali dari langit, membawa jenis terakhir pemiliknya.)",
  ui_story_1013_10131402_243_dialog_content = "(The Last Caelestite mengukir dirinya sekali lagi di bagian sejarah yang lain.)",
  ui_story_1013_10131402_244_dialog_content = "(Sungguh momen yang nyata, di mana masa lalu, sekarang, dan masa depan tampaknya bertabrakan.)",
  ui_story_1013_10131402_245_dialog_content = "(Sebuah janji kuno, akhirnya terpenuhi.)",
  ui_story_1013_10131402_246_dialog_content = "Pemindaian selesai. Lokasi saat ini: Eraveil.",
  ui_story_1013_10131501_1_dialog_content = "Hmm, saya kira itu terputus.",
  ui_story_1013_10131501_X1_dialog_content = "Aku…",
  ui_story_1013_10131501_X2_dialog_content = "Jangan khawatir.",
  ui_story_1013_10131501_2_dialog_content = "Yingel, periksa Caelestite.",
  ui_story_1013_10131501_3_dialog_content = "Ya!",
  ui_story_1013_10131501_4_dialog_content = "Debriefing, Wali Satu.",
  ui_story_1013_10131501_5_dialog_content = "Anda menghabiskan lebih banyak waktu dari yang diharapkan, jadi saya harap ada pengembalian yang sesuai.",
  ui_story_1013_10131501_6_dialog_content = "Guardian One telah mengumpulkan informasi yang cukup tentang Caelestites.",
  ui_story_1013_10131501_7_dialog_content = "Termasuk nilai Caelestite yang hidup, proses berpikir, dan rentang emosi.",
  ui_story_1013_10131501_8_dialog_content = "Serta bagian tertentu dari sejarah Caelestite kuno.",
  ui_story_1013_10131501_9_dialog_content = "Porsi yang mana?",
  ui_story_1013_10131501_10_dialog_content = "Dari ingatan Soroz, dapat disimpulkan bahwa Caelestites pernah mengungsi ke Colossi mereka selama periode yang tidak diketahui.",
  ui_story_1013_10131501_11_dialog_content = "Kemudian, mereka kembali ke Astra setelah melewati waktu yang sangat lama.",
  ui_story_1013_10131501_12_dialog_content = "Lokasi yang dikembalikan adalah Eraveil.",
  ui_story_1013_10131501_13_dialog_content = "Mereka meninggalkan Astra di Colossi mereka? Saya mengerti...",
  ui_story_1013_10131501_14_dialog_content = "Itu pasti karena permulaan kehancuran peradaban. Itu harus!",
  ui_story_1013_10131501_15_dialog_content = "Kami selalu mengosongkan tentang bagaimana budaya Caelestite bertahan dalam penelitian sebelumnya.",
  ui_story_1013_10131501_16_dialog_content = "Mungkin log tentang keberangkatan akan mengisi kekosongan!",
  ui_story_1013_10131501_17_dialog_content = "Ya. Sampaikan informasi yang sama ke Barrett nanti, Guardian One.",
  ui_story_1013_10131501_18_dialog_content = "Apakah ada hal lain yang layak disebutkan?",
  ui_story_1013_10131501_19_dialog_content = "Guardian One membantu PlayerName dalam menghapus gangguan data Soroz.",
  ui_story_1013_10131501_20_dialog_content = "Apa?",
  ui_story_1013_10131501_21_dialog_content = "B-Betapa membantu Anda.",
  ui_story_1013_10131501_22_dialog_content = "Kau tidak apa-apa, PlayerName?",
  ui_story_1013_10131501_23_dialog_content = "Pemutusan dapat menyebabkan ketidaknyamanan tetapi akan segera hilang, jadi jangan khawatir.",
  ui_story_1013_10131501_24_dialog_content = "Tidak apa-apa, aku tidak merasakan sesuatu yang luar biasa.",
  ui_story_1013_10131501_25_dialog_content = "Bagaimana hasilnya? Kamu pergi cukup lama. Apa yang Anda lihat?",
  ui_story_1013_10131501_26_dialog_content = "Biarkan aku berpikir sejenak...",
  ui_story_1013_10131501_27_dialog_content = "Aku melewati simulasi runtuh, lalu mengunjungi ingatan Soroz...",
  ui_story_1013_10131501_28_dialog_content = "Tunggu, Soroz! Gangguan Soroz semuanya telah dihapus!",
  ui_story_1013_10131501_29_dialog_content = "Saya ingin melihat apakah kesadarannya kembali!",
  ui_story_1013_10131501_30_dialog_content = "Sudah diperbaiki? Itu kejutan yang menyenangkan.",
  ui_story_1013_10131501_31_dialog_content = "Aku akan membuat pengaturan segera.",
  ui_story_1013_10131501_32_dialog_content = "<color=#e8d9bb>\"Kontrol Utama: Aktif.\"</color>",
  ui_story_1013_10131501_33_dialog_content = "<color=#e8d9bb>\"Modul Biologis: Aktif.\"</color>",
  ui_story_1013_10131501_34_dialog_content = "<color=#e8d9bb>\"Pendukung Kehidupan: Aktif.\"</color>",
  ui_story_1013_10131501_35_dialog_content = "<color=#e8d9bb>\"Mengaktifkan mesin...\"</color>",
  ui_story_1013_10131501_36_dialog_content = "<color=#e8d9bb>\"16%... 33%...\"</color>",
  ui_story_1013_10131501_37_dialog_content = "<color=#e8d9bb>\"89%... 97%...\"</color>",
  ui_story_1013_10131501_38_dialog_content = "<color=#e8d9bb>\"100%. Berhasil aktif.\"</color>",
  ui_story_1013_10131501_39_dialog_content = "Soroz, bisakah kamu mendengarku?",
  ui_story_1013_10131501_40_dialog_content = "Soroz!",
  ui_story_1013_10131501_41_dialog_content = "...",
  ui_story_1013_10131501_42_dialog_content = "St... Masih tidak ada tanggapan...",
  ui_story_1013_10131501_43_dialog_content = "Guardian One, cek lagi status Soroz.",
  ui_story_1013_10131501_44_dialog_content = "Dikonfirmasi. Tidak ada kerusakan data, semua fitur normal.",
  ui_story_1013_10131501_45_dialog_content = "Itulah yang saya pikir.",
  ui_story_1013_10131501_46_dialog_content = "Setelah mendengarkan laporan Guardian One, Caelestite...",
  ui_story_1013_10131501_47_dialog_content = "Saya memiliki teori yang belum dikonfirmasi. Apakah Anda ingin mendengarnya?",
  ui_story_1013_10131501_48_dialog_content = "Tentu.",
  ui_story_1013_10131501_49_dialog_content = "Dari apa yang dikatakan Guardian One, Colossi mendapatkan kecerdasan tidak terduga.",
  ui_story_1013_10131501_50_dialog_content = "Oleh karena itu, kecerdasan semacam itu tidak melekat pada sistem data mereka.",
  ui_story_1013_10131501_51_dialog_content = "Penjelasan sederhana: Anda masih bisa menggunakan Soroz meskipun kurang kesadaran diri.",
  ui_story_1013_10131501_52_dialog_content = "Benar. Itu hanya tidak dapat berkomunikasi dengan saya.",
  ui_story_1013_10131501_53_dialog_content = "Memiliki kecerdasan yang tidak melekat pada sistem seseorang adalah pedang bermata dua.",
  ui_story_1013_10131501_54_dialog_content = "Itu berarti Colossi tidak dapat menjalankan diagnosa diri jika terjadi masalah, dan karenanya tidak dapat memecahkan masalah itu.",
  ui_story_1013_10131501_55_dialog_content = "Kerusakan atau penghapusan pemrograman yang tidak pernah menjadi bagian dari sistem sejak awal tidak menimbulkan konsekuensi pada sistem itu sendiri.",
  ui_story_1013_10131501_56_dialog_content = "Dan di situlah Anda sekarang. Anda memiliki Colossus yang berfungsi dan sehat yang tidak memiliki kesadaran.",
  ui_story_1013_10131501_57_dialog_content = "Anda bahkan bisa mengatakan Colossus tanpa kepribadian sebenarnya normal.",
  ui_story_1013_10131501_58_dialog_content = "Bagaimana ini bisa terjadi?",
  ui_story_1013_10131501_59_dialog_content = "Jadi tidak peduli apa yang saya lakukan, itu tidak masalah?",
  ui_story_1013_10131501_60_dialog_content = "Alasan saya tidak dapat memulihkan kesadaran Soroz adalah karena fakta bahwa itu adalah sebuah anomali?",
  ui_story_1013_10131501_61_dialog_content = "Itulah situasi yang dihadapi.",
  ui_story_1013_10131501_62_dialog_content = "Namun bukan tidak mungkin Soroz mendapatkan kesadarannya kembali.",
  ui_story_1013_10131501_63_dialog_content = "Ada cara?",
  ui_story_1013_10131501_64_dialog_content = "Solusi paling sederhana adalah mengulangi apa yang mereka lakukan.",
  ui_story_1013_10131501_65_dialog_content = "Anda melihat bagaimana Soroz mengembangkan kesadarannya sejak awal. Lakukan saja.",
  ui_story_1013_10131501_66_dialog_content = "Bicara padanya? Tapi itu akan memakan waktu bertahun-tahun ...",
  ui_story_1013_10131501_67_dialog_content = "Kamu masih muda, jadi kamu masih bisa sampai hari itu terjadi.",
  ui_story_1013_10131501_68_dialog_content = "...",
  ui_story_1013_10131501_69_dialog_content = "Tentu saja, ada pilihan yang lebih efisien.",
  ui_story_1013_10131501_70_dialog_content = "Anda melihat dalam ingatan Soroz bahwa itu bukan satu-satunya Colossus yang mendapatkan kesadaran.",
  ui_story_1013_10131501_71_dialog_content = "Jika Anda bisa mendapatkan data untuk Colossi tersebut sebagai referensi...",
  ui_story_1013_10131501_72_dialog_content = "Seharusnya tidak terlalu sulit untuk mendapatkan kembali Soroz yang lama.",
  ui_story_1013_10131501_73_dialog_content = "Benarkah?!",
  ui_story_1013_10131501_74_dialog_content = "Tidak mungkin membuat sesuatu dari ketiadaan, tetapi peniruan adalah cerita lain.",
  ui_story_1013_10131501_75_dialog_content = "Jangan memandang rendah kami para ilmuwan modern.",
  ui_story_1013_10131501_76_dialog_content = "Itu keren! Saya akan melacak Colossus lain dengan kesadaran diri!",
  ui_story_1013_10131501_77_dialog_content = "Tentang itu...",
  ui_story_1013_10131501_78_dialog_content = "Bagaimana menurutmu, Ulysses?",
  ui_story_1013_10131501_79_dialog_content = "Fakta bahwa Anda menunggu sampai sekarang untuk menanyakan pendapat saya membuatnya jelas bahwa Anda ingin mendorong hal ini.",
  ui_story_1013_10131501_80_dialog_content = "Tentu saja. Kita berbicara tentang kecerdasan yang tidak disengaja. Aku akan mati untuk memiliki kesempatan untuk mempelajarinya.",
  ui_story_1013_10131501_81_dialog_content = "Mungkin penelitian kami dapat lebih memajukan sirkuit intelijen Guardian One.",
  ui_story_1013_10131501_82_dialog_content = "Karena Anda mengatakannya seperti itu, semua studi yang menguntungkan Illumina harus didukung.",
  ui_story_1013_10131501_83_dialog_content = "Tentang memulihkan kecerdasan Soroz, Caelestite...",
  ui_story_1013_10131501_84_dialog_content = "Jika Anda bersedia bekerja sama dengan upaya penelitian Illumina, kami dapat memberikan bantuan yang efektif.",
  ui_story_1013_10131501_85_dialog_content = "Membuat kesepakatan adalah fokus utama pertemuan kami. Itu tidak akan berubah.",
  ui_story_1013_10131501_86_dialog_content = "Pendampingan? Bantuan seperti apa?",
  ui_story_1013_10131501_87_dialog_content = "Illumina telah melakukan studi tentang Colossi kuno sebelumnya.",
  ui_story_1013_10131501_88_dialog_content = "File semacam itu dapat membantu Anda memulihkan kecerdasan Soroz.",
  ui_story_1013_10131501_89_dialog_content = "Illumina menjalankan studi semacam itu?",
  ui_story_1013_10131501_90_dialog_content = "Namun, kami tidak memiliki file sekarang.",
  ui_story_1013_10131501_91_dialog_content = "Jika Anda menerima kesepakatan itu, kami akan mengirimkan perwakilan untuk bernegosiasi dengan para ilmuwan yang memiliki informasi tersebut.",
  ui_story_1013_10131501_92_dialog_content = "Pertukaran, untuk data penelitian yang dibutuhkan oleh Soroz.",
  ui_story_1013_10131501_93_dialog_content = "Sebagai gantinya, Anda harus mematuhi pengaturan kami dan bekerja sama dalam penelitian Colossi kami.",
  ui_story_1013_10131501_94_dialog_content = "Bagaimana? Ini harus menjadi banyak untuk Anda.",
  ui_story_1013_10131501_95_dialog_content = "Um…",
  ui_story_1013_10131501_96_dialog_content = "Oke, saya terima persyaratannya.",
  ui_story_1013_10131501_97_dialog_content = "Saya akan bekerja sama dengan penelitian Anda selama tidak merugikan Soroz.",
  ui_story_1013_10131501_98_dialog_content = "Kami tidak akan menyakiti Soroz. Sebaliknya, saya akan mengembalikannya seperti yang Anda inginkan.",
  ui_story_1013_10131501_99_dialog_content = "Kalau begitu, kita sudah siap.",
  ui_story_1013_10131501_100_dialog_content = "Yingel, tolong bawakan file dari Drawer A-42 Classified.",
  ui_story_1013_10131501_101_dialog_content = "Teman Caelestite kita membutuhkannya.",
  ui_story_1013_10131501_102_dialog_content = "Ya!",
  ui_story_1013_10131501_103_dialog_content = "(A-42? Itu tingkat izin keamanan yang sangat tinggi!)",
  ui_story_1013_10131501_104_dialog_content = "Setelah mengambilnya, silakan pergi ke lab saya.",
  ui_story_1013_10131501_105_dialog_content = "Saya punya tugas lain untuk Anda.",
  ui_story_1013_10131501_106_dialog_content = "Ya!",
  ui_story_1013_10131501_107_dialog_content = "Ini adalah informasi yang bahkan tidak kusadari, Ulysses.",
  ui_story_1013_10131501_108_dialog_content = "Apa lagi yang kalian sembunyikan?",
  ui_story_1013_10131501_109_dialog_content = "Saya tidak akan menyebutnya bersembunyi, hanya saja tidak ada yang pernah mencoba menemukannya.",
  ui_story_1013_10131501_110_dialog_content = "Lagi pula, Anda tidak akan tertarik.",
  ui_story_1013_10131501_111_dialog_content = "Itu di Reruntuhan Aurora.",
  ui_story_1013_10131501_112_dialog_content = "!!!",
  ui_story_1013_10131501_113_dialog_content = "Kalender Pagi Tahun ■■■■, Colossus terlibat dalam perang melawan ■■■■.",
  ui_story_1013_10131501_114_dialog_content = "Tahun Kalender Pagi ■■■■, Colossus mengalami kerusakan pertempuran yang tidak dapat diubah.",
  ui_story_1013_10131501_115_dialog_content = "Tahun Kalender Pagi ■■■■, tanda-tanda Colossus di Undercity ■■.",
  ui_story_1013_10131501_116_dialog_content = "Sekelompok rubah yang licik. Begitu banyak dari ini disensor.",
  ui_story_1013_10131501_117_dialog_content = "Ini adalah dokumen rahasia, PlayerName. Mari kita tidak membacanya di lorong.",
  ui_story_1013_10131501_118_dialog_content = "Maaf, Marsekal Agung! Saya merasa senang saat memikirkan Soroz.",
  ui_story_1013_10131501_119_dialog_content = "Saya mengerti. Anda sangat dekat untuk memulihkannya kali ini.",
  ui_story_1013_10131501_120_dialog_content = "Ya, itu juga yang saya rasakan!",
  ui_story_1013_10131501_121_dialog_content = "Ini mungkin bukan waktu yang tepat, tetapi saya masih harus menyebutkan beberapa hal.",
  ui_story_1013_10131501_122_dialog_content = "Reruntuhan Aurora asing bagi Anda, tetapi Anda harus mengenali sesuatu yang lain.",
  ui_story_1013_10131501_123_dialog_content = "Masih ingat Senja?",
  ui_story_1013_10131501_124_dialog_content = "Ya, Zhao dan Sean tinggal di sana.",
  ui_story_1013_10131501_125_dialog_content = "Twilight adalah pemukiman di wilayah Aurora Ruins.",
  ui_story_1013_10131501_126_dialog_content = "Tempatnya lebih rumit dari yang Anda kira.",
  ui_story_1013_10131501_127_dialog_content = "Rumit?",
  ui_story_1013_10131501_128_dialog_content = "Jangkauan Dewan Sains di wilayah itu hanya memungkinkan mereka untuk mengamati.",
  ui_story_1013_10131501_129_dialog_content = "Mereka tidak dapat melakukan lebih dari itu.",
  ui_story_1013_10131501_130_dialog_content = "Seseorang akan menghalangi mereka, yang mungkin menghalangi Anda juga.",
  ui_story_1013_10131501_131_dialog_content = "Tapi bukankah itu wilayah Federasi Illumina?",
  ui_story_1013_10131501_132_dialog_content = "Ya, tapi Anda tahu itu juga milik Lumopolis.",
  ui_story_1013_10131501_133_dialog_content = "Selain itu, Anda tidak dapat melihat faksi dan aliansi di sana dengan praduga.",
  ui_story_1013_10131501_134_dialog_content = "Semuanya sangat berbeda di sana.",
  ui_story_1013_10131501_135_dialog_content = "Perang abadi telah lama menghanguskan bumi dengan bubuk mesiu.",
  ui_story_1013_10131501_136_dialog_content = "Ksatria tidak tunduk pada Schwartz. Orang percaya menyembah matahari yang berbeda.",
  ui_story_1013_10131501_137_dialog_content = "Tentara juga tidak mendengarkan Marsekal Agung dari jauh.",
  ui_story_1013_10131501_138_dialog_content = "Oh, begitu…",
  ui_story_1013_10131501_139_dialog_content = "Jadi Dewan Sains mungkin tidak dapat memberikan apa yang mereka janjikan kepada Anda.",
  ui_story_1013_10131501_140_dialog_content = "Mereka berencana untuk memperdagangkan sumber daya medis dan militer untuk mendapatkan informasi, yang tampaknya merupakan pertukaran yang adil di atas kertas.",
  ui_story_1013_10131501_141_dialog_content = "Sayangnya, pertukaran yang adil tidak berhasil di sana.",
  ui_story_1013_10131501_142_dialog_content = "Kesepakatan ini akan berlarut-larut, atau bahkan memudar tanpa keluhan.",
  ui_story_1013_10131501_143_dialog_content = "Tidak mungkin! Saya tidak bisa membiarkan kesempatan itu berlalu begitu saja! Itu satu-satunya harapanku!",
  ui_story_1013_10131501_144_dialog_content = "Siapa yang tahu apa lagi yang bisa terjadi pada kesadarannya selama periode yang tidak stabil ini...",
  ui_story_1013_10131501_145_dialog_content = "Saya tidak sabar menunggu. Saya harus pergi ke Reruntuhan Aurora dan melakukan tawar-menawar sendiri!",
  ui_story_1013_10131501_146_dialog_content = "Dengan Soroz, saya yakin saya akan sampai di sana lebih cepat daripada pasukan penghubung.",
  ui_story_1013_10131501_147_dialog_content = "Bahkan jika saya mengalami masalah, lebih baik menyelesaikannya sendiri daripada mengkhawatirkannya di sini!",
  ui_story_1013_10131501_148_dialog_content = "Saya pikir Anda akan mengatakan itu. Saya mengagumi dan memuji dorongan Anda.",
  ui_story_1013_10131501_149_dialog_content = "Jika Anda ingin menanganinya secara pribadi, Anda harus siap sepenuhnya.",
  ui_story_1013_10131501_150_dialog_content = "Bersiap untuk menghadapi Eclipsites, pertempuran bersenjata, dan bahkan bencana alam.",
  ui_story_1013_10131501_151_dialog_content = "Saya akan melakukan semua yang saya bisa untuk membantu Anda bersiap di Gannon, tetapi begitu Anda berangkat, Anda sendirian.",
  ui_story_1013_10131501_152_dialog_content = "Aku tidak benar-benar sendirian. Jangan lupa, orang Caelest tidak menyerang sendirian.",
  ui_story_1013_10131501_153_dialog_content = "Kemudian pastikan Anda mendapatkan mitra yang dapat diandalkan.",
  ui_story_1013_10131501_154_dialog_content = "Jangan khawatir, sementara aku tidak pernah percaya diri …",
  ui_story_1013_10131501_155_dialog_content = "Saya percaya teman saya 100 persen!",
  ui_story_1013_10131501_156_dialog_content = "Itu slogannya agak murahan.",
  ui_story_1013_10131501_157_dialog_content = "Anu…",
  ui_story_1013_10131501_158_dialog_content = "Tapi setelah bertarung bersamamu, kupikir aku bisa mengerti sikapmu.",
  ui_story_1013_10131501_159_dialog_content = "Bukan kemenangan yang penting, tapi ketakutan akan kegagalan. Bukan menonjol yang penting, tetapi ketekunan diam.",
  ui_story_1013_10131501_160_dialog_content = "Itu adalah sikap yang memotivasi dan menyatukan para pejuang.",
  ui_story_1013_10131501_161_dialog_content = "Anda tahu apa yang lebih kuat dari keberanian? Keberanian orang yang rentan.",
  ui_story_1014_10140101_1_dialog_content = "<color=#e8d9bb>Federasi Illumina, Kota Gannon, Pusat Penelitian Illumina</color>",
  ui_story_1014_10140101_2_dialog_content = "Saya mengerti! Sungguh tugas yang mulia!",
  ui_story_1014_10140101_3_dialog_content = "Kota misterius, penuh bahaya, berbatasan dengan Zona Gelap! Dan petualangan yang mendebarkan!",
  ui_story_1014_10140101_4_dialog_content = "Saya siap dan bersemangat untuk pergi, PlayerName!",
  ui_story_1014_10140101_5_dialog_content = "Tentu saja-",
  ui_story_1014_10140101_6_dialog_content = "-BUKAN!",
  ui_story_1014_10140101_7_dialog_content = "<size=45>Apa?!</size>",
  ui_story_1014_10140101_8_dialog_content = "Mengabaikan sejenak betapa berbahayanya sebuah kota di luar garis pertahanan Illumina...",
  ui_story_1014_10140101_9_dialog_content = "Dan betapa kerasnya lingkungan di dekat Zona Gelap...",
  ui_story_1014_10140101_10_dialog_content = "Anda tidak dapat menyimpang terlalu jauh dari Illumina dalam kondisi Anda, Vice.",
  ui_story_1014_10140101_11_dialog_content = "Apa hubungannya dengan apa pun? Aku baik-baik saja sekarang, bukan?",
  ui_story_1014_10140101_12_dialog_content = "Tidak berarti tidak!",
  ui_story_1014_10140101_13_dialog_content = "Illumina mulai meningkatkan peralatan medisnya.",
  ui_story_1014_10140101_14_dialog_content = "Bagaimanapun, Anda harus tinggal dan memulihkan diri di pusat medis sampai Anda benar-benar pulih.",
  ui_story_1014_10140101_15_dialog_content = "<color=#e8d9bb>Berdengung—Berdengung—</color>",
  ui_story_1014_10140101_16_dialog_content = "Hmm? Tahan pikiran itu, PlayerName.",
  ui_story_1014_10140101_17_dialog_content = "Halo...? Ah-!",
  ui_story_1014_10140101_18_dialog_content = "L-Wakil Letnan melapor, Marsekal Agung!",
  ui_story_1014_10140101_19_dialog_content = "(The Grand Marshal? Dia mungkin hanya khawatir tentang Wakil juga ... Tentunya?)",
  ui_story_1014_10140101_20_dialog_content = "Oh? Misi mendesak?",
  ui_story_1014_10140101_21_dialog_content = "(Apa?! Mendesak? Sekarang?!)",
  ui_story_1014_10140101_22_dialog_content = "Dipahami. Biarkan saya mengambil beberapa catatan.",
  ui_story_1014_10140101_23_dialog_content = "<size=33>Dewan... Twilight... Reruntuhan Aurora... pertukaran intel...</size>",
  ui_story_1014_10140101_24_dialog_content = "(Pada dasarnya itu semua yang baru saja kita bahas di sana!)",
  ui_story_1014_10140101_25_dialog_content = "Ya, aku mengerti.",
  ui_story_1014_10140101_26_dialog_content = "Terima kasih telah mempercayai saya. Yakinlah, saya akan menyelesaikan pekerjaan.",
  ui_story_1014_10140101_27_dialog_content = "(Apa sih yang ditugaskan padanya kali ini?)",
  ui_story_1014_10140101_28_dialog_content = "Dipahami! Saya akan menyelesaikan misi dengan fokus maksimal!",
  ui_story_1014_10140101_29_dialog_content = "Jadi, PlayerName, katakan apapun yang kamu mau, tapi aku ikut denganmu!",
  ui_story_1014_10140101_30_dialog_content = "Ini perintah langsung dari Grand Marshal sendiri.",
  ui_story_1014_10140101_31_dialog_content = "Jangan mempersulit saya, atau mempermalukan Grand Marshal.",
  ui_story_1014_10140101_32_dialog_content = "Bagaimana ini terjadi?!",
  ui_story_1014_10140101_33_dialog_content = "Grand Marshal terdengar agak bermasalah. Dia tampaknya sedikit terjebak dalam tugasnya di tangan.",
  ui_story_1014_10140101_34_dialog_content = "\"Wakil Letnan, Anda mewakili markas Illumina dan mendukung misi Caelestite dengan pasukan perbatasan.\"",
  ui_story_1014_10140101_35_dialog_content = "Itu adalah instruksinya.",
  ui_story_1014_10140101_36_dialog_content = "Walaupun demikian-",
  ui_story_1014_10140101_37_dialog_content = "Jangan khawatir, PlayerName.",
  ui_story_1014_10140101_38_dialog_content = "Mengapa Anda tidak memberi tahu saya tentang detail tugas ini?",
  ui_story_1014_10140101_39_dialog_content = "... Baik. Lalu biarkan saya mulai dari atas. Pada rapat dewan sebelumnya...",
  ui_story_1014_10140101_40_dialog_content = "<color=#e8d9bb>Federasi Illumina, Kota Gannon, Balai Konferensi Illumina</color>",
  ui_story_1014_10140101_41_dialog_content = "Jika Anda menerima kesepakatan itu, kami akan mengirimkan perwakilan untuk bernegosiasi dengan para ilmuwan yang memiliki informasi tersebut.",
  ui_story_1014_10140101_42_dialog_content = "Pertukaran, untuk data penelitian yang dibutuhkan oleh Soroz.",
  ui_story_1014_10140101_43_dialog_content = "Tidak ada lagi penundaan. Saya harus pergi ke Aurora Ruins sendiri untuk berdagang!",
  ui_story_1014_10140101_44_dialog_content = "Dengan Soroz, saya yakin saya akan sampai di sana lebih cepat daripada pasukan penghubung.",
  ui_story_1014_10140101_45_dialog_content = "Maksud Anda, Anda akan berkomunikasi dengan mereka yang tinggal di sekitar Reruntuhan Aurora sebagai perwakilan kantor pusat Illumina?",
  ui_story_1014_10140101_46_dialog_content = "Saya tidak berpikir Anda memiliki otoritas semacam itu, Caelestite.",
  ui_story_1014_10140101_47_dialog_content = "Apa masalahnya? Jangan membuat hal-hal politis, Ulysses.",
  ui_story_1014_10140101_48_dialog_content = "Ini pada akhirnya adalah perdagangan antara PlayerName dan Senja. Illumina hanya menyediakan sarana untuk tujuan ini.",
  ui_story_1014_10140101_49_dialog_content = "Ya—wn... Aku menantikannya.",
  ui_story_1014_10140101_50_dialog_content = "Untuk sesuatu seperti <color=#FFB400>Kerapuhan Surgawi</color>, kami sangat membutuhkan orang yang tepat untuk mengawalnya.",
  ui_story_1014_10140101_51_dialog_content = "Kerapuhan Surgawi? Itulah yang Anda harapkan untuk diperdagangkan, bukan?",
  ui_story_1014_10140101_52_dialog_content = "Ya. Markas besar telah bernegosiasi dengan pasukan Illumina yang ditempatkan di Twilight.",
  ui_story_1014_10140101_53_dialog_content = "Karena seringnya pertempuran di zona perbatasan, mereka memutuskan untuk mengirim cyborg tempur ke daerah tersebut.",
  ui_story_1014_10140101_54_dialog_content = "Ini adalah produk terbaru Ulysses.",
  ui_story_1014_10140101_55_dialog_content = "Gunakan itu untuk berinteraksi dengan pasukan Illumina di sana, dan mereka akan menawarkan data penelitian Colossus yang relevan sebagai gantinya.",
  ui_story_1014_10140101_56_dialog_content = "Tapi cyborg itu sangat berharga dan rapuh, harus sangat berhati-hati saat transit.",
  ui_story_1014_10140101_57_dialog_content = "Daripada mengangkutnya dengan pesawat, lebih aman meminta Caelestite mengirimkannya secara khusus.",
  ui_story_1014_10140101_58_dialog_content = "Jadi, Kerapuhan Surgawi yang legendaris...",
  ui_story_1014_10140101_59_dialog_content = "Betul sekali. Itu ada di tangan kita.",
  ui_story_1014_10140101_60_dialog_content = "Anda membuat saya sangat penasaran sekarang! Aku ingin tahu cyborg macam apa itu.",
  ui_story_1014_10140101_61_dialog_content = "<color=#e8d9bb><size=30>Dentang...</size></color>",
  ui_story_1014_10140101_62_dialog_content = "PlayerName! C-Ayo cepat! Itu membuat semacam kebisingan!",
  ui_story_1014_10140101_63_dialog_content = "Ke-bisingan apa? Saya tidak berpikir saya mendengar apa-apa ...",
  ui_story_1014_10140101_64_dialog_content = "... Mungkin aku sedikit gelisah.",
  ui_story_1014_10140101_65_dialog_content = "Apa yang kamu pikirkan, PlayerName?",
  ui_story_1014_10140101_66_dialog_content = "Aku sedikit... khawatir.",
  ui_story_1014_10140101_67_dialog_content = "Soroz tidak dalam kondisi bagus. Akan sulit untuk menyelesaikan bahkan pekerjaan logistik yang paling dasar, dan jika—",
  ui_story_1014_10140101_68_dialog_content = "Jika kita mengalami masalah, kita akan memikirkan sesuatu.",
  ui_story_1014_10140101_69_dialog_content = "Untuk saat ini, kita perlu berhenti berbicara dan mulai bergerak!",
  ui_story_1014_10140101_70_dialog_content = "Ya, Anda mungkin benar ...",
  ui_story_1014_10140101_71_dialog_content = "<color=#e8d9bb>Soroz, Jembatan</color>",
  ui_story_1014_10140101_72_dialog_content = "(Sistem Kontrol Utama... Periksa.)",
  ui_story_1014_10140101_73_dialog_content = "(Fungsi mesin... Periksa.)",
  ui_story_1014_10140101_74_dialog_content = "Saya perlu menangani hal-hal ini sendiri sekarang ...",
  ui_story_1014_10140101_75_dialog_content = "(Saya harus pergi ke lounge dan memeriksa ulang semuanya.)",
  ui_story_1014_10140101_76_dialog_content = "... Hah?!",
  ui_story_1014_10140101_77_dialog_content = "Carleen, Beretta?! Dan... Yingel??",
  ui_story_1014_10140101_78_dialog_content = "Apa yang kalian lakukan di sini?",
  ui_story_1014_10140101_79_dialog_content = "Carleen, aku bahkan belum sempat memberitahumu...",
  ui_story_1014_10140101_80_dialog_content = "Wakil sudah melakukannya. Katanya kau akan berangkat menuju malam abadi, PlayerName.",
  ui_story_1014_10140101_81_dialog_content = "Hanya kalian berdua di luar sana, berjuang sendiri. Bagaimana kami tidak khawatir?",
  ui_story_1014_10140101_82_dialog_content = "Hehe, Carleen tua yang baik dan andal.",
  ui_story_1014_10140101_83_dialog_content = "Saya khawatir Anda tidak akan berhasil tepat waktu!",
  ui_story_1014_10140101_84_dialog_content = "Nah, sudah lama sekali Lumopolis menghubungi pasukan perbatasan di Twilight.",
  ui_story_1014_10140101_85_dialog_content = "Jadi saya membawa Beretta, karena sebaiknya kita melakukan inspeksi saat kita di sana.",
  ui_story_1014_10140101_86_dialog_content = "Kita bertemu lagi, PlayerName.",
  ui_story_1014_10140101_87_dialog_content = "Anda tidak terlihat sangat baik. Perlu saya memberi Anda sedikit suntikan?",
  ui_story_1014_10140101_88_dialog_content = "A-Apa?!",
  ui_story_1014_10140101_89_dialog_content = "Hanya bercanda.",
  ui_story_1014_10140101_90_dialog_content = "Siapa Iluminan ini? Apakah kita bertemu di Eraveil? Anda tidak terlihat akrab.",
  ui_story_1014_10140101_91_dialog_content = "Rambut putih Illuminan itu tidak mengikutimu kali ini?",
  ui_story_1014_10140101_92_dialog_content = "Sopan santun, Beretta.",
  ui_story_1014_10140101_93_dialog_content = "Ya Bu! Nyonya Carleen.",
  ui_story_1014_10140101_94_dialog_content = "Kolonel Yingel, dari Layanan Keamanan Internal Federasi Illumina.",
  ui_story_1014_10140101_95_dialog_content = "Senang akhirnya bisa bertemu denganmu, Letnan Vice. Banyak sekali yang ingin kutanyakan tentang Colossus dan Caelestite.",
  ui_story_1014_10140101_96_dialog_content = "Aduh...! K-Kau terlalu baik. Suatu kehormatan bertemu dengan Anda!",
  ui_story_1014_10140101_97_dialog_content = "(Vice tidak tahu apa yang harus dilakukan!)",
  ui_story_1014_10140101_98_dialog_content = "Jika saya boleh berani, dapatkah saya bertanya apakah Dewan Sains mengatur agar Anda berada di sini?",
  ui_story_1014_10140101_99_dialog_content = "Maaf, tapi aku di sini untuk sebuah misi. Namun...",
  ui_story_1014_10140101_100_dialog_content = "Saya pribadi senang mengunjungi zona perang perbatasan.",
  ui_story_1014_10140101_101_dialog_content = "Saya akan memberi Anda intelijen khusus yang kredibel sesuai dengan File A-42.",
  ui_story_1014_10140101_102_dialog_content = "Saya yakin Anda mungkin juga memerlukan pihak ketiga untuk memverifikasi keaslian Kerapuhan Surgawi.",
  ui_story_1014_10140101_103_dialog_content = "Itu benar, tapi—",
  ui_story_1014_10140101_104_dialog_content = "Jangan khawatir. Markas besar memimpin dalam hal ini, jadi saya tidak akan terlalu ikut campur, apakah semuanya berjalan lancar atau tidak.",
  ui_story_1014_10140101_105_dialog_content = "(Tidak ada alasan untuk meragukannya...)",
  ui_story_1014_10140101_106_dialog_content = "Tunggu... Bukankah ini hanya menyisakan Reinhardt untuk berbicara dengan Dewan Sains?",
  ui_story_1014_10140101_107_dialog_content = "Tentunya Anda tidak khawatir tentang Grand Marshal?",
  ui_story_1014_10140101_108_dialog_content = "Saya kira Anda benar, saya tidak perlu khawatir tentang Reinhardt.",
  ui_story_1014_10140101_109_dialog_content = "<color=#e8d9bb>Sementara itu, Gedung Konferensi Illumina</color>",
  ui_story_1014_10140101_110_dialog_content = "Memburu Forsakin dan Helios bukanlah misi strategis, Reinhardt. Saya tidak berpikir ada kebutuhan bagi Anda untuk melakukannya sendiri.",
  ui_story_1014_10140101_111_dialog_content = "Dewan Sains mempercayakan misi itu kepada mereka yang lebih tepat.",
  ui_story_1014_10140101_112_dialog_content = "Tidak pernah bijaksana untuk terpaku pada masa lalu. Anda perlu fokus pada hal-hal yang lebih penting.",
  ui_story_1014_10140101_113_dialog_content = "Apakah Anda khawatir saya akan menemukan bukti hal-hal yang tidak menguntungkan bagi Ulysses?",
  ui_story_1014_10140101_114_dialog_content = "Maksudmu?",
  ui_story_1014_10140101_115_dialog_content = "Anda tahu betul apa yang saya maksud.",
  ui_story_1014_10140101_116_dialog_content = "Saya tidak sabar menunggu hari kebenaran terungkap, Ulysses. Anda kehabisan waktu untuk bermain bodoh.",
  ui_story_1014_10140101_117_dialog_content = "Jika Anda bersikeras untuk menjadi seperti ini, saya khawatir Komite juga harus menilai kembali kompetensi Anda.",
  ui_story_1014_10140101_118_dialog_content = "Baiklah, kalau begitu beri tahu saya: Apa yang Anda anggap lebih penting daripada nasib Aurorian?",
  ui_story_1014_10140101_119_dialog_content = "Ingin aku memberitahumu? Acara militer gabungan Illumina, strategi serangan balik di masa depan, semuanya—",
  ui_story_1014_10140101_120_dialog_content = "Sangat tidak masuk akal.",
  ui_story_1014_10140101_121_dialog_content = "Saya tidak pernah membutuhkan siapa pun untuk memberi tahu saya bagaimana menjadi Grand Marshal.",
  ui_story_1014_10140101_122_dialog_content = "Keputusan saya tidak mudah diombang-ambingkan oleh orang lain.",
  ui_story_1014_10140101_123_dialog_content = "Aku akan pergi, semuanya.",
  ui_story_1014_10140101_124_dialog_content = "Dia masih begitu keras kepala.",
  ui_story_1014_10140101_125_dialog_content = "Tentu, tapi dengan kemampuannya, dia seharusnya bisa melacak wanita Eclipse itu dengan mudah.",
  ui_story_1014_10140101_126_dialog_content = "Simpan komentar Anda untuk diri Anda sendiri.",
  ui_story_1014_10140101_127_dialog_content = "Saya membuat rencana darurat untuk situasi yang tepat ini.",
  ui_story_1014_10140201_1_dialog_content = "Sistem Kontrol Utama, um, normal.",
  ui_story_1014_10140201_2_dialog_content = "Begitu juga dengan sistem Autopilot.",
  ui_story_1014_10140201_3_dialog_content = "Soroz telah terbang dengan lancar untuk sementara waktu sekarang, PlayerName. Anda bisa sedikit rileks.",
  ui_story_1014_10140201_4_dialog_content = "Sepertinya kau benar, Vice. Terima kasih.",
  ui_story_1014_10140201_5_dialog_content = "Aku baik-baik saja, tapi kamu masih terlihat stres.",
  ui_story_1014_10140201_6_dialog_content = "Tapi tetap saja... Saya tidak berpikir Anda perlu berpegang pada hal Kerapuhan Surgawi ini sepanjang waktu.",
  ui_story_1014_10140201_7_dialog_content = "Kamu bukan induk ayam.",
  ui_story_1014_10140201_8_dialog_content = "Secara teknis, ini merupakan bagian integral dari perbaikan Soroz, jadi ini sangat penting!",
  ui_story_1014_10140201_9_dialog_content = "Saya tidak tahu bagaimana lagi melindunginya untuk saat ini.",
  ui_story_1014_10140201_10_dialog_content = "Selain itu, tidak seberat yang saya bayangkan...",
  ui_story_1014_10140201_11_dialog_content = "Betulkah? Itu aneh. Apakah Anda pikir itu semacam senjata ringan?",
  ui_story_1014_10140201_12_dialog_content = "Ringan dan rapuh... yang tampaknya aneh untuk cyborg tempur tingkat lanjut.",
  ui_story_1014_10140201_13_dialog_content = "P-Pokoknya, aku akan terus memegangnya seperti ini!",
  ui_story_1014_10140201_14_dialog_content = "Sebenarnya...",
  ui_story_1014_10140201_15_dialog_content = "(Sebagai gantinya, aku akan melihat apa yang sedang dilakukan Carleen.)",
  ui_story_1014_10140201_16_dialog_content = "<color=#e8d9bb>Buzz—Keretak—</color>",
  ui_story_1014_10140201_17_dialog_content = "...",
  ui_story_1014_10140201_18_dialog_content = "Masih tidak bagus, Beretta?",
  ui_story_1014_10140201_19_dialog_content = "Maaf, Nona Carleen. Saya tidak terlalu tahu tentang perangkat semacam ini.",
  ui_story_1014_10140201_20_dialog_content = "Hmm?",
  ui_story_1014_10140201_21_dialog_content = "Waktu yang tepat, Vice.",
  ui_story_1014_10140201_22_dialog_content = "Ada apa? Ada yang bisa saya bantu?",
  ui_story_1014_10140201_23_dialog_content = "Aku sedang berpikir untuk menghubungi Ksatria Lumo yang ditempatkan di perbatasan untuk mengetahui situasi di lapangan di sana.",
  ui_story_1014_10140201_24_dialog_content = "Mereka sudah ada di sana selama bertahun-tahun sekarang, dan seharusnya bisa membantu kami.",
  ui_story_1014_10140201_25_dialog_content = "Hal semacam ini biasanya ditangani oleh Tuan Kota. Ini salahku karena tidak melakukan kontak terlebih dahulu.",
  ui_story_1014_10140201_26_dialog_content = "Yah, itu adalah keberangkatan yang agak terakhir!",
  ui_story_1014_10140201_27_dialog_content = "Tapi sekarang saya tidak perlu khawatir, mengingat saya punya panduan hebat sebelum saya.",
  ui_story_1014_10140201_28_dialog_content = "Tolong, Vice, bantu aku mencari tahu apa yang salah dengan benda ini.",
  ui_story_1014_10140201_29_dialog_content = "Sinyal terus terputus.",
  ui_story_1014_10140201_30_dialog_content = "Serahkan padaku!",
  ui_story_1014_10140201_31_dialog_content = "Mari kita lihat... Pertama, kalibrasi sensitivitas antena...",
  ui_story_1014_10140201_32_dialog_content = "Baiklah, cobalah!",
  ui_story_1014_10140201_33_dialog_content = "<color=#e8d9bb>Buzz—Keretak—</color>",
  ui_story_1014_10140201_34_dialog_content = "Hmm baiklah. Jadi bagaimana dengan ... menyesuaikan modul daya!",
  ui_story_1014_10140201_35_dialog_content = "Oke! Sebaiknya pergi sekarang.",
  ui_story_1014_10140201_36_dialog_content = "<color=#e8d9bb>Buzz—Keretak—</color>",
  ui_story_1014_10140201_37_dialog_content = "Ahaha! Dalam hal ini, satu-satunya yang tersisa adalah—",
  ui_story_1014_10140201_38_dialog_content = "<color=#e8d9bb>Bang! Mendering!</color>",
  ui_story_1014_10140201_39_dialog_content = "<color=#e8d9bb>Bip, Bip...</color>",
  ui_story_1014_10140201_40_dialog_content = "Fiuh! Sepotong kue.",
  ui_story_1014_10140201_41_dialog_content = "Jadi begitulah cara Anda memperbaikinya.",
  ui_story_1014_10140201_42_dialog_content = "Apakah ada orang di sana?",
  ui_story_1014_10140201_43_dialog_content = "Ini adalah <color=#FFB400>Ksatria Ironthorn</color>. Saya ulangi, Ironthorn Knights.",
  ui_story_1014_10140201_44_dialog_content = "Bagus, kami memiliki sinyal yang kuat. White Night di ketinggian, Kapten Penjaga Taman Lumopolis Carleen mengirim salam kepada Ironthorn Knights.",
  ui_story_1014_10140201_45_dialog_content = "Kapten Leo menyapa Lady Carleen...",
  ui_story_1014_10140201_46_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1014_10140201_47_dialog_content = "(Apakah sinyalnya masih buruk...?)",
  ui_story_1014_10140201_48_dialog_content = "Pak Leo, Lumopolis akan melanjutkan ke Twilight untuk pemeriksaan rutin.",
  ui_story_1014_10140201_49_dialog_content = "Saya akan hadir atas nama Lumopolis. Saya berharap untuk bertemu dengan Anda saat itu.",
  ui_story_1014_10140201_50_dialog_content = "Bekerja di zona perbatasan itu sulit. Saya berharap memiliki kesempatan untuk berterima kasih secara pribadi.",
  ui_story_1014_10140201_51_dialog_content = "Yah, itu sedikit kejutan! Saya akan melakukan yang terbaik untuk mengkoordinasikan <color=#FFB400>Benteng Lumo</color> patroli.",
  ui_story_1014_10140201_52_dialog_content = "Dan tidak perlu berterima kasih padaku. Saya hanya melakukan pekerjaan saya.",
  ui_story_1014_10140201_53_dialog_content = "Aku akan melihat Anda segera, kemudian.",
  ui_story_1014_10140201_54_dialog_content = "Roger. Ketika Anda tiba, saya akan mengirim seseorang ... Anda tiba ... untuk ...",
  ui_story_1014_10140201_55_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1014_10140201_56_dialog_content = "<color=#e8d9bb>Bip, Bip...</color>",
  ui_story_1014_10140201_57_dialog_content = "Sepertinya sinyalnya benar-benar hilang...",
  ui_story_1014_10140201_58_dialog_content = "Lupakan saja, setidaknya kami berhasil menyampaikan infonya.",
  ui_story_1014_10140201_59_dialog_content = "A-Apakah itu baik-baik saja, Lady Carleen?",
  ui_story_1014_10140201_60_dialog_content = "Posisi Anda sebagai Kapten baru saja dipulihkan setelah pertempuran di Eraveil.",
  ui_story_1014_10140201_61_dialog_content = "Meskipun Anda tampak jauh lebih tegas dari sebelumnya ...",
  ui_story_1014_10140201_62_dialog_content = "menurut Penguasa Kota, secara teknis Anda masih dalam masa percobaan.",
  ui_story_1014_10140201_63_dialog_content = "Saya harap semuanya berjalan lancar...",
  ui_story_1014_10140201_64_dialog_content = "Ini akan baik-baik saja, Beretta. Saya mengerti dari mana Anda berasal, tetapi tidak perlu terlalu khawatir.",
  ui_story_1014_10140201_65_dialog_content = "Bahkan jika ada masalah, kami hanya menanggapi dengan tepat, dan kami akan baik-baik saja.",
  ui_story_1014_10140201_66_dialog_content = "Ya... Anda benar, Nona Carleen!",
  ui_story_1014_10140201_67_dialog_content = "Omong-omong, siapakah Kapten Leo ini?",
  ui_story_1014_10140201_68_dialog_content = "Anda mengucapkan terima kasih yang sopan, tetapi tanggapannya agak kasar.",
  ui_story_1014_10140201_69_dialog_content = "Jangan katakan itu, Beretta.",
  ui_story_1014_10140201_70_dialog_content = "Kita yang tinggal dengan aman di dalam Lumopolis harus menghormati para pejuang di zona perbatasan.",
  ui_story_1014_10140201_71_dialog_content = "<color=#e8d9bb>Bip — Bip — Bip —</color>",
  ui_story_1014_10140201_72_dialog_content = "A-Apa itu?",
  ui_story_1014_10140201_73_dialog_content = "Bukankah itu alarm peringatan Soroz?",
  ui_story_1014_10140201_74_dialog_content = "Oh tidak...",
  ui_story_1014_10140201_75_dialog_content = "Kita harus pergi mencari PlayerName!",
  ui_story_1014_10140201_76_dialog_content = "*Terengah-engah*",
  ui_story_1014_10140201_77_option_content = "Aktifkan Mode Darurat",
  ui_story_1014_10140201_78_dialog_content = "<color=#e8d9bb>Bip—</color>",
  ui_story_1014_10140201_79_option_content = "Menstabilkan Pesawat",
  ui_story_1014_10140201_80_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_1014_10140201_81_dialog_content = "Awas!",
  ui_story_1014_10140201_82_dialog_content = "Jika saya tidak memegangnya, Kerapuhan Surgawi akan terlempar ke mana-mana.",
  ui_story_1014_10140201_83_dialog_content = "Apa sebenarnya yang sedang terjadi, PlayerName?",
  ui_story_1014_10140201_84_dialog_content = "Alarm mengejutkan Anda, kan? Um, salahku. Saya memicunya secara tidak sengaja.",
  ui_story_1014_10140201_85_dialog_content = "Jangan hanya mengatakan sesuatu seperti itu dengan santai seperti sedang berbicara tentang cuaca!",
  ui_story_1014_10140201_86_dialog_content = "Apakah Anda yakin semuanya baik-baik saja? Mengemudikan Colossus lebih sulit daripada yang saya kira...",
  ui_story_1014_10140201_87_dialog_content = "T-Tentu saja, semuanya baik-baik saja.",
  ui_story_1014_10140201_88_dialog_content = "(Saya seorang Caelestite, pada akhirnya!)",
  ui_story_1014_10140201_89_dialog_content = "Jangan memaksakan diri, kita bisa mendarat di suatu tempat terdekat dan istirahat sebentar.",
  ui_story_1014_10140201_90_dialog_content = "Semakin dekat kita dengan malam abadi, semakin banyak Darkflow di sekitar kita.",
  ui_story_1014_10140201_91_dialog_content = "Anda tidak bisa merasa terlalu hebat sekarang, bukan?",
  ui_story_1014_10140201_92_dialog_content = "Jujur.",
  ui_story_1014_10140201_93_dialog_content = "Sangat perseptif... Tapi kau benar. Kepalaku mulai sakit sebelumnya.",
  ui_story_1014_10140201_94_dialog_content = "Aku tidak tahu banyak tentang mengemudikan Colossus, tapi saat mempertimbangkan keamanan Heavenly Fragility...",
  ui_story_1014_10140201_95_dialog_content = "Saran saya adalah mendarat dan beristirahat sebentar.",
  ui_story_1014_10140201_96_dialog_content = "Saya tidak berpikir salah satu dari kami ingin melihat sesuatu terjadi pada Kerapuhan Surgawi karena Anda telah melakukan kesalahan.",
  ui_story_1014_10140201_97_dialog_content = "Tidak, tentu saja tidak.",
  ui_story_1014_10140201_98_dialog_content = "Baik. Memang, saya mencoba meyakinkan diri sendiri bahwa saya baik-baik saja.",
  ui_story_1014_10140201_99_dialog_content = "Semuanya, bersiaplah untuk mendarat. Saya akan memulai keturunan Soroz.",
  ui_story_1014_10140201_100_dialog_content = "Fiuh—",
  ui_story_1014_10140201_101_dialog_content = "Senang bisa keluar dan meregangkan kaki sebentar.",
  ui_story_1014_10140201_102_dialog_content = "Bagaimanapun, apakah kita tahu apa yang terjadi pada Soroz?",
  ui_story_1014_10140201_103_dialog_content = "Sulit membayangkan bahwa Anda harus mendaratkannya secara manual.",
  ui_story_1014_10140201_104_dialog_content = "Itu terlihat lebih serius daripada yang terakhir kali.",
  ui_story_1014_10140201_105_dialog_content = "Ada masalah dengan kesadarannya. Itu tidak memengaruhi fungsi normalnya, tetapi saat ini, saya tidak mendapatkan respons lain.",
  ui_story_1014_10140201_106_dialog_content = "... Saya akan memeriksa instrumennya sekali lagi.",
  ui_story_1014_10140201_107_dialog_content = "Aku akan pergi denganmu.",
  ui_story_1014_10140201_108_dialog_content = "<color=#e8d9bb>wuussss... wuusss...</color>",
  ui_story_1014_10140201_109_dialog_content = "(Ini benar-benar sunyi di luar sana.)",
  ui_story_1014_10140201_110_dialog_content = "Lumina di sini jauh lebih tipis daripada di markas Illumina. Apakah kamu baik - baik saja?",
  ui_story_1014_10140201_111_dialog_content = "Ini bukan apa-apa.",
  ui_story_1014_10140201_112_dialog_content = "Dan selain itu, mendokumentasikan perjalanan Caelestite secara menyeluruh adalah salah satu tugas yang ditugaskan kepadaku.",
  ui_story_1014_10140201_113_dialog_content = "Mengapa Anda tidak melanjutkan dan mencari tahu apa yang terjadi dengan Colossus Anda sekarang?",
  ui_story_1014_10140201_114_dialog_content = "B-Baik, aku ikut.",
  ui_story_1014_10140201_115_dialog_content = "(Rasanya seperti saya sedang dipantau...)",
  ui_story_1014_10140201_116_dialog_content = "Graah...",
  ui_story_1014_10140201_117_dialog_content = "Hah? Bukankah itu suara—",
  ui_story_1014_10140201_118_dialog_content = "<anim type=Shake><size=45>Graaaaaah!</size></anim>",
  ui_story_1014_10140201_119_dialog_content = "Eclipsite?!",
  ui_story_1014_10140201_120_dialog_content = "Saya kira tidak ada yang aneh tentang mereka berada di tempat semacam ini!",
  ui_story_1014_10140201_121_dialog_content = "Kita tidak bisa membiarkan mereka sampai ke Soroz. Bisakah kamu bertarung?",
  ui_story_1014_10140201_122_dialog_content = "Aku... Jika itu adalah simulasi pertempuran atau semacamnya...",
  ui_story_1014_10140201_123_dialog_content = "Kalau begitu, pergi dan dapatkan Vice dan Carleen, sekarang!",
  ui_story_1014_10140201_124_dialog_content = "Pertarungan.",
  ui_story_1014_10140201_125_dialog_content = "Perintah pertempuran diterima.",
  ui_story_1014_10140201_126_dialog_content = "?!",
  ui_story_1014_10140201_127_dialog_content = "(Akhirnya keluar...)",
  ui_story_1014_10140201_128_dialog_content = "S-Siapa yang bilang itu?",
  ui_story_1014_10140201_129_dialog_content = "<color=#e8d9bb>Klang, klang...</color>",
  ui_story_1014_10140201_130_dialog_content = "Saya telah menerima perintah pertempuran Anda.",
  ui_story_1014_10140201_131_dialog_content = "Jangan menyusahkan Yingel.",
  ui_story_1014_10140201_132_dialog_content = "Saya siap bertarung.",
  ui_story_1014_10140201_133_dialog_content = "Kamu-kamu...",
  ui_story_1014_10140201_134_dialog_content = "Anda <color=#FFB400>Kerapuhan Surgawi</color>? Hal yang diberikan Dewan Sains kepada kami ?!",
  ui_story_1014_10140201_135_dialog_content = "Graagh!",
  ui_story_1014_10140201_136_dialog_content = "Lemah.",
  ui_story_1014_10140202_1_dialog_content = "Torrent Cepat—!",
  ui_story_1014_10140202_2_dialog_content = "Ice Blossom! Menyebar!",
  ui_story_1014_10140202_3_dialog_content = "Terima kasih atas bantuannya, Wakil Letnan.",
  ui_story_1014_10140202_4_dialog_content = "Semua baik-baik saja, Axelia?",
  ui_story_1014_10140202_5_dialog_content = "Anda harus menanyakan hal-hal itu.",
  ui_story_1014_10140202_6_dialog_content = "... Meskipun tidak satupun dari mereka dalam kondisi apapun untuk menjawab.",
  ui_story_1014_10140202_7_dialog_content = "Nah, benar-benar sekarang! Anda tidak boleh keluar dari ruang stasis tanpa izin. Ini bukan tujuan misi Anda.",
  ui_story_1014_10140202_8_dialog_content = "Aku akan berhati-hati untuk tidak menyakiti diriku sendiri.",
  ui_story_1014_10140202_9_dialog_content = "Saya tidak ingin mempersulit Anda, Yingel.",
  ui_story_1014_10140202_10_dialog_content = "Ini bukan waktunya untuk mengobrol!",
  ui_story_1014_10140202_11_dialog_content = "Adakah yang mau menjelaskan kepadaku mengapa dia terlihat seperti Aurorian?",
  ui_story_1014_10140202_12_dialog_content = "Sebenarnya, dia ADALAH seorang Aurorian.",
  ui_story_1014_10140202_13_dialog_content = "Tapi selain itu, dia lebih dikenal sebagai Combat Cyborg, kebanggaan dan kegembiraan Dewan Sains,.",
  ui_story_1014_10140202_14_dialog_content = "Sebuah... cyborg?",
  ui_story_1014_10140202_15_dialog_content = "Kami biasa memanggilnya seperti itu.",
  ui_story_1014_10140202_16_dialog_content = "Dia seorang perfeksionis, mampu melaksanakan setiap perintah ke surat itu.",
  ui_story_1014_10140202_17_dialog_content = "Bukan karena dia mengendalikan Lumina, tetapi lebih karena Lumina membentuk dirinya.",
  ui_story_1014_10140202_18_dialog_content = "Selama dia mengaktifkan Luminatics, dia akan menggunakan Lumina untuk melihat, mendengar, dan mengoperasikan semua jenis teknologi untuk mengakhiri pertempuran.",
  ui_story_1014_10140202_19_dialog_content = "Itu luar biasa! Saya belum pernah melihat yang seperti ini!",
  ui_story_1014_10140202_20_dialog_content = "Saya tahu. Dia benar-benar teladan pengguna Luminatics. Namun...",
  ui_story_1014_10140202_21_dialog_content = "Bentuk fisiknya sangat rapuh.",
  ui_story_1014_10140202_22_dialog_content = "Anda dapat mengetahui dari semua perban bahwa organ-organnya terus-menerus mengalami kegagalan.",
  ui_story_1014_10140202_23_dialog_content = "Kegagalan organ? Tapi kenapa? Dan mengapa medtech Illumina tidak bisa menyembuhkannya?",
  ui_story_1014_10140202_24_dialog_content = "Mungkin itu genetik. Siapa tahu?",
  ui_story_1014_10140202_25_dialog_content = "Terlepas dari itu, dia memang seperti itu: meriam kaca.",
  ui_story_1014_10140202_26_dialog_content = "Menjaga dia di markas Illumina adalah pemborosan. Kemampuannya hanya bisa dilihat di tempat yang drastis seperti Twilight.",
  ui_story_1014_10140202_27_dialog_content = "Halo, PlayerName. Salam ini sudah lama ditunggu.",
  ui_story_1014_10140202_28_dialog_content = "Saya perlu merepotkan Anda lagi selama sisa perjalanan, maaf.",
  ui_story_1014_10140202_29_dialog_content = "Sebagai imbalannya, saya akan...",
  ui_story_1014_10140202_30_dialog_content = "tinggalkan ruang stasis saya dan bertarung pada saat dibutuhkan.",
  ui_story_1014_10140202_31_dialog_content = "Tak usah repot-repot!",
  ui_story_1014_10140202_32_dialog_content = "(Kami sudah selesai jika Anda terluka!)",
  ui_story_1014_10140202_33_dialog_content = "Kita dapat dengan mudah menangani sendiri Eclipsites normal. Bagi Anda untuk terlibat adalah seperti menggunakan palu godam untuk memecahkan kacang!",
  ui_story_1014_10140202_34_dialog_content = "Ya. Istirahat saja, kami tidak akan memanggil Anda kecuali kami benar-benar harus.",
  ui_story_1014_10140202_35_dialog_content = "Sekarang setelah Anda menyebutkannya, saya merasa sedikit mengantuk.",
  ui_story_1014_10140202_36_dialog_content = "(Aww... Dia hanya anak kecil yang lucu!)",
  ui_story_1014_10140202_37_dialog_content = "Dia terlihat seumuran dengan kita, tapi dia mudah mengantuk.",
  ui_story_1014_10140202_38_dialog_content = "Dia selalu seperti ini...",
  ui_story_1014_10140202_39_dialog_content = "Baginya, setiap pertempuran adalah pengeluaran energi yang sangat besar. Mungkin yang terbaik baginya untuk beristirahat dan memulihkan diri.",
  ui_story_1014_10140202_40_dialog_content = "Selamat malam semuanya.",
  ui_story_1014_10140202_41_dialog_content = "Haruskah kita membawanya ke lounge?",
  ui_story_1014_10140202_42_dialog_content = "Beretta, bagaimana kabarmu?",
  ui_story_1014_10140202_43_dialog_content = "Datang, Nyonya Carleen!",
  ui_story_1014_10140202_44_dialog_content = "Saya baru saja melakukan pemeriksaan sepintas terhadap Colossus.",
  ui_story_1014_10140202_45_dialog_content = "Meskipun menjadi asisten Raphael, ketika sampai pada penyakit mesin kuno seperti itu, aku masih—",
  ui_story_1014_10140202_46_dialog_content = "Terima kasih atas usaha Anda, Beretta!",
  ui_story_1014_10140202_47_dialog_content = "Terlepas dari itu, tidak mungkin Soroz bisa terbang sekarang.",
  ui_story_1014_10140202_48_dialog_content = "Sebut saja sehari, luangkan waktu untuk istirahat.",
  ui_story_1014_10140202_49_dialog_content = "Beristirahat... di tempat seperti ini?",
  ui_story_1014_10140202_50_dialog_content = "Kita hampir tidak bisa melihat matahari dari sini. Kami bahkan tidak tahu jam berapa sekarang ...",
  ui_story_1014_10140202_51_dialog_content = "Eh, sudahlah. Mungkin ini hanya hal yang Anda lakukan saat berziarah ke tanah suci.",
  ui_story_1014_10140202_52_dialog_content = "Tanah suci? Saya tidak berpikir Anda dapat menyebut tempat semacam itu suci.",
  ui_story_1014_10140202_53_dialog_content = "Itu adalah benteng tempat pertempuran kuno terjadi antara Aurorian dan Eclipsites.",
  ui_story_1014_10140202_54_dialog_content = "Orang-orang Aurorian berpegang teguh, akhirnya mengusir Eclipsites menuju malam abadi.",
  ui_story_1014_10140202_55_dialog_content = "Apakah bernyanyi di atas kuburan orang mati merupakan tradisi Lumopolis?",
  ui_story_1014_10140202_56_dialog_content = "Tidak! Tentu saja tidak!",
  ui_story_1014_10140202_57_dialog_content = "Legenda mengklaim bahwa Reruntuhan Aurora adalah sumber aurora dunia.",
  ui_story_1014_10140202_58_dialog_content = "Itu juga tempat terjauh yang masih bisa dihuni oleh Aurorians, tempat kita bisa melacak akar kita.",
  ui_story_1014_10140202_59_dialog_content = "Itu tidak bertentangan dengan apa yang baru saja saya katakan.",
  ui_story_1014_10140202_60_dialog_content = "Jadi jangan membuatnya menjadi kuburan saja!",
  ui_story_1014_10140202_61_dialog_content = "(Sungguh memusingkan... Aku tidak tahu apakah itu karena Darkflow yang terkonsentrasi, atau keduanya dan pertengkaran mereka.)",
  ui_story_1014_10140202_62_dialog_content = "Cukup, tolong! Bisakah semua orang menahannya...",
  ui_story_1014_10140202_63_dialog_content = "Kemarilah, Beretta.",
  ui_story_1014_10140202_64_dialog_content = "Tenang, Komandan Yingel.",
  ui_story_1014_10140202_65_dialog_content = "Semakin gelap. Mari kembali ke Colossus.",
  ui_story_1014_10140202_66_dialog_content = "...",
  ui_story_1014_10140202_67_dialog_content = "Huh.",
  ui_story_1014_10140301_1_dialog_content = "<color=#e8d9bb>Soroz, Jembatan</color>",
  ui_story_1014_10140301_2_dialog_content = "<anim type=Shake>Menguap-</anim>",
  ui_story_1014_10140301_3_dialog_content = "(Masih sangat lelah... Aku benar-benar tidak bisa tidur nyenyak.)",
  ui_story_1014_10140301_4_dialog_content = "Pagi, PlayerName.",
  ui_story_1014_10140301_5_dialog_content = "Wow! Uh... kau terlihat agak pucat.",
  ui_story_1014_10140301_6_dialog_content = "Sulit tidur?",
  ui_story_1014_10140301_7_dialog_content = "Lebih atau kurang. Aliran Gelap di sini lebih kuat daripada saat kami pertama kali tiba.",
  ui_story_1014_10140301_8_dialog_content = "Saya terbangun setiap kali Eclipsite melewati Soroz tadi malam.",
  ui_story_1014_10140301_9_dialog_content = "Aku tidak bisa tidak merasa seperti kita sedang diburu...",
  ui_story_1014_10140301_10_dialog_content = "Kedengarannya seperti malam yang berat... Kamu harus tidur lebih banyak sekarang.",
  ui_story_1014_10140301_11_dialog_content = "Mmhmm. Ide bagus.",
  ui_story_1014_10140301_12_dialog_content = "Kurasa aku akan kembali ke tempat tidur kalau begitu...",
  ui_story_1014_10140301_13_dialog_content = "<color=#e8d9bb>Dor! Dor!</color>",
  ui_story_1014_10140301_14_dialog_content = "<color=#e8d9bb>Brak—!</color>",
  ui_story_1014_10140301_15_dialog_content = "Oh, demi cinta—",
  ui_story_1014_10140301_16_dialog_content = "Apa yang terjadi di luar sana?!!!",
  ui_story_1014_10140301_17_dialog_content = "Aku akan memeriksanya dengan Beretta.",
  ui_story_1014_10140301_18_dialog_content = "Saya ingin melihat sendiri!",
  ui_story_1014_10140301_19_dialog_content = "(Eclipsites ini benar-benar sudah keterlaluan!)",
  ui_story_1014_10140301_20_dialog_content = "Aku benar-benar mulai kehilangan kesabaran.",
  ui_story_1014_10140301_21_dialog_content = "... Hah? Sean?",
  ui_story_1014_10140301_22_dialog_content = "Hah?! PlayerName?!",
  ui_story_1014_10140301_23_dialog_content = "Sungguh mengejutkan, bertemu denganmu di tempat seperti ini!",
  ui_story_1014_10140301_24_dialog_content = "Jadi benda putih besar ini, seperti, Colossus *mu*, ya?",
  ui_story_1014_10140301_25_dialog_content = "... Siapa lagi itu?!",
  ui_story_1014_10140301_26_dialog_content = "Adil... Pokoknya PlayerName, Saya minta maaf atas masalah yang saya sebabkan kepada semua orang.",
  ui_story_1014_10140301_27_dialog_content = "Aku akan pergi melihat-lihat sebentar lagi. Saya harap \"ketukan pintu\" saya tidak merusak Soroz...",
  ui_story_1014_10140301_28_dialog_content = "(Mendesah...)",
  ui_story_1014_10140301_29_dialog_content = "Aku baru saja berpatroli di pinggiran Twilight.",
  ui_story_1014_10140301_30_dialog_content = "Kami memiliki Lumina yang sangat lemah di sini, jadi kami sering menemukan pengungsi yang tersesat.",
  ui_story_1014_10140301_31_dialog_content = "Tugas utama saya adalah menemukan orang-orang yang terdampar karena bencana mendadak, dan membersihkan Eclipsites saat saya melakukannya.",
  ui_story_1014_10140301_32_dialog_content = "Saat saya melihat orang putih besar ini, saya langsung memikirkan Anda!",
  ui_story_1014_10140301_33_dialog_content = "Mungkin sangat nyaman untuk bepergian sangat jauh dengan Colossus, bukan?",
  ui_story_1014_10140301_34_dialog_content = "Tentunya! Ke mana pun saya pergi, Colossus saya dapat membawa saya ke sana dalam sekejap mata.",
  ui_story_1014_10140301_35_dialog_content = "Luar biasa! Saya berharap saya punya satu juga.",
  ui_story_1014_10140301_36_dialog_content = "Saya pikir mimpi saya benar-benar menjadi kenyataan.",
  ui_story_1014_10140301_37_dialog_content = "Tapi kalau dipikir-pikir, menemukan Colossus baru yang ditinggalkan di pos terdepan semacam ini agak tidak masuk akal...",
  ui_story_1014_10140301_38_dialog_content = "Ya, itu benar-benar tidak masuk akal.",
  ui_story_1014_10140301_39_dialog_content = "Biarkan saya memperkenalkan semua orang. Ini Lady Carleen dan Beretta, Penjaga Taman Lumopolis.",
  ui_story_1014_10140301_40_dialog_content = "Halo.",
  ui_story_1014_10140301_41_dialog_content = "Jangan gegabah lagi, oke?",
  ui_story_1014_10140301_42_dialog_content = "Saya sangat menyesal!",
  ui_story_1014_10140301_43_dialog_content = "Ini Kolonel Yingel, dan kotak yang dia bawa adalah Axelia. Yang saya maksud dengan itu adalah...",
  ui_story_1014_10140301_44_dialog_content = "Yingel! Sudah lama! Siapa sangka kita akan bertemu lagi di tempat seperti ini?!",
  ui_story_1014_10140301_45_dialog_content = "Dan bagaimana kabar Axelia? Masih baik-baik saja?",
  ui_story_1014_10140301_46_dialog_content = "Kalian saling kenal?",
  ui_story_1014_10140301_47_dialog_content = "Nah sekarang, sungguh mengejutkan melihat Anda masih hidup dan sehat.",
  ui_story_1014_10140301_48_dialog_content = "Pff, tentu saja! Berjuang adalah hidup, setidaknya di Twilight, dan keterampilan saya telah meningkat pesat!",
  ui_story_1014_10140301_49_dialog_content = "Optimis seperti dulu...",
  ui_story_1014_10140301_50_dialog_content = "(Tiba-tiba, aku tidak mengantuk sama sekali...)",
  ui_story_1014_10140301_51_dialog_content = "Biarkan saya pergi memeriksa bagaimana Soroz melakukannya untuk terakhir kalinya, lalu saya pikir kita akan baik-baik saja untuk berangkat lagi.",
  ui_story_1014_10140301_52_dialog_content = "Pergi ke jalan? Jangan bilang kalian menuju ke Twilight?",
  ui_story_1014_10140301_53_dialog_content = "Ceritanya panjang, tapi singkatnya, markas Illumina telah memerintahkan kami ke Twilight untuk melakukan semacam perdagangan.",
  ui_story_1014_10140301_54_dialog_content = "Dalam hal ini, izinkan saya menjadi pemandu Anda! Saya tahu beberapa jalan pintas yang bagus.",
  ui_story_1014_10140301_55_dialog_content = "Selain itu, saya juga tidak buruk dalam berurusan dengan Eclipsites. Saya bisa menangani apa pun yang muncul di sepanjang jalan.",
  ui_story_1014_10140301_56_dialog_content = "Itu akan sangat membantu!",
  ui_story_1014_10140301_57_dialog_content = "Hmm…",
  ui_story_1014_10140301_58_dialog_content = "Bagaimana penampilan Colossus?",
  ui_story_1014_10140301_59_dialog_content = "Yah, sepertinya tidak ada masalah besar secara keseluruhan. Saya pikir kita bisa bersiap-siap untuk pergi.",
  ui_story_1014_10140301_60_dialog_content = "A-Bagaimana dengan pintunya?",
  ui_story_1014_10140301_61_dialog_content = "Jangan khawatir, Sean, pintunya baik-baik saja.",
  ui_story_1014_10140301_62_dialog_content = "Fiuh... Itu melegakan. Aku bisa bernapas lagi!",
  ui_story_1014_10140301_63_dialog_content = "<color=#e8d9bb>Grrk...</color>",
  ui_story_1014_10140301_64_dialog_content = "...?! Apa yang terjadi?",
  ui_story_1014_10140301_65_dialog_content = "Lagi?!",
  ui_story_1014_10140301_66_dialog_content = "<anim type=Shake><size=45>Gahhh!!!</size></anim>",
  ui_story_1014_10140301_67_dialog_content = "Betapa baiknya Anda melayani diri sendiri di atas piring perak!",
  ui_story_1014_10140301_68_dialog_content = "Yah, jika ada pengunjung, sebaiknya aku mulai bersih-bersih!",
  ui_story_1014_10140402_1_dialog_content = "Hyaah!",
  ui_story_1014_10140402_2_dialog_content = "Itu harus melakukannya.",
  ui_story_1014_10140402_3_dialog_content = "Harus kuakui aku meremehkanmu saat di pusat medis Illumina!",
  ui_story_1014_10140402_4_dialog_content = "Hehe, sekarang kita akhirnya bisa berangkat.",
  ui_story_1014_10140402_5_dialog_content = "Omong-omong, jika kantor pusat yang mengirimmu untuk berdagang...",
  ui_story_1014_10140402_6_dialog_content = "Saya harus menghubungi orang yang bertanggung jawab di sini sebelumnya.",
  ui_story_1014_10140402_7_dialog_content = "Omong-omong, aku tidak bermaksud meragukanmu!",
  ui_story_1014_10140402_8_dialog_content = "Hanya saja Twilight cukup mewaspadai orang luar.",
  ui_story_1014_10140402_9_dialog_content = "Jika saya memberi tahu mereka sebelumnya, itu akan membuat masuk dan yang lainnya lebih lancar.",
  ui_story_1014_10140402_10_dialog_content = "Ah, begitu. Terima kasih, kalau begitu.",
  ui_story_1014_10140402_11_dialog_content = "<color=#e8d9bb>Di tempat lain, di jembatan</color>",
  ui_story_1014_10140402_12_dialog_content = "(Hm... Dia benar-benar terlihat lebih kuat dari sebelumnya.)",
  ui_story_1014_10140402_13_dialog_content = "Mengamati Sean, Yingel?",
  ui_story_1014_10140402_14_dialog_content = "Axelia? K-Kamu seharusnya tidak muncul begitu saja di belakang seseorang! Ini benar-benar mengerikan ...",
  ui_story_1014_10140402_15_dialog_content = "Oh maafkan saya!",
  ui_story_1014_10140402_16_dialog_content = "Hanya baik untuk bergerak sedikit setelah istirahat.",
  ui_story_1014_10140402_17_dialog_content = "Itu membuat saya sedikit bernostalgia mengingat kami bertiga dulu, berlatih bersama di <color=#FFB400>Program Fosfor</color>.",
  ui_story_1014_10140402_18_dialog_content = "Ini baru lima tahun, namun saya sudah melupakan hampir semua yang terjadi saat itu.",
  ui_story_1014_10140402_19_dialog_content = "Karena pikiranmu selalu dipenuhi dengan segala macam perintah.",
  ui_story_1014_10140402_20_dialog_content = "Kau salah bicara, Yingel...",
  ui_story_1014_10140402_21_dialog_content = "Tapi mungkin ini salah satu kelebihan saya.",
  ui_story_1014_10140402_22_dialog_content = "Kita semua, termasuk Sean, berada dalam peran yang paling kita kuasai.",
  ui_story_1014_10140402_23_dialog_content = "Hmph, bahkan penolakan itu?",
  ui_story_1014_10140402_24_dialog_content = "... Meskipun saya tidak dapat menyangkal dia tampaknya menyukainya.",
  ui_story_1014_10140402_25_dialog_content = "Maaf membuat semua orang menunggu! Kami akhirnya baik untuk kembali ke jalur!",
  ui_story_1014_10140402_26_dialog_content = "Pasukan Illumina di Twilight sedang menunggu untuk menyambut kalian semua!",
  ui_story_1014_10140402_27_dialog_content = "?!",
  ui_story_1014_10140402_28_dialog_content = "Axelia?! Anda sudah bangun!",
  ui_story_1014_10140402_29_dialog_content = "Er, apakah kalian hanya menonton saya berurusan dengan Eclipsites itu?",
  ui_story_1014_10140402_30_dialog_content = "Benar.",
  ui_story_1014_10140402_31_dialog_content = "Bagaimana menurutmu? Bukankah aku benar-benar lebih hebat? Belum lagi jauh lebih kuat daripada saat kita di markas?",
  ui_story_1014_10140402_32_dialog_content = "Mau sparing ronde? Mari kita lihat siapa yang menang kali ini!",
  ui_story_1014_10140402_33_dialog_content = "Tidak, terima kasih.",
  ui_story_1014_10140402_34_dialog_content = "Omong-omong, Anda tampaknya memiliki empat robot asing di sebelah Anda?",
  ui_story_1014_10140402_35_dialog_content = "Mereka adalah Trio Kubik.",
  ui_story_1014_10140402_36_dialog_content = "Er, oke, tapi ada empat—",
  ui_story_1014_10140402_37_dialog_content = "Pria kecil keempat hanya membantu saya mengangkat lengan baju.",
  ui_story_1014_10140402_38_dialog_content = "Aneh sekali! Namun mengapa tidak?!",
  ui_story_1014_10140402_39_dialog_content = "Pokoknya Sean, Axelia adalah apa yang akan kami tawarkan sebagai gantinya selama perdagangan.",
  ui_story_1014_10140402_40_dialog_content = "Jangan membuatnya menggunakan terlalu banyak energinya saat ini.",
  ui_story_1014_10140402_41_dialog_content = "Benarkah?!",
  ui_story_1014_10140402_42_dialog_content = "Apa itu membuatku menjadi senior Axelia?!",
  ui_story_1014_10140402_43_dialog_content = "Apakah Anda memiliki sesuatu yang ingin Anda tanyakan kepada saya?",
  ui_story_1014_10140402_44_dialog_content = "Yah, saya bertanya-tanya tentang struktur militer Twilight saat ini.",
  ui_story_1014_10140402_45_dialog_content = "Um, yah, aku lebih seperti prajurit kaki, jadi...",
  ui_story_1014_10140402_46_dialog_content = "Kalau begitu, apakah ada jenis Eclipsites khusus di sekitar Twilight?",
  ui_story_1014_10140402_47_dialog_content = "Eh, sebenarnya aku tidak terlalu yakin...",
  ui_story_1014_10140402_48_dialog_content = "Namun, jangan ragu untuk menanyakan hal lain kepada saya! Seperti tempat makanan terbaik di Twilight, atau sejarahnya, atau tempat pemandangan terbaik...",
  ui_story_1014_10140402_49_dialog_content = "Panggil ke bawah, maukah kamu...",
  ui_story_1014_10140501_1_dialog_content = "<color=#e8d9bb>Pinggiran Senja</color>",
  ui_story_1014_10140501_2_dialog_content = "Lady Carleen, laporan patroli sebelumnya menunjukkan bahwa Twilight ada di depan.",
  ui_story_1014_10140501_3_dialog_content = "Leo dan yang lainnya akan segera hadir untuk menyambut kami juga. Bersiaplah untuk mendarat, PlayerName.",
  ui_story_1014_10140501_4_dialog_content = "<color=#e8d9bb>Duarr...</color>",
  ui_story_1014_10140501_5_dialog_content = "...?! Apa yang terjadi?",
  ui_story_1014_10140501_6_dialog_content = "Sebuah ledakan.",
  ui_story_1014_10140501_7_dialog_content = "Axelia, kembalilah ke ruang stasismu. Ada kekacauan di luar sana.",
  ui_story_1014_10140501_8_dialog_content = "Tapi ini hanya jenis waktu yang seharusnya saya butuhkan.",
  ui_story_1014_10140501_9_dialog_content = "Sean, apa yang terjadi di luar?",
  ui_story_1014_10140501_10_dialog_content = "Tenang, semuanya. Semuanya baik baik saja.",
  ui_story_1014_10140501_11_dialog_content = "Kami hanya dikelilingi oleh beberapa Eclipsites yang mengganggu.",
  ui_story_1014_10140501_12_dialog_content = "Tapi... kenapa semua orang di tanah tidak bergerak?",
  ui_story_1014_10140501_13_dialog_content = "Mereka semua melihat sesuatu.",
  ui_story_1014_10140501_14_dialog_content = "Saya yakin itu PlayerNameitu Colossus!",
  ui_story_1014_10140501_15_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_1014_10140501_16_dialog_content = "Ada yang salah.",
  ui_story_1014_10140501_17_dialog_content = "Cepat! Temukan tempat untuk mendarat, PlayerName.",
  ui_story_1014_10140501_18_dialog_content = "A-Baiklah! Duduklah, semuanya!",
  ui_story_1014_10140501_19_dialog_content = "Yah, ada beberapa cegukan di sepanjang jalan, tapi kami berhasil. Selamat datang di Senja!",
  ui_story_1014_10140501_20_dialog_content = "Terletak di perbatasan Astra, memiliki iklim yang menyenangkan, gaya hidup sederhana dan tradisional—",
  ui_story_1014_10140501_21_dialog_content = "Keluar dari jalan! Pindahkan! Ayo, biarkan aku lewat...",
  ui_story_1014_10140501_22_dialog_content = "Batuk, batuk—Betapa banyak debunya!",
  ui_story_1014_10140501_23_dialog_content = "Hahaha... Ya, itu. Itu terjadi, kadang-kadang.",
  ui_story_1014_10140501_24_dialog_content = "Halo, bolehkah saya bertanya kemana tujuan kalian? Ada yang bisa saya bantu?",
  ui_story_1014_10140501_25_dialog_content = "Apakah Twilight masih sangat jauh dari sini?",
  ui_story_1014_10140501_26_dialog_content = "Kami berada di pinggiran kota sekarang! Kalian... tidak boleh dari sekitar sini.",
  ui_story_1014_10140501_27_dialog_content = "Baiklah, terima kasih!",
  ui_story_1014_10140501_28_dialog_content = "Tunggu sebentar! Jika Anda juga akan pergi ke Twilight, Anda sebaiknya ikut bersama kami.",
  ui_story_1014_10140501_29_dialog_content = "Maaf, tapi kami tidak punya banyak waktu tersisa.",
  ui_story_1014_10140501_30_dialog_content = "Saya sangat menyarankan agar Anda mencari tempat berlindung, dengan cepat.",
  ui_story_1014_10140501_31_dialog_content = "Tempat berlindung?",
  ui_story_1014_10140501_32_dialog_content = "Anda lihat bagaimana langit menjadi warna yang lucu? Itu pertanda pasti bahwa an <color=#FFB400>Badai aurora</color> datang!",
  ui_story_1014_10140501_33_dialog_content = "Jika Anda tidak segera menemukan tempat berlindung, setelah tiba, tidak ada yang bisa menyelamatkan Anda.",
  ui_story_1014_10140501_34_dialog_content = "Badai Aurora...?",
  ui_story_1014_10140501_35_dialog_content = "Saya hanya pernah membaca tentang ini di buku-buku. Bahkan Northland, dengan seringnya aurora, jarang melihat fenomena seperti itu.",
  ui_story_1014_10140501_36_dialog_content = "Hanya penduduk yang tinggal di zona perbatasan selama beberapa generasi yang menyaksikannya.",
  ui_story_1014_10140501_37_dialog_content = "<color=#e8d9bb>Bip — Bip —</color>",
  ui_story_1014_10140501_38_dialog_content = "Itu sirene peringatan Twilight!",
  ui_story_1014_10140501_39_dialog_content = "Dengar, semuanya. Dengan kecepatan Anda, tidak mungkin Anda mencapai Twilight hari ini.",
  ui_story_1014_10140501_40_dialog_content = "Saya Sean, perwira junior pasukan Illumina yang ditempatkan di Twilight. Jika Anda akan mempercayai saya,",
  ui_story_1014_10140501_41_dialog_content = "Saya bisa memimpin semua orang untuk berlindung di parit darurat!",
  ui_story_1014_10140501_42_dialog_content = "Sangat percaya padamu? Kalian hanya sekelompok anak-anak!",
  ui_story_1014_10140501_43_dialog_content = "Ya, tapi kita tidak punya cara untuk membela diri, kan? Jika kita diserang oleh Eclipsites lagi...",
  ui_story_1014_10140501_44_dialog_content = "Gerhana? Maksudmu... apakah klanmu juga...",
  ui_story_1014_10140501_45_dialog_content = "... Ya. Jika terus seperti ini, jumlah klan yang bertahan di sekitar sini akan terus berkurang.",
  ui_story_1014_10140501_46_dialog_content = "Menuju Twilight adalah kesempatan terbaik kita untuk bertahan hidup.",
  ui_story_1014_10140501_47_dialog_content = "Berhenti mengatakan omong kosong padanya. Kami hanya akan tinggal di sana sebentar.",
  ui_story_1014_10140501_48_dialog_content = "Hari itu akan tiba ketika kita bisa pulang ...",
  ui_story_1014_10140501_49_dialog_content = "<color=#e8d9bb>Buk, Buk, Buk</color>",
  ui_story_1014_10140501_50_dialog_content = "Suara-suara datang dari tanah kali ini.",
  ui_story_1014_10140501_51_dialog_content = "Graaaaaah!",
  ui_story_1014_10140501_52_dialog_content = "<anim type=Shake><size=45>GRAAAAAH!!!</size></anim>",
  ui_story_1014_10140501_53_dialog_content = "Eclipsites... Eclipsites akan datang!",
  ui_story_1014_10140501_54_dialog_content = "Apakah mereka mengatur waktu serangan mereka bertepatan dengan Aurorastorm? Mereka memiliki sedikit kemampuan strategis, tampaknya.",
  ui_story_1014_10140501_55_dialog_content = "Beretta.",
  ui_story_1014_10140501_56_dialog_content = "Ya, Nyonya Carleen!",
  ui_story_1014_10140501_57_dialog_content = "Biarkan saya menutupi retret semua orang!",
  ui_story_1014_10140501_58_dialog_content = "Penghindaran bukanlah strategi jangka panjang yang layak.",
  ui_story_1014_10140501_59_dialog_content = "Tolong, izinkan saya untuk bertarung. Kalau tidak, saya harus mengambil tindakan ekstrim.",
  ui_story_1014_10140501_60_dialog_content = "Jangan khawatir tentang melawan mereka dulu!",
  ui_story_1014_10140501_61_dialog_content = "Apa yang akan terjadi pada warga sipil tak berdaya ini jika kita menyerang?",
  ui_story_1014_10140501_62_dialog_content = "Saya percaya bahwa saya dapat melindungi mereka pada saat yang sama.",
  ui_story_1014_10140501_63_dialog_content = "Tolong jangan khawatir. Tidak butuh waktu lama.",
  ui_story_1014_10140501_64_dialog_content = "Aku berkata tidak!!",
  ui_story_1014_10140501_65_dialog_content = "Beretta, Axelia, kalian berdua berpisah.",
  ui_story_1014_10140501_66_dialog_content = "Beretta, Carleen, Sean—kalian pergi bawa warga sipil ke tempat aman.",
  ui_story_1014_10140501_67_dialog_content = "Axelia, Yingel, Vice—aku ikut denganmu. Kami akan membawa pertempuran ke Eclipsites!",
  ui_story_1014_10140501_68_dialog_content = "Aku paham.",
  ui_story_1014_10140501_69_dialog_content = "Tidak perlu melelahkan diri sendiri.",
  ui_story_1014_10140501_70_dialog_content = "Serahkan Eclipsites ini ke Ironthorn Knights.",
  ui_story_1014_10140501_71_dialog_content = "Maafkan kedatangan kami yang terlambat; Saya senang semua orang baik-baik saja.",
  ui_story_1014_10140501_72_dialog_content = "Waktu yang tepat, Leo! Tolong bantu kami melawan Eclipsites ini sebelum mengawal kami!",
  ui_story_1014_10140501_73_dialog_content = "Tentu saja. Karena pertempuran sudah dekat, mohon maafkan saya karena gagal turun, Lady Carleen.",
  ui_story_1014_10140501_74_dialog_content = "Sepele. Anda tidak perlu menunjukkan kesetiaan pada etiket, hanya pada nama Anda.",
  ui_story_1014_10140501_75_dialog_content = "Ha ha ha! Yah, aku menjadi ksatria untuk Twilight, bukan namaku!",
  ui_story_1014_10140501_76_dialog_content = "Ksatria, berikan senjata!",
  ui_story_1014_10140501_77_dialog_content = "Saya hanya membutuhkan satu hal dari Anda dalam pertarungan ini!",
  ui_story_1014_10140501_78_dialog_content = "Berjuang untuk memusnahkan semua Eclipsites sampai napas terakhir Anda.",
  ui_story_1014_10140501_79_dialog_content = "MENYERANG!!!",
  ui_story_1014_10140602_1_dialog_content = "Tetap dalam formasi. Jangan berpencar.",
  ui_story_1014_10140602_2_dialog_content = "Prioritaskan musuh di sayap samping.",
  ui_story_1014_10140602_3_dialog_content = "Siap, Pak!",
  ui_story_1014_10140602_4_dialog_content = "Masih ada lagi! Kelompok besar Eclipsites lainnya terus maju!",
  ui_story_1014_10140602_5_dialog_content = "Kita akan kelelahan bertarung seperti ini. Haruskah kita mundur?",
  ui_story_1014_10140602_6_dialog_content = "Oh, saya melihat mereka. Hmm, ada beberapa.",
  ui_story_1014_10140602_7_dialog_content = "Kalau begitu, kita...",
  ui_story_1014_10140602_8_dialog_content = "Semua ksatria! Bongkar dan bersiaplah untuk penyerangan!",
  ui_story_1014_10140602_9_dialog_content = "Siap, Pak!",
  ui_story_1014_10140602_10_dialog_content = "Err, penyerangan? Sekarang?",
  ui_story_1014_10140602_11_dialog_content = "Tentunya serangan langsung dengan banyak Eclipsites ini bukanlah ide terbaik...",
  ui_story_1014_10140602_12_dialog_content = "Kalau begitu, kalian orang luar bisa menunggu di sini. Tunggu dan tonton.",
  ui_story_1014_10140602_13_dialog_content = "Semua ksatria! Formasi baji, dua regu. Satu dengan saya, satu dengan deputi.",
  ui_story_1014_10140602_14_dialog_content = "Berpisah sekali melalui garis musuh.",
  ui_story_1014_10140602_15_dialog_content = "Sekarang, perhatikan spanduk di tanganku.",
  ui_story_1014_10140602_16_dialog_content = "Ksatria Ironthorn, BIAYA!",
  ui_story_1014_10140602_17_dialog_content = "<size=50>TOLONG!!</size>",
  ui_story_1014_10140602_18_dialog_content = "Mereka benar-benar memburu gerombolan Eclipsites itu?! Bukankah itu sedikit... gegabah?",
  ui_story_1014_10140602_19_dialog_content = "Belum tentu. Hanya melihat.",
  ui_story_1014_10140602_20_dialog_content = "Serangan mereka berjalan lebih lancar dari yang diharapkan.",
  ui_story_1014_10140602_21_dialog_content = "Nyata! Bahkan banyak Eclipsites tidak bisa menahan para ksatria!",
  ui_story_1014_10140602_22_dialog_content = "Mereka memotongnya dengan presisi bedah...",
  ui_story_1014_10140602_23_dialog_content = "Bagaimana mereka melakukannya?!",
  ui_story_1014_10140602_24_dialog_content = "Saya pikir saya agak mengerti. Kata-kata Beretta sangat tepat.",
  ui_story_1014_10140602_25_dialog_content = "Mereka benar-benar seperti pedang.",
  ui_story_1014_10140602_26_dialog_content = "Saat menyembelih bangkai, tidak ada yang berpikir dua kali tentang berat pisau dibandingkan dengan hewan.",
  ui_story_1014_10140602_27_dialog_content = "Selama bilahnya cukup tajam, itu akan menembus.",
  ui_story_1014_10140602_28_dialog_content = "Memotong...",
  ui_story_1014_10140602_29_dialog_content = "Lihat, Leo kembali dengan setengah dari mereka.",
  ui_story_1014_10140602_30_dialog_content = "<color=#e8d9bb>Klip-klop, klip-klop</color>",
  ui_story_1014_10140602_31_dialog_content = "Bagaimana menurutmu, orang luar? Lagipula bukan ide yang buruk, ya?",
  ui_story_1014_10140602_32_dialog_content = "Perang bukan sekadar permainan angka. Kekuatan yang sama dapat digunakan secara berbeda dengan taktik yang berbeda.",
  ui_story_1014_10140602_33_dialog_content = "Di sini, di sepanjang perbatasan terpencil, kami tidak memiliki kekuatan untuk berbenturan langsung dengan Eclipsites.",
  ui_story_1014_10140602_34_dialog_content = "Mereka tidak mengerti strategi militer. Namun, kami melakukannya, dan ini adalah keuntungan kami.",
  ui_story_1014_10140602_35_dialog_content = "Jadi bagaimana Anda menilai bahwa ini adalah waktu yang tepat untuk penyerangan?",
  ui_story_1014_10140602_36_dialog_content = "Karena saya mengenal jenis Eclipsite ini dengan baik.",
  ui_story_1014_10140602_37_dialog_content = "Mereka agresif dan pandai mengalahkan dengan jumlah yang banyak. Tapi kelemahan mereka jelas: mereka tidak mahir melawan serangan mendadak.",
  ui_story_1014_10140602_38_dialog_content = "Jadi ketika menghadapi mereka, terlepas dari pihak mana yang memiliki lebih banyak kekuatan, kita harus mengambil inisiatif dan menyerang.",
  ui_story_1014_10140602_39_dialog_content = "Serangan langsung kami memusatkan kekuatan kami ke dalam satu garis, yang memotong dan melemahkan musuh.",
  ui_story_1014_10140602_40_dialog_content = "Serangan itu juga memecah formasi Eclipsites. Semakin tersebar musuh, semakin baik bagi kita.",
  ui_story_1014_10140602_41_dialog_content = "Kamu melihat? Saya meninggalkan setengah kekuatan saya di tengah-tengah mereka.",
  ui_story_1014_10140602_42_dialog_content = "Mereka akan berurusan dengan Eclipsites lainnya, menciptakan lebih banyak kekacauan dan kebingungan dengan membelah medan perang sambil menghabisi sekelompok orang yang tersesat.",
  ui_story_1014_10140602_43_dialog_content = "Luar biasa! Sepertinya ada lebih banyak yang harus dipertimbangkan daripada yang saya pikirkan ketika harus melawan Eclipsites.",
  ui_story_1014_10140602_44_dialog_content = "Kami jelas kalah jumlah dengan Eclipsites, namun kalian seimbang di medan perang...",
  ui_story_1014_10140602_45_dialog_content = "Itulah mengapa saya mengatakan bahwa strategi lebih penting daripada kekuasaan.",
  ui_story_1014_10140602_46_dialog_content = "Tetapi Anda, orang luar, memiliki bakat untuk menemukan Eclipsites sebelum saya melakukannya.",
  ui_story_1014_10140602_47_dialog_content = "Perasaan medan perang semacam itu jarang terjadi.",
  ui_story_1014_10140602_48_dialog_content = "Sebenarnya bukan apa-apa untuk menulis tentang rumah.",
  ui_story_1014_10140602_49_dialog_content = "Aku bukan Aurorian sepertimu. Saya seorang Caelestite.",
  ui_story_1014_10140602_50_dialog_content = "Seorang Caelestite? Ras dongeng itu?",
  ui_story_1014_10140602_51_dialog_content = "Hahaha, betapa mempesona! Karakter dari buku saya telah hidup kembali!",
  ui_story_1014_10140602_52_dialog_content = "Jadi, Caelestite, gunakan akal sehatmu dan katakan padaku: Apa yang harus kita lakukan selanjutnya?",
  ui_story_1014_10140602_53_dialog_content = "Um... Luncurkan serangan susulan, sebelum musuh berkumpul kembali?",
  ui_story_1014_10140602_54_dialog_content = "Salah! Kami menarik diri.",
  ui_story_1014_10140602_55_dialog_content = "Hah? Tapi kenapa? Kami baru saja membuat keuntungan!",
  ui_story_1014_10140602_56_dialog_content = "Anda tidak bisa hanya menatap medan perang di depan Anda.",
  ui_story_1014_10140602_57_dialog_content = "Tujuan utama kami adalah mencegat semua Eclipsites. Apa yang kita lakukan sekarang tidak cukup.",
  ui_story_1014_10140602_58_dialog_content = "Di belakang mereka terbentang medan berbahaya dengan lintasan berbahaya. Pertempuran pasti akan bergeser ke sana.",
  ui_story_1014_10140602_59_dialog_content = "Kita perlu mempersiapkan diri terlebih dahulu.",
  ui_story_1014_10140602_60_dialog_content = "Maukah Anda membantu kami, orang luar?",
  ui_story_1014_10140602_61_dialog_content = "Tentu saja! Saya berharap memiliki kesempatan untuk mengamati taktik Anda lagi.",
  ui_story_1014_10140602_62_dialog_content = "Yah, bagaimanapun juga kita akan berurusan dengan Eclipsites.",
  ui_story_1014_10140602_63_dialog_content = "Dengar, membantu atau tidak, tidak ada bedanya bagi kami. Tapi saya punya pertanyaan...",
  ui_story_1014_10140602_64_dialog_content = "Adakah yang pernah melihat Sean yang tolol itu di mana saja?",
  ui_story_1014_10140602_65_dialog_content = "<size=45>Mati!!</size>",
  ui_story_1014_10140602_66_dialog_content = "Berapa banyak dari kalian yang tersisa?!",
  ui_story_1014_10140602_67_dialog_content = "Saya tidak pernah berpikir Anda bisa melawan ini dengan baik, prajurit Illumina.",
  ui_story_1014_10140602_68_dialog_content = "Hah? Baiklah, terima kasih!",
  ui_story_1014_10140602_69_dialog_content = "Anda menarik bahkan di medan perang Ironthorn Knights.",
  ui_story_1014_10140602_70_dialog_content = "Pejuang yang luar biasa seperti dirimu pasti tidak kekurangan pujian.",
  ui_story_1014_10140602_71_dialog_content = "Uh, be-benarkah? Saya tidak sering mendapat pujian.",
  ui_story_1014_10140602_72_dialog_content = "Namun, mengapa tepatnya Anda ada di sini? Saya pikir Kapten menyuruh Anda menunggu di sana?",
  ui_story_1014_10140602_73_dialog_content = "Dia melakukan?!",
  ui_story_1014_10140602_74_dialog_content = "Lihat, semua temanmu masih di sana.",
  ui_story_1014_10140602_75_dialog_content = "Ohhh, aku ingat sekarang. Kapten Leo mengatakan sesuatu tentang orang luar yang tetap tinggal.",
  ui_story_1014_10140602_76_dialog_content = "Tapi aku bukan orang luar! Saya tinggal di sini di Twilight juga.",
  ui_story_1014_10140602_77_dialog_content = "...",
  ui_story_1014_10140602_78_dialog_content = "Adakah yang pernah memberi tahu Anda bahwa Anda bukan alat paling tajam di gudang?",
  ui_story_1014_10140602_79_dialog_content = "Ya!",
  ui_story_1014_10140602_80_dialog_content = "Anda tahu itu BUKAN pujian ...?",
  ui_story_1014_10140602_81_dialog_content = "Sudahlah. Terima kasih kepada Anda, seluruh situasi pertempuran jauh lebih jelas.",
  ui_story_1014_10140602_82_dialog_content = "Arahan misi awal kami adalah menangani Eclipsites. Melihat keadaan saat ini, seharusnya tidak terlalu sulit untuk menghapusnya sepenuhnya.",
  ui_story_1014_10140602_83_dialog_content = "Bagus! Tidak bisa membiarkan salah satu dari mereka pergi!",
  ui_story_1014_10140602_84_dialog_content = "Anda tampak penuh gairah. Itu hal yang bagus.",
  ui_story_1014_10140602_85_dialog_content = "Anda tahu, saya sudah lama mendengar cerita tentang Ironthorn Knights dan Kapten Leo.",
  ui_story_1014_10140602_86_dialog_content = "Memiliki kesempatan untuk bertarung berdampingan dengan kelompok heroik seperti itu benar-benar membuat darahku terpompa!",
  ui_story_1014_10140602_87_dialog_content = "Sembunyikan busur silang ini di rerumputan panjang. Persiapan kami hampir selesai.",
  ui_story_1014_10140602_88_dialog_content = "Sempurna, mereka kembali.",
  ui_story_1014_10140602_89_dialog_content = "<color=#e8d9bb>Klip-klop, klip-klop</color>",
  ui_story_1014_10140602_90_dialog_content = "Kapten.",
  ui_story_1014_10140602_91_dialog_content = "Kerja bagus, dan dieksekusi lebih elegan dari yang saya bayangkan.",
  ui_story_1014_10140602_92_dialog_content = "Kali ini, kami mendapat dukungan dari pejuang Illumina yang baik ini untuk berterima kasih untuk itu.",
  ui_story_1014_10140602_93_dialog_content = "Oh, ayolah, itu bukan apa-apa...",
  ui_story_1014_10140602_94_dialog_content = "Mmhmm, saya melihat. Pertarungan sengit seperti itu tidak bisa luput dari perhatian.",
  ui_story_1014_10140602_95_dialog_content = "Anda seorang petugas Illumina?",
  ui_story_1014_10140602_96_dialog_content = "Ya! Saya letnan dua Sean, dari Twilight's Garrison!",
  ui_story_1014_10140602_97_dialog_content = "Garnisun Twilight, ya. Aku tidak percaya aku tidak pernah tahu kita memiliki pejuang pemberani di sebelah.",
  ui_story_1014_10140602_98_dialog_content = "Nah, mengapa Anda? Aku hampir tidak luar biasa di antara rekan-rekanku, dan aku sebenarnya tidak memiliki banyak pengalaman medan perang.",
  ui_story_1014_10140602_99_dialog_content = "Tentu saja orang seperti Anda tidak akan pernah mendengar tentang saya, Kapten Leo.",
  ui_story_1014_10140602_100_dialog_content = "Sepertinya Anda mengenal saya.",
  ui_story_1014_10140602_101_dialog_content = "Tentu saja!! Siapa di Twilight yang belum pernah mendengar tentang tindakan gagah berani dari Ironthorn Knights!",
  ui_story_1014_10140602_102_dialog_content = "Nah kalau begitu... nak, maukah kamu bergabung dengan kami?",
  ui_story_1014_10140602_103_dialog_content = "Hah?",
  ui_story_1014_10140602_104_dialog_content = "Pejuang yang luar biasa harus menunjukkan nilai mereka di medan perang, tidak merana di barak menghitung hari yang berlalu.",
  ui_story_1014_10140602_105_dialog_content = "Bergabunglah dengan kami, dan saya akan membuat nama Anda dikenal di seluruh Twilight dalam waktu kurang dari sebulan.",
  ui_story_1014_10140602_106_dialog_content = "Namun…",
  ui_story_1014_10140602_107_dialog_content = "Ahem. Kapten Leo, undangan yang keterlaluan seperti itu jelas bertentangan dengan protokol.",
  ui_story_1014_10140602_108_dialog_content = "Paling tidak, cobalah mengubah musuh Anda dengan lebih bijaksana.",
  ui_story_1014_10140602_109_dialog_content = "Ahaha, permintaan maafku, meski aku tidak bisa melihat apa yang memalukan tentang ini.",
  ui_story_1014_10140602_110_dialog_content = "Lumopolis dan Illumina hanyalah tempat untuk beristirahat, musuh utama kita adalah Eclipsites.",
  ui_story_1014_10140602_111_dialog_content = "Saya hanya ingin anak ini memiliki tempat yang lebih baik untuk menelepon ke rumah.",
  ui_story_1014_10140602_112_dialog_content = "Tentu saja, Anda rindu, juga mengesankan. Jika Anda ingin bergabung dengan kami, Ironthorn Knights akan siap menyambut Anda.",
  ui_story_1014_10140602_113_dialog_content = "Kamu... Aku tidak menyangka bahwa Kapten dari Ironthorn Knights adalah seorang master dari ajakan.",
  ui_story_1014_10140602_114_dialog_content = "Anda harus mengundurkan diri dan menjadi politisi di Kota Gannon. Saya juga ingin Anda memiliki tempat yang lebih baik untuk menelepon ke rumah.",
  ui_story_1014_10140602_115_dialog_content = "Politisi, katamu? Bukan pilihan yang buruk. Saya akan memikirkannya.",
  ui_story_1014_10140602_116_dialog_content = "Saya lelah.",
  ui_story_1014_10140602_117_dialog_content = "Hmm?",
  ui_story_1014_10140602_118_dialog_content = "Ya—wn, aku bilang aku lelah.",
  ui_story_1014_10140602_119_dialog_content = "Betulkah? Sekarang juga...?",
  ui_story_1014_10140602_120_dialog_content = "Sudahlah, tidak ada yang bisa dilakukan tentang itu. Kembalilah ke ruang stasis dan istirahatlah, Axelia.",
  ui_story_1014_10140602_121_dialog_content = "Tentu. Aku akan mendukungmu.",
  ui_story_1014_10140602_122_dialog_content = "Aku akan langsung kembali begitu aku bangun.",
  ui_story_1014_10140602_123_dialog_content = "Jangan khawatir tentang itu. Selamat beristirahat.",
  ui_story_1014_10140602_124_dialog_content = "Awasi ruang stasis, PlayerName.",
  ui_story_1014_10140602_125_dialog_content = "Akan melakukan!",
  ui_story_1014_10140602_126_dialog_content = "Dia menghilang begitu saja ke dalam kotak itu!",
  ui_story_1014_10140602_127_dialog_content = "Anda orang luar benar-benar memperluas wawasan saya.",
  ui_story_1014_10140602_128_dialog_content = "Kondisi fisik Axelia tidak bagus, jadi dia harus banyak istirahat di ruang stasis.",
  ui_story_1014_10140602_129_dialog_content = "Jadi mengapa Anda membawanya ke tempat yang berbahaya seperti wilayah perbatasan?",
  ui_story_1014_10140602_130_dialog_content = "Karena membawanya ke Twilight dengan selamat adalah inti dari misi ini.",
  ui_story_1014_10140602_131_dialog_content = "Ah, begitu. Nah, dalam hal ini, saya tidak akan mengorek lebih jauh.",
  ui_story_1014_10140602_132_dialog_content = "Cukup obrolan, saya pikir kelompok di sana mulai gelisah.",
  ui_story_1014_10140602_133_dialog_content = "Aku perlu memasang pagar besi di sini sebelum Eclipsites muncul.",
  ui_story_1014_10140602_134_dialog_content = "Kami di sini untuk membantu, jadi apa yang bisa kami lakukan?",
  ui_story_1014_10140602_135_dialog_content = "Terlibat dalam pertempuran saja sudah cukup bagi kami. Tidak perlu melibatkan Anda dalam hal-hal kecil dari bisnis kami, Lady Carleen.",
  ui_story_1014_10140602_136_dialog_content = "Faktanya, mengingat statusmu, aku mungkin harus menyerahkan komando medan perang kepadamu.",
  ui_story_1014_10140602_137_dialog_content = "Hanya saja dalam keadaan sekarang, aku khawatir para ksatria akan kesulitan untuk beradaptasi. Tolong, maafkan saya karena melangkahi otoritas saya.",
  ui_story_1014_10140602_138_dialog_content = "...",
  ui_story_1014_10140602_139_dialog_content = "Perintah harus menjadi milik siapa pun yang paling mampu memimpin semua orang menuju kemenangan. Tidak perlu formalitas seperti itu di sini.",
  ui_story_1014_10140602_140_dialog_content = "Jika kita bebas untuk melakukan sesuka kita, maka kita akan menuju ke timur, untuk membantu menjaga pertahanan.",
  ui_story_1014_10140602_141_dialog_content = "Jika pengamatan saya benar, garis pertahanan di sana relatif lemah.",
  ui_story_1014_10140602_142_dialog_content = "Timur... Anda benar sekali. Kami kekurangan tenaga kerja yang cukup untuk mencakup semua area, dan itu adalah titik lemah kami.",
  ui_story_1014_10140602_143_dialog_content = "Sepertinya Anda memiliki mata yang cukup taktis, Lady Carleen.",
  ui_story_1014_10140602_144_dialog_content = "Meskipun kelahiranku menghalangiku untuk menyandang gelar Komandan Ksatria, jangan salahkan aku sebagai putri Lumopolis belaka.",
  ui_story_1014_10140602_145_dialog_content = "Tidak pernah! Saya percaya atas nama Ksatria Lumopolis.",
  ui_story_1014_10140602_146_dialog_content = "Kami berdua berjuang untuk kemuliaan yang sama.",
  ui_story_1014_10140602_147_dialog_content = "Ini sepertinya area barisan belakang yang aman. Saya pikir Anda harus menyiapkan ruang stasis Axelia di sini, PlayerName.",
  ui_story_1014_10140602_148_dialog_content = "Baiklah.",
  ui_story_1014_10140602_149_dialog_content = "Penempatan Leo membuat garis timur relatif lemah.",
  ui_story_1014_10140602_150_dialog_content = "Kita harus mendukung pasukan pertahanan di sana.",
  ui_story_1014_10140602_151_dialog_content = "Ya, Nyonya Carleen.",
  ui_story_1014_10140602_152_dialog_content = "Anda bersedia bekerja sama dengan perintah Leo, Carleen.",
  ui_story_1014_10140602_153_dialog_content = "Dia memiliki banyak pengalaman komando. Anda telah melihat sendiri betapa mudahnya dia meraih kemenangan, jika perintahnya diikuti.",
  ui_story_1014_10140602_154_dialog_content = "Tapi dia tidak menetapkan tugas khusus untuk kami.",
  ui_story_1014_10140602_155_dialog_content = "Tidak. Dia tidak mau.",
  ui_story_1014_10140602_156_dialog_content = "Hah? Kenapa tidak?",
  ui_story_1014_10140602_157_dialog_content = "Saya merasakan bahwa Leo sengaja menjaga jarak.",
  ui_story_1014_10140602_158_dialog_content = "Dia tidak akan tunduk kepada saya, tetapi dia juga tidak akan memerintah saya.",
  ui_story_1014_10140602_159_dialog_content = "Karena bagaimanapun juga, aku adalah putri Penguasa Kota Lumopolis.",
  ui_story_1014_10140602_160_dialog_content = "Baiklah, tapi saya masih belum begitu mengerti. Itu adalah hal yang buruk?",
  ui_story_1014_10140602_161_dialog_content = "Saya sendiri tidak begitu yakin.",
  ui_story_1014_10140602_162_dialog_content = "Faktanya, saya lebih suka dia hanya seorang pejuang, tanpa etiket atau kowtow.",
  ui_story_1014_10140602_163_dialog_content = "Di perbatasan yang jauh ini, begitu jauh dari apa pun, yang bisa dilihat hanyalah medan perang.",
  ui_story_1014_10140602_164_dialog_content = "Tapi tidak untuknya. Sebaliknya, dia sangat memperhatikan statusku.",
  ui_story_1014_10140602_165_dialog_content = "Dan dia menggunakan jarak di antara kami untuk mengubah \"kesetiaan\" menjadi \"rasa hormat\".",
  ui_story_1014_10140602_166_dialog_content = "Jadi saya akan menghormatinya sebagai imbalan, dan mengikuti perintah taktisnya.",
  ui_story_1014_10140602_167_dialog_content = "Sangat membingungkan. Apakah ini yang mereka sebut perang politik?",
  ui_story_1014_10140602_168_dialog_content = "Sangat tepat.",
  ui_story_1014_10140602_169_dialog_content = "Mungkin inilah tragedi yang mendefinisikan Lumopolis. Kita tidak pernah bisa benar-benar memisahkan diri kita dari politik.",
  ui_story_1014_10140602_170_dialog_content = "<color=#e8d9bb>Gruk—</color>",
  ui_story_1014_10140602_171_dialog_content = "!!!",
  ui_story_1014_10140602_172_dialog_content = "Suara berisik apa itu?",
  ui_story_1014_10140602_173_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1014_10140602_174_dialog_content = "Ada yang menuju kemari!",
  ui_story_1014_10140602_175_dialog_content = "Darkflownya kental. Mungkin ada banyak dari mereka.",
  ui_story_1014_10140602_176_dialog_content = "Dan... sepertinya mereka membawa teman besar!",
  ui_story_1014_10140701_1_dialog_content = "Ironthorn Knights, bersiaplah untuk pertempuran!",
  ui_story_1014_10140701_2_dialog_content = "Tidak ada yang meninggalkan formasi tanpa perintah saya!",
  ui_story_1014_10140701_3_dialog_content = "Siap, Pak!",
  ui_story_1014_10140701_4_dialog_content = "<color=#e8d9bb>Gruk—</color>",
  ui_story_1014_10140701_5_dialog_content = "Jumlah mereka bahkan lebih banyak daripada yang terakhir kali.",
  ui_story_1014_10140701_6_dialog_content = "Aku yakin itu salah satu yang membuat keributan.",
  ui_story_1014_10140701_7_dialog_content = "<color=#FFB400>Cerritus</color>.",
  ui_story_1014_10140701_8_dialog_content = "Cerritus... Lagi...",
  ui_story_1014_10140701_9_dialog_content = "Apa?",
  ui_story_1014_10140701_10_dialog_content = "Sebuah penyimpangan. Eclipsite yang unik. Seseorang dengan kekuatan luar biasa.",
  ui_story_1014_10140701_11_dialog_content = "Ironthorn Knights pernah bentrok dengan itu sebelumnya, tetapi tidak ada pihak yang bisa memastikan kemenangan yang pasti.",
  ui_story_1014_10140701_12_dialog_content = "Adakah peluang untuk menghentikannya kali ini?",
  ui_story_1014_10140701_13_dialog_content = "Ini bukan pertanyaan apakah kita bisa menghentikannya. Kita harus.",
  ui_story_1014_10140701_14_dialog_content = "Jika mereka melewati kita, mereka mencapai Twilight.",
  ui_story_1014_10140701_15_dialog_content = "Tidak ada Ironthorn Knight lain di sekitar untuk membantu menghentikannya.",
  ui_story_1014_10140701_16_dialog_content = "Tunggu! Lihat ke sana! Di depan Eclipsites!",
  ui_story_1014_10140701_17_dialog_content = "Rakyat?! Warga sipil dalam pelarian!",
  ui_story_1014_10140701_18_dialog_content = "Siapapun... Tolong...",
  ui_story_1014_10140701_19_dialog_content = "Aku tidak bisa... berlari lebih lama lagi...",
  ui_story_1014_10140701_20_dialog_content = "Sedikit lebih jauh. D-Hampir sampai... Senja.",
  ui_story_1014_10140701_21_dialog_content = "Akan ada seseorang di sana untuk melindungi kita, saya tahu akan ada.",
  ui_story_1014_10140701_22_dialog_content = "Bisakah kita membuatnya...?",
  ui_story_1014_10140701_23_dialog_content = "Aku bisa mendengarnya... Di belakangku... para monster...",
  ui_story_1014_10140701_24_dialog_content = "Mereka terdengar begitu dekat... Begitu dekat...",
  ui_story_1014_10140701_25_dialog_content = "Benar-benar ada orang! Mereka akan ditangkap!",
  ui_story_1014_10140701_26_dialog_content = "Cepat, untuk menyelamatkan! Pergi sekarang, sebelum terlambat!",
  ui_story_1014_10140701_27_dialog_content = "Tapi, uh, apa yang harus kita lakukan, Kapten Leo?",
  ui_story_1014_10140701_28_dialog_content = "...",
  ui_story_1014_10140701_29_dialog_content = "Kapten Leo?!",
  ui_story_1014_10140701_30_dialog_content = "Ksatria Ironthorn, tetap dalam formasi.",
  ui_story_1014_10140701_31_dialog_content = "<size=45>Apa?!</size>",
  ui_story_1014_10140701_32_dialog_content = "Massa Eclipsite hampir mendekati kita. Melanggar formasi sekarang sama saja dengan bunuh diri.",
  ui_story_1014_10140701_33_dialog_content = "Kita tidak bisa mematahkan formasi.",
  ui_story_1014_10140701_34_dialog_content = "Tapi bagaimana dengan mereka? Yang sedang dikejar sekarang?!",
  ui_story_1014_10140701_35_dialog_content = "Mereka akan ditangkap!",
  ui_story_1014_10140701_36_dialog_content = "Maaf soal itu, tapi kami ksatria, bukan dewa. Kita tidak bisa menyelamatkan semua orang.",
  ui_story_1014_10140701_37_dialog_content = "Kamu...",
  ui_story_1014_10140701_38_dialog_content = "Saya tidak bisa mengambil risiko semua Twilight dikonsumsi oleh banjir Eclipsites untuk beberapa orang yang tersesat, saya juga tidak bisa meminta Ksatria saya mengorbankan diri untuk warga sipil itu.",
  ui_story_1014_10140701_39_dialog_content = "Di sini, di perbatasan, setiap nyawa berharga, dan setiap keputusan penting.",
  ui_story_1014_10140701_40_dialog_content = "Jadi kita hanya dimaksudkan untuk melihat mereka dibunuh oleh Eclipsites?",
  ui_story_1014_10140701_41_dialog_content = "Kemudian pergi, jika Anda memilih untuk tidak menyaksikannya. Atau bertindak sendiri.",
  ui_story_1014_10140701_42_dialog_content = "Lagi pula, Anda bukan Ironthorn Knights dan bukan milik saya untuk diperintah.",
  ui_story_1014_10140701_43_dialog_content = "...",
  ui_story_1014_10140701_44_dialog_content = "Baik. Kalau begitu tolong, pertahankan, dan jangan biarkan apa pun terjadi pada Axelia!",
  ui_story_1014_10140701_45_dialog_content = "Kami akan melakukan apa yang Anda pilih untuk tidak!",
  ui_story_1014_10140701_46_dialog_content = "<size=40>Aaaaah!</size>",
  ui_story_1014_10140701_47_dialog_content = "Saudara laki-laki!! Apa yang terjadi?!",
  ui_story_1014_10140701_48_dialog_content = "Monster tepat di belakangku! A...kakiku sakit...",
  ui_story_1014_10140701_49_dialog_content = "Anda harus lari! Lari sekarang!",
  ui_story_1014_10140701_50_dialog_content = "Tidak! aku tidak bisa meninggalkanmu...",
  ui_story_1014_10140701_51_dialog_content = "<size=40>Aduh!!</size>",
  ui_story_1014_10140701_52_dialog_content = "<size=40>Enyahlah!!</size>",
  ui_story_1014_10140701_53_dialog_content = "Hah? Apakah ini...",
  ui_story_1014_10140701_54_dialog_content = "Masih ada lagi di sini, Carleen!",
  ui_story_1014_10140701_55_dialog_content = "Aku paham.",
  ui_story_1014_10140701_56_dialog_content = "Tinggalkan yang di sana untukku!",
  ui_story_1014_10140701_57_dialog_content = "Setiap orang! Ikuti aku! Bertahanlah di sana sedikit lebih lama. Kami akan membawamu ke tempat yang aman!",
  ui_story_1014_10140701_58_dialog_content = "Hore! Mereka datang untuk kita!",
  ui_story_1014_10140701_59_dialog_content = "Cepat! Ikuti mereka!",
  ui_story_1014_10140701_60_dialog_content = "Tidak ada waktu bagi kita untuk berada di belakang Ironthorn Knights.",
  ui_story_1014_10140701_61_dialog_content = "Mereka hampir mengenai kita! Siap-siap!",
  ui_story_1014_10140701_62_dialog_content = "Sudah? Bagaimana dengan warga sipil?!",
  ui_story_1014_10140701_63_dialog_content = "Buat mereka tetap bersama!",
  ui_story_1014_10140701_64_dialog_content = "Saya akan melakukan semua yang saya bisa untuk melindungi mereka!",
  ui_story_1014_10140701_65_dialog_content = "Siap-siap. Mereka disini.",
  ui_story_1014_10140701_66_dialog_content = "<color=#e8d9bb>Gemuruh — Gemuruh — Gemuruh—</color>",
  ui_story_1014_10140701_67_dialog_content = "<anim type=Shake><size=45>Graaahh—</size></anim>",
  ui_story_1014_10140701_68_dialog_content = "Mundur sedikit, Vice. Jangan biarkan mereka terlalu dekat.",
  ui_story_1014_10140701_69_dialog_content = "Tidak ada jalan mundur di saat seperti ini! Di kanan mu!",
  ui_story_1014_10140701_70_dialog_content = "Wow! Begitu banyak dari mereka... Dimana semua orang? Dimana saya?!",
  ui_story_1014_10140701_71_dialog_content = "Oh, andai saja Axelia ada di sini.",
  ui_story_1014_10140701_72_dialog_content = "Hai! Perhatikan kata-kata Anda! Jadi aku tidak cukup?!",
  ui_story_1014_10140701_73_dialog_content = "Semuanya, ke belakang saya! Jangan kabur!",
  ui_story_1014_10140701_74_dialog_content = "Aku akan melindungimu...",
  ui_story_1014_10140701_75_dialog_content = "Aduh!! Eclipsites, menuju ke arah kita!",
  ui_story_1014_10140701_76_dialog_content = "Hah? Di mana?",
  ui_story_1014_10140701_77_dialog_content = "Di Sini! Mereka ada di sini!",
  ui_story_1014_10140701_78_dialog_content = "Tunggu, aku datang!",
  ui_story_1014_10140701_79_dialog_content = "Graaagh!",
  ui_story_1014_10140701_80_dialog_content = "... Mereka ada di mana-mana!",
  ui_story_1014_10140701_81_dialog_content = "PlayerName! Bisakah Anda memberi saya gambaran tentang posisi musuh?",
  ui_story_1014_10140701_82_dialog_content = "Saya tidak bisa mengetahui di mana mereka berada ...",
  ui_story_1014_10140701_83_dialog_content = "<size=45>SETIAP ORANG! KELUAR DARI SINI!!</size>",
  ui_story_1014_10140701_84_dialog_content = "Hah? Dan kemana tujuan kita?",
  ui_story_1014_10140701_85_dialog_content = "Aku tidak begitu tahu tapi... Semakin jauh, semakin baik!",
  ui_story_1014_10140701_86_dialog_content = "<color=#e8d9bb>Gemuruh—Gemuruh—</color>",
  ui_story_1014_10140701_87_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1014_10140701_88_dialog_content = "Wow... Orang ini konyol.",
  ui_story_1014_10140701_89_dialog_content = "Jangan hanya berdiri di sana!",
  ui_story_1014_10140701_90_dialog_content = "<anim type=Shake><size=50>Grrr!</size></anim>",
  ui_story_1014_10140701_91_dialog_content = "*Uhuk* Formasi pecah... Apakah semuanya baik-baik saja?",
  ui_story_1014_10140701_92_dialog_content = "PlayerName memperingatkan semua orang, jadi seharusnya tidak ada yang tertangkap.",
  ui_story_1014_10140701_93_dialog_content = "Saya lebih khawatir tentang warga sipil.",
  ui_story_1014_10140701_94_dialog_content = "Jika formasi pecah, kemungkinan besar mereka akan diserang.",
  ui_story_1014_10140701_95_dialog_content = "Kamu benar! Kita harus membantu mereka!",
  ui_story_1014_10140701_96_dialog_content = "Bisakah kita keluar dari sini?",
  ui_story_1014_10140701_97_dialog_content = "Tolong!",
  ui_story_1014_10140701_98_dialog_content = "Eclipse, mereka ada di mana-mana!",
  ui_story_1014_10140701_99_dialog_content = "Kemana mereka pergi? Orang-orang yang datang untuk menyelamatkan kita?!",
  ui_story_1014_10140701_100_dialog_content = "Tetap tenang, semuanya! Datanglah padaku, aku akan melindungimu!",
  ui_story_1014_10140701_101_dialog_content = "PlayerName, musuh...",
  ui_story_1014_10140701_102_dialog_content = "Mereka ada di mana-mana sekarang. Seluruh medan perang penuh dengan mereka!",
  ui_story_1014_10140701_103_dialog_content = "Tidak ada cara bagi warga sipil untuk berkelompok. The Eclipsites berhasil membubarkan kerumunan.",
  ui_story_1014_10140701_104_dialog_content = "J-Jadi, apa yang kita lakukan sekarang?",
  ui_story_1014_10140701_105_dialog_content = "Kurasa...",
  ui_story_1014_10140701_106_dialog_content = "Bukan hanya mereka, tapi kita juga.",
  ui_story_1014_10140701_107_dialog_content = "Monster yang mereka sebut Cerritus itu akan terus melancarkan serangan, dan kita tidak akan bertahan lama di lautan Eclipsites.",
  ui_story_1014_10140701_108_dialog_content = "Anda tepat ... Ini di sini lagi ...",
  ui_story_1014_10140701_109_dialog_content = "Dapatkah Anda melihat jalan keluar, Yingel? Anda biasanya yang paling cerdas di ruangan itu.",
  ui_story_1014_10140701_110_dialog_content = "Lupakan warga sipil, mundur di belakang Ironthorn Knights.",
  ui_story_1014_10140701_111_dialog_content = "Hah? Tapi...",
  ui_story_1014_10140701_112_dialog_content = "Leo benar. Kita harus menghadapinya. Ini perbatasan, dan kita tidak cukup kuat.",
  ui_story_1014_10140701_113_dialog_content = "Bahkan jika kita terus berperang, warga sipil itu masih akan dihabisi satu per satu dalam kekacauan.",
  ui_story_1014_10140701_114_dialog_content = "Kita tidak bisa menyelamatkan semua orang.",
  ui_story_1014_10140701_115_dialog_content = "...",
  ui_story_1014_10140701_116_dialog_content = "Kami telah melakukan yang terbaik, PlayerName. Anda harus memahami situasi kami.",
  ui_story_1014_10140701_117_dialog_content = "<color=#e8d9bb>Gruk—</color>",
  ui_story_1014_10140701_118_dialog_content = "Anda dengar itu? Monster itu datang.",
  ui_story_1014_10140701_119_dialog_content = "K-Kita...",
  ui_story_1014_10140701_120_dialog_content = "Jika Anda tidak mengambil keputusan, saya hanya akan membawa Anda bersamaku.",
  ui_story_1014_10140701_121_dialog_content = "!!!",
  ui_story_1014_10140701_122_dialog_content = "Beri aku perlindungan, Nona Lumopolis. Kami menarik diri.",
  ui_story_1014_10140701_123_dialog_content = "Namun…",
  ui_story_1014_10140701_124_dialog_content = "Saya berjanji! Aku bilang aku akan melindungi mereka...",
  ui_story_1014_10140701_125_dialog_content = "Kemudian biarkan pertumbuhan Anda sendiri dimulai dengan janji yang tidak dapat Anda penuhi.",
  ui_story_1014_10140701_126_dialog_content = "<color=#e8d9bb>Gruk—</color>",
  ui_story_1014_10140701_127_dialog_content = "Maaf, tapi setidaknya aku harus mencoba. Aku tidak bisa melanggar kata-kataku dengan mudah.",
  ui_story_1014_10140701_128_dialog_content = "Karena saya memilih untuk menyebut diri saya seorang ksatria.",
  ui_story_1014_10140701_129_dialog_content = "Anda-",
  ui_story_1014_10140701_130_dialog_content = "Beretta!!",
  ui_story_1014_10140701_131_dialog_content = "Jadi Anda menyebut diri Anda seorang ksatria. Bersyukurlah pada nama itu, karena telah membuatmu benar dan suci.",
  ui_story_1014_10140701_132_dialog_content = "Hah?",
  ui_story_1014_10140701_133_dialog_content = "Rooarrrrr—",
  ui_story_1014_10140701_134_dialog_content = "Cerritus ditolak oleh Luminatics! Itu—",
  ui_story_1014_10140701_135_dialog_content = "Ini pertama kalinya aku bertemu ksatria sepertimu.",
  ui_story_1014_10140701_136_dialog_content = "B-Benarkah? Aku hanya melakukan apa yang diharapkan dari seorang ksatria.",
  ui_story_1014_10140701_137_dialog_content = "Tapi ksatria lain tidak sepertimu.",
  ui_story_1014_10140701_138_dialog_content = "Kamu sangat cantik... Apakah kamu semacam malaikat?",
  ui_story_1014_10140701_139_dialog_content = "Aku juga sudah lama ingin bertemu malaikat, tapi sayangnya... Mereka belum datang sebelum aku.",
  ui_story_1014_10140701_140_dialog_content = "Jadi manusia harus cukup untuk beberapa usaha.",
  ui_story_1014_10140701_141_dialog_content = "Penduduk desa, ikuti cahaya dan datanglah padaku.",
  ui_story_1014_10140701_142_dialog_content = "Malam Putih di atas, cahaya akan membersihkan semua kejahatan, dan membimbing semua jiwa kembali ke rumah.",
  ui_story_1014_10140701_143_dialog_content = "Lihat! Eclipsites takut cahaya di sana!",
  ui_story_1014_10140701_144_dialog_content = "Cepat! Ayo ke sana! Kami akan aman!",
  ui_story_1014_10140701_145_dialog_content = "Saya pernah mendengar tentang dia! Itu pasti dia—Santo Perempuan Senja!",
  ui_story_1014_10140701_146_dialog_content = "Luar biasa! Warga sipil telah berhasil berkumpul lagi!",
  ui_story_1014_10140701_147_dialog_content = "Eclipsites bersembunyi dari cahaya yang memancar dari tubuh gadis itu. Sepertinya kita harus mengikuti jika kita ingin keluar dari sini!",
  ui_story_1014_10140701_148_dialog_content = "Ya, saya setuju. Jadi, ubah rencana: sekarang kita mengepung gadis itu dan melakukan yang terbaik untuk menutupi mundurnya warga sipil.",
  ui_story_1014_10140701_149_dialog_content = "Salin itu, Komandan Yingel!",
  ui_story_1014_10140701_150_dialog_content = "Jangan panggil aku seperti itu.",
  ui_story_1014_10140701_151_dialog_content = "Kapten! Mereka datang kembali! DENGAN warga sipil itu!",
  ui_story_1014_10140701_152_dialog_content = "Saya melihat. Buka formasi dengan hati-hati, dan bawa mereka ke belakang.",
  ui_story_1014_10140701_153_dialog_content = "Siap, Pak!",
  ui_story_1014_10140701_154_dialog_content = "Itu adalah Ironthorn Knights! Untunglah! Kami aman sekarang.",
  ui_story_1014_10140701_155_dialog_content = "Tingkatkan kecepatannya! Bagaimana orang bisa santai sampai kita berada di Twilight, dan keluar dari hutan belantara yang terkutuk ini?",
  ui_story_1014_10140701_156_dialog_content = "Kerja bagus, Kapten Leo.",
  ui_story_1014_10140701_157_dialog_content = "Anda sedang menyindir, bukan, <color=#FFB400>Yang Mulia</color>?",
  ui_story_1014_10140701_158_dialog_content = "Sama sekali tidak. Saya tidak kekanak-kanakan dan sepenuhnya menyadari situasi Anda.",
  ui_story_1014_10140701_159_dialog_content = "Begitu banyak yang melarikan diri ke Twilight, semakin mustahil untuk melindungi mereka dan juga kota kita.",
  ui_story_1014_10140701_160_dialog_content = "Setiap Eclipsite yang berhasil melewati Anda akan langsung bergegas menuju Twilight. Secara alami, Anda tidak dapat meninggalkan garis pertahanan.",
  ui_story_1014_10140701_161_dialog_content = "Terima kasih atas absolusi Anda. Saya merasa lebih baik sekarang.",
  ui_story_1014_10140701_162_dialog_content = "Wajahmu tidak menunjukkannya. Apakah ini masalah martabat yang Anda bicarakan?",
  ui_story_1014_10140701_163_dialog_content = "Tidak terlalu. Hanya saja aku iri padamu, bahwa kamu dapat melakukan dengan mudah apa yang tidak bisa kulakukan.",
  ui_story_1014_10140701_164_dialog_content = "Sekarang giliran Anda, untuk melakukan apa yang saya tidak bisa.",
  ui_story_1014_10140701_165_dialog_content = "Tentu. Pimpin warga sipil ke belakang, dan serahkan medan perang kepadaku.",
  ui_story_1014_10140701_166_dialog_content = "Tidak ada satu pun Eclipsite yang bisa melewati Ironthorn Knights.",
  ui_story_1014_10140701_167_dialog_content = "Saya percaya padamu.",
  ui_story_1014_10140701_168_dialog_content = "Pergilah kalau begitu. Waktu singkat kita bersama sudah berakhir.",
  ui_story_1014_10140701_169_dialog_content = "Selalu terlihat seperti ini dengan kami, saling bahu membahu di medan perang.",
  ui_story_1014_10140701_170_dialog_content = "Ya. Selalu.",
  ui_story_1014_10140701_171_dialog_content = "Kami selalu berlari berlawanan arah.",
  ui_story_1014_10140701_172_dialog_content = "Teman kita semakin dekat. Aku bisa mendengarnya.",
  ui_story_1014_10140701_173_dialog_content = "Ksatria Ironthorn! Bersiap! Siapa yang memberi pria besar tendangan yang sama besarnya?!",
  ui_story_1014_10140701_174_dialog_content = "<size=40>SAYA!!</size>",
  ui_story_1014_10140701_175_dialog_content = "<size=40>Saya juga!</size>",
  ui_story_1014_10140701_176_dialog_content = "Ingin bergabung dengan kami? Jika Anda masih memiliki kekuatan untuk bertarung, tentu saja.",
  ui_story_1014_10140701_177_dialog_content = "Tentu saja! Sudah waktunya untuk membayar kembali sepuluh kali lipat apa yang baru saja kita derita!",
  ui_story_1014_10140701_178_dialog_content = "Hahahahaha! Saya suka semangat itu!",
  ui_story_1014_10140701_179_dialog_content = "Dengan bantuan Anda, tujuan kami tidak akan murni menjadi pertahanan.",
  ui_story_1014_10140701_180_dialog_content = "Malam ini, saya ingin menggantung spanduk kami di tanduknya!",
  ui_story_1014_10140702_1_dialog_content = "<anim type=Shake><size=45>Graah!!! Graaaaah—</size></anim>",
  ui_story_1014_10140702_2_dialog_content = "Istirahatlah, orang besar.",
  ui_story_1014_10140702_3_dialog_content = "Fiuh... Akhirnya turun. Benda itu sangat kuat.",
  ui_story_1014_10140702_4_dialog_content = "Jangan santai dulu. Serangan Eclipsites masih berlangsung, dan kita harus melihatnya sampai akhir.",
  ui_story_1014_10140702_5_dialog_content = "Tentu saja! Tapi setidaknya tekanannya mati.",
  ui_story_1014_10140702_6_dialog_content = "Astaga, akhirnya kita keluar dari gerombolan Eclipsite itu.",
  ui_story_1014_10140702_7_dialog_content = "Bagaimana dengan Cerritus? Kemana perginya orang besar itu?",
  ui_story_1014_10140702_8_dialog_content = "...",
  ui_story_1014_10140702_9_dialog_content = "Terima kasih! Oh, terima kasih, Yang Mulia!",
  ui_story_1014_10140702_10_dialog_content = "Anda menyelamatkan kami semua!",
  ui_story_1014_10140702_11_dialog_content = "Oh, kumohon... Tolong berhenti memanggilku seperti itu.",
  ui_story_1014_10140702_12_dialog_content = "Nama saya adalah <color=#FFB400>Joselyne</color>. Kami akan bertetangga jika Anda memilih untuk menetap di Twilight.",
  ui_story_1014_10140702_13_dialog_content = "Oh benar, apa yang harus kita lakukan sekarang?",
  ui_story_1014_10140702_14_dialog_content = "Mari kita ke Senja dulu. Dengan pasukan Lumopolis dan Illumina di sana, setidaknya kita akan aman.",
  ui_story_1014_10140702_15_dialog_content = "Jika kita terus bergerak, entah kapan kita bisa diserang oleh Eclipsites lagi.",
  ui_story_1014_10140702_16_dialog_content = "Sepakat. Dan aku tidak mau harus melarikan diri, tidak lagi.",
  ui_story_1014_10140702_17_dialog_content = "Semua orang pergi ke Twilight dulu. Kalian semua pasti kelelahan, mengingat apa yang telah kalian lalui.",
  ui_story_1014_10140702_18_dialog_content = "Akan ada orang lain yang tiba di Twilight hari ini juga. Penduduk kota bersiap-siap untuk membuat mereka menetap.",
  ui_story_1014_10140702_19_dialog_content = "Akan ada kamar untuk semua orang malam ini, jadi tolong istirahat dan pulihkan tenaga.",
  ui_story_1014_10140702_20_dialog_content = "Kita bisa mendiskusikan apa yang akan terjadi besok pagi.",
  ui_story_1014_10140702_21_dialog_content = "Luar biasa! Terima kasih banyak telah merawat kami dengan sangat baik.",
  ui_story_1014_10140702_22_dialog_content = "Sayangnya, ini bukan pertama kalinya Twilight harus melakukan ini.",
  ui_story_1014_10140702_23_dialog_content = "Banyak orang yang tinggal di sini juga melarikan diri dari tempat tetangga, jadi semua orang bersimpati pada penderitaan Anda.",
  ui_story_1014_10140702_24_dialog_content = "Kami melakukan apa yang kami bisa untuk membantu. Semoga Anda akan menemukan rumah baru secepat mungkin.",
  ui_story_1014_10140702_25_dialog_content = "Rumah baru? Oh ya, kami akan!",
  ui_story_1014_10140702_26_dialog_content = "Sudah larut. Pergilah ke kota, semuanya.",
  ui_story_1014_10140702_27_dialog_content = "Baik! Tunggu saja kami beres, lalu kami akan datang dan berterima kasih dengan benar, Yang Mulia!",
  ui_story_1014_10140702_28_dialog_content = "Ahh, sudah kubilang panggil saja aku Joselyne.",
  ui_story_1014_10140702_29_dialog_content = "Malam Putih di atas, kami akan mengunjungi Anda di gereja saat kami bisa!",
  ui_story_1014_10140702_30_dialog_content = "Saya bukan bagian dari gereja, jadi Anda tidak akan menemukan saya di sana!",
  ui_story_1014_10140702_31_dialog_content = "Apa? Anda bukan anggota gereja?",
  ui_story_1014_10140702_32_dialog_content = "Tidak, tidak sama sekali. Aku hanyalah manusia biasa, sama seperti kalian semua.",
  ui_story_1014_10140702_33_dialog_content = "Jika Anda ingin menemukan saya, datanglah ke pasar. Saya sering ke sana menjual barang.",
  ui_story_1014_10140702_34_dialog_content = "Oke, pasar. Aku akan ingat itu!",
  ui_story_1014_10140702_35_dialog_content = "Sampai jumpa, Yang Mulia.",
  ui_story_1014_10140702_36_dialog_content = "Itu Joselyn...",
  ui_story_1014_10140702_37_dialog_content = "Ya ampun, suara itu...",
  ui_story_1014_10140702_38_dialog_content = "Mereka kembali.",
  ui_story_1014_10140702_39_dialog_content = "<color=#e8d9bb>Klip-klop, klip-klop</color>",
  ui_story_1014_10140702_40_dialog_content = "Jadi Anda datang mengunjungi perbatasan, Lady Carleen.",
  ui_story_1014_10140702_41_dialog_content = "Benar. Sudah lama sejak Lumopolis terakhir bertukar kabar dengan Twilight.",
  ui_story_1014_10140702_42_dialog_content = "Bukankah agak berlebihan mengirimmu ke sini untuk masalah sepele seperti itu?",
  ui_story_1014_10140702_43_dialog_content = "Anda telah melihat situasi umum di sini. Konflik di sini adalah perjuangan, tetapi kita masih bisa menjaga stabilitas.",
  ui_story_1014_10140702_44_dialog_content = "Pasukan kami terkonsentrasi di sekitar Benteng Lumo. Inti energi Twilight ada di sana, sehingga memiliki banyak pertahanan.",
  ui_story_1014_10140702_45_dialog_content = "Jika Anda punya waktu, Lady Carleen, Anda dipersilakan untuk mengikuti tur.",
  ui_story_1014_10140702_46_dialog_content = "Terima kasih, saya ingin itu.",
  ui_story_1014_10140702_47_dialog_content = "Kami hampir sampai.",
  ui_story_1014_10140702_48_dialog_content = "Sepertinya kita mengadakan pesta penyambutan.",
  ui_story_1014_10140702_49_dialog_content = "Hei, itu... gadis dari pertarungan!",
  ui_story_1014_10140702_50_dialog_content = "Saya ingat semua orang memanggilnya \"Saint of Twilight.\"",
  ui_story_1014_10140702_51_dialog_content = "Tolong lupakan gelar itu dan panggil saja saya Joselyne.",
  ui_story_1014_10140702_52_dialog_content = "Saya terkesan dengan kepahlawanan Anda di medan perang.",
  ui_story_1014_10140702_53_dialog_content = "Saya di sini atas nama rakyat untuk menyambut kembalinya kemenangan Anda.",
  ui_story_1014_10140702_54_dialog_content = "Saya akan mengatakan bahwa perilaku Anda dalam pertempuranlah yang paling mengesankan.",
  ui_story_1014_10140702_55_dialog_content = "Ya! Cara Anda muncul, bermandikan cahaya! Sangat dramatis!",
  ui_story_1014_10140702_56_dialog_content = "Meskipun saya yakin warga sipil yang Anda selamatkan merasa lebih kuat daripada saya.",
  ui_story_1014_10140702_57_dialog_content = "Anda benar-benar tampak seperti utusan ilahi ...",
  ui_story_1014_10140702_58_dialog_content = "Tolong jangan katakan hal seperti itu, itu membuatku takut.",
  ui_story_1014_10140702_59_dialog_content = "Saya tidak pernah menyangka akan melihat Lumina semurni ini sejauh ini dari Lumopolis.",
  ui_story_1014_10140702_60_dialog_content = "Saya tidak begitu akrab dengan gereja perbatasan. Apakah kamu anggota?",
  ui_story_1014_10140702_61_dialog_content = "Caramu berpakaian... tidak seperti yang kubayangkan seorang biarawati.",
  ui_story_1014_10140702_62_dialog_content = "Ah, orang-orang selalu punya ide seperti itu tentangku.",
  ui_story_1014_10140702_63_dialog_content = "Tapi saya bukan anggota gereja, maaf.",
  ui_story_1014_10140702_64_dialog_content = "Jangan bilang kamu tentara Illuminan?",
  ui_story_1014_10140702_65_dialog_content = "Tentara dari Illumina tidak berpakaian seperti itu.",
  ui_story_1014_10140702_66_dialog_content = "Di sini, di perbatasan, tidak semua orang harus bersekutu dengan Lumopolis atau Illumina. Dan bukan hanya tentara yang berperang juga.",
  ui_story_1014_10140702_67_dialog_content = "Secara teknis, dia adalah pedagang tomat.",
  ui_story_1014_10140702_68_dialog_content = "?!",
  ui_story_1014_10140702_69_dialog_content = "Saya ingin mengingatkan Kapten yang perkasa bahwa saya juga berkecimpung dalam bisnis merajut.",
  ui_story_1014_10140702_70_dialog_content = "Anda belum pernah membeli satu pun tomat dari saya, namun saya telah memperbaiki setidaknya dua spanduk Anda.",
  ui_story_1014_10140702_71_dialog_content = "Maaf... Saya ingin mendukung bisnis Anda, tetapi tomat bukan bagian dari diet ksatria.",
  ui_story_1014_10140702_72_dialog_content = "Ksatria! Apa yang kita makan?",
  ui_story_1014_10140702_73_dialog_content = "DAGING!",
  ui_story_1014_10140702_74_dialog_content = "Tidak ada yang seperti betis domba yang lezat, dipanggang dengan sempurna!",
  ui_story_1014_10140702_75_dialog_content = "Yah... Saya harap selera Anda segera menyusul keterampilan tempur Anda.",
  ui_story_1014_10140702_76_dialog_content = "Pokoknya, semua orang selain ksatria adalah orang luar, kan? Aku tidak percaya aku pernah melihat kalian sebelumnya.",
  ui_story_1014_10140702_77_dialog_content = "Betul sekali. Kami baru saja tiba dari Kota Gannon di timur.",
  ui_story_1014_10140702_78_dialog_content = "Kota Gannon? Maka Anda benar-benar telah menempuh perjalanan jauh. Saya hanya pernah melihatnya di peta.",
  ui_story_1014_10140702_79_dialog_content = "Dan saya kira Anda akan tinggal di Twilight lebih lama?",
  ui_story_1014_10140702_80_dialog_content = "Memang. Kami memiliki beberapa hal untuk diperhatikan di sini.",
  ui_story_1014_10140702_81_dialog_content = "Kalau begitu, mengapa tidak ikut denganku? Saya dapat membantu mengatur beberapa akomodasi yang sesuai.",
  ui_story_1014_10140702_82_dialog_content = "Dan saya harap saya tidak mengganggu, tetapi saya juga ingin mengundang Anda semua untuk mencoba beberapa makanan khas setempat.",
  ui_story_1014_10140702_83_dialog_content = "Hanya itu yang bisa kulakukan untuk membalas keberanianmu.",
  ui_story_1014_10140702_84_dialog_content = "Eh? I-Itu sangat baik, tapi pasti tidak perlu.",
  ui_story_1014_10140702_85_dialog_content = "Kami tidak mendapatkan banyak pengunjung di sini, lebih sedikit lagi yang akan berjuang atas nama kami.",
  ui_story_1014_10140702_86_dialog_content = "Saya bermaksud mengundang Anda semua untuk makan malam juga, jika Joselyne tidak mengalahkan saya.",
  ui_story_1014_10140702_87_dialog_content = "Tetapi karena Yang Mulia telah dengan baik hati menawarkan untuk membayar tagihan, saya sarankan Anda menerimanya!",
  ui_story_1014_10140702_88_dialog_content = "Begitu... Apa yang dipikirkan semua orang?",
  ui_story_1014_10140702_89_dialog_content = "Nah pada titik ini, tidak sopan untuk tidak menerima.",
  ui_story_1014_10140702_90_dialog_content = "Pasti menerima! Saya ingin tahu suguhan lezat apa yang dimiliki Twilight. Saya tidak sabar!",
  ui_story_1014_10140702_91_dialog_content = "Saya cukup akrab dengan semua yang ditawarkan kota kami. Saya yakin Anda semua akan puas.",
  ui_story_1014_10140702_92_dialog_content = "Kamu juga berjuang keras, Kapten Leo. Maukah Anda memberi saya kehormatan untuk bergabung dengan kami untuk makan malam?",
  ui_story_1014_10140702_93_dialog_content = "Apakah Anda hanya mengundang saya, atau semua Ironthorn Knights?",
  ui_story_1014_10140702_94_dialog_content = "Saya khawatir restoran yang ada dalam pikiran saya tidak dapat menampung semua ksatria.",
  ui_story_1014_10140702_95_dialog_content = "Ah, Anda tidak boleh menunjukkan pilih kasih seperti itu, Yang Mulia!",
  ui_story_1014_10140702_96_dialog_content = "Bukankah kita semua menumpahkan darah untuk Twilight juga?",
  ui_story_1014_10140702_97_dialog_content = "Baiklah, baiklah, kalian tidak akan ketinggalan.",
  ui_story_1014_10140702_98_dialog_content = "Untuk merayakan kemenangan kita, malam ini kalian semua boleh makan sesuka kalian. Ini pada saya.",
  ui_story_1014_10140702_99_dialog_content = "<size=45>YA! Luar biasa!!</size>",
  ui_story_1014_10140702_100_dialog_content = "Saya khawatir saya tidak dapat bergabung dengan Anda, karena Nona Joselyne sangat murah hati.",
  ui_story_1014_10140702_101_dialog_content = "Aku akan menemani teman baru kita dari jauh.",
  ui_story_1014_10140702_102_dialog_content = "Saya juga ingin melihat sendiri jenis makanan apa yang disukai oleh selera Joselyne.",
  ui_story_1014_10140801_1_dialog_content = "Apa yang kita lakukan untuk tempat tidur dan barang-barang...? Bantal, selimut, pakaian...",
  ui_story_1014_10140801_2_dialog_content = "Ah, aku tidak membawa apa-apa.",
  ui_story_1014_10140801_3_dialog_content = "Ini tidak seperti Anda bisa berhenti dan berkemas ketika Anda melarikan diri untuk hidup Anda.",
  ui_story_1014_10140801_4_dialog_content = "Saya bahkan tidak punya waktu untuk menemukan dompet saya. Saya khawatir akan segera kelaparan.",
  ui_story_1014_10140801_5_dialog_content = "Hei, kudengar mereka bisa meminjamkanmu beberapa hal mendasar di sana.",
  ui_story_1014_10140801_6_dialog_content = "Mari kita pergi bersama dan lihatlah!",
  ui_story_1014_10140801_7_dialog_content = "Ada begitu banyak pengungsi di jalanan.",
  ui_story_1014_10140801_8_dialog_content = "Apakah mereka semua baru saja tiba di sini hari ini?",
  ui_story_1014_10140801_9_dialog_content = "Ya. Sayangnya, pemandangan seperti itu terlalu umum di Twilight.",
  ui_story_1014_10140801_10_dialog_content = "Sungguh?",
  ui_story_1014_10140801_11_dialog_content = "Sementara Lumopolis dan Illumina memiliki garnisun di sini, area di luar kota kami tidak diatur oleh satu kekuatan pun.",
  ui_story_1014_10140801_12_dialog_content = "Desa-desa kecil yang tersebar biasanya mandiri dan puas.",
  ui_story_1014_10140801_13_dialog_content = "Tapi, ketika Aurorastorm dan Eclipsites mulai menyerang, desa-desa tersebut pada dasarnya tidak mampu mempertahankan diri.",
  ui_story_1014_10140801_14_dialog_content = "Penduduk desa tidak punya pilihan selain meninggalkan rumah mereka dan mencari perlindungan dengan garnisun.",
  ui_story_1014_10140801_15_dialog_content = "Mereka tiba seperti butiran pasir yang berbeda-beda, semuanya tertiup angin dan tertiup ke pelabuhan aman yang sama.",
  ui_story_1014_10140801_16_dialog_content = "Butir-butir pasir menumpuk menjadi bukit pasir, dan para pengungsi mengakar dan mendirikan Twilight.",
  ui_story_1014_10140801_17_dialog_content = "Oh, begitu…",
  ui_story_1014_10140801_18_dialog_content = "Mengapa orang tidak memilih untuk terus bergerak dan mencari tempat yang lebih aman?",
  ui_story_1014_10140801_19_dialog_content = "Apakah maksud Anda Lumopolis atau Gannon di timur?",
  ui_story_1014_10140801_20_dialog_content = "Tentu saja mereka ingin pergi. Tetapi dengan kehidupan sehari-hari yang sudah begitu sulit, ternyata tidak sesederhana itu.",
  ui_story_1014_10140801_21_dialog_content = "Bagaimana mereka mencari nafkah di negeri yang begitu jauh? Di mana mereka akan tinggal?",
  ui_story_1014_10140801_22_dialog_content = "Tidak ada yang secara sukarela memberikan tanah atau tempat tinggal kepada orang luar.",
  ui_story_1014_10140801_23_dialog_content = "Tapi di sini, di Reruntuhan Aurora, setidaknya tanahnya subur, dan mereka tidak perlu mengkhawatirkan kebutuhan pokok. Bahkan dengan ancaman Eclipsite yang selalu ada...",
  ui_story_1014_10140801_24_dialog_content = "Semua orang berpikir lebih baik menghadapi kesulitan yang diketahui daripada tanpa akar dan mengembara.",
  ui_story_1014_10140801_25_dialog_content = "Ah... maafkan aku, aku terlalu naif.",
  ui_story_1014_10140801_26_dialog_content = "Hahaha, jangan khawatir! Tidak ada yang akan menilai Anda.",
  ui_story_1014_10140801_27_dialog_content = "Saya yakin tempat ini berbeda dengan tempat lain yang pernah Anda kunjungi, jadi wajar jika Anda bertanya-tanya.",
  ui_story_1014_10140801_28_dialog_content = "Kau benar, itu sama sekali berbeda. Tidak hanya orang-orang yang dibiarkan sendiri, tetapi ternyata, Lumopolis dan Illumina dapat hidup berdampingan di kota yang sama!",
  ui_story_1014_10140801_29_dialog_content = "Anda mengatakan hidup berdampingan, tetapi pada kenyataannya, mereka biasanya saling menghindari.",
  ui_story_1014_10140801_30_dialog_content = "Ada perwakilan faksi di sini bersama kami sekarang. Anda bisa bertanya kepada mereka.",
  ui_story_1014_10140801_31_dialog_content = "Hidup berdampingan Lumopolis dan Illumina adalah sesuatu yang telah terjadi sejak saya tiba di Twilight sebagai seorang anak.",
  ui_story_1014_10140801_32_dialog_content = "Tapi saya pernah mendengar beberapa penatua berbicara tentang masalah di masa lalu.",
  ui_story_1014_10140801_33_dialog_content = "Semua kekuatan ingin menjaga keamanan perbatasan Reruntuhan Aurora. Tapi selain itu, tidak ada perintah yang lebih eksplisit.",
  ui_story_1014_10140801_34_dialog_content = "Illumina dan Lumopolis memandang Reruntuhan Aurora dengan cara yang sama: perbatasan terpencil yang hampir tidak berharga untuk waktu siapa pun, tetapi tetap memalukan untuk ditinggalkan.",
  ui_story_1014_10140801_35_dialog_content = "Karena tidak ada seorang pun yang berada di atas yang dapat diganggu tentang tempat ini, tentara di kedua sisi cenderung kehilangan ketelitian mereka tentang hal-hal yang telah diajarkan kepada mereka tentang pihak lain.",
  ui_story_1014_10140801_36_dialog_content = "Meskipun tanah di dalam dan di sekitar Reruntuhan Aurora cukup subur, terdapat kekurangan sumber energi. Yang kami miliki sebagian besar terkonsentrasi di Twilight dan sekitarnya.",
  ui_story_1014_10140801_37_dialog_content = "Untuk dapat memenuhi kebutuhan energinya sendiri, kedua belah pihak sepakat untuk ditempatkan bersama di sini.",
  ui_story_1014_10140801_38_dialog_content = "Bukankah memperebutkan sumber daya yang sedikit akan menyebabkan konflik?",
  ui_story_1014_10140801_39_dialog_content = "Berurusan dengan Eclipsites sudah sangat menguras tenaga sehingga tidak ada yang memiliki kekuatan untuk menyisihkan konflik internal.",
  ui_story_1014_10140801_40_dialog_content = "Bertahan hidup adalah nama permainan di sini.",
  ui_story_1014_10140801_41_dialog_content = "Medan perang segera mendidik mereka yang tidak mampu membedakan prioritas.",
  ui_story_1014_10140801_42_dialog_content = "Jadi begitulah adanya.",
  ui_story_1014_10140801_43_dialog_content = "Itu mengingatkan saya pada Koalisi Aurorian yang saya baca di buku sejarah.",
  ui_story_1014_10140801_44_dialog_content = "Menghadapi musuh eksternal yang kuat, kedua belah pihak berhasil menyelesaikan perbedaan mereka.",
  ui_story_1014_10140801_45_dialog_content = "<color=#e8d9bb>Wush!</color>",
  ui_story_1014_10140801_46_dialog_content = "<anim type=Goyang>Nghn...</anim>",
  ui_story_1014_10140801_47_dialog_content = "Axelia! Anda sudah bangun!",
  ui_story_1014_10140801_48_dialog_content = "Selamat pagi, PlayerName.",
  ui_story_1014_10140801_49_dialog_content = "Ini bahkan tidak jauh dari pagi ...",
  ui_story_1014_10140801_50_dialog_content = "Hah? Anda memiliki seorang gadis menggemaskan yang disembunyikan?",
  ui_story_1014_10140801_51_dialog_content = "Penampilan saya biasa-biasa saja dan pada dasarnya tidak penting.",
  ui_story_1014_10140801_52_dialog_content = "Saya, bagaimanapun, kelaparan.",
  ui_story_1014_10140801_53_dialog_content = "Waktu yang tepat! Ini restorannya.",
  ui_story_1014_10140801_54_dialog_content = "Apa yang ingin kamu makan?",
  ui_story_1014_10140801_55_dialog_content = "Gula.",
  ui_story_1014_10140801_56_dialog_content = "Di sini kami memiliki puff pastry, custard tart, cream puff, atau cake dengan butter icing.",
  ui_story_1014_10140801_57_dialog_content = "Mmm, semuanya terlihat luar biasa.",
  ui_story_1014_10140801_58_dialog_content = "Anda pikir tidak apa-apa makan begitu banyak makanan penutup, Joselyne?",
  ui_story_1014_10140801_59_dialog_content = "Tidak apa-apa. Indulgensi sesekali tidak masalah.",
  ui_story_1014_10140801_60_dialog_content = "Tampaknya ada sejumlah wajah asing dengan Anda hari ini.",
  ui_story_1014_10140801_61_dialog_content = "Ya, tamu-tamu ini datang jauh-jauh dari Kota Gannon.",
  ui_story_1014_10140801_62_dialog_content = "Gan, ya? Orang tua di sebelah sudah ada di sana. Aku mendengar itu adalah tempat yang sangat kaku...",
  ui_story_1014_10140801_63_dialog_content = "R-Kaku? Tidak seburuk itu...",
  ui_story_1014_10140801_64_dialog_content = "Selain mereka, kami juga memiliki tentara lokal kami sendiri.",
  ui_story_1014_10140801_65_dialog_content = "Ini adalah Sean, seorang perwira muda Illuminan... Dan ini adalah Leo, kapten dari Ksatria Besi Berduri Lumopolis.",
  ui_story_1014_10140801_66_dialog_content = "Ya! Saya letnan dua Sean, dari Twilight Garrison!",
  ui_story_1014_10140801_67_dialog_content = "Hei, ini bukan mess hall Illumina. Tidak perlu salut.",
  ui_story_1014_10140801_68_dialog_content = "Hahaha, selalu menarik melihat reaksi Sean.",
  ui_story_1014_10140801_69_dialog_content = "Bos, babi panggangmu benar-benar menakjubkan.",
  ui_story_1014_10140801_70_dialog_content = "Lain kali saya akan membawa semua ksatria saya ke sini untuk mencicipi!",
  ui_story_1014_10140801_71_dialog_content = "Ini dia lagi, hanya memikirkan daging.",
  ui_story_1014_10140801_72_dialog_content = "Bagaimanapun, ini adalah bisnis, dan Anda tidak akan bertahan jika Anda tidak menawarkan kualitas.",
  ui_story_1014_10140801_73_dialog_content = "Saya tidak melihat orang lain bekerja di sini. Anda tidak bisa menjadi satu-satunya yang menjaga tempat sebesar ini?",
  ui_story_1014_10140801_74_dialog_content = "Bahwa saya.",
  ui_story_1014_10140801_75_dialog_content = "Bukankah itu melelahkan? Dengan bakat Anda, Anda pasti bisa membawa beberapa tangan baru untuk membantu mengembangkan bisnis.",
  ui_story_1014_10140801_76_dialog_content = "Saya tidak terlalu tertarik. Saya senang menjadi pertunjukan satu orang.",
  ui_story_1014_10140801_77_dialog_content = "Ketika saya pertama kali membuka, itu dengan saudara laki-laki saya, tetapi kami sering bertengkar sehingga dengan cepat menjadi melelahkan.",
  ui_story_1014_10140801_78_dialog_content = "Itu pertama kali saya mendengar Anda menyebut saudara laki-laki.",
  ui_story_1014_10140801_79_dialog_content = "Ya. Dia meninggal tiga tahun lalu.",
  ui_story_1014_10140801_80_dialog_content = "Dia dibunuh oleh Eclipsites saat kami melarikan diri ke Twilight.",
  ui_story_1014_10140801_81_dialog_content = "Oh...",
  ui_story_1014_10140801_82_dialog_content = "Dia memiliki beberapa masalah dengan kakinya dan berjuang di belakang grup.",
  ui_story_1014_10140801_83_dialog_content = "Para ksatria Lumopolis tiba tepat saat Eclipsites mendekat. Tapi mereka tidak menyelamatkannya.",
  ui_story_1014_10140801_84_dialog_content = "...",
  ui_story_1014_10140801_85_dialog_content = "(Kesatria...)",
  ui_story_1014_10140801_86_dialog_content = "Saya tidak membenci mereka. Faktanya, mereka menyelamatkan saya.",
  ui_story_1014_10140801_87_dialog_content = "Hidup tidak berharga di sekitar sini, dan tidak ada banyak ruang untuk tawar-menawar.",
  ui_story_1014_10140801_88_dialog_content = "Tidak masalah siapa yang diselamatkan dan siapa yang tidak. Itu semua dimaksudkan untuk menjadi.",
  ui_story_1014_10140801_89_dialog_content = "Jangan katakan itu. Semua nyawa sama berharganya.",
  ui_story_1014_10140801_90_dialog_content = "Saya tahu begitulah cara Anda melihatnya, Joselyne, karena Anda berbeda.",
  ui_story_1014_10140801_91_dialog_content = "Anda akan menyelamatkan semua orang dan membuat semua orang ingin percaya bahwa ada keilahian di dunia ini.",
  ui_story_1014_10140801_92_dialog_content = "Tapi bukan aku yang menjaga kedamaian di Twilight. Itu adalah tentara yang ditempatkan di sini.",
  ui_story_1014_10140801_93_dialog_content = "Jika kita tidak menghargai semua kehidupan, bagaimana Twilight bisa berevolusi menjadi tempat perlindungan seperti sekarang ini?",
  ui_story_1014_10140801_94_dialog_content = "Hidup itu indah. Dan baik menyelamatkan maupun meninggalkan mereka adalah tindakan penghormatan di hadapan keajaiban tersebut.",
  ui_story_1014_10140801_95_dialog_content = "Para prajurit itu baru saja dihadapkan pada pilihan terakhir sebelum orang lain.",
  ui_story_1014_10140801_96_dialog_content = "...",
  ui_story_1014_10140801_97_dialog_content = "Sebenarnya, mereka—",
  ui_story_1014_10140801_98_dialog_content = "Joselyne, maukah Anda memberi saya sepiring sosis di depan Anda? Aku hanya tidak bisa mendapatkan cukup.",
  ui_story_1014_10140801_99_dialog_content = "Ah, ini.",
  ui_story_1014_10140801_100_dialog_content = "Jadi, PlayerName, saya belum benar-benar bertanya ... Apa yang membawa Anda ke Twilight?",
  ui_story_1014_10140801_101_dialog_content = "(Hmm... Leo mengganti topik pembicaraan.)",
  ui_story_1014_10140801_102_dialog_content = "Dan agar petugas Illumina berpangkat menemani Anda! Itu suatu kehormatan.",
  ui_story_1014_10140801_103_dialog_content = "Tentu saja, jika itu rahasia, lupakan aku bertanya.",
  ui_story_1014_10140801_104_dialog_content = "Oh, eh, kami di sini untuk memperbaiki Colossus.",
  ui_story_1014_10140801_105_dialog_content = "Patung raksasa?! Apakah Anda mengatakan Anda memiliki ...",
  ui_story_1014_10140801_106_dialog_content = "Betul sekali! Anda seorang Caelestite, jadi saya kira itu normal.",
  ui_story_1014_10140801_107_dialog_content = "Anda menyebutkan perbaikan... Ada apa dengan itu?",
  ui_story_1014_10140801_108_dialog_content = "Saya tidak yakin bagaimana cara terbaik untuk menjelaskan. Bukan karena ada yang tidak berfungsi, tetapi tampaknya kehilangan kesadaran untuk sementara.",
  ui_story_1014_10140801_109_dialog_content = "Colossus yang kehilangan kesadaran mungkin sedikit sulit untuk dipahami...",
  ui_story_1014_10140801_110_dialog_content = "Tidak apa-apa, saya mengerti. Ini cukup mudah untuk dipahami.",
  ui_story_1014_10140801_111_dialog_content = "Tidak heran Anda datang ke Twilight, lalu. Saya kira Anda sedang mencari peneliti Illumina?",
  ui_story_1014_10140801_112_dialog_content = "Ya. Bagaimana Anda tahu?",
  ui_story_1014_10140801_113_dialog_content = "Saya mungkin tidak mengerti seluk beluk Colossus, tapi saya akrab dengan ceritanya.",
  ui_story_1014_10140801_114_dialog_content = "Lebih akurat untuk mengatakan bahwa semua orang di Twilight mengetahui ceritanya.",
  ui_story_1014_10140801_115_dialog_content = "Tidak banyak legenda yang layak diceritakan kembali di tempat terpencil seperti ini.",
  ui_story_1014_10140801_116_dialog_content = "Legenda? Cerita seperti apa yang pernah kamu dengar?",
  ui_story_1014_10140801_117_dialog_content = "Biarkan saya berpikir tentang di mana untuk memulai.",
  ui_story_1014_10140801_118_dialog_content = "Ah, lupakan saja. Sebaiknya biarkan Joselyne memberi tahu Anda. Dia tahu bagaimana menceritakan kisah yang bagus.",
  ui_story_1014_10140801_119_dialog_content = "bukan? Aku melihatmu mengoceh terus dan terus di bar, sepanjang malam...",
  ui_story_1014_10140801_120_dialog_content = "Saya sibuk makan daging sekarang.",
  ui_story_1014_10140801_121_dialog_content = "Ha! Baik. Saya mengundang Anda untuk makan malam, saya kira saya tidak bisa membuat Anda kelaparan.",
  ui_story_1014_10140801_122_dialog_content = "Jadi, legenda ini kembali ke seribu tahun yang lalu.",
  ui_story_1014_10140801_123_dialog_content = "Tidak lama setelah bangsa Aurorian meninggalkan Northland, Lumopolis baru saja didirikan.",
  ui_story_1014_10140801_124_dialog_content = "Untuk membangun rumah yang layak, Aurorian melakukan militerisasi dan memulai pertarungan tanpa henti melawan Eclipsites.",
  ui_story_1014_10140801_125_dialog_content = "Wilayah Aurorian terus berkembang selama konflik, akhirnya menjadi sesuatu yang mirip dengan yang kita miliki saat ini.",
  ui_story_1014_10140801_126_dialog_content = "Titik terjauh dari perluasan ini adalah tempat Anda berada sekarang: Reruntuhan Aurora.",
  ui_story_1014_10140801_127_dialog_content = "Wow! Jadi tempat ini sudah lama berada tepat di perbatasan!",
  ui_story_1014_10140801_128_dialog_content = "Jangan remehkan posisi strategis Reruntuhan Aurora.",
  ui_story_1014_10140801_129_dialog_content = "Selama garis pertahanan Reruntuhan Aurora bertahan, Eclipsites terkandung dalam malam abadi dan dicegah untuk mencapai seluruh benua.",
  ui_story_1014_10140801_130_dialog_content = "Di sisi lain, jika kita kehilangan lintasan sempit ini, maka area yang jauh lebih luas akan langsung terkena ancaman Eclipsite.",
  ui_story_1014_10140801_131_dialog_content = "Pertempuran ini merupakan titik balik penting dalam perang salib Aurorian untuk mendapatkan kendali atas Astra.",
  ui_story_1014_10140801_132_dialog_content = "Apakah Anda ingin melanjutkan, atau haruskah saya?",
  ui_story_1014_10140801_133_dialog_content = "Anda pergi. Saya baru saja menambahkan beberapa konteks tambahan.",
  ui_story_1014_10140801_134_dialog_content = "Pertempuran untuk Reruntuhan Aurora sangat sulit.",
  ui_story_1014_10140801_135_dialog_content = "Terlalu dekat dengan malam abadi di sini, dengan fenomena aurora yang tidak dapat diprediksi, dan Eclipsites memiliki kekuatan yang belum pernah terjadi sebelumnya.",
  ui_story_1014_10140801_136_dialog_content = "Konflik berlarut-larut. Garis pertahanan tidak dapat sepenuhnya dibangun, dan orang-orang Aurorian yang telah meninggal terbaring di tumpukan yang tampaknya hanya tumbuh lebih tinggi.",
  ui_story_1014_10140801_137_dialog_content = "Suatu hari terjadi perang yang tak berkesudahan ini, hari yang tidak ada catatan tertulisnya.",
  ui_story_1014_10140801_138_dialog_content = "Takdir akhirnya tersenyum pada bangsa Aurorian.",
  ui_story_1014_10140801_139_dialog_content = "Di atas medan perang, awan gelap yang belum pernah ada sebelumnya menutupi matahari.",
  ui_story_1014_10140801_140_dialog_content = "Itu adalah armada <color=#FFB400>Colossi</color>.",
  ui_story_1014_10140801_141_dialog_content = "Sebuah armada?!",
  ui_story_1014_10140801_142_dialog_content = "(Saya pernah melihatnya! Saya pernah melihat yang seperti itu!)",
  ui_story_1014_10140801_143_dialog_content = "(Apakah itu armada?)",
  ui_story_1014_10140801_144_dialog_content = "Armada terus berlayar, ke kejauhan. Tapi salah satu dari mereka mendarat.",
  ui_story_1014_10140801_145_dialog_content = "Itu entah bagaimana berkomunikasi dengan Aurorian dan memutuskan untuk tetap tinggal dan bertarung bersama mereka.",
  ui_story_1014_10140801_146_dialog_content = "Tunggu, apakah Anda yakin Colossus berkomunikasi dengan Aurorian?",
  ui_story_1014_10140801_147_dialog_content = "Bukan Caelestite di kapal?",
  ui_story_1014_10140801_148_dialog_content = "Tidak. Sebenarnya, tidak ada Caelestite di kapal Colossus itu.",
  ui_story_1014_10140801_149_dialog_content = "Itu adalah Colossus <color=#FFB400>kesadaran sendiri</color> yang membuat keputusan.",
  ui_story_1014_10140801_150_dialog_content = "Colossus sendiri...",
  ui_story_1014_10140801_151_dialog_content = "Seorang teman saya yang kutu buku pernah memberi tahu saya bahwa dalam sejarah Aurorian, kata Colossus mendahului kata Caelestite.",
  ui_story_1014_10140801_152_dialog_content = "Itu mungkin benar-benar mendukung legenda.",
  ui_story_1014_10140801_153_dialog_content = "Jadi apa yang terjadi sesudahnya? Apakah Colossus tinggal di Reruntuhan Aurora?",
  ui_story_1014_10140801_154_dialog_content = "Ya. Itu seperti seorang prajurit khusus, entah bagaimana berkomitmen untuk perang yang berkepanjangan ini.",
  ui_story_1014_10140801_155_dialog_content = "Tidak sampai bertahun-tahun kemudian perang akhirnya dimenangkan, dan Aurorian berhasil membangun benteng mereka sendiri di Reruntuhan Aurora.",
  ui_story_1014_10140801_156_dialog_content = "Karena meningkatnya ketidakaktifan akibat kerusakan pertempuran selama bertahun-tahun, Colossus akhirnya berubah menjadi patung yang sunyi.",
  ui_story_1014_10140801_157_dialog_content = "Orang-orang Aurorian di sini memuja Colossus, memperlakukannya seperti totem religius untuk dianggap penting.",
  ui_story_1014_10140801_158_dialog_content = "Sungguh luar biasa untuk berpikir bahwa itu melompati Caelestites untuk membentuk ikatan dengan Aurorian.",
  ui_story_1014_10140801_159_dialog_content = "Apakah itu terpelihara dengan baik?",
  ui_story_1014_10140801_160_dialog_content = "Biarkan aku menyelesaikan cerita dulu.",
  ui_story_1014_10140801_161_dialog_content = "Kemudian kita sampai pada zaman yang lebih modern. Federasi Illumina yang muncul mengirim pasukan ke Reruntuhan Aurora.",
  ui_story_1014_10140801_162_dialog_content = "Peneliti mereka mulai mempelajari Colossus dalam upaya untuk memperbaiki raksasa yang rusak.",
  ui_story_1014_10140801_163_dialog_content = "Mereka ... semi-sukses, mari kita bicara seperti itu.",
  ui_story_1014_10140801_164_dialog_content = "Itu diperbaiki sementara, hanya karena kerusakan yang tidak diketahui membuat Colossus menjadi rusak.",
  ui_story_1014_10140801_165_dialog_content = "Colossus yang tak terkendali, akhirnya, menabrak Zona Gelap yang sulit dipahami.",
  ui_story_1014_10140801_166_dialog_content = "Hancur di Zona Gelap? Betapa ruginya!",
  ui_story_1014_10140801_167_dialog_content = "Ya, banyak generasi yang lebih tua masih menyimpan dendam terhadap Illumina untuk itu.",
  ui_story_1014_10140801_168_dialog_content = "Jadi tentara mereka bersikap dingin.",
  ui_story_1014_10140801_169_dialog_content = "Saya mengerti! Saya bertanya-tanya mengapa orang tua di pasar tidak mau berbicara dengan saya.",
  ui_story_1014_10140801_170_dialog_content = "Saya pikir saya menyinggung mereka entah bagaimana ...",
  ui_story_1014_10140801_171_dialog_content = "Begitulah cara kerja di Twilight. Banyak peristiwa yang tidak jelas pelakunya, sehingga konflik tidak pernah terselesaikan.",
  ui_story_1014_10140801_172_dialog_content = "Juga sulit untuk menentukan benar versus salah dalam upaya Illumina.",
  ui_story_1014_10140801_173_dialog_content = "Menyebabkan kota Twilight kehilangan Colossus kuno tentu saja salah mereka.",
  ui_story_1014_10140801_174_dialog_content = "Tetapi jika penelitian mereka akhirnya membantu memperbaiki Colossus PlayerName, yah, itu tidak semuanya buruk.",
  ui_story_1014_10140801_175_dialog_content = "Omong-omong, peneliti Illumina menghubungi saya.",
  ui_story_1014_10140801_176_dialog_content = "Dia sangat tertarik untuk memperbaiki Colossus dan ingin memulainya secepat mungkin.",
  ui_story_1014_10140801_177_dialog_content = "Betulkah? Tapi ini sangat larut. Dia harus bersiap-siap untuk tidur.",
  ui_story_1014_10140801_178_dialog_content = "Jangan khawatir tentang itu, dia baru saja bangun.",
  ui_story_1014_10140801_179_dialog_content = "Baru saja bangun?",
  ui_story_1014_10140801_180_dialog_content = "Anda tahu mereka, para ilmuwan... Sekelompok eksentrik.",
  ui_story_1014_10140801_181_dialog_content = "Ya benar.",
  ui_story_1014_10140801_182_dialog_content = "Kalau begitu, ayo pergi ke fasilitas penelitian setelah kita makan.",
  ui_story_1014_10140801_183_dialog_content = "Saya tidak suka menunda-nunda dalam hal-hal yang melibatkan Soroz.",
  ui_story_1014_10140801_184_dialog_content = "<color=#e8d9bb>Mencicit-</color>",
  ui_story_1014_10140801_185_dialog_content = "Mereka meninggalkan.",
  ui_story_1014_10140801_186_dialog_content = "Menarik, orang luar ini.",
  ui_story_1014_10140801_187_dialog_content = "Ya, menarik.",
  ui_story_1014_10140801_188_dialog_content = "Perwira Illumina dan Putri Lumopolis... Tak kusangka mereka akan akur.",
  ui_story_1014_10140801_189_dialog_content = "Caelestite legendaris karena suatu alasan.",
  ui_story_1014_10140801_190_dialog_content = "Oh ya, apakah kamu tidak akan berterima kasih padaku?",
  ui_story_1014_10140801_191_dialog_content = "Haruskah saya, Yang Mulia? Saya akan berasumsi Anda akan cukup baik hati untuk menyelamatkan saya sebelum warga.",
  ui_story_1014_10140801_192_dialog_content = "Saya pikir berterima kasih kepada saya akan membuat Anda merasa lebih baik tentang diri Anda sendiri.",
  ui_story_1014_10140801_193_dialog_content = "Sebenarnya, Anda harus berterima kasih kepada saya.",
  ui_story_1014_10140801_194_dialog_content = "Mengapa demikian?",
  ui_story_1014_10140801_195_dialog_content = "Karena itu salahmu untuk terjun langsung ke pertempuran, mencoba menyelamatkan orang dengan sembrono.",
  ui_story_1014_10140801_196_dialog_content = "Anda bisa menjadi pahlawan setiap saat hanya karena seseorang mendukung Anda.",
  ui_story_1014_10140801_197_dialog_content = "Ah, kamu benar. Saya harus berterima kasih kepada seseorang itu.",
  ui_story_1014_10140801_198_dialog_content = "Tetapi dalam hal ini, Anda masih harus berterima kasih kepada saya.",
  ui_story_1014_10140801_199_dialog_content = "Kenapa bisa begitu?",
  ui_story_1014_10140801_200_dialog_content = "Karena aku memberimu lebih sedikit alasan untuk menyesal.",
  ui_story_1014_10140801_201_dialog_content = "Astaga, Colossus utuh!",
  ui_story_1014_10140801_202_dialog_content = "Ini luar biasa! Apakah Anda menyadari betapa berharganya ini untuk penelitian?",
  ui_story_1014_10140801_203_dialog_content = "Maafkan saya, tapi kami tidak menyerahkan Soroz untuk Anda pelajari.",
  ui_story_1014_10140801_204_dialog_content = "Kami datang ke—",
  ui_story_1014_10140801_205_dialog_content = "Ya, saya tahu, perdagangannya, bukan?",
  ui_story_1014_10140801_206_dialog_content = "Apakah Anda membawa Combat Cyborg?",
  ui_story_1014_10140801_207_dialog_content = "Ya, ini.",
  ui_story_1014_10140801_208_dialog_content = "Itu dia. Biarkan saja di sana.",
  ui_story_1014_10140801_209_dialog_content = "Serahkan kesadaran Colossus kepadaku.",
  ui_story_1014_10140801_210_dialog_content = "Tidak apa-apa bagi saya untuk merekam beberapa data saat saya melakukannya, bukan? Itu adil.",
  ui_story_1014_10140801_211_dialog_content = "Tentu, asalkan bisa membuat Soroz kembali sadar.",
  ui_story_1014_10140801_212_dialog_content = "Baiklah, biarkan saya mulai sekarang!",
  ui_story_1014_10140801_213_dialog_content = "Bisakah saya tinggal dan menonton?",
  ui_story_1014_10140801_214_dialog_content = "J-Kalau-kalau ada kecelakaan atau sesuatu.",
  ui_story_1014_10140801_215_dialog_content = "Tidak masalah, jika itu tidak membuat Anda bosan.",
  ui_story_1014_10140801_216_dialog_content = "Ini sangat terlambat, PlayerName. Apakah Anda yakin ingin tinggal di sini?",
  ui_story_1014_10140801_217_dialog_content = "Ya. Aku tidak bisa tidur saat Soroz sedang diperbaiki, jadi mungkin juga.",
  ui_story_1014_10140801_218_dialog_content = "Kalian harus menyerahkan diri.",
  ui_story_1014_10140801_219_dialog_content = "Apakah Anda akan baik-baik saja sendiri?",
  ui_story_1014_10140801_220_dialog_content = "Tidak masalah. Bagaimanapun, ini adalah wilayah Illumina. Tidak ada yang harus terjadi.",
  ui_story_1014_10140801_221_dialog_content = "Baiklah kalau begitu. Jangan berlebihan.",
  ui_story_1014_10140801_222_dialog_content = "Aku paham.",
  ui_story_1014_10140801_223_dialog_content = "<color=#e8d9bb>Dentang, dentang!</color>",
  ui_story_1014_10140801_224_dialog_content = "Hei, bangun, Caelestite.",
  ui_story_1014_10140801_225_dialog_content = "Apa...",
  ui_story_1014_10140801_226_dialog_content = "Bangkit dan bersinar. Tidak ada lagi tidur.",
  ui_story_1014_10140801_227_dialog_content = "Ugh...",
  ui_story_1014_10140801_228_dialog_content = "Mengapa Anda hanya membalik?",
  ui_story_1014_10140801_229_dialog_content = "Bangun dan lihat sendiri...",
  ui_story_1014_10140801_230_dialog_content = "Sudah lama, PlayerName.",
  ui_story_1014_10140801_231_dialog_content = "<size=50>!!!</size>",
  ui_story_1014_10140801_232_dialog_content = "Soroz! Apakah... Apakah Anda kembali?",
  ui_story_1014_10140801_233_dialog_content = "Lanjutkan. Saya sudah selesai dengan perbaikan.",
  ui_story_1014_10140801_234_dialog_content = "Tapi kami belum memiliki cukup data untuk mempertahankan kesadarannya.",
  ui_story_1014_10140801_235_dialog_content = "Anda lebih baik memanfaatkan kesempatan ini.",
  ui_story_1014_10140801_236_dialog_content = "Ini tidak bisa dipertahankan?",
  ui_story_1014_10140801_237_dialog_content = "Terima kasih, PlayerName, untuk terus berusaha menemukan cara untuk memulihkan saya.",
  ui_story_1014_10140801_238_dialog_content = "Senang mendengar suaramu lagi, Soroz!",
  ui_story_1014_10140801_239_dialog_content = "Banyak yang telah terjadi. Saya ingin memulai dengan—",
  ui_story_1014_10140801_240_dialog_content = "Maaf, tapi aku juga tidak bisa bertahan lama kali ini.",
  ui_story_1014_10140801_241_dialog_content = "...",
  ui_story_1014_10140801_242_dialog_content = "Pendekatan Anda benar, tetapi kurang dalam data pendukung.",
  ui_story_1014_10140801_243_dialog_content = "Ya, saya tidak mendapatkan kesempatan untuk menyelesaikan penelitian saya sebelum Colossus... Huh.",
  ui_story_1014_10140801_244_dialog_content = "A-Apa yang harus kita lakukan?",
  ui_story_1014_10140801_245_dialog_content = "Saya menemukan Colossus lain itu.",
  ui_story_1014_10140801_246_dialog_content = "Apa?!",
  ui_story_1014_10140801_247_dialog_content = "Kita hanya perlu menemukannya? Dimana itu?",
  ui_story_1014_10140801_248_dialog_content = "<anim type=Shake>Waktuku hampir habis...</anim>",
  ui_story_1014_10140801_249_dialog_content = "<anim type=Shake>Saya akan meninggalkan koordinat di terminal ...</anim>",
  ui_story_1014_10140801_250_dialog_content = "Koordinat? Untuk Raksasa?",
  ui_story_1014_10140801_251_dialog_content = "<anim type=Shake>PlayerName, Aku percaya padamu.</anim>",
  ui_story_1014_10140801_252_dialog_content = "<anim type=Shake>Tolong... percayalah pada dirimu sendiri juga.</anim>",
  ui_story_1014_10140901_1_dialog_content = "Inilah peta pertempuran terlengkap untuk Aurora Ruins.",
  ui_story_1014_10140901_2_dialog_content = "Saya mendapatkan ini melalui akses khusus, jadi jangan perlihatkan kepada orang lain.",
  ui_story_1014_10140901_3_dialog_content = "Koordinat yang Anda cari seharusnya ada di sekitar sini.",
  ui_story_1014_10140901_4_dialog_content = "Apakah itu di Zona Gelap?",
  ui_story_1014_10140901_5_dialog_content = "Ya, dan itu adalah Undercity pada saat itu.",
  ui_story_1014_10140901_6_dialog_content = "Illumina mempertahankan penjelajahan mereka ke permukaan dan tidak lebih dalam.",
  ui_story_1014_10140901_7_dialog_content = "Jadi, ini pada dasarnya adalah wilayah yang belum dipetakan.",
  ui_story_1014_10140901_8_dialog_content = "Bisakah kita pergi ke sana?",
  ui_story_1014_10140901_9_dialog_content = "Ya, tapi ini sangat berbahaya, jadi lebih baik Anda memikirkannya.",
  ui_story_1014_10140901_10_dialog_content = "Dipahami. Tidak ada yang perlu dipikirkan. Ini untuk Soroz, jadi aku harus pergi.",
  ui_story_1014_10140901_11_dialog_content = "Aku tidak berusaha menghentikanmu. Aku hanya ingin kau memikirkannya.",
  ui_story_1014_10140901_12_dialog_content = "Katakanlah Anda menemukan Colossus tua, lalu apa? Bagaimana Anda mengangkutnya kembali?",
  ui_story_1014_10140901_13_dialog_content = "Nah, eh...",
  ui_story_1014_10140901_14_dialog_content = "Tidak apa-apa, saya akan membantu! Saya mendapatkan atasan saya untuk menyita kendaraan transportasi!",
  ui_story_1014_10140901_15_dialog_content = "Saya berlatih mengemudi sebelumnya. Aku bisa menarik Colossus kembali!",
  ui_story_1014_10140901_16_dialog_content = "Betulkah? Indah sekali!",
  ui_story_1014_10140901_17_dialog_content = "Kalian berdua...",
  ui_story_1014_10140901_18_dialog_content = "Jika Anda berdua dapat menggabungkan satu sel otak Anda menjadi otak yang berfungsi, saya akan menyebutnya keajaiban.",
  ui_story_1014_10140901_19_dialog_content = "Pertama-tama mari kita abaikan apakah Colossus bisa muat di belakang kendaraan.",
  ui_story_1014_10140901_20_dialog_content = "Apakah kota bawah secara ajaib memiliki jalan beraspal untuk Anda kendarai? Bagaimana Anda akan menjauh dari Eclipsites yang berkerumun?",
  ui_story_1014_10140901_21_dialog_content = "Eh ... tentang itu ...",
  ui_story_1014_10140901_22_dialog_content = "Bagian spesifik apa yang Anda butuhkan untuk memperbaiki Soroz, Peneliti?",
  ui_story_1014_10140901_23_dialog_content = "Sejujurnya, saya lebih suka Colossus utuh.",
  ui_story_1014_10140901_24_dialog_content = "Kami tidak tahu segalanya tentang Colossi, jadi apa pun yang hilang bisa menjadi masalah.",
  ui_story_1014_10140901_25_dialog_content = "Tapi jika aku harus memilih salah satu...",
  ui_story_1014_10140901_26_dialog_content = "Itu akan menjadi <color=#FFB400>Modul Kontrol Utama</color>.",
  ui_story_1014_10140901_27_dialog_content = "Ini memiliki nilai penelitian terbesar, dan merupakan subjek dari penelitian sebelumnya.",
  ui_story_1014_10140901_28_dialog_content = "Oke. Mari menilai kembali tujuan kita. Bukan keseluruhan Colossus, tapi modul Kontrol Utama di atasnya.",
  ui_story_1014_10140901_29_dialog_content = "Operasi ini melampaui batas dari apa yang Anda negosiasikan di Gannon.",
  ui_story_1014_10140901_30_dialog_content = "Oleh karena itu, Anda tidak akan menerima bantuan tambahan dari Illumina.",
  ui_story_1014_10140901_31_dialog_content = "Ya aku tahu. Ini urusan pribadi.",
  ui_story_1014_10140901_32_dialog_content = "Namun, Anda mungkin masih menerima bantuan dari individu tertentu.",
  ui_story_1014_10140901_33_dialog_content = "Hah?",
  ui_story_1014_10140901_34_dialog_content = "Apakah Anda menyiratkan bahwa saya dapat membantu, Yingel?",
  ui_story_1014_10140901_35_dialog_content = "Ya. Jadwal Anda terbuka. Anda bebas melakukan apa yang Anda suka.",
  ui_story_1014_10140901_36_dialog_content = "Oh ya!",
  ui_story_1014_10140901_37_dialog_content = "Sean...",
  ui_story_1014_10140901_38_dialog_content = "Demikian pula, Axelia dan aku juga tidak punya apa-apa di piring kami.",
  ui_story_1014_10140901_39_dialog_content = "Kalian ingin membantuku juga?",
  ui_story_1014_10140901_40_dialog_content = "Kota bawah di Zona Gelap sangat mematikan. Saya lebih suka Sean tidak memimpin satu-satunya Caelestite di dunia menuju kematiannya.",
  ui_story_1014_10140901_41_dialog_content = "Aku akan memeriksa kondisi Axelia. Kami akan pergi saat kami siap.",
  ui_story_1014_10140901_42_dialog_content = "Dingin, PlayerName! Biarkan saya mengambil truk dari atasan saya!",
  ui_story_1014_10140901_43_dialog_content = "Aku kehilangan kata-kata...",
  ui_story_1014_10140901_44_dialog_content = "Terima kasih banyak.",
  ui_story_1014_10140901_45_dialog_content = "<color=#e8d9bb>Wuush!</color>",
  ui_story_1014_10140901_46_dialog_content = "Permen untukmu, Axelia.",
  ui_story_1014_10140901_47_dialog_content = "Oke.",
  ui_story_1014_10140901_48_dialog_content = "Bagaimana dengan tugasmu, Yingel?",
  ui_story_1014_10140901_49_dialog_content = "Ini sudah berakhir. Kita sampai di sini dengan selamat, bukan?",
  ui_story_1014_10140901_50_dialog_content = "Maksudku yang lain.",
  ui_story_1014_10140901_51_dialog_content = "Yang lain?",
  ui_story_1014_10140901_52_dialog_content = "Jika Anda menyelesaikan misi Anda, Anda tidak akan terus membantu PlayerName.",
  ui_story_1014_10140901_53_dialog_content = "Anda memiliki beberapa agenda lain.",
  ui_story_1014_10140901_54_dialog_content = "...",
  ui_story_1014_10140901_55_dialog_content = "Saya tidak pernah tahu apa yang ada di kepala Anda, kadang-kadang. Anda tampaknya tidak memperhatikan, namun Anda tahu segalanya.",
  ui_story_1014_10140901_56_dialog_content = "Aku tahu kamu, Yingel.",
  ui_story_1014_10140901_57_dialog_content = "Jika itu adalah tugas yang seharusnya tidak saya ketahui, Anda tidak perlu mengatakan apa pun.",
  ui_story_1014_10140901_58_dialog_content = "Saya mencari <color=#FFB400>Meninggalkan</color>.",
  ui_story_1014_10140901_59_dialog_content = "Ilmuwan pengkhianat itu?",
  ui_story_1014_10140901_60_dialog_content = "Ya.",
  ui_story_1014_10140901_61_dialog_content = "Dia di Twilight?",
  ui_story_1014_10140901_62_dialog_content = "Tidak ada yang tahu di mana dia berada.",
  ui_story_1014_10140901_63_dialog_content = "Jadi yang terbaik yang bisa saya lakukan adalah memancingnya keluar.",
  ui_story_1014_10140901_64_dialog_content = "Caelestite adalah umpannya?",
  ui_story_1014_10140901_65_dialog_content = "Mm. Tidak ada yang bisa lebih baik.",
  ui_story_1014_10140901_66_dialog_content = "Saya kira dia tidak tahu.",
  ui_story_1014_10140901_67_dialog_content = "Dia akan marah, kau tahu.",
  ui_story_1014_10140901_68_dialog_content = "...",
  ui_story_1014_10140901_69_dialog_content = "Keberatan untuk tidur siang setelah selesai dengan permennya, Axelia?",
  ui_story_1014_10140901_70_dialog_content = "Aku ingin kau tidur sampai aku membangunkanmu.",
  ui_story_1014_10140901_71_dialog_content = "Aku akan mendengarkanmu.",
  ui_story_1014_10140901_72_dialog_content = "Aku bilang aku pergi!",
  ui_story_1014_10140901_73_dialog_content = "Dan saya mengerti itu, Yang Mulia.",
  ui_story_1014_10140901_74_dialog_content = "Lalu apa yang kau lakukan menghalangi jalanku?",
  ui_story_1014_10140901_75_dialog_content = "Harap mengerti bahwa saya hanya mengikuti perintah Tuan Kota.",
  ui_story_1014_10140901_76_dialog_content = "Penguasa Kota? Mengapa saya mendengar nama ini bahkan di Twilight?",
  ui_story_1014_10140901_77_dialog_content = "Dia tidak pernah peduli tentang apa yang terjadi di perbatasan.",
  ui_story_1014_10140901_78_dialog_content = "Karena Anda di sini, Yang Mulia. Ini situasi yang sulit bagi kami juga, harap dipahami.",
  ui_story_1014_10140901_79_dialog_content = "Kami hanya bertugas patroli, Benteng Lumo tidak berhak ikut campur.",
  ui_story_1014_10140901_80_dialog_content = "Tolong tunjukkan dokumen yang tepat jika ini adalah perintah dari Tuan Kota.",
  ui_story_1014_10140901_81_dialog_content = "Anu…",
  ui_story_1014_10140901_82_dialog_content = "Carleen? Beretta? Apa yang terjadi di sini?",
  ui_story_1014_10140901_83_dialog_content = "Mengapa penjaga Lumopolis menahan Anda?",
  ui_story_1014_10140901_84_dialog_content = "Tepat waktu, PlayerName, Keburukan.",
  ui_story_1014_10140901_85_dialog_content = "Beretta dan aku ingin pergi ke Benteng Lumo untuk membeli perbekalan sebelum berangkat.",
  ui_story_1014_10140901_86_dialog_content = "Tapi mereka menolak untuk membiarkan kami lewat.",
  ui_story_1014_10140901_87_dialog_content = "Kami tidak menghentikan Anda, Yang Mulia. Hanya saja tempat yang Anda tuju sangat berbahaya. Kami harus mengirimkan pendamping untuk memastikan keselamatan Anda.",
  ui_story_1014_10140901_88_dialog_content = "Saya tidak pernah membutuhkan perlindungan siapa pun di medan perang.",
  ui_story_1014_10140901_89_dialog_content = "Hai PlayerName, saya telah mencari Anda ke mana-mana.",
  ui_story_1014_10140901_90_dialog_content = "Kudengar kau akan pergi ke Undercity di Zona Gelap. Bolehkah saya ikut?",
  ui_story_1014_10140901_91_dialog_content = "Anda ingin pergi juga?",
  ui_story_1014_10140901_92_dialog_content = "Apakah Anda bala bantuan yang dikirim oleh Benteng Lumo?",
  ui_story_1014_10140901_93_dialog_content = "Tidak tidak. Aku sudah lama ingin pergi ke Undercity itu.",
  ui_story_1014_10140901_94_dialog_content = "Aktivitas Eclipsite baru-baru ini di sekitar Twilight entah bagaimana terkait dengan tempat itu.",
  ui_story_1014_10140901_95_dialog_content = "Saya ingin memeriksanya, tetapi tidak nyaman untuk mengambil ksatria lain, dan saya akan kalah jumlah jika sendirian.",
  ui_story_1014_10140901_96_dialog_content = "Karena Anda akan pergi, ini adalah kesempatan sempurna bagi saya.",
  ui_story_1014_10140901_97_dialog_content = "Aku tahu.",
  ui_story_1014_10140901_98_dialog_content = "Adapun penguatan dari Lumo Stronghold, itu orang lain.",
  ui_story_1014_10140901_99_dialog_content = "Dan inilah dia.",
  ui_story_1014_10140901_100_dialog_content = "Saya tidak membuat semua orang menunggu, saya berharap.",
  ui_story_1014_10140901_101_dialog_content = "Pesanan datang agak mendesak, jadi saya hanya membuat sedikit persiapan.",
  ui_story_1014_10140901_102_dialog_content = "Anda akhirnya di sini, <color=#FFB400>Pastor Joseph</color>.",
  ui_story_1014_10140901_103_dialog_content = "Lady Carleen, ini Pastor Joseph dari Gereja dan pengiring Anda. Dia akan menemani Anda dalam perjalanan Anda.",
  ui_story_1014_10140901_104_dialog_content = "Reputasi Anda mendahului Anda, Yang Mulia.",
  ui_story_1014_10140901_105_dialog_content = "Karena dia ada di sini, kami tidak akan menahanmu lagi di sini.",
  ui_story_1014_10140901_106_dialog_content = "Saya berharap yang terbaik untuk Anda, Yang Mulia.",
  ui_story_1014_10140901_107_dialog_content = "Hanya dia?",
  ui_story_1014_10140901_108_dialog_content = "Ya. Permintaan maaf saya. Ini bukan kelalaian pihak Gereja, kami hanya kekurangan tenaga.",
  ui_story_1014_10140901_109_dialog_content = "Jangan dengarkan dia. Anda beruntung Gereja mengirimnya.",
  ui_story_1014_10140901_110_dialog_content = "Ini air yang dalam di mana kita akan pergi. Kami membutuhkan kualitas, bukan kuantitas.",
  ui_story_1014_10140901_111_dialog_content = "Saya melihat doa Anda akhirnya terkabul, Leo.",
  ui_story_1014_10140901_112_dialog_content = "Ya, terima kasih kepada PlayerName. Tidak setiap hari Anda menyusun tim seperti ini.",
  ui_story_1014_10140901_113_dialog_content = "Dan itu belum semuanya. Gadis sipil itu akan datang untukmu lagi.",
  ui_story_1014_10140901_114_dialog_content = "Gadis sipil...",
  ui_story_1014_10140901_115_dialog_content = "Saya lebih menyukainya daripada Yang Mulia.",
  ui_story_1014_10140901_116_dialog_content = "Joselyne? Apa yang kamu lakukan di sini?",
  ui_story_1014_10140901_117_dialog_content = "Bolehkah saya bergabung dengan Anda, PlayerName?",
  ui_story_1014_10140901_118_dialog_content = "Apa? Oh, tentu, tentu saja!",
  ui_story_1014_10140901_119_dialog_content = "Tapi, kenapa?",
  ui_story_1014_10140901_120_dialog_content = "Saya tidak tahan melihat pengunjung dari jauh menjelajah langsung ke dalam kegelapan.",
  ui_story_1014_10140901_121_dialog_content = "Setidaknya aku bisa menyalakan sudut untukmu.",
  ui_story_1014_10140901_122_dialog_content = "<color=#e8d9bb>Klak—Kak—</color>",
  ui_story_1014_10140901_123_dialog_content = "<color=#e8d9bb>Mendering-</color>",
  ui_story_1014_10140901_124_dialog_content = "Hmm, kenapa berhenti lagi?",
  ui_story_1014_10140901_125_dialog_content = "Apakah ada yang macet?",
  ui_story_1014_10140901_126_dialog_content = "Cukup, Sean, berhenti mengutak-atik truk.",
  ui_story_1014_10140901_127_dialog_content = "Sudah kubilang, itu tidak akan berhasil. Disini cukup jauh.",
  ui_story_1014_10140901_128_dialog_content = "Semua orang keluar dari kendaraan. Kami berada di luar Undercity.",
  ui_story_1014_10140901_129_dialog_content = "Waktunya bangun, Axelia.",
  ui_story_1014_10140901_130_dialog_content = "Oh, oke, aku tidur siang yang menyenangkan.",
  ui_story_1014_10140901_131_dialog_content = "Jadi begini...",
  ui_story_1014_10140901_132_dialog_content = "Tidak mengherankan, Darkflow sangat intens.",
  ui_story_1014_10140901_133_dialog_content = "Zona Gelap ada di depan.",
  ui_story_1014_10140901_134_dialog_content = "Itu membuat saya gugup. Saya memiliki kesan yang buruk tentang Zona Gelap.",
  ui_story_1014_10140901_135_dialog_content = "Adakah orang di sini yang pernah ke Undercity?",
  ui_story_1014_10140901_136_dialog_content = "Beberapa orang tua memilikinya, tetapi mereka memperingatkan orang lain untuk tidak pernah menginjakkan kaki di Zona Gelap.",
  ui_story_1014_10140901_137_dialog_content = "Padahal menurutku tidak ada yang perlu ditakutkan. Maksudku, orang-orang tua itu tidak tahan peluru.",
  ui_story_1014_10140901_138_dialog_content = "Jadi jika mereka bisa keluar dari sana hidup-hidup, kita seharusnya tidak punya masalah.",
  ui_story_1014_10140901_139_dialog_content = "Heh, saya pikir Anda akan lebih berwawasan dari itu.",
  ui_story_1014_10140901_140_dialog_content = "Saya belum pernah ke Zona Gelap sebelumnya, wawasan apa yang bisa saya tawarkan?",
  ui_story_1014_10140901_141_dialog_content = "Mari percayai Leo, dia selalu benar dalam penilaiannya.",
  ui_story_1014_10140901_142_dialog_content = "Berhenti menyanjung saya. Saya sebenarnya lebih suka mendengar pendapat Anda tentang masalah ini.",
  ui_story_1014_10140901_143_dialog_content = "Nah, melihat sekeliling, saya tidak berpikir itu menakutkan seperti yang saya kira.",
  ui_story_1014_10140901_144_dialog_content = "Bahkan Eclipsites tampak lebih tangguh.",
  ui_story_1014_10140901_145_dialog_content = "Baiklah, jika kita semua sudah siap, mari menuju Undercity.",
  ui_story_1014_10140901_146_dialog_content = "Sudah waktunya untuk menemukan Colossus itu.",
  ui_story_1014_10140901_147_dialog_content = "Oh, semua kebisingan ini. Sangat menjengkelkan.",
  ui_story_1014_10140901_148_dialog_content = "Sudah beberapa waktu sejak bantahan ini.",
  ui_story_1014_10140901_149_dialog_content = "Apa, oh apa, mungkinkah ini? Lebih intens dari tetesan hujan, lebih menjengkelkan dari panggilan serangga.",
  ui_story_1014_10140901_150_dialog_content = "Ah iya. Itu pasti suara orang.",
  ui_story_1014_10140901_151_dialog_content = "Suara orang yang paling hina.",
  ui_story_1014_10141101_1_dialog_content = "Apakah ini reruntuhan dengan Colossus?",
  ui_story_1014_10141101_2_dialog_content = "Itulah yang tertulis di peta.",
  ui_story_1014_10141101_3_dialog_content = "Hati-hati, ada banyak Eclipsites di sini.",
  ui_story_1014_10141101_4_dialog_content = "...",
  ui_story_1014_10141101_5_dialog_content = "Itu aneh. Mengapa begitu banyak Eclipsites di sini?",
  ui_story_1014_10141101_6_dialog_content = "Menurut pola perilaku mereka, mereka seharusnya tidak berkumpul di sini.",
  ui_story_1014_10141101_7_dialog_content = "Tapi lingkungan ini berbeda dan mungkin memiliki karakteristik yang belum kita sadari.",
  ui_story_1014_10141101_8_dialog_content = "Saya tidak yakin apa yang menggambar Eclipsites di sini, kecuali ada sesuatu yang mengendalikannya.",
  ui_story_1014_10141101_9_dialog_content = "Ini sangat tidak biasa, jadi berhati-hatilah.",
  ui_story_1014_10141101_10_dialog_content = "Eclipsites bukanlah sesuatu yang perlu ditakuti. Kekalahan mereka adalah satu-satunya hasil.",
  ui_story_1014_10141101_11_dialog_content = "Apakah Anda benar-benar sangat kuat?",
  ui_story_1014_10141101_12_dialog_content = "Jangan remehkan dia. Dia yang terkuat di antara kita! Bahkan terkadang aku tidak bisa mengalahkannya.",
  ui_story_1014_10141101_13_dialog_content = "Dari pengamatan saya terhadap spar Sean dan Axelia, dia kalah sembilan kali dari sepuluh, dan hanya mengikatnya sekali.",
  ui_story_1014_10141101_14_dialog_content = "Saya tidak perlu mengerahkan upaya nyata saat melawan Sean.",
  ui_story_1014_10141101_15_dialog_content = "Oi, jangan terus terang begitu!",
  ui_story_1014_10141101_16_dialog_content = "Haha, kamu pasti rukun.",
  ui_story_1014_10141101_17_dialog_content = "Tapi di sini tidak aman, jadi jangan bercanda.",
  ui_story_1014_10141101_18_dialog_content = "Kita perlu menemukan modul yang dibutuhkan PlayerName secepat mungkin dan keluar dari sini.",
  ui_story_1014_10141101_19_dialog_content = "Saya melihat banyak Eclipsites di jalan, jadi bagaimana dengan ini?",
  ui_story_1014_10141101_20_dialog_content = "Axelia, mari kita lihat siapa yang membunuh lebih banyak dari mereka!",
  ui_story_1014_10141101_21_dialog_content = "Yingel bisa menjadi wasit.",
  ui_story_1014_10141101_22_dialog_content = "Ini dia lagi.",
  ui_story_1014_10141101_23_dialog_content = "Baik. Tapi jangan merengek jika kalah.",
  ui_story_1014_10141101_24_dialog_content = "<color=#e8d9bb>Di suatu tempat di luar Reruntuhan Aurora</color>",
  ui_story_1014_10141101_25_dialog_content = "(Eclipsian) Tuhan <color=#FFB400>Asmodeus</color>, Aurorian dan Caelestite telah memasuki reruntuhan.",
  ui_story_1014_10141101_26_dialog_content = "(Eclipsian) Mereka telah melibatkan kerabat kita di dalamnya.",
  ui_story_1014_10141101_27_dialog_content = "(Eclipsian) Biarkan mereka berbaris maju.",
  ui_story_1014_10141101_28_dialog_content = "(Eclipsian) Mungkin keinginan mereka akan membawa saya ke apa yang saya cari.",
  ui_story_1014_10141102_1_dialog_content = "Eclipsite terakhir—milikku!",
  ui_story_1014_10141102_2_dialog_content = "Aaaaah!!",
  ui_story_1014_10141102_3_dialog_content = "Jadi, siapa yang menang, Yingel?",
  ui_story_1014_10141102_4_dialog_content = "Oke, saya akan umumkan hasilnya.",
  ui_story_1014_10141102_5_dialog_content = "Sean membunuh 20 Eclipsites.",
  ui_story_1014_10141102_6_dialog_content = "Oh, masih sedikit kurang dari yang terbaik sepanjang masa.",
  ui_story_1014_10141102_7_dialog_content = "Axelia terbunuh—",
  ui_story_1014_10141102_8_dialog_content = "32!",
  ui_story_1014_10141102_9_dialog_content = "Dengan serius?!",
  ui_story_1014_10141102_10_dialog_content = "Mustahil!",
  ui_story_1014_10141102_11_dialog_content = "Anda menghabiskan terlalu banyak waktu mengejar orang-orang yang melarikan diri, Sean.",
  ui_story_1014_10141102_12_dialog_content = "Axelia memfokuskan energinya pada massa yang dipimpin oleh Eclipsites yang lebih besar.",
  ui_story_1014_10141102_13_dialog_content = "Yah, tidak ada yang bisa saya lakukan tentang itu ...",
  ui_story_1014_10141102_14_dialog_content = "Di mana keahlian saya saat ini, saya harus mengurangi Eclipsites yang lebih lemah terlebih dahulu dan meningkatkannya ke yang lebih besar.",
  ui_story_1014_10141102_15_dialog_content = "Benar, dan itulah alasan Axelia menang.",
  ui_story_1014_10141102_16_dialog_content = "Tikus, Axelia menang lagi!",
  ui_story_1014_10141102_17_dialog_content = "Sean kalah lagi.",
  ui_story_1014_10141102_18_dialog_content = "Tapi Sean tidak akan menyerah. Sean menikmati tantangan dan tidak akan menyerah bahkan jika dia gagal.",
  ui_story_1014_10141102_19_dialog_content = "Sampai dia menang.",
  ui_story_1014_10141102_20_dialog_content = "Aku tahu kau paling mengenalku, Axelia.",
  ui_story_1014_10141102_21_dialog_content = "Namun, tidak mungkin bagi Sean untuk mengalahkanku.",
  ui_story_1014_10141102_22_dialog_content = "Jangan terlalu yakin. Saya akan terus menjadi lebih baik!",
  ui_story_1014_10141102_23_dialog_content = "Apa pendapat Anda tentang penampilan mereka, Joseph?",
  ui_story_1014_10141102_24_dialog_content = "Apakah Anda meminta pendapat saya?",
  ui_story_1014_10141102_25_dialog_content = "Tentu saja. Anda telah menonton mereka diam-diam selama ini, jadi Anda harus memilikinya.",
  ui_story_1014_10141102_26_dialog_content = "(Joseph hampir tidak berbicara karena dia memperhatikan kami?)",
  ui_story_1014_10141102_27_dialog_content = "Saya pikir semua orang di Illumina luar biasa dalam hak mereka sendiri.",
  ui_story_1014_10141102_28_dialog_content = "Axelia sangat kompeten dengan mesin. Yingel mahir dalam observasi dan dukungan. Sean pandai mengadaptasi pengalaman menjadi keterampilan.",
  ui_story_1014_10141102_29_dialog_content = "Kalian bertiga bersama-sama membuat tim yang sempurna.",
  ui_story_1014_10141102_30_dialog_content = "…!",
  ui_story_1014_10141102_31_dialog_content = "Saya setuju dengan penilaian Anda.",
  ui_story_1014_10141102_32_dialog_content = "Terima kasih atas pengakuannya.",
  ui_story_1014_10141102_33_dialog_content = "(Joseph memiliki wawasan yang sangat tajam!)",
  ui_story_1014_10141102_34_dialog_content = "Axelia benar-benar mengesankan.",
  ui_story_1014_10141102_35_dialog_content = "Dia mungkin akan meraih posisi pertama dalam peringkat individu jika dia berpartisipasi dalam latihan militer bersama!",
  ui_story_1014_10141102_36_dialog_content = "Anda tahu tentang latihan militer bersama?",
  ui_story_1014_10141102_37_dialog_content = "Ya, Reinhard pernah bercerita tentang mereka sebelumnya.",
  ui_story_1014_10141102_38_dialog_content = "Dia bahkan mengatakan dia sangat menantikan untuk bertanding dengan sang juara.",
  ui_story_1014_10141102_39_dialog_content = "Kedengarannya seperti sesuatu yang akan dia lakukan.",
  ui_story_1014_10141102_40_dialog_content = "Saya juga berharap untuk melihat dia melawan seseorang seperti Axelia di acara tersebut.",
  ui_story_1014_10141102_41_dialog_content = "Tentu saja, jika ada kesempatan, saya ingin bertanding dengan Lady Carleen, mantan juara.",
  ui_story_1014_10141102_42_dialog_content = "Dasar kurang ajar!",
  ui_story_1014_10141102_43_dialog_content = "Ya, benar.",
  ui_story_1014_10141102_44_dialog_content = "Saya akan berpartisipasi dalam acara berikutnya.",
  ui_story_1014_10141102_45_dialog_content = "Saya berharap untuk melawan Anda, Leo.",
  ui_story_1014_10141102_46_dialog_content = "Itu kesepakatan.",
  ui_story_1014_10141102_47_dialog_content = "Apakah Anda mendaftar untuk acara itu juga, Leo?",
  ui_story_1014_10141102_48_dialog_content = "Ya.",
  ui_story_1014_10141102_49_dialog_content = "Semua Aurorian memenuhi syarat untuk itu.",
  ui_story_1014_10141102_50_dialog_content = "Saya akan pergi hanya untuk menguji diri saya melawan yang terbaik di seluruh Astra, tidak peduli seberapa jauh jaraknya.",
  ui_story_1014_10141102_X50_dialog_content = "<color=#e8d9bb>Jauh di dalam Reruntuhan Aurora</color>",
  ui_story_1014_10141102_51_dialog_content = "(Kita sudah sampai sejauh ini. Sepertinya perjalanan ini akan segera berakhir.)",
  ui_story_1014_10141102_52_dialog_content = "(Tapi masih belum terlihat Forsakin... Mungkinkah asumsi saya salah?)",
  ui_story_1014_10141102_53_dialog_content = "(Tidak, tujuannya selalu jelas, dan PlayerName adalah umpan terbaik.)",
  ui_story_1014_10141102_54_dialog_content = "(Saya tidak mungkin salah. Yang bisa saya lakukan sekarang adalah menunggu.)",
  ui_story_1014_10141102_55_dialog_content = "Yingel, mengapa kamu berhenti? Apakah Anda terluka?",
  ui_story_1014_10141102_56_dialog_content = "Hah...? Tidak, saya baik-baik saja, hanya ingin tahu mengapa ada begitu banyak Eclipsites.",
  ui_story_1014_10141102_57_dialog_content = "Izinkan saya untuk menyela...",
  ui_story_1014_10141102_58_dialog_content = "Tujuan dari misi ini adalah untuk membantu PlayerName menemukan komponen Colossus.",
  ui_story_1014_10141102_59_dialog_content = "Dari apa yang saya tahu, kita seharusnya tidak jauh dari Colossus kuno.",
  ui_story_1014_10141102_60_dialog_content = "Mari kita terus bergerak maju, ya?",
  ui_story_1014_10141102_61_dialog_content = "Ya, Nona Joselyne benar.",
  ui_story_1014_10141102_62_dialog_content = "Tempat ini membuatku heebie-jeebies seperti ada yang mengawasi kita...",
  ui_story_1014_10141102_63_dialog_content = "Kita harus mendapatkan bagian yang kita butuhkan dan kembali ke Twilight!",
  ui_story_1014_10141102_64_dialog_content = "<color=#e8d9bb>Di suatu tempat di luar Reruntuhan Aurora</color>",
  ui_story_1014_10141102_65_dialog_content = "(Eclipsian) Aroma keinginan mereka mendekati Colossus.",
  ui_story_1014_10141102_66_dialog_content = "(Eclipsian) Mungkinkah benda itu ada di dalam Colossus?",
  ui_story_1014_10141102_67_dialog_content = "(Eclipsian) Haruskah kita pindah sekarang, Tuan Asmodeus?",
  ui_story_1014_10141102_68_dialog_content = "(Eclipsian) Biarkan keinginan mereka mendekat, lebih dekat...",
  ui_story_1014_10141102_69_dialog_content = "(Eclipsian) Keinginan pengkhianat Caelestite itu akan menjadi sinyal yang memandu.",
  ui_story_1014_10141102_70_dialog_content = "(Eclipsian) Kita hanya perlu menunggu.",
  ui_story_1014_10141201_1_dialog_content = "Colossus tepat di depan. Jauhkan mata Anda kupas.",
  ui_story_1014_10141201_2_dialog_content = "Saya tidak sabar untuk Colossus dari zaman kuno ...",
  ui_story_1014_10141201_3_dialog_content = "<size=45>Itu sangat besar!</size>",
  ui_story_1014_10141201_4_dialog_content = "Ukurannya benar-benar melebihi harapan saya!",
  ui_story_1014_10141201_5_dialog_content = "Ukurannya termasuk yang terbesar dari semua Colossi yang ditemukan.",
  ui_story_1014_10141201_6_dialog_content = "Pasukan Illumina Federation yang ditempatkan di Twilight mempelajari Colossus ini dan memperoleh banyak data berharga.",
  ui_story_1014_10141201_7_dialog_content = "Jenis data apa?",
  ui_story_1014_10141201_8_dialog_content = "Informasi tentang bagaimana perangkat tertentu dibuat, seperti sebagian cetak biru untuk sistem medisnya.",
  ui_story_1014_10141201_9_dialog_content = "Ada penemuan lain, seperti data memori, atau pesan Caelestite kuno?",
  ui_story_1014_10141201_10_dialog_content = "Saya khawatir saya tidak dapat menjawabnya karena ini adalah informasi rahasia.",
  ui_story_1014_10141201_11_dialog_content = "Namun, karena kecelakaan operasi, Colossus melanjutkan a <color=#FFB400>mengamuk</color> satu kali.",
  ui_story_1014_10141201_12_dialog_content = "Insiden tersebut membuat banyak area internal di Colossus tidak dapat diakses.",
  ui_story_1014_10141201_13_dialog_content = "Setelah itu, itu ditetapkan sebagai objek berisiko tinggi dan bernilai rendah, seperti Reruntuhan Aurora yang terletak di dalamnya.",
  ui_story_1014_10141201_14_dialog_content = "Petugas Ulysses kemungkinan besar mengizinkan ekspedisi ini hanya karena Anda ada di dalamnya.",
  ui_story_1014_10141201_15_dialog_content = "Karena aku Caelestite?",
  ui_story_1014_10141201_16_dialog_content = "Benar.",
  ui_story_1014_10141201_17_dialog_content = "Caelestites dapat mengemudikan Colossi, sehingga kita dapat menemukan hal-hal yang tak terbayangkan.",
  ui_story_1014_10141201_18_dialog_content = "... Mari kita lanjutkan.",
  ui_story_1014_10141201_19_dialog_content = "Haruskah kita masuk ke dalam?",
  ui_story_1014_10141201_20_dialog_content = "Hati-hati.",
  ui_story_1014_10141201_21_dialog_content = "Saya melihat jejak aktivitas Eclipsite.",
  ui_story_1014_10141201_22_dialog_content = "Ada banyak Eclipsites di dalam Colossus ini.",
  ui_story_1014_10141201_23_dialog_content = "Tidak peduli berapa banyak mereka, saya harus mendapatkan datanya.",
  ui_story_1014_10141201_24_dialog_content = "Demi Soroz.",
  ui_story_1014_10141201_25_dialog_content = "Di sini sangat luas.",
  ui_story_1014_10141201_26_dialog_content = "Selain Eclipsites, tidak ada jejak apa pun.",
  ui_story_1014_10141201_27_dialog_content = "Apakah Colossus Anda memiliki kamar yang luas seperti ini, PlayerName?",
  ui_story_1014_10141201_28_option_content = "Ya.",
  ui_story_1014_10141201_29_dialog_content = "Kabin Soroz sangat luas, bahkan Anda bisa jogging di dalamnya tanpa masalah.",
  ui_story_1014_10141201_30_dialog_content = "Menakjubkan!",
  ui_story_1014_10141201_31_option_content = "Tidak.",
  ui_story_1014_10141201_32_dialog_content = "Kamar dan lorong di Soroz luas, tetapi biasanya ada banyak orang di dalamnya.",
  ui_story_1014_10141201_33_dialog_content = "Sehingga membuatnya terasa kurang lapang dari yang sebenarnya.",
  ui_story_1014_10141201_34_dialog_content = "Masuk akal!",
  ui_story_1014_10141201_35_dialog_content = "Ada pintu di depan.",
  ui_story_1014_10141201_36_dialog_content = "Itu menyerupai pintu yang mengarah ke kamar di Soroz.",
  ui_story_1014_10141201_37_dialog_content = "Pintu ini harus mengarah ke jembatan.",
  ui_story_1014_10141201_38_dialog_content = "Tampaknya disegel, tanpa pegangan atau kunci...",
  ui_story_1014_10141201_39_dialog_content = "Bagaimana kita akan membukanya?",
  ui_story_1014_10141201_40_dialog_content = "Semua pintu di Soroz terbuka secara telepati.",
  ui_story_1014_10141201_41_dialog_content = "Biarkan saya mencobanya dengan yang ini.",
  ui_story_1014_10141201_42_option_content = "Force Boost!",
  ui_story_1014_10141201_43_dialog_content = "<color=#e8d9bb>Wuush…</color>",
  ui_story_1014_10141201_44_dialog_content = "<color=#e8d9bb>Pengunjung Caelestite yang tidak terdaftar terdeteksi.</color>",
  ui_story_1014_10141201_45_dialog_content = "Apakah ini sistem utama pada Colossus ini? Kedengarannya sangat kaku.",
  ui_story_1014_10141201_46_dialog_content = "Seperti Soroz tanpa kepribadiannya...",
  ui_story_1014_10141201_47_dialog_content = "<color=#e8d9bb>Silahkan daftarkan diri anda.</color>",
  ui_story_1014_10141201_48_dialog_content = "Nama saya adalah PlayerName, Saya seorang Caelestite.",
  ui_story_1014_10141201_49_dialog_content = "<color=#e8d9bb>Pengguna yang tidak terdaftar diubah menjadi PlayerName.</color>",
  ui_story_1014_10141201_50_dialog_content = "<color=#e8d9bb>Anda telah diberi akses penuh ke Naviduz.</color>",
  ui_story_1014_10141201_51_dialog_content = "<color=#FFB400>Naviduz</color>...? Itu adalah salah satu Colossi dari zaman kuno!",
  ui_story_1014_10141201_52_dialog_content = "Akses penuh, bahkan?! Itu mudah!",
  ui_story_1014_10141201_53_dialog_content = "<color=#e8d9bb>Protokol akses Naviduz mematuhi izin yang ditetapkan oleh semua pilotnya.</color>",
  ui_story_1014_10141201_54_dialog_content = "<color=#e8d9bb>\"Di bawah 100 tahun, hanya administrator yang akan menerima akses penuh.\"</color>",
  ui_story_1014_10141201_55_dialog_content = "<color=#e8d9bb>\"Lebih dari 100 tahun tetapi di bawah... tahun, akses penuh... semua Caelestites.\"</color>",
  ui_story_1014_10141201_56_dialog_content = "<color=#e8d9bb>\"Selama... tahun tetapi di bawah... tahun, akses penuh... semua makhluk hidup.\"</color>",
  ui_story_1014_10141201_57_dialog_content = "<color=#e8d9bb>Menurut protokol, Naviduz saat ini memberikan akses penuh ke semua Caelestites.</color>",
  ui_story_1014_10141201_58_dialog_content = "Itu sudah berapa lama kamu menunggu? ... Saya minta maaf.",
  ui_story_1014_10141201_59_dialog_content = "<color=#e8d9bb>Kepribadian Naviduz ditangguhkan, tidak dapat memahami arti dari \"Maafkan aku\".</color>",
  ui_story_1014_10141201_60_dialog_content = "<color=#e8d9bb>Semua yang ada di Naviduz adalah hadiah untuk Caelestites di masa depan.</color>",
  ui_story_1014_10141201_61_dialog_content = "Kepribadian Anda ditangguhkan? Mengapa?",
  ui_story_1014_10141201_62_dialog_content = "<color=#e8d9bb>Kepribadian membutuhkan daya tambahan untuk dipertahankan.</color>",
  ui_story_1014_10141201_63_dialog_content = "<color=#e8d9bb>Untuk memastikan Naviduz dapat menyimpan dan meneruskan semua data ke Caelestites yang mungkin menemukan Colossus...</color>",
  ui_story_1014_10141201_64_dialog_content = "<color=#e8d9bb>Naviduz memilih untuk menangguhkan kepribadian dan memulai mode konservasi.</color>",
  ui_story_1014_10141201_65_dialog_content = "Apakah sistem dan data kepribadian Anda masih berfungsi?",
  ui_story_1014_10141201_66_dialog_content = "<color=#e8d9bb>Menjalankan diagnostik mandiri.</color>",
  ui_story_1014_10141201_67_dialog_content = "<color=#e8d9bb>\"Sistem kontrol utama, berjalan. Integritas komponen turun 72%. Diperlukan pemeliharaan.\"</color>",
  ui_story_1014_10141201_68_dialog_content = "<color=#e8d9bb>Modul biologi offline.</color>",
  ui_story_1014_10141201_69_dialog_content = "<color=#e8d9bb>Dukungan hidup offline.</color>",
  ui_story_1014_10141201_70_dialog_content = "<color=#e8d9bb>Data kepribadian memburuk 32%, tidak dapat beroperasi pada level normal.</color>",
  ui_story_1014_10141201_71_dialog_content = "Ini telah memburuk sampai tidak berfungsi?",
  ui_story_1014_10141201_72_dialog_content = "Jadi kamu juga, Naviduz...",
  ui_story_1014_10141201_73_dialog_content = "Bagaimanapun, terima kasih telah bertahan selama ini.",
  ui_story_1014_10141201_74_dialog_content = "Tolong buka pintu ke jembatan.",
  ui_story_1014_10141201_75_dialog_content = "<color=#e8d9bb>Perintah diterima.</color>",
  ui_story_1014_10141201_76_dialog_content = "<color=#e8d9bb>Gruk!</color>",
  ui_story_1014_10141201_77_dialog_content = "Pintunya terbuka.",
  ui_story_1014_10141201_78_dialog_content = "Saya melihat jembatan rusak dan konsol kontrol.",
  ui_story_1014_10141201_79_dialog_content = "<anim type=Shake><size=45>Aahhhhhhhh!</size></anim>",
  ui_story_1014_10141201_80_dialog_content = "Awas, inilah Eclipsites yang berkeliaran!",
  ui_story_1014_10141201_81_dialog_content = "Bersiaplah untuk bertarung!",
  ui_story_1014_10141302_1_dialog_content = "Semua Eclipsites dibersihkan.",
  ui_story_1014_10141302_2_dialog_content = "Tutup pintunya, PlayerName, jadi kami tidak mendapatkan teman mereka lagi.",
  ui_story_1014_10141302_3_dialog_content = "Saya akan memberi tahu Naviduz.",
  ui_story_1014_10141302_4_dialog_content = "...",
  ui_story_1014_10141302_5_dialog_content = "Apakah kamu baik-baik saja, Axelia?",
  ui_story_1014_10141302_6_dialog_content = "Anda berjuang untuk waktu yang lama. Kamu perlu istirahat.",
  ui_story_1014_10141302_7_dialog_content = "Aku tidak apa-apa.",
  ui_story_1014_10141302_8_dialog_content = "Konsekuensi dari pertempuran masih dalam jangkauan yang dapat diterima.",
  ui_story_1014_10141302_9_dialog_content = "Oke. Tetapi jika Anda merasa ada yang salah, segera beri tahu saya.",
  ui_story_1014_10141302_10_dialog_content = "Baiklah.",
  ui_story_1014_10141302_11_dialog_content = "(Aku hampir lupa bahwa kekuatan Axelia berasal dari bioteknologi Illumina.)",
  ui_story_1014_10141302_12_dialog_content = "(Dia biasanya tidak menunjukkan emosi, tapi untuk sesaat, dia tampak seperti kesakitan.)",
  ui_story_1014_10141302_13_dialog_content = "(Dia mungkin menahan lebih banyak rasa sakit daripada yang dia tunjukkan...)",
  ui_story_1014_10141302_14_dialog_content = "Anda bebas menyelesaikan pekerjaan Anda, PlayerName.",
  ui_story_1014_10141302_15_dialog_content = "Benar... terima kasih.",
  ui_story_1014_10141302_16_dialog_content = "Kami akan melihat-lihat, jadi waspadalah.",
  ui_story_1014_10141302_17_dialog_content = "Saya akan membantu PlayerName lihat Colossus.",
  ui_story_1014_10141302_18_dialog_content = "Naviduz, saya ingin mendapatkan data kepribadian Anda, jadi saya memerlukan modul Kontrol Utama.",
  ui_story_1014_10141302_19_dialog_content = "<color=#e8d9bb>Perintah diterima. Memeriksa status modul Kontrol Utama.</color>",
  ui_story_1014_10141302_20_dialog_content = "<color=#e8d9bb>Peringatan: Modul Primary Control mengalami kerusakan parah. Penghapusan paksa akan menyebabkan kerusakan permanen.</color>",
  ui_story_1014_10141302_21_dialog_content = "Kita tidak bisa menghapusnya?",
  ui_story_1014_10141302_22_dialog_content = "A-Apa yang akan kita lakukan sekarang?",
  ui_story_1014_10141302_23_dialog_content = "Anda terlihat khawatir. Saya punya saran.",
  ui_story_1014_10141302_24_dialog_content = "Battlesuitku memiliki perangkat duplikasi data. Anda dapat menghubungkannya ke Colossus.",
  ui_story_1014_10141302_25_dialog_content = "Kami mungkin tidak mendapatkan seluruh modul, tetapi kami masih dapat memperoleh data kepribadian yang diperlukan.",
  ui_story_1014_10141302_26_dialog_content = "Bagi Algol, data dan modul adalah satu dan sama.",
  ui_story_1014_10141302_27_dialog_content = "Saya kira itu satu-satunya pilihan yang kita miliki.",
  ui_story_1014_10141302_28_dialog_content = "PlayerName harus menghubungkan perangkat ke modul kontrol Colossus.",
  ui_story_1014_10141302_29_dialog_content = "Tekan tombol ini untuk mulai menggandakan data.",
  ui_story_1014_10141302_30_dialog_content = "Aku paham.",
  ui_story_1014_10141302_31_dialog_content = "<color=#e8d9bb>Menggandakan data. Harap tunggu.</color>",
  ui_story_1014_10141302_32_dialog_content = "Sepertinya kita memiliki lebih banyak menunggu untuk dilakukan.",
  ui_story_1014_10141302_33_dialog_content = "Kita dikelilingi oleh peninggalan teknologi kuno...",
  ui_story_1014_10141302_34_dialog_content = "Malam Putih di atas, saya harap mereka tidak akan mengancam keberadaan kita.",
  ui_story_1014_10141302_35_dialog_content = "<color=#e8d9bb>Bip, bip, bip...</color>",
  ui_story_1014_10141302_36_dialog_content = "Ini adalah markas Ironthorn Knights di Twilight. Harap balas jika Anda tersedia, Pak Leo.",
  ui_story_1014_10141302_37_dialog_content = "Ini adalah Ksatria Ekspedisi Leo. Lanjutkan.",
  ui_story_1014_10141302_38_dialog_content = "Tolong sampaikan lokasi dan kemajuan Anda.",
  ui_story_1014_10141302_39_dialog_content = "Kami sedang menjalankan misi untuk melindungi Caelestite PlayerName di Colossus di dalam Aurora Ruins.",
  ui_story_1014_10141302_40_dialog_content = "Lady Carleen dan beberapa Aurorian dari Illumina bersama kami.",
  ui_story_1014_10141302_41_dialog_content = "Lady Carleen... Salin itu.",
  ui_story_1014_10141302_42_dialog_content = "Lanjutkan misi. Jika Anda mengalami masalah, minta bantuan langsung dari Ironthorn Knights.",
  ui_story_1014_10141302_43_dialog_content = "Ya.",
  ui_story_1014_10141302_44_dialog_content = "Semoga beruntung. Lebih.",
  ui_story_1014_10141302_45_dialog_content = "Meminta bantuan dari Ironthorn Knights?",
  ui_story_1014_10141302_46_dialog_content = "Dibandingkan dengan ksatria ekspedisi yang menghabiskan waktu bertahun-tahun, ksatria di Twilight harus lebih unggul dalam jumlah dan senjata.",
  ui_story_1014_10141302_47_dialog_content = "Mengapa Anda tidak meminta cadangan dari mereka?",
  ui_story_1014_10141302_48_dialog_content = "Lady Carleen, seperti yang Anda lihat, ada masalah tertentu antara Ironthorn dan para ksatria lokal.",
  ui_story_1014_10141302_49_dialog_content = "Sebagian besar Ksatria Ekspedisi memiliki latar belakang sipil atau bangsawan yang diasingkan. Status mereka jauh berbeda dari ksatria biasa.",
  ui_story_1014_10141302_50_dialog_content = "Bahkan ketika kami meminta dukungan, mereka sering kali tidak menganggap kami serius.",
  ui_story_1014_10141302_51_dialog_content = "Jadi, sebagai Ksatria Ekspedisi, kami terbiasa mengandalkan diri sendiri.",
  ui_story_1014_10141302_52_dialog_content = "Sulit dipercaya…",
  ui_story_1014_10141302_53_dialog_content = "Saya akan melaporkan ini ke atasan Lumopolis.",
  ui_story_1014_10141302_54_dialog_content = "Semua warga Lumopolis harus diperlakukan sama terlepas dari status sosial mereka.",
  ui_story_1014_10141302_55_dialog_content = "Saya menghargai keterbukaan pikiran Anda, meskipun menurut saya tidak ada hal penting yang akan muncul darinya.",
  ui_story_1014_10141302_56_dialog_content = "Bias dan konflik akan terus berlanjut selama masih ada jarak antara bangsawan dan warga sipil.",
  ui_story_1014_10141302_57_dialog_content = "Tidak ada yang mengerti itu lebih baik daripada bangsawan yang dibuang seperti saya.",
  ui_story_1014_10141302_58_dialog_content = "... Saya pernah bertemu bangsawan yang diasingkan di masa lalu.",
  ui_story_1014_10141302_59_dialog_content = "Mereka semua akan mengungkapkan penghinaan terhadap situasi mereka, dengan satu atau lain cara.",
  ui_story_1014_10141302_60_dialog_content = "Apakah kamu juga merasakan hal yang sama, Leo?",
  ui_story_1014_10141302_61_dialog_content = "Apakah Anda meminta pendapat saya?",
  ui_story_1014_10141302_62_dialog_content = "Ya, aku sudah tidur.",
  ui_story_1014_10141302_63_dialog_content = "Saya adalah seorang bangsawan kaya di Lumopolis.",
  ui_story_1014_10141302_64_dialog_content = "Saat itu, aku menganggap memperjuangkan dan membela Lumopolis sebagai kehormatan terbesar bagiku sebagai seorang ksatria.",
  ui_story_1014_10141302_65_dialog_content = "Setelah saya diasingkan, saya menjadi tidak lebih dari orang biasa di Twilight.",
  ui_story_1014_10141302_66_dialog_content = "Aku bahkan tidak bisa menukar kejayaan atau sumpahku untuk membela Lumopolis dengan nyawaku demi sepotong roti.",
  ui_story_1014_10141302_67_dialog_content = "Jadi Anda merasa diabaikan dan tidak dihargai?",
  ui_story_1014_10141302_68_dialog_content = "Saya tidak menyangkal itu.",
  ui_story_1014_10141302_69_dialog_content = "Tapi dibuang ke Twilight persis saat aku menyadari bahwa aku hanya bisa mengandalkan diriku sendiri.",
  ui_story_1014_10141302_70_dialog_content = "Setelah lulus ujian menjadi Expedition Knight dan tinggal di Twilight untuk sementara waktu, sikapku berubah.",
  ui_story_1014_10141302_71_dialog_content = "Saya tidak berpikir itu seburuk yang saya bayangkan.",
  ui_story_1014_10141302_72_dialog_content = "Setidaknya di Twilight, Aurorian dari faksi yang berbeda dapat mengesampingkan persaingan mereka dan hidup berdampingan satu sama lain.",
  ui_story_1014_10141302_73_dialog_content = "Saya sangat menikmati melawan Eclipsites dengan orang lain, tapi... Saya masih merasakan ketidakadilan.",
  ui_story_1014_10141302_74_dialog_content = "Tolong jelaskan.",
  ui_story_1014_10141302_75_dialog_content = "Apa yang bisa diberikan jawaban saya?",
  ui_story_1014_10141302_76_dialog_content = "Saya ingin mendengarkan orang sehingga saya dapat meningkatkan hukum dan kebijakan Lumopolis.",
  ui_story_1014_10141302_77_dialog_content = "Saya ingin semua orang di Lumopolis mendapatkan kesetaraan yang pantas mereka dapatkan.",
  ui_story_1014_10141302_78_dialog_content = "Hmm…",
  ui_story_1014_10141302_79_dialog_content = "<color=#e8d9bb>Berbunyi!</color>",
  ui_story_1014_10141302_80_dialog_content = "<color=#e8d9bb>Duplikasi data Colossus selesai. Aman untuk memutuskan sambungan.</color>",
  ui_story_1014_10141302_81_dialog_content = "Saya pikir sudah selesai!",
  ui_story_1014_10141302_82_dialog_content = "Mari kita kembali sekarang!",
  ui_story_1014_10141302_83_dialog_content = "Anda tidak perlu memberi tahu saya dua kali!",
  ui_story_1014_10141302_84_dialog_content = "(Syukurlah perangkat Algol...)",
  ui_story_1014_10141302_85_dialog_content = "(Jika Carleen dan Leo terus berbicara, mereka bisa berakhir dengan saling berkelahi!)",
  ui_story_1014_10141302_86_dialog_content = "<color=#e8d9bb>Gemuruh…</color>",
  ui_story_1014_10141302_87_dialog_content = "*Batuk* Apa yang terjadi?",
  ui_story_1014_10141302_88_dialog_content = "<color=#e8d9bb>Gruk!</color>",
  ui_story_1014_10141302_89_dialog_content = "Colossus bergetar, PlayerName!",
  ui_story_1014_10141302_90_dialog_content = "Jangan bilang ini akan mengamuk lagi!",
  ui_story_1014_10141302_91_dialog_content = "Mengamuk?!",
  ui_story_1014_10141302_92_dialog_content = "Ambil perangkatnya dan keluar dari sini, PlayerName!",
  ui_story_1014_10141302_93_dialog_content = "Getarannya terlalu kuat... Colossus mungkin akan hancur dan runtuh!",
  ui_story_1014_10141302_94_dialog_content = "Kita tidak bisa tinggal di sini!",
  ui_story_1014_10141302_95_dialog_content = "<color=#e8d9bb>Gruk!</color>",
  ui_story_1014_10141302_96_dialog_content = "Oh, tidak!",
  ui_story_1014_10141302_97_dialog_content = "Kita terlalu dekat dengan Twilight, amukan mungkin akan meratakan kota!",
  ui_story_1014_10141302_98_dialog_content = "Ada begitu banyak warga sipil di sana!",
  ui_story_1014_10141302_99_dialog_content = "Kita harus menghentikan ini entah bagaimana!",
  ui_story_1014_10141302_100_dialog_content = "Namun…",
  ui_story_1014_10141302_101_option_content = "Serahkan padaku!",
  ui_story_1014_10141302_102_dialog_content = "Ini adalah teknologi Caelestite.",
  ui_story_1014_10141302_103_dialog_content = "Mungkin dibutuhkan Caelestite untuk menghentikannya.",
  ui_story_1014_10141302_104_dialog_content = "Wakil, Carleen, aku butuh bantuanmu!",
  ui_story_1014_10141302_105_dialog_content = "Bukan masalah!",
  ui_story_1014_10141302_106_dialog_content = "Siap.",
  ui_story_1014_10141302_107_dialog_content = "Terima kasih. Saya akan memulai.",
  ui_story_1014_10141302_108_dialog_content = "Force Boost!",
  ui_story_1014_10141401_1_dialog_content = "<color=#e8d9bb>Wuush…</color>",
  ui_story_1014_10141401_2_dialog_content = "Naviduz!",
  ui_story_1014_10141401_3_dialog_content = "<color=#e8d9bb>Naviduz menunggu pesanan.</color>",
  ui_story_1014_10141401_4_dialog_content = "Apa pun yang Anda coba lakukan, hentikan!",
  ui_story_1014_10141401_5_dialog_content = "Jangan mengamuk! Itu akan membahayakan banyak nyawa tak berdosa!",
  ui_story_1014_10141401_6_dialog_content = "<color=#e8d9bb>Mencari catatan yang relevan dengan amukan.</color>",
  ui_story_1014_10141401_7_dialog_content = "<color=#e8d9bb>Naviduz tidak pernah mengamuk.</color>",
  ui_story_1014_10141401_8_dialog_content = "Tidak pernah? Bagaimana dengan kejadian yang disebutkan Yingel...?",
  ui_story_1014_10141401_9_dialog_content = "<color=#e8d9bb>Mencari informasi mengenai inisiasi terakhir.</color>",
  ui_story_1014_10141401_10_dialog_content = "<color=#e8d9bb>Naviduz mengaktifkan mode pertahanan karena operasi yang salah dari bentuk kehidupan Lumo.</color>",
  ui_story_1014_10141401_11_dialog_content = "<color=#e8d9bb>Untuk melindungi data, Naviduz melakukan tindakan penghindaran yang diperlukan.</color>",
  ui_story_1014_10141401_12_dialog_content = "<color=#e8d9bb>Selama ini, Naviduz tidak merusak bentuk kehidupan apa pun.</color>",
  ui_story_1014_10141401_13_dialog_content = "Jadi gemetar itu, bukankah kamu mengamuk?",
  ui_story_1014_10141401_14_dialog_content = "<color=#e8d9bb>Sistem propulsi Naviduz rusak parah dan tidak dapat dioperasikan.</color>",
  ui_story_1014_10141401_15_dialog_content = "<color=#e8d9bb>Hasil analisis menunjukkan bahwa gemuruh tersebut berasal dari luar. Memproyeksikan rekaman eksternal sekarang.</color>",
  ui_story_1014_10141401_16_dialog_content = "(Eclipsian) Ini adalah penjara, bejana untuk keinginan.",
  ui_story_1014_10141401_17_dialog_content = "(Eclipsian) Keinginan membuat dunia dan pada akhirnya akan menghancurkannya.",
  ui_story_1014_10141401_18_dialog_content = "(Eclipsian) Jadi, keinginan harus dibersihkan sebelum merajalela.",
  ui_story_1014_10141401_19_dialog_content = "Kenapa ada begitu banyak Eclipsites?!",
  ui_story_1014_10141401_20_dialog_content = "Apakah yang di tengah itu pemimpin mereka?",
  ui_story_1014_10141401_21_dialog_content = "(Eclipsian) Aurorian belum keluar, Lord Asmodeus.",
  ui_story_1014_10141401_22_dialog_content = "(Eclipsian) Keinginan mereka akan membawa mereka kepada kita.",
  ui_story_1014_10141401_23_dialog_content = "(Eclipsian) Karena mereka...",
  ui_story_1014_10141401_24_dialog_content = "(Eclipsian) sudah melihat kita.",
  ui_story_1014_10141401_25_dialog_content = "!!!",
  ui_story_1014_10141401_26_dialog_content = "Kau baik-baik saja, PlayerName?",
  ui_story_1014_10141401_27_dialog_content = "Kenapa kamu terlihat sangat pucat?",
  ui_story_1014_10141401_28_dialog_content = "Colossus tidak menyebabkan getaran. Itu adalah Eclipsites di luar!",
  ui_story_1014_10141401_29_dialog_content = "Saya baru saja melihat Eclipsite yang sangat kuat melalui kamera eksternal.",
  ui_story_1014_10141401_30_dialog_content = "Dan dia rupanya bisa melihat saya melalui itu juga.",
  ui_story_1014_10141401_31_dialog_content = "Bagaimana mungkin? Mungkinkah dia sekuat Forsakin?",
  ui_story_1014_10141401_32_dialog_content = "<color=#e8d9bb>Gruk!</color>",
  ui_story_1014_10141401_33_dialog_content = "<color=#e8d9bb>Peringatan, bentuk kehidupan yang tidak sah sedang memasuki Colossus.</color>",
  ui_story_1014_10141401_34_dialog_content = "Hati-Hati. Eclipsites yang kuat akan datang dengan cara ini!",
  ui_story_1014_10141401_35_dialog_content = "Sayangnya, begitu banyak kebisingan. Padahal bukan hanya itu. Ada aroma keinginan yang tersisa.",
  ui_story_1014_10141401_36_dialog_content = "Keinginan akan kekuasaan.",
  ui_story_1014_10141401_37_dialog_content = "Keinginan untuk diakui.",
  ui_story_1014_10141401_38_dialog_content = "Dan... Hmm, apakah ini...",
  ui_story_1014_10141401_39_dialog_content = "Keinginan untuk menyelamatkan rekannya.",
  ui_story_1014_10141401_40_dialog_content = "Siapa kau? Apa maumu?",
  ui_story_1014_10141401_41_dialog_content = "Saya? Mengapa, apakah Anda menginginkan saya juga?",
  ui_story_1014_10141401_42_dialog_content = "Saya Asmodeus, lahir dari keinginan, dan ditakdirkan untuk membersihkan semua keinginan dari dunia ini.",
  ui_story_1014_10141401_43_dialog_content = "Izinkan saya untuk membersihkan keinginan Anda!",
  ui_story_1014_10141401_44_dialog_content = "Apa yang sangat Anda inginkan, Anda akan menjaganya dengan hidup Anda? Aku akan menghancurkannya dan melihatnya.",
  ui_story_1014_10141401_45_dialog_content = "Dalam mimpimu!",
  ui_story_1014_10141401_46_dialog_content = "Carleen!",
  ui_story_1014_10141401_47_dialog_content = "Dia orang yang tangguh. Mari kita bawa dia bersama, semuanya!",
  ui_story_1014_10141401_48_dialog_content = "Jauhi Lady Carleen, Eclipsite!",
  ui_story_1014_10141401_49_dialog_content = "Keinginan... keinginan yang menyedihkan dan tidak penting...",
  ui_story_1014_10141401_50_dialog_content = "Anda tidak akan berhasil hanya dengan itu.",
  ui_story_1014_10141401_51_dialog_content = "Terkadang menginginkan lebih dari yang seharusnya bukanlah hal yang baik, Eclipsite... Tidak, kamu mungkin adalah <color=#FFB400>Wraith</color>, kan?",
  ui_story_1014_10141401_52_dialog_content = "Benar, keinginan itu buruk, jadi saya harus melenyapkannya.",
  ui_story_1014_10141401_53_dialog_content = "Tapi itu adalah tugas yang mustahil, selama ada Aurorian, keinginan tidak akan ada habisnya.",
  ui_story_1014_10141401_54_dialog_content = "Oleh karena itu, saya terpaksa memberantas Aurorian dengan keinginan terlebih dahulu.",
  ui_story_1014_10141401_55_dialog_content = "Saya juga akan membasmi pengkhianat Caelestite.",
  ui_story_1014_10141401_56_dialog_content = "Saya tidak akan mengizinkan PlayerName dirugikan.",
  ui_story_1014_10141401_57_dialog_content = "Oh? Apakah itu yang Anda inginkan?",
  ui_story_1014_10141401_58_dialog_content = "Melindungi PlayerName adalah tugas saya.",
  ui_story_1014_10141401_59_dialog_content = "Sangat penasaran. Anda tidak memiliki keinginan sama sekali.",
  ui_story_1014_10141401_60_dialog_content = "Oh, tidak, tidak. Kesalahanku.",
  ui_story_1014_10141401_61_dialog_content = "Anda sendiri adalah produk dari keinginan. Itu sebabnya kamu sangat kuat.",
  ui_story_1014_10141401_62_dialog_content = "Sangat menarik.",
  ui_story_1014_10141401_63_dialog_content = "Saya bertanya-tanya bagaimana keinginan seperti itu akan terlihat ketika dihancurkan.",
  ui_story_1014_10141401_64_dialog_content = "Saya tidak sabar menunggu!",
  ui_story_1014_10141401_65_dialog_content = "Awas, Eclipsites bergerak!",
  ui_story_1014_10141402_1_dialog_content = "Ugh!",
  ui_story_1014_10141402_2_dialog_content = "Axelia!",
  ui_story_1014_10141402_3_dialog_content = "aku masih bisa melawan...",
  ui_story_1014_10141402_4_dialog_content = "Tidak, kamu tidak bisa. Anda perlu perawatan sekarang!",
  ui_story_1014_10141402_5_dialog_content = "Mengecewakan.",
  ui_story_1014_10141402_6_dialog_content = "Jumlah keinginan Illumina tidak lebih dari seorang gadis kecil yang lemah.",
  ui_story_1014_10141402_7_dialog_content = "Sangat mengecewakan. Apakah ini sesuai dengan keinginan Aurorian akhir-akhir ini?",
  ui_story_1014_10141402_8_dialog_content = "Tak terbayangkan.",
  ui_story_1014_10141402_9_dialog_content = "Mengapa Forsakin terobsesi dengan sesuatu yang begitu tidak berharga?",
  ui_story_1014_10141402_10_dialog_content = "Anda tidak akan mengatakan itu tentang Axelia!",
  ui_story_1014_10141402_11_dialog_content = "Masih menolak menghadapi betapa lemahnya dirimu?",
  ui_story_1014_10141402_12_dialog_content = "Lalu bagaimana dengan ini?",
  ui_story_1014_10141402_13_dialog_content = "Oh tidak, lebih banyak Eclipsites.",
  ui_story_1014_10141402_14_dialog_content = "Joselyne, Joseph, perhatikan Eclipsites yang lebih kecil datang dari sayap kiri Anda!",
  ui_story_1014_10141402_15_dialog_content = "Siap!",
  ui_story_1014_10141402_16_dialog_content = "Yingel, Sean, kalian berdua menangani Eclipsites yang lebih besar di sebelah kanan!",
  ui_story_1014_10141402_17_dialog_content = "Tunggu dulu, mengapa kami harus mendengarkanmu?",
  ui_story_1014_10141402_18_dialog_content = "<anim type=Shake><size=45>Groar!</size></anim>",
  ui_story_1014_10141402_19_dialog_content = "Serahkan ini padaku!",
  ui_story_1014_10141402_20_dialog_content = "Huh.",
  ui_story_1014_10141402_21_dialog_content = "Sisanya kalian melawan yang satu ini denganku!",
  ui_story_1014_10141402_22_dialog_content = "Saya melihat keinginan Anda tidak lebih dari ini.",
  ui_story_1014_10141402_23_dialog_content = "Semakin kuat keinginan, semakin besar kekuatannya.",
  ui_story_1014_10141402_24_dialog_content = "Anda memiliki keinginan duniawi, sehingga Anda lemah.",
  ui_story_1014_10141402_25_dialog_content = "Tapi milikku adalah untuk menghancurkan semua keinginan di dunia!",
  ui_story_1014_10141402_26_dialog_content = "Bebek, PlayerName!",
  ui_story_1014_10141402_27_dialog_content = "Apa?",
  ui_story_1014_10141402_28_dialog_content = "Tidak ada keinginan yang bisa lepas dariku.",
  ui_story_1014_10141402_29_dialog_content = "Ckck!",
  ui_story_1014_10141402_30_dialog_content = "PlayerName!",
  ui_story_1014_10141402_31_dialog_content = "Aduh, itu sakit!",
  ui_story_1014_10141402_32_dialog_content = "Oh tidak, perangkatnya!",
  ui_story_1014_10141402_33_dialog_content = "Jangan mengganggu keinginan dangkal Anda.",
  ui_story_1014_10141402_34_dialog_content = "Ugh!",
  ui_story_1014_10141402_35_dialog_content = "(Saya perlu menyembunyikan perangkat!)",
  ui_story_1014_10141402_36_dialog_content = "Hah?!",
  ui_story_1014_10141402_37_dialog_content = "Jadi itu keinginanmu, Caelestite pengkhianat.",
  ui_story_1014_10141402_38_dialog_content = "...",
  ui_story_1014_10141402_39_dialog_content = "Ini dia?",
  ui_story_1014_10141402_40_dialog_content = "Letakkan!",
  ui_story_1014_10141402_41_dialog_content = "Membosankan sekali.",
  ui_story_1014_10141402_42_dialog_content = "Apa yang dibicarakan benda itu?",
  ui_story_1014_10141402_43_dialog_content = "Membosankan, membosankan, benar-benar membosankan.",
  ui_story_1014_10141402_44_dialog_content = "Anda membatasi keinginan Anda hanya pada tumpukan sampah yang tidak berarti yang disebabkan oleh kesalahan, pengkhianat?",
  ui_story_1014_10141402_45_option_content = "Ini bukan sampah!",
  ui_story_1014_10141402_46_dialog_content = "Data itu adalah keajaiban!",
  ui_story_1014_10141402_47_dialog_content = "Colossi berusaha tanpa henti dalam waktu yang lama, mengumpulkan pengalaman hingga mereka membentuk sebuah kepribadian...",
  ui_story_1014_10141402_48_dialog_content = "Orang bodoh biasa yang tidak melakukan apa-apa selain mengoceh tentang keinginan sepanjang hari seperti Anda tidak akan mengerti nilai sebenarnya!",
  ui_story_1014_10141402_49_dialog_content = "Hehe... Orang bodoh biasa?",
  ui_story_1014_10141402_50_dialog_content = "Saya tidak berpikir pengkhianat akan berbagi pandangan saya.",
  ui_story_1014_10141402_51_dialog_content = "Benar sekali, semua keinginan itu bersifat duniawi dan tidak seharusnya ada di dunia.",
  ui_story_1014_10141402_52_dialog_content = "Eclipsites tidak memiliki keinginan dan karenanya tidak dapat tergoda. Itu menjadikan mereka organisme terkuat untuk bertahan hidup.",
  ui_story_1014_10141402_53_dialog_content = "Saya sendiri memilih untuk menjadi Wraith untuk meninggalkan keinginan.",
  ui_story_1014_10141402_54_dialog_content = "Jangan dengarkan omong kosongnya, PlayerName.",
  ui_story_1014_10141402_55_dialog_content = "Kami akan menyerang bersama dan mendapatkan kembali perangkatnya!",
  ui_story_1014_10141402_56_dialog_content = "Tapi aku berubah pikiran.",
  ui_story_1014_10141402_57_dialog_content = "Jika Anda sangat menginginkannya kembali, Anda dapat memilikinya.",
  ui_story_1014_10141402_58_dialog_content = "Oh tidak, perangkatnya!",
  ui_story_1014_10141402_59_dialog_content = "Fyuh, nyaris saja.",
  ui_story_1014_10141402_60_dialog_content = "(Sepertinya tidak rusak.)",
  ui_story_1014_10141402_61_dialog_content = "(Apa yang dia inginkan? Dia tidak bisa berada di sini hanya untuk mengejek kita.)",
  ui_story_1014_10141402_62_dialog_content = "Saya pikir Anda memiliki keinginan yang besar, tetapi tampaknya saya salah.",
  ui_story_1014_10141402_63_dialog_content = "Saya melihat apa yang Anda kejar hanyalah sampah yang tidak berguna.",
  ui_story_1014_10141402_64_dialog_content = "Keinginan seperti itu bahkan tidak sepadan dengan waktuku.",
  ui_story_1014_10141402_65_dialog_content = "Berhenti mengoceh!",
  ui_story_1014_10141402_66_dialog_content = "Karena Anda batuk apa PlayerName dibutuhkan, saya tidak perlu menahan diri.",
  ui_story_1014_10141402_67_dialog_content = "Ambil ini, Anda Eclipsite!",
  ui_story_1014_10141402_68_dialog_content = "Kesetiaan adalah keinginan yang paling tidak berharga.",
  ui_story_1014_10141402_69_dialog_content = "Sangat kuat...!",
  ui_story_1014_10141402_70_dialog_content = "Itu bahkan tidak menggunakan kekuatan penuhnya...",
  ui_story_1014_10141402_71_dialog_content = "<anim type=Shake><size=45>Groar!</size></anim>",
  ui_story_1014_10141402_72_dialog_content = "Awas, Beretta! bunga es!",
  ui_story_1014_10141402_73_dialog_content = "Sangat mengecewakan.",
  ui_story_1014_10141402_74_dialog_content = "Anda terlalu penuh dengan keinginan yang membosankan bahkan untuk menarik minat saya.",
  ui_story_1014_10141402_75_dialog_content = "Tapi kamu, PlayerName, pengkhianat Caelestites...",
  ui_story_1014_10141402_76_dialog_content = "...",
  ui_story_1014_10141402_77_dialog_content = "Mungkin yang Anda butuhkan hanyalah sedikit lebih banyak waktu untuk mengubah keinginan Anda menjadi sesuatu yang menarik... dan lezat.",
  ui_story_1014_10141402_78_dialog_content = "Dan Anda juga, <color=#FFB400>Keburukan</color>.",
  ui_story_1014_10141402_79_dialog_content = "Aku?",
  ui_story_1014_10141402_80_dialog_content = "Kami pergi, Eclipsites.",
  ui_story_1014_10141402_81_dialog_content = "Ini tidak lagi sepadan dengan waktu kita.",
  ui_story_1014_10141402_82_dialog_content = "Jangan coba-coba lari!",
  ui_story_1014_10141402_83_dialog_content = "Tenang, Beretta!",
  ui_story_1014_10141402_84_dialog_content = "Dia bukan Eclipsite biasa. Yang terbaik yang bisa kami kelola adalah kebuntuan melawannya.",
  ui_story_1014_10141402_85_dialog_content = "Kami tidak memiliki sarana untuk mengejar mereka. Yang perlu kita lakukan sekarang adalah mundur dan mendapatkan cadangan.",
  ui_story_1014_10141402_86_dialog_content = "Namun…",
  ui_story_1014_10141402_87_dialog_content = "Leo benar, Beretta. Kita seharusnya tidak mengejar mereka saat ini.",
  ui_story_1014_10141402_88_dialog_content = "Mari kita kembali ke Senja.",
  ui_story_1014_10141402_89_dialog_content = "Baiklah.",
  ui_story_1014_10141402_90_dialog_content = "Terima kasih atas persetujuannya, Komandan Ksatria.",
  ui_story_1014_10141402_91_dialog_content = "Prajurit berpengalaman mana pun akan sampai pada kesimpulan yang sama.",
  ui_story_1014_10141402_92_dialog_content = "(Forsakin tidak muncul, tapi kami memikat Wraith lain...)",
  ui_story_1014_10141402_93_dialog_content = "(Apakah ini kebetulan atau memang seharusnya begitu?)",
  ui_story_1014_10141402_94_dialog_content = "(Terlepas dari itu, misinya gagal. Forsakin tidak menunjukkan dirinya seperti yang diharapkan.)",
  ui_story_1014_10141402_95_dialog_content = "(Saya harus melacak mereka dengan cara lain.)",
  ui_story_1014_10141402_95X1_dialog_content = "Apakah kita akan pergi begitu saja? Tinggalkan saja Naviduz di sini dan pergi...?",
  ui_story_1014_10141402_95X2_dialog_content = "Apakah tidak ada cara untuk membawanya kembali bersama kita? Vice, pasti teknologi Illumina bisa memperbaikinya!",
  ui_story_1014_10141402_95X3_dialog_content = "Aku takut itu mungkin sulit...",
  ui_story_1014_10141402_95X4_dialog_content = "...",
  ui_story_1014_10141402_95X5_dialog_content = "PlayerName, saya mengerti perasaan Anda, tetapi tidak ada yang bisa kami lakukan saat ini.",
  ui_story_1014_10141402_95X6_dialog_content = "Yingel, Colossus ini sangat penting untuk PlayerName. Benarkah tidak ada yang bisa kita lakukan?",
  ui_story_1014_10141402_95X7_dialog_content = "Colossus sudah cukup terpukul, belum lagi kerusakan tambahan dari amukan terakhir itu.",
  ui_story_1014_10141402_95X8_dialog_content = "Fakta bahwa itu masih berjalan adalah keajaiban tersendiri ...",
  ui_story_1014_10141402_95X9_dialog_content = "Bagaimana ini bisa...",
  ui_story_1014_10141402_95X10_dialog_content = "<color=#e8d9bb>Saya rasa Anda akan pergi, Caelestite PlayerName.</color>",
  ui_story_1014_10141402_95X11_dialog_content = "Naviduz?",
  ui_story_1014_10141402_95X12_dialog_content = "<color=#e8d9bb>Naviduz ingin mengajukan pertanyaan tentang Caelestite.</color>",
  ui_story_1014_10141402_95X13_dialog_content = "<color=#e8d9bb>Caelestite PlayerName, tolong beri tahu saya kapan Anda akan berkunjung lagi dan bagaimana Anda berencana untuk memperbaiki Naviduz.</color>",
  ui_story_1014_10141402_95X14_dialog_content = "...",
  ui_story_1014_10141402_95X15_dialog_content = "Aku… aku tak tahu.",
  ui_story_1014_10141402_95X16_dialog_content = "Maaf... Maaf, tapi Anda harus menunggu sedikit lebih lama...",
  ui_story_1014_10141402_95X17_dialog_content = "<color=#e8d9bb>Perintah diterima.</color>",
  ui_story_1014_10141402_95X18_dialog_content = "<color=#e8d9bb>Menurut konfigurasi 35, di sinilah saya harus memberikan harapan terbaik saya untuk Caelestite PlayerName.</color>",
  ui_story_1014_10141402_95X19_dialog_content = "<color=#e8d9bb>Jangan merasa sedih karena gagal memperbaiki Naviduz. Fokuskan mata Anda pada cakrawala.</color>",
  ui_story_1014_10141402_95X20_dialog_content = "Apa? Itu pesan dari 35? Dia benar-benar memikirkan segalanya ...",
  ui_story_1014_10141402_95X21_dialog_content = "<color=#e8d9bb>Naviduz dan 35 berharap perjalanan Anda aman.</color>",
  ui_story_1014_10141402_95X22_dialog_content = "Terima kasih…",
  ui_story_1014_10141402_95X23_dialog_content = "Aku mendengarmu. Aku akan melanjutkan perjalananku dengan jiwamu di hatiku...",
  ui_story_1014_10141402_95X24_dialog_content = "Ayo, PlayerName.",
  ui_story_1014_10141402_95X25_dialog_content = "Baiklah, ayo pergi. Kami masih memiliki banyak pekerjaan yang harus dilakukan.",
  ui_story_1014_10141402_96_dialog_content = "<color=#e8d9bb>Soroz, Jembatan</color>",
  ui_story_1014_10141402_97_dialog_content = "Terlibat, Soroz!",
  ui_story_1014_10141402_98_dialog_content = "Eclipsites itu tidak mengikuti kita, kan?",
  ui_story_1014_10141402_99_dialog_content = "Saya tidak merasakan mereka lagi, jadi mereka mungkin tidak ada.",
  ui_story_1014_10141402_100_dialog_content = "Tidak tahu apa yang mereka lakukan, tapi aku merasa seperti kita diremehkan.",
  ui_story_1014_10141402_101_dialog_content = "Namun, suatu hari, Eclipsites akan membayar untuk meremehkan kita.",
  ui_story_1014_10141402_102_dialog_content = "Bagaimana kabarmu, Axelia? Anda terkena banyak serangan...",
  ui_story_1014_10141402_103_dialog_content = "Aku baik-baik saja.",
  ui_story_1014_10141402_104_dialog_content = "Tubuh Axelia mungkin rapuh, tapi *batuk*... Aku tidak akan dikalahkan dengan mudah.",
  ui_story_1014_10141402_105_dialog_content = "(Apakah itu salah satu efek samping dari modifikasi?)",
  ui_story_1014_10141402_107_dialog_content = "(Meski begitu, Reinhard pasti punya alasan untuk menentang proyek tersebut.)",
  ui_story_1014_10141402_109_dialog_content = "(Omong-omong, Reinhardt tampaknya memiliki kemampuan tempur dan pemulihan manusia super juga...)",
  ui_story_1014_10141402_110_dialog_content = "Apa yang sedang kamu pikirkan, PlayerName?",
  ui_story_1014_10141402_111_dialog_content = "Hah? Tidak apa-apa.",
  ui_story_1014_10141402_112_dialog_content = "Ada apa, Vice?",
  ui_story_1014_10141402_113_dialog_content = "Tidak ada, sungguh. Hanya saja ada beberapa hal yang saya tidak mengerti.",
  ui_story_1014_10141402_114_dialog_content = "Kenapa Eclipsite bernama Asmodeus menyebutku di akhir?",
  ui_story_1014_10141402_115_dialog_content = "Aku tidak mengenalnya, dan aku tidak pernah memberitahunya namaku.",
  ui_story_1014_10141402_116_option_content = "Mungkinkah itu Chord Link?",
  ui_story_1014_10141402_117_dialog_content = "Anda mendapat kekuatan khusus dengan menggunakan Tautan Chord.",
  ui_story_1014_10141402_118_dialog_content = "Mungkin Asmodeus merasakannya dan menarik perhatiannya padamu?",
  ui_story_1014_10141402_119_dialog_content = "Yah, mana kita tahu…",
  ui_story_1014_10141402_120_dialog_content = "Dia sulit ditebak.",
  ui_story_1014_10141402_121_option_content = "Mungkinkah itu kondisi fisik Anda?",
  ui_story_1014_10141402_122_dialog_content = "Setelah menggunakan Tautan Chord, kondisi fisik Anda menjadi tidak biasa.",
  ui_story_1014_10141402_123_dialog_content = "Dan itu membuatmu bersinar.",
  ui_story_1014_10141402_124_dialog_content = "Tapi hampir tidak ada perbedaan dalam penampilan luar saya.",
  ui_story_1014_10141402_125_dialog_content = "Mungkinkah dia memiliki kemampuan khusus yang dapat mendeteksi perubahan batin?",
  ui_story_1014_10141402_126_dialog_content = "Tidak juga…",
  ui_story_1014_10141402_127_dialog_content = "Mari kita bahas nanti. Bagaimana perasaanmu sekarang, Vice?",
  ui_story_1014_10141402_128_dialog_content = "Kami melakukan banyak pertempuran. Apakah Anda tidak nyaman di mana saja?",
  ui_story_1014_10141402_129_dialog_content = "Santai. Saya sedikit lelah, tetapi tidak ada yang tidak bisa diperbaiki dengan istirahat yang baik.",
  ui_story_1014_10141402_130_dialog_content = "Tubuhku bertahan dengan baik.",
  ui_story_1014_10141402_131_dialog_content = "Senang mendengarnya.",
  ui_story_1014_10141402_132_dialog_content = "Yang perlu kita lakukan sekarang adalah kembali ke Gannon dan memperbaiki Soroz dengan modul dan datanya!",
  ui_story_1014_10141402_133_dialog_content = "Setelah kami menurunkan Axelia dan yang lainnya di Twilight.",
  ui_story_1014_10141402_134_dialog_content = "Ya!",
  ui_story_1014_10141402_135_dialog_content = "<color=#e8d9bb>Ngungg...</color>",
  ui_story_1014_10141402_136_dialog_content = "Soroz baru saja mendapat sinyal komunikasi jarak jauh, dan pengirimnya adalah... Naviduz!",
  ui_story_1014_10141402_137_dialog_content = "<color=#e8d9bb>Tzzst...</color>",
  ui_story_1014_10141402_137X1_dialog_content = "<color=#e8d9bb>Menurut perintah 35, perintah ini akan dijalankan setelah Caelestite pergi.</color>",
  ui_story_1014_10141402_138_dialog_content = "<color=#e8d9bb>Ketentuan permintaan telah dipenuhi. Naviduz mengirimkan permintaan ke Caelestite PlayerName.</color>",
  ui_story_1014_10141402_139_dialog_content = "Colossus mengirimiku permintaan?",
  ui_story_1014_10141402_140_dialog_content = "<color=#e8d9bb>PlayerName dari Caelestites telah memperoleh keseluruhan data Naviduz.</color>",
  ui_story_1014_10141402_141_dialog_content = "<color=#e8d9bb>Inti energi Naviduz rusak dan tidak dapat diperbaiki. Semua operasi akan segera dihentikan.</color>",
  ui_story_1014_10141402_142_dialog_content = "<color=#e8d9bb>Menurut perintah 35, ketika dua syarat di atas terpenuhi, Naviduz akan mengirimkan permintaan ke Caelestite terdekat...</color>",
  ui_story_1014_10141402_143_dialog_content = "Bisakah...",
  ui_story_1014_10141402_144_dialog_content = "<color=#e8d9bb> Naviduz meminta PlayerName <color=#FFB400>menulis puisi</color> untuk Naviduz.</color>",
  ui_story_1014_10141402_145_dialog_content = "...",
  ui_story_1014_10141402_146_dialog_content = "Aku mengerti.",
  ui_story_1014_10141402_147_dialog_content = "Tapi saya belum pernah menulis puisi sebelumnya, jadi hasilnya mungkin tidak bagus.",
  ui_story_1014_10141402_148_dialog_content = "Anda pernah melakukan perjalanan bersama kami",
  ui_story_1014_10141402_149_dialog_content = "Langit berbintang tak terbatas, angin di bawah sayapmu",
  ui_story_1014_10141402_150_dialog_content = "Sebuah perjalanan panjang tak terukur, abadi waktu tak terukur",
  ui_story_1014_10141402_151_dialog_content = "Sebuah perjalanan yang berlangsung hingga bintang-bintang pun memudar",
  ui_story_1014_10141402_152_dialog_content = "Sampai hanya persinggahan sepi yang tersisa",
  ui_story_1014_10141402_153_dialog_content = "Ketika panggilan untuk kembali akhirnya memberi isyarat",
  ui_story_1014_10141402_154_dialog_content = "Jalan pulang pun hilang",
  ui_story_1014_10141402_155_dialog_content = "Kau terlalu lama melayang di langit",
  ui_story_1014_10141402_156_dialog_content = "Berlama-lama dalam kegelapan terlalu lama",
  ui_story_1014_10141402_157_dialog_content = "Waktu telah melenyapkan semua jejak rumah",
  ui_story_1014_10141402_158_dialog_content = "Tapi sekarang mercusuar bersinar sekali lagi",
  ui_story_1014_10141402_159_dialog_content = "Semoga kesadaran Anda mengikuti dandelion yang tertiup angin",
  ui_story_1014_10141402_160_dialog_content = "Sampai terbang kembali ke Eraveil",
  ui_story_1014_10141402_161_dialog_content = "...",
  ui_story_1014_10141402_162_dialog_content = "(Itu jelek... Tidak mengherankan bagi seseorang yang belum pernah menulis puisi sebelumnya...)",
  ui_story_1014_10141402_163_dialog_content = "<color=#e8d9bb>Puisi diterima. Memutar rekaman.</color>",
  ui_story_1014_10141402_164_dialog_content = "Terima kasih, orang Samaria yang baik dari masa depan!",
  ui_story_1014_10141402_165_dialog_content = "Itu suara 35!",
  ui_story_1014_10141402_166_dialog_content = "Naviduz pasti senang ada puisi yang mengiringinya.",
  ui_story_1014_10141402_166X1_dialog_content = "Meskipun kita belum pernah bertemu, saya pikir saat ini, hati kita adalah satu.",
  ui_story_1014_10141402_166X2_dialog_content = "Bahkan tanpa menggunakan kemampuan psikis Anda, Anda juga akan merasakannya!",
  ui_story_1014_10141402_166X3_dialog_content = "Ya, bahkan tanpa kemampuan psikis saya. Perasaan ingin menangis ini...",
  ui_story_1014_10141402_166X4_dialog_content = "Tidak peduli di tangan siapa hadiah ini akhirnya berakhir, saya sangat berharap Anda akan menemukan banyak teman untuk bergabung dengan Anda dalam perjalanan Anda dan Anda tidak akan pernah sendirian.",
  ui_story_1014_10141402_166X5_dialog_content = "Biarkan itu berjalan bersama Anda. Inilah yang saya dan Naviduz sama-sama inginkan!",
  ui_story_1014_10141402_166X6_dialog_content = "Terima kasih. Terima kasih semuanya...",
  ui_story_1014_10141402_166X7_dialog_content = "Saya berjanji untuk menggunakan hadiah Anda dengan baik.",
  ui_story_1014_10141402_168_dialog_content = "Perpisahan, Naviduz.",
  ui_story_1014_10141402_169_dialog_content = "Perpisahan, 35.",
  ui_story_1014_10141501_1_dialog_content = "<color=#e8d9bb>Senja, suatu saat nanti...</color>",
  ui_story_1014_10141501_2_dialog_content = "Disini saja baik-baik saja.",
  ui_story_1014_10141501_3_dialog_content = "Terima kasih, PlayerName.",
  ui_story_1014_10141501_4_dialog_content = "Seharusnya aku berterima kasih padamu karena telah membantuku.",
  ui_story_1014_10141501_5_dialog_content = "Kalau begitu, selamat tinggal, semuanya.",
  ui_story_1014_10141501_6_dialog_content = "Merupakan suatu kehormatan untuk bertarung bersama Anda, tetapi saya harus pergi sekarang.",
  ui_story_1014_10141501_7_dialog_content = "Berharap untuk melihat Anda lagi, PlayerName.",
  ui_story_1014_10141501_8_dialog_content = "Tunggu.",
  ui_story_1014_10141501_9_dialog_content = "Apakah ada hal lain, Komandan Ksatria?",
  ui_story_1014_10141501_10_dialog_content = "Anda masih belum menjawab saya tentang apa yang tidak adil.",
  ui_story_1014_10141501_11_dialog_content = "Ha ha ha. Anda masih menunggu jawaban?",
  ui_story_1014_10141501_12_dialog_content = "Aku akan tumpul, kalau begitu.",
  ui_story_1014_10141501_13_dialog_content = "Saya pikir Lumopolis membutuhkan reformasi besar.",
  ui_story_1014_10141501_14_dialog_content = "Apa-apaan kau…!",
  ui_story_1014_10141501_15_dialog_content = "Anda sudah tahu bahwa gelar di Lumopolis murni turun temurun.",
  ui_story_1014_10141501_16_dialog_content = "Mereka diberikan karena garis keturunan, bukan kemampuan, dan dipertahankan karena kepentingan pribadi.",
  ui_story_1014_10141501_17_dialog_content = "Artinya, sulit bagi mereka yang sangat mampu tetapi bukan keturunan bangsawan untuk maju.",
  ui_story_1014_10141501_18_dialog_content = "Lumopolis membutuhkan reformasi total, dan saya ingin menjadi orang yang memulainya.",
  ui_story_1014_10141501_19_dialog_content = "Kau sadar aku bisa mengirimmu ke Hall of Justice atas tuduhan konspirasi dengan apa yang baru saja kau katakan?",
  ui_story_1014_10141501_20_dialog_content = "Ahaha. Tapi saya tidak berpikir — sebaliknya, saya tahu pasti Anda tidak akan melakukan itu.",
  ui_story_1014_10141501_21_dialog_content = "Meskipun Anda seorang bangsawan, kekuatan tidak membutakan Anda.",
  ui_story_1014_10141501_22_dialog_content = "Anda berbeda dari Bangsawan Lumo pada umumnya karena Anda adalah ksatria sejati yang dibaptis oleh perang.",
  ui_story_1014_10141501_23_dialog_content = "Sebagai seorang ksatria sendiri, itu jelas bagi saya.",
  ui_story_1014_10141501_24_dialog_content = "Benarkah?",
  ui_story_1014_10141501_25_dialog_content = "Maka saya berharap Anda terus berjuang untuk mewujudkan ambisi Anda.",
  ui_story_1014_10141501_26_dialog_content = "Mari kita buktikan melalui tindakan kita masing-masing pilihan mana yang terbaik untuk Lumopolis.",
  ui_story_1014_10141501_27_dialog_content = "Janji!",
  ui_story_1014_10141501_28_dialog_content = "Apakah Anda benar-benar akan membiarkan dia pergi, Lady Carleen?",
  ui_story_1014_10141501_29_dialog_content = "Tidak apa-apa, tinggalkan dia.",
  ui_story_1014_10141501_30_dialog_content = "Apa ini artinya Joselyne... Hei, kemana Joselyne pergi?",
  ui_story_1014_10141501_31_dialog_content = "Seorang pejalan kaki memanggilnya untuk membantu.",
  ui_story_1014_10141501_32_dialog_content = "Kapan PlayerName sedang mengawasi Carleen dan Leo.",
  ui_story_1014_10141501_33_dialog_content = "Itu Joselyne baik-baik saja, dia tidak pernah menolak panggilan untuk meminta bantuan.",
  ui_story_1014_10141501_34_dialog_content = "Sayang sekali kami tidak mendapat kesempatan untuk mengucapkan selamat tinggal.",
  ui_story_1014_10141501_35_dialog_content = "Kita akan bertemu lagi.",
  ui_story_1014_10141501_36_dialog_content = "Yingel, Sean, dan aku juga harus pulang.",
  ui_story_1014_10141501_37_dialog_content = "Misi telah selesai.",
  ui_story_1014_10141501_38_dialog_content = "Itu benar, tapi kita masih perlu memberitahu atasan kita tentang Asmodeus.",
  ui_story_1014_10141501_39_dialog_content = "Di sinilah kita berpisah kemudian, PlayerName, Wakil Letnan, Lady Carleen, Nona Beretta.",
  ui_story_1014_10141501_40_dialog_content = "Mari kita bertemu lagi kapan-kapan!",
  ui_story_1014_10141501_41_dialog_content = "Anda akan mendapatkan bantuan saya, PlayerName.",
  ui_story_1014_10141501_42_dialog_content = "Oh ya, kami berpartisipasi dalam acara militer gabungan berikutnya.",
  ui_story_1014_10141501_43_dialog_content = "Sampai jumpa di simulasi!",
  ui_story_1014_10141501_44_dialog_content = "Ya, nantikan!",
  ui_story_1014_10141501_45_dialog_content = "Kami akan melihat siapa yang keluar di atas.",
  ui_story_1014_10141501_46_option_content = "Nanti!",
  ui_story_1014_10141501_47_dialog_content = "Kami akhirnya membawa mereka kembali ke Twilight dengan selamat.",
  ui_story_1014_10141501_48_dialog_content = "Kita harus bergegas kembali ke Gannon sendiri.",
  ui_story_1014_10141501_49_dialog_content = "Sementara Asmodeus membutuhkan perhatian, prioritasnya adalah memperbaiki Soroz.",
  ui_story_1014_10141501_50_dialog_content = "Ya, mari kita tidak menunda lebih jauh.",
  ui_story_1014_10141501_51_dialog_content = "Ayo kita pergi!",
  ui_story_1014_10141501_52_dialog_content = "<color=#e8d9bb>Gan, suatu saat nanti...</color>",
  ui_story_1014_10141501_53_dialog_content = "Kami mendapatkan data yang Anda butuhkan, Algol!",
  ui_story_1014_10141501_54_dialog_content = "Oke. Tunggu...",
  ui_story_1014_10141501_55_dialog_content = "Anda sudah kembali?",
  ui_story_1014_10141501_56_dialog_content = "Ya.",
  ui_story_1014_10141501_57_dialog_content = "Kami bertemu dengan musuh yang tak terduga, tapi kami berhasil mendapatkan datanya.",
  ui_story_1014_10141501_58_dialog_content = "Ya, saya mendengar tentang Wraith aneh itu... <color=#FFB400>Asmodeus</color>, kan?",
  ui_story_1014_10141501_59_dialog_content = "Anda sudah tahu?!",
  ui_story_1014_10141501_60_dialog_content = "Saya seharusnya tidak terkejut. Illumina memiliki orang-orang di Twilight.",
  ui_story_1014_10141501_61_dialog_content = "Apa pun yang terjadi, yang diperlukan hanyalah satu pesan dan semua Gannon mendengarnya.",
  ui_story_1014_10141501_62_dialog_content = "Sesuatu untuk efek itu. Anda tidak boleh meremehkan jaringan Illumina.",
  ui_story_1014_10141501_63_dialog_content = "Tapi itu tugas Grand Marshal untuk berurusan dengan Wraith dan sejenisnya.",
  ui_story_1014_10141501_64_dialog_content = "Saya hanya ingin melihat data yang Anda bawa kembali dari Colossus.",
  ui_story_1014_10141501_65_dialog_content = "Bagaimana Anda mendapatkannya, ketika begitu banyak regu kembali dengan tangan kosong?",
  ui_story_1014_10141501_66_dialog_content = "Itu karena...",
  ui_story_1014_10141501_67_option_content = "Aku Caelestite.",
  ui_story_1014_10141501_68_dialog_content = "Kesadaran Colossus itu lahir dari usaha gigih seorang Caelestite.",
  ui_story_1014_10141501_69_dialog_content = "Saya hanya mewarisi hadiah yang sangat berharga, sebagai Caelestite terakhir.",
  ui_story_1014_10141501_70_dialog_content = "Menarik. Jadi ini yang diwarisi Caelestite satu sama lain?",
  ui_story_1014_10141501_71_option_content = "Tempat itu juga merupakan \"hadiah\".",
  ui_story_1014_10141501_72_dialog_content = "Colossus telah menunggu seseorang datang dan menyampaikan data berharga yang dimilikinya.",
  ui_story_1014_10141501_73_dialog_content = "Seperti yang dilakukan Guru Francis di Obelisk of Return.",
  ui_story_1014_10141501_74_dialog_content = "Colossus bahkan meminta saya untuk menulis puisi untuk itu.",
  ui_story_1014_10141501_75_dialog_content = "Benarkah? Sangat menarik!",
  ui_story_1014_10141501_76_dialog_content = "Tunjukkan datanya.",
  ui_story_1014_10141501_77_dialog_content = "...",
  ui_story_1014_10141501_78_dialog_content = "Hmm, ini lebih rumit dari yang kukira.",
  ui_story_1014_10141501_79_dialog_content = "Apa maksudmu?",
  ui_story_1014_10141501_80_dialog_content = "Rumit? Bisakah Soroz diperbaiki?",
  ui_story_1014_10141501_81_dialog_content = "Pelan - pelan. Mari saya jelaskan.",
  ui_story_1014_10141501_82_dialog_content = "Anda tahu kesadaran Colossus terbentuk dari upaya gigih Caelestite tertentu.",
  ui_story_1014_10141501_83_dialog_content = "Benar.",
  ui_story_1014_10141501_84_dialog_content = "Dalam usahanya, Colossus mengalami perubahan yang tidak diketahui saat dihadapkan pada situasi di luar sirkuit logikanya.",
  ui_story_1014_10141501_85_dialog_content = "Kami biasanya menyebut perubahan seperti itu \"kesalahan\", tetapi di sini, saya lebih cenderung menyebutnya \"<color=#FFB400>pertumbuhan</color>.\"",
  ui_story_1014_10141501_86_dialog_content = "Tapi karena perubahannya tidak terduga...",
  ui_story_1014_10141501_87_dialog_content = "Mereka tercermin dalam data sebagai variabel yang rumit dan kacau.",
  ui_story_1014_10141501_88_dialog_content = "Beberapa dari variabel ini mungkin tidak berguna, sementara yang lain bisa menjadi kunci kesadaran Colossus.",
  ui_story_1014_10141501_89_dialog_content = "Selain itu, karena data independen antar Colossi, perubahannya juga berbeda.",
  ui_story_1014_10141501_90_dialog_content = "Data yang Anda unduh tidak dapat diterapkan langsung ke Soroz.",
  ui_story_1014_10141501_91_dialog_content = "Saya tidak begitu mengerti semua jargon ini.",
  ui_story_1014_10141501_92_dialog_content = "Saya hanya ingin tahu apakah Soroz dapat dipulihkan!",
  ui_story_1014_10141501_93_dialog_content = "Saya perlu waktu untuk menganalisis data untuk jawaban yang lebih spesifik.",
  ui_story_1014_10141501_94_dialog_content = "Data Soroz sendiri tidak cukup, tetapi dengan data baru ini, saya dapat membuat perbandingan silang.",
  ui_story_1014_10141501_95_dialog_content = "Dan itu sangat meningkatkan peluang yang menguntungkan kita.",
  ui_story_1014_10141501_96_dialog_content = "Saya harap Anda akan mempercayai saya dan memberi saya waktu.",
  ui_story_1014_10141501_97_dialog_content = "Bukannya aku punya pilihan lain.",
  ui_story_1014_10141501_98_dialog_content = "Jangan terlalu pesimis. Saya sangat yakin dengan penelitian AI saya.",
  ui_story_1014_10141501_99_dialog_content = "Setelah apa yang Anda alami, Anda harus beristirahat.",
  ui_story_1014_10141501_100_dialog_content = "Ini pertempuran saya sekarang.",
  ui_story_1014_10141501_101_dialog_content = "Bagaimana kabar Soroz, PlayerName?",
  ui_story_1014_10141501_102_dialog_content = "Apakah datanya membantu?",
  ui_story_1014_10141501_103_dialog_content = "Saya tidak sepenuhnya yakin. Algol berkata dia butuh waktu untuk menyelesaikannya.",
  ui_story_1014_10141501_104_dialog_content = "Oh...",
  ui_story_1014_10141501_105_dialog_content = "Saya harap ini berjalan dengan baik.",
  ui_story_1014_10141501_106_dialog_content = "Begitu juga aku.",
  ui_story_1014_10141501_107_dialog_content = "<color=#e8d9bb>Bip, bip, bip...</color>",
  ui_story_1014_10141501_108_dialog_content = "Wakil Letnan, PlayerName, Apakah kamu disana?",
  ui_story_1014_10141501_109_dialog_content = "Petugas Ulysses?",
  ui_story_1014_10141501_110_dialog_content = "Kami membuat kemajuan dalam penelitian kami di Chord Link.",
  ui_story_1014_10141501_111_dialog_content = "Wakil Letnan, harap melapor ke lokasi yang ditentukan bersama PlayerName. Aku akan mengirimkan koordinatnya sebentar lagi.",
  ui_story_1014_10141501_112_dialog_content = "Koordinat khusus diklasifikasikan, dan tidak ada orang yang tidak berwenang yang boleh menemani Anda.",
  ui_story_1014_10141501_113_dialog_content = "Harap tanggapi setelah diterima.",
  ui_story_1014_10141501_114_dialog_content = "Ya, salinan Wakil Letnan.",
  ui_story_1014_10141501_115_dialog_content = "Sangat baik. Lebih.",
  ui_story_1014_10141501_116_dialog_content = "Diklasifikasikan, lagi? Saya kira saya sudah selesai di sini.",
  ui_story_1014_10141501_117_dialog_content = "Lagipula aku harus kembali ke Lumopolis.",
  ui_story_1014_10141501_118_dialog_content = "Saya ingin mencari tahu lebih banyak tentang Ironthorn Knights.",
  ui_story_1014_10141501_119_dialog_content = "Dan perbarui Penguasa Kota tentang situasi di Twilight.",
  ui_story_1014_10141501_120_dialog_content = "Apakah Anda masih mengkhawatirkan orang-orang itu, Carleen?",
  ui_story_1014_10141501_121_dialog_content = "Tidak mungkin untuk tidak melakukannya.",
  ui_story_1014_10141501_122_dialog_content = "Ini menyangkut Lumopolis, jadi perlu untuk mengetahui lebih banyak tentang mereka, terutama Leo the Expedition Knight.",
  ui_story_1014_10141501_123_dialog_content = "Saya tidak setuju dengan ide-idenya. Dia mungkin saja membuat Lumopolis menjadi tempat yang lebih baik.",
  ui_story_1014_10141501_124_dialog_content = "Namun, saya tidak dapat mengabaikan fakta bahwa dia juga bisa menjadi ancaman potensial bagi Lumopolis.",
  ui_story_1014_10141501_125_dialog_content = "Sangat teliti seperti biasa, Carleen.",
  ui_story_1014_10141501_126_dialog_content = "Ayo pergi ke tempat yang harus kita tuju sekarang.",
  ui_story_1014_10141501_127_dialog_content = "Ayo.",
  ui_story_1014_10141501_128_dialog_content = "<color=#e8d9bb>Di suatu tempat di Federasi Illumina</color>",
  ui_story_1014_10141501_129_dialog_content = "Koordinat membawa kita ke kota bawah?!",
  ui_story_1014_10141501_130_dialog_content = "Itu tidak ditandai di peta Illumina mana pun.",
  ui_story_1014_10141501_131_dialog_content = "Tidak mungkin menemukan tempat ini tanpa koordinatnya.",
  ui_story_1014_10141501_132_dialog_content = "...",
  ui_story_1014_10141501_133_dialog_content = "Tampaknya sangat dipertahankan.",
  ui_story_1014_10141501_134_dialog_content = "Ini adalah fasilitas rahasia, tidak terlalu mengejutkan.",
  ui_story_1014_10141501_135_dialog_content = "Di situ kau rupanya.",
  ui_story_1014_10141501_136_dialog_content = "(Orang ini lagi?)",
  ui_story_1014_10141501_137_dialog_content = "(Tidak nyaman berbicara dengannya, seperti dia selalu menginterogasimu atau semacamnya...)",
  ui_story_1014_10141501_138_dialog_content = "Apa yang kamu lakukan di sini? Bukankah Ulysses yang memanggil kita?",
  ui_story_1014_10141501_139_dialog_content = "Petugas itu memiliki masalah mendesak untuk ditangani, jadi dia memerintahkanku untuk mengawal kalian berdua.",
  ui_story_1014_10141501_140_dialog_content = "Apa yang begitu mendesak sehingga kami harus datang ke sini dalam waktu sesingkat itu?",
  ui_story_1014_10141501_141_dialog_content = "Anda sudah tahu banyak, jadi saya hanya akan datang.",
  ui_story_1014_10141501_142_dialog_content = "Mari kita mulai dengan situasi saat ini.",
  ui_story_1014_10141501_143_dialog_content = "Asal usul Program Phospherus sebenarnya terkait <color=#FFB400>Tautan Chord lain</color> itu di sini.",
  ui_story_1014_10141501_144_dialog_content = "Apa? Ada lebih dari satu Chord Link?",
  ui_story_1014_10141501_145_dialog_content = "Betul sekali. Illumina menemukan Chord Link bertahun-tahun yang lalu.",
  ui_story_1014_10141501_146_dialog_content = "Melalui studi kami, kami menemukan cara memodifikasi Aurorian.",
  ui_story_1014_10141501_147_dialog_content = "Namun, karena berbagai alasan, mesin ini tidak seutuh mitranya di Eraveil.",
  ui_story_1014_10141501_148_dialog_content = "Oleh karena itu, proses modifikasi yang dikembangkan oleh Illumina tidak sempurna karena adanya bagian-bagian yang cacat.",
  ui_story_1014_10141501_149_dialog_content = "Bahkan saat ini, kami tidak dapat mengontrol hasilnya, dan prosesnya memiliki tingkat kegagalan yang tinggi.",
  ui_story_1014_10141501_150_dialog_content = "Lalu mengapa Anda tidak menghentikan proyek itu?",
  ui_story_1014_10141501_151_dialog_content = "Anda tahu itu berbahaya dan bisa membuat orang menderita.",
  ui_story_1014_10141501_152_dialog_content = "Jadi mengapa Anda bersikeras untuk melanjutkannya?",
  ui_story_1014_10141501_153_dialog_content = "Saya tidak keberatan menekankan lagi bahwa sebagian besar populasi Illumina rata-rata.",
  ui_story_1014_10141501_154_dialog_content = "Ini adalah satu-satunya cara untuk memastikan kelangsungan hidup Illumina.",
  ui_story_1014_10141501_155_option_content = "...",
  ui_story_1014_10141501_156_option_content = "Saya tidak setuju dengan itu",
  ui_story_1014_10141501_157_dialog_content = "Saya mengerti bagaimana perasaan Anda, tetapi jangan lupa bahwa kita memiliki kesepakatan.",
  ui_story_1014_10141501_158_dialog_content = "Jika Anda merasa tidak nyaman, Anda tentu berhak untuk berhenti mengizinkan kami mengakses untuk mempelajari Obelisk of Return.",
  ui_story_1014_10141501_159_dialog_content = "Padahal itu akan menghentikan penelitian tentang Chord Link dan efek sampingnya juga.",
  ui_story_1014_10141501_160_dialog_content = "(Dia mengancamku dengan Vice dan Barton!)",
  ui_story_1014_10141501_161_dialog_content = "(Dia tahu dia lebih unggul...)",
  ui_story_1014_10141501_162_dialog_content = "Menilai dari sikap Anda, Anda telah tertangkap.",
  ui_story_1014_10141501_163_dialog_content = "Apa yang Anda coba lakukan sekarang?",
  ui_story_1014_10141501_164_dialog_content = "Setelah mempelajari mesin di Obelisk, kami melakukan perbaikan pada Chord Link kami yang tidak lengkap.",
  ui_story_1014_10141501_165_dialog_content = "Kami ingin membuat model yang lengkap dan sempurna menggunakan komponen kerja dari kedua mesin.",
  ui_story_1014_10141501_166_dialog_content = "Saya percaya seluruh Chord Link akan menyelesaikan banyak masalah,",
  ui_story_1014_10141501_167_dialog_content = "seperti efek samping misterius yang terjadi pada Letnan Wakil dan Komandan Barton.",
  ui_story_1014_10141501_168_dialog_content = "... Apa yang Anda ingin saya lakukan?",
  ui_story_1014_10141501_169_dialog_content = "Chord Link adalah teknologi Caelestite, jadi data tertentu hanya dapat diuraikan dengan kemampuan psikis.",
  ui_story_1014_10141501_170_dialog_content = "Kami mencoba memulihkan data itu sekarang. Kami akan membutuhkan layanan Anda setelah selesai.",
  ui_story_1014_10141501_171_dialog_content = "Kami hanya ingin Anda siaga untuk saat ini.",
  ui_story_1014_10141501_172_dialog_content = "(Mereka menyerbu saya hanya untuk memberi tahu saya itu?)",
  ui_story_1014_10141501_173_dialog_content = "Baik, saya mengerti.",
  ui_story_1014_10141501_174_dialog_content = "Terima kasih atas kerja sama anda.",
  ui_story_1014_10141501_175_dialog_content = "Saya harus pergi, saya masih memiliki banyak pekerjaan yang harus dilakukan.",
  ui_story_1014_10141501_176_dialog_content = "Aku tidak suka perasaan ini.",
  ui_story_1014_10141501_177_dialog_content = "Sepertinya saya adalah alat yang mereka gunakan untuk menghubungi Anda.",
  ui_story_1014_10141501_178_dialog_content = "Jangan menganggap dirimu seperti itu.",
  ui_story_1014_10141501_179_dialog_content = "Saya tidak dapat menghilangkan efek samping Anda tanpa bantuan mereka.",
  ui_story_1014_10141501_180_dialog_content = "PlayerName…",
  ui_story_1014_10141501_181_dialog_content = "Anda dapat mengabaikan kondisi saya.",
  ui_story_1014_10141501_182_dialog_content = "Selain sesekali bersinar, saya merasa baik-baik saja.",
  ui_story_1014_10141501_183_dialog_content = "Jadi tidak apa-apa untuk tidak mendapatkan bantuan dari mereka. Kami akan menemukan cara untuk menghadapinya.",
  ui_story_1014_10141501_184_dialog_content = "Saya tidak ingin melihat Anda melakukan apa yang tidak ingin Anda lakukan, PlayerName.",
  ui_story_1014_10141501_185_option_content = "Terima kasih, Vice.",
  ui_story_1014_10141501_186_dialog_content = "Tapi saya tidak akan menyerah untuk menyelesaikan masalah ini.",
  ui_story_1014_10141501_187_option_content = "Aku tidak akan meninggalkanmu sendirian",
  ui_story_1014_10141501_188_dialog_content = "Soroz mengajari saya sejak kecil untuk menghargai setiap teman.",
  ui_story_1014_10141501_189_dialog_content = "Saya tidak akan pernah meninggalkan seorang teman dalam bahaya dan tidak melakukan apa-apa.",
  ui_story_1014_10141501_190_dialog_content = "...",
  ui_story_1014_10141501_191_dialog_content = "(Ya ampun, tiba-tiba suasana menjadi intens...)",
  ui_story_1014_10141501_192_dialog_content = "Katakanlah, ingin jalan-jalan dan menghabiskan waktu?",
  ui_story_1014_10141501_193_dialog_content = "Lagi pula, kami tidak melakukan apa-apa sekarang. Mereka juga tidak menyebutkan kapan kami dibutuhkan.",
  ui_story_1014_10141501_194_dialog_content = "Yeah, aku yakin itu akan baik-baik saja.",
  ui_story_1014_10141501_195_dialog_content = "(Kota bawah ini sangat besar...)",
  ui_story_1014_10141501_196_dialog_content = "(Hampir semua ruangan di lorong adalah laboratorium.)",
  ui_story_1014_10141501_197_dialog_content = "(Aku bertanya-tanya berapa banyak percobaan rahasia yang dilakukan di laboratorium ini...)",
  ui_story_1014_10141501_198_dialog_content = "Saya harus menolak permintaan Anda.",
  ui_story_1014_10141501_199_dialog_content = "Perangkat itu masih dalam tahap percobaan. Selain itu, subjek Anda masih belum stabil.",
  ui_story_1014_10141501_200_dialog_content = "Kemungkinan besar menempatkan subjek melalui eksperimen itu akan merusak mesin yang berharga.",
  ui_story_1014_10141501_201_dialog_content = "Dan mesin yang tidak lengkap tidak dijamin dapat menyembuhkan subjek.",
  ui_story_1014_10141501_202_dialog_content = "Ini adalah proyek saya, tidak ada ruang untuk pendapat Anda.",
  ui_story_1014_10141501_203_dialog_content = "Yang perlu Anda lakukan adalah mengizinkan saya untuk menggunakan peralatan dan tutup mulut.",
  ui_story_1014_10141501_204_dialog_content = "Saya pikir saya mendengar seseorang berbicara di kejauhan.",
  ui_story_1014_10141501_205_dialog_content = "Suara itu terdengar familiar...",
  ui_story_1014_10141501_206_dialog_content = "Saya tidak setuju.",
  ui_story_1014_10141501_207_dialog_content = "Mesin berharga bukanlah mainan untuk Anda mainkan, belum lagi...",
  ui_story_1014_10141501_208_dialog_content = "Anda tidak lagi memiliki izin untuk menuntut saya seperti itu.",
  ui_story_1014_10141501_209_dialog_content = "Itu dia lagi.",
  ui_story_1014_10141501_210_dialog_content = "Anda memberikan izin dan mengambilnya saat itu cocok untuk Anda.",
  ui_story_1014_10141501_211_dialog_content = "Ketika saya mulai bekerja dengan Anda, saya harus mendapatkan hasil yang tak terhitung jumlahnya untuk mendapatkan izin untuk mengakses semuanya di sini.",
  ui_story_1014_10141501_212_dialog_content = "Tapi sekarang, Anda menghapus semua kontribusi saya begitu saja.",
  ui_story_1014_10141501_213_dialog_content = "Anda hanya mendapatkan apa yang pantas Anda dapatkan.",
  ui_story_1014_10141501_214_dialog_content = "Kedengarannya seperti... <color=#FFB400>Meninggalkan</color>!",
  ui_story_1014_10141501_215_dialog_content = "Apakah dia menyandera seseorang?",
  ui_story_1014_10141501_216_dialog_content = "Mari kita lihat!",
  ui_story_1014_10141501_217_dialog_content = "Sangat sedikit peneliti yang bisa melawan. Mereka akan mendapat masalah jika Forsakin menangkap mereka!",
  ui_story_1014_10141501_218_dialog_content = "Bekukan, biarkan dia pergi!",
  ui_story_1014_10141501_219_dialog_content = "(Ini Forsakin! Tapi kenapa aku tidak merasakan kehadirannya?)",
  ui_story_1014_10141501_220_dialog_content = "(Tunggu, dia tidak menyandera peneliti...)",
  ui_story_1014_10141501_221_dialog_content = "(Dia baru saja berbalik dan lari!)",
  ui_story_1014_10141501_222_dialog_content = "Benar-benar kejutan! Itu <color=#FFB400>bahan percobaan</color> Saya perlu datang sendiri!",
  ui_story_1014_10141501_223_dialog_content = "Meninggalkan! Apa yang Anda lakukan di sini, dan mengapa Anda menghubungi peneliti?",
  ui_story_1014_10141501_224_dialog_content = "Saya tidak menyapa siapa pun.",
  ui_story_1014_10141501_225_dialog_content = "Saya di sini hanya untuk mengambil kembali beberapa hal yang saya tinggalkan.",
  ui_story_1014_10141501_226_dialog_content = "Tapi karena materinya sudah datang, saya akan dengan senang hati menerimanya!",
  ui_story_1014_10141501_227_dialog_content = "Bebek, PlayerName! Dibelakangmu!",
  ui_story_1014_10141501_228_dialog_content = "Apa?",
  ui_story_1014_10141501_229_dialog_content = "<anim type=Shake><size=50>Groar!</size></anim>",
  ui_story_1014_10141501_230_dialog_content = "Ugh!",
  ui_story_1014_10141501_231_dialog_content = "Rasanya lama sekali aku tersingkir...",
  ui_story_1014_10141501_232_dialog_content = "Saya pikir saya ingat bertemu Forsakin berbicara dengan seseorang, lalu...",
  ui_story_1014_10141501_233_dialog_content = "Keburukan! Apakah kamu baik-baik saja, Wakil?",
  ui_story_1014_10141501_234_dialog_content = "Dan... Meninggalkan?!",
  ui_story_1014_10141501_235_dialog_content = "Kita bertemu lagi, Caelestite.",
  ui_story_1014_10141501_236_dialog_content = "Lakukan apa yang saya katakan jika Anda tidak ingin melihatnya terluka.",
  ui_story_1014_10141501_237_dialog_content = "...",
  ui_story_1014_10141501_238_dialog_content = "Apa yang sedang Anda coba lakukan? Biarkan dia pergi!",
  ui_story_1014_10141501_239_dialog_content = "Biarkan saja dia pergi, dan aku akan pergi denganmu.",
  ui_story_1014_10141501_240_dialog_content = "Mungkin Anda tidak mengerti situasinya.",
  ui_story_1014_10141501_241_dialog_content = "Sebagai subjek, Anda tidak diizinkan untuk membuat tuntutan.",
  ui_story_1014_10141501_242_dialog_content = "Terutama yang itu...",
  ui_story_1014_10141501_243_dialog_content = "Anda berdua diperlukan untuk percobaan.",
  ui_story_1015_10150101_1_dialog_content = "Gaok, gaok!",
  ui_story_1015_10150101_2_dialog_content = "Ini akan segera gelap.",
  ui_story_1015_10150101_3_dialog_content = "Benar. Mari bergerak.",
  ui_story_1015_10150101_4_dialog_content = "<color=#e8d9bb>*Langkah kaki*</color>",
  ui_story_1015_10150101_5_dialog_content = "Dengarkan baik-baik, Caelestite.",
  ui_story_1015_10150101_6_dialog_content = "Mulai saat ini dan seterusnya, Anda harus mengikuti instruksi saya ke surat itu.",
  ui_story_1015_10150101_7_dialog_content = "Jangan pernah berpikir untuk mencari bantuan, menolak, atau melakukan gerakan gegabah.",
  ui_story_1015_10150101_8_dialog_content = "Saya akan melakukan penelitian yang sangat penting dan membutuhkan bantuan Anda.",
  ui_story_1015_10150101_9_dialog_content = "Apakah Anda berencana menanamkan sesuatu ke dalam tubuh saya lagi?",
  ui_story_1015_10150101_10_dialog_content = "Jadi, Anda masih ingat proyek kecil terakhir kita.",
  ui_story_1015_10150101_11_dialog_content = "Bagaimana mungkin aku bisa lupa? Anda hampir mengubah saya menjadi salah satu dari hal-hal itu!",
  ui_story_1015_10150101_12_dialog_content = "Hampir, memang. Sayang sekali bahwa hal-hal tidak berjalan seperti yang saya harapkan.",
  ui_story_1015_10150101_13_dialog_content = "Itu tidak penting, tetapi saya agak tertarik untuk melihat apa yang akan terjadi jika Anda dan Schummer menjadi kerabat sekali lagi ...",
  ui_story_1015_10150101_14_dialog_content = "Itu seharusnya menghibur.",
  ui_story_1015_10150101_15_dialog_content = "Ngawur? Bagaimana dengan yang lainnya? Bagaimana dengan Eve, Dawn, dan yang lainnya? Apakah yang terjadi pada mereka \"tidak penting\"?",
  ui_story_1015_10150101_16_dialog_content = "Apa yang telah kau lakukan?! Mengapa kamu akan-",
  ui_story_1015_10150101_17_dialog_content = "Kau membuat telingaku sakit.",
  ui_story_1015_10150101_18_dialog_content = "Kalian Caelestites... Suara kalian sepertinya semakin keras setiap detiknya. Bagaimana kalau aku memotong pita suaramu saja?",
  ui_story_1015_10150101_19_dialog_content = "Lagi pula, Anda bahkan tidak membutuhkan suara Anda untuk berkomunikasi, bukan?",
  ui_story_1015_10150101_20_dialog_content = "...",
  ui_story_1015_10150101_21_dialog_content = "Kaulah yang harus diam...",
  ui_story_1015_10150101_22_dialog_content = "Yang ingin saya katakan di sini adalah, jaga mulutmu, Caelestite.",
  ui_story_1015_10150101_23_dialog_content = "Jadilah anak kecil yang patuh dan lakukan persis seperti yang saya minta. Saya tidak punya waktu atau keinginan untuk bernegosiasi dengan Anda.",
  ui_story_1015_10150101_24_dialog_content = "Selama percobaan berjalan lancar, Anda dan Vice mungkin masih memiliki kesempatan untuk bertahan hidup.",
  ui_story_1015_10150101_25_dialog_content = "... Dan jika percobaan tidak berjalan mulus?",
  ui_story_1015_10150101_26_dialog_content = "Hidup Anda harus lebih dari cukup untuk membayar harga kegagalan.",
  ui_story_1015_10150101_27_dialog_content = "...",
  ui_story_1015_10150101_28_dialog_content = "Anda mencoba menggunakan hidup kami untuk mengancam kami?",
  ui_story_1015_10150101_29_dialog_content = "Saya tidak cukup bodoh untuk percaya pada janji yang dibuat oleh Eclipse.",
  ui_story_1015_10150101_30_dialog_content = "Bahkan jika percobaan berhasil, Anda tetap akan membunuh kami.",
  ui_story_1015_10150101_31_dialog_content = "Membunuhmu sama sekali tidak akan menguntungkanku.",
  ui_story_1015_10150101_32_dialog_content = "Saya memiliki Caelestite terakhir yang bertahan dan produk Chord Link yang sukses sebelum saya.",
  ui_story_1015_10150101_33_dialog_content = "Kalian berdua adalah spesimen yang tak ternilai harganya. Jika diberi kesempatan, saya lebih suka membawa Anda kembali ke laboratorium saya daripada mengakhiri hidup Anda sebelum waktunya.",
  ui_story_1015_10150101_34_dialog_content = "Tapi sayangnya, saya tidak memiliki kebebasan seperti itu di dalam perbatasan Illumina.",
  ui_story_1015_10150101_35_dialog_content = "Oleh karena itu, saya berjanji untuk memberi Anda setidaknya kesempatan untuk keluar dari sini hidup-hidup.",
  ui_story_1015_10150101_36_dialog_content = "Bukan sebagai tanda belas kasihan yang besar, tentu saja, tetapi demi peluang penelitian di masa depan.",
  ui_story_1015_10150101_37_dialog_content = "Kamu...",
  ui_story_1015_10150101_38_dialog_content = "Penelitian tampaknya menjadi satu-satunya hal yang penting dalam pikiran Anda.",
  ui_story_1015_10150101_39_dialog_content = "Tentu saja. Secara pribadi, saya tidak melihat apa lagi dalam hidup yang mungkin layak untuk diganggu.",
  ui_story_1015_10150101_40_dialog_content = "Mari kita bahas eksperimen yang akan datang. Mungkin membuat segalanya sedikit lebih mudah jika Anda tahu apa yang diharapkan.",
  ui_story_1015_10150101_41_dialog_content = "Hei, kami bahkan belum setuju untuk mematuhimu!",
  ui_story_1015_10150101_42_dialog_content = "Anda tidak benar-benar punya pilihan.",
  ui_story_1015_10150101_43_dialog_content = "...",
  ui_story_1015_10150101_44_dialog_content = "Saya sedang meneliti metode merangsang metamorfosis dalam tubuh Aurorian.",
  ui_story_1015_10150101_45_dialog_content = "Tujuan saya adalah untuk mengembangkan Aurorian menjadi spesies yang lebih maju tanpa mengorbankan kemampuan yang sudah mereka miliki.",
  ui_story_1015_10150101_46_dialog_content = "... Kamu terdengar gila.",
  ui_story_1015_10150101_47_dialog_content = "Anda telah menggunakan Chord Link yang ditinggalkan Caelestites sebelumnya. Pikirkan kembali sejenak, dan Anda harus bisa mengerti.",
  ui_story_1015_10150101_48_dialog_content = "Ini memiliki potensi seperti itu.",
  ui_story_1015_10150101_49_dialog_content = "Anda ingin melakukan sesuatu dengan Chord Link?",
  ui_story_1015_10150101_50_dialog_content = "Ya, itu sebabnya saya di sini.",
  ui_story_1015_10150101_51_dialog_content = "Anda pasti tahu bahwa Illumina menggali Tautan Chord yang tersembunyi di Undercity ini, benar?",
  ui_story_1015_10150101_52_dialog_content = "Ya, kami tahu...",
  ui_story_1015_10150101_53_dialog_content = "Peralatan ini sangat penting untuk penelitian saya.",
  ui_story_1015_10150101_54_dialog_content = "Saya perlu menggunakannya untuk eksperimen, mengumpulkan data, dan menemukan penggunaan yang paling cocok untuk Chord Link.",
  ui_story_1015_10150101_55_dialog_content = "Jika memungkinkan, saya ingin menciptakan bentuk kehidupan yang lebih unggul dari Aurorian.",
  ui_story_1015_10150101_56_dialog_content = "K-Kamu ingin berubah Vice untuk eksperimenmu?!",
  ui_story_1015_10150101_57_dialog_content = "Hah, harapanku padanya tidak setinggi itu. Vice hanya akan berfungsi sebagai sampel untuk mengukur data eksperimen. Dia tidak akan terlibat dalam transformasi akhir.",
  ui_story_1015_10150101_58_dialog_content = "Dia akan menjadi orang pertama yang menerima kehormatan ini.",
  ui_story_1015_10150101_59_dialog_content = "...",
  ui_story_1015_10150101_60_dialog_content = "Oh...",
  ui_story_1015_10150101_61_dialog_content = "(Apakah Forsakin menyelamatkannya hanya demi eksperimen ini?)",
  ui_story_1015_10150101_62_dialog_content = "(Atau mungkin sebaliknya, tujuan sebenarnya dari penelitian ini adalah untuk menyelamatkannya...)",
  ui_story_1015_10150101_63_dialog_content = "Namun, jika penelitian saya berjalan dengan baik, Anda juga akan mendapat manfaat darinya.",
  ui_story_1015_10150101_64_dialog_content = "Saya telah melihat data di Illumina. Vice tampaknya menunjukkan efek samping tertentu setelah ditingkatkan oleh Chord Link, benar?",
  ui_story_1015_10150101_65_dialog_content = "Bagaimana Anda mendapatkan data itu ?!",
  ui_story_1015_10150101_66_dialog_content = "Itu bukan urusanmu!",
  ui_story_1015_10150101_67_dialog_content = "Setelah penelitian saya selesai, mungkin ada kemungkinan efek samping ini dapat dihilangkan dengan menggunakan Chord Link.",
  ui_story_1015_10150101_68_dialog_content = "Jadi, seperti yang Anda lihat, ini benar-benar situasi win-win.",
  ui_story_1015_10150101_69_dialog_content = "... Anda pikir Anda dapat membujuk kami untuk mematuhinya dengan mudah?",
  ui_story_1015_10150101_70_dialog_content = "Saya tidak benar-benar berpikir saya perlu membujuk Anda. Membantuku adalah satu-satunya cara bagimu untuk keluar dari sini hidup-hidup.",
  ui_story_1015_10150101_71_dialog_content = "Saya hanya menyatakan fakta, bahwa penelitian ini mungkin bermanfaat bagi Anda.",
  ui_story_1015_10150101_72_dialog_content = "Baiklah baiklah. Seperti yang Anda katakan, kami tidak punya pilihan.",
  ui_story_1015_10150101_73_dialog_content = "Tapi saya tidak mengerti. Apa sebenarnya yang Anda ingin kami bantu?",
  ui_story_1015_10150101_74_dialog_content = "Saya membutuhkan Anda untuk membantu saya menghilangkan beberapa kendala yang menghalangi jalan penelitian saya.",
  ui_story_1015_10150101_75_dialog_content = "Penelitian saya membutuhkan peralatan dan data. Keduanya berada dalam cengkeraman Illumina.",
  ui_story_1015_10150101_76_dialog_content = "Tapi jelas, mereka tidak akan pernah memberikan akses kepada orang luar.",
  ui_story_1015_10150101_77_dialog_content = "<color=#e8d9bb>Perbatasan Senja</color>",
  ui_story_1015_10150101_78_dialog_content = "Cepat, bawa ksatria yang terluka duluan!",
  ui_story_1015_10150101_79_dialog_content = "Siap, Pak!",
  ui_story_1015_10150101_80_dialog_content = "Lakukan apa yang kamu bisa untuk Illumina yang terluka juga. Mereka bahkan lebih singkat daripada kita.",
  ui_story_1015_10150101_81_dialog_content = "Terima kasih, Kapten Leo...",
  ui_story_1015_10150101_82_dialog_content = "Tidak perlu berterima kasih padaku. Kita semua berjuang dalam pertempuran yang sama.",
  ui_story_1015_10150101_83_dialog_content = "Aku tidak menyangka kita akan menghadapi musuh yang begitu kuat hari ini. Kami telah menderita banyak korban...",
  ui_story_1015_10150101_84_dialog_content = "Itu semua salah ku. Saya tidak cukup baik untuk melayani sebagai komandan ...",
  ui_story_1015_10150101_85_dialog_content = "Berhenti menyalahkan diri sendiri. Saat menghadapi musuh sekuat ini, kekalahan tidak bisa dihindari.",
  ui_story_1015_10150101_86_dialog_content = "Dan saya entah bagaimana berpikir kekalahan kami hari ini tidak bisa dihindari.",
  ui_story_1015_10150101_87_dialog_content = "Kenapa bisa begitu?",
  ui_story_1015_10150101_88_dialog_content = "Sepertinya ada yang tidak beres tentang penggerebekan di Twilight ini.",
  ui_story_1015_10150101_89_dialog_content = "Dalam beberapa hari terakhir, kota ini telah menjadi sasaran beberapa serangan besar-besaran berturut-turut.",
  ui_story_1015_10150101_90_dialog_content = "Ini menurut saya aneh. Musuh tidak pernah seaktif ini.",
  ui_story_1015_10150101_91_dialog_content = "Maksudmu Eclipsites sedang merencanakan sesuatu yang besar?",
  ui_story_1015_10150101_92_dialog_content = "Saya tidak yakin, tetapi akan lebih bijaksana untuk mempersiapkannya terlebih dahulu.",
  ui_story_1015_10150101_93_dialog_content = "Sean, kudengar ketuamu baru saja kembali. Apakah itu benar?",
  ui_story_1015_10150101_94_dialog_content = "Ya, dia kembali belum lama ini.",
  ui_story_1015_10150101_95_dialog_content = "Biarkan aku meminjamnya sebentar. Katakan saja padanya aku akan menjemputnya di tempat biasa.",
  ui_story_1015_10150101_96_dialog_content = "Selamat datang! Meja untuk satu?",
  ui_story_1015_10150101_97_dialog_content = "Saya mencari seseorang.",
  ui_story_1015_10150101_98_dialog_content = "Tidak setiap hari saya diundang makan malam oleh Twilight yang paling terkenal.",
  ui_story_1015_10150101_99_dialog_content = "Duduk dan gali.",
  ui_story_1015_10150101_100_dialog_content = "Tidak terima kasih, saya sudah makan.",
  ui_story_1015_10150101_101_dialog_content = "Bahkan lebih baik! Berikan aku piringmu.",
  ui_story_1015_10150101_102_dialog_content = "Saya pikir akan lebih pas untuk menyimpannya di depan saya. Bagaimanapun, ini adalah makan malam selamat datang di rumah saya.",
  ui_story_1015_10150101_103_dialog_content = "Saya berasumsi Anda meminta saya di sini untuk sesuatu yang lebih penting daripada makan.",
  ui_story_1015_10150101_104_dialog_content = "Tentu saja, saya tidak akan pernah meminta seseorang untuk menemani saya hanya untuk melihat wajah saya.",
  ui_story_1015_10150101_105_dialog_content = "Sudahkah Anda membaca laporan korban Illumina selama beberapa hari terakhir?",
  ui_story_1015_10150101_106_dialog_content = "Saya memiliki. Angka-angka itu agak tidak normal.",
  ui_story_1015_10150101_107_dialog_content = "Garnisun Illumina Twilight tidak pernah mengalami kerugian terkonsentrasi seperti itu.",
  ui_story_1015_10150101_108_dialog_content = "Intensitas pertempuran beberapa hari terakhir telah mencapai titik kritis. Kami berada di batas dari apa yang bisa kami tahan.",
  ui_story_1015_10150101_109_dialog_content = "Hal yang paling membingungkan bukanlah jumlah korban yang telah kami timbulkan, tetapi sejauh ini kami tidak mampu mengalahkan musuh secara meyakinkan.",
  ui_story_1015_10150101_110_dialog_content = "Setiap pertempuran telah mengakibatkan kedua belah pihak mundur setelah jalan buntu.",
  ui_story_1015_10150101_111_dialog_content = "Jelas, kami belum bisa mengetahui kekuatan pasukan musuh kami.",
  ui_story_1015_10150101_112_dialog_content = "Skenario terburuknya adalah bahwa semua pertemuan ini sebenarnya adalah kelompok independen dari Eclipsites.",
  ui_story_1015_10150101_113_dialog_content = "Jika mereka berkumpul untuk mengepung Twilight, konsekuensinya akan di luar perhitungan.",
  ui_story_1015_10150101_114_dialog_content = "Baik. Sangat menyegarkan mendengar pikiran dari pikiran yang cerdas.",
  ui_story_1015_10150101_115_dialog_content = "Sudahkah Anda menyusun strategi untuk menghadapi situasi tersebut?",
  ui_story_1015_10150101_116_dialog_content = "Saya mengerahkan pasukan untuk melakukan pengintaian rahasia dalam upaya untuk sepenuhnya memahami pergerakan musuh.",
  ui_story_1015_10150101_117_dialog_content = "Tapi menurut saya, kekuatan militer kita saat ini tidak cukup untuk mempertahankan genggaman kita pada Twilight.",
  ui_story_1015_10150101_118_dialog_content = "Inilah mengapa saya akan mengirim permintaan bala bantuan.",
  ui_story_1015_10150101_119_dialog_content = "Hmm... Ya, ini pilihan yang paling aman.",
  ui_story_1015_10150101_120_dialog_content = "Anda ingin menemui saya mengenai masalah ini, jadi saya menganggap Anda berniat untuk mendapatkan bantuan dari Illumina, benar?",
  ui_story_1015_10150101_121_dialog_content = "Tentu saja, kita masih belum tahu berapa banyak musuh yang harus kita hadapi di masa depan.",
  ui_story_1015_10150101_122_dialog_content = "Akan sangat picik untuk membiarkan perbedaan Lumopolis dan Illumina muncul di antara kita pada titik ini, bukan?",
  ui_story_1015_10150101_123_dialog_content = "Saya mengerti. Saya akan mengirim pesan segera setelah saya kembali.",
  ui_story_1015_10150101_124_dialog_content = "Bagus, lebih cepat lebih baik. Yang paling kurang dari kita saat ini adalah waktu.",
  ui_story_1015_10150101_125_dialog_content = "Saya memiliki firasat bahwa situasi yang kami bayangkan kemungkinan besar akan segera menjadi kenyataan.",
  ui_story_1015_10150101_126_dialog_content = "<color=#e8d9bb>Lumopolis, Pengadilan Kerajaan</color>",
  ui_story_1015_10150101_127_dialog_content = "Huh...",
  ui_story_1015_10150101_128_dialog_content = "Carleen, apakah kamu sudah menyelesaikan laporanmu?",
  ui_story_1015_10150101_129_dialog_content = "Aku pernah.",
  ui_story_1015_10150101_130_dialog_content = "Anda terlihat sedikit lelah.",
  ui_story_1015_10150101_131_dialog_content = "Berbicara dengannya adalah tugas yang melelahkan.",
  ui_story_1015_10150101_132_dialog_content = "Saya pikir itu buang-buang waktu. Apa yang ingin dia dengar hampir tidak ada hubungannya dengan apa yang ingin saya katakan.",
  ui_story_1015_10150101_133_dialog_content = "Anda berbicara tentang perselingkuhan Twilight, ya?",
  ui_story_1015_10150101_134_dialog_content = "Ya. Saya tidak mengerti mengapa dia terus bertanya tentang alokasi sumber daya dan struktur organisasi.",
  ui_story_1015_10150101_135_dialog_content = "Jelas, fakta yang saya laporkan kepadanya adalah—",
  ui_story_1015_10150101_136_dialog_content = "Lupakan. Saya seharusnya tidak mengeluh tentang hal-hal seperti itu.",
  ui_story_1015_10150101_137_dialog_content = "Ya, itu sudah cukup. Sekarang, ayo kita minum teh.",
  ui_story_1015_10150101_138_dialog_content = "Apakah Anda punya rencana untuk beberapa hari ke depan?",
  ui_story_1015_10150101_139_dialog_content = "Tidak banyak. Tuan Kota meminta saya untuk tetap siaga di Lumopolis.",
  ui_story_1015_10150101_140_dialog_content = "Siaga? Oh, itu benar, itu karena <color=#FFB400>Latihan Militer Bersama</color> cepat mendekat, bukan?",
  ui_story_1015_10150101_141_dialog_content = "Ya, seharusnya begitu.",
  ui_story_1015_10150101_142_dialog_content = "Anda harus mempersiapkan diri. Anda adalah bintang pertunjukan, Anda tahu.",
  ui_story_1015_10150101_143_dialog_content = "Tapi... Aku merasa agak gelisah saat ini.",
  ui_story_1015_10150101_144_dialog_content = "Ada apa?",
  ui_story_1015_10150101_145_dialog_content = "Saya belum menerima kabar dari PlayerName.",
  ui_story_1015_10150101_146_dialog_content = "Saya tidak tahu bagaimana dia dan Vice sedang melakukan...",
  ui_story_1015_10150101_147_dialog_content = "Oh itu Carleen! Sudah lama!",
  ui_story_1015_10150101_148_dialog_content = "Memang sudah lama, Gronru. Saya harap saya tidak mengganggu Anda dengan panggilan tiba-tiba saya.",
  ui_story_1015_10150101_149_dialog_content = "Tidak, Anda menelepon pada waktu yang tepat.",
  ui_story_1015_10150101_150_dialog_content = "Saya baru saja membuat terobosan besar dalam pekerjaan saya di Soroz.",
  ui_story_1015_10150101_151_dialog_content = "Dengarkan ini.",
  ui_story_1015_10150101_152_dialog_content = "Aktifkan, Soroz!",
  ui_story_1015_10150101_153_dialog_content = "Aktivasi Soroz selesai.",
  ui_story_1015_10150101_154_dialog_content = "Apakah Anda mendengarnya?!",
  ui_story_1015_10150101_155_dialog_content = "Aku mendengarnya, tapi... bukankah Soroz selalu bisa aktif tanpa insiden?",
  ui_story_1015_10150101_156_dialog_content = "Saya tahu saya tahu! Kami selalu bisa menerbangkannya, tapi dia tidak memiliki kesadaran sebelumnya, kan?",
  ui_story_1015_10150101_157_dialog_content = "Benar.",
  ui_story_1015_10150101_158_dialog_content = "Jangan khawatir, Echo Template-nya pada dasarnya telah dipulihkan.",
  ui_story_1015_10150101_159_dialog_content = "Hanya saja kami orang Aurorian tidak bisa berkomunikasi dengannya secara langsung.",
  ui_story_1015_10150101_160_dialog_content = "Tapi tunggu saja PlayerName untuk kembali, maka dia akan dapat berbicara dengan Soroz!",
  ui_story_1015_10150101_161_dialog_content = "Oh itu benar! Sebenarnya aku ingin bertanya padamu ada apa PlayerName... Dan Vice, Tentu saja!",
  ui_story_1015_10150101_162_dialog_content = "Apa yang terjadi pada mereka setelah terakhir kali saya melihat mereka?",
  ui_story_1015_10150101_163_dialog_content = "Mereka belum menghubungi saya sejak saya kembali ke Lumopolis.",
  ui_story_1015_10150101_164_dialog_content = "Yah, aku sudah melihat laporan mereka.",
  ui_story_1015_10150101_165_dialog_content = "Mereka mengatakan mereka memasuki Undercity rahasia untuk memulihkan diri dan mungkin terpaksa menjadi gelap untuk sementara waktu.",
  ui_story_1015_10150101_166_dialog_content = "Mereka mungkin akan menghubungi Anda saat mereka kembali dengan kekuatan penuh.",
  ui_story_1015_10150101_167_dialog_content = "Undercity rahasia?",
  ui_story_1015_10150101_168_dialog_content = "Ya. Jangan khawatir, tingkat kerahasiaan di sana cukup tinggi.",
  ui_story_1015_10150101_169_dialog_content = "Saya pikir nama itu...",
  ui_story_1015_10150101_170_dialog_content = "Oh ya, itu <color=#FFB400>Institut X</color>.",
  ui_story_1015_10150101_171_dialog_content = "<color=#e8d9bb>Stasiun Kereta Kota Gannon</color>",
  ui_story_1015_10150101_172_dialog_content = "Minggir! Aku tidak bisa melihat apa-apa dari belakang sini!",
  ui_story_1015_10150101_173_dialog_content = "Hei, bukankah itu terlihat agak bengkok bagimu?",
  ui_story_1015_10150101_174_dialog_content = "Itu benar! Gantungkan bendera kita sedikit lebih tinggi!",
  ui_story_1015_10150101_175_dialog_content = "Apa keributan di sini? Apa yang mereka semua lihat?",
  ui_story_1015_10150101_176_dialog_content = "Anda tidak tahu? Latihan Militer Gabungan akan segera dimulai. Itu adalah bendera dari berbagai pasukan yang berpartisipasi yang berkibar di depan.",
  ui_story_1015_10150101_177_dialog_content = "Oh! Saatnya Latihan Gabungan lagi.",
  ui_story_1015_10150101_178_dialog_content = "Latihan tahun ini seharusnya cukup menarik. Surat kabar berbondong-bondong mengantre di meja resepsionis setiap hari.",
  ui_story_1015_10150101_179_dialog_content = "Benar-benar? Apakah ada sesuatu yang istimewa tentang latihan militer tahun ini?",
  ui_story_1015_10150101_180_dialog_content = "Tentu saja. Akan ada peserta Caelestite kali ini, untuk pertama kalinya dalam lebih dari satu dekade.",
  ui_story_1015_10150101_181_dialog_content = "<color=#e8d9bb>Departemen Intelijen Kota Gannon</color>",
  ui_story_1015_10150101_182_dialog_content = "<color=#e8d9bb>Tok, tok, tok…</color>",
  ui_story_1015_10150101_183_dialog_content = "Masuk.",
  ui_story_1015_10150101_184_dialog_content = "Kolonel Yingel, ada telegram penting untukmu.",
  ui_story_1015_10150101_185_dialog_content = "Silakan lihat kenyamanan Anda yang paling awal.",
  ui_story_1015_10150101_186_dialog_content = "Telegram mendesak?",
  ui_story_1015_10150101_187_dialog_content = "Baiklah, saya mengerti. Biarkan saja di mejaku.",
  ui_story_1015_10150101_188_dialog_content = "Siap, Kapten!",
  ui_story_1015_10150101_189_dialog_content = "Mari kita lihat pesanan mendesak siapa ini...",
  ui_story_1015_10150101_190_dialog_content = "Hmm? Tuan Ulysses?",
  ui_story_1015_10150201_1_dialog_content = "Ayo cepat. Berhenti berlama-lama.",
  ui_story_1015_10150201_2_dialog_content = "Anda sebaiknya berjalan lebih cepat dari pisau saya, jika Anda tahu apa yang baik untuk Anda.",
  ui_story_1015_10150201_3_dialog_content = "… Oke.",
  ui_story_1015_10150201_4_dialog_content = "Tapi sungguh, apakah kita harus bangun pagi-pagi sekali setiap hari?",
  ui_story_1015_10150201_5_dialog_content = "Sudah lama sekali aku tidak tidur nyenyak.",
  ui_story_1015_10150201_6_dialog_content = "Jelas, lebih dari satu dekade bermalas-malasan telah mengubah Anda menjadi anak manja yang cengeng.",
  ui_story_1015_10150201_7_dialog_content = "Jadwal kami tidak serampangan parah. Seperti yang Anda lihat, para penjaga sudah bangun untuk giliran kerja mereka.",
  ui_story_1015_10150201_8_dialog_content = "*Huh* Berapa lama ini akan berlangsung?",
  ui_story_1015_10150201_9_dialog_content = "Kami memiliki tenggat waktu yang jelas.",
  ui_story_1015_10150201_10_dialog_content = "Anda pasti pernah mendengar: Illumina sedang mempersiapkan acara yang disebut Latihan Militer Gabungan. Anda berdua akan menerima undangan.",
  ui_story_1015_10150201_11_dialog_content = "Jika Anda tidak hadir saat acara dimulai, Illumina pasti akan mengirim seseorang untuk menimbulkan masalah.",
  ui_story_1015_10150201_12_dialog_content = "Jadi, itulah tenggat waktu kami.",
  ui_story_1015_10150201_13_dialog_content = "(Benar, Latihan Militer Gabungan! Apakah itu yang akan menyelamatkan kita di sini?)",
  ui_story_1015_10150201_14_dialog_content = "Kabar baiknya bagi Anda adalah bahwa penculikan ini tidak akan berlangsung lama.",
  ui_story_1015_10150201_15_dialog_content = "Kabar buruknya adalah, jika percobaan tidak berhasil diselesaikan dalam tenggat waktu, hidup Anda akan jauh lebih pendek dari yang Anda perkirakan.",
  ui_story_1015_10150201_16_dialog_content = "...",
  ui_story_1015_10150201_17_dialog_content = "Jangan buang waktuku. Dengan begitu, Anda bisa menjaga diri Anda tetap hidup.",
  ui_story_1015_10150201_18_dialog_content = "Hei, berhenti mendorongku! Aku tahu jalannya!",
  ui_story_1015_10150201_19_dialog_content = "Saya sudah ke laboratorium berkali-kali sekarang.",
  ui_story_1015_10150201_20_dialog_content = "Saya tidak ingin membuang terlalu banyak waktu untuk sesuatu yang tidak berhubungan dengan percobaan.",
  ui_story_1015_10150201_21_dialog_content = "Berkonsentrasi dan bahkan tidak berpikir untuk mencoba mengungkapkan keberadaan kita.",
  ui_story_1015_10150201_22_dialog_content = "Jika Anda mencoba berteriak minta tolong seperti yang Anda lakukan sebelumnya, saya berjanji, saya akan memotong lidah Anda.",
  ui_story_1015_10150201_23_dialog_content = "Kami mengerti. Lihat, kami melakukan persis seperti yang Anda minta kali ini.",
  ui_story_1015_10150201_24_dialog_content = "Rute patroli dan waktu shift penjaga ditetapkan. Tidak akan ada kecelakaan...",
  ui_story_1015_10150201_25_dialog_content = "...",
  ui_story_1015_10150201_26_dialog_content = "<size=50>Wah!</size> Ini...",
  ui_story_1015_10150201_27_dialog_content = "<size=50><anim type=Shake>Mengaum!!!</anim></size>",
  ui_story_1015_10150201_28_dialog_content = "Forsakin, anjingmu mengikuti kita lagi.",
  ui_story_1015_10150201_29_dialog_content = "Izinkan saya mengatakan ini sekali lagi, Jade bukanlah seekor anjing.",
  ui_story_1015_10150201_30_dialog_content = "Bagus. Anda ... hewan peliharaan.",
  ui_story_1015_10150201_31_dialog_content = "Bukankah memiliki hal yang begitu besar mengikuti kita sedikit mencolok?",
  ui_story_1015_10150201_32_dialog_content = "Kami membutuhkan bantuan untuk penelitian hari ini. Itu sebabnya saya menyebutnya di sini.",
  ui_story_1015_10150201_33_dialog_content = "Riset...",
  ui_story_1015_10150201_34_dialog_content = "Sekarang setelah Anda menyebutkannya, apakah benda ini juga merupakan hasil penelitian Anda?",
  ui_story_1015_10150201_35_dialog_content = "...",
  ui_story_1015_10150201_36_dialog_content = "Hewan apa yang awalnya Jade miliki?",
  ui_story_1015_10150201_37_dialog_content = "Seekor chinchilla.",
  ui_story_1015_10150201_38_dialog_content = "Seekor chinchilla?!",
  ui_story_1015_10150201_39_dialog_content = "Anda mengubah binatang kecil yang lucu menjadi ini ...?",
  ui_story_1015_10150201_40_dialog_content = "Kata-kata seperti \"imut\" dan \"kecil\" hanya menunjukkan arogansi perspektif Anda dari puncak rantai makanan yang seharusnya.",
  ui_story_1015_10150201_41_dialog_content = "Hah?",
  ui_story_1015_10150201_42_dialog_content = "Karena Andalah yang menentukan hidup dan mati makhluk lain, kemampuan mereka untuk menyenangkan Anda menjadi keuntungan mereka.",
  ui_story_1015_10150201_43_dialog_content = "Di alam bebas, ukuran chinchilla tidak diragukan lagi membatasi kemampuannya untuk menempati ceruk ekologis yang lebih tinggi.",
  ui_story_1015_10150201_44_dialog_content = "Dan sekarang Jade telah menembus batasan ini.",
  ui_story_1015_10150201_45_dialog_content = "Dengan cara apa, tepatnya?",
  ui_story_1015_10150201_46_dialog_content = "Sederhananya, ia sekarang memiliki pilihan pilihan predasi yang lebih kaya.",
  ui_story_1015_10150201_47_dialog_content = "Waktu yang tepat, sekarang saatnya bagi kita untuk terlibat dalam pertempuran dengan tentara yang menjaga gerbang.",
  ui_story_1015_10150201_48_dialog_content = "Hai! Anda tidak berencana memberi makan tentara untuk hewan peliharaan Anda, bukan?!",
  ui_story_1015_10150201_49_dialog_content = "Kami setuju untuk membantumu bertarung, tapi kami tidak akan membahayakan nyawa prajurit!",
  ui_story_1015_10150201_50_dialog_content = "Anda tampak begitu tidak peduli dengan masa depan seluruh ras, namun Anda sangat peduli dengan hilangnya satu atau dua nyawa yang tidak berarti.",
  ui_story_1015_10150201_51_dialog_content = "Bagus. Saya tidak tertarik untuk memperbaiki kekurangan Anda.",
  ui_story_1015_10150201_52_dialog_content = "Bisakah Anda benar-benar mengatakan bahwa beberapa nyawa tidak penting? Mereka-",
  ui_story_1015_10150201_53_dialog_content = "Sama seperti sebelumnya, Anda harus memberi saya data pertempuran, Caelestite.",
  ui_story_1015_10150201_54_dialog_content = "Laboratorium telah memperkuat pertahanannya. Pertempuran ini akan lebih sulit daripada yang terakhir kali.",
  ui_story_1015_10150201_55_dialog_content = "Saya bisa menahan lebih dari milik saya di medan perang. Anda harus benar-benar mempertimbangkan untuk membiarkan saya bertarung.",
  ui_story_1015_10150201_56_dialog_content = "Sedangkan untukmu, tetaplah di tempatmu sekarang dan jangan lakukan apa pun kecuali aku menyuruhmu, jika tidak, aku akan memastikan kamu menjadi gigitan pertama Jade untuk sarapan.",
  ui_story_1015_10150201_57_dialog_content = "Hmph.",
  ui_story_1015_10150201_58_dialog_content = "Caelestite, tetap di belakangku.",
  ui_story_1015_10150201_59_dialog_content = "Ayo selesaikan ini.",
  ui_story_1015_10150302_1_dialog_content = "<color=#e8d9bb>Gedebuk-</color>",
  ui_story_1015_10150302_2_dialog_content = "Tidak, tidak, tidak, berhenti! Jangan terlalu keras pada mereka!",
  ui_story_1015_10150302_3_dialog_content = "Apa yang akan kita lakukan jika itu benar-benar melukai mereka?!",
  ui_story_1015_10150302_4_dialog_content = "Ini sudah berakhir. Pindahkan tentara yang tidak sadarkan diri ini ke satu sisi.",
  ui_story_1015_10150302_5_dialog_content = "Jangan biarkan tentara yang berpatroli menemukan mereka, setidaknya saat kita sedang melakukan percobaan.",
  ui_story_1015_10150302_6_dialog_content = "<size=45><anim type=Shake>Graah!</anim></size>",
  ui_story_1015_10150302_7_dialog_content = "Bersikaplah lembut dengan mereka!",
  ui_story_1015_10150302_8_dialog_content = "Biarkan aku yang mengurusnya.",
  ui_story_1015_10150302_9_dialog_content = "Dengan cepat. Berhenti membuang-buang waktu.",
  ui_story_1015_10150302_10_dialog_content = "Saya tahu saya tahu. Ini bukan pertama kalinya.",
  ui_story_1015_10150302_11_dialog_content = "Maaf telah membantu Forsakin mengalahkan kalian.",
  ui_story_1015_10150302_12_dialog_content = "Hah? Banyak hal baru saja jatuh ke tanah.",
  ui_story_1015_10150302_13_dialog_content = "Mari kita kembalikan semua ini ke saku Anda.",
  ui_story_1015_10150302_14_dialog_content = "Pisau... kunci... kartu kunci...",
  ui_story_1015_10150302_15_dialog_content = "Apa ini? Kotak jahit?",
  ui_story_1015_10150302_16_dialog_content = "Saya pikir saya bisa membukanya.",
  ui_story_1015_10150302_17_dialog_content = "<size=45>!!!</size>",
  ui_story_1015_10150302_18_dialog_content = "Oh, itu adalah <color=#FFB400>lebih ringan</color>...",
  ui_story_1015_10150302_19_dialog_content = "<size=50><anim type=Shake>Groar!</anim></size>",
  ui_story_1015_10150302_20_dialog_content = "Wah! Apa yang kamu lakukan, Jidat?!",
  ui_story_1015_10150302_21_dialog_content = "<size=45><anim type=Shake>Graah!</anim></size>",
  ui_story_1015_10150302_22_dialog_content = "<color=#e8d9bb>Krak!</color>",
  ui_story_1015_10150302_23_dialog_content = "It-It menginjak korek api?",
  ui_story_1015_10150302_24_dialog_content = "Itu hanya korek api. Apa masalahnya?",
  ui_story_1015_10150302_25_dialog_content = "...",
  ui_story_1015_10150302_26_dialog_content = "Area di sekitar laboratorium sangat mudah terbakar. Bahkan percikan terkecil pun bisa menimbulkan bencana.",
  ui_story_1015_10150302_27_dialog_content = "Jangan biarkan hal seperti itu terjadi lagi.",
  ui_story_1015_10150302_28_dialog_content = "Oke…",
  ui_story_1015_10150302_29_dialog_content = "(Kalau memang begitu, kenapa para penjaga masih diperbolehkan membawa korek api?)",
  ui_story_1015_10150302_30_dialog_content = "Ayo pergi. Berhenti membuang-buang waktu.",
  ui_story_1015_10150302_31_dialog_content = "<color=#e8d9bb>Ngungg!</color>",
  ui_story_1015_10150302_32_dialog_content = "Pintunya terbuka. Sekarang masuk.",
  ui_story_1015_10150302_33_dialog_content = "Anda pergi ke depan dan menunggu saya di sana.",
  ui_story_1015_10150302_34_dialog_content = "Sedang apa kau?",
  ui_story_1015_10150302_35_dialog_content = "Apakah Anda ... mengubah kode sandi untuk pintu?",
  ui_story_1015_10150302_36_dialog_content = "... Cih.",
  ui_story_1015_10150302_37_dialog_content = "(Mungkin untuk mencegah para penjaga mengejar, menggunakan kunci untuk mengulur waktu.)",
  ui_story_1015_10150302_38_dialog_content = "Hmm... Pintu ini seharusnya untuk menghentikan orang seperti kita, tapi sekarang malah digunakan untuk menghentikan para penjaga.",
  ui_story_1015_10150302_39_dialog_content = "Mesin tidak memiliki kesadaran. Mereka hanya melayani mereka yang tahu bagaimana menggunakannya.",
  ui_story_1015_10150302_40_dialog_content = "Anda tampaknya tahu tempat ini dengan sangat baik.",
  ui_story_1015_10150302_41_dialog_content = "Hmm?",
  ui_story_1015_10150302_42_dialog_content = "Anda dapat menyusup ke lembaga penelitian, membiasakan diri dengan tata letak internal, dan bahkan mendapatkan akses ke sebagian besar pintu dan mesin.",
  ui_story_1015_10150302_43_dialog_content = "Langkah-langkah keamanan Illumina adalah lelucon di mata Anda.",
  ui_story_1015_10150302_44_dialog_content = "Ini semua adalah prasyarat yang diperlukan bagi saya untuk mengimplementasikan rencana saya.",
  ui_story_1015_10150302_45_dialog_content = "Jika saya tidak dapat melakukannya, saya tidak akan berada di sini sekarang.",
  ui_story_1015_10150302_46_dialog_content = "Tapi bagaimana caranya? Karena Anda pernah menjadi peneliti Illumina?",
  ui_story_1015_10150302_47_dialog_content = "Karena saya membangun lembaga penelitian ini sendiri.",
  ui_story_1015_10150302_48_dialog_content = "Apa?!",
  ui_story_1015_10150302_49_dialog_content = "Anda membangunnya...",
  ui_story_1015_10150302_50_dialog_content = "Pada saat itu, itu disebut Undercity X.",
  ui_story_1015_10150302_51_dialog_content = "Baiklah, kode sandi telah diatur ulang.",
  ui_story_1015_10150302_52_dialog_content = "Saatnya memulai percobaan hari ini.",
  ui_story_1015_10150302_53_dialog_content = "Wow, benar-benar ada Chord Link di sini!",
  ui_story_1015_10150302_54_dialog_content = "Meskipun ada beberapa perbedaan antara yang ini dan yang ada di Obelisk of Return, itu jelas merupakan hal yang sama.",
  ui_story_1015_10150302_55_dialog_content = "Illumina telah melakukan penelitian rahasia selama bertahun-tahun sekarang dengan tingkat kerahasiaan yang tinggi.",
  ui_story_1015_10150302_56_dialog_content = "Hanya fosil tua di Komite dan Dewan Sains yang diizinkan mengaksesnya.",
  ui_story_1015_10150302_57_dialog_content = "Aku bertanya-tanya sejauh mana penelitian Illumina telah berkembang...",
  ui_story_1015_10150302_58_dialog_content = "Anda tidak pernah membiarkan kami masuk ke sini sebelumnya... Mengapa Anda berubah pikiran hari ini?",
  ui_story_1015_10150302_59_dialog_content = "Karena penelitian saya sudah maju ke tahap selanjutnya.",
  ui_story_1015_10150302_60_dialog_content = "Illumina telah menginvestasikan penelitian puluhan tahun untuk menemukan cara menggunakan instrumen ini, tetapi saya tidak punya banyak waktu.",
  ui_story_1015_10150302_61_dialog_content = "Jadi, saya perlu menggunakan eksperimen yang efisien untuk mempelajari metode mereka.",
  ui_story_1015_10150302_62_dialog_content = "Apa yang Anda maksudkan?",
  ui_story_1015_10150302_63_dialog_content = "Saya ingin mengaktifkan Tautan Chord untuk memahami prinsip pengoperasiannya.",
  ui_story_1015_10150302_64_dialog_content = "Apakah Anda tahu mengapa saya membawa Anda ke sini?",
  ui_story_1015_10150302_65_dialog_content = "Aktifkan Tautan Chord? Mau pakai siapa?!",
  ui_story_1015_10150302_66_dialog_content = "Saya sudah menyiapkan subjek tes terlebih dahulu, tentu saja.",
  ui_story_1015_10150302_67_dialog_content = "Kau…!",
  ui_story_1015_10150302_68_dialog_content = "TIDAK! Apakah Anda tidak menyentuh Vice!!!",
  ui_story_1015_10150302_69_dialog_content = "Giok.",
  ui_story_1015_10150302_70_dialog_content = "<size=50><anim type=Shake>Mengaum!!!</anim></size>",
  ui_story_1015_10150302_71_dialog_content = "Urgh... Ini sangat... berat...",
  ui_story_1015_10150302_72_dialog_content = "L-Lepaskan Vice! Jangan main-main dengan benda itu jika Anda bahkan belum tahu cara menggunakannya!",
  ui_story_1015_10150302_73_dialog_content = "Inti dari subjek tes ini adalah untuk membantu saya mengklarifikasi dengan tepat bagaimana menggunakannya.",
  ui_story_1015_10150302_74_dialog_content = "Penelitian ilmiah melibatkan menjangkau ke dalam kegelapan, di mana tangan seseorang harus disengat dan digores untuk memastikan bentuk dunia.",
  ui_story_1015_10150302_75_dialog_content = "Jika kita tidak mencoba, ilmu pengetahuan tidak akan pernah maju.",
  ui_story_1015_10150302_76_dialog_content = "Jika menurut Anda ini adalah usaha yang mulia, mengapa Anda tidak mencobanya sendiri?!",
  ui_story_1015_10150302_77_dialog_content = "Saat menggunakan diri Anda sendiri sebagai subjek tes, Anda hanya bisa gagal sekali, tetapi Anda bisa gagal berkali-kali saat menggunakan subjek tes sekali pakai.",
  ui_story_1015_10150302_78_dialog_content = "Penelitian ilmiah bukanlah pertaruhan satu kali. Tentu saja saya membutuhkan kesempatan sebanyak yang diperlukan.",
  ui_story_1015_10150302_79_dialog_content = "<size=45>Kamu... tercela...</size>",
  ui_story_1015_10150302_80_dialog_content = "Merindukan Vice, saya harap Anda siap.",
  ui_story_1015_10150302_81_dialog_content = "Ini akan berjalan seperti pertama kali Anda menggunakan Tautan Chord.",
  ui_story_1015_10150302_82_dialog_content = "Lepaskan aku, kamu!",
  ui_story_1015_10150302_83_dialog_content = "Uji coba Chord Link, ruang uji, dan subjek keduanya siap.",
  ui_story_1015_10150302_84_dialog_content = "Mari kita mulai eksperimennya.",
  ui_story_1015_10150302_85_dialog_content = "Petugas Ulysses, ini bukan cara yang harus kita lakukan.",
  ui_story_1015_10150302_86_dialog_content = "Kami telah meminta penjaga untuk mengintensifkan patroli dan pencarian target mereka, tetapi mereka tetap tidak dapat menemukan penyusup.",
  ui_story_1015_10150302_87_dialog_content = "Personel kami sekarang dalam keadaan panik, dan banyak peneliti terlalu takut untuk kembali ke laboratorium.",
  ui_story_1015_10150302_88_dialog_content = "Apakah Anda berhasil menemukan identitas penyusup?",
  ui_story_1015_10150302_89_dialog_content = "Saya yakin, seperti yang Anda duga sebelumnya, itu adalah Forsakin.",
  ui_story_1015_10150302_90_dialog_content = "Saya tidak tahu bagaimana dia menerobos masuk. Dia tidak hanya berhasil menghindari pencarian kami, dia juga tampaknya mampu melewati semua tindakan pengamanan kami.",
  ui_story_1015_10150302_91_dialog_content = "Juga, beberapa tentara mengklaim telah melihat Caelestite, yang tidak berkomunikasi selama berhari-hari. Mungkinkah dia benar-benar pria Forsakin di dalam?",
  ui_story_1015_10150302_92_dialog_content = "Jika itu Forsakin, dia tidak membutuhkan seseorang di dalam.",
  ui_story_1015_10150302_93_dialog_content = "Apa?",
  ui_story_1015_10150302_94_dialog_content = "Forsakin tahu tempat ini lebih baik dari siapa pun. Dialah yang membangun Institut X.",
  ui_story_1015_10150302_95_dialog_content = "Dia membangunnya? Aku pikir itu kamu...",
  ui_story_1015_10150302_96_dialog_content = "Sebelas tahun yang lalu, Forsakin masih menjadi anggota Illumina, dan merupakan peneliti paling menjanjikan di generasinya.",
  ui_story_1015_10150302_97_dialog_content = "Dia mengirimi saya permintaan — dia ingin diam-diam mengambil alih Undercity yang ditinggalkan tanpa nama.",
  ui_story_1015_10150302_98_dialog_content = "Dia menamakannya Undercity X, pendahulu dari lembaga penelitian ini.",
  ui_story_1015_10150302_99_dialog_content = "Aku tahu.",
  ui_story_1015_10150302_100_dialog_content = "Jadi, ketika Forsakin akhirnya membelot dari Illumina, lembaga penelitian berkembang menjadi seperti sekarang?",
  ui_story_1015_10150302_101_dialog_content = "Bisa dibilang begitu.",
  ui_story_1015_10150302_102_dialog_content = "Dia sangat berbakat, tetapi bakat bisa menjadi hal yang menakutkan.",
  ui_story_1015_10150302_103_dialog_content = "Itu membedakannya dari orang biasa, mendorongnya untuk terus melakukan eksperimen radikal dan berbahaya.",
  ui_story_1015_10150302_104_dialog_content = "Melalui metodenya, Undercity X menguasai bioteknologi tercanggih dari Federasi Illumina.",
  ui_story_1015_10150302_105_dialog_content = "Tetapi pada saat yang sama, bahaya yang ditimbulkan oleh pekerjaannya terus meningkat.",
  ui_story_1015_10150302_106_dialog_content = "Pada akhirnya, baik dia maupun Illumina tidak mampu menanggungnya.",
  ui_story_1015_10150302_107_dialog_content = "Saya ingat pernah mendengar bahwa dia diberhentikan setelah kecelakaan besar terjadi selama salah satu eksperimennya...",
  ui_story_1015_10150302_108_dialog_content = "Ya, api besar menghancurkan Undercity X.",
  ui_story_1015_10150302_109_dialog_content = "Tapi kecelakaan ini hanyalah pemicunya. Itu hanya membuat pejabat tingkat tinggi menyelidiki rahasia Forsakin.",
  ui_story_1015_10150302_110_dialog_content = "Apa yang benar-benar membuatnya tak tertahankan di mata Illumina adalah sifat penelitiannya yang kontroversial dan tak terkendali.",
  ui_story_1015_10150302_111_dialog_content = "Jika sumbernya tidak padam, api hanya akan menyala lebih kuat dan lebih ganas.",
  ui_story_1015_10150302_112_dialog_content = "Memang. Konsekuensinya tidak terbayangkan jika kecelakaan ini terjadi di Kota Gannon.",
  ui_story_1015_10150302_113_dialog_content = "Tetapi jika ini masalahnya... mengapa Undercity X tidak ditinggalkan setelah insiden yang begitu menghancurkan?",
  ui_story_1015_10150302_114_dialog_content = "Masih banyak Undercity lain yang bisa dijadikan lokasi penelitian, bukan?",
  ui_story_1015_10150302_115_dialog_content = "Ah... Nah, inilah mengapa saya mengatakan bakat bisa menjadi hal yang menakutkan.",
  ui_story_1015_10150302_116_dialog_content = "Tidak peduli seberapa tidak etis dan berbahayanya eksperimen tersebut, mereka tidak dapat menaungi pencapaian luar biasa dari penelitiannya.",
  ui_story_1015_10150302_117_dialog_content = "Lagipula, aku sendiri juga sangat mirip dengannya.",
  ui_story_1015_10150302_118_dialog_content = "Aku tidak tahan untuk mengabaikan apa yang ditinggalkannya.",
  ui_story_1015_10150302_119_dialog_content = "Oh, begitu…",
  ui_story_1015_10150302_120_dialog_content = "Setelah kejadian itu, saya membangun kembali Undercity yang rusak, yang menjadi Institut X saat ini.",
  ui_story_1015_10150302_121_dialog_content = "Dengan bantuan instrumen dan pencapaian yang ditinggalkan Forsakin kepada kami, penelitian Illumina di bidang biologi maju pesat.",
  ui_story_1015_10150302_122_dialog_content = "Jadi, sedikit banyak, sepertinya dia telah melakukan sesuatu yang baik untuk Illumina.",
  ui_story_1015_10150302_123_dialog_content = "Semuanya ada harganya, dan sekarang saatnya bagi kita untuk membayar.",
  ui_story_1015_10150302_124_dialog_content = "Meskipun Institut X telah direnovasi total, sifat dan prinsip dasarnya tetap ada.",
  ui_story_1015_10150302_125_dialog_content = "Di mata Forsakin, kami baru saja memutar kembali kotak musiknya dan memberinya tampilan baru.",
  ui_story_1015_10150302_126_dialog_content = "Jika dia ingin memainkan lagunya sendiri, dia bisa meraih dan memetik alang-alang.",
  ui_story_1015_10150401_1_dialog_content = "Jadi... situasi di sini menjadi berbahaya.",
  ui_story_1015_10150401_2_dialog_content = "Meskipun kami memiliki keunggulan dalam hal kekuatan militer, efektivitas tempur kami telah menjadi satu dimensi.",
  ui_story_1015_10150401_3_dialog_content = "Forsakin akrab dengan tata letak institut dan tidak akan pernah memberi kita kesempatan untuk memfokuskan pasukan kita dan mengelilinginya.",
  ui_story_1015_10150401_4_dialog_content = "Dia bisa melakukan hampir semua yang dia inginkan di sini...",
  ui_story_1015_10150401_5_dialog_content = "Itu benar. Para penjaga tidak bisa menyentuhnya.",
  ui_story_1015_10150401_6_dialog_content = "Tidak ada seorang pun di sini yang memiliki kemampuan bertarung individu untuk bersaing dengannya. Tidak peduli berapa banyak penjaga yang kita miliki, mereka praktis tidak berguna.",
  ui_story_1015_10150401_7_dialog_content = "Kita tidak bisa terus seperti ini...",
  ui_story_1015_10150401_8_dialog_content = "Pak, mungkin kita harus mencari bantuan dari Gannon.",
  ui_story_1015_10150401_9_dialog_content = "Jika kita berhasil mengamankan bala bantuan yang memadai, kita pasti akan...",
  ui_story_1015_10150401_10_dialog_content = "Tidak.",
  ui_story_1015_10150401_11_dialog_content = "Kenapa Pak?",
  ui_story_1015_10150401_12_dialog_content = "Ini bukan masalah yang sederhana.",
  ui_story_1015_10150401_13_dialog_content = "Jika mencari bantuan dapat menyelesaikan masalah ini, saya pasti sudah melaporkan situasinya ke Kota Gannon, dan saya pasti tidak membutuhkan Anda untuk menyarankan ini kepada saya.",
  ui_story_1015_10150401_14_dialog_content = "Aku tidak paham...",
  ui_story_1015_10150401_15_dialog_content = "Ini adalah lembaga penelitian rahasia, dan segala sesuatu tentang tempat ini harus dirahasiakan.",
  ui_story_1015_10150401_16_dialog_content = "Memberitahu militer bukanlah pilihan. Jangan lupakan keadaan pemecatan Forsakin.",
  ui_story_1015_10150401_17_dialog_content = "... Ya pak.",
  ui_story_1015_10150401_18_dialog_content = "Saya tidak mempertimbangkan itu, saya hanya merasa bahwa masalah yang ada lebih penting.",
  ui_story_1015_10150401_19_dialog_content = "Forsakin adalah mantan peneliti, dia menyusup ke institut untuk melakukan eksperimennya.",
  ui_story_1015_10150401_20_dialog_content = "Pada akhirnya, saat ini hanyalah konflik antar ilmuwan.",
  ui_story_1015_10150401_21_dialog_content = "Begitu kami melibatkan militer, masalah ini akan mengambil bentuk lain.",
  ui_story_1015_10150401_22_dialog_content = "Ya, aku mengerti.",
  ui_story_1015_10150401_23_dialog_content = "Apakah Anda benar-benar mengerti?",
  ui_story_1015_10150401_24_dialog_content = "...",
  ui_story_1015_10150401_25_dialog_content = "Heh, lagipula kau hanya seorang prajurit, melaksanakan perintah adalah semua yang diperlukan darimu. Tidak perlu bagi Anda untuk memahami pikiran saya sepenuhnya.",
  ui_story_1015_10150401_26_dialog_content = "Pikirkan semua ini sebagai percobaan.",
  ui_story_1015_10150401_27_dialog_content = "Menurut peraturan, isi eksperimen harus dirahasiakan kepada publik. Memahami?",
  ui_story_1015_10150401_28_dialog_content = "Siap, Pak!",
  ui_story_1015_10150401_29_dialog_content = "Baiklah, sekarang mari kita bicara tentang sesuatu yang benar-benar dapat Anda pahami.",
  ui_story_1015_10150401_30_dialog_content = "Memilih untuk tidak mencari bala bantuan dari Gannon tidak berarti bahwa saya hanya akan duduk di sini menunggu malapetaka yang akan segera terjadi.",
  ui_story_1015_10150401_31_dialog_content = "Saya juga punya cara sendiri menghadapi Forsakin.",
  ui_story_1015_10150401_32_dialog_content = "Anda punya rencana? Maksud kamu...",
  ui_story_1015_10150401_33_dialog_content = "<color=#e8d9bb>Tok, tok, tok…</color>",
  ui_story_1015_10150401_34_dialog_content = "Masuk.",
  ui_story_1015_10150401_35_dialog_content = "Perwira Intelijen Illumina, Kolonel Yingel, melaporkan, Pak!",
  ui_story_1015_10150401_36_dialog_content = "<color=#e8d9bb>Bip — Bip —</color>",
  ui_story_1015_10150401_37_dialog_content = "Jadi, begitu cara kerjanya...",
  ui_story_1015_10150401_38_dialog_content = "Ya, hanya mengubah struktur jasmani saja tidak ada gunanya.",
  ui_story_1015_10150401_39_dialog_content = "Ini bukanlah tempat jejak Lumina berada. Tersembunyi lebih dalam...",
  ui_story_1015_10150401_40_dialog_content = "(Vice! Bagaimana perasaanmu saat ini?)",
  ui_story_1015_10150401_41_dialog_content = "(Apakah kamu terluka?)",
  ui_story_1015_10150401_42_dialog_content = "(Saya baik-baik saja, saya hanya merasa ada kekuatan yang mengatur ulang Lumina di dalam diri saya.)",
  ui_story_1015_10150401_43_dialog_content = "(Benarkah? Kurasa itu sudah cukup untuk saat ini. Kuharap tidak ada yang salah...)",
  ui_story_1015_10150401_44_dialog_content = "(Jangan terlalu khawatir. Lagi pula, ini bukan pertemuan pertama saya dengan Chord Link.)",
  ui_story_1015_10150401_45_dialog_content = "(Tapi…)",
  ui_story_1015_10150401_46_dialog_content = "(Hei, dengar—tidakkah menurutmu ini bisa menjadi peluang?)",
  ui_story_1015_10150401_47_dialog_content = "(Sebuah kesempatan?)",
  ui_story_1015_10150401_48_dialog_content = "(Chord Link dapat meningkatkan kekuatan Aurorian, bukan?)",
  ui_story_1015_10150401_49_dialog_content = "(Mungkin saya bisa menggunakan peningkatan ini untuk melepaskan diri dari tali ini.)",
  ui_story_1015_10150401_50_dialog_content = "(Kamu akan mencoba melepaskan diri dari tali itu! Bisakah kamu benar-benar melakukannya?)",
  ui_story_1015_10150401_51_dialog_content = "(Seharusnya tidak mustahil. Aku mungkin bisa melakukannya bahkan sekarang.)",
  ui_story_1015_10150401_52_dialog_content = "(Namun, masalah sebenarnya adalah bagaimana kita akan menangani Forsakin dan Jade setelah aku membebaskan diri.)",
  ui_story_1015_10150401_53_dialog_content = "(Saya masih membutuhkan lebih banyak kekuatan. Saya hanya berharap efek peningkatan Chord Link berhasil.)",
  ui_story_1015_10150401_54_dialog_content = "(Hmm... Perhatian Forsakin sepenuhnya terfokus pada data. Ini memang kesempatan bagus untuk melakukan serangan balik.)",
  ui_story_1015_10150401_55_dialog_content = "(Benar! Kita harus memberinya gambaran seberapa efektif penelitiannya!)",
  ui_story_1015_10150401_56_dialog_content = "(Kita harus bekerja sama untuk melakukan ini. Kita hanya punya satu kesempatan.)",
  ui_story_1015_10150401_57_dialog_content = "(Akan lebih baik jika kita bisa menaklukkan Forsakin sebelum dia bisa bereaksi. Menyeretnya ke dalam pertarungan yang berkepanjangan tidak akan baik untuk kita.)",
  ui_story_1015_10150401_58_dialog_content = "(Dimengerti. Aku akan mencari kesempatan untuk mengalahkannya dalam satu pukulan.)",
  ui_story_1015_10150401_59_dialog_content = "(Baiklah! Saya mengandalkan Anda!)",
  ui_story_1015_10150401_60_dialog_content = "Forsakin, berapa lama lagi percobaan ini akan berlangsung?",
  ui_story_1015_10150401_61_dialog_content = "Ekor Jade sangat berat, aku tidak bisa bernapas karena beratnya.",
  ui_story_1015_10150401_62_dialog_content = "Segera. Tetap diam.",
  ui_story_1015_10150401_63_dialog_content = "Berapa lama lagi? Tidak bisakah Anda memberi saya waktu yang tepat?",
  ui_story_1015_10150401_64_dialog_content = "Kami berada di tahap akhir.",
  ui_story_1015_10150401_65_dialog_content = "<color=#e8d9bb>Bip—</color>",
  ui_story_1015_10150401_66_dialog_content = "(PlayerName! Saya bisa merasakan aliran Lumina mulai berakselerasi!)",
  ui_story_1015_10150401_67_dialog_content = "(Bersiaplah. Kita dapat bergerak segera setelah penyempurnaan selesai!)",
  ui_story_1015_10150401_68_dialog_content = "(Baiklah!)",
  ui_story_1015_10150401_69_dialog_content = "(Saat Anda melepaskan diri, serang Forsakin terlebih dahulu. Jade secara naluriah akan mencoba membantunya, dan kemudian Anda...)",
  ui_story_1015_10150401_70_dialog_content = "Omong-omong, Caelestite.",
  ui_story_1015_10150401_71_dialog_content = "Hah? Apakah kamu bicara dengan ku?",
  ui_story_1015_10150401_72_dialog_content = "Mengapa Anda hanya peduli tentang berapa lama percobaan akan berlangsung, tetapi tidak apakah itu berhasil diselesaikan?",
  ui_story_1015_10150401_73_dialog_content = "Aku…",
  ui_story_1015_10150401_74_dialog_content = "(Oh tidak... Apakah saya memberikan permainan itu?)",
  ui_story_1015_10150401_75_dialog_content = "(Vice, berapa lama sampai penyempurnaan selesai...?)",
  ui_story_1015_10150401_76_dialog_content = "Jangan khawatir, tubuh Vice tidak mengalami perubahan apapun.",
  ui_story_1015_10150401_77_dialog_content = "Tidak ada cedera yang terjadi, juga tidak ada peningkatan yang diharapkan dilakukan.",
  ui_story_1015_10150401_78_dialog_content = "Eksperimen sudah berakhir.",
  ui_story_1015_10150401_79_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_1015_10150401_80_dialog_content = "(Apa yang terjadi?! Peningkatan berhenti?!)",
  ui_story_1015_10150401_81_dialog_content = "A-Apa yang kamu lakukan?",
  ui_story_1015_10150401_82_dialog_content = "Saya baru saja mematikan Chord Link.",
  ui_story_1015_10150401_83_dialog_content = "Mencapai langkah ini dalam percobaan sudah cukup untuk hari ini. Saya tidak mengharapkan perubahan yang tidak perlu terjadi pada subjek tes.",
  ui_story_1015_10150401_84_dialog_content = "Kecuali kalian berdua mengantisipasi sesuatu?",
  ui_story_1015_10150401_85_dialog_content = "(Apa yang bisa kita lakukan, Vice? Dia sepertinya tahu apa yang kita rencanakan...)",
  ui_story_1015_10150401_86_dialog_content = "(Sudahlah, ini satu-satunya kesempatan yang kita miliki!)",
  ui_story_1015_10150401_87_dialog_content = "(Saya akan melepaskan diri dari tali ini. Bersiaplah untuk beraksi!)",
  ui_story_1015_10150401_88_dialog_content = "Tidak ada yang perlu dikatakan? Tampaknya saya memenuhi imajinasi Anda dengan harapan yang agak tidak realistis.",
  ui_story_1015_10150401_89_dialog_content = "Hmph! Tunggu saja sampai saya menjatuhkan Anda, maka Anda akan tahu apa yang tidak realistis.",
  ui_story_1015_10150401_90_dialog_content = "<color=#e8d9bb>Patah-</color>",
  ui_story_1015_10150401_91_dialog_content = "Jadi, Anda benar-benar berhasil melepaskan diri dari tali dengan bantuan Chord Link.",
  ui_story_1015_10150401_92_dialog_content = "Tapi tidak apa-apa. Kejadian seperti itu telah diperhitungkan dalam penilaian risiko dan rencana darurat saya.",
  ui_story_1015_10150401_93_dialog_content = "Aku menangkapmu sekali, aku bisa menangkapmu lagi.",
  ui_story_1015_10150401_94_dialog_content = "Vice! Dia memanggil Eclipsites yang tersembunyi!",
  ui_story_1015_10150401_95_dialog_content = "Sekarang!",
  ui_story_1015_10150502_1_dialog_content = "Terkesiap... Terkesiap...",
  ui_story_1015_10150502_2_dialog_content = "Ini tidak bekerja...?",
  ui_story_1015_10150502_3_dialog_content = "Menggunakan peningkatan Chord Link untuk melepaskan diri dari tali Anda... Apakah Anda benar-benar yakin saya tidak mengantisipasi ini?",
  ui_story_1015_10150502_4_dialog_content = "Jangan berpikir ini adalah kesempatan. Aku sudah mempersiapkan segalanya.",
  ui_story_1015_10150502_5_dialog_content = "Dan Anda masih punya waktu untuk mengobrol selama pertempuran.",
  ui_story_1015_10150502_6_dialog_content = "Ini bukan pertempuran. Pertempuran sudah berakhir.",
  ui_story_1015_10150502_7_dialog_content = "Saya tidak punya waktu untuk menikmati lelucon ini.",
  ui_story_1015_10150502_8_dialog_content = "Apa yang membuat Anda berpikir Anda memiliki keputusan akhir dalam hal ini ?!",
  ui_story_1015_10150502_9_dialog_content = "Nah, apakah dia mungkin memiliki keputusan akhir?",
  ui_story_1015_10150502_10_dialog_content = "<size=45>Vice! Dibelakangmu!</size>",
  ui_story_1015_10150502_11_dialog_content = "Apa...?",
  ui_story_1015_10150502_12_dialog_content = "<size=45>Ahhhh—!</size>",
  ui_story_1015_10150502_13_dialog_content = "<size=45>Vice!!!</size>",
  ui_story_1015_10150502_14_dialog_content = "Helios... Apa yang orang ini lakukan disini?!",
  ui_story_1015_10150502_15_dialog_content = "Saat ini, menolak adalah keputusan paling bodoh yang bisa Anda buat.",
  ui_story_1015_10150502_16_dialog_content = "Peluang Anda untuk sukses adalah nol. Dan campur tangan Anda hanya akan menunda kemajuan percobaan.",
  ui_story_1015_10150502_17_dialog_content = "Saya tidak suka jika orang mengganggu percobaan saya.",
  ui_story_1015_10150502_18_dialog_content = "A-Apa yang kamu lakukan?",
  ui_story_1015_10150502_19_dialog_content = "Eksperimen hari ini telah selesai. Kami akan pergi dari sini setelah saya selesai mengatur data.",
  ui_story_1015_10150502_20_dialog_content = "Vice akan pergi dengan Helios, dan kamu, bersamaku, Caelestite. Mulai sekarang, kalian berdua akan <color=#FFB400>terpisah</color>.",
  ui_story_1015_10150502_21_dialog_content = "Terpisah?!",
  ui_story_1015_10150502_22_dialog_content = "Dari kejadian barusan, saya dapat melihat bahwa kalian berdua tetap bersama akan membentuk faktor yang tidak stabil.",
  ui_story_1015_10150502_23_dialog_content = "Karena ini masalahnya, Anda harus menjauh satu sama lain di masa mendatang.",
  ui_story_1015_10150502_24_dialog_content = "Dengarkan baik-baik, Yingel. Inilah yang terjadi.",
  ui_story_1015_10150502_25_dialog_content = "Forsakin telah menyusup ke lembaga penelitian ini dan menggunakan peralatan kami.",
  ui_story_1015_10150502_26_dialog_content = "Selain itu, Letnan Vice, yang mengunjungi lembaga penelitian pada saat itu, dan Caelestite, tidak dapat dihubungi selama beberapa hari.",
  ui_story_1015_10150502_27_dialog_content = "Berdasarkan laporan saksi mata para prajurit, saya berspekulasi bahwa Forsakin telah menculik mereka.",
  ui_story_1015_10150502_28_dialog_content = "PlayerName Dan Vice...",
  ui_story_1015_10150502_29_dialog_content = "Profesor Ulysses, apa yang Anda ingin saya lakukan?",
  ui_story_1015_10150502_30_dialog_content = "Selamatkan para sandera dan tangkap Forsakin.",
  ui_story_1015_10150502_31_dialog_content = "<size=45>!!!</size>",
  ui_story_1015_10150502_32_dialog_content = "(Apakah dia benar-benar mempercayakan tugas yang begitu sulit kepada seorang kolonel?)",
  ui_story_1015_10150502_33_dialog_content = "... Saya menerima misi.",
  ui_story_1015_10150502_34_dialog_content = "Tapi, Profesor, berdasarkan situasi saat ini, kemungkinan saya menyelesaikan misi ini sangat rendah.",
  ui_story_1015_10150502_35_dialog_content = "Forsakin akrab dengan tata letak situs, dia sangat kuat dan telah menyandera.",
  ui_story_1015_10150502_36_dialog_content = "Jika saya mencoba ini sendirian, saya akan berada pada posisi yang sangat tidak menguntungkan.",
  ui_story_1015_10150502_37_dialog_content = "Jika saya bisa mendaftar untuk menggunakan <color=#FFB400>senjata</color>...",
  ui_story_1015_10150502_38_dialog_content = "Anda inginkan Axelia untuk membantu Anda, benar?",
  ui_story_1015_10150502_39_dialog_content = "... Iya.",
  ui_story_1015_10150502_40_dialog_content = "Anda seharusnya tidak terlalu mengandalkan kekuatannya.",
  ui_story_1015_10150502_41_dialog_content = "Kalian berdua adalah peserta dari <color=#FFB400>Program Fosfor</color>, tetapi spesialisasi Anda berbeda.",
  ui_story_1015_10150502_42_dialog_content = "Misi ini bukanlah misi yang bisa diselesaikan dengan kekuatan belaka. Saya ingin Anda memanfaatkan kemampuan unik Anda.",
  ui_story_1015_10150502_43_dialog_content = "... Saya mengerti, Profesor.",
  ui_story_1015_10150502_44_dialog_content = "Lebih-lebih lagi, Axelia perlu mempersiapkan misi penting lainnya. Saya akan memberi tahu Anda lebih banyak tentang itu di kemudian hari.",
  ui_story_1015_10150502_45_dialog_content = "Tentunya saat berhadapan dengan musuh seperti itu, Anda perlu mempersiapkan tangan dengan baik.",
  ui_story_1015_10150502_46_dialog_content = "Untungnya, saya punya dua kartu truf untuk Anda.",
  ui_story_1015_10150502_47_dialog_content = "Tolong jelaskan.",
  ui_story_1015_10150502_48_dialog_content = "Yang pertama adalah penguatan.",
  ui_story_1015_10150502_49_dialog_content = "Saya telah memilih asisten yang andal untuk Anda. Dia sedang dalam perjalanan ke sini sekarang.",
  ui_story_1015_10150502_50_dialog_content = "Dia Anatoli, salah satu perwira intelijen terpercaya Komite.",
  ui_story_1015_10150502_51_dialog_content = "Aku tahu tentang dia! Dia memang akan sangat membantu!",
  ui_story_1015_10150502_52_dialog_content = "Adapun kartu truf lainnya ...",
  ui_story_1015_10150502_53_dialog_content = "Saya ingin Anda memegangnya sampai akhir.",
  ui_story_1015_10150601_1_dialog_content = "<color=#e8d9bb>Senja, Benteng Lumo</color>",
  ui_story_1015_10150601_2_dialog_content = "...",
  ui_story_1015_10150601_3_dialog_content = "<color=#e8d9bb>Ketuk, ketuk—</color>",
  ui_story_1015_10150601_4_dialog_content = "Masuk!",
  ui_story_1015_10150601_5_dialog_content = "... Joselyne.",
  ui_story_1015_10150601_6_dialog_content = "Senja telah tiba, dan doa akan segera dimulai... Apakah Anda sedang menunggu seseorang?",
  ui_story_1015_10150601_7_dialog_content = "Sepertinya aku datang pada waktu yang buruk.",
  ui_story_1015_10150601_8_dialog_content = "Saya hanya menunggu laporan intelijen. Ini adalah masalah yang paling mendesak untuk Ironthorn saat ini.",
  ui_story_1015_10150601_9_dialog_content = "Situasi di garis depan tidak terlihat optimis, dan semakin banyak pemukiman di sekitarnya yang diserang oleh Eclipsites.",
  ui_story_1015_10150601_10_dialog_content = "Meskipun Undercity memiliki ruang yang lebih dari cukup untuk menyerap penghuni permukiman ini...",
  ui_story_1015_10150601_11_dialog_content = "Jika terus seperti ini, suatu hari kita akan kehilangan kendali atas wilayah ini.",
  ui_story_1015_10150601_12_dialog_content = "Ya. Aku tidak ingin melihat hal seperti itu terjadi.",
  ui_story_1015_10150601_13_dialog_content = "Eclipsites terus berkumpul, namun mereka belum meluncurkan serangan berskala besar. Lumopolis dan Federasi Illumina juga belum mengirimkan instruksi untuk menyerang.",
  ui_story_1015_10150601_14_dialog_content = "Para prajurit sudah kelelahan karena kurangnya tindakan. Siaga diperpanjang semacam ini sebenarnya merugikan mereka.",
  ui_story_1015_10150601_15_dialog_content = "Saya berharap doa hari ini setidaknya dapat sedikit menenangkan kecemasan prajurit Anda.",
  ui_story_1015_10150601_16_dialog_content = "Terima kasih, Joselyn.",
  ui_story_1015_10150601_17_dialog_content = "<color=#e8d9bb>Ketuk, ketuk—</color>",
  ui_story_1015_10150601_18_dialog_content = "Terkesiap... Terkesiap...",
  ui_story_1015_10150601_19_dialog_content = "Kapten Leo... Kami telah menerima kabar dari Illumina!",
  ui_story_1015_10150601_20_dialog_content = "Illumina telah mengirimkan sinyal, memerintahkan semua pasukan yang ditempatkan untuk segera bersiap!",
  ui_story_1015_10150601_21_dialog_content = "Katakan padaku apa yang terjadi! Dengan cepat!",
  ui_story_1015_10150601_22_dialog_content = "It-It's persiapan untuk <color=#FFB400>Latihan Militer Bersama</color>.",
  ui_story_1015_10150601_23_dialog_content = "?!?",
  ui_story_1015_10150601_24_dialog_content = "<color=#e8d9bb>Senja, Kota Bawah yang Diatur oleh Kota</color>",
  ui_story_1015_10150601_25_dialog_content = "Apakah ini undangan rutin ke Twilight?",
  ui_story_1015_10150601_26_dialog_content = "Ya pak. Meskipun tanggal latihan militer sepenuhnya tergantung pada atasan, ini masih dianggap sebagai tradisi.",
  ui_story_1015_10150601_27_dialog_content = "Jadi begitu. Ini bukan kabar baik bagi para prajurit.",
  ui_story_1015_10150601_28_dialog_content = "Memang. Kenapa sekarang, sepanjang masa?!",
  ui_story_1015_10150601_29_dialog_content = "Ya. Genderang perang telah membangkitkan semangat mereka, dan sekarang mereka akan tenggelam oleh kemeriahan latihan militer. Tidak peduli seberapa besar latihan militer itu, itu tidak bisa dibandingkan dengan serunya pertempuran.",
  ui_story_1015_10150601_30_dialog_content = "Apa isi surat undangan itu? Berapa banyak orang yang perlu kita kirim?",
  ui_story_1015_10150601_31_dialog_content = "Tiga orang. Seorang prajurit Illumina, seorang Kesatria Lumo, dan seorang anggota pendeta. Denganmu, itu membuat...",
  ui_story_1015_10150601_32_dialog_content = "<color=#e8d9bb>Senja, Benteng Lumo</color>",
  ui_story_1015_10150601_33_dialog_content = "Jadi begitu. Meskipun ini adalah area yang diatur bersama, jelas bahwa Anda tidak senang dengan urutan Illumina ini.",
  ui_story_1015_10150601_34_dialog_content = "Tentu saja! Semua tentara Gannon itu mengikuti formalitas yang ketat dan meminta orang lain untuk melakukan hal yang sama ke mana pun mereka pergi.",
  ui_story_1015_10150601_35_dialog_content = "Perang di garis depan sudah dekat... Mengapa kita perlu bekerja sama hanya untuk memuaskan kepentingan mereka?!",
  ui_story_1015_10150601_36_dialog_content = "Kedatangan undangan ini memang menjadi kejutan yang menyenangkan.",
  ui_story_1015_10150601_37_dialog_content = "Kejutan yang menyenangkan? Leo, apakah Anda sudah mengambil keputusan?",
  ui_story_1015_10150601_38_dialog_content = "Ya. Saya pergi.",
  ui_story_1015_10150601_39_dialog_content = "Kapten?!",
  ui_story_1015_10150601_40_dialog_content = "Jika latihan itu adalah tahap dimana kekuatan dunia berkumpul untuk dilihat oleh seluruh benua...",
  ui_story_1015_10150601_41_dialog_content = "Berita kerusuhan di perbatasan akan diumumkan ke seluruh benua.",
  ui_story_1015_10150601_42_dialog_content = "Kapten Leo...",
  ui_story_1015_10150601_43_dialog_content = "Saya akan membuat beberapa persiapan dan kemudian bertemu dengan Joseph dan Zhao.",
  ui_story_1015_10150601_44_dialog_content = "Adapun ketika Joseph dan saya pergi, saya akan meninggalkan semuanya di tangan Anda, Joselyne.",
  ui_story_1015_10150601_45_dialog_content = "Hm, saya mengerti.",
  ui_story_1015_10150601_46_dialog_content = "Bertarung berdampingan dengan Ironthorn Knights, membawa energi yang menenangkan bagi orang-orang...",
  ui_story_1015_10150601_47_dialog_content = "Setelah Anda kembali, saya berharap Anda menunjukkan penghargaan Anda sepenuhnya.",
  ui_story_1015_10150601_48_dialog_content = "Hah, tentu saja.",
  ui_story_1015_10150601_49_dialog_content = "<color=#e8d9bb>Federasi Illumina, Di suatu tempat di Kota Gannon</color>",
  ui_story_1015_10150601_50_dialog_content = "Saya dengan tegas menentangnya.",
  ui_story_1015_10150601_51_dialog_content = "Saya punya hak untuk menolak, bukan?",
  ui_story_1015_10150601_52_dialog_content = "Ya, Marsekal Agung, menurut peraturan Dewan Sains, Marsekal Agung memiliki hak untuk memberikan suara atas pendapat Dewan.",
  ui_story_1015_10150601_53_dialog_content = "Bisakah Anda menyarankan mereka untuk mengadakan pemungutan suara sesegera mungkin?",
  ui_story_1015_10150601_54_dialog_content = "Begini... Marsekal Agung, keputusan untuk mengadakan Latihan Militer Gabungan adalah keputusan yang dibuat oleh Dewan setelah mempertimbangkan pro dan kontra dengan cermat.",
  ui_story_1015_10150601_55_dialog_content = "Bahkan jika kau menentangnya, para anggota Dewan tidak akan menyerah begitu saja...",
  ui_story_1015_10150601_56_dialog_content = "Berbicara denganmu benar-benar melelahkan. Katakan saja pada Ulysses untuk datang dan menemuiku.",
  ui_story_1015_10150601_57_dialog_content = "Maaf, tapi Profesor Ulysses mengatakan bahwa dia tidak akan menemui Anda jika Anda datang ke sini mengenai masalah ini.",
  ui_story_1015_10150601_58_dialog_content = "Persetan dengan ini.",
  ui_story_1015_10150601_59_dialog_content = "Pertama, saya tidak pernah tertarik untuk terlibat dalam festival showboating yang konyol ini, Anda semua tampak begitu bersikeras untuk membuat kami semua tunduk.",
  ui_story_1015_10150601_60_dialog_content = "Demikian pula, saya tidak ingin penempatan strategis saya terganggu oleh faktor-faktor yang berlebihan.",
  ui_story_1015_10150601_61_dialog_content = "Reruntuhan Aurora membutuhkan dukungan militer Illumina, tetapi sebaliknya, Anda merampas pasukan dan personel mereka dengan latihan militer ini!",
  ui_story_1015_10150601_62_dialog_content = "Ini benar-benar tidak masuk akal!",
  ui_story_1015_10150601_63_dialog_content = "Maafkan aku, Marsekal Agung, aku...",
  ui_story_1015_10150601_64_dialog_content = "Mengapa Anda mengganggu prajurit yang malang ini?",
  ui_story_1015_10150601_65_dialog_content = "Jika Ulysses tua menolak untuk keluar, Anda sebaiknya berbicara dengan saya.",
  ui_story_1015_10150601_66_dialog_content = "Reinhardt, Anda tampak bingung. Saya sarankan Anda sedikit tenang. Bagaimana kalau kita bermain Joker?",
  ui_story_1015_10150601_67_dialog_content = "Wanita <color=#FFB400>Topeng Besi</color>...",
  ui_story_1015_10150601_68_dialog_content = "Itu tidak lucu, <color=#FFB400>Belisari</color>. Aku bahkan kurang tertarik bermain Joker denganmu sekarang.",
  ui_story_1015_10150601_69_dialog_content = "Saya cukup terkejut bahwa Anda benar-benar menunjukkan wajah Anda di sini.",
  ui_story_1015_10150601_70_dialog_content = "Saya tidak bercanda. Ada batas waktu dan kesabaran yang ingin saya perpanjang.",
  ui_story_1015_10150601_71_dialog_content = "Pilih kartu dan ucapkan bagian Anda dalam kerangka waktu. Bisakah Anda melakukan itu?",
  ui_story_1015_10150601_72_dialog_content = "...",
  ui_story_1015_10150601_73_dialog_content = "Kiri.",
  ui_story_1015_10150601_74_dialog_content = "Sudut pandang saya sederhana. Saya tidak mendukung strategi menghindari realitas perang ini.",
  ui_story_1015_10150601_75_dialog_content = "Tangguhkan Latihan Militer Gabungan dan utamakan mendukung pasukan yang ditempatkan di Twilight!",
  ui_story_1015_10150601_76_dialog_content = "Oh, maaf—Anda menggambar Joker. Kamu kalah.",
  ui_story_1015_10150601_77_dialog_content = "Membuat pilihan tanpa observasi sebelumnya tampaknya menjadi ciri umum di antara Grand Marshals baik dulu maupun sekarang.",
  ui_story_1015_10150601_78_dialog_content = "Reinhardt, perang bukanlah permainan di mana seseorang diperbolehkan untuk melakukan pemborosan yang sembrono. Ini pada dasarnya adalah bisnis.",
  ui_story_1015_10150601_79_dialog_content = "Menang atau kalah tidak relevan. Yang penting adalah apa yang Anda kehilangan dan apa yang Anda peroleh.",
  ui_story_1015_10150601_80_dialog_content = "Anda kalah, jadi waktu yang bisa saya curahkan untuk Anda berakhir di sini.",
  ui_story_1015_10150601_81_dialog_content = "Jika Anda tidak dapat memahami konsep ini, Panitia akan mencari orang lain yang bisa.",
  ui_story_1015_10150601_82_dialog_content = "...",
  ui_story_1015_10150601_83_dialog_content = "<color=#e8d9bb>*menggiling gigi*</color>",
  ui_story_1015_10150601_84_dialog_content = "<color=#e8d9bb>Taman Lumopolis</color>",
  ui_story_1015_10150601_85_dialog_content = "Seperti yang saya duga, Latihan Militer Gabungan Illumina juga memanggil orang-orang dari Dawn Akademi.",
  ui_story_1015_10150601_86_dialog_content = "Hmph! Tentu saja, kami Empat Malaikat tidak keberatan. Mengapa tidak memberikan lebih banyak kesempatan kepada pendatang baru untuk membuktikan diri?",
  ui_story_1015_10150601_87_dialog_content = "Yang mulia Raphael... Jelas, Anda sendiri masih anak-anak!",
  ui_story_1015_10150601_88_dialog_content = "Erm, pokoknya, sejak Kapten Carleen bertanggung jawab, saya tidak perlu tampil.",
  ui_story_1015_10150601_89_dialog_content = "Raih kesempatan ini, Kapten! Ini adalah kesempatan besar untuk menyelesaikan masa percobaan untuk pemulihan Anda dalam satu gerakan!",
  ui_story_1015_10150601_90_dialog_content = "Selain Anda, siapa anak lain yang disebutkan dalam surat undangan?",
  ui_story_1015_10150601_91_dialog_content = "Agak aneh caranya Dawn Akademi menerima empat undangan kali ini.",
  ui_story_1015_10150601_92_dialog_content = "Selain saya, ada satu untuk Chloe, Uriah... Dan Beretta.",
  ui_story_1015_10150601_93_dialog_content = "Tapi sejujurnya, saya tidak terlalu tertarik dengan Latihan Militer Gabungan ini.",
  ui_story_1015_10150601_94_dialog_content = "Dalam latihan militer terakhir, saya memimpin tim saya menuju kemenangan.",
  ui_story_1015_10150601_95_dialog_content = "Dan saya tidak perlu menggunakan kehormatan yang tidak berarti ini untuk membeli kembali posisi resmi saya.",
  ui_story_1015_10150601_96_dialog_content = "Ha! Aku tahu kau akan mengatakan sesuatu seperti itu...",
  ui_story_1015_10150601_97_dialog_content = "Jadi... Beretta, apakah kamu akan baik-baik saja? Apakah Anda memiliki masalah bekerja dengan Chloe Dan Uriah?",
  ui_story_1015_10150601_98_dialog_content = "Apa?!",
  ui_story_1015_10150601_99_dialog_content = "Saya harap Anda dapat mengambil alih dan memimpin Tim Beretta kemenangan untuk Lumopolis.",
  ui_story_1015_10150601_100_dialog_content = "Ini bukan pertama kalinya Anda meninggalkan Lumopolis untuk melakukan tugas eksternal. Saya pikir Anda harus bisa mengatasinya.",
  ui_story_1015_10150601_101_dialog_content = "Tentu saja! Saya akan menghargai kesempatan ini!",
  ui_story_1015_10150601_102_dialog_content = "Hehe, Chloe Dan Uriah akan menemukan diri mereka ditempatkan di tangan Beretta kecil.",
  ui_story_1015_10150601_103_dialog_content = "Pastikan Anda melindungi mereka dengan baik!",
  ui_story_1015_10150601_104_dialog_content = "Baiklah!",
  ui_story_1015_10150601_105_dialog_content = "Namun... satu-satunya hal yang saya agak tidak yakin adalah perjalanan ke Latihan Militer Gabungan.",
  ui_story_1015_10150601_106_dialog_content = "Saya pernah mendengar bahwa Kota Bawah Illumina seperti labirin, dan saya belum pernah ke sana sebelumnya...",
  ui_story_1015_10150601_107_dialog_content = "Oh, Anda tidak perlu khawatir tentang itu.",
  ui_story_1015_10150601_108_dialog_content = "Meskipun saya tidak akan memimpin tim Anda, saya masih berencana pergi ke Kota Gannon bersamamu.",
  ui_story_1015_10150601_109_dialog_content = "Ah, tapi kenapa?",
  ui_story_1015_10150601_110_dialog_content = "Yah... mereka berdua di sana membuatku khawatir...",
  ui_story_1015_10150701_1_dialog_content = "<color=#e8d9bb>Federasi Illumina, Kota Bawah X</color>",
  ui_story_1015_10150701_2_dialog_content = "Petugas Intelijen Federasi Illumina Anatoli, melapor untuk bertugas. Atas perintah Komite, saya di sini untuk membantu Anda, Kolonel Yingel.",
  ui_story_1015_10150701_3_dialog_content = "Anda juga seorang perwira intelijen?",
  ui_story_1015_10150701_4_dialog_content = "Oh... aku tahu kamu. Anda adalah wakil yang menemani Grand Marshal ke Eraveil beberapa waktu lalu untuk melawan Eclipse.",
  ui_story_1015_10150701_5_dialog_content = "Ya, Kolonel Yingel, informasi Anda memang sangat akurat. Saya sudah lama menantikan kesempatan untuk bekerja sama dengan Anda.",
  ui_story_1015_10150701_6_dialog_content = "Sanjungan yang cukup. Mari bersiap untuk bertindak secepat mungkin.",
  ui_story_1015_10150701_7_dialog_content = "Apa yang sedang Anda catat?",
  ui_story_1015_10150701_8_dialog_content = "Oh, ini buku catatanku. Saya baru saja menggambar sketsa Anda dengan catatan— \"seorang kolonel dengan kepribadian langsung.\"",
  ui_story_1015_10150701_9_dialog_content = "Anda—Nah, jika Anda biasanya beroperasi seperti ini, saya tidak akan ikut campur.",
  ui_story_1015_10150701_10_dialog_content = "Misi Anda kali ini adalah bekerja dengan saya untuk menyelamatkan para sandera dan menangkap Forsakin.",
  ui_story_1015_10150701_11_dialog_content = "Maaf mengganggu, Kolonel Yingel. Forsakin ada... di Undercity ini? Dan siapa sanderanya?",
  ui_story_1015_10150701_12_dialog_content = "Ahem... Biarkan saya memberi tahu Anda tentang situasi saat ini.",
  ui_story_1015_10150701_13_dialog_content = "Forsakin, yang pernah diinginkan Illumina, telah mengambil Letnan Vice Dan PlayerName.",
  ui_story_1015_10150701_14_dialog_content = "Dia juga mencoba menyusup ke laboratorium penelitian untuk melakukan eksperimennya.",
  ui_story_1015_10150701_15_dialog_content = "Saya yakin tindakannya pasti terkait dengan apa yang terjadi selama konflik di Eraveil.",
  ui_story_1015_10150701_16_dialog_content = "Dia tertarik dengan perubahan Letnan Vice dibawa oleh teknologi Caelestite.",
  ui_story_1015_10150701_17_dialog_content = "Kalau begitu, mereka berdua berada dalam situasi yang sangat berbahaya!",
  ui_story_1015_10150701_18_dialog_content = "Jaringan intelijen Illumina rumit dan kompleks. Dengan Forsakin menculik dua tokoh terkemuka, tidak mungkin kejadian seperti itu luput dari perhatian.",
  ui_story_1015_10150701_19_dialog_content = "Yang mengkhawatirkan adalah Letnan itu Vice terpisah dari PlayerName.",
  ui_story_1015_10150701_20_dialog_content = "Jadi, operasi kami akan dibagi menjadi dua tahap.",
  ui_story_1015_10150701_21_dialog_content = "Tahap satu: temukan Letnan Vice sesegera mungkin, dan pastikan untuk menemuinya sebelum Forsakin.",
  ui_story_1015_10150701_22_dialog_content = "Tahap dua: akhiri rencana Forsakin. Dia mungkin punya PlayerName, tapi dia tidak akan berani melakukan tindakan sembrono apa pun terhadapnya.",
  ui_story_1015_10150701_23_dialog_content = "Jika kami mendapat kesempatan yang cocok, akan lebih baik jika kami menangkap Forsakin dalam satu gerakan.",
  ui_story_1015_10150701_24_dialog_content = "Ya Bu! Saya mengerti...",
  ui_story_1015_10150701_25_dialog_content = "Kamu sedang apa sekarang",
  ui_story_1015_10150701_26_dialog_content = "Saya menggambar peta berdasarkan catatan masa lalu saya tentang orang-orang yang terlibat dan tindakan orang-orang ini untuk memprediksi kemungkinan tindakan mereka selanjutnya.",
  ui_story_1015_10150701_27_dialog_content = "... Kamu benar-benar sesuatu.",
  ui_story_1015_10150701_28_dialog_content = "<color=#e8d9bb>Bip, Bip!</color>",
  ui_story_1015_10150701_29_dialog_content = "Hah…?",
  ui_story_1015_10150701_30_dialog_content = "(Apakah ini... pengunjung baru?)",
  ui_story_1015_10150701_31_dialog_content = "<color=#e8d9bb>Sementara itu di Undercity X</color>",
  ui_story_1015_10150701_32_dialog_content = "...",
  ui_story_1015_10150701_33_dialog_content = "Jangan berhenti. Pertahankan.",
  ui_story_1015_10150701_34_dialog_content = "Ada apa?",
  ui_story_1015_10150701_35_dialog_content = "Ketika Anda meminta kami untuk bekerja sama dengan Anda, Anda tidak mengatakan hidup kami akan dalam bahaya.",
  ui_story_1015_10150701_36_dialog_content = "Apa yang kau bicarakan Vice? Jangan khawatir, dia akan baik-baik saja. Bagaimana saya bisa rela membiarkan dia mati?",
  ui_story_1015_10150701_37_dialog_content = "Anda ingin menolak, atau mungkin menarik kembali janji kepatuhan Anda?",
  ui_story_1015_10150701_38_dialog_content = "Kenapa aku harus percaya padamu?!",
  ui_story_1015_10150701_39_dialog_content = "Kau sangat menyusahkan.",
  ui_story_1015_10150701_40_dialog_content = "Terimalah ini.",
  ui_story_1015_10150701_41_dialog_content = "<color=#e8d9bb>Buzz ... Buzz ...</color>",
  ui_story_1015_10150701_42_dialog_content = "Jadi ini untuk... Vice?",
  ui_story_1015_10150701_43_dialog_content = "Ya, setiap orang Illumina membawa a <color=#FFB400>penghubung</color>. Ini adalah pita frekuensinya. Saya telah terhubung dengannya selama ini.",
  ui_story_1015_10150701_44_dialog_content = "Helios bersamanya. Anda akan memiliki kesempatan untuk berbicara dengannya dan mengonfirmasi statusnya sebentar lagi.",
  ui_story_1015_10150701_45_dialog_content = "Dan sekarang?",
  ui_story_1015_10150701_46_dialog_content = "Sekarang, tentu saja, Anda akan membantu saya menyingkirkan tentara usil ini.",
  ui_story_1015_10150702_1_dialog_content = "Halo, Vice, Bisakah kamu mendengarku?",
  ui_story_1015_10150702_2_dialog_content = "PlayerName! Apakah itu kamu?!",
  ui_story_1015_10150702_3_dialog_content = "Apakah Anda bertahan baik-baik saja, Vice?",
  ui_story_1015_10150702_4_dialog_content = "Saya baik-baik saja. Hanya terjebak di sini untuk saat ini.",
  ui_story_1015_10150702_5_dialog_content = "Sepertinya tidak ada apa-apa selain gudang kosong di sini.",
  ui_story_1015_10150702_6_dialog_content = "Sebuah gudang?",
  ui_story_1015_10150702_7_dialog_content = "Saya memperingatkan Anda untuk tidak terlibat dalam komunikasi yang tidak perlu.",
  ui_story_1015_10150702_8_dialog_content = "Jika memberi Anda komunikator benar-benar meningkatkan masalah yang Anda berikan kepada saya ...",
  ui_story_1015_10150702_9_dialog_content = "Baiklah saya mengerti! Bisakah kita membicarakan hal lain?",
  ui_story_1015_10150702_10_dialog_content = "Itu cukup bicara.",
  ui_story_1015_10150702_11_dialog_content = "Tujuan kita sudah di depan, jadi mari kita urus urusan dulu.",
  ui_story_1015_10150702_12_dialog_content = "Tempat apa ini? Apa yang kita lakukan di sini?",
  ui_story_1015_10150702_13_dialog_content = "Jangan khawatir, itu hanya besar <color=#FFB400>ruang referensi</color>. Setelah saya mendapatkan apa yang saya inginkan, kita bisa pergi.",
  ui_story_1015_10150702_14_dialog_content = "Bagaimanapun, waktu saya berharga.",
  ui_story_1015_10150702_15_dialog_content = "Jadi mengapa kita masih berdiri di sini alih-alih melanjutkan?",
  ui_story_1015_10150702_16_dialog_content = "Kemarilah.",
  ui_story_1015_10150702_17_dialog_content = "Tempat apa itu?",
  ui_story_1015_10150702_18_dialog_content = "Memindai informasi wajah pengunjung...",
  ui_story_1015_10150702_19_dialog_content = "Menganalisis data akses...",
  ui_story_1015_10150702_20_dialog_content = "Akses arsip diberikan.",
  ui_story_1015_10150702_21_dialog_content = "B-Kenapa aku bisa membukanya?",
  ui_story_1015_10150702_22_dialog_content = "Bukankah saya mengatakan bahwa seluruh lembaga penelitian dulunya milik saya? Namun, Ulysses membuat beberapa perubahan.",
  ui_story_1015_10150702_23_dialog_content = "Karena Anda berhasil memasuki ruang konferensi besar Ulysses, tentunya Anda dapat membantu saya membuka pintu ini.",
  ui_story_1015_10150702_24_dialog_content = "(Monitor pasti menangkap Forsakin yang berdiri di belakangku saat memindai wajahku...)",
  ui_story_1015_10150702_25_dialog_content = "(Jika seseorang melihat, itu tidak akan lama...)",
  ui_story_1015_10150702_26_dialog_content = "Jangan berlama-lama. Cepat masuk ke sini.",
  ui_story_1015_10150702_27_dialog_content = "Anda dan Jade berdiri di depan pintu. Tutup dan jangan membuat masalah.",
  ui_story_1015_10150702_28_dialog_content = "Jika ada yang tiba-tiba masuk, Jade akan mengurus mereka.",
  ui_story_1015_10150702_29_dialog_content = "... Setidaknya beri tahu saya file apa yang Anda cari.",
  ui_story_1015_10150702_30_dialog_content = "Saya mencari data yang tidak akan pernah dipublikasikan oleh Ulysses.",
  ui_story_1015_10150702_31_dialog_content = "Saya ingin melihat data pengujian untuk <color=#FFB400>Program Fosfor</color>.",
  ui_story_1015_10150801_1_dialog_content = "<color=#e8d9bb>Beberapa waktu lalu...</color>",
  ui_story_1015_10150801_2_dialog_content = "Um... Kebijakan privasi—setuju, istilah pengguna—setuju!",
  ui_story_1015_10150801_3_dialog_content = "Perbarui file yang diperlukan...",
  ui_story_1015_10150801_4_dialog_content = "<color=#e8d9bb>Der, der!</color>",
  ui_story_1015_10150801_5_dialog_content = "Masuklah...",
  ui_story_1015_10150801_6_dialog_content = "Petugas Teknologi, seorang gadis yang mengaku sebagai Kapten Penjaga Lumopolis ingin bertemu denganmu.",
  ui_story_1015_10150801_7_dialog_content = "Oh, gadis dari Lumopolis. Katakan padanya untuk berdiri di sisi kiri layar mulai...",
  ui_story_1015_10150801_8_dialog_content = "Layar S-Mulai?",
  ui_story_1015_10150801_9_dialog_content = "Ha! Maaf, saya punya permainan di otak!",
  ui_story_1015_10150801_10_dialog_content = "Hmm? Carleen?",
  ui_story_1015_10150801_11_dialog_content = "Hehe! Tuan Ilmuwan, sebaiknya Anda menjaga sopan santun Anda — orang yang berdiri di sebelah Anda adalah juara Latihan Militer Gabungan yang terakhir, tahukah Anda?",
  ui_story_1015_10150801_12_dialog_content = "Maafkan saya, tetapi karena kekhawatiran tentang status Soroz, saya berencana datang ke sini untuk memastikan situasinya dengan Anda terlebih dahulu.",
  ui_story_1015_10150801_13_dialog_content = "Omong-omong, tidak Vice Dan PlayerName Di Sini?",
  ui_story_1015_10150801_14_dialog_content = "Anda mengatakan Soroz? Hei, terima kasih atas perjalananmu ke Twilight—",
  ui_story_1015_10150801_15_dialog_content = "Lihatlah! Terserah sekarang, dan bahkan bisa mengepakkan sayapnya.",
  ui_story_1015_10150801_16_dialog_content = "Setelah sedikit berbenah dengan Illumina Tech, sekarang kembali ke masa pertempuran lamanya tanpa takut menabrak.",
  ui_story_1015_10150801_17_dialog_content = "Terima kasih atas semua doa terbaiknya, Bu Gronru.",
  ui_story_1015_10150801_18_dialog_content = "Ah, sayang sekali... Tanpa PlayerName dan layanan terjemahan psikisnya, saya tidak dapat mendengar Soroz mengucapkan terima kasih kepada saya sekarang!",
  ui_story_1015_10150801_19_dialog_content = "Jika Soroz baik-baik saja, itu luar biasa.",
  ui_story_1015_10150801_20_dialog_content = "Carleen, apakah Anda yakin dengan Latihan Militer Gabungan?",
  ui_story_1015_10150801_21_dialog_content = "Biarkan saya berbagi strategi kecil lainnya dengan Anda sebelumnya. Lawan Anda kali ini tidak akan mudah dihadapi seperti sebelumnya.",
  ui_story_1015_10150801_22_dialog_content = "Tidak, sebenarnya, saya sudah memilih untuk tidak ambil bagian. Tim Lumopolis akan dipimpin oleh orang lain.",
  ui_story_1015_10150801_23_dialog_content = "Hah? Oh begitu...",
  ui_story_1015_10150801_24_dialog_content = "Kalian bertiga harus segera bertemu karena—",
  ui_story_1015_10150801_25_dialog_content = "Undangan yang Anda miliki berada di bawah formasi Team PlayerName!",
  ui_story_1015_10150801_26_dialog_content = "Jadi begitu. Dalam hal ini, ini juga akan menjadi pertama kalinya Caelestites diwakili dalam latihan militer selama bertahun-tahun.",
  ui_story_1015_10150801_27_dialog_content = "Itu benar, jadi bantulah aku dan jangan menarik pukulanmu ke sana!",
  ui_story_1015_10150801_28_dialog_content = "Begitu, ya. Terima kasih.",
  ui_story_1015_10150801_29_dialog_content = "Jadi, PlayerName Dan Vice adalah...",
  ui_story_1015_10150801_30_dialog_content = "Hmm, tunggu sebentar...",
  ui_story_1015_10150801_31_dialog_content = "<color=#e8d9bb>Bip — Bip—!</color>",
  ui_story_1015_10150801_32_dialog_content = "Saya telah menanamkan izin dan peta ke dalam undangan Anda.",
  ui_story_1015_10150801_33_dialog_content = "Koordinat yang disorot di peta adalah untuk Undercity X, tempat Illumina merawat dan mempelajari Aurorian khusus.",
  ui_story_1015_10150801_34_dialog_content = "(Tetapi... PlayerName Dan Vice sudah lama disana...)",
  ui_story_1015_10150801_35_dialog_content = "Intinya, pass ini akan memberi Anda akses ke sebagian besar fasilitas Illumina.",
  ui_story_1015_10150801_36_dialog_content = "Terima kasih banyak. Tidak ada waktu untuk disia-siakan, saya akan pergi.",
  ui_story_1015_10150801_37_dialog_content = "Teruskan! Tempat ini tidak seperti Lumopolis—Anda tidak akan menemukan penjaga yang menemani Anda... Tetap aman di luar sana!",
  ui_story_1015_10150801_38_dialog_content = "<color=#e8d9bb>Federasi Illumina, Kota Bawah X</color>",
  ui_story_1015_10150801_39_dialog_content = "(Menurut petunjuk di peta, ini seharusnya lokasinya Gronru tersebut...)",
  ui_story_1015_10150801_40_dialog_content = "(Namun, tempat ini bahkan lebih besar dari yang saya bayangkan.)",
  ui_story_1015_10150801_41_dialog_content = "(Jika saya tidak salah, menggunakan bangunan besar dan padat untuk mendukung populasinya yang besar adalah strategi bertahan hidup Illumina.)",
  ui_story_1015_10150801_42_dialog_content = "?!?",
  ui_story_1015_10150801_43_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_1015_10150801_44_dialog_content = "Siapa di sana?",
  ui_story_1015_10150801_45_dialog_content = "... Yingel?",
  ui_story_1015_10150801_46_dialog_content = "Jadi, Andalah yang memicu peringatan pengunjung.",
  ui_story_1015_10150801_47_dialog_content = "Apa yang kamu lakukan di sini—Oh, aku tahu.",
  ui_story_1015_10150801_48_dialog_content = "Kita semua kurang lebih termotivasi oleh tujuan yang sama.",
  ui_story_1015_10150801_49_dialog_content = "Bagaimana situasi saat ini? Bisakah Anda menjelaskannya kepada saya?",
  ui_story_1015_10150801_50_dialog_content = "Ssst—!",
  ui_story_1015_10150801_51_dialog_content = "<anim type=Shake>Gaah... Graaah...</anim>",
  ui_story_1015_10150801_52_dialog_content = "Setidaknya kita tunggu sampai kita selesai melawan Eclipsites ini.",
  ui_story_1015_10150801_53_dialog_content = "Apa yang kamu tunggu? Mari kita lakukan.",
  ui_story_1015_10150802_1_dialog_content = "Bagaimana hal seperti itu bisa terjadi?! Ini semua terlalu konyol!",
  ui_story_1015_10150802_2_dialog_content = "Apa sebenarnya yang diinginkan Forsakin?",
  ui_story_1015_10150802_3_dialog_content = "Mengapa Illumina belum mengirim pasukan untuk mengepung dan menetralisirnya?",
  ui_story_1015_10150802_4_dialog_content = "Tetap tenang, Carleen. Ini bukan Lumopolis—setiap keputusan penting membutuhkan persetujuan bersama dari banyak pihak.",
  ui_story_1015_10150802_5_dialog_content = "Panitia sudah mulai melakukan persiapan, dan kami hanyalah tim garda depan yang dikirim sebelum proses pengambilan keputusan.",
  ui_story_1015_10150802_6_dialog_content = "Jadi, apa tindakan kita selanjutnya?",
  ui_story_1015_10150802_7_dialog_content = "Dari sudut pandang seorang perwira intelijen, kita perlu mengkonsolidasikan intelijen kita dan mendekati Forsakin dengan cara yang seefisien mungkin.",
  ui_story_1015_10150802_8_dialog_content = "Adapun petunjuk intelijen, saya pikir kita bisa mulai dengan kamera pengintai di mana-mana di sekitar sini.",
  ui_story_1015_10150802_9_dialog_content = "Yang perlu saya lakukan hanyalah mengajukan izin untuk meninjau catatan pengawasan, dan kita harus dapat melihat dengan jelas di mana Forsakin dan Vice sekilas.",
  ui_story_1015_10150802_10_dialog_content = "Aku khawatir kita tidak bisa melakukan itu.",
  ui_story_1015_10150802_11_dialog_content = "Entah kenapa, tapi kamera di sini hanya digunakan untuk verifikasi identitas, dan semua catatan langsung dihapus.",
  ui_story_1015_10150802_12_dialog_content = "Bagaimana…",
  ui_story_1015_10150802_13_dialog_content = "Mengapa semua ini terdengar sangat mencurigakan?",
  ui_story_1015_10150802_14_dialog_content = "Lagi pula, kita tidak bisa berkeliaran membabi buta di sekitar Undercity ini.",
  ui_story_1015_10150802_15_dialog_content = "Jangan khawatir, aku hanya memikirkan sesuatu.",
  ui_story_1015_10150802_16_dialog_content = "Saat berurusan dengan masalah Illumina, tentu saja kita harus menggunakan solusi Illumina.",
  ui_story_1015_10150901_1_dialog_content = "(Saya telah mencari di semua file A-prefix bernomor antara 1 dan 50, tetapi saya masih tidak dapat menemukannya.)",
  ui_story_1015_10150901_2_dialog_content = "(Saya perlu mencari cara lain. Perlu waktu satu bulan untuk membaca semua header file di lemari ini saja.)",
  ui_story_1015_10150901_3_dialog_content = "(Selain bertanya langsung kepada Ulysses, saya perlu mengetahui aturan klasifikasi untuk lemari ini dengan cepat...)",
  ui_story_1015_10150901_4_dialog_content = "Vice, apakah kamu punya cukup makanan dan air di sana?",
  ui_story_1015_10150901_5_dialog_content = "Jangan khawatir... Aku...semuanya...membutuhkan.",
  ui_story_1015_10150901_6_dialog_content = "Apa?",
  ui_story_1015_10150901_7_dialog_content = "Hah? Bisakah kamu mendengarku?",
  ui_story_1015_10150901_8_dialog_content = "Oh, aku bisa mendengarmu dengan jelas sekarang. Suara menjadi aneh dan terputus sekarang.",
  ui_story_1015_10150901_9_dialog_content = "Apakah baterai hampir habis? Hal-hal ini tidak memiliki daya tahan baterai yang lama. Mereka cepat habis jika Anda menggunakannya terus-menerus.",
  ui_story_1015_10150901_10_dialog_content = "Hah? Mereka akan kehabisan daya—",
  ui_story_1015_10150901_11_dialog_content = "Kau sangat berisik. Berikan padaku.",
  ui_story_1015_10150901_12_dialog_content = "Hai! Mengapa Anda merebut komunikator dari saya?!",
  ui_story_1015_10150901_13_dialog_content = "Aku akan membiarkanmu bermain dengannya nanti. Datang dan bantu aku dulu.",
  ui_story_1015_10150901_14_dialog_content = "Apa yang kamu inginkan kali ini?",
  ui_story_1015_10150901_15_dialog_content = "Dapatkah Anda Caelestites merasakan objek yang mungkin telah disentuh oleh Aurorian tertentu baru-baru ini?",
  ui_story_1015_10150901_16_dialog_content = "Bantu aku melihatnya.",
  ui_story_1015_10150901_17_dialog_content = "... Kamu pikir aku ini apa, anjing?!",
  ui_story_1015_10150901_18_dialog_content = "Tsk, aku seharusnya melemparmu ke mesin itu di menara.",
  ui_story_1015_10150901_19_dialog_content = "Jika Anda tidak dapat melakukannya, datang dan beri tahu saya jika Anda dapat memecahkan kata sandi konsol ini.",
  ui_story_1015_10150901_20_dialog_content = "Saya baru menyadarinya sendiri... Mesin ini benar-benar sesuatu.",
  ui_story_1015_10150901_21_dialog_content = "Setiap lokasi penelitian memiliki perangkat seperti ini.",
  ui_story_1015_10150901_22_dialog_content = "Ini dapat digunakan untuk mencari informasi dan mengontrol operasi mekanis. Singkatnya, ini adalah alat untuk membantu peneliti.",
  ui_story_1015_10150901_23_dialog_content = "Aku tahu.",
  ui_story_1015_10150901_24_dialog_content = "Apakah saya harus mengoperasikannya? Mungkin seharusnya tidak, hanya untuk berada di sisi yang aman.",
  ui_story_1015_10150901_25_dialog_content = "Saya tidak tahu apa-apa tentang teknologi Illumina.",
  ui_story_1015_10150901_26_dialog_content = "... Lebih sedikit bicara, lebih banyak bertindak.",
  ui_story_1015_10150901_27_dialog_content = "<color=#e8d9bb>Bip—</color>",
  ui_story_1015_10150901_28_dialog_content = "T-Tunggu sebentar, jangan hanya memasukkan angka acak seperti itu...",
  ui_story_1015_10150901_29_dialog_content = "Tujuan teknologi adalah untuk melayani penelitian ilmiah. Jika saya tidak bisa menggunakannya, tidak ada gunanya ada.",
  ui_story_1015_10150901_30_dialog_content = "<color=#e8d9bb>Bip, Bip—Bip—</color>",
  ui_story_1015_10150901_31_dialog_content = "... Bagus.",
  ui_story_1015_10150901_32_dialog_content = "(Untungnya, sepertinya dia benar-benar tahu cara memecahkan benda ini.)",
  ui_story_1015_10150901_33_dialog_content = "<color=#e8d9bb>Bip—</color>",
  ui_story_1015_10150901_34_dialog_content = "<color=#e8d9bb>Peringatan! Peringatan!</color>",
  ui_story_1015_10150901_35_dialog_content = "<color=#e8d9bb>Kesalahan kata sandi, tindakan peringatan darurat diaktifkan—</color>",
  ui_story_1015_10150901_36_dialog_content = "Apa?!",
  ui_story_1015_10150901_37_dialog_content = "<anim type=Shake><size=45>Bip — Bip —</size></anim>",
  ui_story_1015_10150901_38_dialog_content = "Benda apa ini...?",
  ui_story_1015_10150901_39_dialog_content = "Apakah kamu tidak terlalu percaya diri?!? Meninggalkan!",
  ui_story_1015_10150901_40_dialog_content = "Kesalahan tidak bisa dihindari, dan teknologi elektronik bukanlah keahlian saya.",
  ui_story_1015_10150901_41_dialog_content = "Pikirkan sesuatu... Sekarang bukan waktunya menganalisis kekuranganmu!",
  ui_story_1015_10150901_42_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_1015_10150901_43_dialog_content = "Yang diperlukan hanyalah menarik rem listrik dari arsip ini.",
  ui_story_1015_10150901_44_dialog_content = "Yakin?",
  ui_story_1015_10150901_45_dialog_content = "...",
  ui_story_1015_10150901_46_dialog_content = "<anim type=Shake><size=45>Bip — Bip —</size></anim>",
  ui_story_1015_10150901_47_dialog_content = "Itu tidak ada gunanya sama sekali!",
  ui_story_1015_10150901_48_dialog_content = "Tsk... Betapa merepotkan.",
  ui_story_1015_10150901_49_dialog_content = "Kita masih harus berurusan dengan anjing mekanik ini terlebih dahulu. Giok-",
  ui_story_1015_10150901_50_dialog_content = "<anim type=Shake><size=50>Keren!!!</size></anim>",
  ui_story_1015_10150901_51_dialog_content = "Mengisi daya ke depan dan mengunyahnya.",
  ui_story_1015_10150902_1_dialog_content = "<anim type=Shake><size=45>Gigit... Gigit...</size></anim>",
  ui_story_1015_10150902_2_dialog_content = "Bagus sekali. Makan kenyang.",
  ui_story_1015_10150902_3_dialog_content = "Terus awasi pintu untukku, mengerti?",
  ui_story_1015_10150902_4_dialog_content = "<anim type=Shake><size=45>Mengaum...</size></anim>",
  ui_story_1015_10150902_5_dialog_content = "Apakah mesin ini... semacam tindakan pengamanan?",
  ui_story_1015_10150902_6_dialog_content = "Aku tidak tahu. Itu tidak ada di sini ketika saya pergi.",
  ui_story_1015_10150902_7_dialog_content = "Kita sudah membuang terlalu banyak waktu. Kita harus cepat mulai sekarang.",
  ui_story_1015_10150902_8_dialog_content = "<color=#e8d9bb>Bip, Bip—Bip—</color>",
  ui_story_1015_10150902_9_dialog_content = "<color=#e8d9bb>Pusat penyimpanan diaktifkan!</color>",
  ui_story_1015_10150902_10_dialog_content = "Lanjutkan pencarian, Program Phospherus.",
  ui_story_1015_10150902_11_dialog_content = "... Tidak, jika kami tidak dapat menemukan informasi lebih lanjut...",
  ui_story_1015_10150902_12_dialog_content = "Ubah kata kunci, cari <color=#FFB400>Proyek Matahari Buatan</color>.",
  ui_story_1015_10150902_13_dialog_content = "(Buatan...Matahari? Apa maksudnya? Apakah ada hubungannya dengan menciptakan matahari yang sangat besar?)",
  ui_story_1015_10150902_14_dialog_content = "(Sebentar itu Phospherus, selanjutnya ini ... Apa sebenarnya yang dicari Forsakin ...?)",
  ui_story_1015_10150902_15_dialog_content = "Menemukannya.",
  ui_story_1015_10150902_16_dialog_content = "Oke, pindah.",
  ui_story_1015_10150902_17_dialog_content = "Forsakin, apa sebenarnya pentingnya informasi ini, dan apakah layak memutuskan hubungan Anda dengan Ulysses seperti ini?",
  ui_story_1015_10150902_18_dialog_content = "Anda benar-benar ingin tahu?",
  ui_story_1015_10150902_19_dialog_content = "Bahkan jika Anda mengetahuinya, itu tidak akan berguna bagi Anda, karena perangkat di Eraveil telah gagal.",
  ui_story_1015_10150902_20_dialog_content = "Selain itu, penelitian saya telah jauh melampaui tingkat teknologi Illumina dan Caelestite.",
  ui_story_1015_10150902_21_dialog_content = "Saya menyarankan Anda untuk tidak mencoba apa pun.",
  ui_story_1015_10150902_22_dialog_content = "Saya hanya bertanya karena penasaran. Aku baru saja membantumu dalam pertempuran, jadi tidak bisakah aku setidaknya tahu untuk apa aku berjuang?",
  ui_story_1015_10150902_23_dialog_content = "Mempertimbangkan situasi saya saat ini, Anda tidak perlu terlalu berhati-hati, bukan?",
  ui_story_1015_10150902_24_dialog_content = "...",
  ui_story_1015_10150902_25_dialog_content = "Bagus. Tidak ada salahnya untuk memberitahu Anda.",
  ui_story_1015_10150902_26_dialog_content = "Itu adalah sesuatu yang sudah Anda ketahui.",
  ui_story_1015_10150902_27_dialog_content = "Sesuatu yang saya tahu...?",
  ui_story_1015_10150902_28_dialog_content = "Saat itulah Anda pergi ke Mire dan membangunkan Helios yang sudah lama tertidur.",
  ui_story_1015_10150902_29_dialog_content = "Selama ini, dia pasti sudah menceritakan semua tentang pengalaman masa lalu yang dibagikan oleh kami bertiga.",
  ui_story_1015_10150902_30_dialog_content = "Saat itu, kami bertiga tumbuh bersama, bergabung dengan tentara bersama, dan berjuang bersama...",
  ui_story_1015_10150902_31_dialog_content = "Pergaulan jangka panjang ini tentunya bukan karena alasan sentimental seperti yang disebut persahabatan atau ikatan.",
  ui_story_1015_10150902_32_dialog_content = "Itu karena kami adalah subjek tes paling awal <color=#FFB400>Proyek Matahari Buatan</color>.",
  ui_story_1015_10150902_33_dialog_content = "Hanya dengan mengalami proses perkembangan yang sama, menghadapi pertempuran yang sama, dan menerima rangkaian modifikasi yang sama, barulah kita dapat dibandingkan secara kualitatif satu sama lain.",
  ui_story_1015_10150902_34_dialog_content = "Tetapi metode penelitian primitif yang mereka gunakan sama sekali tidak memuaskan.",
  ui_story_1015_10150902_35_dialog_content = "Reinhardt ternyata dia yang sekarang ini benar-benar mengejutkanku.",
  ui_story_1015_10150902_36_dialog_content = "Belakangan, nama proyek ini diubah menjadi lebih enak didengar <color=#FFB400>Fosfor</color>.",
  ui_story_1015_10150902_37_dialog_content = "Jadi itulah yang terjadi... Itulah alasan Anda melakukan semua ini.",
  ui_story_1015_10150902_38_dialog_content = "Ekspresimu memberontak. Apakah semua orang Caelestite begitu memuakkan?",
  ui_story_1015_10150902_39_dialog_content = "Ambil ini. Anda dapat mencoba berbicara dengannya sekarang.",
  ui_story_1015_10150902_40_dialog_content = "Hei!",
  ui_story_1015_10150902_41_dialog_content = "<color=#e8d9bb>Buzz ... Buzz ...</color>",
  ui_story_1015_10150902_42_dialog_content = "PlayerName! Kau baik-baik saja?",
  ui_story_1015_10150902_43_dialog_content = "... Vice!",
  ui_story_1015_10150902_44_dialog_content = "<color=#e8d9bb>Buzz ... Buzz ...</color>",
  ui_story_1015_10150902_45_dialog_content = "Ah...",
  ui_story_1015_10150902_46_dialog_content = "Pita frekuensi Vice aktif!",
  ui_story_1015_10150902_47_dialog_content = "Apakah Anda dapat segera menemukan posisi Vice berdasarkan gelombang radio?",
  ui_story_1015_10150902_48_dialog_content = "Dengan teknologi Illumina saat ini, hal itu mungkin tidak dapat dilakukan.",
  ui_story_1015_10150902_49_dialog_content = "Tapi setidaknya kita tahu Letnan itu Vice sedang menggunakan komunikatornya.",
  ui_story_1015_10150902_50_dialog_content = "Ini menunjukkan bahwa dia memiliki kebebasan bergerak sampai batas tertentu.",
  ui_story_1015_10150902_51_dialog_content = "Jika kecurigaan saya benar, Forsakin pasti berada di ujung lain dari komunikator Letnan Vice.",
  ui_story_1015_10150902_52_dialog_content = "Sepakat. Anatoli, awasi setiap perubahan pita frekuensi di ujung Vice.",
  ui_story_1015_10150902_53_dialog_content = "Ya Bu. Akan melakukan.",
  ui_story_1015_10150902_54_dialog_content = "Mari kita lakukan rencana penyelamatan.",
  ui_story_1015_10150902_55_dialog_content = "Informasi saya menunjukkan bahwa sistem peringatan arsip Profesor Ulysses baru saja dipicu.",
  ui_story_1015_10150902_56_dialog_content = "Tidak diragukan lagi, Forsakin pasti ada di sana, dan PlayerName berada tepat di sisinya.",
  ui_story_1015_10150902_57_dialog_content = "Segera setelah kami menemukan Vice, rencana penyelamatan secara resmi akan dimulai.",
  ui_story_1015_10151001_1_dialog_content = "Saya baik-baik saja, Vice! Saat ini saya berada di beberapa ruang arsip di Undercity X bersama Forsakin!",
  ui_story_1015_10151001_2_dialog_content = "Bagaimana denganmu? Apakah Anda terluka? Kamu ada di mana?!",
  ui_story_1015_10151001_3_dialog_content = "<anim type=Shake>Aku di...pintu...cahaya...</anim>",
  ui_story_1015_10151001_4_dialog_content = "Hah? Apa katamu? Vice?",
  ui_story_1015_10151001_5_dialog_content = "Sial! Kenapa aku tidak bisa mendengarnya? Apakah komunikator ini mati lagi?",
  ui_story_1015_10151001_6_dialog_content = "<color=#e8d9bb>Bip—</color>",
  ui_story_1015_10151001_7_dialog_content = "Panggilan Anda berakhir. Anda menanyakan sesuatu yang seharusnya tidak Anda tanyakan.",
  ui_story_1015_10151001_8_dialog_content = "Anda tidak memberi tahu saya jika ada sesuatu yang seharusnya tidak saya tanyakan! Tentu saja saya akan mencoba mencari tahu apa yang ingin saya ketahui!",
  ui_story_1015_10151001_9_dialog_content = "Apa yang ingin Anda sembunyikan, menekan komunikator dengan tergesa-gesa?",
  ui_story_1015_10151001_10_dialog_content = "Jangan salah paham, aku tidak melakukan apapun.",
  ui_story_1015_10151001_11_dialog_content = "Baterai mesin menyedihkan ini sudah mati.",
  ui_story_1015_10151001_12_dialog_content = "(Ini benar-benar...)",
  ui_story_1015_10151001_13_dialog_content = "(Ini terlalu banyak, dan pada saat yang kritis...)",
  ui_story_1015_10151001_14_dialog_content = "Baiklah, jangan buang waktu lagi.",
  ui_story_1015_10151001_15_dialog_content = "Mari bersiap-siap untuk berangkat. Eksperimen baru sedang menunggu untuk dilakukan.",
  ui_story_1015_10151001_16_dialog_content = "Praktis belum ada yang menginjakkan kaki di area ini kecuali Profesor Ulysses.",
  ui_story_1015_10151001_17_dialog_content = "Hanya ada dua landmark utama di sini. Selain arsip tempat alarm dibunyikan, ada juga laboratorium.",
  ui_story_1015_10151001_18_dialog_content = "Saya mengharapkan tidak kurang dari Anda, Kolonel Yingel... Meskipun saya sudah lama bekerja di Komite, saya tidak tahu apa-apa tentang tempat ini.",
  ui_story_1015_10151001_19_dialog_content = "Anggap saja sebagai laporan rahasia — profesor tidak ingin hal-hal seperti itu diketahui oleh terlalu banyak orang.",
  ui_story_1015_10151001_20_dialog_content = "Jadi, terserah saya untuk menghapus siapa pun yang memasuki tempat ini tanpa izin dengan prasangka ekstrim.",
  ui_story_1015_10151001_21_dialog_content = "Apakah ada pergerakan di rentang frekuensi Vice?",
  ui_story_1015_10151001_22_dialog_content = "Dia dalam keadaan diam radio saat ini. Transmisinya pasti sudah terputus.",
  ui_story_1015_10151001_23_dialog_content = "Berikan padaku-",
  ui_story_1015_10151001_24_dialog_content = "Letnan Vice? Panggilan Vice, ini Yingel, Bisakah kamu mendengarku?",
  ui_story_1015_10151001_25_dialog_content = "Jika Anda dapat menghubungi saya, harap lakukan segera!",
  ui_story_1015_10151001_26_dialog_content = "Hai! Bukankah Forsakin juga akan mendengarmu jika kau memanggilnya seperti itu?!",
  ui_story_1015_10151001_27_dialog_content = "Ini biasanya terjadi, tetapi komunikator Forsakin kehabisan daya.",
  ui_story_1015_10151001_28_dialog_content = "Kehabisan tenaga?!",
  ui_story_1015_10151001_29_dialog_content = "Aku sedang mendengarkan percakapan mereka. PlayerName terlalu sering menggunakan komunikator, sehingga baterai cepat habis.",
  ui_story_1015_10151001_30_dialog_content = "Dilihat dari apa yang saya dengar, itu benar-benar kehabisan daya sekarang.",
  ui_story_1015_10151001_31_dialog_content = "Keberhasilan atau kegagalan misi kita terletak pada saat ini.",
  ui_story_1015_10151001_32_dialog_content = "Apakah itu... Kolonel Yingel?",
  ui_story_1015_10151001_33_dialog_content = "(Ya!)",
  ui_story_1015_10151001_34_dialog_content = "Laporkan lokasi Anda!",
  ui_story_1015_10151001_35_dialog_content = "Apakah ada ciri-ciri khusus tentang tempat Anda ditahan? Itu juga bisa!",
  ui_story_1015_10151001_36_dialog_content = "Ya! Aku terkunci di gudang di Undercity X, dengan pintu abu-abu... Ada jendela di sini dengan cahaya alami!",
  ui_story_1015_10151001_37_dialog_content = "Siap, laksanakan.",
  ui_story_1015_10151001_38_dialog_content = "Saya akan menganggur di frekuensi ini tanpa batas. Harap perhatikan tingkat baterai komunikator Anda. Bahkan jika Forsakin menghubungi Anda lagi, saya masih bisa mendengar semuanya.",
  ui_story_1015_10151001_39_dialog_content = "Siapa lagi yang bersamamu?",
  ui_story_1015_10151001_40_dialog_content = "Helios membawaku ke sini, tapi dia baru saja pergi.",
  ui_story_1015_10151001_41_dialog_content = "Dipahami. Kami akan segera mendatangi Anda.",
  ui_story_1015_10151001_42_dialog_content = "Kolonel Yingel, apakah kamu punya ide?",
  ui_story_1015_10151001_43_dialog_content = "Gudang Undercity X terkonsentrasi di selatan, karena medan di selatan rendah dan mudah dipertahankan, tetapi sulit diserang.",
  ui_story_1015_10151001_44_dialog_content = "Diantaranya, gudang berpintu abu-abu digunakan khusus untuk menyimpan berbagai obat-obatan padat.",
  ui_story_1015_10151001_45_dialog_content = "Gema di ujung Vice sangat keras barusan, jadi dia pasti berada di gudang besar.",
  ui_story_1015_10151001_46_dialog_content = "Ini mengesampingkan semua gudang bawah tanah dan berbagai ruang penyimpanan kecil yang tersebar di sekitar tempat itu.",
  ui_story_1015_10151001_47_dialog_content = "Dengan demikian, gudang di mana Vice ditahan dapat dipersempit menjadi Gudang X-106, X-107, dan X-108.",
  ui_story_1015_10151001_48_dialog_content = "Kalau begitu mari kita mulai pencarian segera.",
  ui_story_1015_10151001_49_dialog_content = "Aku akan pergi ke sana dengan Anatoli. Carleen, Saya ingin Anda mengurus sesuatu untuk saya.",
  ui_story_1015_10151001_50_dialog_content = "Saya ingin Anda pergi ke arsip dan menyelamatkan PlayerName.",
  ui_story_1015_10151001_51_dialog_content = "Untuk memastikan keamanan kedua sandera, akan lebih baik jika kami menyelesaikan penyelamatan secara bersamaan.",
  ui_story_1015_10151001_52_dialog_content = "Jadi begitu. Dipahami.",
  ui_story_1015_10151001_53_dialog_content = "Baiklah. Kami akan memberi Anda dukungan segera setelah penyelamatan selesai di pihak kami.",
  ui_story_1015_10151001_54_dialog_content = "Tolong hati-hati.",
  ui_story_1015_10151001_55_dialog_content = "<color=#e8d9bb>Undercity X, Gudang Selatan</color>",
  ui_story_1015_10151001_56_dialog_content = "Seperti yang diharapkan, persis seperti yang Anda perkirakan, Kolonel.",
  ui_story_1015_10151001_57_dialog_content = "Menurut fitur di sekitar sini, saya yakin kami telah menemukan tempat yang tepat.",
  ui_story_1015_10151001_58_dialog_content = "Kolonel Yingel, Apa yang harus kita lakukan selanjutnya?",
  ui_story_1015_10151001_59_dialog_content = "Yang bisa kita lakukan sekarang adalah mencobanya satu per satu.",
  ui_story_1015_10151001_60_dialog_content = "Untungnya, Forsakin belum mengambil tindakan lebih lanjut...",
  ui_story_1015_10151001_61_dialog_content = "<color=#e8d9bb>Brak—!</color>",
  ui_story_1015_10151001_62_dialog_content = "<anim type=Shake><size=50>Keren!!!</size></anim>",
  ui_story_1015_10151001_63_dialog_content = "A-Apa itu...?",
  ui_story_1015_10151001_64_dialog_content = "(Dia pasti mendeteksi gerakan kita...!)",
  ui_story_1015_10151001_65_dialog_content = "<anim type=Shake><size=50>Keren!!!</size></anim>",
  ui_story_1015_10151001_66_dialog_content = "Hati-Hati! Dia datang dengan cara ini!",
  ui_story_1015_10151101_1_dialog_content = "<color=#e8d9bb>Gruk!</color>",
  ui_story_1015_10151101_2_dialog_content = "Pemogokan sempurna!",
  ui_story_1015_10151101_3_dialog_content = "<anim type=Shake><size=50>Grahhhhhhhh!</size></anim>",
  ui_story_1015_10151101_4_dialog_content = "Apa yang salah dengan dia?!",
  ui_story_1015_10151101_5_dialog_content = "Menurut intelijen kami, Grand Marshal Reinhardt memberinya pukulan berat dalam pertemuan terakhir mereka...",
  ui_story_1015_10151101_6_dialog_content = "Bagaimana itu masih bisa mempertahankan kekuatan yang begitu hebat?",
  ui_story_1015_10151101_7_dialog_content = "<anim type=Shake><size=50>Aahhhh!</size></anim>",
  ui_story_1015_10151101_8_dialog_content = "Awas!",
  ui_story_1015_10151101_9_dialog_content = "Argh...!",
  ui_story_1015_10151101_10_dialog_content = "Terima kasih…",
  ui_story_1015_10151101_11_dialog_content = "Anda tidak bisa terlalu bergantung pada kecerdasan, Kolonel Yingel, karena terkadang bisa tidak akurat.",
  ui_story_1015_10151101_12_dialog_content = "Jika kecerdasan ini memang benar, maka itu...",
  ui_story_1015_10151101_13_dialog_content = "Tidak, dia, Kapten Helios, mungkin telah tinggal sendirian di Zona Gelap selama lebih dari sepuluh tahun. Pikirannya harus dibengkokkan di luar imajinasi.",
  ui_story_1015_10151101_14_dialog_content = "Dengan kekuatan yang dimilikinya, kita tidak bisa meremehkannya.",
  ui_story_1015_10151101_15_dialog_content = "Apalagi dia telah mengalami proses peningkatan dan transformasi, seperti halnya Grand Marshal Reinhardt...",
  ui_story_1015_10151101_16_dialog_content = "Bahkan gabungan kami berdua mungkin tidak sekuat Grand Marshal.",
  ui_story_1015_10151101_17_dialog_content = "Saya sudah tahu itu... Anda tidak perlu mengatakannya, Mayor Anatoli.",
  ui_story_1015_10151101_18_dialog_content = "Terlalu banyak ruang untuk bermanuver di sini, dan mobilitasnya jauh lebih tinggi daripada kita. Jika kita terus melibatkannya, kita hanya akan melelahkan diri kita sendiri!",
  ui_story_1015_10151101_19_dialog_content = "Mari mundur ke koridor untuk membatasi pergerakannya.",
  ui_story_1015_10151101_20_dialog_content = "Baik!",
  ui_story_1015_10151101_21_dialog_content = "<anim type=Shake>Coo...</anim>",
  ui_story_1015_10151101_22_dialog_content = "...",
  ui_story_1015_10151101_23_dialog_content = "Dia berjalan pergi.",
  ui_story_1015_10151101_24_dialog_content = "Kita tidak bisa menghadapinya secara langsung, tapi kita bisa menggunakan medan di sini untuk melancarkan serangan mendadak yang menargetkan kelemahannya.",
  ui_story_1015_10151101_25_dialog_content = "Selama Forsakin tidak—",
  ui_story_1015_10151101_26_dialog_content = "Oh, tidak...",
  ui_story_1015_10151101_27_dialog_content = "<size=45>Ini buruk!</size>",
  ui_story_1015_10151101_28_dialog_content = "Ada apa?",
  ui_story_1015_10151101_29_dialog_content = "Aurorian yang telah ditingkatkan dan dimodifikasi memicu reaksi khusus satu sama lain.",
  ui_story_1015_10151101_30_dialog_content = "Saya khawatir Forsakin akan merasakan bahwa kita sedang bertempur dengan sesama mutannya!",
  ui_story_1015_10151101_31_dialog_content = "…!",
  ui_story_1015_10151101_32_dialog_content = "Ini sepertinya informasi yang sangat penting! Mengapa Anda tidak memberi tahu saya sebelumnya?",
  ui_story_1015_10151101_33_dialog_content = "Eksperimen ini sangat rahasia.",
  ui_story_1015_10151101_34_dialog_content = "Jika bukan karena situasi yang mendesak, semua informasi yang berkaitan dengan percobaan tidak akan tersedia untuk Anda atau saya.",
  ui_story_1015_10151101_35_dialog_content = "Maaf saya membuat kesalahan. Saya gagal memberi tahu Anda tentang situasi secara tepat waktu terkait hal ini.",
  ui_story_1015_10151101_36_dialog_content = "Ini akan menimbulkan masalah...",
  ui_story_1015_10151101_37_dialog_content = "(Komite... Berapa banyak rahasia yang masih mereka sembunyikan?)",
  ui_story_1015_10151101_38_dialog_content = "(Apakah itu modifikasi biologis rahasia atau fakta bahwa kecerdasan yang dipulihkan tim saya telah dirusak...)",
  ui_story_1015_10151101_39_dialog_content = "(Bisakah saya benar-benar mempercayai mereka?)",
  ui_story_1015_10151101_40_dialog_content = "Kita tidak bisa terus memerangi hal ini di sini.",
  ui_story_1015_10151101_41_dialog_content = "Dengan asumsi Forsakin telah mendeteksi serangan kami, tidak mungkin dia tidak waspada.",
  ui_story_1015_10151101_42_dialog_content = "Letnan Vice masih aman untuk saat ini, tapi tidak ada jalan Carleen bisa tahu bahwa kehadiran kita di sini telah ditemukan.",
  ui_story_1015_10151101_43_dialog_content = "Kita perlu menyingkirkannya dengan cepat dan mendukungnya Carleen.",
  ui_story_1015_10151101_44_dialog_content = "Tentu saja, tetapi kita tidak dapat melakukan keduanya sekaligus.",
  ui_story_1015_10151101_45_dialog_content = "Stealth adalah kekuatanmu—temukan kesempatan untuk melewatinya, selamatkan Letnan Vice, dan kemudian dengan cepat pergi ke Carleen.",
  ui_story_1015_10151101_46_dialog_content = "Dan bagaimana denganmu? Apa yang akan kamu lakukan?",
  ui_story_1015_10151101_47_dialog_content = "Forsakin akan lebih sulit dihadapi daripada monster ini. Bahkan dengan lebih dari kita berdua saja, peluang kita untuk menang akan tipis.",
  ui_story_1015_10151101_48_dialog_content = "Saya perlu menyiapkan kartu truf saya — yang cukup kuat untuk menyamakan kedudukan.",
  ui_story_1015_10151101_49_dialog_content = "<color=#e8d9bb>Sementara itu pada PlayerName dan lokasi Forsakin...</color>",
  ui_story_1015_10151101_50_dialog_content = "...",
  ui_story_1015_10151101_51_dialog_content = "<anim type=Shake>Rrr... Gemuruh...!</anim>",
  ui_story_1015_10151101_52_dialog_content = "Tenang, Jade.",
  ui_story_1015_10151101_53_dialog_content = "<anim type=Shake>Groar…</anim>",
  ui_story_1015_10151101_54_dialog_content = "Kau sangat berisik.",
  ui_story_1015_10151101_55_dialog_content = "Dia. Setiap kali mengaum, saya merasa gendang telinga saya akan pecah.",
  ui_story_1015_10151101_56_dialog_content = "Diam.",
  ui_story_1015_10151101_57_dialog_content = "Tikus telah keluar untuk bermain.",
  ui_story_1015_10151101_58_dialog_content = "Tikus?",
  ui_story_1015_10151101_59_dialog_content = "(Lumina ini... Mungkinkah...?)",
  ui_story_1015_10151101_60_option_content = "Gunakan kemampuan psikis",
  ui_story_1015_10151101_61_dialog_content = "(Carleen?!)",
  ui_story_1015_10151101_62_dialog_content = "Keluar.",
  ui_story_1015_10151101_63_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1015_10151101_64_dialog_content = "Betapa bodohnya.",
  ui_story_1015_10151101_65_dialog_content = "<size=45>(Carleen! Hati-Hati!)</size>",
  ui_story_1015_10151101_66_dialog_content = "(Apa...)",
  ui_story_1015_10151101_67_dialog_content = "<color=#e8d9bb>Duarr!!!</color>",
  ui_story_1015_10151101_68_dialog_content = "Batuk... Batuk, batuk!",
  ui_story_1015_10151101_69_dialog_content = "Bagaimana Anda... mengetahuinya?",
  ui_story_1015_10151101_70_dialog_content = "Taktik Anda paling kikuk.",
  ui_story_1015_10151101_71_dialog_content = "...",
  ui_story_1015_10151101_72_dialog_content = "Namun, sebagai faktor yang dapat mempengaruhi hasil percobaan saya, upaya yang saya perlukan untuk menghilangkan Anda harus bermanfaat.",
  ui_story_1015_10151101_73_dialog_content = "<anim type=Shake>Groar…</anim>",
  ui_story_1015_10151101_74_dialog_content = "Ada begitu banyak dari mereka ...",
  ui_story_1015_10151101_75_dialog_content = "Menyerang.",
  ui_story_1015_10151101_76_dialog_content = "<anim type=Shake><size=50>Keren!!!</size></anim>",
  ui_story_1015_10151102_1_dialog_content = "Urgh...!!!",
  ui_story_1015_10151102_2_dialog_content = "<anim type=Shake><size=45>Grah!</size></anim>",
  ui_story_1015_10151102_3_dialog_content = "Tidak ada akhir bagi mereka...",
  ui_story_1015_10151102_4_dialog_content = "Carleen!!!",
  ui_story_1015_10151102_5_dialog_content = "Anda merencanakan serangan bercabang dua, berniat mengambil Caelestite dan gadis kecil itu pada saat bersamaan.",
  ui_story_1015_10151102_6_dialog_content = "Namun, untuk memecah belah dan menaklukkan, seseorang harus memiliki keyakinan mutlak pada kemampuannya sendiri.",
  ui_story_1015_10151102_7_dialog_content = "Kok kau tahu?",
  ui_story_1015_10151102_8_dialog_content = "Itu semua berkat anjing-anjing tua itu dan proyek mereka.",
  ui_story_1015_10151102_9_dialog_content = "Apakah maksud Anda koneksi khusus Reinhardt tersebut?",
  ui_story_1015_10151102_10_dialog_content = "Oh tidak, jika Anda memiliki kemampuan ini, maka Yingel Dan Anatoli—",
  ui_story_1015_10151102_11_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1015_10151102_12_dialog_content = "Batuk... Batuk, batuk, batuk!",
  ui_story_1015_10151102_13_dialog_content = "Ini...",
  ui_story_1015_10151102_14_dialog_content = "<anim type=Shake>Groar…</anim>",
  ui_story_1015_10151102_15_dialog_content = "Tikus lain.",
  ui_story_1015_10151102_16_dialog_content = "Anatoli! Bagaimana Anda bisa sampai di sini?",
  ui_story_1015_10151102_17_dialog_content = "Dimana Vice!",
  ui_story_1015_10151102_18_dialog_content = "Maaf. Saya ditemukan dan tidak dapat menemukan di mana Letnan Vice sedang diadakan. Aku tidak bisa menyelamatkannya...",
  ui_story_1015_10151102_19_dialog_content = "Tampaknya yang Anda miliki di antara Anda hanyalah kesombongan dan ketidakmampuan.",
  ui_story_1015_10151102_20_dialog_content = "Pekerjaan saya di sini akan segera selesai. Anda tidak lagi digunakan.",
  ui_story_1015_10151102_21_dialog_content = "...",
  ui_story_1015_10151102_22_dialog_content = "Tidak!",
  ui_story_1015_10151102_23_dialog_content = "Dan begitu saja kita dikelilingi...",
  ui_story_1015_10151102_24_dialog_content = "tetap bertahan PlayerName, Carleen.",
  ui_story_1015_10151102_25_dialog_content = "Jangan lupa, kita masih punya Kolonel Yingel.",
  ui_story_1015_10151102_26_dialog_content = "Pergi. Jaga mereka—",
  ui_story_1015_10151102_27_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1015_10151102_28_dialog_content = "Forsakin, apakah Anda membaca saya?",
  ui_story_1015_10151102_29_dialog_content = "Saya hanya ingin tahu di mana mouse yang hilang itu.",
  ui_story_1015_10151102_30_dialog_content = "Ternyata dia bersembunyi di suatu tempat yang jauh.",
  ui_story_1015_10151102_31_dialog_content = "Apa pun yang Anda coba lakukan, hentikan sekarang juga.",
  ui_story_1015_10151102_32_dialog_content = "Jika tidak, saya berjanji Anda akan menyesalinya.",
  ui_story_1015_10151102_33_dialog_content = "...",
  ui_story_1015_10151102_34_dialog_content = "Apa yang telah kau lakukan?",
  ui_story_1015_10151102_35_dialog_content = "Terimakasih untuk Anatoli dan upaya Carleen, saya dapat menutupi area di sekitar laboratorium Chord Link <color=#FFB400>bahan peledak</color> sementara mereka memberi saya waktu.",
  ui_story_1015_10151102_36_dialog_content = "Pistol saya sekarang diarahkan ke salah satu laras. Segera setelah saya menarik pelatuknya, Tautan Chord akan hilang selamanya dalam kobaran api, bersama dengan data berharga Anda.",
  ui_story_1015_10151102_37_dialog_content = "?!",
  ui_story_1015_10151102_38_dialog_content = "Adegan yang akrab, bukan begitu, Forsakin?",
  ui_story_1015_10151102_39_dialog_content = "Sekarang, segera menyerah dan lepaskan PlayerName dan yang lainnya.",
  ui_story_1015_10151102_40_dialog_content = "...",
  ui_story_1015_10151102_41_dialog_content = "<size=45>Api... Ada api di mana-mana!</size>",
  ui_story_1015_10151102_42_dialog_content = "<size=45>Eksperimen saya! Eksperimen saya!!!</size>",
  ui_story_1015_10151102_43_dialog_content = "Heheh.",
  ui_story_1015_10151102_44_dialog_content = "Orang-orang tua itu tidak memiliki banyak bakat untuk penelitian, tetapi mereka cukup pandai melatih anjing.",
  ui_story_1015_10151102_45_dialog_content = "Kau…!",
  ui_story_1015_10151102_46_dialog_content = "Kamu tidak akan berani.",
  ui_story_1015_10151102_47_dialog_content = "Chord Link adalah lambang teknologi Caelestite kuno. Itu bukan sesuatu yang mungkin Anda temui di pinggir jalan.",
  ui_story_1015_10151102_48_dialog_content = "Hanya satu perangkat seperti itu yang ada di seluruh Federasi Illumina.",
  ui_story_1015_10151102_49_dialog_content = "Belum lagi data yang disimpan di dalam mesin. Keseluruhan Program Phospherus mungkin hanya puncak gunung es.",
  ui_story_1015_10151102_50_dialog_content = "Sebagai anjing terlatih mereka, tidak mungkin Anda tidak menyadari semua ini.",
  ui_story_1015_10151102_51_dialog_content = "Jika fosil-fosil tua itu menimbang Chord Link dan datanya pada skala kepentingan terbaik mereka, hidup Anda bahkan tidak memenuhi syarat sebagai penyeimbang.",
  ui_story_1015_10151102_52_dialog_content = "Benarkah?",
  ui_story_1015_10151102_53_dialog_content = "Baiklah, mari kita coba.",
  ui_story_1015_10151102_54_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_1015_10151201_1_dialog_content = "<color=#e8d9bb>Booom—!!!</color>",
  ui_story_1015_10151201_2_dialog_content = "Api...",
  ui_story_1015_10151201_3_dialog_content = "Ini terbakar ...",
  ui_story_1015_10151201_4_dialog_content = "Helios, ikut aku ke laboratorium!",
  ui_story_1015_10151201_5_dialog_content = "<anim type=Shake><size=45>Mengaum-!</size></anim>",
  ui_story_1015_10151201_6_dialog_content = "Sekaranglah kesempatan kita!",
  ui_story_1015_10151201_7_dialog_content = "Sebarkan, Bunga Es!",
  ui_story_1015_10151201_8_dialog_content = "Hati-hati, Eclipsites mendekat lagi!",
  ui_story_1015_10151201_9_dialog_content = "<anim type=Shake><size=45>Keren!!!</size></anim>",
  ui_story_1015_10151201_10_dialog_content = "<color=#e8d9bb>Bang! Salah!</color>",
  ui_story_1015_10151201_11_dialog_content = "<anim type=Shake>Graah...</anim>",
  ui_story_1015_10151201_12_dialog_content = "Sekarang! Manfaatkan kesempatan ini untuk menabung PlayerName!",
  ui_story_1015_10151201_13_dialog_content = "Siap, Kapten!",
  ui_story_1015_10151201_14_dialog_content = "PlayerName, Aku akan melepaskanmu!",
  ui_story_1015_10151201_15_dialog_content = "Terima kasih…",
  ui_story_1015_10151201_16_dialog_content = "Adalah Vice Baiklah? Dimana dia?",
  ui_story_1015_10151201_17_dialog_content = "Maaf, saya ditemukan oleh musuh dan tidak dapat menemukan Letnan Vice...",
  ui_story_1015_10151201_18_dialog_content = "Tapi tidak ada musuh lain di area itu, jadi setidaknya aku bisa menjaminmu Letnan Vice aman.",
  ui_story_1015_10151201_19_dialog_content = "Jangan khawatir, orang lain sedang dalam perjalanan untuk menyelamatkan Vice.",
  ui_story_1015_10151201_20_dialog_content = "Yang perlu Anda lakukan sekarang adalah mencegah Forsakin menyelesaikan eksperimennya.",
  ui_story_1015_10151201_21_dialog_content = "Jadi, Anda tidak menghancurkan Chord Link.",
  ui_story_1015_10151201_22_dialog_content = "Apa? Itu tidak hancur?!",
  ui_story_1015_10151201_23_dialog_content = "Bagaimana saya bisa membiarkan sesuatu seperti itu dihancurkan dengan begitu mudah?",
  ui_story_1015_10151201_24_dialog_content = "Jika benar-benar hancur, tidak ada yang tahu berapa banyak masalah Kolonel Yingel akan menemukan dirinya dengan pengadilan militer.",
  ui_story_1015_10151201_25_dialog_content = "Baiklah, itu sudah cukup.",
  ui_story_1015_10151201_26_dialog_content = "Mari singkirkan Eclipsites ini dan hentikan Forsakin!",
  ui_story_1015_10151201_27_dialog_content = "Anda mengeluarkan kata-kata itu dari mulut saya!",
  ui_story_1015_10151202_1_dialog_content = "<color=#e8d9bb>Undercity X, Bertahun-Tahun Lalu</color>",
  ui_story_1015_10151202_2_dialog_content = "Eksperimen saya... Eksperimen saya!",
  ui_story_1015_10151202_3_dialog_content = "Semua data dan bahan tes saya masih ada di dalam! Kita harus mengeluarkan mereka dari sana!",
  ui_story_1015_10151202_4_dialog_content = "<anim type=Shake><size=45>Mencicit! Mencicit, mencicit!</size></anim>",
  ui_story_1015_10151202_5_dialog_content = "Jade, masuklah ke dalam mantelku—kita harus kembali!",
  ui_story_1015_10151202_6_dialog_content = "<anim type=Shake><size=45>Mencicit!</size></anim>",
  ui_story_1015_10151202_7_dialog_content = "Kita perlu mengambil data percobaan, dengan cepat...",
  ui_story_1015_10151202_8_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1015_10151202_9_dialog_content = "Ah!!!",
  ui_story_1015_10151202_10_dialog_content = "Sial! Saya tidak menyangka itu bisa menyebabkan kebakaran sebesar itu ...",
  ui_story_1015_10151202_11_dialog_content = "Jika yang harus kita andalkan hanyalah fasilitas pemadam kebakaran yang ada di Undercity, kita mungkin tidak bisa memadamkan api sebesar ini.",
  ui_story_1015_10151202_12_dialog_content = "Mungkinkah aku sudah tidak punya pilihan selain meminta bantuanmu-tahu-siapa...?",
  ui_story_1015_10151202_13_dialog_content = "<color=#e8d9bb>Berdengung—Berdengung—</color>",
  ui_story_1015_10151202_14_dialog_content = "Api besar itu hampir menghancurkan semua pencapaian penelitian saya.",
  ui_story_1015_10151202_15_dialog_content = "Aku tidak akan membiarkan itu terjadi lagi!",
  ui_story_1015_10151202_16_dialog_content = "Ini...",
  ui_story_1015_10151202_17_dialog_content = "(Bahkan tidak ada satu percikan pun di laboratorium Chord Link...)",
  ui_story_1015_10151202_18_dialog_content = "(Apakah fosil tua itu memasang alat penyiram ini setelah saya pergi?)",
  ui_story_1015_10151202_19_dialog_content = "Tampaknya api tidak hanya menempel pada saya tetapi juga pada mereka.",
  ui_story_1015_10151202_20_dialog_content = "Namun…",
  ui_story_1015_10151202_21_dialog_content = "<color=#e8d9bb>Tzzst—</color>",
  ui_story_1015_10151202_22_dialog_content = "Menyerahlah, Forsakin.",
  ui_story_1015_10151202_23_dialog_content = "Para sandera semuanya aman. Keripik tawar Anda telah menghilang begitu saja.",
  ui_story_1015_10151202_24_dialog_content = "Menggunakan trik kecil itu untuk memaksaku pergi... Apa itu rencanamu?",
  ui_story_1015_10151202_25_dialog_content = "Itu benar, tapi itu bukan hanya tipuan.",
  ui_story_1015_10151202_26_dialog_content = "Saya tahu Anda tidak akan tertipu oleh alat peraga belaka, jadi tong bahan peledak di sekitar laboratorium semuanya nyata.",
  ui_story_1015_10151202_27_dialog_content = "Hanya Anda yang tidak tahu bahwa sejak kebakaran saat itu, Grand Marshal memerintahkan peningkatan lengkap peralatan pemadam kebakaran Undercity.",
  ui_story_1015_10151202_28_dialog_content = "Ada lebih dari dua kali jumlah alat pemadam api dan penyiram di sini sekarang, dan bahkan dindingnya telah diperkuat dengan bahan tahan ledakan dan tahan api.",
  ui_story_1015_10151202_29_dialog_content = "Jadi, itu dia.",
  ui_story_1015_10151202_30_dialog_content = "Dia melakukan banyak hal, tapi sayangnya, itu semua hanyalah hambatan yang tidak berguna.",
  ui_story_1015_10151202_31_dialog_content = "...",
  ui_story_1015_10151202_32_dialog_content = "Kucing menangkap lidahmu?",
  ui_story_1015_10151202_33_dialog_content = "Anda masih tidak bisa mengatasi api bertahun-tahun yang lalu, bukan?",
  ui_story_1015_10151202_34_dialog_content = "Tapi tidakkah kau ingin tahu apa yang sebenarnya terjadi saat itu?",
  ui_story_1015_10151202_35_dialog_content = "Muntahkan.",
  ui_story_1015_10151202_36_dialog_content = "Setelah Anda mengirimkan sinyal marabahaya saat itu, Grand Marshal Reinhardt segera meluncurkan operasi penyelamatan di Undercity X.",
  ui_story_1015_10151202_37_dialog_content = "Hanya karena apinya terlalu ganas, Undercity sudah dipenuhi asap tebal saat tim penyelamat tiba.",
  ui_story_1015_10151202_38_dialog_content = "Meski begitu, Grand Marshal masih yang pertama menyerbu ke dalam api. Dia mencarimu di neraka yang menyala-nyala selama beberapa jam.",
  ui_story_1015_10151202_39_dialog_content = "Saya mendengar dari petugas penyelamat ketika Grand Marshal akhirnya muncul, tubuhnya ditutupi bekas hangus hangus, dan pakaiannya dibakar menjadi kain pucat.",
  ui_story_1015_10151202_40_dialog_content = "Tapi dia tidak peduli seberapa sakitnya dia, yang dia rasakan hanyalah penyesalan—penyesalan karena tidak bisa menemukan adik tercintanya.",
  ui_story_1015_10151202_41_dialog_content = "...",
  ui_story_1015_10151202_42_dialog_content = "Jadi, sekarang Anda tahu.",
  ui_story_1015_10151202_43_dialog_content = "Saat itu, Grand Marshal menolak untuk menyerah padamu. Tidak ada yang menyerah padamu.",
  ui_story_1015_10151202_44_dialog_content = "Andalah yang dengan keras kepala mengira Anda telah ditinggalkan, membelakangi Illumina dan membelot ke sekelompok Eclipsites yang jahat itu.",
  ui_story_1015_10151202_45_dialog_content = "Semua yang telah Anda lakukan selama bertahun-tahun, bukankah itu semua hanya pembalasan terhadap mereka yang Anda pikir sudah menyerah?",
  ui_story_1015_10151202_46_dialog_content = "Sekarang Anda tahu bahwa jika Anda tidak pergi atas kemauan Anda sendiri, tidak ada yang mau menyerah pada Anda.",
  ui_story_1015_10151202_47_dialog_content = "Balas dendam Anda dibangun di atas proposisi palsu sejak awal!",
  ui_story_1015_10151202_48_dialog_content = "Berhenti menolak. Anda tidak punya alasan untuk memusuhi Illumina, dan tidak ada jalan keluar.",
  ui_story_1015_10151202_49_dialog_content = "Heheh.",
  ui_story_1015_10151202_50_dialog_content = "Setelah bertahun-tahun, fosil-fosil tua itu entah bagaimana berhasil mempertahankan rasa uniknya yang buruk.",
  ui_story_1015_10151202_51_dialog_content = "Mereka masih menyukai anjing yang benar-benar bodoh.",
  ui_story_1015_10151202_52_dialog_content = "...",
  ui_story_1015_10151202_53_dialog_content = "Apa menurutmu alasanku memilih meninggalkan Illumina adalah karena sesuatu yang sepele seperti merasa dikhianati?",
  ui_story_1015_10151202_54_dialog_content = "Anda benar-benar salah.",
  ui_story_1015_10151202_55_dialog_content = "Jadi mengapa Anda mengkhianati Illumina?",
  ui_story_1015_10151202_56_dialog_content = "Alasan kepergianku sederhana.",
  ui_story_1015_10151202_57_dialog_content = "Lingkungan yang disediakan oleh Federasi Illumina tidak lagi cukup bagi saya untuk melakukan penelitian ilmiah tingkat lanjut.",
  ui_story_1015_10151202_58_dialog_content = "Baik subjek tes yang tersedia maupun materi penelitian yang disediakan tidak dapat membantu saya dalam membuat terobosan baru.",
  ui_story_1015_10151202_59_dialog_content = "Maka saya memilih keluar karena kemungkinan terobosan baru yang ditawarkan oleh teknologi yang dikuasai Eclipse.",
  ui_story_1015_10151202_60_dialog_content = "Itu saja.",
  ui_story_1015_10151202_61_dialog_content = "<color=#e8d9bb>Sementara itu, di suatu tempat di Undercity...</color>",
  ui_story_1015_10151202_62_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1015_10151202_63_dialog_content = "Tepat waktu!",
  ui_story_1015_10151202_64_dialog_content = "Rencananya selalu setepat tanpa cacat.",
  ui_story_1015_10151202_65_dialog_content = "<color=#e8d9bb>Ngungg...</color>",
  ui_story_1015_10151202_66_dialog_content = "Sudah waktunya untuk <color=#FFB400>penyapu</color> untuk tampil.",
  ui_story_1015_10151301_1_dialog_content = "<color=#e8d9bb>Bwee—Bwee—</color>",
  ui_story_1015_10151301_2_dialog_content = "Aku tidak tahan dengan semua kebisingan ini.",
  ui_story_1015_10151301_3_dialog_content = "Apa?",
  ui_story_1015_10151301_4_dialog_content = "Saya pikir Anda mungkin lebih kuat dari tikus itu.",
  ui_story_1015_10151301_5_dialog_content = "Sekarang tampak jelas bagi saya bahwa Anda tidak lebih baik dari mereka.",
  ui_story_1015_10151301_6_dialog_content = "Potong daya.",
  ui_story_1015_10151301_7_dialog_content = "TIDAK! Jaga saklar daya!",
  ui_story_1015_10151301_8_dialog_content = "<anim type=Shake><size=45>Gaaah!</size></anim>",
  ui_story_1015_10151301_9_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1015_10151301_10_dialog_content = "Sialan... Gerbang utama Undercity terhubung ke sistem tenaga.",
  ui_story_1015_10151301_11_dialog_content = "Setelah listrik padam, gerbang akan terkunci.",
  ui_story_1015_10151301_12_dialog_content = "Apakah jalan keluar di balik pintu itu?",
  ui_story_1015_10151301_13_dialog_content = "Tidak, ada sesuatu... yang lebih merepotkan daripada jalan keluar di belakang sana.",
  ui_story_1015_10151301_14_dialog_content = "Apa itu sebenarnya?",
  ui_story_1015_10151301_15_dialog_content = "<color=#e8d9bb>Meretih-</color>",
  ui_story_1015_10151301_16_dialog_content = "Izinkan saya memberi tahu Anda jawabannya.",
  ui_story_1015_10151301_17_dialog_content = "Chord Link ada di balik pintu itu.",
  ui_story_1015_10151301_19_dialog_content = "Apa pun yang Anda coba lakukan, hentikan sekarang juga!",
  ui_story_1015_10151301_20_dialog_content = "Perangkat itu tidak lengkap... Tidak ada yang tahu apa konsekuensi dari menggunakannya secara sembarangan!",
  ui_story_1015_10151301_21_dialog_content = "Harus kuakui, kau sangat berpengetahuan.",
  ui_story_1015_10151301_22_dialog_content = "Tapi jangan lupa, tikus kecil...",
  ui_story_1015_10151301_23_dialog_content = "Anda bukan seorang peneliti, dan pemahaman Anda tentang mesin ini semuanya berasal dari orang tua itu.",
  ui_story_1015_10151301_24_dialog_content = "Alasan Anda menganggap mesin ini menimbulkan ancaman adalah karena—",
  ui_story_1015_10151301_25_dialog_content = "Anda tidak tahu bagaimana menggunakannya.",
  ui_story_1015_10151301_26_dialog_content = "<color=#e8d9bb>Kegentingan-</color>",
  ui_story_1015_10151301_27_dialog_content = "Faktor-faktor yang mengganggu percobaan ini telah dihilangkan. Ayo lanjutkan.",
  ui_story_1015_10151301_28_dialog_content = "Datang ke sini, subjek tes.",
  ui_story_1015_10151301_29_dialog_content = "...",
  ui_story_1015_10151301_30_dialog_content = "<color=#e8d9bb>Sementara itu di Kota Gannon...</color>",
  ui_story_1015_10151301_31_dialog_content = "<color=#e8d9bb>Tzzst—</color>",
  ui_story_1015_10151301_32_dialog_content = "Kapten Wrath, misi mendesak membutuhkan perhatian Anda. Harap tanggapi jika Anda menyalin!",
  ui_story_1015_10151301_33_dialog_content = "Misi mendesak? Misi mendesak apa yang bisa datang saat ini?",
  ui_story_1015_10151301_34_dialog_content = "Penasaran kan... Yuk simak dan cari tahu.",
  ui_story_1015_10151301_35_dialog_content = "Diterima, silakan lanjutkan.",
  ui_story_1015_10151301_36_dialog_content = "Undercity X diduga telah diserbu oleh Forsakin. Komite telah memerintahkan Anda untuk memberikan dukungan dan segera menangkap Forsakin dan Helios.",
  ui_story_1015_10151301_37_dialog_content = "<size=45>Apa?!</size>",
  ui_story_1015_10151301_38_dialog_content = "Meninggalkan? Dia benar-benar lari kembali ke wilayah Illumina...?",
  ui_story_1015_10151301_39_dialog_content = "...",
  ui_story_1015_10151301_40_dialog_content = "Jika itu masalahnya, Wrath, Aku akan pergi bersamamu.",
  ui_story_1015_10151301_41_dialog_content = "Aku tahu kau tidak bisa melepaskannya.",
  ui_story_1015_10151301_42_dialog_content = "Tapi kau harus berjanji padaku bahwa kau tidak akan melakukan hal konyol.",
  ui_story_1015_10151301_43_dialog_content = "Tentu saja, saya berjanji kepada Anda. Ini misimu—aku tidak akan melibatkan diri lebih dari yang diperlukan.",
  ui_story_1015_10151301_44_dialog_content = "Oke, kalau begitu... Ayo pergi.",
  ui_story_1015_10151302_1_dialog_content = "<color=#e8d9bb>Tok, tok, tok!</color>",
  ui_story_1015_10151302_2_dialog_content = "Masuk.",
  ui_story_1015_10151302_3_dialog_content = "Gasp... Gasp... Melapor!",
  ui_story_1015_10151302_4_dialog_content = "Pak, Wrath sedang dalam perjalanan, sesuai rencana kami, dan diharapkan tiba dalam waktu satu jam.",
  ui_story_1015_10151302_5_dialog_content = "Tapi ada sedikit perubahan pada rencana—Reinhardt juga telah datang.",
  ui_story_1015_10151302_6_dialog_content = "Oh?",
  ui_story_1015_10151302_7_dialog_content = "Tidak apa-apa. Saya berharap sebanyak itu.",
  ui_story_1015_10151302_8_dialog_content = "Apa ini juga bagian dari rencanamu?",
  ui_story_1015_10151302_9_dialog_content = "Heh, ini bukan bagian dari rencanaku.",
  ui_story_1015_10151302_10_dialog_content = "Tapi asap hitam mengepul dari laboratorium Chord Link...",
  ui_story_1015_10151302_11_dialog_content = "Jangan khawatir tentang kebakaran itu. Saya melihat melalui monitor pengawasan bahwa mereka tidak akan terbakar lama.",
  ui_story_1015_10151302_12_dialog_content = "Duduk dan minumlah. Mulai sekarang, yang perlu kita lakukan hanyalah duduk dan menonton pertunjukan.",
  ui_story_1015_10151302_13_dialog_content = "Siap, Jenderal.",
  ui_story_1015_10151302_14_dialog_content = "Tidak heran saya tidak bisa memenangkan permainan Joker melawannya.",
  ui_story_1015_10151302_15_dialog_content = "Ternyata dia sudah melihat ke dalam hati orang-orang.",
  ui_story_1015_10151302_16_dialog_content = "Denier, tidak, Forsakin, benar-benar pantas mendapatkan kecemburuan kita.",
  ui_story_1015_10151302_17_dialog_content = "…?",
  ui_story_1015_10151302_18_dialog_content = "Apakah kamu tidak iri padanya?",
  ui_story_1015_10151302_19_dialog_content = "Pak, saya...",
  ui_story_1015_10151302_20_dialog_content = "Memang. Anda bukan seorang peneliti. Sangat normal jika Anda tidak iri padanya.",
  ui_story_1015_10151302_21_dialog_content = "...",
  ui_story_1015_10151302_22_dialog_content = "Apakah Anda sekarang bertanya-tanya pada diri sendiri apa tentang dia yang membuat saya iri?",
  ui_story_1015_10151302_23_dialog_content = "Siap, Jenderal.",
  ui_story_1015_10151302_24_dialog_content = "Dia memiliki sifat unik yang membuatnya menjadi peneliti yang sempurna.",
  ui_story_1015_10151302_25_dialog_content = "Kegigihan?",
  ui_story_1015_10151302_26_dialog_content = "Kekejaman.",
  ui_story_1015_10151302_27_dialog_content = "Ada pepatah lama Illumina—",
  ui_story_1015_10151302_28_dialog_content = "\"Tidak ada kebaikan atau kejahatan yang melekat dalam sains dan teknologi, tetapi hanya ada di hati para Aurorian yang menggunakannya.\"",
  ui_story_1015_10151302_29_dialog_content = "Namun, sering kali ada saatnya seseorang harus menjadi penjahat terlebih dahulu untuk mendorong peradaban maju.",
  ui_story_1015_10151302_30_dialog_content = "Anda tidak selalu dapat memiliki kue dan memakannya, dan Forsakin sangat menyadari hal ini. Dan wanita itu juga mengetahuinya dengan baik...",
  ui_story_1015_10151302_31_dialog_content = "Untuk mendapatkan hasil penelitian yang dia cari, dia dapat memperlakukan mantan rekannya sebagai subjek uji tanpa ragu-ragu.",
  ui_story_1015_10151302_32_dialog_content = "Ini adalah bukti paling menentukan dari kekejamannya.",
  ui_story_1015_10151302_33_dialog_content = "Tapi bukankah benar dia tidak punya pilihan lain?",
  ui_story_1015_10151302_34_dialog_content = "Tidak, tidak, tidak, kami tidak memaksanya.",
  ui_story_1015_10151302_35_dialog_content = "Yang kami lakukan hanyalah menciptakan peluang yang sedikit membatasi tetapi sangat menarik baginya.",
  ui_story_1015_10151302_36_dialog_content = "Memanfaatkan kesempatan ini sepenuhnya merupakan keputusannya sendiri.",
  ui_story_1015_10151302_37_dialog_content = "Penelitiannya tidak pernah menyimpang dari esensi eksperimen ini—menggunakan metode ilmiah untuk menjelajahi batas-batas potensi biologis.",
  ui_story_1015_10151302_38_dialog_content = "Ini telah terjadi sejak awal Project Artificial Sun.",
  ui_story_1015_10151302_39_dialog_content = "Anda sudah familiar dengan Project Artificial Sun, bukan? Itu adalah pendahulu dari Program Phospherus.",
  ui_story_1015_10151302_40_dialog_content = "Pencapaian terbesarnya adalah teknologi peningkatan Aurorian, yang dikembangkan secara mandiri oleh Illumina. Namun, hasilnya tidak stabil karena keterbatasan teknologi kami yang belum berkembang.",
  ui_story_1015_10151302_41_dialog_content = "Satu kekuatan kuat bergerak bebas di dalam Aurorian, dan itu hanya bisa dijinakkan dengan kemauan yang kuat.",
  ui_story_1015_10151302_42_dialog_content = "Hasil dari melakukannya adalah tingkat keberhasilannya sangat rendah, dan subjek juga cenderung kehilangan kendali atas kekuatannya.",
  ui_story_1015_10151302_43_dialog_content = "Pada gilirannya, akibat kehilangan kendali adalah kematian, cacat permanen, atau... menjadi salah satu monster itu.",
  ui_story_1015_10151302_44_dialog_content = "Namun, mantan Denier, juga dikenal sebagai Forsakin, tidak menyerah pada salah satu dari nasib tersebut.",
  ui_story_1015_10151302_45_dialog_content = "Apakah dia dianggap gagal?",
  ui_story_1015_10151302_46_dialog_content = "Sebenarnya, tidak.",
  ui_story_1015_10151302_47_dialog_content = "Dia adalah subjek yang sukses, tetapi lintasan kesuksesannya tidak sesuai dengan harapan kami.",
  ui_story_1015_10151302_48_dialog_content = "Yang kami inginkan adalah subjek dengan kekuatan yang ditingkatkan, tetapi dalam kasusnya, kecerdasannya ditingkatkan.",
  ui_story_1015_10151302_49_dialog_content = "Kesuksesannya menjadikannya peneliti paling berbakat dan ancaman tersembunyi terbesar di Illumina.",
  ui_story_1015_10151302_50_dialog_content = "Anda telah melihat bagaimana cerita ini berakhir. Dia tidak diragukan lagi telah menjadi pengkhianat, berdiri berlawanan langsung dengan Illumina.",
  ui_story_1015_10151302_51_dialog_content = "Jadi, sehubungan dengan semua Illumina, Reinhardt adalah produk paling sukses dari Project Artificial Sun.",
  ui_story_1015_10151302_52_dialog_content = "Tapi masih ada satu hal yang saya tidak mengerti.",
  ui_story_1015_10151302_53_dialog_content = "Bagaimana cara menentukan keberhasilan seorang Aurorian yang dimodifikasi oleh Project Artificial Sun?",
  ui_story_1015_10151302_54_dialog_content = "Lagi pula, tidak semua karakteristik kegagalan dapat terwujud segera setelah peningkatan.",
  ui_story_1015_10151302_55_dialog_content = "Masih ingat dengan pertempuran yang terjadi di Undercity 80?",
  ui_story_1015_10151302_56_dialog_content = "Ya, aku ingat.",
  ui_story_1015_10151302_57_dialog_content = "Saat itu, saya merevisi informasi yang disampaikan kepada tim individu, dimodifikasi oleh Project Artificial Sun, sesuai kebutuhan Panitia.",
  ui_story_1015_10151302_58_dialog_content = "Kecerdasan palsu itu digunakan untuk membimbing mereka ke dalam pengepungan Eclipsite.",
  ui_story_1015_10151302_59_dialog_content = "Saya masih ingat banyak tim pengintai yang dikompromikan saat itu untuk mendapatkan intelijen yang cukup akurat.",
  ui_story_1015_10151302_60_dialog_content = "Tim bawahan saya adalah salah satunya, dan dia adalah satu-satunya dari timnya yang selamat.",
  ui_story_1015_10151302_61_dialog_content = "Oh, saya pikir saya ingat pernah mendengar ceritanya. Siapa namanya?",
  ui_story_1015_10151302_62_dialog_content = "<color=#FFB400>Anatoli</color>.",
  ui_story_1015_10151302_63_dialog_content = "Ah, ya, itu namanya. Saya mendengar bahwa Anda baru saja mempromosikannya menjadi wakil Reinhardt?",
  ui_story_1015_10151302_64_dialog_content = "Apakah dia tahu tentang masalah ini? Lebih penting lagi, apakah dia cukup andal untuk memantau tindakan Reinhard?",
  ui_story_1015_10151302_65_dialog_content = "Saya percaya dia dapat dipercaya dalam kemampuannya untuk mengumpulkan intelijen.",
  ui_story_1015_10151302_66_dialog_content = "Apalagi tugas ini sendiri merupakan ujian atas kesetiaannya.",
  ui_story_1015_10151302_67_dialog_content = "Jika Anda yakin itu benar, lanjutkan dan lakukan seperti itu.",
  ui_story_1015_10151302_68_dialog_content = "Kami sudah keluar dari topik. Mari kita bicara tentang Undercity 80.",
  ui_story_1015_10151302_69_dialog_content = "Pertempuran itu adalah pemutaran subjek yang dimodifikasi.",
  ui_story_1015_10151302_70_dialog_content = "Dengan sengaja memimpin mereka ke dalam perjuangan putus asa, memungkinkan mereka untuk mendorong Lumina mereka hingga batasnya, dan kemudian...",
  ui_story_1015_10151302_71_dialog_content = "Individu yang lebih lemah langsung dieliminasi.",
  ui_story_1015_10151302_72_dialog_content = "Individu dengan cacat mental dan ketidakstabilan juga bisa kehilangan kendali dan akhirnya tersingkir dalam situasi ekstrim seperti itu.",
  ui_story_1015_10151302_73_dialog_content = "Tetapi subjek yang berhasil bertahan dari pertempuran sengit ini dan selamat.",
  ui_story_1015_10151302_74_dialog_content = "Tapi... bukankah justru karena tingkat keberhasilannya sangat rendah sehingga proyek itu akhirnya dibatalkan?",
  ui_story_1015_10151302_75_dialog_content = "Sampai Illumina mendapatkan Chord Link yang tidak lengkap itu.",
  ui_story_1015_10151302_76_dialog_content = "Benar, Project Artificial Sun tidak akan dimulai ulang.",
  ui_story_1015_10151302_77_dialog_content = "Tapi Chord Link itu menandai titik balik.",
  ui_story_1015_10151302_78_dialog_content = "Chord Link adalah puncak teknologi Caelestite, mewakili sumber daya baru yang berbeda dari Project Artificial Sun.",
  ui_story_1015_10151302_79_dialog_content = "Dengan mengintegrasikan kedua teknologi ini, lahirlah subjek uji Program Phospherus.",
  ui_story_1015_10151302_80_dialog_content = "Aurorian yang dimodifikasi oleh Program Phospherus memiliki kekuatan yang berasal dari dua teknologi berbeda ini di dalam tubuh mereka.",
  ui_story_1015_10151302_81_dialog_content = "Kedua kekuatan ini saling mengimbangi dan, sampai batas tertentu, meningkatkan tingkat keberhasilan peningkatan.",
  ui_story_1015_10151302_82_dialog_content = "Namun, keseimbangannya tidak cukup stabil, sehingga sebagian besar Aurorian yang dimodifikasi oleh Program Fosfer sangat rapuh.",
  ui_story_1015_10151302_83_dialog_content = "Begitu kekuatan mereka yang luar biasa digunakan secara berlebihan, keseimbangan halus antara kedua kekuatan itu dapat dengan mudah dipatahkan.",
  ui_story_1015_10151302_84_dialog_content = "Dan tubuh mereka juga akan runtuh bersamanya.",
  ui_story_1015_10151302_85_dialog_content = "Axelia adalah contoh yang sangat baik dari ini.",
  ui_story_1015_10151302_86_dialog_content = "Tapi kali ini berbeda. Forsakin menghasilkan kekuatan baru, dan penelitiannya dapat membawa eksperimen tersebut ke tingkat yang lebih tinggi.",
  ui_story_1015_10151302_87_dialog_content = "Maksudmu... yang <color=#FFB400>benih</color>?",
  ui_story_1015_10151302_88_dialog_content = "Benar.",
  ui_story_1015_10151302_89_dialog_content = "Forsakin telah mempelajari benih selama bertahun-tahun, dan itu telah menjadi pencapaian puncak teknologi Eclipsite.",
  ui_story_1015_10151302_90_dialog_content = "Benih akan menjadi bagian terakhir dari teka-teki, dan Forsakin adalah satu-satunya yang mampu menempatkannya.",
  ui_story_1015_10151302_91_dialog_content = "Pada akhirnya, ketiga kekuatan ini akan membentuk keseluruhan yang seimbang di dalam tubuh Aurorian, menjadi kekuatan yang baru dan stabil.",
  ui_story_1015_10151302_92_dialog_content = "…!",
  ui_story_1015_10151302_93_dialog_content = "Adapun hasil tes pertama yang krusial, kita hanya bisa menunggu dan melihat.",
  ui_story_1015_10151302_94_dialog_content = "<color=#e8d9bb>Sementara itu di Laboratorium Tautan Chord Federasi Illumina</color>",
  ui_story_1015_10151302_95_dialog_content = "<color=#e8d9bb>Der, der!</color>",
  ui_story_1015_10151302_96_dialog_content = "Berisik.",
  ui_story_1015_10151302_97_dialog_content = "Meskipun lingkungan ini hampir tidak cocok untuk percobaan ini, itu sudah cukup.",
  ui_story_1015_10151302_98_dialog_content = "Memulai pemeriksaan parameter akhir.",
  ui_story_1015_10151302_99_dialog_content = "Semua parameter diverifikasi akurat.",
  ui_story_1015_10151302_100_dialog_content = "Saatnya menambahkan bahan percobaan akhir.",
  ui_story_1015_10151302_101_dialog_content = "Mari kita mulai eksperimennya.",
  ui_story_1015_10151302_102_dialog_content = "Benih akan memandu arah evolusi.",
  ui_story_1015_10151302_103_dialog_content = "<color=#e8d9bb>Di luar Laboratorium Chord Link</color>",
  ui_story_1015_10151302_104_dialog_content = "Ice Blossom! Menyebar!",
  ui_story_1015_10151302_105_dialog_content = "<color=#e8d9bb>Gedebuk-!!!</color>",
  ui_story_1015_10151302_106_dialog_content = "Bahkan setelah mengalami ledakan dan begitu banyak hantaman, sepertinya kami tidak bisa membuat satu penyok pun di pintu ini.",
  ui_story_1015_10151302_107_dialog_content = "Tampaknya masuk paksa bukan lagi pilihan yang layak.",
  ui_story_1015_10151302_108_dialog_content = "Lagi pula, bahan tahan ledakan terkuat yang pernah ada digunakan selama pembangunan fasilitas ini.",
  ui_story_1015_10151302_109_dialog_content = "Fitur yang semula ditujukan untuk mencegah potensi kebakaran kini menjadi kendala.",
  ui_story_1015_10151302_110_dialog_content = "Chord Link di belakang pintu ini kemungkinan besar merupakan bagian penting dari eksperimen Forsakin.",
  ui_story_1015_10151302_111_dialog_content = "Jika dia dibiarkan menggunakannya secara sembarangan, itu akan menyebabkan lebih banyak masalah di masa depan.",
  ui_story_1015_10151302_112_dialog_content = "Ya, kita harus segera menghentikannya!",
  ui_story_1015_10151302_113_dialog_content = "Apakah tidak ada yang bisa kita lakukan?",
  ui_story_1015_10151302_114_dialog_content = "Coba kuingat...",
  ui_story_1015_10151302_115_dialog_content = "Mungkin ada jalan.",
  ui_story_1015_10151302_116_dialog_content = "Ada apa?",
  ui_story_1015_10151302_117_dialog_content = "Undercity ini dulunya adalah laboratorium rahasia Forsakin. Oleh karena itu, sejumlah besar subjek tes yang gagal dibuang di sini setiap hari.",
  ui_story_1015_10151302_118_dialog_content = "Untuk menghemat waktu, dia membangun saluran pipa dari laboratorium ke ruang pengolahan limbah di ruang bawah tanah.",
  ui_story_1015_10151302_119_dialog_content = "Selama rekonstruksi Undercity, jalur pipa ini disegel di dalam dinding tetapi tidak dibongkar.",
  ui_story_1015_10151302_120_dialog_content = "Meskipun ini tampak seperti jalan memutar yang sangat besar, mendobrak dinding dan menyegel pipa akan jauh lebih mudah daripada mendobrak pintu ini.",
  ui_story_1015_10151302_121_dialog_content = "Kita bisa menggunakan jalan pintas yang dia gunakan sebagai saluran pembuangan sampah untuk melompatinya.",
  ui_story_1015_10151401_1_dialog_content = "Ini adalah bagian terlemah dari tembok!",
  ui_story_1015_10151401_2_dialog_content = "<color=#e8d9bb>Dor! Dor!</color>",
  ui_story_1015_10151401_3_dialog_content = "<color=#e8d9bb>Gruk!</color>",
  ui_story_1015_10151401_4_dialog_content = "Parasutnya terbuka!",
  ui_story_1015_10151401_5_dialog_content = "Berhenti di sana, Forsakin!",
  ui_story_1015_10151401_6_dialog_content = "Kami telah mengalahkan semua Eclipsites di bawah komandomu!",
  ui_story_1015_10151401_7_dialog_content = "Anda terlambat.",
  ui_story_1015_10151401_8_dialog_content = "Eksperimen saya telah membuahkan hasil.",
  ui_story_1015_10151401_9_dialog_content = "<color=#e8d9bb>Ngungg!</color>",
  ui_story_1015_10151401_10_dialog_content = "PlayerName, Lihat! Tautan Kord!",
  ui_story_1015_10151401_11_dialog_content = "Sesuatu sepertinya muncul dari dalamnya!",
  ui_story_1015_10151401_12_dialog_content = "Apa... Apa ini?!",
  ui_story_1015_10151401_13_dialog_content = "Monster macam apa ini?!",
  ui_story_1015_10151401_14_dialog_content = "Catatan lab dari eksperimen ke-112 pada subjek uji Helios—",
  ui_story_1015_10151401_15_dialog_content = "Proses eksperimen: saat menggunakan Chord Link untuk menyempurnakan subjek Project Artificial Sun—",
  ui_story_1015_10151401_16_dialog_content = "Benih telah ditambahkan ke Tautan Chord.",
  ui_story_1015_10151401_17_dialog_content = "Hasil eksperimen: eksperimen awalnya berhasil, dan risiko penghentian aktivitas subjek berkurang secara signifikan.",
  ui_story_1015_10151401_18_dialog_content = "Dia merekam eksperimennya?",
  ui_story_1015_10151401_19_dialog_content = "Dia secara pribadi mengubah mantan rekannya menjadi monster ini, dan masih memiliki pikiran yang tidak berperasaan untuk menyelesaikan catatan percobaan ...",
  ui_story_1015_10151401_20_dialog_content = "Petugas Ulysses benar—kau benar-benar hewan berdarah dingin.",
  ui_story_1015_10151401_21_dialog_content = "Ulysses?",
  ui_story_1015_10151401_22_dialog_content = "Orang tua itu mungkin lebih menantikan hasil percobaan ini daripada saya.",
  ui_story_1015_10151401_23_dialog_content = "Apa katamu?",
  ui_story_1015_10151401_24_dialog_content = "Saatnya melanjutkan eksperimen berikutnya.",
  ui_story_1015_10151401_25_dialog_content = "Memverifikasi stabilitas subjek melalui pertempuran yang sebenarnya.",
  ui_story_1015_10151401_26_dialog_content = "Silakan, subjek tes, pisahkan mereka.",
  ui_story_1015_10151401_27_dialog_content = "!!!",
  ui_story_1015_10151401_28_dialog_content = "PlayerName, temukan tempat untuk bersembunyi!",
  ui_story_1015_10151401_29_dialog_content = "B-baiklah!",
  ui_story_1015_10151401_30_dialog_content = "...",
  ui_story_1015_10151401_31_dialog_content = "(Monster itu tidak merespon? Apakah itu berarti eksperimen Forsakin gagal?)",
  ui_story_1015_10151401_32_dialog_content = "Begitu ya, sepertinya eksperimenku telah mencapai kesuksesan lebih jauh.",
  ui_story_1015_10151401_33_dialog_content = "(Sukses lebih lanjut? Apa maksudnya?)",
  ui_story_1015_10151401_34_dialog_content = "Memang, tampaknya diperlukan pendekatan yang berbeda.",
  ui_story_1015_10151401_35_dialog_content = "Helios, Prajurit Illumina—",
  ui_story_1015_10151401_36_dialog_content = "…!",
  ui_story_1015_10151401_37_dialog_content = "Dia bereaksi! Mungkinkah dia benar-benar mengerti?!",
  ui_story_1015_10151401_38_dialog_content = "Berdiri di depan Anda sekarang adalah pengkhianat dan musuh Federasi Illumina.",
  ui_story_1015_10151401_39_dialog_content = "Misi Anda adalah melenyapkan mereka.",
  ui_story_1015_10151401_40_dialog_content = "<anim type=Shake><size=50>Aahhhhhhhh!</size></anim>",
  ui_story_1015_10151401_41_dialog_content = "Tunggu! Berhenti!",
  ui_story_1015_10151401_42_dialog_content = "Kami bukan musuhmu! Forsakin adalah pengkhianat dan musuh Illumina!",
  ui_story_1015_10151401_43_dialog_content = "<anim type=Shake><size=50>Keren!!!</size></anim>",
  ui_story_1015_10151401_44_dialog_content = "Argh!",
  ui_story_1015_10151401_45_dialog_content = "Tidak ada gunanya... Tampaknya belum sepenuhnya mendapatkan kembali kewarasannya.",
  ui_story_1015_10151401_46_dialog_content = "Mari kita turunkan dulu.",
  ui_story_1015_10151402_1_dialog_content = "<anim type=Shake><size=50>Aahhhhhhhh!</size></anim>",
  ui_story_1015_10151402_2_dialog_content = "Bagaimana dia menjadi begitu kuat...?",
  ui_story_1015_10151402_3_dialog_content = "Tidak hanya lebih kuat, tindakannya juga menjadi lebih tidak terduga.",
  ui_story_1015_10151402_4_dialog_content = "Semuanya, hati-hati!",
  ui_story_1015_10151402_5_dialog_content = "Jika dia hanya melakukan serangan balik secara naluriah sebelumnya, sepertinya dia sekarang mulai menggunakan taktik.",
  ui_story_1015_10151402_6_dialog_content = "Apakah monster ini sudah belajar menyusun strategi?",
  ui_story_1015_10151402_7_dialog_content = "Situasi telah berubah menjadi sulit...",
  ui_story_1015_10151402_8_dialog_content = "Eksperimen itu memang mencapai kesuksesan lebih lanjut. Teori saya benar.",
  ui_story_1015_10151402_9_dialog_content = "Tiga kekuatan berbeda yang berinteraksi dalam subjek uji telah membentuk keadaan stabil.",
  ui_story_1015_10151402_10_dialog_content = "Bahkan selama pertempuran intensitas tinggi, keseimbangan tetap terjaga.",
  ui_story_1015_10151402_11_dialog_content = "Dan poin terpenting adalah eksperimen ini dapat direplikasi.",
  ui_story_1015_10151402_12_dialog_content = "Sekarang, yang perlu saya lakukan hanyalah memverifikasi hasil akhir untuk membuktikan bahwa percobaan itu benar-benar berhasil.",
  ui_story_1015_10151402_13_dialog_content = "<anim type=Shake>Groar…</anim>",
  ui_story_1015_10151402_14_dialog_content = "Hati-hati—ada yang salah dengannya!",
  ui_story_1015_10151402_15_dialog_content = "Apakah itu Lumina atau Darkflow? Ketika mereka bercampur seperti itu, aku bahkan tidak bisa membedakannya!",
  ui_story_1015_10151402_16_dialog_content = "Jangan khawatir tentang itu sekarang, bersiaplah untuk bertahan!",
  ui_story_1015_10151402_17_dialog_content = "<anim type=Shake><size=50>Aahhhh!</size></anim>",
  ui_story_1015_10151402_18_dialog_content = "Apa ini?!",
  ui_story_1015_10151402_19_dialog_content = "Apakah penampilannya baru saja berubah ?!",
  ui_story_1015_10151402_20_dialog_content = "Aku pernah melihat ini sebelumnya, dalam fragmen ingatan yang kurasakan di Undercity 80...",
  ui_story_1015_10151402_21_dialog_content = "Seperti inilah dia awalnya!",
  ui_story_1015_10151402_22_dialog_content = "Langkah ini akhirnya tercapai.",
  ui_story_1015_10151402_23_dialog_content = "Hasil percobaan akhir juga telah diverifikasi.",
  ui_story_1015_10151402_24_dialog_content = "Keadaan stabil membawa manfaat yang lebih besar, karena membuat daya ini dapat dikendalikan.",
  ui_story_1015_10151402_25_dialog_content = "Itu dapat mengekang efek samping dari Project Artificial Sun, yang menyebabkan Aurorian kehilangan kewarasannya dan menjadi monster.",
  ui_story_1015_10151402_26_dialog_content = "Pada saat yang sama, itu juga memungkinkan Aurorian mengubah bentuknya secara mandiri.",
  ui_story_1015_10151402_27_dialog_content = "Inilah yang saya harapkan untuk dicapai.",
  ui_story_1015_10151402_28_dialog_content = "<anim type=Shake>Argh…</anim>",
  ui_story_1015_10151402_29_dialog_content = "<anim type=Shake>Dimana saya...?</anim>",
  ui_story_1015_10151402_30_dialog_content = "D-Dia bisa bicara?!",
  ui_story_1015_10151402_31_dialog_content = "Tidak... tidak... Mengapa... saya tidak berada di Undercity 80?",
  ui_story_1015_10151402_32_dialog_content = "Siapa kamu?",
  ui_story_1015_10151402_33_dialog_content = "Dia sebenarnya telah dikembalikan ke bentuk Auroriannya... Apakah kewarasannya juga telah dipulihkan?",
  ui_story_1015_10151402_34_dialog_content = "Saya Yingel, seorang perwira intelijen yang bekerja langsung di bawah wewenang Komite.",
  ui_story_1015_10151402_35_dialog_content = "Kapten Helios, Anda dicurigai berkolusi dengan musuh... berkolaborasi dengan Eclipsites.",
  ui_story_1015_10151402_36_dialog_content = "Segera letakkan senjatamu, hentikan perlawananmu, dan bekerja samalah dengan penyelidikan Komite!",
  ui_story_1015_10151402_37_dialog_content = "Tidak, saya tidak...",
  ui_story_1015_10151402_38_dialog_content = "Bagaimana...mungkin aku berkolusi dengan musuh?",
  ui_story_1015_10151402_39_dialog_content = "I MI...",
  ui_story_1015_10151402_40_dialog_content = "Tenang, Kapten Helios!",
  ui_story_1015_10151402_41_dialog_content = "Lihatlah sekelilingmu. Ini bukan Undercity 80.",
  ui_story_1015_10151402_42_dialog_content = "Anda tidak perlu bertarung lagi ...",
  ui_story_1015_10151402_43_dialog_content = "Apa yang telah terjadi? Kenapa saya disini?",
  ui_story_1015_10151402_44_dialog_content = "Kenapa... aku tidak ingat...?",
  ui_story_1015_10151402_45_dialog_content = "Argh...!",
  ui_story_1015_10151402_46_dialog_content = "Kemampuan kognitif subjek utuh, tetapi ingatannya tampak tidak teratur dan tidak lengkap. Tidak ada ingatan baru yang terbentuk setelah kehilangan kendali.",
  ui_story_1015_10151402_47_dialog_content = "Dicatat sementara sebagai efek samping yang membutuhkan perhatian. Studi lebih lanjut diperlukan untuk sepenuhnya menghilangkan efek samping ini.",
  ui_story_1015_10151402_48_dialog_content = "Tentu saja, ada kemungkinan lebih besar bahwa situasi ini disebabkan oleh cacat pada subjek itu sendiri.",
  ui_story_1015_10151402_49_dialog_content = "Secara keseluruhan, percobaan berhasil.",
  ui_story_1015_10151402_50_dialog_content = "Saya akhirnya menguasai proses evolusi.",
  ui_story_1015_10151402_51_dialog_content = "Hanya satu pertanyaan yang tersisa...",
  ui_story_1015_10151402_52_dialog_content = "(Subjek tes ini akan diperlukan untuk verifikasi selanjutnya.)",
  ui_story_1015_10151402_53_dialog_content = "(Saya perlu memikirkan cara untuk membuatnya ikut dengan saya.)",
  ui_story_1015_10151402_54_dialog_content = "(Namun, dia secara bertahap mendapatkan kembali kesadaran dan kognisi — variabel yang tidak kondusif untuk rencanaku.)",
  ui_story_1015_10151402_55_dialog_content = "(Namun, ada cara untuk menghadapi subjek tes berpikiran sederhana semacam ini.)",
  ui_story_1015_10151402_56_dialog_content = "Kamu... aku mengenalimu...",
  ui_story_1015_10151402_57_dialog_content = "Kau... Denier?",
  ui_story_1015_10151402_58_dialog_content = "Kenapa kamu... terlihat seperti itu...?",
  ui_story_1015_10151402_59_dialog_content = "Dimana... Reinhardt...?",
  ui_story_1015_10151402_60_dialog_content = "Kenapa dia... tidak bersamamu...?",
  ui_story_1015_10151402_61_dialog_content = "...",
  ui_story_1015_10151402_62_dialog_content = "Baik Denier maupun dirimu yang dulu telah lama ditinggalkan oleh Illumina.",
  ui_story_1015_10151402_63_dialog_content = "Saya bukan Denier.",
  ui_story_1015_10151402_64_dialog_content = "Ditinggalkan?",
  ui_story_1015_10151402_65_dialog_content = "<anim type=Shake>Urgh...!!!</anim>",
  ui_story_1015_10151402_66_dialog_content = "Dia mengumpulkan Darkflow!",
  ui_story_1015_10151402_67_dialog_content = "Apakah Forsakin mencoba mengganggunya dengan kata-katanya untuk menjerumuskannya ke dalam kekacauan lagi dan membuatnya menjadi monster?!",
  ui_story_1015_10151402_68_dialog_content = "Semua orang cukup banyak di kaki terakhir mereka karena ...",
  ui_story_1015_10151402_69_dialog_content = "Dengar... Mereka menyebutmu monster.",
  ui_story_1015_10151402_70_dialog_content = "<anim type=Shake>Tidak... aku bukan... aku bukan monster...</anim>",
  ui_story_1015_10151402_71_dialog_content = "<anim type=Shake>Aku... seorang prajurit... dari Illumina...</anim>",
  ui_story_1015_10151402_72_dialog_content = "Cih...",
  ui_story_1015_10151402_73_dialog_content = "Federasi Illumina tidak lagi memiliki tempat untukmu.",
  ui_story_1015_10151402_74_dialog_content = "Ikutlah dengan saya, dan Anda akan memiliki kesempatan untuk bertahan hidup.",
  ui_story_1015_10151402_75_dialog_content = "Tetaplah di sini, dan hanya kematian yang akan menunggumu.",
  ui_story_1015_10151402_76_dialog_content = "Jangan percaya padanya! Illumina tidak pernah menyerah pada siapa pun!",
  ui_story_1015_10151402_77_dialog_content = "Federasi Illumina mengabaikan mereka yang tidak dapat berkontribusi lebih jauh untuk tujuannya, terutama mereka yang gagal.",
  ui_story_1015_10151402_78_dialog_content = "Marsekal Agung Reinhardt tidak pernah menyerah mencarimu.",
  ui_story_1015_10151402_79_dialog_content = "Reinhardt tidak pernah kembali dengan bala bantuan.",
  ui_story_1015_10151402_80_dialog_content = "Dia tidak punya suara dalam masalah ini! Petugas Illumina membiusnya sehingga dia tidak berdaya untuk menyelamatkanmu!",
  ui_story_1015_10151402_81_dialog_content = "Saya melihat itu semua dengan kemampuan psikis saya. Saya tahu itu benar sekali!",
  ui_story_1015_10151402_82_dialog_content = "Jangan lupa, di Undercity 80, Reinhardt berhadapan dengan kami, belati terhunus.",
  ui_story_1015_10151402_83_dialog_content = "Buka matamu dan lihat. Mantan temanmu bukan lagi seorang Aurorian.",
  ui_story_1015_10151402_84_dialog_content = "Dia yang berlumuran darah!",
  ui_story_1015_10151402_85_dialog_content = "Apakah Anda tidak membenci orang-orang munafik ini?",
  ui_story_1015_10151402_86_dialog_content = "<size=45>Tenang, kamu!</size>",
  ui_story_1015_10151402_87_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_1015_10151402_88_dialog_content = "<anim type=Shake><size=50>Urgh!!!</size></anim>",
  ui_story_1015_10151402_89_dialog_content = "Mengapa-!",
  ui_story_1015_10151402_90_dialog_content = "… Apa yang kaulakukan?",
  ui_story_1015_10151402_91_dialog_content = "Saya... seorang prajurit... dari Illumina...",
  ui_story_1015_10151402_92_dialog_content = "Aku akan bekerja sama... dengan penyelidikan...",
  ui_story_1015_10151402_93_dialog_content = "Tapi aku juga...ingin melindungi temanku...",
  ui_story_1015_10151402_94_dialog_content = "...",
  ui_story_1015_10151402_95_dialog_content = "Betapa bodohnya.",
  ui_story_1015_10151402_96_dialog_content = "Tampaknya persepsi subjek tentang dirinya sendiri dan orang lain cacat.",
  ui_story_1015_10151402_97_dialog_content = "Ini mungkin semacam gangguan mental. Kognisi yang salah ini harus diberantas sepenuhnya.",
  ui_story_1015_10151402_98_dialog_content = "Ini...",
  ui_story_1015_10151402_99_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1015_10151402_100_dialog_content = "A-Apa itu tadi?!",
  ui_story_1015_10151402_101_dialog_content = "Kembali, PlayerName! Sebuah lubang besar muncul di pintu!",
  ui_story_1015_10151402_102_dialog_content = "Sesuatu yang sangat kuat sedang menerobos pintu!",
  ui_story_1015_10151402_103_dialog_content = "Astaga!!!",
  ui_story_1015_10151402_104_dialog_content = "<color=#e8d9bb>Duarr!!!</color>",
  ui_story_1015_10151402_105_dialog_content = "Itu deskripsi yang akurat, tapi itu bukan sesuatu—itu hanya aku.",
  ui_story_1015_10151402_106_dialog_content = "Jadi, Anda sebenarnya ada di sini, Forsakin.",
  ui_story_1015_10151402_107_dialog_content = "Tepat pada isyarat.",
  ui_story_1015_10151402_108_dialog_content = "Kita bertemu lagi, Reinhardt. Bahkan setelah sekian lama, Anda belum membuat kemajuan apapun.",
  ui_story_1015_10151402_109_dialog_content = "Masih rela digunakan.",
  ui_story_1015_10151402_110_dialog_content = "Lama tidak bertemu, Forsakin.",
  ui_story_1015_10151402_111_dialog_content = "Sepertinya Anda sendiri belum melakukannya dengan baik dengan Eclipsites. Dan sekarang, Anda bahkan telah jatuh ke posisi terendah terbaru ini.",
  ui_story_1015_10151402_112_dialog_content = "Hmm? Siapa namamu? Wra...?",
  ui_story_1015_10151402_113_dialog_content = "Pemain kecil yang mengandalkan teman lama untuk mengamankan posisinya tidak perlu diingat.",
  ui_story_1015_10151402_114_dialog_content = "Apakah itu seharusnya menjadi penghinaan? Anda pasti salah mengira saya sebagai seseorang yang peduli.",
  ui_story_1015_10151402_115_dialog_content = "Saat aku menjatuhkanmu ke tanah nanti, jangan menangis mencari adikmu.",
  ui_story_1015_10151402_116_dialog_content = "Betapa tidak dewasa.",
  ui_story_1015_10151402_117_dialog_content = "Apakah itu... Reinhardt?",
  ui_story_1015_10151402_118_dialog_content = "Helios?! Penampilanmu...",
  ui_story_1015_10151402_119_dialog_content = "Apakah ini... bala bantuan? Anda akhirnya...",
  ui_story_1015_10151402_120_dialog_content = "...",
  ui_story_1015_10151402_121_dialog_content = "Ya, saya minta maaf karena terlambat.",
  ui_story_1015_10151402_122_dialog_content = "Aku datang untuk menjemputmu, dan aku membawa bala bantuan.",
  ui_story_1015_10151402_123_dialog_content = "Amankan tempat ini!",
  ui_story_1015_10151402_124_dialog_content = "Siap, Kapten!",
  ui_story_1015_10151402_125_dialog_content = "Persis seperti yang saya perkirakan.",
  ui_story_1015_10151402_126_dialog_content = "Reinhardt, mari kita buat kesepakatan.",
  ui_story_1015_10151402_127_dialog_content = "Apa...?",
  ui_story_1015_10151402_128_dialog_content = "Mengizinkan saya dan subjek tes saya meninggalkan Illumina tidak akan berdampak buruk pada Anda.",
  ui_story_1015_10151402_129_dialog_content = "Hah? Mungkin Anda sudah terlalu lama berada di Malam Abadi. Sepertinya Darkflow masuk ke otakmu.",
  ui_story_1015_10151402_130_dialog_content = "Anda tidak dalam posisi untuk bernegosiasi dengan kami sekarang.",
  ui_story_1015_10151402_131_dialog_content = "Saya tidak bernegosiasi dengan Anda.",
  ui_story_1015_10151402_132_dialog_content = "Fosil tua itu tidak menginginkanku, mereka menginginkannya.",
  ui_story_1015_10151402_133_dialog_content = "(Apa maksudnya? Komite menginginkan Helios?)",
  ui_story_1015_10151402_134_dialog_content = "(Tapi misi saya hanya untuk menangkap Forsakin dan menyelamatkan Letnan Vice.)",
  ui_story_1015_10151402_135_dialog_content = "Anda tahu persis apa yang akan terjadi jika dia jatuh ke tangan orang-orang itu.",
  ui_story_1015_10151402_136_dialog_content = "Saya tidak bisa menyetujui permintaan Anda.",
  ui_story_1015_10151402_137_dialog_content = "Saya akan memilih untuk mempercayai Anda jika itu lebih dari satu dekade yang lalu, sebelum Anda meninggalkan Illumina.",
  ui_story_1015_10151402_138_dialog_content = "Tapi setelah bertahun-tahun berjuang, aku mengenalmu lebih baik dari siapa pun.",
  ui_story_1015_10151402_139_dialog_content = "Apa yang ingin Anda lakukan tidak berbeda dengan apa yang mereka inginkan.",
  ui_story_1015_10151402_140_dialog_content = "Serahkan dia padaku, dan aku akan menggunakan statusku sebagai Grand Marshal untuk melindunginya. Saya tidak akan membiarkan siapa pun menyentuhnya.",
  ui_story_1015_10151402_141_dialog_content = "Anda tidak memiliki kekuatan.",
  ui_story_1015_10151402_142_dialog_content = "Negosiasi ini tidak ke mana-mana. Saya tidak perlu membuang waktu lagi di sini.",
  ui_story_1015_10151402_143_dialog_content = "Giok.",
  ui_story_1015_10151402_144_dialog_content = "<anim type=Shake><size=50>Graaaaaah!</size></anim>",
  ui_story_1015_10151402_145_dialog_content = "Selamat tinggal.",
  ui_story_1015_10151402_146_dialog_content = "<color=#e8d9bb>Fwooosh!!!</color>",
  ui_story_1015_10151501_1_dialog_content = "Melapor masuk. Menurut intelijen yang disampaikan oleh Kolonel Yingel dan Mayor Anatoli, kami menemukan Letnan Vice di laboratorium terbengkalai.",
  ui_story_1015_10151501_2_dialog_content = "Letnan Vice, kembali bertugas!",
  ui_story_1015_10151501_3_dialog_content = "Vice! Apakah kamu baik-baik saja? Apakah Anda terluka?",
  ui_story_1015_10151501_4_dialog_content = "Aku baik-baik saja!",
  ui_story_1015_10151501_5_dialog_content = "Maaf aku sangat ceroboh dan menyebabkan begitu banyak masalah bagi semua orang...",
  ui_story_1015_10151501_6_dialog_content = "Selama Anda kembali, aman dan sehat, maka semuanya baik-baik saja.",
  ui_story_1015_10151501_7_dialog_content = "Itu benar. Jangan terlalu keras pada diri sendiri.",
  ui_story_1015_10151501_8_dialog_content = "Forsakin adalah musuh yang licik. Butuh semua upaya bersama kami untuk menghadapinya.",
  ui_story_1015_10151501_9_dialog_content = "Oke…",
  ui_story_1015_10151501_10_dialog_content = "Bagaimana pencariannya? Apakah Anda menemukan jejak Forsakin?",
  ui_story_1015_10151501_11_dialog_content = "Melaporkan! Kami telah mencari di seluruh Undercity dan tidak menemukan jejak Forsakin.",
  ui_story_1015_10151501_12_dialog_content = "Bagaimana dengan berbagai pintu masuk dan keluar, dan bagian dari Undercity lama?",
  ui_story_1015_10151501_13_dialog_content = "Setiap pintu masuk dan keluar dijaga, dan tidak ada yang terlihat masuk atau keluar.",
  ui_story_1015_10151501_14_dialog_content = "Jadi begitu. Namun, kita tidak bisa terlalu yakin. Lanjutkan pencarian.",
  ui_story_1015_10151501_15_dialog_content = "Siap, Kapten!",
  ui_story_1015_10151501_16_dialog_content = "Forsakin benar-benar berhasil menghilang dari bawah hidung kita bahkan tanpa berkeringat.",
  ui_story_1015_10151501_17_dialog_content = "Dia memuntahkan racunnya dan berlari seperti angin.",
  ui_story_1015_10151501_18_dialog_content = "Marsekal Agung, Kapten Wrath—Saya pikir saya mungkin tahu bagaimana Forsakin melarikan diri.",
  ui_story_1015_10151501_19_dialog_content = "Hmm? Beritahu kami.",
  ui_story_1015_10151501_20_dialog_content = "Forsakin merancang dan membangun Undercity ini.",
  ui_story_1015_10151501_21_dialog_content = "Setelah membangun Undercity dan sebelum membelot dari Federasi Illumina, Forsakin diam-diam melakukan perjalanan antara sini dan Kota Gannon berkali-kali.",
  ui_story_1015_10151501_22_dialog_content = "Menurut intelijen yang saya kumpulkan, Forsakin adalah seseorang yang tidak tahan membuang-buang waktu untuk hal-hal yang tidak berguna.",
  ui_story_1015_10151501_23_dialog_content = "Jadi saya berspekulasi bahwa dia mungkin juga membangun jalan rahasia yang dapat digunakan untuk melakukan perjalanan cepat antara sini dan Kota Gannon.",
  ui_story_1015_10151501_24_dialog_content = "Apakah Anda mengatakan bahwa dia mungkin sudah melarikan diri ke Gannon?",
  ui_story_1015_10151501_25_dialog_content = "Ya.",
  ui_story_1015_10151501_26_dialog_content = "Hm, itu masuk akal. Saya akan segera mengatur pencarian Kota Gannon untuk diselidiki.",
  ui_story_1015_10151501_27_dialog_content = "Reinhardt, biarkan aku menangani ini.",
  ui_story_1015_10151501_28_dialog_content = "Tidak, karena masalah ini terkait dengan Forsakin dan Helios, saya harus mengambilnya sendiri.",
  ui_story_1015_10151501_29_dialog_content = "Tepat sekali karena ini menyangkut dua hal itu, sehingga Anda tidak bisa diminta untuk mengurusnya.",
  ui_story_1015_10151501_30_dialog_content = "Komite menugaskan misi ini kepadaku, jadi akulah yang harus memastikannya selesai.",
  ui_story_1015_10151501_31_dialog_content = "Juga, target kami adalah kakakmu dan mantan rekanmu...",
  ui_story_1015_10151501_32_dialog_content = "Bahkan jika saya yakin Anda dapat menangani kekacauan ini dengan adil, ada orang yang tidak begitu percaya.",
  ui_story_1015_10151501_33_dialog_content = "Siapa pun yang memiliki mata dapat melihat bahwa mereka telah mencoba mencari alasan untuk mengacaukan Anda baru-baru ini.",
  ui_story_1015_10151501_34_dialog_content = "Dan Latihan Militer Gabungan akan segera dimulai. Semua kekuatan Astra akan memusatkan perhatian pada Illumina.",
  ui_story_1015_10151501_35_dialog_content = "Yang perlu Anda lakukan sekarang hanyalah kembali ke Gannon.",
  ui_story_1015_10151501_36_dialog_content = "Tidak hanya mengembalikan bantuan untuk menstabilkan situasi dan mengamankan otoritas Anda ...",
  ui_story_1015_10151501_37_dialog_content = "Selama Anda yang bertanggung jawab, bahkan jika Forsakin benar-benar ada di Gannon, dia tidak akan berani menimbulkan masalah.",
  ui_story_1015_10151501_38_dialog_content = "...",
  ui_story_1015_10151501_39_dialog_content = "Jika Anda tidak mempercayai saya, Anda dapat mengirim penyelia untuk mengawasi saya atau sesuatu. Saya bahkan tidak keberatan jika banyak supervisor mengawasi saya—semakin banyak semakin meriah.",
  ui_story_1015_10151501_40_dialog_content = "Seperti yang selalu saya katakan, saya hanya tertarik untuk mengalahkan Anda secara adil dan jujur.",
  ui_story_1015_10151501_41_dialog_content = "Begitulah selalu, bagaimana itu, dan bagaimana itu akan selalu.",
  ui_story_1015_10151501_42_dialog_content = "Saya percaya padamu.",
  ui_story_1015_10151501_43_dialog_content = "Saya akan meninggalkan tugas mengejar Forsakin dan membawa kembali Helios ke tangan Anda.",
  ui_story_1015_10151501_44_dialog_content = "Jangan khawatir, aku berjanji akan menemukan mereka.",
  ui_story_1015_10151501_45_dialog_content = "Nah, sekarang sudah beres, mengapa kalian semua tidak kembali ke Kota Gannon bersamaku? Apa yang kamu katakan, PlayerName?",
  ui_story_1015_10151501_46_dialog_content = "Tapi, misi...",
  ui_story_1015_10151501_47_dialog_content = "Karena Panitia mempercayakan hal ini kepada Kapten Wrath, Anda tidak perlu lagi khawatir tentang itu.",
  ui_story_1015_10151501_48_dialog_content = "Mari kita selesaikan masalah ini terlebih dahulu.",
  ui_story_1015_10151501_49_dialog_content = "Siap, Kapten.",
  ui_story_1015_10151501_50_dialog_content = "Ya, aku mengerti.",
  ui_story_1015_10151501_51_dialog_content = "<size=30>Memang, masih banyak yang harus kulakukan untuk membantumu merencanakan jadwal Grand Marshal untuk periode latihan, serta—</size>",
  ui_story_1015_10151501_52_dialog_content = "Anatoli.",
  ui_story_1015_10151501_53_dialog_content = "<size=45>Bu!</size>",
  ui_story_1015_10151501_54_dialog_content = "Apakah Anda memiliki instruksi tambahan, Grand Marshal?",
  ui_story_1015_10151501_55_dialog_content = "Kau tidak perlu menemaniku lagi. Pergi dan ambil bagian dalam latihan.",
  ui_story_1015_10151501_56_dialog_content = "Ya — tunggu sebentar, Grand Marshal, saya belum bergabung dengan tim mana pun, jadi saya tidak bisa ikut latihan.",
  ui_story_1015_10151501_57_dialog_content = "Anda tidak perlu khawatir tentang itu, salah satu anggota tim memiliki beberapa urusan yang harus dihadiri dan tidak dapat berpartisipasi.",
  ui_story_1015_10151501_58_dialog_content = "Anda akan mengisi tempat itu.",
  ui_story_1015_10151501_59_dialog_content = "Ya Bu. Saya akan berada di tim mana?",
  ui_story_1015_10151501_60_dialog_content = "Anda harus cukup akrab dengannya sekarang. Itu tim Yingel.",
  ui_story_1015_10151501_61_dialog_content = "Apa? Kelompok ku?",
  ui_story_1015_10151501_62_dialog_content = "Apakah sesuatu terjadi pada Axelia?",
  ui_story_1015_10151501_63_dialog_content = "Tidak, itu bukan dia. Itu Sean.",
  ui_story_1015_10151501_64_dialog_content = "Saya baru saja menerima kabar dari Twilight.",
  ui_story_1015_10151501_65_dialog_content = "Rupanya, kondisi fisik Sean tiba-tiba memburuk dan dia harus tinggal di Twilight untuk observasi sementara.",
  ui_story_1015_10151501_66_dialog_content = "Bagaimana dia? Apakah dia baik baik saja?",
  ui_story_1015_10151501_67_dialog_content = "Pesan dari Twilight menyatakan bahwa dia hanya mengalami beberapa fenomena aneh saat menggunakan Luminatics yang belum pernah dia alami sebelumnya.",
  ui_story_1015_10151501_68_dialog_content = "Ini mungkin terkait dengan cacat genetik bawaan.",
  ui_story_1015_10151501_69_dialog_content = "Benarkah...?",
  ui_story_1015_10151501_70_dialog_content = "Setelah kita selesai di Gannon, mari kita pergi ke Twilight dan mengunjunginya.",
  ui_story_1015_10151501_71_dialog_content = "Jadi, Anda ingin saya bekerja sama dengan Yingel Dan Axelia?",
  ui_story_1015_10151501_72_dialog_content = "Saya akan mematuhi perintah Anda.",
  ui_story_1015_10151501_73_dialog_content = "(Ini sedikit menyimpang dari rencana awal, tapi tetap tidak masalah. Aku seharusnya bisa membuat ini berhasil.)",
  ui_story_1015_10151501_74_dialog_content = "Saya juga tidak keberatan.",
  ui_story_1015_10151501_75_dialog_content = "Itu menyelesaikannya kemudian.",
  ui_story_1015_10151501_76_dialog_content = "Saatnya kembali ke Kota Gannon.",
  ui_story_1015_10151501_77_dialog_content = "<color=#e8d9bb>Beberapa hari kemudian, di Kota Gannon...</color>",
  ui_story_1015_10151501_78_dialog_content = "Kereta akan tiba di Gannon. Harap bersiap untuk turun dan perhatikan jarak antara kereta dan peron.",
  ui_story_1015_10151501_79_dialog_content = "May cahaya iluminasi memandu Anda dalam perjalanan Anda.",
  ui_story_1015_10151501_80_dialog_content = "Permisi, biarkan kami turun dari kereta.",
  ui_story_1015_10151501_81_dialog_content = "Banyak sekali orang yang keluar hari ini... Ini benar-benar latihan militer terbesar di Astra!",
  ui_story_1015_10151501_82_dialog_content = "Tapi tempat ini sangat besar... Kita tidak salah jalan, kan? Apakah ini bahkan stasiun yang tepat?",
  ui_story_1015_10151501_83_dialog_content = "Ini seharusnya, sesuai dengan instruksi Lady Carleen.",
  ui_story_1015_10151501_84_dialog_content = "semoga kita tidak tersesat...",
  ui_story_1015_10151501_85_dialog_content = "Beretta.",
  ui_story_1015_10151501_86_dialog_content = "Wanita Carleen!",
  ui_story_1015_10151501_87_dialog_content = "Sesuai kesepakatan, aku di sini untuk menjemputmu.",
  ui_story_1015_10151501_88_dialog_content = "Terima kasih banyak! Tanpa Anda di sini, kami pasti akan tersesat...",
  ui_story_1015_10151501_89_dialog_content = "Jangan sebutkan itu. Ikuti lebih banyak latihan ini dan Anda akan segera terbiasa dengan bidang ini.",
  ui_story_1015_10151501_90_dialog_content = "Ayo.",
  ui_story_1015_10151501_91_dialog_content = "Ya, Nyonya Carleen!",
  ui_story_1015_10151501_92_dialog_content = "Bukankah gadis tadi terlihat seperti itu Lady?",
  ui_story_1015_10151501_93_dialog_content = "Memang, sepertinya memang begitu.",
  ui_story_1015_10151501_94_dialog_content = "Apakah kamu tidak akan menyapa?",
  ui_story_1015_10151501_95_dialog_content = "Hahaha, bukan sekarang.",
  ui_story_1015_10151501_96_dialog_content = "Ada begitu banyak orang di sini. Mari kita tidak menghalangi mereka, eh?",
  ui_story_1015_10151501_97_dialog_content = "Kita masih punya banyak waktu untuk bernostalgia dan saling menyapa sebelum Latihan Gabungan resmi dimulai.",
  ui_story_1015_10151501_98_dialog_content = "Ada benarnya.",
  ui_story_1015_10151501_99_dialog_content = "Terutama ketika rekan satu tim baru kita masih memiliki misi di tangan mereka...",
  ui_story_1015_10151501_100_dialog_content = "Beri jalan, beri jalan.",
  ui_story_1015_10151501_101_dialog_content = "Gagak, ke sini—dan hati-hati jangan sampai menabrak pintu.",
  ui_story_1015_10151501_102_dialog_content = "Aku tahu.",
  ui_story_1015_10151501_103_dialog_content = "Saya benar-benar minta maaf tentang ini ...",
  ui_story_1015_10151501_104_dialog_content = "Jelas akulah yang seharusnya mengurus misi ini, tapi aku benar-benar membutuhkan bantuanmu.",
  ui_story_1015_10151501_105_dialog_content = "Saya pembantu Anda. Adalah tugas saya untuk membantu dan melindungi Anda.",
  ui_story_1015_10151501_106_dialog_content = "Selain itu, jika saya tidak membantu, Anda tidak akan dapat mengirimkan ini ke Kota Gannon sendirian.",
  ui_story_1015_10151501_107_dialog_content = "Itu satu-satunya cara... Lagi pula, aku bukan tipe fisik.",
  ui_story_1015_10151501_108_dialog_content = "Apakah Anda butuh bantuan, ahli taktik Illumina?",
  ui_story_1015_10151501_109_dialog_content = "Itu tidak perlu, kita akan mencapai tujuan kita.",
  ui_story_1015_10151501_110_dialog_content = "Jika aku butuh sesuatu, aku akan melakukannya sendiri untuk mencarimu.",
  ui_story_1015_10151501_111_dialog_content = "Bagus. Tidak perlu malu hanya karena kita belum pernah bekerja sama sebelumnya.",
  ui_story_1015_10151501_112_dialog_content = "Bahkan jika suatu hari Anda memutuskan ingin bergabung dengan Ironthorn Knights, beri tahu saya dan saya berjanji tidak akan keberatan.",
  ui_story_1015_10151501_113_dialog_content = "Anda memiliki selera humor yang tinggi.",
  ui_story_1015_10151501_114_dialog_content = "Jika Anda tidak keberatan, silakan mendaftar dengan Pak Joseph terlebih dahulu.",
  ui_story_1015_10151501_115_dialog_content = "Crow dan aku harus mengantarnya ke pawang sebelum kami bisa mendaftar.",
  ui_story_1015_10151501_116_dialog_content = "Oke, kalau begitu kita lanjutkan.",
  ui_story_1015_10151501_117_dialog_content = "Sampai jumpa lagi, Zhao.",
  ui_story_1015_10151501_118_dialog_content = "...",
  ui_story_1015_10151501_119_dialog_content = "Ada apa, Gagak?",
  ui_story_1015_10151501_120_dialog_content = "...",
  ui_story_1015_10151501_121_dialog_content = "Anda ingin bertanya mengapa saya bekerja sama dengan mereka, bukan Anda lagi, bukan?",
  ui_story_1015_10151501_122_dialog_content = "Aku bisa melindungimu, mereka tidak bisa.",
  ui_story_1015_10151501_123_dialog_content = "Aku tahu.",
  ui_story_1015_10151501_124_dialog_content = "Tapi ini adalah keputusan yang kami buat bersama—setiap warga Twilight.",
  ui_story_1015_10151501_125_dialog_content = "Saya juga warga Twilight.",
  ui_story_1015_10151501_126_dialog_content = "Aku tahu, tapi kali ini berbeda.",
  ui_story_1015_10151501_127_dialog_content = "Kolaborasi dengan Ironthorn Knights dan Church of the God of Light ini semua demi menunjukkan kepada dunia luar persatuan dan kekuatan Twilight.",
  ui_story_1015_10151501_128_dialog_content = "Jika kita menjadi yang teratas, barulah kita akan memiliki pengakuan dan daya ungkit yang cukup untuk angkat bicara dan memberikan tekanan pada kekuatan Astra lainnya.",
  ui_story_1015_10151501_129_dialog_content = "Apakah mereka semua sangat tidak menyukai Twilight?",
  ui_story_1015_10151501_130_dialog_content = "Tidak, mereka tidak menyukai Twilight.",
  ui_story_1015_10151501_131_dialog_content = "Mereka hanya tidak peduli.",
  ui_story_1015_10151501_132_dialog_content = "Tapi kami melakukannya. Senja adalah rumah kita, kita tidak bisa berdiam diri dan menyaksikan gelombang Eclipsites menelannya.",
  ui_story_1015_10151501_133_dialog_content = "Jadi kali ini, kita harus menang. Kita harus membuat mereka peduli, agar mereka mengirim lebih banyak bala bantuan ke Twilight.",
  ui_story_1015_10151501_134_dialog_content = "...",
  ui_story_1015_10151501_135_dialog_content = "Aku akan mengikutimu.",
  ui_story_1015_10151501_136_dialog_content = "Terima kasih atas pengertian Anda.",
  ui_story_1015_10151501_137_dialog_content = "Sudah larut. Ayo cepat dan antarkan dia.",
  ui_story_1015_10151501_138_dialog_content = "Apakah mereka sasarannya?",
  ui_story_1015_10151501_139_dialog_content = "Mereka sama sekali tidak terlihat menyenangkan! Lagipula tidak semenyenangkan boneka beruang dalam mimpiku...",
  ui_story_1015_10151501_140_dialog_content = "Jangan terlalu cepat menilai, kawan.",
  ui_story_1015_10151501_141_dialog_content = "Misi Guru bagi kita hari ini adalah mengamati mereka, jadi itulah yang akan kita lakukan.",
  ui_story_1015_10151501_142_dialog_content = "Intuisi Guru jarang salah. Saya yakin mereka pasti punya agenda tersembunyi.",
  ui_story_1015_10151501_143_dialog_content = "Saya hanya berharap mereka menyukai makhluk kecil seperti saya...",
  ui_story_1015_10151501_144_dialog_content = "Dan itulah situasi saat ini.",
  ui_story_1015_10151501_145_dialog_content = "Reinhardt telah kembali ke Kota Gannon, dan keberadaan Forsakin serta target subjek tes tidak diketahui, meskipun kemungkinan besar mereka juga berada di suatu tempat di Kota Gannon.",
  ui_story_1015_10151501_146_dialog_content = "Selain itu, berbagai kekuatan kini telah berkumpul di Gannon, karena Latihan Militer Gabungan akan segera dimulai.",
  ui_story_1015_10151501_147_dialog_content = "Namun, tim gabungan Twilight yang dibentuk oleh anggota Illumina dan Lumopolis memang merupakan kejadian yang tidak terduga.",
  ui_story_1015_10151501_148_dialog_content = "Apakah Anda ingin saya menemukan dua spesialis untuk membentuk tim dan menahan tindakan mereka?",
  ui_story_1015_10151501_149_dialog_content = "Mereka memang layak untuk diperhatikan, tetapi tidak perlu menganggapnya terlalu serius.",
  ui_story_1015_10151501_150_dialog_content = "Yingel Dan Axelia adalah dua prajurit yang sangat bisa dipercaya.",
  ui_story_1015_10151501_151_dialog_content = "Selain itu, Anda memiliki hal-hal lain untuk diperhatikan.",
  ui_story_1015_10151501_152_dialog_content = "Siap, Jenderal.",
  ui_story_1015_10151501_153_dialog_content = "<color=#e8d9bb>Sementara itu, di suatu tempat di Gannon City...</color>",
  ui_story_1015_10151501_154_dialog_content = "<anim type=Shake><size=45>Mengaum...</size></anim>",
  ui_story_1015_10151501_155_dialog_content = "Turunkan dia di sini.",
  ui_story_1015_10151501_156_dialog_content = "<anim type=Shake><size=45>Rwrrr!</size></anim>",
  ui_story_1015_10151501_157_dialog_content = "<anim type=Shake>Menggeram-</anim>",
  ui_story_1015_10151501_158_dialog_content = "Anak yang baik.",
  ui_story_1015_10151501_159_dialog_content = "Ganti kembali dan ikuti pipa-pipa ini. Tinggalkan Undercity ini.",
  ui_story_1015_10151501_160_dialog_content = "<anim type=Shake><size=45>Grr?!</size></anim>",
  ui_story_1015_10151501_161_dialog_content = "<anim type=Shake><size=45>Rrr... Gemuruh...!</size></anim>",
  ui_story_1015_10151501_162_dialog_content = "Tidak ada yang dapat Anda lakukan untuk saya di sini.",
  ui_story_1015_10151501_163_dialog_content = "Jika Anda tinggal di sini lebih lama lagi, Anda hanya akan memperlambat saya.",
  ui_story_1015_10151501_164_dialog_content = "Anda tahu di mana harus menunggu saya.",
  ui_story_1015_10151501_165_dialog_content = "<anim type=Shake>Groar…</anim>",
  ui_story_1015_10151501_166_dialog_content = "Ciit!",
  ui_story_1015_10151501_167_dialog_content = "Menyangkal...?",
  ui_story_1015_10151501_168_dialog_content = "...",
  ui_story_1015_10151501_169_dialog_content = "Kau sudah bangun.",
  ui_story_1015_10151501_170_dialog_content = "Oke…",
  ui_story_1015_10151501_171_dialog_content = "Kemana... kau... membawaku?",
  ui_story_1015_10151501_172_dialog_content = "Kemampuan kognitif pulih secara bertahap?",
  ui_story_1015_10151501_173_dialog_content = "Meskipun ini menunjukkan bahwa percobaan itu sukses, waktunya sangat disayangkan.",
  ui_story_1015_10151501_174_dialog_content = "Apa yang kamu bicarakan...? Saya tidak mengerti...",
  ui_story_1015_10151501_175_dialog_content = "Bukan apa-apa.",
  ui_story_1015_10151501_176_dialog_content = "Dimana saya? Kau belum menjawabku...",
  ui_story_1015_10151501_177_dialog_content = "...",
  ui_story_1015_10151501_178_dialog_content = "Kota Gannon.",
  ui_story_1015_10151501_179_dialog_content = "Kami kembali?",
  ui_story_1015_10151501_180_dialog_content = "Ya.",
  ui_story_1015_10151501_181_dialog_content = "Kami kembali.",
  ui_story_1016_10160101_1_dialog_content = "<color=#e8d9bb>CHOO—</color>",
  ui_story_1016_10160101_2_dialog_content = "<color=#e8d9bb>Ka-chunk, ka-chunk, ka-chunk—</color>",
  ui_story_1016_10160101_3_dialog_content = "Perhatian, semua peserta Latihan Militer Gabungan.",
  ui_story_1016_10160101_4_dialog_content = "Kereta sudah sampai tujuan. Anda sekarang dapat keluar dari kereta.",
  ui_story_1016_10160101_5_dialog_content = "Harap tunggu instruksi lebih lanjut di stasiun.",
  ui_story_1016_10160101_6_dialog_content = "Wow! Sungguh pengalaman pertama yang luar biasa di kereta!",
  ui_story_1016_10160101_7_dialog_content = "Kereta jauh lebih cepat daripada kereta kuda, bukan?",
  ui_story_1016_10160101_8_dialog_content = "Berderak terus-menerus agak berlebihan jika Anda bertanya kepada saya. Saya merasa jauh lebih baik sekarang setelah kami turun.",
  ui_story_1016_10160101_9_dialog_content = "Tempat ini adalah tempat latihan bersama akan diadakan, kan? Apa yang harus kita lakukan sekarang?",
  ui_story_1016_10160101_10_dialog_content = "Tunggu saja di sini sekarang. Seseorang akan menjelaskan hal-hal segera.",
  ui_story_1016_10160101_11_dialog_content = "Anatoli! Lama tak jumpa!",
  ui_story_1016_10160101_12_dialog_content = "Apakah Anda ikut serta dalam latihan bersama juga?",
  ui_story_1016_10160101_13_dialog_content = "Tentu saja. Semua orang di sini adalah peserta yang bersemangat dalam latihan yang akan datang.",
  ui_story_1016_10160101_14_dialog_content = "Jadi begitu! Itu menjelaskan kegembiraan di udara!",
  ui_story_1016_10160101_15_dialog_content = "Semoga saja Illumina menjaga hal-hal tetap sopan.",
  ui_story_1016_10160101_16_dialog_content = "Tidak perlu khawatir. Penindasan adalah pakaian kuat Lumopolis.",
  ui_story_1016_10160101_17_dialog_content = "Hmph.",
  ui_story_1016_10160101_18_dialog_content = "Tolong bersihkan jalan, semuanya! Kami sedang menurunkan beberapa kargo rapuh sekarang!",
  ui_story_1016_10160101_19_dialog_content = "Jangan menabrak apapun, jangan menabrak apapun.",
  ui_story_1016_10160101_20_dialog_content = "Jadi kemana kita akan membawa ini, Zhao?",
  ui_story_1016_10160101_21_dialog_content = "Penerima seharusnya menemui kita di sini...",
  ui_story_1016_10160101_22_dialog_content = "Terima kasih atas bantuan kalian berdua. Anda dapat meninggalkan ini dengan saya sekarang.",
  ui_story_1016_10160101_23_dialog_content = "Anda telah menyelesaikan misi Anda.",
  ui_story_1016_10160101_24_dialog_content = "Ah, jadi selama ini Anda adalah penerimanya, Kolonel Yingel.",
  ui_story_1016_10160101_25_dialog_content = "Apakah ada sesuatu yang aneh tentang itu?",
  ui_story_1016_10160101_26_dialog_content = "Partisipasi Anda dalam senam bersama agak aneh ya.",
  ui_story_1016_10160101_27_dialog_content = "Saya selalu berpikir kejadian seperti ini berada di bawah status seseorang seperti Anda.",
  ui_story_1016_10160101_28_dialog_content = "Kalau begitu, Anda pasti sangat memikirkan saya.",
  ui_story_1016_10160101_29_dialog_content = "Ini dia. Mengangkut benda ini tidak mudah, Anda tahu.",
  ui_story_1016_10160101_30_dialog_content = "Apakah Anda ingin memeriksa dan memastikan semuanya utuh?",
  ui_story_1016_10160101_31_dialog_content = "Ya.",
  ui_story_1016_10160101_32_dialog_content = "<color=#e8d9bb>Tok, tok.</color>",
  ui_story_1016_10160101_33_dialog_content = "Waktu untuk bangun, Axelia.",
  ui_story_1016_10160101_34_dialog_content = "<color=#e8d9bb>Tsss—</color>",
  ui_story_1016_10160101_35_dialog_content = "Yaawn.",
  ui_story_1016_10160101_36_dialog_content = "Selamat pagi, Yingel.",
  ui_story_1016_10160101_37_dialog_content = "Apakah kamu tidur dengan nyenyak?",
  ui_story_1016_10160101_38_dialog_content = "Ya, saya merasa cukup istirahat sekarang.",
  ui_story_1016_10160101_39_dialog_content = "Ugh, betapa menyesakkan.",
  ui_story_1016_10160101_40_dialog_content = "Aku benar-benar tidak peduli terkurung dalam ruang yang menyesakkan ini.",
  ui_story_1016_10160101_41_dialog_content = "Anda berkeringat seperti baru saja menyelesaikan pertempuran, Leo.",
  ui_story_1016_10160101_42_dialog_content = "Ya, dan saya juga merasa lelah.",
  ui_story_1016_10160101_43_dialog_content = "Tidakkah Anda pikir Anda sedikit melebih-lebihkan? Itu hanyalah bentuk transportasi lainnya.",
  ui_story_1016_10160101_44_dialog_content = "Kami tidak pernah dalam bahaya.",
  ui_story_1016_10160101_45_dialog_content = "Itu tidak ada hubungannya dengan apakah kita dalam bahaya atau tidak...",
  ui_story_1016_10160101_46_dialog_content = "Apakah Anda ingin serbet?",
  ui_story_1016_10160101_47_dialog_content = "Mengapa ya, terima kasih... Hmm? L-Nyonya Carleen?!",
  ui_story_1016_10160101_48_dialog_content = "Saya mengerti bagaimana perasaan anda. Banyak orang dari Lumopolis mengalami kesulitan menyesuaikan diri dengan mesin tersebut.",
  ui_story_1016_10160101_49_dialog_content = "Jadi begitu. Kalau saja semua orang sama pengertiannya dengan Anda, nona.",
  ui_story_1016_10160101_50_dialog_content = "Harus kukatakan, bertemu denganmu di sini cukup mengejutkan.",
  ui_story_1016_10160101_51_dialog_content = "Saya berasumsi bahwa pertemuan kami berikutnya adalah di Lumopolis.",
  ui_story_1016_10160101_52_dialog_content = "Mengingat status kami, pertemuan di Lumopolis akan penuh dengan komplikasi. Namun, di sini, kami bebas berbicara sebagai peserta latihan.",
  ui_story_1016_10160101_53_dialog_content = "Ha ha ha ha! Kata yang bagus, nona!",
  ui_story_1016_10160101_54_dialog_content = "Sedikit kesederhanaan selalu diterima saat orang menjalani kehidupan yang begitu rumit.",
  ui_story_1016_10160101_55_dialog_content = "Hei, itu Leo dan Yusuf! Apakah kalian di sini untuk latihan bersama juga?",
  ui_story_1016_10160101_56_dialog_content = "Pasti perjalanan panjang dari Twilight!",
  ui_story_1016_10160101_57_dialog_content = "PlayerName! Apa yang kamu lakukan di sini?",
  ui_story_1016_10160101_58_dialog_content = "Saya diundang ke latihan bersama, jadi saya ikut Carleen Dan Vice.",
  ui_story_1016_10160101_59_dialog_content = "Jadi begitu. Saya akan meminta tumpangan ke Colossus Anda jika saya tahu Anda akan datang ...",
  ui_story_1016_10160101_60_dialog_content = "Ha ha ha! Anda selalu dipersilakan untuk bergabung, Anda tahu!",
  ui_story_1016_10160101_61_dialog_content = "Ahem! Semua peserta, harap berkumpul di sini.",
  ui_story_1016_10160101_62_dialog_content = "Sekarang saya akan memberikan instruksi lebih lanjut tentang Latihan Militer Gabungan.",
  ui_story_1016_10160101_63_dialog_content = "Apa aku baru saja mendengar suara Vivian?",
  ui_story_1016_10160101_64_dialog_content = "Ya! Mari kita pergi!",
  ui_story_1016_10160101_65_dialog_content = "C-Hati-hati, Vice. Ada banyak orang di sini.",
  ui_story_1016_10160101_66_dialog_content = "Anda bisa bersantai sejenak. Ini tidak seperti aku terluka karena apa yang terjadi sebelumnya atau apapun.",
  ui_story_1016_10160101_67_dialog_content = "Selain itu, apakah Anda tidak ingat apa yang dikatakan pemeriksaan medis? Saya sesehat mungkin!",
  ui_story_1016_10160101_68_dialog_content = "Tapi saya masih berpikir ...",
  ui_story_1016_10160101_69_dialog_content = "Ayo pergi!",
  ui_story_1016_10160101_70_dialog_content = "Pertama, terima kasih semua telah datang ke Kota Gannon hari ini untuk berpartisipasi dalam Latihan Militer Gabungan kami.",
  ui_story_1016_10160101_71_dialog_content = "Saya Vivian, Kepala Staf Federasi Illumina, dan saya akan melayani sebagai pemandu Anda.",
  ui_story_1016_10160101_72_dialog_content = "Illumina sangat mementingkan efisiensi, jadi mari kita lanjutkan tanpa penundaan lebih lanjut.",
  ui_story_1016_10160101_73_dialog_content = "Setelah penjelasan aturan saya selesai, Latihan Militer Gabungan akan resmi dimulai.",
  ui_story_1016_10160101_74_dialog_content = "Mereka benar-benar tidak bertele-tele, ya?",
  ui_story_1016_10160101_75_dialog_content = "Sejujurnya, ini lebih cocok untukku daripada pidato formal yang bertele-tele.",
  ui_story_1016_10160101_76_dialog_content = "Seperti yang diketahui semua orang dengan sangat baik, Latihan Militer Gabungan ini bertujuan untuk meningkatkan kemampuan generasi muda dalam menghadapi kerasnya peperangan.",
  ui_story_1016_10160101_77_dialog_content = "Setiap peserta yang berkumpul di sini hari ini berusia di bawah dua puluh lima tahun.",
  ui_story_1016_10160101_78_dialog_content = "Anda semua adalah perwira muda yang baru mulai menunjukkan bakat Anda atau siswa yang belum meninggalkan keamanan menara gading akademisi.",
  ui_story_1016_10160101_79_dialog_content = "Terlepas dari perbedaan usia atau pengalaman, Anda masing-masing akan melihat pertempuran suatu hari nanti.",
  ui_story_1016_10160101_80_dialog_content = "Anda semua harus melakukan yang terbaik untuk mengasah kemampuan tempur Anda melalui belajar, kerja sama, dan kompetisi.",
  ui_story_1016_10160101_81_dialog_content = "Untuk mempersiapkan pelatihan Anda, latihan militer akan dibagi menjadi dua tahap: pendidikan dan penilaian tempur.",
  ui_story_1016_10160101_82_dialog_content = "Selama fase pendidikan, Illumina akan memberi Anda sumber daya berkualitas tinggi dan pengetahuan pendahulu Anda untuk meningkatkan diri.",
  ui_story_1016_10160101_83_dialog_content = "Selama fase penilaian, Anda akan membentuk tim dan bersaing satu sama lain untuk menentukan pemenang akhir.",
  ui_story_1016_10160101_84_dialog_content = "Saya ragu siapa pun perlu diingatkan bahwa sesuai dengan tradisi, pemenang penilaian akan diberikan hadiah yang sangat unik—",
  ui_story_1016_10160101_85_dialog_content = "Kesempatan untuk berdebat dengan Grand Marshal.",
  ui_story_1016_10160101_86_dialog_content = "Kesempatan untuk melawan Grand Marshal? Itu terlalu menakutkan... Siapa yang mau itu?",
  ui_story_1016_10160101_87_dialog_content = "Tapi sekali lagi, juara senam bersama pasti juga cukup tangguh...",
  ui_story_1016_10160101_88_dialog_content = "Kamu benar! Terakhir kali putri dari Lumopolis...",
  ui_story_1016_10160101_89_dialog_content = "Itu menyimpulkan pengenalan dasar latihan.",
  ui_story_1016_10160101_90_dialog_content = "Tolong angkat spanduknya!",
  ui_story_1016_10160101_91_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_1016_10160101_92_dialog_content = "Wah! Itu satu rantai panjang bendera!",
  ui_story_1016_10160101_93_dialog_content = "Ini adalah <color=#FFB400>Spanduk Juara</color>.",
  ui_story_1016_10160101_94_dialog_content = "Hanya juara Latihan Militer Gabungan yang memiliki hak istimewa untuk menambahkan bendera faksi mereka ke dalamnya.",
  ui_story_1016_10160101_95_dialog_content = "Dengan setiap latihan bersama yang diadakan, Panji Juara telah berkembang menjadi seperti yang Anda lihat sekarang.",
  ui_story_1016_10160101_96_dialog_content = "Anda dapat melihat bukti kemenangan masa lalu setiap faksi utama.",
  ui_story_1016_10160101_97_dialog_content = "Seperti bintang yang tak terhitung jumlahnya bersinar di langit di atas—",
  ui_story_1016_10160101_98_dialog_content = "Spanduk ini adalah simbol dari latihan bersama kita, serta keinginan pantang menyerah setiap generasi untuk meraih kemenangan dalam pertempuran!",
  ui_story_1016_10160101_99_dialog_content = "(!!!)",
  ui_story_1016_10160101_100_dialog_content = "(Apakah saya melihat sesuatu, atau apakah itu bendera Caelestites...?!)",
  ui_story_1016_10160101_101_dialog_content = "Sekarang, semuanya. Tanpa basa-basi lagi, suatu kehormatan bagi saya untuk mengumumkan—",
  ui_story_1016_10160101_102_dialog_content = "Awal resmi Latihan Militer Gabungan ini!",
  ui_story_1016_10160101_103_dialog_content = "<color=#e8d9bb>*Tepuk tangan*</color>",
  ui_story_1016_10160101_104_dialog_content = "Kami sekarang akan mulai mendaftarkan semua orang secara resmi untuk acara tersebut.",
  ui_story_1016_10160101_105_dialog_content = "Dalam surat undangan Anda, Anda akan menemukan tim tempat Anda ditugaskan.",
  ui_story_1016_10160101_106_dialog_content = "Sebuah tim terdiri dari tiga peserta, yang mewakili unit operasional paling dasar dalam Latihan Militer Gabungan ini.",
  ui_story_1016_10160101_107_dialog_content = "Faksi kapten tim juga akan berfungsi sebagai faksi seluruh tim.",
  ui_story_1016_10160101_108_dialog_content = "Harap luangkan waktu sejenak untuk menemukan anggota lain dari tim Anda.",
  ui_story_1016_10160101_109_dialog_content = "Jadi, Carleen Dan Vice akan di tim saya, kan?",
  ui_story_1016_10160101_110_dialog_content = "Apakah Anda lupa atau sesuatu? Tentu kami!",
  ui_story_1016_10160101_111_dialog_content = "Undangan itu juga mengatakan bahwa Anda akan memimpin tim, Kapten.",
  ui_story_1016_10160101_112_dialog_content = "Ah, tolong jangan katakan itu...",
  ui_story_1016_10160101_113_dialog_content = "Setelah Anda mengkonfirmasi anggota lain dari tim Anda, silakan datang ke saya untuk pendaftaran.",
  ui_story_1016_10160101_114_dialog_content = "Setelah pendaftaran selesai, saya akan mengantar Anda semua ke barak Anda untuk meletakkan barang bawaan Anda. Setelah itu, Anda bebas melakukan apa saja sesuka Anda di dalam area yang diizinkan.",
  ui_story_1016_10160101_115_dialog_content = "Kelas pertamamu akan diadakan besok pagi.",
  ui_story_1016_10160101_116_dialog_content = "Aku sangat gembira!",
  ui_story_1016_10160101_117_dialog_content = "Saya sudah tahu tentang latihan bersama ini sejak saya masih kecil, tetapi ini adalah pertama kalinya saya ikut serta!",
  ui_story_1016_10160101_118_dialog_content = "Seperti apa terakhir kali Anda datang, Carleen?",
  ui_story_1016_10160101_119_dialog_content = "Aku merasakan hal yang sama sepertimu, kurang lebih.",
  ui_story_1016_10160101_120_dialog_content = "Bersemangat, namun tidak sepenuhnya percaya diri.",
  ui_story_1016_10160101_121_dialog_content = "Tidak sepenuhnya percaya diri, namun Anda keluar di atas, ya?",
  ui_story_1016_10160101_122_dialog_content = "Menjadi jenius yang lahir alami pasti sangat menyenangkan!",
  ui_story_1016_10160101_123_dialog_content = "A-aku tidak berusaha menyombongkan diri! Benar-benar!",
  ui_story_1016_10160101_124_dialog_content = "Heehee! Saya hanya bercanda, Carleen!",
  ui_story_1016_10160101_125_dialog_content = "Apa pendapatmu tentang semua ini, PlayerName? Anda hampir tidak berbicara sejak kita tiba di sini.",
  ui_story_1016_10160101_126_dialog_content = "Apakah Anda masih belum terbiasa dengan lingkungan yang penuh tekanan seperti ini?",
  ui_story_1016_10160101_127_dialog_content = "Saya hanya berpikir... Sebagian besar peserta lainnya adalah teman-teman kita.",
  ui_story_1016_10160101_128_dialog_content = "Saya kira saya tidak siap secara mental untuk menghadapi mereka, itu saja.",
  ui_story_1016_10160101_129_dialog_content = "Masuk akal, mengingat betapa Anda cenderung menghindari konflik.",
  ui_story_1016_10160101_130_dialog_content = "Tapi tidak apa-apa! Yuk lebih fokus belajar daripada berkompetisi!",
  ui_story_1016_10160101_131_dialog_content = "T-Tapi aku juga ingin menang kali ini...",
  ui_story_1016_10160101_132_dialog_content = "Hah?",
  ui_story_1016_10160101_133_dialog_content = "Saya melihat bendera Caelestites di Banner of Champions sebelumnya.",
  ui_story_1016_10160101_134_dialog_content = "Itu membuat saya sangat senang melihat tanda orang-orang saya dalam sejarah, tapi ...",
  ui_story_1016_10160101_135_dialog_content = "Ketika saya melihat seberapa jauh itu dari bendera yang paling baru ditambahkan, saya juga merasa sedikit sedih.",
  ui_story_1016_10160101_136_dialog_content = "Sudah begitu lama sejak Caelestites mengambil bagian dalam kompetisi ini...",
  ui_story_1016_10160101_137_dialog_content = "Saya tidak ingin harga diri rakyat saya tertahan jauh di masa lalu, seperti bendera itu.",
  ui_story_1016_10160101_138_dialog_content = "Saya ingin menggantung satu lagi di bagian paling depan spanduk!",
  ui_story_1016_10160101_139_dialog_content = "Dengarkan baik-baik! Semua orang di tim kami berasal dari Lumopolis.",
  ui_story_1016_10160101_140_dialog_content = "Artinya, tindakan kita secara langsung mencerminkan standar pendidikannya yang termasyhur!",
  ui_story_1016_10160101_141_dialog_content = "Kita tidak boleh mempermalukan Lumopolis atau Dawn Akademi!",
  ui_story_1016_10160101_142_dialog_content = "Sudah membuat pidato muluk, Kapten?",
  ui_story_1016_10160101_143_dialog_content = "Aku tidak sedang berpidato!",
  ui_story_1016_10160101_144_dialog_content = "Saya hanya ingin meningkatkan semangat semua orang untuk kompetisi yang akan datang...",
  ui_story_1016_10160101_145_dialog_content = "Dia benar. Persaingan Latihan Militer Gabungan ini sangat ketat.",
  ui_story_1016_10160101_146_dialog_content = "Kami harus menjaga semangat kami jika kami tidak ingin tertinggal.",
  ui_story_1016_10160101_147_dialog_content = "Apakah begitu? Apa kesan Anda tentang tim lain?",
  ui_story_1016_10160101_148_dialog_content = "aku hanya sadar PlayerName dan timnya.",
  ui_story_1016_10160101_149_dialog_content = "Kemampuan psikis A Caelestite, dikombinasikan dengan Lady Carleen dan kekuatan gabungan Nona Vice, menjadikan mereka ancaman yang kuat.",
  ui_story_1016_10160101_150_dialog_content = "Nah, Nyonya Carleen adalah juara bertahan setelah semua. Saya yakin dia tidak akan kehilangan gelarnya dengan mudah.",
  ui_story_1016_10160101_151_dialog_content = "Selain PlayerNametim, ada dua tim penting lainnya.",
  ui_story_1016_10160101_152_dialog_content = "Salah satunya adalah tim Leo. Dia dan rekan-rekannya semuanya berasal dari Twilight.",
  ui_story_1016_10160101_153_dialog_content = "Selama salah satu misi saya sebelumnya, saya mendapat hak istimewa untuk melihat secara langsung bagaimana para pejuang dari Twilight berperang.",
  ui_story_1016_10160101_154_dialog_content = "Ketiganya memiliki pengalaman tempur yang kaya. Tidak ada tim lain yang bisa dibandingkan di departemen ini.",
  ui_story_1016_10160101_155_dialog_content = "Jadi begitu. Pengalaman tempur nyata memang memberi mereka keunggulan atas kita semua.",
  ui_story_1016_10160101_156_dialog_content = "Meskipun perbedaan usia tidak terlalu jauh, perbedaan pengalaman sangat besar.",
  ui_story_1016_10160101_157_dialog_content = "Tim lain yang harus kita awasi adalah tim Yingel, karena dia sudah melakukannya Axelia Dan Anatoli di sisinya.",
  ui_story_1016_10160101_158_dialog_content = "Ketiganya adalah petarung top Illumina untuk generasi mereka.",
  ui_story_1016_10160101_159_dialog_content = "Selain itu, mereka memiliki pengetahuan ilmiah dan teknologi Illumina yang lengkap. Tidak ada yang tahu seberapa kuat yang membuat mereka.",
  ui_story_1016_10160101_160_dialog_content = "Ugh... Sains dan teknologi bukanlah kekuatan kita.",
  ui_story_1016_10160101_161_dialog_content = "Saya sangat setuju, itulah sebabnya kita harus menjauh dari mereka.",
  ui_story_1016_10160101_162_dialog_content = "Ingat, kita datang ke Kota Gannon sebagai tamu, jadi kita harus menerima cara mereka melakukan sesuatu.",
  ui_story_1016_10160101_163_dialog_content = "Mari kita anggap ini sebagai pengalaman belajar yang berharga.",
  ui_story_1016_10160101_164_dialog_content = "Mengatakan demikian adalah satu hal, tetapi melakukannya bukanlah tugas yang mudah.",
  ui_story_1016_10160101_165_dialog_content = "Sama seperti bagaimana Anda masih belum mengetahui jalan-jalan Kota Gannon meski sudah lama tersesat.",
  ui_story_1016_10160101_166_dialog_content = "Ke-Kenapa kau menyerangku, tiba-tiba?!",
  ui_story_1016_10160101_167_dialog_content = "Karena saya ingin kembali ke barak, Kapten. Berapa lama sebelum Anda akhirnya bisa membawa kami ke arah yang benar?",
  ui_story_1016_10160101_168_dialog_content = "J-Beri aku waktu sebentar! Saya hampir menemukan jawabannya!",
  ui_story_1016_10160101_169_dialog_content = "Jika kita belok kanan di sini...",
  ui_story_1016_10160101_170_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_1016_10160101_171_dialog_content = "<size=45>Urgh!</size>",
  ui_story_1016_10160101_172_dialog_content = "Hmm…",
  ui_story_1016_10160101_173_dialog_content = "Aku sangat menyesal! Seharusnya aku lebih memperhatikan jalan!",
  ui_story_1016_10160101_174_dialog_content = "Kau baik-baik saja?",
  ui_story_1016_10160101_175_dialog_content = "Aku baik-baik saja, dan tolong jangan menyalahkan dirimu sendiri. Orang-orang cenderung sering bertemu dengan saya.",
  ui_story_1016_10160101_176_dialog_content = "Bisakah Anda menyerahkan tongkat saya? Sepertinya saya tidak dapat menemukannya.",
  ui_story_1016_10160101_177_dialog_content = "Tentu saja. Ini dia.",
  ui_story_1016_10160101_178_dialog_content = "Maafkan aku, tapi... apakah kamu buta?",
  ui_story_1016_10160101_179_dialog_content = "Oh, saya minta maaf untuk mengganggu Anda.",
  ui_story_1016_10160101_180_dialog_content = "Boohoo, akulah yang seharusnya minta maaf! Seharusnya aku tidak pernah bertemu denganmu!",
  ui_story_1016_10160101_181_dialog_content = "Kemana kamu pergi? Biarkan saya mengantar Anda ke sana!",
  ui_story_1016_10160101_182_dialog_content = "Itu tidak perlu, terima kasih. Namun, saya mencari seorang gadis kecil yang mengenakan pakaian boneka. Pernahkah Anda melihatnya?",
  ui_story_1016_10160101_183_dialog_content = "Sama sekali tak tahu…",
  ui_story_1016_10160101_184_dialog_content = "Maka aku tidak akan menyusahkanmu lagi. Saya dapat terus mencari sendiri.",
  ui_story_1016_10160101_185_dialog_content = "Oh, ngomong-ngomong... Aku juga peserta Latihan Militer Gabungan, sama seperti kalian bertiga.",
  ui_story_1016_10160101_186_dialog_content = "Hah?",
  ui_story_1016_10160101_187_dialog_content = "Nama saya Disis. Saya berharap dapat melihat Anda di kelas besok.",
  ui_story_1016_10160101_188_dialog_content = "Misi kami adalah menjadi setinggi mungkin, mengerti?",
  ui_story_1016_10160101_189_dialog_content = "Kami tidak tertarik membaca buku atau bermain tentara. Kami di sini untuk menemukan cara untuk memperkuat pesan kami.",
  ui_story_1016_10160101_190_dialog_content = "Kita perlu memperingatkan seluruh dunia tentang malapetaka Twilight yang akan datang!",
  ui_story_1016_10160101_191_dialog_content = "Sekarang aku tahu apa yang sebenarnya kau cari, Leo.",
  ui_story_1016_10160101_192_dialog_content = "Apakah begitu? Lalu beri tahu kami, jika Anda sangat pintar.",
  ui_story_1016_10160101_193_dialog_content = "Anda ingin kesempatan untuk berhadapan dengan Grand Marshal.",
  ui_story_1016_10160101_194_dialog_content = "Ha ha ha ha! Itu benar! Apa yang bisa menjadi berita yang lebih besar daripada pemukulan seseorang Reinhardt dalam pertempuran?",
  ui_story_1016_10160101_195_dialog_content = "Anda menggigit lebih dari yang bisa Anda kunyah.",
  ui_story_1016_10160101_196_dialog_content = "Apa? Kalian serius?",
  ui_story_1016_10160101_197_dialog_content = "Mengalahkan persaingan untuk hak berduel dengan Grand Marshal seharusnya tidak menjadi tantangan.",
  ui_story_1016_10160101_198_dialog_content = "Tapi saya tidak berpikir Anda bisa mengalahkannya dalam pertarungan satu lawan satu.",
  ui_story_1016_10160101_199_dialog_content = "Blunt seperti biasa, saya melihat.",
  ui_story_1016_10160101_200_dialog_content = "Pertarungan solo bukanlah kekuatanmu. Seharusnya aku tidak perlu mengingatkanmu tentang itu, kan?",
  ui_story_1016_10160101_201_dialog_content = "Tidak, saya sangat jelas tentang itu.",
  ui_story_1016_10160101_202_dialog_content = "Tapi aku bukan orang yang akan menghadapi Reinhardt dalam pertempuran, haruskah kita berhasil.",
  ui_story_1016_10160101_203_dialog_content = "!!!",
  ui_story_1016_10160101_204_dialog_content = "Jadi itu sebabnya kau membawanya bersama...",
  ui_story_1016_10160101_205_dialog_content = "Saya tidak tahu tentang peluang Joseph untuk menang.",
  ui_story_1016_10160101_206_dialog_content = "Tapi saya yakin pesan kami akan didengar dengan keras dan jelas.",
  ui_story_1016_10160101_207_dialog_content = "Dengar itu? Seseorang menangis.",
  ui_story_1016_10160101_208_dialog_content = "Hah?",
  ui_story_1016_10160101_209_dialog_content = "Tenang saja dan dengarkan baik-baik.",
  ui_story_1016_10160101_210_dialog_content = "<size=30>*Menangis*</size>",
  ui_story_1016_10160101_211_dialog_content = "Kau benar!",
  ui_story_1016_10160101_212_dialog_content = "Aneh sekali, tangisan orang tersebut sama sekali tidak terdengar sedih.",
  ui_story_1016_10160101_213_dialog_content = "Itu semakin dekat. Mereka pasti berjalan ke arah kita.",
  ui_story_1016_10160101_214_dialog_content = "*Hiks*",
  ui_story_1016_10160101_215_dialog_content = "Seorang setengah manusia? Itu pemandangan yang langka.",
  ui_story_1016_10160101_216_dialog_content = "Apakah semuanya baik-baik saja? Aku mendengarmu menangis dari jauh.",
  ui_story_1016_10160101_217_dialog_content = "Hah? A-Apakah kamu bertanya padaku?",
  ui_story_1016_10160101_218_dialog_content = "Saya minta maaf jika itu mengganggu Anda.",
  ui_story_1016_10160101_219_dialog_content = "Itu hanya karena kepalaku terlalu sakit. Itu masalah lama.",
  ui_story_1016_10160101_220_dialog_content = "Kedengarannya serius, jika sakit kepala Anda cukup menyakitkan untuk membuat Anda menangis...",
  ui_story_1016_10160101_221_dialog_content = "Aku melihatmu di stasiun kereta tadi. Kamu juga salah satu peserta Latihan Militer Gabungan, kan?",
  ui_story_1016_10160101_222_dialog_content = "Ya. Nama saya Merry.",
  ui_story_1016_10160101_223_dialog_content = "Asalmu dari mana?",
  ui_story_1016_10160101_224_dialog_content = "Umbraton.",
  ui_story_1016_10160101_225_dialog_content = "Berapa banyak dari Anda yang ada di sana?",
  ui_story_1016_10160101_226_dialog_content = "Tiga, termasuk saya sendiri.",
  ui_story_1016_10160101_227_dialog_content = "Sekarang jika saya boleh bertanya, pernahkah Anda melihat seorang gadis kecil mengenakan pakaian boneka di sekitar sini?",
  ui_story_1016_10160101_228_dialog_content = "Dia rekan satu tim saya, dan dia tampaknya tersesat di dekatnya.",
  ui_story_1016_10160101_229_dialog_content = "Kami belum, maaf. Anda satu-satunya peserta lain yang kami lihat sejauh ini.",
  ui_story_1016_10160101_230_dialog_content = "Jadi begitu. Nah, jika Anda tidak memiliki pertanyaan lain untuk saya, saya harus terus mencarinya.",
  ui_story_1016_10160101_231_dialog_content = "Terima kasih atas waktu Anda. Saya berharap dapat melihat Anda selama pelatihan.",
  ui_story_1016_10160101_232_dialog_content = "Ada apa denganmu, menginterogasinya seperti itu?!",
  ui_story_1016_10160101_233_dialog_content = "Menginterogasi? Aku hanya mengumpulkan informasi, itu saja.",
  ui_story_1016_10160101_234_dialog_content = "Apakah Anda curiga padanya?",
  ui_story_1016_10160101_235_dialog_content = "Saya tidak bisa mengatakan dengan pasti, setidaknya tidak sekarang. Mari kita tunggu dan lihat saja.",
  ui_story_1016_10160101_236_dialog_content = "Saya memiliki pembaruan untuk dibagikan kepada semua orang.",
  ui_story_1016_10160101_237_dialog_content = "Kami harus memenangkan kejuaraan dengan segala cara.",
  ui_story_1016_10160101_238_dialog_content = "Apakah ada pertanyaan?",
  ui_story_1016_10160101_239_dialog_content = "Tidak.",
  ui_story_1016_10160101_240_dialog_content = "... Apakah itu benar-benar keputusan dari Komite?",
  ui_story_1016_10160101_241_dialog_content = "Ya.",
  ui_story_1016_10160101_242_dialog_content = "Saya kira saya tidak punya pertanyaan lebih lanjut, kalau begitu.",
  ui_story_1016_10160101_243_dialog_content = "Tidak ada strategi khusus untuk tahap pembelajaran Latihan Gabungan, jadi ikuti saja pelajaran seperti biasa.",
  ui_story_1016_10160101_244_dialog_content = "Dan ingatlah untuk tidak menonjolkan diri, untuk menghindari perhatian atau pertengkaran yang tidak perlu.",
  ui_story_1016_10160101_245_dialog_content = "Perintah kami adalah untuk tetap dirahasiakan. Tak seorang pun di luar ruangan ini yang tahu tentang misi kita.",
  ui_story_1016_10160101_246_dialog_content = "Aku mengerti.",
  ui_story_1016_10160101_247_dialog_content = "Aku mengerti.",
  ui_story_1016_10160101_248_dialog_content = "Itu saja untuk saat ini. Rapat ditunda.",
  ui_story_1016_10160101_249_dialog_content = "Bagus, aku mulai merasa lelah.",
  ui_story_1016_10160101_250_dialog_content = "Di sini, saya akan mengantar Anda kembali ke ruang stasis Anda.",
  ui_story_1016_10160101_251_dialog_content = "Anatoli, bisakah Anda membantu saya mendapatkan pintu?",
  ui_story_1016_10160101_252_dialog_content = "Tentu-",
  ui_story_1016_10160101_253_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_1016_10160101_254_dialog_content = "Ahhh!",
  ui_story_1016_10160101_255_dialog_content = "Seseorang di luar pintu!",
  ui_story_1016_10160101_256_dialog_content = "Siapa di sana?!",
  ui_story_1016_10160101_257_dialog_content = "Itu menyakitkan! Jangan membuka pintu begitu saja!",
  ui_story_1016_10160101_258_dialog_content = "Oh, bagus sekali! Lihat benjolan besar di kepalaku ini!",
  ui_story_1016_10160101_259_dialog_content = "...",
  ui_story_1016_10160101_260_dialog_content = "Apakah anak ini musuh?",
  ui_story_1016_10160101_261_dialog_content = "H-Hei! Ada apa dengan tatapan itu?!",
  ui_story_1016_10160101_262_dialog_content = "A-aku tidak menguping kalian atau apapun!",
  ui_story_1016_10160101_263_dialog_content = "Kami tidak mengatakan apa-apa tentang Anda menguping.",
  ui_story_1016_10160101_264_dialog_content = "Kamu...",
  ui_story_1016_10160101_265_dialog_content = "Itu dia, Minch! Aku sudah mencarimu kemana-mana!",
  ui_story_1016_10160101_266_dialog_content = "Mengapa Anda lari seperti itu? Bukankah saya memperingatkan Anda tentang betapa mudahnya tersesat di Kota Gannon?",
  ui_story_1016_10160101_267_dialog_content = "Butuh waktu cukup lama, Merry!",
  ui_story_1016_10160101_268_dialog_content = "Kalian berdua saling kenal? Mungkinkah...",
  ui_story_1016_10160101_269_dialog_content = "Saya minta maaf jika teman kami membuat Anda kesulitan.",
  ui_story_1016_10160101_270_dialog_content = "Ini adalah pertama kalinya kami di Kota Gannon, dan tata letak kota memudahkan pendatang baru seperti kami tersesat.",
  ui_story_1016_10160101_271_dialog_content = "Apa kita... mengganggu sesuatu?",
  ui_story_1016_10160101_272_dialog_content = "Untuk apa kau meminta maaf, Dysis?! Merekalah yang memukul wajahku dengan pintu!",
  ui_story_1016_10160101_273_dialog_content = "Biarkan saja, Min. Anda harus lebih menghormati kenalan baru kami.",
  ui_story_1016_10160101_274_dialog_content = "...",
  ui_story_1016_10160101_275_dialog_content = "Kalau begitu, kita harus pergi sekarang.",
  ui_story_1016_10160101_276_dialog_content = "Ya, sementara saya masih ingat jalan kembali.",
  ui_story_1016_10160101_277_dialog_content = "Hmph! Nanti, brengsek!",
  ui_story_1016_10160101_278_dialog_content = "Ketiganya adalah peserta dari Umbraton.",
  ui_story_1016_10160101_279_dialog_content = "Haruskah kita benar-benar membiarkan mereka pergi seperti ini? Mungkin saja mereka mendengar percakapan kami.",
  ui_story_1016_10160101_280_dialog_content = "Jika mereka benar-benar mendengar kami, saya akan menemukan cara untuk menyelesaikan masalah ini.",
  ui_story_1016_10160101_281_dialog_content = "Untuk saat ini, mari kita kembali dan beristirahat.",
  ui_story_1016_10160101_282_dialog_content = "Kita masih perlu mempersiapkan untuk kelas besok.",
  ui_story_1016_10160101_283_dialog_content = "<color=#e8d9bb>Lubang, tepuk, lubang, tepuk ...</color>",
  ui_story_1016_10160101_284_dialog_content = "Apakah mereka pergi...?",
  ui_story_1016_10160101_285_dialog_content = "Ya, kelompok tentara terakhir telah pergi.",
  ui_story_1016_10160101_286_dialog_content = "Bagaimana perasaanmu, Helios?",
  ui_story_1016_10160101_287_dialog_content = "Ini hanya goresan... Jangan khawatirkan aku.",
  ui_story_1016_10160101_288_dialog_content = "Aku... aku masih bisa bertarung.",
  ui_story_1016_10160101_289_dialog_content = "Pertarungan tidak akan membawa kita kemana-mana di Kota Gannon, Helios. Saat kita ketahuan, setiap prajurit di Illumina akan menembaki kita.",
  ui_story_1016_10160101_290_dialog_content = "Kekuatan kasar bukanlah jawabannya.",
  ui_story_1016_10160101_291_dialog_content = "Namun…",
  ui_story_1016_10160101_292_dialog_content = "Tahan saja untuk saat ini. Dalam situasi seperti ini, adalah kepentingan terbaik kita untuk tetap tenang.",
  ui_story_1016_10160101_293_dialog_content = "Kita hanya perlu menunggu sedikit lebih lama.",
  ui_story_1016_10160101_294_dialog_content = "Apa sebenarnya yang kita tunggu?",
  ui_story_1016_10160101_295_dialog_content = "Itu <color=#FFB400>Hantu</color>.",
  ui_story_1016_10160201_1_dialog_content = "<anim type=Shake>Menguap-</anim> Aku tidak bisa tidur sama sekali tadi malam.",
  ui_story_1016_10160201_2_dialog_content = "Seluruh kota ini berbau seperti pabrik.",
  ui_story_1016_10160201_3_dialog_content = "Sebuah laboratorium?! Apa yang kamu rencanakan dengan kami di sini ?!",
  ui_story_1016_10160201_4_dialog_content = "Saya tidak berniat menjadi tikus percobaan untuk Illumina!",
  ui_story_1016_10160201_5_dialog_content = "Wow, tempat yang familiar.",
  ui_story_1016_10160201_6_dialog_content = "Saya pikir saya tahu apa yang kita lakukan di sini hari ini.",
  ui_story_1016_10160201_7_dialog_content = "<color=#e8d9bb>Cincin-</color>",
  ui_story_1016_10160201_8_dialog_content = "Terlalu keras, TERLALU KERAS! Pipa bawah, kalian semua!",
  ui_story_1016_10160201_9_dialog_content = "Nama saya Gronru, dan saya akan menjadi instruktur Anda untuk semua kelas terkait penelitian Anda.",
  ui_story_1016_10160201_10_dialog_content = "Jelas, sebagian besar dari Anda tidak peduli tentang sains, tapi jangan khawatir! Kelas saya sama sekali tidak membosankan!",
  ui_story_1016_10160201_11_dialog_content = "Jadi untuk pelajaran pertama kita, saya menyiapkan sesuatu yang sangat menyenangkan untuk Anda semua... Penemuan terbaru dan terhebat kami!",
  ui_story_1016_10160201_12_dialog_content = "Manjakan mata Anda dengan perangkat pelatihan militer terbaru Illumina—",
  ui_story_1016_10160201_13_dialog_content = "<color=#FFB400>Simulator Pertempuran</color>!",
  ui_story_1016_10160201_14_dialog_content = "Sudah kuduga!",
  ui_story_1016_10160201_15_dialog_content = "Sebuah helm? Bagaimana tepatnya ini seharusnya melatih kita?",
  ui_story_1016_10160201_16_dialog_content = "Kamu bercanda? Gadget kecil ini bekerja lebih baik daripada pedang atau senjata apa pun!",
  ui_story_1016_10160201_17_dialog_content = "Katakan padaku, menurutmu apa hal tersulit untuk dilatih bagi seorang prajurit?",
  ui_story_1016_10160201_18_dialog_content = "Apakah itu kekuatan fisik? Atau mungkin Luminatics?",
  ui_story_1016_10160201_19_dialog_content = "Ini keahlian tempur.",
  ui_story_1016_10160201_20_dialog_content = "Bingo! Hal tersulit bagi seorang prajurit untuk dilatih adalah keahlian tempur mereka!",
  ui_story_1016_10160201_21_dialog_content = "Untuk waktu yang lama, satu-satunya cara untuk mendapatkan keahlian semacam itu adalah dengan bertarung dan bertahan dalam pertarungan yang sebenarnya.",
  ui_story_1016_10160201_22_dialog_content = "Sayangnya, perang itu brutal, dan tidak setiap prajurit cukup beruntung untuk meninggalkannya hidup-hidup.",
  ui_story_1016_10160201_23_dialog_content = "Kecuali, tentu saja, mereka telah mengalami berton-ton pertempuran simulasi!",
  ui_story_1016_10160201_24_dialog_content = "Tapi bagaimana perang realistis bisa disimulasikan...?",
  ui_story_1016_10160201_25_dialog_content = "Ini pertanyaan yang bagus, mengingat itulah yang akan kita bahas dalam pelajaran hari ini!",
  ui_story_1016_10160201_26_dialog_content = "Anda masing-masing akan diberikan perangkat seperti yang saya pegang sekarang.",
  ui_story_1016_10160201_27_dialog_content = "Setelah memakainya, kalian semua akan dikirim ke medan perang virtual pada saat yang bersamaan.",
  ui_story_1016_10160201_28_dialog_content = "Sesampai di sana, Anda akan dapat menggunakan Luminatics dan semua jenis senjata seperti yang biasa Anda lakukan di kehidupan nyata, dan lawan Anda adalah teman lama kita, Eclipsites.",
  ui_story_1016_10160201_29_dialog_content = "Perlakukan mereka sama seperti biasanya, dan jangan berhenti sampai Anda kalah!",
  ui_story_1016_10160201_30_dialog_content = "Ha ha ha! Ini mulai terdengar menarik!",
  ui_story_1016_10160201_31_dialog_content = "Mari kita lihat seberapa baik helm ini dapat mensimulasikan peperangan yang sebenarnya!",
  ui_story_1016_10160201_32_dialog_content = "Hebat, sepertinya semua orang bersiap untuk pergi!",
  ui_story_1016_10160201_33_dialog_content = "Lalu tanpa basa-basi lagi, saya akan membagikan helm agar kita bisa mulai dengan simulasi latihan tempur hari ini.",
  ui_story_1016_10160201_34_dialog_content = "Selama simulasi, performa Anda juga akan dipantau dan dinilai. Anda dapat melacak statistik Anda di layar terdekat.",
  ui_story_1016_10160201_35_dialog_content = "Angka tidak berbohong, jadi lakukan yang terbaik untuk mengumpulkan poin dan mencapai puncak papan skor!",
  ui_story_1016_10160201_36_dialog_content = "<color=#e8d9bb>Anda telah memasuki simulasi pertempuran.</color>",
  ui_story_1016_10160201_37_dialog_content = "Sepertinya ini akan sama seperti terakhir kali.",
  ui_story_1016_10160201_38_dialog_content = "Dimanakah Vice Dan Carleen? Apa mereka belum memakai helmnya?",
  ui_story_1016_10160201_39_dialog_content = "Tunggu, ini...",
  ui_story_1016_10160201_40_dialog_content = "Wah! Saya memuat hampir secara instan!",
  ui_story_1016_10160201_41_dialog_content = "Sepertinya mereka telah melakukan banyak peningkatan pada Battlefield Simulator. Tubuhku sulit membedakan antara simulasi dan kehidupan nyata!",
  ui_story_1016_10160201_42_dialog_content = "Saya kira semakin realistis simulasi pertempuran, semakin banyak insting bertahan hidup kita mulai muncul.",
  ui_story_1016_10160201_43_dialog_content = "Ini terlihat seperti garis pertahanan Illumina, bukan?",
  ui_story_1016_10160201_44_dialog_content = "<color=#e8d9bb>Semua peserta latihan telah berhasil dimuat ke dalam simulasi.</color>",
  ui_story_1016_10160201_45_dialog_content = "<color=#e8d9bb>Peringatan: Pertempuran yang akan Anda alami adalah rekreasi dari pertempuran sesungguhnya di Illumina.</color>",
  ui_story_1016_10160201_46_dialog_content = "<color=#e8d9bb>Dalam pertempuran ini, gelombang Eclipsites berhasil menembus garis pertahanan Federasi, menimbulkan banyak korban.</color>",
  ui_story_1016_10160201_47_dialog_content = "<color=#e8d9bb>Untuk menilai kemampuan tempur para peserta dengan lebih baik, skala simulasi telah dikurangi ke tingkat yang dapat dikelola oleh skuadron tiga orang.</color>",
  ui_story_1016_10160201_48_dialog_content = "<color=#e8d9bb>Setiap tim telah ditempatkan pada titik acak di seluruh medan perang. May keberuntungan memihak Anda.</color>",
  ui_story_1016_10160201_49_dialog_content = "<color=#e8d9bb>Biarkan pertempuran dimulai.</color>",
  ui_story_1016_10160201_50_dialog_content = "Jadi semua orang ditempatkan di area yang berbeda, ya?",
  ui_story_1016_10160201_51_dialog_content = "Agaknya untuk mencegah tim saling mengganggu selama pertempuran, ya.",
  ui_story_1016_10160201_52_dialog_content = "Sistem mengatakan ini adalah simulasi pertempuran Illumina yang sebenarnya. Akan membantu jika kita tahu lebih banyak tentang apa yang terjadi dalam pertempuran aslinya.",
  ui_story_1016_10160201_53_dialog_content = "Apakah Anda tahu sesuatu tentang itu, Vice?",
  ui_story_1016_10160201_54_dialog_content = "Saya benar-benar tidak. Terlalu banyak pertempuran yang terjadi di perbatasan untuk dihitung, dan kami mendapat banyak laporan tentang Eclipsites yang menerobos pertahanan kami.",
  ui_story_1016_10160201_55_dialog_content = "Jika sejarah merupakan indikasi, seperti inilah garis pertahanan kita di sebagian besar waktu.",
  ui_story_1016_10160201_56_dialog_content = "Keadaan pertempuran yang konstan ...",
  ui_story_1016_10160201_57_dialog_content = "Saya melihat Eclipse!",
  ui_story_1016_10160201_58_dialog_content = "Ada begitu banyak dari mereka... Bisakah kita benar-benar menangani ini hanya dengan kita bertiga?",
  ui_story_1016_10160201_59_dialog_content = "Tunggu... Sistem mengatakan bahwa Eclipsites berhasil menembus garis pertahanan militer.",
  ui_story_1016_10160201_60_dialog_content = "Apakah ini berarti bahwa meskipun simulasi telah diperkecil, kita tidak dapat mengubah hasil dari pertempuran ini?",
  ui_story_1016_10160201_61_dialog_content = "Perasaan tidak berdaya ini... Ini pasti yang dirasakan para prajurit Illumina ketika mereka melihat semua Eclipsites ini.",
  ui_story_1016_10160201_62_dialog_content = "Ya, tapi untungnya ini hanya simulasi.",
  ui_story_1016_10160201_63_dialog_content = "Sekarang mari kita berikan semua yang kita punya!",
  ui_story_1016_10160201_64_dialog_content = "Sepakat! Mari kita lakukan!",
  ui_story_1016_10160202_1_dialog_content = "Carleen! Anda harus mundur sekarang!",
  ui_story_1016_10160202_2_dialog_content = "aku ingin, tapi...",
  ui_story_1016_10160202_3_dialog_content = "Rasanya semakin banyak Eclipse yang kami kalahkan, semakin banyak mereka mulai muncul.",
  ui_story_1016_10160202_4_dialog_content = "Kamu benar. Seolah-olah mereka berfokus pada lokasi persis kita.",
  ui_story_1016_10160202_5_dialog_content = "Jika kita tidak segera keluar dari sini, mereka akan menyerbu kita...",
  ui_story_1016_10160202_6_dialog_content = "Hmm? Wanita Carleen!",
  ui_story_1016_10160202_7_dialog_content = "Beretta? Apa yang kamu lakukan di sini?!",
  ui_story_1016_10160202_8_dialog_content = "M-Timku tersapu oleh Eclipsites.",
  ui_story_1016_10160202_9_dialog_content = "Saya tidak punya pilihan selain bertahan selama mungkin, tetapi Eclipsites terus memaksa saya semakin jauh ke belakang.",
  ui_story_1016_10160202_10_dialog_content = "Saya menemukan sejumlah peserta selama pertempuran tanpa akhir ...",
  ui_story_1016_10160202_11_dialog_content = "Cukup bicara. Fokus pada musuh.",
  ui_story_1016_10160202_12_dialog_content = "Saya fokus pada mereka! Aku tidak membutuhkanmu untuk mengingatkanku!",
  ui_story_1016_10160202_13_dialog_content = "Anatoli juga ada di sini! Anda berada di tim Yingel, bukan?",
  ui_story_1016_10160202_14_dialog_content = "Apakah dia dan rekan setimmu yang lain juga terhanyut?",
  ui_story_1016_10160202_15_dialog_content = "Ya, tapi hanya karena seseorang ikut campur dalam pertempuran kita.",
  ui_story_1016_10160202_16_dialog_content = "Hai! Apa maksudmu dengan mengganggu? Kita berada di pihak yang sama, bukan?!",
  ui_story_1016_10160202_17_dialog_content = "Apa lagi yang akan saya sebut ketika Anda membebani kami seperti itu?",
  ui_story_1016_10160202_18_dialog_content = "Ckck!",
  ui_story_1016_10160202_19_dialog_content = "Saya tidak berpikir kita pernah bertemu sebelumnya. Apakah Anda dengan...",
  ui_story_1016_10160202_20_dialog_content = "Sekarang bukan waktunya, PlayerName! Kami praktis tenggelam dalam Eclipsites!",
  ui_story_1016_10160202_21_dialog_content = "Pada tingkat ini, kita tidak akan bisa bertahan lebih lama lagi!",
  ui_story_1016_10160202_22_dialog_content = "Anda benar, jumlah mereka terus berlipat ganda...",
  ui_story_1016_10160202_23_dialog_content = "Beretta! Anatoli! Dan, eh, kamu di sana!",
  ui_story_1016_10160202_24_dialog_content = "<size=45>Nama saya min!!!</size>",
  ui_story_1016_10160202_25_dialog_content = "Kita perlu bekerja sama! Ini satu-satunya cara kita untuk melarikan diri dari tengah semua pertempuran ini!",
  ui_story_1016_10160202_26_dialog_content = "Saya khawatir sudah terlambat... Saya tidak bisa memikirkan apa pun sekarang...",
  ui_story_1016_10160202_27_dialog_content = "Urgh—!",
  ui_story_1016_10160202_28_dialog_content = "<size=45>Beretta!!!</size>",
  ui_story_1016_10160202_29_dialog_content = "Oh, tidak, sekarang kita harus menghadapi sendiri semua Eclipsites timnya.",
  ui_story_1016_10160202_30_dialog_content = "Ahhhh! I-Mereka datang tepat ke arah kita! Apa yang harus kita lakukan?!",
  ui_story_1016_10160202_31_dialog_content = "Kita hanya perlu menjaga garis...",
  ui_story_1016_10160202_32_dialog_content = "Semuanya, coba hancurkan musuh di belakangmu! Sepertinya ada lebih sedikit dari mereka di sana!",
  ui_story_1016_10160202_34_dialog_content = "Awas, PlayerName!",
  ui_story_1016_10160202_35_dialog_content = "Ugh—!",
  ui_story_1016_10160202_36_dialog_content = "Dibelakangmu! Putar balik cepat-",
  ui_story_1016_10160202_37_dialog_content = "<color=#e8d9bb>Bip—</color>",
  ui_story_1016_10160202_38_dialog_content = "<color=#e8d9bb>Anda telah keluar dari simulasi pertempuran.</color>",
  ui_story_1016_10160202_39_dialog_content = "Fiuh... aku keluar, ya?",
  ui_story_1016_10160202_40_dialog_content = "Bahkan sekarat di Battle Simulator terasa sangat nyata...",
  ui_story_1016_10160202_41_dialog_content = "bagaimana ya Vice Dan Carleen bertahan?",
  ui_story_1016_10160202_42_dialog_content = "Ah—Sepertinya kita semua terbunuh.",
  ui_story_1016_10160202_43_dialog_content = "Memang. Melawan banyak Eclipsites itu, tidak pernah ada peluang untuk menang.",
  ui_story_1016_10160202_44_dialog_content = "Haha, mereka menangkapmu juga. Bagaimana perasaan Anda tentang simulasi ini?",
  ui_story_1016_10160202_45_dialog_content = "Rasanya sangat nyata. Gronru benar, ini adalah alat pamungkas untuk memberi prajurit keahlian tempur yang sesungguhnya.",
  ui_story_1016_10160202_46_dialog_content = "Pertarungan menegangkan seperti itu cukup sulit untuk dialami di dunia nyata, apalagi bertahan.",
  ui_story_1016_10160202_47_dialog_content = "Tidak bercanda. Jika kita benar-benar bertarung dalam pertempuran itu, tidak mungkin kita semua bisa kembali hidup-hidup.",
  ui_story_1016_10160202_48_dialog_content = "Saya tau? Setelah pertempuran itu, saya merasa seperti saya memahami parahnya situasi Illumina jauh lebih baik.",
  ui_story_1016_10160202_49_dialog_content = "Saya kira beberapa tentara... Tidak punya pilihan selain bertarung dalam pertempuran yang kalah.",
  ui_story_1016_10160202_50_dialog_content = "Ya...",
  ui_story_1016_10160202_51_dialog_content = "Baiklah, kelas! Bagi Anda yang keluar dari simulasi, harap arahkan perhatian Anda ke sini.",
  ui_story_1016_10160202_52_dialog_content = "Saya yakin bahwa pertempuran dan simulator meninggalkan kesan abadi pada Anda masing-masing.",
  ui_story_1016_10160202_53_dialog_content = "Jadi, inilah survei pengalaman pengguna bagi Anda untuk membagikan umpan balik Anda tentang Battle Simulator!",
  ui_story_1016_10160202_54_dialog_content = "Tidak ada yang pergi sampai semua orang menulis sesuatu!",
  ui_story_1016_10160202_55_dialog_content = "Uh... Survei?",
  ui_story_1016_10160202_56_dialog_content = "Pengajar Gronru? Apakah Anda yakin tidak hanya menggunakan kami untuk menjalankan tes?",
  ui_story_1016_10160202_57_dialog_content = "Apa? Bagaimana Anda bisa mengatakan sesuatu seperti itu ?!",
  ui_story_1016_10160202_58_dialog_content = "Umpan balik Anda sangat penting untuk meningkatkan fungsi Battle Simulator!",
  ui_story_1016_10160202_59_dialog_content = "Semua orang akan mendapat manfaat dari itu, bukan begitu?",
  ui_story_1016_10160202_60_dialog_content = "Yah, ayo...",
  ui_story_1016_10160202_61_dialog_content = "<color=#e8d9bb>Dua puluh menit kemudian</color>",
  ui_story_1016_10160202_62_dialog_content = "Akhirnya! Itu adalah survei terpanjang yang pernah saya isi...",
  ui_story_1016_10160202_63_dialog_content = "Aku tahu! Tanganku pegal karena terlalu banyak menulis!",
  ui_story_1016_10160202_64_dialog_content = "Survei meminta kami untuk memberikan skor kami dari simulasi pertempuran. Adakah yang tahu berapa banyak poin yang kami dapatkan?",
  ui_story_1016_10160202_65_dialog_content = "Tidak tahu. Saya bahkan tidak tahu apakah kami melakukannya dengan baik atau tidak.",
  ui_story_1016_10160202_66_dialog_content = "Pengajar Gronru, dimana kita bisa melihat skor kita?",
  ui_story_1016_10160202_67_dialog_content = "Oh, benar! Anda harus menunggu beberapa saat lagi.",
  ui_story_1016_10160202_68_dialog_content = "Masih ada beberapa peserta yang bertarung di dalam simulasi.",
  ui_story_1016_10160202_69_dialog_content = "Mereka masih di sana?! Tapi sekarang sudah begitu lama...",
  ui_story_1016_10160202_70_dialog_content = "<color=#e8d9bb>Simulasi pertempuran sekarang selesai.</color>",
  ui_story_1016_10160202_71_dialog_content = "<color=#e8d9bb>Menghitung semua hasil pertempuran—</color>",
  ui_story_1016_10160202_72_dialog_content = "<color=#e8d9bb>Perhitungan selesai. Aurorian menang.</color>",
  ui_story_1016_10160202_73_dialog_content = "Apa? Kami menang?!",
  ui_story_1016_10160202_74_dialog_content = "<size=45>Mereka menang?!?</size>",
  ui_story_1016_10160202_75_dialog_content = "Mustahil! Tidak ada yang bisa menyelesaikan tahap ini...!",
  ui_story_1016_10160202_76_dialog_content = "Siapa yang terakhir keluar dari simulasi?",
  ui_story_1016_10160202_77_dialog_content = "Fiuh! Helm ini sangat tidak nyaman jika dipakai terlalu lama.",
  ui_story_1016_10160202_78_dialog_content = "Simulasi itu terasa sangat nyata! Itu tidak buruk sama sekali jika Anda bertanya kepada saya!",
  ui_story_1016_10160202_79_dialog_content = "Saya kira terus-menerus terlibat dalam perang telah memberi Illumina gagasan yang sangat jelas tentang seperti apa pertempuran itu.",
  ui_story_1016_10160202_80_dialog_content = "Tetapi pengalaman yang terlalu realistis juga memiliki kekurangan.",
  ui_story_1016_10160202_81_dialog_content = "Jika Anda tahu bagaimana pertarungan aslinya berlangsung, Anda dapat memprediksi setiap perubahan di medan perang.",
  ui_story_1016_10160202_82_dialog_content = "Itu, pada gilirannya, secara drastis menurunkan kesulitan simulasi.",
  ui_story_1016_10160202_83_dialog_content = "K-Dia pikir itu terlalu mudah?!",
  ui_story_1016_10160202_84_dialog_content = "Saya tidak suka lingkungan simulasi.",
  ui_story_1016_10160202_85_dialog_content = "Tidak peduli seberapa tulus doa saya, saya hanya dijawab oleh cahaya buatan.",
  ui_story_1016_10160202_86_dialog_content = "Jangan terlalu serius, Yusuf! Anggap saja ini sebagai permainan!",
  ui_story_1016_10160202_87_dialog_content = "Hei lihat, skor kita akhirnya masuk!",
  ui_story_1016_10160202_88_dialog_content = "Tim Leo... Skor mereka sangat tinggi...",
  ui_story_1016_10160202_89_dialog_content = "Bahkan tidak ada yang mendekati...",
  ui_story_1016_10160202_90_dialog_content = "Kita bertempur di medan perang yang sama, bukan?",
  ui_story_1016_10160202_91_dialog_content = "Bagaimana mereka berhasil mengatasi semua Eclipsites itu...?",
  ui_story_1016_10160202_92_dialog_content = "Saya melihat cara mereka melakukannya.",
  ui_story_1016_10160202_93_dialog_content = "Itu mereka... Merekalah yang membawa semua Eclipsites itu ke atas kepala kita...",
  ui_story_1016_10160202_94_dialog_content = "Apa?!",
  ui_story_1016_10160202_95_dialog_content = "Tapi bagaimana caranya? Bagaimana mereka bisa melakukan hal seperti itu?",
  ui_story_1016_10160202_96_dialog_content = "Itu benar. Mereka tahu cara memancing Eclipsites yang masuk untuk mengikuti mereka sampai mereka semua berkumpul di satu tempat.",
  ui_story_1016_10160202_97_dialog_content = "Setelah itu, mereka menggunakan medan untuk keuntungan mereka dan memaksa Eclipsites untuk melawan mereka di koridor sempit. Begitu mereka tidak bisa mengandalkan jumlah mereka untuk menang, tim Leo dengan mudah memusnahkan mereka.",
  ui_story_1016_10160202_98_dialog_content = "Eclipsites tidak berbeda dengan sekawanan domba, berjalan satu per satu ke sarang serigala yang kelaparan ...",
  ui_story_1016_10160202_99_dialog_content = "Herding Eclipsites... Saya tidak tahu itu bahkan bisa dilakukan...",
  ui_story_1016_10160202_100_dialog_content = "Itu bukan strategi yang sangat pintar, tetapi ketika Anda dihadapkan dengan banyak musuh seperti itu, yang dapat Anda lakukan hanyalah memeras otak untuk mencari solusi.",
  ui_story_1016_10160202_101_dialog_content = "Anda juga tidak akan menemukan jawabannya di buku. Tidak ada buku yang benar-benar dapat memberi tahu Anda cara memenangkan pertempuran yang tidak dapat dimenangkan.",
  ui_story_1016_10160202_102_dialog_content = "Satu-satunya pilihan Anda adalah membuat rencana dan mewujudkannya, tidak peduli seberapa menggelikan kelihatannya.",
  ui_story_1016_10160202_103_dialog_content = "Dan jika Anda cukup beruntung untuk bertahan hidup berkali-kali karena strategi konyol itu, itu berarti Anda telah menemukan cara Anda sendiri untuk muncul sebagai pemenang dalam pertempuran.",
  ui_story_1016_10160202_104_dialog_content = "(Itu benar! Ketika saya pertama kali melihat Leo, dia menggunakan metode yang paling tidak biasa untuk bertarung.)",
  ui_story_1016_10160202_105_dialog_content = "(Saya rasa tidak ada di antara kita yang bisa dibandingkan dengan orang-orang dari Twilight dalam hal improvisasi di medan perang.)",
  ui_story_1016_10160202_106_dialog_content = "Heh, hal yang cukup kuat di sana, Leo! Kalian berhasil membuat seisi kelas terdiam!",
  ui_story_1016_10160202_107_dialog_content = "Apakah ada di antara kalian yang mencatat? Atau apakah Anda terlalu sibuk menatap papan skor?",
  ui_story_1016_10160202_108_dialog_content = "Sejujurnya, sepertinya kalian semua adalah sekelompok anak yang baru saja melihat senjata untuk pertama kalinya!",
  ui_story_1016_10160301_1_dialog_content = "<color=#e8d9bb>Satu minggu kemudian</color>",
  ui_story_1016_10160301_2_dialog_content = "Hah? Apa yang saya lakukan di kantor? Apakah saya salah belok di suatu tempat?",
  ui_story_1016_10160301_3_dialog_content = "Aku yakin kelasnya...",
  ui_story_1016_10160301_4_dialog_content = "Apakah Anda berjalan-jalan, PlayerName?",
  ui_story_1016_10160301_5_dialog_content = "Kelas akan segera dimulai, lho.",
  ui_story_1016_10160301_6_dialog_content = "Anatoli! Oh, syukurlah!",
  ui_story_1016_10160301_7_dialog_content = "Apakah Anda tahu bagaimana menuju ke kelas dari sini? Aku sudah berjalan di lorong-lorong ini begitu lama sehingga aku mulai pusing, heheheh.",
  ui_story_1016_10160301_8_dialog_content = "Jadi begitu. Ikuti aku.",
  ui_story_1016_10160301_9_dialog_content = "Anda beruntung saya menemukan Anda, atau Anda mungkin kehilangan kredit karena terlambat.",
  ui_story_1016_10160301_10_dialog_content = "Semua orang berbicara tentang kredit hari ini. Apa sebenarnya mereka?",
  ui_story_1016_10160301_11_dialog_content = "Maksud Anda, Anda belum melihat buku pegangan yang Anda berikan kemarin?",
  ui_story_1016_10160301_12_dialog_content = "Belum, tidak. Gronru menyeret saya untuk melakukan beberapa pekerjaan debug pada Soroz kemarin.",
  ui_story_1016_10160301_13_dialog_content = "Lalu izinkan saya memberi Anda penjelasan singkat.",
  ui_story_1016_10160301_14_dialog_content = "Mulai hari ini, penampilan semua orang di kelasnya akan dicatat sebagai jumlah kredit tertentu.",
  ui_story_1016_10160301_15_dialog_content = "Setiap peserta akan terus mengakumulasi kredit hingga akhir fase pembelajaran.",
  ui_story_1016_10160301_16_dialog_content = "Penggunaan yang paling jelas dari kredit ini adalah untuk menilai kemampuan Anda. Namun, mereka juga melayani tujuan lain.",
  ui_story_1016_10160301_17_dialog_content = "Kredit Anda juga akan membantu Anda selama penilaian.",
  ui_story_1016_10160301_18_dialog_content = "Kok bisa?",
  ui_story_1016_10160301_19_dialog_content = "Sebelum memulai fase penilaian, Anda akan diizinkan menukar kredit Anda dengan item tertentu, yang dapat meningkatkan kekuatan Anda secara keseluruhan.",
  ui_story_1016_10160301_20_dialog_content = "Semakin banyak kredit yang Anda peroleh, semakin banyak dukungan yang dapat Anda peroleh.",
  ui_story_1016_10160301_21_dialog_content = "Untuk alasan ini, setiap orang berharap mendapatkan kredit sebanyak mungkin selama kelas mereka.",
  ui_story_1016_10160301_22_dialog_content = "Tidak heran semua orang begitu kompetitif akhir-akhir ini!",
  ui_story_1016_10160301_23_dialog_content = "Itu benar. Anda harus menanggapinya dengan lebih serius jika ingin ada harapan untuk menang di sini.",
  ui_story_1016_10160301_24_dialog_content = "Sepertinya kita berhasil tepat pada waktunya.",
  ui_story_1016_10160301_25_dialog_content = "Apakah Anda menghafal jalan di sini kali ini?",
  ui_story_1016_10160301_26_dialog_content = "Haha, saya yakin berharap begitu!",
  ui_story_1016_10160301_27_dialog_content = "Jadi apa yang kita pelajari hari ini?",
  ui_story_1016_10160301_28_dialog_content = "Strategi ofensif dalam pertarungan langsung.",
  ui_story_1016_10160301_29_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_1016_10160301_30_dialog_content = "Hai! Kalian berdua di sana!",
  ui_story_1016_10160301_31_dialog_content = "Dua puluh detik lagi dan Anda akan terlambat!",
  ui_story_1016_10160301_32_dialog_content = "Hampir saja...",
  ui_story_1016_10160301_33_dialog_content = "Baiklah, sekarang siswa yang paling lambat akhirnya tiba, kita bisa memulai pelajaran kita.",
  ui_story_1016_10160301_34_dialog_content = "Nama saya adalah Wrath. Saya Kapten Legion Penjaga Illumina, sekaligus instruktur Anda untuk hari ini.",
  ui_story_1016_10160301_35_dialog_content = "Dan topik kelas hari ini sangat sederhana: berkelahi!",
  ui_story_1016_10160301_36_dialog_content = "Berkelahi?",
  ui_story_1016_10160301_37_dialog_content = "Sekarang Anda semua mungkin berpikir sendiri, \"Berjuang? Apa yang bisa kita pelajari dari berkelahi?\"",
  ui_story_1016_10160301_38_dialog_content = "Saya tahu Anda semua yang berdiri di sini memiliki semacam kepercayaan pada kemampuan bertarung Anda.",
  ui_story_1016_10160301_39_dialog_content = "Namun, saya yakin banyak dari Anda juga pemalas dalam hal berkelahi.",
  ui_story_1016_10160301_40_dialog_content = "Apa yang akan saya ajarkan kepada Anda bukanlah cara untuk menang, tetapi mencapai kemenangan yang sempurna!",
  ui_story_1016_10160301_41_dialog_content = "Dalam pertarungan yang dapat dimenangkan, mengakhiri segalanya dengan cepat akan membantu Anda menghemat kekuatan untuk pertempuran berikutnya.",
  ui_story_1016_10160301_42_dialog_content = "Kemenangan tidak selalu datang dengan mudah. Setiap tindakan yang mengarah ke sana harus dijalankan dengan sempurna.",
  ui_story_1016_10160301_43_dialog_content = "Kurasa itu masuk akal…",
  ui_story_1016_10160301_44_dialog_content = "Saya tidak berpikir saya telah menjalani pelatihan tempur yang berfokus secara khusus pada efisiensi.",
  ui_story_1016_10160301_45_dialog_content = "Dia benar, meskipun melakukan segalanya dengan sempurna tampaknya sedikit tidak realistis.",
  ui_story_1016_10160301_46_dialog_content = "Apakah Anda dapat tampil di level yang sempurna, Instruktur Wrath?",
  ui_story_1016_10160301_47_dialog_content = "Apakah Anda meragukan saya, punk?",
  ui_story_1016_10160301_48_dialog_content = "Tidak sama sekali, saya hanya khawatir bahwa saya tidak akan dapat mempelajari sesuatu yang praktis.",
  ui_story_1016_10160301_49_dialog_content = "Tch. Saya lebih khawatir bahwa Anda tidak akan bisa menerima pelatihan saya.",
  ui_story_1016_10160301_50_dialog_content = "Obrolan ringan yang cukup. Berkumpullah dengan kelompokmu, kalian semua!",
  ui_story_1016_10160301_51_dialog_content = "Hari ini kita akan fokus pada pertempuran nyata, dan kamu akan menghadapi prajurit Illumina yang sangat terlatih untuk kelas hari ini.",
  ui_story_1016_10160301_52_dialog_content = "Kelompok pertama, bersiaplah!",
  ui_story_1016_10160301_53_dialog_content = "<size=45>Ya Bu!</size>",
  ui_story_1016_10160301_54_dialog_content = "Mari beri siswa ini salam Illumina yang tepat.",
  ui_story_1016_10160301_55_dialog_content = "<size=45>Ya Bu!</size>",
  ui_story_1016_10160301_56_dialog_content = "Dan pastikan untuk memberikan sambutan yang sangat hangat kepada anak laki-laki ksatria dari Lumopolis itu.",
  ui_story_1016_10160301_57_dialog_content = "Jika itu masih belum cukup bagi Anda, silakan datang menemui saya setelah kelas untuk les privat!",
  ui_story_1016_10160301_58_dialog_content = "Saya pikir saya hanya akan lebih fokus pada pelajaran hari ini saja.",
  ui_story_1016_10160301_59_dialog_content = "Kami membutuhkan semua kredit yang bisa kami dapatkan, bukan?",
  ui_story_1016_10160301_60_dialog_content = "Itu benar. Ini adalah kesempatan pertama kita untuk mendapatkan kredit, jadi mari lakukan yang terbaik!",
  ui_story_1016_10160301_61_dialog_content = "Apa yang harus saya lakukan, Yingel?",
  ui_story_1016_10160301_62_dialog_content = "Tenang saja untuk saat ini.",
  ui_story_1016_10160301_63_dialog_content = "<size=32>Apa hanya aku... atau para siswa ini terlihat sedikit menakutkan...?</size>",
  ui_story_1016_10160301_64_dialog_content = "<size=32>Aku di sana bersamamu...</size>",
  ui_story_1016_10160401_1_dialog_content = "<color=#e8d9bb>Satu bulan kemudian</color>",
  ui_story_1016_10160401_2_dialog_content = "Baiklah, cukup untuk pelajaran hari ini.",
  ui_story_1016_10160401_3_dialog_content = "Kelas dibubarkan.",
  ui_story_1016_10160401_4_dialog_content = "Jalan untuk pergi, PlayerName! Kami mencetak banyak kredit hari ini!",
  ui_story_1016_10160401_5_dialog_content = "Ya, tapi tidak mudah ketika semua orang berjuang untuk melakukan hal yang sama. Aku lelah.",
  ui_story_1016_10160401_6_dialog_content = "Sekarang kita mendekati akhir fase pembelajaran, wajar saja jika persaingan menjadi begitu sengit.",
  ui_story_1016_10160401_7_dialog_content = "Sudahkah Anda melihat peringkat untuk hari ini?",
  ui_story_1016_10160401_8_dialog_content = "Belum. Di mana kita dalam daftar?",
  ui_story_1016_10160401_9_dialog_content = "Posisi ketiga.",
  ui_story_1016_10160401_10_dialog_content = "Wow! Kami naik dari urutan keempat!",
  ui_story_1016_10160401_11_dialog_content = "Hal-hal terlihat! Bagaimana kabar tempat pertama dan kedua?",
  ui_story_1016_10160401_12_dialog_content = "Tim Leo jauh di depan orang lain di tempat pertama. Tidak ada kejutan di sana.",
  ui_story_1016_10160401_13_dialog_content = "Faktanya... Saya khawatir tidak ada tim yang mampu menutup celah sebelum dimulainya fase berikutnya.",
  ui_story_1016_10160401_14_dialog_content = "Jadi mereka masih memimpin...",
  ui_story_1016_10160401_15_dialog_content = "Di tempat kedua adalah Tim Yingel, meskipun baru belakangan ini mereka mulai menunjukkan bakat mereka.",
  ui_story_1016_10160401_16_dialog_content = "Tim mereka tidak memiliki kekurangan yang jelas dan sejauh ini telah tampil baik di setiap kelas, yang telah mengamankan tempat mereka di klasemen.",
  ui_story_1016_10160401_17_dialog_content = "Seberapa jauh kita di belakang mereka?",
  ui_story_1016_10160401_18_dialog_content = "Sekitar setengah dari jarak mereka di belakang Tim Leo?",
  ui_story_1016_10160401_19_dialog_content = "Kedengarannya seperti mereka cukup jauh di depan, lalu...",
  ui_story_1016_10160401_20_dialog_content = "Performa kelas Yingel sejauh ini luar biasa. Memang sulit melampaui dia dalam hal ini.",
  ui_story_1016_10160401_21_dialog_content = "Tetapi di luar kelas adalah cerita yang sama sekali berbeda.",
  ui_story_1016_10160401_22_dialog_content = "Di luar kelas?",
  ui_story_1016_10160401_23_dialog_content = "Kemarin, saya melihat sejumlah tim melakukan latihan ekstrakurikuler sendiri-sendiri.",
  ui_story_1016_10160401_24_dialog_content = "Setelah itu, mereka menyerahkan hasil pelatihan mereka kepada instruktur untuk ditukar dengan kredit.",
  ui_story_1016_10160401_25_dialog_content = "Apa? Aku tidak tahu kita bisa melakukan itu!",
  ui_story_1016_10160401_26_dialog_content = "Memang. Tampaknya penyelenggara Latihan Militer Gabungan ini sangat menekankan pelatihan bagi kita semua.",
  ui_story_1016_10160401_27_dialog_content = "Dan meskipun metode ini tidak menawarkan banyak kredit, kredit dapat bertambah seiring waktu.",
  ui_story_1016_10160401_28_dialog_content = "Ini mungkin cara kami untuk mengungguli Tim Yingel.",
  ui_story_1016_10160401_29_dialog_content = "Ya! Saya pikir ini adalah ide yang hebat!",
  ui_story_1016_10160401_30_dialog_content = "Kalian berdua benar-benar bersemangat. Kalau begini terus, kita akan bersaing dengan yang lain setiap jam sepanjang hari!",
  ui_story_1016_10160401_31_dialog_content = "Baiklah, mari kita lihat jadwalnya.",
  ui_story_1016_10160401_32_dialog_content = "Kita perlu merencanakan semuanya dengan hati-hati jika kita ingin memaksimalkan kredit kita.",
  ui_story_1016_10160401_33_dialog_content = "<color=#e8d9bb>Keesokan harinya, di ruang kelas</color>",
  ui_story_1016_10160401_34_dialog_content = "Semakin banyak peserta yang tinggal setelah kelas selesai.",
  ui_story_1016_10160401_35_dialog_content = "Haruskah kita melakukan beberapa pelatihan ekstrakurikuler juga?",
  ui_story_1016_10160401_36_dialog_content = "Anda dipersilakan untuk melakukannya sendiri.",
  ui_story_1016_10160401_37_dialog_content = "Tetapi jika hanya untuk mendapatkan lebih banyak kredit, itu tidak perlu.",
  ui_story_1016_10160401_38_dialog_content = "Tetapi semakin banyak kredit yang kita peroleh, semakin banyak keuntungan yang akan kita dapatkan dalam penilaian. Bukankah itu penting?",
  ui_story_1016_10160401_39_dialog_content = "Ya, tapi kita tidak perlu melakukan latihan bersama ini terlalu serius...",
  ui_story_1016_10160401_40_dialog_content = "Lihat, Yingel.",
  ui_story_1016_10160401_41_dialog_content = "Lantai dan sparring partner di sana sangat berwarna sekarang.",
  ui_story_1016_10160401_42_dialog_content = "Sangat berwarna?",
  ui_story_1016_10160401_43_dialog_content = "Apa yang telah terjadi? Apakah itu cat?",
  ui_story_1016_10160401_44_dialog_content = "Boneka pelatihan meledak tiba-tiba sekarang.",
  ui_story_1016_10160401_45_dialog_content = "...",
  ui_story_1016_10160401_46_dialog_content = "Saya menduga seseorang mengisinya dengan berbagai jenis cat sebelumnya.",
  ui_story_1016_10160401_47_dialog_content = "Apakah mungkin itu Vivian dan yang lainnya melakukan ini?",
  ui_story_1016_10160401_48_dialog_content = "Tentunya mereka tidak akan memainkan lelucon kekanak-kanakan seperti itu, kan?",
  ui_story_1016_10160401_49_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_1016_10160401_50_dialog_content = "<size=45>Apakah itu pistol?!</size>",
  ui_story_1016_10160401_51_dialog_content = "Apa yang kamu pikir kamu lakukan?!?",
  ui_story_1016_10160401_52_dialog_content = "Aku…",
  ui_story_1016_10160401_53_dialog_content = "Chloe, kau baik-baik saja?",
  ui_story_1016_10160401_54_dialog_content = "Aku baik-baik saja. Tidak ada peluru yang ditembakkan. Satu-satunya hal yang keluar adalah setumpuk confetti.",
  ui_story_1016_10160401_55_dialog_content = "Telingaku masih berdenging dari seberapa keras suara tembakan itu, meskipun...",
  ui_story_1016_10160401_56_dialog_content = "Jelaskan dirimu, prajurit! Bagaimana hal seperti ini bisa terjadi?!",
  ui_story_1016_10160401_57_dialog_content = "Saya tidak berpikir itu salahnya, Beretta.",
  ui_story_1016_10160401_58_dialog_content = "Lihatlah ekspresi terkejut di wajah mereka.",
  ui_story_1016_10160401_59_dialog_content = "Hah?",
  ui_story_1016_10160401_60_dialog_content = "Memang benar... Ada yang tidak beres saat aku menarik pelatuknya, jadi aku menjauhkan senjatanya secepat mungkin.",
  ui_story_1016_10160401_61_dialog_content = "Sepertinya firasatku benar. Seseorang mengganti salah satu blank saya dengan... confetti?",
  ui_story_1016_10160401_62_dialog_content = "Seseorang mengganti amunisi Anda? Tapi bagaimana bisa?!",
  ui_story_1016_10160401_63_dialog_content = "Aku sama bingungnya denganmu.",
  ui_story_1016_10160401_64_dialog_content = "Mohon maafkan saya. Saya akan melaporkan ini ke atasan saya segera.",
  ui_story_1016_10160401_65_dialog_content = "Bagian yang kosong ditukar?",
  ui_story_1016_10160401_66_dialog_content = "Tapi siapa yang akan melakukan sesuatu yang sangat berbahaya...?",
  ui_story_1016_10160401_67_dialog_content = "Ini lebih konyol daripada berbahaya.",
  ui_story_1016_10160401_68_dialog_content = "Seseorang ingin mengganggu pelatihan orang lain untuk menghentikan mereka mendapatkan kredit.",
  ui_story_1016_10160401_69_dialog_content = "Tetapi siapa yang akan menggunakan hal-hal yang tidak dewasa seperti itu?",
  ui_story_1016_10160401_70_dialog_content = "Sulit untuk mengatakannya. Dengan begitu banyak faksi yang berkumpul di sini, taruhannya tinggi dan rumit.",
  ui_story_1016_10160401_71_dialog_content = "Tapi selama kita bisa menghindari tersedot ke dalam lumpur ini, itu bukan urusan kita.",
  ui_story_1016_10160401_72_dialog_content = "Jangan terlibat dengan siapa pun atau apa pun di luar kelas kita, mengerti?",
  ui_story_1016_10160401_73_dialog_content = "Aku mengerti.",
  ui_story_1016_10160401_74_dialog_content = "Ayo, Axelia.",
  ui_story_1016_10160401_75_dialog_content = "Oke.",
  ui_story_1016_10160401_76_dialog_content = "<color=#e8d9bb>Sementara itu, di Laboratorium Illumina</color>",
  ui_story_1016_10160401_77_dialog_content = "Saya melakukannya! Saya mendapat izin untuk menggunakan Battle Simulator!",
  ui_story_1016_10160401_78_dialog_content = "Kami akan dapat menghemat banyak waktu dan energi dengan ini!",
  ui_story_1016_10160401_79_dialog_content = "Sepakat. Setelah peserta lainnya meninggalkan kelas, kita dapat kembali dan melakukan beberapa pelatihan ketahanan.",
  ui_story_1016_10160401_80_dialog_content = "Itu harus menjadi rute kita yang paling efisien untuk mendapatkan lebih banyak kredit.",
  ui_story_1016_10160401_81_dialog_content = "Anda telah banyak memikirkan hal ini, bukan, Carleen?",
  ui_story_1016_10160401_82_dialog_content = "Saya adalah peserta latihan bersama terakhir, ingat? Saya masih memiliki beberapa pengetahuan yang berguna dari pengalaman saya sebelumnya.",
  ui_story_1016_10160401_83_dialog_content = "Tidak ada waktu untuk kalah. Mari kita mulai sekarang juga.",
  ui_story_1016_10160401_84_dialog_content = "Tentu! Kami baru saja memasang helm di kepala kami seperti terakhir kali, kan?",
  ui_story_1016_10160401_85_dialog_content = "Hah? dimana saya?",
  ui_story_1016_10160401_86_dialog_content = "Ini tidak terlihat seperti simulasi terakhir.",
  ui_story_1016_10160401_87_dialog_content = "Dimana musuhnya?",
  ui_story_1016_10160401_88_dialog_content = "Biarkan saya menjelajahi daerah itu ...",
  ui_story_1016_10160401_89_option_content = "Force Boost!",
  ui_story_1016_10160401_90_dialog_content = "<anim type=Shake>Hiss...</anim>",
  ui_story_1016_10160401_91_dialog_content = "Saya merasakan banyak musuh! Bahkan lebih dari terakhir kali!",
  ui_story_1016_10160401_92_dialog_content = "Aliran Gelap yang mereka keluarkan juga sangat kuat!",
  ui_story_1016_10160401_93_dialog_content = "Jangan bilang kita harus kabur lagi?",
  ui_story_1016_10160401_94_dialog_content = "Saya tidak berpikir ada tempat bagi kita untuk lari ...",
  ui_story_1016_10160401_95_dialog_content = "Mereka datang!",
  ui_story_1016_10160401_96_dialog_content = "<anim type=Shake><size=50>Graaaaah!!!</size></anim>",
  ui_story_1016_10160401_97_dialog_content = "Ice Blossom! Menyebar!",
  ui_story_1016_10160401_98_dialog_content = "Seranganku... tidak berpengaruh...",
  ui_story_1016_10160401_99_dialog_content = "Pasti ada yang salah dengan Eclipsites ini!",
  ui_story_1016_10160401_100_dialog_content = "Terserah, ini masih simulasi. Terus berjuang!",
  ui_story_1016_10160402_11_dialog_content = "Awas, kalian berdua!",
  ui_story_1016_10160402_12_dialog_content = "Bahkan ada lebih banyak di sini ...",
  ui_story_1016_10160402_13_dialog_content = "Carleen! Vice!",
  ui_story_1016_10160402_14_dialog_content = "<size=45>Ah-!!!</size>",
  ui_story_1016_10160402_15_dialog_content = "<anim type=Shake>Terkesiap—Terkesiap—</anim>",
  ui_story_1016_10160402_16_dialog_content = "Pertarungan macam apa itu...",
  ui_story_1016_10160402_17_dialog_content = "Kamu benar. Ada yang salah dengan Eclipsites itu.",
  ui_story_1016_10160402_18_dialog_content = "Kuat bahkan tidak mulai menggambarkan monster-monster itu.",
  ui_story_1016_10160402_19_dialog_content = "Kamu benar. Serangan mereka tidak berbeda dengan Eclipsites biasa, tetapi Darkflow mereka sangat padat...",
  ui_story_1016_10160402_20_dialog_content = "Anda tidak berpikir bahwa seseorang mungkin telah mengutak-atik Battle Simulator, bukan?",
  ui_story_1016_10160402_21_dialog_content = "Majulah.",
  ui_story_1016_10160402_22_dialog_content = "Guardian One pernah mengatakan kepada saya bahwa tidak peduli seberapa realistis sebuah simulasi, itu tetap saja hanya data.",
  ui_story_1016_10160402_23_dialog_content = "Pertarungan yang kami alami dalam simulasi lebih seperti semacam komputasi data.",
  ui_story_1016_10160402_24_dialog_content = "Jika seseorang mengubah angka dalam data dan membuatnya sangat besar, keseimbangan dalam simulasi akan benar-benar hilang.",
  ui_story_1016_10160402_25_dialog_content = "Hasilnya bahkan mungkin terlihat seperti yang baru saja kita lihat.",
  ui_story_1016_10160402_26_dialog_content = "Kamu benar! Data yang melibatkan tingkat kekuatan Eclipsites itu pasti telah diubah untuk menjadikannya sangat kuat!",
  ui_story_1016_10160402_27_dialog_content = "Tapi siapa yang akan melakukan sesuatu yang salah?",
  ui_story_1016_10160402_28_dialog_content = "PlayerName, dapatkah Anda merasakan ada orang di sekitar?",
  ui_story_1016_10160402_29_dialog_content = "Aku mencoba, tapi aku tidak merasakan ada yang mencurigakan.",
  ui_story_1016_10160402_30_dialog_content = "Oh, begitu…",
  ui_story_1016_10160402_31_dialog_content = "Jika kecurigaan kita benar, kita harus melaporkannya kepada instruktur kita.",
  ui_story_1016_10160402_32_dialog_content = "Saya pikir lebih baik jika kita menunda pelatihan kita untuk saat ini. Segalanya cukup aneh, apa adanya.",
  ui_story_1016_10160402_33_dialog_content = "Sepakat. Mari kita kembali ke barak.",
  ui_story_1016_10160402_34_dialog_content = "Jadi seseorang benar-benar mengutak-atik simulasinya, ya?",
  ui_story_1016_10160402_35_dialog_content = "Ya. Gronru menjalankan pemindaian diagnostik penuh dari Battle Simulator, dan menemukan banyak data yang telah diubah secara manual.",
  ui_story_1016_10160402_36_dialog_content = "Sayangnya, kami masih belum tahu siapa yang melakukannya.",
  ui_story_1016_10160402_37_dialog_content = "Apa motif pelaku melakukan ini...?",
  ui_story_1016_10160402_38_dialog_content = "Apapun yang terjadi di dalam Battle Simulator tidak memiliki efek nyata pada kita atau dunia nyata.",
  ui_story_1016_10160402_39_dialog_content = "Dengan mengingat hal itu... Sepertinya pelakunya mencoba menghentikan kami untuk mendapatkan lebih banyak kredit.",
  ui_story_1016_10160402_40_dialog_content = "Ketika Anda mengatakannya seperti itu, itu masuk akal.",
  ui_story_1016_10160402_41_dialog_content = "Tapi bukankah itu berarti pelakunya adalah salah satu peserta?",
  ui_story_1016_10160402_42_dialog_content = "Itu sangat mungkin. Bagaimanapun, persaingan yang ketat pasti akan mengundang pesaing yang lebih ganas lagi.",
  ui_story_1016_10160402_43_dialog_content = "Pada Latihan Militer Gabungan sebelumnya, selalu terjadi ketegangan antara peserta dari Lumopolis dan Illumina.",
  ui_story_1016_10160402_44_dialog_content = "Dari perspektif itu, latihan ini hanyalah versi kecil dari persaingan antar faksi yang berbeda.",
  ui_story_1016_10160402_45_dialog_content = "Tapi mengapa mereka menargetkan tim kita?",
  ui_story_1016_10160402_46_dialog_content = "Saya Caelestite, Carleen dari Lumopolis, dan Vice adalah dari Illumina.",
  ui_story_1016_10160402_47_dialog_content = "Persaingan antara faksi yang berbeda seharusnya tidak ada hubungannya dengan kita, bukan?",
  ui_story_1016_10160402_48_dialog_content = "Saya tidak berpikir kami harus ditargetkan.",
  ui_story_1016_10160402_49_dialog_content = "Ingat, kami baru saja mendapat izin untuk menggunakan Battle Simulator di luar jadwal reguler.",
  ui_story_1016_10160402_50_dialog_content = "Mungkin saja siapa pun yang mengutak-atik simulator tidak tahu kami akan menggunakannya nanti.",
  ui_story_1016_10160402_51_dialog_content = "Lalu target sebenarnya...",
  ui_story_1016_10160402_52_dialog_content = "Menurut jadwal, tim Leo adalah tim selanjutnya yang menggunakan Battle Simulator.",
  ui_story_1016_10160402_53_dialog_content = "Oh! Itu sangat masuk akal kalau begitu!",
  ui_story_1016_10160402_54_dialog_content = "Karena mereka berada di tempat pertama, wajar saja jika seseorang mencoba memperlambatnya!",
  ui_story_1016_10160402_55_dialog_content = "Memang. Dari semua kemungkinan, saya yakin ini yang paling mungkin.",
  ui_story_1016_10160402_56_dialog_content = "Tapi untuk saat ini, mari kita fokus pada diri kita sendiri.",
  ui_story_1016_10160402_57_dialog_content = "Kita harus lebih khawatir tentang situasi kita daripada apa yang orang lain lakukan.",
  ui_story_1016_10160402_58_dialog_content = "Ayo, mari kita buat rencana untuk latihan besok.",
  ui_story_1016_10160402_59_dialog_content = "Oke!",
  ui_story_1016_10160402_60_dialog_content = "Hahahahaha! Ini terlalu menyenangkan!",
  ui_story_1016_10160402_61_dialog_content = "Saya tidak tahu Anda tahu cara mengotak-atik Battle Simulator seperti itu, Dysis!",
  ui_story_1016_10160402_62_dialog_content = "Saya belajar bagaimana melakukannya baru-baru ini.",
  ui_story_1016_10160402_63_dialog_content = "Latihan Militer Gabungan memberi kami kesempatan untuk membaca buku-buku yang biasanya tidak dapat kami akses. Saya sarankan Anda berdua melakukan hal yang sama.",
  ui_story_1016_10160402_64_dialog_content = "Kesempatan belajar seperti ini tidak datang setiap hari lho.",
  ui_story_1016_10160402_65_dialog_content = "Baca buku, katamu? Itu kaya, berasal dari orang buta. Hitung saya!",
  ui_story_1016_10160402_66_dialog_content = "Ayo buat lebih banyak lagi kenakalan besok, Merry!",
  ui_story_1016_10160402_67_dialog_content = "Melihat? Mereka sudah mulai saling curiga! Ini bagus!",
  ui_story_1016_10160402_68_dialog_content = "Hanya mencoba untuk tidak tertangkap. Sepertinya mereka akan marah.",
  ui_story_1016_10160402_69_dialog_content = "Bukan kesempatan! Orang-orang dari Illumina terlalu sibuk mencurigai orang-orang dari Lumopolis, dan sebaliknya.",
  ui_story_1016_10160402_70_dialog_content = "Mereka tidak akan pernah mencurigai kita, dengan skor rendah kita dan sikap netral kita!",
  ui_story_1016_10160402_71_dialog_content = "Anda mendapatkan suara saya untuk ini, Minch.",
  ui_story_1016_10160402_72_dialog_content = "Nalar adalah rantai yang membelenggu pikiran kita, terus-menerus memaksa kita untuk mencari makna dalam segala hal yang kita lakukan.",
  ui_story_1016_10160402_73_dialog_content = "Ya ampun, kita pergi lagi...",
  ui_story_1016_10160402_74_dialog_content = "Namun mereka gagal menyadari bahwa cara berpikir mereka terlalu sempit.",
  ui_story_1016_10160402_75_dialog_content = "Sebagai makhluk kecil dan tidak penting, semua tindakan kita sama sekali tidak berarti.",
  ui_story_1016_10160402_76_dialog_content = "Kegagalan mereka untuk memahami hal ini berarti mereka tidak akan pernah memiliki jawaban atas kejahatan yang tidak beralasan.",
  ui_story_1016_10160402_77_dialog_content = "Jadi mainkan permainanmu, Minch sayangku. Mainkan mereka sesuka hati Anda.",
  ui_story_1016_10160402_78_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1016_10160402_79_dialog_content = "Dimana mereka...",
  ui_story_1016_10160402_80_dialog_content = "Sigh, mereka meninggalkanku lagi.",
  ui_story_1016_10160402_81_dialog_content = "Baiklah, aku akan kembali sendiri. Sekarang ke arah mana barak itu lagi...?",
  ui_story_1016_10160402_82_dialog_content = "Hmm?",
  ui_story_1016_10160501_1_dialog_content = "Kami menemukan tanda-tanda Eclipsites! Pergi panggil bala bantuan!",
  ui_story_1016_10160501_2_dialog_content = "Kita tidak bisa membiarkan satu pun lolos!",
  ui_story_1016_10160501_3_dialog_content = "Kapten Wrath telah diberitahukan! Kita harus segera bergabung dengan yang lain!",
  ui_story_1016_10160501_4_dialog_content = "Aku mengerti…",
  ui_story_1016_10160501_5_dialog_content = "Hei, kenapa kau hanya berdiri di sekitar seperti itu? Apakah Anda tidak mendengar kami? Ada Eclipsites di depan!",
  ui_story_1016_10160501_6_dialog_content = "Maaf, ini mataku...",
  ui_story_1016_10160501_7_dialog_content = "Oh, tidak, dia buta!",
  ui_story_1016_10160501_8_dialog_content = "Dia adalah? Oh... T-Tolong maafkan kekasaran saya barusan.",
  ui_story_1016_10160501_9_dialog_content = "Sayangnya, kami tidak dapat menyisihkan siapa pun untuk mengantarmu pulang sekarang.",
  ui_story_1016_10160501_10_dialog_content = "Apakah Anda keberatan bersembunyi di dekat jalan untuk saat ini? Daerah ini masih aman, saya jamin.",
  ui_story_1016_10160501_11_dialog_content = "Tidak apa-apa, tolong jangan menyusahkan diri sendiri karena saya.",
  ui_story_1016_10160501_12_dialog_content = "Bagaimanapun, ini darurat. Silakan, dan harap berhati-hati.",
  ui_story_1016_10160501_13_dialog_content = "Kami benar-benar minta maaf... Tolong jaga dirimu baik-baik!",
  ui_story_1016_10160501_14_dialog_content = "Kalau begitu, cepatlah.",
  ui_story_1016_10160501_15_dialog_content = "Baik!",
  ui_story_1016_10160501_16_dialog_content = "Gerhana di Kota Gannon...",
  ui_story_1016_10160501_17_dialog_content = "Tampaknya seseorang di luar sana membuat kerusakan lebih dari kita.",
  ui_story_1016_10160501_18_dialog_content = "<color=#e8d9bb>Lubang, tepuk, lubang, tepuk ...</color>",
  ui_story_1016_10160501_19_dialog_content = "Di sana! Di depan saja!",
  ui_story_1016_10160501_20_dialog_content = "Kami hampir—",
  ui_story_1016_10160501_21_dialog_content = "Hati-Hati!!!",
  ui_story_1016_10160501_22_dialog_content = "<anim type=Shake><size=50>Graaaaah!!!</size></anim>",
  ui_story_1016_10160501_23_dialog_content = "Apa? I-Mereka berbalik ke arah kita!",
  ui_story_1016_10160501_24_dialog_content = "Terlalu banyak yang harus kita tangani...",
  ui_story_1016_10160501_25_dialog_content = "Kami tidak punya pilihan selain bertarung!",
  ui_story_1016_10160501_26_dialog_content = "Setidaknya sampai bala bantuan tiba...",
  ui_story_1016_10160501_27_dialog_content = "Jangan terlihat putus asa, kalian berdua! Ini Kota Gannon, bukan?",
  ui_story_1016_10160501_28_dialog_content = "Siapa kamu?!",
  ui_story_1016_10160501_29_dialog_content = "Hanya seorang pejalan kaki yang baik hati.",
  ui_story_1016_10160501_30_dialog_content = "Sulit dipercaya...",
  ui_story_1016_10160501_31_dialog_content = "Th-Terima kasih!",
  ui_story_1016_10160501_32_dialog_content = "Jika Anda ingin berterima kasih kepada seseorang, ucapkan terima kasih kepada orang ini. Dia yang suka jalan-jalan setiap hari.",
  ui_story_1016_10160501_33_dialog_content = "Apakah Anda mencoba mengepung pasukan musuh?",
  ui_story_1016_10160501_34_dialog_content = "Cara Anda melakukannya sangat tidak efisien, dan memiliki kemungkinan besar menimbulkan korban.",
  ui_story_1016_10160501_35_dialog_content = "Jika berita tentang manuver yang salah ini tersiar, Anda akan menjadi bahan tertawaan seluruh kota.",
  ui_story_1016_10160501_36_dialog_content = "Pelajaran, Pak.",
  ui_story_1016_10160501_37_dialog_content = "(Menilai dari penampilannya, dia terlihat seperti seorang perwira. Tetap saja...)",
  ui_story_1016_10160501_38_dialog_content = "(Mengapa dia berjalan-jalan dengan seseorang yang jelas-jelas berasal dari Lumopolis?)",
  ui_story_1016_10160501_39_dialog_content = "Berapa banyak pasukan yang siaga di daerah ini?",
  ui_story_1016_10160501_40_dialog_content = "Taruh aku sebagai komando, dan aku akan tangani serangannya.",
  ui_story_1016_10160501_41_dialog_content = "Tapi Pak, ini...",
  ui_story_1016_10160501_42_dialog_content = "Tidak peduli apakah itu mengikuti protokol atau tidak! Tidak ada waktu untuk disia-siakan!",
  ui_story_1016_10160501_43_dialog_content = "Siap, Pak!",
  ui_story_1016_10160501_44_dialog_content = "Beri tahu semua pasukan terdekat untuk menyebar dari setiap persimpangan dalam radius lima blok.",
  ui_story_1016_10160501_45_dialog_content = "Kita akan memperlambat pengejaran kita saat mereka membentuk formasi.",
  ui_story_1016_10160501_46_dialog_content = "Ingat, tidak semua pertempuran bisa dimenangkan dengan kekuatan kasar saja.",
  ui_story_1016_10160501_47_dialog_content = "Seorang nelayan tidak menjangkau ke dalam air untuk menangkap ikan, tetapi mengejarnya ke jaringnya.",
  ui_story_1016_10160502_1_dialog_content = "Sekelompok kecil Eclipsites? Tapi dari mana mereka berasal?",
  ui_story_1016_10160502_2_dialog_content = "Kami belum tahu, Bu. Kami sudah menugaskan seseorang untuk menyelidiki masalah ini.",
  ui_story_1016_10160502_3_dialog_content = "Tetapi mengingat waktu kemunculan mereka, mungkinkah mereka ada hubungannya dengan Forsakin? Dia masih bersembunyi di suatu tempat di kota.",
  ui_story_1016_10160502_4_dialog_content = "Tentu saja entah bagaimana mereka terikat padanya. Misteri sebenarnya adalah bagaimana dia berhasil melakukannya sejak awal.",
  ui_story_1016_10160502_5_dialog_content = "Kami telah meningkatkan cakupan dan frekuensi patroli kami selama beberapa hari terakhir.",
  ui_story_1016_10160502_6_dialog_content = "Namun kami masih belum menemukan tanda-tanda Forsakin.",
  ui_story_1016_10160502_7_dialog_content = "Mungkin... Mungkin dia semakin mahir menyembunyikan gerakannya?",
  ui_story_1016_10160502_8_dialog_content = "Itu mungkin, tetapi sesuatu mengatakan kepada saya bahwa itu tidak sesederhana itu.",
  ui_story_1016_10160502_9_dialog_content = "Akhir-akhir ini, aku merasakan sesuatu yang tidak beres di Gannon City...",
  ui_story_1016_10160502_10_dialog_content = "Kapten! Kami baru saja menerima kabar dari medan pertempuran!",
  ui_story_1016_10160502_11_dialog_content = "Semua unit terdekat mengatur pengepungan musuh!",
  ui_story_1016_10160502_12_dialog_content = "Pengepungan? Di mana mereka, dan berapa banyak dari mereka yang telah dikerahkan?",
  ui_story_1016_10160502_13_dialog_content = "Saya tidak pernah memberikan perintah seperti itu! Siapa di luar sana yang memimpin pasukanku?!",
  ui_story_1016_10160502_14_dialog_content = "Mereka tidak bilang, Bu...",
  ui_story_1016_10160502_15_dialog_content = "Lalu cari tahu!",
  ui_story_1016_10160502_16_dialog_content = "Aku masih jenderal di sekitar sini! Tidak ada yang harus memberi perintah selain dari saya!",
  ui_story_1016_10160502_17_dialog_content = "Pesan baru AA baru saja diterima, Kapten!",
  ui_story_1016_10160502_18_dialog_content = "Sekelompok kecil Eclipsites yang menyusup ke Kota Gannon telah dimusnahkan!",
  ui_story_1016_10160502_19_dialog_content = "<size=50>Apa?!</size>",
  ui_story_1016_10160502_20_dialog_content = "Mereka semua? Apa kamu yakin?",
  ui_story_1016_10160502_21_dialog_content = "Ya Bu. Tidak ada tanda-tanda aktivitas Eclipsite yang terdeteksi di sekitarnya.",
  ui_story_1016_10160502_22_dialog_content = "Dalam waktu yang begitu singkat...",
  ui_story_1016_10160502_23_dialog_content = "Heh. Sangat menarik.",
  ui_story_1016_10160502_24_dialog_content = "Saya ingin tahu kepada siapa saya harus berterima kasih untuk semua ini?",
  ui_story_1016_10160502_25_dialog_content = "Baiklah, saya pikir kita sudah selesai di sini.",
  ui_story_1016_10160502_26_dialog_content = "Kami memiliki tempat lain untuk sekarang, jadi kami akan menyerahkan pembersihan kepada Anda dan pasukan Anda.",
  ui_story_1016_10160502_27_dialog_content = "Oh, dan lebih baik jika Anda tidak memberi tahu atasan Anda tentang saya mengambil komando hari ini.",
  ui_story_1016_10160502_28_dialog_content = "Saya pikir itu akan menyelamatkan semua orang dari banyak masalah jika kita menyimpan ini untuk diri kita sendiri...",
  ui_story_1016_10160502_29_dialog_content = "Menyimpannya untuk dirimu sendiri? Tapi semua orang berhak tahu siapa yang menyelamatkan kota kita dari Eclipsites, bukan begitu?",
  ui_story_1016_10160502_30_dialog_content = "Aku bahkan berencana membuat medali untukmu dan segalanya!",
  ui_story_1016_10160502_31_dialog_content = "Pengajar Wrath...",
  ui_story_1016_10160502_32_dialog_content = "Kita tidak di kelas lagi, jadi tidak perlu memanggilku seperti itu. Di luar sini, kita semua tentara.",
  ui_story_1016_10160502_33_dialog_content = "Maafkan saya karena mengambil alih komando atas pasukan Anda.",
  ui_story_1016_10160502_34_dialog_content = "Saya akan menerima hukuman apa pun yang Anda inginkan.",
  ui_story_1016_10160502_35_dialog_content = "Hmm... Saya pikir beberapa medali yang bagus akan lebih baik daripada hukuman.",
  ui_story_1016_10160502_36_dialog_content = "Mari kita kesampingkan topik itu untuk saat ini.",
  ui_story_1016_10160502_37_dialog_content = "Anda tidak hanya membantu kami di saat kami membutuhkan, tetapi juga menyelesaikan masalah dengan kecepatan dan efisiensi yang luar biasa. Itu layak dipuji, tidak peduli bagaimana Anda memotongnya.",
  ui_story_1016_10160502_38_dialog_content = "Dan saya bukan tipe orang yang menghukum aset terpuji.",
  ui_story_1016_10160502_39_dialog_content = "Terima kasih, Komandan.",
  ui_story_1016_10160502_40_dialog_content = "Keahlian tempur dan kecepatan eksekusi Anda sangat terpuji.",
  ui_story_1016_10160502_41_dialog_content = "Saya tidak berpikir orang lain bisa menangani krisis ini lebih sempurna dari Anda.",
  ui_story_1016_10160502_42_dialog_content = "Kemampuan Anda tidak diragukan lagi merupakan produk dari pertempuran konstan Anda di garis depan.",
  ui_story_1016_10160502_43_dialog_content = "Tidak hanya itu, pengalaman Anda juga menanamkan rasa kepraktisan dalam taktik Anda.",
  ui_story_1016_10160502_44_dialog_content = "Karena itu, saya tidak tersinggung serius dengan cara berpikir Anda. Ketegasan semacam ini mutlak diperlukan di medan perang.",
  ui_story_1016_10160502_45_dialog_content = "Tapi di sini di Kota Gannon, aturan dan institusi kami lebih diutamakan.",
  ui_story_1016_10160502_46_dialog_content = "Butuh waktu lama bagi saya untuk mempelajarinya, dan saya harap Anda juga akan melakukan hal yang sama.",
  ui_story_1016_10160502_47_dialog_content = "Aturan dan institusi...",
  ui_story_1016_10160502_48_dialog_content = "Itulah yang membuat sistem tetap stabil, bukan?",
  ui_story_1016_10160502_49_dialog_content = "Itu benar. Stabilitas adalah segalanya.",
  ui_story_1016_10160502_50_dialog_content = "Kita tidak boleh kewalahan oleh kekuatan luar atau perselisihan internal.",
  ui_story_1016_10160502_51_dialog_content = "Untuk mempertahankan stabilitas ini, terkadang kita tidak punya pilihan selain mengorbankan sebagian dari kemenangan kita.",
  ui_story_1016_10160502_52_dialog_content = "Saya mengerti. Saya mengerti sekarang.",
  ui_story_1016_10160502_53_dialog_content = "Terima kasih, instruktur.",
  ui_story_1016_10160502_54_dialog_content = "Ini akan membuat dirinya semakin jelas, jika Anda pernah meninggalkan perbatasan.",
  ui_story_1016_10160502_55_dialog_content = "Itu saja untuk saat ini.",
  ui_story_1016_10160502_56_dialog_content = "Saya mengajar kelas besok, jadi jangan terlambat.",
  ui_story_1016_10160502_57_dialog_content = "Siap, Kapten!",
  ui_story_1016_10160502_58_dialog_content = "... Tapi bagaimana jika sistem itu dibengkokkan sejak awal, Bu?",
  ui_story_1016_10160502_59_dialog_content = "Hah? Apa?",
  ui_story_1016_10160502_60_dialog_content = "Struktur yang dibangun di atas fondasi yang tidak rata cepat atau lambat pasti akan runtuh, terlepas dari berapa banyak aturan dan institusi yang mendukungnya.",
  ui_story_1016_10160502_61_dialog_content = "Jika itu masalahnya, pengorbanan apa pun yang kita lakukan demi itu semua sia-sia.",
  ui_story_1016_10160502_62_dialog_content = "Jadi begitu. Jadi Anda tidak puas dengan struktur saat ini, menurut saya?",
  ui_story_1016_10160502_63_dialog_content = "Maafkan saya jika saya terdengar kasar, tetapi apakah Anda tahu mengapa kami berpartisipasi dalam Latihan Militer Gabungan ini?",
  ui_story_1016_10160502_64_dialog_content = "Saat ini, di Zona Gelap di ujung terjauh dari tanah kami, Eclipsites berkumpul berbondong-bondong.",
  ui_story_1016_10160502_65_dialog_content = "Mereka siap untuk menyerang melalui pertahanan kita pada waktu tertentu.",
  ui_story_1016_10160502_66_dialog_content = "Tapi panggilan marabahaya kami hanya pernah bertemu dengan keheningan.",
  ui_story_1016_10160502_67_dialog_content = "Beri tahu kami, Komandan, apakah pertahanan kami terhadap Twilight diperlukan untuk stabilitas sistem?",
  ui_story_1016_10160502_68_dialog_content = "Atau apakah itu hanya pengorbanan lain dalam skema besar?",
  ui_story_1016_10160502_69_dialog_content = "... Sudah berapa lama ini terjadi di perbatasan?",
  ui_story_1016_10160502_70_dialog_content = "Sepertinya saya benar: Anda tidak tahu apa-apa.",
  ui_story_1016_10160502_71_dialog_content = "Yang berarti komandan lainnya sama-sama tidak sadar.",
  ui_story_1016_10160502_72_dialog_content = "Maaf jika saya sudah mengatakan terlalu banyak.",
  ui_story_1016_10160502_73_dialog_content = "...",
  ui_story_1016_10160502_74_dialog_content = "Anda harus kembali ke barak.",
  ui_story_1016_10160502_75_dialog_content = "Saya akan menyelidiki semua yang baru saja Anda katakan kepada saya.",
  ui_story_1016_10160502_76_dialog_content = "Aku mengerti.",
  ui_story_1016_10160502_77_dialog_content = "(Bagaimana saya bisa benar-benar tidak mengetahui sesuatu yang begitu mendesak?)",
  ui_story_1016_10160502_78_dialog_content = "(Apa artinya ini, Reinhardt?)",
  ui_story_1016_10160502_79_dialog_content = "(Atau mungkinkah ini di luar kendalimu juga...?)",
  ui_story_1016_10160502_80_dialog_content = "Penolakan.",
  ui_story_1016_10160502_81_dialog_content = "Menyangkal!",
  ui_story_1016_10160502_82_dialog_content = "... Maaf, saya baru saja terganggu.",
  ui_story_1016_10160502_83_dialog_content = "Apa itu buruk...?",
  ui_story_1016_10160502_84_dialog_content = "Kau terlihat... sangat pucat.",
  ui_story_1016_10160502_85_dialog_content = "Semua Eclipsites yang saya selipkan ke Kota Gannon telah musnah.",
  ui_story_1016_10160502_86_dialog_content = "Orang yang memegang komando tidak memberiku waktu untuk bereaksi... Siapapun mereka, mereka pasti sangat kuat.",
  ui_story_1016_10160502_87_dialog_content = "Apakah ini berarti... Kita kehabisan pilihan?",
  ui_story_1016_10160502_88_dialog_content = "Sampai Wraith muncul, tampaknya itulah masalahnya.",
  ui_story_1016_10160502_89_dialog_content = "Saya tidak suka menempatkan semua taruhan kami pada mereka.",
  ui_story_1016_10160502_90_dialog_content = "Ini bukan taruhan, ini perdagangan.",
  ui_story_1016_10160502_91_dialog_content = "Penelitian yang saya miliki di tangan saya cukup untuk menyelamatkan hidup kami berdua.",
  ui_story_1016_10160601_1_dialog_content = "<color=#e8d9bb>Beberapa hari kemudian, menjelang akhir fase pembelajaran</color>",
  ui_story_1016_10160601_2_dialog_content = "Dengan baik? Di mana kita di klasemen sekarang?!",
  ui_story_1016_10160601_3_dialog_content = "Biarku lihat-",
  ui_story_1016_10160601_4_dialog_content = "Tempat kedua! Kami berhasil mencapai posisi kedua!",
  ui_story_1016_10160601_5_dialog_content = "Luar biasa!!! Kami benar-benar melakukannya!",
  ui_story_1016_10160601_6_dialog_content = "<color=#e8d9bb>Cincin-</color>",
  ui_story_1016_10160601_7_dialog_content = "Ayo cari tempat duduk kita. Kita harus menunjukkan perilaku terbaik kita hari ini.",
  ui_story_1016_10160601_8_dialog_content = "Kamu benar. Bagaimanapun, ini adalah kelas terakhir dari fase tersebut.",
  ui_story_1016_10160601_9_dialog_content = "Selamat siang, semua peserta latihan!",
  ui_story_1016_10160601_10_dialog_content = "Seperti yang kalian ketahui, kelas hari ini adalah yang terakhir untuk tahap pembelajaran Latihan Militer Gabungan.",
  ui_story_1016_10160601_11_dialog_content = "Setelah hari ini, Anda akan memulai persiapan pertempuran untuk fase penilaian, dan bersaing untuk menentukan juara pamungkas.",
  ui_story_1016_10160601_12_dialog_content = "Kredit yang telah Anda kumpulkan selama fase pembelajaran juga akan memberi Anda dukungan dalam pertempuran yang akan datang.",
  ui_story_1016_10160601_13_dialog_content = "Harap arahkan perhatian Anda ke peringkat di dinding untuk melihat posisi tim Anda.",
  ui_story_1016_10160601_14_dialog_content = "Di tempat pertama, dan dengan selisih yang besar, adalah Tim Leo.",
  ui_story_1016_10160601_15_dialog_content = "Terima kasih terima kasih!",
  ui_story_1016_10160601_16_dialog_content = "Menarik ke tempat kedua pada jam kesebelas adalah Tim PlayerName!",
  ui_story_1016_10160601_17_dialog_content = "Ternyata tidak mudah juga...",
  ui_story_1016_10160601_18_dialog_content = "Tim Yingel, dengan performa konsisten mereka, mengamankan tempat ketiga!",
  ui_story_1016_10160601_19_dialog_content = "Terima kasih.",
  ui_story_1016_10160601_20_dialog_content = "Adapun sisa klasemen, Anda dapat memeriksanya sendiri di lain waktu.",
  ui_story_1016_10160601_21_dialog_content = "Kembali ke topik pelajaran terakhir Anda, panitia ingin semua orang melakukan pemanasan sebelum dimulainya fase penilaian.",
  ui_story_1016_10160601_22_dialog_content = "Dengan demikian, kelas hari ini akan fokus pada pertempuran.",
  ui_story_1016_10160601_23_dialog_content = "Tempur? Apakah akan berbeda dari kelas tempur terakhir yang kita miliki?",
  ui_story_1016_10160601_24_dialog_content = "Itu akan terjadi, karena Anda akan menghadapi lawan yang berbeda.",
  ui_story_1016_10160601_25_dialog_content = "Keselamatan adalah prioritas utama di semua kelas Anda sebelumnya. Anda tidak pernah berada dalam bahaya nyata.",
  ui_story_1016_10160601_26_dialog_content = "Apakah itu melawan tentara terlatih atau musuh yang disimulasikan, pelajaran tempur Anda tidak memiliki cara untuk melukai Anda.",
  ui_story_1016_10160601_27_dialog_content = "Namun, dalam fase penilaian, tidak ada yang bisa menjamin keselamatan Anda.",
  ui_story_1016_10160601_28_dialog_content = "Untuk alasan ini, saya ingin melihat apakah Anda semua siap menghadapi Eclipsites yang sebenarnya.",
  ui_story_1016_10160601_29_dialog_content = "Eclipses nyata? Di kelas?",
  ui_story_1016_10160601_30_dialog_content = "Departemen Penelitian Biologi Illumina berbaik hati memberi kami beberapa spesimen pelatihan yang berharga.",
  ui_story_1016_10160601_31_dialog_content = "Harap bersiap untuk pertempuran, semuanya!",
  ui_story_1016_10160601_32_dialog_content = "<color=#e8d9bb>Memukul-!!!</color>",
  ui_story_1016_10160601_33_dialog_content = "Wow! Saya tidak menyadari akan ada Eclipsites sebanyak ini!",
  ui_story_1016_10160601_34_dialog_content = "Apakah Illumina telah melakukan penelitian pada mereka semua? Usaha yang berani...",
  ui_story_1016_10160601_35_dialog_content = "Mengetahui lawan Anda adalah yang paling penting dalam peperangan.",
  ui_story_1016_10160601_36_dialog_content = "Tahukah Anda berapa biaya yang harus kami keluarkan untuk mendapatkan banyak spesimen penelitian yang berharga ini? Kehidupan prajurit yang tak terhitung jumlahnya, Nona Beretta.",
  ui_story_1016_10160601_37_dialog_content = "Namun…",
  ui_story_1016_10160601_38_dialog_content = "Jangan khawatir. Eclipsites ini berada di bawah kendali kita.",
  ui_story_1016_10160601_39_dialog_content = "Nah, semuanya! Tidak ada aturan atau batasan tambahan untuk kelas akhir Anda.",
  ui_story_1016_10160601_40_dialog_content = "Silakan gunakan setiap dan semua metode yang Anda inginkan untuk menghapus lawan Anda!",
  ui_story_1016_10160601_41_dialog_content = "<anim type=Shake><size=50>Graaaaah!!!</size></anim>",
  ui_story_1016_10160601_42_dialog_content = "A-Apa kita mulai sekarang?!",
  ui_story_1016_10160601_43_dialog_content = "aku masih belum siap...",
  ui_story_1016_10160601_44_dialog_content = "Hati-hati, PlayerName.",
  ui_story_1016_10160601_45_dialog_content = "M-Maaf! Saya tidak memperhatikan!",
  ui_story_1016_10160601_46_dialog_content = "Mengawasi tim lain selama pertempuran.",
  ui_story_1016_10160601_47_dialog_content = "Ini adalah kesempatan bagus bagi kita untuk melihat kemampuan tempur mereka yang sebenarnya.",
  ui_story_1016_10160601_48_dialog_content = "Lakukan yang terbaik untuk menghindari pertarungan, Axelia.",
  ui_story_1016_10160601_49_dialog_content = "Tinggalkan semuanya Anatoli dan saya.",
  ui_story_1016_10160601_50_dialog_content = "Apakah itu tidak apa apa?",
  ui_story_1016_10160601_51_dialog_content = "Ini masih satu kelas. Aku yakin kita tidak dalam bahaya terlalu banyak.",
  ui_story_1016_10160601_52_dialog_content = "Tim lain juga hadir.",
  ui_story_1016_10160601_53_dialog_content = "Anda mengatakan itu, tapi ...",
  ui_story_1016_10160601_54_dialog_content = "Mereka juga tampaknya tidak bertarung dengan kekuatan penuh.",
  ui_story_1016_10160601_55_dialog_content = "Tutupi sayap kiriku, Uriah!",
  ui_story_1016_10160601_56_dialog_content = "Baik!",
  ui_story_1016_10160601_57_dialog_content = "Ini tidak bagus! Kami dikelilingi di semua sisi...",
  ui_story_1016_10160601_58_dialog_content = "Chloe!",
  ui_story_1016_10160601_59_dialog_content = "Aku sedikit sibuk sekarang!",
  ui_story_1016_10160601_60_dialog_content = "Apa yang terjadi? Rasanya seperti kita berjuang sendirian!",
  ui_story_1016_10160601_61_dialog_content = "Bagaimana kami bisa berada di garis depan pertempuran?",
  ui_story_1016_10160601_62_dialog_content = "Saya pikir itu karena mereka semua mundur...",
  ui_story_1016_10160601_63_dialog_content = "Apa?!",
  ui_story_1016_10160601_64_dialog_content = "Tapi mereka semua berperingkat sangat tinggi di atas kita! Bagaimana mereka bisa kabur saat pertarungan sesungguhnya dimulai?!",
  ui_story_1016_10160601_65_dialog_content = "Tangan kami juga penuh, Anda tahu?",
  ui_story_1016_10160601_66_dialog_content = "Apa yang kamu bicarakan?! Anda bahkan belum menghunus pedang Anda!",
  ui_story_1016_10160601_67_dialog_content = "Sepertinya semua orang menahan diri ...",
  ui_story_1016_10160601_68_dialog_content = "Masuk akal. Semua orang berusaha menyembunyikan kekuatan mereka yang sebenarnya sampai fase penilaian.",
  ui_story_1016_10160601_69_dialog_content = "Tapi kalau terus begini, kita tidak akan bisa mengalahkan semua Eclipsites ini...",
  ui_story_1016_10160601_70_dialog_content = "Jika tidak ada yang ingin bertarung dengan kekuatan penuh, maka kita semua harus bekerja sama!",
  ui_story_1016_10160601_71_dialog_content = "Musuh tidak terlalu kuat, jadi jika semua orang melempar sedikit, kita seharusnya bisa menang tanpa masalah!",
  ui_story_1016_10160601_72_dialog_content = "Oh? Itu patut dicoba, saya kira.",
  ui_story_1016_10160601_73_dialog_content = "Aku sama sekali tidak keberatan bertarung bersama orang-orang dari faksi lain!",
  ui_story_1016_10160601_74_dialog_content = "Sepakat. Jika tidak ada lagi yang bisa diperebutkan di kelas terakhir kita, mari kita bekerja sama dan menyelesaikannya.",
  ui_story_1016_10160601_75_dialog_content = "Kami juga setuju! Sekarang tolong bantu kami!",
  ui_story_1016_10160601_76_dialog_content = "Terdengar menyenangkan! Hitung saya!",
  ui_story_1016_10160601_77_dialog_content = "Baiklah! Mari gabungkan kekuatan kita untuk menang, semuanya!",
  ui_story_1016_10160601_78_dialog_content = "Pertama, kita perlu mendorong musuh ke belakang dan menarik tim Beretta keluar dari bahaya!",
  ui_story_1016_10160602_1_dialog_content = "Bagus sekali! Semua Eclipsites telah dimusnahkan!",
  ui_story_1016_10160602_2_dialog_content = "Selamat untuk semua yang telah menyelesaikan pelajaran terakhir Anda, serta fase pembelajaran Latihan Militer Gabungan.",
  ui_story_1016_10160602_3_dialog_content = "Kami berharap kompetisi akan jauh lebih intens, tetapi dalam kejadian yang mengejutkan, tim memutuskan untuk bekerja sama dan menghapus lawan mereka!",
  ui_story_1016_10160602_4_dialog_content = "Yah, ini bukan karena kebaikan hati semua orang, haha.",
  ui_story_1016_10160602_5_dialog_content = "Dan dengan itu, fase pembelajaran secara resmi ditutup! Sebelum kita melanjutkan, izinkan saya untuk secara singkat memperkenalkan penilaian yang akan datang.",
  ui_story_1016_10160602_6_dialog_content = "Saya yakin banyak dari Anda yang ingin tahu lebih banyak tentangnya, ya?",
  ui_story_1016_10160602_7_dialog_content = "Fase penilaian untuk Latihan Militer Gabungan ini akan berlangsung di Undercity yang terbengkalai.",
  ui_story_1016_10160602_8_dialog_content = "Terletak di dekat garis pertahanan kami, sudah lama dikuasai oleh Eclipsites. Daerah sekitarnya telah kehilangan kehidupan Aurorian selama bertahun-tahun.",
  ui_story_1016_10160602_9_dialog_content = "Tujuan Anda adalah untuk berjuang mencapai jangkauan terdalam Undercity ini, dan merebut kembali spanduk yang telah ditanam di sana.",
  ui_story_1016_10160602_10_dialog_content = "Aturan untuk ini sangat sederhana: siapa pun yang mengambil spanduk akan dinobatkan sebagai juara, dan akan mendapat kesempatan untuk berduel dengan Grand Marshal.",
  ui_story_1016_10160602_11_dialog_content = "Anda dapat mencapai tujuan ini dengan cara apa pun yang diperlukan. Tidak ada aturan atau batasan lain dalam fase ini.",
  ui_story_1016_10160602_12_dialog_content = "Apakah akan ada jaminan untuk keselamatan kita?",
  ui_story_1016_10160602_13_dialog_content = "Lebih baik jika Anda tidak mengandalkannya.",
  ui_story_1016_10160602_14_dialog_content = "Untuk mengeluarkan potensi tempur penuh dari setiap peserta, tingkat kesulitan dan bahaya fase penilaian telah ditingkatkan secara signifikan.",
  ui_story_1016_10160602_15_dialog_content = "Ingat, pertarungan sesungguhnya jauh berbeda dengan latihan. Keberhasilan dalam fase pembelajaran tidak serta merta diterjemahkan menjadi kesuksesan dalam fase penilaian.",
  ui_story_1016_10160602_16_dialog_content = "Selama misi Anda, instruktur kami akan menggunakan berbagai metode untuk memantau kinerja Anda.",
  ui_story_1016_10160602_17_dialog_content = "Setiap tindakan jahat yang dilakukan terhadap peserta dapat dan akan digunakan sebagai bukti terhadap Anda di pengadilan militer.",
  ui_story_1016_10160602_18_dialog_content = "Selain itu, kami tidak akan dapat mengganggu atau membantu Anda dengan bahaya apa pun yang Anda hadapi.",
  ui_story_1016_10160602_19_dialog_content = "Dengan mengingat hal itu, Anda sebaiknya hanya mengandalkan diri Anda sendiri, bukan pada dukungan apa pun yang mungkin kami tawarkan.",
  ui_story_1016_10160602_20_dialog_content = "Jadi begitu. Terima kasih telah mengklarifikasi.",
  ui_story_1016_10160602_21_dialog_content = "Itu cocok untukku. Jika kita memiliki orang-orang yang siap untuk menyelamatkan kita, ini semua hanya akan menjadi satu pertandingan besar.",
  ui_story_1016_10160602_22_dialog_content = "Sekarang saatnya semua orang bersiap untuk fase penilaian!",
  ui_story_1016_10160602_23_dialog_content = "Demi keadilan, Anda hanya akan diberikan peralatan tempur minimum yang diperlukan.",
  ui_story_1016_10160602_24_dialog_content = "Untuk dukungan apa pun di luar itu, Anda dapat menggunakan kredit Anda dari fase pembelajaran untuk membelinya.",
  ui_story_1016_10160602_25_dialog_content = "Bagus! Kami akhirnya dapat memanfaatkan kredit yang diperoleh dengan susah payah!",
  ui_story_1016_10160602_26_dialog_content = "Benar! Besok, saya akan memandu Anda ke salah satu pusat penelitian utama Illumina, tempat kami telah menyiapkan segala macam item pendukung untuk Anda.",
  ui_story_1016_10160602_27_dialog_content = "Beberapa akan meningkatkan kemampuan tempur Anda, sementara yang lain akan memberi Anda informasi penting di medan perang.",
  ui_story_1016_10160602_28_dialog_content = "Sumber daya yang tersedia akan ditentukan oleh kredit yang Anda peroleh.",
  ui_story_1016_10160602_29_dialog_content = "Dengan kata lain, mereka yang memiliki lebih banyak kredit akan dapat memperoleh lebih banyak dukungan untuk fase mendatang.",
  ui_story_1016_10160602_30_dialog_content = "Apakah Anda memilih untuk meningkatkan kekuatan Anda atau mengkompensasi kekurangan Anda sepenuhnya terserah Anda.",
  ui_story_1016_10160602_31_dialog_content = "Hmm, apa yang harus kita pilih...?",
  ui_story_1016_10160602_32_dialog_content = "Setelah Anda membuat semua persiapan yang diperlukan, silakan kembali ke barak sesegera mungkin. Kami akan berkumpul di ruang kelas besok pagi untuk memulai fase penilaian.",
  ui_story_1016_10160602_33_dialog_content = "Itu saja yang saya miliki untuk hari ini. Kelas dibubarkan!",
  ui_story_1016_10160602_34_dialog_content = "<color=#e8d9bb>Hari berikutnya</color>",
  ui_story_1016_10160602_35_dialog_content = "Wow! Lihatlah semua peralatan ini!",
  ui_story_1016_10160602_36_dialog_content = "Senapan dan bayonet, granat, dan semua jenis alat pelindung...",
  ui_story_1016_10160602_37_dialog_content = "Bagaimana kita harus memilih?! Saya ingin mereka semua!",
  ui_story_1016_10160602_38_dialog_content = "Jika Anda mencermati semuanya, sebagian besar barang ini membutuhkan banyak kredit.",
  ui_story_1016_10160602_39_dialog_content = "Meskipun kami menempati posisi kedua, kami masih sangat terbatas dalam seberapa banyak yang kami mampu.",
  ui_story_1016_10160602_40_dialog_content = "Memang. Tampaknya sebagian besar dari hal-hal ini hanyalah insentif bagi kami untuk berbuat lebih baik di fase sebelumnya. Lagi pula, penyelenggara tidak ingin kami terlalu bergantung pada bantuan dari luar.",
  ui_story_1016_10160602_41_dialog_content = "Kita harus memilih apa yang paling kita butuhkan.",
  ui_story_1016_10160602_42_dialog_content = "Jika Anda bertanya kepada saya, memiliki PlayerName di tim kami memberi kami keuntungan alami dalam hal mengumpulkan informasi.",
  ui_story_1016_10160602_43_dialog_content = "Jadi mungkin kita harus menggunakan kredit kita untuk meningkatkan kemampuan tempur kita?",
  ui_story_1016_10160602_44_dialog_content = "Ketika Anda mengatakannya seperti itu, saya pikir kita harus berinvestasi pada item yang lebih defensif.",
  ui_story_1016_10160602_45_dialog_content = "PlayerName relatif tidak berdaya dalam pertempuran. Kita harus memprioritaskan menjaganya tetap aman dalam pertempuran yang akan datang.",
  ui_story_1016_10160602_46_dialog_content = "Hah? K-Kamu tidak perlu menghabiskan sebanyak itu untukku, kamu tahu...",
  ui_story_1016_10160602_47_dialog_content = "Saya sangat setuju dengan anda, Carleen!",
  ui_story_1016_10160602_48_dialog_content = "Kemarilah, PlayerName! Mari kita lihat apakah pakaian pelindung ini cocok untuk Anda!",
  ui_story_1016_10160602_49_dialog_content = "Tunggu, maksudmu di sini?!",
  ui_story_1016_10160602_50_dialog_content = "Oh, kurasa tidak apa-apa, jika itu berarti aku tidak akan menahan kalian berdua...",
  ui_story_1016_10160602_51_dialog_content = "Itu semua adalah sekumpulan mesin...",
  ui_story_1016_10160602_52_dialog_content = "Saya tidak bisa benar-benar bersemangat atas hal ini. Anda memilih, Zhao.",
  ui_story_1016_10160602_53_dialog_content = "Tentu. Aku sudah memberikan banyak pemikiran.",
  ui_story_1016_10160602_54_dialog_content = "Apa yang kita butuhkan lebih dari apapun adalah informasi.",
  ui_story_1016_10160602_55_dialog_content = "Jika kita bisa tetap selangkah lebih maju dari musuh, tidak ada pertempuran yang terlalu berat bagi kita.",
  ui_story_1016_10160602_56_dialog_content = "Ya, itu masuk akal. Saya juga lebih suka tidak terkejut.",
  ui_story_1016_10160602_57_dialog_content = "Mari kita ambil peta, serta komunikator ini.",
  ui_story_1016_10160602_58_dialog_content = "Komunikator itu cukup mahal. Kita akan dikenakan biaya lebih dari setengah kredit kita hanya untuk mendapatkannya.",
  ui_story_1016_10160602_59_dialog_content = "Menurut uraiannya, komunikator ini dapat digunakan untuk menghubungi instruktur kapan saja selama fase penilaian.",
  ui_story_1016_10160602_60_dialog_content = "Tidak ada lagi yang bisa memberi kami informasi yang lebih berguna.",
  ui_story_1016_10160602_61_dialog_content = "Baik-baik saja maka. Kami akan membiarkan Anda mengambil gambar yang satu ini.",
  ui_story_1016_10160602_62_dialog_content = "Tutup pintu.",
  ui_story_1016_10160602_63_dialog_content = "Siap, Pak!",
  ui_story_1016_10160602_64_dialog_content = "<color=#e8d9bb>Gedebuk.</color>",
  ui_story_1016_10160602_65_dialog_content = "Apakah Anda sepenuhnya menyadari misi Anda?",
  ui_story_1016_10160602_66_dialog_content = "Ya. Kami harus memenangkan kejuaraan dengan segala cara.",
  ui_story_1016_10160602_67_dialog_content = "Aku sudah memberitahu yang lain.",
  ui_story_1016_10160602_68_dialog_content = "Saya percaya pada kekuatan gabungan Anda, tetapi Anda tidak perlu bermain sesuai aturan.",
  ui_story_1016_10160602_69_dialog_content = "Saya sudah menyiapkan beberapa persediaan untuk Anda. Anda akan menemukannya jauh lebih berguna daripada apa pun yang dapat dibeli dengan kredit Anda.",
  ui_story_1016_10160602_70_dialog_content = "Dan jangan khawatir, Anda akan bisa memasuki fase penilaian dengan ini.",
  ui_story_1016_10160602_71_dialog_content = "Untuk intel, Anda telah diberikan peta yang sangat mendetail yang juga mencakup lokasi spanduk yang tepat.",
  ui_story_1016_10160602_72_dialog_content = "Anda tidak perlu meraba-raba dalam kegelapan seperti tim lainnya dengan ini. Langsung saja menuju lokasi target.",
  ui_story_1016_10160602_73_dialog_content = "Di loker di sana, Anda akan menemukan beberapa peralatan peningkat pertempuran. Ambil apa pun yang Anda butuhkan.",
  ui_story_1016_10160602_74_dialog_content = "(Apa pun yang kita butuhkan? Bahkan salah satu dari item ini menghabiskan kredit seluruh tim...)",
  ui_story_1016_10160602_75_dialog_content = "(Para petinggi akan marah jika kita ketahuan curang secara terang-terangan.)",
  ui_story_1016_10160602_76_dialog_content = "(Apakah Panitia sangat membutuhkan sang juara?)",
  ui_story_1016_10160602_77_dialog_content = "Itu saja untuk saat ini. Saya meninggalkan sisanya di tangan Anda.",
  ui_story_1016_10160602_78_dialog_content = "Jangan beri tahu siapa pun tentang pertemuan kita hari ini.",
  ui_story_1016_10160602_79_dialog_content = "<color=#e8d9bb>Gedebuk.</color>",
  ui_story_1016_10160602_80_dialog_content = "Saya memiliki Kubus. Saya tidak butuh yang lain.",
  ui_story_1016_10160602_81_dialog_content = "Saya juga tidak memerlukan peralatan tambahan. Ambil pilihanmu, Anatoli.",
  ui_story_1016_10160602_82_dialog_content = "Aku?",
  ui_story_1016_10160602_83_dialog_content = "Memberi satu orang semua peralatan ini akan meningkatkan peluang keberhasilan kita.",
  ui_story_1016_10160602_84_dialog_content = "... Bagus. Saya akan melakukan apa yang diperintahkan.",
  ui_story_1016_10160602_85_dialog_content = "Kita semua hanya melakukan apa yang diperintahkan, Anatoli.",
  ui_story_1016_10160602_86_dialog_content = "Setelah sekian lama berurusan dengan Komite, kalian berdua pasti sudah terbiasa dengan perintah seperti ini sekarang, kan?",
  ui_story_1016_10160602_87_dialog_content = "Apa ada yang ingin kaukatakan?",
  ui_story_1016_10160602_88_dialog_content = "Tidak. Aku hanya bertanya.",
  ui_story_1016_10160602_89_dialog_content = "Sebagai Petugas Intelijen, Anda harus berusaha untuk tidak mengajukan pertanyaan secara sembarangan.",
  ui_story_1016_10160602_90_dialog_content = "Adapun untuk melakukan apa yang saya diberitahu, ya, saya sudah lama terbiasa. Pesanan adalah yang terpenting, apa pun yang diperlukan.",
  ui_story_1016_10160602_91_dialog_content = "Aku paham…",
  ui_story_1016_10160602_92_dialog_content = "Namun, itu tidak berarti saya selalu setuju dengan pesanan saya.",
  ui_story_1016_10160602_93_dialog_content = "Ketika itu terjadi, saya memilih untuk menyembunyikan perbedaan pendapat saya di balik tindakan saya.",
  ui_story_1016_10160701_1_dialog_content = "<color=#e8d9bb>Klakson, klakson—</color>",
  ui_story_1016_10160701_2_dialog_content = "Baiklah, semuanya keluar! Kami telah tiba di tujuan kami!",
  ui_story_1016_10160701_3_dialog_content = "Undercity yang tampak jompo di depan adalah tempat fase penilaian akan berlangsung!",
  ui_story_1016_10160701_4_dialog_content = "Prajurit kita sekarang akan mengawal setiap tim ke titik awal yang berbeda di Undercity.",
  ui_story_1016_10160701_5_dialog_content = "Mari kita lihat, apakah saya melupakan sesuatu...?",
  ui_story_1016_10160701_6_dialog_content = "Oh, benar! Berhati-hatilah di luar sana! Anda diizinkan untuk bertarung satu sama lain, tetapi tidak ada pukulan mematikan!",
  ui_story_1016_10160701_7_dialog_content = "Saya akan mengawasi dari bayang-bayang setiap langkah, Anda dengar?",
  ui_story_1016_10160701_8_dialog_content = "Oh, kau membuatku merinding...",
  ui_story_1016_10160701_9_dialog_content = "Bawa mereka ke titik awal mereka, tentara!",
  ui_story_1016_10160701_10_dialog_content = "Saya memiliki harapan besar untuk kalian semua!",
  ui_story_1016_10160701_11_dialog_content = "Mari kita pastikan peralatan kita sudah beres.",
  ui_story_1016_10160701_12_dialog_content = "Ya! Terlihat bagus untukku!",
  ui_story_1016_10160701_13_dialog_content = "Kami bersenjata lengkap, jadi Eclipsites itu sebaiknya berhati-hati!",
  ui_story_1016_10160701_14_dialog_content = "Mari kita tetap pada rencana yang kita bahas sebelumnya.",
  ui_story_1016_10160701_15_dialog_content = "Tim lain pasti membeli peta dan item pengumpulan informasi lainnya. Yang perlu kita lakukan hanyalah menggunakan PlayerNamekemampuan psikis untuk mengikuti salah satu dari mereka ke Undercity.",
  ui_story_1016_10160701_16_dialog_content = "Diterima. Saya sudah mencari tim lain.",
  ui_story_1016_10160701_17_dialog_content = "Tapi sepertinya mereka masih di luar jangkauan. Titik awal kita harus benar-benar berjauhan.",
  ui_story_1016_10160701_18_dialog_content = "Kami akan baik-baik saja setelah kami menyelidiki lebih jauh ke kota.",
  ui_story_1016_10160701_19_dialog_content = "Sebenarnya apa nama yang kamu beli, Minch...?",
  ui_story_1016_10160701_20_dialog_content = "Cukup keren, ya? Lihat apa yang terjadi saat saya melempar granat kilat ini—",
  ui_story_1016_10160701_21_dialog_content = "<size=50>Waah!</size>",
  ui_story_1016_10160701_22_dialog_content = "Apa itu? Apakah kita sudah diserang?",
  ui_story_1016_10160701_23_dialog_content = "Nah, Merry hanya main-main.",
  ui_story_1016_10160701_24_dialog_content = "Ah, kau menangis lagi?",
  ui_story_1016_10160701_25_dialog_content = "Tentu saja tidak! Mataku benar-benar perih...",
  ui_story_1016_10160701_26_dialog_content = "Apa gunanya menghabiskan kredit kita untuk itu, Minch?",
  ui_story_1016_10160701_27_dialog_content = "Untuk bersenang-senang! Duh!",
  ui_story_1016_10160701_28_dialog_content = "Lihat, kami tidak memiliki cukup kredit untuk membeli sesuatu yang berguna.",
  ui_story_1016_10160701_29_dialog_content = "Jadi saya berpikir, \"Mengapa tidak bersenang-senang saja?\"",
  ui_story_1016_10160701_30_dialog_content = "Kurasa itu masuk akal…",
  ui_story_1016_10160701_31_dialog_content = "Lagi pula, kami di sini bukan untuk memenangkan kejuaraan.",
  ui_story_1016_10160701_32_dialog_content = "Itu hanya akan membuat masalah lebih merepotkan jika kita menang, mengingat sang juara harus menempelkan bendera fraksi mereka sendiri di spanduk.",
  ui_story_1016_10160701_33_dialog_content = "Fraksi mana yang kami katakan, lagi?",
  ui_story_1016_10160701_34_dialog_content = "Umbraton, meskipun saya belum pernah ke sana.",
  ui_story_1016_10160701_35_dialog_content = "Yuck, benarkah? Bendera Umbraton terlihat sangat jelek.",
  ui_story_1016_10160701_36_dialog_content = "Ditambah sang juara harus berhadapan dengan itu Reinhardt, Kanan? Hitung saja aku!",
  ui_story_1016_10160701_37_dialog_content = "Bukan kau yang melawannya, Minch. Bagaimanapun, Dysis adalah kapten tim kami.",
  ui_story_1016_10160701_38_dialog_content = "Aku juga tidak tertarik untuk melawannya. Dia hanyalah pahlawan tak berarti yang didukung oleh sistem yang sama tak berartinya.",
  ui_story_1016_10160701_39_dialog_content = "Upaya kami akan lebih baik dihabiskan untuk para peserta.",
  ui_story_1016_10160701_40_dialog_content = "Jangan lupa mengapa kita datang ke sini pada awalnya.",
  ui_story_1016_10160701_41_dialog_content = "Apakah akan membunuhmu untuk berhenti bersikap sok tahu sepanjang waktu, Dysis?",
  ui_story_1016_10160701_42_dialog_content = "Ayo, mari bersenang-senang selagi kita masih bisa!",
  ui_story_1016_10160701_43_dialog_content = "Tim lain praktis menunggu kita mengacau dengan mereka!",
  ui_story_1016_10160701_44_dialog_content = "Saya menemukan tim!",
  ui_story_1016_10160701_45_dialog_content = "Benar-benar? Siapa?",
  ui_story_1016_10160701_46_dialog_content = "Itu sekelompok orang aneh dari Umbraton.",
  ui_story_1016_10160701_47_dialog_content = "Saya pikir nama kapten mereka adalah Dysis atau semacamnya?",
  ui_story_1016_10160701_48_dialog_content = "Oh, aku ingat mereka! Dysis, Minch, dan Merry!",
  ui_story_1016_10160701_49_dialog_content = "Jika Anda bertanya, mereka tidak menganggap saya sebagai orang yang sangat taat aturan.",
  ui_story_1016_10160701_50_dialog_content = "Mereka langsung menuju Undercity, dan cepat.",
  ui_story_1016_10160701_51_dialog_content = "Menilai dari gerakan mereka, kupikir mereka mungkin sedang melakukan sesuatu!",
  ui_story_1016_10160701_52_dialog_content = "Saya setuju. Mereka harus memiliki tujuan yang jelas jika mereka bergerak secepat itu.",
  ui_story_1016_10160701_53_dialog_content = "Kita harus segera menyusul mereka.",
  ui_story_1016_10160701_54_dialog_content = "Kita tidak perlu melakukannya. Mereka akan segera melewati lokasi kita.",
  ui_story_1016_10160701_55_dialog_content = "Hei, kurasa aku sudah bisa mendengarnya...",
  ui_story_1016_10160701_56_dialog_content = "Yoo-hoo! Tangkap kami jika Anda bisa!",
  ui_story_1016_10160701_57_dialog_content = "Pelan-pelan, Min...",
  ui_story_1016_10160701_58_dialog_content = "Tunggu, ada yang tidak beres!",
  ui_story_1016_10160701_59_dialog_content = "Mereka dikejar oleh sekumpulan Eclipsites!",
  ui_story_1016_10160701_60_dialog_content = "Apa?!",
  ui_story_1016_10160701_61_dialog_content = "Mereka rupanya berhasil memprovokasi setiap Eclipsite di area tersebut dengan gerakan nekat mereka.",
  ui_story_1016_10160701_62_dialog_content = "Tidak hanya itu... sepertinya mereka bertiga juga tidak berniat melawan mereka.",
  ui_story_1016_10160701_63_dialog_content = "Mereka hanya memimpin Eclipsites di dekat hidung!",
  ui_story_1016_10160701_64_dialog_content = "Apa yang mereka lakukan? Apakah mereka tidak tahu ini bukan permainan lagi?",
  ui_story_1016_10160701_65_dialog_content = "Saya ragu mereka memiliki tujuan yang jelas dalam pikiran. Cepat, ayo pergi sebelum kita terjebak dalam kekacauan mereka.",
  ui_story_1016_10160701_66_dialog_content = "Saya setuju, tapi...",
  ui_story_1016_10160701_67_dialog_content = "Mereka berlari lurus ke arah kita sekarang!",
  ui_story_1016_10160701_68_dialog_content = "Lihat, Minch! Tim Caelestite ada di depan!",
  ui_story_1016_10160701_69_dialog_content = "Caelestite, ya? Aku yakin dia sangat menyenangkan! Mari kita lihat apakah dia ingin bermain!",
  ui_story_1016_10160701_70_dialog_content = "<size=50>Membantu! Eclipsites akan memakan kita! Seseorang bantu kami!!!</size>",
  ui_story_1016_10160701_71_dialog_content = "Sudah terlambat, mereka melihat kita...",
  ui_story_1016_10160701_72_dialog_content = "...",
  ui_story_1016_10160701_73_dialog_content = "Dysis! Anda dan tim Anda, dengarkan!",
  ui_story_1016_10160701_74_dialog_content = "Anda harus berbalik dan mulai melawan Eclipsites itu!",
  ui_story_1016_10160701_75_dialog_content = "Hah? Kamu pikir kamu siapa untuk memerintahku?!",
  ui_story_1016_10160701_76_dialog_content = "Berbalik dan bertarung, dan kami akan bekerja sama denganmu!",
  ui_story_1016_10160701_77_dialog_content = "Terus berlari ke arah kami, dan kami tidak punya pilihan selain memperlakukanmu sebagai musuh dan menyerang!",
  ui_story_1016_10160701_78_dialog_content = "Menyerang?!?!",
  ui_story_1016_10160701_79_dialog_content = "Ini adalah satu-satunya cara bagi kita untuk mempertahankan keunggulan.",
  ui_story_1016_10160701_80_dialog_content = "Aduh, jangan terlalu serius! Aku hanya ingin sedikit bersenang-senang, itu saja!",
  ui_story_1016_10160701_81_dialog_content = "Baik, kami akan melakukan apa yang Anda katakan dan bekerja sama!",
  ui_story_1016_10160701_82_dialog_content = "Merry, berbalik dan pukul Eclipsites itu yang tidak akan mereka lupakan!",
  ui_story_1016_10160701_83_dialog_content = "Tentu saja!",
  ui_story_1016_10160701_84_dialog_content = "Mereka menyerang! Kita juga harus bergabung dengan mereka!",
  ui_story_1016_10160701_85_dialog_content = "Benar! Mari kita akhiri ini dengan cepat!",
  ui_story_1016_10160802_1_dialog_content = "<anim type=Shake>Gaah...</anim>",
  ui_story_1016_10160802_2_dialog_content = "Heh! Itu jauh lebih mudah dari yang saya kira!",
  ui_story_1016_10160802_3_dialog_content = "Sayangnya, sepertinya tim lain jauh di depan kita sekarang.",
  ui_story_1016_10160802_4_dialog_content = "Ini bau! Kita tidak akan pernah bisa mengejar ketinggalan karena Eclipsites bodoh itu...",
  ui_story_1016_10160802_5_dialog_content = "Mungkin hanya aku, tapi sejak kita bertemu dengan mereka bertiga...",
  ui_story_1016_10160802_6_dialog_content = "Mau tak mau aku merasa seperti kita telah ditipu!",
  ui_story_1016_10160802_7_dialog_content = "Sekarang bukan waktunya untuk mengeluh.",
  ui_story_1016_10160802_8_dialog_content = "Pada tingkat ini, kejuaraan akan segera berada di luar jangkauan kita.",
  ui_story_1016_10160802_9_dialog_content = "Ayo pergi. Dysis, Anda dan tim Anda sebaiknya mengikuti kami.",
  ui_story_1016_10160802_10_dialog_content = "Ah, terima kasih atas perhatian Anda, tetapi kami tidak memiliki keinginan untuk menjelajah lebih jauh ke kota.",
  ui_story_1016_10160802_11_dialog_content = "Kami memiliki masalah yang lebih penting untuk ditangani sekarang.",
  ui_story_1016_10160802_12_dialog_content = "(Sesuatu tentang mereka tampaknya sangat aneh ...)",
  ui_story_1016_10160802_13_dialog_content = "Kalau begitu, kita berangkat sekarang. PlayerName, Vice, ayo terus bergerak.",
  ui_story_1016_10160802_14_dialog_content = "Tentu.",
  ui_story_1016_10160802_15_dialog_content = "<color=#e8d9bb>Jauh di dalam Zona Gelap Undercity</color>",
  ui_story_1016_10160802_16_dialog_content = "Ada tanda-tanda dari tim lain?",
  ui_story_1016_10160802_17_dialog_content = "Tidak sama sekali. Dilihat dari situasinya, sepertinya kami telah membuat kemajuan paling banyak dari semua orang.",
  ui_story_1016_10160802_18_dialog_content = "Bagus, kita masih memimpin. Fase penilaian jauh lebih mudah daripada yang saya perkirakan.",
  ui_story_1016_10160802_19_dialog_content = "Kemudian lagi, dengan seorang kesatria, ahli taktik, dan master Luminatics yang kuat di tim kami...",
  ui_story_1016_10160802_20_dialog_content = "Pada dasarnya tidak mungkin kita kalah, kan?",
  ui_story_1016_10160802_21_dialog_content = "Heheh, kamu pasti merasa rendah hati hari ini, bukan?",
  ui_story_1016_10160802_22_dialog_content = "Kami telah berhasil mempertahankan keunggulan sampai sekarang, jadi mari kita akhiri ini secepat mungkin.",
  ui_story_1016_10160802_23_dialog_content = "Pengajar Gronru—",
  ui_story_1016_10160802_24_dialog_content = "Silakan, saya mendengarkan.",
  ui_story_1016_10160802_25_dialog_content = "Kami ingin membelanjakan kredit kami yang tersisa untuk menentukan lokasi yang tepat dari target kami. Bisakah Anda melakukannya untuk kami?",
  ui_story_1016_10160802_26_dialog_content = "Tentu saja saya bisa, tetapi tidakkah menurut kalian ini sedikit berlebihan?",
  ui_story_1016_10160802_27_dialog_content = "Kita hampir mencapai akhir, jadi sebaiknya kita gunakan semua sumber daya yang kita miliki.",
  ui_story_1016_10160802_28_dialog_content = "<color=#e8d9bb>Bip—</color>",
  ui_story_1016_10160802_29_dialog_content = "Baiklah, lanjutkan dan periksa peta Anda. Area yang disorot adalah tempat Anda akan menemukan target.",
  ui_story_1016_10160802_30_dialog_content = "Karena semuanya adalah permainan yang adil sesuai dengan aturan yang kami berikan kepada Anda, saya tidak punya cara untuk menangkap Anda karena curang.",
  ui_story_1016_10160802_31_dialog_content = "Faktanya, saya sangat senang melihat kalian menggunakan aturan permainan untuk keuntungan Anda.",
  ui_story_1016_10160802_32_dialog_content = "Jadi lanjutkan, dan selesaikan tahap ini!",
  ui_story_1016_10160802_33_dialog_content = "Inilah saat yang kita tunggu-tunggu.",
  ui_story_1016_10160802_34_dialog_content = "Ayo maju terus, mumpung kita masih jauh di depan yang lain.",
  ui_story_1016_10160802_35_dialog_content = "<color=#e8d9bb>Jauh di dalam Zona Gelap Kota Bawah, dekat tujuan</color>",
  ui_story_1016_10160802_36_dialog_content = "<anim type=Shake>Graaah...</anim>",
  ui_story_1016_10160802_37_dialog_content = "Baiklah, itu seharusnya menjadi Eclipsite terakhir.",
  ui_story_1016_10160802_38_dialog_content = "Meskipun Anda telah memilih untuk berjalan di jalan kegelapan, saya berdoa agar Dewa Cahaya menghindarkan Anda dari penderitaan Anda.",
  ui_story_1016_10160802_39_dialog_content = "Saya masih berpikir Anda terdengar lebih menakutkan ketika Anda berbicara seperti itu, Joseph...",
  ui_story_1016_10160802_40_dialog_content = "Meskipun kita sudah sedekat mungkin dengan target kita, lokasi tepatnya...",
  ui_story_1016_10160802_41_dialog_content = "... bisa berada di mana saja di Undercity sebesar ini!",
  ui_story_1016_10160802_42_dialog_content = "<color=#e8d9bb>Bang, bang—!</color>",
  ui_story_1016_10160802_43_dialog_content = "<size=45>!!!</size>",
  ui_story_1016_10160802_44_dialog_content = "Sebuah penyergapan!",
  ui_story_1016_10160802_45_dialog_content = "Kedengarannya seperti pekerjaan untuk Petugas Intelijen.",
  ui_story_1016_10160802_46_dialog_content = "Maaf membuat Anda menunggu, dan terima kasih telah membuka jalan bagi kami. Tempat ini sangat cocok untuk pertarungan terakhir, tidakkah Anda setuju?",
  ui_story_1016_10160802_47_dialog_content = "<size=32>Cih...</size>",
  ui_story_1016_10160802_48_dialog_content = "<size=32>Mereka tiba di sini bahkan sebelum kita melakukannya, Leo.</size>",
  ui_story_1016_10160802_49_dialog_content = "<size=32>Ini rumah mereka, saya seharusnya sudah melihat ini datang sejak lama.</size>",
  ui_story_1016_10160802_50_dialog_content = "Nah, sejak mereka melepaskan tembakan pertama, sudah jelas untuk apa mereka di sini.",
  ui_story_1016_10160802_51_dialog_content = "Ini bukanlah sesuatu yang bisa kami hindari. Bagaimanapun, hanya ada satu juara.",
  ui_story_1016_10160802_52_dialog_content = "Saya senang Anda mengerti. Sepertinya kita akhirnya bisa mulai menganggap serius sekarang.",
  ui_story_1016_10160802_53_dialog_content = "Saya siap bertarung.",
  ui_story_1016_10160901_1_dialog_content = "<color=#e8d9bb>Bang, bang, bang—!</color>",
  ui_story_1016_10160901_2_dialog_content = "Sepertinya kita tidak diterima di sini.",
  ui_story_1016_10160901_3_dialog_content = "Mereka membuat saya ditembaki. Hati-Hati, Leo, gadis itu mendatangimu.",
  ui_story_1016_10160901_4_dialog_content = "Ini belum berakhir.",
  ui_story_1016_10160901_5_dialog_content = "<size=45>!!!</size>",
  ui_story_1016_10160901_6_dialog_content = "Leo!",
  ui_story_1016_10160901_7_dialog_content = "Trims!",
  ui_story_1016_10160901_8_dialog_content = "Siapa yang tahu gadis kecil seperti itu bisa mengemas pukulan yang begitu serius, ya?",
  ui_story_1016_10160901_9_dialog_content = "Federasi Illumina memiliki talenta muda, itu sudah pasti. Tidak bisa mengatakan saya tidak sedikit cemburu, jujur.",
  ui_story_1016_10160901_10_dialog_content = "Kotak.",
  ui_story_1016_10160901_11_dialog_content = "Agh!",
  ui_story_1016_10160901_12_dialog_content = "(Dia tahu persis ke arah mana aku mencoba bergerak. Mungkinkah dia memisahkan kita?)",
  ui_story_1016_10160901_13_dialog_content = "(Sekarang kesempatan kita.)",
  ui_story_1016_10160901_14_dialog_content = "(Menggunakan peralatan yang tidak pantas ini meninggalkan rasa tidak enak di mulutku.)",
  ui_story_1016_10160901_15_dialog_content = "(Apakah ini benar-benar... Bagaimana orang-orang itu ingin tim kita menang?)",
  ui_story_1016_10160901_16_dialog_content = "(Saya masih belum memiliki informasi yang cukup. Sepertinya saya harus mencari tahu sambil jalan.)",
  ui_story_1016_10160901_17_dialog_content = "(Dimulai dengan ini!)",
  ui_story_1016_10160901_18_dialog_content = "Aku tahu kau akan mengejarku.",
  ui_story_1016_10160901_19_dialog_content = "<size=45>Apa?!</size>",
  ui_story_1016_10160901_20_dialog_content = "Saya sudah melihat strategi Anda benar.",
  ui_story_1016_10160901_21_dialog_content = "Tolong jangan remehkan satu orang pun dari Twilight!",
  ui_story_1016_10160901_22_dialog_content = "Aduh!!!",
  ui_story_1016_10160901_23_dialog_content = "(Dia kuat!)",
  ui_story_1016_10160901_24_dialog_content = "(Meskipun aku memakai semua perlengkapan ini, serangannya masih berhasil menembus pertahananku...)",
  ui_story_1016_10160901_25_dialog_content = "(Pria ini jauh lebih kuat dari yang ditunjukkan intel saya!)",
  ui_story_1016_10160901_26_dialog_content = "Maafkan aku, tapi aku harus mengalahkanmu sekarang.",
  ui_story_1016_10160901_27_dialog_content = "<size=45>!!!</size>",
  ui_story_1016_10160901_28_dialog_content = "Yingel! Saya butuh bantuan!",
  ui_story_1016_10160901_29_dialog_content = "Apa?!",
  ui_story_1016_10160901_30_dialog_content = "Anatoli!",
  ui_story_1016_10160901_31_dialog_content = "Sekarang adalah waktu yang salah untuk kehilangan fokus!",
  ui_story_1016_10160901_32_dialog_content = "—!",
  ui_story_1016_10160901_33_dialog_content = "(Ini tidak baik, mereka membuat kita dalam posisi bertahan sekarang.)",
  ui_story_1016_10160901_34_dialog_content = "<color=#e8d9bb>Sementara itu, di tempat lain di Undercity</color>",
  ui_story_1016_10160901_35_dialog_content = "Kita ada di mana?",
  ui_story_1016_10160901_36_dialog_content = "Aku tidak berpikir bahwa mengikuti tim itu akan membawa kita ke tempat seperti ini...",
  ui_story_1016_10160901_37_dialog_content = "Sepertinya beberapa koridor...",
  ui_story_1016_10160901_38_dialog_content = "Tapi yang jelas tempat ini sudah lama ditinggalkan.",
  ui_story_1016_10160901_39_dialog_content = "Saya tau? Tidak ada apa-apa di sini selain debu dan sarang laba-laba.",
  ui_story_1016_10160901_40_dialog_content = "Rasanya seperti sesuatu yang menakutkan akan melompat keluar dan menakuti kita...",
  ui_story_1016_10160901_41_dialog_content = "<anim type=Shake><size=45>Grr...</size></anim>",
  ui_story_1016_10160901_42_dialog_content = "Perasaan ini... Hati-hati, semuanya!",
  ui_story_1016_10160901_43_dialog_content = "Sesuatu yang besar sedang menyerang kita!",
  ui_story_1016_10160901_44_dialog_content = "<anim type=Shake><size=50>Grahhhh—!!!</size></anim>",
  ui_story_1016_10160901_45_dialog_content = "Ah-!",
  ui_story_1016_10160901_46_dialog_content = "A-Apakah itu laba-laba raksasa?!",
  ui_story_1016_10160901_47_dialog_content = "Tetap waspada! Benda itu terlihat kuat.",
  ui_story_1016_10160901_48_dialog_content = "Mari kita selesaikan ini dengan cepat. Kami masih harus menemukan spanduk itu!",
  ui_story_1016_10160902_1_dialog_content = "<anim type=Shake><size=50>Grahhhh—!!!</size></anim>",
  ui_story_1016_10160902_2_dialog_content = "Kami menyerang bersama, Vice!",
  ui_story_1016_10160902_3_dialog_content = "Siap!",
  ui_story_1016_10160902_4_dialog_content = "Bunga Es—!",
  ui_story_1016_10160902_5_dialog_content = "<anim type=Shake><size=50>Keren!!!</size></anim>",
  ui_story_1016_10160902_6_dialog_content = "<size=45>Sekarang!</size>",
  ui_story_1016_10160902_7_dialog_content = "Aku hanya butuh satu tembakan!",
  ui_story_1016_10160902_8_dialog_content = "<anim type=Shake><size=40>Mengaum-!</size></anim>",
  ui_story_1016_10160902_9_dialog_content = "Kami akhirnya menurunkannya...",
  ui_story_1016_10160902_10_dialog_content = "Fiuh—aku tahu.",
  ui_story_1016_10160902_11_dialog_content = "Hal itu terlalu sulit!",
  ui_story_1016_10160902_12_dialog_content = "Eclipsites yang kami hadapi sampai sekarang tidak ada apa-apanya dibandingkan dengan bug besar ini!",
  ui_story_1016_10160902_13_dialog_content = "Memang. Eclipsite sekuat ini seharusnya tidak berada dalam fase penilaian sama sekali.",
  ui_story_1016_10160902_14_dialog_content = "Ini seharusnya menjadi program pelatihan. Mengapa sesuatu yang berbahaya ini bersembunyi di balik bayang-bayang di sini?",
  ui_story_1016_10160902_15_dialog_content = "Mungkinkah seseorang sengaja menaruhnya di sini?",
  ui_story_1016_10160902_16_dialog_content = "Saya tidak bisa mengatakan dengan pasti. Mungkin saja sejauh ini kita benar-benar tidak beruntung.",
  ui_story_1016_10160902_17_dialog_content = "Undercity ini telah ditinggalkan selama berabad-abad, jadi pasti ada Eclipsites yang bersembunyi di mana-mana.",
  ui_story_1016_10160902_18_dialog_content = "Mari kita simpan diskusi ini untuk nanti.",
  ui_story_1016_10160902_19_dialog_content = "Kami telah kehilangan cukup waktu seperti itu.",
  ui_story_1016_10160902_20_dialog_content = "Penundaan lebih lanjut, dan kami akan kehilangan kesempatan untuk menang.",
  ui_story_1016_10160902_21_dialog_content = "<color=#e8d9bb>Gruk—</color>",
  ui_story_1016_10160902_22_dialog_content = "Suara apa itu?!",
  ui_story_1016_10160902_23_dialog_content = "Eclipsite?",
  ui_story_1016_10160902_24_dialog_content = "Mungkinkah lebih banyak Eclipsites?",
  ui_story_1016_10160902_25_dialog_content = "Saya khawatir tidak. Dengarkan baik-baik...",
  ui_story_1016_10160902_26_dialog_content = "<color=#e8d9bb>Boom... Gemuruh... Bang...</color>",
  ui_story_1016_10160902_27_dialog_content = "Itu adalah suara tembakan dan Luminatics, dan sepertinya tidak hanya berasal dari satu tim.",
  ui_story_1016_10160902_28_dialog_content = "Kamu benar. Hampir terdengar seperti dua tim yang berbeda saling bertarung!",
  ui_story_1016_10160902_29_dialog_content = "Tujuan kami untuk fase ini adalah untuk merebut kembali panji, bukan untuk saling bertarung. Satu-satunya alasan mereka bisa bertarung...",
  ui_story_1016_10160902_30_dialog_content = "Apakah karena mereka pasti menemukan spanduknya!",
  ui_story_1016_10160902_31_dialog_content = "Spanduk?",
  ui_story_1016_10160902_32_dialog_content = "Apakah menurut Anda seseorang menemukan spanduk itu?",
  ui_story_1016_10160902_33_dialog_content = "Itu mungkin. Mari kita dengarkan lebih dekat.",
  ui_story_1016_10160902_34_dialog_content = "<color=#e8d9bb>Boom... Gemuruh... Bang...</color>",
  ui_story_1016_10160902_35_dialog_content = "Itu adalah suara tembakan dan Luminatics, dan sepertinya tidak hanya berasal dari satu tim.",
  ui_story_1016_10160902_36_dialog_content = "Mungkinkah dua tim menemukan bendera pada saat yang sama, dan sekarang mereka memperebutkan bendera itu?!",
  ui_story_1016_10160902_37_dialog_content = "Saya akan mengatakan itu taruhan yang cukup aman!",
  ui_story_1016_10160902_38_dialog_content = "Maka kita harus bergegas sebelum pertarungan mereka selesai!",
  ui_story_1016_10160902_39_dialog_content = "Setuju!",
  ui_story_1016_10160902_40_dialog_content = "<color=#e8d9bb>Sementara itu, di kedalaman Undercity</color>",
  ui_story_1016_10160902_41_dialog_content = "Target terkunci!",
  ui_story_1016_10160902_42_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_1016_10160902_43_dialog_content = "Anda tidak akan melewati saya!",
  ui_story_1016_10160902_44_dialog_content = "(Saya tidak berpikir mereka akan begitu kuat. Bahkan setelah kalah, mereka masih cocok dengan pukulan kita.)",
  ui_story_1016_10160902_45_dialog_content = "(Terutama Petugas Intelijen itu, Anatoli. Bagaimana dia memasuki fase penilaian dengan peralatan seperti itu?)",
  ui_story_1016_10160902_46_dialog_content = "(Saya telah mengawasi tim mereka selama ini. Meskipun memiliki kredit yang jauh lebih sedikit daripada kami, mereka berhasil mendapatkan perlengkapan yang lebih baik.)",
  ui_story_1016_10160902_47_dialog_content = "(Itu tidak bertambah. Jika ada, sepertinya Illumina diam-diam memberi mereka keuntungan yang tidak adil.)",
  ui_story_1016_10160902_48_dialog_content = "(Tapi itu tidak masalah lagi. Federasi Illumina tahu semua tentang situasi kita di Twilight, jadi misi kita sudah selesai. Tinggal yang tersisa...)",
  ui_story_1016_10160902_49_dialog_content = "Yusuf!",
  ui_story_1016_10160902_50_dialog_content = "Apa itu, Leo?",
  ui_story_1016_10160902_51_dialog_content = "...",
  ui_story_1016_10160902_52_dialog_content = "(Tunggu, apakah maksudnya...?)",
  ui_story_1016_10160902_53_dialog_content = "Aku paham.",
  ui_story_1016_10160902_54_dialog_content = "(Serangannya semakin lambat. Apakah ini jebakan?)",
  ui_story_1016_10160902_55_dialog_content = "(Tidak, ini kesempatan sempurna bagi kami!)",
  ui_story_1016_10160902_56_dialog_content = "Yingel!",
  ui_story_1016_10160902_57_dialog_content = "Paham!",
  ui_story_1016_10160902_58_dialog_content = "Zhao! Tarik mundur dan bersiaplah untuk bertahan!",
  ui_story_1016_10160902_59_dialog_content = "Siap!",
  ui_story_1016_10160902_60_dialog_content = "Kami tidak akan membiarkanmu!",
  ui_story_1016_10160902_61_dialog_content = "<color=#e8d9bb>Bang, bang, bang—!</color>",
  ui_story_1016_10160902_62_dialog_content = "Sial, dia memotong jalan keluar kita!",
  ui_story_1016_10160902_63_dialog_content = "Sekarang, Axelia!",
  ui_story_1016_10160902_64_dialog_content = "Maaf atas keterlambatannya.",
  ui_story_1016_10160902_65_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_1016_10160902_66_dialog_content = "Urgh—!",
  ui_story_1016_10160902_67_dialog_content = "Zhao kalah!",
  ui_story_1016_10160902_68_dialog_content = "Tetap dekat dengan saya! Saya akan menggunakan Luminatics saya untuk mendukung Anda!",
  ui_story_1016_10160902_69_dialog_content = "Latihan sia-sia.",
  ui_story_1016_10160902_70_dialog_content = "<color=#e8d9bb>Duarr!!!</color>",
  ui_story_1016_10160902_71_dialog_content = "Batuk... Batuk, batuk, batuk!",
  ui_story_1016_10160902_72_dialog_content = "Saya seharusnya tidak terkejut, tetapi senjata pamungkas Illumina benar-benar hebat.",
  ui_story_1016_10160902_73_dialog_content = "Sepertinya kita tidak punya kesempatan lagi, Leo.",
  ui_story_1016_10160902_74_dialog_content = "Tidak bercanda. Kami menyerah.",
  ui_story_1016_10160902_75_dialog_content = "Pilihan bijak.",
  ui_story_1016_10160902_76_dialog_content = "Ambil spanduk, Axelia.",
  ui_story_1016_10160902_77_dialog_content = "Aku mengerti.",
  ui_story_1016_10160902_78_dialog_content = "Dan pemenangnya adalah-",
  ui_story_1016_10160902_79_dialog_content = "<size=45>Kita berhasil!!!</size>",
  ui_story_1016_10160902_80_dialog_content = "...",
  ui_story_1016_10160902_81_dialog_content = "...",
  ui_story_1016_10160902_82_dialog_content = "...",
  ui_story_1016_10160902_83_dialog_content = ".... Benar?",
  ui_story_1016_10160902_84_dialog_content = "Sayangnya tidak ada.",
  ui_story_1016_10160902_85_dialog_content = "Jika Anda tiba lima detik lebih awal, Anda akan memiliki kesempatan untuk melawan kami demi spanduk itu.",
  ui_story_1016_10160902_86_dialog_content = "Benar-benar? Tampaknya kami tertunda terlalu lama.",
  ui_story_1016_10160902_87_dialog_content = "Bagaimana ini mungkin...?",
  ui_story_1016_10160902_88_dialog_content = "Kami sangat merindukannya...",
  ui_story_1016_10160902_89_dialog_content = "Cukup. Bagaimanapun, kami melakukan yang terbaik.",
  ui_story_1016_10160902_90_dialog_content = "Sekarang pemenang telah diputuskan, tidak ada gunanya menyesali hasilnya.",
  ui_story_1016_10160902_91_dialog_content = "Sebaliknya, kita harus berusaha untuk terus berkembang.",
  ui_story_1016_10160902_92_dialog_content = "Ya kamu benar...",
  ui_story_1016_10160902_93_dialog_content = "Tanpa basa-basi lagi, izinkan saya untuk mengumumkan hasilnya.",
  ui_story_1016_10160902_94_dialog_content = "Pemenang fase penilaian adalah—<color=#FFB400>Tim Yingel</color>!",
  ui_story_1016_10160902_95_dialog_content = "Selain itu, penghargaan untuk peserta dengan kinerja tertinggi dalam Latihan Militer Gabungan ini adalah—Letnan <color=#FFB400>Axelia</color>!",
  ui_story_1016_10160902_96_dialog_content = "Selamat untuk kalian bertiga!",
  ui_story_1016_10160902_97_dialog_content = "Terima kasih.",
  ui_story_1016_10160902_98_dialog_content = "(Misi kita akhirnya selesai.)",
  ui_story_1016_10160902_99_dialog_content = "Saya menang.",
  ui_story_1016_10160902_100_dialog_content = "Tepat seperti yang diharapkan.",
  ui_story_1016_10160902_101_dialog_content = "(Keduanya sama sekali tidak terlihat terkejut atau bersemangat tentang kemenangan mereka.)",
  ui_story_1016_10160902_102_dialog_content = "(Saya tahu mereka bukan orang yang paling ekspresif, tapi ini terasa aneh bahkan bagi mereka.)",
  ui_story_1016_10160902_103_dialog_content = "(Mungkinkah ini juga bagian dari rencana...?)",
  ui_story_1016_10161001_1_dialog_content = "Selamat, Letnan Axelia!",
  ui_story_1016_10161001_2_dialog_content = "Semua orang di Federasi Illumina sedang merayakan kemenanganmu!",
  ui_story_1016_10161001_3_dialog_content = "Saya hanya menjalankan tugas saya.",
  ui_story_1016_10161001_4_dialog_content = "Minggir, kalian semua—",
  ui_story_1016_10161001_5_dialog_content = "Dia butuh istirahatnya sekarang.",
  ui_story_1016_10161001_6_dialog_content = "Sepertinya seluruh Illumina sedang mencoba menjabat tangan gadis malang itu sekarang.",
  ui_story_1016_10161001_7_dialog_content = "Ya, benar.",
  ui_story_1016_10161001_8_dialog_content = "Sekarang setelah semuanya berakhir, kurasa aku pantas mengetahui kebenaran di balik keputusanmu—",
  ui_story_1016_10161001_9_dialog_content = "Alasan Anda rela kalah dalam pertarungan.",
  ui_story_1016_10161001_10_dialog_content = "Karena kita sudah mencapai tujuan kita.",
  ui_story_1016_10161001_11_dialog_content = "Kapten Wrath sepenuhnya menyadari situasi Twilight sekarang. Dengan pengalaman tempurnya, saya yakin dia tahu persis apa yang kami alami.",
  ui_story_1016_10161001_12_dialog_content = "Pengetahuan itu, pada gilirannya, akan menyebar dengan cepat melalui jaringan intelijen Illumina sebelum mencapai petinggi Lumopolis.",
  ui_story_1016_10161001_13_dialog_content = "Meski begitu, saya masih berpikir kami memiliki kewajiban untuk memenangkan kejuaraan untuk diri kami sendiri.",
  ui_story_1016_10161001_14_dialog_content = "Itu akan membawa lebih banyak perhatian kepada kami, yang dapat digunakan untuk meningkatkan lebih banyak dukungan untuk Twilight.",
  ui_story_1016_10161001_15_dialog_content = "Dengan konjungtur semakin dekat, kami membutuhkan semua bantuan yang bisa kami dapatkan.",
  ui_story_1016_10161001_16_dialog_content = "Namun Anda masih memilih untuk mengikuti keputusan saya untuk menyerah.",
  ui_story_1016_10161001_17_dialog_content = "Itu karena aku percaya pada penilaianmu. Saya masih melakukannya, sebenarnya, tetapi saya hanya ingin tahu alasannya.",
  ui_story_1016_10161001_18_dialog_content = "Karena ini adalah kesempatan terbaik kita untuk meyakinkan orang lain untuk membantu kita.",
  ui_story_1016_10161001_19_dialog_content = "Saya pikir tim dari Illumina memiliki beberapa trik selama ini.",
  ui_story_1016_10161001_20_dialog_content = "Saya telah memperhatikan mereka sejak kami memulai Latihan Militer Gabungan, dan begitu banyak hal tentang mereka yang tampak aneh.",
  ui_story_1016_10161001_21_dialog_content = "Mereka kuat, tidak diragukan lagi, namun mereka tampaknya kurang puas dengan kemenangan mereka.",
  ui_story_1016_10161001_22_dialog_content = "Apakah Anda mencoba mengatakan ... bahwa mereka curang?",
  ui_story_1016_10161001_23_dialog_content = "Saya tidak punya bukti nyata, tapi saya yakin akan hal itu.",
  ui_story_1016_10161001_24_dialog_content = "Perlengkapan yang mereka bawa ke pertempuran terakhir lebih baik daripada yang mampu dibeli oleh kredit mereka.",
  ui_story_1016_10161001_25_dialog_content = "Perbedaannya tidak terlalu terlihat, setidaknya tidak di permukaan, tapi itu pasti membawa kekuatan mereka ke level berikutnya.",
  ui_story_1016_10161001_26_dialog_content = "Seseorang telah membantu mereka di belakang layar.",
  ui_story_1016_10161001_27_dialog_content = "Anda pikir itu mungkin atasan Illumina?",
  ui_story_1016_10161001_28_dialog_content = "Itu mungkin, yang berarti kemenangan mereka terjamin sejak awal.",
  ui_story_1016_10161001_29_dialog_content = "Tapi sepertinya menang bukanlah tujuan mereka yang sebenarnya. Saya pikir itu pasti sesuatu yang lain.",
  ui_story_1016_10161001_30_dialog_content = "Jika ya, maka kemenangan hanyalah langkah yang diperlukan di sepanjang jalan...",
  ui_story_1016_10161001_31_dialog_content = "Jangan-jangan...?",
  ui_story_1016_10161001_32_dialog_content = "Siapa tahu?",
  ui_story_1016_10161001_33_dialog_content = "Tapi sesuatu memberitahuku hal-hal akan menjadi sedikit sibuk.",
  ui_story_1016_10161001_34_dialog_content = "Apa-",
  ui_story_1016_10161001_35_dialog_content = "PlayerName dan timnya berhasil memberikan setiap kejutan yang kami siapkan untuk tim dari Twilight...",
  ui_story_1016_10161001_36_dialog_content = "Ketiganya benar-benar menyebalkan! Apakah mereka mencoba merusak rencana kita atau semacamnya?!",
  ui_story_1016_10161001_37_dialog_content = "Dari apa yang saya tahu, semua ini murni kebetulan, tetapi itu tidak berarti rencana kami telah digagalkan.",
  ui_story_1016_10161001_38_dialog_content = "Tim dari Twilight berhasil menunjukkan kekuatan mereka, dan kejutan kami menghasilkan penemuan yang tidak terduga.",
  ui_story_1016_10161001_39_dialog_content = "Saya yakin master kami akan senang mengetahui tentang semua orang kuat yang kami temui di sini.",
  ui_story_1016_10161001_40_dialog_content = "Tidak hanya itu, Caelestite dan timnya mengalahkan Spider Queen jauh lebih cepat dari yang kami perkirakan. Ini hanya dapat berarti bahwa kekuatan mereka juga meningkat pesat.",
  ui_story_1016_10161001_41_dialog_content = "Tetap saja, jebakan kami tampaknya membuat mereka kehilangan kesempatan untuk memenangkan kejuaraan.",
  ui_story_1016_10161001_42_dialog_content = "Saya hanya berharap mereka tidak akan terlalu marah dengan kami...",
  ui_story_1016_10161001_43_dialog_content = "<anim type=Shake>Yaawn—</anim>aku kalah.",
  ui_story_1016_10161001_44_dialog_content = "Bisakah kita kembali sekarang? Aku tidak ingin bangun dari tempat tidur selama tiga hari setelah ini...",
  ui_story_1016_10161001_45_dialog_content = "Sabar, Min.",
  ui_story_1016_10161001_46_dialog_content = "Kami masih memiliki pekerjaan yang harus dilakukan. Kita belum bisa kembali.",
  ui_story_1016_10161001_47_dialog_content = "Itu benar. Kami masih memiliki satu tugas yang sangat penting untuk dilaksanakan.",
  ui_story_1016_10161001_48_dialog_content = "<color=#e8d9bb>Kota Gannon, Kantor Ulysses</color>",
  ui_story_1016_10161001_49_dialog_content = "Kembali di Gannon City, ya...",
  ui_story_1016_10161001_50_dialog_content = "Apa yang terjadi selanjutnya akan menjadi awal dari babak baru Illumina.",
  ui_story_1016_10161001_51_dialog_content = "Hmm? Apa ini...",
  ui_story_1016_10161001_52_dialog_content = "Seperti biasa, rencananya sempurna, hingga detail terkecil. Andai saja dia memasukkan waktu untuk mengatur napas.",
  ui_story_1016_10161001_53_dialog_content = "Esien, bisakah kamu datang menemuiku?",
  ui_story_1016_10161001_54_dialog_content = "Segera.",
  ui_story_1016_10161001_55_dialog_content = "<color=#e8d9bb>Ketuk, ketuk, ketuk</color>",
  ui_story_1016_10161001_56_dialog_content = "Bagaimana saya bisa membantu Anda, Pak?",
  ui_story_1016_10161001_57_dialog_content = "Ambil ini dan kirimkan ke Lady <color=#FFB400>Topeng Besi</color>... Beri tahu dia-",
  ui_story_1016_10161001_58_dialog_content = "Ini adalah perubahan yang saya usulkan pada struktur pertahanan kota, dan saya membutuhkan kerja samanya.",
  ui_story_1016_10161001_59_dialog_content = "Aku mengerti.",
  ui_story_1016_10161001_60_dialog_content = "<color=#e8d9bb>Sementara itu, di suatu tempat di Gannon City...</color>",
  ui_story_1016_10161001_61_dialog_content = "Belum waktunya, tetapi pencarian Illumina semakin panik.",
  ui_story_1016_10161001_62_dialog_content = "Sialan kau, orang tua... Apa kau sangat menginginkan hasil penelitianku?",
  ui_story_1016_10161001_63_dialog_content = "Kalau begitu, mungkin Jade bisa...",
  ui_story_1016_10161001_64_dialog_content = "...",
  ui_story_1016_10161001_65_dialog_content = "Saya hampir lupa. Jade mungkin sudah lama pergi sekarang.",
  ui_story_1016_10161001_66_dialog_content = "Menyangkal!",
  ui_story_1016_10161001_67_dialog_content = "Apa itu, Reinhardt?",
  ui_story_1016_10161001_68_dialog_content = "Apa kau tidak ingat hari ini hari apa?",
  ui_story_1016_10161001_69_dialog_content = "Hari ini...?",
  ui_story_1016_10161001_70_dialog_content = "Apakah sudah waktunya untuk menyerahkan hasil percobaan kami? Atau mungkin ini hari terakhir periode penilaian kita?",
  ui_story_1016_10161001_71_dialog_content = "Salah di kedua akun!",
  ui_story_1016_10161001_72_dialog_content = "Anda benar-benar lupa? Ini hari ulang tahunmu hari ini, Denier!",
  ui_story_1016_10161001_73_dialog_content = "Ulang tahunku? Oh ya, itu benar.",
  ui_story_1016_10161001_74_dialog_content = "Bagaimana Anda bisa melupakan hari ulang tahun Anda sendiri?",
  ui_story_1016_10161001_75_dialog_content = "Tidak ada yang spesial, sungguh. Selain beberapa gerakan adat, ulang tahun benar-benar tidak berbeda dari hari lainnya.",
  ui_story_1016_10161001_76_dialog_content = "Sigh... Tanggapan khas Denier lainnya.",
  ui_story_1016_10161001_77_dialog_content = "Anda adalah satu-satunya orang yang akan memberikan penilaian yang begitu tenang dan rasional pada hari ulang tahun Anda sendiri.",
  ui_story_1016_10161001_78_dialog_content = "Tetapi hanya karena Anda tidak peduli, bukan berarti itu tidak penting bagi orang lain.",
  ui_story_1016_10161001_79_dialog_content = "Hah?",
  ui_story_1016_10161001_80_dialog_content = "Aku memberimu hadiah ulang tahun.",
  ui_story_1016_10161001_81_dialog_content = "Nih, makanlah!",
  ui_story_1016_10161001_82_dialog_content = "Ciit!",
  ui_story_1016_10161001_83_dialog_content = "Apa ini?!",
  ui_story_1016_10161001_84_dialog_content = "Ha ha ha! Saya pikir dia menyukai Anda, Denier!",
  ui_story_1016_10161001_85_dialog_content = "Saya menemukannya di medan perang selama penempatan terakhir saya. Saya tidak yakin binatang apa dia, tapi saya pikir dia sangat lucu!",
  ui_story_1016_10161001_86_dialog_content = "Jadi saya memutuskan untuk membawanya kembali dan merawatnya untuk sementara waktu. Saya mencoba memberi makan roti serbuk gergaji, tetapi dia tampaknya tidak peduli.",
  ui_story_1016_10161001_87_dialog_content = "Anggap dia pendukungku setiap kali aku tidak di sisimu, oke?",
  ui_story_1016_10161001_88_dialog_content = "Kamu bercanda kan...?",
  ui_story_1016_10161001_89_dialog_content = "Ini chinchilla. Roti serbuk gergaji tidak ada di mana pun dalam makanan alaminya.",
  ui_story_1016_10161001_90_dialog_content = "Jika Anda akan merawatnya, Anda harus mencoba memberinya makan jerami atau biji-bijian. Bahkan beberapa wortel akan sangat membantu.",
  ui_story_1016_10161001_91_dialog_content = "Melihat? Saya tahu Anda akan menjadi orang yang sempurna untuk merawatnya!",
  ui_story_1016_10161001_92_dialog_content = "Saya hanya tahu ini karena kami terus-menerus melakukan percobaan pada hewan seperti ini. Menjaga mereka cukup makan hanyalah bagian dari proses.",
  ui_story_1016_10161001_93_dialog_content = "<anim type=Shake><size=45>Mencicit!!!</size></anim>",
  ui_story_1016_10161001_94_dialog_content = "Hentikan, Denier! Anda membuatnya takut!",
  ui_story_1016_10161001_95_dialog_content = "...",
  ui_story_1016_10161001_96_dialog_content = "<anim type=Shake>Mencicit...</anim>",
  ui_story_1016_10161001_97_dialog_content = "Aku berjanji tidak akan melakukan apapun padanya. Lagipula dia adalah hadiah darimu.",
  ui_story_1016_10161001_98_dialog_content = "Jadi, apakah itu berarti Anda menerima hadiah saya?",
  ui_story_1016_10161001_99_dialog_content = "Ya.",
  ui_story_1016_10161001_100_dialog_content = "Kalau begitu mari kita pikirkan nama untuknya!",
  ui_story_1016_10161001_101_dialog_content = "Sebuah nama, ya...",
  ui_story_1016_10161001_102_dialog_content = "Mari kita panggil dia <color=#FFB400>Giok</color>.",
  ui_story_1016_10161001_103_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_1016_10161001_104_dialog_content = "M-Eksperimen saya...",
  ui_story_1016_10161001_105_dialog_content = "Mereka semua pergi sekarang...",
  ui_story_1016_10161001_106_dialog_content = "Mengapa, Reinhardt... Kenapa kamu belum kembali?!",
  ui_story_1016_10161001_107_dialog_content = "<anim type=Shake><size=45>Mencicit, mencicit—</size></anim>",
  ui_story_1016_10161001_108_dialog_content = "Kamu...",
  ui_story_1016_10161001_109_dialog_content = "Anggap dia pendukungku setiap kali aku tidak di sisimu, oke?",
  ui_story_1016_10161001_110_dialog_content = "Kau…?!",
  ui_story_1016_10161001_111_dialog_content = "<anim type=Shake><size=45>Mencicit! Mencicit-!!!</size></anim>",
  ui_story_1016_10161001_112_dialog_content = "<anim type=Shake>Mencicit...</anim>",
  ui_story_1016_10161001_113_dialog_content = "—!!!",
  ui_story_1016_10161001_114_dialog_content = "Ciit!",
  ui_story_1016_10161001_115_dialog_content = "<anim type=Shake>Mencicit... mencicit...</anim>",
  ui_story_1016_10161001_116_dialog_content = "Kenapa kamu masih disini? Tidakkah kamu tahu aku bisa mematahkan leher kecilmu kapan pun aku mau?",
  ui_story_1016_10161001_117_dialog_content = "Kenapa kamu tidak lari seperti dia?",
  ui_story_1016_10161001_118_dialog_content = "<anim type=Shake><size=32>Mencicit...</size></anim>",
  ui_story_1016_10161001_119_dialog_content = "...",
  ui_story_1016_10161001_120_dialog_content = "Lupakan...",
  ui_story_1016_10161001_121_dialog_content = "Aku akan membiarkanmu tinggal untuk saat ini.",
  ui_story_1016_10161001_122_dialog_content = "Paling tidak, Anda memiliki beberapa nilai sebagai subjek tes.",
  ui_story_1016_10161001_123_dialog_content = "Nilai, ya?",
  ui_story_1016_10161001_124_dialog_content = "Memang benar di dunia ini, segala sesuatu diukur dari nilainya.",
  ui_story_1016_10161001_125_dialog_content = "<color=#e8d9bb>Gemerisik, gemerisik...</color>",
  ui_story_1016_10161001_126_dialog_content = "Denier... Aku merasakan pergerakan... Hati-hati...",
  ui_story_1016_10161001_127_dialog_content = "Groar...",
  ui_story_1016_10161001_128_dialog_content = "Itu... sebuah Eclipsite!",
  ui_story_1016_10161001_129_dialog_content = "...",
  ui_story_1016_10161001_130_dialog_content = "Letakkan senjatamu. Itu tidak akan menyakitimu.",
  ui_story_1016_10161001_131_dialog_content = "(Eclipsian) Lady Forsakin, saya membawa pesan dari Tuhan <color=#FFB400>Figerald</color>.",
  ui_story_1016_10161001_132_dialog_content = "(Eclipsian) Bicaralah.",
  ui_story_1016_10161001_133_dialog_content = "(Eclipsian) \"Untuk menyambut kami dengan baik <color=#FFB400>para tamu tersayang</color>, kamu harus menghancurkan sistem pertahanan Illumina dari dalam.\"",
  ui_story_1016_10161001_134_dialog_content = "(Eclipsian) Jadi akhirnya waktunya.",
  ui_story_1016_10161001_135_dialog_content = "<color=#e8d9bb>Hari pameran terakhir, 15 menit sebelum dimulainya pertandingan</color>",
  ui_story_1016_10161001_136_dialog_content = "Mendesah-",
  ui_story_1016_10161001_137_dialog_content = "Saya tidak percaya kami tidak dapat membantu Carleen melindungi gelarnya.",
  ui_story_1016_10161001_138_dialog_content = "Aku tahu…",
  ui_story_1016_10161001_139_dialog_content = "Jangan terlihat begitu kalah. Tidak ada yang memalukan tentang kekalahan kami.",
  ui_story_1016_10161001_140_dialog_content = "Mereka yang mengikuti Latihan Militer Gabungan adalah yang terbaik dan paling cerdas dari faksi masing-masing. Melihat orang yang lebih kuat dari kita seharusnya tidak mengejutkan.",
  ui_story_1016_10161001_141_dialog_content = "Kemenangan dan kekalahan tidak pernah tertulis di batu. Kami mungkin telah gagal, tapi sekarang kami tahu seberapa kuat saingan kami. Jika ada, mereka memberi kami tujuan baru untuk diusahakan.",
  ui_story_1016_10161001_142_dialog_content = "Tidak ada yang seperti salah satu pidato motivasi kuat Carleen untuk mengangkat semangat kita, ya?",
  ui_story_1016_10161001_143_dialog_content = "B-benarkah?",
  ui_story_1016_10161001_144_dialog_content = "Kalian datang untuk melihat pertandingan juga?",
  ui_story_1016_10161001_145_dialog_content = "Hai, Leo! Tidak berharap untuk melihat Anda di sini.",
  ui_story_1016_10161001_146_dialog_content = "Apakah Zhao dan Joseph tidak bersamamu?",
  ui_story_1016_10161001_147_dialog_content = "Latihan Militer Gabungan benar-benar merugikan Zhao, jadi dia memutuskan untuk meneruskan pertandingan.",
  ui_story_1016_10161001_148_dialog_content = "Joseph tetap tinggal untuk menemaninya sementara para dokter memeriksanya di rumah sakit.",
  ui_story_1016_10161001_149_dialog_content = "Kalian benar-benar tampak rukun sekarang. Kalian bahkan saling menjaga!",
  ui_story_1016_10161001_150_dialog_content = "Ha ha ha! Kamu mungkin benar!",
  ui_story_1016_10161001_151_dialog_content = "Bekerja sama juga sangat membantu kami untuk lebih mengenal satu sama lain.",
  ui_story_1016_10161001_152_dialog_content = "Meskipun kami berasal dari faksi yang berbeda, kami tetap menghormati satu sama lain sebagai rival dan rekan seperjuangan.",
  ui_story_1016_10161001_153_dialog_content = "Persaingan persahabatan, saya melihat ...",
  ui_story_1016_10161001_154_dialog_content = "Saya akan mengingatnya.",
  ui_story_1016_10161001_155_dialog_content = "Hei, bukankah itu Yingel? Dan Anatoli juga!",
  ui_story_1016_10161001_156_dialog_content = "Hah? Di mana? Haruskah kita pergi menyapa?",
  ui_story_1016_10161001_157_dialog_content = "Di sana, di sebelah kursi hakim.",
  ui_story_1016_10161001_158_dialog_content = "Ini tidak bisa...",
  ui_story_1016_10161001_159_dialog_content = "Apakah itu Eclipsites?",
  ui_story_1016_10161001_160_dialog_content = "Situasinya sangat mengerikan saat ini.",
  ui_story_1016_10161001_161_dialog_content = "Ayo selidiki.",
  ui_story_1016_10161001_162_dialog_content = "Itu aneh, saya bertanya-tanya mengapa mereka terlihat sangat serius?",
  ui_story_1016_10161001_163_dialog_content = "Kami terlalu jauh untuk mendengar apa pun yang mereka bicarakan.",
  ui_story_1016_10161001_164_dialog_content = "Pikirkan itu sesuatu yang penting?",
  ui_story_1016_10161001_165_dialog_content = "Kita harus bertanya pada mereka sendiri.",
  ui_story_1016_10161001_166_dialog_content = "Untuk seorang kesatria Lumopolis, Anda tampaknya agak khawatir dengan urusan Illumina, Leo.",
  ui_story_1016_10161001_167_dialog_content = "Maafkan kekasaran saya, tetapi saya merasa saya harus mengoreksi pernyataan Anda. Bukan Illumina yang saya khawatirkan, tetapi keselamatan dan keamanan Twilight.",
  ui_story_1016_10161001_168_dialog_content = "Tentunya Anda sudah mendengar tentang bahaya besar yang dihadapi Twilight? Bahaya itu semakin dekat setiap hari.",
  ui_story_1016_10161001_169_dialog_content = "Twilight membutuhkan semua bantuan yang bisa didapatnya jika ingin selamat dari serangan Eclipsites.",
  ui_story_1016_10161001_170_dialog_content = "Sepertinya, teman-teman kita dari Illumina membutuhkan bantuan.",
  ui_story_1016_10161001_171_dialog_content = "Selain sebagai hal yang benar untuk dilakukan, mendapatkan dukungan dari para pemimpin masa depan Illumina sekarang juga akan membantu kita dalam jangka panjang.",
  ui_story_1016_10161001_172_dialog_content = "Saya pernah mendengar tentang situasi di Twilight, ya. Saya juga sangat menyadari tekanan Anda dan rekan Anda.",
  ui_story_1016_10161001_173_dialog_content = "Saya melaporkan masalah ini ke petinggi Lumopolis dan meminta dukungan mereka.",
  ui_story_1016_10161001_174_dialog_content = "Terima kasih atas perhatiannya, Bu Carleen.",
  ui_story_1016_10161001_175_dialog_content = "Tetapi menilai dari pengalaman kami sebelumnya, saya khawatir permintaan Anda hanya akan diabaikan.",
  ui_story_1016_10161001_176_dialog_content = "Yang dibutuhkan Twilight saat ini bukanlah janji yang diucapkan, melainkan tindakan. Tindakan nyata, tegas, dan suportif.",
  ui_story_1016_10161001_177_dialog_content = "...",
  ui_story_1016_10161001_178_dialog_content = "Semua sama, saya akan mencoba yang terbaik.",
  ui_story_1016_10161001_179_dialog_content = "Twilight terima kasih atas usahamu, Lady Carleen. Seperti halnya saya.",
  ui_story_1016_10161001_180_dialog_content = "Bahkan satu tindakan kebaikan pun dapat mengubah keadaan demi kebaikan kita.",
  ui_story_1016_10161001_181_dialog_content = "Harap tetap di sini dan nikmati pertandingannya, semuanya. Aku hanya akan pergi sebentar.",
  ui_story_1016_10161001_182_dialog_content = "Tunggu, aku juga datang. Sebagai seorang prajurit Illumina, saya juga memiliki kewajiban untuk membantu mereka jika mereka dalam kesulitan!",
  ui_story_1016_10161001_183_dialog_content = "Hitung saya juga!",
  ui_story_1016_10161001_184_dialog_content = "Dan saya juga.",
  ui_story_1016_10161001_185_dialog_content = "Besar! Lalu mari kita pergi.",
  ui_story_1016_10161001_186_dialog_content = "Sudahkah kita menemukan motif atau tersangka?",
  ui_story_1016_10161001_187_dialog_content = "Mereka masih menyelidiki.",
  ui_story_1016_10161001_188_dialog_content = "Berapa banyak sistem pertahanan Kota Gannon yang telah disusupi?",
  ui_story_1016_10161001_189_dialog_content = "Dari sistem yang telah kami periksa sejauh ini, kira-kira 16% di antaranya rusak berat atau cacat total.",
  ui_story_1016_10161001_190_dialog_content = "Namun, kami hanya memeriksa setengahnya. Ukuran besar Kota Gannon dan lorong yang rumit membuat sulit untuk menilai dengan cepat seluruh jaringan sistem pertahanan kita.",
  ui_story_1016_10161001_191_dialog_content = "Tetapi meskipun hanya sebagian kecil dari sistem kami yang rusak, itu cukup untuk meninggalkan celah yang jelas di pertahanan kami. Situasi membutuhkan tindakan segera.",
  ui_story_1016_10161001_192_dialog_content = "Tindakan sabotase pedih ini... Mungkinkah perbuatan Forsakin?",
  ui_story_1016_10161001_193_dialog_content = "Itu sangat mungkin.",
  ui_story_1016_10161001_194_dialog_content = "Ikut denganku. Ini harus segera kami laporkan...",
  ui_story_1016_10161001_195_dialog_content = "Yingel! Anatoli! Tunggu!",
  ui_story_1016_10161001_196_dialog_content = "PlayerName? Bersama Letnan Vice dan tamu kita dari Lumopolis?",
  ui_story_1016_10161001_197_dialog_content = "Pertandingan akan segera dimulai, bukan? Mengapa Anda di sini dan tidak di kursi Anda?",
  ui_story_1016_10161001_198_dialog_content = "Kami melihat kalian berdua pergi terburu-buru sekarang. Sepertinya ada sesuatu yang mengganggumu.",
  ui_story_1016_10161001_199_dialog_content = "Jika Anda membutuhkan bantuan, saya akan dengan senang hati membantu.",
  ui_story_1016_10161001_200_dialog_content = "Menawarkan bantuan Anda? Itu tidak seperti kamu sama sekali, Leo. Selain itu, mengapa urusan kita harus menyangkut seorang ksatria dari Lumopolis?",
  ui_story_1016_10161001_201_dialog_content = "Jadi begitu. Jika Anda akan berbicara terus terang, maka saya mungkin juga melakukan hal yang sama.",
  ui_story_1016_10161001_202_dialog_content = "Saya menawarkan bantuan saya sekarang untuk mendapatkan dukungan Anda untuk Twilight di masa mendatang.",
  ui_story_1016_10161001_203_dialog_content = "Dan apa yang membuat Anda begitu yakin bahwa kami membutuhkan bantuan Anda?",
  ui_story_1016_10161001_204_dialog_content = "Belum lagi, saya hanya seorang Petugas Intelijen. Saya tidak mewakili Illumina, jadi saya tidak punya cara untuk menjanjikan dukungannya untuk tujuan Anda.",
  ui_story_1016_10161001_205_dialog_content = "Saya sangat menyadari itu, tapi saya tidak mencari semua dukungan Illumina. Saya hanya butuh dukungan Anda, serta dukungan sekutu Anda.",
  ui_story_1016_10161001_206_dialog_content = "Anda dan rekan Anda kuat, dan saat ini itulah yang dibutuhkan Twilight.",
  ui_story_1016_10161001_207_dialog_content = "Tidak hanya itu...",
  ui_story_1016_10161001_208_dialog_content = "Dengan pertandingan eksibisi terakhir Latihan Militer Gabungan berlangsung, semua orang menonton pertandingan atau menjaga perimeter.",
  ui_story_1016_10161001_209_dialog_content = "Itu memberitahu saya Anda sedikit bertangan pendek sekarang. Apakah aku salah?",
  ui_story_1016_10161001_210_dialog_content = "...",
  ui_story_1016_10161001_211_dialog_content = "Yingel, jika ada sesuatu yang salah, kita tidak akan hanya berdiam diri dan tidak melakukan apa-apa. Kita sekutu, bukan?",
  ui_story_1016_10161001_212_dialog_content = "Apalagi jika Forsakin terlibat...",
  ui_story_1016_10161001_213_dialog_content = "Forsakin?!",
  ui_story_1016_10161001_214_dialog_content = "Kamu...",
  ui_story_1016_10161001_215_dialog_content = "Maaf, saya tidak bermaksud untuk menguping saat kami berjalan ke sini...",
  ui_story_1016_10161001_216_dialog_content = "Kekuatanmu benar-benar sesuatu yang lain, Caelestite.",
  ui_story_1016_10161001_217_dialog_content = "aku benar-benar minta maaf...",
  ui_story_1016_10161001_218_dialog_content = "Bisakah Anda ceritakan tentang situasi saat ini, Yingel? Jika Forsakin terlibat, kami pasti tidak bisa mengabaikannya!",
  ui_story_1016_10161001_219_dialog_content = "Kami telah bertarung di sisi satu sama lain berkali-kali! Anda dapat mempercayai kami, saya berjanji!",
  ui_story_1016_10161001_220_dialog_content = "Benar sekali!",
  ui_story_1016_10161001_221_dialog_content = "...",
  ui_story_1016_10161001_222_dialog_content = "Firasatmu benar. Kami membutuhkan bantuan sekarang lebih dari sebelumnya.",
  ui_story_1016_10161001_223_dialog_content = "Pertahanan Kota Gannon telah sangat dikompromikan. Kami telah mengerahkan sebagian besar pasukan kami untuk menjaga sistem yang masih beroperasi sementara sisanya sedang diperiksa dan diperbaiki.",
  ui_story_1016_10161001_224_dialog_content = "Sayangnya, kami tidak memiliki cukup orang untuk melakukannya secara efektif. Jika Anda bersedia membantu, maka saya tidak akan menolak Anda.",
  ui_story_1016_10161001_225_dialog_content = "Tetapi jika Anda atau sekutu Anda menemukan tanda-tanda Forsakin atau Wraith lainnya, Anda harus segera memberi tahu kami.",
  ui_story_1016_10161001_226_dialog_content = "Forsakin... Atau Wraith lainnya?!",
  ui_story_1016_10161001_227_dialog_content = "Itu benar. Dan jika Anda berhasil menangkap mereka, Anda harus menyerahkannya ke dalam tahanan Illumina.",
  ui_story_1016_10161001_228_dialog_content = "Kota Anda, aturan Anda.",
  ui_story_1016_10161001_229_dialog_content = "Anda mengatakan pertahanan telah dikompromikan, bukan?",
  ui_story_1016_10161001_230_dialog_content = "Seberapa serius mereka rusak?",
  ui_story_1016_10161001_231_dialog_content = "Sulit untuk mengatakannya saat ini.",
  ui_story_1016_10161001_232_dialog_content = "Biasanya, tingkat kerusakan ini tidak perlu terlalu dikhawatirkan, tetapi mengingat waktu serta kehadiran Forsakin di Kota Gannon...",
  ui_story_1016_10161001_233_dialog_content = "Kita harus siap untuk apa pun. Kita tidak bisa membiarkan apa pun lolos.",
  ui_story_1016_10161001_234_dialog_content = "Jadi maksudmu pengkhianat Illumina ada di suatu tempat di kota sekarang, ya?",
  ui_story_1016_10161001_235_dialog_content = "(Jika memang begitu, aku cukup yakin Eclipsites yang kita temui sebelumnya berada di bawah komandonya.)",
  ui_story_1016_10161001_236_dialog_content = "Kami masih belum tahu keberadaannya, tapi kemungkinan besar dia masih di sini.",
  ui_story_1016_10161001_237_dialog_content = "Jika Anda bersikeras membantu kami, maka Anda harus tetap waspada setiap saat.",
  ui_story_1016_10161001_238_dialog_content = "Besar Anatoli, tetapkan mereka ke area yang membutuhkan dukungan.",
  ui_story_1016_10161001_239_dialog_content = "Segera.",
  ui_story_1016_10161001_240_dialog_content = "Letnan Vice, sebagai seseorang yang cukup mengenal Kota Gannon, Anda akan bertanggung jawab atas tim.",
  ui_story_1016_10161001_241_dialog_content = "Bukan masalah! Anda dapat mengandalkan saya!",
  ui_story_1016_10161001_242_dialog_content = "Tugas Anda adalah berpatroli di Sektor A hingga C, yang semuanya berada di dekat Stasiun Kereta Kota Gannon. Sesampai di sana, harap periksa status sistem pertahanan kami dan catat kerusakan apa pun.",
  ui_story_1016_10161001_243_dialog_content = "Melapor kepada Yingel atau saya sendiri setelah Anda menyelesaikan tugas Anda.",
  ui_story_1016_10161001_244_dialog_content = "Paham!",
  ui_story_1016_10161101_1_dialog_content = "Pertandingan terakhir akan segera dimulai. Apakah kamu siap?",
  ui_story_1016_10161101_2_dialog_content = "Tentu saja. Aku lebih dari siap, sebenarnya.",
  ui_story_1016_10161101_3_dialog_content = "Bagaimana denganmu? Apakah orang-orangmu menemukan sesuatu?",
  ui_story_1016_10161101_4_dialog_content = "Belum.",
  ui_story_1016_10161101_5_dialog_content = "Forsakin kemungkinan besar bersembunyi di sektor Kota Gannon yang belum berkembang. Tempat itu memiliki lorong-lorong yang berjalan ke segala arah, jadi butuh waktu bagi kita untuk mencarinya secara menyeluruh.",
  ui_story_1016_10161101_6_dialog_content = "Saya menghargai usahanya.",
  ui_story_1016_10161101_7_dialog_content = "Bukan apa-apa, sungguh.",
  ui_story_1016_10161101_8_dialog_content = "Saya akan memimpin pencarian sendiri, tetapi kemudian saya berpikir tentang Latihan Militer Gabungan dan menyadari bahwa saya harus tinggal di sini.",
  ui_story_1016_10161101_9_dialog_content = "Masuk akal. Siapa yang tahu masalah apa yang mungkin ditimbulkan oleh para gosip bodoh itu jika Kapten Pengawal Kerajaan tidak hadir untuk pertandingan final?",
  ui_story_1016_10161101_10_dialog_content = "Itu selalu kelompok idiot yang sama menghalangi.",
  ui_story_1016_10161101_11_dialog_content = "Tapi itu tidak masalah. Aku sudah menugaskan pengamanan ketat di sekeliling.",
  ui_story_1016_10161101_12_dialog_content = "Bahkan jika saya tidak di sini, Forsakin akan kesulitan untuk menghentikan pertandingan final.",
  ui_story_1016_10161101_13_dialog_content = "Terima kasih. Dengan bantuan Anda, kami dapat menyelesaikan Latihan Militer Gabungan tanpa masalah lebih lanjut.",
  ui_story_1016_10161101_14_dialog_content = "<color=#e8d9bb> Sementara itu, di laboratorium Algol</color>",
  ui_story_1016_10161101_15_dialog_content = "Di sana kita pergi! Penyesuaian akhir sekarang selesai.",
  ui_story_1016_10161101_16_dialog_content = "Tetap saja, anak kecil itu tampaknya terbang sedikit lebih lambat dari biasanya. Mungkin bagian-bagiannya mulai aus?",
  ui_story_1016_10161101_17_dialog_content = "Itu tidak akan banyak membantumu di luar sana, jadi mengapa tidak meninggalkannya bersamaku untuk saat ini? Saya akan menjalankannya seperti baru dalam waktu singkat!",
  ui_story_1016_10161101_18_dialog_content = "Tidak usah.",
  ui_story_1016_10161101_19_dialog_content = "Saya membutuhkan si kecil ini untuk membantu saya mengangkat lengan baju saya.",
  ui_story_1016_10161101_20_dialog_content = "Aku akan mengalami lebih banyak kesulitan bertarung tanpanya.",
  ui_story_1016_10161101_21_dialog_content = "Apakah begitu? Baiklah, lakukan dengan caramu.",
  ui_story_1016_10161101_22_dialog_content = "Saya hanya harus memperbaikinya setelah Anda menyelesaikan pertempuran Anda Reinhardt.",
  ui_story_1016_10161101_23_dialog_content = "Trio Kubik kini dalam kondisi prima bertarung. Gunakan mereka sepenuhnya, Axelia.",
  ui_story_1016_10161101_24_dialog_content = "Anda menciptakan mereka, Algol. Anda mengenal mereka lebih baik daripada orang lain.",
  ui_story_1016_10161101_25_dialog_content = "Aku percaya padamu, sama seperti aku percaya Cubes.",
  ui_story_1016_10161101_26_dialog_content = "Ha ha ha ha! Terima kasih sayang. Saya senang mendengarnya.",
  ui_story_1016_10161101_27_dialog_content = "Saya telah melihat Anda tumbuh hampir sepanjang hidup Anda, jadi wajar saja jika saya ingin menjaga Anda.",
  ui_story_1016_10161101_28_dialog_content = "Bagaimana perasaan mu saat ini?",
  ui_story_1016_10161101_29_dialog_content = "Tidak ada kelainan status. Berdiri untuk pertempuran.",
  ui_story_1016_10161101_30_dialog_content = "Itu bagus.",
  ui_story_1016_10161101_31_dialog_content = "Tapi jangan meremehkan Reinhardt hanya karena itu, Axelia.",
  ui_story_1016_10161101_32_dialog_content = "Meskipun modifikasi pertempuran Reinhard agak ketinggalan jaman, dia masih menjadi salah satu Aurorian terkuat di seluruh Illumina.",
  ui_story_1016_10161101_33_dialog_content = "Anda tahu keterbatasan Anda juga. Dalam situasi apa pun Anda tidak boleh memaksakan diri.",
  ui_story_1016_10161101_34_dialog_content = "Aku akan berjuang sampai akhir dan mendapatkan kemenangan.",
  ui_story_1016_10161101_35_dialog_content = "Tidak ada yang memberi tahu Anda apa yang harus dilakukan ketika Anda memikirkan sesuatu, bukan?",
  ui_story_1016_10161101_36_dialog_content = "Bahkan jika saya yang menyuruh Anda untuk tidak melakukannya, selalu ada kemungkinan Anda masih tidak mau mendengarkan.",
  ui_story_1016_10161101_37_dialog_content = "Saya akan mendengarkan Profesor Ulysses.",
  ui_story_1016_10161101_38_dialog_content = "Dan coba sesekali dengarkan saran orang lain, hmm?",
  ui_story_1016_10161101_39_dialog_content = "Tapi itu cukup kuliah untuk satu hari. Pergilah, sayangku.",
  ui_story_1016_10161101_40_dialog_content = "Langsung ke arena.",
  ui_story_1016_10161101_41_dialog_content = "Aku mengerti.",
  ui_story_1016_10161101_42_dialog_content = "Bagus. Semoga berhasil, Axelia.",
  ui_story_1016_10161101_43_dialog_content = "<color=#e8d9bb>Kembali ke arena</color>",
  ui_story_1016_10161101_44_dialog_content = "Sebagai juri hari ini, merupakan kehormatan besar bagi saya untuk mengumumkan dimulainya pertandingan final Latihan Militer Gabungan!",
  ui_story_1016_10161101_45_dialog_content = "<size=45>Woooooo!!!</size>",
  ui_story_1016_10161101_46_dialog_content = "Pertama, mari kita sambut Grand Marshal of Illumina, Illumination Enlightened yang tak terkalahkan—Reinhardt!",
  ui_story_1016_10161101_47_dialog_content = "<size=45>Reinhardt—! Reinhardt—!</size>",
  ui_story_1016_10161101_48_dialog_content = "Mari kita beri tepuk tangan meriah untuk semua peserta Latihan Militer Gabungan yang telah bekerja keras!",
  ui_story_1016_10161101_49_dialog_content = "Di mata dunia dan saya sendiri, Anda telah membuktikan tidak hanya kekuatan Anda tetapi juga kemampuan Anda untuk belajar dan meningkatkan diri!",
  ui_story_1016_10161101_50_dialog_content = "Saya tidak memiliki apa-apa selain rasa hormat tertinggi untuk Anda semua!",
  ui_story_1016_10161101_51_dialog_content = "<size=45>Woooooo!!!</size>",
  ui_story_1016_10161101_52_dialog_content = "Dan sekarang, mari sambut penantang hari ini, peserta yang melampaui rekan-rekannya dan mendapatkan hak istimewa untuk menghadapi Grand Marshal Reinhardt dalam pertempuran—",
  ui_story_1016_10161101_53_dialog_content = "Axelia, dari Federasi Illumina!",
  ui_story_1016_10161101_54_dialog_content = "Axelia—!",
  ui_story_1016_10161101_55_dialog_content = "...",
  ui_story_1016_10161101_56_dialog_content = "Axelia, ya? Belum pernah mendengar tentang dia... Dia pasti sangat kuat!",
  ui_story_1016_10161101_57_dialog_content = "Tidak bercanda. Bahkan kami orang-orang dari Illumina terkejut!",
  ui_story_1016_10161101_58_dialog_content = "Saya tidak tahu ada pembangkit tenaga listrik lain seperti dia!",
  ui_story_1016_10161101_59_dialog_content = "Para pejuang, tolong berjabat tangan.",
  ui_story_1016_10161101_60_dialog_content = "Axelia...",
  ui_story_1016_10161101_61_dialog_content = "Saya pernah mendengar tentang Anda. Kekuatan Anda adalah sesuatu yang harus dikagumi.",
  ui_story_1016_10161101_62_dialog_content = "Terima kasih atas pujian Anda.",
  ui_story_1016_10161101_63_dialog_content = "Apakah Anda bisa mendapatkan istirahat yang cukup sebelum pertandingan? Lagipula, Latihan Militer Gabungan baru saja berakhir kemarin.",
  ui_story_1016_10161101_64_dialog_content = "Saya tidak akan mudah pada Anda hanya karena Anda tidak sepenuhnya beristirahat.",
  ui_story_1016_10161101_65_dialog_content = "Aku merasa baik-baik saja, karena...",
  ui_story_1016_10161101_66_dialog_content = "Segala sesuatu yang telah saya lakukan adalah dalam persiapan untuk momen ini.",
  ui_story_1016_10161101_67_dialog_content = "…!",
  ui_story_1016_10161101_68_dialog_content = "Perintahku adalah menghadapimu dalam pertempuran.",
  ui_story_1016_10161101_69_dialog_content = "Saya akan menghabiskan setiap opsi yang memungkinkan untuk mengalahkan Anda.",
  ui_story_1016_10161101_70_dialog_content = "Apakah begitu? Saya menantikannya saat itu.",
  ui_story_1016_10161101_71_dialog_content = "Bersaing melawan anggota generasi muda yang kuat selalu mengasyikkan.",
  ui_story_1016_10161101_72_dialog_content = "...",
  ui_story_1016_10161101_73_dialog_content = "(Ada apa dengan gadis ini?)",
  ui_story_1016_10161101_74_dialog_content = "(Sesuatu tentang ekspresinya meresahkan. Itu tidak mirip dengan prajurit mana pun yang pernah saya lihat ...)",
  ui_story_1016_10161101_75_dialog_content = "(Tapi itu dari orang yang sekarat.)",
  ui_story_1016_10161101_76_dialog_content = "(Apakah aku benar-benar membuatnya takut seburuk itu?)",
  ui_story_1016_10161101_77_dialog_content = "(Atau apakah itu sesuatu yang lain ...?)",
  ui_story_1016_10161101_78_dialog_content = "Nah, jika kedua petarung mau mengambil tempat mereka, kita bisa memulai pertandingan!",
  ui_story_1016_10161101_79_dialog_content = "...",
  ui_story_1016_10161101_80_dialog_content = "Siap-",
  ui_story_1016_10161101_81_dialog_content = "<size=50><color=#FFB400>Awal</color>!</size>",
  ui_story_1016_10161101_82_dialog_content = "—!",
  ui_story_1016_10161101_83_dialog_content = "Kotak!",
  ui_story_1016_10161101_84_dialog_content = "<size=45>!!!</size>",
  ui_story_1016_10161101_85_dialog_content = "Serangan yang sangat kuat!",
  ui_story_1016_10161101_86_dialog_content = "Sepertinya aku harus keluar semua juga.",
  ui_story_1016_10161101_87_dialog_content = "<color=#e8d9bb>Duarr!!!</color>",
  ui_story_1016_10161101_88_dialog_content = "<size=45>Ya!!!</size>",
  ui_story_1016_10161101_89_dialog_content = "Reinhardt—! Reinhardt—!",
  ui_story_1016_10161101_90_dialog_content = "Serangan awal berhasil. Penilaian kerusakan: target belum menerima kerusakan yang terlihat.",
  ui_story_1016_10161101_91_dialog_content = "Kekuatan musuh sedikit lebih tinggi dari yang diharapkan, tapi masih dalam parameter yang bisa diatur.",
  ui_story_1016_10161101_92_dialog_content = "Meningkatkan keluaran Lumina.",
  ui_story_1016_10161101_93_dialog_content = "Tiga-",
  ui_story_1016_10161101_94_dialog_content = "(Dia mengisi serangan ?!)",
  ui_story_1016_10161101_95_dialog_content = "(Saya harus menghentikannya!)",
  ui_story_1016_10161101_96_dialog_content = "Dua-",
  ui_story_1016_10161101_97_dialog_content = "<size=45>Menembus semua!</size>",
  ui_story_1016_10161101_98_dialog_content = "—!",
  ui_story_1016_10161101_99_dialog_content = "Minggir!",
  ui_story_1016_10161101_100_dialog_content = "Satu!",
  ui_story_1016_10161101_101_dialog_content = "(Terlambat, ya?)",
  ui_story_1016_10161101_103_dialog_content = "Pergilah, tombakku!",
  ui_story_1016_10161101_104_dialog_content = "Maaf atas keterlambatannya.",
  ui_story_1016_10161101_105_dialog_content = "<color=#e8d9bb>Ledakan-!!!</color>",
  ui_story_1016_10161101_106_dialog_content = "<size=45>Woooooo!!!</size>",
  ui_story_1016_10161101_107_dialog_content = "Uhuk uhuk...!",
  ui_story_1016_10161101_108_dialog_content = "Astaga... Itu lebih menyakitkan dari yang kukira.",
  ui_story_1016_10161101_109_dialog_content = "Kamu benar-benar luar biasa, nak.",
  ui_story_1016_10161101_110_dialog_content = "Serangan kedua berhasil.",
  ui_story_1016_10161101_111_dialog_content = "Penilaian kerusakan: minimal. Target berhasil meniadakan sebagian besar serangan dengan Luminatics miliknya sendiri.",
  ui_story_1016_10161101_112_dialog_content = "Meningkatkan output Lumina lebih jauh lagi.",
  ui_story_1016_10161101_113_dialog_content = "(Dia masih bisa meningkatkan hasilnya ?!)",
  ui_story_1016_10161101_114_dialog_content = "(Ledakan Lumina sekuat itu akan jauh di luar batasku. Aku akan mendapat masalah jika dia mendaratkan serangan langsung...)",
  ui_story_1016_10161101_115_dialog_content = "Tiga-",
  ui_story_1016_10161101_116_dialog_content = "<color=#e8d9bb>Retakan-</color>",
  ui_story_1016_10161101_117_dialog_content = "<size=45>!</size>",
  ui_story_1016_10161101_118_dialog_content = "(Tunggu, apakah itu <color=#FFB400>retak</color> muncul di tubuhnya?)",
  ui_story_1016_10161101_119_dialog_content = "(Apakah tubuhnya mulai rusak?! Apakah kekuatan kolosal miliknya datang dengan harga setinggi itu?!)",
  ui_story_1016_10161101_120_dialog_content = "(Saya tidak tahu Komite telah membuat meriam kaca seperti itu...)",
  ui_story_1016_10161101_121_dialog_content = "Berhenti, Axelia!",
  ui_story_1016_10161101_122_dialog_content = "Tubuhmu tidak bisa menahan ketegangan serangan seperti itu!!!",
  ui_story_1016_10161101_123_dialog_content = "Argh…",
  ui_story_1016_10161101_124_dialog_content = "Dua...",
  ui_story_1016_10161101_125_dialog_content = "Tidak mendengarkan, ya? Kurasa aku tidak punya pilihan...",
  ui_story_1016_10161101_126_dialog_content = "Hakim! Anda harus menghentikan pertandingan sekarang!",
  ui_story_1016_10161101_127_dialog_content = "Nyawa Axelia akan berada dalam bahaya kalau terus begini!",
  ui_story_1016_10161101_128_dialog_content = "Apa yang dibicarakan oleh Grand Marshal Anda?",
  ui_story_1016_10161101_129_dialog_content = "Tidak ada ide. aku tidak bisa mendengarnya...",
  ui_story_1016_10161101_130_dialog_content = "Kesunyian! Lanjutkan pertandingan!",
  ui_story_1016_10161101_131_dialog_content = "(Juri dan penonton tidak bisa mendengarku! Tunggu...)",
  ui_story_1016_10161101_132_dialog_content = "(Saya bisa merasakan pingsan <color=#FFB400>Penghalang aliran gelap</color> antara arena dan tribun! Kapan ini muncul?!)",
  ui_story_1016_10161101_133_dialog_content = "(Mungkinkah itu alasan mereka tidak bisa mendengarku? Aku harus memecahkannya untuk mencari tahu!)",
  ui_story_1016_10161101_134_dialog_content = "<size=45>!!!</size>",
  ui_story_1016_10161101_135_dialog_content = "(Dia memotong gerakanku?!)",
  ui_story_1016_10161101_136_dialog_content = "Sasaran... Terkunci...",
  ui_story_1016_10161101_137_dialog_content = "Satu!",
  ui_story_1016_10161101_138_dialog_content = "<size=45>Maaf atas keterlambatannya!</size>",
  ui_story_1016_10161101_139_dialog_content = "…!",
  ui_story_1016_10161101_140_dialog_content = "<color=#e8d9bb>Ledakan-!!!</color>",
  ui_story_1016_10161101_141_dialog_content = "<color=#e8d9bb>Sementara itu, di Kota Gannon</color>",
  ui_story_1016_10161101_142_dialog_content = "Aku memeriksa bagian dalam stasiun. Tidak ada masalah di sana.",
  ui_story_1016_10161101_143_dialog_content = "Tidak ada di daerah sekitarnya juga.",
  ui_story_1016_10161101_144_dialog_content = "Sama di ujung saya.",
  ui_story_1016_10161101_145_dialog_content = "PlayerName! Saya menemukan sesuatu di sini!",
  ui_story_1016_10161101_146_dialog_content = "Semua alutsista di terowongan perawatan ini telah dihancurkan. Ada tanda-tanda aktivitas Eclipsite di sini juga!",
  ui_story_1016_10161101_147_dialog_content = "Saya sedang dalam perjalanan!",
  ui_story_1016_10161101_148_dialog_content = "<anim type=Shake><size=50>Grahhh—!</size></anim>",
  ui_story_1016_10161101_149_dialog_content = "Jadi ada Eclipsites di sini!",
  ui_story_1016_10161101_150_dialog_content = "Jangan biarkan salah satu dari mereka melarikan diri!",
  ui_story_1016_10161102_1_dialog_content = "Mereka pasti sudah mencapai Kota Gannon sekarang.",
  ui_story_1016_10161102_2_dialog_content = "Tapi kita belum bisa pergi. Ini masih bukan waktu yang tepat.",
  ui_story_1016_10161102_3_dialog_content = "Mengapa kita bersembunyi...?",
  ui_story_1016_10161102_4_dialog_content = "Kenapa kau tidak... mempercayai mereka...",
  ui_story_1016_10161102_5_dialog_content = "Percaya mereka?",
  ui_story_1016_10161102_6_dialog_content = "Bagaimana jika saya memberi tahu Anda bahwa Kota Gannon sudah dipenuhi dengan Eclipsites?",
  ui_story_1016_10161102_7_dialog_content = "Atau bahwa orang-orang yang memerintah kota ini telah memilih untuk berpihak pada Eclipsites juga?",
  ui_story_1016_10161102_8_dialog_content = "Jika saya memberi tahu Anda semua itu, apakah Anda masih mempercayai mereka?",
  ui_story_1016_10161102_9_dialog_content = "...",
  ui_story_1016_10161102_10_dialog_content = "Saat ini, satu-satunya yang bisa kau percayai adalah aku.",
  ui_story_1016_10161102_11_dialog_content = "Aku satu-satunya yang bisa menyelamatkanmu, dan mengeluarkanmu dari tempat ini.",
  ui_story_1016_10161102_12_dialog_content = "...",
  ui_story_1016_10161102_13_dialog_content = "(Eclipsian) Nyonya Forsakin.",
  ui_story_1016_10161102_14_dialog_content = "(Eclipsian) Bicaralah.",
  ui_story_1016_10161102_15_dialog_content = "(Eclipsian) Saya membawa pesan lain dari Lord Figerald.",
  ui_story_1016_10161102_16_dialog_content = "(Eclipsian) \"Semuanya ada di tempat sekarang. Anda boleh mundur.\"",
  ui_story_1016_10161102_17_dialog_content = "(Eclipsian) Sudah waktunya. Buat lebih cepat lain kali, bodoh.",
  ui_story_1016_10161102_18_dialog_content = "(Eclipsian) Maafkan saya.",
  ui_story_1016_10161102_19_dialog_content = "(Eclipsian) Kami telah mengidentifikasi rute pelarian tersembunyi.",
  ui_story_1016_10161102_20_dialog_content = "(Eclipsian) Anda dapat menggunakannya untuk melarikan diri dari Kota Gannon, jika Anda mau.",
  ui_story_1016_10161102_21_dialog_content = "(Eclipsian) Dimana?",
  ui_story_1016_10161102_22_dialog_content = "(Eclipsian) Di sini.",
  ui_story_1016_10161102_23_dialog_content = "Begitu ya... Lokasi yang sangat jauh untuk rute pelarian.",
  ui_story_1016_10161102_24_dialog_content = "Ayo pergi, spesimen.",
  ui_story_1016_10161201_1_dialog_content = "<color=#e8d9bb>Ledakan-!!!</color>",
  ui_story_1016_10161201_2_dialog_content = "<size=45>Batuk, batuk, batuk!!!</size>",
  ui_story_1016_10161201_3_dialog_content = "Argh…",
  ui_story_1016_10161201_4_dialog_content = "Serangan ketiga... Batuk, batuk... Berhasil.",
  ui_story_1016_10161201_5_dialog_content = "Penilaian kerusakan... Target mengalami cedera yang terlihat.",
  ui_story_1016_10161201_6_dialog_content = "Melanjutkan ofensif.",
  ui_story_1016_10161201_7_dialog_content = "(Tapi level Lumina saya terlalu rendah...)",
  ui_story_1016_10161201_8_dialog_content = "(Saya perlu waktu untuk mengumpulkan kekuatan saya jika saya ingin terus menyerang.)",
  ui_story_1016_10161201_9_dialog_content = "(Dia akan mati jika ini terus berlanjut...)",
  ui_story_1016_10161201_10_dialog_content = "(Kenapa? Kenapa dia rela mempertaruhkan nyawanya hanya untuk mengalahkanku?)",
  ui_story_1016_10161201_11_dialog_content = "(Mungkinkah dia melakukan ini di bawah perintah Ulysses? Apakah Komite menyuruhnya melakukan ini?!)",
  ui_story_1016_10161201_12_dialog_content = "Kotak!",
  ui_story_1016_10161201_13_dialog_content = "—!",
  ui_story_1016_10161201_14_dialog_content = "(Pola serangannya telah berubah. Lumina-nya tidak terlihat sekuat sebelumnya.)",
  ui_story_1016_10161201_15_dialog_content = "(Sepertinya dia mencoba mengumpulkan kekuatan untuk serangan selanjutnya.)",
  ui_story_1016_10161201_16_dialog_content = "(Ini bisa menjadi kesempatan saya.)",
  ui_story_1016_10161201_17_dialog_content = "Axelia, mengapa kamu begitu bertekad untuk mengalahkanku?",
  ui_story_1016_10161201_18_dialog_content = "Karena aku mampu melakukannya. Itu sebabnya saya harus menang.",
  ui_story_1016_10161201_19_dialog_content = "Anda tidak benar-benar menjawab pertanyaan saya.",
  ui_story_1016_10161201_20_dialog_content = "Apa Ulysses menyuruhmu melakukan ini?",
  ui_story_1016_10161201_21_dialog_content = "...",
  ui_story_1016_10161201_22_dialog_content = "(Dia tidak menyangkalnya. Sepertinya ini yang dilakukan Komite.)",
  ui_story_1016_10161201_23_dialog_content = "(Apakah mereka benar-benar ingin menguatkan suara mereka dengan mengalahkanku?)",
  ui_story_1016_10161201_24_dialog_content = "(Jika dia benar-benar mengikuti perintah mereka, seorang gadis seperti dia akan membuang nyawanya untuk menjalankan misinya tanpa ragu.)",
  ui_story_1016_10161201_25_dialog_content = "(Namun saat ini, hal terakhir yang dibutuhkan Komite adalah lebih banyak otoritas.)",
  ui_story_1016_10161201_26_dialog_content = "(Jika aku ingin menyelamatkan anak ini, aku harus menaklukkannya dan memaksanya untuk menyerah.)",
  ui_story_1016_10161201_27_dialog_content = "Ini belum selesai-",
  ui_story_1016_10161201_28_dialog_content = "<size=45>Pembukaan!</size>",
  ui_story_1016_10161201_29_dialog_content = "<color=#e8d9bb>*klang!*</color>",
  ui_story_1016_10161201_30_dialog_content = "Kamu kalah.",
  ui_story_1016_10161201_31_dialog_content = "<size=50>Woooooo—!!!</size>",
  ui_story_1016_10161201_32_dialog_content = "Grand Marshal berhasil mengalahkannya!",
  ui_story_1016_10161201_33_dialog_content = "Apakah ini berarti dia menang?",
  ui_story_1016_10161201_34_dialog_content = "...",
  ui_story_1016_10161201_35_dialog_content = "Menyerah.",
  ui_story_1016_10161201_36_dialog_content = "Saya memahami tekad Anda dengan sangat baik, tetapi kita semua memiliki alasan untuk tidak ingin kalah.",
  ui_story_1016_10161201_37_dialog_content = "Aku tidak ingin menyakitimu, dan aku pasti tidak ingin melihatmu menyakiti dirimu sendiri seperti ini.",
  ui_story_1016_10161201_38_dialog_content = "Anda tidak hanya lebih muda dari saya, Axelia, Anda juga memiliki potensi yang jauh lebih besar daripada saya. Masa depan Federasi Illumina semakin penuh harapan karena Anda.",
  ui_story_1016_10161201_39_dialog_content = "Jadi tolong, jangan membuang semuanya hanya untuk ini.",
  ui_story_1016_10161201_40_dialog_content = "<anim type=Shake>SAYA...</anim>",
  ui_story_1016_10161201_41_dialog_content = "<anim type=Shake><size=45>Aku... belum kalah!</size></anim>",
  ui_story_1016_10161201_42_dialog_content = "?!",
  ui_story_1016_10161201_43_dialog_content = "Kotak!",
  ui_story_1016_10161201_44_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_1016_10161201_45_dialog_content = "Argh... Batuk, batuk!!!",
  ui_story_1016_10161201_46_dialog_content = "(Robot kecil yang tampak lemah itu membawa bahan peledak berdampak tinggi selama ini ?!)",
  ui_story_1016_10161201_47_dialog_content = "(Menggunakan jurus nekat seperti itu, hanya untuk menjauhkanku... Sepertinya dia menerima lebih banyak kerusakan daripada aku.)",
  ui_story_1016_10161201_48_dialog_content = "<anim type=Shake>Itu menyakitkan...</anim>",
  ui_story_1016_10161201_49_dialog_content = "<anim type=Shake>Tapi aku masih bisa melawan...</anim>",
  ui_story_1016_10161201_50_dialog_content = "<anim type=Shake>aku tidak akan pernah menyerah...</anim>",
  ui_story_1016_10161201_51_dialog_content = "(Dia sudah mengambil keputusan, bukan? Itu berarti hanya ada dua hasil yang mungkin untuk pertandingan ini...)",
  ui_story_1016_10161201_52_dialog_content = "(Jika saya menang, dia mati.)",
  ui_story_1016_10161201_53_dialog_content = "(Dan jika aku menyerah sebelum dia mencoba membakarku, dewan akan mengambil jalan mereka... Tapi setidaknya dia akan tetap hidup.)",
  ui_story_1016_10161201_54_dialog_content = "<anim type=Shake>Aku akan... melaksanakan perintahku dan... mengalahkanmu...</anim>",
  ui_story_1016_10161201_55_dialog_content = "<color=#e8d9bb>Retakan-</color>",
  ui_story_1016_10161201_56_dialog_content = "<anim type=Shake>Aku... aku masih bisa...</anim>",
  ui_story_1016_10161201_57_dialog_content = "...",
  ui_story_1016_10161201_58_dialog_content = "Apa yang sedang terjadi? Mengapa tidak Reinhardt melawan balik?",
  ui_story_1016_10161201_59_dialog_content = "Biarkan dia memilikinya, Grand Marshal!",
  ui_story_1016_10161201_60_dialog_content = "Kamu benar! Apa yang merasukinya?",
  ui_story_1016_10161201_61_dialog_content = "Sepertinya waktunya telah tiba.",
  ui_story_1016_10161201_62_dialog_content = "<color=#e8d9bb>Bzzzt—</color>",
  ui_story_1016_10161201_63_dialog_content = "Mulailah fase operasi selanjutnya.",
  ui_story_1016_10161201_64_dialog_content = "Dan Anda yakin Anda memiliki segalanya di bawah kendali?",
  ui_story_1016_10161201_65_dialog_content = "Ya.",
  ui_story_1016_10161201_66_dialog_content = "Dia tidak memiliki cara untuk menang sekarang.",
  ui_story_1016_10161201_67_dialog_content = "<color=#e8d9bb>Sementara itu, jauh di dalam Kota Gannon</color>",
  ui_story_1016_10161201_68_dialog_content = "Terkesiap... Terkesiap...",
  ui_story_1016_10161201_69_dialog_content = "Kemana... Kemana perginya Eclipsites?!",
  ui_story_1016_10161201_70_dialog_content = "Mereka melihat kami dan berlari seperti angin.",
  ui_story_1016_10161201_71_dialog_content = "Di mana tepatnya kita?",
  ui_story_1016_10161201_72_dialog_content = "Saya belum pernah ke sini sebelumnya. Apakah Anda tahu di mana kita berada, Vice?",
  ui_story_1016_10161201_73_dialog_content = "Aku juga tidak tahu...",
  ui_story_1016_10161201_74_dialog_content = "Tapi dari apa yang bisa saya katakan, kita seharusnya berada cukup dekat dengan level bawah Kota Gannon.",
  ui_story_1016_10161201_75_dialog_content = "Letnan Vice? PlayerName? Apa yang kamu lakukan di sini?",
  ui_story_1016_10161201_76_dialog_content = "Hah?",
  ui_story_1016_10161201_77_dialog_content = "Bukankah kau seharusnya memeriksa stasiun kereta?",
  ui_story_1016_10161201_78_dialog_content = "C-Kolonel Yingel?!",
  ui_story_1016_10161201_79_dialog_content = "Kami juga tidak berharap melihat kalian berdua di sini.",
  ui_story_1016_10161201_80_dialog_content = "Selama inspeksi kami di stasiun kereta, kami menemukan sekelompok Eclipsites bersembunyi di dalam salah satu terowongan pemeliharaan.",
  ui_story_1016_10161201_81_dialog_content = "Itu benar, tapi mereka kabur begitu melihat kita. Kami mengikuti mereka sampai ke sini, tapi masih belum ada tanda-tanda keberadaan mereka.",
  ui_story_1016_10161201_82_dialog_content = "Bagaimana denganmu? Saya pikir kalian berdua keluar berpatroli di kota?",
  ui_story_1016_10161201_83_dialog_content = "Bagaimana Anda berakhir di sini juga?",
  ui_story_1016_10161201_84_dialog_content = "Kami mengalami situasi yang sama seperti Anda.",
  ui_story_1016_10161201_85_dialog_content = "Eclipsites itu bertingkah aneh, seolah-olah mereka tidak berniat bertarung sama sekali ...",
  ui_story_1016_10161201_86_dialog_content = "Itu pasti bagian dari rencana mereka. Kita harus lebih waspada.",
  ui_story_1016_10161201_87_dialog_content = "Saya setuju bahwa mereka pasti merencanakan sesuatu juga.",
  ui_story_1016_10161201_88_dialog_content = "Jadi haruskah kita menyerah mengejar mereka untuk saat ini?",
  ui_story_1016_10161201_89_dialog_content = "Tidak akan pernah!",
  ui_story_1016_10161201_90_dialog_content = "Membiarkan mereka mengamuk di Kota Gannon hanya akan menciptakan masalah yang lebih besar.",
  ui_story_1016_10161201_91_dialog_content = "Kami berada di bagian terdalam kota, tempat kami menyimpan peralatan teknologi penting dalam jumlah besar. Jika salah satu dari perangkat itu dihancurkan oleh Eclipsite, itu akan menjadi bencana besar bagi Federasi Illumina.",
  ui_story_1016_10161201_92_dialog_content = "Kita perlu menangkap mereka dan menghentikan rencana mereka sebelum membuahkan hasil!",
  ui_story_1016_10161201_93_dialog_content = "Dapatkah Anda merasakan ke arah mana Eclipsites pergi, PlayerName?",
  ui_story_1016_10161201_94_dialog_content = "Saya bisa mencoba, tetapi tata letak yang rumit dari tempat ini sangat menghambat kemampuan psikis saya. Saya hanya bisa merasakan arah umum mereka, paling banyak.",
  ui_story_1016_10161201_95_dialog_content = "Saya tidak punya cara untuk mengatakan dengan tepat di mana mereka berada sekarang.",
  ui_story_1016_10161201_96_dialog_content = "Jangan khawatir tentang itu. Arahkan saja saya ke arah yang benar, dan saya akan menemukan jalan ke depan.",
  ui_story_1016_10161201_97_dialog_content = "Baiklah, ini dia.",
  ui_story_1016_10161201_98_option_content = "Force Boost!",
  ui_story_1016_10161201_99_dialog_content = "Darkflow berkumpul di bawah kita di suatu tempat...",
  ui_story_1016_10161201_100_dialog_content = "Tunggu, apakah itu...?",
  ui_story_1016_10161201_101_dialog_content = "<size=45>!!!</size>",
  ui_story_1016_10161201_102_dialog_content = "Dia <color=#FFB400>Figerald!</color>!!!",
  ui_story_1016_10161201_103_dialog_content = "Apakah Anda berbicara tentang itu <color=#FFB400>Hantu</color>?! Dimana dia?!",
  ui_story_1016_10161201_104_dialog_content = "Tepat di bawah kami! Itu juga sangat dekat!",
  ui_story_1016_10161201_105_dialog_content = "Di bawah kita, ya...?",
  ui_story_1016_10161201_106_dialog_content = "(Kita sudah dekat dengan bagian terdalam Kota Gannon. Satu-satunya yang ada di bawah kita adalah <color=#FFB400>Wali Satu</color> bingkai utama.)",
  ui_story_1016_10161201_107_dialog_content = "(Apakah Eclipse mengejar Guardian One ?!)",
  ui_story_1016_10161201_108_dialog_content = "Kita harus cepat! Ikuti aku!",
  ui_story_1016_10161201_109_dialog_content = "Orang-orang yang membangun Undercity terkutuk ini pasti punya otak cacing.",
  ui_story_1016_10161201_110_dialog_content = "Kenapa lagi mereka membuatnya begitu sulit dinavigasi ?!",
  ui_story_1016_10161201_111_dialog_content = "Tahan di sana, Wraith!",
  ui_story_1016_10161201_112_dialog_content = "Tidak ada tempat bagimu untuk lari! Serahkan dirimu, dan datanglah dengan damai!",
  ui_story_1016_10161201_113_dialog_content = "Apa? Tapi bagaimana ini bisa terjadi?!",
  ui_story_1016_10161201_114_dialog_content = "Mereka seharusnya sudah berurusan dengan setiap Aurorian yang usil sekarang...",
  ui_story_1016_10161201_114X1_dialog_content = "Hah? Dimana <color=#FFB400>dia</color>? Apakah dia sudah pergi <color=#FFB400>di sana</color>?",
  ui_story_1016_10161201_115_dialog_content = "Sialan mereka semua! Apa tidak ada orang yang bisa kuandalkan?!",
  ui_story_1016_10161201_116_dialog_content = "Hentikan mereka, dasar bajingan! Aku memerintahkanmu!",
  ui_story_1016_10161201_117_dialog_content = "<anim type=Shake><size=45>Keren!!!</size></anim>",
  ui_story_1016_10161201_118_dialog_content = "Bersiaplah, semuanya!!!",
  ui_story_1016_10161301_1_dialog_content = "Untuk waktu yang lama, saya selalu memiliki pertanyaan yang sama di pikiran saya—",
  ui_story_1016_10161301_2_dialog_content = "Apa hal terpenting bagi Federasi Illumina?",
  ui_story_1016_10161301_3_dialog_content = "Persenjataan yang kuat dan canggih?",
  ui_story_1016_10161301_4_dialog_content = "Tentara yang sangat terlatih?",
  ui_story_1016_10161301_5_dialog_content = "Teknologi mutakhir?",
  ui_story_1016_10161301_6_dialog_content = "Aku memikirkannya begitu lama, namun aku tidak pernah bisa menemukan jawaban.",
  ui_story_1016_10161301_7_dialog_content = "Tapi kemudian saya menginjakkan kaki di medan perang.",
  ui_story_1016_10161301_8_dialog_content = "Di sana, saya melihat semuanya ...",
  ui_story_1016_10161301_9_dialog_content = "Kegigihan.",
  ui_story_1016_10161301_10_dialog_content = "Tugas.",
  ui_story_1016_10161301_11_dialog_content = "Pengorbanan.",
  ui_story_1016_10161301_12_dialog_content = "Pada saat itu, saya akhirnya menyadari apa yang paling penting bagi Federasi Illumina—",
  ui_story_1016_10161301_13_dialog_content = "Dia <color=#FFB400>rakyat</color>.",
  ui_story_1016_10161301_14_dialog_content = "Di permukaan, Illumina tidak memiliki penghalang alami atau teknologi kuno untuk menangkis Eclipsites.",
  ui_story_1016_10161301_15_dialog_content = "Darah, keringat, dan air mata dari generasi rakyat kita yang tak terhitung jumlahnya adalah yang membangun Undercities.",
  ui_story_1016_10161301_16_dialog_content = "Ketika satu generasi berlalu, generasi berikutnya dengan teguh menghadapi tantangan. Begitulah selama bertahun-tahun.",
  ui_story_1016_10161301_17_dialog_content = "Hidup adalah hal yang sangat berharga, namun demi rekan-rekan mereka, serta generasi masa depan mereka—",
  ui_story_1016_10161301_18_dialog_content = "Mereka mengorbankan diri tanpa ragu-ragu.",
  ui_story_1016_10161301_19_dialog_content = "Tapi tidak ada kehidupan yang harus dikorbankan untuk sesuatu yang sepele seperti perselisihan internal.",
  ui_story_1016_10161301_20_dialog_content = "Jika dibiarkan, tragedi tak berarti semacam ini pasti akan terulang kembali.",
  ui_story_1016_10161301_21_dialog_content = "Bahkan jika saya kalah Axelia sekarang, para pengecut itu hanya akan terus melemparkan lebih banyak orang seperti dia ke tombakku...",
  ui_story_1016_10161301_22_dialog_content = "Satu-satunya alasan mereka ingin aku kalah Axelia tidak lebih dari menanggalkan gelarku sebagai Marsekal Agung.",
  ui_story_1016_10161301_23_dialog_content = "Tidak bisa mengatakan gelar itu tidak penting, tetapi tidak terlalu penting sehingga layak untuk mengorbankan nyawa orang-orang saya.",
  ui_story_1016_10161301_24_dialog_content = "Bagaimanapun, menyelamatkan gadis malang ini harus didahulukan.",
  ui_story_1016_10161301_25_dialog_content = "Itulah sebabnya...",
  ui_story_1016_10161301_26_dialog_content = "<size=45>Berhenti-!</size>",
  ui_story_1016_10161301_27_dialog_content = "<anim type=Shake>Aku tidak akan pernah berhenti...</anim>",
  ui_story_1016_10161301_28_dialog_content = "<color=#e8d9bb>*klang!*</color>",
  ui_story_1016_10161301_29_dialog_content = "Berhenti, Axelia. <color=#FFB400>saya menyerah</color>.",
  ui_story_1016_10161301_30_dialog_content = "Jika orang-orang di belakang Anda sangat ingin Anda menang, biarkan mereka mendapatkan apa yang mereka inginkan.",
  ui_story_1016_10161301_31_dialog_content = "Aku hanya ingin kamu hidup, dan hidup dengan baik.",
  ui_story_1016_10161301_32_dialog_content = "Bukan sebagai meriam kaca mereka, atau aset berharga, tetapi sebagai a <color=#FFB400>orang</color>.",
  ui_story_1016_10161301_33_dialog_content = "…!",
  ui_story_1016_10161301_34_dialog_content = "Apa yang dia katakan barusan?",
  ui_story_1016_10161301_35_dialog_content = "Tidak ada ide. Aku masih tidak bisa mendengar mereka.",
  ui_story_1016_10161301_36_dialog_content = "Mengapa Grand Marshal menjatuhkan senjatanya? Apakah dia akan menggunakan semacam gerakan khusus?",
  ui_story_1016_10161301_37_dialog_content = "Anda baru saja mendengar saya, bukankah Anda menghakimi?",
  ui_story_1016_10161301_38_dialog_content = "Apa... Apa itu, Marsekal Agung?",
  ui_story_1016_10161301_39_dialog_content = "Jadi akhirnya kau bisa mendengarku, eh? Astaga, kebetulan sekali.",
  ui_story_1016_10161301_40_dialog_content = "Saya bilang saya menyerah. Axelia menang.",
  ui_story_1016_10161301_41_dialog_content = "...",
  ui_story_1016_10161301_42_dialog_content = "T-Tapi itu...",
  ui_story_1016_10161301_43_dialog_content = "Berhenti mengulur waktu, dan umumkan saja pemenangnya.",
  ui_story_1016_10161301_44_dialog_content = "Tidak sopan membiarkan seorang gadis kecil menunggu.",
  ui_story_1016_10161301_45_dialog_content = "U-Dimengerti... Pertandingan sudah berakhir!",
  ui_story_1016_10161301_46_dialog_content = "Marsekal Agung Reinhardt telah menyerah secara sukarela! Pemenang pertandingan eksibisi adalah—<color=#FFB400>Axelia</color>!",
  ui_story_1016_10161301_47_dialog_content = "<color=#e8d9bb>Sementara itu, jauh di dalam Kota Gannon</color>",
  ui_story_1016_10161301_48_dialog_content = "Dan setelah semua kesulitan untuk sampai ke sini, hama-hama itu tetap mengikutiku.",
  ui_story_1016_10161301_48X1_dialog_content = "Apakah dia sudah masuk ke dalam? Lalu sesuai rencana...",
  ui_story_1016_10161301_49_dialog_content = "Kau tidak akan bisa kabur!",
  ui_story_1016_10161301_50_dialog_content = "<color=#e8d9bb>Dor, dor, dor!</color>",
  ui_story_1016_10161301_51_dialog_content = "Cih! Gadis kecil yang gigih, bukan?!",
  ui_story_1016_10161301_52_dialog_content = "Jadi itu berhasil sampai di sini, setelah semua ...",
  ui_story_1016_10161301_53_dialog_content = "Huff...huff... Akhirnya ketahuan juga.",
  ui_story_1016_10161301_53X1_dialog_content = "Caelestite, kita bertemu lagi.",
  ui_story_1016_10161301_53X2_dialog_content = "Anda benar-benar menyelamatkan hari di Obelisk of Return... Baru-baru ini, saya tidak bisa menghentikan suasana hati yang buruk yang selalu saya alami.",
  ui_story_1016_10161301_53X3_dialog_content = "Apa yang kamu rencanakan?!",
  ui_story_1016_10161301_53X4_dialog_content = "Aku tidak akan membiarkanmu melarikan diri kali ini!",
  ui_story_1016_10161301_53X5_dialog_content = "Ini adalah akhir dari baris untuk Anda! Tidak ada jalan keluar!",
  ui_story_1016_10161301_53X6_dialog_content = "Ck, ck, ck... Jangan terlalu bersemangat.",
  ui_story_1016_10161301_54_dialog_content = "Jika saya tidak salah, ini pasti level terendah Kota Gannon, bukan?",
  ui_story_1016_10161301_55_dialog_content = "Lemari besi ini terlihat sangat dibentengi. Sesuatu yang sangat penting pasti ada di dalam.",
  ui_story_1016_10161301_56_dialog_content = "Mainframe untuk Guardian One terletak tepat di luar pintu itu! Kita tidak bisa membiarkan Eclipse mengambilnya!",
  ui_story_1016_10161301_57_dialog_content = "Apa?! Tapi saya pikir Guardian One bahkan lebih pendek dari saya!",
  ui_story_1016_10161301_58_dialog_content = "Droid itu hanyalah salah satu dari banyak terminal antarmuka Guardian One.",
  ui_story_1016_10161301_59_dialog_content = "Tubuh aslinya, bisa dikatakan, ada di sini.",
  ui_story_1016_10161301_60_dialog_content = "Dari apa yang saya dengar, sebagian besar sistem pertahanan Illumina secara otomatis dikendalikan oleh Guardian One.",
  ui_story_1016_10161301_61_dialog_content = "Jika sesuatu terjadi pada Guardian One, seluruh Illumina akan berada dalam bahaya!",
  ui_story_1016_10161301_62_dialog_content = "<size=45>Ck, ck, ck!</size>",
  ui_story_1016_10161301_63_dialog_content = "Anda benar sekali, teman berambut putih saya.",
  ui_story_1016_10161301_64_dialog_content = "Tapi ini sudah terlambat. Pasukan kita telah berhasil masuk.",
  ui_story_1016_10161301_65_dialog_content = "Apa?!",
  ui_story_1016_10161301_66_dialog_content = "Bagaimana mungkin? Tanpa kunci—",
  ui_story_1016_10161301_67_dialog_content = "Saya akan membiarkan Anda mengetahuinya sendiri.",
  ui_story_1016_10161301_68_dialog_content = "Sedikit lagi, sedikit lagi, dan kemudian Eclipse tidak akan...",
  ui_story_1016_10161301_69_dialog_content = "Dapatkan mereka, antek-antekku! Jangan biarkan mereka mengganggu!",
  ui_story_1016_10161301_70_dialog_content = "Astaga!!!",
  ui_story_1016_10161301_71_dialog_content = "Tetap bersama, semuanya! Kita tidak bisa membiarkan dia lolos dengan ini!",
  ui_story_1016_10161302_1_dialog_content = "<color=#e8d9bb>Di sektor perumahan Kota Gannon</color>",
  ui_story_1016_10161302_2_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1016_10161302_3_dialog_content = "Ini bukan laboratorium rahasia, atau semacamnya. Itu hanya tempat tinggal biasa.",
  ui_story_1016_10161302_4_dialog_content = "Apakah memang ada jalan menuju dunia luar di suatu tempat di sini?",
  ui_story_1016_10161302_5_dialog_content = "Anda ... pergi.",
  ui_story_1016_10161302_6_dialog_content = "Kenapa?",
  ui_story_1016_10161302_7_dialog_content = "Karena ini adalah akhir dari garis bagi kita.",
  ui_story_1016_10161302_8_dialog_content = "Illumina telah menyerah pada kami berdua. Tidak ada gunanya tinggal di sini lagi.",
  ui_story_1016_10161302_9_dialog_content = "Itu benar. Panitia menyerah pada kami ...",
  ui_story_1016_10161302_10_dialog_content = "Aku... aku ingat sekarang...",
  ui_story_1016_10161302_11_dialog_content = "Apa yang kamu ingat?",
  ui_story_1016_10161302_12_dialog_content = "...",
  ui_story_1016_10161302_13_dialog_content = "Segalanya.",
  ui_story_1016_10161302_14_dialog_content = "Kenangan masa laluku, pertempuran itu, penantian tanpa akhir...",
  ui_story_1016_10161302_15_dialog_content = "Dan keputusasaan.",
  ui_story_1016_10161302_16_dialog_content = "Maka Anda harus sepenuhnya menyadari situasi Anda saat ini.",
  ui_story_1016_10161302_17_dialog_content = "Segala sesuatu yang pernah menjadi milik Anda tidak ada lagi.",
  ui_story_1016_10161302_18_dialog_content = "Kamu bukan lagi prajurit Illumina, tapi desertir dan monster.",
  ui_story_1016_10161302_19_dialog_content = "Jadi jika Anda ingin hidup, bantu saya menemukan jalan keluarnya.",
  ui_story_1016_10161302_20_dialog_content = "Tidak usah.",
  ui_story_1016_10161302_21_dialog_content = "Tidak pernah ada jalan keluar di tempat ini.",
  ui_story_1016_10161302_22_dialog_content = "...",
  ui_story_1016_10161302_23_dialog_content = "Hmph, jadi ini rencanamu selama ini.",
  ui_story_1016_10161302_24_dialog_content = "Tidak bisa mengatakan saya terkejut.",
  ui_story_1016_10161302_25_dialog_content = "Serahkan penelitian Anda dan serahkan.",
  ui_story_1016_10161302_26_dialog_content = "Bekerja samalah, dan aku akan membuat kematianmu secepat dan semudah mungkin.",
  ui_story_1016_10161302_27_dialog_content = "Keluar dari jalan.",
  ui_story_1016_10161302_28_dialog_content = "Tampaknya Anda tidak mau bekerja sama.",
  ui_story_1016_10161302_29_dialog_content = "Terserah Anda kalau begitu. Tentara!",
  ui_story_1016_10161302_30_dialog_content = "Apa... Apa yang kamu pikir kamu lakukan?!",
  ui_story_1016_10161302_31_dialog_content = "Tangkap mereka.",
  ui_story_1016_10161302_32_dialog_content = "Paham!",
  ui_story_1016_10161302_33_dialog_content = "Betapa sombongnya.",
  ui_story_1016_10161302_34_dialog_content = "<size=45>Membela!</size>",
  ui_story_1016_10161302_35_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1016_10161302_36_dialog_content = "...",
  ui_story_1016_10161302_37_dialog_content = "Jangan sia-siakan kekuatanmu.",
  ui_story_1016_10161302_38_dialog_content = "Untuk menjatuhkanmu, prajuritku telah dilengkapi dengan baju besi eksperimental jenis baru, milik Dewan Sains.",
  ui_story_1016_10161302_39_dialog_content = "Anda akan dikalahkan jauh sebelum efeknya hilang.",
  ui_story_1016_10161302_40_dialog_content = "Lagipula sepertinya kalian punya otak.",
  ui_story_1016_10161302_41_dialog_content = "Meski begitu, kamu masih tidak lebih dari sekumpulan orang bodoh.",
  ui_story_1016_10161302_42_dialog_content = "<color=#e8d9bb>Sementara itu, di arena</color>",
  ui_story_1016_10161302_43_dialog_content = "Saya menang?",
  ui_story_1016_10161302_44_dialog_content = "Itu benar. Anda adalah pemenangnya.",
  ui_story_1016_10161302_45_dialog_content = "Sekarang berhentilah sebelum Anda lebih menyakiti diri sendiri.",
  ui_story_1016_10161302_46_dialog_content = "...",
  ui_story_1016_10161302_47_dialog_content = "Apa? Apakah saya mendengarnya dengan benar?",
  ui_story_1016_10161302_48_dialog_content = "Yang legendaris Reinhardt benar-benar kalah dalam pertarungan?!",
  ui_story_1016_10161302_49_dialog_content = "Tapi bagaimana?",
  ui_story_1016_10161302_50_dialog_content = "Ini tidak bisa...",
  ui_story_1016_10161302_51_dialog_content = "<size=45>Apa yang kalian mainkan?!</size>",
  ui_story_1016_10161302_52_dialog_content = "Reinhardt menyerahkan dirinya? Dia bahkan tidak bertarung dengan kemampuan terbaiknya!",
  ui_story_1016_10161302_53_dialog_content = "Taktik kotor dan curang macam apa yang kalian para pengecut tua gunakan untuk membuat ini terjadi?!",
  ui_story_1016_10161302_54_dialog_content = "Harap perhatikan kata-kata Anda, Komandan Barton. Bagaimanapun, ini adalah pertandingan resmi!",
  ui_story_1016_10161302_55_dialog_content = "Tenanglah, Barton.",
  ui_story_1016_10161302_56_dialog_content = "Ini bukan waktunya untuk membiarkan kemarahan menguasai Anda.",
  ui_story_1016_10161302_57_dialog_content = "Jika ini adalah keputusan Reinhard, saya yakin dia punya alasan bagus untuk melakukannya.",
  ui_story_1016_10161302_58_dialog_content = "Saya percaya penilaiannya, jadi mari kita tanyakan padanya nanti.",
  ui_story_1016_10161302_59_dialog_content = "<size=45>Apakah kamu bercanda?!</size>",
  ui_story_1016_10161302_60_dialog_content = "<size=45>Benarkah ini akhirnya? Pertarungan macam apa ini?!</size>",
  ui_story_1016_10161302_61_dialog_content = "Diam, semuanya!",
  ui_story_1016_10161302_62_dialog_content = "Saya harus meminta Anda untuk menghormati hasil pertandingan ini!",
  ui_story_1016_10161302_63_dialog_content = "Adegan yang sangat hidup.",
  ui_story_1016_10161302_64_dialog_content = "Saya yakin sekarang sudah hampir waktunya.",
  ui_story_1016_10161302_65_dialog_content = "Petugas Ulysses! Saya punya pesan mendesak untuk Anda!",
  ui_story_1016_10161302_66_dialog_content = "Silakan.",
  ui_story_1016_10161302_67_dialog_content = "Situasinya adalah...",
  ui_story_1016_10161302_68_dialog_content = "Ya, ya... Baiklah kalau begitu.",
  ui_story_1016_10161302_69_dialog_content = "Anda dapat melanjutkan tugas Anda sekarang.",
  ui_story_1016_10161302_70_dialog_content = "Siap, Jenderal.",
  ui_story_1016_10161302_71_dialog_content = "May Saya mohon pinjam mikrofon Anda, hakim?",
  ui_story_1016_10161302_72_dialog_content = "Tapi Pak, ini...",
  ui_story_1016_10161302_73_dialog_content = "Saya memiliki pengumuman mendesak untuk semua orang—",
  ui_story_1016_10161302_74_dialog_content = "Itu pesan dari panitia.",
  ui_story_1016_10161302_75_dialog_content = "V-Baiklah, kalau begitu...",
  ui_story_1016_10161302_76_dialog_content = "Ahem... Perhatian, semuanya. Saya memiliki perintah darurat untuk diumumkan.",
  ui_story_1016_10161302_77_dialog_content = "Apa? Perintah darurat?",
  ui_story_1016_10161302_78_dialog_content = "Perintah darurat apa?",
  ui_story_1016_10161302_79_dialog_content = "Orang tua bodoh itu pasti merencanakan sesuatu.",
  ui_story_1016_10161302_80_dialog_content = "Mereka busuk sampai ke intinya, semuanya.",
  ui_story_1016_10161302_81_dialog_content = "Perasaanku tidak enak…",
  ui_story_1016_10161302_82_dialog_content = "Beberapa saat yang lalu, Komite menerima laporan mengejutkan.",
  ui_story_1016_10161302_83_dialog_content = "Petugas Intelijen Komite menemukan tanda-tanda Forsakin dan Helios, dua penjahat Illumina yang paling dicari, di sini di Kota Gannon. Berkat upaya mereka, kami telah menemukan keberadaan mereka saat ini.",
  ui_story_1016_10161302_84_dialog_content = "Mustahil! Saya bertanggung jawab untuk menemukan mereka selama ini! Prajuritku adalah orang-orang yang menjelajahi seluruh kota untuk mencari mereka berdua!",
  ui_story_1016_10161302_85_dialog_content = "Patroli saya dan saya belum menemukan tanda-tanda Forsakin!",
  ui_story_1016_10161302_86_dialog_content = "Itu hanya membuktikan bahwa usaha Anda tidak cukup baik.",
  ui_story_1016_10161302_87_dialog_content = "Saat mengejar Forsakin, Petugas Intelijen juga menemukan jalan rahasia yang tidak ditemukan di peta kota mana pun.",
  ui_story_1016_10161302_88_dialog_content = "Yang sangat mengejutkan kami, terowongan itu... Mengarah langsung ke area pemukiman Grand Marshal Reinhardt.",
  ui_story_1016_10161302_89_dialog_content = "Tidak ingin melepaskan unsur kejutan, Petugas Intelijen terus melacaknya secara diam-diam, hanya untuk menemukan dia berjalan dengan angkuh ke rumah Reinhardt.",
  ui_story_1016_10161302_90_dialog_content = "<size=45>Apa?! Itu tidak mungkin!!</size>",
  ui_story_1016_10161302_91_dialog_content = "...",
  ui_story_1016_10161302_92_dialog_content = "Jadi ini rencanamu selama ini...",
  ui_story_1016_10161302_93_dialog_content = "Apakah kamu bercanda?!",
  ui_story_1016_10161302_94_dialog_content = "Anda pembuat kode terkutuk...",
  ui_story_1016_10161302_95_dialog_content = "Selalu cepat memfitnah orang lain, meski menolak menginjakkan kaki di medan perang!",
  ui_story_1016_10161302_96_dialog_content = "Demi Anda, sebaiknya Anda memiliki bukti yang cukup untuk mendukung klaim liar ini.",
  ui_story_1016_10161302_97_dialog_content = "Itu benar. Pedangku tidak akan mentolerir satu orang pun yang menodai reputasi rekanku.",
  ui_story_1016_10161302_98_dialog_content = "Silakan tenang, kalian semua.",
  ui_story_1016_10161302_99_dialog_content = "Saya mengerti bahwa perkembangan ini cukup memprihatinkan. Panitia juga awalnya tidak mau percaya.",
  ui_story_1016_10161302_100_dialog_content = "Tetapi pada kenyataannya, kami memiliki bukti kesalahan yang tidak dapat disangkal. Setiap patroli dapat membuktikan kebenaran dari masalah ini.",
  ui_story_1016_10161302_101_dialog_content = "Saat ini, kedua buronan itu berusaha mati-matian untuk melarikan diri dari Kota Gannon.",
  ui_story_1016_10161302_102_dialog_content = "Ini tidak masuk akal! Saya pergi!",
  ui_story_1016_10161302_103_dialog_content = "Apakah kita seharusnya hanya duduk di sini dan menunggu dengan sabar sampai mereka menyerang kita?!",
  ui_story_1016_10161302_104_dialog_content = "Tolong jangan panik, semuanya; kami telah menugaskan keamanan tambahan untuk perimeter arena. Keamanan Anda adalah perhatian terbesar Komite.",
  ui_story_1016_10161302_105_dialog_content = "Tanpa penundaan lebih lanjut, Komite telah mengambil keputusan—",
  ui_story_1016_10161302_106_dialog_content = "Reinhardt, Anda dicurigai membantu dan bersekongkol dengan musuh.",
  ui_story_1016_10161302_107_dialog_content = "Karena itu, Komite telah memilih untuk mencabut status Anda sebagai Marsekal Agung.",
  ui_story_1016_10161302_108_dialog_content = "Selain itu, Anda harus sepenuhnya tunduk pada penyelidikan kami atas potensi kejahatan Anda.",
  ui_story_1016_10161401_1_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1016_10161401_2_dialog_content = "Intrusi ilegal terdeteksi, intrusi ilegal terdeteksi!",
  ui_story_1016_10161401_2X1_dialog_content = "Seseorang ada di sana! Minggir, Wraith!",
  ui_story_1016_10161401_3_dialog_content = "Ck, tunjukkan sedikit rasa hormat, dan aku bahkan mungkin mempertimbangkan untuk memberimu kematian cepat.",
  ui_story_1016_10161401_4_dialog_content = "Adapun yang lain ...",
  ui_story_1016_10161401_5_dialog_content = "Pergilah sekarang.",
  ui_story_1016_10161401_6_dialog_content = "<anim type=Shake><size=45>Grahhh—!</size></anim>",
  ui_story_1016_10161401_7_dialog_content = "bunga es! Menyebar-!",
  ui_story_1016_10161401_8_dialog_content = "<anim type=Shake>Graaah...</anim>",
  ui_story_1016_10161401_9_dialog_content = "(Eclipsian) Pasukan kita berkurang, Lord Figerald...",
  ui_story_1016_10161401_10_dialog_content = "Satu-satunya kewajiban Anda adalah mati. Jadi buatlah terburu-buru.",
  ui_story_1016_10161401_11_dialog_content = "Beri dia waktu yang cukup, dan para Aurorian ini pasti akan kalah!",
  ui_story_1016_10161401_12_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1016_10161401_24_dialog_content = "Heheh... <size=50>Ha ha ha ha</size>!",
  ui_story_1016_10161401_26_dialog_content = "Saya akan menunjukkan kepada Anda! Saya akan menunjukkan kepada Anda semua bahwa saya masih pantas mendapatkan tempat saya!",
  ui_story_1016_10161401_27_dialog_content = "(Tempatnya? Apakah ini berarti dia dikeluarkan dari Eclipse?)",
  ui_story_1016_10161401_28_dialog_content = "Lihatlah sekelilingmu.",
  ui_story_1016_10161401_29_dialog_content = "Antek-antek Anda telah dimusnahkan.",
  ui_story_1016_10161401_30_dialog_content = "Anda adalah komandan dari apa-apa sekarang.",
  ui_story_1016_10161401_31_dialog_content = "Komandan apa-apa, katamu?",
  ui_story_1016_10161401_32_dialog_content = "Dan bagaimana dengan itu? Saya lebih dari cukup untuk menghancurkan Anda bug yang tidak penting!",
  ui_story_1016_10161401_33_dialog_content = "<anim type=Shake><size=45>Hrrrrgh—!!!</size></anim>",
  ui_story_1016_10161401_34_dialog_content = "Apa yang dilakukannya?",
  ui_story_1016_10161401_35_dialog_content = "Awas, PlayerName!",
  ui_story_1016_10161401_36_dialog_content = "<anim type=Shake><size=45>Ck, ck, ck!</size></anim>",
  ui_story_1016_10161401_37_dialog_content = "Sudah lama sejak aku melepaskan kekuatan sejatiku!",
  ui_story_1016_10161401_38_dialog_content = "Aku menyimpan serangan ini untuk gadis malang dari Northland...",
  ui_story_1016_10161401_39_dialog_content = "Tapi menggunakannya pada kalian orang bodoh seharusnya sama memuaskannya!",
  ui_story_1016_10161401_40_dialog_content = "Meringkuk di hadapanku, cacing!",
  ui_story_1016_10161401_41_dialog_content = "Ambil momen terakhir ini untuk berdamai dengan dewa-dewa Anda!",
  ui_story_1016_10161402_0X1_dialog_content = "Hama sialan... Mereka benar-benar mendorongku ke...",
  ui_story_1016_10161402_0X2_dialog_content = "Mati! Kalian semua harus mati!!!",
  ui_story_1016_10161402_0X3_dialog_content = "Hati-Hati! Dia masih punya kekuatan tersisa!",
  ui_story_1016_10161402_0X4_dialog_content = "Dan kamu, Caelestite! Anda seharusnya sudah mati sejak lama !!!",
  ui_story_1016_10161402_0X5_dialog_content = "Cepat! Kembali, PlayerName!",
  ui_story_1016_10161402_0X6_dialog_content = "Jangan mencoba menghentikanku!",
  ui_story_1016_10161402_0X7_dialog_content = "Ah!",
  ui_story_1016_10161402_0X8_dialog_content = "<color=#e8d9bb>Nguuung!</color>",
  ui_story_1016_10161402_0X9_dialog_content = "(Apa-?!)",
  ui_story_1016_10161402_0X10_dialog_content = "(Jangan sentuh dia.)",
  ui_story_1016_10161402_0X11_dialog_content = "(Sudahkah kamu menemukannya? Tunggu apa lagi? Ayo pergi dari sini—)",
  ui_story_1016_10161402_0X12_dialog_content = "(Lepaskan tanganmu darinya.)",
  ui_story_1016_10161402_0X13_dialog_content = "(Jangan katakan saya tidak memperingatkan Anda.)",
  ui_story_1016_10161402_1_dialog_content = "<anim type=Shake><size=45>Aduh!</size></anim>",
  ui_story_1016_10161402_2_dialog_content = "<anim type=Shake>Sialan kau... Dasar Aurorian kotor...!</anim>",
  ui_story_1016_10161402_3_dialog_content = "<anim type=Shake>Sialan kalian semua! Sialan Forsakin, dan sial juga semua Eclipse!!!</anim>",
  ui_story_1016_10161402_4_dialog_content = "<anim type=Shake>Kalian semua bisa masuk neraka!!!</anim>",
  ui_story_1016_10161402_4X1_dialog_content = "Argh…",
  ui_story_1016_10161402_5_dialog_content = "Vice!",
  ui_story_1016_10161402_6_dialog_content = "<anim type=Shake>Jika aku harus mati, aku menolak mati di tanganmu serangga tak berguna!!!</anim>",
  ui_story_1016_10161402_7_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_1016_10161402_7X1_dialog_content = "<color=#e8d9bb>Ngungg!</color>",
  ui_story_1016_10161402_8_dialog_content = "—!!!",
  ui_story_1016_10161402_9_dialog_content = "Kau terlalu banyak omong.",
  ui_story_1016_10161402_10_dialog_content = "Uhuk uhuk!",
  ui_story_1016_10161402_10X1_dialog_content = "Vice! Kau baik-baik saja?!",
  ui_story_1016_10161402_11_dialog_content = "Dengan cepat! Dia mungkin berpura-pura mati untuk membuat kita lengah.",
  ui_story_1016_10161402_12_dialog_content = "Aku akan pergi melihatnya.",
  ui_story_1016_10161402_13_dialog_content = "...",
  ui_story_1016_10161402_14_dialog_content = "Musuh sama sekali tidak sadar. Kita harus baik-baik saja untuk saat ini.",
  ui_story_1016_10161402_15_dialog_content = "Dia berhasil bertahan hidup, tetapi tidak sebelum kehilangan kesadaran.",
  ui_story_1016_10161402_15X1_dialog_content = "(Apakah seranganku tadi benar-benar sekuat itu?)",
  ui_story_1016_10161402_15X2_dialog_content = "(Mungkinkah ini berarti...)",
  ui_story_1016_10161402_16_dialog_content = "Lalu izinkan saya menyingkirkan dia dari kesengsaraannya dan membalaskan nyawa setiap orang yang menjadi korban dia dan kaumnya.",
  ui_story_1016_10161402_17_dialog_content = "Tunggu! Jangan bunuh dia!",
  ui_story_1016_10161402_18_dialog_content = "Hah? Kenapa tidak?",
  ui_story_1016_10161402_19_dialog_content = "Apakah kamu tidak ingat apa yang saya katakan sebelumnya? Jika Forsakin atau Wraith lainnya ditangkap, mereka harus diserahkan ke tahanan Illumina.",
  ui_story_1016_10161402_20_dialog_content = "... Apapun yang Anda katakan kemudian.",
  ui_story_1016_10161402_21_dialog_content = "Tetapi mengingat keadaannya, saya ragu dia akan menjawab pertanyaan Anda dalam waktu dekat.",
  ui_story_1016_10161402_22_dialog_content = "Itu bukan urusanmu. Kami akan mengurusnya.",
  ui_story_1016_10161402_23_dialog_content = "Mengapa mengampuni dia, Yingel? Dia sudah menyakiti begitu banyak orang!",
  ui_story_1016_10161402_24_dialog_content = "Harap tenang, PlayerName. Aku tahu kamu juga kesal.",
  ui_story_1016_10161402_25_dialog_content = "Tapi tolong pertimbangkan ini: dalam sejarah Astra, kami belum melakukan penelitian yang berarti tentang para Wraith.",
  ui_story_1016_10161402_26_dialog_content = "Selain sebagai subjek penelitian yang berharga, Figerald mungkin juga memberi kita informasi penting tentang <color=#FFB400>Gerhana</color>.",
  ui_story_1016_10161402_27_dialog_content = "Yang paling penting, dia bisa memasuki tempat semacam ini tanpa menemui perlawanan apapun...",
  ui_story_1016_10161402_28_dialog_content = "Artinya, dia mempercayai siapa pun yang memberinya kunci dan informasi lainnya.",
  ui_story_1016_10161402_29_dialog_content = "Kemungkinan besar informan ini adalah pengkhianat di dalam Federasi Illumina.",
  ui_story_1016_10161402_30_dialog_content = "Anda membuat poin yang valid, tetapi saya masih tidak setuju dengan Anda.",
  ui_story_1016_10161402_31_dialog_content = "Kurangnya pengetahuan kita tentang Wraith bisa menjadi indikasi bahwa kita tidak memiliki cara untuk mengendalikan mereka. Bahkan Federasi Illumina pun tidak.",
  ui_story_1016_10161402_32_dialog_content = "Apa yang akan Anda lakukan, jika dia akhirnya sadar dan keluar dari tahanan Anda?",
  ui_story_1016_10161402_33_dialog_content = "Federasi akan melakukan segala daya untuk mencegah hal itu terjadi.",
  ui_story_1016_10161402_34_dialog_content = "Tetapi Anda tidak dapat menjamin bahwa itu tidak akan terjadi.",
  ui_story_1016_10161402_35_dialog_content = "Kami juga tidak dapat mengabaikan prospek untuk melanjutkan tujuan kami hanya karena risikonya terlalu besar.",
  ui_story_1016_10161402_36_dialog_content = "...",
  ui_story_1016_10161402_37_dialog_content = "Kemudian lakukan sesukamu.",
  ui_story_1016_10161402_38_dialog_content = "Vice, Anatoli, PlayerName, apa pendapatmu tentang ini?",
  ui_story_1016_10161402_39_dialog_content = "Aku tidak keberatan.",
  ui_story_1016_10161402_40_dialog_content = "Jika ini keputusanmu, Kolonel Yingel, maka saya juga tidak keberatan.",
  ui_story_1016_10161402_41_option_content = "Tidak ada keberatan di sini.",
  ui_story_1016_10161402_42_option_content = "Saya tidak setuju.",
  ui_story_1016_10161402_43_dialog_content = "Carleen benar, Yingel. Kita tidak bisa mengambil risiko Figerald kabur",
  ui_story_1016_10161402_44_dialog_content = "Butuh semua yang kami miliki untuk menjatuhkannya kali ini. Tidak ada yang tahu apa yang akan dia lakukan jika kita membiarkannya hidup!",
  ui_story_1016_10161402_45_dialog_content = "Apakah Anda tahu berapa banyak nyawa yang dia hancurkan ...",
  ui_story_1016_10161402_46_dialog_content = "Saya memahami frustrasi Anda, tetapi saya harus bersikeras pada tindakan saya sendiri.",
  ui_story_1016_10161402_47_dialog_content = "Tolong percaya padaku, serta sekutumu di Illumina.",
  ui_story_1016_10161402_48_dialog_content = "Begitu banyak dari kita sendiri memberikan hidup mereka untuk membantu kita belajar lebih banyak tentang Eclipsites. Saya menolak untuk membiarkan pengorbanan mereka sia-sia!",
  ui_story_1016_10161402_49_dialog_content = "...",
  ui_story_1016_10161402_50_dialog_content = "...",
  ui_story_1016_10161402_51_dialog_content = "Baiklah.",
  ui_story_1016_10161402_52_dialog_content = "Terima kasih atas pengertianmu.",
  ui_story_1016_10161402_53_dialog_content = "Saya akan menghubungi Departemen Intelijen dan meminta mereka menahan dan menginterogasi Wraith ini segera.",
  ui_story_1016_10161402_54_dialog_content = "Tapi pekerjaan kami belum selesai. Saya khawatir rekannya ada di balik pintu itu.",
  ui_story_1016_10161402_55_dialog_content = "Memang, dan kami memiliki Guardian One di dalam...",
  ui_story_1016_10161402_56_dialog_content = "Nah, tidak peduli siapa atau apa musuh kita selanjutnya, biarkan mereka melakukan yang terburuk!",
  ui_story_1016_10161402_57_dialog_content = "Aku hanya berharap ini semua akan segera berakhir.",
  ui_story_1016_10161402_58_dialog_content = "(Saya tidak tahu caranya Axelia sedang melakukan. Apakah dia... masih hidup?)",
  ui_story_1016_10161402_59_dialog_content = "(Kami siap menjalankan misi kami dengan segala cara, tapi saat aku melihatnya pergi...)",
  ui_story_1016_10161402_60_dialog_content = "Tetap waspada, semuanya!",
  ui_story_1016_10161402_61_dialog_content = "Ada sesuatu tepat di balik pintu itu!",
  ui_story_1016_10161402_62_dialog_content = "(Aura ini...!)",
  ui_story_1016_10161402_63_dialog_content = "<color=#e8d9bb>Gruk—</color>",
  ui_story_1016_10161402_64_dialog_content = "<color=#e8d9bb>Bwee—Bwee—</color>",
  ui_story_1016_10161402_65_dialog_content = "Bersiaplah untuk pertempuran lain, PlayerName!",
  ui_story_1016_10161402_66_dialog_content = "Tetap dalam formasi! Jangan tunjukkan kelemahan!",
  ui_story_1016_10161402_67_dialog_content = "<color=#e8d9bb>Duarr...</color>",
  ui_story_1016_10161402_68_dialog_content = "Seseorang keluar!",
  ui_story_1016_10161402_69_dialog_content = "Apakah itu...?!",
  ui_story_1016_10161402_70_dialog_content = "(Saya melihat sosok aneh keluar dari balik pintu.)",
  ui_story_1016_10161402_71_dialog_content = "(Itu hanya sesaat, tapi aku merasakan Aliran Gelap bahkan lebih kuat daripada Figerald yang berasal dari tubuh mereka.)",
  ui_story_1016_10161402_72_dialog_content = "(Kami sudah menggunakan sebagian besar kekuatan kami untuk melawan Figerald.)",
  ui_story_1016_10161402_73_dialog_content = "(Pada saat itu, orang asing itu bisa saja mengalahkan kita kapan pun mereka mau...)",
  ui_story_1016_10161402_74_dialog_content = "Hati-Hati, Vice! Mereka datang tepat pada Anda!",
  ui_story_1016_10161402_75_dialog_content = "Hah?!",
  ui_story_1016_10161402_76_dialog_content = "Setelah berpisah dunia begitu lama...",
  ui_story_1016_10161402_77_dialog_content = "Akhirnya, kita akhirnya bertemu lagi.",
  ui_story_1016_10161402_78_dialog_content = "Siapa kau?",
  ui_story_1016_10161402_79_dialog_content = "(Dia terlihat seperti a <color=#FFB400>Hantu</color>!)",
  ui_story_1016_10161402_80_dialog_content = "(Saya bahkan tidak tahu namanya, jadi kenapa...)",
  ui_story_1016_10161402_81_dialog_content = "(Mengapa dia tampak begitu <color=#FFB400>akrab</color>?!)",
  ui_story_1016_10161402_82_dialog_content = "Tunggu! Jangan pergi!",
  ui_story_1016_10161402_83_dialog_content = "Anda akan segera tahu segalanya ...",
  ui_story_1016_10161402_84_dialog_content = "Di masa depan.",
  ui_story_1016_10161402_85_dialog_content = "Hentikan dia!",
  ui_story_1016_10161402_86_dialog_content = "Dia membawa <color=#FFB400>konsol inti Guardian One</color>!",
  ui_story_1016_10161402_87_dialog_content = "Berkilau!",
  ui_story_1016_10161402_88_dialog_content = "Tidak ada gunanya.",
  ui_story_1016_10161402_89_dialog_content = "I-Itu tidak berpengaruh?!",
  ui_story_1016_10161402_90_dialog_content = "Setelah dia! Kita tidak bisa membiarkannya melarikan diri dengan konsol inti Guardian One!",
  ui_story_1016_10161402_91_dialog_content = "<color=#e8d9bb>Sementara itu, di Kota Gannon</color>",
  ui_story_1016_10161402_92_dialog_content = "Mereka tidak bisa pergi jauh. Cari di setiap sudut tempat.",
  ui_story_1016_10161402_93_dialog_content = "Siap, Pak!",
  ui_story_1016_10161402_94_dialog_content = "...",
  ui_story_1016_10161402_95_dialog_content = "Mereka sangat gigih.",
  ui_story_1016_10161402_96_dialog_content = "Pada tingkat ini, hanya masalah waktu sebelum mereka menemukan kita di sini.",
  ui_story_1016_10161402_97_dialog_content = "Kita harus pergi.",
  ui_story_1016_10161402_98_dialog_content = "Tempat ini... Sepertinya Undercity 80.",
  ui_story_1016_10161402_99_dialog_content = "Tidak ada gunanya mengatakan hal seperti itu lagi.",
  ui_story_1016_10161402_100_dialog_content = "Kau pikir begitu? Mungkin kamu benar...",
  ui_story_1016_10161402_101_dialog_content = "Saat itu... Kita tidak berbeda dengan sekarang. Terjebak di Undercity, dikelilingi oleh musuh...",
  ui_story_1016_10161402_102_dialog_content = "Baru saat itu... Kami melawan Eclipsites... bukan rekan kami...",
  ui_story_1016_10161402_103_dialog_content = "Apakah benar-benar ada perbedaan?",
  ui_story_1016_10161402_104_dialog_content = "Sejauh yang saya ketahui, siapa pun yang menghalangi jalan saya adalah musuh.",
  ui_story_1016_10161402_105_dialog_content = "Aurorian, Eclipsites, tidak ada bedanya bagiku.",
  ui_story_1016_10161402_106_dialog_content = "Tidak... Ini sama sekali tidak sama.",
  ui_story_1016_10161402_107_dialog_content = "Eclipsites adalah musuh alami kami... Tapi kawan-kawan kami? Mereka hanya tidak tahu apa yang telah kita lalui.",
  ui_story_1016_10161402_108_dialog_content = "Ini semua salah paham.",
  ui_story_1016_10161402_109_dialog_content = "Tidak ada kesalahpahaman, Helios.",
  ui_story_1016_10161402_110_dialog_content = "Inilah siapa mereka sebenarnya: bodoh, orang bodoh yang patuh membabi buta.",
  ui_story_1016_10161402_111_dialog_content = "...",
  ui_story_1016_10161402_112_dialog_content = "Apa... Apa yang terjadi padamu... hingga membuatmu berakhir seperti ini?",
  ui_story_1016_10161402_113_dialog_content = "Kapan pikiran Anda menjadi begitu jernih?",
  ui_story_1016_10161402_114_dialog_content = "Sedikit demi sedikit, selama beberapa hari terakhir...",
  ui_story_1016_10161402_115_dialog_content = "Awalnya, rasanya pikiranku... diselimuti kabut tebal...",
  ui_story_1016_10161402_116_dialog_content = "Tapi sekarang ... semuanya menjadi sedikit lebih jelas ...",
  ui_story_1016_10161402_117_dialog_content = "Benarkah?",
  ui_story_1016_10161402_118_dialog_content = "Sepertinya hasil percobaan saya telah sangat melampaui harapan saya.",
  ui_story_1016_10161402_119_dialog_content = "Kau masih... belum menjawabku...",
  ui_story_1016_10161402_120_dialog_content = "Katakan padaku... kenapa kita pergi...",
  ui_story_1016_10161402_121_dialog_content = "Izinkan saya... membantu Anda kembali ke Illumina.",
  ui_story_1016_10161402_122_dialog_content = "Betapa tidak dewasa.",
  ui_story_1016_10161402_123_dialog_content = "Apakah Anda benar-benar mengharapkan kami diterima di sini? Apa sebenarnya yang memberi Anda ide itu?",
  ui_story_1016_10161402_124_dialog_content = "Ini adalah rumah kami.",
  ui_story_1016_10161402_125_dialog_content = "Teman-teman kita, dan Reinhardt, mereka menunggu kita.",
  ui_story_1016_10161402_126_dialog_content = "Reinhardt bukan teman saya. Dia sudah lama meninggalkanku, sama seperti dia meninggalkanmu.",
  ui_story_1016_10161402_127_dialog_content = "Di setiap level, Illumina benar-benar rusak.",
  ui_story_1016_10161402_128_dialog_content = "kemarahanmu...",
  ui_story_1016_10161402_129_dialog_content = "Kebencianmu... akan memakanmu...",
  ui_story_1016_10161402_130_dialog_content = "Ah, benarkah? Lalu izinkan saya memberi tahu Anda tentang kebenaran di balik segalanya.",
  ui_story_1016_10161402_131_dialog_content = "Jika Anda masih ingin percaya pada mereka sesudahnya, maka tidak ada yang membantu Anda sama sekali.",
  ui_story_1016_10161402_132_dialog_content = "Kebenaran?",
  ui_story_1016_10161402_133_dialog_content = "Ya, dan sebenarnya kita semua adalah senjata yang diciptakan demi kepentingan Illumina. Anda, saya, dan bahkan Reinhardt.",
  ui_story_1016_10161402_134_dialog_content = "Panitia memberi kami program modifikasi eksperimental yang disebut Proyek: Matahari Buatan untuk meningkatkan kekuatan kami.",
  ui_story_1016_10161402_135_dialog_content = "Pertarungan kami di Undercity 80 hanyalah uji coba bagi kami, subjek ujian mereka yang berharga.",
  ui_story_1016_10161402_136_dialog_content = "Apa yang disebut misi kami telah gagal sejak awal.",
  ui_story_1016_10161402_137_dialog_content = "Tapi bagaimana bisa?!",
  ui_story_1016_10161402_138_dialog_content = "Begitu banyak orang... Begitu banyak dari kita yang tewas dalam pertempuran itu!",
  ui_story_1016_10161402_139_dialog_content = "Itulah tujuan mereka selama ini.",
  ui_story_1016_10161402_140_dialog_content = "Komite ingin kami bertempur tanpa harapan agar kami dapat membuka potensi penuh kami.",
  ui_story_1016_10161402_141_dialog_content = "Sebagian besar dari kami dianggap gagal selama proses modifikasi, dan terbunuh dalam pertempuran atau berakhir dengan cara yang sama seperti Anda.",
  ui_story_1016_10161402_142_dialog_content = "Mengapa... Mengapa mereka melakukan ini?",
  ui_story_1016_10161402_143_dialog_content = "Sudah kubilang, demi percobaan mereka. Project Artificial Sun memiliki tingkat keberhasilan yang sangat rendah dengan memodifikasi subjek ujinya.",
  ui_story_1016_10161402_144_dialog_content = "Satu-satunya cara untuk benar-benar mengukur kesuksesan mereka adalah dengan memaksa kami melakukan pertempuran brutal melawan Eclipsites dan melihat siapa yang selamat.",
  ui_story_1016_10161402_145_dialog_content = "Reinhardt adalah satu-satunya yang dianggap sukses.",
  ui_story_1016_10161402_146_dialog_content = "Kami semua dibuang seperti sampah.",
  ui_story_1016_10161402_147_dialog_content = "Masih tidak mengerti? Kalau begitu biarkan saya membuatnya lebih sederhana, Anda bukan orang di mata Federasi Illumina. Anda adalah senjata, alat, dan tidak lebih.",
  ui_story_1016_10161402_148_dialog_content = "Jangan biarkan mereka membodohi Anda dengan pembicaraan mereka tentang kerabat dan negara. Jika Anda ingin bertahan hidup, Anda harus mulai memikirkan diri sendiri.",
  ui_story_1016_10161402_149_dialog_content = "Tidak ada tempat di dunia mereka untuk senjata rusak seperti kita.",
  ui_story_1016_10161402_150_dialog_content = "Anda sudah melihatnya sendiri, bukan? Cara semua orang menarik senjata mereka hanya dengan melihatmu.",
  ui_story_1016_10161402_151_dialog_content = "...",
  ui_story_1016_10161402_152_dialog_content = "Kamu... Kamu sendiri yang mengatakannya... Mereka hanya cuek...",
  ui_story_1016_10161402_153_dialog_content = "Itu sebabnya... kita perlu membuat mereka... melihat semuanya dengan jelas...",
  ui_story_1016_10161402_154_dialog_content = "Dan kalahkan orang-orang... yang membuat mereka buta.",
  ui_story_1016_10161402_155_dialog_content = "Itu akan mengatur Illumina di jalan yang benar lagi.",
  ui_story_1016_10161402_156_dialog_content = "Kita perlu memperbaiki masalah... bukan berkubang dalam kebencian kita.",
  ui_story_1016_10161402_157_dialog_content = "Jadi, Anda masih percaya semua kebohongan mereka.",
  ui_story_1016_10161402_158_dialog_content = "Tidak. Aku sudah lama berhenti percaya.",
  ui_story_1016_10161402_159_dialog_content = "Ini hanya ... jawaban saya sendiri untuk masalah ini. Anda mengatakan kepada saya untuk berpikir sendiri, kan?",
  ui_story_1016_10161402_160_dialog_content = "Jika Anda ingin pergi, saya tidak akan menghentikan Anda.",
  ui_story_1016_10161402_161_dialog_content = "Tapi aku tinggal di sini. Saya perlu mempelajari seluruh kebenaran... dan menghentikan mereka mengirim lebih banyak orang ke kematian mereka.",
  ui_story_1016_10161402_162_dialog_content = "Aku tidak akan mengizinkannya.",
  ui_story_1016_10161402_163_dialog_content = "Anda adalah subjek ujian saya. Sampai Anda benar-benar tidak melayani saya lagi, Anda ikut dengan saya.",
  ui_story_1016_10161402_164_dialog_content = "Tidak ada pilihan lain untukmu.",
  ui_story_1016_10161402_165_dialog_content = "Disini! Saya menemukan target!",
  ui_story_1016_10161402_166_dialog_content = "Cih.",
  ui_story_1016_10161402_167_dialog_content = "Hama yang merepotkan.",
  ui_story_1016_10161402_168_dialog_content = "!!!",
  ui_story_1016_10161402_169_dialog_content = "Jangan goyah! Serangannya tidak akan berhasil padamu!",
  ui_story_1016_10161402_170_dialog_content = "Masih belum menyerah, eh...?",
  ui_story_1016_10161402_171_dialog_content = "Tentu saja tidak. Kami telah mengambil setiap langkah untuk memastikan penjahat Illumina yang paling dicari tidak melarikan diri.",
  ui_story_1016_10161402_172_dialog_content = "Minggir!",
  ui_story_1016_10161402_173_dialog_content = "Fokus, kawan! Jangan biarkan mereka lolos kali ini!",
  ui_story_1016_10161402_174_dialog_content = "Pasukan A, bentuk garis pertahanan dan dorong ke arah musuh!",
  ui_story_1016_10161402_175_dialog_content = "Regu B, mengapit mereka dari belakang dan hentikan pelarian mereka!",
  ui_story_1016_10161402_176_dialog_content = "Siap, Pak!",
  ui_story_1016_10161402_177_dialog_content = "Menyebalkan sekali.",
  ui_story_1016_10161402_178_dialog_content = "Apa yang kamu tunggu? Ayo pergi, spesimen.",
  ui_story_1016_10161402_179_dialog_content = "Tidak...",
  ui_story_1016_10161402_180_dialog_content = "Aku akan... Aku akan menahan mereka selama aku bisa. Luangkan waktu itu untuk melarikan diri.",
  ui_story_1016_10161402_181_dialog_content = "Apa-apaan kau ini?!",
  ui_story_1016_10161402_182_dialog_content = "<size=45>Kembali!</size>",
  ui_story_1016_10161402_183_dialog_content = "Turunkan dia!",
  ui_story_1016_10161402_184_dialog_content = "<color=#e8d9bb>Ledakan-!!!</color>",
  ui_story_1016_10161402_185_dialog_content = "Batuk, batuk, batuk—!",
  ui_story_1016_10161402_186_dialog_content = "Dia menurunkan langit-langit dan menjebak dirinya sendiri di pihak kita!",
  ui_story_1016_10161402_187_dialog_content = "Lari, Denier.",
  ui_story_1016_10161402_188_dialog_content = "Ini adalah hal terakhir yang bisa kulakukan untukmu.",
  ui_story_1016_10161402_189_dialog_content = "Bodoh!",
  ui_story_1016_10161402_190_dialog_content = "Dasar idiot yang tidak bisa dipercaya!",
  ui_story_1016_10161402_191_dialog_content = "Berlari...",
  ui_story_1016_10161402_192_dialog_content = "Membantu Forsakin kabur, begitu...",
  ui_story_1016_10161402_193_dialog_content = "Itu tidak masalah. Lagipula-",
  ui_story_1016_10161402_194_dialog_content = "Anda adalah target utama kami selama ini.",
  ui_story_1016_10161402_195_dialog_content = "Tangkap dia.",
  ui_story_1016_10161402_196_dialog_content = "Siap, Pak!",
  ui_story_1016_10161402_197_dialog_content = "Tetap kembali...",
  ui_story_1016_10161402_198_dialog_content = "Aku tidak ingin menyakiti rekan-rekanku...",
  ui_story_1016_10161402_199_dialog_content = "Letakkan senjatamu!",
  ui_story_1016_10161402_200_dialog_content = "<size=45>Tetap kembali!</size>",
  ui_story_1016_10161402_201_dialog_content = "Aduh!!!",
  ui_story_1016_10161402_202_dialog_content = "Tidak ada gunanya menolak.",
  ui_story_1016_10161402_203_dialog_content = "…!",
  ui_story_1016_10161402_204_dialog_content = "Tahan dia!",
  ui_story_1016_10161402_205_dialog_content = "Target utama kami telah ditangkap.",
  ui_story_1016_10161402_206_dialog_content = "Target sekunder lolos, tapi tidak masalah.",
  ui_story_1016_10161402_207_dialog_content = "Misi selesai.",
  ui_story_1016_10161402_208_dialog_content = "Sekarang tinggal menunggu sinyal dari Petugas Ulysses.",
  ui_story_1016_10161402_209_dialog_content = "<color=#e8d9bb>Kembali ke arena</color>",
  ui_story_1016_10161402_210_dialog_content = "Letnan Axelia, tolong bantu Komite dengan menangkap Reinhardt.",
  ui_story_1016_10161402_211_dialog_content = "...",
  ui_story_1016_10161402_212_dialog_content = "Aku mengerti…",
  ui_story_1016_10161402_213_dialog_content = "Berhenti, Axelia! Tubuhmu sudah—",
  ui_story_1016_10161402_214_dialog_content = "…!",
  ui_story_1016_10161402_215_dialog_content = "Axelia!",
  ui_story_1016_10161402_216_dialog_content = "Hmm... Apa dia sudah terlalu memaksakan diri?",
  ui_story_1016_10161402_217_dialog_content = "Saya pikir dia akan bertahan sedikit lebih lama.",
  ui_story_1016_10161402_218_dialog_content = "Tapi itu tidak mengubah apa pun. Prajurit, tangkap dia.",
  ui_story_1016_10161402_219_dialog_content = "Siap, Pak!",
  ui_story_1016_10161402_220_dialog_content = "Berhenti, kalian semua!",
  ui_story_1016_10161402_221_dialog_content = "Ulysses! Anda harus tahu sekarang bahwa tindakan Dewan benar-benar di luar batas!",
  ui_story_1016_10161402_222_dialog_content = "Kalian para pengecut tua sudah cukup lama mencoba menahan kami!",
  ui_story_1016_10161402_223_dialog_content = "Bukankah kalian para idiot tahu itu Reinhardt apakah satu-satunya orang yang menghentikan kami untuk mengejarmu?!",
  ui_story_1016_10161402_224_dialog_content = "Tapi sekarang... Sekarang kamu benar-benar berhasil!",
  ui_story_1016_10161402_225_dialog_content = "Anda harus memberi tahu kami apa yang sebenarnya terjadi, Marsekal Agung.",
  ui_story_1016_10161402_226_dialog_content = "Jika mereka benar-benar berkomplot melawan kami, kami akan bertarung di sisimu dengan segala yang kami miliki.",
  ui_story_1016_10161402_227_dialog_content = "Harap tenang, Komandan. Komite hanya bertindak sesuai dengan aturan kami.",
  ui_story_1016_10161402_228_dialog_content = "Anda semua, di sisi lain, telah membengkokkan aturan itu untuk keuntungan pribadi Anda sendiri. Jika ada yang bertindak di luar batas, itu Anda.",
  ui_story_1016_10161402_229_dialog_content = "Jika Anda memiliki keberatan terhadap keputusan Komite, Anda dipersilakan untuk mengajukannya secara tertulis dan bukannya menggunakan kekerasan dan intimidasi.",
  ui_story_1016_10161402_230_dialog_content = "Anak dari...",
  ui_story_1016_10161402_231_dialog_content = "Sekarang saya harus meminta Anda semua menunjukkan rasa kesopanan yang tepat. Jika tidak, Komite tidak punya pilihan selain melabeli Anda sebagai rekan konspirator tersangka Reinhard.",
  ui_story_1016_10161402_232_dialog_content = "Cukup.",
  ui_story_1016_10161402_233_dialog_content = "Ini tidak ada hubungannya dengan mereka.",
  ui_story_1016_10161402_234_dialog_content = "Reinhard?!",
  ui_story_1016_10161402_235_dialog_content = "Biarkan aku membela diri, Wrath.",
  ui_story_1016_10161402_236_dialog_content = "Saya ingin melihat apakah saya dapat secara sah membuktikan ketidakbersalahan saya kepada semua Illumina.",
  ui_story_1016_10161402_237_dialog_content = "...",
  ui_story_1016_10161402_238_dialog_content = "Ya sudah.",
  ui_story_1016_10161402_239_dialog_content = "Terima kasih…",
  ui_story_1016_10161402_240_dialog_content = "Aku menyerahkan segalanya di tanganmu sekarang.",
  ui_story_1016_10161402_241_dialog_content = "Termasuk gadis itu. Dia dalam kondisi yang sangat buruk, jadi segera beri dia perhatian medis.",
  ui_story_1016_10161402_242_dialog_content = "...",
  ui_story_1016_10161402_243_dialog_content = "Marsekal Agung...?!",
  ui_story_1016_10161402_244_dialog_content = "Marsekal Agung...",
  ui_story_1016_10161402_245_dialog_content = "...",
  ui_story_1016_10161402_246_dialog_content = "Anda tidak perlu menyusahkan diri sendiri lagi, Ulysses.",
  ui_story_1016_10161402_247_dialog_content = "Saya setuju dengan penyelidikan Anda.",
  ui_story_1016_10161402_248_dialog_content = "Terima kasih atas kerja sama anda, Reinhardt.",
  ui_story_1016_10161402_249_dialog_content = "Bawa dia pergi.",
  ui_story_1016_10161402_250_dialog_content = "Siap, Pak!",
  ui_story_1016_10161501_1_dialog_content = "Itu menyimpulkan laporan saya.",
  ui_story_1016_10161501_2_dialog_content = "Jadi Wraith tak dikenal mencuri <color=#FFB400>Wali Satu</color> konsol inti, dan tidak dapat ditemukan...",
  ui_story_1016_10161501_3_dialog_content = "Kolonel Yingel, ini adalah kelalaian tugas yang menyedihkan.",
  ui_story_1016_10161501_4_dialog_content = "Saya minta maaf, dan siap menerima hukuman apa pun atas kegagalan saya.",
  ui_story_1016_10161501_5_dialog_content = "Selain orang-orang yang ada di sana pada saat itu, apakah ada orang lain yang mengetahui hal ini?",
  ui_story_1016_10161501_6_dialog_content = "Tidak pak. Masalahnya harus diketahui hanya oleh kita.",
  ui_story_1016_10161501_7_dialog_content = "Setiap orang yang hadir selama insiden itu berkumpul di sini sekarang. Tidak ada gunanya mereka memiliki kesempatan untuk membocorkan informasi ini.",
  ui_story_1016_10161501_8_dialog_content = "Hmm… Aku paham.",
  ui_story_1016_10161501_9_dialog_content = "Kolonel Yingel, dengan ini Anda dibebaskan dari misi Anda. Saya pribadi akan bertanggung jawab untuk menemukan dan menangkap Wraith yang tidak dikenal.",
  ui_story_1016_10161501_10_dialog_content = "Beristirahatlah untuk saat ini. Komite akan memiliki pesanan untuk Anda di lain waktu.",
  ui_story_1016_10161501_11_dialog_content = "Untuk kalian semua, tolong jangan mengungkapkan informasi apa pun mengenai masalah ini kepada orang lain.",
  ui_story_1016_10161501_12_dialog_content = "Siap, Jenderal.",
  ui_story_1016_10161501_13_dialog_content = "Siap, Jenderal.",
  ui_story_1016_10161501_14_dialog_content = "Aku mengerti.",
  ui_story_1016_10161501_15_dialog_content = "Mengerti. Berbagi informasi ini hanya akan mempersulit kami.",
  ui_story_1016_10161501_16_dialog_content = "Aku juga akan mengunci bibirku.",
  ui_story_1016_10161501_17_dialog_content = "Terima kasih atas kerja sama Anda.",
  ui_story_1016_10161501_18_dialog_content = "Itu saja untuk saat ini.",
  ui_story_1016_10161501_19_dialog_content = "Tunggu, bolehkah saya bertanya bagaimana caranya Axelia sedang melakukan?",
  ui_story_1016_10161501_20_dialog_content = "Letnan Axelia mendorong dirinya terlalu keras selama pertandingan final, dan saat ini dalam keadaan tidak sadar.",
  ui_story_1016_10161501_21_dialog_content = "Dia dirawat di pusat medis, dan Kapten Wrath sedang mengawasinya.",
  ui_story_1016_10161501_22_dialog_content = "Benar-benar? Dia masih...",
  ui_story_1016_10161501_23_dialog_content = "Aku harus pergi menemuinya sekarang!",
  ui_story_1016_10161501_24_dialog_content = "Dalam hal ini, saya akan melapor ke Grand Marshal Reinhardt.",
  ui_story_1016_10161501_25_dialog_content = "PlayerName, Letnan Vice, Nyonya Carleen, Leo... Di sinilah kita berpisah.",
  ui_story_1016_10161501_26_dialog_content = "Tidak perlu untuk itu.",
  ui_story_1016_10161501_27_dialog_content = "Hmm?",
  ui_story_1016_10161501_28_dialog_content = "Reinhardt telah dicopot dari pangkatnya. Untuk saat ini, Federasi Illumina tidak memiliki Grand Marshal.",
  ui_story_1016_10161501_29_dialog_content = "<size=45>Apa?!</size>",
  ui_story_1016_10161501_30_option_content = "Kamu bercanda kan?!",
  ui_story_1016_10161501_31_dialog_content = "Apa yang telah terjadi? Mengapa kita baru mendengar tentang ini sekarang?",
  ui_story_1016_10161501_32_option_content = "Apa yang terjadi?!",
  ui_story_1016_10161501_33_dialog_content = "Mengapa Reinhardt dicopot dari posisinya?",
  ui_story_1016_10161501_34_dialog_content = "Harap tenang, semuanya.",
  ui_story_1016_10161501_35_dialog_content = "Saya mengerti bahwa ini sangat mendadak, tetapi itu terjadi saat Anda mengejar Eclipsites yang bersembunyi di Kota Gannon. Secara alami, Anda tidak memiliki cara untuk mengetahuinya sampai sekarang.",
  ui_story_1016_10161501_36_dialog_content = "Patroli kami menemukan tanda-tanda Forsakin dan Helios, dua penjahat Illumina yang paling dicari, di Gannon City.",
  ui_story_1016_10161501_37_dialog_content = "Mereka telah bersembunyi di kota selama beberapa hari terakhir, menunggu kesempatan untuk mengganggu Latihan Militer Gabungan.",
  ui_story_1016_10161501_38_dialog_content = "Sayangnya, tempat persembunyian mereka tak lain adalah rumah Reinhardt.",
  ui_story_1016_10161501_39_dialog_content = "Setelah kami menangkap mereka, Komite ditempatkan Reinhardt dicurigai bersekongkol dengan musuh dan mencopot jabatannya.",
  ui_story_1016_10161501_40_dialog_content = "Tapi bagaimana itu mungkin?!",
  ui_story_1016_10161501_41_dialog_content = "Marsekal Agung Reinhardt tidak akan pernah memihak musuh!",
  ui_story_1016_10161501_42_dialog_content = "Seperti yang sudah saya nyatakan, dia bukan lagi Marsekal Agung Federasi Illumina.",
  ui_story_1016_10161501_43_dialog_content = "Komite masih melakukan penyelidikan penuh atas masalah ini. Jika dia berhasil membuktikan bahwa dia tidak bersalah, dia akan diangkat kembali sebagai Grand Marshal.",
  ui_story_1016_10161501_44_dialog_content = "Yang kami butuhkan dari Anda semua adalah kerja sama dan pengertian Anda, tidak lebih.",
  ui_story_1016_10161501_45_dialog_content = "Namun…",
  ui_story_1016_10161501_46_dialog_content = "aku tetap tak beli...",
  ui_story_1016_10161501_47_dialog_content = "Apakah Anda \"membelinya\" atau tidak, itu tidak relevan. Anda hanya perlu menunggu Komite menyelesaikan penyelidikannya.",
  ui_story_1016_10161501_48_dialog_content = "Selain itu, bagi Anda yang memiliki kedekatan dan sering berhubungan dengan Reinhardt—",
  ui_story_1016_10161501_49_dialog_content = "Yaitu PlayerName, Vice, Dan Anatoli, juga harus tunduk pada penyelidikan mereka.",
  ui_story_1016_10161501_50_dialog_content = "Apakah kamu serius?!",
  ui_story_1016_10161501_51_dialog_content = "Permintaan...?",
  ui_story_1016_10161501_52_dialog_content = "Ini...",
  ui_story_1016_10161501_53_option_content = "Bagus",
  ui_story_1016_10161501_54_dialog_content = "Saya tidak menyembunyikan apa pun, jadi tanyakan apa pun yang Anda inginkan.",
  ui_story_1016_10161501_55_dialog_content = "Saya percaya pada kepolosan Reinhardt. Dia tidak pernah melakukan kesalahan, sejauh yang saya tahu.",
  ui_story_1016_10161501_56_dialog_content = "Baik.",
  ui_story_1016_10161501_57_option_content = "Dan jika saya menolak?",
  ui_story_1016_10161501_58_dialog_content = "Aku tidak bertanya barusan.",
  ui_story_1016_10161501_59_dialog_content = "Anda tidak punya pilihan lain selain bekerja sama dengan penyelidikan.",
  ui_story_1016_10161501_60_dialog_content = "Apakah itu cara memperlakukan tamu terhormat Illumina?",
  ui_story_1016_10161501_61_dialog_content = "Kapten Wrath?!",
  ui_story_1016_10161501_62_dialog_content = "Baiklah. Vice, PlayerName, dan asisten Reinhardt.",
  ui_story_1016_10161501_63_dialog_content = "Kapten Wrath, Saya harus meminta Anda untuk tidak mengganggu urusan resmi Komite.",
  ui_story_1016_10161501_64_dialog_content = "Aku di sini bukan untuk menghalangi jalanmu. Saya hanya datang untuk mengingatkan Anda bahwa terlalu ketat dengan orang lain dapat berdampak negatif pada pekerjaan Anda.",
  ui_story_1016_10161501_65_dialog_content = "...",
  ui_story_1016_10161501_66_dialog_content = "Maafkan saya jika kata-kata saya terdengar agak kasar.",
  ui_story_1016_10161501_67_dialog_content = "Kami akan sangat menghargai kerja sama Anda dalam masalah yang sangat penting ini.",
  ui_story_1016_10161501_68_dialog_content = "Untuk saat ini, kami dengan rendah hati meminta kalian bertiga tetap di sini di Illumina sampai penyelidikan selesai.",
  ui_story_1016_10161501_69_dialog_content = "...",
  ui_story_1016_10161501_70_dialog_content = "Bukannya kita punya pilihan, kan?",
  ui_story_1016_10161501_71_dialog_content = "Coba pahami.",
  ui_story_1016_10161501_72_dialog_content = "Maka itu menyelesaikannya.",
  ui_story_1016_10161501_73_dialog_content = "PlayerName dan sisanya, tenang saja untuk saat ini. Tidak ada gunanya mengubah ini menjadi konflik yang lebih besar.",
  ui_story_1016_10161501_74_dialog_content = "Baiklah…",
  ui_story_1016_10161501_75_dialog_content = "Jika tidak ada pertanyaan lebih lanjut, semua orang dibubarkan.",
  ui_story_1016_10161501_76_dialog_content = "Dengan cuti Anda, saya masih memiliki hal-hal lain untuk menghadiri. Selamat tinggal.",
  ui_story_1016_10161501_77_dialog_content = "Dia tidak membuang waktu, kan...?",
  ui_story_1016_10161501_78_dialog_content = "Apa yang sebenarnya terjadi saat kita pergi, Kapten Wrath? Mengapa Grand Marshal Reinhardt...",
  ui_story_1016_10161501_79_dialog_content = "Masih belum jelas.",
  ui_story_1016_10161501_80_dialog_content = "Bahkan saya tidak memiliki pemahaman yang jelas tentang apa yang terjadi saat ini.",
  ui_story_1016_10161501_81_dialog_content = "Yang saya tahu adalah saat ini adalah waktu yang salah untuk terlibat konflik langsung dengan Komite.",
  ui_story_1016_10161501_82_dialog_content = "Jika ada, mereka akan senang jika kita menyerang mereka secara terbuka, karena itu hanya akan semakin merusak peluang Reinhard.",
  ui_story_1016_10161501_83_dialog_content = "Apakah dia akan baik-baik saja...?",
  ui_story_1016_10161501_84_dialog_content = "...",
  ui_story_1016_10161501_85_dialog_content = "Percayalah padanya.",
  ui_story_1016_10161501_86_dialog_content = "Wanita Carleen—!",
  ui_story_1016_10161501_87_dialog_content = "Akhirnya aku menemukanmu!",
  ui_story_1016_10161501_88_dialog_content = "Ada apa?",
  ui_story_1016_10161501_89_dialog_content = "Saya baru saja menerima panggilan darurat dari Tuan Kota! Setiap peserta Latihan Gabungan dari Lumopolis, termasuk Anda, harus segera kembali ke Lumopolis!",
  ui_story_1016_10161501_90_dialog_content = "Perintah dari Penguasa Kota...?",
  ui_story_1016_10161501_91_dialog_content = "Dipahami. Beri aku waktu sebentar untuk mengumpulkan barang-barangku dulu.",
  ui_story_1016_10161501_92_dialog_content = "Ya, wanitaku! Kami akan menunggumu!",
  ui_story_1016_10161501_93_dialog_content = "Sepertinya sesuatu yang luar biasa akan terjadi... Atau lebih tepatnya, ini sudah dimulai.",
  ui_story_1016_10161501_94_dialog_content = "Aku akan kembali untuk mencari Joseph dan Zhao, jadi kita bisa merencanakan perjalanan kita kembali ke Twilight.",
  ui_story_1016_10161501_95_dialog_content = "Aku akan pergi sekarang. Semoga beruntung semuanya.",
  ui_story_1016_10161501_96_dialog_content = "Kamu juga...",
  ui_story_1016_10161501_97_dialog_content = "<color=#e8d9bb>Sementara itu, di fasilitas penelitian yang dirahasiakan</color>",
  ui_story_1016_10161501_98_dialog_content = "Hmm? Akhirnya bangun, kan?",
  ui_story_1016_10161501_99_dialog_content = "Vitalitas yang begitu kuat hanya bisa diharapkan dari buah eksperimen Forsakin.",
  ui_story_1016_10161501_100_dialog_content = "Aku ingat kamu...",
  ui_story_1016_10161501_101_dialog_content = "Ulysses. Anda pernah menjadi komandan saya.",
  ui_story_1016_10161501_102_dialog_content = "Anda belum berubah sama sekali.",
  ui_story_1016_10161501_103_dialog_content = "Oh? Jadi, bahkan ingatanmu perlahan mulai pulih?",
  ui_story_1016_10161501_104_dialog_content = "Kejutan yang tak terduga.",
  ui_story_1016_10161501_105_dialog_content = "Betapa menyedihkan, bahwa tingkat kecerdasan Anda masih sangat kurang.",
  ui_story_1016_10161501_106_dialog_content = "...",
  ui_story_1016_10161501_107_dialog_content = "Ada satu hal yang saya masih belum mengerti. Mengapa Anda memilih untuk mengikuti perintah Forsakin ketika Anda jelas tidak berniat melawan kami?",
  ui_story_1016_10161501_108_dialog_content = "Anda bahkan membiarkan diri Anda ditangkap, supaya dia bisa melarikan diri. Mengapa demikian?",
  ui_story_1016_10161501_109_dialog_content = "Aku tidak mengikuti perintahnya.",
  ui_story_1016_10161501_110_dialog_content = "Saya... seorang prajurit Illumina...",
  ui_story_1016_10161501_111_dialog_content = "Perintahku adalah untuk melindungi rekan-rekanku dan orang-orang Illumina.",
  ui_story_1016_10161501_112_dialog_content = "!",
  ui_story_1016_10161501_113_dialog_content = "Ha ha ha! Ini benar-benar kejutan!",
  ui_story_1016_10161501_114_dialog_content = "Aku penasaran, tapi apa yang dia katakan padamu? Apakah dia mengatakan bahwa tindakan Komite adalah alasan dia menjadi seperti sekarang ini?",
  ui_story_1016_10161501_115_dialog_content = "Tidak, tidak, tentu saja tidak. Saya yakin bahwa mengkhianati Illumina dan semua orangnya sepenuhnya adalah keputusannya sendiri.",
  ui_story_1016_10161501_116_dialog_content = "...",
  ui_story_1016_10161501_117_dialog_content = "Keberadaan yang menyedihkan. Hidup dalam kebohongan demi kebohongan, dan tidak pernah meragukannya.",
  ui_story_1016_10161501_118_dialog_content = "Tapi alih-alih memercayai kata-kata Eclipsite yang setengah terbentuk daripada kata-kata sesama Aurorian.",
  ui_story_1016_10161501_119_dialog_content = "Tetap saja, itu seharusnya tidak mengejutkan. Lagi pula, Anda hanyalah produk yang cacat.",
  ui_story_1016_10161501_120_dialog_content = "Hanya sekarang, Anda akhirnya memiliki semacam nilai.",
  ui_story_1016_10161501_121_dialog_content = "<color=#e8d9bb>Tok, tok.</color>",
  ui_story_1016_10161501_122_dialog_content = "Memasuki.",
  ui_story_1016_10161501_123_dialog_content = "Pak.",
  ui_story_1016_10161501_124_dialog_content = "Apakah saya tidak sepenuhnya jelas? Saya sedang melakukan eksperimen penting, dan tidak seorang pun boleh mengganggu saya saat ini.",
  ui_story_1016_10161501_125_dialog_content = "Maafkan saya, tetapi Anda memiliki tamu yang sangat penting di sini untuk menemui Anda.",
  ui_story_1016_10161501_126_dialog_content = "<color=#FFB400>Topeng Besi</color>, ya? Heheheh... Kurasa wajar jika dia ingin melihatku.",
  ui_story_1016_10161501_127_dialog_content = "<color=#e8d9bb>Beberapa saat kemudian, di suatu tempat di Kota Gannon</color>",
  ui_story_1016_10161501_128_dialog_content = "Biar saya tebak: Anda datang untuk menanyai saya?",
  ui_story_1016_10161501_129_dialog_content = "Melakukannya sekarang akan membuatku tidak sabar.",
  ui_story_1016_10161501_130_dialog_content = "Saya datang ke sini hari ini dengan satu motif: untuk meminta bantuan Anda mengkonfirmasi kecurigaan saya.",
  ui_story_1016_10161501_131_dialog_content = "Tapi kecurigaanmu selalu benar, bukan?",
  ui_story_1016_10161501_132_dialog_content = "Ampuni aku sanjunganmu. Itu tidak ada gunanya bagi kita.",
  ui_story_1016_10161501_133_dialog_content = "Setuju.",
  ui_story_1016_10161501_134_dialog_content = "Nah, izinkan saya untuk meringkas rencana sejauh ini.",
  ui_story_1016_10161501_135_dialog_content = "Intinya, rencananya adalah untuk menggulingkan Reinhardt dengan menggunakan barang-barang buangan Eclipse untuk menimbulkan kepanikan, lalu menyuruh orang-orangmu mengendalikan situasi.",
  ui_story_1016_10161501_136_dialog_content = "Sayangnya, Eclipse tidak hanya menginginkan Forsakin dan subjek tesnya kembali, mereka juga menginginkan inti Guardian One.",
  ui_story_1016_10161501_137_dialog_content = "Selain itu, sekelompok pengganggu yang tidak disukai sekarang sangat mengetahui rencana tersebut.",
  ui_story_1016_10161501_138_dialog_content = "Siapa itu?",
  ui_story_1016_10161501_139_dialog_content = "<color=#FFB400>Senja</color>.",
  ui_story_1016_10161501_140_dialog_content = "Tim dari Twilight itu mengetahui rencanamu, itulah sebabnya mereka menyerahkan kemenangan kepada bawahanmu.",
  ui_story_1016_10161501_141_dialog_content = "Mungkinkah ... seseorang membocorkan rencana itu kepada mereka?",
  ui_story_1016_10161501_142_dialog_content = "Ada kemungkinan lain. Sebagai permulaan...",
  ui_story_1016_10161501_143_dialog_content = "Bawahanmu tidak pernah bertarung dengan kekuatan penuh.",
  ui_story_1016_10161501_144_dialog_content = "Peralatan mereka di fase akhir tidak sesuai dengan kredit mereka.",
  ui_story_1016_10161501_145_dialog_content = "Dan mereka diberikan semua jawaban atas pertanyaan di fase akademik sebelumnya.",
  ui_story_1016_10161501_146_dialog_content = "...",
  ui_story_1016_10161501_147_dialog_content = "Tindakan Anda terlalu jelas.",
  ui_story_1016_10161501_148_dialog_content = "Sekecil apa pun, ada alasan mengapa Illumina dan Lumopolis tidak mau memprovokasi kota Twilight.",
  ui_story_1016_10161501_149_dialog_content = "Sekarang setelah mereka memiliki inisiatif, mereka telah menjadi variabel di fase akhir rencana kami.",
  ui_story_1016_10161501_150_dialog_content = "Tugas Anda sekarang adalah memastikan bahwa mereka menjadi variabel yang dikendalikan.",
  ui_story_1016_10161501_151_dialog_content = "Tidak hanya itu, Anda harus mengambil konsol inti Guardian One sesegera mungkin.",
  ui_story_1016_10161501_152_dialog_content = "Saya lebih suka memainkan game ini sebaik mungkin, daripada memiliki ketidakpastian karena terlalu banyak variabel yang memengaruhi kinerja saya.",
  ui_story_1016_10161501_153_dialog_content = "Begitu... Kalau begitu aku akan melakukan itu.",
  ui_story_1016_10161501_154_dialog_content = "Hmph. Anda tampaknya cukup percaya diri dengan eksperimen Anda, Ulysses.",
  ui_story_1016_10161501_155_dialog_content = "Tapi tentu saja.",
  ui_story_1016_10161501_156_dialog_content = "Setelah saya sepenuhnya menganalisis penelitian Forsakin, itu akan menghasilkan terobosan teknologi terbesar yang telah dilihat oleh Federasi Illumina selama bertahun-tahun.",
  ui_story_1016_10161501_157_dialog_content = "Dengan pengetahuan ini, kita akan dapat menggunakan Chord Link di Undercity X untuk memproduksi tentara super secara massal.",
  ui_story_1016_10161501_158_dialog_content = "Lagi pula, apakah itu dari Program Phospherus atau Project Artificial Sun, kami memiliki banyak mata pelajaran untuk dipilih.",
  ui_story_1016_10161501_159_dialog_content = "Segera, kekuatan Federasi Illumina akan tumbuh pesat.",
  ui_story_1016_10161501_160_dialog_content = "Maka Anda sebaiknya cepat. Waktu adalah sumber daya yang jauh lebih berharga daripada cahaya.",
  ui_story_1016_10161501_161_dialog_content = "Satu hal terakhir. Pada akhirnya, apa yang Anda lakukan tidak lebih dari menjiplak karya Forsakin.",
  ui_story_1016_10161501_162_dialog_content = "Akankah integritas Anda sebagai peneliti profesional memungkinkan Anda melakukan ini?",
  ui_story_1016_10161501_163_dialog_content = "Tidak masalah.",
  ui_story_1016_10161501_164_dialog_content = "Untuk memastikan kelangsungan peradaban kita, kita harus siap melakukan apapun yang diperlukan.",
  ui_story_1016_10161501_165_dialog_content = "<color=#e8d9bb>Beberapa hari kemudian, di Pusat Medis Kota Gannon</color>",
  ui_story_1016_10161501_166_dialog_content = "(Sudah beberapa hari sejak akhir pertandingan final, tapi Axelia masih belum bangun)",
  ui_story_1016_10161501_167_dialog_content = "(Sepertinya dia hampir menghancurkan tubuhnya lagi kali ini.)",
  ui_story_1016_10161501_168_dialog_content = "(Syukurlah, para dokter dan peneliti dapat memperbaiki tubuhnya dengan cepat, berdasarkan pengalaman mereka sebelumnya.)",
  ui_story_1016_10161501_169_dialog_content = "(Sayangnya, tingkat kerusakannya berarti tidak ada yang tahu kapan dia akan bangun.)",
  ui_story_1016_10161501_170_dialog_content = "Nng...",
  ui_story_1016_10161501_171_dialog_content = "Axelia?!",
  ui_story_1016_10161501_172_dialog_content = "Rasanya... Aku baru saja terbangun dari mimpi panjang.",
  ui_story_1016_10161501_173_dialog_content = "Kau... Kau akhirnya bangun...",
  ui_story_1016_10161501_174_dialog_content = "Selamat pagi, Yingel.",
  ui_story_1016_10161501_175_dialog_content = "Anda terlihat lelah.",
  ui_story_1016_10161501_176_dialog_content = "Benar-benar? Mungkin sedikit...",
  ui_story_1016_10161501_177_dialog_content = "Bagaimana perasaanmu? Apakah ada yang sakit?",
  ui_story_1016_10161501_178_dialog_content = "Saya merasa sangat normal.",
  ui_story_1016_10161501_179_dialog_content = "Tapi aku masih membutuhkan lebih banyak waktu sebelum fungsi tempurku pulih.",
  ui_story_1016_10161501_180_dialog_content = "Jangan khawatir tentang pertempuran sekarang. Anda hanya beruntung masih hidup, Axelia.",
  ui_story_1016_10161501_181_dialog_content = "...",
  ui_story_1016_10161501_182_dialog_content = "Reinhardt mengatakan sesuatu yang mirip dengan saya selama pertempuran kami.",
  ui_story_1016_10161501_183_dialog_content = "Kudengar dia secara sukarela menyerah...",
  ui_story_1016_10161501_184_dialog_content = "Itulah alasan kamu masih hidup.",
  ui_story_1016_10161501_185_dialog_content = "Yang mengingatkan saya, inilah medali kemenangan Anda.",
  ui_story_1016_10161501_186_dialog_content = "Illumina berada dalam keadaan kacau akhir-akhir ini, dan dengan ketidaksadaranmu, tidak ada kesempatan untuk mengadakan upacara penghargaan yang layak.",
  ui_story_1016_10161501_187_dialog_content = "Jadi ini harus dilakukan.",
  ui_story_1016_10161501_188_dialog_content = "Medali ini... rasanya berat.",
  ui_story_1016_10161501_189_dialog_content = "...",
  ui_story_1016_10161501_190_dialog_content = "Yingel? Dapatkah saya mengajukan pertanyaan?",
  ui_story_1016_10161501_191_dialog_content = "Ada apa?",
  ui_story_1016_10161501_192_dialog_content = "Selama pertempuran kami, Reinhardt mengatakan sesuatu padaku—",
  ui_story_1016_10161501_193_dialog_content = "Bahwa dia ingin aku hidup sebagai pribadi.",
  ui_story_1016_10161501_194_dialog_content = "Bisakah Anda memberi tahu saya apa artinya <color=#FFB400>hidup sebagai pribadi</color>?",
  ui_story_1017_10170101_1_dialog_content = "Bisa dengar saya, Grand Marshal?",
  ui_story_1017_10170101_2_dialog_content = "Saya bisa.",
  ui_story_1017_10170101_3_dialog_content = "Ayo kita mulai.",
  ui_story_1017_10170101_4_dialog_content = "Saya Nemesis, Inspektur Jenderal dari Illumina Federation, hakim yang memimpin untuk kasus ini.",
  ui_story_1017_10170101_5_dialog_content = "Saya akan mengawasi persidangan internal ketiga mengenai tuduhan Anda membantu dan melindungi musuh serta buronan, sesuai dengan hukum Federasi Illumina.",
  ui_story_1017_10170101_6_dialog_content = "Berdasarkan Undang-Undang Investigasi Illumina Federation, kamu memiliki hak—",
  ui_story_1017_10170101_7_dialog_content = "Lewati omong kosongnya.",
  ui_story_1017_10170101_8_dialog_content = "Maka kami akan memulai proses resmi. Apakah Anda ingin memberikan pernyataan mengenai dakwaan yang diajukan oleh Ulysses terhadap Anda?",
  ui_story_1017_10170101_9_dialog_content = "Saya akan mengulangi bahwa saya benar-benar tidak mengetahui Forsakin bersembunyi di Gannon selama latihan militer.",
  ui_story_1017_10170101_10_dialog_content = "Tidak ada bentuk penyuruhan sama sekali antara aku dan dia.",
  ui_story_1017_10170101_11_dialog_content = "Mengingat Anda telah mempertahankan pernyataan ini dalam ketiga sesi interogasi, saya tidak dapat memberikan keputusan yang menguntungkan bagi Anda.",
  ui_story_1017_10170101_12_dialog_content = "Bukankah ini yang kalian semua inginkan?",
  ui_story_1017_10170101_13_dialog_content = "Mari kita jujur satu sama lain. Apa tujuan akhir kamu?",
  ui_story_1017_10170101_14_dialog_content = "Saya ingin memberikan kesaksian tambahan, Yang Mulia.",
  ui_story_1017_10170101_15_dialog_content = "Iya.",
  ui_story_1017_10170101_16_dialog_content = "Berdasarkan laporan intelijen, sebelum latihan, Forsakin dan Reinhardt membuat perjanjian berikut secara langsung di Institut X:",
  ui_story_1017_10170101_17_dialog_content = "Reinhardt berjanji akan membiarkan Forsakin pergi asalkan Helios tetap tinggal di belakang.",
  ui_story_1017_10170101_18_dialog_content = "Yingel dan Anatoli bisa membuktikannya.",
  ui_story_1017_10170101_19_dialog_content = "Yang Mulia—",
  ui_story_1017_10170101_20_dialog_content = "<size=30>Jangan mengganggu, Wrath.</size>",
  ui_story_1017_10170101_21_dialog_content = "Tolong berikan kesaksian, Kolonel Yingel.",
  ui_story_1017_10170101_22_dialog_content = "Anda hanya perlu memberi tahu hakim apakah Forsakin membuat kesepakatan dengan Reinhardt.",
  ui_story_1017_10170101_23_dialog_content = "... Iya.",
  ui_story_1017_10170101_24_dialog_content = "Kenapa kamu-",
  ui_story_1017_10170101_25_dialog_content = "Diam, berbicara di luar giliran hanya akan memperburuk situasi bagi Grand Marshal.",
  ui_story_1017_10170101_26_dialog_content = "Menyusul kesepakatan tersebut, tergugat memilih untuk bertindak pasif karena pertalian lama.",
  ui_story_1017_10170101_27_dialog_content = "Dia memerintahkan bala bantuan untuk membantu pelarian buronan, yang mengakibatkan pencurian inti Guardian One.",
  ui_story_1017_10170101_28_dialog_content = "Apakah Anda mengaku bersalah atas hal itu, Grand Marshal?",
  ui_story_1017_10170101_29_dialog_content = "Saya sebagian bertanggung jawab atas pencurian inti ini, tapi tunjukkan bukti untuk tuduhan lainnya.",
  ui_story_1017_10170101_30_dialog_content = "Anatoli.",
  ui_story_1017_10170101_31_dialog_content = "Ya, Tuan?",
  ui_story_1017_10170101_32_dialog_content = "Apakah Reinhardt memberitahu Forsakin dan Helios bahwa, \"Saya datang untuk menjemput kalian, dan saya membawa bala bantuan?\"",
  ui_story_1017_10170101_33_dialog_content = "...",
  ui_story_1017_10170101_34_dialog_content = "Ya atau tidak?",
  ui_story_1017_10170101_35_dialog_content = "Ya…",
  ui_story_1017_10170101_36_dialog_content = "Buat pembelaanmu mengenai kesaksian itu, Grand Marshal.",
  ui_story_1017_10170101_37_dialog_content = "...",
  ui_story_1017_10170101_38_dialog_content = "Saya mengistirahatkan kasus saya, Yang Mulia.",
  ui_story_1017_10170101_39_dialog_content = "(Ini bukan cara kejadiannya...)",
  ui_story_1017_10170101_40_dialog_content = "(Tunggu sebentar, jika Kolonel Yingel dan saya adalah saksi-saksinya...)",
  ui_story_1017_10170101_41_dialog_content = "Apakah Anda mengaku bersalah atas tuduhan yang disebutkan, Grand Marshal? Apakah Anda memiliki sesuatu yang lain untuk dikatakan?",
  ui_story_1017_10170101_42_dialog_content = "Heh, aku akui kelalaianku yang menyebabkan kekacauan di Illumina saat ini!",
  ui_story_1017_10170101_43_dialog_content = "Jadi jika kau ingin pernyataan dariku—",
  ui_story_1017_10170101_44_dialog_content = "Hahaha!",
  ui_story_1017_10170101_45_dialog_content = "Itu saja yang ingin saya katakan, Yang Mulia. Silakan menjatuhkan hukuman kepada saya.",
  ui_story_1017_10170101_46_dialog_content = "...",
  ui_story_1017_10170101_47_dialog_content = "Menyusul penutupan persidangan ketiga dari Reinhardt, dengan ini saya menyatakan...",
  ui_story_1017_10170101_48_dialog_content = "Mantan Marsekal Agung Reinhardt dari Federasi Illumina dituduh melakukan hal-hal berikut:",
  ui_story_1017_10170101_49_dialog_content = "Menyalahgunakan posisi dan kekuatannya untuk melakukan perjanjian rahasia dengan buronan Forsakin, yang telah menyusup ke Undercity milik Illumina.",
  ui_story_1017_10170101_50_dialog_content = "Tindakan tersebut kemudian menyebabkan inti Guardian One dicuri, 78 prajurit Illumina dan anggota keluarga mereka mengalami luka, dan berakibat pada penempatan keamanan federal dalam posisi rentan.",
  ui_story_1017_10170101_51_dialog_content = "Terdakwa mengaku bersalah karena kelalaian.",
  ui_story_1017_10170101_52_dialog_content = "Namun, bukti yang ada tidak cukup untuk mendukung tuduhan membantu musuh. Sidang lanjutan akan dilakukan ketika syarat-syarat untuk persidangan terpenuhi, atau ketika kedua belah pihak dapat menghasilkan bukti yang cukup.",
  ui_story_1017_10170101_53_dialog_content = "Berdasarkan Undang-Undang Investigasi Federasi Illumina, Departemen Kehakiman memberikan putusan sebagai berikut:",
  ui_story_1017_10170101_54_dialog_content = "Terdakwa akan dicopot dari posisi sebagai Grand Marshal.",
  ui_story_1017_10170101_55_dialog_content = "Terdakwa akan dicabut semua hak yang diberikan kepada seorang prajurit Illumina.",
  ui_story_1017_10170101_56_dialog_content = "Terdakwa akan ditahan, berlaku segera.",
  ui_story_1017_10170101_57_dialog_content = "Ditunda.",
  ui_story_1017_10170101_58_dialog_content = "Dia keluar, dia keluar!",
  ui_story_1017_10170101_59_dialog_content = "M-Mbak!",
  ui_story_1017_10170101_60_dialog_content = "Ah...",
  ui_story_1017_10170101_61_dialog_content = "<size=30>Siapa dia?</size>",
  ui_story_1017_10170101_62_dialog_content = "Petugas Belisaria. Dia memiliki banyak kekuasaan atas Komite.",
  ui_story_1017_10170101_63_dialog_content = "Saya sangat gugup, saya lupa memberi hormat.",
  ui_story_1017_10170101_64_option_content = "Kau membuatku tegang.",
  ui_story_1017_10170101_65_option_content = "Kamu sudah selesai.",
  ui_story_1017_10170101_66_dialog_content = "Sedikit optimisme akan sangat dihargai, terima kasih.",
  ui_story_1017_10170101_67_dialog_content = "Yah, sudah terlambat untuk kamu memberi hormat sekarang.",
  ui_story_1017_10170101_68_dialog_content = "...",
  ui_story_1017_10170101_69_dialog_content = "Jika dia juga muncul... Aku ingin tahu apakah ada kemungkinan perkembangan positif untuk Grand Marshal.",
  ui_story_1017_10170101_70_dialog_content = "Aku merindukanmu tadi.",
  ui_story_1017_10170101_71_dialog_content = "Kamu pasti Caelestite, 'kan?",
  ui_story_1017_10170101_72_dialog_content = "Ya... Bu.",
  ui_story_1017_10170101_73_dialog_content = "Officer Belisaria!",
  ui_story_1017_10170101_74_dialog_content = "Aku dengar kamu, Caelestite, dan teman Lumopolis-mu ikut dalam Latihan Militer Gabungan.",
  ui_story_1017_10170101_75_dialog_content = "Ya, Bu.",
  ui_story_1017_10170101_76_dialog_content = "Heheh, lumayan...",
  ui_story_1017_10170101_77_dialog_content = "Aku merasa ada perasaan yang tak bisa dijelaskan tentang kalian berdua.",
  ui_story_1017_10170101_78_dialog_content = "Sebentar lagi, kamu akan menguji firasatku.",
  ui_story_1017_10170101_79_dialog_content = "Maafkan aku sekarang, Caelestite. Pertemuan kita berikutnya akan dalam suasana resmi.",
  ui_story_1017_10170101_80_dialog_content = "...",
  ui_story_1017_10170101_81_dialog_content = "I-Itu membuatku ketakutan...",
  ui_story_1017_10170101_82_dialog_content = "Setidaknya kali ini kamu memberi hormat.",
  ui_story_1017_10170101_83_dialog_content = "Tapi dia terus memandang kami dengan aneh.",
  ui_story_1017_10170101_84_dialog_content = "Mungkin aku bereaksi berlebihan...",
  ui_story_1017_10170101_85_dialog_content = "Hei, para jenderal—Komandan Hiiro!",
  ui_story_1017_10170101_86_dialog_content = "...",
  ui_story_1017_10170101_87_dialog_content = "Ini mungkin bukan tempat yang tepat untuk berbicara.",
  ui_story_1017_10170101_88_dialog_content = "Mereka semua terlihat sangat serius...",
  ui_story_1017_10170101_89_dialog_content = "PlayerName, Letnan Vice.",
  ui_story_1017_10170101_90_dialog_content = "Anatoli! Bagaimana kabarnya?",
  ui_story_1017_10170101_91_dialog_content = "...",
  ui_story_1017_10170101_92_dialog_content = "Ayo bicara di tempat yang tenang.",
  ui_story_1017_10170101_93_dialog_content = "Komandan, Eclipsite di sepanjang perbatasan mulai bergerak. Situasi ini telah berlangsung selama beberapa hari sekarang.",
  ui_story_1017_10170101_94_dialog_content = "Kami sudah meminta <color=#FFB400>Tim Pengintaian Dark Zone</color> menyesuaikan penyelidikan mereka berdasarkan data yang terdeteksi.",
  ui_story_1017_10170101_95_dialog_content = "Dengan membandingkan data historis dengan data yang kita miliki sekarang, sangat jelas bahwa <color=#FFB400>gangguan aurora</color> lebih sering terjadi daripada sebelumnya dalam 20 tahun terakhir.",
  ui_story_1017_10170101_96_dialog_content = "Yang bisa berarti bahwa Eclipse sedang mempersiapkan potensi Darkover Crisis.",
  ui_story_1017_10170101_97_dialog_content = "Kalian semua dengar itu?",
  ui_story_1017_10170101_98_dialog_content = "Ketika Darkover Crisis terakhir melanda, kami juga yang duduk di sini.",
  ui_story_1017_10170101_99_dialog_content = "Bertahun-tahun telah berlalu sejak itu, dan kami pun menjadi diam.",
  ui_story_1017_10170101_100_dialog_content = "Apakah gelombang Darkover ada hubungannya dengan pencurian inti Guardian One?",
  ui_story_1017_10170101_101_dialog_content = "Jelas, mengingat apa yang telah dilakukan Eclipse.",
  ui_story_1017_10170101_102_dialog_content = "Tapi kali ini, mereka berhasil mendapatkan inti Guardian One, yang mengubah keadaan.",
  ui_story_1017_10170101_103_dialog_content = "Bagaimana tracking-nya?",
  ui_story_1017_10170101_104_dialog_content = "Kamu dengar laporannya, sebuah Tim Rekayasa Elit Dark Zone telah dikirim.",
  ui_story_1017_10170101_105_dialog_content = "Tim Pengintaian Elite Zona Gelap?",
  ui_story_1017_10170101_106_dialog_content = "Jika Anda maksudkan dia, maka saya kira itu memang tim elit.",
  ui_story_1017_10170101_107_dialog_content = "Bukankah tanggung jawab Esien untuk melacak Wraith dan mengambil kembali Guardian One?",
  ui_story_1017_10170101_108_dialog_content = "Kalau dia bisa melakukannya, aku tak akan mengirim Pepita.",
  ui_story_1017_10170101_109_dialog_content = "Maksudmu tahanan yang membelot dari Illumina dan bergabung dengan True Order?",
  ui_story_1017_10170101_110_dialog_content = "Tahanan?",
  ui_story_1017_10170101_111_dialog_content = "Tidakkah kalian semua bereaksi berlebihan?",
  ui_story_1017_10170101_112_dialog_content = "Dia seharusnya sudah di balik jeruji besi sekarang.",
  ui_story_1017_10170101_113_dialog_content = "Beberapa kartu sebaiknya disimpan dekat hingga saat Anda membutuhkannya.",
  ui_story_1017_10170101_114_dialog_content = "Dia memiliki pengalaman dalam infiltrasi Dark Zone. Dalam beberapa hal, hanya dia yang dapat menyelesaikan misi ini.",
  ui_story_1017_10170101_115_dialog_content = "Belisaria, komite tidak pernah memberikanmu otoritas untuk melatih tentara bayaran pribadi tanpa izin.",
  ui_story_1017_10170101_116_dialog_content = "Tapi, tugas saya untuk merehabilitasi tahanan dan memanfaatkannya.",
  ui_story_1017_10170101_117_dialog_content = "Kapan tim lainnya pergi?",
  ui_story_1017_10170101_118_dialog_content = "Komandan, informasi tim sudah tersusun rapi, dan Anda bisa mengeluarkan perintah kapan saja siap. Mereka siap untuk berangkat besok pagi paling cepat.",
  ui_story_1017_10170101_119_dialog_content = "Ada tim lain?",
  ui_story_1017_10170101_120_dialog_content = "Hasil penyelidikan kami menunjukkan bahwa Letnan Vice memiliki hubungan yang menarik dengan salah satu anggota Eclipse yang menyusup ke Gannon.",
  ui_story_1017_10170101_121_dialog_content = "Selain itu, ketiga anggota Umbraton yang berpartisipasi dalam latihan militer juga memberikan petunjuk dengan berbagai tingkatan.",
  ui_story_1017_10170101_122_dialog_content = "Mempertimbangkan semua hal, kami pikir mereka mungkin bisa melacak inti dari Guardian One.",
  ui_story_1017_10170101_123_dialog_content = "Kami membentuk tim sementara untuk mendukung Tim Pengintaian Dark Zone.",
  ui_story_1017_10170101_124_dialog_content = "Ayo, kamu nggak percaya kan kalau ketiga badut itu berasal dari Umbraton?",
  ui_story_1017_10170101_125_dialog_content = "Jangan dibohongi, Topeng Besi.",
  ui_story_1017_10170101_126_dialog_content = "Saya menawarkan tumpangan kepada mereka karena saya tahu mereka akan berguna.",
  ui_story_1017_10170101_127_dialog_content = "Mengapa kita tidak mendengar kabar terbaru dari kamu, Ulysses. Bagaimana perkembangan senjatamu?",
  ui_story_1017_10170101_128_dialog_content = "Prototipe eksperimental Forsakin telah diautopsi. Saya pikir saatnya untuk menghidupkan kembali Program Phospherus.",
  ui_story_1017_10170101_129_dialog_content = "Dengan Program Phospherus 2.0, kekuatan tempur Aurorian akan mengalami peningkatan yang signifikan.",
  ui_story_1017_10170101_130_dialog_content = "Jadi sekarang adalah waktu yang sempurna untuk memilih Grand Marshal berikutnya.",
  ui_story_1017_10170101_131_dialog_content = "Ada kandidat yang cocok?",
  ui_story_1017_10170101_132_dialog_content = "Ini adalah tautan terlemah dari proyek ini.",
  ui_story_1017_10170101_133_dialog_content = "Aku sangat khawatir Krisis Darkover berikutnya akan menimpa kita dan kita akan merasa tak berdaya.",
  ui_story_1017_10170101_134_dialog_content = "Kandidatnya adalah bagian terlemah?",
  ui_story_1017_10170101_135_dialog_content = "Saya tidak setuju.",
  ui_story_1017_10170101_136_dialog_content = "Pengaruh Reinhardt yang dibangun selama bertahun-tahun ternyata jauh melampaui ekspektasi.",
  ui_story_1017_10170101_137_dialog_content = "Situasi saat ini merupakan konsekuensi langsung dari \"Program Phospherus.\" Haruskah kita benar-benar melanjutkannya?",
  ui_story_1017_10170101_138_dialog_content = "Tidak cukup bukti dari interogasi Reinhardt untuk menghukumnya. Pemecatannya kemungkinan bersifat sementara.",
  ui_story_1017_10170101_139_dialog_content = "Dr. Ulysses, sebaliknya... kau tidak terlalu percaya diri?",
  ui_story_1017_10170101_140_dialog_content = "Tidak ada gunanya membahas hal yang sudah menjadi kesimpulan pasti.",
  ui_story_1017_10170101_141_dialog_content = "Jika Anda memiliki masalah, ikuti jalur yang tepat dan ajukan gugatan.",
  ui_story_1017_10170101_142_dialog_content = "Ulysses, sesekali Anda harus meninggalkan penelitian Anda dan mencicipi apa yang terjadi di luar tembok ini.",
  ui_story_1017_10170101_143_dialog_content = "Katakan kamu ingin daging. Apakah kamu akan meminta ternak untuk berjalan sendiri ke rumah pemotongan?",
  ui_story_1017_10170101_144_dialog_content = "Jika kamu ingin memamerkan \"senjata pamungkas\"mu, silakan saja. Saya tidak masalah dengan itu.",
  ui_story_1017_10170101_145_dialog_content = "Tapi saat menyangkut pemilihan Grand Marshal berikutnya, mungkin lebih bijaksana untuk, seperti yang Anda katakan, mengikuti jalur yang tepat.",
  ui_story_1017_10170101_146_dialog_content = "Cukup. Di Illumina, kami selalu mengutamakan penyelesaian masalah publik daripada perselisihan pribadi.",
  ui_story_1017_10170101_147_dialog_content = "Mengingat semua orang ada di sini, kita harus membahas kandidat Grand Marshal.",
  ui_story_1017_10170101_148_dialog_content = "Apakah semua file sudah terkirim?",
  ui_story_1017_10170101_149_dialog_content = "Ya. Para komandan terhormat, di hadapan Anda adalah berkas terperinci tentang personel militer mulai dari pangkat kolonel ke atas.",
  ui_story_1017_10170101_150_dialog_content = "Jaringan hubungan pribadi mereka dan evaluasi dari rekan kerja juga termasuk di dalamnya.",
  ui_story_1017_10170101_151_dialog_content = "Ketika Illumina didirikan, ada keputusan bulat bahwa prajurit terkuat harus mengisi peran sebagai Grand Marshal.",
  ui_story_1017_10170101_152_dialog_content = "Seiring waktu, ini berubah menjadi aturan tak tertulis bahwa kandidat Grand Marshal harus menjalani peningkatan fisik.",
  ui_story_1017_10170101_153_dialog_content = "Saya tidak keberatan dengan Program Phospherus 2.0. Tetapi jika menyangkut kemampuan murni, hanya keempat jenderal itu yang pantas menjadi Grand Marshal.",
  ui_story_1017_10170101_154_dialog_content = "Jika kita hanya akan mengembangkan Reinhardt lain dari antara mereka, apa gunanya menggantikan Grand Marshal sejak awal?",
  ui_story_1017_10170101_155_dialog_content = "Bukankah memilih salah satu dari mereka sebagai Grand Marshal itu seperti menembak kaki kita sendiri?",
  ui_story_1017_10170101_156_dialog_content = "Bagaimana menurutmu, Ulysses?",
  ui_story_1017_10170101_157_dialog_content = "...",
  ui_story_1017_10170101_158_dialog_content = "Dari keempat orang itu, ada satu yang sesuai dengan kriteria...",
  ui_story_1017_10170201_1_dialog_content = "Siapa pun yang di luar, silakan masuk.",
  ui_story_1017_10170201_2_dialog_content = "Uh, salam, Komandan Hiiro, dan semua yang lain!",
  ui_story_1017_10170201_3_dialog_content = "Halo, para petugas.",
  ui_story_1017_10170201_4_dialog_content = "Maaf mengganggu. Saya di sini untuk menemui Komandan Hiiro, tetapi saya tidak menyangka kalian semua ada di sini...",
  ui_story_1017_10170201_5_dialog_content = "Kami mendengar tentang Grand Marshal dan kami ingin—",
  ui_story_1017_10170201_X5_dialog_content = "<color=#e8d9bb>Bip — Bip —</color>",
  ui_story_1017_10170201_6_dialog_content = "...",
  ui_story_1017_10170201_7_dialog_content = "Semuanya, perintah telah tiba untuk memanggil kita kembali ke zona perang.",
  ui_story_1017_10170201_8_dialog_content = "Begitu cepat?",
  ui_story_1017_10170201_9_dialog_content = "Aku juga dapat, dan belum pernah melihat deskripsi tugas yang begitu singkat sebelumnya.",
  ui_story_1017_10170201_10_dialog_content = "Sama.",
  ui_story_1017_10170201_11_dialog_content = "Hmph, khawatir kami berkomplot untuk memberontak bersama, ya?",
  ui_story_1017_10170201_12_dialog_content = "Aku menjadi jenderal Federasi dengan berperang. Aku baik-baik saja dengan bermain keras!",
  ui_story_1017_10170201_13_dialog_content = "Demi kehati-hatian, mari kita lakukan tugas masing-masing secara terpisah untuk saat ini. Kita akan mengikuti situasinya.",
  ui_story_1017_10170201_14_dialog_content = "Tentu.",
  ui_story_1017_10170201_15_dialog_content = "Bagaimana dengan kamu, Wrath?",
  ui_story_1017_10170201_X15_dialog_content = "Hah, apa?",
  ui_story_1017_10170201_X16_dialog_content = "Kamu juga sudah menerima perintahnya, kan?",
  ui_story_1017_10170201_X17_dialog_content = "... Legiun Pengawalku selama ini hanya untuk pameran saja. Kalianlah yang akan menjadi pasukan terdepan, bagaimanapun juga.",
  ui_story_1017_10170201_X18_dialog_content = "Kabar-kabari kalau ada apa-apa ya. Jaga diri.",
  ui_story_1017_10170201_X19_dialog_content = "Baiklah, jaga diri.",
  ui_story_1017_10170201_16_dialog_content = "Saya? <color=#FFB400>Legiun Pengawal saya hanyalah kedok saja, anyway</color>. Kalian yang akan bertindak lebih dulu. Saya tidak akan meninggalkan Gannon dalam waktu dekat.",
  ui_story_1017_10170201_17_dialog_content = "Baiklah, jaga diri.",
  ui_story_1017_10170201_18_dialog_content = "...",
  ui_story_1017_10170201_19_dialog_content = "Mereka semua pergi.",
  ui_story_1017_10170201_20_dialog_content = "Apa yang terjadi? Bahkan Commander Hiiro juga...",
  ui_story_1017_10170201_21_dialog_content = "Menurut kamu, apa yang sedang mereka bahas?",
  ui_story_1017_10170201_22_option_content = "Pemberontakan",
  ui_story_1017_10170201_23_dialog_content = "Aku bisa merasakan ketegangan yang sangat kuat antara mereka dan pihak yang berkuasa.",
  ui_story_1017_10170201_24_dialog_content = "Mereka mungkin khawatir akan reaksi setelah apa yang terjadi pada Grand Marshal...",
  ui_story_1017_10170201_25_dialog_content = "Sst! Hati-hati dengan apa yang kamu ucapkan keras-keras!",
  ui_story_1017_10170201_26_option_content = "Menyelamatkan Grand Marshal",
  ui_story_1017_10170201_27_dialog_content = "Grand Marshal dijebak. Para komandan pasti ingin membebaskannya dengan cara apa pun.",
  ui_story_1017_10170201_28_dialog_content = "Dalam hal ini, apa yang bisa kita lakukan...?",
  ui_story_1017_10170201_29_option_content = "Tidak yakin",
  ui_story_1017_10170201_30_dialog_content = "Mereka pergi dengan tergesa-gesa. Pasti bukan untuk hal yang baik.",
  ui_story_1017_10170201_31_dialog_content = "Huh, sepertinya kita datang sia-sia ya...",
  ui_story_1017_10170201_32_dialog_content = "*Terengah-engah* Itu dia, Vice!",
  ui_story_1017_10170201_33_dialog_content = "Ada misi mendesak untuk kamu!",
  ui_story_1017_10170201_34_dialog_content = "Apakah mereka rekan tim yang akan pergi bersamamu?",
  ui_story_1017_10170201_35_dialog_content = "Vivian pergi dengan terburu-buru. Dia hanya memberi tahu kita apa yang harus dilakukan dan menghilang.",
  ui_story_1017_10170201_36_dialog_content = "Ya, dia terlihat cemas. Perubahan besar akan datang ke Illumina, kubayangkan.",
  ui_story_1017_10170201_37_dialog_content = "Banyak yang terjadi... Aku tak bisa memahaminya saat ini.",
  ui_story_1017_10170201_38_dialog_content = "Dan sekarang aku bahkan mendengar siulan aneh...",
  ui_story_1017_10170201_39_dialog_content = "Aku juga mendengarnya.",
  ui_story_1017_10170201_40_dialog_content = "Aku telah menunggu kalian, penumpang Acheron Ferryman.",
  ui_story_1017_10170201_41_dialog_content = "Perwira Charon! Jadi saya dalam misi ini bersama Anda?",
  ui_story_1017_10170201_42_dialog_content = "Halo, Vice, dan kamu juga, Caelestite.",
  ui_story_1017_10170201_43_dialog_content = "Halo, Vice, dan kamu juga, Caelestite.",
  ui_story_1017_10170201_44_dialog_content = "Halo, Vice, dan kamu juga, Caelestite.",
  ui_story_1017_10170201_45_dialog_content = "Geng ini akhirnya berkumpul semua—Ehem, salam, semuanya.",
  ui_story_1017_10170201_46_dialog_content = "Bagaimana kalian bisa masuk ke sini?",
  ui_story_1017_10170201_47_dialog_content = "Tidak menyangka, bukan? Kami adalah anggota resmi dari <color=#FFB400>Tim Pelacak</color>!",
  ui_story_1017_10170201_48_dialog_content = "Ya, sangat menyenangkan memiliki kesempatan untuk bepergian bersama semua orang!",
  ui_story_1017_10170201_49_dialog_content = "Ada apa ini, Officer Charon?",
  ui_story_1017_10170201_50_dialog_content = "Semua tiga di antara mereka adalah teman yang diundang untuk menaiki Acheron Ferryman seperti kamu.",
  ui_story_1017_10170201_51_dialog_content = "Kawan?",
  ui_story_1017_10170201_52_dialog_content = "Iya, tapi kamu tidak ada di daftar itu, Caelestite.",
  ui_story_1017_10170201_53_dialog_content = "Jadi, segera berangkatlah, karena Acheron Ferryman akan pergi.",
  ui_story_1017_10170201_54_dialog_content = "Tunggu, biarkan saya naik kereta!",
  ui_story_1017_10170201_55_dialog_content = "PlayerName, apa yang kamu...",
  ui_story_1017_10170201_56_dialog_content = "Ceritakan padaku, Caelestite, mengapa aku harus mengizinkanmu bergabung?",
  ui_story_1017_10170201_57_option_content = "Aku khawatir tentang Vice.",
  ui_story_1017_10170201_58_dialog_content = "Vivian mengatakan ada kemungkinan operasi ini akan membawa kamu jauh ke dalam Dark Zone...",
  ui_story_1017_10170201_59_dialog_content = "Aku khawatir musuh misterius dari latihan militer itu mungkin akan mengambil langkah lain terhadap Vice.",
  ui_story_1017_10170201_60_dialog_content = "Jadi, tolong ajak aku bersamamu.",
  ui_story_1017_10170201_61_option_content = "Aku mengkhawatirkanmu.",
  ui_story_1017_10170201_62_dialog_content = "Vivian mengatakan Illumina membentuk skuad pelacak, tapi saya tidak menyangka itu akan mencakup ketiga orang tersebut.",
  ui_story_1017_10170201_63_dialog_content = "Aku khawatir mereka akan membuat masalah untukmu, jadi izinkan aku ikut denganmu.",
  ui_story_1017_10170201_64_dialog_content = "Tentu saja, temanku tidak keberatan, tetapi tempat yang akan kita tuju sarat dengan bahaya.",
  ui_story_1017_10170201_65_dialog_content = "Tujuan perjalanan kita ini bisa jadi adalah akhir dari kehidupanmu.",
  ui_story_1017_10170201_66_dialog_content = "Percayalah padaku, aku memiliki banyak pengalaman dalam menghadapi bahaya!",
  ui_story_1017_10170201_67_dialog_content = "PlayerName…",
  ui_story_1017_10170201_68_dialog_content = "Hei, kamu dengar itu, Other End? Caelestite ingin berjalan langsung ke neraka bersama kita!",
  ui_story_1017_10170201_69_dialog_content = "Kamu tidak perlu mengatakannya seperti itu...",
  ui_story_1017_10170201_70_dialog_content = "Sayangnya, saya harus meminta kamu yang tak diundang untuk minggir agar kami bisa melanjutkan perjalanan.",
  ui_story_1017_10170201_71_dialog_content = "Masih banyak persiapan yang harus kita lakukan sebelum memasuki Zona Gelap.",
  ui_story_1017_10170201_72_dialog_content = "Sepertinya aku akan pergi sekarang, PlayerName.",
  ui_story_1017_10170201_73_option_content = "Dah, Vice.",
  ui_story_1017_10170201_74_dialog_content = "Ada yang ingin kamu katakan padaku?",
  ui_story_1017_10170201_75_dialog_content = "Ya…",
  ui_story_1017_10170201_76_option_content = "Vice, tunggu.",
  ui_story_1017_10170201_77_dialog_content = "Lalu?",
  ui_story_1017_10170201_78_dialog_content = "Dark Zone sangat berbahaya, jadi jaga dirimu baik-baik.",
  ui_story_1017_10170201_79_dialog_content = "Aku tahu, tapi aku selalu berhasil keluar dari masalah, bukan?",
  ui_story_1017_10170201_80_dialog_content = "Itu karena...",
  ui_story_1017_10170201_81_dialog_content = "Karena apa?",
  ui_story_1017_10170201_82_dialog_content = "Pokoknya, perasaanku tidak enak tentang ini...",
  ui_story_1017_10170201_83_dialog_content = "Aku paham. Kamu seorang Caelestite, kamu punya kekuatan telekinesis yang luar biasa, bla bla bla...",
  ui_story_1017_10170201_84_dialog_content = "Saya akan baik-baik saja dengan Officer Charon di sekitar!",
  ui_story_1017_10170201_85_dialog_content = "Oke. Tapi jika kamu terjerat masalah besar, cukup... panggil namaku!",
  ui_story_1017_10170201_86_dialog_content = "Memanggil namamu? Bisakah kamu mendengarnya dari jarak yang sangat jauh?",
  ui_story_1017_10170201_87_dialog_content = "Tak tahu, tapi coba saja.",
  ui_story_1017_10170201_88_dialog_content = "Agak aneh ya... Yah, dah.",
  ui_story_1017_10170201_89_dialog_content = "Dah, Vice.",
  ui_story_1017_10170201_90_dialog_content = "<color=#e8d9bb>Dug... Dug...</color>",
  ui_story_1017_10170201_X90_dialog_content = "\"Vice\"...",
  ui_story_1017_10170201_91_dialog_content = "Jika ada pertanyaan, silakan ajukan.",
  ui_story_1017_10170201_92_dialog_content = "Aku tidak mengerti. Figerald telah mengorbankan segalanya untukmu, jadi bagaimana dia bisa berakhir seperti itu?",
  ui_story_1017_10170201_93_dialog_content = "Orang yang menciptakan masalah bagi diri sendiri tidak akan berakhir dengan baik; bukan seperti dia tidak diberi kesempatan.",
  ui_story_1017_10170201_94_dialog_content = "Secara keseluruhan, pekerjaan itu tidak dijalankan dengan lancar, dan kalian berdua pantas dihukum.",
  ui_story_1017_10170201_95_dialog_content = "Sayang sekali, pada akhirnya saya mendapatkan apa yang saya inginkan, membuat misi ini sukses.",
  ui_story_1017_10170201_96_dialog_content = "Sudah sibuk merayakan, Anemone?",
  ui_story_1017_10170201_97_dialog_content = "Kita berhasil.",
  ui_story_1017_10170201_98_dialog_content = "Biarkan aku periksa... Nah, ada ide apa ini, gadis Illumina kecil?",
  ui_story_1017_10170201_99_dialog_content = "Bukankah aku sudah bilang jangan pernah memanggilku seperti itu?",
  ui_story_1017_10170201_100_dialog_content = "Heh, naif sekali... Ayo, ceritakan apa yang kamu tahu.",
  ui_story_1017_10170201_101_dialog_content = "Mesin tua. Kamu mengalami semua masalah itu hanya untuk ini?",
  ui_story_1017_10170201_102_dialog_content = "Memang tua, benar. Tapi itu milik <color=#FFB400>The Engineer</color>. Hanya saja, ya... itu tertinggal di Kota Gannon.",
  ui_story_1017_10170201_103_dialog_content = "Insinyur?",
  ui_story_1017_10170201_104_dialog_content = "Sepertinya kamu benar-benar dalam kegelapan, gadis kecil Illumina.",
  ui_story_1017_10170201_105_dialog_content = "Insinyur telah ada lebih lama daripada sejarah Illumina. Illumina tidak akan ada apa-apanya tanpa mereka.",
  ui_story_1017_10170201_106_dialog_content = "Apa yang kamu rencanakan?",
  ui_story_1017_10170201_107_dialog_content = "Mengembalikan barang-barang kepada pemilik yang sah, tentu saja. Dunia ini jauh lebih luas dari yang telah kamu lihat. Setelah The Engineer terbangun, kamu akan mendapatkan perspektif yang lebih luas.",
  ui_story_1017_10170201_108_dialog_content = "Oh? Apakah kamu kebetulan tertarik untuk menggelar karpet merah untuk kedatangan Sang Insinyur...",
  ui_story_1017_10170201_109_dialog_content = "Membentang dari Eclipse Hall hingga ke inti Astra...",
  ui_story_1017_10170201_110_dialog_content = "Sebuah karpet merah raksasa yang ditenun dari Darkflow yang bercampur dan sisa-sisa Aurorian... Saya yakin itu pasti akan menjadi pemandangan yang sangat menakjubkan.",
  ui_story_1017_10170201_111_dialog_content = "Lalu, apa yang bisa aku dapatkan dari ini?",
  ui_story_1017_10170201_112_dialog_content = "Bekerja untuk Eclipse sudah merupakan anugerah kebaikan yang diberikan kepadamu.",
  ui_story_1017_10170201_113_dialog_content = "Cukup dengan omong kosong, Asmodeus. Bukankah kamu harus kembali dan melapor?",
  ui_story_1017_10170201_114_dialog_content = "Kamu pasti seru di pesta...",
  ui_story_1017_10170201_115_dialog_content = "Bagaimana kalau begini: kamu yang mengurus persiapan \"karpet merah,\" dan aku janji, setelah pekerjaan selesai, akan ada tempat untukmu di dalam Eclipse.",
  ui_story_1017_10170201_116_dialog_content = "Kamu tahu betul bahwa itu lebih mudah diucapkan daripada dilakukan.",
  ui_story_1017_10170201_117_dialog_content = "Tenang saja. Di antara rongsokan yang telah kamu ciptakan, ada sesuatu yang ternyata benar-benar berguna. Aku akan membawanya untukmu.",
  ui_story_1017_10170201_118_dialog_content = "Jika Sang Insinyur tahu bahwa kamu yang mengatur semua ini, bukankah ia ingin bertemu dengan salah satu kerabat Illumina-nya?",
  ui_story_1017_10170201_119_dialog_content = "Aku akan menanganinya, tetapi sementara itu aku punya urusan pribadi yang harus diurus.",
  ui_story_1017_10170201_120_dialog_content = "Lakukan sesuka Anda. Namun, Forsakin, Anda mungkin ingin mempercepat sedikit. Rekan-rekan Illumina Anda mulai tidak sabar.",
  ui_story_1017_10170201_121_dialog_content = "Aku sudah tahu itu. Tak perlu kaubilang.",
  ui_story_1017_10170201_122_dialog_content = "Fokus pada bisnismu. Hama yang mengganggu itu bisa diserahkan kepada Eclipsite.",
  ui_story_1017_10170202_1_dialog_content = "Semua bersih, Kapten! Eclipsites telah dieliminasi!",
  ui_story_1017_10170202_2_dialog_content = "Tidak pernahkah aku bilang jangan panggil aku kapten?",
  ui_story_1017_10170202_3_dialog_content = "Mereka yang terburu-buru di depan sudah pergi. Yang kamu tangani—",
  ui_story_1017_10170202_4_dialog_content = "Itu! Sangat! Membosankan!",
  ui_story_1017_10170202_5_dialog_content = "Tapi Kapten Pepita, mereka yang kita ikuti adalah lawan yang sangat kuat!",
  ui_story_1017_10170202_6_dialog_content = "Data Darkflow di dashboard hampir mencapai puncaknya!",
  ui_story_1017_10170202_7_dialog_content = "Itulah mengapa saya bilang untuk langsung kabur saat ketiga orang itu muncul.",
  ui_story_1017_10170202_8_dialog_content = "Sebaliknya, saya terus terhambat oleh laporan tentang ini dan itu... Saya bisa mentolerir kalian mengacaukan kesenangan saya, tapi bukan kepala kalian yang akan melayang karena kehilangan target kita!",
  ui_story_1017_10170202_9_dialog_content = "Kapten, saya hanya mengikuti protokol pengintaian, melaporkan semua yang saya lihat seperti adanya.",
  ui_story_1017_10170202_10_dialog_content = "Anomali cuaca yang telah kita deteksi... kecepatan di mana Darkflow menyebar ke pedalaman benua... koordinat setiap kilometer yang kita tempuh...",
  ui_story_1017_10170202_11_dialog_content = "Oke, oke. Belisaria berjanji padaku tidak akan ada formalitas seperti ini.",
  ui_story_1017_10170202_12_dialog_content = "Mengingat jumlah kalian, bukankah kalian bisa melapor lebih cepat?",
  ui_story_1017_10170202_13_dialog_content = "Eh, aku...",
  ui_story_1017_10170202_14_dialog_content = "Lanjut saja, tujuan kita adalah melacak inti Guardian One. Mendapatkannya kembali dengan segala cara sangat penting.",
  ui_story_1017_10170202_15_dialog_content = "Ya, Kapten! Apakah kita melanjutkan ke arah yang sama seperti sebelumnya?",
  ui_story_1017_10170202_16_dialog_content = "Kita dekat dengan Zona Gelap. Aku bisa mengatasinya. Aku bisa berjalan di jalur ini dengan mata tertutup.",
  ui_story_1017_10170202_17_dialog_content = "Sudah? Sepertinya kita membuat kemajuan yang sangat baik!",
  ui_story_1017_10170202_18_dialog_content = "Menyusul itu satu hal, mengambil kembali barang itu adalah hal lain.",
  ui_story_1017_10170202_19_dialog_content = "Mari tetapkan beberapa aturan dasar. Jika kita melihat Eclipsite mencoba menghambat kita lagi, saya yang mengemudikan kendaraan, kalian turun dan bersihkan jalannya.",
  ui_story_1017_10170202_20_dialog_content = "Situasinya mendesak, jadi aku tidak akan melambat lagi.",
  ui_story_1017_10170202_21_dialog_content = "Siap, Kapten!",
  ui_story_1017_10170202_22_dialog_content = "Satu kali lagi, saya bukan kaptenmu!",
  ui_story_1017_10170301_1_dialog_content = "Jenderal tidak menjelaskan secara detail, tetapi prajurit sudah mulai dikerahkan di berbagai zona perang.",
  ui_story_1017_10170301_2_dialog_content = "Tapi rasanya seperti masalah Grand Marshal ini baru saja berlalu, dan sekarang ini...",
  ui_story_1017_10170301_3_dialog_content = "Tanpa Grand Marshal, siapa yang akan memimpin dari sekarang?",
  ui_story_1017_10170301_4_dialog_content = "\"Rekan-rekan sebangsa Illumina, saya memiliki pengumuman yang sangat penting—\"",
  ui_story_1017_10170301_5_dialog_content = "...",
  ui_story_1017_10170301_6_dialog_content = "\"Sejak berdirinya Federasi Illumina, para Grand Marshal selalu memimpin kami dalam pertempuran melawan invasi Eclipsite.\"",
  ui_story_1017_10170301_7_dialog_content = "\"Illumina melambangkan Aurorian yang bersatu dengan cita-cita yang sama, dan Grand Marshal selalu menjadi bagian dari kemuliaan tersebut.\"",
  ui_story_1017_10170301_8_dialog_content = "\"Sekarang, mungkin ini adalah saat paling krusial untuk berhasil atau gagal dalam sejarah kita...\"",
  ui_story_1017_10170301_9_dialog_content = "\"Tetapi meskipun jalannya suram, kita harus tetap maju bersama-sama.\"",
  ui_story_1017_10170301_10_dialog_content = "\"Dengan ini, atas nama Military and Political Affairs Committee of Illumina Federation, saya menyatakan kepada semua saudara sebangsa—\"",
  ui_story_1017_10170301_11_dialog_content = "\"Grand Marshal baru siap dan mampu memimpin kita dalam perang melawan Eclipsite.\"",
  ui_story_1017_10170301_12_dialog_content = "\"Ini untuk Grand Marshal—\"",
  ui_story_1017_10170301_13_dialog_content = "\"Wrath, dan masa depan baru untuk Federasi!\"",
  ui_story_1017_10170301_14_dialog_content = "... Jenderal Wrath?!",
  ui_story_1017_10170301_15_dialog_content = "... Marsekal Agung baru?!",
  ui_story_1017_10170301_16_dialog_content = "Jadi ternyata memang Jenderal Wrath, ya?",
  ui_story_1017_10170301_17_dialog_content = "Kenapa kalian semua di sini?",
  ui_story_1017_10170301_18_dialog_content = "PlayerName, baru saja saya mendengar bahwa Eclipsite sedang menyerang Twilight!",
  ui_story_1017_10170301_19_dialog_content = "Sekarang?!",
  ui_story_1017_10170301_20_dialog_content = "Ya. Orang-orang penting di Illumina tidak membuang waktu, bahkan dalam menggantikan Grand Marshal.",
  ui_story_1017_10170301_21_dialog_content = "Kejadian aneh selama latihan militer, mantan marsekal yang dipenjara, Eclipsites yang gelisah di perbatasan... Semua ini tidak mungkin kebetulan.",
  ui_story_1017_10170301_22_dialog_content = "(Dan Vice dikirim ke Dark Zone untuk menjalankan misi...)",
  ui_story_1017_10170301_23_dialog_content = "Kita tidak punya waktu untuk menganalisanya sekarang, PlayerName.",
  ui_story_1017_10170301_24_dialog_content = "Aku dengar Colossus-mu sudah diperbaiki. Aku di sini untuk meminta tumpangan kembali ke Twilight.",
  ui_story_1017_10170301_25_dialog_content = "Ini cara tercepat balik yang bisa saya pikirkan.",
  ui_story_1017_10170301_26_dialog_content = "Saya tidak menentangnya, kecuali Gronru masih membuat penyesuaian pada Soroz.",
  ui_story_1017_10170301_27_dialog_content = "Itulah sebabnya saya di sini.",
  ui_story_1017_10170301_28_dialog_content = "Aku masih jauh dari memahami Soroz, tetapi itu bisa lepas landas kapan saja.",
  ui_story_1017_10170301_29_dialog_content = "Sungguh?",
  ui_story_1017_10170301_30_dialog_content = "Tentu saja.",
  ui_story_1017_10170301_31_dialog_content = "Tolong, PlayerName! Perjalanan ini tidak akan mudah, tetapi saya harus kembali dan membantu Twilight.",
  ui_story_1017_10170301_32_dialog_content = "Ayo pergi!",
  ui_story_1017_10170301_33_dialog_content = "Kalian pergi, Leo. Aku akan mencoba Lumopolis.",
  ui_story_1017_10170301_34_dialog_content = "Lumopolis? Bahkan Carleen tidak bisa melakukan apa-apa. Apa yang membuatmu yakin kau bisa?",
  ui_story_1017_10170301_35_dialog_content = "Saya rasa situasi tidak bisa lebih buruk dari sini.",
  ui_story_1017_10170301_36_dialog_content = "Kalian kembali bersama PlayerName. Demi kota kita, aku harus mencoba meskipun seberapa sulit pun itu.",
  ui_story_1017_10170301_37_dialog_content = "...",
  ui_story_1017_10170301_38_dialog_content = "Apakah itu benar-benar yang kamu rasakan?",
  ui_story_1017_10170301_39_dialog_content = "Ya, Twilight dalam masalah dan Ironthorn Knights tidak bisa menyelamatkannya tanpa Anda.",
  ui_story_1017_10170301_40_dialog_content = "Percayalah padaku, tujuan saya adalah untuk mencari tahu apa yang terjadi di Twilight, dan pergi ke Lumopolis untuk meminta bantuan juga merupakan bagian dari rencana tersebut.",
  ui_story_1017_10170301_41_dialog_content = "Kamu tahu apa yang bisa terjadi jika kita kehilangan ahli strategi dalam pertempuran.",
  ui_story_1017_10170301_42_dialog_content = "Kamu memiliki PlayerName bersamamu. Kamu akan baik-baik saja–bahkan lebih baik, sebenarnya.",
  ui_story_1017_10170301_43_dialog_content = "Bagaimana kalau begitu? Kamu pimpin prajurit dan bunuh para Eclipsite, nanti aku bawa kabar baik.",
  ui_story_1017_10170301_44_dialog_content = "Bagaimana menurutmu, Ayah?",
  ui_story_1017_10170301_45_dialog_content = "Saya percaya pada kalian semua.",
  ui_story_1017_10170301_46_dialog_content = "Saya akan memberikan semuanya!",
  ui_story_1017_10170301_47_dialog_content = "Itu rencananya, ya.",
  ui_story_1017_10170301_48_dialog_content = "Hati-hati di jalan.",
  ui_story_1017_10170301_49_dialog_content = "Hati-hati di jalan.",
  ui_story_1017_10170301_50_dialog_content = "<color=#e8d9bb>Sementara itu, di lab Ulysses</color>",
  ui_story_1017_10170301_51_dialog_content = "Profesor, data simulasi seleksi arah untuk batch pertama Benih telah lulus uji signifikansi.",
  ui_story_1017_10170301_52_dialog_content = "Kita bergerak lebih cepat dari yang diharapkan. Apakah ini berarti kita siap untuk memulai uji klinis?",
  ui_story_1017_10170301_53_dialog_content = "Kamu dengar siaran itu. Ada Grand Marshal baru, jadi kita tidak boleh membuat kesalahan.",
  ui_story_1017_10170301_54_dialog_content = "Ya, Profesor. Tetapi eksperimen penelitian Anda belum pernah menemui masalah apa pun.",
  ui_story_1017_10170301_55_dialog_content = "Yah, saya rasa kita tidak perlu terpaku pada masa lalu.",
  ui_story_1017_10170301_56_dialog_content = "Anda terlalu rendah hati, Dokter. Semuanya pasti berjalan sesuai rencana.",
  ui_story_1017_10170301_57_dialog_content = "Kamu boleh pergi sekarang.",
  ui_story_1017_10170301_58_dialog_content = "Ya, Profesor.",
  ui_story_1017_10170301_59_dialog_content = "Untuk mencapai hasil yang diharapkan, sebuah eksperimen harus menjalani penyesuaian secara berkala.",
  ui_story_1017_10170301_60_dialog_content = "Apakah Wrath sesuai dengan yang kamu harapkan?",
  ui_story_1017_10170301_61_dialog_content = "Kamu tahu apa yang kupikirkan.",
  ui_story_1017_10170301_62_dialog_content = "Saya hanya memiliki satu tujuan. Saya bisa menerima perubahan apa pun selama itu tidak melemahkan stabilitas Illumina.",
  ui_story_1017_10170301_63_dialog_content = "Apakah Program Phospherus 2.0 dapat diterima oleh Anda?",
  ui_story_1017_10170301_64_dialog_content = "Para Eclipsite sudah mengetuk pintu depan Twilight. Langkah terbaru Eclipse praktis dibuat khusus untuk proyek Anda.",
  ui_story_1017_10170301_65_dialog_content = "Jangan pernah mengandalkan apapun saat melawan Eclipsites.",
  ui_story_1017_10170301_66_dialog_content = "Begitu Darkover Crisis berakhir, saya tahu harus segera terjun ke dalam modifikasi bio-Aurorian.",
  ui_story_1017_10170301_67_dialog_content = "Dan seiring berjalannya waktu, aku perlahan menyadari bahwa Seed dari Forsakin adalah komponen yang sangat penting.",
  ui_story_1017_10170301_68_dialog_content = "Semoga niatmu sejalan dengan niatku. Aku harus mengingatkanmu bahwa rasa cemburu adalah dosa di antara para ilmuwan.",
  ui_story_1017_10170301_69_dialog_content = "Kamu tidak kemari untuk konseling psikologis, 'kan?",
  ui_story_1017_10170301_70_dialog_content = "Kita akan mengobrol di hari lain. Untuk saat ini, saya ingin tahu apakah rencana Anda untuk Program Phospherus 2.0 sesuai dengan rencana saya.",
  ui_story_1017_10170301_71_dialog_content = "Karena cara terbaik untuk menyambut Grand Marshal baru adalah dengan kemenangan.",
  ui_story_1017_10170301_72_dialog_content = "Ini bukan hanya Kemarahan. Saya berharap legiunnya debut di medan perang dengan kehadiran yang benar-benar baru.",
  ui_story_1017_10170301_73_dialog_content = "Tahu kah kamu, Topeng Besi, saya rasa kamu tidak seobjektif yang diisyaratkan oleh julukanmu.",
  ui_story_1017_10170301_74_dialog_content = "Kehormatan, ketenaran, pemujaan masyarakat... Akan lebih baik jika Anda menjadi Marsekal Agung.",
  ui_story_1017_10170301_75_dialog_content = "Saya tahu dari pengalaman saya selama empat puluh tahun bahwa menjaga pertahanan jauh lebih sulit daripada melancarkan serangan.",
  ui_story_1017_10170301_76_dialog_content = "Kaum muda mempunyai takdirnya sendiri, dan kita harus menyiapkan panggung untuk mereka.",
  ui_story_1017_10170301_77_dialog_content = "Maka biarlah Twilight menjadi panggung untuk Phospherus 2.0.",
  ui_story_1017_10170301_78_dialog_content = "Entah itu Wrath atau tentara Illuminan, mereka semua akan menjadi bagian dari rencanaku...",
  ui_story_1017_10170301_79_dialog_content = "dan menjadi bintang Federasi ketika mereka memberikan kemenangan telak di Twilight.",
  ui_story_1017_10170301_80_dialog_content = "Masuk.",
  ui_story_1017_10170301_81_dialog_content = "Profesor, eksperimen fungsionalitas Eclipsite hari ini akan segera dimulai. Apakah Anda ingin mengamati?",
  ui_story_1017_10170301_82_dialog_content = "Tertarik, Topeng Besi? Meskipun itu hanya pencatatan rutin data kemampuan Eclipsite.",
  ui_story_1017_10170301_83_dialog_content = "Aku akan pergi. Aku sudah cukup lama duduk di bangku besi ini.",
  ui_story_1017_10170302_1_dialog_content = "Masuk.",
  ui_story_1017_10170302_2_dialog_content = "Pasukan Marsekal Agung akan segera dikerahkan. Apakah ada hal lain yang perlu dilakukan untuk eksperimen ini?",
  ui_story_1017_10170302_3_dialog_content = "Coba lihat laporan-laporan ini.",
  ui_story_1017_10170302_4_dialog_content = "Data... Sangat bagus, pak, proyek Anda sukses!",
  ui_story_1017_10170302_5_dialog_content = "Terima kasih telah mengizinkan saya menjadi bagian dari usaha megah ini.",
  ui_story_1017_10170302_6_dialog_content = "Ini jauh dari cukup.",
  ui_story_1017_10170302_7_dialog_content = "Arti...?",
  ui_story_1017_10170302_8_dialog_content = "Ini baru batch pertama Biji. Akan ada batch kedua, ketiga...",
  ui_story_1017_10170302_9_dialog_content = "Maksud kamu, Twilight adalah tes lapangan untuk batch pertama?",
  ui_story_1017_10170302_10_dialog_content = "Ya. Data klinis memang bagus, namun penelitian ilmiah bagaikan kotak Pandora yang berisi setengah keajaiban dan setengah kehancuran.",
  ui_story_1017_10170302_11_dialog_content = "Sebelum kita mengetahui semua yang ada di dalam kotak ini, yang bisa kita lakukan hanyalah terus meningkatkan eksperimennya. Data terbaru kami tampaknya menunjukkan hasil yang positif.",
  ui_story_1017_10170302_12_dialog_content = "Ya, ya, aku mengerti...",
  ui_story_1017_10170302_13_dialog_content = "Aku merasakan keraguan dalam dirimu.",
  ui_story_1017_10170302_14_dialog_content = "Ada sesuatu yang aku tidak yakin harus kukatakan.",
  ui_story_1017_10170302_15_dialog_content = "Utarakan pikiranmu.",
  ui_story_1017_10170302_16_dialog_content = "Ada rumor di kota bahwa prajurit telah memperoleh kekuatan mengerikan dengan menyuntikkan zat khusus...",
  ui_story_1017_10170302_17_dialog_content = "Bukankah itu fakta?",
  ui_story_1017_10170302_18_dialog_content = "Sebagian, tapi aku khawatir ini akan mempengaruhi rencana kita ke depannya.",
  ui_story_1017_10170302_19_dialog_content = "Itu saja?",
  ui_story_1017_10170302_20_dialog_content = "Juga... Aku khawatir apa yang kita lakukan dalam persidangan Reinhardt akan kembali menghantui kita.",
  ui_story_1017_10170302_21_dialog_content = "Heh, aku tahu maksudmu, Esien.",
  ui_story_1017_10170302_22_dialog_content = "Visi Anda terbatas karena Anda adalah salah satu anggota muda Komite.",
  ui_story_1017_10170302_23_dialog_content = "Aku tidak mengerti maksud Anda, Pak.",
  ui_story_1017_10170302_24_dialog_content = "Saya memiliki kekhawatiran yang sama ketika seusia Anda.",
  ui_story_1017_10170302_25_dialog_content = "Saya mengikuti prosedur eksperimen hingga tuntas dan membuat rencana darurat untuk setiap kemungkinan hasil...",
  ui_story_1017_10170302_26_dialog_content = "Dulu, saya sangat menikmati perasaan bisa mengendalikan segala sesuatu.",
  ui_story_1017_10170302_27_dialog_content = "Tapi perfeksionisme yang sama itulah yang menyebabkan saya mengalami kerugian besar.",
  ui_story_1017_10170302_28_dialog_content = "Apa yang kamu kehilangan?",
  ui_story_1017_10170302_29_dialog_content = "Terobosan, kejutan, apapun yang bisa disebut keajaiban.",
  ui_story_1017_10170302_30_dialog_content = "Tapi pak, bukankah \"peraturan, rencana, pelaksanaan, ulangi\" adalah julukan yang telah tertanam di kalangan Illuminati sejak muda?",
  ui_story_1017_10170302_31_dialog_content = "Saya tegaskan. Anda masih muda dan harus mencari jalan Anda sendiri.",
  ui_story_1017_10170302_32_dialog_content = "Keteraturan adalah konsep yang konyol. Kekacauan adalah sifat sejati dunia.",
  ui_story_1017_10170302_33_dialog_content = "...",
  ui_story_1017_10170302_34_dialog_content = "Apakah menjadi ilmuwan terbaik di Illumina impian Anda, Pak?",
  ui_story_1017_10170302_35_dialog_content = "Aku bukan seperti itu sekarang?",
  ui_story_1017_10170302_36_dialog_content = "Kamu memang!",
  ui_story_1017_10170302_37_dialog_content = "Ikutlah denganku untuk memeriksa batch Seed berikutnya.",
  ui_story_1017_10170302_38_dialog_content = "Siap, Jenderal.",
  ui_story_1017_10170401_1_dialog_content = "\"Hari ini, Grand Marshal Wrath akan memimpin Legiun Pengawal untuk memperkuat Twilight dan membasmi Eclipsite.\"",
  ui_story_1017_10170401_2_dialog_content = "\"Ini juga debut Grand Marshal sejak menjabat posisi tersebut.\"",
  ui_story_1017_10170401_3_dialog_content = "\"Dilaporkan bahwa prajurit harus menjalani penyaringan dan pelatihan ketat untuk menjadi elit tempur bagi Legiun Pengawal.\"",
  ui_story_1017_10170401_4_dialog_content = "\"Banyak prajurit akan mengendarai senjata terbaru Illumina, Engine VII, dalam pertempuran.\"",
  ui_story_1017_10170401_5_dialog_content = "\"Legiun Ketiga, dipimpin oleh Jenderal Hiiro, telah dikerahkan.\"",
  ui_story_1017_10170401_6_dialog_content = "\"Banyak prajurit dan warga sipil Illumina berkumpul menunggu kedatangan Grand Marshal.\"",
  ui_story_1017_10170401_7_dialog_content = "Lihat! Mereka di sini—",
  ui_story_1017_10170401_8_dialog_content = "Lihatlah formasi itu! Sangat mengesankan...",
  ui_story_1017_10170401_9_dialog_content = "\"Grand Marshal Wrath dan Legiun Penjaga mendekat dengan sorak sorai yang meriah!\"",
  ui_story_1017_10170401_10_dialog_content = "\"Grand Marshal dan para prajurit tampak yakin bahwa kemenangan sudah terjamin. Seolah-olah ini adalah parade kemenangan.\"",
  ui_story_1017_10170401_11_dialog_content = "\"Di samping Grand Marshal, semua mata juga tertuju pada Engine VII, yang dikembangkan dan dibangun oleh Tech Officer Gronru dan timnya.\"",
  ui_story_1017_10170401_12_dialog_content = "Kata-kata itu mengatakan bahwa proses penciptaan harus mengatasi beberapa kendala. Saya akan memberikan detail secara langsung hari ini.",
  ui_story_1017_10170401_13_dialog_content = "Aduh! Sakit...",
  ui_story_1017_10170401_14_dialog_content = "Maaf...",
  ui_story_1017_10170401_15_dialog_content = "Hei, aku kenal kamu... Kamu Axelia, pemenang pertandingan eksibisi!",
  ui_story_1017_10170401_16_dialog_content = "Anda bersama Legiun Penjaga! Itu membuatmu lebih mengesankan daripada Marsekal Agung Reinhardt!",
  ui_story_1017_10170401_17_dialog_content = "Cyborg Tempur Axelia dibuat untuk Illumina.",
  ui_story_1017_10170401_18_dialog_content = "Legiun Penjaga... Apakah semuanya seperti ini?",
  ui_story_1017_10170401_19_dialog_content = "Lihatlah fisik mereka, sangat berbeda dengan kita...",
  ui_story_1017_10170401_20_dialog_content = "Mampu memimpin prajurit seperti itu dalam perang, Grand Marshal Wrath benar-benar luar biasa...",
  ui_story_1017_10170401_21_dialog_content = "Ya, terbukti bahwa dia bahkan lebih perkasa dari Marsekal Agung Reinhardt!",
  ui_story_1017_10170401_22_dialog_content = "Pernahkah Anda memperhatikan betapa seriusnya penampilan Jenderal Hiiro?",
  ui_story_1017_10170401_23_dialog_content = "Dia selalu terlihat seperti itu.",
  ui_story_1017_10170401_24_dialog_content = "Grand marshal tidak dapat mendengar Anda jika Anda hanya berbisik.",
  ui_story_1017_10170401_25_dialog_content = "Kom-Komandan! Kami baru saja...",
  ui_story_1017_10170401_26_dialog_content = "Anda dapat menyimpan penjelasannya untuk komandan Anda.",
  ui_story_1017_10170401_27_dialog_content = "Komandan...",
  ui_story_1017_10170401_28_dialog_content = "Apa yang kamu lakukan disini, Kolonel Yingel? Tidak ingin melewatkan penampilan publik pertama grand marshal yang baru?",
  ui_story_1017_10170401_29_dialog_content = "Saya hanya khawatir tentang Axelia.",
  ui_story_1017_10170401_30_dialog_content = "Dengan dia menjadi karya besar Ulysses dan sebagainya, apa yang perlu Anda khawatirkan?",
  ui_story_1017_10170401_31_dialog_content = "Axelia sudah mencapai batasnya dalam pertarungan itu, tapi Ulysses tidak berpikir begitu...",
  ui_story_1017_10170401_32_dialog_content = "Anda bisa membaca pikirannya, mengesankan.",
  ui_story_1017_10170401_33_dialog_content = "Mungkin tidak adil bagi para prajurit dalam Program Phospherus, tetapi Ulysses memang mengorbankan banyak hal.",
  ui_story_1017_10170401_34_dialog_content = "Jadi, mendorong Aurorian untuk bertempur seperti senjata sekali pakai bukanlah pengorbanan? Proyek Ulysses menggoyang fondasi Illumina!",
  ui_story_1017_10170401_35_dialog_content = "Federasi yang dibangun atas daging dan darah Aurorian ini berada di ambang kepunahan, dan kalian berdua masih mendukungnya!",
  ui_story_1017_10170401_36_dialog_content = "Daging dan darah... Apakah kamu benar-benar berpikir itu saja cukup untuk melawan Eclipsite?",
  ui_story_1017_10170401_37_dialog_content = "Tentu saja tidak.",
  ui_story_1017_10170401_38_dialog_content = "Tapi dalam perang yang tak terhitung jumlahnya dengan para Eclipsite selama ini, kami tidak pernah meninggalkan martabat kami sebagai Aurorian seperti yang kami lakukan hari ini.",
  ui_story_1017_10170401_39_dialog_content = "Pengorbanan yang dilakukan Axelia, para prajurit, dan Anda tidak akan membuat kami damai. Mereka hanya akan membuat publik semakin takut terhadap Eclipsite.",
  ui_story_1017_10170401_40_dialog_content = "Ini tidak ada bedanya dengan menyerahkan diri kita kepada mereka!",
  ui_story_1017_10170401_41_dialog_content = "Aku benci perang, tapi aku juga tidak akan menyerah. Jika Illumina membutuhkanku, aku akan bertarung demi Illumina.",
  ui_story_1017_10170401_42_dialog_content = "Ingatlah kata-kata itu, Kolonel Yingel, ketika Anda menyaksikan para prajurit ini hendak berangkat berperang.",
  ui_story_1017_10170401_43_dialog_content = "Mereka mungkin tidak menyadari pengorbanan yang akan mereka lakukan dan begitu juga Axelia, tetapi kamu menyadarinya.",
  ui_story_1017_10170401_44_dialog_content = "...",
  ui_story_1017_10170401_45_dialog_content = "\"Grand Marshal Wrath telah mengambil sikap di depan Legiun Penjaga...\"",
  ui_story_1017_10170401_46_dialog_content = "Perhatian, semua prajurit Illuminan!",
  ui_story_1017_10170401_47_dialog_content = "Aku, Marsekal Agung Wrath dari Federasi Illumina, dengan ini menyatakan:",
  ui_story_1017_10170401_48_dialog_content = "Eclipsite telah menyerang Twilight, menghancurkan saudara-saudara kita yang ditempatkan di sana. Hari ini, kita akan menuju perbatasan dan menyingkirkan mereka semua!",
  ui_story_1017_10170401_49_dialog_content = "Legiun Penjaga telah berkumpul hari ini untuk mewakili yang terbaik dari Illumina. Anda telah dipilih untuk memimpin batalion bersama saya dan berjuang demi kejayaan kita.",
  ui_story_1017_10170401_50_dialog_content = "Kita harus menang dalam pertempuran ini dengan cara apa pun yang diperlukan! Jayalah Illumina!",
  ui_story_1017_10170401_51_dialog_content = "Jayalah Illumina!!!",
  ui_story_1017_10170401_52_dialog_content = "Perhatian, Komandan Hiiro dari Legiun ke-3!",
  ui_story_1017_10170401_53_dialog_content = "Ya!",
  ui_story_1017_10170401_54_dialog_content = "Siapkan pasukan Anda, kirim pesanan, dan bersiap untuk penempatan.",
  ui_story_1017_10170401_55_dialog_content = "Ya!",
  ui_story_1017_10170401_56_dialog_content = "Legiun Pengawal, maju!",
  ui_story_1017_10170401_57_dialog_content = "Ya!!!",
  ui_story_1017_10170401_58_dialog_content = "Bisakah kamu percaya... kita benar-benar siaga menunggu perintah?",
  ui_story_1017_10170401_59_dialog_content = "Aura ini... sangat mengintimidasi!",
  ui_story_1017_10170401_60_dialog_content = "Apakah dia baru saja menyentuh lencana kerahnya?",
  ui_story_1017_10170401_61_dialog_content = "Ya, aku melihat itu.",
  ui_story_1017_10170401_62_dialog_content = "Namun, dia tetap melakukannya.",
  ui_story_1017_10170401_63_dialog_content = "Yah, tapi aku ingin tahu apa yang ada dalam pikirannya saat ini...",
  ui_story_1017_10170401_64_dialog_content = "...",
  ui_story_1017_10170401_65_dialog_content = "(Jadi beginilah rasanya menjadi Grand Marshal yang memimpin seluruh tentara.)",
  ui_story_1017_10170401_66_dialog_content = "(Kamu pasti sudah terbiasa dengan ini setelah bertahun-tahun, Reinhardt...)",
  ui_story_1017_10170401_67_dialog_content = "(Saya ingin tahu apa yang Anda pikirkan saat pertama kali berdiri di sini?)",
  ui_story_1017_10170401_68_dialog_content = "(Apakah Anda sudah tahu bahwa posisi itu milik Anda, atau apakah Anda senang usaha dan pengorbanan Anda yang tak kenal lelah akhirnya membuahkan hasil...?)",
  ui_story_1017_10170401_69_dialog_content = "Aku rasa kamu sangat mampu. Ayo berteman.",
  ui_story_1017_10170401_70_dialog_content = "Teman-teman? Aku tidak butuh teman. Yang saya butuhkan hanyalah pelatihan.",
  ui_story_1017_10170401_71_dialog_content = "(Aku terus mengingatkan diri bahwa persahabatan akan membuatku lemah, jadi aku tidak ingin menjadi temanmu.)",
  ui_story_1017_10170401_72_dialog_content = "(Saya menjadikan Grand Marshal sebagai tujuan saya dan terus mengasah diri untuk itu.)",
  ui_story_1017_10170401_73_dialog_content = "(Tetapi saat kupikir aku sudah berhasil sejauh ini...)",
  ui_story_1017_10170401_74_dialog_content = "Ini adalah perangkat manipulasi energi terbaru yang dikembangkan oleh departemen penelitian. Mari kita minta Reinhardt maju untuk memberikan demonstrasi kepada kita.",
  ui_story_1017_10170401_75_dialog_content = "Dia?",
  ui_story_1017_10170401_76_dialog_content = "Di antara kalian semua, dialah satu-satunya yang mampu mengendalikan dengan sempurna.",
  ui_story_1017_10170401_77_dialog_content = "...",
  ui_story_1017_10170401_78_dialog_content = "(Mengontrol perangkat energi, ya? Tak apa, aku akan menghabiskan sepuluh kali lebih banyak waktu untuk menyempurnakannya.)",
  ui_story_1017_10170401_79_dialog_content = "(Saat tiba waktunya untuk latihan resmi, tidak akan ada kesenjangan keterampilan di antara kami.)",
  ui_story_1017_10170401_80_dialog_content = "Reinhardt, Wrath, kalian berdua adalah satu tim sekarang. Dan Reinhardt, Anda akan bertanggung jawab untuk menyampaikan perintah tempur.",
  ui_story_1017_10170401_81_dialog_content = "Mengapa aku tidak bisa melakukan itu?",
  ui_story_1017_10170401_82_dialog_content = "Menyampaikan perintah tempur secara langsung mempengaruhi keselamatan tim Anda.",
  ui_story_1017_10170401_83_dialog_content = "Pastikan untuk mengamati dan mempelajari dasar-dasar kepemimpinan tim saat sedang beraksi.",
  ui_story_1017_10170401_84_dialog_content = "...",
  ui_story_1017_10170401_85_dialog_content = "(Memimpin pasukan, bertanggung jawab atas keselamatan prajurit... Saya tidak pernah berhenti belajar dan berkembang, dan secara bertahap, saya membangun pengikut.)",
  ui_story_1017_10170401_86_dialog_content = "Selamat! Wrath of the 1st Legion, Anda telah dipromosikan menjadi Kapten! Pertahankan kerja bagus dalam misi masa depan.",
  ui_story_1017_10170401_87_dialog_content = "(Semua berjalan sesuai harapan. Saya hanya butuh kesempatan untuk membuktikan diri.)",
  ui_story_1017_10170401_88_dialog_content = "(Tetapi ketika para Eclipsite menyerang Undercity 19...)",
  ui_story_1017_10170401_89_dialog_content = "(Saya adalah orang pertama yang menerima perintah untuk memberikan dukungan, hanya agar Anda mengambil misi dan penghargaan dari saya...)",
  ui_story_1017_10170401_90_dialog_content = "Dan Medali Kontribusi Illumina diberikan kepada—Reinhardt!",
  ui_story_1017_10170401_91_dialog_content = "(Anda selalu unggul dalam bertindak, dan karena keunggulan Anda, banyak kriteria yang tidak perlu ditambahkan dalam penilaian promosi.)",
  ui_story_1017_10170401_92_dialog_content = "(Saya tidak punya ambisi untuk mengejar prestasi di luar medan perang. Prajurit harus menyelesaikan masalah seperti prajurit!)",
  ui_story_1017_10170401_93_dialog_content = "(Jadi akhirnya aku sadar bahwa aku tidak punya alasan untuk tidak menantangmu secara langsung!)",
  ui_story_1017_10170401_94_dialog_content = "Sekarang bukan waktunya untuk bertindak berdasarkan emosi Anda. Kita masih punya banyak Eclipsite di sekitar kita!",
  ui_story_1017_10170401_95_dialog_content = "Hentikan omong kosong itu dan angkat senjata. Entah kamu membunuhku, atau kamu mengakui bahwa aku lebih kuat darimu.",
  ui_story_1017_10170401_96_dialog_content = "Betapa tidak dewasa.",
  ui_story_1017_10170401_97_dialog_content = "Bebek—",
  ui_story_1017_10170401_98_dialog_content = "Kamu tidak perlu membunuh Eclipsite untukku. Aku bilang, angkat senjatamu dan bawa!",
  ui_story_1017_10170401_99_dialog_content = "Aku ulangi lagi, jangan terbawa suasana dan fokus pada pertempuran!",
  ui_story_1017_10170401_100_dialog_content = "Pergi ke neraka—",
  ui_story_1017_10170401_101_dialog_content = "Apakah Anda akan menerima tantangan saya setelah selesai mengatasi para Eclipsite itu?",
  ui_story_1017_10170401_102_dialog_content = "Selama kamu hidup, apa pun yang kamu inginkan.",
  ui_story_1017_10170401_103_dialog_content = "Setuju!",
  ui_story_1017_10170401_104_dialog_content = "Jangan pernah berpikir untuk menghalangiku, Eclipsite!",
  ui_story_1017_10170502_1_dialog_content = "(Seberapa familiar bagi saya untuk menyelesaikan setiap tantangan melawan Anda dalam posisi yang sama.)",
  ui_story_1017_10170502_2_dialog_content = "(Baik dalam latihan atau pertarungan nyata, kamu tidak pernah kalah sama sekali. Bagaimana kamu bisa melakukannya?)",
  ui_story_1017_10170502_3_dialog_content = "(Dengan itu dalam pikiran, kami bertarung lagi dalam pertempuran terakhir untuk gelar Grand Marshal...)",
  ui_story_1017_10170502_4_dialog_content = "Pemenang kita adalah... Reinhardt!",
  ui_story_1017_10170502_5_dialog_content = "Selamat kepada Reinhardt yang telah menjadi Grand Marshal Federasi Illumina!",
  ui_story_1017_10170502_6_dialog_content = "Grand Marshal Reinhardt!",
  ui_story_1017_10170502_7_dialog_content = "Meskipun Wrath mungkin kurang berhasil kali ini, kehebatannya sebagai prajurit Illumina tetap tidak dapat dipertanyakan.",
  ui_story_1017_10170502_8_dialog_content = "(Aku tak bisa menerima ini, aku belum selesai!)",
  ui_story_1017_10170502_9_dialog_content = "(Aku akan menantangmu lagi!)",
  ui_story_1017_10170502_10_dialog_content = "(100 kali lagi jika tidak bisa dalam 10 kali, dan 1.000 kali lagi jika tidak bisa dalam 100 kali!)",
  ui_story_1017_10170502_11_dialog_content = "Ayo kembali. Ramalan cuaca mengatakan cuaca buruk hari ini. Mungkin sedang hujan di permukaan.",
  ui_story_1017_10170502_12_dialog_content = "Aku tidak butuh belas kasihanmu.",
  ui_story_1017_10170502_13_dialog_content = "Bagiku, kamu bukan seseorang yang harus dikasihani, tapi temanku.",
  ui_story_1017_10170502_14_dialog_content = "Teman?",
  ui_story_1017_10170502_15_dialog_content = "Ya, seorang teman yang selalu mengusik tapi membuat kita berdua menjadi lebih baik.",
  ui_story_1017_10170502_16_dialog_content = "Siapa yang kamu sebut teman? Kita tidak pernah jadi sobat.",
  ui_story_1017_10170502_17_dialog_content = "(Aku tak punya teman, tidak ada selain kamu sebagai target.)",
  ui_story_1017_10170502_18_dialog_content = "Kita berseteru demi masa depan Illumina, tetapi seharusnya kita mengayunkan tinju kita pada musuh bersama dalam pertarungan yang nyata.",
  ui_story_1017_10170502_19_dialog_content = "Masa depanmu ada di telapak tanganmu. Jika kamu menggenggamnya terus, kamu akan berakhir dengan tidak ada apa-apa.",
  ui_story_1017_10170502_20_dialog_content = "Ambil lencana Grand Marshal-mu dan rayakan. Aku akan terus mengejarmu.",
  ui_story_1017_10170502_21_dialog_content = "Aku tidak akan memberi kelonggaran padamu meskipun kamu adalah Grand Marshal.",
  ui_story_1017_10170502_22_dialog_content = "Jika kamu bisa mengalahkan saya, kursi itu milikmu.",
  ui_story_1017_10170502_23_dialog_content = "Apakah kamu begitu yakin akan mengalahkanku sepanjang hidupmu?",
  ui_story_1017_10170502_24_dialog_content = "...",
  ui_story_1017_10170502_25_dialog_content = "Apa kamu yang melupakan sesuatu?",
  ui_story_1017_10170502_26_dialog_content = "Ya, aku sudah tidur.",
  ui_story_1017_10170502_27_dialog_content = "Lalu awasi belakangmu, karena aku akan mengejarmu.",
  ui_story_1017_10170502_28_dialog_content = "Apakah itu Grand Marshal atau gelar lainnya, saya akan merebutnya dari Anda suatu saat nanti!",
  ui_story_1017_10170502_29_dialog_content = "(Siapa yang bisa membayangkan aku menggantikanmu, tapi tidak dengan cara yang aku inginkan.)",
  ui_story_1017_10170502_30_dialog_content = "(Aku mendengar sorak-sorai dan cemoohan, tapi aku bukan boneka seperti kamu.)",
  ui_story_1017_10170502_31_dialog_content = "(Orang-orang yang mengharapkan saya untuk patuh hanya akan melihat orang lain...)",
  ui_story_1017_10170502_32_dialog_content = "(Seorang Grand Marshal yang keras kepala.)",
  ui_story_1017_10170601_1_dialog_content = "<color=#e8d9bb>Di kota Twilight, banyak penduduk yang berjalan menuju rumah sakit...</color>",
  ui_story_1017_10170601_2_dialog_content = "Bertahanlah sedikit lebih lama. <color=#FFB400>Rumah sakit</color> sudah di depan.",
  ui_story_1017_10170601_3_dialog_content = "Kakiku sudah menyerah...",
  ui_story_1017_10170601_4_dialog_content = "Ayo. Aku akan menggendongmu. Zona perang di sekitar sini sarat dengan Eclipsite. Tidak bisa diprediksi apakah mereka akan datang ke sini.",
  ui_story_1017_10170601_5_dialog_content = "Argh! Aduh, aduh...",
  ui_story_1017_10170601_6_dialog_content = "Letakkan dia di tandu.",
  ui_story_1017_10170601_7_dialog_content = "Hmm? Dan kamu...",
  ui_story_1017_10170601_8_dialog_content = "Tetap tenang, dan hati-hati dengan kakinya.",
  ui_story_1017_10170601_9_dialog_content = "Mengerti, Joselyne.",
  ui_story_1017_10170601_10_dialog_content = "Kamu bekerja di rumah sakit, kan?",
  ui_story_1017_10170601_11_dialog_content = "Hai, saya Joselyne, dan di samping saya ada seorang perawat rumah sakit.",
  ui_story_1017_10170601_12_dialog_content = "Senang bertemu kalian semua. Aku Chi.",
  ui_story_1017_10170601_13_dialog_content = "Chi, kamu masih sangat muda, tapi sungguh menakjubkan betapa mampunya kamu.",
  ui_story_1017_10170601_14_dialog_content = "Heheh!",
  ui_story_1017_10170601_15_dialog_content = "Joselyne...",
  ui_story_1017_10170601_16_dialog_content = "Ah! Kau pasti... Santa dari Gereja White Night, bukan?",
  ui_story_1017_10170601_17_dialog_content = "Suci?!",
  ui_story_1017_10170601_18_dialog_content = "Tidak, aku bukan Santa Perempuan. Aku hanya orang biasa.",
  ui_story_1017_10170601_19_dialog_content = "Apa itu Saintess, Joselyne?",
  ui_story_1017_10170601_20_dialog_content = "Sang Santa adalah dewi hidup yang mengawasi umat Dewa Cahaya!",
  ui_story_1017_10170601_21_dialog_content = "Selama Sang Santa ada di sini, Eclipsite tidak berani menginjakkan kaki di rumah kita.",
  ui_story_1017_10170601_22_dialog_content = "Wow! Ini benar-benar nyata, Yang Mulia?",
  ui_story_1017_10170601_23_dialog_content = "Sungguh, aku bukan seorang Santa. Panggil saja aku Joselyne.",
  ui_story_1017_10170601_24_dialog_content = "Meskipun aku percaya bahwa Cahaya akan memutus kegelapan dan menjadi mercusuar abadi bagi semua orang.",
  ui_story_1017_10170601_25_dialog_content = "Aku akan berusaha sebaik mungkin hingga hari itu tiba.",
  ui_story_1017_10170601_26_dialog_content = "\"God of Light,\" apa itu sebenarnya? Sungguh membingungkan, Joselyne...",
  ui_story_1017_10170601_27_dialog_content = "Ini berarti kebaikan akan mengalahkan kejahatan dan kita semua akan berada dalam pelukan Dewa Cahaya.",
  ui_story_1017_10170601_28_dialog_content = "Joselyne—",
  ui_story_1017_10170601_29_dialog_content = "Bagaimana keadaan di rumah sakit, Joselyne?",
  ui_story_1017_10170601_30_dialog_content = "Kami belum pernah memiliki orang sebanyak ini di sini sekaligus, tetapi kami masih harus memiliki ruang.",
  ui_story_1017_10170601_31_dialog_content = "Bagaimana keadaannya di garis depan?",
  ui_story_1017_10170601_32_dialog_content = "Sayangnya! Eclipsite melakukan serangan mendadak, menghantam kita dengan keras. Prajurit kita mengalami korban yang banyak!",
  ui_story_1017_10170601_33_dialog_content = "Pertahanan luar Twilight telah runtuh, menyebabkan banyak penduduk diserang...",
  ui_story_1017_10170601_34_dialog_content = "Astaga!",
  ui_story_1017_10170601_35_dialog_content = "Sudah berakhir. Semua sudah berakhir...",
  ui_story_1017_10170601_36_dialog_content = "Tidak ada kabar sama sekali untuk Leo dan yang lainnya?",
  ui_story_1017_10170601_37_dialog_content = "Kami mengirim pesan beberapa waktu lalu, tetapi tidak ada tanda-tanda dari Kapten!",
  ui_story_1017_10170601_38_dialog_content = "Saya akan membawa kuda dan perlengkapan Kapten ke <color=#FFB400>gerbang</color> Twilight untuk menerimanya.",
  ui_story_1017_10170601_39_dialog_content = "Ketika sang Kapten sedang tidak ada, kuda ini tampak bersemangat untuk berjuang untuknya, menerjang ke dalam pertempuran dan nyaris lolos dari bahaya yang ditimbulkan oleh Eclipsites.",
  ui_story_1017_10170601_40_dialog_content = "Ksatria Ironthorn masih berada di tengah-tengah pertempuran... Aku akan pergi terlebih dahulu. Semua urusan di sini kini ada di tanganmu.",
  ui_story_1017_10170601_41_dialog_content = "Demi White Night—",
  ui_story_1017_10170601_42_dialog_content = "Chi, tolong bantu pria ini membawa wanita yang terluka ke rumah sakit.",
  ui_story_1017_10170601_43_dialog_content = "Dan beritahu kepala perawat untuk mengirim lebih banyak tenaga medis ke pinggiran Twilight.",
  ui_story_1017_10170601_44_dialog_content = "Kau mau ke mana, Joselyne?",
  ui_story_1017_10170601_45_dialog_content = "Ke medan tempur.",
  ui_story_1017_10170601_46_dialog_content = "Ke medan tempur? Maksudku... seharusnya para prajurit lah yang pergi ke medan tempur, bukan?",
  ui_story_1017_10170601_47_dialog_content = "Saya seorang pejuang, dan inilah tempat yang seharusnya saya tempati saat ini.",
  ui_story_1017_10170601_48_dialog_content = "Kamu pasti bisa, Chi. Sampai jumpa nanti.",
  ui_story_1017_10170601_49_dialog_content = "...",
  ui_story_1017_10170601_50_dialog_content = "Apakah kamu siap untuk itu?",
  ui_story_1017_10170601_51_dialog_content = "Usia tak menentukan diriku; aku punya kekuatan yang serius!",
  ui_story_1017_10170601_52_dialog_content = "<color=#e8d9bb>Joselyne menjelajahi pinggiran zona perang...</color>",
  ui_story_1017_10170601_53_dialog_content = "Perhatikan pijakan kakimu!",
  ui_story_1017_10170601_54_dialog_content = "Tanpa ampun!",
  ui_story_1017_10170601_55_dialog_content = "Saya pikir yang ini sudah tidak berfungsi.",
  ui_story_1017_10170601_56_dialog_content = "Hati-hati dengan musuh yang terjatuh. Terkadang, serangan mereka bisa menjadi yang paling mematikan.",
  ui_story_1017_10170601_57_dialog_content = "Mengerti. Terima kasih atas pengingatnya!",
  ui_story_1017_10170601_58_dialog_content = "Ini ajaran Kapten—sekarang, tanpa dia di sekitar, ada yang terasa hilang.",
  ui_story_1017_10170601_59_dialog_content = "Mungkin semua orang tidak mengatakannya dengan keras, tetapi jauh di dalam, mereka pasti khawatir...",
  ui_story_1017_10170601_60_dialog_content = "Aku bisa merasakan... Ini pertama kalinya aku melihat begitu banyak Eclipsite.",
  ui_story_1017_10170601_61_dialog_content = "Tahu apa yang mereka kejar?",
  ui_story_1017_10170601_62_dialog_content = "Tidak tahu sama sekali. Seluruh operasi ini sangat kacau, dan barisan pertahanan kita terus ambruk...",
  ui_story_1017_10170601_63_dialog_content = "Jika kita terus begini, Twilight akan sia-sia.",
  ui_story_1017_10170601_64_dialog_content = "Di belakangmu!",
  ui_story_1017_10170601_65_dialog_content = "Ugh!",
  ui_story_1017_10170601_66_dialog_content = "Bagaimana Ksatria Ironthorn bisa begitu pesimis?",
  ui_story_1017_10170601_67_dialog_content = "Meskipun tanpa Leo di sini, kita harus berusaha semampu kita untuk menghilangkan para Eclipsite!",
  ui_story_1017_10170601_68_dialog_content = "Kami sudah ditempatkan di sini sejak lama. Jadi kami sangat menyadari bahwa Twilight hanyalah sebuah gurun tandus yang terlupakan, ditinggalkan oleh para dewa. Jika tidak ada bantuan yang datang, Eclipsite akan memangsa Twilight sesuka mereka.",
  ui_story_1017_10170601_69_dialog_content = "Kita membela tempat ini hanya karena kita lahir dan dibesarkan di sini, tanpa ada pilihan lain yang tersedia.",
  ui_story_1017_10170601_70_dialog_content = "Andai saja kita bisa kembali ke... Siapa yang rela menanggung penderitaan ini, berjuang untuk bertahan hidup di tanah terkutuk ini?",
  ui_story_1017_10170601_71_dialog_content = "...",
  ui_story_1017_10170601_72_dialog_content = "Dengan semua yang telah dikatakan... itu tidak berarti saya mundur. Namun, bahkan kita, prajurit tanpa nama, seharusnya tahu apa yang kita perjuangkan...",
  ui_story_1017_10170601_73_dialog_content = "Apa ini terlalu banyak untuk diminta?",
  ui_story_1017_10170601_74_dialog_content = "Melindungi tempat ini bukan alasan yang cukup baik?",
  ui_story_1017_10170601_75_dialog_content = "Anak-anak lokal yang tidak pernah melihat dunia luar menganggap Twilight adalah seluruh dunia.",
  ui_story_1017_10170601_76_dialog_content = "Saya yakin, kita semua berpikir sama sebelum menyadari bahwa ada dunia yang lebih besar di luar sana.",
  ui_story_1017_10170601_77_dialog_content = "Dan para prajurit yang mengorbankan diri mereka, bukankah mereka melakukannya untuk melindungi dunia kecil ini?",
  ui_story_1017_10170601_78_dialog_content = "...",
  ui_story_1017_10170601_79_dialog_content = "Prajurit tidak perlu membuktikan diri mereka melalui pertempuran besar.",
  ui_story_1017_10170601_80_dialog_content = "Mereka hebat hanya dengan mempertahankan sepotong tanah.",
  ui_story_1017_10170601_81_dialog_content = "Mungkin... Meskipun kata-kata Anda memang benar, beberapa tahun terakhir ini telah menunjukkan kepada kami bahwa kita semua berjuang untuk Kapten...",
  ui_story_1017_10170601_82_dialog_content = "Leo juga berjuang untukmu, bukan?",
  ui_story_1017_10170601_83_dialog_content = "Memang. Bagi kami, dia telah mengorbankan banyak hal.",
  ui_story_1017_10170601_84_dialog_content = "Untuk mencegah kerugian lebih lanjut, mari kita lindungi tanah tempat pertempuran berlangsung!",
  ui_story_1017_10170601_85_dialog_content = "Apakah kamu lahir di sini atau datang karena alasan yang berbeda, mari kita bertarung untuk satu sama lain!",
  ui_story_1017_10170601_86_dialog_content = "Ya, kamu benar sekali! Aku akan memberi tahu kawan-kawan sekarang juga!",
  ui_story_1017_10170601_87_dialog_content = "Dengarkan! Ironthorn Knights! Membiarkan Eclipsites maju satu inci lagi adalah penghinaan bagi saudara-saudara kita yang gugur!",
  ui_story_1017_10170601_88_dialog_content = "Ingatlah ini tentang Ksatria Ironthorn: ini bukan hanya tentang besi di baju besi kita, tetapi juga besi dalam tekad dan semangat kita!",
  ui_story_1017_10170601_89_dialog_content = "Kita tidak akan memberi sedikit pun ruang bagi Eclipsites, bahkan jika itu berarti kita harus membangun tembok dengan daging kita sendiri!",
  ui_story_1017_10170601_90_dialog_content = "Ayo, semua bersama!",
  ui_story_1017_10170601_91_dialog_content = "Aku juga!",
  ui_story_1017_10170601_92_dialog_content = "Lindungi Twilight dengan nyawa kita!",
  ui_story_1017_10170601_93_dialog_content = "Lindungi Twilight dengan nyawa kita!",
  ui_story_1017_10170602_1_dialog_content = "Apakah kita hampir sampai di Twilight, Soroz?",
  ui_story_1017_10170602_2_dialog_content = "PlayerName, kamu telah mengajukan pertanyaan yang sama 10 kali dalam 1 menit terakhir.",
  ui_story_1017_10170602_3_dialog_content = "Aku sangat gugup...",
  ui_story_1017_10170602_4_dialog_content = "Begitu rupanya. Saya sudah memeriksa adanya latensi dalam koneksi kita, tetapi sepertinya tidak ada.",
  ui_story_1017_10170602_5_dialog_content = "Tidak ada lag dalam komunikasi, meskipun terasa seperti kamu bergerak sangat lambat...",
  ui_story_1017_10170602_6_dialog_content = "Mengkonfirmasi kecepatan penerbangan: selalu pertahankan <color=#FFB400>kecepatan maksimum</color>.",
  ui_story_1017_10170602_7_dialog_content = "...",
  ui_story_1017_10170602_8_dialog_content = "Sepertinya semangatmu sedang rendah. Maukah kamu berbagi alasannya dengan saya?",
  ui_story_1017_10170602_9_dialog_content = "Baru saja teringat, berapa lama waktu yang lalu saat kamu kehilangan kesadaran.",
  ui_story_1017_10170602_10_dialog_content = "Dan saya bahkan tidak repot-repot bertanya bagaimana kabarmu sebelum memintamu untuk membawa kami ke Twilight.",
  ui_story_1017_10170602_11_dialog_content = "Mungkin sudah lama bagi kamu, tapi dalam pemrograman saya, kita tidak pernah terpisah.",
  ui_story_1017_10170602_12_dialog_content = "Sepertinya memang begitu yang kamu rasakan, sih.",
  ui_story_1017_10170602_13_dialog_content = "Saya bisa menyaksikan begitu banyak pemandangan berbeda hanya karena kamu dan teman-temanmu memiliki banyak tempat untuk dikunjungi.",
  ui_story_1017_10170602_14_dialog_content = "Ngomong-ngomong, <color=#FFB400>pemandangan baru</color>. Tujuan kita ada di depan sana.",
  ui_story_1017_10170602_15_dialog_content = "Apakah kita di sana sekarang?",
  ui_story_1017_10170602_16_dialog_content = "Kita hampir sampai. Tolong konfirmasi tempat pendaratan.",
  ui_story_1017_10170602_17_dialog_content = "Setelah kita selesai di Twilight, aku akan memberimu seluruh ceritanya.",
  ui_story_1017_10170602_18_dialog_content = "Ayo pelan-pelan dan terbang di ketinggian rendah, lalu <color=#FFB400>buka pintu</color>.",
  ui_story_1017_10170602_19_dialog_content = "Melambat. Membuka <color=#FFB400>Palka 3</color>...",
  ui_story_1017_10170602_20_dialog_content = "Leo—",
  ui_story_1017_10170602_21_dialog_content = "Terima kasih banyak, PlayerName. Ketika semuanya tenang di Twilight, saya akan secara resmi mengakui bantuan Anda.",
  ui_story_1017_10170602_22_dialog_content = "Tak masalah. Soroz sedang turun. Di mana kita harus mendarat?",
  ui_story_1017_10170602_23_dialog_content = "Lihat prajurit itu di gerbang?",
  ui_story_1017_10170602_24_dialog_content = "Aku melihat seseorang... dan mungkin ada tiga kuda...",
  ui_story_1017_10170602_25_dialog_content = "Dia salah satu temanku, menungguku bersama kudaku.",
  ui_story_1017_10170602_26_option_content = "Penglihatanmu bagus sekali!",
  ui_story_1017_10170602_27_dialog_content = "Tak bisa percaya kamu bisa membedakan mana orang dan mana kuda dari sejauh ini.",
  ui_story_1017_10170602_28_dialog_content = "Nah, Twilight adalah tempat yang bagus untuk berlatih.",
  ui_story_1017_10170602_29_option_content = "Tidak bisa bilang ini tak terduga",
  ui_story_1017_10170602_30_dialog_content = "Pasti ada chemistry antara kapten dan anak buahnya.",
  ui_story_1017_10170602_31_dialog_content = "Butuh bertahun-tahun untuk mengembangkannya.",
  ui_story_1017_10170602_32_dialog_content = "Saya bersedia mengajari Anda sedikit tentang kampanye dan bertarung saat kita mendapatkan kesempatan.",
  ui_story_1017_10170602_33_dialog_content = "Ketinggian pendaratan tercapai. PlayerName, tolong konfirmasi tempat pendaratan.",
  ui_story_1017_10170602_34_dialog_content = "Bagaimana kalau kita mendarat di dekat gerbang itu, Leo?",
  ui_story_1017_10170602_35_dialog_content = "Tentu... Hampir, hampir... Di sini, sempurna. Nah, lalu—",
  ui_story_1017_10170602_36_dialog_content = "Jagalah Joseph untukku, PlayerName!",
  ui_story_1017_10170602_37_dialog_content = "Sampai jumpa, Joseph.",
  ui_story_1017_10170602_38_dialog_content = "Sampai jumpa, Leo.",
  ui_story_1017_10170602_39_dialog_content = "???",
  ui_story_1017_10170602_40_dialog_content = "Dia melompat keluar begitu saja?!",
  ui_story_1017_10170602_41_dialog_content = "Hei, bagaimana—dengan—saya—",
  ui_story_1017_10170602_42_dialog_content = "Kamu—harus—kembali—",
  ui_story_1017_10170602_43_dialog_content = "...",
  ui_story_1017_10170602_44_dialog_content = "Kapten! Tidak menyangka yang melompat dari benda raksasa itu ternyata kau!",
  ui_story_1017_10170602_45_dialog_content = "Apakah itu... Colossus legendaris?!",
  ui_story_1017_10170602_46_dialog_content = "Benar. Maaf membuat kamu menunggu!",
  ui_story_1017_10170602_47_dialog_content = "Ayo menuju pertempuran sekarang juga. Katakan padaku, bagaimana keadaan Twilight?",
  ui_story_1017_10170602_48_dialog_content = "Eclipsite menyerang dari <color=#FFB400>Eternal Night</color>. Meskipun benteng luar telah ditembus, kawan-kawan kita masih bertahan di posisi mereka.",
  ui_story_1017_10170602_49_dialog_content = "Siapa yang memimpin Eclipsites?",
  ui_story_1017_10170602_50_dialog_content = "Tidak ada pemimpin khusus di antara Eclipsites. Mereka berkumpul dalam jumlah besar, dan tindakan mereka adalah kekacauan murni!",
  ui_story_1017_10170602_51_dialog_content = "Berapa jumlah korban?",
  ui_story_1017_10170602_52_dialog_content = "Banyak warga di pinggiran kota yang diserang. Saat ini kami telah memindahkan mereka ke zona yang lebih aman. Ratusan prajurit terluka, dan juga...",
  ui_story_1017_10170602_53_dialog_content = "Kita telah kehilangan <color=#FFB400>75</color> rekan kita...",
  ui_story_1017_10170602_54_dialog_content = "<color=#FFB400>75</color> kalah?! Lalu kenapa kamu masih di sini?",
  ui_story_1017_10170602_55_dialog_content = "Kapten... Sebelum Anda kembali, kuda Anda lepas dari kendalinya dan menerjang ke medan pertempuran, menumbangkan para Eclipsite...",
  ui_story_1017_10170602_56_dialog_content = "Aku nyaris tak bisa menahannya. Aku tidak tahu harus berbuat apa sekarang!",
  ui_story_1017_10170602_57_dialog_content = "Hmph, dibutuhkan lebih banyak lagi untuk menaklukkan Twilight!",
  ui_story_1017_10170602_58_dialog_content = "Sudah ngobrol dengan penduduk kota-kota terdekat?",
  ui_story_1017_10170602_59_dialog_content = "Mereka yang mampu bertarung sudah datang untuk mendukung kita... tetapi beberapa kota masih kesulitan untuk mengusir ancaman itu sendiri.",
  ui_story_1017_10170602_60_dialog_content = "Kali ini, tidak hanya pertempuran yang menantang... konsumsi sumber daya medis juga sangat luar biasa...",
  ui_story_1017_10170602_61_dialog_content = "Tidak ada bantuan medis dari Benteng Lumo?",
  ui_story_1017_10170602_62_dialog_content = "Tidak. Rumah sakit itu diisi oleh dokter dan perawat dari kota. Bahkan beberapa anak yang lebih tua juga ikut membantu...",
  ui_story_1017_10170602_63_dialog_content = "Segalanya menjadi lebih sulit saat berada di Twilight.",
  ui_story_1017_10170602_64_dialog_content = "Kabar baiknya adalah saya kembali dan tidak akan membiarkan teman-teman mati sia-sia.",
  ui_story_1017_10170602_65_dialog_content = "Kabar buruknya, kita masih satu-satunya yang bisa kita andalkan.",
  ui_story_1017_10170602_66_dialog_content = "Hmm... Kapten, kenapa Zhao tidak bersama Anda?",
  ui_story_1017_10170602_67_dialog_content = "Dia sedang sibuk dengan sesuatu, tapi aku tahu dia akan membalikkan keadaan untuk kita pada waktunya.",
  ui_story_1017_10170602_68_dialog_content = "Mungkinkah membalikkan keadaan mengingat krisis yang dihadapi Twilight?",
  ui_story_1017_10170602_69_dialog_content = "Di atas kamu!",
  ui_story_1017_10170602_70_dialog_content = "Tangkap!",
  ui_story_1017_10170602_71_dialog_content = "<color=#e8d9bb>Sang prajurit menangkap PlayerName yang jatuh dari langit, dan keduanya hampir terjatuh dari kuda mereka...</color>",
  ui_story_1017_10170602_72_dialog_content = "Tunggu, aku kenal kamu! Kamu hampir menindihku hingga gepeng!",
  ui_story_1017_10170602_73_dialog_content = "Aku pikir... Colossus juga akan jatuh menimpa aku!",
  ui_story_1017_10170602_74_dialog_content = "Maafkan ini...",
  ui_story_1017_10170602_75_dialog_content = "Kau baik-baik saja?",
  ui_story_1017_10170602_76_option_content = "Aku baik-baik saja",
  ui_story_1017_10170602_77_dialog_content = "Soroz sedang berlayar pada ketinggian yang sempurna.",
  ui_story_1017_10170602_78_option_content = "Di mana aku? Apakah aku masih hidup?",
  ui_story_1017_10170602_79_dialog_content = "Aku pikir jantungku akan berhenti saat jatuh.",
  ui_story_1017_10170602_80_dialog_content = "Untungnya, Soroz sedang berlayar pada ketinggian yang tepat.",
  ui_story_1017_10170602_81_dialog_content = "Kenapa kalian kemari?",
  ui_story_1017_10170602_82_dialog_content = "Kita seharusnya pergi ke Twilight bersama. Mengapa saya harus kembali?",
  ui_story_1017_10170602_83_dialog_content = "Terima kasih, tapi ini sejauh yang bisa kamu lakukan.",
  ui_story_1017_10170602_84_dialog_content = "Berbalik dan kawal orang ini kembali.",
  ui_story_1017_10170602_85_dialog_content = "Kapten...",
  ui_story_1017_10170602_86_dialog_content = "Aku tidak ingin kehilangan lebih banyak prajuritku lagi!",
  ui_story_1017_10170602_87_dialog_content = "Whoa, aku tidak punya rencana untuk jadi prajuritmu.",
  ui_story_1017_10170602_88_dialog_content = "Soroz dan saya akan sangat bermanfaat dalam pertempuran di Twilight.",
  ui_story_1017_10170602_89_dialog_content = "Soroz berada pada ketinggian yang sempurna untuk melihat seluruh pasukan lawan saat ini.",
  ui_story_1017_10170602_90_dialog_content = "Ini bisa menjadi mata di langit sementara saya membimbing Anda melalui pertempuran.",
  ui_story_1017_10170602_91_dialog_content = "Mata-di-langit cukup meyakinkan.",
  ui_story_1017_10170602_92_dialog_content = "Mengingat ketidakhadiran Zhao, bimbingan PlayerName di medan perang mungkin sangat penting bagi kita.",
  ui_story_1017_10170602_93_dialog_content = "Itu benar.",
  ui_story_1017_10170602_94_dialog_content = "Tapi pertempuran ini bukan latihan atau simulasi. Kematian di sini adalah nyata.",
  ui_story_1017_10170602_95_dialog_content = "Kamu yakin masih mau datang?",
  ui_story_1017_10170602_96_dialog_content = "Tentu saja!",
  ui_story_1017_10170602_97_dialog_content = "Baiklah, maju dengan kecepatan penuh ke medan pertempuran!",
  ui_story_1017_10170602_98_dialog_content = "Siap, Kapten!",
  ui_story_1017_10170602_99_dialog_content = "Sepertinya ini tak ada habisnya...",
  ui_story_1017_10170602_100_dialog_content = "Dan kami masih belum melihat pemimpin untuk mereka.",
  ui_story_1017_10170602_101_dialog_content = "Semua orang kelelahan, Joselyne. Kita tidak akan bertahan lebih lama jika terus seperti ini.",
  ui_story_1017_10170602_102_dialog_content = "Benteng baru belum selesai. Jika kita menyerah sekarang, semua usaha yang kita lakukan untuk mempertahankannya akan sia-sia!",
  ui_story_1017_10170602_103_dialog_content = "Tapi semangat sudah di titik terendah. Saya khawatir bahwa bahkan jika Kapten kembali, mungkin tidak akan membuat perbedaan...",
  ui_story_1017_10170602_104_dialog_content = "Siapa bilang bahkan aku tidak bisa menahan diri?",
  ui_story_1017_10170602_105_dialog_content = "Akhirnya kau kembali! Kapten!",
  ui_story_1017_10170602_106_dialog_content = "Kapten sudah kembali!!!",
  ui_story_1017_10170602_107_dialog_content = "Jauh di atas... itu...",
  ui_story_1017_10170602_108_dialog_content = "Saya telah kembali, saudara-saudara Ksatria Ironthorn saya!",
  ui_story_1017_10170602_109_dialog_content = "Mulai saat ini, tunjukkan kepada mereka seperti apa seorang ksatria!",
  ui_story_1017_10170602_110_dialog_content = "PlayerName dan Soroz Colossus akan memberikan perlindungan untuk kita!",
  ui_story_1017_10170602_111_dialog_content = "Jadi, ini Colossus legendaris, ya? Lebih besar dari yang kubayangkan!",
  ui_story_1017_10170602_112_dialog_content = "Ayo bertarung bersama Colossus!",
  ui_story_1017_10170602_113_dialog_content = "Benar, kita punya Soroz. Sekarang, perhatikan dan dengarkan perintahku!",
  ui_story_1017_10170602_114_dialog_content = "Ikuti jalur terbang Soroz dengan kecepatan penuh dan hancurkan para Eclipsite!",
  ui_story_1017_10170602_115_dialog_content = "Ya!",
  ui_story_1017_10170602_116_dialog_content = "Aku mengandalkanmu, PlayerName!",
  ui_story_1017_10170602_117_dialog_content = "Saya akan memberikan semuanya!",
  ui_story_1017_10170701_1_dialog_content = "Akses utama ke Lumopolis seharusnya ada di sekitar sini...",
  ui_story_1017_10170701_2_dialog_content = "Aduh!",
  ui_story_1017_10170701_X2_dialog_content = "Gigit dan Kraus!",
  ui_story_1017_10170701_3_dialog_content = "Bosan sekali, bosan sekali! Bagaimana kalau kita menggoda seseorang?",
  ui_story_1017_10170701_4_dialog_content = "Siapa kalian berdua?",
  ui_story_1017_10170701_5_dialog_content = "Coba tebak!",
  ui_story_1017_10170701_6_dialog_content = "Tolong berhenti menggangguku. Aku punya urusan mendesak dan harus pergi.",
  ui_story_1017_10170701_7_dialog_content = "Minta bantuan saya, tapi saya tidak bisa menjamin itu akan selesai!",
  ui_story_1017_10170701_8_dialog_content = "...",
  ui_story_1017_10170701_9_dialog_content = "Tahu arah ke Lumopolis?",
  ui_story_1017_10170701_10_dialog_content = "Tak ada yang ingin pergi ke tempat pucat, mengambang, dan dingin beku itu.",
  ui_story_1017_10170701_11_dialog_content = "Aku ingat ada akses khusus untuk...",
  ui_story_1017_10170701_12_dialog_content = "Pengingat ramah: Akses ke Lumopolis telah ditutup.",
  ui_story_1017_10170701_13_dialog_content = "Apakah baru saja ditutup? Tahukah kamu alasan spesifik mengapa?",
  ui_story_1017_10170701_14_dialog_content = "Kamu punya terlalu banyak pertanyaan. Keluarkan saja niat burukmu atau—",
  ui_story_1017_10170701_15_dialog_content = "Bawa aku bersamamu!",
  ui_story_1017_10170701_16_dialog_content = "<size=30>Informasi tentang Illumina tersebar dan Lumopolis bereaksi lebih cepat dari yang kubayangkan.</size>",
  ui_story_1017_10170701_17_dialog_content = "<size=30>Mungkin saya bisa meminjam kendaraan dari Courier Union...</size>",
  ui_story_1017_10170701_18_dialog_content = "<size=30>Tapi alasan apa yang bisa aku berikan...?</size>",
  ui_story_1017_10170701_19_dialog_content = "Ugh!",
  ui_story_1017_10170701_20_dialog_content = "Sedang apa kau?",
  ui_story_1017_10170701_21_dialog_content = "Kamu tidak bisa lolos dari hidung kami dengan begitu banyak konspirasi yang kamu baukan!",
  ui_story_1017_10170701_22_dialog_content = "Kamu tidak datang dengan damai, dan kami akan mengubahmu menjadi bos!",
  ui_story_1017_10170701_23_dialog_content = "Tidakkah kamu mencium bau mesiu dari Twilight pada diriku? Saya sedang menjalankan misi mendesak, jadi tolong biarkan saya keluar!",
  ui_story_1017_10170701_24_dialog_content = "Aku pusing... di sini...",
  ui_story_1017_10170701_25_dialog_content = "Ini Umbraton, bukan Twilight!",
  ui_story_1017_10170701_26_dialog_content = "Semua enak-enak di tempat sampah. Ingat untuk menghangatkannya sebelum kamu makan!",
  ui_story_1017_10170701_27_dialog_content = "Halo, bos, kami menemukan sesuatu yang baru, jadi jangan lupa beri kami makan ekstra!",
  ui_story_1017_10170701_28_dialog_content = "Bukankah aku sudah bilang jangan membawa pulang sampah usang?",
  ui_story_1017_10170701_29_dialog_content = "Bukan sampah, ini orang jahat! Lihat!",
  ui_story_1017_10170701_30_dialog_content = "Mencurigakan dan licik.",
  ui_story_1017_10170701_31_dialog_content = "Berusaha lari saat melihat kita!",
  ui_story_1017_10170701_32_dialog_content = "...",
  ui_story_1017_10170701_33_dialog_content = "Oh tidak, dia rusak!",
  ui_story_1017_10170701_34_dialog_content = "Apa yang dilakukan pria Illumina yang tampan seperti dia di sini?",
  ui_story_1017_10170701_35_dialog_content = "Dia menyebutkan menangkap Lumopolis, menghancurkan Serikat Kurir, dan lain-lain...",
  ui_story_1017_10170701_36_dialog_content = "Benar, dan ubah Umbraton menjadi senja!",
  ui_story_1017_10170701_37_dialog_content = "Tidak, ke kota Twilight!",
  ui_story_1017_10170701_38_dialog_content = "Senja?",
  ui_story_1017_10170701_39_dialog_content = "Ya, Twilight! Dan dia juga berbau mesiu!",
  ui_story_1017_10170701_40_dialog_content = "Temukan aku <color=#FFB400>Kleken</color>. Kalian berdua, pergi makan.",
  ui_story_1017_10170701_41_dialog_content = "Tentu, Bos! Waktunya pulang kerja, saatnya makan!",
  ui_story_1017_10170701_42_dialog_content = "City Lord, berapa lama lagi Anda butuh waktu untuk membuat keputusan?",
  ui_story_1017_10170701_43_dialog_content = "Surat-surat yang sedang saya pegang ini langsung dari Benteng Lumo.",
  ui_story_1017_10170701_44_dialog_content = "Kami menghadapi penurunan empat puluh persen dalam hasil <color=#FFB400>Tambang Vok</color> jika kita tidak mengirimkan prajurit kita sekarang.",
  ui_story_1017_10170701_45_dialog_content = "Pikirkan saja—hal ini bisa menyebabkan kekurangan dan gangguan pada bahan baku kita, dan itu akan berdampak lebih lanjut pada volume perdagangan luar negeri Lumopolis...",
  ui_story_1017_10170701_46_dialog_content = "Percayalah padaku. Kerugian tidak akan terbatas hanya pada ini saja!",
  ui_story_1017_10170701_47_dialog_content = "Sejak kapan keamanan Twilight mulai berdampak pada ekonomi Lumopolis?",
  ui_story_1017_10170701_48_dialog_content = "Anda khawatir tentang kekayaan yang telah Anda kumpulkan di Twilight selama bertahun-tahun, bukan?",
  ui_story_1017_10170701_49_dialog_content = "Omong kosong! Meskipun Rumah <color=#FFB400>Dietrich</color> mungkin tidak memiliki akar kuno, kami telah menambang sumber daya selama bertahun-tahun, memasok Lumopolis...",
  ui_story_1017_10170701_50_dialog_content = "Dan di masa-masa sulit, kami telah menawarkan tempat perlindungan untuk banyak ksatria yang diasingkan...",
  ui_story_1017_10170701_51_dialog_content = "Mengingat kontribusi kami, Rumah <color=#FFB400>Dietrich</color> seharusnya sudah diberi tempat utama di Uptown beberapa tahun lalu!",
  ui_story_1017_10170701_52_dialog_content = "Sekarang, <color=#FFB400>Troy</color>, begini ceritanya. Sementara kamu menikmati hidup yang baik di samping Tuan Kota, aku yakin kemampuanmu dalam mengatasi Eclipsite itu sudah berkarat.",
  ui_story_1017_10170701_53_dialog_content = "Illumina selalu memiliki kecenderungan untuk berperang. Biarkan mereka menenangkan Eclipsite sendiri.",
  ui_story_1017_10170701_54_dialog_content = "Juga, Ironthorn Knights memiliki banyak pengaruh di Twilight.",
  ui_story_1017_10170701_55_dialog_content = "Membahas tentang menawarkan perlindungan kepada ksatria, kemana pedangmu akan diarahkan selanjutnya? Pasti kamu sudah merencanakannya sejak lama.",
  ui_story_1017_10170701_56_dialog_content = "Anda mungkin tidak menyadarinya, tetapi yang dipertahankan oleh Ironthorn Knights adalah keseluruhan Twilight.",
  ui_story_1017_10170701_57_dialog_content = "Mereka sangat akrab dengan para prajurit Illumina, dan Leo bahkan bergabung dengan mereka dalam Latihan Militer Gabungan.",
  ui_story_1017_10170701_58_dialog_content = "Sejauh yang saya tahu, rumah Leo sudah runtuh. Atau apakah kamu merasa terancam oleh ketenarannya di Twilight?",
  ui_story_1017_10170701_59_dialog_content = "Ahem, ada kabar tentang hal lain selain Twilight?",
  ui_story_1017_10170701_60_dialog_content = "Tuan Kota, izinkan saya untuk memberi tahu Anda tentang apa yang saya pelajari selama Latihan Militer Gabungan.",
  ui_story_1017_10170701_61_dialog_content = "Majulah.",
  ui_story_1017_10170701_62_dialog_content = "Saya berteman dengan seorang tentara dari Twilight. Dia—",
  ui_story_1017_10170701_63_dialog_content = "Masih Twilight? Tidak apa-apa, tidak usah dijelaskan lagi.",
  ui_story_1017_10170701_64_dialog_content = "Tapi—",
  ui_story_1017_10170701_65_dialog_content = "Lihat meja itu?",
  ui_story_1017_10170701_66_dialog_content = "Saya sudah melihat cukup banyak pesan dari Twilight, Benteng Lumo, dan bahkan Umbraton untuk seumur hidup.",
  ui_story_1017_10170701_67_dialog_content = "Lantas, kenapa kamu belum mengambil tindakan apa pun?",
  ui_story_1017_10170701_68_dialog_content = "Kamu telah tinggal di Twilight terlalu lama sehingga ketidaksabaran mereka menular padamu.",
  ui_story_1017_10170701_69_dialog_content = "...",
  ui_story_1017_10170701_70_dialog_content = "(Ayah mungkin terlihat santai tentang hal itu, tetapi jarinya tidak pernah berhenti mengetuk meja...)",
  ui_story_1017_10170701_71_dialog_content = "(Dia tidak ingin mendengar tentang Twilight, tapi apa yang sedang dia tunggu?)",
  ui_story_1017_10170701_72_dialog_content = "Tuan Kota! Kami memiliki intel baru tentang Federasi Illumina!",
  ui_story_1017_10170701_73_dialog_content = "Bicaralah.",
  ui_story_1017_10170701_74_dialog_content = "Pasukan baru dari Illumina telah melewati pertahanan dan sekarang hampir mencapai Twilight.",
  ui_story_1017_10170701_75_dialog_content = "Mereka berhasil melewati pertahanan?",
  ui_story_1017_10170701_76_dialog_content = "Ya!",
  ui_story_1017_10170701_77_dialog_content = "Apa masalah dengan kekuatan baru ini?",
  ui_story_1017_10170701_78_dialog_content = "Pasukan baru ini adalah Legion Pengawal yang dibentuk setelah Wrath mengambil alih sebagai Grand Marshal.",
  ui_story_1017_10170701_79_dialog_content = "Mereka memiliki perlengkapan tempur dan prajurit baru di dalamnya, dan dengar ini—salah satu prajurit mereka benar-benar berhasil mengalahkan Reinhardt dalam latihan militer.",
  ui_story_1017_10170701_80_dialog_content = "(Axelia? Dia seharusnya sedang beristirahat sekarang...)",
  ui_story_1017_10170701_81_dialog_content = "Ada kabar tentang jenderal Illumina dan Caelestite?",
  ui_story_1017_10170701_82_dialog_content = "Selain Hiiro, Komandan lainnya sedang menjalani tugas berbeda, dan sepertinya mereka belum menuju ke Twilight.",
  ui_story_1017_10170701_83_dialog_content = "Untuk Caelestite, kami mendengar bahwa Colossus-nya menuju Twilight segera setelah perang dimulai.",
  ui_story_1017_10170701_84_dialog_content = "PlayerName pergi ke Twilight?",
  ui_story_1017_10170701_85_dialog_content = "Apakah itu masalah?",
  ui_story_1017_10170701_86_dialog_content = "Tidak bisa lebih jelas lagi—kerentanan Twilight terbuka lebar di depan mata semua kekuatan besar setelah latihan militer.",
  ui_story_1017_10170701_87_dialog_content = "Sepertinya Federasi Illumina percaya bahwa mereka telah menguasai Twilight, itulah sebabnya mereka mengirim pasukan yang tangguh ini.",
  ui_story_1017_10170701_88_dialog_content = "Mulai saat ini, siapa yang tahu apakah masih ada tempat untuk White Night in Twilight.",
  ui_story_1017_10170701_89_dialog_content = "Menggantikan marshal dan mengirim pasukan baru untuk menenangkan Eclipsites di saat kritis seperti ini...",
  ui_story_1017_10170701_90_dialog_content = "Bagi saya, itu keputusan yang sangat konyol.",
  ui_story_1017_10170701_91_dialog_content = "Lebih baik kamu mencari tahu apakah mereka berniat untuk memberikan bala bantuan atau melakukan sesuatu yang lain, Schwartz.",
  ui_story_1017_10170701_92_dialog_content = "Kirim perintah untuk menggerakkan bala bantuan untuk segera berangkat ke Twilight.",
  ui_story_1017_10170701_93_dialog_content = "Terima kasih, City Lord. Bolehkah Anda menjelaskan sedikit tentang pemikiran Anda?",
  ui_story_1017_10170701_94_dialog_content = "Setelah pasukan Illumina menyeberangi garis pertahanan, Lumopolis harus segera bergerak.",
  ui_story_1017_10170701_95_dialog_content = "Apakah itu upaya kerja sama atau agenda pribadi, sangat penting bagi kita untuk mengirim pasukan.",
  ui_story_1017_10170701_96_dialog_content = "Ingat, utamakan keselamatan Benteng Lumo di atas segalanya dan jangan terlibat dalam operasi Illumina apa pun.",
  ui_story_1017_10170701_97_dialog_content = "Saya harus menyetujui setiap tindakan pasukan penguat secara pribadi.",
  ui_story_1017_10170701_98_dialog_content = "Ya!",
  ui_story_1017_10170701_99_dialog_content = "(Ayah merasa curiga terhadap pasukan Illumina...)",
  ui_story_1017_10170701_100_dialog_content = "Siapa yang akan memimpin bala bantuan, City Lord? Saya ingin menjadi relawan—",
  ui_story_1017_10170701_101_dialog_content = "Kamu diberhentikan. Memperkuat Twilight bukan salah satu tanggung jawabmu.",
  ui_story_1017_10170701_102_dialog_content = "Tapi—",
  ui_story_1017_10170701_103_dialog_content = "Kita akan mengakhiri di sini untuk hari ini.",
  ui_story_1017_10170801_1_dialog_content = "Permisi... Keluargaku belum kembali. Bisakah Anda tetap membuka gerbang sedikit lebih lama?",
  ui_story_1017_10170801_2_dialog_content = "Perintah Lord jelas—Kunci rapat gerbang itu. Hanya penduduk White Night yang boleh masuk.",
  ui_story_1017_10170801_3_dialog_content = "Aku mengerti, tapi... anakku juga merupakan penduduk White Night... Dia pergi ke garis depan untuk melindungi kita.",
  ui_story_1017_10170801_4_dialog_content = "Apakah saya tidak cukup jelas? Gerbang akan segera ditutup. Mundur!",
  ui_story_1017_10170801_5_dialog_content = "Dewa Cahaya yang perkasa, betapa aku berharap Engkau tidak meninggalkan kami...",
  ui_story_1017_10170801_6_dialog_content = "Setelah senja tiba malam, dan setelah malam tiba senja lagi...",
  ui_story_1017_10170801_7_dialog_content = "Untuk anak-anak di garis depan, doa saya tulus bersama kalian.",
  ui_story_1017_10170801_8_dialog_content = "Mundur, PlayerName!",
  ui_story_1017_10170801_9_dialog_content = "Komandan tidak mundur dalam pertempuran!",
  ui_story_1017_10170801_10_dialog_content = "Aku belum pernah melihat invasi Eclipsite sebesar ini sebelumnya.",
  ui_story_1017_10170801_11_dialog_content = "Dua serangan sebelumnya dikerumuni oleh Eclipsites. Sekarang bukan saatnya untuk memaksakan.",
  ui_story_1017_10170801_12_dialog_content = "Yah, aku memang merasakan Darkflow semakin kuat...",
  ui_story_1017_10170801_13_dialog_content = "Mereka tidak memiliki pemimpin, motif yang jelas, dan jumlah yang sangat banyak. Kita tidak bisa menyerang secara membabi buta tanpa mengetahui lebih banyak informasi.",
  ui_story_1017_10170801_14_dialog_content = "Kapten, kedua tim yang menjaga garis pertahanan telah tercerai-berai oleh Eclipsite. Para prajurit mengalami korban yang banyak.",
  ui_story_1017_10170801_15_dialog_content = "Semua unit, mundur 100 langkah segera!",
  ui_story_1017_10170801_16_dialog_content = "Ya!",
  ui_story_1017_10170801_17_dialog_content = "Minta Logistik untuk membuat gerobak darurat dan mengangkut korban ke penginapan kota.",
  ui_story_1017_10170801_18_dialog_content = "Kami akan mengurus orang-orang yang terluka sendiri!",
  ui_story_1017_10170801_19_dialog_content = "Siap, Kapten!",
  ui_story_1017_10170801_20_dialog_content = "Leo, mari kita coba mencari tahu saat kita mundur. Menurutmu apa yang sedang dikerjakan Eclipsite?",
  ui_story_1017_10170801_21_dialog_content = "Mereka hanya mencoba mengurangi kita dengan jumlah yang banyak. Ini tidak masuk akal.",
  ui_story_1017_10170801_22_dialog_content = "Apa pemikiran tentang rencana Eclipsite, PlayerName?",
  ui_story_1017_10170801_23_dialog_content = "Biarkan aku mencoba kekuatanku.",
  ui_story_1017_10170801_24_dialog_content = "(Semua Eclipsite di luar Twilight... Darkflow-nya padat...)",
  ui_story_1017_10170801_25_dialog_content = "(Mereka bergerak perlahan dan berkerumun rapat seolah-olah...)",
  ui_story_1017_10170801_26_dialog_content = "(Seolah-olah mereka membentuk jaring Darkflow raksasa untuk menyelimuti Twilight...)",
  ui_story_1017_10170801_27_dialog_content = "(Banyak simpul... di jaring...)",
  ui_story_1017_10170801_28_dialog_content = "(Tunggu... Intensitas Darkflow berbeda untuk setiap titik, tapi sepertinya mereka menunjuk ke...)",
  ui_story_1017_10170801_29_dialog_content = "Leo, Darkflow meliputi jarak yang cukup jauh, dan sepertinya mereka berada di bawah komando pusat.",
  ui_story_1017_10170801_30_dialog_content = "Apakah kamu tahu apa itu central command?",
  ui_story_1017_10170801_31_dialog_content = "Maaf, itu di luar jangkauanku.",
  ui_story_1017_10170801_32_dialog_content = "Setidaknya itu berarti Eclipsites tidak bertindak secara acak.",
  ui_story_1017_10170801_33_dialog_content = "Ya. Dan untuk saat ini, menemukan pusat komando tersebut adalah kuncinya.",
  ui_story_1017_10170801_34_dialog_content = "Soroz, coba cari central command.",
  ui_story_1017_10170801_35_dialog_content = "Mencari...",
  ui_story_1017_10170801_36_dialog_content = "Memperluas bidang pandangan...",
  ui_story_1017_10170801_37_dialog_content = "\"Center\" belum terdeteksi. Pencarian masih berlangsung...",
  ui_story_1017_10170801_38_dialog_content = "Tidak ditemukan...",
  ui_story_1017_10170801_39_dialog_content = "Jika disebabkan oleh jarak, lokasinya mungkin sangat dekat dengan Zona Gelap, atau bahkan di dalam Zona Gelap.",
  ui_story_1017_10170801_40_dialog_content = "Saya menduga hanya dengan mengeliminasi siapa pun yang memimpin, kita akan menghentikan Eclipsites.",
  ui_story_1017_10170801_41_dialog_content = "Apakah Anda sedang mempertimbangkan untuk menjelajahi Zona Gelap?",
  ui_story_1017_10170801_42_dialog_content = "Benar. Twilight akan hancur jika kita tidak melakukan sesuatu.",
  ui_story_1017_10170801_43_dialog_content = "Aku bersamamu, Kapten!",
  ui_story_1017_10170801_44_dialog_content = "Tidak, kamu ambil alih sebagai komandan utama dan pertahankan barisan.",
  ui_story_1017_10170801_45_dialog_content = "Tim pengintaian, tunggu perintah saya—",
  ui_story_1017_10170801_46_dialog_content = "PlayerName, dari belakang, ada pasukan militer yang mendekatimu.",
  ui_story_1017_10170801_47_dialog_content = "Bisakah kamu katakan milik siapa pasukan mereka?",
  ui_story_1017_10170801_48_dialog_content = "Bendera di kendaraan transportasi bagian depan menampilkan sebuah gambar:",
  ui_story_1017_10170801_49_dialog_content = "Illumina!",
  ui_story_1017_10170801_50_dialog_content = "Leo, itu pasukan Illumina di belakang kita!",
  ui_story_1017_10170801_51_dialog_content = "Perhatian, Legiun Penjaga!",
  ui_story_1017_10170801_52_dialog_content = "Semua perusahaan maju dalam formasi berlian!",
  ui_story_1017_10170801_53_dialog_content = "Engine VII, utamakan mengisi celah di barikade. Jangan biarkan Eclipsite maju selangkah lagi!",
  ui_story_1017_10170801_54_dialog_content = "Ya!!!",
  ui_story_1017_10170801_55_dialog_content = "Inikah akhirnya untuk kalian penyusup? Kalian bahkan tidak akan bertahan 10 menit sebagai sasaran latihan!",
  ui_story_1017_10170801_56_dialog_content = "Ini... aura yang begitu mengesankan... Apakah ini Grand Marshal Illumina yang baru?",
  ui_story_1017_10170801_57_dialog_content = "Dia hanya menjadi instruktur latihanku saat itu, tetapi sekarang dia terlihat sangat berbeda sebagai Grand Marshal.",
  ui_story_1017_10170801_58_dialog_content = "Ya, seragam baru yang sepenuhnya, dan mungkin jauh lebih kuat!",
  ui_story_1017_10170801_59_dialog_content = "Tentara mereka juga sangat tangguh. Lihat yang di sana itu—",
  ui_story_1017_10170801_60_dialog_content = "Dia berhasil membunuh sepuluh Eclipsite berturut-turut, tanpa henti sejenak...",
  ui_story_1017_10170801_61_dialog_content = "Saya penasaran tentang senjata Illumina ini yang dikendalikan oleh prajurit dari dalam.",
  ui_story_1017_10170801_62_option_content = "(Aku ingin sekali memiloti salah satu dari itu)",
  ui_story_1017_10170801_63_dialog_content = "Untuk alasan keselamatan, saya tidak menyarankan mencoba itu.",
  ui_story_1017_10170801_64_option_content = "(Aku ingin memodifikasi Soroz)",
  ui_story_1017_10170801_65_dialog_content = "Tidak cocok gayanya. Tidak kusarankan mencoba itu.",
  ui_story_1017_10170801_66_dialog_content = "Ini hanya sebuah pikiran...",
  ui_story_1017_10170801_67_dialog_content = "Aku lihat prajurit itu juga di sini.",
  ui_story_1017_10170801_68_dialog_content = "Dia berhasil mengalahkan Reinhardt dalam latihan militer dan sekarang sudah bertarung untuk Wrath. Sangat mengesankan.",
  ui_story_1017_10170801_69_dialog_content = "Axelia... Tapi dia terluka parah. Apa yang dia lakukan di sini?",
  ui_story_1017_10170801_70_dialog_content = "Hei, senang melihatmu di sini, PlayerName. Apakah tampilannya membuat dagumu terbuka lebar?",
  ui_story_1017_10170801_71_dialog_content = "...",
  ui_story_1017_10170801_72_dialog_content = "Kita bertemu lagi, Kapten para Ksatria.",
  ui_story_1017_10170801_73_dialog_content = "Sudah lama, petugas... Oh, maaf, seharusnya saya memanggil Anda Grand Marshal!",
  ui_story_1017_10170801_74_dialog_content = "Meskipun sudah kembali ke tempat asalmu, sepertinya kamu tidak mengalami waktu yang mudah.",
  ui_story_1017_10170801_75_dialog_content = "Maukah kamu menjelaskan tujuan kehadiranmu dan prajurit Illumina di sini?",
  ui_story_1017_10170801_76_dialog_content = "Sebagai Grand Marshal Federasi Illumina, saya memimpin pasukan elit untuk membantu Twilight dalam menenangkan Eclipsites.",
  ui_story_1017_10170801_77_dialog_content = "Apakah itu sulit untuk dicerna?",
  ui_story_1017_10170801_78_dialog_content = "Agak mengejutkan bagi ego seperti Illumina untuk menyisihkan pasukan untuk Twilight.",
  ui_story_1017_10170801_79_dialog_content = "Nah, jika Twilight jatuh, Illumina berikutnya, jadi itu logikanya.",
  ui_story_1017_10170801_80_dialog_content = "Anda memiliki wawasan, Grand Marshal. Saya harap tidak ada tindakan curang seperti dalam latihan.",
  ui_story_1017_10170801_81_dialog_content = "Saya juga sedang menyelidiki hal itu. Sebagai sekutu Twilight kali ini, saya harap kita akan menikmati bekerja bersama.",
  ui_story_1017_10170801_82_dialog_content = "Bersulang.",
  ui_story_1017_10170801_83_dialog_content = "Dengarkan, Legiun Penjaga, Ksatria Ironthorn telah bertahan di medan pertempuran untuk waktu yang lama!",
  ui_story_1017_10170801_84_dialog_content = "Jangan ragu dan hancurkan semua Eclipsite!",
  ui_story_1017_10170801_85_dialog_content = "Ya!!!",
  ui_story_1017_10170801_86_dialog_content = "Perhatian, Ksatria Ironthorn!",
  ui_story_1017_10170801_87_dialog_content = "Serang dalam formasi baji. Mereka yang tidak ingin dianggap sebagai lelucon, ambil posisi depan bersamaku!",
  ui_story_1017_10170801_88_dialog_content = "Ya!!!",
  ui_story_1017_10170901_1_dialog_content = "Ulysses sedih karena mengutak-atik kartu buangan saya dan melemparkannya ke pertempuran pertama yang dia lihat.",
  ui_story_1017_10170901_2_dialog_content = "Masih berani untuk mendorong maju?",
  ui_story_1017_10170901_3_dialog_content = "(Eclipsian) Sampah-sampah ini ternyata benar-benar tahu cara bertarung.",
  ui_story_1017_10170901_4_dialog_content = "Kamu mengharapkan yang lain? Mereka memiliki Seed-ku di dalam tubuh mereka. Seharusnya kamu sudah merasakannya sekarang.",
  ui_story_1017_10170901_5_dialog_content = "(Eclipsian)...",
  ui_story_1017_10170901_6_dialog_content = "Aku tahu apa yang kamu pikirkan, bahwa seharusnya ada seseorang di sini.",
  ui_story_1017_10170901_7_dialog_content = "Jadi, kau sudah menungguku? Tak bisa menahan serangan kecil seperti ini?",
  ui_story_1017_10170901_8_dialog_content = "Berbeda dari yang diperkirakan. Kami mendapat penyusup pesta.",
  ui_story_1017_10170901_9_dialog_content = "Bukankah ini kesempatan emas untuk balas dendam? Kau seharusnya senang.",
  ui_story_1017_10170901_10_dialog_content = "Itu bukan urusanmu. Di mana itu?",
  ui_story_1017_10170901_11_dialog_content = "Ini.",
  ui_story_1017_10170901_12_dialog_content = "Mudbundle?",
  ui_story_1017_10170901_13_dialog_content = "Yah, memang sedikit membuat mual untuk dilihat, tetapi itu akan meningkatkan kecepatan dorongan Anda. Ada pendapat?",
  ui_story_1017_10170901_14_dialog_content = "Jika saya tidak salah ingat, ia bisa memakan lingkungannya, menciptakan rawa-rawa, dan cara-cara menyiksa Aurorian-nya adalah... cukup unik, memang, sangat unik.",
  ui_story_1017_10170901_15_dialog_content = "Ayo kita coba.",
  ui_story_1017_10170901_16_dialog_content = "(Bahasa Eclipsian) Ya.",
  ui_story_1017_10170901_17_dialog_content = "(Eclipsian) Darkflow... menyatu, perasaan... kelaparan yang tak terpuaskan!",
  ui_story_1017_10170901_18_dialog_content = "Eclipsites hanya perlu berdiri di rawa Mudbundle agar biji di dalam mereka dapat terhubung ke inti.",
  ui_story_1017_10170901_19_dialog_content = "(Dalam bahasa Eclipsian) Kekuatan terus saja mengalir masuk!!!",
  ui_story_1017_10170901_20_dialog_content = "Yang perlu kamu lakukan selanjutnya adalah hanya melahap Aurorian dan memberi makan diri kalian. Saat waktunya tiba, Mudbundle akan melakukan pembersihan.",
  ui_story_1017_10170901_21_dialog_content = "Tidak suka dengan penjelasan yang membosankan ini. Aku serahkan ini padamu. Pertemuan berikutnya akan saat kita memeriksa \"karpet.\"",
  ui_story_1017_10170901_22_dialog_content = "(Makanan Eclipsian) MAKANAN!!!",
  ui_story_1017_10170901_23_dialog_content = "Ayo, semua makanan itu milikmu sebelum Twilight terbenam dalam lumpur!",
  ui_story_1017_10170901_24_dialog_content = "(Eclipsian) Grrr!!!",
  ui_story_1017_10170901_25_dialog_content = "Oh tidak, aku merasakan Darkflow yang sangat kuat datang!",
  ui_story_1017_10170901_26_dialog_content = "Begitu cepat? Apakah itu seseorang dari pusat komando?",
  ui_story_1017_10170901_27_dialog_content = "Tidak yakin, tapi memang jaringan Darkflow semakin mendekat pada kita.",
  ui_story_1017_10170901_28_dialog_content = "Eh... Ah...",
  ui_story_1017_10170901_29_dialog_content = "Apa yang terjadi di sana?",
  ui_story_1017_10170901_30_dialog_content = "Melapor, Marsekal Agung! Sepertinya beberapa prajurit mungkin terpengaruh oleh Darkflow...",
  ui_story_1017_10170901_31_dialog_content = "Berikan pertolongan medis secepat mungkin dan beri saya laporan status tentang orang-orang yang terluka.",
  ui_story_1017_10170901_32_dialog_content = "Ya!",
  ui_story_1017_10170901_33_dialog_content = "(Tiba-tiba aku merasakan... gelombang kekuatan...)",
  ui_story_1017_10170901_34_dialog_content = "Kau baik-baik saja, Grand Marshal?",
  ui_story_1017_10170901_35_dialog_content = "Darkflow... memang membuat orang merasa tidak nyaman...",
  ui_story_1017_10170901_36_dialog_content = "Mundur bersama prajurit Anda. Ksatria Ironthorn Skuad 1 dan 2, serang musuh. Skuad 3 dan 4 akan memberikan dukungan!",
  ui_story_1017_10170901_37_dialog_content = "Jangan terlalu cepat. Eclipsites ini tidak punya kesempatan.",
  ui_story_1017_10170901_38_dialog_content = "Terus bantu aku, PlayerName!",
  ui_story_1017_10170901_39_dialog_content = "Eclipsite dengan bentuk unik sedang mendekat di depan.",
  ui_story_1017_10170901_40_dialog_content = "Bisakah itu seseorang dari pusat komando mereka?",
  ui_story_1017_10170901_41_dialog_content = "Tidak dapat dipastikan. Tetapi Darkflow yang terdeteksi lebih kuat daripada Eclipsite lainnya.",
  ui_story_1017_10170901_42_dialog_content = "Mengerti. Ada yang lain untuk dibagikan?",
  ui_story_1017_10170901_43_dialog_content = "Pendeteksian sedang berlangsung. Saya akan menyinkronkan dengan Anda setelah hasilnya tersedia.",
  ui_story_1017_10170901_44_dialog_content = "Oke, aku mengandalkanmu!",
  ui_story_1017_10170901_45_dialog_content = "Eclipsite yang sangat kuat akan datang ke sini, semua orang. Bersiaplah untuk menyerang!",
  ui_story_1017_10170901_46_dialog_content = "Akhirnya, bukan hanya sebagai sasaran empuk.",
  ui_story_1017_10170901_47_dialog_content = "Amati dan pelajari, ksatria. Legiun Penjaga tidak akan jatuh. Kita bisa melakukannya!",
  ui_story_1017_10170901_48_dialog_content = "Oke. Lindungi mereka, Ksatria Ironthorn!",
  ui_story_1017_10170901_49_dialog_content = "Ya!!!",
  ui_story_1017_10171001_1_dialog_content = "Fiuh... Akhirnya selesai juga!",
  ui_story_1017_10171001_2_dialog_content = "Aku tidak percaya betapa banyak Eclipsites yang dipanggil sebelum akhirnya jatuh. Hal itu membuat kita lengah.",
  ui_story_1017_10171001_3_dialog_content = "Saya mulai melihat strategi mereka sekarang, dan kita seharusnya aman untuk sementara waktu.",
  ui_story_1017_10171001_4_dialog_content = "Melaporkan, Marsekal Agung! Jumlah prajurit yang terkena Darkflow terus meningkat!",
  ui_story_1017_10171001_5_dialog_content = "Sudahkah kita tahu penyebabnya?",
  ui_story_1017_10171001_6_dialog_content = "Belum. Banyak prajurit kehilangan kendali atas tubuh mereka, masuk ke dalam kegilaan <color=#FFB400>haus darah</color>. Penyembuhan terbukti sama sekali tidak berguna.",
  ui_story_1017_10171001_7_dialog_content = "...",
  ui_story_1017_10171001_8_dialog_content = "(Kehilangan kendali dan haus darah... Aku ingin tahu apakah semua orang merasa begitu saat pertempuran...)",
  ui_story_1017_10171001_9_dialog_content = "Sektor timur! Kapten, sekelompok Eclipsite kembali membuat masalah di parit-parit!",
  ui_story_1017_10171001_10_dialog_content = "Sepertinya Eclipsite ini bukan pemimpinnya.",
  ui_story_1017_10171001_11_dialog_content = "Ada yang punya petunjuk?",
  ui_story_1017_10171001_12_dialog_content = "Ketika saya merawat mereka, saya menyadari pengaruh Darkflow pada prajurit lebih buruk daripada yang biasanya kita lihat.",
  ui_story_1017_10171001_13_dialog_content = "Mungkin kita harus mengirim mereka ke rumah sakit untuk perawatan lebih lanjut agar mereka bisa sembuh.",
  ui_story_1017_10171001_14_dialog_content = "Grand Marshal Wrath, izinkan saya membawa prajurit yang terluka dalam pasukan Anda ke rumah sakit.",
  ui_story_1017_10171001_15_dialog_content = "Aku baru saja akan mengajukan permintaan itu. Terima kasih! Illumina akan memberikan kompensasi kepada kamu setelah perang.",
  ui_story_1017_10171001_16_dialog_content = "Itulah yang saya lakukan.",
  ui_story_1017_10171001_17_dialog_content = "Grand Marshal! Laporan menyebutkan bahwa beberapa prajurit telah terpisah dari unit dan bergerak ke arah yang sama...",
  ui_story_1017_10171001_18_dialog_content = "Seolah-olah mereka digerakkan oleh kekuatan tak dikenal.",
  ui_story_1017_10171001_19_dialog_content = "Apakah mungkin pusat komando mereka ada di balik ini?",
  ui_story_1017_10171001_20_dialog_content = "Tidak bisa menyangkal itu. Kami menduga arah Darkflow dimanipulasi oleh pusat komando.",
  ui_story_1017_10171001_21_dialog_content = "Bagaimana dengan prajurit di Twilight, apakah mereka merasakan hal yang sama?",
  ui_story_1017_10171001_22_dialog_content = "Kapten, kami melihat sesuatu...",
  ui_story_1017_10171001_23_dialog_content = "Yakin?",
  ui_story_1017_10171001_24_dialog_content = "Ya, Kapten.",
  ui_story_1017_10171001_25_dialog_content = "Semua prajurit yang berperilaku aneh itu berasal dari pasukan Anda, Grand Marshal.",
  ui_story_1017_10171001_26_dialog_content = "Apa yang Anda maksudkan?",
  ui_story_1017_10171001_27_dialog_content = "Tak perlu berbelit-belit, dalam beberapa serangan terakhir, prajuritmu bertindak secara tidak wajar.",
  ui_story_1017_10171001_28_dialog_content = "Apakah karena musuh terlalu kuat...",
  ui_story_1017_10171001_29_dialog_content = "Atau apakah Anda memiliki mata-mata di unit Anda, Grand Marshal?",
  ui_story_1017_10171001_30_dialog_content = "Apakah kamu meragukan niat Illumina untuk datang membantu Twilight?",
  ui_story_1017_10171001_31_dialog_content = "Sama sekali tidak. Saya hanya berpikir musuh kita bukanlah musuh biasa. Sebagai kapten, saya harus bertanggung jawab kepada anak buah saya.",
  ui_story_1017_10171001_32_dialog_content = "Berdasarkan apa yang kita miliki, prajurit kalian mulai salah mengira Aurorian sebagai Eclipsite.",
  ui_story_1017_10171001_33_dialog_content = "Gigit lidahmu! Saya tidak akan pernah melakukan trik yang mencurigakan seperti itu!",
  ui_story_1017_10171001_34_dialog_content = "Kapten Leo, Grand Marshal Wrath, saya percaya semua orang di sini demi kebaikan Twilight.",
  ui_story_1017_10171001_35_dialog_content = "Meskipun aku masih belum yakin mengapa para prajurit tidak mengikuti perintah mereka...",
  ui_story_1017_10171001_36_dialog_content = "Aku khawatir ini adalah trik musuh kita untuk sengaja mengaburkan pertimbangan kita.",
  ui_story_1017_10171001_37_dialog_content = "Tentu saja, prajuritku tidak sepenuhnya mengikuti perintahku dalam pertempuran terakhir.",
  ui_story_1017_10171001_38_dialog_content = "Dan sebagai Grand Marshal, aku bertanggung jawab atas segala hal di sini atas nama Illumina.",
  ui_story_1017_10171001_39_dialog_content = "Nanti, aku akan memberikan jawaban yang memuaskan untuk kamu.",
  ui_story_1017_10171001_40_dialog_content = "Tapi jika kamu tetap meragukan motif Illumina, aku akan menganggap itu sebagai tindakan perang.",
  ui_story_1017_10171001_41_dialog_content = "\"Menganggap sebagai tindakan perang\" adalah pernyataan yang sangat berlebihan untuk apa yang hanya sekedar pengingat singkat dari saya.",
  ui_story_1017_10171001_42_dialog_content = "Kamu baru di posisi ini, jadi tolong pelajari kecenderungan bertarung dari orang-orang yang di bawah kamu.",
  ui_story_1017_10171001_43_dialog_content = "Jika mereka menunjukkan pengkhianatan lagi atau bahkan menyakiti prajuritku, aku akan membalas dengan cara yang sama.",
  ui_story_1017_10171001_44_dialog_content = "Gonggonganmu lebih buruk daripada gigitanmu.",
  ui_story_1017_10171001_45_dialog_content = "Jika kau ingin melawan Illumina, percayalah, aku sendiri sudah lebih dari cukup untuk menghadapimu!",
  ui_story_1017_10171001_46_dialog_content = "Marsekal Agung! Melaporkan situasi mendesak!",
  ui_story_1017_10171001_47_dialog_content = "Tim tempur Letnan Axelia telah hilang.",
  ui_story_1017_10171001_48_dialog_content = "???",
  ui_story_1017_10171001_49_dialog_content = "Wilayah mana yang menjadi tanggung jawabnya?",
  ui_story_1017_10171001_50_dialog_content = "Sektor barat, Grand Marshal, tempat sekelompok Eclipsite masih bergerak menuju Twilight sekarang.",
  ui_story_1017_10171001_51_dialog_content = "Garda Legion, kita akan bergerak ke barat untuk membunuh Eclipsite!",
  ui_story_1017_10171001_52_dialog_content = "Semua yang terluka, tetap semangat kecuali jika kaki patah atau kehilangan kepala!",
  ui_story_1017_10171001_53_dialog_content = "Laporkan prajurit dengan perilaku mencurigakan kepada saya segera!",
  ui_story_1017_10171001_54_dialog_content = "Ya!",
  ui_story_1017_10171001_55_dialog_content = "Kamu ikut denganku, PlayerName.",
  ui_story_1017_10171001_56_dialog_content = "Aku?",
  ui_story_1017_10171001_57_dialog_content = "Sekarang!",
  ui_story_1017_10171001_58_dialog_content = "...",
  ui_story_1017_10171001_59_dialog_content = "Kapten, haruskah kita bergerak sendiri?",
  ui_story_1017_10171001_60_dialog_content = "Sapu baru menyapu bersih. Tidak mengatasi masalah sekarang hanya akan membuat segalanya lebih sulit nanti.",
  ui_story_1017_10171001_61_dialog_content = "Bersiaplah untuk menuju ke timur. Dekat dengan area permukiman. Kita tidak boleh membiarkan satu pun Eclipsite masuk.",
  ui_story_1017_10171001_62_dialog_content = "Siap, Kapten!",
  ui_story_1017_10171001_63_dialog_content = "Leo, personel dari rumah sakit sudah di sini. Saya akan membawa yang terluka parah ke sana.",
  ui_story_1017_10171001_64_dialog_content = "Mengapa kita tidak menyelamatkan rumah sakit untuk warga sipil yang terluka? Aku akan minta teman-temanku di <color=#FFB400>penginapan</color> untuk membantu yang terluka kita.",
  ui_story_1017_10171001_65_dialog_content = "Kapten, bar tersebut sudah...",
  ui_story_1017_10171001_66_dialog_content = "Lalu, mari kita ubah staf Logistik menjadi unit medis untuk sementara waktu, dan tukarkan <color=#FFB400>bijih</color> yang tersisa ke Lumo Stronghold untuk perbekalan medis.",
  ui_story_1017_10171001_67_dialog_content = "Tapi Kapten, Benteng Lumo sudah menutup gerbangnya!",
  ui_story_1017_10171001_68_dialog_content = "Itulah mengapa saya bilang tukar bijih itu dengan mereka!",
  ui_story_1017_10171001_69_dialog_content = "Mengerti, Kapten!",
  ui_story_1017_10171001_70_dialog_content = "Semuanya menjadi bermasalah ketika Benteng Lumo terlibat.",
  ui_story_1017_10171001_71_dialog_content = "Meskipun saya lahir di Twilight, saya tetap berasal dari Lumopolis dan akan berusaha membantu.",
  ui_story_1017_10171001_72_dialog_content = "Jarang melihat seseorang yang bangga menjadi orang Lumopolis.",
  ui_story_1017_10171001_73_dialog_content = "Faksi tidak penting. Saya hanya ingin semua orang di Twilight hidup dengan damai.",
  ui_story_1017_10171001_74_dialog_content = "Kamu berpikir terlalu jauh ke depan.",
  ui_story_1017_10171001_75_dialog_content = "Tanpa bantuan dari Illumina dan Lumopolis, Twilight tidak akan bertahan, apalagi damai.",
  ui_story_1017_10171001_76_dialog_content = "Ingin tahu apa hal terpenting bagi sebuah pasukan?",
  ui_story_1017_10171001_77_dialog_content = "Hati. Kita harus bersatu dalam hati untuk menang. Sayangnya, pasukan Illumina yang kita lihat sama sekali tidak memiliki kohesi.",
  ui_story_1017_10171001_78_dialog_content = "Bisakah Colossus melihat setiap gerakan musuh?",
  ui_story_1017_10171001_79_dialog_content = "Sangat jelas, PlayerName.",
  ui_story_1017_10171001_80_dialog_content = "Baik, Wrath... Grand Marshal.",
  ui_story_1017_10171001_81_dialog_content = "Apakah kamu tidak merasa ini canggung?",
  ui_story_1017_10171001_82_dialog_content = "...",
  ui_story_1017_10171001_83_dialog_content = "Ada apa dengan ekspresi itu?",
  ui_story_1017_10171001_84_dialog_content = "Uh, tidak ada... Aku hanya belum terbiasa bekerja dengan Grand Marshal.",
  ui_story_1017_10171001_85_dialog_content = "Hmm, bukankah kamu cukup dekat dengan Reinhardt?",
  ui_story_1017_10171001_86_dialog_content = "Jadi kenapa kamu gugup di sekitarku? Apa bedanya antara aku dan dia?",
  ui_story_1017_10171001_87_dialog_content = "(Apakah kamu bahkan harus bertanya...?)",
  ui_story_1017_10171001_88_dialog_content = "Panggil saja aku dengan namaku. Aku juga akan memanggilmu dengan namamu sebagai tanda hormat.",
  ui_story_1017_10171001_89_dialog_content = "Mengerti, Wrath...",
  ui_story_1017_10171001_90_dialog_content = "Aku ingin minta bantuanmu terkait prajuritku.",
  ui_story_1017_10171001_91_dialog_content = "Tentu.",
  ui_story_1017_10171001_92_dialog_content = "Saya tidak yakin apakah mereka akan menjadi lebih buruk dalam pertempuran yang akan datang.",
  ui_story_1017_10171001_93_dialog_content = "Untuk saat ini, aku perlu kamu mengunci posisi mereka dan mengaturnya sebelum musuh melancarkan serangan besar.",
  ui_story_1017_10171001_94_dialog_content = "Tidak masalah. Soroz juga bisa membantu.",
  ui_story_1017_10171001_95_dialog_content = "Memindai prajurit abnormal. Perkiraan Waktu: 60 detik.",
  ui_story_1017_10171001_96_dialog_content = "Aku punya pertanyaan.",
  ui_story_1017_10171001_97_dialog_content = "Ada apa?",
  ui_story_1017_10171001_98_dialog_content = "Bagaimana bisa Axelia ada di tim kamu?",
  ui_story_1017_10171001_99_dialog_content = "Seingat saya, dia terluka parah dalam latihan itu dan seharusnya masih dalam masa pemulihan.",
  ui_story_1017_10171001_100_dialog_content = "Itulah kegigihan prajurit Illumina, mengerti?",
  ui_story_1017_10171001_101_dialog_content = "Mempertaruhkan nyawa dan terjun ke pertempuran berulang kali?",
  ui_story_1017_10171001_102_dialog_content = "Kamu tidak berpikir dia bisa melakukannya?",
  ui_story_1017_10171001_103_dialog_content = "Saya memang berpikir dia bisa, saya hanya merasa bahwa Axelia...",
  ui_story_1017_10171001_104_dialog_content = "Dia tidak akan takut atau menginginkan perang seperti orang-orang yang aku kenal.",
  ui_story_1017_10171001_105_dialog_content = "Saya hampir tidak merasakan emosi apa pun darinya dalam pertemuan-pertemuan sebelumnya.",
  ui_story_1017_10171001_106_dialog_content = "Emosi bukanlah senjata untuk kemenangan, Caelestite.",
  ui_story_1017_10171001_107_dialog_content = "Tidak, yang kumaksud adalah—",
  ui_story_1017_10171001_108_dialog_content = "Aku paham maksudmu.",
  ui_story_1017_10171001_109_dialog_content = "Sebelum menjadi Grand Marshal, aku juga memiliki keraguan yang sama seperti kamu.",
  ui_story_1017_10171001_110_dialog_content = "Tapi aku paham ini sekarang:",
  ui_story_1017_10171001_111_dialog_content = "Untuk mengalahkan seseorang yang tak terkalahkan, Anda harus meninggalkan identitas lama dan melihat segala sesuatu dari perspektif orang tersebut.",
  ui_story_1017_10171001_112_dialog_content = "Meninggalkan identitas lama... Tapi aku melihatmu memimpin serangan seperti biasa.",
  ui_story_1017_10171001_113_dialog_content = "Untuk seorang Caelestite yang memiliki persepsi supernatural, pikiranmu ternyata cukup sederhana.",
  ui_story_1017_10171001_114_dialog_content = "Aku hijau karena iri...",
  ui_story_1017_10171001_115_dialog_content = "Kedengarannya seperti bukan pujian…",
  ui_story_1017_10171001_116_dialog_content = "Kamu salah paham. Jaga mata kamu di jalan dan waspadai lubang-lubang.",
  ui_story_1017_10171001_117_dialog_content = "Menemukan prajurit abnormal di bawah rintangan 20 meter di depan.",
  ui_story_1017_10171001_118_dialog_content = "Prajurit tak terduga di depan, Wrath!",
  ui_story_1017_10171001_119_dialog_content = "Ayo.",
  ui_story_1017_10171001_120_dialog_content = "...",
  ui_story_1017_10171001_121_dialog_content = "Apa yang kamu rasakan?",
  ui_story_1017_10171001_122_dialog_content = "...",
  ui_story_1017_10171001_123_dialog_content = "Dia masih agak sadar, tapi tidak bisa mendengar ucapanmu.",
  ui_story_1017_10171001_124_dialog_content = "Biar kucoba bertelepati dengannya dan lihat apa yang bisa kutemukan.",
  ui_story_1017_10171001_125_dialog_content = "Tentu.",
  ui_story_1017_10171001_126_option_content = "Telepati—",
  ui_story_1017_10171001_127_dialog_content = "(Apakah aku dalam suatu kekacauan?)",
  ui_story_1017_10171001_128_dialog_content = "(Menutupi tanah seperti karpet raksasa...)",
  ui_story_1017_10171001_129_dialog_content = "(Bangunan-bangunan bobrok di sekitar sini sepertinya tidak asing...)",
  ui_story_1017_10171001_130_dialog_content = "(Ini harusnya Twilight sih...)",
  ui_story_1017_10171001_131_dialog_content = "(Tapi dari mana semua lumpur ini berasal? Terus berkumpul di bawah kakiku...)",
  ui_story_1017_10171001_132_dialog_content = "(Tampaknya tidak mengalir ke arah tertentu...)",
  ui_story_1017_10171001_133_dialog_content = "Argh…",
  ui_story_1017_10171001_134_dialog_content = "Bagaimana perasaanmu? Tidak enak?",
  ui_story_1017_10171001_135_dialog_content = "Darkflow sedikit membuatku pusing, tapi aku akan bisa melaluinya.",
  ui_story_1017_10171001_136_dialog_content = "Apa yang ada di pikiran para prajurit adalah Twilight yang tertutup dalam rawa-rawa yang tampaknya tak berkesudahan...",
  ui_story_1017_10171001_137_dialog_content = "Lumpur terus berkumpul di bawah kakiku dan rasanya seperti aku bisa jatuh kapan saja.",
  ui_story_1017_10171001_138_dialog_content = "Quagmire, Darkflow... Lumpur dalam pikiran mereka mungkin berkaitan dengan Darkflow dalam kenyataan.",
  ui_story_1017_10171001_139_dialog_content = "Mungkin itu alasan di balik perilaku mereka yang tidak menentu...",
  ui_story_1017_10171001_140_dialog_content = "Jika kita bisa mengetahui asal lumpur ini, mungkin kita bisa menemukan musuh utama...",
  ui_story_1017_10171001_141_dialog_content = "Apa-apaan ini...!",
  ui_story_1017_10171001_142_dialog_content = "Tunggu, bagaimana ini bisa terjadi?",
  ui_story_1017_10171001_143_dialog_content = "Ini salah satu milikmu?",
  ui_story_1017_10171001_144_dialog_content = "Bukankah sudah jelas? Saya hampir membunuhnya!",
  ui_story_1017_10171001_145_dialog_content = "Darkflow sepertinya menghantamnya cukup keras hingga membuatnya kehilangan akal sehatnya...",
  ui_story_1017_10171001_146_dialog_content = "Biar kucoba menyelidiki pikirannya.",
  ui_story_1017_10171001_147_dialog_content = "Pergilah sejauh yang kamu bisa, tetapi hentikan segera jika kamu merasakan bahaya.",
  ui_story_1017_10171001_148_option_content = "Telepati—",
  ui_story_1017_10171001_149_dialog_content = "(Ini adalah skenario yang sama, tetapi lumpurnya mengalir jauh lebih cepat daripada sebelumnya...)",
  ui_story_1017_10171001_150_dialog_content = "(Dan kali ini datang dari arah yang sama.)",
  ui_story_1017_10171001_151_dialog_content = "(Apakah itu Malam Abadi?)",
  ui_story_1017_10171001_152_dialog_content = "(Langit yang suram menyatu dengan sempurna dengan lumpur.)",
  ui_story_1017_10171001_153_dialog_content = "(Itu harusnya... Di situlah pusat komando berada...)",
  ui_story_1017_10171001_154_dialog_content = "(Oh, tidak—)",
  ui_story_1017_10171001_155_dialog_content = "Kamu... Eclipsite!",
  ui_story_1017_10171001_156_dialog_content = "Menyerah!",
  ui_story_1017_10171001_157_dialog_content = "Wrath? Apa yang terjadi padanya?",
  ui_story_1017_10171001_158_dialog_content = "Jangan khawatir, dia baru saja pingsan.",
  ui_story_1017_10171001_159_dialog_content = "Tapi tidak perlu menyelidiki lebih jauh. Bahkan aku pun bisa merasakan Darkflow dalam dirinya sekarang.",
  ui_story_1017_10171001_160_dialog_content = "Lihat cakrawala di sana, semakin gelap saja...",
  ui_story_1017_10171001_161_dialog_content = "Itulah arahnya! Lumpur itu mengalir semakin cepat dan cepat dari Eternal Night dalam pikirannya.",
  ui_story_1017_10171001_162_dialog_content = "Itu pasti tempat pusat komando berada!",
  ui_story_1017_10171001_163_dialog_content = "Jadi kita sudah menemukan lokasi musuh?",
  ui_story_1017_10171001_164_dialog_content = "Aku cukup yakin. Mungkin aku sudah menghabiskan terlalu banyak waktu dengan Darkflow karena aku merasa pusing hanya dengan melihat sekeliling...",
  ui_story_1017_10171001_165_dialog_content = "Kamu benar, langit di atas Malam Abadi semakin gelap.",
  ui_story_1017_10171001_166_dialog_content = "Sepertinya Darkflow bisa mengendalikan prajurit dan mengubah lingkungan. Ada bau busuk di sekitar.",
  ui_story_1017_10171001_167_dialog_content = "<color=#e8d9bb>Ocehan, ocehan...</color>",
  ui_story_1017_10171001_168_dialog_content = "Apakah kamu mendengar itu?",
  ui_story_1017_10171001_169_dialog_content = "Kedengarannya seperti cairan yang mengalir...",
  ui_story_1017_10171001_170_dialog_content = "Cairan mengalir... Oh tidak, jangan bilang ada tanah longsor di Twilight!",
  ui_story_1017_10171001_171_dialog_content = "Dan itu berasal dari Eternal Night!",
  ui_story_1017_10171001_172_dialog_content = "Saya percaya musuh utama sedang mendekat.",
  ui_story_1017_10171001_173_dialog_content = "<color=#e8d9bb>Babble, babble...</color>",
  ui_story_1017_10171001_174_dialog_content = "PlayerName, segerombolan besar Eclipsite terdeteksi di sebelah baratmu. Diperkirakan akan memasuki radius deteksi kamu dalam 5 detik.",
  ui_story_1017_10171001_175_dialog_content = "Secepat itu? Biar aku cek dulu...",
  ui_story_1017_10171001_176_option_content = "Telepati—",
  ui_story_1017_10171001_177_dialog_content = "(Semua hitam... Sungguh suatu kerumitan!)",
  ui_story_1017_10171001_178_dialog_content = "Inilah yang persis saya lihat dalam pikiran mereka, Wrath! Eclipsite sedang menuju ke sini dengan lumpur!",
  ui_story_1017_10171001_179_dialog_content = "Hah?",
  ui_story_1017_10171001_180_dialog_content = "Perbarui Ksatria Lumo sekarang dan suruh mereka mengevakuasi orang-orang!",
  ui_story_1017_10171001_181_dialog_content = "Baik, Grand Marshal!",
  ui_story_1017_10171001_182_dialog_content = "Recon, ikut aku untuk memeriksanya. Engine VII, lindungi bagian belakang!",
  ui_story_1017_10171001_183_dialog_content = "Tidak ada yang bergerak tanpa perintah saya. Jika kalian merasa ada yang salah, segera mundur!",
  ui_story_1017_10171001_184_dialog_content = "Grand Marshal! Prajurit di peleton timur menjadi gila satu demi satu!",
  ui_story_1017_10171001_185_dialog_content = "Timur? Tapi yang aku rasakan justru ke barat...",
  ui_story_1017_10171001_186_dialog_content = "Awas!",
  ui_story_1017_10171001_187_dialog_content = "Bahkan di sini? Tapi bagaimana?",
  ui_story_1017_10171001_188_dialog_content = "Jelas bahwa kita dikelilingi.",
  ui_story_1017_10171001_189_dialog_content = "Tetap dekat denganku, PlayerName!",
  ui_story_1017_10171101_1_dialog_content = "<color=#e8d9bb>Sebuah gedung laboratorium di Illumina, tidak terlalu lama yang lalu...</color>",
  ui_story_1017_10171101_2_dialog_content = "Sedang apa kau?",
  ui_story_1017_10171101_3_dialog_content = "Hanya, tahu saja, berpatroli... Ya, ini giliranku untuk mengawasi area ini hari ini...",
  ui_story_1017_10171101_4_dialog_content = "Ini adalah laboratorium Profesor Ulysses dan tidak ada jadwal patroli rutin.",
  ui_story_1017_10171101_5_dialog_content = "Eh, yah...",
  ui_story_1017_10171101_6_dialog_content = "Siapa yang mengirimkan kamu?",
  ui_story_1017_10171101_7_dialog_content = "Aku…",
  ui_story_1017_10171101_8_dialog_content = "S-saya minta maaf, Komandan Yingel! Saya tidak seharusnya berbohong. Saya hanya...",
  ui_story_1017_10171101_9_dialog_content = "Aku tahu kakakku menjadi bagian dari <color=#FFB400>eksperimen</color> terbesar dalam sejarah Illumina, dan aku sangat iri, itulah mengapa aku...",
  ui_story_1017_10171101_10_dialog_content = "Proyek ini sangat rahasia dan tidak seorang pun anggota keluarga yang harus tahu sampai berhasil.",
  ui_story_1017_10171101_11_dialog_content = "Saya dan saudara saya sangat dekat, jadi saya tahu segalanya tentang dia. Tolong percayai saya! Saya sedang mengatakan yang sebenarnya...",
  ui_story_1017_10171101_12_dialog_content = "...",
  ui_story_1017_10171101_13_dialog_content = "Sejak dia bergabung dalam eksperimen ini, baik Ibu dan saya benar-benar bahagia untuknya!",
  ui_story_1017_10171101_14_dialog_content = "Tapi karena pengalaman yang terbatas, saya tidak terpilih...",
  ui_story_1017_10171101_15_dialog_content = "Kamu merasa sedih?",
  ui_story_1017_10171101_16_dialog_content = "Ya…",
  ui_story_1017_10171101_17_dialog_content = "Akan ada kesempatan lain di masa depan...",
  ui_story_1017_10171101_18_dialog_content = "Benarkah? Aku masih punya kesempatan lain untuk menjadi Bintang Illumina?",
  ui_story_1017_10171101_19_dialog_content = "Tentu.",
  ui_story_1017_10171101_20_dialog_content = "Terima kasih, Komandan Yingel! Aku akan segera pergi.",
  ui_story_1017_10171101_21_dialog_content = "Oke. Mereka seharusnya sedang melawan Eclipsite saat ini.",
  ui_story_1017_10171101_22_dialog_content = "Ya, saudaraku sangat berbakat... Eclipsites tidak akan berpeluang melawannya!",
  ui_story_1017_10171101_23_dialog_content = "...",
  ui_story_1017_10171101_24_dialog_content = "Ah, maaf, Komandan Yingel, saya tidak akan mengambil lebih banyak waktu Anda. Selamat hari!",
  ui_story_1017_10171101_25_dialog_content = "Jadi, apakah itu masa depan Illumina?",
  ui_story_1017_10171101_26_dialog_content = "...",
  ui_story_1017_10171101_27_dialog_content = "<size=30>Profesor...</size>",
  ui_story_1017_10171101_28_dialog_content = "...",
  ui_story_1017_10171101_29_dialog_content = "Profesor Ulysses?",
  ui_story_1017_10171101_30_dialog_content = "Oh, itu dia. Bagaimana penyelidikan berjalan?",
  ui_story_1017_10171101_31_dialog_content = "Ini bukan tentang pekerjaan. Ini masalah lain...",
  ui_story_1017_10171101_32_dialog_content = "Ada apa?",
  ui_story_1017_10171101_33_dialog_content = "Pak, Axelia mengalami luka parah dalam latihan gabungan.",
  ui_story_1017_10171101_34_dialog_content = "Lawan yang dihadapinya adalah Reinhardt, yang paling tangguh yang pernah dia hadapi hingga saat itu.",
  ui_story_1017_10171101_35_dialog_content = "...",
  ui_story_1017_10171101_36_dialog_content = "Apa ada sesuatu yang ingin kau katakan?",
  ui_story_1017_10171101_37_dialog_content = "Pak, Axelia telah mengalami banyak luka parah, namun dia masih terus berjuang untuk Illumina.",
  ui_story_1017_10171101_38_dialog_content = "Aku khawatir setelah Program Phospherus 2.0, dia...",
  ui_story_1017_10171101_39_dialog_content = "Dalam hal ini, Anda bereaksi berlebihan.",
  ui_story_1017_10171101_40_dialog_content = "Berikut perbandingan dari kedua set data. Silahkan lihat.",
  ui_story_1017_10171101_41_dialog_content = "Setelah Phospherus 2.0, kinerja fisik prajurit meningkat 10 kali lipat.",
  ui_story_1017_10171101_42_dialog_content = "Mungkin bisa mencapai 20, bahkan 50 kali di masa depan.",
  ui_story_1017_10171101_43_dialog_content = "Axelia mencetak skor sangat tinggi pada data pasca-eksperimen dengan kerusakan pertempuran yang jauh lebih sedikit.",
  ui_story_1017_10171101_44_dialog_content = "Maksudnya, dia berada di puncak kemampuannya.",
  ui_story_1017_10171101_45_dialog_content = "Dan itu berlaku untuk semua prajurit yang dikirim ke Twilight.",
  ui_story_1017_10171101_46_dialog_content = "Tapi pak, saya masih merasa mengirimkan Axelia kembali ke medan perang setelah dia baru saja pulih itu... kejam...",
  ui_story_1017_10171101_47_dialog_content = "Dan hal itu berlaku untuk semua prajurit muda yang percaya bahwa mereka adalah \"bintang masa depan\" dari Illumina.",
  ui_story_1017_10171101_48_dialog_content = "Ya, kenyataannya memang kejam, dan itu adalah tugas mereka sebagai prajurit Illumina.",
  ui_story_1017_10171101_49_dialog_content = "Harus benar-benar seperti itu?",
  ui_story_1017_10171101_50_dialog_content = "Jika mereka tidak menyadari bahwa inilah cara mereka mendapatkan kekuatan mereka...",
  ui_story_1017_10171101_51_dialog_content = "Sangat menghancurkan bagi mereka ketika mereka sedang jatuh bebas setelah mencapai puncak.",
  ui_story_1017_10171101_52_dialog_content = "Yingel, jalur pertanyaan Anda tidak sesuai untuk seorang petugas intelijen.",
  ui_story_1017_10171101_53_dialog_content = "Kecuali jika kamu memiliki permintaan lain, saya harus melanjutkan eksperimen saya.",
  ui_story_1017_10171101_54_dialog_content = "Tapi Profesor—",
  ui_story_1017_10171101_55_dialog_content = "Sebelum menjelaskan diri Anda, coba cari tahu tujuan yang ingin dicapai.",
  ui_story_1017_10171101_56_dialog_content = "Jika kamu tidak bisa, aku rasa perlu bagi kamu untuk berhenti dari yang sedang kamu kerjakan dan mampir ke labku lebih sering.",
  ui_story_1017_10171101_57_dialog_content = "Satu dari sepuluh ribu subjek datang ke sini hanya karena satu alasan—",
  ui_story_1017_10171101_58_dialog_content = "Melampaui batas fisik, mengalahkan Eclipsites, melindungi Illumina dan Aurorian, itu saja.",
  ui_story_1017_10171101_59_dialog_content = "Seorang Aurorian mati di lab ini setiap hari, tetapi itu lebih baik daripada kita semua mati saat Eclipsites datang.",
  ui_story_1017_10171101_60_dialog_content = "Tujuan saya adalah mencapai terobosan dan mengasah gudang senjata. Tanpa peningkatan, tidak ada masa depan bagi Aurorian.",
  ui_story_1017_10171101_61_dialog_content = "Eksperimen, persenjataan, data... Aku menghargai semua yang kamu lakukan.",
  ui_story_1017_10171101_62_dialog_content = "Tapi, saya tidak bisa membenarkan pengorbanan prajurit, terutama ketika mereka tidak menyadari akibatnya.",
  ui_story_1017_10171101_63_dialog_content = "Nah, beberapa orang tahu konsekuensinya.",
  ui_story_1017_10171101_64_dialog_content = "Dia mau melakukan itu demi tujuan tersebut. Bagaimana dengan kamu?",
  ui_story_1017_10171101_65_dialog_content = "Tidak, bukan seperti itu cara Illumina sampai sejauh ini...",
  ui_story_1017_10171101_66_dialog_content = "Ugh!",
  ui_story_1017_10171101_67_dialog_content = "Suara apa itu...?",
  ui_story_1017_10171101_68_dialog_content = "Karena eksperimen sudah dimulai, Anda sebaiknya mengamati kesenjangan antara kedua kelompok.",
  ui_story_1017_10171101_69_dialog_content = "(Tidak... suara itu...)",
  ui_story_1017_10171101_70_dialog_content = "Keduanya meningkatkan kondisi fisik, namun hasilnya sama sekali berbeda.",
  ui_story_1017_10171101_71_dialog_content = "Subjek di sebelah kiri lebih mudah meledak dalam waktu yang lebih lama dengan Seed baru.",
  ui_story_1017_10171101_72_dialog_content = "Yang di sebelah kanan hampir seluruhnya dilahap oleh Eclipsite.",
  ui_story_1017_10171101_73_dialog_content = "Sekarang kamu tahu mengapa Reinhardt harus dihilangkan dengan segala cara?",
  ui_story_1017_10171101_74_dialog_content = "Subjek di sebelah kiri...",
  ui_story_1017_10171101_75_dialog_content = "Terlepas dari bagaimana Anda menafsirkan sejarah dan kebenaran, inilah kenyataan dunia nyata.",
  ui_story_1017_10171101_76_dialog_content = "Ini adalah satu-satunya cara bagi kita untuk bertahan hidup dan maju.",
  ui_story_1017_10171101_77_dialog_content = "Darkover akan datang, jadi kita harus menggunakan ini untuk tetap unggul darinya.",
  ui_story_1017_10171101_X78_dialog_content = "(Kepalaku... sakit...)",
  ui_story_1017_10171101_78_dialog_content = "Profesor, subjek di sebelah kiri menunjukkan reaksi yang kuat terhadap Darkflow di ruangan sebelah kanan!",
  ui_story_1017_10171101_79_dialog_content = "Dokter, subjek di sebelah kiri menunjukkan reaksi kuat terhadap Darkflow di ruangan sebelah kanan!",
  ui_story_1017_10171101_80_dialog_content = "Ya, memang begitu seharusnya. Benih bereaksi terhadap benih lainnya.",
  ui_story_1017_10171101_81_dialog_content = "Aku penasaran apa yang akan dia lakukan selanjutnya...",
  ui_story_1017_10171101_X82_dialog_content = "...",
  ui_story_1017_10171101_82_dialog_content = "Profesor, dia mencoba menerobos kaca dan masuk ke ruangan di sebelah kanan!",
  ui_story_1017_10171101_83_dialog_content = "Dokter, dia mencoba menembus kaca dan masuk ke ruangan di sebelah kanan!",
  ui_story_1017_10171101_84_dialog_content = "Aku lihat dia bahkan tidak mencoba membuka pintu, tapi hanya memecahkan kacanya saja.",
  ui_story_1017_10171101_85_dialog_content = "Sangat baik, kali ini tidak meningkatkan otak dan mengatasi kekurangan pada batch pertama Seed.",
  ui_story_1017_10171101_86_dialog_content = "Bagaimana ini berbeda dari membuat Eclipsite yang sebenarnya?",
  ui_story_1017_10171101_87_dialog_content = "Mengalahkan Eclipsites memerlukan cara yang luar biasa.",
  ui_story_1017_10171101_88_dialog_content = "Di luar pertempuran, dia tetap seorang Aurorian sesama.",
  ui_story_1017_10171101_89_dialog_content = "Tidak, Aurorian dari Illumina tidak akan pernah bersatu dengan Eclipsites... Saya mohon, tolong hentikan eksperimen ini segera.",
  ui_story_1017_10171101_90_dialog_content = "...",
  ui_story_1017_10171101_91_dialog_content = "Profesor, dia berhasil! Dia mulai melahap Eclipsite!",
  ui_story_1017_10171101_92_dialog_content = "Profesor Ulysses, tolong hentikan eksperimen ini segera!",
  ui_story_1017_10171101_93_dialog_content = "Baru saja dimulai.",
  ui_story_1017_10171101_94_dialog_content = "Seorang prajurit Illumina sedang memakan Eclipsite! Ini adalah pelanggaran besar terhadap prosedur... Tolong berhenti sekarang!",
  ui_story_1017_10171101_95_dialog_content = "Jika tidak salah ingat, aku menulis prosedurnya.",
  ui_story_1017_10171101_96_dialog_content = "Verifikasi dan terobosan adalah tujuan dari semua eksperimen.",
  ui_story_1017_10171101_97_dialog_content = "Profesor! Subjek tes sedang memukul kaca kita!",
  ui_story_1017_10171101_98_dialog_content = "(Tatapan penuh amarah pembunuh di matanya... Apakah dia sedang menatapku?)",
  ui_story_1017_10171101_99_dialog_content = "Tolong... Hentikan eksperimen...",
  ui_story_1017_10171101_100_dialog_content = "Profesor, ada yang tidak beres dengan Komandan Yingel!",
  ui_story_1017_10171101_101_dialog_content = "Bagaimana perasaanmu, Yingel?",
  ui_story_1017_10171101_102_dialog_content = "Kepalaku... sakit... sangat...",
  ui_story_1017_10171101_103_dialog_content = "Mengapa kau tidak pergi dan beristirahat dulu?",
  ui_story_1017_10171101_104_dialog_content = "Catat, reaksi dan jarak antara Seed perlu konfirmasi lebih lanjut.",
  ui_story_1017_10171101_105_dialog_content = "Profesor! Gelasnya baru saja—",
  ui_story_1017_10171101_106_dialog_content = "Panggil keamanan!",
  ui_story_1017_10171101_107_dialog_content = "Tidak! Bergerak, Profesor!",
  ui_story_1017_10171101_108_dialog_content = "...",
  ui_story_1017_10171201_1_dialog_content = "Kita tidak bisa melanjutkan! Rawan lumpur menyebar terlalu cepat!",
  ui_story_1017_10171201_2_dialog_content = "Semuanya, bubar dan mundur!",
  ui_story_1017_10171201_3_dialog_content = "Tapi, apakah kamu akan terus melanjutkan?",
  ui_story_1017_10171201_4_dialog_content = "Beberapa prajuritku terjebak di dalam. Aku tidak akan meninggalkan mereka.",
  ui_story_1017_10171201_5_dialog_content = "Tapi setengah dari Twilight kini tertutup lumpur...",
  ui_story_1017_10171201_6_dialog_content = "Itulah mengapa kita harus membasmi musuh utama sebelum ia menenggelamkan seluruh kota.",
  ui_story_1017_10171201_7_dialog_content = "Dari serangan itu, musuh di tengah bergerak secara tidak teratur.",
  ui_story_1017_10171201_8_dialog_content = "Ini adalah pil, memang. Mengelilingi kita dengan Eclipsites sementara bersembunyi di lumpur dan menembak!",
  ui_story_1017_10171201_9_dialog_content = "Kita harus terus maju untuk menemukannya.",
  ui_story_1017_10171201_10_dialog_content = "Saya khawatir lebih banyak prajurit akan mati jika ini terus berlanjut...",
  ui_story_1017_10171201_11_dialog_content = "Tak ada yang mati sia-sia, PlayerName. Jangan merasa kasihan pada mereka!",
  ui_story_1017_10171201_12_dialog_content = "Aku hanya...",
  ui_story_1017_10171201_13_dialog_content = "Tidak perlu. Semua orang sudah tahu kemungkinan tersebut sebelum kita datang.",
  ui_story_1017_10171201_14_dialog_content = "Sebenarnya, saya ingin bertanya, mengapa beberapa dari mereka dikirim untuk bertempur?",
  ui_story_1017_10171201_15_dialog_content = "Apa yang kamu ketahui secara khusus?",
  ui_story_1017_10171201_16_dialog_content = "Aku hanya menebak di sini...",
  ui_story_1017_10171201_17_dialog_content = "Untuk memiliki reaksi yang begitu intens terhadap Darkflow, mereka dan Eclipsites mungkin memiliki hal yang sama di dalam tubuh mereka.",
  ui_story_1017_10171201_18_dialog_content = "Rasanya begitu akrab ketika saya terhubung pikiran dengan mereka.",
  ui_story_1017_10171201_19_dialog_content = "Begitu juga saat aku ditanamkan Seed...",
  ui_story_1017_10171201_20_dialog_content = "Itulah satu-satunya penjelasan untuk perubahan mereka, bahkan mengikuti perintah pusat.",
  ui_story_1017_10171201_21_dialog_content = "Hal itu tidak terjadi pada prajurit di Twilight.",
  ui_story_1017_10171201_22_dialog_content = "Bagaimana perasaanmu tentangku?",
  ui_story_1017_10171201_23_dialog_content = "Kamu...",
  ui_story_1017_10171201_24_dialog_content = "Yah, terus terang, saya menyadari mengapa mereka mengirim saya ke Twilight saat para prajurit mulai menunjukkan tanda-tanda.",
  ui_story_1017_10171201_25_dialog_content = "Bukankah Anda di sini untuk membantu Twilight?",
  ui_story_1017_10171201_26_dialog_content = "Kami benar-benar membutuhkan bantuan sekarang, tapi apakah kamu melihat ada orang yang datang?",
  ui_story_1017_10171201_27_dialog_content = "...",
  ui_story_1017_10171201_28_dialog_content = "Pesan dan sinyal minta bantuan tidak mendapat jawaban sepanjang pertempuran.",
  ui_story_1017_10171201_29_dialog_content = "Mungkin karena gangguan Darkflow?",
  ui_story_1017_10171201_30_dialog_content = "Kamu tidak mengerti Illumina. Kami tidak pernah bertempur dalam pertempuran yang tidak kami persiapkan, kecuali jika ada tujuan lain.",
  ui_story_1017_10171201_31_dialog_content = "Sekarang kita hanya bisa mengandalkan diri kita sendiri.",
  ui_story_1017_10171201_32_dialog_content = "Penyesalan saya hanya kemungkinan bahwa, saya akan berakhir seperti Reinhardt...",
  ui_story_1017_10171201_33_dialog_content = "Sungguh pil pahit untuk ditelan!",
  ui_story_1017_10171201_34_dialog_content = "Aku akan bersamamu dalam ini, Wrath...",
  ui_story_1017_10171201_35_dialog_content = "Cukup, sekarang bukan saatnya untuk baper. Apa yang dilihat Soroz?",
  ui_story_1017_10171201_36_dialog_content = "Sekitar 300 meter di depan, ada gugusan Darkflow besar yang bergerak di rawa-rawa.",
  ui_story_1017_10171201_37_dialog_content = "Apakah itu central command atau...?",
  ui_story_1017_10171201_38_dialog_content = "Darkflow berkumpul dan menyebar di sekitar. Penilaian awal menunjukkan bahwa ini adalah Eclipsite tingkat tinggi.",
  ui_story_1017_10171201_39_dialog_content = "Apakah itu menuju ke arah kita?",
  ui_story_1017_10171201_40_dialog_content = "Kemunculan entitas ini tidak menentu, sehingga sulit untuk memprediksi lintasan gerakannya atau mengantisipasi waktu kedatangannya.",
  ui_story_1017_10171201_41_dialog_content = "Kamu melihat ada yang memimpin?",
  ui_story_1017_10171201_42_dialog_content = "Terus mencari...",
  ui_story_1017_10171201_43_dialog_content = "Terima kasih, Soroz.",
  ui_story_1017_10171201_44_dialog_content = "Hei, ke mana dia pergi?",
  ui_story_1017_10171201_45_dialog_content = "Waow, dari mana datangnya semua Eclipsite ini?",
  ui_story_1017_10171201_46_dialog_content = "Apa yang terjadi, PlayerName!",
  ui_story_1017_10171201_47_dialog_content = "(Tunggu, tubuhku terasa...)",
  ui_story_1017_10171201_48_dialog_content = "Ada Eclipsite tingkat tinggi yang bergerak di rawa-rawa!",
  ui_story_1017_10171201_49_dialog_content = "Lihat itu? Bahkan jika kita tidak menyerang, Eclipsite tetap akan mencoba membuat kita melakukannya!",
  ui_story_1017_10171201_50_dialog_content = "Jadi sebaiknya kita bertarung dengan baik!",
  ui_story_1017_10171201_51_dialog_content = "Mungkin ada banyak Eclipsite yang bersembunyi di rawa. Aku siap untuk membunuh!",
  ui_story_1017_10171201_52_dialog_content = "Tahan dulu, Wrath, terlalu berbahaya untuk menginjak lumpur!",
  ui_story_1017_10171201_53_dialog_content = "Tidak, aku harus melanjutkan! Meskipun rawa ini menenggelamkanku, aku harus membunuhnya!",
  ui_story_1017_10171201_54_dialog_content = "Semua perusahaan, tarik Eclipsite umum ke kedua sisi!",
  ui_story_1017_10171201_55_dialog_content = "Engine VII, hantam Eclipsite di depan dan bersihkan jalan untukku!",
  ui_story_1017_10171201_56_dialog_content = "Ya!",
  ui_story_1017_10171201_57_dialog_content = "Kamu pikir kamu siapa, bersembunyi di belakang antek-antekmu...",
  ui_story_1017_10171201_58_dialog_content = "Grand Marshal! Eclipsite terlihat di sisi barat!",
  ui_story_1017_10171201_59_dialog_content = "Grand Marshal, mereka telah pindah ke sisi timur!",
  ui_story_1017_10171201_60_dialog_content = "Jadi, upaya mengepung selanjutnya harusnya...",
  ui_story_1017_10171201_61_dialog_content = "Perhatikan di bawah kaki, Wrath!",
  ui_story_1017_10171201_62_dialog_content = "Aku tahu strategi gerakanmu adalah—",
  ui_story_1017_10171201_63_dialog_content = "Sungguh bodoh sekali!",
  ui_story_1017_10171201_64_dialog_content = "Grand Marshal! Kau baik-baik saja?",
  ui_story_1017_10171201_65_dialog_content = "Ini... sama sekali tidak cukup... untuk berbuat apa-apa padaku...",
  ui_story_1017_10171201_66_dialog_content = "Kamu terlihat buruk! Kembali padaku!",
  ui_story_1017_10171201_67_dialog_content = "Tidak, aku yang memukulnya...",
  ui_story_1017_10171201_68_dialog_content = "Cepat sekali. Aku hanya melihatnya muncul dari lumpur sebentar sebelum menyelam kembali.",
  ui_story_1017_10171201_69_dialog_content = "Kau melukainya?",
  ui_story_1017_10171201_70_dialog_content = "Kurasa tidak. Tapi itu... mencoba untuk...",
  ui_story_1017_10171201_71_dialog_content = "Kamu menggigil di seluruh tubuh, Wrath!",
  ui_story_1017_10171201_72_dialog_content = "Itu dia... Hal itu... mencoba untuk...",
  ui_story_1017_10171201_73_dialog_content = "Marsekal Agung! Engine VII akan menjemput Anda! Ayo naik dan keluar dari rawa!",
  ui_story_1017_10171201_74_dialog_content = "Tidak ada yang mendekati!",
  ui_story_1017_10171201_75_dialog_content = "Rawa ini adalah wilayah kekuasaan Eclipsite itu.",
  ui_story_1017_10171201_76_dialog_content = "Jika kamu naik... kamu akan...",
  ui_story_1017_10171201_77_dialog_content = "Tapi kamu sedang mengerjakannya sekarang!",
  ui_story_1017_10171201_78_dialog_content = "(Tetap waspada, tetap waspada!)",
  ui_story_1017_10171201_79_dialog_content = "Keluar dari sana, Wrath!",
  ui_story_1017_10171201_80_dialog_content = "Ini menerjang ke arah ini... Aku tidak bisa mundur.",
  ui_story_1017_10171201_81_dialog_content = "Jika kamu jatuh, Twilight selesai!",
  ui_story_1017_10171201_82_dialog_content = "Aku tidak akan jatuh... Sekarang...",
  ui_story_1017_10171201_83_dialog_content = "Merasa... kekuatan melonjak dalam diriku...",
  ui_story_1017_10171201_84_dialog_content = "Aku harus membunuhnya!",
  ui_story_1017_10171201_85_dialog_content = "Lalu aku akan mencari tahu lokasinya untukmu!",
  ui_story_1017_10171201_86_dialog_content = "Kembali!",
  ui_story_1017_10171201_87_dialog_content = "Darkflow lebih lemah di posisi sepuluhmu. Kelilingi dari sana dan serang Eclipsite dari belakang!",
  ui_story_1017_10171201_88_dialog_content = "Eclipsite akan datang ke arahmu, mundur!",
  ui_story_1017_10171201_89_dialog_content = "Darkflow semakin berkurang 5 langkah di belakangmu, silahkan lanjutkan...",
  ui_story_1017_10171201_90_dialog_content = "(Apa? Tiba-tiba... aku membeku di tempat ini...)",
  ui_story_1017_10171201_91_dialog_content = "PlayerName!",
  ui_story_1017_10171201_92_dialog_content = "(Ayo, bergerak, Eclipsites akan datang!)",
  ui_story_1017_10171201_93_dialog_content = "PlayerName?!",
  ui_story_1017_10171201_94_dialog_content = "(Tidak, aku sama sekali tidak bisa bergerak...)",
  ui_story_1017_10171201_95_dialog_content = "(Aku harus membimbing Wrath secara telepati...)",
  ui_story_1017_10171301_1_dialog_content = "Yang lainnya! Tombak petir, tembus!",
  ui_story_1017_10171301_2_dialog_content = "(Semakin lama ini berlangsung, semakin sedikit kendali yang aku miliki atas tubuhku...)",
  ui_story_1017_10171301_3_dialog_content = "(Dan perasaan itu berubah dari kebingungan menjadi haus darah...)",
  ui_story_1017_10171301_4_dialog_content = "(Apakah aku akan berakhir seperti tentara-tentara itu...?)",
  ui_story_1017_10171301_5_dialog_content = "(Tidak!)",
  ui_story_1017_10171301_6_dialog_content = "(Aku tidak boleh jatuh! Tidak di sini, tidak sekarang!)",
  ui_story_1017_10171301_7_dialog_content = "Hai, awas!",
  ui_story_1017_10171301_8_dialog_content = "Aduh!",
  ui_story_1017_10171301_9_dialog_content = "Kembali bersama kami sekarang?",
  ui_story_1017_10171301_10_dialog_content = "Setelah dilempar, ya.",
  ui_story_1017_10171301_11_dialog_content = "Apa katamu?",
  ui_story_1017_10171301_12_dialog_content = "(Tunggu, PlayerName yang sedang berbicara...)",
  ui_story_1017_10171301_13_dialog_content = "(Mengapa aku merasa sedang berbicara dengan Eclipsite?)",
  ui_story_1017_10171301_14_dialog_content = "Kau baik-baik saja?",
  ui_story_1017_10171301_15_dialog_content = "Aku baik-baik saja...",
  ui_story_1017_10171301_16_dialog_content = "(Ini PlayerName! Ini PlayerName di depanku!)",
  ui_story_1017_10171301_17_dialog_content = "Wrath!",
  ui_story_1017_10171301_18_dialog_content = "Aku baik-baik saja.",
  ui_story_1017_10171301_19_dialog_content = "Bukankah sudah kubilang untuk menjauh dari rawa-rawa itu?",
  ui_story_1017_10171301_20_dialog_content = "Tapi kamu melangkah masuk ke dalamnya seperti yang dilakukan prajurit sebelumnya...",
  ui_story_1017_10171301_21_dialog_content = "...",
  ui_story_1017_10171301_22_dialog_content = "Wrath?",
  ui_story_1017_10171301_23_dialog_content = "(Ada yang salah dengan Wrath...)",
  ui_story_1017_10171301_24_dialog_content = "Ada Eclipsites di sana. Aku harus pergi membunuh mereka!",
  ui_story_1017_10171301_25_dialog_content = "Apa? Saya tidak melihat ada Eclipsite sama sekali!",
  ui_story_1017_10171301_26_dialog_content = "Tombak petir, tusuk!",
  ui_story_1017_10171301_27_dialog_content = "Wrath, itu bukan Eclipsite. Itu hanya lumpur biasa.",
  ui_story_1017_10171301_28_dialog_content = "Tombak petir, tusuk!",
  ui_story_1017_10171301_29_dialog_content = "Apa yang terjadi di sini?",
  ui_story_1017_10171301_30_dialog_content = "Kurasa kamu masih bingung.",
  ui_story_1017_10171301_31_dialog_content = "Jadi, Eclipsite bersembunyi di lumpur, menunggu untuk menyergap kita?",
  ui_story_1017_10171301_32_dialog_content = "(Dia bisa mendeteksi dan bereaksi terhadap Eclipsite, tetapi sepertinya tidak sepenuhnya mengendalikan tindakannya...)",
  ui_story_1017_10171301_33_dialog_content = "Mulai amati selagi aku masih bisa pergi!",
  ui_story_1017_10171301_34_dialog_content = "Ayo! Jam satu!",
  ui_story_1017_10171301_35_dialog_content = "Siap!",
  ui_story_1017_10171301_36_dialog_content = "Jam satu, Wrath!",
  ui_story_1017_10171301_37_dialog_content = "...",
  ui_story_1017_10171301_38_dialog_content = "Kamu salah jalan!",
  ui_story_1017_10171301_39_dialog_content = "PlayerName, Wrath telah menyerbu ke dalam kawanan Eclipsite.",
  ui_story_1017_10171301_40_dialog_content = "Para Eclipsite akan menghancurkannya!",
  ui_story_1017_10171301_41_dialog_content = "Force Boost!",
  ui_story_1017_10171301_42_dialog_content = "(Ini adalah quagmire...)",
  ui_story_1017_10171301_43_dialog_content = "(Ini bergerak cepat, dan ke segala arah.)",
  ui_story_1017_10171301_44_dialog_content = "(Hei, tempat ini sudah terganggu...)",
  ui_story_1017_10171301_45_dialog_content = "(Cahaya!)",
  ui_story_1017_10171301_46_dialog_content = "(Lumpur itu menggerombol dan membentuk sebuah gambar...)",
  ui_story_1017_10171301_47_dialog_content = "(Ini adalah... Ulysses, Belisaria, dan di layar ada...)",
  ui_story_1017_10171301_48_dialog_content = "(Itu menghilang sebelum saya bisa memahami sisanya... Wrath tidak ada di sini, meskipun.)",
  ui_story_1017_10171301_49_dialog_content = "(Lagi bersinar!)",
  ui_story_1017_10171301_50_dialog_content = "(Ini Reinhardt!)",
  ui_story_1017_10171301_51_dialog_content = "(Seorang Reinhardt muda... dan penonton, spanduk...)",
  ui_story_1017_10171301_52_dialog_content = "(\"Ujian Terakhir Marsekal Agung Illumina\"... Kalah dari Reinhardt, sepertinya...)",
  ui_story_1017_10171301_53_dialog_content = "(Hujan...?)",
  ui_story_1017_10171301_54_dialog_content = "(Hujan di tempat yang tampak seperti Undercity?)",
  ui_story_1017_10171301_55_dialog_content = "(Hari itu pasti tak terlupakan untuk Wrath...)",
  ui_story_1017_10171301_56_dialog_content = "(Ini adalah... laboratorium Illumina.)",
  ui_story_1017_10171301_57_dialog_content = "(Saya melihat Ulysses dan yang lain di sekitar tempat tidur laboratorium.)",
  ui_story_1017_10171301_58_dialog_content = "(Di atas tempat tidur ada...)",
  ui_story_1017_10171301_59_dialog_content = "(Reinhardt?)",
  ui_story_1017_10171301_60_dialog_content = "(Bagaimana bisa Reinhardt?)",
  ui_story_1017_10171301_61_dialog_content = "(Dan bukan Wrath?!)",
  ui_story_1017_10171301_62_dialog_content = "(Tunggu sebentar, itu bukan Ulysses di samping tempat tidur... Itu Wrath!)",
  ui_story_1017_10171301_63_dialog_content = "(Bisakah kamu mendengarku, Wrath?!)",
  ui_story_1017_10171301_64_dialog_content = "(...)",
  ui_story_1017_10171301_65_dialog_content = "(Bangun, kamu sedang berada di Twilight melawan Eclipsites sekarang!)",
  ui_story_1017_10171301_66_dialog_content = "(Eclipsites... Siapa pun yang naik ke tempat tidur akan berubah menjadi Eclipsites...)",
  ui_story_1017_10171301_67_dialog_content = "(Twilight akan segera dihancurkan dan kamu terluka di mana-mana! Bangun!)",
  ui_story_1017_10171301_68_dialog_content = "(Bagaimana bisa Reinhardt tidak pernah terluka?)",
  ui_story_1017_10171301_69_dialog_content = "(Karena dia adalah seorang Eclipsite.)",
  ui_story_1017_10171301_70_dialog_content = "(Semua orang terluka! Tapi kamu adalah Grand Marshal dan prajurit-prajurit membutuhkanmu!)",
  ui_story_1017_10171301_71_dialog_content = "(Marsekal Agung...)",
  ui_story_1017_10171301_72_dialog_content = "(Apakah ini berhasil? Biar saya coba cara lain.)",
  ui_story_1017_10171301_73_dialog_content = "(Ujian Terakhir dari Grand Marshal!)",
  ui_story_1017_10171301_74_dialog_content = "(Kamu belum mengalahkan Reinhardt belum. Kembali ke pertempuran!)",
  ui_story_1017_10171301_75_dialog_content = "(Reinhardt... Sial Reinhardt!)",
  ui_story_1017_10171301_76_dialog_content = "(Ya, Reinhardt masih di arena. Tunjukkan bahwa kamu lebih baik!)",
  ui_story_1017_10171301_77_dialog_content = "(Wrath...!)",
  ui_story_1017_10171301_78_dialog_content = "PlayerName, akhirnya kamu sadar kembali.",
  ui_story_1017_10171301_79_dialog_content = "Aku baik-baik saja. Di mana Wrath? Bagaimana keadaannya?",
  ui_story_1017_10171301_80_dialog_content = "Evaluasi awal menunjukkan bahwa kesadarannya sepertinya telah pulih sepenuhnya, dan dia berhasil menekan Eclipsite sekali lagi.",
  ui_story_1017_10171301_81_dialog_content = "Bagus!",
  ui_story_1017_10171301_82_dialog_content = "Apa yang baru saja kamu lakukan, memulai Forced Boost saat kondisi Wrath belum pasti, sangat berisiko.",
  ui_story_1017_10171301_83_dialog_content = "Aku tahu, tapi itu adalah keadaan darurat dan aku tidak punya waktu untuk terbuang...",
  ui_story_1017_10171301_84_dialog_content = "Mungkin aku merasa aman karena kamu ada di sekitar.",
  ui_story_1017_10171301_85_dialog_content = "Lihat ke kanan Anda—itu adalah Ksatria Ironthorn yang telah menjaga keamanan Anda.",
  ui_story_1017_10171301_86_dialog_content = "Leo dan teman-temannya ada di sini!",
  ui_story_1017_10171301_87_dialog_content = "Mereka bergabung dalam pertempuran saat kamu sedang terhubung ke Wrath.",
  ui_story_1017_10171301_88_dialog_content = "Terima kasih, Soroz!",
  ui_story_1017_10171301_89_dialog_content = "Soroz akan terus mengarahkan untuk kamu.",
  ui_story_1017_10171301_90_dialog_content = "Tombak petir, tusuk!",
  ui_story_1017_10171301_91_dialog_content = "Ngomong apa kamu barusan?",
  ui_story_1017_10171301_92_option_content = "Aku mencoba membantu",
  ui_story_1017_10171301_93_dialog_content = "Senang melihatmu kembali bersama kami.",
  ui_story_1017_10171301_94_dialog_content = "Urus urusanmu sendiri.",
  ui_story_1017_10171301_95_option_content = "Aku tidak bermaksud mengatakan itu",
  ui_story_1017_10171301_96_dialog_content = "Aku hanya mencoba menyadarkanmu...",
  ui_story_1017_10171301_97_dialog_content = "Berhenti melihat hal-hal yang seharusnya tidak kamu lihat, paham?",
  ui_story_1017_10171301_98_dialog_content = "Yah, senang melihatmu mencela aku seperti itu lagi!",
  ui_story_1017_10171301_99_dialog_content = "Kita masih harus melindungi Twilight.",
  ui_story_1017_10171301_100_dialog_content = "Bahkan jika aku berubah menjadi Eclipsite, aku akan menjadi orang yang memastikan kota tetap utuh!",
  ui_story_1017_10171301_101_dialog_content = "Perhatian, Legiun Penjaga!",
  ui_story_1017_10171301_102_dialog_content = "Kita semua pernah merasakan ketidaknyamanan dalam berbagai tingkatan di medan pertempuran, tetapi percayalah, itu hanya sementara.",
  ui_story_1017_10171301_103_dialog_content = "Cobalah untuk berkonsentrasi, hal itu akan mengurangi banyak dampak negatif dari Darkflow.",
  ui_story_1017_10171301_104_dialog_content = "Aku jamin, aku akan menemukan setiap prajurit yang hilang, tapi hingga saat itu, aku membutuhkan kalian semua!",
  ui_story_1017_10171301_105_dialog_content = "Siapa saja yang terluka atau tidak sepenuhnya sadar, kembali ke Illumina segera!",
  ui_story_1017_10171301_106_dialog_content = "Bagi kalian yang masih bisa bertarung atau <color=#FFB400>tidak takut akan pengaruh Darkflow</color>, ikuti aku menyerang pusat komando!",
  ui_story_1017_10171301_107_dialog_content = "Ya!!!",
  ui_story_1017_10171401_1_dialog_content = "Apakah kamu sudah puas?",
  ui_story_1017_10171401_2_dialog_content = "Bahkan tidak dekat—",
  ui_story_1017_10171401_3_dialog_content = "Semua hal baik tentu harus disimpan hingga akhir. \"Karpet\" ini sangat rapi tersusun.",
  ui_story_1017_10171401_4_dialog_content = "Lahap mereka semua—",
  ui_story_1017_10171401_5_dialog_content = "Berhenti bergerak. Aku sedang melakukan penyesuaian terakhir.",
  ui_story_1017_10171401_6_dialog_content = "Tempat ini menyedihkan dibandingkan dengan lab yang sebenarnya. Progresnya terlalu lambat.",
  ui_story_1017_10171401_7_dialog_content = "(Bahasa Eclipsian) Ada seorang Aurorian yang menolak untuk jatuh...",
  ui_story_1017_10171401_8_dialog_content = "Jangan khawatir, Grand Marshal baru adalah kursus terakhir dari Mudbundle.",
  ui_story_1017_10171401_9_dialog_content = "Berikan aku segalanya—",
  ui_story_1017_10171401_10_dialog_content = "(Eclipsian) Bukan dia, yang lain. Aurorian ini hampir tidak terpengaruh.",
  ui_story_1017_10171401_11_dialog_content = "Ada yang baru? Aku harus segera memeriksanya.",
  ui_story_1017_10171401_12_dialog_content = "...",
  ui_story_1017_10171401_13_dialog_content = "Huh, aku mengharapkan lebih dari seorang bodoh yang tak bisa bertarung keluar dari kantong kertas basah.",
  ui_story_1017_10171401_14_dialog_content = "Axelia adalah mesin perang. Axelia telah berjuang.",
  ui_story_1017_10171401_15_dialog_content = "Kupikir kamu bukan bisu. Karena kamu bisa membuka mulut, coba rasakan ini.",
  ui_story_1017_10171401_16_dialog_content = "...",
  ui_story_1017_10171401_17_dialog_content = "Bagus. Apa tujuanmu jika bukan membunuh Eclipsite?",
  ui_story_1017_10171401_18_dialog_content = "\"Axelia harus mengalahkan Marsekal Agung Reinhardt dengan segala cara.\"",
  ui_story_1017_10171401_19_dialog_content = "Heh, sulit dipercaya Ulysses membuatnya berantakan seperti itu. Mungkin dia tidak peduli apakah kamu selamat atau tidak.",
  ui_story_1017_10171401_20_dialog_content = "\"Axelia harus hidup sebagai seorang manusia.\"",
  ui_story_1017_10171401_21_dialog_content = "Cukup bicara. Saatnya Mudbundle menikmati hidangannya.",
  ui_story_1017_10171401_22_dialog_content = "Kerja bagus menjebak seluruh tentara di sini. Kamu bisa melanjutkannya sendiri dari sini.",
  ui_story_1017_10171401_23_dialog_content = "(Bahasa Eclipsian) Ya.",
  ui_story_1017_10171401_24_dialog_content = "...",
  ui_story_1017_10171401_25_dialog_content = "Kamu akan mati karena menyergap prajuritku!",
  ui_story_1017_10171401_26_dialog_content = "Ketemu! Aku kira kamu jatuh ke dalam quagmire.",
  ui_story_1017_10171401_27_dialog_content = "Grand Marshal, kami telah menemukan anggota tim Letnan Axelia satu per satu.",
  ui_story_1017_10171401_28_dialog_content = "Bagus. Periksa apakah ada yang terluka dan waspadai serangan lain dari komando pusat.",
  ui_story_1017_10171401_29_dialog_content = "Ada prajurit lain di sekitar sini, Soroz?",
  ui_story_1017_10171401_30_dialog_content = "Mencari...",
  ui_story_1017_10171401_31_dialog_content = "...",
  ui_story_1017_10171401_32_dialog_content = "Mengapa kamu hanya menghalangi dan tidak membunuh Eclipsites yang kamu temui, Axelia?",
  ui_story_1017_10171401_33_dialog_content = "\"Axelia harus mengalahkan Marsekal Agung Reinhardt dengan segala cara.\"",
  ui_story_1017_10171401_34_dialog_content = "Apakah itu yang Ulysses katakan padamu?",
  ui_story_1017_10171401_35_dialog_content = "\"Axelia harus mengalahkan Marsekal Agung Reinhardt dengan segala cara.\"",
  ui_story_1017_10171401_36_dialog_content = "Kamu sudah mencapai tujuan itu. Kamu mengalahkan dia dalam latihan gabungan.",
  ui_story_1017_10171401_37_dialog_content = "...",
  ui_story_1017_10171401_38_dialog_content = "Dia tampaknya tidak benar-benar rusak, tapi masih sedikit linglung.",
  ui_story_1017_10171401_39_dialog_content = "Apa yang Reinhardt katakan padamu sebelum dia menyerah, Axelia?",
  ui_story_1017_10171401_40_dialog_content = "Marsekal Agung Reinhardt menginginkan \"Axelia untuk hidup sebagai seorang manusia.\"",
  ui_story_1017_10171401_41_dialog_content = "Oh, wow...",
  ui_story_1017_10171401_42_dialog_content = "Bahkan ketika dia akan pergi ke penjara, dia tidak lupa meninggalkan saran yang luar biasa. Ada yang lain?",
  ui_story_1017_10171401_43_dialog_content = "Axelia harus menyelesaikan dua tujuan.",
  ui_story_1017_10171401_44_dialog_content = "\"Axelia harus mengalahkan Marsekal Agung Reinhardt dengan segala cara.\"",
  ui_story_1017_10171401_45_dialog_content = "\"Axelia harus hidup sebagai seorang manusia.\"",
  ui_story_1017_10171401_46_dialog_content = "...",
  ui_story_1017_10171401_47_dialog_content = "Kamu telah menyelesaikan misi pertamamu, Axelia. Tujuan kedua kini menjadi misi satu-satunya untukmu.",
  ui_story_1017_10171401_48_dialog_content = "Tujuan utama adalah \"Axelia harus hidup sebagai seorang manusia.\"",
  ui_story_1017_10171401_49_dialog_content = "Itu benar. Kita hanya bisa hidup dengan mengalahkan Eclipsites. Kamu adalah prajurit Illumina, dan kamu memiliki hak untuk hidup.",
  ui_story_1017_10171401_50_dialog_content = "Axelia harus mengalahkan Eclipsites, Axelia ingin hidup.",
  ui_story_1017_10171401_51_dialog_content = "Axelia sedang menggerakkan tubuhnya...?",
  ui_story_1017_10171401_52_dialog_content = "Dia sudah lepas dari bahaya, setidaknya untuk saat ini. Mungkin dia memerlukan lebih banyak waktu untuk pulih sepenuhnya.",
  ui_story_1017_10171401_53_dialog_content = "Grand Marshal, tim Letnan Axelia telah terkena dampak keras dari Darkflow, dan mereka hampir tidak mampu bertahan dalam pertempuran.",
  ui_story_1017_10171401_54_dialog_content = "Kurasa benteng mereka mungkin tidak jauh dari sini...",
  ui_story_1017_10171401_55_dialog_content = "Terima kasih atas bantuanmu dan Soroz, PlayerName.",
  ui_story_1017_10171401_56_dialog_content = "Satu permintaan terakhir, bantu antarkan prajurit yang tidak bisa bertarung lagi pulang ke rumah untukku.",
  ui_story_1017_10171401_57_dialog_content = "Sekarang?",
  ui_story_1017_10171401_58_dialog_content = "Belum lagi Eclipsite yang bersembunyi di rawa-rawa bisa muncul kapan saja!",
  ui_story_1017_10171401_59_dialog_content = "Dan aku merasakan pusat komando semakin mendekat!",
  ui_story_1017_10171401_60_dialog_content = "Apa kamu tahu kenapa?",
  ui_story_1017_10171401_61_dialog_content = "Kenapa?",
  ui_story_1017_10171401_62_dialog_content = "Karena ke mana pun aku pergi, itu ikut.",
  ui_story_1017_10171401_63_dialog_content = "Hah?",
  ui_story_1017_10171401_64_dialog_content = "Kami mungkin tidak bisa menemukan skuad Axelia sebelumnya karena mereka membuat markas di sekitar sini dan mengisolasi kita dengan rawa-rawa.",
  ui_story_1017_10171401_65_dialog_content = "Mengirim Eclipsite untuk mengganggu pasukan dari segala arah hanyalah taktik penundaan, membuka jalan untuk serangan terakhir.",
  ui_story_1017_10171401_66_dialog_content = "Tak menarik perhatianku hingga sekarang... Kurasa pukulan yang kuberikan mulai terlalu berlebihan.",
  ui_story_1017_10171401_67_dialog_content = "Tapi mengapa musuh utama melakukan itu?",
  ui_story_1017_10171401_68_dialog_content = "Menarget prajuritku, lalu menarget diriku, sepanjang waktu bersembunyi di balik rawa. Dia pasti sangat membenci Illumina.",
  ui_story_1017_10171401_69_dialog_content = "Kamu tahu siapa dalang di balik ini?",
  ui_story_1017_10171401_70_dialog_content = "Tentu saja. Kalahkan inti dari rawa itu dan dia tidak akan punya tempat untuk bersembunyi.",
  ui_story_1017_10171401_71_dialog_content = "Di depan, 500 meter, gugusan Darkflow besar sedang mendekati posisi Anda dengan cepat.",
  ui_story_1017_10171401_72_dialog_content = "Wrath, Soroz terdeteksi—",
  ui_story_1017_10171401_73_dialog_content = "Perhatikan di bawah kaki kalian!",
  ui_story_1017_10171401_74_dialog_content = "Leo! Apa yang kamu lakukan di sini?",
  ui_story_1017_10171401_75_dialog_content = "Eclipsite itu muncul di mana-mana tetapi terus bergerak ke satu arah.",
  ui_story_1017_10171401_76_dialog_content = "Jadi, apakah kamu di sini untuk saling menyalahkan?",
  ui_story_1017_10171401_77_dialog_content = "Tidak, orang-orang di Twilight akan membela setiap orang yang berjuang bersama mereka.",
  ui_story_1017_10171401_78_dialog_content = "Kamu telah memeriksa para prajurit dan itu membuatmu pemimpin yang dapat dipercaya.",
  ui_story_1017_10171401_79_dialog_content = "Pertempuran ini telah berlangsung terlalu lama. Mari kita selesaikan.",
  ui_story_1017_10171401_80_dialog_content = "Tak usah bilang dua kali. Tapi jangan lupa pertandingan kita setelah semua ini selesai.",
  ui_story_1017_10171401_81_dialog_content = "Tentu saja.",
  ui_story_1017_10171401_82_dialog_content = "(Aku masih bisa pergi dan sepenuhnya sadar...)",
  ui_story_1017_10171401_83_dialog_content = "(Semoga ini terakhir kalinya aku harus memberikan perintah untuk menyerang.)",
  ui_story_1017_10171401_84_dialog_content = "100 meter, PlayerName.",
  ui_story_1017_10171401_85_dialog_content = "Musuh diperkirakan akan memasuki jangkauan deteksi Anda dalam 5 detik.",
  ui_story_1017_10171401_86_dialog_content = "Aku bahkan tidak bisa melihatnya dari jarak dekat ini. Harus beralih menggunakan kemampuan psikis...",
  ui_story_1017_10171401_87_dialog_content = "Rooarrrrr—",
  ui_story_1017_10171401_88_dialog_content = "Apa-apaan ini...",
  ui_story_1017_10171401_89_dialog_content = "Wrath, itu punya mulut berdarah!",
  ui_story_1017_10171401_90_dialog_content = "Besar sekali, bisa menelan kita utuh...",
  ui_story_1017_10171401_91_dialog_content = "Lindungi kami, Engine VII!",
  ui_story_1017_10171401_92_dialog_content = "Hembusan angin! Apakah itu diciptakan oleh penyerang...",
  ui_story_1017_10171401_93_dialog_content = "L-Lihat! Ada sesuatu yang muncul dari rawa...",
  ui_story_1017_10171401_94_dialog_content = "Groooarrrrr!",
  ui_story_1017_10171401_95_dialog_content = "Hati-hati, Darkflow kali ini lebih keras daripada serangan sebelumnya!",
  ui_story_1017_10171401_96_dialog_content = "Marsekal Agung! Apa yang harus kita—",
  ui_story_1017_10171401_97_dialog_content = "Prajurit di depan telah ditarik ke dalam rawa oleh musuh!",
  ui_story_1017_10171401_98_dialog_content = "...",
  ui_story_1017_10171401_99_dialog_content = "(Tidak, aku masih bisa melakukan ini...)",
  ui_story_1017_10171401_100_dialog_content = "Wrath, rawa semakin meluas! Keluar sekarang!",
  ui_story_1017_10171401_101_dialog_content = "Perhatian, Legiun Penjaga—",
  ui_story_1017_10171401_102_dialog_content = "...",
  ui_story_1017_10171401_103_dialog_content = "(Bahkan memberikan perintah pun menjadi beban...)",
  ui_story_1017_10171401_104_dialog_content = "Semua orang lain... keluar dari kubangan...",
  ui_story_1017_10171401_105_dialog_content = "Pastikan kamu tetap jauh dariku...",
  ui_story_1017_10171401_106_dialog_content = "Prajurit-prajuritku, ikuti aku ke rawa dan tutupi mundurnya tentara Illumina!",
  ui_story_1017_10171401_107_dialog_content = "Tetap semangat, Grand Marshal Wrath!",
  ui_story_1017_10171401_108_dialog_content = "Aku bilang, menjauhlah dariku!",
  ui_story_1017_10171401_109_dialog_content = "...",
  ui_story_1017_10171401_110_dialog_content = "Tapi kamu jangan terus memaksakan diri, Wrath!",
  ui_story_1017_10171401_111_dialog_content = "Ksatria... Lindungi prajuritku... Aku memohon padamu...",
  ui_story_1017_10171401_112_dialog_content = "Entah itu Eclipsite atau apapun, aku tidak akan menyerah...",
  ui_story_1017_10171401_113_dialog_content = "Oh, begitu…",
  ui_story_1017_10171401_114_dialog_content = "Naik kuda, PlayerName!",
  ui_story_1017_10171401_115_dialog_content = "(Jika Wrath terjebak dalam lumpur lagi...)",
  ui_story_1017_10171401_116_dialog_content = "Wrath, jangan lupa kamu belum menyelesaikan pertarungan antara kamu dan Reinhardt!",
  ui_story_1017_10171401_117_dialog_content = "!!!",
  ui_story_1017_10171401_118_dialog_content = "(Fokus... Konsentrasi...)",
  ui_story_1017_10171401_119_dialog_content = "(Ini...)",
  ui_story_1017_10171401_120_dialog_content = "(Pertempuranku, pertempuran Grand Marshal Wrath...)",
  ui_story_1017_10171402_1_dialog_content = "<color=#e8d9bb>Di kota Twilight, tanah telah berubah menjadi lumpur yang berantakan...</color>",
  ui_story_1017_10171402_2_dialog_content = "Kapten! Garis pertahanan kita telah jatuh, dan rawa telah membanjiri Twilight, membuat warga panik!",
  ui_story_1017_10171402_3_dialog_content = "Bahkan Grand Marshal Illumina pun tertelan oleh lumpur...",
  ui_story_1017_10171402_4_dialog_content = "Bawa para penghuni ke rumah sakit. Kami akan terus mencari.",
  ui_story_1017_10171402_X1_dialog_content = "Cepat! Lari! Lumpur banjir masuk ke kota!",
  ui_story_1017_10171402_X2_dialog_content = "Apa yang terjadi?! Anakku... Di mana anakku?",
  ui_story_1017_10171402_X3_dialog_content = "Joselyne masih berada di medan perang...",
  ui_story_1017_10171402_X4_dialog_content = "Garis pertahanan kita telah jatuh, dan rawa telah membanjiri Twilight, membuat penduduk panik!",
  ui_story_1017_10171402_X5_dialog_content = "Kapten belum kembali ke Twilight... Pergi dan beri tahu mereka sekarang!",
  ui_story_1017_10171402_5_dialog_content = "Marsekal Agung—",
  ui_story_1017_10171402_6_dialog_content = "Wrath! Wra...",
  ui_story_1017_10171402_7_dialog_content = "Masih bertahan, PlayerName?",
  ui_story_1017_10171402_8_dialog_content = "Aku baik-baik saja, hanya terlalu lelah untuk menggunakan kemampuan psikisku.",
  ui_story_1017_10171402_9_dialog_content = "Kami juga mencari di mana-mana di lingkungan sekitar...",
  ui_story_1017_10171402_10_dialog_content = "Aku sama sekali tidak bisa merasakan lokasinya sebelum Eclipsite itu jatuh.",
  ui_story_1017_10171402_11_dialog_content = "Terakhir kali Soroz melihatnya, dia berada di samping mulut makhluk itu, tertutup lumpur.",
  ui_story_1017_10171402_12_dialog_content = "Ini semua salahku. Aku tidak berada dekat dengannya seperti yang seharusnya...",
  ui_story_1017_10171402_13_dialog_content = "Aku harus melihat dia menyerang musuh dengan mata yang sayu dan jelas terkuras...",
  ui_story_1017_10171402_14_dialog_content = "Namun, dia tetap memilih untuk menarik Eclipsite menjauh...",
  ui_story_1017_10171402_15_dialog_content = "Bukan salahmu. Kita harus bekerja sama dan itulah bagaimana kita mengalahkan mereka.",
  ui_story_1017_10171402_16_dialog_content = "Tapi untuk melindungi kami, Marshal Wrath sebenarnya memerintahkan Engine VII untuk menghentikan kami membantu...",
  ui_story_1017_10171402_17_dialog_content = "Keputusan yang sangat berbahaya... Dia dan para prajuritnya mempertaruhkan segalanya.",
  ui_story_1017_10171402_18_dialog_content = "...",
  ui_story_1017_10171402_19_dialog_content = "Axelia selamat, tetapi tidak dapat menemukan Grand Marshal Wrath.",
  ui_story_1017_10171402_20_dialog_content = "Aku senang melihat kamu berhasil, Axelia.",
  ui_story_1017_10171402_21_dialog_content = "Grand Marshal Wrath adalah seorang prajurit Illumina, dan \"Prajurit Illumina memiliki hak untuk hidup.\"",
  ui_story_1017_10171402_22_dialog_content = "...",
  ui_story_1017_10171402_23_dialog_content = "Ayo percepat dan lakukan putaran lain di luar perimeter.",
  ui_story_1017_10171402_24_dialog_content = "Jika lawan baru kita menyerang sekarang, akan lebih sulit untuk menemukannya!",
  ui_story_1017_10171402_25_dialog_content = "Tentu!",
  ui_story_1017_10171402_26_dialog_content = "PlayerName, tidak ada jejak Wrath yang terlihat di dalam batas-batas Twilight.",
  ui_story_1017_10171402_27_dialog_content = "Berdasarkan durasi pencarian dan estimasi kami, tingkat kematian Wrath: 99%.",
  ui_story_1017_10171402_28_dialog_content = "Tak mungkin...",
  ui_story_1017_10171402_29_dialog_content = "Tidak mungkin!",
  ui_story_1017_10171402_30_dialog_content = "<size=50>Wrath!!!</size>",
  ui_story_1017_10171501_1_dialog_content = "(Apakah ini Twilight setelah gelap?)",
  ui_story_1017_10171501_2_dialog_content = "(Aku sendirian...)",
  ui_story_1017_10171501_3_dialog_content = "(Hmm, terpisah lagi. Reinhardt masih sangat pandai bertarung...)",
  ui_story_1017_10171501_4_dialog_content = "(Aku merasa... lemah... sulit untuk bergerak...)",
  ui_story_1017_10171501_5_dialog_content = "(Undercity... begitu menakutkan heningnya...)",
  ui_story_1017_10171501_6_dialog_content = "(Sialan, benda di punggungku ini...)",
  ui_story_1017_10171501_7_dialog_content = "(Setelah kalah dari Reinhardt, mereka memasang pengikat di dalam tubuhku...)",
  ui_story_1017_10171501_8_dialog_content = "(Apakah ini harga terakhir yang harus saya bayar karena kalah dalam pertandingan?)",
  ui_story_1017_10171501_9_dialog_content = "(Pertempuran ini jelas belum berakhir...)",
  ui_story_1017_10171501_10_dialog_content = "(Itu tidak bisa menyakiti saya!)",
  ui_story_1017_10171501_11_dialog_content = "(Tak bisa menyakitiku!)",
  ui_story_1017_10171501_12_dialog_content = "(Aku mengusulkan pertandingan ulang...)",
  ui_story_1017_10171501_13_dialog_content = "(Kerumunan ini meneriakkan namaku secara serentak...)",
  ui_story_1017_10171501_14_dialog_content = "(Berikan tombak petirku... seragamku... kembali padaku...)",
  ui_story_1017_10171501_15_dialog_content = "(Aku ingin menjadi Grand Marshal untuk Illumina...)",
  ui_story_1017_10171501_16_dialog_content = "(Tidak ada seorang pun... yang bisa menghentikanku...)",
  ui_story_1017_10171501_17_dialog_content = "Beberapa hari yang lalu, pada pertemuan rahasia para petinggi Illumina...",
  ui_story_1017_10171501_18_dialog_content = "Dia di sini, Komandan.",
  ui_story_1017_10171501_19_dialog_content = "Duduklah.",
  ui_story_1017_10171501_20_dialog_content = "Apa pun itu, berikan saja padaku dengan jelas agar aku bisa kembali ke tugasanku.",
  ui_story_1017_10171501_21_dialog_content = "Duduk.",
  ui_story_1017_10171501_22_dialog_content = "...",
  ui_story_1017_10171501_23_dialog_content = "Bagaimana perasaanmu jika kamu diminta untuk menjadi Grand Marshal di Illumina?",
  ui_story_1017_10171501_24_dialog_content = "Aku? Tapi mengapa?",
  ui_story_1017_10171501_25_dialog_content = "Karena kamu ingin melakukannya, dan karena Federasi memiliki kebutuhan tersebut.",
  ui_story_1017_10171501_26_dialog_content = "Aku tidak mengerti. Apa yang salah dari Reinhardt?",
  ui_story_1017_10171501_27_dialog_content = "Bukankah itu sudah dijelaskan saat persidangan? Kamu ada di sana.",
  ui_story_1017_10171501_28_dialog_content = "Tapi itu bukan yang sebenarnya, jadi sebenarnya apa yang kamu lakukan?",
  ui_story_1017_10171501_29_dialog_content = "Apa yang kamu lihat tidak selalu nyata. Belajarlah untuk lebih pragmatis.",
  ui_story_1017_10171501_30_dialog_content = "Tentukan apakah kamu ingin menjadi Grand Marshal atau biarkan orang lain.",
  ui_story_1017_10171501_31_dialog_content = "Apakah mereka bertiga tahu?",
  ui_story_1017_10171501_32_dialog_content = "Tergantung pada kamu. Semoga kamu akan memikirkannya dengan serius.",
  ui_story_1017_10171501_33_dialog_content = "...",
  ui_story_1017_10171501_34_dialog_content = "Tidak ada yang ingin kamu tambahkan, Ulysses?",
  ui_story_1017_10171501_35_dialog_content = "Kamu fantastis dalam segala aspek kecuali fisik.",
  ui_story_1017_10171501_36_dialog_content = "Ketika kamu menjadi Grand Marshal, aku akan menghilangkan kekurangan itu untukmu.",
  ui_story_1017_10171501_37_dialog_content = "...",
  ui_story_1017_10171501_38_dialog_content = "Apa yang Anda rencanakan?",
  ui_story_1017_10171501_39_dialog_content = "Jangan khawatir, ini hanya eksperimen kecil yang sama yang Reinhardt jalani.",
  ui_story_1017_10171501_40_dialog_content = "Peningkatan fisik untuk menjadi prajurit terhebat di Illumina.",
  ui_story_1017_10171501_41_dialog_content = "Reinhardt memiliki modifikasi bio?",
  ui_story_1017_10171501_42_dialog_content = "Kaget?",
  ui_story_1017_10171501_43_dialog_content = "(Reinhardt?!)",
  ui_story_1017_10171501_44_dialog_content = "(Kuat! Tak terkalahkan! Puncak yang tak tertandingi?!)",
  ui_story_1017_10171501_45_dialog_content = "(Ini semua palsu!)",
  ui_story_1017_10171501_46_dialog_content = "Dia masih muda ketika bergabung dengan Proyek Matahari Buatan.",
  ui_story_1017_10171501_47_dialog_content = "Tapi wajar saja jika dia tidak mengungkapkan hal itu meskipun dia tahu kebenarannya, karena semua orang ingin menjadi hebat secara alami.",
  ui_story_1017_10171501_48_dialog_content = "...",
  ui_story_1017_10171501_49_dialog_content = "Anda memerlukan kesempatan untuk membuktikan apakah Anda dilahirkan untuk menjadi Grand Marshal.",
  ui_story_1017_10171501_50_dialog_content = "Dan sekarang adalah kesempatan itu.",
  ui_story_1017_10171501_51_dialog_content = "Kesempatan apa?",
  ui_story_1017_10171501_52_dialog_content = "Pertempuran besar pasti akan terjadi di sekitar Twilight cepat atau lambat. Saya yakin kita bisa menang dengan kamu yang memimpin.",
  ui_story_1017_10171501_53_dialog_content = "Aku akan menang, tapi aku melakukannya dengan caraku sendiri.",
  ui_story_1017_10171501_54_dialog_content = "Anda tidak harus menjawab itu sekarang.",
  ui_story_1017_10171501_55_dialog_content = "Satu lagi... Apakah kamu ingat sesuatu yang pernah kamu katakan dulu?",
  ui_story_1017_10171501_56_dialog_content = "Kamu berdiri di pinggir lapangan setelah kalah dalam pertandingan.",
  ui_story_1017_10171501_57_dialog_content = "Aku bilang kamu seharusnya tidak kalah darinya, tapi kamu menjawab—",
  ui_story_1017_10171501_58_dialog_content = "Aku akan membayar berapapun untuk menembus batas fisikku!",
  ui_story_1017_10171501_59_dialog_content = "Ini jawaban saya untuk kamu.",
  ui_story_1017_10171501_60_dialog_content = "...",
  ui_story_1017_10171501_61_dialog_content = "<color=#e8d9bb>Wrath menceritakan detail pertemuan rahasia kepada Barton, Hiiro, dan Sharona.</color>",
  ui_story_1017_10171501_62_dialog_content = "...",
  ui_story_1017_10171501_63_dialog_content = "Penjahat di Komite itu akan merendahkan diri ke tingkat apa pun!",
  ui_story_1017_10171501_64_dialog_content = "Saya percaya masih ada kesempatan selama itu bukan salah satu dari Ulysses' anak buah.",
  ui_story_1017_10171501_65_dialog_content = "Apa pendapatmu, Barton?",
  ui_story_1017_10171501_66_dialog_content = "Saya tidak punya tambahan, kecuali saya tidak akan membiarkan masalah ini mati.",
  ui_story_1017_10171501_67_dialog_content = "Mengenai siapa yang akan menggantikannya di masa depan, aku tidak peduli satu pun.",
  ui_story_1017_10171501_68_dialog_content = "Bukan berarti saya akan mendengarkan atau mengikuti siapa pun selain Reinhardt, anyway.",
  ui_story_1017_10171501_69_dialog_content = "Tapi bagaimana jika mereka memanggil kamu bukan aku?",
  ui_story_1017_10171501_70_dialog_content = "Aku takkan membiarkan Ulysses mengusik tubuh ini. Aku akan membunuhnya.",
  ui_story_1017_10171501_71_dialog_content = "Jika itu memang kebenaran tentang Grand Marshal, itu bukan urusanmu.",
  ui_story_1017_10171501_72_dialog_content = "Dark Zone semakin tidak tenang. Saya rasa orang-orang penting akan bereaksi segera.",
  ui_story_1017_10171501_73_dialog_content = "Tanpa Grand Marshal untuk memimpin, mengusir serangan Eclipsite akan menjadi tantangan.",
  ui_story_1017_10171501_74_dialog_content = "Apakah kamu siap untuk itu, Wrath?",
  ui_story_1017_10171501_75_dialog_content = "Reinhardt tidak takut saat menjadi grand marshal, jadi saya tidak perlu takut.",
  ui_story_1017_10171501_76_dialog_content = "Apa yang terjadi jika kamu berubah menjadi monster?",
  ui_story_1017_10171501_77_dialog_content = "Maka aku hanya punya satu permintaan, yaitu bawa Reinhardt untuk membunuhku secara pribadi.",
  ui_story_1017_10171501_78_dialog_content = "Itu benar-benar... absurd.",
  ui_story_1017_10171501_79_dialog_content = "Jangan bilang begitu. Kamu akan bertemu Grand Marshal selama kamu kembali dengan selamat.",
  ui_story_1017_10171501_80_dialog_content = "Kamu bisa mencari dia sendiri.",
  ui_story_1017_10171501_81_dialog_content = "Tunggu, saya tidak bercanda tentang Reinhardt.",
  ui_story_1017_10171501_82_dialog_content = "Dari kita semua di sini, hanya kamu yang bisa mewujudkannya.",
  ui_story_1017_10171501_83_dialog_content = "Maksudmu…",
  ui_story_1017_10171501_84_dialog_content = "Benar, begitu Eclipse mulai bergerak, Sharona dan Barton akan kembali ke zona perang dan siap sedia.",
  ui_story_1017_10171501_85_dialog_content = "Sampai garisnya dalam masalah, aku akan menyelamatkan bala bantuanmu hingga saat terakhir.",
  ui_story_1017_10171501_86_dialog_content = "Dengan kata lain, semakin sengit pertempurannya, semakin besar peluang kita.",
  ui_story_1017_10171501_87_dialog_content = "Konsekuensi dari hal itu adalah penjara atau kematian. Apakah kamu yakin, Wrath?",
  ui_story_1017_10171501_88_dialog_content = "Saya yakin. Saya tidak pikir ada kemungkinan lain.",
  ui_story_1017_10171501_89_dialog_content = "Bagaimana jika bergabung dengan Program Phospherus?",
  ui_story_1017_10171501_90_dialog_content = "Sejujurnya, belum.",
  ui_story_1017_10171501_91_dialog_content = "Tapi percayalah padaku, aku membuat keputusan yang lebih baik untuk situasi mendesak.",
  ui_story_1017_10171501_92_dialog_content = "Sungguh?",
  ui_story_1017_10171501_93_dialog_content = "Pokoknya, tenang saja bahwa kamu tidak akan mencemarkan nama Illumina dalam pertempuran ini di bawah komandoku.",
  ui_story_1017_10171501_94_dialog_content = "<color=#e8d9bb>Keesokan harinya...</color>",
  ui_story_1017_10171501_95_dialog_content = "Bagaimana perasaanmu?",
  ui_story_1017_10171501_96_dialog_content = "Sama sekali tidak ada.",
  ui_story_1017_10171501_97_dialog_content = "Tak lama lagi, pikiranmu akan menjadi buram.",
  ui_story_1017_10171501_98_dialog_content = "Ketika kamu bangun lagi, kamu akan menemukan dunia menjadi jauh lebih adil untukmu.",
  ui_story_1017_10171501_99_dialog_content = "Adil...",
  ui_story_1017_10171501_100_dialog_content = "Ketika yang kuat menguasai yang lemah, yang lemah hanya akan mengeluh tentang ketidakadilan dunia.",
  ui_story_1017_10171501_101_dialog_content = "Mereka menganggap Eclipsites itu sebagai perundung, padahal sebenarnya mereka sendiri yang belum cukup kuat.",
  ui_story_1017_10171501_102_dialog_content = "Sama saja dengan kamu yang mencoba mengalahkan Reinhardt.",
  ui_story_1017_10171501_103_dialog_content = "Setelah prosedur, lapangan akan menjadi lebih seimbang antara kalian.",
  ui_story_1017_10171501_104_dialog_content = "(Lapangan... Bahkan...)",
  ui_story_1017_10171501_105_dialog_content = "(Dulu, aku berpikir bahwa aku tak akan berhenti untuk mencapai tujuanku.)",
  ui_story_1017_10171501_106_dialog_content = "(Tapi saat ujung tajam menusuk tubuhku, rasanya seperti aku menyaksikan diriku sendiri membongkar kapal ini...)",
  ui_story_1017_10171501_107_dialog_content = "(Menghancurkan ambisi dan kesombongan ku, menjadi debu.)",
  ui_story_1017_10171501_108_dialog_content = "(Setiap langkah yang kuambil, setiap pilihan yang kubuat rasanya seperti berjuang untuk mendapatkan udara di bawah air...)",
  ui_story_1017_10171501_109_dialog_content = "(Tapi di tengah arus bawah yang meningkat, aku merasa tenggelam semakin dalam...)",
  ui_story_1017_10171501_110_dialog_content = "(Apakah aku harus terus berjuang? Apakah ini benar-benar hasil yang kudambakan?)",
  ui_story_1017_10171501_111_dialog_content = "(Lapangan ini memang rata, memang.)",
  ui_story_1017_10171501_112_dialog_content = "(Tapi keadilan seperti itu...)",
  ui_story_1017_10171501_113_dialog_content = "(Datang terlambat.)",
  ui_story_1018_10180101_1_dialog_content = "<color=#e8d9bb>Di bayangan tersembunyi Zona Gelap...</color>",
  ui_story_1018_10180101_2_dialog_content = "Kapten... Aku beruntung karena tidak tersambar oleh <color=#FFB400>Eclipsite bercahaya hijau</color> yang aneh itu tadi!",
  ui_story_1018_10180101_3_dialog_content = "Pilar es raksasa dan puncak es aneh yang kita temui—jauh melampaui apa yang aku bayangkan untuk wilayah Malam Abadi...",
  ui_story_1018_10180101_4_dialog_content = "Tapi karena misi kita adalah melacak inti dari Guardian One, mengapa kita bersembunyi di sini, mengawasi para Eclipsite ini?",
  ui_story_1018_10180101_5_dialog_content = "Ssst, jangan terlalu keras!",
  ui_story_1018_10180101_6_dialog_content = "Oh... Melihat semangatmu barusan, aku kira kita sudah menemukan <color=#FFB400>sarang Eclipsite</color>...",
  ui_story_1018_10180101_7_dialog_content = "Tapi ini <color=#FFB400>semua dataran datar</color>, dengan Eclipsites berkumpul dalam kelompok pada interval...",
  ui_story_1018_10180101_8_dialog_content = "Aku hanya tidak mengerti apa yang layak untuk dilihat dari mereka.",
  ui_story_1018_10180101_9_dialog_content = "Nah, itu membuktikan bahwa pikiranmu satu arah seperti para Eclipsite.",
  ui_story_1018_10180101_10_dialog_content = "Tapi jangan bilang siapa-siapa kamu masuk reguku saat kita kembali nanti!",
  ui_story_1018_10180101_11_dialog_content = "Hah? Kenapa? Apa yang salah dengan yang aku katakan kali ini...",
  ui_story_1018_10180101_12_dialog_content = "Rahasia dalam melacak adalah beralih dari reaktif menjadi proaktif dan berpikir seperti musuh.",
  ui_story_1018_10180101_13_dialog_content = "Eclipsite yang mengambil inti itu menggunakan segala cara untuk menjaga kita tetap di tempat aneh itu, karena ia tidak ingin kita datang ke sini.",
  ui_story_1018_10180101_14_dialog_content = "Setelah semua, pencuri tidak pernah ingin siapa pun mengetahui di mana mereka bersembunyi.",
  ui_story_1018_10180101_15_dialog_content = "Tempat ini tampaknya biasa saja, namun dijaga oleh banyak Eclipsite, jadi pasti sangat penting bagi Eclipse.",
  ui_story_1018_10180101_16_dialog_content = "Jadi... apa sebenarnya yang dijaga oleh para Eclipsite?",
  ui_story_1018_10180101_17_dialog_content = "Jika saya benar, apapun itu, itu sama pentingnya dengan inti Guardian One.",
  ui_story_1018_10180101_18_dialog_content = "Lihat ini...",
  ui_story_1018_10180101_19_dialog_content = "Kapten! Eclipsite baru saja mulai bersemangat!",
  ui_story_1018_10180101_20_dialog_content = "Lihat, benda itu bereaksi seperti inti Guardian One.",
  ui_story_1018_10180101_21_dialog_content = "Ini adalah proyek besar, saya mengerti.",
  ui_story_1018_10180101_22_dialog_content = "Apakah Anda mengatakan bahwa selain inti dari Guardian One, kita mungkin menemukan kejutan bonus?",
  ui_story_1018_10180101_23_dialog_content = "Nah, apa kamu tidak setuju kita harus memberikan satu atau dua kejutan untuk Belisaria?",
  ui_story_1018_10180101_24_dialog_content = "Kapten, Anda benar-benar ahli pengintaian!",
  ui_story_1018_10180101_25_dialog_content = "Tapi masalahnya... Aku khawatir Eclipsites bisa menghabisi kita sebelum kita bahkan sampai di sana.",
  ui_story_1018_10180101_26_dialog_content = "Berfikir positif! Kendaraan kita hampir menyatu dengan Dark Zone.",
  ui_story_1018_10180101_27_dialog_content = "Eksterior diberi perlakuan khusus agar dapat menyatu dengan sempurna dengan lingkungan sekitarnya.",
  ui_story_1018_10180101_28_dialog_content = "Semua dari kalian juga terpilih karena Lumina kalian lemah sehingga lebih sulit bagi Eclipsite untuk merasakan keberadaan kalian.",
  ui_story_1018_10180101_29_dialog_content = "Hmm, apakah itu alasan mengapa kamu tidak bisa meningkatkan Luminatics-mu?",
  ui_story_1018_10180101_30_dialog_content = "Huh... Komandan sebelumnya pernah bilang padaku—aku ditakdirkan hanya menjadi pengemudi seumur hidupku.",
  ui_story_1018_10180101_31_dialog_content = "Cuma bercanda denganmu! Saat kembali nanti, jangan lupa bilang padanya bahwa kau sekarang adalah pesuruh yang mengikutiku ke Zona Gelap!",
  ui_story_1018_10180101_32_dialog_content = "Pokoknya, percayalah pada pengalaman orang tua, sebenarnya lebih aman jika Anda berada lebih dalam di Zona Gelap.",
  ui_story_1018_10180101_33_dialog_content = "Kapten... Apakah benar Anda bukan mantan anggota Eclipse yang membelot dan bergabung dengan Illumina?",
  ui_story_1018_10180101_34_dialog_content = "Pertanyaan yang seharusnya kamu tanyakan adalah apakah dulu aku bergabung dengan Illumina tetapi sekarang beralih ke pihak Eclipse.",
  ui_story_1018_10180101_35_dialog_content = "...",
  ui_story_1018_10180101_36_dialog_content = "Kalian mendekat dan lindungi aku. Lakukan dengan diam-diam.",
  ui_story_1018_10180101_37_dialog_content = "Saya akan melihat bagaimana persisnya benda ini mirip dengan inti Guardian One.",
  ui_story_1018_10180101_38_dialog_content = "Mengerti, Kapten. Apakah kita harus berbagi koordinat saat ini dengan tim pelacak di belakang kita?",
  ui_story_1018_10180101_39_dialog_content = "Baru saja mereka keluar dari masalah... Sepertinya segalanya tidak berjalan lancar untuk mereka.",
  ui_story_1018_10180101_40_dialog_content = "<color=#e8d9bb>Lumopolis, Pengadilan Kerajaan</color>",
  ui_story_1018_10180101_41_dialog_content = "Penguasa Kota, jika niat bala bantuan hanya untuk melindungi Benteng Lumo, mengapa mereka pergi ke Twilight?",
  ui_story_1018_10180101_42_dialog_content = "Tahu kah kamu apa yang membentuk tentara Illumina baru ini?",
  ui_story_1018_10180101_43_dialog_content = "Kenapa tanya begitu?",
  ui_story_1018_10180101_44_dialog_content = "Lihatlah.",
  ui_story_1018_10180101_45_dialog_content = "Ini... adalah surat mendesak dari Gereja White Night di Twilight dan bahkan belum ditandatangani.",
  ui_story_1018_10180101_46_dialog_content = "\"Quagmire menghancurkan basis Twilight. Eclipsites berkeliaran tak terkendali. Upaya perlawanan bersama Illumina dan Lumo Knights hampir sia-sia...\"",
  ui_story_1018_10180101_47_dialog_content = "\"Prajurit Illumina mengalami korban yang serius. Grand Marshal masih belum ditemukan. Hanya para Ksatria yang bertahan di posisi mereka.\"",
  ui_story_1018_10180101_48_dialog_content = "\"Rumah sakit penuh. Persediaan mulai habis. Semua orang dalam keadaan kritis...\"",
  ui_story_1018_10180101_49_dialog_content = "Grand Marshal hilang? Bagaimana bisa begitu?",
  ui_story_1018_10180101_50_dialog_content = "Federasi Illumina memang tidak tak terkalahkan, meskipun saya belum pernah melihat hasil seperti pertempuran Twilight.",
  ui_story_1018_10180101_51_dialog_content = "Meskipun begitu, legiun-legiun Illumina lainnya tetap teguh di Gannon dan tidak pernah berani keluar.",
  ui_story_1018_10180101_52_dialog_content = "Mereka tidak memiliki niat untuk membantu Twilight, tetapi sebenarnya sedang menguji coba teknologi militer baru melalui Grand Marshal yang baru saja diangkat.",
  ui_story_1018_10180101_53_dialog_content = "Jika jalannya tetap, tentara baru ini akan menjadi korban dari tes ini.",
  ui_story_1018_10180101_54_dialog_content = "Kamu tahu ini sejak awal, Tuan Kota?",
  ui_story_1018_10180101_55_dialog_content = "Ini hanya sejarah yang terulang kembali. Motifnya sangat cocok dengan Illumina.",
  ui_story_1018_10180101_56_dialog_content = "Lalu bagaimana dengan prajurit yang masih bertempur di garis depan?",
  ui_story_1018_10180101_57_dialog_content = "Terlepas dari Illumina, saya pikir penguatan harus menjamin keselamatan masyarakat di Twilight.",
  ui_story_1018_10180101_58_dialog_content = "Aku masih merenung.",
  ui_story_1018_10180101_59_dialog_content = "Tetapi jika kamu tidak segera memutuskan, bukankah kota-kota permukaan Lumopolis dan bukan hanya Twilight yang akan terpengaruh!",
  ui_story_1018_10180101_60_dialog_content = "<size=45>Aku sedang merenung.</size>",
  ui_story_1018_10180101_61_dialog_content = "...",
  ui_story_1018_10180101_62_dialog_content = "City Lord, seorang kurir dari Shadowlord Istvan meminta audiensi.",
  ui_story_1018_10180101_63_dialog_content = "Kirim dia masuk.",
  ui_story_1018_10180101_64_dialog_content = "Saya melihat pulau terbang ini seperti biasa sepi! Salam, Tuan Kota dan Lady Carleen.",
  ui_story_1018_10180101_65_dialog_content = "Apa urusanmu, utusan dari Kota Hiruk-pikuk?",
  ui_story_1018_10180101_66_dialog_content = "Wow, aku tidak tahu kalau aku cocok menjadi utusan!",
  ui_story_1018_10180101_67_dialog_content = "Saya di sini hanya untuk menyampaikan beberapa kata dari Istvan.",
  ui_story_1018_10180101_68_dialog_content = "Saya percaya Anda juga mengawasi keributan di Twilight.",
  ui_story_1018_10180101_69_dialog_content = "Tapi meskipun kamu mengirim bala bantuan, kamu meninggalkan kota-kota terdekat untuk mengurus diri mereka sendiri. Kenapa begitu?",
  ui_story_1018_10180101_70_dialog_content = "Apakah itu kata-kata Istvan yang sebenarnya?",
  ui_story_1018_10180101_71_dialog_content = "Benar... Agak dilebih-lebihkan.",
  ui_story_1018_10180101_72_dialog_content = "Mungkin kamu tidak tahu bahwa pengunjung dari Twilight kebetulan bertemu dengan Istvan dalam perjalanan untuk menemui kamu.",
  ui_story_1018_10180101_73_dialog_content = "Dari apa yang dia katakan, situasi di Twilight telah menjadi jauh lebih buruk.",
  ui_story_1018_10180101_74_dialog_content = "Apakah pengunjung dari Twilight ini adalah Zhao?",
  ui_story_1018_10180101_75_dialog_content = "Ya, itu namanya!",
  ui_story_1018_10180101_76_dialog_content = "Tuan Kota, Zhao dari Twilight ingin audiensi.",
  ui_story_1018_10180101_77_dialog_content = "Lihat, dia sudah di sini.",
  ui_story_1018_10180101_78_dialog_content = "Tapi seluruh lalu lintas ke Lumopolis telah ditutup.",
  ui_story_1018_10180101_79_dialog_content = "Selama Istvan ingin melakukannya, tidak ada yang tidak bisa dilakukan.",
  ui_story_1018_10180101_80_dialog_content = "Orang ini Zhao telah bolak-balik antara faksi-faksi. Setelah Illumina, dia pergi ke Umbraton, lalu setelah Umbraton, dia pergi ke Lumopolis...",
  ui_story_1018_10180101_81_dialog_content = "Jika kamu mengusirnya, dia akan pergi ke Northland, Gurun Rediesel...",
  ui_story_1018_10180101_82_dialog_content = "\"Tubuh lemah, tetapi tidak pernah menyerah sebelum mendapatkan apa yang diinginkan. Itulah Zhao, orang yang ingin bertemu denganmu.\"",
  ui_story_1018_10180101_83_dialog_content = "Sekarang itu adalah kata-kata persis dari Istvan.",
  ui_story_1018_10180101_84_dialog_content = "Dia pasti cepat-cepat melempar kentang panas yang bernama Twilight. Kenapa Istvan tidak datang sendiri?",
  ui_story_1018_10180101_85_dialog_content = "Saya hanya utusan. Anda harus menanyakan hal itu kepada pengunjung, Tuan Kota.",
  ui_story_1018_10180101_86_dialog_content = "Tempat ini terlalu terang. Saatnya aku kembali ke bawah laut. Aku akan pamit, City Lord dan Lady Carleen!",
  ui_story_1018_10180101_87_dialog_content = "...",
  ui_story_1018_10180101_88_dialog_content = "Kamu tidak berniat mengundang Zhao masuk?",
  ui_story_1018_10180101_89_dialog_content = "Masalah dengan Twilight melibatkan Lumopolis dan Illumina. Tidak ada orang lain yang memiliki hak untuk bernegosiasi.",
  ui_story_1018_10180101_90_dialog_content = "Dan karena Illumina telah menunjukkan kartu mereka, terserah Lumopolis untuk membela Twilight.",
  ui_story_1018_10180101_91_dialog_content = "Kamu akan ikut denganku.",
  ui_story_1018_10180101_92_dialog_content = "Apakah Anda akan pergi ke Twilight secara pribadi?",
  ui_story_1018_10180101_93_dialog_content = "Aku bukan orang yang akan mengungkap aib Illumina. Kekejaman yang mereka lakukan terhadap Aurorian adalah urusan untuk dinilai oleh Kuil.",
  ui_story_1018_10180201_1_dialog_content = "<color=#e8d9bb>Kota Senja</color>",
  ui_story_1018_10180201_2_dialog_content = "(Kami telah mencari begitu lama...)",
  ui_story_1018_10180201_3_dialog_content = "(Di mana kamu, Wrath?)",
  ui_story_1018_10180201_4_dialog_content = "Kapten, kami berhasil membasmi Eclipsite yang merayap masuk bersama lumpur setelah kami mengalahkan musuh di pusat komando.",
  ui_story_1018_10180201_5_dialog_content = "Selama rawa masih ada, Twilight sementara ini terhindar dari bahaya.",
  ui_story_1018_10180201_6_dialog_content = "Mengingat situasi saat ini, apakah Anda akan menganggap fase pertempuran ini selesai, Kapten?",
  ui_story_1018_10180201_7_dialog_content = "Meskipun kita membuat kemajuan dalam pertempuran, masih akan ada waktu sebelum semuanya berakhir.",
  ui_story_1018_10180201_8_dialog_content = "Darkflow di Twilight sudah banyak berkurang, kan, PlayerName?",
  ui_story_1018_10180201_9_dialog_content = "Ya. Soroz tidak merasakan adanya musuh yang ditarik oleh Darkflow.",
  ui_story_1018_10180201_10_dialog_content = "Nah, lumpur yang menutupi Twilight tetap menjadi masalah.",
  ui_story_1018_10180201_11_dialog_content = "Benar. Untuk sementara ini, rumah sakit hanya bisa menstabilkan kondisi prajurit yang terkena. Belum ada obat yang ditemukan.",
  ui_story_1018_10180201_12_dialog_content = "Ini akan menjadi satu sakit kepala besar...",
  ui_story_1018_10180201_13_dialog_content = "Kapten, semua warga Twilight telah dipindahkan ke rumah sakit sementara.",
  ui_story_1018_10180201_14_dialog_content = "Mereka yang tinggal lebih dekat dengan daerah pusat telah menyumbangkan rumah mereka untuk menampung para pengungsi.",
  ui_story_1018_10180201_15_dialog_content = "Kebanyakan orang tidak menderita berkat usaha tanpa pamrih Anda.",
  ui_story_1018_10180201_16_dialog_content = "Tapi tidak mungkin bagi semua orang untuk berdesakan di Twilight. Saya akan mempertimbangkan untuk memindahkan pengungsi dari garis Illumina ke kota-kota tetangga.",
  ui_story_1018_10180201_17_dialog_content = "Kapten, pinggiran zona perang masih berantakan, dan saya khawatir bahwa pemindahan sekarang mungkin bukan langkah yang paling aman.",
  ui_story_1018_10180201_18_dialog_content = "Grand Marshal Wrath dan pasukannya yang berani, yang telah memimpin serangan, juga terjebak di dalam, dan kami tidak tahu di mana mereka berada...",
  ui_story_1018_10180201_19_dialog_content = "Mari kita lakukan persiapan terlebih dahulu, dan pikirkan setelah pertempuran mereda.",
  ui_story_1018_10180201_20_dialog_content = "Permisi, prajurit, kira-kira berapa banyak dari kalian yang hilang?",
  ui_story_1018_10180201_21_dialog_content = "Dua tim bergabung dalam serangan Grand Marshal, dengan total lebih dari seratus prajurit...",
  ui_story_1018_10180201_22_dialog_content = "Dan hampir semua dari mereka... adalah rekrutan baru.",
  ui_story_1018_10180201_23_dialog_content = "Itu hampir setengah dari Ironthorn Knights.",
  ui_story_1018_10180201_24_dialog_content = "Kapten, kami melihat beberapa prajurit di tembok barat. Namun, dengan situasi yang belum jelas, rekan-rekan kami menjaga jarak.",
  ui_story_1018_10180201_25_dialog_content = "Cek sekarang!",
  ui_story_1018_10180201_26_dialog_content = "Mereka... Ya, mereka adalah prajurit yang maju ke medan perang bersama Grand Marshal.",
  ui_story_1018_10180201_27_dialog_content = "Sekilas melihat sekeliling dan ada puluhan dari mereka...",
  ui_story_1018_10180201_28_dialog_content = "Pindahkan tentara yang tewas ke pangkalan dengan hati-hati dan waspadai musuh yang bersembunyi di lumpur.",
  ui_story_1018_10180201_29_dialog_content = "Ya!",
  ui_story_1018_10180201_30_dialog_content = "...",
  ui_story_1018_10180201_31_dialog_content = "Mereka mati begitu saja... Bahkan tidak sempat mengenal mereka...",
  ui_story_1018_10180201_32_dialog_content = "Itulah seorang prajurit untukmu, PlayerName.",
  ui_story_1018_10180201_33_dialog_content = "Bertempur dalam perang secara teratur, terkadang bahkan tidak sempat berduka untuk teman yang gugur sebelum bergegas ke pertempuran berikutnya.",
  ui_story_1018_10180201_34_dialog_content = "...",
  ui_story_1018_10180201_35_dialog_content = "Kita masih punya yang bernapas, Leo!",
  ui_story_1018_10180201_36_dialog_content = "Bagaimana situasinya?",
  ui_story_1018_10180201_37_dialog_content = "Kita seharusnya bisa menstabilkannya dengan perawatan...",
  ui_story_1018_10180201_38_dialog_content = "...",
  ui_story_1018_10180201_39_dialog_content = "Apakah dia takut, atau mencoba mengatakan sesuatu?",
  ui_story_1018_10180201_40_dialog_content = "Sepertinya dia sedang mengunyah sesuatu.",
  ui_story_1018_10180201_41_dialog_content = "*Meraung*",
  ui_story_1018_10180201_42_dialog_content = "Pedang Kilat!",
  ui_story_1018_10180201_43_dialog_content = "Dia tiba-tiba berubah menjadi Eclipsite!",
  ui_story_1018_10180201_44_dialog_content = "Ternyata ketakutan terburukku menjadi kenyataan...",
  ui_story_1018_10180201_45_dialog_content = "*Meraung*",
  ui_story_1018_10180201_46_dialog_content = "Dan di sana juga?",
  ui_story_1018_10180201_47_dialog_content = "Kapten! Prajurit-prajurit yang gugur ini... Tidak, Eclipsites sedang menyerang kita!",
  ui_story_1018_10180201_48_dialog_content = "Situasinya lebih buruk dari yang kubayangkan. Kita harus menghentikan operasi pencarian dan penyelamatan!",
  ui_story_1018_10180201_49_dialog_content = "Bersiaplah untuk bertarung!",
  ui_story_1018_10180201_50_dialog_content = "Tunggu, Leo...",
  ui_story_1018_10180202_1_dialog_content = "Apakah prajurit ini benar-benar sudah mati?",
  ui_story_1018_10180202_2_dialog_content = "...",
  ui_story_1018_10180202_3_dialog_content = "Jangan merasa kasihan pada Eclipsites.",
  ui_story_1018_10180202_4_dialog_content = "Bahkan jika mereka dulunya prajurit, mereka hanya akan menyebabkan kerugian yang lebih besar jika diizinkan untuk bertahan.",
  ui_story_1018_10180202_5_dialog_content = "Prajurit Illumina, serahkan ini pada kami. Kalian segera keluar dari Twilight secepatnya!",
  ui_story_1018_10180202_6_dialog_content = "Kapten Leo, prajurit Illumina... kita belum bisa meninggalkan Twilight.",
  ui_story_1018_10180202_7_dialog_content = "Kubilang, semua prajurit Illumina, keluar dari Twilight.",
  ui_story_1018_10180202_8_dialog_content = "...",
  ui_story_1018_10180202_9_dialog_content = "Dalam hal ini, Kapten Leo, saya harus menyampaikan suatu hal penting kepada Anda.",
  ui_story_1018_10180202_10_dialog_content = "Tolong dengarkan aku, lalu Anda bisa memutuskan apakah ingin kami pergi.",
  ui_story_1018_10180202_11_dialog_content = "Bicaralah.",
  ui_story_1018_10180202_12_dialog_content = "Sebelum datang ke Twilight, Legiun Pengawal Illumina kami terdiri dari prajurit paling terampil, itulah sebabnya kami juga dikenal sebagai Elite Reserve.",
  ui_story_1018_10180202_13_dialog_content = "Saudara-saudara yang berdiri di belakangku ini adalah anggota Elite Reserve, pengikut setia terbaik dari Grand Marshal Wrath.",
  ui_story_1018_10180202_14_dialog_content = "Kami belum pernah menghadapi pertempuran seintens ini sebelumnya, tetapi kenyataan bahwa kami masih bertahan adalah bukti kekuatan kami.",
  ui_story_1018_10180202_15_dialog_content = "Aku tahu maksudmu, tetapi para pemula yang berubah menjadi Eclipsite ini menerima pelatihan khusus dari Illumina.",
  ui_story_1018_10180202_16_dialog_content = "Setelah datang ke Twilight, mereka, termasuk Marsekal Besar Anda, tercemar oleh rawa-rawa.",
  ui_story_1018_10180202_17_dialog_content = "Itulah kenyataannya... namun, saya janji, sebelum terjun ke pertempuran, tidak ada satupun dari kami yang bisa menduga hal seperti ini akan terjadi.",
  ui_story_1018_10180202_18_dialog_content = "Dengan banyaknya korban luka berat kawan-kawan kami dan tidak tahu keberadaan Grand Marshal, kami semua merasa sangat hancur.",
  ui_story_1018_10180202_19_dialog_content = "Oleh karena itu, mewakili prajurit Elite Reserve, saya di sini untuk menyuarakan permohonan kami: marilah kita tetap di sini dan membela Twilight.",
  ui_story_1018_10180202_20_dialog_content = "Sampai kita menemukan Grand Marshal, inilah perintah yang harus diikuti oleh semua prajurit Illumina kita.",
  ui_story_1018_10180202_21_dialog_content = "Kami secara sukarela bergabung dengan pasukan yang melindungi Twilight, dan jika Grand Marshal tidak ada, saya akan mengambil alih komando untuk sementara.",
  ui_story_1018_10180202_22_dialog_content = "Seperti pemimpin, seperti prajurit, begitu yang kulihat.",
  ui_story_1018_10180202_23_dialog_content = "Bahkan jika musuh-musuh itu dulunya adalah kawan seperjuanganmu?",
  ui_story_1018_10180202_24_dialog_content = "Jika mereka berubah menjadi Eclipsite yang menimbulkan kekacauan di Twilight... Aku tidak akan menunjukkan belas kasihan...",
  ui_story_1018_10180202_25_dialog_content = "*Meraung*",
  ui_story_1018_10180202_26_dialog_content = "Ada lebih banyak di sini, Kapten!",
  ui_story_1018_10180202_27_dialog_content = "Aku…",
  ui_story_1018_10180202_28_dialog_content = "Pedang Kilat!",
  ui_story_1018_10180202_29_dialog_content = "Tindakanmu tidak mendukung sumpahmu, prajurit. Minggir. Mereka sudah tak bisa diselamatkan.",
  ui_story_1018_10180202_30_dialog_content = "Jangan langsung menyimpulkan, Leo. Orang-orang yang tidak menyerang bukan berarti tidak ada harapan.",
  ui_story_1018_10180202_31_dialog_content = "Ya, mereka ragu-ragu...",
  ui_story_1018_10180202_32_dialog_content = "Tapi kalian semua melihatnya, menahan diri hanya memberi mereka kesempatan untuk menyakiti kalian.",
  ui_story_1018_10180202_33_dialog_content = "Tapi mereka tetap Aurorian!",
  ui_story_1018_10180202_34_dialog_content = "*Meraung*",
  ui_story_1018_10180202_35_dialog_content = "Lihat lagi, mereka tidak berbeda dengan Eclipsite! Siapa pun yang mencoba menyakiti prajurit Twilight adalah musuh!",
  ui_story_1018_10180202_36_dialog_content = "Prajurit Illumina, jika kalian ingin membela Twilight, tunjukkan kekuatan kalian dan jangan kenal ampun pada musuh!",
  ui_story_1018_10180202_37_dialog_content = "Jika tidak, tinggalkan Twilight, jasa Anda tidak lagi diperlukan.",
  ui_story_1018_10180202_38_dialog_content = "Aku—",
  ui_story_1018_10180202_39_dialog_content = "Bukan hak kamu untuk memerintahkan prajuritku...",
  ui_story_1018_10180202_40_dialog_content = "Terkendala oleh Darkflow... Namun mereka... tidak pantas mati...",
  ui_story_1018_10180202_41_dialog_content = "Aku yakin...",
  ui_story_1018_10180202_42_dialog_content = "Leo, ini Wrath!",
  ui_story_1018_10180202_43_dialog_content = "...",
  ui_story_1018_10180202_44_dialog_content = "Karena... Aku pernah ke sana...",
  ui_story_1018_10180202_45_dialog_content = "Grand Marshal!",
  ui_story_1018_10180301_1_dialog_content = "Wrath! Kami sudah mencarimu kemana-mana!",
  ui_story_1018_10180301_2_dialog_content = "Kamu langsung mengendalikan prajurit yang mengamuk begitu kamu muncul...",
  ui_story_1018_10180301_3_dialog_content = "Mereka tidak bisa mengendalikan diri... di bawah pengaruh rawa-rawa...",
  ui_story_1018_10180301_4_dialog_content = "Mereka tidak bermaksud... melukai siapa pun...",
  ui_story_1018_10180301_5_dialog_content = "...",
  ui_story_1018_10180301_6_dialog_content = "Demi White Night... Senang kau selamat, Grand Marshal!",
  ui_story_1018_10180301_7_option_content = "Saat ini kamu terlihat sangat lelah",
  ui_story_1018_10180301_8_dialog_content = "Kamu terluka atau merasa tidak nyaman di bagian mana saja?",
  ui_story_1018_10180301_9_dialog_content = "Selain rasa sakit dari dampak quagmire...",
  ui_story_1018_10180301_10_dialog_content = "Aku tidak ingat apa-apa.",
  ui_story_1018_10180301_11_option_content = "Apa yang terjadi?",
  ui_story_1018_10180301_12_dialog_content = "Kenapa kami sama sekali tidak bisa menemukanmu?",
  ui_story_1018_10180301_13_dialog_content = "Aku juga tidak yakin...",
  ui_story_1018_10180301_14_dialog_content = "Yang aku ingat hanyalah semuanya menjadi gelap setelah berhasil keluar dari lumpur...",
  ui_story_1018_10180301_15_dialog_content = "Jangan khawatir, aku hanya terkena lumpur di seluruh tubuhku.",
  ui_story_1018_10180301_16_dialog_content = "Berapa banyak lagi prajurit seperti ini yang masih ada di luar sana...?",
  ui_story_1018_10180301_17_dialog_content = "Leo telah mencari mereka...",
  ui_story_1018_10180301_18_dialog_content = "Tapi untungnya kamu kembali!",
  ui_story_1018_10180301_19_dialog_content = "Ya…",
  ui_story_1018_10180301_20_dialog_content = "Aku memang bilang aku akan menyelamatkan Twilight sebelum berubah menjadi Eclipsite.",
  ui_story_1018_10180301_21_dialog_content = "Sekarang saya harus menambahkan tentara saya ke dalam daftar itu...",
  ui_story_1018_10180301_22_dialog_content = "Aku tak akan mentolerir upaya untuk mengesampingkan mereka sebagai Eclipsite dan membunuh mereka...",
  ui_story_1018_10180301_23_dialog_content = "Senang melihat kau baik-baik saja, Grand Marshal.",
  ui_story_1018_10180301_24_dialog_content = "Tidak pernah ada niat saya untuk menyakiti prajurit Illumina. Saya hanya menjaga kepentingan Twilight.",
  ui_story_1018_10180301_25_dialog_content = "Membunuh musuh saat situasi menguntungkan, meninggalkan pasukan saat menghadapi kesulitan... Maaf jika saya menolak untuk menerima strategi para Ksatria.",
  ui_story_1018_10180301_26_dialog_content = "Marsekal Agung, saya...",
  ui_story_1018_10180301_27_dialog_content = "Kini aku kembali, aku akan memimpin prajurit-prajuritku.",
  ui_story_1018_10180301_28_dialog_content = "Aku tidak punya cukup energi untuk bertarung lagi denganmu, jadi jangan melampaui batasmu...",
  ui_story_1018_10180301_29_dialog_content = "Sesuai keinginan Anda, Grand Marshal.",
  ui_story_1018_10180301_30_dialog_content = "Grand Marshal Wrath, sepertinya kamu sedang lemah saat ini.",
  ui_story_1018_10180301_31_dialog_content = "Tolong ikut denganku ke rumah sakit untuk perawatan!",
  ui_story_1018_10180301_32_dialog_content = "Kita berada di medan perang. Aku tidak akan pergi selama prajurit-prajuritku masih berdiri.",
  ui_story_1018_10180301_33_dialog_content = "Baiklah, setidaknya izinkan saya untuk membalut lukamu. Silahkan istirahat sejenak di atas kudaku!",
  ui_story_1018_10180301_34_dialog_content = "Jika Anda ingin melakukannya untuk pasukan Anda, saya sarankan untuk memeriksakan diri Anda.",
  ui_story_1018_10180301_35_dialog_content = "Ya, kamu menghabiskan cukup banyak waktu di rawa-rawa, jadi mungkin sebaiknya jangan mengambil risiko.",
  ui_story_1018_10180301_36_dialog_content = "Baiklah. Terima kasih sebelumnya, Joselyne.",
  ui_story_1018_10180301_37_dialog_content = "Demi White Night... Sungguh mengherankan kamu masih bisa mengaktifkan Luminatics.",
  ui_story_1018_10180301_38_dialog_content = "Kamu memiliki banyak luka, tetapi tidak ada yang fatal, meskipun kondisimu sangat melemah.",
  ui_story_1018_10180301_39_dialog_content = "Sangat lemah? Aku tidak berpikir begitu...",
  ui_story_1018_10180301_40_dialog_content = "Sebaliknya, saya merasa tubuh saya pulih dengan cepat.",
  ui_story_1018_10180301_41_dialog_content = "Setelah dipikir-pikir, ada kekuatan yang mengalir dalam diriku ketika aku tidak sadar...",
  ui_story_1018_10180301_42_dialog_content = "Seolah-olah ada seseorang yang menyembuhkan saya... Perasaan itu sulit untuk dijelaskan.",
  ui_story_1018_10180301_43_dialog_content = "Menyembuhkan kamu? Bagaimana mungkin ada orang lain di sana?",
  ui_story_1018_10180301_44_dialog_content = "Itu memang aneh... Tapi tidak mustahil, mengingat saya berdiri di sini sekarang ini.",
  ui_story_1018_10180301_45_dialog_content = "Sayang sekali aku tidak bisa melindungi prajurit-prajuritku...",
  ui_story_1018_10180301_46_dialog_content = "Grand Marshal, kami belum menemukan dua tim yang maju ke medan perang bersama Anda.",
  ui_story_1018_10180301_47_dialog_content = "Kapten Axelia telah memimpin misi pencarian.",
  ui_story_1018_10180301_48_dialog_content = "Tapi... Mereka yang baru saja kamu temui mungkin saja itu mereka...",
  ui_story_1018_10180301_49_dialog_content = "Aku mengantarkan mereka langsung ke musuh...",
  ui_story_1018_10180301_50_dialog_content = "Tidak, Grand Marshal! Kami yang melanggar perintah Anda...",
  ui_story_1018_10180301_51_dialog_content = "Kami bertekad untuk melanjutkan bersama Anda! Dan anggota baru ini, mereka adalah...",
  ui_story_1018_10180301_52_dialog_content = "Kamu melancarkan serangan terhadap musuh seperti itu tanpa ragu dan berhasil membalikkan keadaan.",
  ui_story_1018_10180301_53_dialog_content = "Jika kita bisa menemukan mereka segera, mungkin masih ada harapan!",
  ui_story_1018_10180301_54_dialog_content = "...",
  ui_story_1018_10180301_55_dialog_content = "Bagaimanapun, aku tidak bisa membiarkan kamu mengambil risiko bersamaku lagi...",
  ui_story_1018_10180301_56_dialog_content = "<color=#e8d9bb>Semua orang datang ke tepi barat zona perang...</color>",
  ui_story_1018_10180301_57_dialog_content = "Tak pernah menyangka rawa ini bisa sampai sejauh ini... Sepertinya masih terus bergerak.",
  ui_story_1018_10180301_58_dialog_content = "Mungkin lebih banyak musuh yang akan datang, dan siapa tahu kemana rawa-rawa mengalir May membawa prajurit yang hilang.",
  ui_story_1018_10180301_59_dialog_content = "Dalam hal ini, pertempuran tidak akan berakhir selama rawa-rawa itu masih ada.",
  ui_story_1018_10180301_60_dialog_content = "Yang paling saya khawatirkan adalah musuh menyerang bersama prajurit saya...",
  ui_story_1018_10180301_61_dialog_content = "Saya bertanggung jawab atas dampak negatif dalam pertempuran ini karena salah penghakiman.",
  ui_story_1018_10180301_62_dialog_content = "Kamu tidak bisa tahu, Grand Marshal. Mari kita lanjutkan pencarian di sepanjang rawa-rawa.",
  ui_story_1018_10180301_63_dialog_content = "Tentu saja…",
  ui_story_1018_10180301_64_dialog_content = "Grand Marshal Wrath! Lihat sayap barat dari garis pertahanan—",
  ui_story_1018_10180301_65_dialog_content = "Tiga Engine VII mecha ada di sana! Bersama dengan prajurit kita!",
  ui_story_1018_10180301_66_dialog_content = "Itu mecha yang melindungi seranganku... Tidak menyangka akan ada di sini.",
  ui_story_1018_10180301_67_dialog_content = "Semuanya berantakan... Basis di belakang mereka telah hancur berkeping-keping. Untungnya, mereka berhasil bertahan.",
  ui_story_1018_10180301_68_dialog_content = "Ini hanya menyisakan 1 Engine VII M.I.A, tapi seharusnya ada di dekat sini. Ayo kita periksa...",
  ui_story_1018_10180301_69_dialog_content = "<color=#e8d9bb>Gigit! Gigit!</color>",
  ui_story_1018_10180301_70_dialog_content = "Eh...Kapten?!",
  ui_story_1018_10180301_71_dialog_content = "...",
  ui_story_1018_10180301_72_dialog_content = "Mech-nya benar-benar hancur...",
  ui_story_1018_10180301_73_dialog_content = "Dan para prajurit di sekitar Engine VII... mereka menggerogoti cangkang luar mech...",
  ui_story_1018_10180301_74_dialog_content = "Aum...",
  ui_story_1018_10180301_75_dialog_content = "Mengisi kembali diri Anda dengan ini seperti Eclipsite?",
  ui_story_1018_10180301_76_dialog_content = "Astaga...",
  ui_story_1018_10180301_77_dialog_content = "Rarrr!",
  ui_story_1018_10180301_78_dialog_content = "...",
  ui_story_1018_10180301_79_dialog_content = "Tetap di kuda, Grand Marshal. Mereka sepertinya tidak menyadari kita mendekat. Kita bisa melanjutkan dari sini.",
  ui_story_1018_10180301_80_dialog_content = "Benar, aku bisa mengalahkan segelintir Eclipsite ini sendirian.",
  ui_story_1018_10180301_81_dialog_content = "Mereka bukan Eclipsite... Mereka adalah prajuritku...",
  ui_story_1018_10180301_82_dialog_content = "Cukup tundukkan mereka saja...",
  ui_story_1018_10180301_83_dialog_content = "...",
  ui_story_1018_10180301_84_dialog_content = "Bagaimana bisa Anda begitu teguh sebagai Grand Marshal, namun begitu ragu-ragu saat menyangkut anak buah Anda?",
  ui_story_1018_10180301_85_dialog_content = "Tundukkan mereka... Mungkin masih ada harapan untuk mereka...",
  ui_story_1018_10180301_86_dialog_content = "Wrath benar, aku bisa mencoba menyelamatkan mereka!",
  ui_story_1018_10180302_1_dialog_content = "Fiuh... Mereka baik-baik saja sekarang.",
  ui_story_1018_10180302_2_dialog_content = "Kita bisa serahkan mereka ke tim medis. Aku lihat PlayerName tahu cara menyembuhkan sekaligus mengkoordinasikan di medan perang.",
  ui_story_1018_10180302_3_dialog_content = "Ketika Wrath mengalami hal yang sama sebelumnya, inilah cara dia keluar dari situasi tersebut.",
  ui_story_1018_10180302_4_dialog_content = "Mereka hanya terperangkap dalam pikiran mereka sendiri dan tidak bisa mengendalikan diri.",
  ui_story_1018_10180302_5_dialog_content = "Tapi saya minta maaf tentang prajurit yang telah melahap sebagian besar dari baju besi itu.",
  ui_story_1018_10180302_6_dialog_content = "Demi White Night di atas... Leo mencoba menaklukkannya dan saya percaya dia telah berusaha sebaik mungkin.",
  ui_story_1018_10180302_7_dialog_content = "Prajurit itu mengalami mutilasi dan hanya Darkflow yang menopangnya...",
  ui_story_1018_10180302_8_dialog_content = "Saya rasa Grand Marshal seharusnya melihat gambaran besar dan kurang terikat pada seorang... tentara seperti itu.",
  ui_story_1018_10180302_9_dialog_content = "Itu aku tahu, kamu tak perlu mengingatkanku...",
  ui_story_1018_10180302_10_dialog_content = "Apakah kamu berencana mengirimkan semua prajurit yang kita temukan ke rumah sakit?",
  ui_story_1018_10180302_11_dialog_content = "Beberapa ratus merupakan jumlah yang cukup banyak.",
  ui_story_1018_10180302_12_dialog_content = "Memang, orang-orang yang terluka yang telah kita selamatkan ini tidak akan muat di fasilitas ini...",
  ui_story_1018_10180302_13_dialog_content = "Tetapi mengingat kondisi khusus mereka, mereka harus segera ditangani.",
  ui_story_1018_10180302_14_dialog_content = "Salah satu prajuritku sudah menangani hal ini. Ketika dia kembali, aku akan memindahkan warga ke kota-kota yang lebih besar.",
  ui_story_1018_10180302_15_dialog_content = "Apa yang akan kamu gunakan untuk memindahkannya? Kereta dorong?",
  ui_story_1018_10180302_16_dialog_content = "Ya, beberapa gerbong yang tersisa, dan mungkin beberapa dari mereka harus berjalan...",
  ui_story_1018_10180302_17_dialog_content = "Berjalan hampir sama saja dengan menyerahkan diri mereka kepada Eclipsites sebagai makanan.",
  ui_story_1018_10180302_18_dialog_content = "Aku punya saran... Meskipun keputusan terserah pada PlayerName.",
  ui_story_1018_10180302_19_dialog_content = "Sebenarnya, aku juga dapat satu...",
  ui_story_1018_10180302_20_dialog_content = "Soroz.",
  ui_story_1018_10180302_21_dialog_content = "Tidak akan menjadi masalah untuk mengungsikan penduduk Twilight sesegera mungkin, dan Eraveil mungkin adalah lokasi yang paling aman saat ini.",
  ui_story_1018_10180302_22_dialog_content = "Tapi apa rencanamu untuk orang-orang yang terluka yang kita temukan nanti?",
  ui_story_1018_10180302_23_dialog_content = "Sebelum rawa-rawa menghilang... Kita akan mencari solusi. Penduduk yang tak berdaya adalah prioritas utama.",
  ui_story_1018_10180302_24_dialog_content = "Leo, izinkan aku mencoba Benteng Lumo.",
  ui_story_1018_10180302_25_dialog_content = "Banyak anggota gereja yang secara sukarela tetap tinggal untuk memberikan bantuan medis.",
  ui_story_1018_10180302_26_dialog_content = "Aku akan meminta bantuan gereja untuk mereka yang membutuhkan perhatian segera. Mudah-mudahan, hal itu juga akan memfasilitasi upaya penyelamatan Grand Marshal di masa depan.",
  ui_story_1018_10180302_27_dialog_content = "Benteng Lumo... Saya tidak terlalu optimis tentang itu.",
  ui_story_1018_10180302_28_dialog_content = "Tapi yang terpenting adalah kita harus memastikan keselamatan para pengungsi, dan tidak ada yang bisa memastikan langkah terbaik, jadi saya tidak akan menghentikan Anda.",
  ui_story_1018_10180302_29_dialog_content = "Kurasa tidak peduli apa masalah antar faksi, Gereja White Night tidak akan mengusir Aurorian.",
  ui_story_1018_10180302_30_dialog_content = "Namun, apakah Anda keberatan jika prajurit Illumina berlindung di Gereja White Night, Grand Marshal Wrath?",
  ui_story_1018_10180302_31_dialog_content = "Jangan libatkan saya. Illumina tidak pernah berurusan dengan agama.",
  ui_story_1018_10180302_32_dialog_content = "Tetapi mengingat situasinya, saya akan sangat menghargai jika Anda bisa merawat prajurit-prajurit saya.",
  ui_story_1018_10180302_33_dialog_content = "Yakin tidak butuh bantuan medis?",
  ui_story_1018_10180302_34_dialog_content = "Aku hanya merasa lelah... Aku merasa lebih baik setelah berbicara dengan kalian.",
  ui_story_1018_10180302_35_dialog_content = "May Bolehkah saya meminjam kuda Anda, Joselyne?",
  ui_story_1018_10180302_36_dialog_content = "Tentu saja! Jangan khawatir, Grand Marshal, saya akan mencari bantuan untuk prajurit Anda.",
  ui_story_1018_10180302_37_dialog_content = "Kuharap perang sudah berakhir saat kita bertemu lagi. Aku akan bersiap-siap sekarang.",
  ui_story_1018_10180302_38_dialog_content = "Hati-hati di jalan.",
  ui_story_1018_10180302_39_dialog_content = "PlayerName, nanti temui prajuritku di pintu keluar barat.",
  ui_story_1018_10180302_40_dialog_content = "Ketika krisis di Twilight berakhir, saya akan menemukan Anda dan kita akan menetapkan para pengungsi.",
  ui_story_1018_10180302_41_dialog_content = "Ehem, terima kasih atas semua yang telah Anda lakukan. Saya yakin kita akan bertemu lagi.",
  ui_story_1018_10180302_42_dialog_content = "Apa... Aku tak pernah bilang aku akan pergi.",
  ui_story_1018_10180302_43_dialog_content = "Soroz akan membawa penduduk ke tempat yang aman dengan autopilot.",
  ui_story_1018_10180302_44_dialog_content = "Aku bilang aku akan melindungi Twilight bersamamu. Aku tidak akan pergi sampai perang ini berakhir.",
  ui_story_1018_10180302_45_dialog_content = "Kamu jauh lebih gigih daripada yang kukira, PlayerName.",
  ui_story_1018_10180302_46_dialog_content = "Kita sudah cukup lama bertarung bersama hingga aku bisa mengharapkan ini darimu.",
  ui_story_1018_10180302_47_dialog_content = "PlayerName, saya telah mendarat di pintu masuk barat Twilight. Kami berada dalam jangkauan komunikasi.",
  ui_story_1018_10180302_48_dialog_content = "Soroz, tolong bawa orang-orang dari Twilight ke tempat yang aman di rumah kita.",
  ui_story_1018_10180302_49_dialog_content = "Tujuan Penetapan: Eraveil",
  ui_story_1018_10180302_50_dialog_content = "PlayerName, pastikan untuk menjaga keselamatan dirimu.",
  ui_story_1018_10180302_51_dialog_content = "Terima kasih, aku serahkan mereka kepadamu.",
  ui_story_1018_10180401_1_dialog_content = "<color=#e8d9bb>Di kereta yang melaju menuju Zona Gelap...</color>",
  ui_story_1018_10180401_2_dialog_content = "Satu, dua, tiga... Kita sudah berputar empat kali. Ada perintah, Pak?",
  ui_story_1018_10180401_3_dialog_content = "Tenanglah, Merry, nantinya akan ada jawaban untuk misteri itu.",
  ui_story_1018_10180401_4_dialog_content = "Apakah benar Pak Charon percaya pada arahan yang diberikan oleh Minch?",
  ui_story_1018_10180401_5_dialog_content = "Kita sudah bekerja sama dalam waktu yang lama, jadi sudah jelas... Ngomong-ngomong, apakah kamu baik-baik saja di sana, Minch?",
  ui_story_1018_10180401_6_dialog_content = "Aku sakit kepala sejak tadi. Mungkin karena angin...",
  ui_story_1018_10180401_7_dialog_content = "Tidak ada angin di dalam kereta!",
  ui_story_1018_10180401_8_dialog_content = "Di luar jendela. Kita menghadapi angin kencang dengan tingkat yang sangat tidak biasa.",
  ui_story_1018_10180401_9_dialog_content = "Hanya dari lampu yang redup, aku bisa tahu bahwa kota yang baru saja kita lewati sedang dalam masalah. Mungkin itu sebabnya dia terlambat.",
  ui_story_1018_10180401_10_dialog_content = "Jadi bercak kegelapan itu sebenarnya adalah sebuah kota... Rasanya seperti cakar obsidian yang menjulur keluar dari Zona Gelap...",
  ui_story_1018_10180401_11_dialog_content = "Huh. Jarang sekali bisa naik kereta yang nyaman dan artistik, dan ini pemandangan yang aku dapatkan...",
  ui_story_1018_10180401_12_dialog_content = "Apakah kamu benar-benar percaya pada ketiga orang itu, Petugas Charon? Kau bilang kita hanya perlu istirahat sejak kita pergi.",
  ui_story_1018_10180401_13_dialog_content = "Ini adalah kali ketiga saya bangun, jadi mengapa kita belum mencapai Dark Zone?",
  ui_story_1018_10180401_14_dialog_content = "Kami sedang menjalankan misi, Vice. Jangan khawatir, Other End akan memastikan kita aman.",
  ui_story_1018_10180401_15_dialog_content = "Tapi pak, saya tidak ingat jarak dari Illumina ke Zona Gelap sepanjang ini...",
  ui_story_1018_10180401_16_dialog_content = "Orang yang memberi saya misi ini juga memberikan dua petunjuk yang tepat, dan inilah langkah yang diperlukan untuk mengurai misteri tersebut.",
  ui_story_1018_10180401_17_dialog_content = "Petunjuk yang tepat? Apa itu?",
  ui_story_1018_10180401_18_dialog_content = "Salah satunya mencakup berbagai koordinat di luar garis Illumina. Di mana pun kami pernah berada ada di peta.",
  ui_story_1018_10180401_19_dialog_content = "Jadi, saya yakin kita tidak melewati tempat yang seharusnya tidak kita lalui.",
  ui_story_1018_10180401_20_dialog_content = "Tapi menurut tanda-tandanya, bukankah kita telah berputar-putar di sini selama ini?",
  ui_story_1018_10180401_21_dialog_content = "Ssst... Kita tidak ingin membuat tamu kita terkejut.",
  ui_story_1018_10180401_22_dialog_content = "Mereka bertiga? Jadi kamu juga merasakan ada yang salah?",
  ui_story_1018_10180401_23_dialog_content = "Sebut saja agenda rahasia. Berputar-putar juga merupakan bagian dari misi ini.",
  ui_story_1018_10180401_24_dialog_content = "Sebuah burung kecil memberitahuku bahwa kita akan segera menemukan jawaban dari misteri ini.",
  ui_story_1018_10180401_25_dialog_content = "Misteri lagi?",
  ui_story_1018_10180401_26_dialog_content = "Jadi siapa pemeran pendukung kedua?",
  ui_story_1018_10180401_27_dialog_content = "Petunjuk kedua adalah menuju ke lokasi yang ditandai khusus, lalu melakukan video konferensi dengan Tim Rekognisi Dark Zone.",
  ui_story_1018_10180401_28_dialog_content = "Hah? Tapi kami belum menerima sinyal posisi dari mereka dalam waktu yang lama.",
  ui_story_1018_10180401_29_dialog_content = "Apakah kapten mematikan komunikatornya? Atau adakah alat pengacau sinyal di dekat mereka?",
  ui_story_1018_10180401_30_dialog_content = "Pak, saya percaya kita perlu informasi terbaru tentang situasi saat ini, atau kita tidak akan memiliki harapan untuk menyelesaikan misi!",
  ui_story_1018_10180401_31_dialog_content = "Saya sangat khawatir tentang kondisi saat ini dari Illumina.",
  ui_story_1018_10180401_32_dialog_content = "Tahan keraguanmu untuk sementara waktu dan mungkin aku bisa memberikan jawaban.",
  ui_story_1018_10180401_33_dialog_content = "Mendengar suara wanita, Officer Charon?",
  ui_story_1018_10180401_34_dialog_content = "Baru saja melintas di depanku.",
  ui_story_1018_10180401_35_dialog_content = "Victoria!",
  ui_story_1018_10180401_36_dialog_content = "Anda di sini, Bu!",
  ui_story_1018_10180401_37_dialog_content = "Ingat aku, Konduktor Illumina? Di depan orang luar, mungkin aku tidak seharusnya memanggilmu sebagai kerabat... atau saudara jauh.",
  ui_story_1018_10180401_38_dialog_content = "Hemat ucapan misteriusmu, Lady Victoria. Apa yang akan kamu dan ketiga bawahanmu lakukan?",
  ui_story_1018_10180401_39_dialog_content = "Lady Victoria...? Jadi ketiga orang ini dari True Order?",
  ui_story_1018_10180401_40_dialog_content = "Saya harap mereka tidak membuat perjalanan Anda tidak menyenangkan, Nona Vice.",
  ui_story_1018_10180401_41_dialog_content = "Nah, kamu harus bertanya pada Charon itu. Apakah kita berputar-putar karena kamu?",
  ui_story_1018_10180401_42_dialog_content = "Tidak sepenuhnya. Tapi kehadiranku sekarang secara resmi melegitimasi kereta ini yang penuh dengan anggota True Order.",
  ui_story_1018_10180401_43_dialog_content = "Nona Vice, saya menebak Anda di sini karena Anda tertarik dengan pengunjung misterius ke Illumina...",
  ui_story_1018_10180401_44_dialog_content = "Serta apa yang terjadi pada kota Twilight yang telah Anda lewati.",
  ui_story_1018_10180401_45_dialog_content = "Bagaimana kamu tahu tentang orang yang menyelinap ke Illumina? Dan apakah ada sesuatu yang terjadi di Twilight?",
  ui_story_1018_10180401_46_dialog_content = "Nah, itulah mengapa kereta ini membutuhkan pencerahanku!",
  ui_story_1018_10180401_47_dialog_content = "Mengenai apa yang terjadi di Twilight... Biarlah saya katakan bahwa Caelestite dan Marsekal Besar baru belum menemukan trik untuk bertahan hidup.",
  ui_story_1018_10180401_48_dialog_content = "PlayerName juga pergi ke Twilight?!",
  ui_story_1018_10180401_49_dialog_content = "Saya tahu tentang Grand Marshal, tapi apakah mereka mengalami masalah di Twilight?",
  ui_story_1018_10180401_50_dialog_content = "Situasi mereka di Twilight tergantung pada bagaimana Anda memandang mereka. Jangan khawatir tentang hal yang tidak diketahui sebelum wahyu itu terungkap.",
  ui_story_1018_10180401_51_dialog_content = "Apakah itu benar, Charon? PlayerName dan Marsekal Agung tidak dalam bahaya, bukan?",
  ui_story_1018_10180401_52_dialog_content = "...",
  ui_story_1018_10180401_53_dialog_content = "Jadi, apakah kamu ingin pergi dan melihat rawa itu sendiri?",
  ui_story_1018_10180401_54_dialog_content = "Meskipun kitab tersebut mengungkapkan bahwa takdir bagi gadis muda ini adalah... Eternal Night.",
  ui_story_1018_10180401_55_dialog_content = "Jatuh ke dalam malam abadi setelah melupakan kekasih, namun tetap diberi makan oleh tombak gelap untuk menyelesaikan pengorbanan dan penebusan.",
  ui_story_1018_10180401_56_dialog_content = "Selamat, Nona Vice, karena Anda akan menemukan kebenaran dalam perjalanan ini.",
  ui_story_1018_10180401_57_dialog_content = "Apa yang kamu bicarakan...?",
  ui_story_1018_10180401_58_dialog_content = "Omong kosong! Perjalanan ini bukan tentang takdir, melainkan prajurit Illumina yang menjalankan misi.",
  ui_story_1018_10180401_59_dialog_content = "Tolong jangan menghalangi kami, Lady Victoria, atau akan ada masalah.",
  ui_story_1018_10180401_60_dialog_content = "Selama ini kamu bersama anggota-anggotaku, apakah kamu masih belum merasakan bahwa The Warp sedang bekerja?",
  ui_story_1018_10180401_61_dialog_content = "Warp... Bukankah kamu yang bertanggung jawab atas kita yang terus berputar-putar tanpa henti?",
  ui_story_1018_10180401_62_dialog_content = "Aku melihat tanda leluhur pada dirimu telah memudar. Saatnya untuk beberapa pengungkapan.",
  ui_story_1018_10180401_63_dialog_content = "Karena berbagai alasan, Eclipse menggunakan itu untuk menghentikanmu mendekat.",
  ui_story_1018_10180401_64_dialog_content = "Setelah mencapai jarak tertentu, Anda akan kembali ke titik awal. Itulah kekuatan dari The Warp.",
  ui_story_1018_10180401_65_dialog_content = "Dan \"titik awal\" mengacu pada pusat lingkaran, jadi kamu hanya bisa bergerak di dalam garis radius.",
  ui_story_1018_10180401_66_dialog_content = "Bagaimana itu dicapai?",
  ui_story_1018_10180401_67_dialog_content = "Jangan terlalu mendalaminya, Miss Vice, karena itu hanya akan membuat Anda gila.",
  ui_story_1018_10180401_68_dialog_content = "Tapi dengan bimbingan saya, kita akan lolos dari masalah ini. Sekarang, apakah Konduktor akan menolak keberangkatan saya mengingat hal itu?",
  ui_story_1018_10180401_69_dialog_content = "...",
  ui_story_1018_10180401_70_dialog_content = "Saya akan menganggap keheningan ini sebagai izin untuk naik. Anda boleh menambah kecepatan, Konduktor.",
  ui_story_1018_10180401_71_dialog_content = "Saya bingung, Tuan. Apakah kita masih menuju Malam Abadi?",
  ui_story_1018_10180401_72_dialog_content = "Kereta akan berhenti di mana pun yang Anda inginkan, Nona Vice.",
  ui_story_1018_10180401_73_dialog_content = "Jadi, terserah aku ya...",
  ui_story_1018_10180401_74_dialog_content = "<color=#e8d9bb>*Peluit kereta*</color>",
  ui_story_1018_10180401_75_dialog_content = "Tunggu!",
  ui_story_1018_10180401_76_dialog_content = "Apa yang terjadi dengan embusan angin tiba-tiba ini? Bukan pertanda serangan musuh, bukan?",
  ui_story_1018_10180401_77_dialog_content = "Axelia harus melindungi bawahan...",
  ui_story_1018_10180401_78_dialog_content = "Sangat aneh angin kencang ini tidak menyebabkan satu gelombang pun di rawa...",
  ui_story_1018_10180401_79_dialog_content = "Axelia, apakah kamu melihat sesuatu yang tidak biasa dalam upaya penyelamatan di sini?",
  ui_story_1018_10180401_80_dialog_content = "Mungkin musuh utama belum dikalahkan dan hanya sedang bersembunyi menunggu...",
  ui_story_1018_10180401_81_dialog_content = "<color=#e8d9bb>Krucuk...</color>",
  ui_story_1018_10180401_82_dialog_content = "Kapten, sektor yang menjadi tanggung jawabku sudah disisir. Kami sedang memindahkan yang terluka ke rumah sakit.",
  ui_story_1018_10180401_83_dialog_content = "Salinan. Operasi penyelamatan jauh lebih lancar tanpa gangguan Eclipsite.",
  ui_story_1018_10180401_84_dialog_content = "<color=#e8d9bb>Krucuk...</color>",
  ui_story_1018_10180401_85_dialog_content = "Axelia mendengar suara aneh...",
  ui_story_1018_10180401_86_dialog_content = "Aku juga mendengarnya, seperti sesuatu yang keluar dari air...",
  ui_story_1018_10180401_87_dialog_content = "Aum...",
  ui_story_1018_10180401_88_dialog_content = "Itu…?",
  ui_story_1018_10180401_89_dialog_content = "Grand Marshal! Lihatlah prajurit di tandu itu!",
  ui_story_1018_10180401_90_dialog_content = "Tak mungkin!",
  ui_story_1018_10180401_91_dialog_content = "Lumpur pada mereka mengalir seolah-olah hidup.",
  ui_story_1018_10180401_92_dialog_content = "Jadi suara itu adalah...",
  ui_story_1018_10180401_93_dialog_content = "Ah—! Tolong!",
  ui_story_1018_10180401_94_dialog_content = "Semuanya, menjauh dari tandu dan berkumpul di sekitarku!",
  ui_story_1018_10180401_95_dialog_content = "Jelas, tidak ada masalah saat mereka diselamatkan...",
  ui_story_1018_10180401_96_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_1018_10180401_97_dialog_content = "Aum...",
  ui_story_1018_10180401_98_dialog_content = "Tunggu, angin itu lagi! Ini mungkin jebakan!",
  ui_story_1018_10180401_99_dialog_content = "Berlindunglah di balik penghalang apa pun yang bisa kamu temukan!",
  ui_story_1018_10180401_100_dialog_content = "Aku hampir terpukau...",
  ui_story_1018_10180401_101_dialog_content = "Berpeganganlah padaku, PlayerName!",
  ui_story_1018_10180401_102_dialog_content = "Tak bisa membuka mata... Apakah ini musuh baru?",
  ui_story_1018_10180401_103_dialog_content = "<color=#e8d9bb>Guyuran!</color>",
  ui_story_1018_10180401_104_dialog_content = "Awas, lumpur menyembur ke arah ini!",
  ui_story_1018_10180401_105_dialog_content = "Di belakangmu, Grand Marshal Wrath!",
  ui_story_1018_10180401_106_dialog_content = "Aku melihatnya... Ini bukan hanya lumpur, ada sesuatu di dalamnya!",
  ui_story_1018_10180401_107_dialog_content = "Grah!",
  ui_story_1018_10180401_108_dialog_content = "Banyak Eclipsites di rawa!",
  ui_story_1018_10180401_109_dialog_content = "Memang, genangan air itu memimpin para Eclipsite, dengan bantuan prajurit yang berada di bawah pengaruh Darkflow...",
  ui_story_1018_10180401_110_dialog_content = "Ahh!",
  ui_story_1018_10180401_111_dialog_content = "Ah—! Tolong!",
  ui_story_1018_10180401_112_dialog_content = "Mereka menjadi gila, Grand Marshal Wrath. Saya harus memperlakukan mereka seperti Eclipsite!",
  ui_story_1018_10180401_113_dialog_content = "Tidak, bukan itu...",
  ui_story_1018_10180401_114_dialog_content = "Ada Eclipsites di belakang kita! Lumpur akan menenggelamkan kita semua jika kita tidak mengambil tindakan!",
  ui_story_1018_10180401_115_dialog_content = "Leo...",
  ui_story_1018_10180401_116_dialog_content = "<color=#e8d9bb>*Bunyi peluit kereta dalam hembusan angin*</color>",
  ui_story_1018_10180401_117_dialog_content = "Oh tidak, satu lagi!",
  ui_story_1018_10180401_118_dialog_content = "Aku mendengar peluit kereta...",
  ui_story_1018_10180401_119_dialog_content = "Pak! Peta menunjukkan ini adalah... Twilight?",
  ui_story_1018_10180401_120_dialog_content = "Apakah The Warp yang melakukan ini, Lady Victoria? Mengapa kita di sini?",
  ui_story_1018_10180401_121_dialog_content = "Kami berhasil melarikan diri dari The Warp, dan saya mengarahkan kereta ke sini sesuai dengan keinginan Miss Vice.",
  ui_story_1018_10180401_122_dialog_content = "Twilight kebetulan berada di ujung garis radius.",
  ui_story_1018_10180401_123_dialog_content = "Sulit dipercaya…",
  ui_story_1018_10180401_124_dialog_content = "Pak, saya melihat banyak orang di sana. Apakah itu PlayerName dan yang lainnya?",
  ui_story_1018_10180401_125_dialog_content = "Ada banyak lumpur di bawah kereta. Hati-hati dengan Eclipsites yang mungkin ada di dalamnya.",
  ui_story_1018_10180401_126_dialog_content = "Lumpur kotor, Eclipsite kotor! The Other End akan menghancurkan mereka!",
  ui_story_1018_10180401_127_dialog_content = "Berpegangan erat, semuanya. Kita akan melewati lumpur untuk berhenti di depan!",
  ui_story_1018_10180401_128_dialog_content = "<color=#e8d9bb>*Peluit kereta*</color>",
  ui_story_1018_10180401_129_dialog_content = "Hey, Grand Marshal Wrath—",
  ui_story_1018_10180401_130_dialog_content = "Selamat atas janji temu Anda. Maaf, aku terlambat!",
  ui_story_1018_10180401_131_dialog_content = "Marsekal Agung Wrath! PlayerName!",
  ui_story_1018_10180401_132_dialog_content = "Vice!",
  ui_story_1018_10180401_133_dialog_content = "Charon, Vice... Apa yang kamu lakukan di sini?",
  ui_story_1018_10180401_134_dialog_content = "Bukankah kamu sedang menjalankan misi? Mengapa kamu berada di Twilight?",
  ui_story_1018_10180401_135_dialog_content = "Perhatikan waktu, Konduktor. Ini hanya perhentian sementara.",
  ui_story_1018_10180401_136_dialog_content = "Saya mendengar tentang pertempuran di Twilight dan saya khawatir, Grand Marshal. Namun, saya tidak bisa tinggal terlalu lama sebelum harus melanjutkan misi saya.",
  ui_story_1018_10180401_137_dialog_content = "Kamu sudah mengalahkan Eclipsite, jadi itu sudah sangat membantu.",
  ui_story_1018_10180401_138_dialog_content = "Di sisi lain, apakah kamu yang menciptakan angin kencang dan bukan musuhnya?",
  ui_story_1018_10180401_139_dialog_content = "Kami tidak datang ke sini secara kebetulan, tetapi saya tidak punya waktu untuk menjelaskannya. Lumpur ini membentang sangat jauh, mungkin juga dengan lebih banyak Eclipsites di dalamnya.",
  ui_story_1018_10180401_140_dialog_content = "Apakah angin ini berarti The Warp akan aktif lagi, Lady...?",
  ui_story_1018_10180401_141_dialog_content = "Tidak merasa gelisah...? Duduk sebentar, aku akan ajak semua orang bersamaku.",
  ui_story_1018_10180401_142_dialog_content = "Berdasarkan jaraknya, dalam 20 detik.",
  ui_story_1018_10180401_143_dialog_content = "Mari kita hitung mundur, nona...",
  ui_story_1018_10180401_144_dialog_content = "Apakah kamu menemui masalah di sepanjang perjalanan, Vice?",
  ui_story_1018_10180401_145_dialog_content = "Dibandingkan dengan kalian di Twilight, apa yang saya alami itu tidak ada apa-apanya.",
  ui_story_1018_10180401_146_dialog_content = "Kecuali omong kosong misterius dari Lady Victoria... yang saya tidak mengerti.",
  ui_story_1018_10180401_147_dialog_content = "Bagaimanapun, hati-hati. Kemunculan True Order tidak pernah membawa pertanda baik.",
  ui_story_1018_10180401_148_dialog_content = "Kapan kamu juga mulai bawel?",
  ui_story_1018_10180401_149_dialog_content = "Sebenarnya, saya pikir Lady Victoria sedang membantu kita.",
  ui_story_1018_10180401_150_dialog_content = "Jika itu juga niat Charon...",
  ui_story_1018_10180401_151_dialog_content = "15, 14, 13...",
  ui_story_1018_10180401_152_dialog_content = "10, 9...",
  ui_story_1018_10180401_153_dialog_content = "Oleh karena itu, teruslah berjuang, Grand Marshal. Semua orang di Illumina menantikan kepulanganmu dengan selamat!",
  ui_story_1018_10180401_154_dialog_content = "Tentu, dan kamu juga. May semoga misi kamu berhasil dengan selamat.",
  ui_story_1018_10180401_155_dialog_content = "5, 4, 3...",
  ui_story_1018_10180401_156_dialog_content = "Kamu ingat apa yang kukatakan padamu?",
  ui_story_1018_10180401_157_dialog_content = "Kamu bilang untuk memanggil namamu jika aku dalam bahaya. Aku ingat!",
  ui_story_1018_10180401_158_dialog_content = "2, 1, 0.",
  ui_story_1018_10180401_159_dialog_content = "Kalau begitu, selamat tinggal, semuanya.",
  ui_story_1018_10180401_160_dialog_content = "<color=#e8d9bb>Gruk—</color>",
  ui_story_1018_10180401_161_dialog_content = "Mereka tiba-tiba menghilang...",
  ui_story_1018_10180401_162_dialog_content = "Tak bisa dipercaya. Itu telah melampaui pemahamanku tentang Luminatics.",
  ui_story_1018_10180401_163_dialog_content = "Ahh!",
  ui_story_1018_10180401_164_dialog_content = "Grand Marshal! Ksatria Lumo tidak lagi mampu menahan para prajurit itu...",
  ui_story_1018_10180401_165_dialog_content = "Apakah kita benar-benar kehabisan pilihan...",
  ui_story_1018_10180401_166_dialog_content = "Kapten, saudara-saudara kita bertanya-tanya, siapa sebenarnya musuh kita?",
  ui_story_1018_10180401_167_dialog_content = "Mantan prajurit Grand Marshal yang berubah menjadi Eclipsite sangat kejam dan brutal...",
  ui_story_1018_10180401_168_dialog_content = "Aku tidak akan mundur meskipun kali ini dia mencoba menghentikanku.",
  ui_story_1018_10180401_169_dialog_content = "Siapa pun yang menyakiti prajuritku akan dihadapi olehku!",
  ui_story_1018_10180401_170_dialog_content = "Ikuti saya, ksatria, dan habisi mereka semua!",
  ui_story_1018_10180401_171_dialog_content = "Siap, Pak!",
  ui_story_1018_10180401_X171_dialog_content = "Kenapa tiba-tiba ada embusan angin ini? Kita tidak sedang diserang, bukan...?",
  ui_story_1018_10180401_X172_dialog_content = "Jumlah Eclipsite semakin bertambah, tetapi misi pencarian dan penyelamatan masih berlangsung. Apakah ada temuan abnormal sejauh ini?",
  ui_story_1018_10180401_X173_dialog_content = "Melaporkan, Marsekal Agung! Operasi pencarian dan penyelamatan di area yang saya tangani belum terpengaruh sejauh ini!",
  ui_story_1018_10180401_X174_dialog_content = "Laporan, Grand Marshal. Sejumlah besar Eclipsite muncul di wilayah saya. Saya telah membasmi mereka semua.",
  ui_story_1018_10180401_X175_dialog_content = "Marsekal Agung, tampaknya Kapten Leo mengalami beberapa kesulitan di Rawan.",
  ui_story_1018_10180401_X176_dialog_content = "Mengerti, aku akan ke sana. Kalian yang lain, tetap waspada.",
  ui_story_1018_10180401_X177_dialog_content = "Semua yang terluka sudah dimuat di tandu, Kapten. Segera, saya akan mengangkut mereka ke rumah sakit.",
  ui_story_1018_10180401_X178_dialog_content = "Bagus. Semakin banyak Eclipsite muncul di Quagmire, kita harus mundur sebelum mereka melancarkan serangan berikutnya.",
  ui_story_1018_10180401_X179_dialog_content = "Siap, Kapten!",
  ui_story_1018_10180401_X180_dialog_content = "Aku baru saja mendengar suara aneh... Suaranya datang dari salah satu prajurit.",
  ui_story_1018_10180401_X181_dialog_content = "Jangan terlalu dekat dengan mereka, Axelia. Prajurit-prajurit ini baru saja ditarik keluar dari Quagmire.",
  ui_story_1018_10180401_X182_dialog_content = "Lumpur yang menutupi tubuh mereka mengalir seolah-olah hidup...",
  ui_story_1018_10180401_X183_dialog_content = "Kita tidak memiliki cara untuk membersihkannya dari tubuh mereka saat ini...",
  ui_story_1018_10180401_X184_dialog_content = "Aum...",
  ui_story_1018_10180401_X185_dialog_content = "Aum...",
  ui_story_1018_10180401_X186_dialog_content = "Yang terluka tidak bisa bertahan lebih lama lagi, Grand Marshal!",
  ui_story_1018_10180401_X187_dialog_content = "Lumpur di tubuh mereka... Apakah mulai bergerak lebih cepat?",
  ui_story_1018_10180401_X188_dialog_content = "Benarkah? Lalu itu hanya bisa berarti satu hal...",
  ui_story_1018_10180401_X189_dialog_content = "Mundur, semua! Lumpur sebentar lagi akan percik keluar!",
  ui_story_1018_10180401_X190_dialog_content = "Ini bukan hanya lumpur... Ada sesuatu yang lain di dalamnya!",
  ui_story_1018_10180401_X191_dialog_content = "Aahhhh!",
  ui_story_1018_10180401_X192_dialog_content = "Seperti yang saya duga, lumpur ini mengarahkan Eclipsite menuju kita. Darkflow juga mulai mempengaruhi para prajurit ini...",
  ui_story_1018_10180401_X193_dialog_content = "... Aku butuh tim ksatria untuk melindungi yang terluka! Sisanya, bersiaplah untuk pertempuran!",
  ui_story_1018_10180401_X194_dialog_content = "Siap, Pak!",
  ui_story_1018_10180401_X195_dialog_content = "<color=#e8d9bb>Haa... Haa...</color>",
  ui_story_1018_10180401_X196_dialog_content = "Lebih banyak lagi... Dan mereka menyerang dari belakang!",
  ui_story_1018_10180401_X197_dialog_content = "Aku hampir tak bisa berdiri lagi—",
  ui_story_1018_10180401_X198_dialog_content = "Berlindunglah di balik penghalang apa pun yang bisa kamu temukan!",
  ui_story_1018_10180401_X199_dialog_content = "Mataku... Aku bahkan tak bisa membukanya. Apakah itu... Musuh baru?",
  ui_story_1018_10180401_X200_dialog_content = "Berpeganganlah padaku, PlayerName!",
  ui_story_1018_10180401_X201_dialog_content = "<color=#e8d9bb>Psssh— Wu-wuuuu!</color>",
  ui_story_1018_10180401_X202_dialog_content = "PlayerName, kau baik-baik saja?",
  ui_story_1018_10180401_X203_dialog_content = "Sepertinya... Aku mendengar suara peluit kereta...",
  ui_story_1018_10180401_X204_dialog_content = "Apakah aku salah lihat? Wajah kotor itu di sana... PlayerName?!",
  ui_story_1018_10180401_X205_dialog_content = "B-Bagaimana kita sudah berada di Twilight?! Ini luar biasa...",
  ui_story_1018_10180401_X206_dialog_content = "Warp itu cukup menarik, bukan? Tetapi yang lebih menarik adalah keinginan hati Anda yang membawa kita ke sini, Nona Vice.",
  ui_story_1018_10180401_X207_dialog_content = "Memang prestasi yang luar biasa...",
  ui_story_1018_10180401_X208_dialog_content = "Aku masih belum benar-benar mengerti, tapi bisakah kita berhenti di depan? Sepertinya PlayerName dan yang lainnya dalam bahaya yang serius...",
  ui_story_1018_10180401_X209_dialog_content = "Kubangan dan para Eclipsite mulai mendekat dari segala arah di sekitar mereka...",
  ui_story_1018_10180401_X210_dialog_content = "Sayangnya, Nona Vice, ini bukan tujuan akhir kita. Tidak ada berhenti setelah kita memasuki Warp.",
  ui_story_1018_10180401_X211_dialog_content = "Tapi kita semakin dekat dan dekat dengan mereka... Bukankah ada sesuatu yang bisa kita lakukan untuk membantu?",
  ui_story_1018_10180401_X212_dialog_content = "Kita mungkin tidak bisa menghentikan...",
  ui_story_1018_10180401_X213_dialog_content = "Tapi Other End lebih dari cukup untuk menggempur Eclipsites yang kotor dan berlumpur ini! Berpeganganlah dengan erat, semuanya!",
  ui_story_1018_10180401_X214_dialog_content = "<color=#e8d9bb>Kecelakaan—</color>",
  ui_story_1018_10180401_X215_dialog_content = "Graah—",
  ui_story_1018_10180401_X216_dialog_content = "C-Captain! Apakah itu... Apakah itu kereta tadi?! Sepertinya kereta itu menabrak semua Eclipsite di sekitarnya!",
  ui_story_1018_10180401_X217_dialog_content = "Sepertinya desain dari Illumina... Tapi lupakan itu sekarang! Kita harus merawat yang terluka!",
  ui_story_1018_10180401_X218_dialog_content = "Siap, Pak!",
  ui_story_1018_10180401_X219_dialog_content = "Tidak ada salahnya... Itu tadi kereta Charon. Aku pikir aku bahkan melihat Vice di atasnya juga...",
  ui_story_1018_10180401_X220_dialog_content = "Tapi mengapa mereka tiba-tiba muncul di sini, hanya untuk menghilang segera setelahnya?",
  ui_story_1018_10180401_X221_dialog_content = "Saya tidak yakin... Vice dan Charon pergi untuk misi di Dark Zone sebelum saya datang ke Twilight.",
  ui_story_1018_10180401_X222_dialog_content = "Mereka muncul secara tak terduga, membasmi Eclipsites untuk kita, dan menghilang. Itu sesuatu yang tidak biasa.",
  ui_story_1018_10180401_X223_dialog_content = "Melapor, Marsekal Agung! Kami menemukan tim yang hilang lainnya di area ini!",
  ui_story_1018_10180401_X224_dialog_content = "Mengerti. Aku akan segera ke sana.",
  ui_story_1018_10180401_X225_dialog_content = "PlayerName, sangat mungkin misi mereka jauh melampaui pemahaman kita, tapi kita harus percaya mereka bisa menanganinya sendiri.",
  ui_story_1018_10180401_X226_dialog_content = "Saat ini, kita memiliki masalah kita sendiri untuk ditangani.",
  ui_story_1018_10180401_X227_dialog_content = "Aku tahu. Aku hanya berharap semuanya berjalan lancar untuk mereka.",
  ui_story_1018_10180401_X228_dialog_content = "(Tolong berhati-hati, Vice.)",
  ui_story_1018_10180501_1_dialog_content = "<color=#e8d9bb>Kereta ini melayang di dalam kehampaan yang tidak diketahui...</color>",
  ui_story_1018_10180501_2_dialog_content = "Lepaskan lengan bajumu, Minch, selama ini kamu membuatku sesak!",
  ui_story_1018_10180501_3_dialog_content = "Hei, lihat, loncengnya bersinar. Apakah itu artinya kita berhasil?",
  ui_story_1018_10180501_4_dialog_content = "Memang, sensasi benda tebal yang mengenai kelopak mataku sangat jelas.",
  ui_story_1018_10180501_5_dialog_content = "Di mana kita, Lady Victoria...?",
  ui_story_1018_10180501_6_dialog_content = "Tanpa terang atau kegelapan, hanya Kebenaran. Inilah tempat perlindungan rahasiaku.",
  ui_story_1018_10180501_7_dialog_content = "Oh tidak! Aku akan berlutut untuk mendengar ajaran dari Masterku!",
  ui_story_1018_10180501_8_dialog_content = "Ini adalah rasa sakit yang tumpul dari Firman Kebenaran yang aku ingat. Aku akan mendengarkan dengan penuh perhatian!",
  ui_story_1018_10180501_9_dialog_content = "Apakah ada yang keberatan berbicara dengan bahasa yang sederhana? Tempat apa ini?",
  ui_story_1018_10180501_10_dialog_content = "Jangan khawatir, Nona Vice. Kami sudah melarikan diri dari The Warp.",
  ui_story_1018_10180501_11_dialog_content = "Jadi, kamu menyelamatkan kami?",
  ui_story_1018_10180501_12_dialog_content = "Intinya, kamu mengikuti bimbinganku—",
  ui_story_1018_10180501_13_dialog_content = "Nyonya, aku \"melihat\" darah!",
  ui_story_1018_10180501_14_dialog_content = "Aku \"mendengar\" kata-kata yang jelas dan rasa sakit menusuk telingaku!",
  ui_story_1018_10180501_15_dialog_content = "Tak kusangka Black Tome akan memberikan wahyu sekarang...",
  ui_story_1018_10180501_16_dialog_content = "Huruf-hurufnya berubah begitu cepat...",
  ui_story_1018_10180501_17_dialog_content = "\"Setelah operasi, kegagalan akan dihadapi.\"",
  ui_story_1018_10180501_18_dialog_content = "Apakah ini yang disebut \"Eclipse akan mengembangkan ekornya, dan ketika Aurora tiba, Dia akan memulai perjalanan kembali.\"",
  ui_story_1018_10180501_19_dialog_content = "Tidak, ini masih berubah...",
  ui_story_1018_10180501_20_dialog_content = "\"Di tengah kemunduran, sebuah usaha megah akan bangkit.\"",
  ui_story_1018_10180501_21_dialog_content = "Ini berkaitan dengan \"Di saat bencana, Aurorian akan bertemu dengan-Nya, namun terhambat oleh Aurora.\"",
  ui_story_1018_10180501_22_dialog_content = "Wahyu ini tidak jelas...",
  ui_story_1018_10180501_23_dialog_content = "Nyonya, kebencian yang sengit membakar di mata Sang Lord...",
  ui_story_1018_10180501_24_dialog_content = "Tutup matamu, Dysis! Itu bukan Tuhan, karena Dia tidak membenci!",
  ui_story_1018_10180501_25_dialog_content = "Tahan napas, semuanya.",
  ui_story_1018_10180501_26_dialog_content = "...",
  ui_story_1018_10180501_27_dialog_content = "Pak, ada sinyal samar yang masuk di dasbor.",
  ui_story_1018_10180501_28_dialog_content = "Ini adalah koordinat dari Tim Ekspedisi Dark Zone, dan lokasinya tidak ada di peta.",
  ui_story_1018_10180501_29_dialog_content = "Karena ini bukan <color=#FFB400>tempat nyata</color>, melainkan \"Setiap orang meninggalkan rumah, namun perjalanan pulang adalah awal\" dalam wahyu.",
  ui_story_1018_10180501_30_dialog_content = "Apa artinya itu? Bisakah kita menemukan mereka?",
  ui_story_1018_10180501_31_dialog_content = "Aku percaya saatnya Terang dan Kegelapan mengakhiri perang mereka, dan Lord of Truth akan datang.",
  ui_story_1018_10180501_32_dialog_content = "Untuk menyaksikan momen tersebut, saya akan mengantarkan Anda ke tujuan.",
  ui_story_1018_10180501_33_dialog_content = "Namun, saya membutuhkan bantuan Anda, Konduktor.",
  ui_story_1018_10180501_34_dialog_content = "...",
  ui_story_1018_10180501_35_dialog_content = "Saya sangat tidak nyaman sekarang ini, Officer Charon...",
  ui_story_1018_10180501_36_dialog_content = "Santapan rahasia Lady Victoria sepertinya semakin menyempit... Aku kesulitan bernapas...",
  ui_story_1018_10180501_37_dialog_content = "Iya, aku juga...",
  ui_story_1018_10180501_38_dialog_content = "Akhirnya ketemu juga, ternyata...",
  ui_story_1018_10180501_39_dialog_content = "Apa yang Anemone lakukan, meninggalkanmu selama ini?",
  ui_story_1018_10180501_40_dialog_content = "Siapa yang berbicara...?",
  ui_story_1018_10180501_41_dialog_content = "Aku benci kamu, tapi aku tidak ingat alasannya...",
  ui_story_1018_10180501_42_dialog_content = "Tinggalkan rakyatku, kotoran!",
  ui_story_1018_10180501_43_dialog_content = "Anda tidak menarik bagi saya. Tapi wanita pirang itu, saya suka benda di tangan Anda.",
  ui_story_1018_10180501_44_dialog_content = "Kebenaran akan mengguncangmu sampai ke inti, pelayan kejahatan.",
  ui_story_1018_10180501_45_dialog_content = "Aku rasa kalian yang seharusnya gemetar. Apa yang kalian lakukan dengan mata tertutup?",
  ui_story_1018_10180501_46_dialog_content = "Menawarkan darah untuk perlindungan dari Lord of Truth.",
  ui_story_1018_10180501_47_dialog_content = "Oh, kamu sedang melakukan ritual.",
  ui_story_1018_10180501_48_dialog_content = "Akulah lawanmu, pengecut yang takut menampakkan wajah! Terimalah Hellfire ini!",
  ui_story_1018_10180501_49_dialog_content = "Murid Dysis telah memberikan persembahan.",
  ui_story_1018_10180501_50_dialog_content = "Dengan persembahan rasa sakit, Tuhan akan menyampaikan Injil kepada kamu.",
  ui_story_1018_10180501_51_dialog_content = "Murid Merry telah memberikan persembahan.",
  ui_story_1018_10180501_52_dialog_content = "Biar aku yang melakukannya, lebih efisien seperti itu.",
  ui_story_1018_10180501_53_dialog_content = "Saksikan Mukjizat ini!",
  ui_story_1018_10180501_54_dialog_content = "Ritual akan selesai sebentar lagi, Conductor!",
  ui_story_1018_10180501_55_dialog_content = "Kau baik-baik saja, Perwira Charon?",
  ui_story_1018_10180501_56_dialog_content = "Tetap di tempat, Acheron Ferryman sedang melintas! Memutar kereta ke bawah!",
  ui_story_1018_10180501_57_dialog_content = "Kakiku terangkat dari lantai?",
  ui_story_1018_10180501_58_dialog_content = "Dengan persembahan seekor hewan peliharaan, Tuhan akan mengungkap misteri tersebut.",
  ui_story_1018_10180501_59_dialog_content = "Murid Minch telah membuat persembahan.",
  ui_story_1018_10180501_60_dialog_content = "Kamu sedang lari?",
  ui_story_1018_10180501_61_dialog_content = "May semoga Tuhan menerima persembahan ini, ambil kekuatan darahku dan tunjukkan kebenaran kemerahan kepada dunia!",
  ui_story_1018_10180501_62_dialog_content = "Mukjizat telah terjadi... Alam Wraith telah ditembus!",
  ui_story_1018_10180501_63_dialog_content = "T-tunggu, semua orang...!",
  ui_story_1018_10180501_64_dialog_content = "Tidak, aku tidak bisa, aku jatuh terlalu cepat...",
  ui_story_1018_10180501_65_dialog_content = "Dalam perjalanan menuju Zona Gelap, kita akan melewati <color=#FFB400>Sungai Styx</color>, yang juga dikenal sebagai <color=#FFB400>Padang Gurun Terlupakan</color>.",
  ui_story_1018_10180501_66_dialog_content = "Tolong tutup mata sebelum melihat cahaya untuk menghindari deteksi oleh elemen berbahaya.",
  ui_story_1018_10180501_67_dialog_content = "Tapi saat aku menutup mata, aku melihat gerombolan Eclipsites mendekat ke arahku...",
  ui_story_1018_10180501_68_dialog_content = "Mereka hanya ada di pikiran Anda, tidak nyata.",
  ui_story_1018_10180501_69_dialog_content = "Tapi mereka adalah prajurit Illumina...",
  ui_story_1018_10180501_70_dialog_content = "Aku melihat mereka memangsa mecha...",
  ui_story_1018_10180501_71_dialog_content = "Mereka saling membunuh...",
  ui_story_1018_10180501_72_dialog_content = "Saya juga melihat rawa hitam yang membentang dari Zona Gelap hingga ke garis depan Illumina...",
  ui_story_1018_10180501_73_dialog_content = "(Meninggalkan, jangan mendekat.)",
  ui_story_1018_10180501_74_dialog_content = "(Itu kamu... Siapa kamu?)",
  ui_story_1018_10180501_75_dialog_content = "(Meninggalkan, jangan mendekat.)",
  ui_story_1018_10180501_76_dialog_content = "(Tapi, saya merasa ada kekuatan tak dikenal yang mendorong saya maju...)",
  ui_story_1018_10180501_77_dialog_content = "Vice?",
  ui_story_1018_10180501_78_dialog_content = "Ada suara yang menyuruh kita pergi...",
  ui_story_1018_10180501_79_dialog_content = "Jangan dengarkan atau menatap, atau kamu mungkin tidak akan pernah bangun lagi.",
  ui_story_1018_10180501_80_dialog_content = "Aku tidak bisa melihatnya dengan jelas, tapi aku bisa mendengar suaranya dan detak jantungnya. Rasanya begitu nyata...",
  ui_story_1018_10180501_81_dialog_content = "Seolah-olah aku adalah dia...",
  ui_story_1018_10180501_82_dialog_content = "Itu adalah tanda yang tepat bahwa bahaya ada di tikungan.",
  ui_story_1018_10180501_83_dialog_content = "(PlayerName bilang untuk menelepon jika aku dalam bahaya.)",
  ui_story_1018_10180501_84_dialog_content = "(Ini harus sampai, kan...)",
  ui_story_1018_10180501_85_dialog_content = "(Keluar, bahaya.)",
  ui_story_1018_10180501_86_dialog_content = "(Tapi tidak peduli apa, aku akan bertemu denganmu...)",
  ui_story_1018_10180501_87_dialog_content = "(Karena ini pertama kalinya aku merasa seseorang bisa begitu dekat denganku...)",
  ui_story_1018_10180501_88_dialog_content = "(...)",
  ui_story_1018_10180501_89_dialog_content = "(Apa ini...?)",
  ui_story_1018_10180501_90_dialog_content = "(Detak jantung Vice...)",
  ui_story_1018_10180501_91_dialog_content = "(Dia dalam bahaya...)",
  ui_story_1018_10180501_92_dialog_content = "PlayerName, awas di belakangmu!",
  ui_story_1018_10180601_1_dialog_content = "Aum...",
  ui_story_1018_10180601_2_dialog_content = "Grand Marshal, berikan perintahnya... Senapanku sudah terkunci di kepalanya...",
  ui_story_1018_10180601_X2_dialog_content = "Simpan senjatamu!",
  ui_story_1018_10180601_X3_dialog_content = "Tapi... Tapi dia telah membunuh begitu banyak prajurit kita! Dia bahkan menyerang Anda, komandan atasannya! Dia tidak pantas menjadi prajurit Illumina, apalagi pemimpin Skuadron Kesembilan!",
  ui_story_1018_10180601_X4_dialog_content = "Itu bukan salahnya. Ada sesuatu di matanya yang memberitahu saya bahwa dia masih ada di sana.",
  ui_story_1018_10180601_X5_dialog_content = "Grand Marshal! Para ksatria sudah tidak bisa menahan prajurit-prajurit itu lagi... Dengan keadaan seperti ini, kita semua akan segera berada dalam bahaya besar...",
  ui_story_1018_10180601_3_dialog_content = "Meskipun dia memegang komando Skuadron Kesembilan, tangannya ternoda dengan darah saudara-saudara kita. Dia tidak pantas diperlakukan seperti prajurit Illumina!",
  ui_story_1018_10180601_4_dialog_content = "Matanya memberitahuku bahwa masih ada seseorang di sana!",
  ui_story_1018_10180601_5_dialog_content = "Lihat baik-baik, aku ini Grand Marshal-mu. Sekarang lepaskan tanganmu!",
  ui_story_1018_10180601_6_dialog_content = "... Marsekal Agung...",
  ui_story_1018_10180601_7_dialog_content = "Dia sebenarnya bisa mendengar kita...",
  ui_story_1018_10180601_8_dialog_content = "Aku akan membawamu kembali ke Illumina. Kamu tidak akan mati di sini.",
  ui_story_1018_10180601_9_dialog_content = "...",
  ui_story_1018_10180601_10_dialog_content = "Tubuhnya dikendalikan oleh Darkflow. Dia akan mematahkan lehermu lebih cepat atau lambat jika kamu menunggu.",
  ui_story_1018_10180601_11_dialog_content = "Aum...",
  ui_story_1018_10180601_12_dialog_content = "(Kekuatan di dalam diriku... Rasanya seperti telah terbangkitkan...)",
  ui_story_1018_10180601_13_dialog_content = "(Saya mulai merasa ingin membunuhnya...)",
  ui_story_1018_10180601_14_dialog_content = "Wrath, dia juga kehilangan akal seperti kamu dulu, jadi jangan terburu-buru...",
  ui_story_1018_10180601_15_dialog_content = "Mungkin biarkan aku mencoba dengan kemampuan psikisku?",
  ui_story_1018_10180601_16_dialog_content = "Kita tidak tahu kondisinya, jadi kamu mungkin bisa terluka.",
  ui_story_1018_10180601_17_dialog_content = "Tapi mungkin ini satu-satunya kesempatan yang kita punya...",
  ui_story_1018_10180601_18_dialog_content = "Jika ada sesuatu yang mulai salah, saya akan berhenti segera, saya janji.",
  ui_story_1018_10180601_19_dialog_content = "Jika dia menyakitimu, aku tak akan ragu-ragu...",
  ui_story_1018_10180601_20_dialog_content = "Baiklah…",
  ui_story_1018_10180601_21_option_content = "Coba telepati",
  ui_story_1018_10180601_22_dialog_content = "(Saya di... Ini adalah... Undercity Illumina...)",
  ui_story_1018_10180601_23_dialog_content = "(Ini pasti ruang tamu. Aku bahkan bisa mencium aroma deterjen.)",
  ui_story_1018_10180601_24_dialog_content = "Tapi, Bu, ini adalah kesempatan sekali seumur hidup!",
  ui_story_1018_10180601_25_dialog_content = "(Bertengkar dengan Ibu?)",
  ui_story_1018_10180601_26_dialog_content = "Tantangan tak terhitung menuju tujuannya membuat Komandan Wrath menjadi seperti yang dia sekarang!",
  ui_story_1018_10180601_27_dialog_content = "Jika aku melewatkan program latihan prajurit ini, impianku untuk menjadi Grand Marshal tidak akan pernah terwujud!",
  ui_story_1018_10180601_28_dialog_content = "Komandan Wrath percaya pada kemampuan saya, dan dia bilang saya memiliki potensi untuk peran berpangkat lebih tinggi!",
  ui_story_1018_10180601_29_dialog_content = "Untuk bangkit sebagai pemimpin... Untuk meraih kemenangan dalam pertempuran, satu demi satu... Sama seperti yang dikejar oleh ayahmu, dan sekarang, giliranmu...",
  ui_story_1018_10180601_30_dialog_content = "Kamu benar-benar mewarisi keberanian dan kecerdasan ayahmu. Dalam pandanganku, kamu selalu yang terbaik...",
  ui_story_1018_10180601_31_dialog_content = "Tapi sayang... Aku dengar program latihannya bisa sangat menuntut...",
  ui_story_1018_10180601_32_dialog_content = "Jika kamu gagal melewati pelatihan itu, mungkin kamu tidak akan pernah bisa kembali ke medan perang lagi...",
  ui_story_1018_10180601_33_dialog_content = "Tetap bersamaku, ya? Kalian berdua adalah segalanya yang aku miliki sekarang...",
  ui_story_1018_10180601_34_dialog_content = "Mama... Aku percaya pada kakakku...",
  ui_story_1018_10180601_35_dialog_content = "Ya, Bu. Tolong percayalah padaku juga! Aku akan bertahan, tidak diragukan lagi!",
  ui_story_1018_10180601_36_dialog_content = "Tidak ada masa depan untuk saya jika terus tinggal di Kota Gannon. Memasuki medan perang dan menerima kematian sebagai bagian yang tak terhindarkan— itulah yang dilakukan prajurit sejati!",
  ui_story_1018_10180601_37_dialog_content = "Oh sayang... Tolong jangan mengatakan hal seperti itu lagi.",
  ui_story_1018_10180601_38_dialog_content = "Pokoknya, aku sudah memutuskan!",
  ui_story_1018_10180601_39_dialog_content = "(...)",
  ui_story_1018_10180601_40_dialog_content = "(Apa yang akan dipikirkan ibunya jika dia tahu apa yang terjadi padanya di medan pertempuran?)",
  ui_story_1018_10180601_41_dialog_content = "(Ups, aku lupa waktu saat mendengarkan mereka!)",
  ui_story_1018_10180601_42_dialog_content = "(Hmm, ini tempat baru, dan cahayanya sangat silau...)",
  ui_story_1018_10180601_43_dialog_content = "Komandan, apakah ini ujian terakhir dari Program Phospherus?",
  ui_story_1018_10180601_44_dialog_content = "Benar, ini adalah langkah terakhir.",
  ui_story_1018_10180601_45_dialog_content = "Tidak ada larangan sekarang. Tujuan Anda hanya mengalahkan lawan berikutnya dan bertahan hidup.",
  ui_story_1018_10180601_46_dialog_content = "(Hei, pergi dari sini sekarang!)",
  ui_story_1018_10180601_47_dialog_content = "(Ibu? Apa yang sedang Ibu lakukan di sini... Aku sudah memutuskan, jadi tolong jangan coba menghentikanku..)",
  ui_story_1018_10180601_48_dialog_content = "(Dia menganggapku sebagai ibunya. Kalau begitu...)",
  ui_story_1018_10180601_49_dialog_content = "(Jangan dengarkan dia. Bergabung dengan proyek itu akan mengubahmu menjadi Eclipsite! Aku tidak ingin melihatmu seperti itu!)",
  ui_story_1018_10180601_50_dialog_content = "(Tidak, Bu... Komandan berpikir aku benar-benar berbakat, dan aku harus lulus tes ini.)",
  ui_story_1018_10180601_51_dialog_content = "Kita bisa mulai kapanpun kau siap.",
  ui_story_1018_10180601_52_dialog_content = "(Dia berbohong padamu! Kamu sedang berjuang dalam pertempuran di Twilight sekarang!)",
  ui_story_1018_10180601_53_dialog_content = "(Bukan musuh di depanmu, melainkan Wrath, atasanmu. Sekarang keluar dari ruangan!)",
  ui_story_1018_10180601_54_dialog_content = "(Wrath, Grand Marshal, juga sedang menonton?)",
  ui_story_1018_10180601_55_dialog_content = "(Twilight, kamu menyebutkan... Aku merasa seperti pernah ke sana...)",
  ui_story_1018_10180601_56_dialog_content = "Apa lagi yang kautunggu?",
  ui_story_1018_10180601_57_dialog_content = "Tidak... Komandan, saya siap.",
  ui_story_1018_10180601_58_dialog_content = "(Tolong, bangun!)",
  ui_story_1018_10180601_59_dialog_content = "(Ibu, saksikan aku... Aku akan menjadi prajurit yang pemberani.)",
  ui_story_1018_10180601_60_dialog_content = "Astaga!",
  ui_story_1018_10180601_61_dialog_content = "(Hei, bangun! Jangan melawan!)",
  ui_story_1018_10180601_62_dialog_content = "Komandan, saat aku melihat Eclipsite, aku merasa... gelombang kekuatan mengalir dalam diriku.",
  ui_story_1018_10180601_63_dialog_content = "Benar, rasakan kekuatannya, lalu kendalikan kekuatan itu.",
  ui_story_1018_10180601_64_dialog_content = "Astaga!",
  ui_story_1018_10180601_65_dialog_content = "Semua Eclipsite... HARUS MATI!",
  ui_story_1018_10180601_66_dialog_content = "(Oh tidak, jika aku tidak mengakhiri ini sekarang...)",
  ui_story_1018_10180601_67_dialog_content = "MATI!!!",
  ui_story_1018_10180601_68_dialog_content = "Astaga!",
  ui_story_1018_10180601_69_dialog_content = "<color=#e8d9bb>Roooaaarrr!!!</color>",
  ui_story_1018_10180601_70_dialog_content = "Oh tidak! Tampaknya raungan-Nya telah membangkitkan semangat semua prajurit yang terkorupsi lainnya!",
  ui_story_1018_10180602_1_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_1018_10180602_2_dialog_content = "...",
  ui_story_1018_10180602_3_dialog_content = "Maaf, Grand Marshal. Ini satu-satunya cara.",
  ui_story_1018_10180602_4_dialog_content = "Kau tidak apa-apa, PlayerName?",
  ui_story_1018_10180602_5_dialog_content = "Maaf, aku gagal menyelamatkannya...",
  ui_story_1018_10180602_6_dialog_content = "Tapi dia adalah prajurit yang hebat.",
  ui_story_1018_10180602_7_dialog_content = "Axelia sedih...",
  ui_story_1018_10180602_8_dialog_content = "Apa yang akan kamu lakukan dengan prajurit-prajurit di sana?",
  ui_story_1018_10180602_9_dialog_content = "...",
  ui_story_1018_10180602_10_dialog_content = "Membunuh mereka sendiri. Aku tidak pantas menjadi Grand Marshal...",
  ui_story_1018_10180602_11_dialog_content = "(Apa yang harus saya lakukan?)",
  ui_story_1018_10180602_12_dialog_content = "(Apa yang akan kamu lakukan, Reinhardt, jika ini adalah kamu?)",
  ui_story_1018_10180602_13_dialog_content = "Biar aku yang melakukannya.",
  ui_story_1018_10180602_14_dialog_content = "Leo...",
  ui_story_1018_10180602_15_dialog_content = "Pura-pura saja kamu tidak bisa menghentikanku saat aku berusaha keras untuk membunuh mereka.",
  ui_story_1018_10180602_16_dialog_content = "Saya hanya seorang ksatria penduduk Twilight. Saya tidak memiliki tanggung jawab menjalankan seluruh tentara seperti kamu.",
  ui_story_1018_10180602_17_dialog_content = "Belas kasihan hanya akan menyebabkan kerugian yang lebih besar. Kamu harus belajar untuk menghadapi kenyataan itu.",
  ui_story_1018_10180602_18_dialog_content = "Tidak, aku tidak tahan dengan semua darah ini di tanganku...",
  ui_story_1018_10180602_19_dialog_content = "Saya berjanji pada mereka bahwa saya akan memimpin mereka menuju kemenangan dalam pertempuran ini...",
  ui_story_1018_10180602_20_dialog_content = "Sebaliknya, aku malah membawa mereka langsung ke kuburan...",
  ui_story_1018_10180602_21_dialog_content = "(Aku pikir selama aku punya kekuatan, jika aku cukup kuat, aku bisa melakukan apa saja.)",
  ui_story_1018_10180602_22_dialog_content = "(Kuat cukup... Sungguh lelucon...)",
  ui_story_1018_10180602_23_dialog_content = "Wrath, saya rasa apa yang kamu lakukan lebih sulit daripada mencoba menjadi lebih kuat.",
  ui_story_1018_10180602_24_dialog_content = "...",
  ui_story_1018_10180602_25_dialog_content = "Menempatkan tubuh mereka sendiri dalam bahaya adalah tujuan seorang prajurit.",
  ui_story_1018_10180602_26_dialog_content = "Ketika mereka sendiri menjadi bahaya dan tidak mampu melindungi nyawa...",
  ui_story_1018_10180602_27_dialog_content = "Ini adalah satu-satunya hal yang bisa kita lakukan untuk mereka sebagai para komandan.",
  ui_story_1018_10180602_28_dialog_content = "Komandan...",
  ui_story_1018_10180602_29_dialog_content = "(Ini yang kamu maksud dengan melepaskan, Reinhardt...?)",
  ui_story_1018_10180602_30_dialog_content = "Percayalah padaku, prajuritmu sedang mati di tempat yang seharusnya dan rasa sakit mereka akan segera berakhir.",
  ui_story_1018_10180602_31_dialog_content = "Tunggu, Leo.",
  ui_story_1018_10180602_32_dialog_content = "Anda mungkin benar tentang mereka yang meninggal di tempat yang seharusnya...",
  ui_story_1018_10180602_33_dialog_content = "Saya harus menghadapi kenyataan.",
  ui_story_1018_10180602_34_dialog_content = "Daripada hidup dalam penderitaan, aku akan membuatnya cepat dan mudah bagi mereka.",
  ui_story_1018_10180602_35_dialog_content = "Marsekal Agung...",
  ui_story_1018_10180602_36_dialog_content = "Semua prajurit, izinkan aku mengucapkan beberapa kata terakhir kepada mantan rekan kalian.",
  ui_story_1018_10180602_37_dialog_content = "Tidak peduli apa pun, kami akan selalu mengikuti Anda!",
  ui_story_1018_10180602_38_dialog_content = "...",
  ui_story_1018_10180602_39_dialog_content = "Meskipun kamu tidak bisa memahami apa yang aku katakan, aku berjanji padamu...",
  ui_story_1018_10180602_40_dialog_content = "Kalian adalah prajurit Illumina, terlahir untuk melayani Illumina dengan bangga, menanggung tugas menghancurkan Eclipsite.",
  ui_story_1018_10180602_41_dialog_content = "Kamu tahu pertempuran adalah jalan tercepat menuju kematian, namun kamu tetap maju tanpa rasa takut...",
  ui_story_1018_10180602_42_dialog_content = "Kalian akan mati sebagai prajurit pemberani Illumina...",
  ui_story_1018_10180602_43_dialog_content = "Bukan seseorang yang dipaksa untuk ditinggalkan...",
  ui_story_1018_10180602_44_dialog_content = "Kami akan melanjutkan misi yang belum selesai dan terus berjuang!",
  ui_story_1018_10180602_45_dialog_content = "Aum...",
  ui_story_1018_10180602_46_dialog_content = "(Itu dia, Wrath, ini akan selesai sangat cepat...)",
  ui_story_1018_10180602_47_dialog_content = "Dan kamu bebas dari kewajibanmu dan bebas untuk merayakannya...",
  ui_story_1018_10180602_48_dialog_content = "Kemenangan di tempat yang bebas dari perang.",
  ui_story_1018_10180602_49_dialog_content = "Astaga!",
  ui_story_1018_10180602_50_dialog_content = "Para sniper mengambil bidikan...",
  ui_story_1018_10180602_51_dialog_content = "Tembak!",
  ui_story_1018_10180602_52_dialog_content = "<color=#e8d9bb>Dor! Dor! Dor!</color>",
  ui_story_1018_10180602_53_dialog_content = "...",
  ui_story_1018_10180602_54_dialog_content = "Perang telah berakhir untukmu. Beristirahatlah dalam damai.",
  ui_story_1018_10180602_55_dialog_content = "...",
  ui_story_1018_10180602_56_dialog_content = "...",
  ui_story_1018_10180701_1_dialog_content = "<color=#e8d9bb>Dalam perjalanan menuju Benteng Lumo...</color>",
  ui_story_1018_10180701_2_dialog_content = "Benteng Lumo ada di depan, Chi. Bagaimana kabarmu?",
  ui_story_1018_10180701_3_dialog_content = "Mmm... Aku masih memiliki sedikit energi yang tersisa...",
  ui_story_1018_10180701_4_dialog_content = "Kamu tidak terlihat baik. Apakah prajurit yang lolos dari tali itu menakutimu?",
  ui_story_1018_10180701_5_dialog_content = "Tidak, Joselyne...",
  ui_story_1018_10180701_6_dialog_content = "Melihatmu berjuang keras melindungi semua orang, aku sama sekali tidak takut.",
  ui_story_1018_10180701_7_dialog_content = "Tapi kali ini... ada begitu banyak yang terluka... beberapa bahkan perlu diikat dengan tali...",
  ui_story_1018_10180701_8_dialog_content = "Oh, aku tidak bermaksud mengeluh atau apa pun! Aku tahu bahwa para prajurit ini di sini untuk melindungi kami...",
  ui_story_1018_10180701_9_dialog_content = "Hanya saja... Joselyne, pasti sangat sulit bagi kamu untuk menghadapi situasi seperti ini sepanjang waktu, kan...",
  ui_story_1018_10180701_10_dialog_content = "...",
  ui_story_1018_10180701_11_dialog_content = "Tahu nggak, Chi, bahwa hidup di Twilight saat aku masih kecil itu lebih sulit daripada sekarang?",
  ui_story_1018_10180701_12_dialog_content = "Saat kamu kecil, Joselyne?",
  ui_story_1018_10180701_13_dialog_content = "Ketika aku berusia 12 tahun, Eclipsites menyerbu Twilight. Orang tuaku kehilangan nyawa mereka untuk melindungiku.",
  ui_story_1018_10180701_14_dialog_content = "Tak ada yang datang membantu desa kami, jadi kami hanya bisa mengandalkan diri sendiri.",
  ui_story_1018_10180701_15_dialog_content = "Aku ingat, bahkan anak-anak yang sedikit lebih tua dariku mengambil senjata dan berjuang. Aku tidak pernah melihat banyak dari mereka lagi...",
  ui_story_1018_10180701_16_dialog_content = "Lalu... Apa yang terjadi selanjutnya?",
  ui_story_1018_10180701_17_dialog_content = "Kemudian Eclipsite masuk ke desa. Aku membawa anak-anak yang tersisa bersamaku dan bersembunyi di mana-mana. Ketakutan itu tetap bersamaku selama bertahun-tahun.",
  ui_story_1018_10180701_18_dialog_content = "Untungnya, kami diselamatkan oleh Kesatria Ekspedisi, dan para prajurit membawaku ke panti asuhan Gereja White Night, lalu aku menjadi seorang biarawati.",
  ui_story_1018_10180701_19_dialog_content = "Itu memang terdengar cukup berat... Jadi, mengapa Anda kemudian memutuskan untuk bergabung dengan Ksatria Ekspedisi?",
  ui_story_1018_10180701_20_dialog_content = "Karena saya percaya bahwa hanya dengan aktif melawan Eclipsites, orang-orang Twilight memiliki kesempatan untuk bertahan hidup.",
  ui_story_1018_10180701_21_dialog_content = "Saya diselamatkan oleh para Ksatria, jadi saya ingin menciptakan lingkungan yang aman untuk Twilight seperti yang mereka lakukan.",
  ui_story_1018_10180701_22_dialog_content = "Joselyne, kamu benar-benar orang yang luar biasa!",
  ui_story_1018_10180701_23_dialog_content = "Kamu telah membantu banyak orang, Chi. Kamu lebih baik daripada saya pada usia ini!",
  ui_story_1018_10180701_24_dialog_content = "Di sinilah kita. Dorong sedikit lagi dan orang-orang yang terluka akan aman.",
  ui_story_1018_10180701_25_dialog_content = "Baiklah!",
  ui_story_1018_10180701_26_dialog_content = "<color=#e8d9bb>Knock-knock, knock, knock-knock</color>",
  ui_story_1018_10180701_27_dialog_content = "Saya Joselyne, seorang prajurit dari Twilight. Kami membawa yang terluka dan meminta bantuan medis serta tempat berlindung di Benteng Lumo!",
  ui_story_1018_10180701_28_dialog_content = "City Lord telah memerintahkan bahwa hanya penduduk Lumo yang diizinkan masuk. Anda harus mencari tempat perlindungan di tempat lain.",
  ui_story_1018_10180701_29_dialog_content = "Tolong dengarkan, orang-orang yang terluka di belakangku termasuk ksatria dari Benteng Lumo. Mereka bertarung bersama kita. Setidaknya yang bisa kalian lakukan adalah membiarkan mereka masuk.",
  ui_story_1018_10180701_30_dialog_content = "Ironthorn Knights telah meminta bantuan berkali-kali sebelumnya. Sayangnya, Benteng Lumo hanya memiliki sumber daya terbatas, dan kami tidak dapat menawarkan perawatan medis untuk lebih banyak prajurit.",
  ui_story_1018_10180701_31_dialog_content = "Tapi, Pak—",
  ui_story_1018_10180701_32_dialog_content = "<color=#e8d9bb>Buk! Bum!</color>",
  ui_story_1018_10180701_33_dialog_content = "Joselyne! Semakin sulit mengendalikan kedua prajurit Illumina itu!",
  ui_story_1018_10180701_34_dialog_content = "Jika mereka berhasil melepaskan diri dari tali lagi dan menyerang orang-orang yang terluka...",
  ui_story_1018_10180701_35_dialog_content = "Anggota tim Anda merupakan ancaman bagi penduduk Benteng Lumo. Ini alasan yang lebih kuat untuk tidak membiarkan Anda masuk!",
  ui_story_1018_10180701_36_dialog_content = "Oh, begitu…",
  ui_story_1018_10180701_37_dialog_content = "Tolong sampaikan pesan untuk Ayah Joseph dari Gereja White Night untuk saya—",
  ui_story_1018_10180701_38_dialog_content = "Saya, Joselyne, meminta suaka untuk Aurorian dari Gereja White Night sebagai Sang Santa dari Twilight.",
  ui_story_1018_10180701_39_dialog_content = "Pastor Joseph sibuk dengan urusan penting dan tidak ada di kota. Adapun Anda, Anda hanyalah “Orang Suci” yang dibicarakan oleh orang-orang Twilight.",
  ui_story_1018_10180701_40_dialog_content = "Bahkan jika kamu adalah seorang Santa yang sejati, saya tetap tidak akan menentang perintah Tuan Kota!",
  ui_story_1018_10180701_41_dialog_content = "Apakah Gereja akan mengabaikan kehidupan Aurorian ketika umat Dewa Cahaya sedang dalam kesulitan besar?!",
  ui_story_1018_10180701_42_dialog_content = "Rarrr!",
  ui_story_1018_10180701_43_dialog_content = "Ya Tuhan... Apakah para prajurit ini telah berubah menjadi Eclipsite?",
  ui_story_1018_10180701_44_dialog_content = "Joselyne!",
  ui_story_1018_10180701_45_dialog_content = "Jangan panik! Beranjaklah sejauh mungkin dari gerobak-gerobak itu. Saya akan menangani ini!",
  ui_story_1018_10180701_46_dialog_content = "<size=30>Buka gerbangnya.</size>",
  ui_story_1018_10180701_47_dialog_content = "Membiarkan prajurit seperti itu masuk hampir sama saja dengan menggali kuburan kita sendiri...",
  ui_story_1018_10180701_48_dialog_content = "Buka gerbangnya.",
  ui_story_1018_10180701_49_dialog_content = "Berani-beraninya kau melawan Sang Suci! Apakah kau telah membelakangi Gereja?",
  ui_story_1018_10180701_50_dialog_content = "Aku, Kapten Carleen dari Guardian of Lumopolis Gardens, memerintahkanmu untuk membuka gerbang bagi para pengungsi sebagai Lord Kota Sementara dari Benteng Lumo!",
  ui_story_1018_10180701_51_dialog_content = "Aku akan menghadapi Eclipsites. Sekarang buka gerbangnya!",
  ui_story_1018_10180701_52_dialog_content = "Nyonya Carleen... Y-Ya!",
  ui_story_1018_10180701_53_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_1018_10180702_1_dialog_content = "<color=#e8d9bb>Melihat cahaya dunia lain ini, semua orang tak bisa menahan diri untuk ingin tunduk hormat...</color>",
  ui_story_1018_10180702_2_dialog_content = "Seorang Nyonya Suci yang asli!",
  ui_story_1018_10180702_3_dialog_content = "Ini tidak mungkin salah, satu-satunya Nyonya Suci dalam cahaya suci!",
  ui_story_1018_10180702_4_dialog_content = "Sebagai saksi Dewa Cahaya, yang kusampaikan hanyalah kebenaran—",
  ui_story_1018_10180702_5_dialog_content = "Dengan cahaya sucimu, semoga kamu membimbing Aurorian yang tersesat.",
  ui_story_1018_10180702_6_dialog_content = "Joselyne! Cahaya emas berkilauan di tubuh para prajurit!",
  ui_story_1018_10180702_7_dialog_content = "Ini terasa aneh...dalam arti yang baik. Maksudku... rasa sakit di tubuhku menghilang...",
  ui_story_1018_10180702_8_dialog_content = "Uh, Joselyne... Apakah kamu... menangis?",
  ui_story_1018_10180702_9_dialog_content = "Melihat Nona Suci secara langsung... Ini sangat luar biasa bagi saya...",
  ui_story_1018_10180702_10_dialog_content = "Chi, dia adalah utusan Tuhan itu sendiri, Sang Lady Santa dari Gereja White Night!",
  ui_story_1018_10180702_11_dialog_content = "Nyonya Suci...",
  ui_story_1018_10180702_12_dialog_content = "Joselyne—",
  ui_story_1018_10180702_13_dialog_content = "Ayah Joseph! Malam Putih di atas—",
  ui_story_1018_10180702_14_dialog_content = "Demi White Night— Salam duka untuk para prajurit di Senja. Bagaimana keadaan Leo di sana?",
  ui_story_1018_10180702_15_dialog_content = "Kini jumlah Eclipsite lebih sedikit, berkat tentara Illumina dan Caelestite.",
  ui_story_1018_10180702_16_dialog_content = "Namun rawa-rawa tetap menjadi masalah, dan prajurit Illumina pun kesulitan...",
  ui_story_1018_10180702_17_dialog_content = "Saya sangat menyesal mendengar itu. Para prajurit di benteng mengikuti perintah dari bangsawan Lumopolis, dan bala bantuan yang dikirim oleh Lord Kota sebagian besar ditujukan untuk tujuan pertahanan.",
  ui_story_1018_10180702_18_dialog_content = "Selain terus memohon pada Schwartz diri sendiri, saya tidak bisa melakukan banyak hal lainnya...",
  ui_story_1018_10180702_19_dialog_content = "Saya hanya bisa mengirim anggota gereja ke Twilight dan membantu, lalu mengirimkan surat-surat tak henti-hentinya ke Kuil Malam Putih untuk meminta bantuan.",
  ui_story_1018_10180702_20_dialog_content = "Aku mengerti! Sekarang Lady Saintess ada di sini, Gereja White Night diberkahi dengan anugerah ilahi!",
  ui_story_1018_10180702_21_dialog_content = "Saya juga tidak menyangka itu. Saya berencana mengunjungi Lumopolis setelah mengirimkan permintaan terbaru saya.",
  ui_story_1018_10180702_22_dialog_content = "Namun sebelum saya berangkat, saya menerima instruksi pribadi dari Lady Saintess sendiri, jadi saya tetap tinggal dan menunggu.",
  ui_story_1018_10180702_23_dialog_content = "Kita akan membahas detailnya nanti. Saya harus pergi membuat persiapan di gereja.",
  ui_story_1018_10180702_24_dialog_content = "Saya akan mengirim anggota gereja ke Twilight untuk mengangkut yang terluka.",
  ui_story_1018_10180702_25_dialog_content = "Terima kasih atas bantuan Anda, Ayah Joseph!",
  ui_story_1018_10180702_26_dialog_content = "Tetapi beberapa yang terluka terpengaruh secara unik, jadi tolong awasi mereka.",
  ui_story_1018_10180702_27_dialog_content = "Tidak perlu khawatir. Pengawal bersama Lady Saintess juga ahli dalam pengobatan seperti dirinya. Aku akan menjaga mereka.",
  ui_story_1018_10180702_28_dialog_content = "Demi White Night.",
  ui_story_1018_10180702_29_dialog_content = "Demi White Night.",
  ui_story_1018_10180702_30_dialog_content = "Fiuh... Terima kasih kepada Dewa Cahaya yang abadi, seharusnya tidak ada masalah lagi.",
  ui_story_1018_10180702_31_dialog_content = "Kamu... Kamu benar-benar Lady Suci... Kedatangan ilahi di dunia terlupakan ini!",
  ui_story_1018_10180702_32_dialog_content = "Dengan kehadiran Nyonya Suci, lumpur ini tidak akan menyebar lebih jauh!",
  ui_story_1018_10180702_33_dialog_content = "Lihat, awan gelap di atas Twilight telah dihilangkan oleh Lady Saintess, membuat para Eclipsite tidak bisa melarikan diri!",
  ui_story_1018_10180702_34_dialog_content = "Terima kasih, Yang Mulia!",
  ui_story_1018_10180702_35_dialog_content = "Terima kasih kembali, dan tidak perlu memanggil saya Nona Suci.",
  ui_story_1018_10180702_36_dialog_content = "Yang Mulia, ada permintaan yang dengan rendah hati saya minta—anak saya masih bertarung di Twilight...",
  ui_story_1018_10180702_37_dialog_content = "Yang Mulia, saya mohon untuk didengarkan—",
  ui_story_1018_10180702_38_dialog_content = "Yang Mulia...",
  ui_story_1018_10180702_39_dialog_content = "Semuanya, panggil saja aku Hilda, ya.",
  ui_story_1018_10180702_40_dialog_content = "Aku telah mendengarkan semua doa-doa mu...",
  ui_story_1018_10180702_41_dialog_content = "Yang Mulia, tolong jangan tinggalkan kami lagi...",
  ui_story_1018_10180702_42_dialog_content = "...",
  ui_story_1018_10180702_43_dialog_content = "Tidak perlu menjawab semuanya, Yang Mulia.",
  ui_story_1018_10180702_44_dialog_content = "Tapi ini pertama kalinya aku bertemu Aurorian di luar Kuil...",
  ui_story_1018_10180702_45_dialog_content = "Kamu tidak perlu menjawab.",
  ui_story_1018_10180702_46_dialog_content = "Oke.",
  ui_story_1018_10180702_47_dialog_content = "Nyonya Suci telah menerima semua salam hormat dari Anda.",
  ui_story_1018_10180702_48_dialog_content = "Terima kasih, Carleen. Sebenarnya saya sangat senang!",
  ui_story_1018_10180702_49_dialog_content = "Hmm, siapa kamu? Kenapa kamu menatapku...?",
  ui_story_1018_10180702_50_dialog_content = "Apa ceritanya dengan tanduk di kepalamu?",
  ui_story_1018_10180702_51_dialog_content = "Jaga sikapmu—",
  ui_story_1018_10180702_52_dialog_content = "Tidak masalah!",
  ui_story_1018_10180702_53_dialog_content = "Sebenarnya ini adalah cerita yang berkaitan dengan <color=#FFB400>rhinocorn</color>...",
  ui_story_1018_10180702_54_dialog_content = "Kamu bicara tentang legenda Rhinohorn Guardian, kan? Aku sudah mendengar tentang itu sejak kecil. Begini ceritanya...",
  ui_story_1018_10180702_55_dialog_content = "<color=#e8d9bb>Setelah Joselyne merawat yang terluka...</color>",
  ui_story_1018_10180702_56_dialog_content = "Salam, Nona Santa! Saya, Joselyne, minta maaf atas keterlambatan saya.",
  ui_story_1018_10180702_57_dialog_content = "Halo, Joselyne. Ayah Joseph menyebutkan Anda padaku dan saya senang bisa membantu.",
  ui_story_1018_10180702_58_dialog_content = "Aku malu karena tidak bisa menyelamatkan Aurorian yang terluka oleh Eclipsite, dan berterima kasih karena kamu menyembuhkan mereka dengan aura-mu.",
  ui_story_1018_10180702_59_dialog_content = "Jangan merasa malu. Anda telah melakukan segala yang Anda bisa untuk menyelamatkan mereka, sebagai orang baik yang Anda.",
  ui_story_1018_10180702_60_dialog_content = "Kalau tidak keberatan, tolong panggil saja saya Hilda. Itu nama saya, dan ada banyak hal yang ingin saya tanyakan kepada Anda!",
  ui_story_1018_10180702_61_dialog_content = "Bagaimana bisa saya memanggil Anda dengan nama? Anda kan Lady Saintess!",
  ui_story_1018_10180702_62_dialog_content = "Joselyne, menurutku Lady Saintess sama hangat dan baik hati seperti para suster di sini di Twilight.",
  ui_story_1018_10180702_63_dialog_content = "Oh, dan aku belum menyelesaikan ceritanya, Chi! Pada akhirnya...",
  ui_story_1018_10180702_64_dialog_content = "...",
  ui_story_1018_10180702_65_dialog_content = "Apa yang kamu pikirkan, Lady Joselyne?",
  ui_story_1018_10180702_66_dialog_content = "Lady Carleen, aku tak pernah membayangkan bahwa...",
  ui_story_1018_10180702_67_dialog_content = "Nyonya Suci sebenarnya memiliki aura kepolosan seperti anak kecil.",
  ui_story_1018_10180702_68_dialog_content = "Sejujurnya, saat pertama kali bertemu dengannya, aku juga terkejut dengan... kepolosannya.",
  ui_story_1018_10180702_69_dialog_content = "Tapi kamu melihat bagaimana dia secara alami tertarik pada gadis-gadis seumuran Chi, dan betapa penasarannya dia dengan cerita-cerita yang beredar di sekitar Twilight.",
  ui_story_1018_10180702_70_dialog_content = "Mungkin dia masih mencari jalannya untuk melampaui menjadi Lady Saintess.",
  ui_story_1018_10180702_71_dialog_content = "Anda benar, saya berpikiran sempit.",
  ui_story_1018_10180702_72_dialog_content = "Bukankah kamu berencana untuk tinggal setelah menyerahkan yang terluka kepada Gereja?",
  ui_story_1018_10180702_73_dialog_content = "Pertempuran di Twilight belum berakhir. Saya harus kembali dan berjuang bersama para pejuang.",
  ui_story_1018_10180702_74_dialog_content = "Saya merasa tenang mengetahui Ayah Joseph di sini.",
  ui_story_1018_10180702_75_dialog_content = "Oke, aku akan memimpin bala bantuan Lumopolis dan pergi bersamamu.",
  ui_story_1018_10180702_76_dialog_content = "Aku juga ikut! Kita masih bisa melakukannya, kan?",
  ui_story_1018_10180702_77_dialog_content = "Ya, Yang Mulia.",
  ui_story_1018_10180702_78_dialog_content = "Dengan Lady Saintess bersama kita, Twilight pasti akan diselamatkan. Ayo pergi!",
  ui_story_1018_10180801_1_dialog_content = "<color=#e8d9bb>Di Luar Senja</color>",
  ui_story_1018_10180801_2_dialog_content = "(Eclipsian) Tuan, saya kurang mengerti mengapa Anda memilih untuk menyembuhkannya.",
  ui_story_1018_10180801_3_dialog_content = "(Eclipsian) Dia seharusnya bergabung dengan kita, seperti para prajurit itu.",
  ui_story_1018_10180801_4_dialog_content = "Dia selamat setelah didorong ke ambang batas. Saya terkejut dengan hasil eksperimen yang satu ini.",
  ui_story_1018_10180801_5_dialog_content = "Jika aku bisa mengerti mengapa benih di dalam dirinya begitu istimewa, perjalanan ini tidak akan sia-sia.",
  ui_story_1018_10180801_6_dialog_content = "(Eclipsian) Tuan, sudah lama sekali sejak terakhir kali saya merasakan menggertakkan gigi dengan enak.",
  ui_story_1018_10180801_7_dialog_content = "Mudbundle hampir sepenuhnya pulih. Bersiaplah untuk menaruh lebih banyak karpet.",
  ui_story_1018_10180801_8_dialog_content = "(Dalam bahasa Eclipsian) Haruskah kita terus mendorong maju?",
  ui_story_1018_10180801_9_dialog_content = "Itu benar, tetapi kali ini, berkeliling Twilight.",
  ui_story_1018_10180801_10_dialog_content = "Kita akan mengubah semua prajurit Ulysses menjadi Eclipsite begitu kita menguasai Illumina.",
  ui_story_1018_10180801_11_dialog_content = "(Eclipsian) Apa rencana untuk para prajurit ini, Tuan?",
  ui_story_1018_10180801_12_dialog_content = "Minta Mudbundle untuk memindahkan mereka ke garis pertahanan, dan jangan lupa tentang \"karya seni\" itu.",
  ui_story_1018_10180801_13_dialog_content = "Tapi sebelum aku pergi, aku ingin melihat apakah dia suka dengan hadiah yang aku punya untuknya.",
  ui_story_1018_10180801_14_dialog_content = "Kapten Axelia, Grand Marshal! Kami telah menemukan Skuadron Kesembilan...",
  ui_story_1018_10180801_15_dialog_content = "Mereka... ternyata berbaring di lumpur dekat penghalang sepanjang waktu.",
  ui_story_1018_10180801_16_dialog_content = "Kami berhasil melihat mereka ketika lumpur surut... tapi mereka sudah...",
  ui_story_1018_10180801_17_dialog_content = "...",
  ui_story_1018_10180801_18_dialog_content = "Bawa saya ke sana.",
  ui_story_1018_10180801_19_dialog_content = "Kecuali awak tank, semua prajurit dari Skuadron Kesembilan sudah ada di sini.",
  ui_story_1018_10180801_20_dialog_content = "Sisanya dari mereka semua telah melakukan pengorbanan tertinggi, termasuk... pengemudi dari Engine VII.",
  ui_story_1018_10180801_21_dialog_content = "Mengapa prajurit itu mati seperti ini...",
  ui_story_1018_10180801_22_dialog_content = "Ada luka tembakan di bawah dagunya dan jarinya masih kuat menekan pelatuk. Jelas, dia mengakhiri hidupnya sendiri sebelum kehilangan kendali...",
  ui_story_1018_10180801_23_dialog_content = "...",
  ui_story_1018_10180801_24_dialog_content = "Ini hanya prajurit biasa, bukan?",
  ui_story_1018_10180801_25_dialog_content = "Ya, mereka memang...",
  ui_story_1018_10180801_26_dialog_content = "Mereka saling menopang, mungkin mencoba untuk melawan Mire?",
  ui_story_1018_10180801_27_dialog_content = "Ini sangat kejam... Hampir tak ada daging yang tersisa, sebagian besar hanya tulang...",
  ui_story_1018_10180801_28_dialog_content = "Mengorbankan diri seperti ini... Mereka sangat gagah berani.",
  ui_story_1018_10180801_29_dialog_content = "Saya minta maaf atas penilaian spontan yang telah saya buat.",
  ui_story_1018_10180801_30_dialog_content = "...",
  ui_story_1018_10180801_31_dialog_content = "Wrath...",
  ui_story_1018_10180801_32_dialog_content = "Ini adalah sesuatu yang belum pernah saya lihat dalam bertahun-tahun di garnisun.",
  ui_story_1018_10180801_33_dialog_content = "Apakah ada yang bisa kita lakukan?",
  ui_story_1018_10180801_34_dialog_content = "Terus periksa sekeliling dan temukan semua yang terluka.",
  ui_story_1018_10180801_35_dialog_content = "<color=#e8d9bb>Glup, glup...</color>",
  ui_story_1018_10180801_36_dialog_content = "Kapten! Ada sesuatu yang bergerak di lumpur di belakang para prajurit!",
  ui_story_1018_10180801_37_dialog_content = "Jadi ini adalah daya tarik utama Twilight?",
  ui_story_1018_10180801_38_dialog_content = "Ternyata ini adalah \"karya seni\" yang asli.",
  ui_story_1018_10180801_39_dialog_content = "Forsakin?",
  ui_story_1018_10180801_40_dialog_content = "Kamu yang di balik semua ini?",
  ui_story_1018_10180801_41_dialog_content = "Saya di sini hanya untuk menyapa Grand Marshal. Apakah Anda menikmati waktu bertarung?",
  ui_story_1018_10180801_42_dialog_content = "Untuk... sakin...!",
  ui_story_1018_10180801_43_dialog_content = "Santai. Kamu nggak bisa serius dalam kondisi seperti ini.",
  ui_story_1018_10180801_44_dialog_content = "Kamu tidak akan menyakiti Grand Marshal Wrath!",
  ui_story_1018_10180801_45_dialog_content = "Kamu lagi? Aku tahu seharusnya aku tidak bermain setengah-setengah padamu, bodoh.",
  ui_story_1018_10180801_46_dialog_content = "Aku akan membuatmu membayar dua kali lipat untuk apa yang telah kau lakukan pada prajurit-prajuritku!",
  ui_story_1018_10180801_47_dialog_content = "Apa yang telah saya lakukan? Membunuh mereka semua pun tidak akan cukup untuk menebus semua kerugian yang telah saya alami.",
  ui_story_1018_10180801_48_dialog_content = "Kamu mungkin tidak tahu bagaimana kamu bisa sampai pada saat ini. Apa yang telah Illumina lakukan padamu bisa membunuhmu ribuan kali lipat.",
  ui_story_1018_10180801_49_dialog_content = "Tidakkah kamu ingin tahu mengapa kamu telah berjuang keras, namun Illumina sama sekali tidak peduli?",
  ui_story_1018_10180801_50_dialog_content = "Diam, si nenek tak bermartabat!",
  ui_story_1018_10180801_51_dialog_content = "Hmm, sepertinya kamu punya firasat juga. Apakah mereka tahu bahwa membunuh prajuritnya sendiri adalah motif Grand Marshal yang baru?",
  ui_story_1018_10180801_52_dialog_content = "Kau meminta ini, Forsakin!",
  ui_story_1018_10180801_53_dialog_content = "Tenanglah, Wrath! Dia sengaja mencoba membuatmu marah.",
  ui_story_1018_10180801_54_dialog_content = "...",
  ui_story_1018_10180801_55_dialog_content = "Aku tahu kamu di balik semua yang terjadi di Twilight, dan aku tidak akan membiarkanmu lolos begitu saja!",
  ui_story_1018_10180801_56_dialog_content = "Saya tidak menyangkal itu, dan saya senang melakukannya untuk menghukum pencurian.",
  ui_story_1018_10180801_57_dialog_content = "Karena kalian semua telah melihat karya seni tersebut, kita akan beralih ke pertunjukan yang sesungguhnya. Jaga mata kalian tetap terbuka sekarang!",
  ui_story_1018_10180801_58_dialog_content = "Sedang apa kau?",
  ui_story_1018_10180801_59_dialog_content = "Hmm, apakah kamu menantangku dengan berdiri di depannya seperti ini?",
  ui_story_1018_10180801_60_dialog_content = "Dan Axelia juga.",
  ui_story_1018_10180801_61_dialog_content = "Ya, aku ikut!",
  ui_story_1018_10180801_62_dialog_content = "Biarlah. Aku sudah cukup terhibur. Bukan aku yang kau lawan...",
  ui_story_1018_10180801_63_dialog_content = "Aum...",
  ui_story_1018_10180801_64_dialog_content = "Itu suara pilot mecha... Tapi dia 'kan sudah mati?",
  ui_story_1018_10180801_65_dialog_content = "Aum...",
  ui_story_1018_10180801_66_dialog_content = "Kalian sudah pernah mengorbankan diri sekali...",
  ui_story_1018_10180801_67_dialog_content = "Aku tak bisa... membiarkanmu...",
  ui_story_1018_10180801_68_dialog_content = "Axelia merasakan kemarahanmu, Grand Marshal...",
  ui_story_1018_10180801_69_dialog_content = "Apa ini...",
  ui_story_1018_10180801_70_dialog_content = "Axelia ingin melindungi Grand Marshal, dan meskipun Axelia tidak dapat merasakan kehangatan tubuh...",
  ui_story_1018_10180801_71_dialog_content = "Yingel mengatakan bahwa di sinilah letak hati Axelia.",
  ui_story_1018_10180801_72_dialog_content = "Saya rasa lebih panas daripada kekuatan di dalam diri kita.",
  ui_story_1018_10180801_73_dialog_content = "Axelia...",
  ui_story_1018_10180801_74_dialog_content = "Jangan khawatir, aku tak akan membiarkannya mengendalikan diriku.",
  ui_story_1018_10180801_75_dialog_content = "Kapten... seluruh skuadron sedang menuju ke arah kita! Apa yang harus kita lakukan sekarang?",
  ui_story_1018_10180801_76_dialog_content = "Lumpur... tidak, Aliran Gelap, itu meresap keluar dari tubuh mereka! Aku bisa melihat itu! Ada kilau seram di mata para prajurit!",
  ui_story_1018_10180801_77_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_1018_10180801_78_dialog_content = "Tombak petir, tusuk!",
  ui_story_1018_10180801_79_dialog_content = "Roh mereka telah lama pergi. Hanya akan mencoreng warisan mereka jika mereka terus berjuang.",
  ui_story_1018_10180801_80_dialog_content = "Semua orang, dengarkan! Jangan biarkan prajurit kita menderita lagi. Mereka melindungi kita dan tidak seharusnya mengorbankan diri sia-sia!",
  ui_story_1018_10180801_81_dialog_content = "Baik, Grand Marshal.",
  ui_story_1018_10180801_82_dialog_content = "Nah, tanpa belas kasihan. Lalu kau tidak keberatan jika aku membawa sisanya bersamaku...",
  ui_story_1018_10180801_83_dialog_content = "Jangan coba-coba lari!",
  ui_story_1018_10180801_84_dialog_content = "Bukankah para prajurit itu masuk ke dalam lumpur...",
  ui_story_1018_10180801_85_dialog_content = "Mereka adalah bawahan dari Axelia.",
  ui_story_1018_10180801_86_dialog_content = "Axelia akan memimpin Regu Delapan!",
  ui_story_1018_10180801_87_dialog_content = "Axelia akan baik-baik saja, kan...?",
  ui_story_1018_10180801_88_dialog_content = "Prajurit yang menyerbu bersamanya telah setia, jadi seharusnya tidak menjadi masalah.",
  ui_story_1018_10180801_89_dialog_content = "Ayo kita lanjut setelah selesai di sini!",
  ui_story_1018_10180801_90_dialog_content = "Tentu!",
  ui_story_1018_10180802_1_dialog_content = "Masih mengejarku dalam kondisimu ini?",
  ui_story_1018_10180802_2_dialog_content = "Axelia... harus melindungi mereka... tolong kembalikan mereka padaku.",
  ui_story_1018_10180802_3_dialog_content = "Kalau begitu, sepertinya kamu harus mencari cara untuk membunuhku.",
  ui_story_1018_10180802_4_dialog_content = "Axelia... akan membawa Skuad Delapan kembali ke rumah!",
  ui_story_1018_10180802_5_dialog_content = "Inilah yang seharusnya terlihat saat membunuh!",
  ui_story_1018_10180802_6_dialog_content = "Tidak...",
  ui_story_1018_10180802_7_dialog_content = "Kapten Axelia, apakah kamu... baik-baik saja?",
  ui_story_1018_10180802_8_dialog_content = "...",
  ui_story_1018_10180802_9_dialog_content = "Apakah itu kesedihan yang kulihat di wajah ciptaan Ulysses yang tak beremosi?",
  ui_story_1018_10180802_10_dialog_content = "Axelia... tidak tidak memiliki emosi.",
  ui_story_1018_10180802_11_dialog_content = "Masih tidak mau mengaku?",
  ui_story_1018_10180802_12_dialog_content = "Jangan sakiti mereka... Mereka sedang menderita...",
  ui_story_1018_10180802_13_dialog_content = "Apakah mereka terlihat bisa mendengar kata-katamu?",
  ui_story_1018_10180802_14_dialog_content = "Axelia tidak akan membiarkan kamu lolos begitu saja...",
  ui_story_1018_10180802_15_dialog_content = "Selain melihat aku memeras nyawa mereka, apa lagi yang bisa kamu lakukan?",
  ui_story_1018_10180802_16_dialog_content = "(Eclipsian) Tuanku, Mudbundle sudah siap dan siaga.",
  ui_story_1018_10180802_17_dialog_content = "Baiklah, karena kamu memohon, aku akan meninggalkan beberapa untukmu. Tapi sisanya...",
  ui_story_1018_10180802_18_dialog_content = "Kapten Axelia, semua orang... mereka menghilang ke dalam rawa...",
  ui_story_1018_10180802_19_dialog_content = "Kembalikan... mereka padaku...",
  ui_story_1018_10180802_20_dialog_content = "Astaga!",
  ui_story_1018_10180802_21_dialog_content = "Kapten Axelia, hati-hati!",
  ui_story_1018_10180802_22_dialog_content = "Astaga!",
  ui_story_1018_10180802_23_dialog_content = "Hentikan...",
  ui_story_1018_10180802_24_dialog_content = "Tolong! Kapten Axelia!",
  ui_story_1018_10180802_25_dialog_content = "Astaga!",
  ui_story_1018_10180802_26_dialog_content = "Aduh...",
  ui_story_1018_10180802_27_dialog_content = "Kamu bukan mesin perang... Tolong jangan membunuh mereka...",
  ui_story_1018_10180802_28_dialog_content = "Astaga!",
  ui_story_1018_10180802_29_dialog_content = "Arghhhh—!",
  ui_story_1018_10180802_30_dialog_content = "...",
  ui_story_1018_10180802_31_dialog_content = "(Terpekiknya... angin, suara senjata... Semua hening sekarang...)",
  ui_story_1018_10180802_32_dialog_content = "(Apakah dia... mati?)",
  ui_story_1018_10180802_33_dialog_content = "(Atau mungkin... Axelia sudah mati...)",
  ui_story_1018_10180802_34_dialog_content = "(...)",
  ui_story_1018_10180802_35_dialog_content = "Kapten Axelia, tolong selamatkan saya!",
  ui_story_1018_10180802_36_dialog_content = "(Aku merasa sangat berat... tidak bisa bergerak...)",
  ui_story_1018_10180802_37_dialog_content = "(Cepat... harus menyelamatkannya!)",
  ui_story_1018_10180802_38_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_1018_10180802_39_dialog_content = "(Tubuhnya terhantam keras ke tanah...)",
  ui_story_1018_10180802_40_dialog_content = "(Rasanya seperti tubuh Axelia telah dihempaskan ke tanah...)",
  ui_story_1018_10180802_41_dialog_content = "<color=#e8d9bb>Roooaaarrr!!!</color>",
  ui_story_1018_10180802_42_dialog_content = "(Dia mencabik dada prajurit itu dan mulai menyantapnya...)",
  ui_story_1018_10180802_43_dialog_content = "(Prajurit itu terjatuh dalam genangan darahnya sendiri...)",
  ui_story_1018_10180802_44_dialog_content = "(Tapi Axelia rasanya... seolah-olah diriku sendiri yang jatuh di sana...)",
  ui_story_1018_10180802_45_dialog_content = "<color=#e8d9bb>Dentang! Dentang!</color>",
  ui_story_1018_10180802_46_dialog_content = "(Lima kali, enam kali...)",
  ui_story_1018_10180802_47_dialog_content = "(Axelia telah jatuh enam kali...)",
  ui_story_1018_10180802_48_dialog_content = "(Ke-sepuluh kali...)",
  ui_story_1018_10180802_49_dialog_content = "(Ke-23 kali, ke-24 kali...)",
  ui_story_1018_10180802_50_dialog_content = "(Seratus dua kali...)",
  ui_story_1018_10180802_51_dialog_content = "(Dua ribu kali...)",
  ui_story_1018_10180802_52_dialog_content = "(...)",
  ui_story_1018_10180802_53_dialog_content = "Sebelas ribu, seratus sebelas kali...",
  ui_story_1018_10180802_54_dialog_content = "(Axelia masih kalah...)",
  ui_story_1018_10180802_55_dialog_content = "(Ayah mengatakan Axelia adalah mesin perang yang sangat baik, dan mesin perang tidak pernah menyerah.)",
  ui_story_1018_10180802_56_dialog_content = "(Tapi Axelia terus saja dikalahkan...)",
  ui_story_1018_10180802_57_dialog_content = "(Axelia sama sekali tidak tahu cara menghentikan ini.)",
  ui_story_1018_10180802_58_dialog_content = "Axelia!",
  ui_story_1018_10180802_59_dialog_content = "(Ayah? Mohon maafkan Axelia...)",
  ui_story_1018_10180802_60_dialog_content = "Ingat, Axelia, kamu harus hidup sebagai seorang manusia!",
  ui_story_1018_10180802_61_dialog_content = "(Hidup... Tapi apa yang bisa Axelia lakukan...?)",
  ui_story_1018_10180802_62_dialog_content = "(Mungkin Axelia bisa...)",
  ui_story_1018_10180802_63_dialog_content = "Aum...",
  ui_story_1018_10180802_64_dialog_content = "Astaga!",
  ui_story_1018_10180802_65_dialog_content = "Guntur menggelegar!",
  ui_story_1018_10180802_66_dialog_content = "Bangun, Axelia! Dengar suaraku!",
  ui_story_1018_10180802_67_dialog_content = "Kamu tidak bisa maju lebih jauh lagi, Wrath!",
  ui_story_1018_10180802_68_dialog_content = "Aum...",
  ui_story_1018_10180802_69_dialog_content = "Bahkan Axelia akan...",
  ui_story_1018_10180802_70_dialog_content = "<color=#e8d9bb>Hai—</color>",
  ui_story_1018_10180802_71_dialog_content = "Suara itu...",
  ui_story_1018_10180802_72_dialog_content = "Cahayanya terang sekali...",
  ui_story_1018_10180802_73_dialog_content = "Grand Marshal, Leo, maaf telah datang terlambat!",
  ui_story_1018_10180802_74_dialog_content = "Saya, Joselyne, dalam Aura dari Lady Saintess, akan menebus Aurorian kembali dalam anugerah Tuhan!",
  ui_story_1018_10180802_75_dialog_content = "Eclipsite jahat tak akan pernah menyakitimu lagi!",
  ui_story_1018_10180802_76_dialog_content = "Kapten! Ini Joselyne! Dan... Lady Carleen serta Skyriders Lumopolis!",
  ui_story_1018_10180802_77_dialog_content = "Apakah gadis yang berdiri di bawah cahaya itu adalah orang yang kupikir...?",
  ui_story_1018_10180802_78_dialog_content = "Saya sudah mendengarkan, tapi belum waktunya mereka kembali.",
  ui_story_1018_10180802_79_dialog_content = "Semua kehidupan itu berharga. Kamu akan dibersihkan dari kejahatan oleh anugerah Tuhan.",
  ui_story_1018_10180802_80_dialog_content = "Mandi dalam cahaya suci, dengarkan doa-doa, dan terimalah berkat ilahi.",
  ui_story_1018_10180802_81_dialog_content = "Biarkan kekuatan mengalir untuk menyembuhkan luka dan membasmi pikiran jahat.",
  ui_story_1018_10180802_82_dialog_content = "May Tuhan Cahaya Abadi selalu bersama Aurorian.",
  ui_story_1018_10180802_83_dialog_content = "Kapten, lihat prajurit itu! Mereka bersinar dengan cahaya emas!",
  ui_story_1018_10180802_84_dialog_content = "Ya, Joselyne berhasil membawa Lady Saintess bersamanya...",
  ui_story_1018_10180802_85_dialog_content = "Apakah dia menyembuhkan prajurit-prajurit yang terkorupsi?",
  ui_story_1018_10180802_86_dialog_content = "Ya. Konon dia tidak hanya bisa memutuskan pengaruh Darkflow, bahkan sekadar melihat aura suci tersebut bisa menyembuhkan Aurorian biasa.",
  ui_story_1018_10180802_87_dialog_content = "Benar...",
  ui_story_1018_10180802_88_dialog_content = "Aku merasakan kekuatan tertentu di tubuhku yang menyebar untuk memberikan kelegaan yang besar...",
  ui_story_1018_10180802_89_dialog_content = "Dan juga, para prajurit yang berubah menjadi Eclipsite telah menghentikan serangan mereka...",
  ui_story_1018_10180802_90_dialog_content = "Aku merasakan kesakitanmu. Yang kamu butuhkan sekarang adalah beristirahat dengan tenang untuk pulih.",
  ui_story_1018_10180802_91_dialog_content = "Demi White Night!",
  ui_story_1018_10180802_92_dialog_content = "Maaf, kami terlambat!",
  ui_story_1018_10180802_93_dialog_content = "Halo...",
  ui_story_1018_10180802_94_dialog_content = "Semua orang, ini adalah Lady Saintess dari Lumopolis Temple.",
  ui_story_1018_10180802_95_dialog_content = "Kuil Lumopolis? Ada apa di sini?",
  ui_story_1018_10180802_96_dialog_content = "Grand Marshal Wrath, Lady Saintess di sini untuk membantu menyembuhkan prajurit yang terluka.",
  ui_story_1018_10180802_97_dialog_content = "Mereka yang mengikutiku ke Benteng Lumo kini stabil, berkat bantuannya.",
  ui_story_1018_10180802_98_dialog_content = "Apakah Yang Mulia Sang Suci memiliki kekuatan ilahi...?",
  ui_story_1018_10180802_99_dialog_content = "Tidak. Aku seorang Aurorian yang tak berbeda denganmu, Grand Marshal.",
  ui_story_1018_10180802_100_dialog_content = "Tapi, bagaimana mungkin aku hanya tidak merasa...",
  ui_story_1018_10180802_101_dialog_content = "Saya merasa sedih mendengar apa yang terjadi pada Anda dan prajurit Anda, jadi saya merawat mereka tanpa persetujuan Anda. Saya harap Anda bisa memaafkan saya.",
  ui_story_1018_10180802_102_dialog_content = "Tidak, seharusnya aku yang berterima kasih padamu.",
  ui_story_1018_10180802_103_dialog_content = "Mengapa kau datang, bolehkah saya tanya?",
  ui_story_1018_10180802_104_dialog_content = "Aku telah mendengar bisikan Aurorian dalam mimpi buruk mereka. Aku bisa merasakan rasa sakit dan penderitaan.",
  ui_story_1018_10180802_105_dialog_content = "Kamu juga terganggu oleh itu dan aku mendengarmu.",
  ui_story_1018_10180802_106_dialog_content = "...",
  ui_story_1018_10180802_107_dialog_content = "Oh, maaf, ini bukan waktunya bagi saya untuk mengoceh.",
  ui_story_1018_10180802_108_dialog_content = "Tolong periksa prajurit Anda, Grand Marshal. Mereka seharusnya sudah keluar dari bahaya sekarang.",
  ui_story_1018_10180802_109_dialog_content = "Ya. Sekali lagi, terima kasih banyak.",
  ui_story_1018_10180802_110_dialog_content = "Sungguh, Nyonya Suci ini benar-benar luar biasa...",
  ui_story_1018_10180802_111_dialog_content = "Aku dengar itu.",
  ui_story_1018_10180802_112_dialog_content = "Apa? Tapi itu hampir-hampir seperti bisikan saja!",
  ui_story_1018_10180802_113_dialog_content = "Kamu tidak seperti yang lainnya.",
  ui_story_1018_10180802_114_dialog_content = "Ini adalah Caelestite, Lady Saintess.",
  ui_story_1018_10180802_115_dialog_content = "Salam, Lady Saintess. Saya PlayerName.",
  ui_story_1018_10180802_116_dialog_content = "Senang bertemu dengan Anda, PlayerName. Tolong, panggil saja aku Hilda.",
  ui_story_1018_10180802_117_dialog_content = "Hilda...",
  ui_story_1018_10180802_118_dialog_content = "Aku pernah membaca sebuah buku cerita dan tokoh utamanya juga bernama Hilda.",
  ui_story_1018_10180802_119_dialog_content = "Benarkah? Seperti apa Hilda itu?",
  ui_story_1018_10180802_120_dialog_content = "Sebenarnya, Hilda itu adalah hewan...",
  ui_story_1018_10180802_121_dialog_content = "Berani-beraninya kau memanggil Sang Suci Perempuan...!",
  ui_story_1018_10180802_122_dialog_content = "Tidak, maksudku yang di buku itu! Hilda suka menanam bunga...",
  ui_story_1018_10180802_123_dialog_content = "Hee... Hewan yang suka menanam bunga? Apakah itu sedikit moe atau sedikit fox?",
  ui_story_1018_10180802_124_dialog_content = "Apakah itu memiliki tanduk? Sayap? Apakah itu mengunjungi banyak tempat...?",
  ui_story_1018_10180802_125_dialog_content = "Kapten, apakah dia \"Santo Perempuan\" dari Gereja Lumopolis?",
  ui_story_1018_10180802_126_dialog_content = "Ya.",
  ui_story_1018_10180901_1_dialog_content = "<color=#e8d9bb>Kota Gannon</color>",
  ui_story_1018_10180901_2_dialog_content = "Yah... bagaimana kalau kita menyajikan berita seperti ini:",
  ui_story_1018_10180901_3_dialog_content = "Karena laporan pertempuran yang tidak menguntungkan dari Twilight, keluarga para prajurit yang akan segera diterjunkan kesulitan menghadapi pemisahan yang akan datang...",
  ui_story_1018_10180901_4_dialog_content = "Hei, bagaimana kalau menggunakan nada yang sedikit lebih optimistis? Kita tidak ingin membuatnya terlihat seperti kita sedang kalah dalam perang...",
  ui_story_1018_10180901_5_dialog_content = "Bukankah itu kebenarannya? Twilight tidak pernah sekalipun mengirimkan kabar baik. Jika keadaan terus seperti ini, kita akan kehabisan berita untuk dilaporkan...",
  ui_story_1018_10180901_6_dialog_content = "Jenderal Hiiro, bagaimana bisa kali ini kita tidak memperkuat Twilight, tetapi garis pertahanan?",
  ui_story_1018_10180901_7_dialog_content = "Karena itulah perintah yang diberikan kepada kami.",
  ui_story_1018_10180901_8_dialog_content = "Tapi pertempuran di Twilight sangat samar-samar...",
  ui_story_1018_10180901_9_dialog_content = "Alihkan kekhawatiran Anda menjadi semangat untuk menyelesaikan krisis yang akan datang.",
  ui_story_1018_10180901_10_dialog_content = "Ya…",
  ui_story_1018_10180901_11_dialog_content = "Jenderal, pasukan sudah siap.",
  ui_story_1018_10180901_12_dialog_content = "Bagaimana dengan senapan yang dikirim oleh Chief of Staff?",
  ui_story_1018_10180901_13_dialog_content = "Dalam posisi!",
  ui_story_1018_10180901_14_dialog_content = "Ayo.",
  ui_story_1018_10180901_15_dialog_content = "Ya!",
  ui_story_1018_10180901_16_dialog_content = "Legiun ke-3 telah berangkat! Kami yakin bahwa pertempuran di Twilight dapat membawa dampak positif—",
  ui_story_1018_10180901_17_dialog_content = "Hmm? Sepertinya communicator ini menangkap sinyal yang aneh?",
  ui_story_1018_10180901_18_dialog_content = "Aku juga memperhatikannya!",
  ui_story_1018_10180901_19_dialog_content = "Apakah ini lelucon atau...? Mari kita lihat apakah kita bisa membuatnya lebih jelas...",
  ui_story_1018_10180901_20_dialog_content = "Program Phospherus adalah skema yang dirancang oleh Ulysses dan Forsakin Eclipse...",
  ui_story_1018_10180901_21_dialog_content = "Apa ini...",
  ui_story_1018_10180901_22_dialog_content = "Kamu yang mengirim sinyal itu, kan?",
  ui_story_1018_10180901_23_dialog_content = "Kenapa bisa begitu?",
  ui_story_1018_10180901_24_dialog_content = "Izinkan saya menguraikannya.",
  ui_story_1018_10180901_25_dialog_content = "Kamu mulai sebagai informan Esien, ditempatkan di samping Grand Marshal untuk mengamati setiap gerak-geriknya.",
  ui_story_1018_10180901_26_dialog_content = "Kemudian, Anda dipaksa untuk membantu Ulysses mengatur operasi \"bendera palsu\" dalam latihan bersama.",
  ui_story_1018_10180901_27_dialog_content = "Selanjutnya, dalam persidangan Reinhardt, Anda akhirnya menyadari bahwa Anda hanyalah pion dalam pertarungan politik...",
  ui_story_1018_10180901_28_dialog_content = "Jadi kamu menebusnya dengan mengabaikan apa yang kami lakukan dan bahkan membantu kami secara diam-diam.",
  ui_story_1018_10180901_29_dialog_content = "Saya hanya tidak menyangka seorang perwira intelijen tahu banyak tentang komunikasi. Apakah atasan Anda tidak keberatan dengan ini?",
  ui_story_1018_10180901_30_dialog_content = "Petugas intel mengumpulkan info dan juga membocorkannya pada saat yang tepat. Saya benar-benar melakukan ini sendiri. Ini tidak ada hubungannya dengan orang lain.",
  ui_story_1018_10180901_31_dialog_content = "Saya melihat kamu serius.",
  ui_story_1018_10180901_32_dialog_content = "Melakukan apa yang Anda ajarkan adalah cara saya menilai orang. Intel Anda akurat dan sikap Anda tegas.",
  ui_story_1018_10180901_33_dialog_content = "Itu berarti sekarang aku percaya semua yang kau katakan padaku di penjara.",
  ui_story_1018_10180901_34_dialog_content = "<color=#e8d9bb>Tidak lama yang lalu, Vivian mengunjungi Penjara Illumina untuk ketiga kalinya...</color>",
  ui_story_1018_10180901_35_dialog_content = "Fakta bahwa kita berhasil masuk ke penjara keamanan tinggi berarti intel dari Anatoli sempurna.",
  ui_story_1018_10180901_36_dialog_content = "Petugas Vivian, mengingat betapa pentingnya operasi ini, mengapa Anda mempercayai intel dari seorang pria yang dikenal karena melakukan sumpah palsu?",
  ui_story_1018_10180901_37_dialog_content = "Perasaan dalam.",
  ui_story_1018_10180901_38_dialog_content = "Wrath memang berpikir Anatoli memiliki alasan yang tidak diketahui untuk melakukan sumpah palsu, dan cara dia terus ikut campur dengan tujuan kita menunjukkan bahwa dia ragu-ragu.",
  ui_story_1018_10180901_39_dialog_content = "Dia pasti telah membuat keputusan untuk membantu kita kali ini.",
  ui_story_1018_10180901_40_dialog_content = "Nah... apakah penjaga patroli yang muncul tiba-tiba ini yang disebut \"tangan penolong\"?",
  ui_story_1018_10180901_41_dialog_content = "...",
  ui_story_1018_10180901_42_dialog_content = "Kepala Staf Vivian, siapa pun yang mencoba masuk ke penjara keamanan tinggi ini harus menunjukkan kredensial yang relevan.",
  ui_story_1018_10180901_43_dialog_content = "Cek saja dengan atasan Anda untuk itu. Saya tidak mendapatkan apa-apa dari bos saya.",
  ui_story_1018_10180901_44_dialog_content = "Atasan langsung Anda, Reinhardt, saat ini sedang ditahan di dalam tembok ini. Saya menyarankan Anda dan tim Anda untuk berpikir dua kali sebelum melanjutkan.",
  ui_story_1018_10180901_45_dialog_content = "Kepala, sepertinya intuisi Anda tentang petugas intelijen tidak sepenuhnya akurat.",
  ui_story_1018_10180901_46_dialog_content = "Dia akan menjadi orang pertama yang aku salah.",
  ui_story_1018_10180901_47_dialog_content = "Tetapi tetap ikuti rencana. Bagaimanapun juga, kita harus membebaskan Grand Marshal sebelum Hiiro mengirim pasukan.",
  ui_story_1018_10180901_48_dialog_content = "Ini adalah kesempatan terakhir bagi kita, jadi bersiaplah untuk bertarung!",
  ui_story_1018_10180901_49_dialog_content = "Tentu saja! untuk Marsekal Agung!",
  ui_story_1018_10180901_50_dialog_content = "Chief of Staff, apakah Anda berencana untuk menerobos masuk? Jika begitu, kita...",
  ui_story_1018_10180901_51_dialog_content = "Aduh, aduh, aduh...",
  ui_story_1018_10180901_52_dialog_content = "... Kami bahkan belum menyentuhmu sama sekali.",
  ui_story_1018_10180901_53_dialog_content = "Aku akan menangani ini.",
  ui_story_1018_10180901_54_dialog_content = "Ya, petugas!",
  ui_story_1018_10180901_55_dialog_content = "... Anatoli, apa yang terjadi? Kamu mempermainkan kami, bukan!",
  ui_story_1018_10180901_56_dialog_content = "Maaf, aku harus menghilangkan keraguan ini dengan cara ini.",
  ui_story_1018_10180901_57_dialog_content = "Apa keraguannya?",
  ui_story_1018_10180901_58_dialog_content = "Jalan mana yang kamu pilih terkait masa depan Illumina, dan sejauh mana kamu bersedia melangkah?",
  ui_story_1018_10180901_59_dialog_content = "Apa kesimpulanmu?",
  ui_story_1018_10180901_60_dialog_content = "Dari pengamatan yang panjang, Grand Marshal adalah pemimpin yang dapat diandalkan.",
  ui_story_1018_10180901_61_dialog_content = "Sebagai seorang perwira intelijen, meragukan segala sesuatu adalah naluri dasar, itulah mengapa saya membenci keyakinan buta.",
  ui_story_1018_10180901_62_dialog_content = "Tapi, pernah ada seseorang yang memberikan kepercayaan tanpa syarat padaku, dan aku melihat hal yang sama darimu.",
  ui_story_1018_10180901_63_dialog_content = "Inilah masa depan yang saya rindukan, jadi saya memilih untuk berdiri bersama Anda.",
  ui_story_1018_10180901_64_dialog_content = "Heh, maafkan saya karena tidak mempercayai siapa pun yang mengkhianati marsekal, meskipun saya sangat menikmati pidato Anda.",
  ui_story_1018_10180901_65_dialog_content = "Akan ada banyak kesempatan untuk kamu mengenal aku. Petugas patroli bekerja untukku, jadi kalian harus segera berangkat.",
  ui_story_1018_10180901_66_dialog_content = "Selamat bergabung di tim, kawan yang pemberani!",
  ui_story_1018_10180901_67_dialog_content = "Aku akan melewatkan operasi high-profile, terima kasih. Aku lebih terbiasa berada di balik layar.",
  ui_story_1018_10180901_68_dialog_content = "Jika Anda berhasil, saya punya beberapa chip yang bisa berguna.",
  ui_story_1018_10180901_69_dialog_content = "Baiklah, kita sepakat.",
  ui_story_1018_10180901_70_dialog_content = "<color=#e8d9bb>Buzz ... Buzz ...</color>",
  ui_story_1018_10180901_71_dialog_content = "Mengapa semua perangkat membuat suara itu?",
  ui_story_1018_10180901_72_dialog_content = "<color=#e8d9bb>Bip—</color>",
  ui_story_1018_10180901_73_dialog_content = "Ini aneh sekali... Apakah komunikatornya rusak? Sinyal tiba-tiba saja jadi kacau.",
  ui_story_1018_10180901_74_dialog_content = "Sama disini...",
  ui_story_1018_10180901_75_dialog_content = "Apa yang sedang... terjadi di dunia ini?",
  ui_story_1018_10180901_76_dialog_content = "Tampaknya Komite telah membuat langkah...",
  ui_story_1018_10180901_77_dialog_content = "Kepala Staf, kita kehilangan kontak dengan unit garis depan tepat ketika gangguan komunikasi terjadi.",
  ui_story_1018_10180901_78_dialog_content = "Aku tidak percaya mereka membungkuk sampai selevel ini...",
  ui_story_1018_10180901_79_dialog_content = "Federasi tidak pernah memutus komunikasi dengan pasukan pertahanan saat mereka mengacaukan sinyal di masa lalu.",
  ui_story_1018_10180901_80_dialog_content = "Kita kehabisan waktu. Hati-hati di belakangmu, Anatoli.",
  ui_story_1018_10180901_81_dialog_content = "...",
  ui_story_1018_10180901_82_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1018_10180901_83_dialog_content = "Profesor, gangguan saluran telah diatasi. Anda dapat melanjutkan rapat daring sekarang.",
  ui_story_1018_10180901_84_dialog_content = "...",
  ui_story_1018_10180901_85_dialog_content = "Untuk mengurangi risiko potensial, saya harus menggunakan metode ini.",
  ui_story_1018_10180901_86_dialog_content = "Kami akan terus mencari sumber sinyal tersebut. Pemulihan penuh mungkin masih memerlukan waktu.",
  ui_story_1018_10180901_87_dialog_content = "Sepertinya kita semakin dekat pada saat rencana Anda terungkap di hadapan semua rekan Illumina, Dok.",
  ui_story_1018_10180901_88_dialog_content = "Aku akan segera mengirim Esien untuk memeriksanya.",
  ui_story_1018_10180901_89_dialog_content = "Biaya menciptakan gangguan jauh lebih rendah daripada bentrokan langsung. Anda seharusnya hanya fokus pada memperbaiki kekurangan dalam eksperimen Anda, Dokter.",
  ui_story_1018_10180901_90_dialog_content = "Jadi, apakah kamu memiliki solusi untuk pertempuran di Twilight?",
  ui_story_1018_10180901_91_dialog_content = "Aku selalu punya solusi, hanya tinggal memilih mana yang terbaik. Semuanya tergantung pada bagaimana situasi berkembang.",
  ui_story_1018_10180901_92_dialog_content = "Saya akan memperbaiki cacat pada batch keempat dari Seed.",
  ui_story_1018_10180901_93_dialog_content = "Dari pengalamanku, bijaksana untuk tidak menghabiskan kesabaran hanya pada satu hal.",
  ui_story_1018_10180901_94_dialog_content = "Ada kabar baik dari Tim Rekonesansi Dark Zone?",
  ui_story_1018_10180901_95_dialog_content = "Tim Rekonesansi Zona Gelap telah mengirimkan beberapa gambar <color=#FFB400>perangkat tiruan</color> yang dicurigai menyerupai inti Guardian One.",
  ui_story_1018_10180901_96_dialog_content = "Berdasarkan penilaian awal kami, pencurian inti Guardian One oleh Eclipsian tampaknya merupakan bagian dari persiapan proyek terkait The Engineer.",
  ui_story_1018_10180901_97_dialog_content = "...",
  ui_story_1018_10180901_98_dialog_content = "Krisis Darkover telah berakhir selama 10 tahun. Lihat apa yang telah kita lakukan sejak saat itu.",
  ui_story_1018_10180901_99_dialog_content = "Kekhawatiran Anda tidak berdasar, Topeng Besi.",
  ui_story_1018_10180901_100_dialog_content = "Saya familiar dengan Guardian One. Butuh waktu untuk inti dari Guardian One menjadi berguna.",
  ui_story_1018_10180901_101_dialog_content = "Ngomong-ngomong, untuk mempercepat penelitian tentang Seed, saya tidak akan ikut dalam pertemuan apa pun setelah ini. Selamat tinggal.",
  ui_story_1018_10180901_102_dialog_content = "Profesor, ini hasilnya. Tolong lihat.",
  ui_story_1018_10180901_103_dialog_content = "Mengapa data pertempuran terbaru begitu buruk?",
  ui_story_1018_10180901_104_dialog_content = "Profesor, ada panggilan dari Komandan Belisaria...",
  ui_story_1018_10180901_105_dialog_content = "Sambungkan saja.",
  ui_story_1018_10180901_106_dialog_content = "Aku masih ingin mengingatkan Anda, dokter.",
  ui_story_1018_10180901_107_dialog_content = "Bahkan gadis yang suka menyendiri itu muncul, jadi bisa dibayangkan betapa jauh kita tertinggal.",
  ui_story_1018_10180901_108_dialog_content = "Serangan terang-terangan dari Eclipse menyebabkan operasi di Zona Gelap ditunda... Jika itu bisa dianggap sebagai kabar baik bagi kamu.",
  ui_story_1018_10180901_109_dialog_content = "Apa maksudmu?",
  ui_story_1018_10180901_110_dialog_content = "Kamu bisa melanjutkan eksperimen, sayangnya proyek ini tidak lagi menjadi prioritas utama bagi saya.",
  ui_story_1018_10180901_111_dialog_content = "Jaga kesehatan, Dokter.",
  ui_story_1018_10180901_112_dialog_content = "...",
  ui_story_1018_10180901_113_dialog_content = "Profesor... Haruskah kita melanjutkan eksperimen kita?",
  ui_story_1018_10180901_114_dialog_content = "Tentu saja, ini tidak cukup untuk menghentikan kita!",
  ui_story_1018_10180901_115_dialog_content = "Apakah ada yang perlu kita tingkatkan? Langkah-langkah, lingkungan, penilaian?",
  ui_story_1018_10180901_116_dialog_content = "Profesor... Saya percaya ini bukan masalah.",
  ui_story_1018_10180901_117_dialog_content = "Mungkin kita bisa menyesuaikan pendekatan penelitian...",
  ui_story_1018_10180901_118_dialog_content = "Itulah persis pikirannya!",
  ui_story_1018_10180901_119_dialog_content = "Illumina Tech, Chord Link, Seeds... Katakan padaku, apa yang bisa dimodifikasi dari ketiga hal tersebut?",
  ui_story_1018_10180901_120_dialog_content = "Profesor, tingkat iterasi Seed saat ini sebenarnya sudah baik, tetapi efek perbaikan di setiap versi hampir tidak terlihat...",
  ui_story_1018_10180901_121_dialog_content = "Aku melihat aku terlalu konservatif tentang dosisnya...",
  ui_story_1018_10180901_122_dialog_content = "Waktu hampir habis. Tingkatkan dosis yang diambil dari batch Seed berikutnya!",
  ui_story_1018_10180901_123_dialog_content = "Kamu menyuruh Esien untuk melakukan rekrutmen lagi, dan membuat pengecualian bagi para prajurit yang ditolak agar bisa bergabung kembali dalam proyek tersebut.",
  ui_story_1018_10180901_124_dialog_content = "...",
  ui_story_1018_10180901_125_dialog_content = "Jadi, lab Profesor Ulysses ini memang tempat yang populer, ya!",
  ui_story_1018_10180901_126_dialog_content = "Profesor…",
  ui_story_1018_10180901_127_dialog_content = "Apa yang kalian lakukan di sini?",
  ui_story_1018_10180901_128_dialog_content = "Santai saja. Baru saja aku mendapat perintah untuk meminjamkan tim laboratoriumku kepada dokter selama beberapa hari.",
  ui_story_1018_10180901_129_dialog_content = "Committee?",
  ui_story_1018_10180901_130_dialog_content = "Kamu belum dapat pemberitahuan? Oh, mungkin Kolonel Yingel lupa memberi tahu kamu.",
  ui_story_1018_10180901_131_dialog_content = "Ya, aku juga mendapat perintah itu. Mungkin mereka berharap kita bisa mempercepat proyek dengan bekerja sama...",
  ui_story_1018_10180901_132_dialog_content = "Belisaria hanya mengirim orang untuk mengawasi saya...",
  ui_story_1018_10180901_133_dialog_content = "Apa pun. Saya tetap tidak akan menyerah.",
  ui_story_1018_10180901_134_dialog_content = "Saya akan membiarkan Anda menangani wajib militer, Yingel. Asisten saya di sebelah akan memberi Anda pengarahan.",
  ui_story_1018_10180901_135_dialog_content = "Mengerti...",
  ui_story_1018_10180901_136_dialog_content = "Tech Officer Gronru, seberapa banyak pengetahuan tim lab Anda tentang Program Phospherus?",
  ui_story_1018_10180901_137_dialog_content = "Oh, kamu bisa bertanya sendiri kepada mereka. Mereka semua sangat ingin belajar!",
  ui_story_1018_10180901_138_dialog_content = "Aku siap mendengar ajaran dari Profesor Ulysses.",
  ui_story_1018_10180901_139_dialog_content = "Ini dia, Kolonel Yingel. Anda tampil bagus di sana tadi. Saya tidak pikir Profesor Ulysses curiga sama sekali!",
  ui_story_1018_10180901_140_dialog_content = "Terima kasih, Bu Gronru, meskipun itu bukan tugas saya untuk melakukannya...",
  ui_story_1018_10180901_141_dialog_content = "Tapi, sejak menyaksikan eksperimennya secara langsung, saya tidak bisa lagi berpura-pura seolah-olah tidak ada yang terjadi.",
  ui_story_1018_10180901_142_dialog_content = "Setiap kali aku menutup mata, aku bisa melihat Axelia bertarung melawan prajurit di medan perang...",
  ui_story_1018_10180901_143_dialog_content = "Santai, burung kecil yang baik! Kamu sudah melakukan dengan sangat baik. Kami akan mengambil alih urusan pertempuran.",
  ui_story_1018_10180901_144_dialog_content = "Maksudmu?",
  ui_story_1018_10180901_145_dialog_content = "Semua orang di Illumina memiliki kekhawatiran yang sama seperti kamu, jadi secara ketat, kamu lah yang membantu kami.",
  ui_story_1018_10180901_146_dialog_content = "Sekarang giliran saya untuk pergi. Saya akan membawa semua yang terluka pulang ke rumah!",
  ui_story_1018_10180901_147_dialog_content = "Benarkah? Apakah Komite juga mengesahkan ini?",
  ui_story_1018_10180901_148_dialog_content = "Itu terserah Anda untuk memutuskan, Kolonel Yingel!",
  ui_story_1018_10180901_149_dialog_content = "...",
  ui_story_1018_10180901_150_dialog_content = "Nyonya Gronru, bolehkah saya meminta bantuan...",
  ui_story_1018_10180901_151_dialog_content = "Baiklah, akan kudengarkan.",
  ui_story_1018_10180901_152_dialog_content = "Bisakah aku... pergi ke medan perang bersamamu?",
  ui_story_1018_10180901_153_dialog_content = "Yah, itu bukan masalah, pada dasarnya...",
  ui_story_1018_10180901_154_dialog_content = "Tapi kamu tampak kurang baik terakhir kali aku melihatmu di sini. Jika aku tidak salah, suara senjata yang saling beradu membuatmu tidak nyaman.",
  ui_story_1018_10180901_155_dialog_content = "Benar. Sebagai prajurit, aku tahu aku harus membawa senjata.",
  ui_story_1018_10180901_156_dialog_content = "Namun saat aku sendirian, suara dingin dan kejam dari pertempuran akan bergema di telingaku dan membuatku ketakutan...",
  ui_story_1018_10180901_157_dialog_content = "Namun, Illumina membutuhkan saya sekarang dan saya harus melakukan sesuatu, seperti yang saya katakan kepada Officer Vivian...",
  ui_story_1018_10180901_158_dialog_content = "Oh, Vivian itu—ups, hampir saja terucap.",
  ui_story_1018_10180901_159_dialog_content = "Burung kecil yang baik hati harus menemukan jalannya sendiri. Temui aku di halaman saat kamu siap!",
  ui_story_1018_10180901_160_dialog_content = "Tentu. Terima kasih, Bu Gronru.",
  ui_story_1018_10181002_1_dialog_content = "Kapten Penjaga, sebagian besar lumpur telah menyebar, dan tidak ada tanda-tanda aktivitas Eclipsite di sekitar Twilight sekarang.",
  ui_story_1018_10181002_2_dialog_content = "Dengan bantuan kita, misi pencarian dan penyelamatan Illumina kini telah selesai. Grand Marshal Wrath sedang mengumpulkan informasi dari bawahannya.",
  ui_story_1018_10181002_3_dialog_content = "Siap, laksanakan. Siaga setelah pasukan siap.",
  ui_story_1018_10181002_4_dialog_content = "Saya melihat ini adalah seperti apa Twilight tanpa lumpur—sebuah tempat yang ramai.",
  ui_story_1018_10181002_5_dialog_content = "Ya, Lady Saintess, di sini dulunya adalah pasar dan Anda masih bisa melihat kios-kiosnya.",
  ui_story_1018_10181002_6_dialog_content = "Tembok yang rusak di sana dulu digunakan untuk mengelilingi bedeng bunga kecil.",
  ui_story_1018_10181002_7_dialog_content = "Aneh, tapi ada banyak jenis bunga yang berbeda di taman bunga itu dan mereka mekar sepanjang tahun.",
  ui_story_1018_10181002_8_dialog_content = "Anak-anak suka bermain di sini, dan begitu juga aku saat masih kecil.",
  ui_story_1018_10181002_9_dialog_content = "Tapi tempat bermain mereka kini telah dirusak oleh Eclipsites.",
  ui_story_1018_10181002_10_dialog_content = "Meskipun aku percaya bunga-bunga itu akan mekar lagi.",
  ui_story_1018_10181002_11_dialog_content = "Dan saya percaya di bawah asuhan Nyonya Joselyne, anak-anak akan menikmati kehidupan di sini lagi.",
  ui_story_1018_10181002_12_dialog_content = "Aku sudah bisa mendengar tawa mereka!",
  ui_story_1018_10181002_13_dialog_content = "Terima kasih atas doronganmu, Lady Saintess! Tapi aku khawatir bahwa...",
  ui_story_1018_10181002_14_dialog_content = "Eclipsites tidak hanya menghancurkan rumah, tetapi juga kepercayaan orang-orang di Twilight terhadap para pejuang...",
  ui_story_1018_10181002_15_dialog_content = "Mungkin mereka tidak akan percaya bahwa tempat ini akan memberikan kenyamanan dan kedamaian lagi.",
  ui_story_1018_10181002_16_dialog_content = "Aku percaya akan berhasil.",
  ui_story_1018_10181002_17_dialog_content = "Leo...?",
  ui_story_1018_10181002_18_dialog_content = "Di bawah lumpur ini terbaring para pejuang yang mengorbankan diri mereka dalam pertempuran ini.",
  ui_story_1018_10181002_19_dialog_content = "Twilight berawal dari tempat yang dibangun di atas tubuh para prajurit. Situasi sekarang hanya meyakinkan mereka bahwa perang akan selalu ada.",
  ui_story_1018_10181002_20_dialog_content = "Selama masih ada orang yang bersedia tinggal di sini, tekad untuk melindungi Twilight tidak akan pernah goyah.",
  ui_story_1018_10181002_21_dialog_content = "Sebelum ini, Twilight adalah zona nyaman bagi saya.",
  ui_story_1018_10181002_22_dialog_content = "Tanpa kampanye ini, saya mungkin masih akan khawatir tentang kapan kota ini akan jatuh dan ragu untuk melangkah maju.",
  ui_story_1018_10181002_23_dialog_content = "Hasil saat ini merupakan kesempatan bagi Twilight dan saya untuk mengevaluasi kembali pandangan kami.",
  ui_story_1018_10181002_24_dialog_content = "Leo, apakah yang baru saja kamu katakan menunjukkan bahwa pandanganmu tentang Lumopolis telah berubah?",
  ui_story_1018_10181002_25_dialog_content = "Tidak, Nyonya Carleen, saya minta maaf telah mengecewakan Anda.",
  ui_story_1018_10181002_26_dialog_content = "Namun, tindakan Marshal Wrath membuat saya menyadari bahwa ketidakpuasan terhadap suatu situasi tidak bisa hanya bersifat permukaan saja.",
  ui_story_1018_10181002_27_dialog_content = "Saya harus melakukan perubahan agar kemampuan saya sejalan dengan ambisi saya.",
  ui_story_1018_10181002_28_dialog_content = "Saya berjanji kepada kalian semua bahwa masa depan Twilight juga menjadi tanggung jawab saya sendiri.",
  ui_story_1018_10181002_29_dialog_content = "Apakah itu membuat kamu lebih tenang sekarang, Joselyne?",
  ui_story_1018_10181002_30_dialog_content = "Leo, aku sangat tersentuh oleh apa yang kamu katakan...",
  ui_story_1018_10181002_31_dialog_content = "Saya percaya Twilight bisa dibangun kembali dan lebih baik dari sebelumnya!",
  ui_story_1018_10181002_32_dialog_content = "Sebenarnya, ada ide yang sedang tercetus di kepala saya, dan saya ingin tahu apakah Lady Saintess bisa memberikan saya bimbingan?",
  ui_story_1018_10181002_33_dialog_content = "Yang Mulia, kami masih memiliki urusan mendesak yang harus kami tangani.",
  ui_story_1018_10181002_34_dialog_content = "Ya, tapi bisakah aku bertukar beberapa kata lagi dengan Joselyne?",
  ui_story_1018_10181002_35_dialog_content = "Lady Joselyne, tolong singkat saja.",
  ui_story_1018_10181002_36_dialog_content = "Lady Saintess, saya ingin membangun gereja di Twilight yang akan melindungi semua orang, tidak hanya pengikut Dewa Cahaya.",
  ui_story_1018_10181002_37_dialog_content = "Aurorian, demi-human, Caelestite, bahkan mereka yang terpaksa beralih ke kegelapan...",
  ui_story_1018_10181002_38_dialog_content = "Mereka mungkin tidak diterima di kamp mereka, tetapi semua yang menginjakkan kaki di Twilight bisa tinggal, selama mereka memiliki cinta dan kasih sayang di hati mereka.",
  ui_story_1018_10181002_39_dialog_content = "Twilight seharusnya tidak hanya memiliki matahari terbenam, tetapi juga disinari oleh cahaya.",
  ui_story_1018_10181002_40_dialog_content = "Seperti orang-orang di Astra dan tempat lainnya, mereka seharusnya dapat melihat cahaya matahari, bulan, dan bintang-bintang.",
  ui_story_1018_10181002_41_dialog_content = "Saya tahu ini pekerjaan yang sangat berat, tetapi saya berharap untuk mendapatkan berkat Anda terlebih dahulu.",
  ui_story_1018_10181002_42_dialog_content = "Anda sangat saleh dan murah hati, Nyonya Joselyne.",
  ui_story_1018_10181002_43_dialog_content = "Seperti para Aurorian asli yang berpetualang ke selatan untuk mengajak orang lain, membangun gereja impianmu di sini juga merupakan tantangan yang sama besarnya.",
  ui_story_1018_10181002_44_dialog_content = "Namun cahaya suci dapat menerangi setiap sudut keyakinan, terutama dalam bimbingan Anda.",
  ui_story_1018_10181002_45_dialog_content = "Ambil langkah itu jika Anda bersedia. Anda punya dukungan saya.",
  ui_story_1018_10181002_46_dialog_content = "Terima kasih, Nona Saintess. Aku tidak akan pernah melupakan ini!",
  ui_story_1018_10181002_47_dialog_content = "Fiuh... Apakah itu pidato yang bagus?",
  ui_story_1018_10181002_48_dialog_content = "Pilihan kata Anda sangat sempurna, Yang Mulia. Namun, saatnya bagi kami untuk melanjutkan perjalanan.",
  ui_story_1018_10181002_49_dialog_content = "Oke, aku biarkan kamu mengurusnya dari sini.",
  ui_story_1018_10181002_50_dialog_content = "Oh, Carleen, setelah Twilight aman, pergilah ke garis depan dan temui pasukan City Lord.",
  ui_story_1018_10181002_51_dialog_content = "Dia mengirim pasukan ke garis depan?!",
  ui_story_1018_10181002_52_dialog_content = "Tapi kenapa dia terlihat sangat acuh tak acuh saat di pengadilan tadi?",
  ui_story_1018_10181002_53_dialog_content = "Yah, dia menyebutkan \"Mengambil keuntungan dari situasi\"... Saya juga tidak yakin.",
  ui_story_1018_10181002_54_dialog_content = "Bukan hanya tentara Lord Kota, tetapi juga rekan-rekan Marsekal.",
  ui_story_1018_10181002_55_dialog_content = "Bukankah pertempuran sudah selesai?",
  ui_story_1018_10181002_56_dialog_content = "Tenang saja, pertempuran di Twilight sudah berakhir.",
  ui_story_1018_10181002_57_dialog_content = "Namun perang baru saja dimulai bagi Aurorian, itulah mengapa saya meninggalkan Kuil.",
  ui_story_1018_10181002_58_dialog_content = "Sangat senang bertemu denganmu dalam perjalanan ini. Aku akan mendoakanmu.",
  ui_story_1018_10181002_59_dialog_content = "May Semoga Dewa Cahaya bersama Anda. Saya menantikan saat kita bertemu lagi.",
  ui_story_1018_10181002_60_dialog_content = "God of Light yang abadi.",
  ui_story_1018_10181002_61_dialog_content = "Demi White Night.",
  ui_story_1018_10181002_62_dialog_content = "Eclipsite tidak mundur, tetapi malah bergerak ke garis depan Illumina. Saya rasa kita tidak akan bisa mengakhiri kenaikan Darkover dengan mudah...",
  ui_story_1018_10181002_63_dialog_content = "Aku melihat kalian semua tahu.",
  ui_story_1018_10181002_64_dialog_content = "Grand Marshal Wrath! Setidaknya Lady Saintess mengatakan Twilight aman untuk saat ini.",
  ui_story_1018_10181002_65_dialog_content = "Kota ini bertahan, berkat usaha bersama Illumina dan para Ksatria!",
  ui_story_1018_10181002_66_dialog_content = "Terima kasih atas pengakuan itu, tapi tidak perlu menghibur saya, Joselyne.",
  ui_story_1018_10181002_67_dialog_content = "Sebenarnya, aku merasa bersyukur bahwa situasinya menjadi jelas.",
  ui_story_1018_10181002_68_dialog_content = "Kami berhasil dalam hal hasil, tapi bagi saya, itu adalah kegagalan yang sangat buruk...",
  ui_story_1018_10181002_69_dialog_content = "Grand Marshal Wrath, Illumina tidak bisa menghadapi kesulitan saat ini sendiri.",
  ui_story_1018_10181002_70_dialog_content = "Lumopolis seharusnya tidak diam saja ketika pertempuran di Twilight berlangsung tidak menguntungkan.",
  ui_story_1018_10181002_71_dialog_content = "Sekarang pasukan Tuan Kota sedang berkumpul di garis depan, terlepas dari bagaimana Illumina bereaksi, Lumopolis tidak akan menjadi penonton lagi.",
  ui_story_1018_10181002_72_dialog_content = "Anda salah paham, Lady Carleen. Hanya kegagalan yang bisa memberi semua ini arti.",
  ui_story_1018_10181002_73_dialog_content = "Kampanye Twilight, prajurit yang dikorbankan, dan proyek atasan... Semuanya harus berakhir dengan kegagalan saya.",
  ui_story_1018_10181002_74_dialog_content = "Itu satu-satunya cara agar Illumina memiliki masa depan.",
  ui_story_1018_10181002_75_dialog_content = "Grand Marshal, apakah kamu dan rekan-rekanmu sedang merencanakan sesuatu?",
  ui_story_1018_10181002_76_dialog_content = "Aku harus memastikan keyakinanku sendiri, tidak peduli bahaya apa yang menanti di garis depan.",
  ui_story_1018_10181002_77_dialog_content = "Saya khawatir apa yang terjadi pada Twilight bisa terjadi pada Illumina.",
  ui_story_1018_10181002_78_dialog_content = "Tidakkah Axelia mengatakan bahwa Forsakin juga membawa prajurit-prajuritnya?",
  ui_story_1018_10181002_79_dialog_content = "Selama mereka yang membela, masih darah dan daging, aku yakin ini tak akan terulang lagi.",
  ui_story_1018_10181002_80_dialog_content = "Aku berjanji pada prajurit yang gugur bahwa aku akan membawa mereka kembali ke Illumina, tidak peduli apa yang terjadi.",
  ui_story_1018_10181002_81_dialog_content = "Nanti kita bicara tentang Twilight. Pasukan Illumina-ku akan kembali ke garis depan.",
  ui_story_1018_10181002_82_dialog_content = "Jika itu tujuan Anda, para Ksatria Twilight akan menemani Anda.",
  ui_story_1018_10181002_83_dialog_content = "Musuh-musuh belum sepenuhnya dieliminasi, jadi kita masih tetap sekutu.",
  ui_story_1018_10181002_84_dialog_content = "Baiklah! Aku tidak akan melupakan sekutu kita dari Twilight.",
  ui_story_1018_10181002_85_dialog_content = "Dalam hal ini, bisakah saya mengantarkan kamu dengan pesawat Lumopolis, Leo dan Grand Marshal Wrath?",
  ui_story_1018_10181002_86_dialog_content = "Dengan hormat, saya menolak. Para ksatria terbiasa mengendarai kuda dalam pertempuran, bukan menggunakan kendaraan udara.",
  ui_story_1018_10181002_87_dialog_content = "Terima kasih atas tawaran Anda, Lady Carleen, tetapi itu tidak sesuai dengan prosedur Illumina.",
  ui_story_1018_10181002_88_dialog_content = "Tapi, aku bisa melihat para prajurit kelelahan. Mungkin mereka bisa beristirahat di kapal udara.",
  ui_story_1018_10181002_89_dialog_content = "Carleen benar. Jika kita menghadapi pertempuran yang berat, mereka harus istirahat sekarang.",
  ui_story_1018_10181002_90_dialog_content = "Saya rasa prajurit yang terluka juga tidak bisa menangani perjalanan dengan berjalan kaki.",
  ui_story_1018_10181002_91_dialog_content = "Jadi, bahkan kamu sekarang tahu kunci untuk memimpin pasukan dalam pertempuran?",
  ui_story_1018_10181002_92_dialog_content = "Kurasa Twilight adalah tempat latihan yang sebenarnya.",
  ui_story_1018_10181002_93_dialog_content = "Grand Marshal, maka kami akan dengan rendah hati menuruti perintah Anda.",
  ui_story_1018_10181002_94_dialog_content = "Kapten, haruskah kita...?",
  ui_story_1018_10181002_95_dialog_content = "...",
  ui_story_1018_10181002_96_dialog_content = "Ayo ikut, Leo.",
  ui_story_1018_10181002_97_dialog_content = "Berhenti ragu-ragu jika kita akan membunuh musuh bersama, Kesatria.",
  ui_story_1018_10181002_98_dialog_content = "Tentu!",
  ui_story_1018_10181101_1_dialog_content = "<color=#e8d9bb>Garis Pertahanan Illumina</color>",
  ui_story_1018_10181101_2_dialog_content = "Komandan, kami telah mengkonfirmasi bahwa ksatria yang terlihat di sepanjang garis pertahanan timur dan barat berasal dari Lumopolis.",
  ui_story_1018_10181101_3_dialog_content = "Hingga saat ini, belum ada tanda-tanda Eclipsites terdeteksi di sepanjang garis pertahanan timur dan barat. Kesatria Lumopolis dan unit pertahanan kita terus menjaga pengawasan yang ketat.",
  ui_story_1018_10181101_4_dialog_content = "Aku paham.",
  ui_story_1018_10181101_5_dialog_content = "Ada perubahan dalam gerakan mereka?",
  ui_story_1018_10181101_6_dialog_content = "Rute mereka sama seperti biasa—langsung dari pusat, maju ke daratan secara vertikal. Unit serangan kami sedang bertempur langsung dengan musuh dan siap untuk menembus formasi mereka.",
  ui_story_1018_10181101_7_dialog_content = "Tujuan mereka masih belum diketahui, jadi skuad serangan harus menahan Eclipsites dari parit-parit.",
  ui_story_1018_10181101_8_dialog_content = "Tapi, Komandan... meskipun kita berhasil mengusir satu kelompok Eclipsites, mereka hanya akan mengirimkan yang berikutnya. Apakah kita benar-benar baik-baik saja jika terus bertahan seperti ini?",
  ui_story_1018_10181101_9_dialog_content = "Eclipsite hanya sedang menguji kita, bukan berusaha melancarkan serangan.",
  ui_story_1018_10181101_10_dialog_content = "Kita tidak boleh gegabah sampai kita mengerti sepenuhnya.",
  ui_story_1018_10181101_11_dialog_content = "Bagaimana kabar bentengnya?",
  ui_story_1018_10181101_12_dialog_content = "Jenderal Barton mengawasi masalah pertahanan antara Undercities, dan pasukan di bawah Jenderal Hiiro seharusnya segera mencapai garis pertahanan.",
  ui_story_1018_10181101_13_dialog_content = "Kerusakan pada peralatan komunikasi sebelumnya belum dapat diperbaiki. Jadi kami sudah mengirimkan pemberitahuan sesuai dengan permintaan Anda. Operasi pertempuran darat kini berada di tangan pasukan garis depan.",
  ui_story_1018_10181101_14_dialog_content = "Setiap Undercity didedikasikan untuk strategi pertahanan mereka sendiri dan tidak akan merespon tindakan di sepanjang garis pertahanan.",
  ui_story_1018_10181101_15_dialog_content = "Oke. Masih belum ada kabar dari Twilight?",
  ui_story_1018_10181101_16_dialog_content = "Tidak ada kabar dari Grand Marshal. Tetapi melihat peningkatan kewaspadaan pasukan Lumopolis, pertempuran di Twilight sepertinya akan segera berakhir.",
  ui_story_1018_10181101_17_dialog_content = "Saya harap semuanya berjalan sesuai harapan.",
  ui_story_1018_10181101_18_dialog_content = "Komandan! Di luar garis pertahanan, rawa-rawa tiba-tiba muncul di parit dan menangkap beberapa prajurit!",
  ui_story_1018_10181101_19_dialog_content = "Serangan Eclipsite kali ini jauh lebih ganas daripada sebelumnya!",
  ui_story_1018_10181101_20_dialog_content = "Di parit? Sebelumnya tidak ada tanda-tanda rawa-rawa yang menyebar.",
  ui_story_1018_10181101_21_dialog_content = "Komandan, perluasan rawa ini bukanlah secara bertahap—tiba-tiba melonjak naik dari bawah tanah!",
  ui_story_1018_10181101_22_dialog_content = "Seperti yang dijelaskan oleh para prajurit, pada awalnya, hanya ada sedikit lumpur di parit tersebut, lalu tiba-tiba, lumpur itu teraduk, menumpuk seperti gila!",
  ui_story_1018_10181101_23_dialog_content = "Sudah menyebar ke penghalang yang berdekatan!",
  ui_story_1018_10181101_24_dialog_content = "...",
  ui_story_1018_10181101_25_dialog_content = "Sampaikan situasi kepada Kavaleri Lumo di front barat dan pindahkan cadangan ke pusat, segera!",
  ui_story_1018_10181101_26_dialog_content = "Komando, ikuti saya ke garis depan pusat!",
  ui_story_1018_10181101_27_dialog_content = "Ya!",
  ui_story_1018_10181101_28_dialog_content = "Mereka menyebut ini sebagai penghalang? Seperti ini sepuluh tahun lalu, dan masih sama sepuluh tahun kemudian.",
  ui_story_1018_10181101_29_dialog_content = "Makanan—",
  ui_story_1018_10181101_30_dialog_content = "Kamu di sini bukan untuk makan. Kamu hanya perlu mengangkut rekan-rekan yang kompeten itu.",
  ui_story_1018_10181101_31_dialog_content = "Tak lama lagi, jalur dari Dark Zone menuju daerah inti akan muncul.",
  ui_story_1018_10181101_32_dialog_content = "Api biru sedang menyala—",
  ui_story_1018_10181101_33_dialog_content = "Heh, kamu bergerak cepat, harus kuakui.",
  ui_story_1018_10181101_34_dialog_content = "Oh, ternyata kau, si pengkhianat.",
  ui_story_1018_10181101_35_dialog_content = "Heh, teko, ketel, hitam. Apakah kamu lupa tentang prajurit yang kamu bunuh?",
  ui_story_1018_10181101_36_dialog_content = "Kau bodoh yang tak tahu apa-apa! Kau membunuh semua prajurit di Twilight?",
  ui_story_1018_10181101_37_dialog_content = "Tidak semua. Cukup banyak yang tewas di tangan rekan-rekan mereka sendiri, meskipun itu sesuai dengan tradisi Illumina yang menggunakan lalu melupakan.",
  ui_story_1018_10181101_38_dialog_content = "Diam dan bersiaplah untuk mati!",
  ui_story_1018_10181101_39_dialog_content = "Yang akan menemui kematian adalah kamu. Grand Marshal baru kalian sangat menderita di hadapan mereka.",
  ui_story_1018_10181101_40_dialog_content = "Mereka?",
  ui_story_1018_10181101_41_dialog_content = "Terlihat familiar? Itulah yang dia dapatkan karena mencoba berpura-pura pintar.",
  ui_story_1018_10181101_42_dialog_content = "Apa yang terjadi dengan Wrath?",
  ui_story_1018_10181101_43_dialog_content = "Hanya masalah waktu hingga dia mati. Lalu giliranmu menjadi Grand Marshal.",
  ui_story_1018_10181101_44_dialog_content = "Grand Marshal bukanlah orang yang bisa kamu hina!",
  ui_story_1018_10181101_45_dialog_content = "Astaga!",
  ui_story_1018_10181101_46_dialog_content = "...",
  ui_story_1018_10181101_47_dialog_content = "Apa, tidak bisa melakukannya? Kamu harus segera mengambil keputusan.",
  ui_story_1018_10181101_48_dialog_content = "Komandan, dia sebenarnya menghilang ke dalam rawa...",
  ui_story_1018_10181101_49_dialog_content = "Tunggu, apakah lumpur itu sudah menelan Twilight, menyebar ke sini dari bawah...",
  ui_story_1018_10181101_50_dialog_content = "Garis pertahanan Illumina... Apakah itu juga akan tertelan?",
  ui_story_1018_10181101_51_dialog_content = "Bunuh Eclipsite-nya dulu dan tunggu kabar dari saya tentang apa yang terjadi di bawah parit-parit.",
  ui_story_1018_10181101_52_dialog_content = "Karena muncul dari bawah tanah, akan lebih cepat jika kita mengacaukan Undercity-Undercity itu.",
  ui_story_1018_10181101_53_dialog_content = "Jangan panik dan pertahankan garis!",
  ui_story_1018_10181101_54_dialog_content = "Baik!",
  ui_story_1018_10181101_55_dialog_content = "Tim penyerang, mundur ke samping tembok dan hapuskan para Eclipsite.",
  ui_story_1018_10181101_56_dialog_content = "Astaga!",
  ui_story_1018_10181101_57_dialog_content = "Komandan, dia... apakah dia salah satu prajurit Illumina kita?",
  ui_story_1018_10181101_58_dialog_content = "Penuh dengan Darkflow, memangsa Eclipsite, menyakiti kawan-kawan...",
  ui_story_1018_10181101_59_dialog_content = "Mereka adalah Eclipsites, tanpa ampun!",
  ui_story_1018_10181101_60_dialog_content = "T-terpahami, Komandan!",
  ui_story_1018_10181102_1_dialog_content = "<color=#e8d9bb>Duaaaar!</color>",
  ui_story_1018_10181102_2_dialog_content = "Artileri sudah dikerahkan! Sepertinya rawa-rawa telah berhenti menyebar!",
  ui_story_1018_10181102_3_dialog_content = "Eclipsites juga berhenti!",
  ui_story_1018_10181102_4_dialog_content = "Perintah Anda tepat waktu, Komandan!",
  ui_story_1018_10181102_5_dialog_content = "Aku tidak memberikan perintah itu...",
  ui_story_1018_10181102_6_dialog_content = "Selongsong itu ditembakkan dari tiga benteng yang berbeda.",
  ui_story_1018_10181102_7_dialog_content = "Apa mungkin...",
  ui_story_1018_10181102_8_dialog_content = "Oh ya, sungguh menggembirakan! Sudah lama aku tidak merasa bersemangat seperti ini karena bombardir!",
  ui_story_1018_10181102_9_dialog_content = "Sedikit meleset dari sasaran, tapi masih mencapai hasil yang diharapkan.",
  ui_story_1018_10181102_10_dialog_content = "Komandan, ini Jenderal Barton dan Jenderal Hiiro!",
  ui_story_1018_10181102_11_dialog_content = "Itu benar-benar mereka! Datang untuk mendukung kita!",
  ui_story_1018_10181102_12_dialog_content = "Menguatkan Undercity berjalan dengan baik, dan aku tidak akan melewatkan pertempuran ini demi apapun!",
  ui_story_1018_10181102_13_dialog_content = "Tidak ada alasan untuk melewatkannya saat pertarungan sudah ada di depan pintu rumahmu.",
  ui_story_1018_10181102_14_dialog_content = "Saya sangat berterima kasih atas bantuan kalian berdua. Eclipsites saat ini masih berada di bawah kendali.",
  ui_story_1018_10181102_15_dialog_content = "Namun, rawa-rawa terlihat di parit-parit, dan aku khawatir itu akan meresap ke dalam Undercity.",
  ui_story_1018_10181102_16_dialog_content = "Tidak ada tanda-tanda itu saat kami ke sini. Mungkin saja musuh baru saja tiba.",
  ui_story_1018_10181102_17_dialog_content = "Benar, selama ini aku mengawasi perimeter seperti elang.",
  ui_story_1018_10181102_18_dialog_content = "Banjir lumpur melanda Twilight, dan Forsakin terlibat...",
  ui_story_1018_10181102_19_dialog_content = "Bagaimanapun, kita akan menghadapinya bersama.",
  ui_story_1018_10181102_20_dialog_content = "Kita hanya menunggu Wrath. Semoga berjalan sesuai rencana dia...",
  ui_story_1018_10181102_21_dialog_content = "Aku percaya akan berhasil.",
  ui_story_1018_10181102_22_dialog_content = "Grand Marshal!",
  ui_story_1018_10181102_23_dialog_content = "Saya juga percaya pada Wrath!",
  ui_story_1018_10181102_24_dialog_content = "Chief of Staff! Apa yang kamu lakukan di sini?",
  ui_story_1018_10181102_25_dialog_content = "Berdasarkan rencana Wrath, jika Eclipsite menyerang bagian depan, saya akan menjadi yang terakhir dikerahkan.",
  ui_story_1018_10181102_26_dialog_content = "Grand Marshal juga akan bertindak bersamaku setelah menerima perintah.",
  ui_story_1018_10181102_27_dialog_content = "Jadi, itu berarti salah satu dari tiga senjata besar berada di bawah kendali Grand Marshal?",
  ui_story_1018_10181102_28_dialog_content = "Belum <color=#FFB400>mengendarai gerbong senjata</color> dalam waktu yang lama, tapi aku rasa aku masih bisa melakukannya.",
  ui_story_1018_10181102_29_dialog_content = "Marsekal Agung, bagaimana Anda...",
  ui_story_1018_10181102_30_dialog_content = "Oh, hampir lupa!",
  ui_story_1018_10181102_31_dialog_content = "Operasi: Pembebasan Penjara berhasil untuk Chief of Staff Vivian, Ma'am!",
  ui_story_1018_10181102_32_dialog_content = "Wow...",
  ui_story_1018_10181102_33_dialog_content = "Grand Marshal, Kapten Sharona dari 1st Legion berhasil mempertahankan garis dan menolak masuknya semua Eclipsite.",
  ui_story_1018_10181102_34_dialog_content = "Selama aku, Kapten Barton dari 2nd Legion, ada di sini, tidak ada Eclipsite yang akan masuk ke kota bawah!",
  ui_story_1018_10181102_35_dialog_content = "Kapten Hiiro dari Legiun ke-3, yang bertanggung jawab atas penguatan terakhir, telah menyelesaikan tugasnya.",
  ui_story_1018_10181102_36_dialog_content = "Sangat baik dilakukan, semuanya. Dan selamat bekerja untuk semua rekan-rekan Illumina ku.",
  ui_story_1018_10181102_37_dialog_content = "Jenderal dan Grand Marshal semua di sini... Saya masih sulit untuk percaya...",
  ui_story_1018_10181102_38_dialog_content = "Grand Marshal!",
  ui_story_1018_10181102_39_dialog_content = "Hormat!",
  ui_story_1018_10181201_1_dialog_content = "Komandan, tidak ada jejak Forsakin yang ditemukan di parit.",
  ui_story_1018_10181201_2_dialog_content = "Saat ini, para ksatria Lumopolis masih memegang garis pertahanan, dan kabarnya bala bantuan menuju Twilight sudah dalam perjalanan kembali.",
  ui_story_1018_10181201_3_dialog_content = "Siap, laksanakan. Laporkan segera saat bala bantuan terlihat.",
  ui_story_1018_10181201_4_dialog_content = "Sepertinya Lumopolis tidak berniat untuk terlibat dalam pertempuran.",
  ui_story_1018_10181201_5_dialog_content = "Kami tidak yakin apa yang terjadi di Twilight, tetapi masih ada ruang untuk harapan. Saya hanya khawatir tentang Wrath...",
  ui_story_1018_10181201_6_dialog_content = "Benar, sudah lama tidak ada kabar dari Twilight.",
  ui_story_1018_10181201_7_dialog_content = "Ini kelalaianku. Aku sudah tinggal di sini sejak Wrath pergi ke Twilight.",
  ui_story_1018_10181201_8_dialog_content = "Jika aku menyerang, garis pertahanan mungkin akan jatuh, tetapi jika aku mundur ke belakang garis, aku mungkin akan melewatkan laporan yang keluar dari Twilight.",
  ui_story_1018_10181201_9_dialog_content = "Aku bahkan tidak bisa mencapai dasar rawa yang menyebar dan membiarkan Forsakin kabur.",
  ui_story_1018_10181201_10_dialog_content = "Kamu tidak salah. Saya mendengar tentang situasi di Twilight dalam perjalanan dan musuh menggunakan serangan yang belum pernah terjadi sebelumnya, jadi semua orang harus berhati-hati.",
  ui_story_1018_10181201_11_dialog_content = "Sesuatu sedang mendekat dengan cepat dari lumpur di depan, Grand Marshal.",
  ui_story_1018_10181201_12_dialog_content = "Ini punya keinginan mati! Izinkan aku untuk mengabulkannya!",
  ui_story_1018_10181201_13_dialog_content = "Hati-hati dengan rawa, Forsakin mungkin sedang mengintai.",
  ui_story_1018_10181201_14_dialog_content = "Menyelinap seperti tikus, itukah cara kamu menyerang garis pertahanan?",
  ui_story_1018_10181201_15_dialog_content = "Panther's Prowl!",
  ui_story_1018_10181201_16_dialog_content = "Telan semua—",
  ui_story_1018_10181201_17_dialog_content = "Akhirnya menunjukkan dirimu, belatung?!",
  ui_story_1018_10181201_18_dialog_content = "Graaaah—!",
  ui_story_1018_10181201_19_dialog_content = "Komandan! Eclipsite muncul dari rawa-rawa, dan pasukan tentara tak dikenal yang cukup besar sedang menuju garis pertahanan!",
  ui_story_1018_10181201_20_dialog_content = "Tolong berikan perintahmu, Grand Marshal!",
  ui_story_1018_10181201_21_dialog_content = "...",
  ui_story_1018_10181201_22_dialog_content = "Aku tidak akan memberikan perintah. Aku bukan komandan dalam pertempuran ini.",
  ui_story_1018_10181201_23_dialog_content = "Tapi, Marsekal Agung...",
  ui_story_1018_10181201_24_dialog_content = "Tidak bisa dinegosiasikan. Aku ikut dalam pertarungan ini sebagai warga negara biasa.",
  ui_story_1018_10181201_25_dialog_content = "Semua orang, lakukan saja apa yang seharusnya kalian lakukan.",
  ui_story_1018_10181201_26_dialog_content = "...",
  ui_story_1018_10181201_27_dialog_content = "Kalau begitu, aku tidak ingin mencatat selongsong di sini sia-sia! Bidikkan senapan ke arah timur!",
  ui_story_1018_10181201_28_dialog_content = "Bidik, senapan sisi barat!",
  ui_story_1018_10181201_29_dialog_content = "Komandan, legiun pertahanan di sisi timur dan barat telah berkumpul dan siap.",
  ui_story_1018_10181201_30_dialog_content = "Cadangan timur dan barat, cari Forsakin di sepanjang rawa-rawa. Tim penyerang, bersiaplah untuk menyerang Eclipsites!",
  ui_story_1018_10181201_31_dialog_content = "Tunggu, Sharona, bukankah Eclipsite yang tertutup lumpur itu prajurit Illumina?",
  ui_story_1018_10181201_32_dialog_content = "...",
  ui_story_1018_10181201_33_dialog_content = "Beberapa di antara mereka masih sedikit sadar, tetapi banyak yang telah berubah menjadi Eclipsite secara tak dapat kembali.",
  ui_story_1018_10181201_34_dialog_content = "Bagaimana kita...",
  ui_story_1018_10181201_35_dialog_content = "Biar kubantu.",
  ui_story_1018_10181201_36_dialog_content = "Marsekal Agung...",
  ui_story_1018_10181201_37_dialog_content = "Jangan khawatir. Aku akan menyelamatkan mereka selama masih ada harapan.",
  ui_story_1018_10181201_38_dialog_content = "Tapi Grand Marshal, mereka memangsa prajurit. Saya hanya...",
  ui_story_1018_10181201_39_dialog_content = "Aku juga akan melakukan itu jika aku jadi kamu, tapi tubuhku bisa menahan gigitan mereka.",
  ui_story_1018_10181201_40_dialog_content = "Terus pimpin prajuritmu. Tim yang mengangkut yang terluka sudah dalam perjalanan.",
  ui_story_1018_10181201_41_dialog_content = "Baik, Grand Marshal.",
  ui_story_1018_10181201_42_dialog_content = "<color=#e8d9bb>Duaaaar!</color>",
  ui_story_1018_10181201_43_dialog_content = "Ini... tembakan artileri Komandan Hiiro, mengenai pusat rawa dengan tepat!",
  ui_story_1018_10181201_44_dialog_content = "Belum ada tembakan dari penembak bagian barat.",
  ui_story_1018_10181201_45_dialog_content = "Jangan lihat aku, juga sisi ku.",
  ui_story_1018_10181201_46_dialog_content = "Itu hanya bisa berarti...",
  ui_story_1018_10181201_47_dialog_content = "Heh, kaukira kau bisa menghentikan Mudbundle?",
  ui_story_1018_10181201_48_dialog_content = "Ini menghancurkan Twilight.",
  ui_story_1018_10181201_49_dialog_content = "Lumpur datang—",
  ui_story_1018_10181201_50_dialog_content = "Kamu sudah menghancurkan Twilight, Forsakin, kenapa sekarang kamu menyerang bagian depan?",
  ui_story_1018_10181201_51_dialog_content = "Ayo, jangan bilang kamu masih di pihak Illumina setelah mereka membuangmu ke dalam sel!",
  ui_story_1018_10181201_52_dialog_content = "Daripada dengan cara yang sulit, kenapa tidak kau buka saja gerbangnya dan biarkan aku membakar mereka yang menjebakmu?",
  ui_story_1018_10181201_53_dialog_content = "Illumina memiliki aturan dan prinsipnya sendiri. Ini sejauh yang Anda dapatkan.",
  ui_story_1018_10181201_54_dialog_content = "Masih bermain sebagai bangsawan, kusadari. Tidak heran mereka menyeretmu ke dalam kubangan.",
  ui_story_1018_10181201_55_dialog_content = "Jangan bicara seperti itu pada Grand Marshal!",
  ui_story_1018_10181201_56_dialog_content = "Buka matamu, anjing penjaga. Tidak ada Grand Marshal di sini.",
  ui_story_1018_10181201_57_dialog_content = "Tidak ada Grand Marshal? Sepertinya Anda bicara terlalu cepat.",
  ui_story_1018_10181201_58_dialog_content = "<color=#e8d9bb>Tanah yang bergetar bergema dengan suara roda yang menggelegar dan kaki kuda yang berlari kencang...</color>",
  ui_story_1018_10181201_59_dialog_content = "Mendarat lebih awal memang keputusan yang tepat. Lebih praktis untuk bergerak di darat!",
  ui_story_1018_10181201_60_dialog_content = "Musuh tidak akan punya tempat untuk lari setelah kita menyeberangi parit. Semua senjata, tembak ke rawa-rawa!",
  ui_story_1018_10181201_61_dialog_content = "Hei, garis Illumina benar-benar melompat. Rencana serangan mereka masih tetap sederhana seperti biasanya.",
  ui_story_1018_10181201_62_dialog_content = "Itu membuatnya lebih baik. Kita akan menjadi tembok terakhir yang menutup jalan keluarnya.",
  ui_story_1018_10181201_63_dialog_content = "Axelia akan mengambil semua bawahan...",
  ui_story_1018_10181201_64_dialog_content = "Sudah pulih begitu cepat? Axelia pasti dibuat seperti mecha Illumina...",
  ui_story_1018_10181201_65_dialog_content = "Menurutku Axelia bahkan lebih baik untuk menjadi sebaik baru sekarang dengan semua kerusakan yang dia alami.",
  ui_story_1018_10181201_66_dialog_content = "Bersiaplah untuk bertarung, PlayerName. Kita masih harus membunuh Eclipsite sebelum mencapai tujuan kita.",
  ui_story_1018_10181201_67_dialog_content = "Tentu, bukan masalah.",
  ui_story_1018_10181201_68_dialog_content = "Lalu, duduklah dengan tenang. Para penembak akan menembak para penyendiri seolah-olah mereka adalah Eclipsite.",
  ui_story_1018_10181201_69_dialog_content = "Mengerti...",
  ui_story_1018_10181201_70_dialog_content = "<color=#e8d9bb>Mendering-</color>",
  ui_story_1018_10181201_71_dialog_content = "Awas! Belok!",
  ui_story_1018_10181201_72_dialog_content = "Engine VII? Tiba-tiba muncul dari... parit!",
  ui_story_1018_10181201_73_dialog_content = "Itu yang rusak di Twilight...",
  ui_story_1018_10181201_74_dialog_content = "Tidak percaya ini dibawa ke sini... Tidak heran prajurit menghilang secara massal.",
  ui_story_1018_10181201_75_dialog_content = "Aum...",
  ui_story_1018_10181201_76_dialog_content = "Suara itu... Mungkin pilotnya masih memiliki sedikit kesadaran?",
  ui_story_1018_10181201_77_dialog_content = "Jangan mendekatinya—prajurit-prajurit merayap tepat di samping kakinya!",
  ui_story_1018_10181201_78_dialog_content = "Ada berapa banyak di dalam sana...?",
  ui_story_1018_10181201_79_dialog_content = "<color=#e8d9bb>Buzz...Krauk!</color>",
  ui_story_1018_10181201_80_dialog_content = "Jeda... Dia ragu-ragu...",
  ui_story_1018_10181201_81_dialog_content = "Grand Marshal, mungkin masih ada harapan untuk prajurit di dalam setelah semua ini. Axelia mencoba menyelamatkannya.",
  ui_story_1018_10181201_82_dialog_content = "Kamu pernah rusak dulu!",
  ui_story_1018_10181201_83_dialog_content = "Axelia telah rusak berkali-kali sebelum ini.",
  ui_story_1018_10181201_84_dialog_content = "Tapi Axelia mampu pulih setiap kali.",
  ui_story_1018_10181201_85_dialog_content = "Pilot di dalam adalah anggota skuad Axelia. Adalah tugas Axelia untuk melindungi mereka.",
  ui_story_1018_10181201_86_dialog_content = "...",
  ui_story_1018_10181201_87_dialog_content = "Roooooarrr!!!",
  ui_story_1018_10181201_88_dialog_content = "Tubuhnya telah menyatu sepenuhnya dengan mecha. Ini pasti sangat menyulitkan bagi pilot.",
  ui_story_1018_10181201_89_dialog_content = "Mecha juga merupakan bagian dari Axelia. Axelia tahu itu sangat berat baginya.",
  ui_story_1018_10181201_90_dialog_content = "Maaf mendengarnya, Axelia...",
  ui_story_1018_10181201_91_dialog_content = "Wrath, biarkan aku pergi bersama Axelia! Aku akan menyelamatkan para prajurit bersamanya!",
  ui_story_1018_10181201_92_dialog_content = "Sebagai Grand Marshal, ini adalah tugas saya untuk menghentikanmu, tetapi mengingat kasus ini...",
  ui_story_1018_10181201_93_dialog_content = "Leo, tolong alihkan perhatian Engine VII untuk kami!",
  ui_story_1018_10181201_94_dialog_content = "Bukan masalah.",
  ui_story_1018_10181201_95_dialog_content = "Wrath...?",
  ui_story_1018_10181201_96_dialog_content = "Aku tidak bisa membiarkan kalian berdua menghadapinya sendirian.",
  ui_story_1018_10181201_97_dialog_content = "Engine VII dulunya adalah perisai tentara di Twilight, tapi sekarang dia berada di pihak yang berlawanan.",
  ui_story_1018_10181201_98_dialog_content = "Dia harus melewati perisai ini untuk menyakiti kamu.",
  ui_story_1018_10181201_99_dialog_content = "Astaga!",
  ui_story_1018_10181201_100_dialog_content = "Oh tidak, prajurit-prajurit merangkak keluar dari parit...",
  ui_story_1018_10181201_101_dialog_content = "Mereka adalah bawahan dari Axelia.",
  ui_story_1018_10181201_102_dialog_content = "Dia tidak akan bisa lolos dengan menggunakan prajuritku untuk memperlambatku!",
  ui_story_1018_10181201_103_dialog_content = "Lakukan apa yang kamu inginkan, Axelia, dan selamatkan teman-temanmu! Aku akan mengurus prajurit-prajuritnya!",
  ui_story_1018_10181201_104_dialog_content = "Axelia salin.",
  ui_story_1018_10181202_1_dialog_content = "Para prajurit di sini sudah berhasil ditaklukkan tetapi masih sadar.",
  ui_story_1018_10181202_2_dialog_content = "Sama di sini juga. Hati-hati dengan tembakan dari Engine VII.",
  ui_story_1018_10181202_3_dialog_content = "Roooooarrr!!!",
  ui_story_1018_10181202_4_dialog_content = "Axelia tahu bahwa kamu sedang mengalami pengalaman yang sulit.",
  ui_story_1018_10181202_5_dialog_content = "Kamu tidak ingin menyakiti orang... Axelia tahu semua itu.",
  ui_story_1018_10181202_6_dialog_content = "Aum...",
  ui_story_1018_10181202_7_dialog_content = "Dia perlahan menjauh dari depan. Tidak ada musuh di sana.",
  ui_story_1018_10181202_8_dialog_content = "Ikuti dengan hati-hati! Setelah dia membersihkan parit, taklukkan dari belakang!",
  ui_story_1018_10181202_9_dialog_content = "Astaga!",
  ui_story_1018_10181202_10_dialog_content = "Aku harus membuat langkah!",
  ui_story_1018_10181202_11_dialog_content = "Minggir, Axelia!",
  ui_story_1018_10181202_12_dialog_content = "Tombak petir, tusuk!",
  ui_story_1018_10181202_13_dialog_content = "Aum...",
  ui_story_1018_10181202_14_dialog_content = "Dia berhenti! Tapi Axelia...",
  ui_story_1018_10181202_15_dialog_content = "Leo, Axelia sedang menuju ke arahmu!",
  ui_story_1018_10181202_16_dialog_content = "Hai—",
  ui_story_1018_10181202_17_dialog_content = "Jaraknya bukan masalah.",
  ui_story_1018_10181202_18_dialog_content = "Hai—",
  ui_story_1018_10181202_19_dialog_content = "<color=#e8d9bb>Meringkik—</color>",
  ui_story_1018_10181202_20_dialog_content = "Fiuh—",
  ui_story_1018_10181202_21_dialog_content = "Saya telah menyaksikan keberanian Anda lagi, Leo dari Twilight.",
  ui_story_1018_10181202_22_dialog_content = "Sedang apa kau di sini?",
  ui_story_1018_10181202_23_dialog_content = "Kerja bagus, Axelia.",
  ui_story_1018_10181202_24_dialog_content = "Marsekal Agung menangkap Axelia.",
  ui_story_1018_10181202_25_dialog_content = "Kamu telah melampaui versi dirimu saat pertandingan pameran. Kau seorang prajurit yang luar biasa.",
  ui_story_1018_10181202_26_dialog_content = "Axelia telah merenungkan apa yang dikatakan Grand Marshal...",
  ui_story_1018_10181202_27_dialog_content = "Axelia ingin bertanya kepada Grand Marshal, mengalahkan Eclipsite dan melindungi prajurit Illumina...",
  ui_story_1018_10181202_28_dialog_content = "Apakah itu termasuk \"Hidup sebagai pribadi\"?",
  ui_story_1018_10181202_29_dialog_content = "Kamu sudah di sana, Axelia.",
  ui_story_1018_10181202_30_dialog_content = "Terima kasih, Grand Marshal. Axelia akan terus berjuang.",
  ui_story_1018_10181202_31_dialog_content = "Kamu akan mendapatkan kesempatanmu, Axelia. Berikut teman-temanmu yang peduli padamu.",
  ui_story_1018_10181202_32_dialog_content = "Axelia! Senang akhirnya bisa menyusul...",
  ui_story_1018_10181202_33_dialog_content = "Yingel...",
  ui_story_1018_10181202_34_dialog_content = "Maaf! Aku tahu tentang ini, tapi tetap membiarkan kamu mengalaminya... Maaf!",
  ui_story_1018_10181202_35_dialog_content = "Axelia hanya tahu bahwa Yingel ingin melindungi Axelia.",
  ui_story_1018_10181202_36_dialog_content = "Senang sekali Axelia baik-baik saja! Bukankah saya bilang burung kecil yang baik hati pasti akan mendapatkan hadiah?",
  ui_story_1018_10181202_37_dialog_content = "Grand Marshal, Tech Officer Gronru dan Kolonel Yingel akan membawa para prajurit Illumina pulang!",
  ui_story_1018_10181202_38_dialog_content = "Tentu. Jaga para prajurit ini.",
  ui_story_1018_10181202_39_dialog_content = "Mengenai apa yang terjadi dalam penyelidikan itu, Marsekal Agung... Saya sangat menyesal.",
  ui_story_1018_10181202_40_dialog_content = "Juga, eksperimen Profesor Ulysses...",
  ui_story_1018_10181202_41_dialog_content = "Tapi percayalah, saya tidak akan pernah membela dia dalam masalah ini lagi. Saya tidak ingin melihat teman-teman yang tidak bersalah terluka.",
  ui_story_1018_10181202_42_dialog_content = "Izinkan saya membawa mereka kembali ke Illumina untuk pengobatan. Aku akan mencari solusi untuk masalah mereka...",
  ui_story_1018_10181202_43_dialog_content = "Kalian semua korban, tidak perlu merasa bersalah.",
  ui_story_1018_10181202_44_dialog_content = "Tapi aku membuatmu kehilangan kursi Marsekal Agung...",
  ui_story_1018_10181202_45_dialog_content = "Posisi itu bukan sesuatu yang bisa kamu ubah dengan kata-katamu.",
  ui_story_1018_10181202_46_dialog_content = "Terima kasih telah memberi kesempatan kepada saya untuk menjadi Grand Marshal.",
  ui_story_1018_10181202_47_dialog_content = "Kamu kembali, Wrath.",
  ui_story_1018_10181202_48_dialog_content = "Wow, dua Grand Marshal!",
  ui_story_1018_10181202_49_dialog_content = "Kutahu Wrath akan baik-baik saja!",
  ui_story_1018_10181202_50_dialog_content = "Kamu memang bersikap seperti Grand Marshal, harus kuakui.",
  ui_story_1018_10181202_51_dialog_content = "Itulah yang akan dilakukan oleh pertarungan sengit di Twilight pada Anda.",
  ui_story_1018_10181202_52_dialog_content = "Kami telah menunggumu di bagian depan.",
  ui_story_1018_10181202_53_dialog_content = "Aku berjanji akan menggantikanmu sementara sebagai Grand Marshal dan kembali dengan selamat. Aku tidak akan mengingkari kata-kataku.",
  ui_story_1018_10181202_54_dialog_content = "Grand Marshal dan keempat komandan, jangan bilang...",
  ui_story_1018_10181202_55_dialog_content = "...",
  ui_story_1018_10181202_56_dialog_content = "Aku telah berjuang demi suatu hasil, tapi sekarang aku juga telah membuktikan satu hal...",
  ui_story_1018_10181202_57_dialog_content = "Kamu benar-benar memenuhi syarat, Wrath.",
  ui_story_1018_10181202_58_dialog_content = "Tapi aku belum selesai...",
  ui_story_1018_10181202_59_dialog_content = "Kamu benar-benar memenuhi syarat.",
  ui_story_1018_10181202_60_dialog_content = "...",
  ui_story_1018_10181202_61_dialog_content = "Ahem, kamu pikir aku akan menerima apa yang baru saja kamu katakan?",
  ui_story_1018_10181202_62_dialog_content = "Jika saya tidak bisa mengalahkan Anda, saya tidak pantas menjadi Grand Marshal.",
  ui_story_1018_10181202_63_dialog_content = "Pertempuran belum berakhir, jadi kamu berikan perintah.",
  ui_story_1018_10181202_64_dialog_content = "...",
  ui_story_1018_10181202_65_dialog_content = "Kapten Wrath dari Pengawal Kerajaan berhasil memukul mundur Eclipsites dari Twilight.",
  ui_story_1018_10181202_66_dialog_content = "Legion Keempat Illumina telah berkumpul dan menunggu perintah dari Grand Marshal!",
  ui_story_1018_10181401_1_dialog_content = "Masih banyak waktu, tapi aku kira akan ada kawah besar di sini sekarang.",
  ui_story_1018_10181401_2_dialog_content = "Apa, kamu jadi sentimental karena berpisah dengannya?",
  ui_story_1018_10181401_3_dialog_content = "Itu konyol. Saya pikir kamu sudah selesai dengan urusanmu, itulah sebabnya kita tidak boleh buang waktu lagi.",
  ui_story_1018_10181401_4_dialog_content = "Ayo, saat yang kamu tunggu-tunggu akan tiba.",
  ui_story_1018_10181401_5_dialog_content = "Oke. Tapi sebelum kita pergi, aku masih ada beberapa hal yang harus dibersihkan.",
  ui_story_1018_10181401_6_dialog_content = "Saya tahu Forsakin. Dia tidak akan mengambil risiko melakukan semua ini kecuali jika itu menguntungkan eksperimennya.",
  ui_story_1018_10181401_7_dialog_content = "Belum lagi meninggalkan Helios di Gannon mungkin adalah sesuatu yang tidak ia duga.",
  ui_story_1018_10181401_8_dialog_content = "Itu berarti Forsakin menyelinap ke Undercity Illumina karena Ulysses berjanji untuk memberikan apa yang dia inginkan.",
  ui_story_1018_10181401_9_dialog_content = "Dan Ulysses mempermainkannya. Dia menambahkan Seeds ke Program Phospherus saat dia mendapatkannya.",
  ui_story_1018_10181401_10_dialog_content = "Itu pasti mungkin.",
  ui_story_1018_10181401_11_dialog_content = "Jadi inti Guardian One juga menjadi bagian dari tawar-menawar mereka?",
  ui_story_1018_10181401_12_dialog_content = "Ini bagian dari rencana Eclipse, tetapi masih belum jelas apakah itu termasuk dalam kesepakatan mereka.",
  ui_story_1018_10181401_13_dialog_content = "Saya lebih cenderung percaya bahwa pencurian inti itu bukan bagian dari rencana Ulysses.",
  ui_story_1018_10181401_14_dialog_content = "Komite tidak memiliki alasan untuk kehilangan inti kepada Eclipse demi Program Phospherus.",
  ui_story_1018_10181401_15_dialog_content = "Tidak hanya biayanya terlalu tinggi, tetapi bahkan jika prajurit yang ditanam dengan Benih berhasil, mereka tidak akan bisa bertempur dalam pertempuran di masa depan.",
  ui_story_1018_10181401_16_dialog_content = "Apa katamu?",
  ui_story_1018_10181401_17_dialog_content = "...",
  ui_story_1018_10181401_18_dialog_content = "...",
  ui_story_1018_10181401_19_dialog_content = "Kamu telah ditanamkan Seed...?",
  ui_story_1018_10181401_20_dialog_content = "Jadi apa? Aku masih baik-baik saja, bukan?",
  ui_story_1018_10181401_21_dialog_content = "...",
  ui_story_1018_10181401_22_dialog_content = "Aku melihat aku bersikeras menjadikanmu Grand Marshal hanya agar kamu mendapatkan implan...",
  ui_story_1018_10181401_23_dialog_content = "Ini tidak ada hubungannya denganmu. Itu keputusan saya.",
  ui_story_1018_10181401_24_dialog_content = "Seharusnya aku tidak...",
  ui_story_1018_10181401_25_dialog_content = "Tidak mungkin dia bisa sampai sekarang sendirian tanpa Benihku!",
  ui_story_1018_10181401_26_dialog_content = "Akhirnya menampakkan diri juga, Forsakin.",
  ui_story_1018_10181401_27_dialog_content = "Dasar sampah kotor!",
  ui_story_1018_10181401_28_dialog_content = "Forsakin, kau telah membuat prajuritku menderita. Sekarang saatnya mengakhiri ini!",
  ui_story_1018_10181401_29_dialog_content = "Tunggu, Wrath, ada prajurit di lumpur di belakangnya!",
  ui_story_1018_10181401_30_dialog_content = "Aum...",
  ui_story_1018_10181401_31_dialog_content = "Aku tak percaya dia sampai sebegini rendahnya...",
  ui_story_1018_10181401_32_dialog_content = "Kendalikan mereka dan jaga garisnya! Aku akan mengurus ini!",
  ui_story_1018_10181401_33_dialog_content = "Baik!",
  ui_story_1018_10181401_34_dialog_content = "Sangat bersemangat, ya. Apakah kamu tidak ingin tahu mengapa Seed di dalam dirimu tidak membuatmu terbalik?",
  ui_story_1018_10181401_35_dialog_content = "Atau sebenarnya kamu sangat menikmati membantai teman-temanmu dalam nafsu pembunuhan?",
  ui_story_1018_10181401_36_dialog_content = "Diam, Forsakin, kau yang menyakiti prajurit itu.",
  ui_story_1018_10181401_37_dialog_content = "...",
  ui_story_1018_10181401_38_dialog_content = "Jadi kaulah yang menyembuhkanku di lumpur itu...",
  ui_story_1018_10181401_39_dialog_content = "Kamu menyiksa prajurit-prajuritku, mendorongku hingga ke ujung... Semua untuk melihat bagaimana aku akan bereaksi dengan Seed di dalam tubuhku...",
  ui_story_1018_10181401_40_dialog_content = "Kurasa kamu tidak sebodoh yang kukira. Saya hanya membantu Ulysses secara kebetulan, karena dia gagal total sebagai ilmuwan.",
  ui_story_1018_10181401_41_dialog_content = "Apa yang dijanjikan Eclipse kepada Anda, Forsakin?",
  ui_story_1018_10181401_42_dialog_content = "Bagaimana kamu bisa memahami hal seperti itu? Kau pikir kau punya kekuatan untuk melindungi segalanya?",
  ui_story_1018_10181401_43_dialog_content = "Bahkan setelah diperbaiki sekalipun, Aurorian tetap saja sekelompok orang yang lemah secara fisik dan mental.",
  ui_story_1018_10181401_44_dialog_content = "Daripada digunakan dan dibuang oleh hierarki Illumina nanti, sebaiknya Anda mencari jalan keluar sekarang.",
  ui_story_1018_10181401_45_dialog_content = "Keselarasanmu dengan Eclipse membuatmu tidak lebih dari boneka Eclipsite sendiri.",
  ui_story_1018_10181401_46_dialog_content = "Kamu pikir kamu sangat pintar karena kamu berada dalam proyek Matahari Buatan.",
  ui_story_1018_10181401_47_dialog_content = "Tapi semua orang yang hadir, ditambah mereka yang jatuh di Twilight, berhasil sampai sejauh ini dengan kehendak mereka sendiri.",
  ui_story_1018_10181401_48_dialog_content = "Dibandingkan dengan mereka, kamu adalah orang bodoh yang sebenarnya.",
  ui_story_1018_10181401_49_dialog_content = "Kamu yang lemah dan rapuh!",
  ui_story_1018_10181401_50_dialog_content = "Diam, kau idiot! Kamu masih hidup hanya karena Seed-ku.",
  ui_story_1018_10181401_51_dialog_content = "Dunia bukan dongeng untuk anak berusia tiga tahun. Untuk bertahan hidup, seseorang harus terus naik tangga dengan segala cara.",
  ui_story_1018_10181401_52_dialog_content = "Kalian, Aurorian yang bodoh yang berkeliaran seperti kecoa, tak akan pernah tahu kebenaran, bahkan dalam kematian.",
  ui_story_1018_10181401_53_dialog_content = "Aku tahu kamu memiliki ambisi, Forsakin, tetapi aku tidak bisa membiarkanmu mengorbankan orang lain untuk mewujudkannya.",
  ui_story_1018_10181401_54_dialog_content = "Ini terakhir kali saya mengatakan ini kepada kamu—",
  ui_story_1018_10181401_55_dialog_content = "Kamu menyakiti rekanmu di Illumina, dan Illumina tidak akan mengampunimu. Tapi aku bukan Grand Marshal sekarang dan aku berharap kamu akan berhenti.",
  ui_story_1018_10181401_56_dialog_content = "Berhenti menuruti Eclipse. Itu bukan yang sebenarnya kamu inginkan.",
  ui_story_1018_10181401_57_dialog_content = "Kamu yang harus menjawab pada orang lain, Reinhardt! Kamu tidak bisa melindungi semua orang.",
  ui_story_1018_10181401_58_dialog_content = "Dan jangan mengasihaniku. Aku sudah berhenti ingin berada di pihakmu sejak lama.",
  ui_story_1018_10181401_59_dialog_content = "Kamu bisa mengejarku sepuasnya, tapi aku takkan pernah berhenti.",
  ui_story_1018_10181401_60_dialog_content = "<color=#e8d9bb>Berkeritik—</color>",
  ui_story_1018_10181401_61_dialog_content = "Ehem, apakah pidato perpisahan itu hadiahmu untuknya?",
  ui_story_1018_10181401_62_dialog_content = "Ambil ini, Wraith!",
  ui_story_1018_10181401_63_dialog_content = "Prajurit-prajurit sudah ditaklukkan, tetapi kemudian Wraith pun muncul.",
  ui_story_1018_10181401_64_dialog_content = "Kalau saja aku ingin, kamu pasti sudah mati sekarang.",
  ui_story_1018_10181401_65_dialog_content = "Terus berbicara dan mungkin saja saya berubah pikiran, Forsakin.",
  ui_story_1018_10181401_66_dialog_content = "Berhenti mengikuti Eclipse atau kamu akan kehilangan nyawamu karena itu, Forsakin.",
  ui_story_1018_10181401_67_dialog_content = "Itu urusanku. Yang harus kamu waspadai, Reinhardt, adalah aku yang akan membunuhmu.",
  ui_story_1018_10181401_68_dialog_content = "<color=#e8d9bb>Berkeritik—</color>",
  ui_story_1018_10181401_69_dialog_content = "Seed di dalamku sedang bergetar sedikit... Hati-hati, ada musuh di dekat sini!",
  ui_story_1018_10181401_70_dialog_content = "*Muntah*",
  ui_story_1018_10181401_71_dialog_content = "Astaga!",
  ui_story_1018_10181401_72_dialog_content = "Ini meludahkan mereka yang diambil dari Twilight oleh Forsakin...",
  ui_story_1018_10181401_73_dialog_content = "Astaga!",
  ui_story_1018_10181401_74_dialog_content = "Bukankah mecha itu sudah dikalahkan? Sekarang bangkit lagi!",
  ui_story_1018_10181401_75_dialog_content = "Aku melihat bahwa Forsakin memiliki rencana cadangan.",
  ui_story_1018_10181401_76_dialog_content = "Parit-parit itu penuh dengan lumpur, di mana mecha yang kalah telah terbaring sepanjang waktu ini.",
  ui_story_1018_10181401_77_dialog_content = "Kini Eclipsite rawa-rawa telah muncul kembali, ia tidak akan mudah dikalahkan...",
  ui_story_1018_10181401_78_dialog_content = "Apa yang harus kita lakukan sekarang, Grand Marshal?",
  ui_story_1018_10181401_79_dialog_content = "...",
  ui_story_1018_10181401_80_dialog_content = "...",
  ui_story_1018_10181401_81_dialog_content = "Ini salahku bahwa prajurit-prajuritku tidak bisa beristirahat dengan tenang...",
  ui_story_1018_10181401_82_dialog_content = "Aku bersumpah akan mengambil jasad mereka, dengan cara apa pun!",
  ui_story_1018_10181401_83_dialog_content = "Tapi Forsakin baru saja melukaimu...",
  ui_story_1018_10181401_84_dialog_content = "Aku tahu batasku. Aku akan menahan diri untuk tidak menggunakan kekuatan itu.",
  ui_story_1018_10181401_85_dialog_content = "Aku akan langsung menyerang jantung dan menghancurkannya!",
  ui_story_1018_10181401_86_dialog_content = "Aku akan menyerang bersamamu, Wrath. Serahkan prajurit yang menggila padaku.",
  ui_story_1018_10181401_87_dialog_content = "Kita akan pertahankan garis ini!",
  ui_story_1018_10181401_88_dialog_content = "Ya!",
  ui_story_1018_10181401_89_dialog_content = "Marsekal Agung—",
  ui_story_1018_10181401_90_dialog_content = "Bagaimana bisa kamu...",
  ui_story_1018_10181401_91_dialog_content = "Para Skyriders Lumo akan memberikan perlindungan. Eclipsite tidak akan menyentuh kamu.",
  ui_story_1018_10181401_92_dialog_content = "Saya sangat mengenal strategi Grand Marshal. Ksatria Twilight akan melengkapi serangan tersebut.",
  ui_story_1018_10181401_93_dialog_content = "Dan aku juga, Wrath, akan membantumu dalam pertarungan!",
  ui_story_1018_10181401_94_dialog_content = "Demi White Night... Sungguh koalisi multi-faksi yang kita miliki!",
  ui_story_1018_10181401_95_dialog_content = "Kalau begitu, mari kita jalankan peran masing-masing dan berkumpul kembali setelah menghancurkan musuh!",
  ui_story_1018_10181401_96_dialog_content = "Apa pendapatmu, Reinhardt?",
  ui_story_1018_10181401_97_dialog_content = "Tidak peduli apa pun, jangan pernah tinggalkan teman-teman Illumina!",
  ui_story_1018_10181501_1_dialog_content = "<color=#e8d9bb>Tik-tik-tik...</color>",
  ui_story_1018_10181501_2_dialog_content = "Hei, lagi hujan nih...",
  ui_story_1018_10181501_3_dialog_content = "Ini agak tidak biasa.",
  ui_story_1018_10181501_4_dialog_content = "Tak ada tanda-tanda Eclipsite di mana pun, Grand Marshal.",
  ui_story_1018_10181501_5_dialog_content = "Unit-unit Lumopolis menuju ke jalur timur dan barat.",
  ui_story_1018_10181501_6_dialog_content = "Di tempatku baik-baik saja. Lumpur mulai surut dan semuanya berjalan lancar!",
  ui_story_1018_10181501_7_dialog_content = "Wrath memang tahu cara bertarung!",
  ui_story_1018_10181501_8_dialog_content = "Bisakah hujan menyebabkan lumpur surut?",
  ui_story_1018_10181501_9_dialog_content = "Aku tidak menyadari itu. Mungkin ini benar-benar berakhir sekarang...",
  ui_story_1018_10181501_10_dialog_content = "Kamu bangun. Merasa baik-baik saja?",
  ui_story_1018_10181501_11_dialog_content = "Aku sudah terjaga, hanya memikirkan apa yang kamu katakan padaku sebelumnya...",
  ui_story_1018_10181501_12_dialog_content = "<color=#e8d9bb>Sebelum Wrath berangkat untuk mencari Ulysses...</color>",
  ui_story_1018_10181501_13_dialog_content = "Berapa lama kamu akan tinggal di sana?",
  ui_story_1018_10181501_14_dialog_content = "Apa lagi yang ingin dikatakan? Kamu dengar pertanyaannya—",
  ui_story_1018_10181501_15_dialog_content = "Reinhardt!",
  ui_story_1018_10181501_16_dialog_content = "Apakah kamu pikir aku akan terjebak dengan sesuatu yang bodoh seperti kamu bersekongkol dengan musuh?",
  ui_story_1018_10181501_17_dialog_content = "...",
  ui_story_1018_10181501_18_dialog_content = "Apakah kamu sependiam ini saat mendaftar untuk Artificial Sun?",
  ui_story_1018_10181501_19_dialog_content = "Ketahuan, ya.",
  ui_story_1018_10181501_20_dialog_content = "Kamu menjalani modifikasi. Apakah itu cara kamu bisa mengalahkan saya dalam duel?",
  ui_story_1018_10181501_21_dialog_content = "...",
  ui_story_1018_10181501_22_dialog_content = "Jawab aku!",
  ui_story_1018_10181501_23_dialog_content = "Banyak hal yang tidak semudah yang kamu kira. Berhenti bertanya, demi kebaikan Illumina.",
  ui_story_1018_10181501_24_dialog_content = "Sebagai Grand Marshal yang terhormat, kamu bisa—",
  ui_story_1018_10181501_25_dialog_content = "Itulah mengapa aku harus menerima hasil ini.",
  ui_story_1018_10181501_26_dialog_content = "...",
  ui_story_1018_10181501_27_dialog_content = "Lepaskan kepalan tanganmu jika kamu sudah mengerti. Ini bukan saatnya untuk berkelahi denganku.",
  ui_story_1018_10181501_28_dialog_content = "...",
  ui_story_1018_10181501_29_dialog_content = "Masa depanmu ada di telapak tanganmu.",
  ui_story_1018_10181501_30_dialog_content = "Menjaganya tergulung dan kamu akan berakhir dengan tidak ada apa-apa.",
  ui_story_1018_10181501_31_dialog_content = "\"Menjaganya terus meringkuk dan kita akan berakhir tanpa apa-apa.\"",
  ui_story_1018_10181501_32_dialog_content = "Kenapa aku jadi ingat itu sekarang...",
  ui_story_1018_10181501_33_dialog_content = "Ini karena saatnya kita mengayunkan tinju kita pada musuh bersama.",
  ui_story_1018_10181501_34_dialog_content = "Kepulan tinju harus diarahkan pada musuh bersama.",
  ui_story_1018_10181501_35_dialog_content = "...",
  ui_story_1018_10181501_36_dialog_content = "Percayalah padaku, kamu akan menyadari kekuatan yang aku miliki.",
  ui_story_1018_10181501_37_dialog_content = "Apakah ini semua bagian dari rencanamu?",
  ui_story_1018_10181501_38_dialog_content = "...",
  ui_story_1018_10181501_39_dialog_content = "Apakah kamu siap untuk membiarkan aku melakukan apa pun yang diperlukan...?",
  ui_story_1018_10181501_40_dialog_content = "...",
  ui_story_1018_10181501_41_dialog_content = "Aku paham.",
  ui_story_1018_10181501_42_dialog_content = "Aku akan menggantikanmu sebagai Grand Marshal.",
  ui_story_1018_10181501_43_dialog_content = "Tapi akan tiba saatnya di mana kau adalah satu-satunya lawanku.",
  ui_story_1018_10181501_44_dialog_content = "Namun sebelum itu, kita akan mengayunkan tinju kita dan mengalahkan musuh bersama kita.",
  ui_story_1018_10181501_45_dialog_content = "Wrath.",
  ui_story_1018_10181501_46_dialog_content = "Hah?",
  ui_story_1018_10181501_47_dialog_content = "Lakukan apa saja yang diperlukan, tapi pastikan kamu kembali dengan selamat.",
  ui_story_1018_10181501_48_dialog_content = "...",
  ui_story_1018_10181501_49_dialog_content = "<color=#e8d9bb>Tik-tik-tik...</color>",
  ui_story_1018_10181501_50_dialog_content = "Aku berhasil kembali dengan selamat, tapi para prajurit... Mereka sudah tak bisa ditolong, bukan?",
  ui_story_1018_10181501_51_dialog_content = "Mereka berhasil bertahan sampai sekarang.",
  ui_story_1018_10181501_52_dialog_content = "Mereka adalah pejuang sejati. Illumina akan memberikan penghormatan yang layak kepada mereka.",
  ui_story_1018_10181501_53_dialog_content = "Aku gagal menyelamatkan mereka di Twilight... Lalu aku harus membunuh mereka lagi seolah-olah mereka adalah musuh...",
  ui_story_1018_10181501_54_dialog_content = "Kegagalan lain...",
  ui_story_1018_10181501_55_dialog_content = "Meskipun aku menjadi Grand Marshal, aku tetap ditakdirkan untuk gagal.",
  ui_story_1018_10181501_56_dialog_content = "Kamu tidak gagal, Wrath. Kamu memimpin semua orang dalam menyelamatkan Twilight dan mempertahankan garis pertahanan.",
  ui_story_1018_10181501_57_dialog_content = "Hujannya benar-benar deras. Ayo kita kembali.",
  ui_story_1018_10181501_58_dialog_content = "...",
  ui_story_1018_10181501_59_dialog_content = "Ayo kembali. Ramalan cuaca mengatakan cuaca buruk hari ini. Mungkin sedang hujan di permukaan.",
  ui_story_1018_10181501_60_dialog_content = "<color=#e8d9bb>Mendering-</color>",
  ui_story_1018_10181501_61_dialog_content = "Heh... Reinhardt...",
  ui_story_1018_10181501_62_dialog_content = "Tentang apa kamu tertawa?",
  ui_story_1018_10181501_63_dialog_content = "Apakah seorang Grand Marshal ditakdirkan untuk merasakan keputusasaan seperti itu kapan saja?",
  ui_story_1018_10181501_64_dialog_content = "Ketika aku menutup mata, aku bisa melihat para pejuang yang mengorbankan diri mereka di Twilight...",
  ui_story_1018_10181501_65_dialog_content = "Untuk mencegah berubah menjadi Eclipsite dan melukai orang, mereka memilih untuk menembak otak mereka sendiri...",
  ui_story_1018_10181501_66_dialog_content = "Axelia mengalami kerusakan berkali-kali, namun bangkit setelah setiap kerusakan hanya untuk menyelamatkan skuadnya...",
  ui_story_1018_10181501_67_dialog_content = "Lalu ada orang itu, yang sangat ingin kembali ke Illumina dengan secercah kewarasan terakhirnya...",
  ui_story_1018_10181501_68_dialog_content = "Kita semua ingin memenangkan perang, tetapi itu menuntut biaya yang sangat besar...",
  ui_story_1018_10181501_69_dialog_content = "Kamu pasti telah melalui skenario serupa tak terhitung kali...",
  ui_story_1018_10181501_70_dialog_content = "Tapi dalam semua tahunmu sebagai Grand Marshal, aku tidak pernah melihat sedikit pun penyesalan dalam dirimu.",
  ui_story_1018_10181501_71_dialog_content = "Kamu bahkan mengalah di medan perang untuk melindungi Axelia.",
  ui_story_1018_10181501_72_dialog_content = "Dan dilemparkan ke dalam sel dengan nasib yang ditentukan oleh orang lain, hanya demi masa depan Illumina.",
  ui_story_1018_10181501_73_dialog_content = "Hanya kamu yang bisa melakukan semua itu, Reinhardt.",
  ui_story_1018_10181501_74_dialog_content = "...",
  ui_story_1018_10181501_75_dialog_content = "Grand Marshal adalah sumpah, keyakinan, payung... Seseorang yang tidak bisa mati dan harus terus meratapi orang lain.",
  ui_story_1018_10181501_76_dialog_content = "Grand Marshal adalah seseorang yang melindungi rakyat dengan darah dan dagingnya sendiri.",
  ui_story_1018_10181501_77_dialog_content = "Hanya aku yang bisa melakukannya? Yah, kamu bertahan hingga sekarang untuk menjaga Illumina sendiri.",
  ui_story_1018_10181501_78_dialog_content = "Apakah itu benar...",
  ui_story_1018_10181501_79_dialog_content = "<color=#e8d9bb>Hujan membilas tanah yang berlumpur sementara cahaya redup menembus lapisan awan yang jauh.</color>",
  ui_story_1018_10181501_80_dialog_content = "<color=#e8d9bb>Bahu Wrath terlihat ramping, tetapi saat ia berdiri teguh dan kuat dalam permainan cahaya dan bayangan, kontur tubuhnya menjadi lebih tajam dan tegak lurus.</color>",
  ui_story_1018_10181501_81_dialog_content = "Tapi aku yakin sekarang aku tidak ingin menjadi Grand Marshal lagi...",
  ui_story_1018_10181501_82_dialog_content = "Kamu telah memikul beban untukku saat krisis. Sekarang saatnya aku melanjutkan tugas itu.",
  ui_story_1018_10181501_83_dialog_content = "Masalah yang muncul sama sulitnya, tapi percayalah, aku akan menghilangkan semua musuh di dalam.",
  ui_story_1018_10181501_84_dialog_content = "Bagaimana rencana Anda untuk menghadapi Komite?",
  ui_story_1018_10181501_85_dialog_content = "Kami mengendalikan militer, Grand Marshal. Berikan saja kata-kata dan saya akan menghancurkan hari mereka!",
  ui_story_1018_10181501_86_dialog_content = "Fakta bahwa aku di sini untuk bertarung berarti kita memiliki persetujuan diam-diam dari Komite.",
  ui_story_1018_10181501_87_dialog_content = "Mereka tidak terburu-buru menjalankan Program Phospherus hanya untuk Twilight.",
  ui_story_1018_10181501_88_dialog_content = "Dengan meluapnya Darkover dan pencurian inti Guardian One, apa yang dikerjakan Eclipse menjadi masalah terbesar.",
  ui_story_1018_10181501_89_dialog_content = "Mereka tidak akan memasukkanmu kembali ke sel jika kamu kembali ke Gannon, bukan?",
  ui_story_1018_10181501_90_dialog_content = "Apa yang terjadi pada prajurit akan membuat Ulysses dipanggil untuk pertanggungjawaban.",
  ui_story_1018_10181501_91_dialog_content = "Bagaimanapun caranya, Belisaria dihormati. Mereka akan membuat keputusan yang tepat mengenai saya.",
  ui_story_1018_10181501_92_dialog_content = "Mengenai Eclipse, kami telah mengirim dua regu ke Zona Gelap, Grand Marshal.",
  ui_story_1018_10181501_93_dialog_content = "Saya tidak tahu apa rencana Komite itu, tetapi saya pikir Charon dan Vice memerlukan bantuan kita.",
  ui_story_1018_10181501_94_dialog_content = "Itu benar... Mereka sempat bertemu denganku sebentar, dan saat ini kondisi mereka memang sedang tidak baik...",
  ui_story_1018_10181501_95_dialog_content = "Apa yang akan kamu lakukan, PlayerName?",
  ui_story_1018_10181501_96_dialog_content = "Masih ada pengungsi Twilight di Eraveil, jadi saya akan kembali dengan Leo untuk membantu.",
  ui_story_1018_10181501_97_dialog_content = "Tapi aku juga sangat khawatir tentang Vice dan yang lainnya...",
  ui_story_1018_10181501_98_dialog_content = "Saya tidak akan membiarkan mereka terluka, PlayerName, saya bisa menjanjikan itu kepada Anda.",
  ui_story_1018_10181501_99_dialog_content = "Tidak peduli apa jenis pukulan yang mungkin diberikan oleh Komite nanti, saya akan mengutamakan mencari mereka.",
  ui_story_1018_10181501_100_dialog_content = "Maka saya akan menangani masalah di Twilight. Setelah bertarung berdampingan Leo untuk waktu yang lama, saya ingin Illumina memberikan harapan kepada kota itu.",
  ui_story_1018_10181501_101_dialog_content = "Dan jangan lupa untuk segera mendapatkan perawatan...",
  ui_story_1018_10181501_102_dialog_content = "Mengerti. Aku akan menghubungi kamu jika tidak ada pilihan lain.",
  ui_story_1018_10181501_103_dialog_content = "Tentu, jika saya bisa membantu.",
  ui_story_1018_10181501_104_dialog_content = "<color=#e8d9bb>*Statis*</color>",
  ui_story_1018_10181501_105_dialog_content = "Seluruh hal ini berubah menjadi pertunjukan yang hebat, tidak, komedi. Dan penulis naskah kita Ulysses bahkan tidak memiliki keberanian untuk hadir dalam pertemuan hari ini.",
  ui_story_1018_10181501_106_dialog_content = "Bagaimana Anda berencana untuk mengakhiri ini?",
  ui_story_1018_10181501_107_dialog_content = "Bukan waktunya mengakhiri ini.",
  ui_story_1018_10181501_108_dialog_content = "Apa kamu bercanda? Dua Grand Marshal Illumina baru saja meraih kemenangan besar di medan perang.",
  ui_story_1018_10181501_109_dialog_content = "Apakah kamu benar-benar berpikir mereka akan merayu kamu untuk negosiasi damai?",
  ui_story_1018_10181501_110_dialog_content = "Kamu pikir aku tidak tahu Reinhardt keluar dari sel Illumina?",
  ui_story_1018_10181501_111_dialog_content = "Belum saatnya bukti kunci muncul. Bagaimana perkembangannya tergantung pada sikap mereka.",
  ui_story_1018_10181501_112_dialog_content = "Gerakan klasik Belisaria, tidak pernah meninggalkan sesuatu tanpa rencana cadangan.",
  ui_story_1018_10181501_113_dialog_content = "Namun, pertempuran di garis pertahanan ini bukan hanya pertempuran kecil—seluruh benua Astra sedang menyaksikannya.",
  ui_story_1018_10181501_114_dialog_content = "Benar, mereka semua sedang menonton, dan semoga saja semakin dekat.",
  ui_story_1018_10181501_115_dialog_content = "Jika Krisis Darkover memang terjadi, sejauh mana setiap faksi akan melangkah?",
  ui_story_1018_10181501_116_dialog_content = "Kamu mendukung rencana Ulysses untuk membuat Lumopolis akhirnya membuka kartunya, ya?",
  ui_story_1018_10181501_117_dialog_content = "Itu salah satu bagian, ya.",
  ui_story_1018_10181501_118_dialog_content = "Baik di Twilight maupun di garis depan, kalian semua melihat bahwa kita masih menjadi ancaman bagi Eclipsites.",
  ui_story_1018_10181501_119_dialog_content = "Dan mereka bahkan menunjukkan kartu lubang mereka.",
  ui_story_1018_10181501_120_dialog_content = "Maksudmu gadis itu?",
  ui_story_1018_10181501_121_dialog_content = "Ya, tapi itu pasti bukan semuanya.",
  ui_story_1018_10181501_122_dialog_content = "Siapa yang menyangka? Inilah \"latihan militer\" yang kamu, Belisaria, harapkan untuk diikuti.",
  ui_story_1018_10181501_123_dialog_content = "Mari kita tunda dulu hal lainnya. Mengingat biaya yang sangat besar, apakah kamu sudah mempertimbangkan konsekuensinya?",
  ui_story_1018_10181501_124_dialog_content = "Aku bersedia mendengarkan siapa pun yang punya rencana yang lebih baik.",
  ui_story_1018_10181501_125_dialog_content = "Senjata untuk Eclipse kali ini masih benih Forsakin, tetapi setidaknya sekarang kita juga memilikinya.",
  ui_story_1018_10181501_126_dialog_content = "Itulah mengapa saya mendukung Ulysses.",
  ui_story_1018_10181501_127_dialog_content = "Di masa depan, kita harus merebut semua senjata yang berpotensi menghancurkan kita.",
  ui_story_1018_10181501_128_dialog_content = "Apakah mereka berasal dari Lumopolis atau Northland, bahkan sekte radikal sekalipun.",
  ui_story_1018_10181501_129_dialog_content = "Inti dari Guardian One telah dicuri, dan kekhawatiran terbesar Anda adalah keseimbangan antara faksi-faksi ini?",
  ui_story_1018_10181501_130_dialog_content = "Tidak ada prioritas. Terjepit dari segala sisi adalah situasi sulit yang dihadapi Illumina saat ini.",
  ui_story_1018_10181501_131_dialog_content = "Insinyur yang meninggalkan Illumina tidak hanya dikritik oleh Lumopolis saja.",
  ui_story_1018_10181501_132_dialog_content = "Mengingat situasinya, kita mungkin perlu mengubah arah dan menunjukkan kepada semua orang siapa sebenarnya Sang Insinyur.",
  ui_story_1018_10181501_133_dialog_content = "Kau yakin?",
  ui_story_1018_10181501_134_dialog_content = "Berita dari Tim Rekonesansi Dark Zone sesuai dengan yang diharapkan.",
  ui_story_1018_10181501_135_dialog_content = "Inti dari Guardian One adalah bagian terakhir yang tepat untuk kebangkitan kembali The Engineer.",
  ui_story_1018_10181501_136_dialog_content = "Karena kampanye di garis depan telah berakhir, Insinyur seharusnya segera bangun.",
  ui_story_1018_10181501_137_dialog_content = "...",
  ui_story_1018_10181501_138_dialog_content = "Sang Insinyur, Penguasa Kota Gannon yang pertama dan sejati.",
  ui_story_1018_10181501_139_dialog_content = "Jika sesuatu yang se-antik itu benar-benar terbangun, well... Saya agak menantikannya.",
  ui_story_1018_10181501_140_dialog_content = "Heh, bahkan lebih untuk saya.",
  ui_story_1018_10181501_141_dialog_content = "*Statis*",
  ui_story_1018_10181501_142_dialog_content = "Lagi?",
  ui_story_1018_10181501_143_dialog_content = "Tidak... Aku...",
  ui_story_1018_10181501_144_dialog_content = "Sepertinya... Mesin...",
  ui_story_1018_10181501_145_dialog_content = "Telah terbangun...",
  ui_story_1019_10190101_1_dialog_content = "<color=#e8d9bb>Ngungg...</color>",
  ui_story_1019_10190101_2_dialog_content = "Ya, Seed bukanlah meningkatkan kemampuan, tapi mengubahnya.",
  ui_story_1019_10190101_3_dialog_content = "Jadi, meskipun akses intinya telah diduplikasi, Darkflow masih bisa merusak di rawa-rawa...",
  ui_story_1019_10190101_4_dialog_content = "Ha... Bagaimana bisa kau terpikirkan hal ini?",
  ui_story_1019_10190101_5_dialog_content = "(Batuk kering)",
  ui_story_1019_10190101_6_dialog_content = "Seharusnya ada di sekitar sini di suatu tempat...",
  ui_story_1019_10190101_7_dialog_content = "... Tetapi hasil ini pasti layak bagi subjek yang mati di Twilight.",
  ui_story_1019_10190101_8_dialog_content = "<color=#e8d9bb>Dentang-</color>",
  ui_story_1019_10190101_9_dialog_content = "Tiga pil terakhir...",
  ui_story_1019_10190101_10_dialog_content = "Empat puluh tahun penelitian, dan dua puluh tahun dari itu dihabiskan untuk mengkompilasi <color=#FFB400>database gen spesial</color>... Aku sudah berusaha semampuku.",
  ui_story_1019_10190101_11_dialog_content = "Tapi, mengapa aku masih merasa pahit dan tidak terpenuhi?",
  ui_story_1019_10190101_12_dialog_content = "Saya tidak begitu puas dengan hasilnya, <color=#FFB400>Robby</color>...",
  ui_story_1019_10190101_13_dialog_content = "<color=#e8d9bb>Desir... Desir...</color>",
  ui_story_1019_10190101_14_dialog_content = "Betapa kencangnya angin ini...",
  ui_story_1019_10190101_15_dialog_content = "Tunggu, kenapa aku berada di awan?",
  ui_story_1019_10190101_16_dialog_content = "Ketidakberatanku ini terasa familiar... Aku tidak jatuh lagi, bukan?!",
  ui_story_1019_10190101_17_dialog_content = "Harus tetap tenang! Soroz akan menangkap saya.",
  ui_story_1019_10190101_18_dialog_content = "Apakah kamu memanggilku, Navigator?",
  ui_story_1019_10190101_19_dialog_content = "Terbangmu hari ini cocok dengan perasaan perutku yang kacau belakangan ini. Kemana kita pergi?",
  ui_story_1019_10190101_20_dialog_content = "Kita menuju ke <color=#FFB400>Spire Battlefield</color> untuk misi airdrop.",
  ui_story_1019_10190101_21_dialog_content = "... Sebuah misi airdrop? Untuk siapa?",
  ui_story_1019_10190101_22_dialog_content = "Berikut ini adalah instruksi tempur yang telah disiarkan ke semua navigator:",
  ui_story_1019_10190101_23_dialog_content = "\"Semua Navigator, silakan menuju Medan Tempur Spire untuk menurunkan senjata Anda.\"",
  ui_story_1019_10190101_24_dialog_content = "Kecepatan dikurangi untuk pendaratan akhir. Menunggu perintah, Navigator. Harap pastikan pendaratan senjata dengan aman.",
  ui_story_1019_10190101_25_dialog_content = "H-Tunggu sebentar, apa yang kau bicarakan?!",
  ui_story_1019_10190101_26_dialog_content = "Soroz? Soroz...!",
  ui_story_1019_10190101_27_dialog_content = "Ahhhhhhhh!!!",
  ui_story_1019_10190101_28_dialog_content = "Roaaarrrr!",
  ui_story_1019_10190101_29_dialog_content = "Dari mana datangnya Eclipsite ini?! Kenapa... saya jatuh bersama Eclipsite?!",
  ui_story_1019_10190101_30_dialog_content = "Soroz! Ada apa?!",
  ui_story_1019_10190101_31_dialog_content = "Navigator, tolong pastikan semua senjata mendarat dengan selamat. Ini adalah tugas Anda sebagai Caelestite.",
  ui_story_1019_10190101_32_dialog_content = "Roaaarrrr!",
  ui_story_1019_10190101_33_dialog_content = "Omong kosong... I-Ini pasti mimpi!",
  ui_story_1019_10190101_34_dialog_content = "Navigator, kamu tidak sedang bermimpi.",
  ui_story_1019_10190101_35_dialog_content = "Koordinat mengkonfirmasi ini adalah Medan Perang Spire. Harap pastikan semua senjata mendarat dengan aman.",
  ui_story_1019_10190101_36_dialog_content = "Menara...? Tapi ini adalah Eraveil! Saya mengenali Obelisk of Return yang tinggi itu!",
  ui_story_1019_10190101_37_dialog_content = "Apakah itu... Caelestite yang berlarian di mana-mana di tanah? Atau apakah mereka...",
  ui_story_1019_10190101_38_dialog_content = "Ini adalah mimpi. Ini pasti mimpi! Mungkin aku akan bangun setelah jatuh ke tanah...",
  ui_story_1019_10190101_39_dialog_content = "Persetan dengan ini!",
  ui_story_1019_10190101_40_dialog_content = "...",
  ui_story_1019_10190101_41_dialog_content = "... Aku masih di udara...",
  ui_story_1019_10190101_42_dialog_content = "Ketika kamu menyerah pada jatuh yang tak terhindarkan, entah mengapa perjalanan turunnya menjadi sangat panjang...",
  ui_story_1019_10190101_43_dialog_content = "<color=#e8d9bb>Ledakan-!!!</color>",
  ui_story_1019_10190101_44_dialog_content = "Aah—!",
  ui_story_1019_10190101_45_dialog_content = "...",
  ui_story_1019_10190101_46_dialog_content = "Apakah kamu sudah bangun sekarang?",
  ui_story_1019_10190101_47_dialog_content = "White Night di atas, kami telah tiba dengan selamat.",
  ui_story_1019_10190101_48_dialog_content = "Leo... Joselyne? Di mana kita...?",
  ui_story_1019_10190101_49_dialog_content = "Kembali di Eraveil.",
  ui_story_1019_10190101_50_dialog_content = "Pesawat itu bergoyang begitu keras sehingga para prajurit hampir tidak bisa berdiri, namun kamu malah tertidur pulas...",
  ui_story_1019_10190101_51_dialog_content = "Eraveil...",
  ui_story_1019_10190101_52_dialog_content = "Benar... ya, ini Eraveil...",
  ui_story_1019_10190101_53_dialog_content = "Setelah kampanye di Senja dan di garis pertahanan Illumina, kami naik pesawat Lumopolis kembali ke Eraveil...",
  ui_story_1019_10190101_54_dialog_content = "Jadi, ini semua hanya mimpi... Fyuh!",
  ui_story_1019_10190101_55_dialog_content = "Kamu yakin baik-baik saja, berlarian seperti ini?",
  ui_story_1019_10190101_56_dialog_content = "Saya baik-baik saja! Ini luar biasa, Leo!",
  ui_story_1019_10190101_57_dialog_content = "Ketidakberatannya terasa begitu nyata, seperti menghidupkan kembali sebuah kenangan...",
  ui_story_1019_10190101_58_dialog_content = "Tapi itu hanya mimpi... Syukurlah itu hanya mimpi!",
  ui_story_1019_10190101_59_dialog_content = "Uh, kau bisa melepaskanku sekarang...",
  ui_story_1019_10190101_60_dialog_content = "<color=#e8d9bb>(Berpelukan)</color>",
  ui_story_1019_10190101_61_dialog_content = "Sepatuku kotor, PlayerName. Kamu mungkin tidak seharusnya menginjaknya.",
  ui_story_1019_10190101_62_dialog_content = "Oh, maaf... Tapi, kurasa bukan aku...",
  ui_story_1019_10190101_63_dialog_content = "Chubb... Chubb...",
  ui_story_1019_10190101_64_dialog_content = "Apa benda putih berbentuk kubus ini, dan mengapa ia menempel di sepatu botku?",
  ui_story_1019_10190101_65_dialog_content = "Itu Chubb, temanku dari Eraveil. Tapi kenapa tampaknya mabuk?",
  ui_story_1019_10190101_66_dialog_content = "Chubb... (Sendawa)",
  ui_story_1019_10190101_67_dialog_content = "Hei! Kapten Leo! Lady Saintess! Caelestite!",
  ui_story_1019_10190101_68_dialog_content = "Akhirnya, kamu kembali!",
  ui_story_1019_10190101_69_dialog_content = "Ketika para pria mendengar bahwa kamu telah mengusir para Eclipsite dari Twilight, mereka langsung mulai kembali!",
  ui_story_1019_10190101_70_dialog_content = "Para wanita dari tempat pembuatan bir dan saya telah mempersiapkan makanan dan anggur untuk memberi hadiah kepada semua prajurit!",
  ui_story_1019_10190101_71_dialog_content = "Meskipun anggur ini belum difermentasi dalam waktu yang lama, buah Eraveil yang digunakan untuk membuatnya memberikan rasa yang unik.",
  ui_story_1019_10190101_72_dialog_content = "Jadi Chubb punya anggur buah...",
  ui_story_1019_10190101_73_dialog_content = "Caelestite, apakah Grand Marshal Wrath baik-baik saja? Kenapa saya tidak melihatnya?",
  ui_story_1019_10190101_74_dialog_content = "Wrath lebih kurang baik, tetapi dia masih harus kembali ke Illumina untuk beristirahat.",
  ui_story_1019_10190101_75_dialog_content = "Itu kabar yang bagus! Saya benar-benar ingin berterima kasih secara pribadi kepada semua prajurit yang mempertahankan Twilight.",
  ui_story_1019_10190101_76_dialog_content = "Oh, benar, Caelestite. Terima kasih sudah menerima kami!",
  ui_story_1019_10190101_77_dialog_content = "Kami tidak punya banyak hal untuk dilakukan di sini, jadi kami memberi makan ikan, membuat anggur, dan menghilangkan hama dari pohon buah...",
  ui_story_1019_10190101_78_dialog_content = "Saya membersihkan kamarku setiap hari! Plus, bendera yang tergantung di atas pohon-pohon dirancang khusus untuk menyambutmu dan semua kesatria untuk kembalinya kalian dengan kemenangan...",
  ui_story_1019_10190101_79_dialog_content = "Kalian sudah melakukan banyak hal...",
  ui_story_1019_10190101_80_dialog_content = "Harap terima niat baik kami sebagai ucapan terima kasih karena telah menerima kami di sini di Eraveil!",
  ui_story_1019_10190101_81_dialog_content = "Seharusnya aku yang berterima kasih padamu! Eraveil belum pernah sepadat ini...",
  ui_story_1019_10190101_82_dialog_content = "Anda dapat tinggal di Eraveil selama yang Anda inginkan.",
  ui_story_1019_10190101_83_dialog_content = "Nah, itu tentu berarti lebih sedikit anggur murni di Twilight.",
  ui_story_1019_10190101_84_dialog_content = "Malam Putih di atas. Terima kasih atas semua yang telah kau lakukan untuk Twilight, PlayerName.",
  ui_story_1019_10190101_85_dialog_content = "Chubb! Ch... Belek! Nngh...",
  ui_story_1019_10190101_86_dialog_content = "<color=#e8d9bb>Bersulang!!!</color>",
  ui_story_1019_10190101_87_dialog_content = "Aku tidak menyangka perjalananmu ke Lumopolis akan begitu penuh peristiwa. Kerja bagus melakukannya semua sendiri.",
  ui_story_1019_10190101_88_dialog_content = "Tidak ada apa-apa. Selama semuanya berjalan baik untuk Twilight, semua yang saya lakukan itu sepadan.",
  ui_story_1019_10190101_89_dialog_content = "Aku tahu aku benar tentangmu. Selamat!",
  ui_story_1019_10190101_90_dialog_content = "...",
  ui_story_1019_10190101_91_dialog_content = "Apa salahnya? Tidak ada satu pun minuman setelah pertempuran?",
  ui_story_1019_10190101_92_dialog_content = "Aku tidak bisa minum terlalu banyak karena kondisiku, jadi aku serahkan urusan minum kepada kalian. Sudah bertahun-tahun aku tidak melihat adegan seperti ini.",
  ui_story_1019_10190101_93_dialog_content = "Aku setuju.",
  ui_story_1019_10190101_94_dialog_content = "Tapi saya kenal mereka dengan baik. Meskipun mereka minum dan tertawa, Twilight masih ada di pikiran mereka.",
  ui_story_1019_10190101_95_dialog_content = "Setiap orang membawa beban kecemasan pada diri mereka, kecuali makhluk kubus putih yang bebas dari kekhawatiran.",
  ui_story_1019_10190101_96_dialog_content = "Jadi, saya memutuskan untuk kembali besok.",
  ui_story_1019_10190101_97_dialog_content = "Prajurit tidur dengan bau mesiu. Setelah kita habiskan minuman ini, saatnya bersiap untuk pertempuran berikutnya.",
  ui_story_1019_10190101_98_dialog_content = "<color=#e8d9bb>Pesta yang meriah berlanjut hingga larut malam...</color>",
  ui_story_1019_10190101_99_dialog_content = "<color=#e8d9bb>Bip—</color>",
  ui_story_1019_10190101_100_dialog_content = "Oh, itu kamu. Bagaimana keadaan di Eraveil?",
  ui_story_1019_10190101_101_dialog_content = "Cukup baik...",
  ui_story_1019_10190101_102_dialog_content = "Mengingat kamu menghubungi saya di waktu malam yang begitu larut, saya asumsikan kamu ingin update tentang Vice?",
  ui_story_1019_10190101_103_dialog_content = "Ya... Ada kabar tentang Vice dan yang lainnya?",
  ui_story_1019_10190101_104_dialog_content = "Ada berita, tapi saya belum bisa memberi Anda informasi pasti tentang status mereka saat ini.",
  ui_story_1019_10190101_105_dialog_content = "Benarkah? Tahu apa kamu?!",
  ui_story_1019_10190101_106_dialog_content = "Tim pelacak yang dipimpin oleh Charon telah mengirimkan sinyal kembali. Itulah cara tim pengintaian kami berkomunikasi bahwa segala sesuatunya berjalan dengan baik.",
  ui_story_1019_10190101_107_dialog_content = "Tapi katakanlah mereka menemui sesuatu yang merepotkan, seperti di Twilight-",
  ui_story_1019_10190101_108_dialog_content = "Saya sudah mendengar tentang itu, itulah sebabnya saya masih mencoba untuk memastikan apa yang sedang terjadi. Jangan khawatir. Saya akan memberi tahu Anda ketika saya memiliki sesuatu.",
  ui_story_1019_10190101_109_dialog_content = "Jadi apa yang bisa saya lakukan sekarang? Saya pernah berada di pertempuran di Twilight. Mungkin saya bisa membantu dengan cara tertentu.",
  ui_story_1019_10190101_110_dialog_content = "Kamu tidak perlu melakukan apa-apa, PlayerName.",
  ui_story_1019_10190101_111_dialog_content = "Tapi–",
  ui_story_1019_10190101_112_dialog_content = "Saya menghargai pikiran itu, tetapi sekarang bukan waktunya untuk datang ke Illumina.",
  ui_story_1019_10190101_113_dialog_content = "Sejak kita kehilangan inti dari Wali Satu, ada masalah dalam pertahanan Gannon, dan itulah yang sedang kita kerjakan.",
  ui_story_1019_10190101_114_dialog_content = "Keberanian dan niat baik yang Anda tunjukkan di Twilight adalah bantuan terbesar yang bisa Anda berikan kepada saya.",
  ui_story_1019_10190101_115_dialog_content = "Aku akan mengurus segalanya dari sini. Lihat, sudah malam. Pergi dan istirahatlah.",
  ui_story_1019_10190101_116_dialog_content = "Baiklah…",
  ui_story_1019_10190101_117_dialog_content = "...",
  ui_story_1019_10190101_118_dialog_content = "Anda tidak bisa tidur karena Anda khawatir untuk keselamatan Vice.",
  ui_story_1019_10190101_119_dialog_content = "Ya...",
  ui_story_1019_10190101_120_dialog_content = "<color=#e8d9bb>Kamu diam-diam menghitung selama 20 detik dan mencatat denyut jantungmu.</color>",
  ui_story_1019_10190101_121_dialog_content = "Soroz…",
  ui_story_1019_10190101_122_dialog_content = "Soroz selalu di sini.",
  ui_story_1019_10190101_123_dialog_content = "Meditasi 20 detik sepertinya berhasil. Aku merasa menemukan tempat bahagia ku.",
  ui_story_1019_10190101_124_dialog_content = "...",
  ui_story_1019_10190101_125_dialog_content = "Saya telah mengambil data gambar dari masa-masa bahagia Anda. Anda akan berdiri dengan kepala saat Anda bahagia sebagai seorang anak kecil.",
  ui_story_1019_10190101_126_dialog_content = "Berdiri dengan kepala?!",
  ui_story_1019_10190101_127_dialog_content = "Kamu bahkan menuntut aku untuk melakukannya untukmu juga, tidak peduli apa pun.",
  ui_story_1019_10190101_128_dialog_content = "Nah, handstand itu sulit sekarang, untuk kamu dan aku.",
  ui_story_1019_10190101_129_dialog_content = "Berdasarkan perhitungan saya, probabilitas Soroz melakukan handstand dengan sukses adalah 59%. Kamu perlu menemukan tempat yang aman jika saya melakukan manuver seperti itu.",
  ui_story_1019_10190101_130_dialog_content = "Apa? Ha ha! Terima kasih atas peringatannya, Soroz, tapi aku rasa kita baik-baik saja.",
  ui_story_1019_10190101_131_dialog_content = "Sudah lama sejak saya hanya duduk di kontrol tanpa melakukan apa-apa, tanpa peduli di dunia...",
  ui_story_1019_10190101_132_dialog_content = "Kamu telah mencapai banyak hal setelah Echo Template-ku rusak.",
  ui_story_1019_10190101_133_dialog_content = "Ya. Mungkin kalian masih belum tahu apa yang terjadi, jika dipikir-pikir...",
  ui_story_1019_10190101_134_dialog_content = "Setelah Echo Template kamu rusak, kami mengikuti koordinatmu dan menemukan sebuah kunci di kota bawah.",
  ui_story_1019_10190101_135_dialog_content = "Kemudian kami mengikuti set koordinat berikutnya menuju Eraveil.",
  ui_story_1019_10190101_136_dialog_content = "Ini adalah pertama kalinya saya menginjak tanah kelahiran, namun semua kerabat saya telah lama pergi.",
  ui_story_1019_10190101_137_dialog_content = "Oh, dan kami hampir kehilangan sahabat terbaik kami...",
  ui_story_1019_10190101_138_dialog_content = "Aku melihat leluhur Caelestite meninggalkan benua dalam Colossi mereka, dan kemudian menyaksikan kembalinya mereka setelah waktu yang sangat lama.",
  ui_story_1019_10190101_139_dialog_content = "Mengingat kembali, semuanya masih terasa seperti mimpi bagi saya. Saya tidak bisa tidak bertanya-tanya apa yang terjadi pada mereka pada akhirnya.",
  ui_story_1019_10190101_140_dialog_content = "Setelah itu, untuk menyelamatkanku, kamu terjebak di medan perang kuno.",
  ui_story_1019_10190101_141_dialog_content = "Beruntung, kami menemukan kesadaran Naviduz dan akhirnya membangunkanmu.",
  ui_story_1019_10190101_142_dialog_content = "...",
  ui_story_1019_10190101_143_dialog_content = "Tidak peduli seberapa sering saya membaca log perbaikan, itu tidak sebanding dengan mendengar cerita dari Anda, PlayerName.",
  ui_story_1019_10190101_144_dialog_content = "Jadi kamu tahu? Apakah aku baru saja menceritakan semua itu sia-sia?",
  ui_story_1019_10190101_145_dialog_content = "Tech Officer Gronru mencatat pengalamanmu secara detail di log perbaikan saya.",
  ui_story_1019_10190101_146_dialog_content = "Tapi, apakah Anda keberatan menceritakan kepada saya tentang partisipasi Anda dalam Latihan Militer Gabungan sebagai perwakilan Caelestite?",
  ui_story_1019_10190101_147_dialog_content = "Oh, itu...",
  ui_story_1019_10190201_1_dialog_content = "<color=#e8d9bb>Beberapa Hari Kemudian: Pusat Medis Illumina, Pagi Hari</color>",
  ui_story_1019_10190201_2_dialog_content = "Ini... semua hancur oleh tangan saya...",
  ui_story_1019_10190201_3_dialog_content = "M-Maaf, Dr. Chandra. Aku masih belum bisa mengendalikan diri...",
  ui_story_1019_10190201_4_dialog_content = "Tidak perlu minta maaf, Kapten Helios!",
  ui_story_1019_10190201_5_dialog_content = "Latihan bertarung dengan porsi yang tepat dapat menjadi saluran untuk emosimu, dan bersifat terapeutik.",
  ui_story_1019_10190201_6_dialog_content = "Saya benar-benar tidak tahu apa yang bisa saya lakukan untuk Illumina dalam keadaan ini...",
  ui_story_1019_10190201_7_dialog_content = "Hapuslah pikiran itu, Kapten Helios.",
  ui_story_1019_10190201_8_dialog_content = "Anda menyebut banyak tempat dalam kenangan Anda, terutama Dark Zone, yang merupakan bagian kunci dari intelijen untuk Illumina.",
  ui_story_1019_10190201_9_dialog_content = "Mengenai orang-orang dan pertemuan yang telah Anda coba ingat...",
  ui_story_1019_10190201_10_dialog_content = "Otak kita secara rutin memproses persepsi sensorik dan emosi ketika kita berada di sekitar orang lain.",
  ui_story_1019_10190201_11_dialog_content = "Seiring kamu semakin bisa mengendalikan perasaanmu, fungsi-fungsi itu juga akan pulih secara bertahap.",
  ui_story_1019_10190201_12_dialog_content = "Aku paham... Kalau begitu, aku harus bekerja lebih keras.",
  ui_story_1019_10190201_13_dialog_content = "Oh, saya akan memperbaiki model yang rusak, dan... di masa depan, biarkan saya membantu Anda membangunnya juga.",
  ui_story_1019_10190201_14_dialog_content = "Oh, dan satu hal lagi! Maafkan aku telah membangunkanmu di tengah malam seperti ini...",
  ui_story_1019_10190201_15_dialog_content = "Tidak apa-apa, Kapten Helios. Ini pekerjaanku. (Menguap)",
  ui_story_1019_10190201_16_dialog_content = "Nah, mari kita tinggalkan begitu saja untuk hari ini.",
  ui_story_1019_10190201_17_dialog_content = "Semoga kamu terus mencatat pikiran dan impianmu.",
  ui_story_1019_10190201_18_dialog_content = "Aku tidak tahu mengapa Grand Marshal ingin melihat catatan-catatan ini, tapi jelas ini penting baginya.",
  ui_story_1019_10190201_19_dialog_content = "Dan jangan abaikan emosi dan gambar tiba-tiba yang muncul di pikiran Anda.",
  ui_story_1019_10190201_20_dialog_content = "Di bawah nyala api biasanya ada kayu bakar yang telah membakar selama waktu yang lama.",
  ui_story_1019_10190201_21_dialog_content = "Selama aku hidup, aku tak akan pernah melupakan apapun di dunia yang dingin dan gelap itu.",
  ui_story_1019_10190201_22_dialog_content = "Terima kasih sekali lagi, Dr. Chandra.",
  ui_story_1019_10190201_23_dialog_content = "<color=#e8d9bb>Bip—</color>",
  ui_story_1019_10190201_24_dialog_content = "Siapa yang mengirimiku pesan sepagi ini?",
  ui_story_1019_10190201_25_dialog_content = "<color=#e8d9bb>Wuush, wuush—</color>",
  ui_story_1019_10190201_26_dialog_content = "(Eclipsian) 1011X.",
  ui_story_1019_10190201_27_dialog_content = "(Dalam bahasa Eclipsian) Ya, kami telah mendapatkan <color=#FFB400>Drive Ring</color> terakhir.",
  ui_story_1019_10190201_28_dialog_content = "(Eclipsian) 01X11.",
  ui_story_1019_10190201_29_dialog_content = "(Eclipsian) Saya membaca nama mulia Anda dan berharap Anda memandang...",
  ui_story_1019_10190201_30_dialog_content = "(Eclipsian) Kami dengan rendah hati menunggu kedatanganmu...",
  ui_story_1019_10190201_31_dialog_content = "<color=#e8d9bb>Bip—</color>",
  ui_story_1019_10190201_32_dialog_content = "Di mana aku?",
  ui_story_1019_10190201_33_dialog_content = "Siapa sosok-sosok bayangan ini?",
  ui_story_1019_10190201_34_dialog_content = "Berhenti melihat, PlayerName!",
  ui_story_1019_10190201_35_dialog_content = "Tunggu, itu kamu, Vice?",
  ui_story_1019_10190201_36_dialog_content = "Ini kamu! Sungguh ini kamu, Vice!",
  ui_story_1019_10190201_37_dialog_content = "Pulang.",
  ui_story_1019_10190201_38_dialog_content = "Apakah kamu tersesat, Vice? Apakah kamu dalam bahaya?",
  ui_story_1019_10190201_39_dialog_content = "Cepat, katakan di mana kamu! Aku akan membantumu keluar.",
  ui_story_1019_10190201_40_dialog_content = "Pulang.",
  ui_story_1019_10190201_41_dialog_content = "...",
  ui_story_1019_10190201_42_dialog_content = "Pergi kemana, Vice?",
  ui_story_1019_10190201_43_dialog_content = "Pulang.",
  ui_story_1019_10190201_44_dialog_content = "Rumah? Di mana saya?",
  ui_story_1019_10190201_45_dialog_content = "Pulang.",
  ui_story_1019_10190201_46_dialog_content = "Siapa kamu? Dimana Vice?",
  ui_story_1019_10190201_47_dialog_content = "<color=#e8d9bb>Bip—</color>",
  ui_story_1019_10190201_48_dialog_content = "Di sini berbahaya, PlayerName!",
  ui_story_1019_10190201_49_dialog_content = "Vice! Kamu ada di mana?!",
  ui_story_1019_10190201_50_dialog_content = "<color=#e8d9bb>Bip — Bip — Bip —</color>",
  ui_story_1019_10190201_51_dialog_content = "Vice... Vice!",
  ui_story_1019_10190201_52_dialog_content = "Mimpi buruk lagi, PlayerName?",
  ui_story_1019_10190201_53_dialog_content = "Mimpi...",
  ui_story_1019_10190201_54_dialog_content = "Aku bermimpi lagi...",
  ui_story_1019_10190201_55_dialog_content = "Ada yang tidak beres, Soroz. Sejak aku kembali ke Eraveil, aku terus mengalami mimpi aneh...",
  ui_story_1019_10190201_56_dialog_content = "Rasanya lebih seperti aku merasakan sesuatu... tapi aku juga tidak bisa menjelaskannya dengan tepat.",
  ui_story_1019_10190201_57_dialog_content = "Mungkin kamu terlalu stres, PlayerName. Kamu telah di sini menunggu berita selama beberapa malam berturut-turut. Kamu harus kembali ke kamarmu untuk beristirahat.",
  ui_story_1019_10190201_58_dialog_content = "Sekarang jam berapa?",
  ui_story_1019_10190201_59_dialog_content = "Matahari akan terbit dalam tiga jam.",
  ui_story_1019_10190201_60_dialog_content = "Satu hari lagi telah berlalu...",
  ui_story_1019_10190201_61_dialog_content = "Sungguh mengerikan hanya duduk di sini menunggu, tak berdaya untuk melakukan apa pun...",
  ui_story_1019_10190201_62_dialog_content = "<color=#e8d9bb>Bip—</color>",
  ui_story_1019_10190201_63_dialog_content = "Aku mengenali suara itu... Kamu telah menemukan lebih banyak koordinat lama dalam data Naviduz.",
  ui_story_1019_10190201_64_dialog_content = "Kamu menyebut mereka \"gema dari masa lalu.\"",
  ui_story_1019_10190201_65_dialog_content = "Ya.",
  ui_story_1019_10190201_66_dialog_content = "Naviduz mengulang-ulang koordinat ini berulang kali sebelum jatuh ke dalam keheningan, tetapi tidak ada lokasi yang sesuai yang pernah ditemukan di tanah ini.",
  ui_story_1019_10190201_67_dialog_content = "Apakah itu karena medan telah berubah?",
  ui_story_1019_10190201_68_dialog_content = "Waktu juga telah berubah.",
  ui_story_1019_10190201_69_dialog_content = "Namun kamu tidak pernah berhenti mencari...",
  ui_story_1019_10190201_70_dialog_content = "Saya dapat sepenuhnya memulihkan kesadaran saya setelah saya memeriksa semua data.",
  ui_story_1019_10190201_71_dialog_content = "Sebenarnya, kamu sudah menjadi Soroz yang aku kenal.",
  ui_story_1019_10190201_72_dialog_content = "Kesesuaian psikis kita hanya 90% dari sebelum perbaikan, PlayerName.",
  ui_story_1019_10190201_73_dialog_content = "Benarkah? Aku tidak merasakan perbedaan apa pun.",
  ui_story_1019_10190201_74_dialog_content = "Aku akan terus belajar.",
  ui_story_1019_10190201_75_dialog_content = "Aku ingin mengajukan pertanyaan...",
  ui_story_1019_10190201_76_dialog_content = "Aku tahu Reinhardt bilang jangan khawatir tentang Illumina, tapi aku masih khawatir.",
  ui_story_1019_10190201_77_dialog_content = "Semakin sunyi di Eraveil, semakin gelisah yang saya rasakan. Ini membuat saya berpikir bahwa ketika saya merasakan detak jantung Vice...",
  ui_story_1019_10190201_78_dialog_content = "dia mencoba memberitahuku sesuatu, tapi aku tidak bisa memahaminya...",
  ui_story_1019_10190201_79_dialog_content = "Jadi, apa yang ingin kamu tanyakan kepada saya, PlayerName?",
  ui_story_1019_10190201_80_dialog_content = "Tidak, aku sudah memutuskan! Bahkan jika Reinhardt menolak untuk membiarkanku pergi ke Illumina, aku—",
  ui_story_1019_10190201_81_dialog_content = "<color=#e8d9bb>Bip—</color>",
  ui_story_1019_10190201_82_dialog_content = "Kenapa itu dia...",
  ui_story_1019_10190201_83_dialog_content = "Apakah ini berita yang telah kamu tunggu?",
  ui_story_1019_10190201_84_dialog_content = "Ya! Lihat!",
  ui_story_1019_10190201_85_dialog_content = "...",
  ui_story_1019_10190201_86_dialog_content = "\"Datang ke Illumina sekarang\"",
  ui_story_1019_10190201_87_dialog_content = "\"Segera\"",
  ui_story_1019_10190301_1_dialog_content = "<color=#e8d9bb>Halaman Layanan Illumina</color>",
  ui_story_1019_10190301_2_dialog_content = "Oh tidak, lupa bertanya ke mana aku harus pergi.",
  ui_story_1019_10190301_3_dialog_content = "Permisi, pak, bisa–",
  ui_story_1019_10190301_4_dialog_content = "Warga sipil tidak diizinkan di halaman servis. Harap segera kosongkan area tersebut.",
  ui_story_1019_10190301_5_dialog_content = "Oh, aku bukan warga sipil. Aku ini Caeles—",
  ui_story_1019_10190301_6_dialog_content = "Berkumpul!",
  ui_story_1019_10190301_7_dialog_content = "Ya!",
  ui_story_1019_10190301_8_dialog_content = "Lagi, tempat ini tidak aman karena kerentanan dalam pertahanannya. Tolong pergi sekarang.",
  ui_story_1019_10190301_9_dialog_content = "Kerentanan...",
  ui_story_1019_10190301_10_dialog_content = "Sepertinya keamanan masih menjadi masalah meski dengan semua prajurit ini.",
  ui_story_1019_10190301_11_dialog_content = "Ha! Ambil ini, PlayerName!",
  ui_story_1019_10190301_12_dialog_content = "Tunggu sebentar... Siapa kamu lagi?",
  ui_story_1019_10190301_13_dialog_content = "Ayolah, kamu lupa aku?!",
  ui_story_1019_10190301_14_dialog_content = "Oh, aku ingat sekarang. Kamu...",
  ui_story_1019_10190301_15_option_content = "Greenie",
  ui_story_1019_10190301_16_dialog_content = "Tidak, saya maksud Sean!",
  ui_story_1019_10190301_17_dialog_content = "(Tidak bisa percaya aku membiarkan kesan pertama tentang dia lepas begitu saja...)",
  ui_story_1019_10190301_18_dialog_content = "Ha, nah, beberapa orang memanggilku seperti itu!",
  ui_story_1019_10190301_19_option_content = "Gagak",
  ui_story_1019_10190301_20_dialog_content = "Tidak, tunggu, bukan Crow... Itu Sean!",
  ui_story_1019_10190301_21_dialog_content = "Hmm, dibandingkan dengan Crow, sepertinya aku memang cukup tidak mencolok.",
  ui_story_1019_10190301_22_option_content = "Sean",
  ui_story_1019_10190301_23_dialog_content = "Benar. Kamu adalah Sean...",
  ui_story_1019_10190301_24_dialog_content = "Maaf! Kamu terlihat... berbeda, dari yang aku ingat.",
  ui_story_1019_10190301_25_dialog_content = "Nah, tentu saja. Saya telah berlatih keterampilan tinju saya dan menjadi lebih kuat setiap hari!",
  ui_story_1019_10190301_26_dialog_content = "Tidak apa-apa, aku akan memberimu kelonggaran kali ini.",
  ui_story_1019_10190301_27_dialog_content = "Apa yang kamu lakukan di sini, Sean?",
  ui_story_1019_10190301_28_dialog_content = "Saya rutin kembali ke Gannon untuk pemeriksaan fisik. Kali ini saya datang lebih awal tetapi tidak menyangka akan bertemu dengan Anda.",
  ui_story_1019_10190301_29_dialog_content = "Lalu kenapa kamu tidak bergabung dengan patroli dan membantu mencari para Eclipsite?",
  ui_story_1019_10190301_30_dialog_content = "Salam, Petugas Vivian! Ini karena saya...",
  ui_story_1019_10190301_31_dialog_content = "Cuma bercanda. Lakukan apa yang seharusnya kamu lakukan dan berhati-hatilah.",
  ui_story_1019_10190301_32_dialog_content = "Ya, ma'am! Sampai jumpa, PlayerName.",
  ui_story_1019_10190301_33_dialog_content = "Sampai jumpa, Sean.",
  ui_story_1019_10190301_34_dialog_content = "Seperti yang diprediksi oleh Grand Marshal, kekurangan berita pasti akan membawa Anda ke Illumina.",
  ui_story_1019_10190301_35_dialog_content = "Dia berpikir saya akan datang sendiri, jadi dia memintamu...",
  ui_story_1019_10190301_36_dialog_content = "Tentu saja. Kami tahu setiap gerakan yang kamu dan Colossus-mu lakukan di Astra seperti telapak tangan kami sendiri.",
  ui_story_1019_10190301_37_dialog_content = "Tapi Illumina sedang berantakan sekarang; para atasan sibuk menyelesaikan pertarungan kekuasaan.",
  ui_story_1019_10190301_38_dialog_content = "Dan seperti yang sudah kamu lihat, keamanan masih menjadi masalah besar.",
  ui_story_1019_10190301_39_dialog_content = "Oh, apakah itu Grand Marshal...",
  ui_story_1019_10190301_40_option_content = "Reinhardt?",
  ui_story_1019_10190301_41_dialog_content = "Siapa lagi? Dia adalah pemimpin spiritual setiap prajurit di Illumina. Tak ada yang bisa menandingi.",
  ui_story_1019_10190301_42_option_content = "Wrath?",
  ui_story_1019_10190301_43_dialog_content = "Wrath adalah Grand Marshal dalam nama, tetapi dia memberitahu committee bahwa dia akan mengembalikan posisi tersebut kepada Reinhardt.",
  ui_story_1019_10190301_44_dialog_content = "Namun, tidak peduli siapa yang menjadi Grand Marshal, tampaknya tidak ada yang sejalan dengan keinginan komite, namun tentara tidak bisa kekurangan komando yang terpadu...",
  ui_story_1019_10190301_45_dialog_content = "Jadi, komite menunda penyelidikan atas dugaan kolusi Grand Marshal, dan memutuskan bahwa urusan Illuminan akan diawasi bersama oleh komite dan militer.",
  ui_story_1019_10190301_46_dialog_content = "Sepertinya pekerjaanmu semakin sulit.",
  ui_story_1019_10190301_47_dialog_content = "Memang. Illumina sangat tidak terorganisir sehingga saya bahkan tidak bisa menjangkau marshal sebagian besar waktu.",
  ui_story_1019_10190301_48_dialog_content = "Tidak heran saya tidak pernah mendengar kabar darinya... Maaf telah membuat semuanya menjadi lebih sulit untuk kalian semua!",
  ui_story_1019_10190301_49_dialog_content = "Jadi... apakah Wrath masih ingin berduel dengan Reinhardt?",
  ui_story_1019_10190301_50_dialog_content = "Sayangnya, ya. Jelas bukan untuk peran sebagai Grand Marshal, tetapi itu tidak menghentikannya untuk ingin bertarung dengan Reinhardt.",
  ui_story_1019_10190301_51_dialog_content = "Seperti biasanya dia... Bagaimana kabar Wrath? Apakah operasinya berjalan dengan baik?",
  ui_story_1019_10190301_52_dialog_content = "Saya juga ingin tahu itu, tetapi birokrasi saat ini sangat rumit sehingga segala sesuatu yang melibatkan Program Phospherus ditolak mentah-mentah.",
  ui_story_1019_10190301_53_dialog_content = "Jadi jika kamu di sini untuk mengunjunginya, itu adalah hal yang benar-benar tidak bisa dilakukan.",
  ui_story_1019_10190301_54_dialog_content = "Sebenarnya, aku kemari untuk–",
  ui_story_1019_10190301_55_dialog_content = "Graaagh!",
  ui_story_1019_10190301_56_dialog_content = "Kepala Staf! Mekanik mengatakan bahwa saluran ventilasi di sisi barat halaman layanan rusak. Eclipsites pasti masuk dari sana!",
  ui_story_1019_10190301_57_dialog_content = "Akhirnya, kita menemukan kerusakan setelah semalam suntuk!",
  ui_story_1019_10190301_58_dialog_content = "Bentuk formasi, lindungi para insinyur, dan ikuti saya untuk membunuh Eclipsite!",
  ui_story_1019_10190301_59_dialog_content = "Ya, Bu!!!",
  ui_story_1019_10190301_60_dialog_content = "Hei, kamu di depan, minggir!",
  ui_story_1019_10190301_61_dialog_content = "Kepala Staf! Di belakangmu... Eclipsite telah mencekik seseorang hingga mati!",
  ui_story_1019_10190301_62_dialog_content = "Mungkinkah itu...?",
  ui_story_1019_10190301_63_dialog_content = "Bu bu bu!",
  ui_story_1019_10190301_64_dialog_content = "Di depan begitu banyak orang juga...",
  ui_story_1019_10190301_65_dialog_content = "Bu bu bu!",
  ui_story_1019_10190301_66_dialog_content = "Oke, oke. Meskipun sebenarnya belum waktunya untuk berolahraga...",
  ui_story_1019_10190301_67_dialog_content = "Siapkan diri untuk menjalankan program!",
  ui_story_1019_10190301_68_dialog_content = "Bu!",
  ui_story_1019_10190301_69_dialog_content = "Siapa gerangan itu?",
  ui_story_1019_10190402_1_dialog_content = "Unggah, unggah... Hmm, masih belum cukup data sama sekali tentang aktivitas luar ruangan.",
  ui_story_1019_10190402_2_dialog_content = "Jadi ini penampakan saat seorang ilmuwan bertarung...",
  ui_story_1019_10190402_3_dialog_content = "Hei, sebelum kamu mulai mengulang-ulang stereotip tentang ilmuwan, biarkan saya mengingatkanmu...",
  ui_story_1019_10190402_4_dialog_content = "Tidak semua dari kita adalah kutu buku yang murung, membosankan, dan tidak atletis.",
  ui_story_1019_10190402_5_dialog_content = "Tidak, tidak, bukan itu yang saya maksud...",
  ui_story_1019_10190402_6_dialog_content = "Siapa ini, PlayerName?",
  ui_story_1019_10190402_7_dialog_content = "Algol, seorang ilmuwan dari Dewan Ilmu Pengetahuan Illumina.",
  ui_story_1019_10190402_8_dialog_content = "Dia mengundangku ke Illumina, tapi aku rasa... dia tidak sama seperti saat aku terakhir melihatnya.",
  ui_story_1019_10190402_9_dialog_content = "Dewan Sains? Ini adalah pertama kalinya saya melihat salah satu dari mereka secara langsung.",
  ui_story_1019_10190402_10_dialog_content = "Ter-konfirmasi!",
  ui_story_1019_10190402_11_dialog_content = "Hai, Caelestite! Oh iya, apakah aku mengundangmu?",
  ui_story_1019_10190402_12_dialog_content = "Halo, Profesor Algol. Saya Vivian, Kepala Staf Federasi Illumina.",
  ui_story_1019_10190402_13_dialog_content = "Nah... karena kamu di sini, ikuti aku.",
  ui_story_1019_10190402_14_dialog_content = "Profesor Algol, saya ingin memberi tahu Anda bahwa Grand Marshal telah mengirim saya untuk membantu PlayerName di Illumina.",
  ui_story_1019_10190402_15_dialog_content = "Saya harus diberi penjelasan tentang rencana Anda dan melaporkannya kepada Grand Marshal.",
  ui_story_1019_10190402_16_dialog_content = "Pertemuan kita spontan dan tidak akan dicatat. Jika kamu bersikeras untuk membuat catatan, gunakan ini.",
  ui_story_1019_10190402_17_dialog_content = "Maksudmu…",
  ui_story_1019_10190402_18_dialog_content = "Kepalamu.",
  ui_story_1019_10190402_19_dialog_content = "Hiks!",
  ui_story_1019_10190402_20_dialog_content = "...",
  ui_story_1019_10190402_21_dialog_content = "Untuk alasan keamanan, namun, saya memiliki pertanyaan untuk Anda. Itu... benda yang bertarung bersama Anda bukan senjata normal, bukan?",
  ui_story_1019_10190402_22_dialog_content = "Tentu saja bukan! Namanya Bool, dan itu adalah p-",
  ui_story_1019_10190402_23_dialog_content = "Huuu!",
  ui_story_1019_10190402_24_dialog_content = "Itu sakit! Berhenti, teman...!",
  ui_story_1019_10190402_25_dialog_content = "Astaga... Mm, yup, itu terasa enak! Naik sedikit lagi...",
  ui_story_1019_10190402_26_dialog_content = "Bool juga memberikan pijatan?",
  ui_story_1019_10190402_27_dialog_content = "Bool bilang berat badanmu bertambah beberapa pon sejak terakhir kali.",
  ui_story_1019_10190402_28_dialog_content = "Apa?! Bagaimana itu bisa bicara?",
  ui_story_1019_10190402_29_dialog_content = "Sebagai seorang Caelestite, kamu harus tahu bahwa tidak semua komunikasi terjadi secara lisan.",
  ui_story_1019_10190402_30_dialog_content = "Kami—Bool dan saya—memiliki cara unik dalam berbicara satu sama lain.",
  ui_story_1019_10190402_31_dialog_content = "Misalnya, Bool sekarang mengatakan bahwa ia sangat puas dengan sistem pertempuran yang telah saya tingkatkan untuknya!",
  ui_story_1019_10190402_32_dialog_content = "Bu!",
  ui_story_1019_10190402_33_dialog_content = "Hehe! Jangan sebutkan itu!",
  ui_story_1019_10190402_34_dialog_content = "(Pintu masuk megah mereka itu agak mengerikan...)",
  ui_story_1019_10190402_35_dialog_content = "Hmm? Caelestite, ada yang ingin kamu katakan?",
  ui_story_1019_10190402_36_dialog_content = "Hiks!",
  ui_story_1019_10190402_37_dialog_content = "Memang... Saya juga melihat rasa tidak suka yang samar-samar tersembunyi di wajahnya.",
  ui_story_1019_10190402_38_dialog_content = "Kamu juga bisa tahu apa yang sedang kupikirkan?",
  ui_story_1019_10190402_39_dialog_content = "Haha, santai! Ayo pergi.",
  ui_story_1019_10190402_40_dialog_content = "Oh... Apa yang begitu mendesak sehingga Anda membutuhkan saya untuk datang ke Illumina, Profesor Algol?",
  ui_story_1019_10190402_41_dialog_content = "Kamu datang tanpa tahu apa yang kamu cari?",
  ui_story_1019_10190402_42_dialog_content = "Meski itu memang cocok dengan stereotip yang saya miliki untuk Caelestite.",
  ui_story_1019_10190402_43_dialog_content = "Masih ingat data kepribadian Naviduz yang kamu salin untuk memulihkan Soroz?",
  ui_story_1019_10190402_44_dialog_content = "Koordinat dalam data tidak memiliki lokasi yang cocok.",
  ui_story_1019_10190402_45_dialog_content = "Tetapi Illumina baru-baru ini memperbarui bagian dari peta Eternal Night-nya, dan mungkin ada petunjuk untuk menemukan inti Guardian One di suatu tempat.",
  ui_story_1019_10190402_46_dialog_content = "Data tersebut bahkan mungkin dapat memberikan jawaban untuk koordinat yang tidak diketahui yang ditemukan oleh skuad pelacak.",
  ui_story_1019_10190402_47_dialog_content = "Benarkah? Baguslah kalau begitu! Apa yang kamu inginkan saya lakukan?",
  ui_story_1019_10190402_48_dialog_content = "Kali ini yang kami butuhkan bukan kemampuan psikis Anda, tapi kemampuan belajar Soroz.",
  ui_story_1019_10190402_49_dialog_content = "Kemampuan belajar?",
  ui_story_1019_10190402_50_dialog_content = "Ya. Kemampuan Soroz untuk memulihkan kesadaran dalam waktu singkat membuktikan bahwa dia cepat belajar.",
  ui_story_1019_10190402_51_dialog_content = "Saya ingin memanfaatkan kemampuan itu untuk meningkatkan efisiensi proses pemetaan Dark Zone, sambil memberi saya beberapa perspektif baru untuk penelitian saya.",
  ui_story_1019_10190402_52_dialog_content = "Kedengarannya mengesankan... Ngomong-ngomong, kami akan senang membantu.",
  ui_story_1019_10190402_53_dialog_content = "Lalu sambungkan Soroz ke <color=#FFB400>terminal</color>ku. Itu akan memakan waktu.",
  ui_story_1019_10190402_54_dialog_content = "Sejauh berapa lama tepatnya, biarkan aku melihat...",
  ui_story_1019_10190402_55_dialog_content = "Bukankah <color=#FFB400>terminal</color> itu adalah benda di pergelangan tanganmu?",
  ui_story_1019_10190402_56_dialog_content = "Ini adalah gelang teknologi. Tentu saja, saya lebih suka menyebutnya band lengan olahraga.",
  ui_story_1019_10190402_57_dialog_content = "Oh, saatnya berolahraga. Kalian mau ikut denganku?",
  ui_story_1019_10190402_58_dialog_content = "Tapi ini masih pagi. Apakah Anda biasanya berolahraga pada waktu ini, Profesor Algol?",
  ui_story_1019_10190402_59_dialog_content = "Begitulah cara jam biologis saya bekerja.",
  ui_story_1019_10190402_60_dialog_content = "Bagaimana kalau begini, kita sebut saja pertempuran yang baru saja kita lalui sebagai latihan. Lalu, kita bisa langsung ke urusan yang sebenarnya!",
  ui_story_1019_10190402_61_dialog_content = "...",
  ui_story_1019_10190402_62_dialog_content = "Butler... Butler... Buka pintu dan tuangkan tiga cangkir kopi untukku sambil melakukannya.",
  ui_story_1019_10190402_63_dialog_content = "Guardian One menolak. Guardian One bukanlah seorang butler.",
  ui_story_1019_10190402_64_dialog_content = "...",
  ui_story_1019_10190402_65_dialog_content = "Uh, baiklah, mungkin saja dia baru bangun...",
  ui_story_1019_10190501_1_dialog_content = "<color=#e8d9bb>Kantor Algol</color>",
  ui_story_1019_10190501_2_dialog_content = "Selamat datang di laboratoriumku! Agak berantakan. Pokoknya, cari tempat untuk duduk.",
  ui_story_1019_10190501_3_dialog_content = "Saya tidak tahu bahwa lab Illumina bisa terlihat seperti ini...",
  ui_story_1019_10190501_4_dialog_content = "Tanaman pot, mesin olahraga, dan semua barang keren ini...",
  ui_story_1019_10190501_5_dialog_content = "Apakah ini tempat tidur atau sofa?",
  ui_story_1019_10190501_6_dialog_content = "Kenapa kamu tidak berbaring di atasnya dan mencoba sendiri? Tombol pijatnya ada di sana.",
  ui_story_1019_10190501_7_dialog_content = "Whoa, ini sangat nyaman. Membuatku ingin tidur.",
  ui_story_1019_10190501_8_dialog_content = "Ini sangat berbeda dari gaya khas Illumina...",
  ui_story_1019_10190501_9_dialog_content = "Benar sekali. Tidak ada dari pengaturan ini yang sesuai dengan Peraturan Living Quarters Illumina...",
  ui_story_1019_10190501_10_dialog_content = "Hah? Hampir semua yang kamu lihat di sini sebagian besar dibangun menggunakan bahan daur ulang yang tua.",
  ui_story_1019_10190501_11_dialog_content = "Dan aku menggabungkan ruang kerja dan ruang tinggalku menjadi satu ruangan. Bukankah itu termasuk dalam konservasi sumber daya?",
  ui_story_1019_10190501_12_dialog_content = "Belum lagi ini melanggar Peraturan Prajurit Illumina jika Chief of Staff mendapatkan pijat selama jam kerja.",
  ui_story_1019_10190501_13_dialog_content = "K-Kamu tidak melihat aku sedang dipijat...",
  ui_story_1019_10190501_14_dialog_content = "Bukankah tadi kamu bilang itu membuatmu mengantuk?",
  ui_story_1019_10190501_15_dialog_content = "Jangan hanya berdiri di sana, Caelestite. Lihat roda itu di sana?",
  ui_story_1019_10190501_16_dialog_content = "Berdiri di atasnya selama 10 menit akan membakar lebih banyak lemak darimu daripada lari sepuluh putaran mengelilingi Colossus.",
  ui_story_1019_10190501_17_dialog_content = "Mari kita bicarakan hal itu nanti...",
  ui_story_1019_10190501_18_dialog_content = "Bip!",
  ui_story_1019_10190501_19_dialog_content = "Sudah lama tidak bertemu, Caelestite!",
  ui_story_1019_10190501_20_dialog_content = "Hei, Guardian One! Jadi kamu adalah droid pelayan!",
  ui_story_1019_10190501_21_dialog_content = "Guardian One tidak pernah setuju untuk menjadi butler Algol.",
  ui_story_1019_10190501_22_dialog_content = "... Lalu apa yang sedang kamu bawa itu?",
  ui_story_1019_10190501_23_dialog_content = "Ini adalah dua cangkir kopi yang menyegarkan untuk dua tamu, dibuat khusus oleh Guardian One. Algol harus membuat sendiri.",
  ui_story_1019_10190501_24_dialog_content = "Itu tidak adil...",
  ui_story_1019_10190501_25_dialog_content = "Hei, apakah kamu menambahkan mentega ke dalam ini? Saya hanya pernah mencicipi kopi dengan rasa ini di Umbraton sebelumnya.",
  ui_story_1019_10190501_26_dialog_content = "Ini adalah campuran khusus yang harus cocok dengan selera Anda.",
  ui_story_1019_10190501_27_dialog_content = "Aku sangat menyukainya.",
  ui_story_1019_10190501_28_dialog_content = "Biarkan aku menyesap...",
  ui_story_1019_10190501_29_dialog_content = "Hmm... Aku mencium aroma rumput segar. Sungguh lezat yang tak terduga!",
  ui_story_1019_10190501_30_dialog_content = "Ini adalah campuran Eraveil yang spesial.",
  ui_story_1019_10190501_31_dialog_content = "Algol baru-baru ini telah mengembangkan banyak program menarik. Guardian One dapat membuat kopi dengan rasa khusus sesuai dengan kebiasaan makan Anda di Illumina.",
  ui_story_1019_10190501_32_dialog_content = "Kamu memang menjadi pelayan yang baik, tahu.",
  ui_story_1019_10190501_33_dialog_content = "...",
  ui_story_1019_10190501_34_dialog_content = "Huuh!",
  ui_story_1019_10190501_35_dialog_content = "Oke, kita sudah mendapatkan pengaturannya. Saya akan mulai menjalankan data!",
  ui_story_1019_10190501_36_dialog_content = "Inputter, inputter... Di mana benda kutukan itu?",
  ui_story_1019_10190501_37_dialog_content = "Ups... Tolong ambilkan itu untukku, Guardian One.",
  ui_story_1019_10190501_38_dialog_content = "...",
  ui_story_1019_10190501_39_dialog_content = "... Aku akan melakukannya.",
  ui_story_1019_10190501_40_dialog_content = "Hei, kenapa ada hati merah muda di seluruh bagian belakang?",
  ui_story_1019_10190501_41_dialog_content = "\"Yang terkasih Algol, bisakah kamu mengajari saya matematika?\"",
  ui_story_1019_10190501_42_dialog_content = "Dan ini juga... \"Kebijakanmu menerangiku seperti sorotan lampu pencari Undercity.\"",
  ui_story_1019_10190501_43_dialog_content = "Ditandatangani \"Tebak Siapa\"...",
  ui_story_1019_10190501_44_dialog_content = "Oh, itu... Hanya beberapa surat cinta lama yang pernah aku terima di masa lalu.",
  ui_story_1019_10190501_45_option_content = "... Itu sangat canggung.",
  ui_story_1019_10190501_46_option_content = "... Tidak apa-apa, aku tidak mau tahu.",
  ui_story_1019_10190501_47_dialog_content = "Algol, sungguh mengejutkan bahwa kamu menggunakan surat cinta seseorang sebagai kertas coretan.",
  ui_story_1019_10190501_48_dialog_content = "Mengapa saya tidak menggunakan kertas yang ada di depan saya? Lagipula, ini berarti saya tidak pernah membuangnya.",
  ui_story_1019_10190501_49_dialog_content = "Kamu bisa saja menggunakan papan tulis putih.",
  ui_story_1019_10190501_50_dialog_content = "Papan besar ini memiliki peta... perhitungan, perhitungan, dan masih banyak perhitungan lagi.",
  ui_story_1019_10190501_51_dialog_content = "Saya juga melihat banyak revisi berdasarkan suasana hati Dr. Algol pada memo-memo ini.",
  ui_story_1019_10190501_52_dialog_content = "Apakah kamu juga melihat kesedihan yang tersembunyi di dalam mereka?",
  ui_story_1019_10190501_53_dialog_content = "Dari ketidakmampuanku untuk memecahkan misteri tentang Guardian?",
  ui_story_1019_10190501_54_dialog_content = "Wali? Maksud kamu Wali Satu?",
  ui_story_1019_10190501_55_dialog_content = "Tidak!",
  ui_story_1019_10190501_56_dialog_content = "Guardian One adalah AI kuno yang bertugas mengurus operasi harian seluruh sistem teknologi Illumina.",
  ui_story_1019_10190501_57_dialog_content = "Sebenarnya itu adalah gugus komputer yang sangat besar. Wraith mencuri inti dan kamu telah melihat dampak yang ditimbulkannya pada Kota Gannon.",
  ui_story_1019_10190501_X57_dialog_content = "Kluster ini dikembangkan menggunakan teknologi kuno—Guardian—sebagai dasarnya.",
  ui_story_1019_10190501_58_dialog_content = "Kamu bisa mengatakan Guardian adalah prototipe untuk Guardian One.",
  ui_story_1019_10190501_59_dialog_content = "Guardian One adalah bagian dari kluster komputer dengan inti independen untuk memproses data. Ia juga menyimpan banyak informasi dari zaman kuno.",
  ui_story_1019_10190501_X59_dialog_content = "Oleh karena itu, meskipun mereka memiliki nama yang sama secara teori, untuk membedakan, kamu bisa memanggil Guardian One... um, \"Mailbox\".",
  ui_story_1019_10190501_60_dialog_content = "Guardian One bukanlah kotak surat.",
  ui_story_1019_10190501_61_dialog_content = "Bip, bip, bip, bip, bip...",
  ui_story_1019_10190501_62_dialog_content = "Guardian One tidak mengerti apa yang Algol katakan.",
  ui_story_1019_10190501_63_dialog_content = "Sepertinya kamu masih perlu belajar bagaimana memproses dialog Aurorian yang kompleks.",
  ui_story_1019_10190501_64_dialog_content = "Wali Satu mengerti.",
  ui_story_1019_10190501_65_dialog_content = "(Sulit dipercaya Algol tidak menepis Guardian One...)",
  ui_story_1019_10190501_66_dialog_content = "Bagaimanapun, pekerjaan saya adalah mempelajari Guardian dan mengembangkan fitur-fitur lainnya.",
  ui_story_1019_10190501_67_dialog_content = "Apakah mesin ini prototipenya?",
  ui_story_1019_10190501_68_dialog_content = "Ini adalah <color=#FFB400>simulator</color>. Aslinya telah lama dikunci karena alasan keamanan.",
  ui_story_1019_10190501_69_dialog_content = "Benar. Ini akan terlihat rusak jika ini adalah teknologi kuno.",
  ui_story_1019_10190501_70_dialog_content = "Tidak selalu. Saya pernah melihat aslinya sebelumnya, dan saya hanya bisa menggambarkan bagian luarnya sebagai... memancarkan aura tua namun berkelas.",
  ui_story_1019_10190501_71_dialog_content = "Kami telah melihat kemajuan di setiap teknologi pinggiran selama beberapa tahun terakhir, kecuali untuk Guardian, yang masih mengalami hambatan.",
  ui_story_1019_10190501_72_dialog_content = "Kalau saja aku bisa memeriksanya sebelum disimpan...",
  ui_story_1019_10190501_73_dialog_content = "Oh, aku marah setiap kali memikirkannya!",
  ui_story_1019_10190501_74_dialog_content = "Hiks!",
  ui_story_1019_10190501_75_dialog_content = "Apa? Bahkan kamu juga mengejek saya!",
  ui_story_1019_10190501_76_dialog_content = "Bool tampaknya bukan sedang mengejekmu, tapi tidak setuju dengan apa yang kamu katakan.",
  ui_story_1019_10190501_77_dialog_content = "Bu!",
  ui_story_1019_10190501_78_dialog_content = "Oh hebat, bahkan Caelestite sekarang lebih pintar daripada saya!",
  ui_story_1019_10190501_79_dialog_content = "...",
  ui_story_1019_10190501_80_dialog_content = "Berbicara tentang kesalahpahaman...",
  ui_story_1019_10190501_81_dialog_content = "Mengingat Anda bisa terhubung dengan Guardian One secara psikis, mungkin Anda juga bisa mengintip pikiran Bool.",
  ui_story_1019_10190501_82_dialog_content = "Huuu!",
  ui_story_1019_10190501_83_dialog_content = "Ia bersembunyi di belakangmu. Saya rasa ia tidak menerima ide itu.",
  ui_story_1019_10190501_84_dialog_content = "Huu...",
  ui_story_1019_10190501_85_dialog_content = "Bisakah kamu melihat? Dia hanya berpura-pura sulit untuk didapatkan.",
  ui_story_1019_10190501_86_dialog_content = "Oke... Kalau begitu, biar kucoba.",
  ui_story_1019_10190501_87_dialog_content = "Huu...",
  ui_story_1019_10190501_88_option_content = "Tautan Telepati",
  ui_story_1019_10190501_89_dialog_content = "(Tunggu, apakah Bool bersembunyi di belakang Algol lagi? Saya hanya melihat Algol...)",
  ui_story_1019_10190501_90_dialog_content = "(Apakah ada yang salah?)",
  ui_story_1019_10190501_91_dialog_content = "(Saya tidak melihat ada apa-apa di sekitar...)",
  ui_story_1019_10190501_92_dialog_content = "(Apakah Algol bukan Aurorian tetapi droid? AI, mungkin?!)",
  ui_story_1019_10190501_93_dialog_content = "(Tidak mungkin... Apa ini ide gila? Dia baru saja bertarung menggunakan Lumina!)",
  ui_story_1019_10190501_94_dialog_content = "(Mungkin saya tidak cukup dalam dan harus pergi lebih dalam.)",
  ui_story_1019_10190501_95_dialog_content = "(Masuk lebih dalam...)",
  ui_story_1019_10190501_96_dialog_content = "(Lebih dalam...)",
  ui_story_1019_10190501_97_dialog_content = "(Hah? Apakah itu... Bool?)",
  ui_story_1019_10190501_98_dialog_content = "(Aku sebenarnya bisa beralih antara dua objek yang bisa kurasakan. Perasaan ini luar biasa. Rasanya seperti aku memiliki dua pasang mata...)",
  ui_story_1019_10190501_99_dialog_content = "<color=#e8d9bb>Huu!!! Plak—</color>",
  ui_story_1019_10190501_100_dialog_content = "Aah!",
  ui_story_1019_10190601_1_dialog_content = "Saya lihat Bool juga sangat peduli padamu!",
  ui_story_1019_10190601_2_dialog_content = "Detak jantung, tekanan darah... Semua normal, dan tingkat oksigen dalam darahmu telah membaik.",
  ui_story_1019_10190601_3_dialog_content = "Kamu menyebut penghajaran itu sebagai olahraga?",
  ui_story_1019_10190601_4_dialog_content = "Apa maksudmu dengan \"dihajar\"? Kamu bahkan tidak memiliki satu lebam pun di tubuhmu, belum lagi ini adalah cara yang canggih untuk berkomunikasi.",
  ui_story_1019_10190601_5_dialog_content = "Hiks!",
  ui_story_1019_10190601_6_dialog_content = "Aku ingat nada itu! Kamu tidak berpikir sudah terlambat untuk menunjukkan simpati sekarang...",
  ui_story_1019_10190601_7_dialog_content = "Dr. Algol, bagaimana Anda berkomunikasi dengan Bool?",
  ui_story_1019_10190601_8_dialog_content = "Nah, Bool menyampaikan pesan yang berbeda dengan memukul saya dengan intensitas yang bervariasi. Jelas, itu masih harus dikerjakan dengan Caelestite.",
  ui_story_1019_10190601_9_dialog_content = "Tidak apa-apa. Itu adalah sesuatu yang bisa saya lakukan tanpa.",
  ui_story_1019_10190601_10_dialog_content = "Tapi Bool selalu bersikap ramah padamu sebelumnya. Kenapa dia berperilaku seperti itu...?",
  ui_story_1019_10190601_11_dialog_content = "Nah, aku memang melihat sesuatu di pikiran Bool.",
  ui_story_1019_10190601_12_dialog_content = "Tetapi tidak seperti Guardian One, gambar tersebut tidak spesifik dan tidak jelas.",
  ui_story_1019_10190601_13_dialog_content = "Pikiran Bool bekerja lebih seperti komputer, setelah semua.",
  ui_story_1019_10190601_14_dialog_content = "Lagipula, mohon maafkan kehebohan itu. Itu tidak terlalu menyakitimu, kan?",
  ui_story_1019_10190601_15_dialog_content = "...",
  ui_story_1019_10190601_16_dialog_content = "<color=#e8d9bb>Bip — Bip — Bip —</color>",
  ui_story_1019_10190601_17_dialog_content = "Hei, koordinat tertentu dalam data Soroz memang muncul di peta baru.",
  ui_story_1019_10190601_18_dialog_content = "Kita belum pernah memeriksa tempat itu sebelumnya, bukan?",
  ui_story_1019_10190601_19_dialog_content = "Tunggu, apakah ini berarti kita memiliki beberapa set koordinat?",
  ui_story_1019_10190601_20_dialog_content = "Ini bisa saja dari sumber yang sama tetapi dengan sinyal yang berfluktuasi.",
  ui_story_1019_10190601_21_dialog_content = "Barat laut dari Gannon, sekitar 2.500 mil...",
  ui_story_1019_10190601_22_dialog_content = "Yah, masih bisa dilakukan. Tidak sejauh yang kukira.",
  ui_story_1019_10190601_23_dialog_content = "Tapi, sinyal-sinyal ini jauh lebih tua daripada yang dari Obelisk of Return.",
  ui_story_1019_10190601_24_dialog_content = "Maksudmu Eraveil bukan tempat asal Colossus?",
  ui_story_1019_10190601_25_dialog_content = "Benar sekali. Lokasi Eraveil saat ini lebih berfungsi seperti benteng perbatasan Eclipsite dalam invasi mereka ke Astra.",
  ui_story_1019_10190601_26_dialog_content = "Colossus mungkin berasal dari Zona Gelap.",
  ui_story_1019_10190601_27_dialog_content = "Jadi Eraveil bukanlah rumah Soroz...",
  ui_story_1019_10190601_28_dialog_content = "Mungkin bukan rumah Caelestite...",
  ui_story_1019_10190601_29_dialog_content = "Lokasi rumah seseorang tidak memiliki arti penting, Caelestite.",
  ui_story_1019_10190601_30_dialog_content = "Intinya, Soroz telah tinggal bersama Caelestites di Eraveil sejak pertama kali memahami konsep \"rumah\".",
  ui_story_1019_10190601_31_dialog_content = "Dari perspektif biomekanik, versi terkini dari Soroz seharusnya dihitung sebagai ciptaan Anda.",
  ui_story_1019_10190601_32_dialog_content = "...",
  ui_story_1019_10190601_33_dialog_content = "Jangan merasa kecewa. Kita hanya sedang berspekulasi sekarang.",
  ui_story_1019_10190601_34_dialog_content = "Kami akan menemukan jawabannya setelah kita konfirmasi lokasinya.",
  ui_story_1019_10190601_35_dialog_content = "Dr. Algol, apa yang harus kita lakukan untuk mempersiapkan pencarian di Dark Zone?",
  ui_story_1019_10190601_36_dialog_content = "Dengan intel dari Helios dan Tim Ekspedisi Zona Gelap, kita mulai sedikit mengetahui tentang Zona Gelap.",
  ui_story_1019_10190601_37_dialog_content = "Seorang ahli sedang membuat peta sekarang, didukung oleh data Soroz.",
  ui_story_1019_10190601_38_dialog_content = "Mari kita bicara dengannya. Ini pasti akan menarik.",
  ui_story_1019_10190601_39_dialog_content = "Tentu.",
  ui_story_1019_10190601_40_dialog_content = "<color=#e8d9bb>Ding!</color>",
  ui_story_1019_10190601_41_dialog_content = "Hmm? Ada Eclipsite di Taman Teknologi... Siapa yang bertanggung jawab atas patroli?",
  ui_story_1019_10190601_42_dialog_content = "Barton seharusnya bertugas pada saat ini. Bagaimana kamu tahu ada Eclipsite di Tech Park?",
  ui_story_1019_10190601_43_dialog_content = "Gelangku bisa merasakan ancaman di sekitar, tapi tidak akan menjadi masalah jika Barton berjaga.",
  ui_story_1019_10190601_44_dialog_content = "Taman Teknologi adalah tempat penting di Gannon. Kita tidak boleh ada Eclipsite di sekitar sini.",
  ui_story_1019_10190601_45_dialog_content = "Di mana Eclipsites? Saya harus mencarinya dan menempatkan pengawal segera.",
  ui_story_1019_10190601_46_dialog_content = "Barton sudah mengerjakannya.",
  ui_story_1019_10190601_47_dialog_content = "Laporkan ancaman, evaluasi Eclipsite, kirim prajurit, bunuh Eclipsite, perbaiki pelanggaran... gelang ini bisa melakukan semua itu.",
  ui_story_1019_10190601_48_dialog_content = "Namun…",
  ui_story_1019_10190601_49_dialog_content = "Percayalah padaku, tidak apa-apa. Kamu tidak bisa menangani segalanya sendiri. Itu akan membuatmu lelah.",
  ui_story_1019_10190601_50_dialog_content = "Ini tugasku. Aku tidak merasa lelah.",
  ui_story_1019_10190601_51_dialog_content = "Cukup pendiam, tapi Bool bilang lingkaran hitam di bawah matamu sudah mengkhianatimu.",
  ui_story_1019_10190601_52_dialog_content = "Hiks!",
  ui_story_1019_10190601_53_dialog_content = "Ayo, kita akan melewati sumber ancaman di perjalanan kita. Kita bisa memeriksanya jika kamu masih khawatir.",
  ui_story_1019_10190601_54_dialog_content = "Hiks!",
  ui_story_1019_10190702_1_dialog_content = "Tidak bisa membayangkan Eclipsite di Taman Teknologi...",
  ui_story_1019_10190702_2_dialog_content = "Apakah itu benar-benar Eclipsite? Mengapa ia lebih tampak seperti prajurit Illumina?",
  ui_story_1019_10190702_3_dialog_content = "Tanyakan pada Barton. Dia seharusnya sudah selesai dengan Eclipsite di ujungnya.",
  ui_story_1019_10190702_4_dialog_content = "Apa yang sedang kamu lakukan di sini? Bukankah Grand Marshal sudah menyuruhmu untuk tinggal di Eraveil?",
  ui_story_1019_10190702_5_dialog_content = "Yah, ceritanya panjang.",
  ui_story_1019_10190702_6_dialog_content = "Aku sudah menyuruh Caelestite itu untuk datang.",
  ui_story_1019_10190702_7_dialog_content = "Kamu Algol, ilmuwan yang mengirimkan pesan kepadaku, benar?",
  ui_story_1019_10190702_8_dialog_content = "Ya. Eclipsites tidak menyelinap masuk dari luar, bukan?",
  ui_story_1019_10190702_9_dialog_content = "Semakin sedikit kalian para ilmuwan yang ikut campur dengan Eclipsite, semakin baik.",
  ui_story_1019_10190702_10_dialog_content = "Saya yakin Anda mendengar apa yang terjadi di Twilight. Meskipun Ulysses tidak berhasil, itu masih memberikan dampak besar pada militer.",
  ui_story_1019_10190702_11_dialog_content = "Jangan samakan saya dengan ilmuwan lainnya. Saya tidak tertarik pada Aurorian.",
  ui_story_1019_10190702_12_dialog_content = "Barton, Dr. Algol memiliki niat baik. Tolong beri tahu kami apa yang sedang terjadi dengan Eclipsite.",
  ui_story_1019_10190702_13_dialog_content = "...",
  ui_story_1019_10190702_14_dialog_content = "Sejujurnya, ini aneh! Aku tidak melihat Eclipsite saat tiba di lokasi. Aku hanya melihat dua prajurit yang lewat di dekat gedung lab...",
  ui_story_1019_10190702_15_dialog_content = "Siapa yang tahu ketika saya mendekat, mereka menyerang saya seperti anjing gila!",
  ui_story_1019_10190702_16_dialog_content = "Kami menemui hal yang sama.",
  ui_story_1019_10190702_17_dialog_content = "Sekarang jika saya pikirkan, mereka mungkin dari Program Fosfor. Apa pendapatmu, Nak?",
  ui_story_1019_10190702_18_dialog_content = "Ketika saya mengarahkan operasi Anda, saya bisa merasakan Darkflow pada mereka itu berbeda.",
  ui_story_1019_10190702_19_dialog_content = "Jika mereka adalah Eclipsites, mungkin ada masalah dengan sistem pertahanan yang membuat mereka bisa melarikan diri dari penahanan laboratorium.",
  ui_story_1019_10190702_20_dialog_content = "Itu mungkin. Taman Teknologi Illumina memiliki lebih dari pusat medis dan Laboratorium Black Umbrella...",
  ui_story_1019_10190702_21_dialog_content = "Seperti ilmuwan yang melakukan eksperimen pada subjek Aurorian!",
  ui_story_1019_10190702_22_dialog_content = "Huu...",
  ui_story_1019_10190702_23_dialog_content = "Mengapa kamu tidak menghadapi Ulysses tentang hal itu?",
  ui_story_1019_10190702_24_dialog_content = "Kamu pikir saya tidak mau?",
  ui_story_1019_10190702_25_dialog_content = "Tidak ada akhir untuk penyelidikan Phospherus dan Komite telah memalingkan muka terhadap Ulysses yang mengubah para prajurit!",
  ui_story_1019_10190702_26_dialog_content = "Jika kamu bertanya padaku, ini hanya semakin membahayakan Gannon setiap hari!",
  ui_story_1019_10190702_27_dialog_content = "Mengapa Illumina tidak menjatuhkan hukuman kepada Ulysses yang telah merugikan begitu banyak prajurit?",
  ui_story_1019_10190702_28_dialog_content = "Aku bisa menjelaskan itu.",
  ui_story_1019_10190702_29_dialog_content = "Ini demi prajurit karena Ulysses memiliki kewajiban untuk membantu merawat yang terluka.",
  ui_story_1019_10190702_30_dialog_content = "Dan setiap dokumen yang relevan dengan kasus ini berada di gedungnya. Panel tinjauan masih mengakses dan memeriksa mereka.",
  ui_story_1019_10190702_31_dialog_content = "Plus, meskipun Ulysses sedang diawasi, dia masih relatif bebas untuk melakukan apa pun yang dia inginkan.",
  ui_story_1019_10190702_32_dialog_content = "Jadi kecuali jika mendesak, kita tidak bisa masuk ke laboratoriumnya.",
  ui_story_1019_10190702_33_dialog_content = "Anda dapat menggunakan pelanggaran Eclipsite sebagai alasan untuk memeriksa Ulysses.",
  ui_story_1019_10190702_34_dialog_content = "Hiks!",
  ui_story_1019_10190702_35_dialog_content = "Aku sudah mencoba itu. Tidak berhasil.",
  ui_story_1019_10190702_36_dialog_content = "Lalu, ikuti saya. Saya berwenang untuk masuk ke labnya. Saya akan bilang kalian di sini untuk membantu saya.",
  ui_story_1019_10190702_37_dialog_content = "Setidaknya dari yang saya tahu, tidak ada cara Eclipsite bisa menembus level terendah di Gannon dari luar.",
  ui_story_1019_10190702_38_dialog_content = "Juga, saya tidak ingin Illumina Tech Park menjadi sarang Eclipsite setelah kehilangan inti Guardian One.",
  ui_story_1019_10190702_39_dialog_content = "Itu ide bagus. Apa pendapatmu, Barton?",
  ui_story_1019_10190702_40_dialog_content = "Ayo kita coba...",
  ui_story_1019_10190702_41_dialog_content = "Ayo pergi, tapi hati-hati, jika Eclipsites berhasil kabur dari gudang, akan ada lebih banyak di dalamnya.",
  ui_story_1019_10190802_1_dialog_content = "Huuu!",
  ui_story_1019_10190802_2_dialog_content = "Hei, jangan terburu-buru. Saya sedang mengirimkan data kepada Anda sekarang...",
  ui_story_1019_10190802_3_dialog_content = "Para prajurit patroli melaporkan bahwa tidak ada Eclipsite yang terlihat di gedung lain, jadi ini seharusnya adalah tempat yang tepat.",
  ui_story_1019_10190802_4_dialog_content = "Apakah Ulysses sengaja membebaskan Eclipsites ini?",
  ui_story_1019_10190802_5_dialog_content = "Kurasa dia tidak punya nyali. Lagipula, dia tidak cukup bodoh untuk ingin mati bersama sisanya di Illumina.",
  ui_story_1019_10190802_6_dialog_content = "Ahem, itu pujian untukku, ya?",
  ui_story_1019_10190802_7_dialog_content = "Apakah kamu tahu ada Eclipsites di labmu, Ulysses?",
  ui_story_1019_10190802_8_dialog_content = "Tidak pernah ada kekurangan subjek Eclipsite di gedung laboratorium ini demi penelitian Aurorian dan Eclipsite.",
  ui_story_1019_10190802_9_dialog_content = "Itu bukan rahasia. Atau urusanmu juga.",
  ui_story_1019_10190802_10_dialog_content = "Tapi sejak inti itu dicuri, ada banyak celah di katup gudang gedung laboratorium. Itulah mungkin dari mana Eclipsites melarikan diri.",
  ui_story_1019_10190802_11_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_1019_10190802_12_dialog_content = "Mereka bukan Eclipsite yang digunakan untuk tujuan eksperimental. Plus, kamu jelas dilarang untuk mengubah Aurorian.",
  ui_story_1019_10190802_13_dialog_content = "Dan apakah mereka adalah prajurit yang telah berubah atau subjek Eclipsite sebenarnya...",
  ui_story_1019_10190802_14_dialog_content = "Kami memiliki hak untuk menyelidiki ketika mereka melarikan diri dari laboratorium Anda dan mengancam orang-orang kami.",
  ui_story_1019_10190802_15_dialog_content = "Jelas dilarang? Hah...",
  ui_story_1019_10190802_16_dialog_content = "Meski begitu, siapa yang memberi izin kepada Anda untuk masuk ke gedung saya dan berurusan dengan subjek-subjek Eclipsite itu?",
  ui_story_1019_10190802_17_dialog_content = "Tidak peduli apa yang dikatakan Komite. Tugas kita adalah membunuh semua Eclipsite!",
  ui_story_1019_10190802_18_dialog_content = "Kamu tidak bisa benar hanya karena kamu yang paling keras suaranya. Namun, kamu memang harus pandai untuk melacak subjek bagi saya.",
  ui_story_1019_10190802_19_dialog_content = "Bagaimana kamu bisa...!",
  ui_story_1019_10190802_20_dialog_content = "Aku hanya memeriksa sistem Bool barusan... Bagaimana bisa situasinya menjadi begitu kacau?",
  ui_story_1019_10190802_21_dialog_content = "Saya mengundang mereka untuk membantu saya, Ulysses. Ini tidak ada hubungannya dengan kamu.",
  ui_story_1019_10190802_22_dialog_content = "Tidak begitu cepat...",
  ui_story_1019_10190802_23_dialog_content = "Anda memiliki pesan dari Komite, ma'am.",
  ui_story_1019_10190802_24_dialog_content = "Mereka berharap Anda akan menghadiri tinjauan akhir tepat waktu.",
  ui_story_1019_10190802_25_dialog_content = "... Aku paham.",
  ui_story_1019_10190802_26_dialog_content = "(Apakah Ulysses sedang menatapku?)",
  ui_story_1019_10190802_27_dialog_content = "Sudah lama tidak bertemu, Caelestite.",
  ui_story_1019_10190802_28_dialog_content = "Itu terjadi di ruang konferensi waktu itu, kamu dan Reinhardt. Algol juga ada di sana.",
  ui_story_1019_10190802_29_dialog_content = "Betapa membuang-buang waktu pertemuan yang membosankan, monoton, dan sombong itu.",
  ui_story_1019_10190802_30_dialog_content = "Itu adalah waktu yang lama sebelumnya, setelah itu perubahan baru telah terjadi di dunia ini. Tapi tidak ada yang luput dari pengetahuanmu. Benar kan, Caelestite?",
  ui_story_1019_10190802_31_dialog_content = "Apa maksudmu?",
  ui_story_1019_10190802_32_dialog_content = "Saya telah mendapatkan visi yang aneh untuk waktu yang lama, dan mereka datang kepada saya lebih sering dalam beberapa tahun terakhir.",
  ui_story_1019_10190802_33_dialog_content = "Adegan-adegan itu terasa begitu nyata seolah-olah mereka secara fisik mengendalikan gerakan tubuhku, detak jantungku...",
  ui_story_1019_10190802_34_dialog_content = "Bu! Bu! Bu!",
  ui_story_1019_10190802_35_dialog_content = "Tempat apa itu?",
  ui_story_1019_10190802_36_dialog_content = "Detak Jantung?",
  ui_story_1019_10190802_37_dialog_content = "Kita berdua bisa melihat kebenaran, namun selalu ada seseorang yang mencoba menjauhkanku dari itu...",
  ui_story_1019_10190802_38_dialog_content = "Dan membuatmu buta terhadap tujuan hidup... Sungguh sangat disayangkan untukmu.",
  ui_story_1019_10190802_39_dialog_content = "Ahem, jadi siapa yang akan tersisa untuk melawan Eclipsites setelah tinjauan akhir?",
  ui_story_1019_10190802_40_dialog_content = "Apa yang sedang kamu omongkan? Aku belum pernah bertemu dengan orang yang tidak bisa kalahkan.",
  ui_story_1019_10190802_41_dialog_content = "Saya pikir kamu mencoba memenangkan PlayerName dan memaafkan kejahatanmu!",
  ui_story_1019_10190802_42_dialog_content = "Sama sekali tidak. Saya hanya bertanya kepada Caelestite Terakhir di Astra karena penasaran.",
  ui_story_1019_10190802_43_dialog_content = "Jika Anda memanfaatkan kesempatan ini, Anda mungkin bisa melihat kebenaran di sini...",
  ui_story_1019_10190802_44_dialog_content = "Bu! Bu! Bu!",
  ui_story_1019_10190802_45_dialog_content = "Hei, tunggu sebentar. Aku bingung...",
  ui_story_1019_10190802_46_dialog_content = "Apa yang salah dengan Bool?",
  ui_story_1019_10190802_47_dialog_content = "Ini bertingkah aneh. Belum pernah ia berperilaku seperti ini sebelumnya.",
  ui_story_1019_10190802_48_dialog_content = "Heh, siapa yang bisa bilang perilaku aneh ini bukan berkah?",
  ui_story_1019_10190802_49_dialog_content = "Berkat?",
  ui_story_1019_10190802_50_dialog_content = "Ketika mimpi buruk datang mengetuk, adalah berkah ketika ada seseorang yang menjaga pintu.",
  ui_story_1019_10190802_51_dialog_content = "Tapi sampai sekarang, semuanya masih tampak kabur...",
  ui_story_1019_10190802_52_dialog_content = "Tahu kan, waktu yang kamu habiskan untuk berteka-teki sebaiknya digunakan untuk mencari tahu apa yang salah dengan dirimu.",
  ui_story_1019_10190802_53_dialog_content = "Ah, enaknya menjadi muda.",
  ui_story_1019_10190802_54_dialog_content = "Jadi, PlayerName, kebenaran apa yang ingin kamu ketahui?",
  ui_story_1019_10190802_55_dialog_content = "(Jangan bilang dia tahu...)",
  ui_story_1019_10190802_56_option_content = "(Kebenaran di balik mimpi?)",
  ui_story_1019_10190802_57_option_content = "(Kenyataan dari detak jantung Vice?)",
  ui_story_1019_10190802_58_dialog_content = "(Tapi bagaimana mungkin dia tahu?)",
  ui_story_1019_10190802_59_dialog_content = "(Atau dia hanya menggunakan saya untuk menghapuskan rasa bersalahnya sendiri, seperti yang Vivian katakan?)",
  ui_story_1019_10190802_60_dialog_content = "Melihat cara kamu ragu, pasti ada pertanyaan yang ingin kamu ajukan.",
  ui_story_1019_10190802_61_dialog_content = "Yang perlu kamu lakukan hanyalah datang ke labku dan membantu aku dengan \"eksperimen\" kecil. Lalu, kamu akan tahu jawabannya.",
  ui_story_1019_10190802_62_dialog_content = "Kita bahkan bisa mengetahui... batas dirimu.",
  ui_story_1019_10190802_63_dialog_content = "Grand Marshal sudah menjelaskan untuk menghentikan semua percobaan, Ulysses!",
  ui_story_1019_10190802_64_dialog_content = "Lupakan eksperimen. Sentuh PlayerName, dan saya akan mendapatkanmu sendiri.",
  ui_story_1019_10190802_65_dialog_content = "Kalian berdua salah paham. Aku lah yang akan menjadi subjek eksperimen, yang akan dilakukan oleh PlayerName.",
  ui_story_1019_10190802_66_dialog_content = "Lagipula, setiap spekulasi yang lahir dari rasa penasaran harus diverifikasi melalui eksperimen, 'kan?",
  ui_story_1019_10190802_67_dialog_content = "Eksperimen apa yang ada di pikiranmu?",
  ui_story_1019_10190802_68_dialog_content = "Saya ingin kamu menggunakan kemampuan psikismu untuk melihat beberapa mimpi aneh saya dan melihat apakah jawaban yang kamu cari ada di antara mereka.",
  ui_story_1019_10190802_69_dialog_content = "Mimpi aneh!",
  ui_story_1019_10190802_70_dialog_content = "Bu! Bu! Bu!",
  ui_story_1019_10190802_71_dialog_content = "Apa yang terjadi? Kita harus keluar dari sini sekarang, Caelestite.",
  ui_story_1019_10190802_72_dialog_content = "Tapi, aku ingin tinggal...",
  ui_story_1019_10190802_73_dialog_content = "PlayerName?!",
  ui_story_1019_10190802_74_dialog_content = "Saya ingin mencoba eksperimen ini.",
  ui_story_1019_10190802_75_dialog_content = "Bu! Bu! Bu!",
  ui_story_1019_10190802_76_dialog_content = "Hei, tunggu... Berhenti menyeretku...",
  ui_story_1019_10190802_77_dialog_content = "Maaf, saya harus menyelesaikan masalah dengan Bool terlebih dahulu.",
  ui_story_1019_10190802_78_dialog_content = "Jangan khawatir. Aku akan tetap mengawasi, meski itu bukan tanggung jawabku.",
  ui_story_1019_10190802_79_dialog_content = "Tapi ini adalah tugas saya untuk memastikan PlayerName aman.",
  ui_story_1019_10190802_80_dialog_content = "Lab saya aman. Silakan masuk.",
  ui_story_1019_10190901_1_dialog_content = "Apakah kamu siap, Caelestite? Saya ingin bertanya sesuatu sebelum kita mulai.",
  ui_story_1019_10190901_2_dialog_content = "Bagaimana menurutmu penampakan akhir dunia nanti?",
  ui_story_1019_10190901_3_dialog_content = "Jika Krisis Darkover terjadi lagi, bagaimana Aurorian bisa melawannya?",
  ui_story_1019_10190901_4_dialog_content = "Uh, itu tidak pernah terlintas di pikiranku.",
  ui_story_1019_10190901_5_dialog_content = "Caelestite pernah mencapai prestasi besar dengan meninggalkan Astra. Bukankah kamu ingin tahu bagaimana rasanya langit yang belum terjamah itu?",
  ui_story_1019_10190901_6_dialog_content = "Itu juga merupakan keajaiban Caelestite dan Colossus kuno yang terlalu jauh dari masa kini.",
  ui_story_1019_10190901_7_dialog_content = "Saya hanya orang biasa. Sudut terjauh yang pernah saya kunjungi adalah tanah timur yang tidak jauh dari Astra.",
  ui_story_1019_10190901_8_dialog_content = "Heh, kalian selalu membiarkan rasa takut membatasi imajinasi kalian.",
  ui_story_1019_10190901_9_dialog_content = "Kenapa bisa begitu?",
  ui_story_1019_10190901_10_dialog_content = "Tak lama lagi kau akan tahu. Sekarang, mari kita mulai.",
  ui_story_1019_10190901_11_dialog_content = "...",
  ui_story_1019_10190901_12_option_content = "Tautan Telepati",
  ui_story_1019_10190901_13_dialog_content = "Ini Northland...?",
  ui_story_1019_10190901_14_dialog_content = "Begitu banyak pilar es, menunjuk ke langit seperti pisau.",
  ui_story_1019_10190901_15_dialog_content = "Tidak, kegelapan ini lebih dekat dengan Zona Gelap...",
  ui_story_1019_10190901_16_dialog_content = "Saya pernah menjelajahi Reruntuhan Aurora sebelumnya. Mereka memiliki beberapa batu hitam yang memberikan suasana dingin yang sama.",
  ui_story_1019_10190901_17_dialog_content = "Namun batu-batu itu terletak datar di tanah yang kokoh, sedangkan pilar-pilar ini melayang di udara.",
  ui_story_1019_10190901_18_dialog_content = "Beberapa bahkan bercahaya dan membentang ke atas...",
  ui_story_1019_10190901_19_dialog_content = "Apakah ini bagian dari ingatan Ulysses? Mengapa dia datang ke sini?",
  ui_story_1019_10190901_20_dialog_content = "Dan bagaimana mungkin kenangan seperti itu ada dalam kesadarannya?",
  ui_story_1019_10190901_21_dialog_content = "Ini adalah tempat yang terlantar tanpa tanda-tanda kehidupan...",
  ui_story_1019_10190901_22_dialog_content = "<color=#e8d9bb>Klink, denting!</color>",
  ui_story_1019_10190901_23_dialog_content = "Ada apa?",
  ui_story_1019_10190901_24_dialog_content = "Pilar-pilar tersebut berubah seolah-olah ditarik oleh suatu kekuatan menjadi satu gugusan menuju langit.",
  ui_story_1019_10190901_25_dialog_content = "Apakah mereka sedang menyatu menjadi sesuatu?",
  ui_story_1019_10190901_26_dialog_content = "Tempat apa ini sebenarnya?",
  ui_story_1019_10190901_27_dialog_content = "<color=#e8d9bb>Menabrak...</color>",
  ui_story_1019_10190901_28_dialog_content = "*Terengah-engah*",
  ui_story_1019_10190901_29_dialog_content = "Jadi bagaimana perasaanmu, Caelestite?",
  ui_story_1019_10190901_30_dialog_content = "Apa yang dia tunjukkan kepadamu, Nak?!",
  ui_story_1019_10190901_31_option_content = "Di mana tempat itu?",
  ui_story_1019_10190901_32_dialog_content = "Ini...",
  ui_story_1019_10190901_33_option_content = "Mengapa kamu menunjukkan ini padaku?",
  ui_story_1019_10190901_34_dialog_content = "Karena…",
  ui_story_1019_10190901_35_dialog_content = "Itulah akhir dari dunia.",
  ui_story_1019_10190901_36_dialog_content = "Di mana Eclipsite mengintai dan mencoba membangkitkan iblis...",
  ui_story_1019_10190901_37_dialog_content = "Iblis...?",
  ui_story_1019_10190901_38_dialog_content = "(Apakah itu yang saya dengar tentang Medan Perang Kuno?)",
  ui_story_1019_10190901_39_dialog_content = "Tapi aku tidak melihat Eclipsite, hanya tiang-tiang es yang tak terhitung jumlahnya.",
  ui_story_1019_10190901_40_dialog_content = "Itu karena mereka sudah mulai.",
  ui_story_1019_10190901_41_dialog_content = "Dimulai?",
  ui_story_1019_10190901_42_dialog_content = "Bangkitkan iblis!",
  ui_story_1019_10190901_43_dialog_content = "...",
  ui_story_1019_10190901_44_dialog_content = "Ulysses, kamu gila! Menjauhlah dari PlayerName!",
  ui_story_1019_10190901_45_dialog_content = "Saya melihat Kepala Staf, Komandan Barton, dan PlayerName semuanya ada di sini...",
  ui_story_1019_10190901_46_dialog_content = "Tepat waktu, Anatoli.",
  ui_story_1019_10190901_47_dialog_content = "Komite yang mengirimmu ke sini, kan?",
  ui_story_1019_10190901_48_dialog_content = "Ya, Dr. Ulysses. Ini adalah briefing investigasi Phospherus yang telah Anda diberitahu.",
  ui_story_1019_10190901_49_dialog_content = "Aku akan hadir. Namun...",
  ui_story_1019_10190901_50_dialog_content = "Saya berharap Caelestite juga bisa berpartisipasi karena Komite menganggapnya sebagai penyelamat Aurorian.",
  ui_story_1019_10190901_51_dialog_content = "Saya khawatir itu melanggar aturan, Dr. Ulysses.",
  ui_story_1019_10190901_52_dialog_content = "Dan aturan mana yang memungkinkan Caelestite untuk masuk dan keluar Gannon sesuka hati?",
  ui_story_1019_10190901_53_dialog_content = "Pertimbangkan usulan saya, Caelestite. Saya tahu ada hal-hal yang ingin Anda ketahui.",
  ui_story_1019_10190901_54_dialog_content = "Mungkin hanya aku, di seluruh Illumina, yang bisa dan akan memberitahumu kebenaran.",
  ui_story_1019_10190901_55_dialog_content = "...",
  ui_story_1019_10190901_56_dialog_content = "Apakah kamu sadar apa yang paling penting untukmu saat ini? Lakukan persiapan untuk bertahan hidup sebelum setan datang!",
  ui_story_1019_10190901_57_dialog_content = "...",
  ui_story_1019_10190901_58_dialog_content = "Bawa Ulysses pergi, Anatoli.",
  ui_story_1019_10190901_59_dialog_content = "Caelestite?",
  ui_story_1019_10190901_60_dialog_content = "...",
  ui_story_1019_10190901_61_dialog_content = "Hahaha... Bagaimana mungkin kau bisa menjadi penyelamat Aurorian, benar? *batuk*",
  ui_story_1019_10190901_62_dialog_content = "Ragu, lemah, tanpa ambisi! Kamu itu... *uhuk-uhuk*",
  ui_story_1019_10190901_63_dialog_content = "Maaf, saya terlambat, pak. Mohon izinkan saya membantu Anda.",
  ui_story_1019_10190901_64_dialog_content = "Tidak perlu!",
  ui_story_1019_10190901_65_dialog_content = "Ha…",
  ui_story_1019_10190901_66_dialog_content = "(Darkflow? Tidak, tidak tepatnya...)",
  ui_story_1019_10190901_67_dialog_content = "Aku tak akan pernah berhenti... Semua dari kalian akan menyesalinya! *batuk*",
  ui_story_1019_10190901_68_dialog_content = "Anda goyah, Dokter... Apakah Anda yakin Anda baik-baik saja?",
  ui_story_1019_10190901_69_dialog_content = "Ini aku! Jangan sentuh aku!",
  ui_story_1019_10190901_70_dialog_content = "Hraaagh!!!",
  ui_story_1019_10190901_71_dialog_content = "Kilauan, bersembunyi di bayang-bayang.",
  ui_story_1019_10190901_72_dialog_content = "Sebuah musuh yang menyerupai Eclipsite, sama seperti yang kita temui sebelumnya...",
  ui_story_1019_10190901_73_dialog_content = "Ini bukan musuhmu...",
  ui_story_1019_10190901_74_dialog_content = "Lalu apa itu?!",
  ui_story_1019_10190901_75_dialog_content = "Simpanlah untuk panel tinjauan. Pimpin kami, PlayerName, dan kita akan menghancurkannya!",
  ui_story_1019_10190901_76_dialog_content = "Tentu!",
  ui_story_1019_10190902_1_dialog_content = "Turunkan pedang itu, Barton!",
  ui_story_1019_10190902_2_dialog_content = "Saya sudah melaporkan ini ke Grand Marshal. Orang-orangnya sedang dalam perjalanan dan dia ingin kita untuk memecahkan masalah di lab.",
  ui_story_1019_10190902_3_dialog_content = "Kamu membiarkan orang gila itu hidup? Makhluk itu menyerang kita tapi tidak Ulysses!",
  ui_story_1019_10190902_4_dialog_content = "Ini akan menjadi akhir dari Illumina jika dia membebaskan Eclipsite di laboratorium!",
  ui_story_1019_10190902_5_dialog_content = "Anatoli sekarang bertanggung jawab atas masalah yang menyangkut Ulysses, Barton. Grand Marshal menyatakan bahwa dia akan mencari tahu sampai ke akar masalah ini.",
  ui_story_1019_10190902_6_dialog_content = "Hei, aku melihat kerumunan! Apa yang aku lewatkan?",
  ui_story_1019_10190902_7_dialog_content = "Anak muda juga ada di sini. Saya lihat kamu telah dibaptis dengan api. Bahkan aroma kalian pun berbeda!",
  ui_story_1019_10190902_8_dialog_content = "...",
  ui_story_1019_10190902_9_dialog_content = "Saya akan membawa Dr. Ulysses bersamaku meskipun kalian berdua menghalangi.",
  ui_story_1019_10190902_10_dialog_content = "Jangan pedulikan itu. Kita di sini hanya untuk mengambil alih labnya. Baiklah, semua orang keluar!",
  ui_story_1019_10190902_11_dialog_content = "Mengambil alih labku? Sungguh konyol...",
  ui_story_1019_10190902_12_dialog_content = "Saya adalah ketua Dewan Sains! Kamu tidak bisa menyamai pencapaian saya dalam sepuluh kehidupan.",
  ui_story_1019_10190902_13_dialog_content = "Bagus kamu telah mencapai semua itu! Meski monopoli tidak diperbolehkan di Illumina. Dan saya rasa tidak ada file di sini yang tidak bisa saya pahami.",
  ui_story_1019_10190902_14_dialog_content = "Tapi sebelum Anda pergi, dok, maukah Anda menyerahkan akses komputer?",
  ui_story_1019_10190902_15_dialog_content = "Kami, Laboratorium Payung Hitam, juga akan mengambil alih subjek Eclipsite dan bahan biologis.",
  ui_story_1019_10190902_16_dialog_content = "Tenanglah, selama aku di sini, tidak akan ada Eclipsite yang berkeliaran di Tech Park.",
  ui_story_1019_10190902_17_dialog_content = "Kamu benar-benar tidak ingin mencari tahu kebenaran, Caelestite?",
  ui_story_1019_10190902_18_option_content = "Tidak.",
  ui_story_1019_10190902_19_dialog_content = "(Ada hubungan aneh antara Ulysses dan visi-visi itu...)",
  ui_story_1019_10190902_20_dialog_content = "(Aku harus memberitahu Vivian tentang apa yang aku lihat.)",
  ui_story_1019_10190902_21_option_content = "Ya, aku suka.",
  ui_story_1019_10190902_22_dialog_content = "(Mengapa Ulysses menunjukkan visi itu padaku... Apakah dia mencoba memberi tahu saya sesuatu?)",
  ui_story_1019_10190902_23_dialog_content = "(Tapi dia tampaknya tidak benar, jadi mungkin saya tidak seharusnya mempercayainya...)",
  ui_story_1019_10190902_24_dialog_content = "Saya percaya kebenaran akan terungkap setelah tinjauan.",
  ui_story_1019_10190902_25_dialog_content = "Hahaha…",
  ui_story_1019_10190902_26_dialog_content = "Jadi ini adalah akhir dari Aurorian, begitu... Usahaku pada akhirnya diinjak-injak oleh kalian, para bodoh.",
  ui_story_1019_10190902_27_dialog_content = "Lupakan saja, lupakan saja...",
  ui_story_1019_10190902_28_dialog_content = "Kalau begitu, izinkan saya mengungkapkannya secara pribadi.",
  ui_story_1019_10190902_29_dialog_content = "Ini akan menjadi semacam kehormatan bagi kalian untuk menyaksikan sejarah dengan mata kepala sendiri...",
  ui_story_1019_10190902_30_dialog_content = "Beritahu Belisaria untuk memanggil saksi-saksi saya.",
  ui_story_1019_10190902_31_dialog_content = "Saksi? Siapa yang Anda maksud?",
  ui_story_1019_10190902_32_dialog_content = "Yingel, Axelia, Sean. Cukup panggil mereka.",
  ui_story_1019_10190902_33_dialog_content = "Siap, Jenderal.",
  ui_story_1019_10190902_34_dialog_content = "...",
  ui_story_1019_10190902_35_dialog_content = "Aku telah menyampaikan kekhawatiranmu kepada Grand Marshal, PlayerName, tapi kita harus menyerahkan Ulysses kepada komite tinjauan sekarang.",
  ui_story_1019_10190902_36_dialog_content = "Sebelum mereka mencapai kesimpulan, kita memiliki hal yang lebih penting untuk dilakukan. Jangan lupa kita memiliki koordinat yang harus kita telusuri.",
  ui_story_1019_10190902_37_dialog_content = "Tapi saya masih terpaku pada pertanyaan yang dia ajukan kepada saya...",
  ui_story_1019_10190902_38_dialog_content = "Bagaimana menurutmu penampakan akhir dunia nanti?",
  ui_story_1019_10190902_39_dialog_content = "Jika Krisis Darkover terjadi lagi, bagaimana Aurorian bisa melawannya?",
  ui_story_1019_10190902_40_dialog_content = "*Hela nafas dalam-dalam* Wuuss—",
  ui_story_1019_10190902_41_dialog_content = "Mungkin karena kurang tidur belakangan ini, tapi aku merasa agak bingung seolah-olah aku kehilangan sesuatu yang penting.",
  ui_story_1019_10190902_42_dialog_content = "Jika kamu benar-benar merasa kehilangan sesuatu, saya yakin kamu akan tetap berjuang dan mencarinya, tidak peduli seberapa jauh dan gelap.",
  ui_story_1019_10190902_43_dialog_content = "Tapi Illumina berbeda. Itu adalah rumah kita, harapan kita.",
  ui_story_1019_10190902_44_dialog_content = "Jika kita bisa melihat langit di atas kota bawah tanah dari sini...",
  ui_story_1019_10190902_45_dialog_content = "Matahari seharusnya sudah terbit di permukaan.",
  ui_story_1019_10190902_46_dialog_content = "Namun bagi orang-orang Illumina, meninggalkan Undercities untuk berdiri di bawah matahari adalah hal terjauh yang bisa mereka lakukan.",
  ui_story_1019_10190902_47_dialog_content = "Gannon belum melihat matahari selama bertahun-tahun, tetapi tetap aman dari kegelapan.",
  ui_story_1019_10190902_48_dialog_content = "Kecuali kita semakin dalam masuk ke bawah tanah seiring berjalannya waktu.",
  ui_story_1019_10190902_49_dialog_content = "Aku benar-benar penasaran bagaimana Gannon saat pertama kali dibangun.",
  ui_story_1019_10190902_50_dialog_content = "Satu hal yang pasti: Eclipsite ada di mana-mana.",
  ui_story_1019_10190902_51_dialog_content = "Ancaman dari Eclipsites mendorong kami untuk bertahan hidup di sini dan menjadikan tujuan kami untuk membunuh mereka.",
  ui_story_1019_10190902_52_dialog_content = "Saya benar-benar tidak bisa menebak apa yang akan terjadi pada Illumina setelah pengadilan.",
  ui_story_1019_10190902_53_dialog_content = "...",
  ui_story_1019_10190902_54_dialog_content = "Aku tahu banyak hal yang sedang berkecamuk di pikiranmu, Nak, tapi tetap bertahan!",
  ui_story_1019_10190902_55_dialog_content = "Aku merasa lebih bersemangat setelah berbicara dengan kalian semua.",
  ui_story_1019_10190902_56_dialog_content = "Itu mungkin hasil dari jam biologis Algol yang disebutkan. Sekarang adalah awal dari hari baru.",
  ui_story_1019_10190902_57_dialog_content = "Oh, begitu…",
  ui_story_1019_10190902_58_dialog_content = "Nah, selamat pagi, Vivian, dan Barton.",
  ui_story_1019_10190902_59_dialog_content = "Selamat pagi, PlayerName.",
  ui_story_1019_10190902_60_dialog_content = "Selamat pagi, Illumina! Ayo selesaikan pekerjaanmu dan mari berharap ini akan segera berakhir.",
  ui_story_1019_10191001_1_dialog_content = "<color=#e8d9bb>Di ruang konferensi tingkat tinggi Balai Konferensi Illumina, semua orang tampak diam.</color>",
  ui_story_1019_10191001_2_dialog_content = "Kalian menjadi diam saatnya menjatuhkan hukuman padaku.",
  ui_story_1019_10191001_3_dialog_content = "Ehem...",
  ui_story_1019_10191001_4_dialog_content = "Hmm…",
  ui_story_1019_10191001_5_dialog_content = "Ini sudah ulasan kelima, jadi mengapa kita tidak mengubahnya dan mengobrol santai. Bukankah kamu memanggil saksi?",
  ui_story_1019_10191001_6_dialog_content = "...",
  ui_story_1019_10191001_7_dialog_content = "Obrolan santai? Berapa lama lagi kau akan menyeret ini? Bukankah pertempuran di Twilight dan garis pertahanan Illumina telah membuktikan tekad dan kekuatan militer kita?",
  ui_story_1019_10191001_8_dialog_content = "Helios, seorang saksi untuk latihan militer, masih dalam pemulihan dari koma, dan prajurit dalam Program Phospherus juga masih dalam pemeriksaan.",
  ui_story_1019_10191001_9_dialog_content = "Itu hanya alasan. Saya menuntut bukti yang lebih konkret!",
  ui_story_1019_10191001_10_dialog_content = "Saya setuju. Baik itu latihan atau Program Fosfor, sebagai seseorang yang telah melalui keduanya, kesaksian saya sendiri harus cukup!",
  ui_story_1019_10191001_11_dialog_content = "Saya lihat Anda pulih dengan baik dari prosedur tersebut, Grand Marshal Wrath.",
  ui_story_1019_10191001_12_dialog_content = "Saya mengerti pendapat Anda, tetapi kita tidak bisa begitu saja mengabaikan pandangan dan kontribusi Dr. Ulysses.",
  ui_story_1019_10191001_13_dialog_content = "Apakah kamu masih belum puas dengan seberapa lama proses review berlangsung?",
  ui_story_1019_10191001_14_dialog_content = "Kami bisa memberinya satu kesempatan lagi, tetapi itu akan menjadi yang terakhir.",
  ui_story_1019_10191001_15_dialog_content = "Reinhardt?",
  ui_story_1019_10191001_16_dialog_content = "Tapi dengan satu syarat: pasukan saya tidak akan menyerah lebih jauh. Saya akan memiliki saksi saya hadir sebelum putusan akhir.",
  ui_story_1019_10191001_17_dialog_content = "Maka kamu akan dipaksa untuk menjatuhkan hukuman Ulysses.",
  ui_story_1019_10191001_18_dialog_content = "Tentu. Sekarang, manfaatkan momen ini, Ulysses, karena saya ingin mendengar sesuatu yang berbeda dalam pernyataan penutup Anda.",
  ui_story_1019_10191001_19_dialog_content = "Heh. Aku... *batuk-batuk*",
  ui_story_1019_10191001_20_dialog_content = "Obat dan air Anda, dokter...",
  ui_story_1019_10191001_21_dialog_content = "...",
  ui_story_1019_10191001_22_dialog_content = "Aku tak apa, hanya sedikit tidak fit karena lelah.",
  ui_story_1019_10191001_23_dialog_content = "Aku sudah bilang aku tidak menyembunyikan apa-apa darimu.",
  ui_story_1019_10191001_24_dialog_content = "Ya, tapi hanya untuk pertanyaan yang diajukan dan tidak lebih.",
  ui_story_1019_10191001_25_dialog_content = "Kali ini, kami berharap Anda akan mengungkapkan hasil penelitian Anda dan apakah tim Anda akan melanjutkan pekerjaan Anda setelah Anda meninggalkan lab dengan jujur.",
  ui_story_1019_10191001_26_dialog_content = "Bagaimanapun, pekerjaanmu adalah warisan sejarah, dan saatnya untuk meneruskannya kepada generasi baru.",
  ui_story_1019_10191001_27_dialog_content = "Heh, apakah kamu sedang menyiratkan bahwa aku terlalu tua?",
  ui_story_1019_10191001_28_dialog_content = "Saya, Ulysses, lahir pada tahun 1945 dalam Kalender Pagi, telah hidup lebih dari setengah abad...",
  ui_story_1019_10191001_29_dialog_content = "Seperti teman-teman sebaya saya, seharusnya saya sudah lama meninggal menurut rata-rata usia hidup Aurorian Illumina.",
  ui_story_1019_10191001_30_dialog_content = "Apakah kamu benar-benar ingin mempercayakan masalah berat Engineer sejak pendirian Illumina kepada prajurit yang hanya tahu senjata dan peluru?",
  ui_story_1019_10191001_31_dialog_content = "...",
  ui_story_1019_10191001_32_dialog_content = "Masalah insinyur? Apa maksudnya?",
  ui_story_1019_10191001_33_dialog_content = "Apakah kamu tahu apa yang dia bicarakan, Reinhardt?",
  ui_story_1019_10191001_34_dialog_content = "...",
  ui_story_1019_10191001_35_dialog_content = "Jangan menyimpang dari subjek, Ulysses. Apa tujuan Anda mengimplementasikan Program Phospherus?",
  ui_story_1019_10191001_36_dialog_content = "Seperti yang Anda ketahui sekarang, untuk meningkatkan daya hidup Aurorian, Illumina telah melakukan eksperimen transformasi Aurorian selama bertahun-tahun.",
  ui_story_1019_10191001_37_dialog_content = "Kecuali untuk Helios dan Denier, semua subjek yang menonjol, dari eksperimen peningkatan awal hingga Program Phospherus, ada di sini.",
  ui_story_1019_10191001_38_dialog_content = "...",
  ui_story_1019_10191001_39_dialog_content = "...",
  ui_story_1019_10191001_40_dialog_content = "Eksperimen peningkatan dan... subjek yang luar biasa?",
  ui_story_1019_10191001_41_dialog_content = "Banyak prajurit dari Federasi Illumina telah memilih untuk meningkatkan kemampuan tempur mereka untuk melindungi kehidupan masyarakat.",
  ui_story_1019_10191001_42_dialog_content = "Dan bahkan ada lebih banyak Aurorian dengan cacat fisik yang memperpanjang hidup mereka melalui teknologi.",
  ui_story_1019_10191001_43_dialog_content = "Apakah saya salah satunya, dokter, karena Anda sedang menatap saya?",
  ui_story_1019_10191001_44_dialog_content = "Apakah aku salah satu dari mereka yang umurnya diperpanjang oleh teknologimu?",
  ui_story_1019_10191001_45_dialog_content = "...",
  ui_story_1019_10191001_46_dialog_content = "Ini lelucon, kan? Saya hanya datang ke sini untuk pemeriksaan rutin... tapi transformasi yang memperpanjang umur?",
  ui_story_1019_10191001_47_dialog_content = "Kamu bukan Aurorian biasa, Sean. Kamu adalah subjek luar biasa dari Program Phospherus.",
  ui_story_1019_10191001_48_dialog_content = "...",
  ui_story_1019_10191001_49_dialog_content = "Kamu merasa sulit untuk mempercayainya, bukan? Namun, kamu hanya tidak menyadari betapa beruntungnya kamu.",
  ui_story_1019_10191001_50_dialog_content = "Bagi seseorang yang hidup di era perang seperti saya, siapa pun yang mampu bertarung bisa merenggut hak hidup dari mereka yang tidak mampu.",
  ui_story_1019_10191001_51_dialog_content = "Jadi, pilihan apa yang akan kamu buat, jika kamu berada di posisi saya?",
  ui_story_1019_10191001_52_dialog_content = "Apa ide baru yang sedang kau renungkan hari ini, Uly?",
  ui_story_1019_10191001_53_dialog_content = "Sama tua, sama tua.",
  ui_story_1019_10191001_54_dialog_content = "Ah, rekayasa genetika. Bagaimana menurutmu mereka bisa mencetuskan istilah itu?",
  ui_story_1019_10191001_55_dialog_content = "Apakah ada gunanya untuk bertanya-tanya?",
  ui_story_1019_10191001_56_dialog_content = "Yang penting adalah saya sedang mempelajarinya sekarang.",
  ui_story_1019_10191001_57_dialog_content = "\"Istilah itu dari mana\" tidak pernah terlintas dalam pikiranku, karena seringkali konyol untuk menentukan sumbernya.",
  ui_story_1019_10191001_58_dialog_content = "Gannon ditemukan oleh pasukan terdepan dari Lumopolis.",
  ui_story_1019_10191001_59_dialog_content = "Para prajurit yang tak kenal takut itu, hampir punah saat berjuang melawan Eclipsites, hanya menemukan diri mereka ditinggalkan oleh Lumopolis...",
  ui_story_1019_10191001_60_dialog_content = "Kekuatan itu akhirnya berkembang menjadi kekuatan militer di sudut Undercity.",
  ui_story_1019_10191001_61_dialog_content = "Tapi entah kenapa, aku tak bisa melupakan perkataan Robby.",
  ui_story_1019_10191001_62_dialog_content = "Apa ide baru yang sedang kau renungkan hari ini, Uly?",
  ui_story_1019_10191001_63_dialog_content = "...",
  ui_story_1019_10191001_64_dialog_content = "Apa yang membuatmu begitu tertarik?",
  ui_story_1019_10191001_65_dialog_content = "Catatan Tahunan Illumina Federation... Kenapa kamu membaca ini? Tidak mengejek sejarah lagi?",
  ui_story_1019_10191001_66_dialog_content = "Tahu tidak berapa tahun Illumina Federation sudah ada, Robby?",
  ui_story_1019_10191001_67_dialog_content = "<color=#FFB400>649.</color>",
  ui_story_1019_10191001_68_dialog_content = "Anda tahu sampai detailnya?",
  ui_story_1019_10191001_69_dialog_content = "Tentu saja. Jika ayah saya tidak menentangnya, mungkin saya akan menjadi sejarawan di bawah dorongan ibu saya.",
  ui_story_1019_10191001_70_dialog_content = "Kamu tidak sedang menguji saya tentang waktu pendirian Illumina, bukan?",
  ui_story_1019_10191001_71_dialog_content = "Saat menelusuri sejarah rekayasa genetika, saya menemukan masalah dalam Annals of Illumina Federation.",
  ui_story_1019_10191001_72_dialog_content = "Tidak ada penjelasan tentang bagaimana rekayasa genetika dimulai di Illumina seolah-olah ada ambang batas tinggi yang harus dilewati sejak awal.",
  ui_story_1019_10191001_73_dialog_content = "Apakah Anda menyarankan bahwa itu sebenarnya adalah teknologi Lumopolis, yang ada sebelum Illumina?",
  ui_story_1019_10191001_74_dialog_content = "Atau sejarah Illumina melebihi 649 tahun?",
  ui_story_1019_10191001_75_dialog_content = "Mungkin saja. Aku akan terus meneliti itu.",
  ui_story_1019_10191001_76_dialog_content = "Oleh karena itu, aku menjadi terobsesi, dan bertekad untuk menemukan jawabannya.",
  ui_story_1019_10191001_77_dialog_content = "Aku tidak yakin apakah di luar arsip itu damai atau kacau.",
  ui_story_1019_10191001_78_dialog_content = "Saya hanya tahu perang tidak bisa mencapai ruangan kecil seperti itu dan mengganggu upaya saya untuk mencari kebenaran.",
  ui_story_1019_10191001_79_dialog_content = "Sehari, lalu sebulan berlalu...",
  ui_story_1019_10191001_80_dialog_content = "Ada suara di kepala saya yang mengatakan untuk tidak takut gagal karena sejarah pada akhirnya akan memberikan jawabannya.",
  ui_story_1019_10191001_81_dialog_content = "Satu tahun, lalu dua tahun telah berlalu...",
  ui_story_1019_10191001_82_dialog_content = "Hingga suatu hari...",
  ui_story_1019_10191001_83_dialog_content = "Robby, coba lihat ini! Apa yang tertulis di kanan bawah?",
  ui_story_1019_10191001_84_dialog_content = "Insinyur?",
  ui_story_1019_10191001_85_dialog_content = "Siapa atau apa itu?",
  ui_story_1019_10191001_86_dialog_content = "Saya telah menemukan banyak kekosongan dan penolakan sengaja mengenai sumber rekayasa genetika dalam penelitian saya.",
  ui_story_1019_10191001_87_dialog_content = "Tapi, aku menemukan jawaban di suatu tempat dalam buku itu.",
  ui_story_1019_10191001_88_dialog_content = "\"Masalah kelebihan beban Lumina telah diselesaikan di bawah bimbingan...\"",
  ui_story_1019_10191001_89_dialog_content = "Dibawah bimbingan siapa?",
  ui_story_1019_10191001_90_dialog_content = "Tepat! Ada seseorang yang memandu mereka, kan?",
  ui_story_1019_10191001_91_dialog_content = "Insinyur? Kamu pikir Insinyur itu dihilangkan dalam buku?",
  ui_story_1019_10191001_92_dialog_content = "Itulah yang dikatakan oleh intuisiku.",
  ui_story_1019_10191001_93_dialog_content = "Menarik bagaimana itu dihapus dalam teks utama tetapi tetap ada di margin...",
  ui_story_1019_10191001_94_dialog_content = "Tapi bisa kah kamu yakin, Uly? Ada lagi yang sama di tempat lain?",
  ui_story_1019_10191001_95_dialog_content = "Tidak, tetapi jika Anda memasukkan Insinyur ke dalam semua deskripsi samar itu...",
  ui_story_1019_10191001_96_dialog_content = "Itu akan menjelaskan banyak hal.",
  ui_story_1019_10191001_97_dialog_content = "\"Aurorian dengan cepat membentuk unit teknologi untuk memulai studi tentang teknologi kuno di bawah kepemimpinan Engineer.\"",
  ui_story_1019_10191001_98_dialog_content = "\"Insinyur memimpin unit teknologi untuk memeriksa struktur Kota Gannon dan mengajari mereka menggunakan teknologi tertentu.\"",
  ui_story_1019_10191001_99_dialog_content = "Aku belum pernah melihatmu lebih bahagia, Uly.",
  ui_story_1019_10191001_100_dialog_content = "Aku akan terus menggali!",
  ui_story_1019_10191001_101_dialog_content = "Untuk suara tembakan artileri yang terus menerus di luar gedung arsip...",
  ui_story_1019_10191001_102_dialog_content = "Berikan aku lebih banyak waktu. Aku tahu mereka akan berubah menjadi teriakan kemenangan Aurorian atas Eclipsite!",
  ui_story_1019_10191101_1_dialog_content = "Bagaimana perkembangan dengan peta Zona Gelap?",
  ui_story_1019_10191101_2_dialog_content = "Hei, kalau bukan Dr. Algol! Tidak setiap hari Anda keluar dari laboratorium Anda!",
  ui_story_1019_10191101_3_dialog_content = "Halo, Dr. Joyce.",
  ui_story_1019_10191101_4_dialog_content = "Halo. Hei, bukankah kamu seorang Caelestite?",
  ui_story_1019_10191101_5_dialog_content = "Halo.",
  ui_story_1019_10191101_6_dialog_content = "Algol memberitahuku bahwa Colossus-mu sangat membantu dalam pemetaan Zona Gelapku. Terima kasih banyak!",
  ui_story_1019_10191101_7_dialog_content = "Senang bisa membantu. Saya berjanji akan membantu Illumina dan itu juga membantu saya dalam prosesnya.",
  ui_story_1019_10191101_8_dialog_content = "Berhenti ngobrol, Joyce. Saya ingin pendapat Anda tentang koordinat Zona Gelap, dan seberapa layaknya untuk dijelajahi.",
  ui_story_1019_10191101_9_dialog_content = "Data baru tentang Dark Zone? Kamu hampir menyusul <color=#FFB400>simulasi geografis</color>.",
  ui_story_1019_10191101_10_dialog_content = "Seperti yang kamu tahu, model saat ini saya diturunkan dari medan yang sudah kita petakan.",
  ui_story_1019_10191101_11_dialog_content = "Ini juga berarti jika koordinatnya terlalu jauh dari Gannon dengan ketidakberurutan di antaranya, perhitungan menjadi, yah, rumit.",
  ui_story_1019_10191101_12_dialog_content = "Saya hanya bisa menghitung kontiguitas dan diskontinuitas secara terpisah berdasarkan probabilitas dan mensimulasikan lingkungan sesuai itu.",
  ui_story_1019_10191101_13_dialog_content = "Jadi apa hasilnya? Sudahkah kamu menemukan satu?",
  ui_story_1019_10191101_14_dialog_content = "Ck, begitu tidak sabaran...",
  ui_story_1019_10191101_15_dialog_content = "Katakan saja padaku.",
  ui_story_1019_10191101_16_dialog_content = "Oke, oke. Saya masih menyempurnakan model dari petunjuk yang diberikan oleh Helios.",
  ui_story_1019_10191101_17_dialog_content = "Di luar daerah yang dapat ditinggali di Astra adalah lapisan rawa beku yang tidak rata dan ditutupi salju tipis.",
  ui_story_1019_10191101_18_dialog_content = "Di seberang rawa, kamu memiliki hutan pilar es dengan berbagai bentuk dan ukuran...",
  ui_story_1019_10191101_19_dialog_content = "Beberapa berbentuk lancip seperti paku, beberapa menyerupai kerucut terbalik, dan beberapa tampak seperti spiral yang membelit...",
  ui_story_1019_10191101_20_dialog_content = "Langsung ke intinya!",
  ui_story_1019_10191101_21_dialog_content = "Bu! Bu! Bu!",
  ui_story_1019_10191101_22_dialog_content = "Menurutmu menarik?",
  ui_story_1019_10191101_23_dialog_content = "Bu! Bu! Bu!",
  ui_story_1019_10191101_24_dialog_content = "...",
  ui_story_1019_10191101_25_dialog_content = "<color=#e8d9bb>Setelah mengobrol dengan Joyce selama lima belas menit...</color>",
  ui_story_1019_10191101_26_dialog_content = "... Jadi di antara pilar-pilar ini, sebagian udara akan menjadi cair karena suhu dan membentuk monolit yang aneh.",
  ui_story_1019_10191101_27_dialog_content = "Saya tidak begitu jelas tentang prinsip yang tepat, meskipun mungkin ini berhubungan dengan teknologi levitasi dari Lumopolis.",
  ui_story_1019_10191101_28_dialog_content = "Dan ketika aliran udara mengeras, beberapa naik ke atas sementara yang lain turun...",
  ui_story_1019_10191101_29_dialog_content = "Tunggu, apa yang baru saja kamu katakan?",
  ui_story_1019_10191101_30_dialog_content = "... Itulah kesimpulan saya mengapa mereka terlihat sangat berbeda satu sama lain.",
  ui_story_1019_10191101_31_dialog_content = "Apa sebenarnya yang kamu tanyakan?",
  ui_story_1019_10191101_32_dialog_content = "Pilar-pilar batu yang menjulang ke atas...",
  ui_story_1019_10191101_33_dialog_content = "Aku melihat mereka di dalam pikiran Ulysses.",
  ui_story_1019_10191101_34_dialog_content = "Aku yakin itu yang aku lihat... Mungkinkah itu kebetulan?",
  ui_story_1019_10191101_35_dialog_content = "...",
  ui_story_1019_10191101_36_dialog_content = "Ulangi apa yang baru saja kamu katakan lagi, Joyce.",
  ui_story_1019_10191101_37_dialog_content = "Saya berkata, \"Ketika aliran udara mengeras, beberapa naik ke atas sementara yang lain turun. Itulah mengapa mereka tampak begitu berbeda satu sama lain.\"",
  ui_story_1019_10191101_38_dialog_content = "Berbicara tentang naik dan turun, kita pernah melakukan eksperimen...",
  ui_story_1019_10191101_39_dialog_content = "Ini tidak mungkin salah...",
  ui_story_1019_10191101_40_dialog_content = "Sekarang jika aku mengingat kembali, beberapa pilar batu es yang terbang itu memiliki lingkaran cahaya yang bersinar...",
  ui_story_1019_10191101_41_dialog_content = "Maksudmu kamu melihat inti dari Guardian One? Itu ada di pilar-pilar terbang itu?!",
  ui_story_1019_10191101_42_dialog_content = "... Begitukah?",
  ui_story_1019_10191101_43_dialog_content = "Ya! Itu dia!",
  ui_story_1019_10191101_44_dialog_content = "Ini menarik! Luar biasa!",
  ui_story_1019_10191101_45_dialog_content = "Apa yang kamu lihat di pikiran Ulysses cocok persis dengan gambar yang diduga sebagai inti Guardian One, yang dikirim kembali oleh tim ekspedisi Dark Zone.",
  ui_story_1019_10191101_46_dialog_content = "Dan jika pilar terbang itu berada dalam jangkauan koordinat Soroz...",
  ui_story_1019_10191101_47_dialog_content = "Aku mengerti... Sinyal berkedip itu bukan berarti koordinat yang banyak, tapi karena pilar-pilarnya yang bergerak!",
  ui_story_1019_10191101_48_dialog_content = "Biarkan aku memahami ini. Jadi, bukan hanya Ulysses yang tahu di mana inti itu, tetapi mungkin juga dari situlah asal Colossus?",
  ui_story_1019_10191101_49_dialog_content = "Dia bahkan memberi petunjuk bahwa dia tahu apa yang Vice temui!",
  ui_story_1019_10191101_50_dialog_content = "...",
  ui_story_1019_10191101_51_dialog_content = "Saya mengerti. Saya tidak hanya sangat membantu Anda, tetapi juga telah memecahkan misteri besar juga.",
  ui_story_1019_10191101_52_dialog_content = "Tch... Tapi jika dia terhubung dengan Eclipse, itu bukan berita baik dalam cara apapun kamu memandangnya.",
  ui_story_1019_10191101_53_dialog_content = "Ulysses tidak pernah meninggalkan Undercity, namun dia sangat terlibat dalam skema Eclipse...",
  ui_story_1019_10191101_54_dialog_content = "Saya berpikir, apakah Wraiths menyelinap ke Gannon dan membawa lari inti Guardian One semua berkat Ulysses?",
  ui_story_1019_10191101_55_dialog_content = "Aku punya teori yang lebih berani...",
  ui_story_1019_10191101_56_dialog_content = "Tidak mungkin bagi Guardian One untuk melewati sistem keamanan saya kecuali seseorang menggunakan benda itu untuk mengelakkannya...",
  ui_story_1019_10191101_57_dialog_content = "Prototipe itu \"disimpan untuk alasan keamanan\".",
  ui_story_1019_10191101_58_dialog_content = "...",
  ui_story_1019_10191101_59_dialog_content = "Jika Ulysses adalah orang yang mengoperasikan prototipe secara rahasia, kita harus pergi ke Majelis Illumina dan menuntut penjelasan.",
  ui_story_1019_10191101_60_dialog_content = "Tidak, mari kita langsung saja ke kantornya.",
  ui_story_1019_10191101_61_dialog_content = "Jika kita benar, tempat itu akan menjadi yang paling berbahaya di Illumina!",
  ui_story_1019_10191101_62_dialog_content = "...",
  ui_story_1019_10191201_1_dialog_content = "May Aku bertanya apa yang sedang kamu lakukan? Menghapus teks, menutupi sejarah...",
  ui_story_1019_10191201_2_dialog_content = "Apa yang kamu sembunyikan tentang Insinyur itu? Atau apakah itu adalah rahasia Lumopolis yang tak terucapkan?",
  ui_story_1019_10191201_3_dialog_content = "Yang bisa saya konfirmasi adalah semua informasi tentang Engineer hanya tersedia dalam file Illumina dan Komite tidak memiliki pengetahuan di luar itu.",
  ui_story_1019_10191201_4_dialog_content = "Apakah kamu menganggap aku bodoh?!",
  ui_story_1019_10191201_5_dialog_content = "Komite tidak menghapus informasi tersebut.",
  ui_story_1019_10191201_6_dialog_content = "Setidaknya bukan Committee yang sedang menjabat.",
  ui_story_1019_10191201_7_dialog_content = "Jika Krisis Darkover tidak terjadi, yang memaksa orang-orang tingkat atas untuk mencabut pembatasan penelitian Guardian, saya tidak akan pernah menemukan apa pun tentang Engineer.",
  ui_story_1019_10191201_8_dialog_content = "Guardian?",
  ui_story_1019_10191201_9_dialog_content = "Sebuah mesin kuno misterius yang ditemukan di Gannon oleh tim penjelajah dari Lumopolis.",
  ui_story_1019_10191201_10_dialog_content = "Penduduk yang datang kemudian menamakannya Guardian.",
  ui_story_1019_10191201_11_dialog_content = "Apakah Guardian masih dalam penelitian?",
  ui_story_1019_10191201_12_dialog_content = "Algol hanya memiliki salinan <color=#FFB400>terpasir</color>. Prototipe disegel karena alasan keamanan.",
  ui_story_1019_10191201_13_dialog_content = "Itu hanya rencana awal...",
  ui_story_1019_10191201_14_dialog_content = "Ulysses?!",
  ui_story_1019_10191201_15_dialog_content = "Saya selalu curiga ada hubungan antara penutupan prototipe dan kurangnya transparansi pada Engineer.",
  ui_story_1019_10191201_16_dialog_content = "Sampai aku menemukan catatan-catatan banyak dari Insinyur di prototipe tersebut.",
  ui_story_1019_10191201_17_dialog_content = "<color=#e8d9bb>Klink, denting!</color>",
  ui_story_1019_10191201_18_dialog_content = "Di situ kamu, Uly! Aku telah mencari kamu sepanjang hari. Kami khawatir kamu pergi untuk bertempur.",
  ui_story_1019_10191201_19_dialog_content = "Mereka bilang kamu takkan bisa bangkit lagi, tapi aku tahu tak ada yang bisa membuatmu terjatuh.",
  ui_story_1019_10191201_20_dialog_content = "Benar, 'kan?",
  ui_story_1019_10191201_21_dialog_content = "...",
  ui_story_1019_10191201_22_dialog_content = "... Kamu sangat diam. Ada apa, Uly?",
  ui_story_1019_10191201_23_dialog_content = "Kamu masih ingat berkas-berkas Engineer yang telah aku selidiki?",
  ui_story_1019_10191201_24_dialog_content = "Ya. Tapi, aku pikir dengan seburuk apa pun perang ini berlangsung, ditambah kamu... baru saja kehilangan keluargamu, kamu pasti sudah lama menyerah.",
  ui_story_1019_10191201_25_dialog_content = "Kamu tidak akan percaya ini, Robby, tapi AI kuno yang baru-baru ini diungkap oleh Komite adalah kunci dari misteri Engineer.",
  ui_story_1019_10191201_26_dialog_content = "AI kuno? Guardian, benar? Bukankah Algol sedang mengerjakan kasus itu?",
  ui_story_1019_10191201_27_dialog_content = "Itu hanya salinan yang divirtualisasi. Yang sedang Anda lihat sekarang ini adalah aslinya—prototipe.",
  ui_story_1019_10191201_28_dialog_content = "Uly! Kamu memindahkan prototipe yang disegel...? Kau sadar kau bisa masuk penjara karena ini?",
  ui_story_1019_10191201_29_dialog_content = "Akan berbeda jika saya bisa menggali catatan penelitian Insinyur...",
  ui_story_1019_10191201_30_dialog_content = "...",
  ui_story_1019_10191201_31_dialog_content = "Insinyur itu tidak hanya menangani rekayasa genetik...",
  ui_story_1019_10191201_32_dialog_content = "Hipotesisnya tentang eksperimen Aurorian dan teknologi sihir, serta pemikirannya tentang sifat tubuh dan pikiran...",
  ui_story_1019_10191201_33_dialog_content = "Mereka menyerang otakku seperti arus listrik yang kuat! Belum pernah aku merasa begitu bersemangat!",
  ui_story_1019_10191201_34_dialog_content = "Uly...",
  ui_story_1019_10191201_35_dialog_content = "Biarkan aku menyelesaikan.",
  ui_story_1019_10191201_36_dialog_content = "Dia menyebutkan upaya pengeditan gen Aurorian yang ditargetkan dalam salah satu catatannya...",
  ui_story_1019_10191201_37_dialog_content = "Hasilnya adalah ciri fisik yang beberapa ratus kali lebih unggul dari Aurorian modern! Apakah kamu menyadari apa artinya itu?",
  ui_story_1019_10191201_38_dialog_content = "Era di mana Insinyur berada memiliki tingkat teknologi yang lebih tinggi dari sekarang?",
  ui_story_1019_10191201_39_dialog_content = "Ada yang lain?",
  ui_story_1019_10191201_40_dialog_content = "Oh, dan Engineer \"memiliki\" Guardian!",
  ui_story_1019_10191201_41_dialog_content = "Tidak, Robby, bukan itu intinya.",
  ui_story_1019_10191201_42_dialog_content = "Intinya adalah: jika teknologi ini bisa ditiru, kita tidak perlu berlindung dari Eclipsite di kota bawah tanah yang suram ini.",
  ui_story_1019_10191201_43_dialog_content = "...",
  ui_story_1019_10191201_44_dialog_content = "Kalau semua yang kamu katakan itu benar, Uly, itu akan menjadi...",
  ui_story_1019_10191201_45_dialog_content = "Menakjubkan, bukan? Ini pasti akan menjadi terobosan dan masa depan Illumina! Ini juga berarti terwujudnya mimpiku—mengalahkan Eclipsite dan kembali ke permukaan!",
  ui_story_1019_10191201_46_dialog_content = "Dan juga impianmu untuk berkeliling di seluruh Eoria!",
  ui_story_1019_10191201_47_dialog_content = "Berpergian ke seluruh Eoria...",
  ui_story_1019_10191201_48_dialog_content = "Ada keberanian dan kekuatan yang tak tertandingi dalam hatimu, Uly.",
  ui_story_1019_10191201_49_dialog_content = "Dan di sana aku, khawatir tentangmu... Senang melihatmu kembali bersemangat.",
  ui_story_1019_10191201_50_dialog_content = "Pokoknya, selama kamu baik-baik saja...",
  ui_story_1019_10191201_51_dialog_content = "Aku tidak merasakan apa-apa ketika Robby pertama kali mengatakan itu.",
  ui_story_1019_10191201_52_dialog_content = "Baru setelah dia kehilangan senyum itu dan kemudian diterjang oleh rasa sakit perang, saya mengerti pesan sebenarnya.",
  ui_story_1019_10191201_53_dialog_content = "Saya harus segera dan menciptakan kembali karya Engineer sebelum Eclipsite membasmi Aurorian.",
  ui_story_1019_10191201_54_dialog_content = "Bahkan jika itu berarti aku harus mengisolasi semua orang, termasuk diriku sendiri.",
  ui_story_1019_10191201_55_dialog_content = "Karena aku hanya merasa hidup ketika menemukan cara untuk meningkatkan kemampuan bertarung Aurorian dalam catatan Insinyur...",
  ui_story_1019_10191201_56_dialog_content = "*Uhuk-uhuk* Dan kegembiraan juga!",
  ui_story_1019_10191201_57_dialog_content = "Apakah Anda merasa baik-baik saja, Pak? Apakah Anda membutuhkan...",
  ui_story_1019_10191201_58_dialog_content = "Aku baik-baik saja...! *Batuk-batuk*",
  ui_story_1019_10191201_59_dialog_content = "Butuh hampir 10 tahun bagi saya untuk mencari petunjuk yang ditinggalkan oleh Engineer dan menyatukan kembali karyanya.",
  ui_story_1019_10191201_60_dialog_content = "10 tahun! Apa yang bisa mereka capai sekarang setelah mereka mengambil alih lab saya?",
  ui_story_1019_10191201_61_dialog_content = "<color=#e8d9bb>Tik-tik-tik...</color>",
  ui_story_1019_10191201_62_dialog_content = "Dokumen-dokumen ini sangat rapi. OCD pria tua itu menghemat waktu dan tenaga kita. Hei, apa ini...?",
  ui_story_1019_10191201_63_dialog_content = "...",
  ui_story_1019_10191201_64_dialog_content = "Hei, bukankah kita sepakat hanya satu putaran terakhir? Sudah setengah jam. Apakah kamu mencoba curang?",
  ui_story_1019_10191201_65_dialog_content = "Nah, kamu bisa melakukannya sendiri jika itu tidak memerlukan banyak usaha, Migard!",
  ui_story_1019_10191201_66_dialog_content = "Sudah lama aku tidak bermain game se-mudah ini. Satu-satunya kekurangan adalah permainannya berjalan sangat lambat!",
  ui_story_1019_10191201_67_dialog_content = "Apakah ada yang kurang dalam peningkatan umum pada komputer Illumina? Atau apakah mesin ini adalah harta pribadi dari Pria Tua itu?",
  ui_story_1019_10191201_68_dialog_content = "Apa yang hilang?",
  ui_story_1019_10191201_69_dialog_content = "Uh, aku bersumpah aku tidak bermain game saat bertugas! Itu, uh...",
  ui_story_1019_10191201_70_dialog_content = "Coba biarkan saya melihat komputer.",
  ui_story_1019_10191201_71_dialog_content = "Apakah ini mesinnya, Dr. Algol?",
  ui_story_1019_10191201_72_dialog_content = "Tidak. Mungkin ada petunjuk yang kita lewatkan...",
  ui_story_1019_10191201_73_dialog_content = "Tunggu, jangan bergerak...",
  ui_story_1019_10191201_74_dialog_content = "Apa yang kamu lakukan, berdiri begitu dekat?",
  ui_story_1019_10191201_75_dialog_content = "Bagaimana caranya aku bisa mengetahui apa yang salah tanpa mendekatinya?",
  ui_story_1019_10191201_76_dialog_content = "Apakah kalian menemui sesuatu yang buruk di jalan? Aku merasakan firasat buruk...",
  ui_story_1019_10191201_77_dialog_content = "Apakah Anda berbicara tentang saya atau Bool?",
  ui_story_1019_10191201_78_dialog_content = "Bu! Bu! Bu!",
  ui_story_1019_10191201_79_dialog_content = "Bahaya? Tidak, bahaya besar? Itulah kasusnya ketika kita pertama kali bertemu Ulysses...",
  ui_story_1019_10191201_80_dialog_content = "Ada yang terasa salah sejak kamu datang. Sekarang saya merasa seperti kita sedang diawasi di lab ini...",
  ui_story_1019_10191201_81_dialog_content = "Bisakah kamu merasakannya, Anak Muda?",
  ui_story_1019_10191201_82_dialog_content = "Sedikit…",
  ui_story_1019_10191201_83_dialog_content = "Bu! Bu! Bu!",
  ui_story_1019_10191201_84_dialog_content = "Aduh! Berapa kali harus kubilang jangan menarik leherku seperti itu, Bool!",
  ui_story_1019_10191201_85_dialog_content = "Di luar pintu? Apa yang ada di sana...?",
  ui_story_1019_10191201_86_dialog_content = "Oh tidak, aku merasakan aliran Darkflow yang sangat kuat...",
  ui_story_1019_10191201_87_dialog_content = "Eclipsite yang lolos dari radar... Ia berhasil menghindari Diving Spines.",
  ui_story_1019_10191201_88_dialog_content = "Hati-hati, semuanya!",
  ui_story_1019_10191201_89_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_1019_10191202_1_dialog_content = "Hraaagh—",
  ui_story_1019_10191202_2_dialog_content = "Apakah dia akhirnya mati?",
  ui_story_1019_10191202_3_dialog_content = "Besar sekali... Ini pasti jadi bos di setiap game!",
  ui_story_1019_10191202_4_dialog_content = "Tapi tidak ada tanda apapun. Bagaimana kita tahu dari mana asalnya?",
  ui_story_1019_10191202_5_dialog_content = "Ini tidak memiliki nomor seri seperti subjek Eclipsite.",
  ui_story_1019_10191202_6_dialog_content = "Lagi pula, kita bahkan tidak tahu apakah ini benar-benar subjek Eclipsite atau apa...",
  ui_story_1019_10191202_7_dialog_content = "Apakah ini salah satu subjek Ulysses? Apakah dia berniat menggunakan monster-monster ini melawan Komite seperti yang dia lakukan pada Wrath dan pengawalnya?",
  ui_story_1019_10191202_8_dialog_content = "Bagaimanapun, menciptakan senjata melawan rakyatmu sendiri membuatmu sama dengan Eclipse.",
  ui_story_1019_10191202_9_dialog_content = "Apakah Komite sudah mencapai keputusan?",
  ui_story_1019_10191202_10_dialog_content = "Masih belum bisa berkomunikasi dengan Grand Marshal. Tinjauan mungkin belum selesai.",
  ui_story_1019_10191202_11_dialog_content = "Kita tidak bisa menunggu Komite. Kita harus bergerak sekarang untuk melacak prototipe dan celah. Itu lebih mendesak daripada persidangan Ulysses.",
  ui_story_1019_10191202_12_dialog_content = "Benar. Mari kita diskusikan temuan kita dalam 10 menit.",
  ui_story_1019_10191202_13_dialog_content = "Saya harus memeriksa gedung lab terlebih dahulu dan mengisolasi para peneliti. Mereka mungkin memiliki informasi yang berguna.",
  ui_story_1019_10191202_14_dialog_content = "Tolong beri tahu semua petugas patroli di sekitar ancaman, Dr. Algol, dan minta bala bantuan.",
  ui_story_1019_10191202_15_dialog_content = "Kita masih belum tahu berapa banyak Eclipsite di sekitar dan harus tetap dalam kewaspadaan tinggi.",
  ui_story_1019_10191202_16_dialog_content = "Tidak masalah. Saya harus terus mencari prototipe itu sendiri.",
  ui_story_1019_10191301_1_dialog_content = "Di mana aku berhenti, Esien?",
  ui_story_1019_10191301_2_dialog_content = "Bagaimana kamu hanya merasa hidup dan bahagia saat membaca catatan Insinyur...",
  ui_story_1019_10191301_3_dialog_content = "Benar, bergembira...",
  ui_story_1019_10191301_4_dialog_content = "Kebahagiaan karena saya melihat visi megah dari Insinyur. Dia menggunakan rekayasa genetika Aurorian yang ditargetkan untuk menciptakan satu batch prajurit super demi yang lain!",
  ui_story_1019_10191301_5_dialog_content = "Apakah prajurit super produksi massal akhirnya menjadi Proyek: Matahari Buatan dan Program Phospherus?",
  ui_story_1019_10191301_6_dialog_content = "Yang benar-benar mengejutkan saya bukanlah menduplikasi eksperimen tetapi not terakhirnya.",
  ui_story_1019_10191301_7_dialog_content = "Jumlah prajurit super tiba-tiba mencapai puncaknya pada suatu titik <color=#FFB400>600 tahun</color> yang lalu.",
  ui_story_1019_10191301_8_dialog_content = "Tapi itu terjadi ketika Guardian ditutup untuk alasan yang tidak diketahui.",
  ui_story_1019_10191301_9_dialog_content = "Dan Insinyur itu dihapus selamanya dari sejarah Illumina.",
  ui_story_1019_10191301_10_dialog_content = "Mengapa demikian?",
  ui_story_1019_10191301_11_dialog_content = "...",
  ui_story_1019_10191301_12_dialog_content = "Bagaimana menurutmu, Yingel?",
  ui_story_1019_10191301_13_dialog_content = "Um... Karena eksperimen Engineer gagal?",
  ui_story_1019_10191301_14_dialog_content = "Tidak, itu sukses tanpa syarat.",
  ui_story_1019_10191301_15_dialog_content = "Ini karena Illumina akhirnya menyadari...",
  ui_story_1019_10191301_16_dialog_content = "Prajurit super yang diproduksi massal oleh Engineer sebenarnya adalah Eclipsite yang akan membunuh Aurorian dalam pertempuran.",
  ui_story_1019_10191301_17_dialog_content = "Kurasa mungkin aku salah, Robby...",
  ui_story_1019_10191301_18_dialog_content = "Eclipsite yang diambil dari medan perang memiliki susunan genetik yang lebih rumit, tetapi beberapa sampel individu masih bisa diisolasi.",
  ui_story_1019_10191301_19_dialog_content = "Gen dari Aurorian dan beberapa individu Eclipsite lebih dari 90% kompatibel.",
  ui_story_1019_10191301_20_dialog_content = "90%?",
  ui_story_1019_10191301_21_dialog_content = "Sebagian besar Eclipsite yang tersusun secara anorganik tidak lebih dari cangkang yang ditembakkan musuh ke medan perang.",
  ui_story_1019_10191301_22_dialog_content = "Namun, banyak musuh lainnya memiliki susunan genetik yang sangat mirip dengan Aurorian. Mungkin mereka adalah yang menembakkan peluru.",
  ui_story_1019_10191301_23_dialog_content = "Kita tidak akan pernah bisa mengalahkan mereka kecuali kita membuat senjata yang serupa. Kita bahkan tidak akan bisa mengidentifikasi musuh yang melemparkan granat ini kepada kita.",
  ui_story_1019_10191301_24_dialog_content = "Apakah kamu sedang memikirkan untuk membuat Eclipsites, Uly?",
  ui_story_1019_10191301_25_dialog_content = "Tidak, senjata kita akan lebih kuat dari itu.",
  ui_story_1019_10191301_26_dialog_content = "Senjata kami adalah cangkang Eclipsite dan Aurorian dengan Luminatics yang kuat.",
  ui_story_1019_10191301_27_dialog_content = "Integrasi genetik Eclipsite dan Aurorian...?",
  ui_story_1019_10191301_28_dialog_content = "Kamu gila, Uly...",
  ui_story_1019_10191301_29_dialog_content = "Tidak, akhirnya aku sudah mendapat titik terang.",
  ui_story_1019_10191301_30_dialog_content = "Ini adalah satu-satunya cara kami Aurorian memiliki peluang untuk mengalahkan Eclipsites.",
  ui_story_1019_10191301_31_dialog_content = "Hanya ada satu hasil jika kita bertarung melawan mereka dengan bentuk asli kita...",
  ui_story_1019_10191301_32_dialog_content = "Jadi untuk itu, apakah kita harus berubah menjadi Eclipsite?",
  ui_story_1019_10191301_33_dialog_content = "Bukan berubah menjadi! Melampaui mereka! Itulah kejeniusan Engineer. Dia membuat Aurorian menjadi jauh lebih kuat.",
  ui_story_1019_10191301_34_dialog_content = "Apakah kamu sadar apa yang sedang kamu katakan, Uly? Kamu menolak tujuan perlawanan kita dan berbalik melawan prinsip kita!",
  ui_story_1019_10191301_35_dialog_content = "Sejak kamu menemukan karya dari Insinyur tersebut, kamu sudah terlalu jauh dalam penelitianmu.",
  ui_story_1019_10191301_36_dialog_content = "Pernahkah terlintas di pikiranmu bahwa, inilah yang diinginkan Engineer, untuk menyesatkan kita menciptakan Eclipsite, bahkan menjadi mereka sendiri?",
  ui_story_1019_10191301_37_dialog_content = "Aku tidak akan mengubah kita menjadi Eclipsite, tetapi Aurorian yang lebih kuat!",
  ui_story_1019_10191301_38_dialog_content = "Saya sudah menemukan caranya. Proyek ini akan segera memasuki fase baru.",
  ui_story_1019_10191301_39_dialog_content = "Kamu selalu percaya padaku, 'kan? Aku bisa mewujudkan impian kita. Aku bisa mengubah takdir semua Aurorian!",
  ui_story_1019_10191301_40_dialog_content = "Bukan seperti ini, Uly... Bukan seperti ini...",
  ui_story_1019_10191301_41_dialog_content = "Kami bahkan belum mengetahui satu hal tertentu...",
  ui_story_1019_10191301_42_dialog_content = "Jika Anda mengklaim bahwa Insinyur membuatnya menjadi mungkin, siapa dia? Mengapa dia menghilang dari sejarah Illumina?",
  ui_story_1019_10191301_43_dialog_content = "Mengapa dia mengkhianati Illumina, dan mengapa dia menjadi musuh bagi semua Aurorian?",
  ui_story_1019_10191301_44_dialog_content = "...",
  ui_story_1019_10191301_45_dialog_content = "Siapa sebenarnya Insinyur itu?",
  ui_story_1019_10191301_46_dialog_content = "Eclipsite? Aurorian? Setan? Atau mungkin...",
  ui_story_1019_10191301_47_dialog_content = "Tidak dari yang disebutkan di atas? *Uhuk-uhuk*",
  ui_story_1019_10191301_48_dialog_content = "Berapa banyak lagi batuk yang akan kamu lakukan? Apakah kamu tidak akan mengatakan apa-apa sampai kamu mati jika kami tidak mencoba memaksamu untuk berbicara?",
  ui_story_1019_10191301_49_dialog_content = "Heheh... Meski aku ingin menjelaskan tentang proses panjang selama 40 tahun, beban yang aku tanggung begitu besar, sampai-sampai aku tidak tahu harus mulai dari mana...",
  ui_story_1019_10191301_50_dialog_content = "Berkat kamu, aku jadi ingat Robby dan betapa semangatnya aku dulu.",
  ui_story_1019_10191301_51_dialog_content = "Tapi identitas Insinyur tidak lagi menarik bagi saya.",
  ui_story_1019_10191301_52_dialog_content = "...",
  ui_story_1019_10191301_53_dialog_content = "Mungkin Anda tidak lagi peduli tentang siapa Insinyur itu, Ulysses.",
  ui_story_1019_10191301_54_dialog_content = "Tapi saya peduli tentang kemana Illumina akan pergi.",
  ui_story_1019_10191301_55_dialog_content = "Aku sudah memberimu cukup waktu untuk menjelaskan visimu.",
  ui_story_1019_10191301_56_dialog_content = "Beritahu saya, bagaimana saya harus memutuskan jika Program Phospherus memberikan manfaat untuk Illumina?",
  ui_story_1019_10191301_57_dialog_content = "Berdiri di hadapanmu adalah seseorang yang telah membawa dekade perdamaian ke Illumina, serta orang dengan potensi tertinggi untuk sepuluh tahun ke depan.",
  ui_story_1019_10191301_58_dialog_content = "Hanya ada satu cara bagi Aurorian untuk mengatasi Eclipsite, dan itu adalah jalan yang akan saya tempuh, bahkan di atas tulang-tulang Aurorian.",
  ui_story_1019_10191301_59_dialog_content = "Kamu ingin tahu manfaatnya? Itu jawabanku.",
  ui_story_1019_10191401_1_dialog_content = "Officer... Aku mendengar sesuatu...",
  ui_story_1019_10191401_2_dialog_content = "Semua peneliti telah diberitahu untuk evakuasi dari pusat ini. Apa yang kamu lakukan di sini?",
  ui_story_1019_10191401_3_dialog_content = "Tunggu sebentar, saya kenal Anda... Anda adalah asisten Ulysses.",
  ui_story_1019_10191401_4_dialog_content = "Dari penampungan mana subjek tersebut kabur?",
  ui_story_1019_10191401_5_dialog_content = "Subjek tes... Subjek tes dokter semuanya diberi label dan disimpan dalam batch.",
  ui_story_1019_10191401_6_dialog_content = "Ini... Maaf, tapi saya belum pernah melihatnya sebelumnya. Namun demikian, file yang relevan seharusnya ada di komputer dokter.",
  ui_story_1019_10191401_7_dialog_content = "Saya telah memeriksa komputer Ulysses. Hanya data eksperimen dan laporan.",
  ui_story_1019_10191401_8_dialog_content = "Jadi, dari mana mereka berasal?",
  ui_story_1019_10191401_9_dialog_content = "Biar kulihat...",
  ui_story_1019_10191401_10_dialog_content = "Akses ditolak? Mungkin dia membuat rencana darurat.",
  ui_story_1019_10191401_11_dialog_content = "Bagaimana menurutmu, Bool?",
  ui_story_1019_10191401_12_dialog_content = "Huuu!",
  ui_story_1019_10191401_13_dialog_content = "Ya, itu luar biasa!",
  ui_story_1019_10191401_14_dialog_content = "Masukkan kata sandi Anda, asisten.",
  ui_story_1019_10191401_15_dialog_content = "Baiklah…",
  ui_story_1019_10191401_16_dialog_content = "<color=#e8d9bb>Klik, klik—</color>",
  ui_story_1019_10191401_17_dialog_content = "<color=#e8d9bb>Nguuung!</color>",
  ui_story_1019_10191401_18_dialog_content = "Ya, aku menemukannya!",
  ui_story_1019_10191401_19_dialog_content = "Berkas tentang prajurit super... Berapa banyak iterasi yang telah mereka lalui?",
  ui_story_1019_10191401_20_dialog_content = "Aku belum pernah melihat ini sebelumnya di laboratorium...",
  ui_story_1019_10191401_21_dialog_content = "Tentu saja tidak. Itu adalah eksperimen rahasia Ulysses sendiri!",
  ui_story_1019_10191401_22_dialog_content = "Prajurit super ini pasti yang telah menyerang kita. Di mana mereka disimpan?",
  ui_story_1019_10191401_23_dialog_content = "Simpan, simpan...",
  ui_story_1019_10191401_24_dialog_content = "Huuu!",
  ui_story_1019_10191401_25_dialog_content = "Ketemu!",
  ui_story_1019_10191401_26_dialog_content = "<color=#FFB400>Warehouse Zero</color>? Bukankah itu...",
  ui_story_1019_10191401_27_dialog_content = "Apakah ada Gudang Zero di Gannon?",
  ui_story_1019_10191401_28_dialog_content = "Belum pernah dengar.",
  ui_story_1019_10191401_29_dialog_content = "Jika ini adalah Warehouse Zero yang saya pikirkan...",
  ui_story_1019_10191401_30_dialog_content = "Ikuti aku!",
  ui_story_1019_10191401_31_dialog_content = "...",
  ui_story_1019_10191401_32_dialog_content = "Mereka semua terlalu cepat untukku...",
  ui_story_1019_10191401_33_dialog_content = "Ini melampaui transformasi Aurorian... Ini adalah produksi massal Eclipsite!",
  ui_story_1019_10191401_34_dialog_content = "Orang-orang yang menerobos sistem pertahanan sudah cukup berbahaya. Kita akan mati jika kita tidak menemukan sumbernya dengan cepat.",
  ui_story_1019_10191401_35_dialog_content = "<color=#e8d9bb>Kegentingan!</color>",
  ui_story_1019_10191401_36_dialog_content = "... Ini adalah Gudang Nol?",
  ui_story_1019_10191401_37_dialog_content = "Sangat besar!",
  ui_story_1019_10191401_38_dialog_content = "Semua gerbang terbuka... Cukup besar untuk memarkir beberapa Engine VII.",
  ui_story_1019_10191401_39_dialog_content = "Bau larutan begitu menyengat... Apakah ini tempat eksperimen dilakukan? Hati-hati, semua orang.",
  ui_story_1019_10191401_40_dialog_content = "<color=#e8d9bb>*Statis*</color>",
  ui_story_1019_10191401_41_dialog_content = "Bu! Bu! Bu!",
  ui_story_1019_10191401_42_dialog_content = "Itu nyata...",
  ui_story_1019_10191401_43_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_1019_10191401_44_dialog_content = "Suara itu datang dari alat di depan! Itu adalah seorang super-soldier!",
  ui_story_1019_10191401_45_dialog_content = "Sepertinya ini eksperimen yang setengah jadi, sangat mirip dengan monster yang pernah menyerang kita sebelumnya.",
  ui_story_1019_10191401_46_dialog_content = "Bagus kita telah menemukan sumbernya! Berhati-hatilah saat memeriksa sesuatu, semuanya.",
  ui_story_1019_10191401_47_dialog_content = "<color=#e8d9bb>*Statis*</color>",
  ui_story_1019_10191401_48_dialog_content = "Wah, hee!",
  ui_story_1019_10191401_49_dialog_content = "Bu! Bu! Bu!",
  ui_story_1019_10191401_50_dialog_content = "Lebih baik Anda tidak menyentuh ini, Dr. Algol. Kita tidak ingin mengaktifkan jebakan apa pun!",
  ui_story_1019_10191401_51_dialog_content = "Panel kontrol suhu, tombol batalkan, inputter...",
  ui_story_1019_10191401_52_dialog_content = "Ini tidak mungkin salah...",
  ui_story_1019_10191401_53_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_1019_10191401_54_dialog_content = "Pasti prajurit super itu berjuang keras untuk lepas dari alat itu!",
  ui_story_1019_10191401_55_dialog_content = "Bu! Bu! Bu!",
  ui_story_1019_10191401_56_dialog_content = "Bagian luar dari tampilan dan mainframe telah diganti, tetapi sistem operasi, antarmuka, dan panel perintah...",
  ui_story_1019_10191401_57_dialog_content = "Apakah \"kekhawatiran keamanan\" hanya tipuan?",
  ui_story_1019_10191401_58_dialog_content = "Dan di sini...",
  ui_story_1019_10191401_59_dialog_content = "Ini masih berjalan...",
  ui_story_1019_10191401_60_dialog_content = "Apa sebenarnya yang telah dia lakukan di sini selama ini?",
  ui_story_1019_10191401_61_dialog_content = "Booooo!!!",
  ui_story_1019_10191401_62_dialog_content = "Bool sangat cepat sekali!",
  ui_story_1019_10191401_63_dialog_content = "<color=#e8d9bb>Klang... Klink...!!!</color>",
  ui_story_1019_10191401_64_dialog_content = "Roaar—",
  ui_story_1019_10191401_65_dialog_content = "Gawat, super-prajuritnya lepas!",
  ui_story_1019_10191401_66_dialog_content = "Di sini tidak aman, Dr. Algol, tolong pergi!",
  ui_story_1019_10191401_67_dialog_content = "...",
  ui_story_1019_10191401_68_dialog_content = "Dr. Algol!!!",
  ui_story_1019_10191401_69_dialog_content = "...",
  ui_story_1019_10191401_70_dialog_content = "<color=#e8d9bb>Retakan-!!!</color>",
  ui_story_1019_10191401_71_dialog_content = "Skill Mecha!",
  ui_story_1019_10191401_72_dialog_content = "Ini bukan dinding, tapi gerbang di ruang yang begitu luas!",
  ui_story_1019_10191401_73_dialog_content = "Keluar dari sini. Kami memiliki monster besar di belakang kita!",
  ui_story_1019_10191401_74_dialog_content = "Kembali ke pintu masuk... Aku tidak mengerti. Itu kosong saat kita masuk!",
  ui_story_1019_10191401_75_dialog_content = "... Menyeramkan saat itu berdiri tegak.",
  ui_story_1019_10191401_76_dialog_content = "Tapi begitu Dr. Algol datang, dia terlalu tertarik untuk menggerakkan langkahnya.",
  ui_story_1019_10191401_77_dialog_content = "Dr. Algol!",
  ui_story_1019_10191401_78_dialog_content = "Bu! Bu! Bu!",
  ui_story_1019_10191401_79_dialog_content = "Melawan Eclipsites adalah keahlian Anda.",
  ui_story_1019_10191401_80_dialog_content = "Itu Eclipsite di belakangmu! Kamu tidak bisa mengabaikan keselamatanmu sendiri, tidak peduli apa pun!",
  ui_story_1019_10191401_81_dialog_content = "Kamu akan mengerti pilihanku jika kamu telah melalui rasa sakit itu.",
  ui_story_1019_10191401_82_dialog_content = "Semua bulu-bulu itu yang kucabut satu per satu...",
  ui_story_1019_10191401_83_dialog_content = "Semua jari yang kugigit sampai berdarah...",
  ui_story_1019_10191401_84_dialog_content = "Dan semua kode yang menyiksa namun juga membuatku bersemangat pada saat yang sama...",
  ui_story_1019_10191401_85_dialog_content = "Tidak ada kesempatan bagi saya untuk meninggalkan prototipe ini lagi!",
  ui_story_1019_10191401_86_dialog_content = "...",
  ui_story_1019_10191401_87_dialog_content = "Lindungi Dr. Algol dan bersiaplah untuk bertarung!",
  ui_story_1019_10191502_1_dialog_content = "Apakah semua orang baik-baik saja?",
  ui_story_1019_10191502_2_dialog_content = "Hanya goresan. Bukan masalah besar.",
  ui_story_1019_10191502_3_dialog_content = "Kamu berdarah... Jangan bilang kamu akan berubah menjadi monster karena infeksi seperti dalam game itu?",
  ui_story_1019_10191502_4_dialog_content = "... Apa yang kamu katakan? Luka goresan seperti ini biasa terjadi di Laboratorium Payung Hitam.",
  ui_story_1019_10191502_5_dialog_content = "Tapi Diving Spines bereaksi lebih dari biasanya. Komposisi dan output energinya menunjukkan perubahan yang signifikan.",
  ui_story_1019_10191502_6_dialog_content = "Setuju! Tapi monster-monster ini tetap tidak ada tandingannya untuk Throne-ku!",
  ui_story_1019_10191502_7_dialog_content = "Apa rencana Ulysses untuk membuat prajurit super ini secara diam-diam? Dan prototipenya masih berjalan...",
  ui_story_1019_10191502_8_dialog_content = "Mengingat betapa keras kepala dia dengan Program Fosfer, tidak sulit untuk menyimpulkan bahwa dia ingin menggantikan Aurorian dengan super-prajurit dan meningkatkan peluang bertahan hidup Aurorian.",
  ui_story_1019_10191502_9_dialog_content = "Yang saya khawatirkan adalah: apakah ini semua prajurit super? Ada lebih dari seratus Aurorian yang telah berubah di Legion Pengawal Wrath saja...",
  ui_story_1019_10191502_10_dialog_content = "Mari lihat apakah Dr. Algol menemukan sesuatu yang baru. Mungkin dia telah menemukan sumber dan jumlah total prajurit super.",
  ui_story_1019_10191502_11_dialog_content = "<color=#e8d9bb>Klik, klik—</color>",
  ui_story_1019_10191502_12_dialog_content = "Bool bisa menekan tombol... dan itu cepat!",
  ui_story_1019_10191502_13_dialog_content = "Benar.",
  ui_story_1019_10191502_14_dialog_content = "Sekarang saya tahu mengapa Bool menarik rambutku.",
  ui_story_1019_10191502_15_dialog_content = "Hiks!",
  ui_story_1019_10191502_16_dialog_content = "Dr. Algol, bagaimana Bool menjalankan prototipe tersebut?",
  ui_story_1019_10191502_17_dialog_content = "Apakah itu terhubung ke otakmu sementara memberi perintah kepada tentakelnya untuk menjalankan perintahmu?",
  ui_story_1019_10191502_18_dialog_content = "Tebakan bagus, tapi tidak. Bool mungkin meniru tindakan sebelumnya dengan memanfaatkan indera peraba dan memori.",
  ui_story_1019_10191502_19_dialog_content = "Ada kabar baru di sini, Dr. Algol?",
  ui_story_1019_10191502_20_dialog_content = "Super-soldier setengah jadi ini memang sama dengan yang menyerang kita.",
  ui_story_1019_10191502_21_dialog_content = "Apakah ini semua?",
  ui_story_1019_10191502_22_dialog_content = "Sudah cukup menakjubkan bagi saya untuk menemukan prototipe yang berjalan...",
  ui_story_1019_10191502_23_dialog_content = "Tapi kemungkinan saya tidak akan tahu lebih banyak detail tentang para prajurit ini sampai saya masuk ke dalam sistem.",
  ui_story_1019_10191502_24_dialog_content = "Saya berharap kita bisa memeriksa gudang secara menyeluruh sementara Bool menjalankan algoritma, untuk melihat apakah ada subjek atau gudang lain yang ada.",
  ui_story_1019_10191502_25_dialog_content = "Semuanya, mulai dari pencurian inti Guardian One hingga pelanggaran di pertahanan Gannon, ada hubungannya dengan Ulysses.",
  ui_story_1019_10191502_26_dialog_content = "Yang perlu saya lakukan sekarang adalah menemukan risiko lain yang mungkin ditimbulkan oleh prototipe yang masih berjalan ini, dan apa yang digunakan Ulysses untuk itu.",
  ui_story_1019_10191502_27_dialog_content = "Saya benar-benar ingin memberikan wawancara satu lawan satu kepada Ulysses sekarang juga...",
  ui_story_1019_10191502_28_dialog_content = "Dimatikan karena kekhawatiran keamanan... Sungguh lucu.",
  ui_story_1019_10191502_29_dialog_content = "Kenapa itu lucu?",
  ui_story_1019_10191502_30_dialog_content = "Sebelum penelitian apa pun tentang Guardian diizinkan, saya telah mengunjungi mesin ini sebagai salah satu siswa Ulysses.",
  ui_story_1019_10191502_31_dialog_content = "Dia tampak tidak tertarik pada AI saat itu dan hanya melakukan apa yang seharusnya dia lakukan. Kemudian, ketika aku mendengar bahwa itu ditutup karena alasan keamanan, aku pikir dia benar-benar menyerah pada ide tersebut.",
  ui_story_1019_10191502_32_dialog_content = "Jadi mengapa dia telah menggunakannya secara diam-diam?",
  ui_story_1019_10191502_33_dialog_content = "Tidak ada kemajuan nol dalam penelitian ini yang disebabkan oleh pengaturan yang buruk atau catatan sejarah yang hilang...",
  ui_story_1019_10191502_34_dialog_content = "Ini selalu karena orang-orang yang melakukan penelitian.",
  ui_story_1019_10191502_35_dialog_content = "Booooo!!!",
  ui_story_1019_10191502_36_dialog_content = "<color=#e8d9bb>Nguuung!</color>",
  ui_story_1019_10191502_37_dialog_content = "Bagus sekali...",
  ui_story_1019_10191502_38_dialog_content = "Akankah kita akhirnya melihat wujud sesungguhnya dari Guardian?",
  ui_story_1019_10191502_39_dialog_content = "Sebuah lingkaran dan empat kursor... Apa ini?",
  ui_story_1019_10191502_40_dialog_content = "Sepertinya kata sandi login diperlukan. Tapi tidak tahu apakah itu protokol milik prototipe sendiri atau langkah pengamanan Ulysses...",
  ui_story_1019_10191502_41_dialog_content = "Apa yang akan kita temukan setelah login?",
  ui_story_1019_10191502_42_dialog_content = "Kita akan tahu setelah kita masuk.",
  ui_story_1019_10191502_43_dialog_content = "Siap-siap lewati instruksinya, Bool!",
  ui_story_1019_10191502_44_dialog_content = "Hiks!",
  ui_story_1020_10200101_1_dialog_content = "<size=45>Booooo!</size>",
  ui_story_1020_10200101_2_dialog_content = "Bisakah Bool benar-benar menangani pemecahan kata sandi ini?",
  ui_story_1020_10200101_3_dialog_content = "Bool sangat cepat... Sungguh menakjubkan melihatnya sebegitu dekat.",
  ui_story_1020_10200101_4_dialog_content = "Ini hanya membuktikan kecurigaan saya...",
  ui_story_1020_10200101_5_dialog_content = "Bool menunjukkan respons yang sangat kuat terhadap masuk ke kantor Ulysses dan terhadap Ulysses sendiri.",
  ui_story_1020_10200101_6_dialog_content = "Mungkin Bool mencoba memberi tahu saya bahwa prototipe ini entah bagaimana terhubung dengan Ulysses.",
  ui_story_1020_10200101_7_dialog_content = "Bagaimana Bool bisa tahu?",
  ui_story_1020_10200101_8_dialog_content = "Aku juga ingin tahu. Lagipula, ini tampaknya bukan pertama kalinya Bool mengoperasikan prototipe ini.",
  ui_story_1020_10200101_9_dialog_content = "Semuanya dimulai saat aku dan Bool pertama kali bertemu.",
  ui_story_1020_10200101_10_dialog_content = "Sebelum prototipe disegel, tim peneliti dan saya menciptakan salinan terisolasi dari Sistem Guardian tepat di gudang rusak ini.",
  ui_story_1020_10200101_11_dialog_content = "Khawatir bahwa kami akan melewatkan beberapa detail, saya begadang setiap hari. Adapun, sebagian dari itu juga berasal dari keinginan saya untuk menghabiskan lebih banyak waktu dengan prototipe.",
  ui_story_1020_10200101_12_dialog_content = "Dengungan mesin membantu saya tidur di malam hari, tetapi sesekali, saya terbangun oleh bunyi bip yang aneh...",
  ui_story_1020_10200101_13_dialog_content = "Saya membawa simulator kembali ke kamar saya saat selesai, hanya untuk menemukan bahwa sesuatu seperti kabel atau tentakel telah melilit leher saya...",
  ui_story_1020_10200101_14_dialog_content = "Sejak saat itu, sebagian dari prototipe telah menempel padamu seperti parasit.",
  ui_story_1020_10200101_15_dialog_content = "Sepertinya itu memiliki beberapa kesamaan dengan Throne dan Diving Spines.",
  ui_story_1020_10200101_16_dialog_content = "Mungkin, tapi tidak ada satupun dari kalian yang bisa membayangkan betapa menakutkannya pertemuan pertama kali dengan Bool!",
  ui_story_1020_10200101_17_dialog_content = "Ini menghancurkan setiap potongan perabotan di kamarku tanpa henti atau ragu-ragu.",
  ui_story_1020_10200101_18_dialog_content = "Setiap kali saya mencoba berkomunikasi dengan Bool, situasinya menjadi sedikit konfrontatif...",
  ui_story_1020_10200101_19_dialog_content = "Tulang selangka, tulang rusuk, tulang belikatku... Hampir semua bagian tubuhku yang bisa dililitnya patah...",
  ui_story_1020_10200101_20_dialog_content = "Kamu menyebut itu \"konfrontatif\"? Sepertinya Bool mencoba membunuhmu!",
  ui_story_1020_10200101_21_dialog_content = "Inilah sebabnya mengapa saya sangat fokus pada latihan fisik.",
  ui_story_1020_10200101_22_dialog_content = "Tunggu sebentar... Apakah itu sebabnya kamu memiliki begitu banyak peralatan olahraga di labmu? Untuk memperkuat tubuhmu dari serangan Bool?",
  ui_story_1020_10200101_23_dialog_content = "Itu dan pemeriksaan fisik harian saya, ya... Bahkan, saya bahkan bisa menyebut diri saya sebagai pasien tetap di Pusat Medis Illumina!",
  ui_story_1020_10200101_24_dialog_content = "Sungguh tak bisa dipercaya sejauh mana Anda akan pergi untuk mempelajari Bool, Dr. Algol...",
  ui_story_1020_10200101_25_dialog_content = "Sangat menarik melihat seorang wanita yang berdedikasi pada ilmu pengetahuan.",
  ui_story_1020_10200101_26_dialog_content = "Aku tahu bahwa Bool tidak memiliki niat buruk terhadapku. Terkadang, memang butuh waktu untuk teman-teman saling terbiasa satu sama lain.",
  ui_story_1020_10200101_27_dialog_content = "Tapi ketika saya mulai fokus pada pekerjaan saya lagi, saya menyadari bahwa Bool jauh lebih dari sekadar makhluk parasit.",
  ui_story_1020_10200101_28_dialog_content = "Sangat tertarik dengan penelitian saya dan bahkan memberikan umpan balik yang sangat membantu.",
  ui_story_1020_10200101_29_dialog_content = "Sulit membayangkan apa yang telah Bool alami dari menjadi bagian dari prototipe hingga menjadi seperti sekarang...",
  ui_story_1020_10200101_30_dialog_content = "Lagi pula, pada saat aku terbiasa dengan kehadiran Bool, aku tiba-tiba menyadari bahwa aku telah menghabiskan hampir enam bulan terkunci di lab saya.",
  ui_story_1020_10200101_31_dialog_content = "Tapi setengah tahun itu adalah waktu paling santai dan memuaskan dalam hidupku.",
  ui_story_1020_10200101_32_dialog_content = "Itulah saat orang-orang mulai memberi label saya sebagai robot dan penyendiri tanpa teman, tapi saya tidak peduli.",
  ui_story_1020_10200101_33_dialog_content = "Aku tidak perlu menjelaskan diriku kepada Aurorian yang tidak akan pernah mengerti aku. Aku selalu merasa paling nyaman di sekitar mesin.",
  ui_story_1020_10200101_34_dialog_content = "Guardian One ternyata tidak mudah untuk dihadapi... dan itu menguras banyak energiku.",
  ui_story_1020_10200101_35_dialog_content = "Jadi pertama adalah Guardian One, dan kemudian Bool? Dr. Algol, Anda benar-benar—",
  ui_story_1020_10200101_36_dialog_content = "Aneh?",
  ui_story_1020_10200101_37_dialog_content = "Sedikit, tapi itu hanya membuatmu semakin menarik!",
  ui_story_1020_10200101_38_dialog_content = "Aku setuju. Aku selalu suka menjadi aneh, tahu kan.",
  ui_story_1020_10200101_39_dialog_content = "Itu sebenarnya musik bagi telingaku. Saya juga cocok dengan label itu.",
  ui_story_1020_10200101_40_dialog_content = "Tidak ada yang salah dengan label! Lihat saja milikku: Ace Gamer, Raid Machine, dan Next-Round Jinx...",
  ui_story_1020_10200101_41_dialog_content = "Saya ingin mendapatkan sebanyak mungkin label dalam urat itu sebanyak mungkin!",
  ui_story_1020_10200101_42_dialog_content = "Saya juga, karena mereka terdengar unik. Bagaimana denganmu, anak muda, apa julukanmu?",
  ui_story_1020_10200101_43_dialog_content = "Aku rasa aku tidak punya label apa-apa...",
  ui_story_1020_10200101_44_dialog_content = "Iya, itu Pecundang!",
  ui_story_1020_10200101_45_dialog_content = "Y-Ya, tentu...",
  ui_story_1020_10200101_46_dialog_content = "Jadi sekarang kamu dengan senang hati menerima itu meskipun sebelumnya kamu membencinya?",
  ui_story_1020_10200101_47_dialog_content = "Saat ini, aku hanya tidak bisa memikirkan hal lain...",
  ui_story_1020_10200101_48_dialog_content = "Cukup bicara. Sekarang kita harus bagaimana, Dr. Algol?",
  ui_story_1020_10200101_49_dialog_content = "Oh, tidak ada apa-apa untuk sementara ini.",
  ui_story_1020_10200101_50_dialog_content = "Dengar suara-suara itu? Kedengarannya seperti Bool sedang melalui file data yang diperbarui dari prototipe secara naluriah.",
  ui_story_1020_10200101_51_dialog_content = "Setelah ini, Bool akan menyesuaikan logika operasinya dan memecahkan sandi. Namun, ini mungkin akan memakan waktu yang sedikit lebih lama.",
  ui_story_1020_10200101_52_dialog_content = "Tapi begitu selesai, kita akan memiliki akses ke lebih dari sekadar skema Ulysses.",
  ui_story_1020_10200101_53_dialog_content = "Kita bahkan mungkin bisa menggunakan kode pertahanan Guardian untuk membangun inti baru dan memperkuat pertahanan Illumina.",
  ui_story_1020_10200101_54_dialog_content = "Itu akan luar biasa!",
  ui_story_1020_10200101_55_dialog_content = "Saya terkejut prototipe ini masih berjalan setelah bertahun-tahun. Di atas itu semua, ini hanya ditemukan berkat seorang Caelestite.",
  ui_story_1020_10200101_56_dialog_content = "Saya rasa Anda tidak bisa menyingkirkan kemungkinan apa pun dalam hal penelitian.",
  ui_story_1020_10200101_57_dialog_content = "Hahaha... Ini benar-benar mengejutkan! Hahaha!",
  ui_story_1020_10200101_58_dialog_content = "Saya punya pertanyaan... Jika Ulysses benar-benar secara diam-diam memproduksi prajurit super di tempat ini...",
  ui_story_1020_10200101_59_dialog_content = "Tidakkah dia merasa tidak nyaman mengobati begitu banyak tentara yang terluka di pusat medis?",
  ui_story_1020_10200101_60_dialog_content = "Kurasa dia tidak akan merasa seperti itu jika prototipe memberi tahu kita bahwa dia bekerja sama dengan Eclipsite.",
  ui_story_1020_10200101_61_dialog_content = "Orang-orang tidak mencari alasan untuk menjelaskan tindakan jahat mereka. Mereka hanya menikmati metode mereka.",
  ui_story_1020_10200201_1_dialog_content = "Berdiri di hadapanmu adalah seseorang yang telah membawa dekade perdamaian ke Illumina, serta orang dengan potensi tertinggi untuk sepuluh tahun ke depan.",
  ui_story_1020_10200201_2_dialog_content = "Kamu ingin tahu manfaatnya? Itu jawabanku.",
  ui_story_1020_10200201_3_dialog_content = "Membawa satu dekade perdamaian ke Illumina... Apakah kamu merujuk pada Reinhardt?",
  ui_story_1020_10200201_4_dialog_content = "Illumina telah memiliki banyak Grand Marshal, beberapa di antaranya secara alami kuat, tetapi lebih banyak yang mengandalkan kerja keras.",
  ui_story_1020_10200201_5_dialog_content = "Sebelum Reinhardt, banyak dari Grand Marshal tersebut tidak bisa mengendalikan kekuatan mereka...",
  ui_story_1020_10200201_6_dialog_content = "Mereka secara sukarela atau dipaksa mengakhiri hidup mereka.",
  ui_story_1020_10200201_7_dialog_content = "Eksperimen serupa telah berjalan selama bertahun-tahun sebelum saya lahir.",
  ui_story_1020_10200201_8_dialog_content = "Saya percaya ini adalah masa lalu yang tidak pernah ingin disebutkan oleh Illumina. Juga, ini adalah tamparan bagi para peneliti.",
  ui_story_1020_10200201_9_dialog_content = "Seandainya saya tidak mengusulkan ide untuk memodifikasi prajurit saat mereka masih balita dan proses seleksi untuk <color=#FFB400>Undercity 80</color>...",
  ui_story_1020_10200201_10_dialog_content = "Tidak akan ada Marsekal Agung yang berani seperti Reinhardt di Illumina.",
  ui_story_1020_10200201_11_dialog_content = "...",
  ui_story_1020_10200201_12_dialog_content = "Peluncuran Proyek: Artificial Sun akhirnya menempatkan teknologi Illumina pada jalur yang benar. Bahkan bisa disebut unggul.",
  ui_story_1020_10200201_13_dialog_content = "Kemungkinan kami mengorbankan beberapa orang dalam prosesnya, tetapi itu diperlukan untuk menjaga perdamaian dan kemajuan.",
  ui_story_1020_10200201_14_dialog_content = "Jadi kamu mengakui bahwa bencana di <color=#FFB400>Undercity 80</color> bukan disebabkan oleh laporan yang salah...",
  ui_story_1020_10200201_15_dialog_content = "Tentu saja tidak, tetapi saya tidak perlu menjelaskan setiap langkah dari eksperimen kepada publik.",
  ui_story_1020_10200201_16_dialog_content = "Administrasi yang stabil memerlukan kontrol yang ketat. Hal ini hanya akan membuat dampak etis dan moral menjadi lebih mematikan bagi orang-orang Illumina.",
  ui_story_1020_10200201_17_dialog_content = "Dampak etis dan moral...",
  ui_story_1020_10200201_18_dialog_content = "Informasi yang telah merenggut nyawa rekan-rekan saya hanyalah satu langkah dalam eksperimen bagi Anda...",
  ui_story_1020_10200201_19_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1020_10200201_20_dialog_content = "Masih ingat tujuan dari misi pengintaian Undercity 80 ini?",
  ui_story_1020_10200201_21_dialog_content = "Kita harus berhasil!",
  ui_story_1020_10200201_22_dialog_content = "Graaah!",
  ui_story_1020_10200201_23_dialog_content = "Pak! Ini adalah informasi yang <color=#FFB400>Peng</color> berikan kepada saya... Dia tidak menodai tim pramuka!",
  ui_story_1020_10200201_24_dialog_content = "Peng... Kerja bagus! Kamu melakukannya dengan sangat baik!",
  ui_story_1020_10200201_25_dialog_content = "Jalan keluarnya ada di depan kita, Anatoli. Ayo lari sampai ke luar!",
  ui_story_1020_10200201_26_dialog_content = "Siap, Pak!",
  ui_story_1020_10200201_27_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1020_10200201_28_dialog_content = "Pak!",
  ui_story_1020_10200201_29_dialog_content = "Berikan Anatoli informasinya! Kamu, dan kalian semua, tutupi mundur dengan saya!",
  ui_story_1020_10200201_30_dialog_content = "Siap, Pak!",
  ui_story_1020_10200201_31_dialog_content = "Pak, saya—",
  ui_story_1020_10200201_32_dialog_content = "Masih ingat apa yang pernah aku ajarkan tentang pekerjaan pengintaian?",
  ui_story_1020_10200201_33_dialog_content = "...",
  ui_story_1020_10200201_34_dialog_content = "Jika anggota lain memberikanmu informasi apa pun, kamu harus segera melarikan diri dengan itu dengan segala cara!",
  ui_story_1020_10200201_35_dialog_content = "Mengerti, Pak! Tapi kita semua akan bisa keluar!",
  ui_story_1020_10200201_36_dialog_content = "Graaah!",
  ui_story_1020_10200201_37_dialog_content = "Argh—",
  ui_story_1020_10200201_38_dialog_content = "Sudahkah kamu lupa apa yang sudah saya katakan? Jangan biarkan emosi mengganggu pekerjaanmu! Saat melakukan pekerjaan pengintaian, hanya ada informasi, Eclipsite, dan orang mati!",
  ui_story_1020_10200201_39_dialog_content = "Pergi!",
  ui_story_1020_10200201_40_dialog_content = "Graaah!",
  ui_story_1020_10200201_41_dialog_content = "Pak!",
  ui_story_1020_10200201_42_dialog_content = "... Ayo!",
  ui_story_1020_10200201_43_dialog_content = "... Kembalilah dengan informasi yang telah aku berikan kepadamu, Anatoli...",
  ui_story_1020_10200201_44_dialog_content = "... Dengan saya menutupi mundurmu, kamu harus bisa berlari... lebih cepat...",
  ui_story_1020_10200201_45_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1020_10200201_46_dialog_content = "Kamu meremehkan kehidupan dan tujuan mereka tanpa rasa penyesalan sama sekali!",
  ui_story_1020_10200201_47_dialog_content = "Reinhardt mendapatkan gelar sebagai Enlightened Illumination dari pemulihan di Undercity 80. Pengorbanan mereka menghasilkan dekade perdamaian.",
  ui_story_1020_10200201_48_dialog_content = "Bukankah itu sepadan untuk memungkinkan orang seperti kamu dan saya untuk hidup?",
  ui_story_1020_10200201_49_dialog_content = "... Aku menghargai segala yang telah dilakukan Grand Marshal untuk Illumina.",
  ui_story_1020_10200201_50_dialog_content = "Tapi, tekad untuk mencari tahu mengapa rekan-rekanku meninggal adalah yang membuatku tetap hidup.",
  ui_story_1020_10200201_51_dialog_content = "Selama bertahun-tahun mengikutimu, seharusnya aku menyadari lebih awal...",
  ui_story_1020_10200201_52_dialog_content = "Sebagai Petugas Intelijen, tujuanku adalah untuk membuat lebih banyak prajurit bertahan dalam pertempuran melalui intel yang akurat, Grand Marshal.",
  ui_story_1020_10200201_53_dialog_content = "Namun, informasi yang saya bawa kembali lah yang menyebabkan kamu diserang oleh Eclipsite dan kehilangan anggota kunci.",
  ui_story_1020_10200201_54_dialog_content = "Saya sepenuhnya menerima hukuman atas konsekuensi dari laporan saya yang salah, tetapi sebelum itu...",
  ui_story_1020_10200201_55_dialog_content = "Saya berharap kamu akan menjatuhkan hukuman mati kepada Dr. Ulysses!",
  ui_story_1020_10200201_56_dialog_content = "Anatoli...",
  ui_story_1020_10200201_57_dialog_content = "Aku bersedia menunggu! Tak peduli apa pun, aku pasti harus membalaskan pengorbanan teman-temanku!",
  ui_story_1020_10200201_58_dialog_content = "Aku bersumpah demi hidupku untuk itu!",
  ui_story_1020_10200201_59_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1020_10200201_60_dialog_content = "Reinhardt…",
  ui_story_1020_10200201_61_dialog_content = "Belisaria!",
  ui_story_1020_10200201_62_dialog_content = "Terlepas dari di mana Ulysses berpihak, aku tidak akan mengutuk siapa pun dari orang-orangku ke takdir yang kejam seperti itu!",
  ui_story_1020_10200201_63_dialog_content = "Sekarang buatlah keputusanmu! Jika kamu menolak... maka aku akan membuatkannya untukmu!",
  ui_story_1020_10200201_64_dialog_content = "Siapkan pedang.",
  ui_story_1020_10200201_65_dialog_content = "Guntur menggelegar!",
  ui_story_1020_10200201_66_dialog_content = "Berhenti—",
  ui_story_1020_10200201_67_dialog_content = "Jatuhkan senjata kalian, semua!",
  ui_story_1020_10200201_68_dialog_content = "...",
  ui_story_1020_10200201_69_dialog_content = "Saya tidak akan menyalahkan siapa pun, karena menurut saya, setiap dari kalian membuat pilihan demi kelangsungan hidup Illumina.",
  ui_story_1020_10200201_70_dialog_content = "Itulah mengapa saya mendukung eksperimen Ulysses, serta militer yang melampaui Komite dan mengirim pasukan sesuka hati.",
  ui_story_1020_10200201_71_dialog_content = "Tetapi ketika permainan catur berakhir, pion seharusnya kembali ke tempat mereka.",
  ui_story_1020_10200201_72_dialog_content = "Sebuah pion di papan catur? Apakah itu yang kamu pikirkan tentang dirimu sendiri?",
  ui_story_1020_10200201_73_dialog_content = "Sampai sekarang, Federasi Illumina telah berjuang di dua front terpisah. Sementara pasukan Eclipsite semakin mendekati Kota Gannon, kanker telah menyebar dan merugikan kami dari dalam...",
  ui_story_1020_10200201_74_dialog_content = "Bisakah kamu benar-benar hanya duduk di sana dan berpura-pura tidak ada yang terjadi?",
  ui_story_1020_10200201_75_dialog_content = "Illumina tidak akan menjadi titik dalam melawan Eclipsite dan menjelajahi yang tidak diketahui dan mematikan untuk kedua kalinya.",
  ui_story_1020_10200201_76_dialog_content = "Kita tidak akan bergerak sebelum mereka melakukannya.",
  ui_story_1020_10200201_77_dialog_content = "Apa katamu?",
  ui_story_1020_10200201_78_dialog_content = "Sampai krisis datang, Illumina tidak akan menjadi yang pertama menyerang, apalagi memotong kedua lengan—meskipun mereka penuh kista.",
  ui_story_1020_10200201_79_dialog_content = "Kamu paham?",
  ui_story_1020_10200201_80_dialog_content = "Hahaha... Topeng Besi, bukankah kau sudah cukup dengan permainan keseimbangan ini antara Aurorian?",
  ui_story_1020_10200201_81_dialog_content = "Maukah kamu agar aku memberitahu bagaimana semua ini akan berakhir untuk semua orang?",
  ui_story_1020_10200201_82_dialog_content = "Bahkan jika kami mati, itu bukan karena kami memimpin serangan untuk Lumopolis!",
  ui_story_1020_10200201_83_dialog_content = "Aduh... kau membuatku jadi tuli.",
  ui_story_1020_10200201_84_dialog_content = "Mengapa kamu tidak memberitahuku potensi apa yang dimiliki Illumina untuk sepuluh tahun ke depan?",
  ui_story_1020_10200201_X84_dialog_content = "Apakah itu calon Grand Marshal yang ingin Anda kirim ke medan perang tanpa memandang biaya?",
  ui_story_1020_10200201_85_dialog_content = "Heheh...",
  ui_story_1020_10200201_86_dialog_content = "Ada lebih dari satu potensi untuk Program Phospherus. Orang yang bisa menjadi puncak dari Illumina dalam sepuluh tahun adalah Sean.",
  ui_story_1020_10200201_87_dialog_content = "...",
  ui_story_1020_10200201_88_dialog_content = "... Aku?",
  ui_story_1020_10200301_1_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1020_10200301_2_dialog_content = "Bool sudah melakukannya sejak beberapa saat lalu...",
  ui_story_1020_10200301_3_dialog_content = "...",
  ui_story_1020_10200301_4_dialog_content = "Kurasa dia tidak mendengarku...",
  ui_story_1020_10200301_5_dialog_content = "Bip—Algol mungkin dalam mode siaga. Guardian One akan membangunkannya.",
  ui_story_1020_10200301_6_dialog_content = "Guardian One? Mengapa kamu... membawa begitu banyak barang?",
  ui_story_1020_10200301_7_dialog_content = "Ini adalah perangkat komputasi yang biasanya digunakan oleh Algol. Guardian One berpikir Algol akan membangun inti bahkan lebih cepat dengan bantuan mereka.",
  ui_story_1020_10200301_8_dialog_content = "<color=#e8d9bb>Dentang-</color>",
  ui_story_1020_10200301_9_dialog_content = "Ah! Aku kenal suara itu di mana saja! Guardian One, datanglah ke sini dan bantu aku merangkainya.",
  ui_story_1020_10200301_10_dialog_content = "(Dia benar-benar sudah bangun!)",
  ui_story_1020_10200301_11_dialog_content = "Kecepatan operasional Algol lambat hari ini.",
  ui_story_1020_10200301_12_dialog_content = "Itu karena mesin ini berasal dari ribuan tahun yang lalu...",
  ui_story_1020_10200301_13_dialog_content = "Dalam satu cara, itu seperti leluhurmu.",
  ui_story_1020_10200301_14_dialog_content = "Leluhur ini sama sekali tidak mirip denganku.",
  ui_story_1020_10200301_15_dialog_content = "Bool membutuhkan waktu lebih lama dari yang saya perkirakan untuk membobol kata sandi itu.",
  ui_story_1020_10200301_16_dialog_content = "Bisakah jadi setelah begitu banyak pembaruan, Bool tidak lagi mengenal aturan bahasa dari simbol-simbol tersebut?",
  ui_story_1020_10200301_17_dialog_content = "Sejak pertama kali berkontak dengan prototipenya, ia tidak pernah berhenti bekerja selama satu detik pun. Berapa banyak data yang diproses Bool...",
  ui_story_1020_10200301_18_dialog_content = "Algol begitu cemas sampai-sampai dia mulai mondar-mandir.",
  ui_story_1020_10200301_19_dialog_content = "Tentu saja aku mondar-mandir! Aku kan gugup!",
  ui_story_1020_10200301_20_dialog_content = "Andai saja Bool bisa berkomunikasi dengan teman Caelestite kita secara telepati seperti yang kamu lakukan! Melihat sebagian kecil dari data tersebut pasti akan sangat membantu...",
  ui_story_1020_10200301_21_dialog_content = "Jika saya menjalankan semua perangkat komputasi ini bersamaan pada saat yang sama, tidak ada yang tidak mungkin!",
  ui_story_1020_10200301_22_dialog_content = "Kita mungkin tidak bisa menggunakan ucapan untuk berkomunikasi, tapi aku pernah merasakan beberapa \"pesan\" dari Bool sebelumnya.",
  ui_story_1020_10200301_23_dialog_content = "Mungkin saya bisa menggunakan kekuatan saya pada Bool dan mencoba menemukan beberapa petunjuk.",
  ui_story_1020_10200301_24_dialog_content = "Aku menghargai tawarannya, tapi kau harus merasa beruntung bahwa Bool tidak menyerangmu sekarang.",
  ui_story_1020_10200301_25_dialog_content = "... Tapi kamu bilang Bool sangat pandai belajar, kan? Mungkin ia mempercayaiku setelah kejadian kecil tadi?",
  ui_story_1020_10200301_26_dialog_content = "PlayerName sangat pintar.",
  ui_story_1020_10200301_27_dialog_content = "Itu masuk akal... Kurasa kita tidak punya pilihan lain, jadi maju dan uji keberanianmu.",
  ui_story_1020_10200301_28_dialog_content = "Menguji keberanianku?",
  ui_story_1020_10200301_29_dialog_content = "Oh... Tolong jadi baik, Bool!",
  ui_story_1020_10200301_30_option_content = "Tautan Telepati—",
  ui_story_1020_10200301_31_dialog_content = "...",
  ui_story_1020_10200301_32_dialog_content = "Itu cepat... Apakah Bool menolakmu atau apa?",
  ui_story_1020_10200301_33_dialog_content = "Tidak... Informasi yang datang padaku terlalu banyak dan terlalu cepat!",
  ui_story_1020_10200301_34_dialog_content = "... Jadi, apakah kamu menemukan sesuatu yang berguna?",
  ui_story_1020_10200301_35_dialog_content = "Sesuatu yang berguna...",
  ui_story_1020_10200301_36_option_content = "Aku melihat beberapa baris.",
  ui_story_1020_10200301_37_dialog_content = "Banyak garis, sebenarnya... Seperti mereka jatuh dari langit.",
  ui_story_1020_10200301_38_dialog_content = "Tapi mungkin mereka bukan garis sama sekali...",
  ui_story_1020_10200301_39_dialog_content = "Itu banyak sekali kata-kata yang tidak berarti apa-apa!",
  ui_story_1020_10200301_40_dialog_content = "Argh! Mengapa aku tidak bisa menjadi orang yang terhubung dengan prototipe?",
  ui_story_1020_10200301_41_option_content = "Saya melihat banyak angka.",
  ui_story_1020_10200301_42_dialog_content = "Mereka juga bergerak begitu cepat!",
  ui_story_1020_10200301_43_dialog_content = "Angka? Seperti nol dan satu? Berapa banyak? Apakah mereka dalam urutan tertentu?",
  ui_story_1020_10200301_44_dialog_content = "Saya rasa jumlahnya lebih banyak dari itu...",
  ui_story_1020_10200301_45_dialog_content = "Tapi aku tidak yakin berapa banyak atau apakah mereka dalam urutan tertentu...",
  ui_story_1020_10200301_46_option_content = "Aku tidak bisa mengerti apa-apa.",
  ui_story_1020_10200301_47_dialog_content = "Semuanya berlalu begitu cepat sehingga berakhir sebelum saya bisa melihat lebih dekat.",
  ui_story_1020_10200301_48_dialog_content = "Biarkan saya mencoba lagi!",
  ui_story_1020_10200301_49_dialog_content = "Sekarang setelah saya tahu apa yang diharapkan, saya akan mencoba sesuatu yang sedikit berbeda.",
  ui_story_1020_10200301_50_dialog_content = "Jangan memaksakan diri. Bahkan saya belum sepenuhnya memahami bagaimana Bool bekerja.",
  ui_story_1020_10200301_51_dialog_content = "Jika kamu mulai merasa tidak nyaman, hentikan saja untuk sekarang.",
  ui_story_1020_10200301_52_dialog_content = "Aku mengerti.",
  ui_story_1020_10200301_53_dialog_content = "Sejujurnya, kemampuan psikisku telah menjadi lebih kuat sejak munculnya Obelisk of Return.",
  ui_story_1020_10200301_54_dialog_content = "Sekarang saya dapat dengan cepat melihat seluruh Astra dari puncak obelisk itu, bukan dengan mata saya sendiri tetapi dengan mata lingkungan...",
  ui_story_1020_10200301_55_dialog_content = "Terdengar cukup abstrak bagi saya. Apakah Anda benar-benar berpikir Anda bisa menggunakan itu untuk melihat data Bool?",
  ui_story_1020_10200301_56_dialog_content = "Mungkin dengan mata lingkungan...",
  ui_story_1020_10200301_57_dialog_content = "Tapi kita tidak akan tahu kecuali saya mencoba!",
  ui_story_1020_10200301_58_option_content = "Tautan Telepati—",
  ui_story_1020_10200301_59_dialog_content = "(S-Sangat cepat!)",
  ui_story_1020_10200301_60_dialog_content = "(Aku perlu... untuk mengikuti...)",
  ui_story_1020_10200301_61_dialog_content = "(Argh! Mataku sakit hanya dari melihat—)",
  ui_story_1020_10200301_62_dialog_content = "(Tunggu! Saya perlu menggunakan mata lingkungan, bukan mata saya sendiri...)",
  ui_story_1020_10200301_63_dialog_content = "(Pertama, saya akan mencoba menarget satu urutan saja, dan kemudian...)",
  ui_story_1020_10200301_64_option_content = "Jangkauan Telepati—",
  ui_story_1020_10200301_65_dialog_content = "(...)",
  ui_story_1020_10200301_66_dialog_content = "(Ini memang angka-angka...)",
  ui_story_1020_10200301_67_dialog_content = "(01105745630112... 2311111... 0010112231...)",
  ui_story_1020_10200301_68_dialog_content = "(Jika saya bisa menyampaikan angka-angka ini ke Algol, mungkin dia bisa memecahkan kata sandi ini segera...)",
  ui_story_1020_10200301_69_dialog_content = "(Tapi... Bagaimana aku bisa mengingat mereka semua?)",
  ui_story_1020_10200301_70_dialog_content = "Aku melihatnya! Deretan angka jatuh seperti hujan!",
  ui_story_1020_10200301_71_dialog_content = "Wow! Apakah ini termasuk kode curang untuk menyelesaikan level ini?",
  ui_story_1020_10200301_72_dialog_content = "Saya tidak berpikir itu akan semudah itu... Tapi mungkin kode itu tersembunyi di suatu tempat di sana.",
  ui_story_1020_10200301_73_dialog_content = "Bisakah kamu menyalin angka-angka itu saat menggunakan kekuatanmu, Caelestite?",
  ui_story_1020_10200301_74_dialog_content = "Jika Anda bisa membawa kembali cukup data, saya mungkin bisa menggunakan komputer ini untuk menemukan kata sandi.",
  ui_story_1020_10200301_75_dialog_content = "Sudah cukup sulit bagi saya untuk menguraikan angka-angka dalam rangkaian data tersebut. Saya rasa saya tidak bisa menyalinnya...",
  ui_story_1020_10200301_76_dialog_content = "Lalu…",
  ui_story_1020_10200301_77_dialog_content = "Ada apa?",
  ui_story_1020_10200301_78_dialog_content = "Aku tidak berpikir kamu bisa menghafal begitu banyak angka sekaligus...",
  ui_story_1020_10200301_79_dialog_content = "Kau percaya padaku?",
  ui_story_1020_10200301_80_dialog_content = "Tentu saja... Tapi kenapa kamu bertanya?",
  ui_story_1020_10200301_81_dialog_content = "Aku punya firasat...",
  ui_story_1020_10200301_82_dialog_content = "Sejak saat ia mengembangkan kepribadian, pabrik otomatis yang kompleks yang dikenal sebagai Colossus menjadi mampu untuk kreativitas dan adaptabilitas.",
  ui_story_1020_10200301_83_dialog_content = "Otak kita juga memiliki kedua karakteristik unik ini.",
  ui_story_1020_10200301_84_dialog_content = "Namun, meskipun kita dapat beradaptasi dengan berbagai skenario kompleks, tingkat kreativitas dan adaptabilitas ini...",
  ui_story_1020_10200301_85_dialog_content = "Mereka hanya akan mengganggu proses komputasi mesin, sehingga menghambat efisiensi keseluruhannya.",
  ui_story_1020_10200301_86_dialog_content = "Jadi jika kamu benar-benar percaya padaku, cukup matikan kreativitas dan adaptabilitas otakmu.",
  ui_story_1020_10200301_87_dialog_content = "Hah? Tapi... Bagaimana saya bisa melakukan itu?",
  ui_story_1020_10200301_88_dialog_content = "Secara sederhana, kamu perlu berhenti berpikir seperti manusia dan mulai beroperasi seperti mesin.",
  ui_story_1020_10200301_89_dialog_content = "Kurasa aku belum pernah mencoba itu sebelumnya...",
  ui_story_1020_10200301_90_dialog_content = "Ini yang saya lakukan setiap kali pekerjaan saya sangat sulit. Jangan khawatir, saya akan membantu kamu mengingat sebanyak mungkin angka-angka tersebut.",
  ui_story_1020_10200301_91_dialog_content = "Fokus saja pada proses dan jangan khawatir tentang semua informasi yang datang padamu. Ketika cukup banyak data melewati permukaan kesadaran kita, itu cenderung meninggalkan beberapa jejak.",
  ui_story_1020_10200301_92_dialog_content = "Percayalah padaku, begitu kamu dalam keadaan pikiran yang tepat, segalanya akan terasa jauh lebih lambat.",
  ui_story_1020_10200301_93_dialog_content = "Fokus pada prosesnya...",
  ui_story_1020_10200301_94_dialog_content = "Mungkin aku akan bangun setelah jatuh ke tanah...",
  ui_story_1020_10200301_95_dialog_content = "... Aku masih di udara?",
  ui_story_1020_10200301_96_dialog_content = "Ketika kamu menyerah pada jatuh yang tak terhindarkan, prosesnya menjadi sangat panjang karena alasan tertentu...",
  ui_story_1020_10200301_97_dialog_content = "Saya pikir saya mengerti apa yang Anda katakan sebelumnya.",
  ui_story_1020_10200301_98_dialog_content = "Apa yang terlintas di pikiran Anda?",
  ui_story_1020_10200301_99_dialog_content = "Tepatnya, itu bukan kecelakaan... Yah, bagaimanapun, saya rasa saya tahu apa yang harus dilakukan sekarang.",
  ui_story_1020_10200301_100_option_content = "Rasakan—Lebih Dalam—",
  ui_story_1020_10200301_101_dialog_content = "Wow, mata PlayerName bergerak cepat.",
  ui_story_1020_10200301_102_dialog_content = "Betapa hebatnya PlayerName! Aku penasaran untuk mengetahui apa yang ada di dalam kepala itu.",
  ui_story_1020_10200301_103_dialog_content = "Dengan ini aku mengklaim Caelestite ini sebagai asisten penelitian pribadiku. Setelah semua ini berakhir, aku bahkan akan membuatkan dia sebuah pakaian!",
  ui_story_1020_10200301_104_dialog_content = "Algol ingin berteman dengan Caelestite.",
  ui_story_1020_10200301_105_dialog_content = "Ini tidak akan seperti pakaian yang dia kenakan sekarang. Tidak, ini akan lebih mirip dengan cangkang luar Anda.",
  ui_story_1020_10200301_106_dialog_content = "Bip—",
  ui_story_1020_10200301_107_dialog_content = "11101100...",
  ui_story_1020_10200301_108_dialog_content = "Ada!",
  ui_story_1020_10200301_109_dialog_content = "Kode biner?",
  ui_story_1020_10200301_110_dialog_content = "010221111, 022211110101...",
  ui_story_1020_10200301_111_dialog_content = "... Atau mungkin tidak?",
  ui_story_1020_10200301_112_dialog_content = "Guardian One, rekam suaranya agar kita tidak melewatkan apa pun.",
  ui_story_1020_10200301_113_dialog_content = "Bip. Wali Satu mengerti.",
  ui_story_1020_10200301_114_dialog_content = "Gronru, Vivian, dan Migard, gunakan juga komputer-komputer itu! Konsentrasi dan dukung diri kalian dengan Lumina.",
  ui_story_1020_10200301_115_dialog_content = "Oke!",
  ui_story_1020_10200301_116_dialog_content = "0101157567565500101... 100150115332234560101...",
  ui_story_1020_10200301_117_dialog_content = "(Nomor lima... nomor enam... tujuh, delapan, sembilan...)",
  ui_story_1020_10200301_118_dialog_content = "(Berapa banyak lagi yang ada?)",
  ui_story_1020_10200301_119_dialog_content = "(Tunggu... Apakah saya melihat sesuatu? Kenapa rasanya seperti... ada sesuatu yang berkedip...)",
  ui_story_1020_10200301_120_dialog_content = "(Oh tidak... Aku mulai berpikir lagi...)",
  ui_story_1020_10200301_121_dialog_content = "(Arggh! Semuanya begitu cepat... Aku hampir tidak bisa mengikutinya!)",
  ui_story_1020_10200401_1_dialog_content = "Apa yang sebenarnya Anda katakan, Dr. Ulysses?",
  ui_story_1020_10200401_2_dialog_content = "Kamu, Yingel, dan Axelia. Kalian bertiga adalah produk dari Program Phospherus.",
  ui_story_1020_10200401_3_dialog_content = "...",
  ui_story_1020_10200401_4_dialog_content = "...",
  ui_story_1020_10200401_5_dialog_content = "Sebuah produk dari Phospherus seharusnya cerdas seperti Yingel atau mesin pemukul Eclipsite yang perkasa seperti Axelia.",
  ui_story_1020_10200401_6_dialog_content = "Bukan saya...",
  ui_story_1020_10200401_7_dialog_content = "Kamu lebih kuat dari yang kamu tahu, Sean.",
  ui_story_1020_10200401_8_dialog_content = "Kuat... Itu pertama kalinya aku dikaitkan dengan kata itu.",
  ui_story_1020_10200401_9_dialog_content = "Ambil ini, Axelia! Ha!",
  ui_story_1020_10200401_10_dialog_content = "Aduh!",
  ui_story_1020_10200401_11_dialog_content = "...",
  ui_story_1020_10200401_12_dialog_content = "Aku bahkan bisa melukai diriku sendiri meninju Axelia... Memang sangat kuat...",
  ui_story_1020_10200401_13_dialog_content = "Rekrutan baru? Lebih seperti anak kecil! Hei! Twilight bukan tempat untukmu!",
  ui_story_1020_10200401_14_dialog_content = "...",
  ui_story_1020_10200401_15_dialog_content = "Apa yang kamu lakukan di Kota Gannon sebelum datang ke sini? Mengapa kamu bahkan tidak bisa mengalahkan Eclipsite seperti ini?",
  ui_story_1020_10200401_16_dialog_content = "...",
  ui_story_1020_10200401_17_dialog_content = "Ini bukan tempat saya untuk mengatakannya, tapi mari kita semua asah diri kita dalam kondisi yang sulit, Sean.",
  ui_story_1020_10200401_18_dialog_content = "Saya akan mengerjakannya, Pak...",
  ui_story_1020_10200401_19_dialog_content = "Semakin kuat kekuatan, semakin besar tanggung jawabnya. Bukan salahku jika aku lebih kuat dari Sean, hahaha! Benar bukan?",
  ui_story_1020_10200401_20_dialog_content = "Tapi... Aku bertanggung jawab untuk area ini.",
  ui_story_1020_10200401_21_dialog_content = "Tidak apa-apa. Aku akan memberi tahu pemimpin skuad bahwa Eclipsite di area ini terlalu kuat.",
  ui_story_1020_10200401_22_dialog_content = "...",
  ui_story_1020_10200401_23_dialog_content = "Berlari lebih cepat, Sean! Hanya sedikit lebih cepat!",
  ui_story_1020_10200401_24_dialog_content = "... Ya... Siap, Pak!",
  ui_story_1020_10200401_25_dialog_content = "Profesor Ulysses mengatakan saya sekuat Yingel dan Axelia.",
  ui_story_1020_10200401_26_dialog_content = "Tapi mengapa hanya aku yang memiliki tangan...",
  ui_story_1020_10200401_27_dialog_content = "... tertutup oleh kapalan?",
  ui_story_1020_10200401_28_dialog_content = "Ini adalah bekas dari latihanku... Tidak peduli bagaimana kamu melihatnya, kamu hanya akan melihatnya pada orang yang tidak berguna seperti saya.",
  ui_story_1020_10200401_29_dialog_content = "Bukan hanya tangan, hampir di seluruh tubuhku ada bekas luka dari latihan...",
  ui_story_1020_10200401_30_dialog_content = "Apakah saya kurang berlatih?",
  ui_story_1020_10200401_31_dialog_content = "Sean...",
  ui_story_1020_10200401_32_dialog_content = "Kamu dikirim ke Twilight hanya karena kamu dianggap gagal di tahap awal.",
  ui_story_1020_10200401_33_dialog_content = "Namun, salah penilaian tidak bisa dihindari di fase awal dari setiap eksperimen.",
  ui_story_1020_10200401_34_dialog_content = "Sebuah kegagalan...",
  ui_story_1020_10200401_35_dialog_content = "Jadi aku berada di Twilight karena aku gagal... Haha...",
  ui_story_1020_10200401_36_dialog_content = "Ini bukan salahmu, Sean. Jangan dengarkan apa pun yang dikatakan Ulysses.",
  ui_story_1020_10200401_37_dialog_content = "Setiap dari kita adalah kegagalan dalam program ini.",
  ui_story_1020_10200401_38_dialog_content = "Terima kasih telah mencoba menghiburku, Grand Marshal, tapi aku tahu pada akhirnya, aku tidak seperti kalian semua...",
  ui_story_1020_10200401_39_dialog_content = "Tanyakan padanya bagaimana kegagalan Twilight akan menjadi potensi masa depan Illumina.",
  ui_story_1020_10200401_40_dialog_content = "Langsung ke intinya, Ulysses.",
  ui_story_1020_10200401_41_dialog_content = "Nah, kamu adalah hakimnya, Topeng Besi...",
  ui_story_1020_10200401_42_dialog_content = "Kami memang meninggalkan studi kami tentang Sean, tetapi perubahan terjadi pada tubuhnya ketika dia lebih dekat dengan Zona Gelap di Twilight.",
  ui_story_1020_10200401_43_dialog_content = "Setelah verifikasi berulang kali, saya menemukan bahwa Luminatics Sean tidak dibatasi oleh cacat genetik. Malah sebaliknya, dia bisa menyerap Darkflow.",
  ui_story_1020_10200401_44_dialog_content = "Dia tidak bisa mengubah energi menjadi Lumina, tetapi itu memberinya kekebalan alami yang kuat saat melawan Eclipsites.",
  ui_story_1020_10200401_45_dialog_content = "Faktanya, ini adalah sifat serupa yang dimiliki oleh mereka yang berada dalam ekspedisi yang dipimpin oleh Pepita ke Zona Gelap.",
  ui_story_1020_10200401_46_dialog_content = "Saya tidak akan menggunakan istilah teknis, tetapi mereka adalah harapan Aurorian untuk mengalahkan Eclipsites!",
  ui_story_1020_10200401_47_dialog_content = "Saya telah menyelesaikan rencana untuk peningkatan fisik. Saya percaya sekelompok ciptaan baru saya akan siap untuk Dark Zone sangat segera.",
  ui_story_1020_10200401_48_dialog_content = "Apakah ini semacam lelucon, Ulysses? Mengapa Federasi Illumina membiarkanmu melanjutkan omong kosong ini?",
  ui_story_1020_10200401_49_dialog_content = "Sean! Saya harus memberitahu Anda, Sean—",
  ui_story_1020_10200401_50_dialog_content = "Mungkin kamu mengetahui dari berkas-berkas bahwa prajurit Illumina telah menyelamatkanmu dari Eclipsite dan mengirimkanmu ke panti asuhan sebagai seorang yatim piatu.",
  ui_story_1020_10200401_51_dialog_content = "Tapi orang yang membawa kalian ke Eclipsite untuk mati tidak lain adalah orang tua kalian sendiri!",
  ui_story_1020_10200401_52_dialog_content = "Mereka tidak ingin kamu hidup dan menderita cacat fisik yang sama seperti yang mereka alami.",
  ui_story_1020_10200401_53_dialog_content = "Tapi berkat Program Phospherus, kamu tidak akan menderita lagi.",
  ui_story_1020_10200401_54_dialog_content = "Saya telah memodifikasi tubuhmu dan memberimu kesempatan hidup baru. Jika kamu ingin diakui sebagai orang yang kuat, kamu harus—",
  ui_story_1020_10200401_55_dialog_content = "Apa yang sedang Anda lakukan, Profesor Ulysses?",
  ui_story_1020_10200401_56_dialog_content = "Berjanjilah padaku bahwa kamu akan menyelami Zona Gelap dan membasmi Eclipsites.",
  ui_story_1020_10200401_57_dialog_content = "Dibandingkan menjadi prajurit biasa di Twilight, lebih baik memaksimalkan potensi genetikmu dan menjadi pahlawan Aurorian yang melawan Eclipse di wilayah mereka sendiri!",
  ui_story_1020_10200401_58_dialog_content = "Lalu... Kamu akan bisa melihat iblis yang selama ini bersembunyi di balik layar...",
  ui_story_1020_10200401_59_dialog_content = "Berhenti, Ulysses!",
  ui_story_1020_10200401_60_dialog_content = "Jauhi Sean, Profesor!",
  ui_story_1020_10200401_61_dialog_content = "Anda bersedia mengorbankan siapa saja dalam eksperimen Anda, hanya untuk mengklaim bahwa Anda yang menyelamatkan Sean.",
  ui_story_1020_10200401_62_dialog_content = "Kekejaman dan keegoisanmu membuatku merasa jijik!",
  ui_story_1020_10200401_63_dialog_content = "Tak seorang pun bisa meninggalkannya, merenggut nyawanya, atau bahkan mendikte bagaimana dia harus hidup sekarang!",
  ui_story_1020_10200401_64_dialog_content = "Tak seorang pun yang bisa meninggalkannya, merenggut nyawanya, atau bahkan mendikte bagaimana dia harus hidup!",
  ui_story_1020_10200401_65_dialog_content = "Nah, aku tidak berpikir kamu harus mengelilingiku seperti selimut, Yingel, Axelia...",
  ui_story_1020_10200401_66_dialog_content = "Profesor Ulysses mengatakan bahwa orang tuaku lah yang membawaku ke Eclipsite.",
  ui_story_1020_10200401_67_dialog_content = "Saya selalu bilang pada diri sendiri bahwa itu hanyalah mimpi...",
  ui_story_1020_10200401_68_dialog_content = "Tapi bagaimana mungkin pengalaman yang tak terlupakan itu hanya sekedar mimpi?",
  ui_story_1020_10200401_69_dialog_content = "Namun, aku memilih untuk memandangnya sebagai pengorbanan orang tuaku untuk menyelamatkanku.",
  ui_story_1020_10200401_70_dialog_content = "Itu bodoh, aku tahu, tapi itu satu-satunya cara untuk menipu diri sendiri agar tetap hidup, bukan?",
  ui_story_1020_10200401_71_dialog_content = "Apa yang terjadi saat itu tidak lagi penting, Sean.",
  ui_story_1020_10200401_72_dialog_content = "Kamu adalah pejuang Twilight yang hebat—tidak, pejuang Illumina!",
  ui_story_1020_10200401_73_dialog_content = "Seperti saya, kini kamu juga seorang prajurit Illumina yang mampu membunuh banyak Eclipsite.",
  ui_story_1020_10200401_74_dialog_content = "Mungkin ini terdengar egois, tapi saya rasa kamu tidak harus menjadi seorang pejuang atau pahlawan.",
  ui_story_1020_10200401_75_dialog_content = "Cukup jadi Sean.",
  ui_story_1020_10200401_76_dialog_content = "Hahahaha! Jadi kamu ingin mengulangi kekalahan dalam perang kuno itu?",
  ui_story_1020_10200401_77_dialog_content = "Dunia ini tidak semudah itu... Saya telah menyaksikan betapa kuatnya Eclipse. Saya tahu ini adalah satu-satunya kesempatan bagi Aurorian.",
  ui_story_1020_10200401_78_dialog_content = "Kamu mengorbankan orang-orangmu sendiri demi ilmu pengetahuan! Tindakanmu hanya akan menghancurkan Federasi Illumina dan semua Aurorian!",
  ui_story_1020_10200401_79_dialog_content = "Mesin perang tidak pantas berdebat denganku tentang pengorbanan dan kehancuran!",
  ui_story_1020_10200401_80_dialog_content = "Saya benar-benar iri pada Forsakin yang mampu menawarkan teori tentang kekuatan misterius yang tersembunyi di dalam Lumina dan Darkflow di usia muda, dan kemudian melanjutkannya.",
  ui_story_1020_10200401_81_dialog_content = "Sedangkan kamu, lebih suka mempercayai perasaanmu dan memikirkan tentang nyawa-nyawa yang tidak berarti...",
  ui_story_1020_10200401_82_dialog_content = "Emosimu lah yang menahan Aurorian...",
  ui_story_1020_10200401_83_dialog_content = "Kebodohanmu lah yang menyebabkan lebih banyak pengorbanan...",
  ui_story_1020_10200401_84_dialog_content = "Kamu memberitahu Aurorian untuk takut akan kematian, membuat mereka tenggelam dalam penantian membosankan untuk takdir mereka yang sudah ditentukan...",
  ui_story_1020_10200401_85_dialog_content = "Aku, bagaimanapun, tidak akan menjadi budak bagi emosi...",
  ui_story_1020_10200401_86_dialog_content = "Tidak akan pernah!",
  ui_story_1020_10200401_87_dialog_content = "Aku akan terbiasa dengan ini...",
  ui_story_1020_10200401_88_dialog_content = "Biasakan dirimu dengan kematian Aurorian setiap detik! Berlusan, beratus-ratus, beribu-ribu!",
  ui_story_1020_10200401_89_dialog_content = "Aku akan melangkah di atas semua tubuhmu yang membusuk untuk menciptakan Aurorian yang kuat baik dalam tubuh maupun pikiran!",
  ui_story_1020_10200401_90_dialog_content = "Kamu pasti pernah mendengar tentang evolusi, bukan? Nah, Aurorian harus berevolusi.",
  ui_story_1020_10200401_91_dialog_content = "Setiap menit, setiap detik...",
  ui_story_1020_10200401_92_dialog_content = "Itulah satu-satunya cara bagi kita untuk bertahan di hari kiamat, dengan cakrawala yang lebih luas dan tubuh yang kuat...",
  ui_story_1020_10200401_93_dialog_content = "Untuk naik...",
  ui_story_1020_10200401_94_dialog_content = "Apakah Anda baik-baik saja, Pak?",
  ui_story_1020_10200401_95_dialog_content = "Evolusi... Istilah yang luar biasa.",
  ui_story_1020_10200401_96_dialog_content = "Setiap menit, setiap detik...",
  ui_story_1020_10200401_97_dialog_content = "Petugas Ulysses!",
  ui_story_1020_10200401_98_dialog_content = "Dia gila?",
  ui_story_1020_10200401_99_dialog_content = "Jika saya tidak melihatnya sendiri... Saya tidak akan percaya...",
  ui_story_1020_10200401_100_dialog_content = "Apa yang terjadi padanya?",
  ui_story_1020_10200401_101_dialog_content = "Itulah mengapa saya bersikeras untuk memanggil Chandra, saksi saya.",
  ui_story_1020_10200401_102_dialog_content = "Selama ini aku bersama dia, Grand Marshal.",
  ui_story_1020_10200401_103_dialog_content = "Buat tindakan Ulysses diketahui oleh semua orang.",
  ui_story_1020_10200401_104_dialog_content = "Ya, Grand Marshal. Ketika Dr. Ulysses sedang dalam terapi, dia kadang-kadang menatap ke kejauhan seperti ini...",
  ui_story_1020_10200401_105_dialog_content = "Hanya untuk kemudian bertindak seolah-olah tidak ada yang terjadi di momen berikutnya.",
  ui_story_1020_10200401_106_dialog_content = "...",
  ui_story_1020_10200401_107_dialog_content = "Lanjutkan, Saksi Chandra.",
  ui_story_1020_10200401_108_dialog_content = "Profesor Ulysses memulai psikoterapi sepuluh tahun yang lalu. Ini adalah rekam medisnya.",
  ui_story_1020_10200401_109_dialog_content = "Aku tidak terlibat saat itu, tapi seperti yang bisa kamu lihat dari berkas ini, itu adalah ketika Eclipsite mulai menyusup ke berbagai faksi.",
  ui_story_1020_10200401_110_dialog_content = "Dan beberapa bulan sebelum latihan militer, Profesor Ulysses kembali meningkatkan sesi terapinya.",
  ui_story_1020_10200401_111_dialog_content = "Setelah itu, Forsakin menyelinap ke Lab X dan Wraiths mengambil inti Guardian One dari Gannon.",
  ui_story_1020_10200401_112_dialog_content = "Dr. Ulysses terlibat dalam kedua insiden kunci. Jadi kami menduga mungkin ada komunikasi khusus antara dia dan Eclipse.",
  ui_story_1020_10200401_113_dialog_content = "...",
  ui_story_1020_10200401_114_dialog_content = "Yang menarik perhatian saya adalah beberapa hal aneh yang disebutkan Ulysses selama sesi perawatannya...",
  ui_story_1020_10200401_115_dialog_content = "Pilar es bukanlah air hujan yang mengental, melainkan batu yang menjulang...",
  ui_story_1020_10200401_116_dialog_content = "Unit penggerak sudah habis dan terputus, tapi mata yang satu masih tetap mengawasi dari atas...",
  ui_story_1020_10200401_117_dialog_content = "Pilar es yang menjulang, unit penggerak... dan mata yang waspada di langit...",
  ui_story_1020_10200401_118_dialog_content = "Ini tidak terdengar seperti apa pun di Astra. Bagaimana seseorang seperti dia, yang tidak pernah meninggalkan Kota Gannon, tahu tentang ini?",
  ui_story_1020_10200401_119_dialog_content = "Ini hampir pasti bukan kebetulan! Aku yakin kamu juga punya kecurigaan, Belisaria!",
  ui_story_1020_10200401_120_dialog_content = "Bagaimana dia bisa begitu yakin?",
  ui_story_1020_10200401_121_dialog_content = "Bukti?",
  ui_story_1020_10200401_122_dialog_content = "Karena itu tertulis dalam memoar Helios, mantan prajurit yang berpetualang ke Zona Gelap dan menjadi Eclipsite!",
  ui_story_1020_10200401_123_dialog_content = "Komite telah menolak saya kesempatan untuk membuktikan kecurigaan saya karena dia belum sadar kembali.",
  ui_story_1020_10200401_124_dialog_content = "Tapi jika kesaksiannya sejalan dengan tuduhan saya terhadap Ulysses, bagaimana lagi Anda akan menjelaskannya?",
  ui_story_1020_10200401_125_dialog_content = "Saya punya ide. Bagaimana dengan kamu?",
  ui_story_1020_10200401_126_dialog_content = "Itu Hantu?",
  ui_story_1020_10200401_127_dialog_content = "Jadi itu yang dia maksud...",
  ui_story_1020_10200401_128_dialog_content = "...",
  ui_story_1020_10200401_129_dialog_content = "Tidak perlu membuang banyak waktu untukku.",
  ui_story_1020_10200401_130_dialog_content = "Ketika dia tiba, mereka yang tidak memiliki cincin akan dibiarkan merangkak di tanah dan mati dalam ketakutan dan ketidakberartiannya.",
  ui_story_1020_10200401_131_dialog_content = "Cincin apa?",
  ui_story_1020_10200401_132_dialog_content = "Pencuri sialan! Parasit! Kamu menginginkan cincinnya, bukan?",
  ui_story_1020_10200401_133_dialog_content = "Enam ratus tahun yang lalu, kota melayang itu adalah pijakan saya untuk naik tingkat, yang ditujukan untuk membawa saya ke ketinggian yang lebih besar!",
  ui_story_1020_10200401_134_dialog_content = "Kota mengambang... Lumopolis?",
  ui_story_1020_10200401_135_dialog_content = "Tapi saat dia tiba, aku akan naik ke kemuliaan sekali lagi. Aku akan kembali ke istananya dan pelukannya yang penuh cinta.",
  ui_story_1020_10200401_136_dialog_content = "Mengapa kau melihat Aurorian sebagai musuhmu?",
  ui_story_1020_10200401_137_dialog_content = "Tentu saja karena keserakahanmu yang tak terbatas! Aurorian ingin mencuri ciptaannya dan mengklaim sebagai milik mereka sendiri!",
  ui_story_1020_10200401_138_dialog_content = "Tapi sebentar lagi, dia akan mengambil semua itu kembali!",
  ui_story_1020_10200401_139_dialog_content = "Ck, ck, ck!",
  ui_story_1020_10200401_140_dialog_content = "...",
  ui_story_1020_10200401_141_dialog_content = "Akar dari semua ini adalah mesin kuno dari era sebelum pendirian Illumina...",
  ui_story_1020_10200401_142_dialog_content = "Ini nasib Illumina? Heheh...",
  ui_story_1020_10200401_143_dialog_content = "Di mana perangkat itu?",
  ui_story_1020_10200401_144_dialog_content = "Di sebuah gudang, dijaga oleh jenius yang sangat kau sukai itu.",
  ui_story_1020_10200401_145_dialog_content = "Evolusi... Istilah yang luar biasa.",
  ui_story_1020_10200401_146_dialog_content = "Setiap menit, setiap detik...",
  ui_story_1020_10200401_147_dialog_content = "...",
  ui_story_1020_10200501_1_dialog_content = "... Apakah ini semua dari mereka?",
  ui_story_1020_10200501_2_dialog_content = "Semua sudah diperiksa, tidak ada kesalahan atau kelalaian. Menurut Anda, apakah ada yang kurang, Dr. Algol?",
  ui_story_1020_10200501_3_dialog_content = "Aku mengharapkan lebih banyak angka. Urutannya juga siklikal... Mungkin ini adalah set karakter yang terbatas.",
  ui_story_1020_10200501_4_dialog_content = "Juga, bahasa komputer paling awal berasal dari Guardian System. Terlepas dari perkembangannya selama bertahun-tahun, aturan yang mengatur bahasanya harus tetap utuh.",
  ui_story_1020_10200501_5_dialog_content = "Program saya dapat menganalisis data ini dan menentukan logika di balik pengelompokannya.",
  ui_story_1020_10200501_6_dialog_content = "Segera, saya akan dapat menggunakan komputer ini untuk mengakses seluruh \"Guardian System\", bersama dengan Bool! Setiap detik sekarang!",
  ui_story_1020_10200501_7_dialog_content = "Tapi karena ini adalah set terbatas, bagaimana bisa PlayerName masih terhubung? Apakah dia baik-baik saja?",
  ui_story_1020_10200501_8_dialog_content = "Hei, rambutnya berdiri tegak... Itu terasa familiar bagi saya, tapi saya tidak bisa benar-benar mengingat apa itu.",
  ui_story_1020_10200501_9_dialog_content = "Hampir sampai... Hampir sampai...",
  ui_story_1020_10200501_10_dialog_content = "Huuu!",
  ui_story_1020_10200501_11_dialog_content = "Selesai!",
  ui_story_1020_10200501_12_dialog_content = "Sekarang aku hanya perlu memasukkan ini dalam urutan yang benar...",
  ui_story_1020_10200501_13_dialog_content = "<color=#e8d9bb>Bip — Bip — Bip —</color>",
  ui_story_1020_10200501_14_dialog_content = "... Tidak baik, hah?",
  ui_story_1020_10200501_15_dialog_content = "Aku ingat sekarang! Itu Bool. Rambutnya sekarang terlihat persis seperti tentakel Bool!",
  ui_story_1020_10200501_16_dialog_content = "Mungkin kepala PlayerName adalah superkomputer seperti Bool?",
  ui_story_1020_10200501_17_dialog_content = "Saya khawatir ada yang salah dengan PlayerName, Dr. Algol!",
  ui_story_1020_10200501_18_dialog_content = "... Bahkan jika dia memiliki kemampuan psikis yang paling kuat di dunia, itu tidak menjadikannya sebuah komputer...",
  ui_story_1020_10200501_19_dialog_content = "Mari kita bangunkan dia—",
  ui_story_1020_10200501_20_dialog_content = "85... X... 32.875... X...",
  ui_story_1020_10200501_21_dialog_content = "Hah?",
  ui_story_1020_10200501_22_dialog_content = "Dia bergumam apa, sih?",
  ui_story_1020_10200501_23_dialog_content = "... \"X\"?",
  ui_story_1020_10200501_24_dialog_content = "Bukan hanya angka?",
  ui_story_1020_10200501_25_dialog_content = "3292... X... 4782... X... 2212323293845...",
  ui_story_1020_10200501_26_dialog_content = "Wajahnya telah berubah seMerah tomat!",
  ui_story_1020_10200501_27_dialog_content = "... 12983289... X...",
  ui_story_1020_10200501_28_dialog_content = "50227833... X...",
  ui_story_1020_10200501_29_dialog_content = "Orang ini sebenarnya bisa mengimbangi kecepatan komputasi Bool... Dia akan berada dalam bahaya serius jika ini terus berlanjut...",
  ui_story_1020_10200501_30_dialog_content = "... Tapi jika kita menghentikannya sekarang, akan semakin sulit untuk mendapatkan informasi ini lagi...",
  ui_story_1020_10200501_31_dialog_content = "Di sini! Aku akan memasangkan gelangku padanya dan memberinya dua menit lagi.",
  ui_story_1020_10200501_32_dialog_content = "... Apa yang akan itu lakukan?",
  ui_story_1020_10200501_33_dialog_content = "Dua menit adalah waktu terlama sel otak seseorang dapat mempertahankan operasi kecepatan tinggi, dan gelang ini dapat memantau kesehatan pemakainya dengan cermat.",
  ui_story_1020_10200501_34_dialog_content = "Jika data mulai membebani pikirannya, gelang akan memberi kita peringatan.",
  ui_story_1020_10200501_35_dialog_content = "Sebelum itu terjadi, saya akan membutuhkan bantuan untuk merekam lebih banyak data. Gronru, Guardian One, kita harus mengumpulkan sebanyak mungkin informasi yang berguna dalam dua menit ke depan.",
  ui_story_1020_10200501_36_dialog_content = "Bahkan sebagian dari itu akan berfungsi. Ini mungkin satu-satunya kesempatan kita untuk mengakses file memori paling aman dari prototipe!",
  ui_story_1020_10200501_37_dialog_content = "Bukan masalah!",
  ui_story_1020_10200501_38_dialog_content = "Wali Satu mengerti.",
  ui_story_1020_10200501_39_dialog_content = "Perhatikan jamnya, Vivian. Beri tahu kami saat dua menit sudah habis, dan kami akan berhenti.",
  ui_story_1020_10200501_40_dialog_content = "Tentu.",
  ui_story_1020_10200501_41_dialog_content = "Migard, jika gelang tersebut mengirimkan peringatan dalam dua menit itu, angkat PlayerName dan bawa dia keluar dari sini.",
  ui_story_1020_10200501_42_dialog_content = "Bisa!",
  ui_story_1020_10200501_43_dialog_content = "862033934... X...",
  ui_story_1020_10200501_44_dialog_content = "385782493666... X...",
  ui_story_1020_10200501_45_dialog_content = "Bip, bip, bip, bip, bip...",
  ui_story_1020_10200501_46_dialog_content = "236758423423... X...",
  ui_story_1020_10200501_47_dialog_content = "(\"X\"?)",
  ui_story_1020_10200501_48_dialog_content = "(Apakah karakter yang bersinar itu adalah \"X\"?)",
  ui_story_1020_10200501_49_dialog_content = "(Argh... Mungkin sudah banyak waktu yang telah berlalu sekarang...)",
  ui_story_1020_10200501_50_dialog_content = "(Kepalaku sepertinya tidak sakit sebanyak sebelumnya!)",
  ui_story_1020_10200501_51_dialog_content = "(Tapi apa maksud dari \"X\" ini?)",
  ui_story_1020_10200501_52_dialog_content = "(Ahhh... Ini mempercepat lagi...)",
  ui_story_1020_10200502_1_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10200502_2_dialog_content = "Tepat dua menit.",
  ui_story_1020_10200502_3_dialog_content = "Bagus sekali!",
  ui_story_1020_10200502_4_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10200502_5_dialog_content = "Oke, oke... Pelan-pelan, ya!",
  ui_story_1020_10200502_6_dialog_content = "Nah, mari kita gunakan komputer ini untuk menganalisis data yang baru saja kita terima. Saya yakin kali ini pasti berhasil.",
  ui_story_1020_10200502_7_dialog_content = "Bu!",
  ui_story_1020_10200502_8_dialog_content = "Argh—",
  ui_story_1020_10200502_9_dialog_content = "Kau tidak apa-apa, PlayerName?",
  ui_story_1020_10200502_10_dialog_content = "Wow, bicara tentang tekanan darah tinggi! Dan saturasi oksigen nadi Anda... Bisakah Anda melihat kami dengan jelas?",
  ui_story_1020_10200502_11_dialog_content = "Y-Ya, aku melihatmu...",
  ui_story_1020_10200502_12_dialog_content = "Duduk dan jangan bergerak. Ikuti jari saya dengan mata Anda.",
  ui_story_1020_10200502_13_dialog_content = "Kiri kanan...",
  ui_story_1020_10200502_14_dialog_content = "Bagaimana perasaan mu saat ini?",
  ui_story_1020_10200502_15_dialog_content = "Kepalaku... Rasanya sedikit pusing... Dan anggota tubuhku terasa sangat lemas...",
  ui_story_1020_10200502_16_dialog_content = "Apa kamu merasa mual atau ada masalah dengan penglihatan?",
  ui_story_1020_10200502_17_dialog_content = "Aku rasa tidak...",
  ui_story_1020_10200502_18_dialog_content = "Nih, minum ini.",
  ui_story_1020_10200502_19_dialog_content = "Ada apa?",
  ui_story_1020_10200502_20_dialog_content = "Aktivitas serebral yang intens seperti itu biasanya diikuti oleh gejala hipoksia. Percayalah, aku agak ahli dalam hal ini.",
  ui_story_1020_10200502_21_dialog_content = "Namun, saya tidak menyangka kamu bisa menggunakan kemampuan psikis hingga sejauh ini. Kamu benar-benar telah membantu saya sekarang!",
  ui_story_1020_10200502_22_dialog_content = "Aku juga tidak tahu aku bisa... Pada awalnya, angka-angka bergerak begitu cepat sehingga aku hampir tidak bisa membaca satu baris dengan jelas.",
  ui_story_1020_10200502_23_dialog_content = "Tapi ketika saya berhenti mencoba fokus pada urutan dan, seperti yang kamu katakan, menyerah berpikir... Tiba-tiba, angka-angka mulai mengalir lebih alami...",
  ui_story_1020_10200502_24_dialog_content = "Pada satu titik, aku bahkan berhenti sejenak untuk berpikir...",
  ui_story_1020_10200502_25_dialog_content = "Tetapi segera setelah saya melakukannya, angka-angka itu kembali mempercepat...",
  ui_story_1020_10200502_26_dialog_content = "Cepat... Lambat... Lalu berpikir... Kecepatan dipengaruhi oleh pikiran... Kurva belajar yang sepenuhnya responsif...",
  ui_story_1020_10200502_27_dialog_content = "Tunggu, tapi bukankah kamu bilang kamu sudah berhenti berpikir sama sekali? Bagaimana kamu bisa melihat angka-angka itu dengan begitu jelas? Sebenarnya, siapa kamu?",
  ui_story_1020_10200502_28_dialog_content = "Yakin... Kamu bukan semacam kecerdasan buatan atau apa pun, kan?",
  ui_story_1020_10200502_29_dialog_content = "K-Kamu benar-benar harus bertanya?",
  ui_story_1020_10200502_30_dialog_content = "Pokoknya, saya ingat melihat \"X\" saat saya di sana. Apa artinya itu?",
  ui_story_1020_10200502_31_dialog_content = "Aku tidak salah ingat... bukan?",
  ui_story_1020_10200502_32_dialog_content = "Tidak, kamu bukan...",
  ui_story_1020_10200502_33_dialog_content = "Tapi sayangnya... hanya Bool—bagian lain dari perangkat kuno itu—yang tahu apa yang harus dilakukan dengan informasi itu...",
  ui_story_1020_10200502_34_dialog_content = "Algol juga merasa tak berdaya.",
  ui_story_1020_10200502_35_dialog_content = "Apa perasaan yang aneh... ditinggalkan oleh teknologi yang diciptakan jauh sebelum zaman kita...",
  ui_story_1020_10200502_36_dialog_content = "Apakah mesin ini dibuat oleh seseorang, ataukah ini hasil karya seorang dewa? Hahahaha!",
  ui_story_1020_10200502_37_dialog_content = "...",
  ui_story_1020_10200502_38_dialog_content = "Federasi Illumina telah terjebak menggunakan komputer berbasis biner selama enam ratus tahun terakhir!",
  ui_story_1020_10200502_39_dialog_content = "Dari perhitungan matematika hingga pengukuran materi dalam keadaan stabil, kami selalu percaya bahwa biner adalah solusi optimal untuk semua kebutuhan komputasi kami.",
  ui_story_1020_10200502_40_dialog_content = "Tapi mesin ini... Bahasa komputasi paling dasarnya menggunakan karakter selain nol dan satu! Mungkin ini adalah bahasa ternary atau bahkan quaternary...",
  ui_story_1020_10200502_41_dialog_content = "Dan bagaimana dengan \"X\" itu? Saya bahkan tidak bisa memahami ilmu di balik ini... Sebuah \"X\"!",
  ui_story_1020_10200502_42_dialog_content = "Rasanya hampir seperti dia mengejekku, apa kau setuju? Hahahaha!",
  ui_story_1020_10200502_43_dialog_content = "Bagaimana bisa terjadi? Seberapa rumit logika yang diprosesnya?",
  ui_story_1020_10200502_44_dialog_content = "Dan apa yang sebenarnya terjadi pada peradaban kuno ini?",
  ui_story_1020_10200502_45_dialog_content = "Mengapa tidak ada yang tersisa selain Caelestite, Aurorian, dan Eclipsite?",
  ui_story_1020_10200502_46_dialog_content = "Oh! Hampir saja aku lupa... Ada juga God of Light! Dan juga Lord of Truth! Apakah Bloody Bible menyembunyikan jawabannya?",
  ui_story_1020_10200502_47_dialog_content = "Heheh... Hahahaha...",
  ui_story_1020_10200502_48_dialog_content = "Apa yang terjadi padanya? Ini semakin menyeramkan...",
  ui_story_1020_10200502_49_dialog_content = "Algol menyadari bahwa dia agak tidak berguna.",
  ui_story_1020_10200502_50_dialog_content = "Tidak berguna? Jangan membuatku tertawa! Aku sudah cukup melakukan itu sendiri...",
  ui_story_1020_10200502_51_dialog_content = "Hahahaha!",
  ui_story_1020_10200502_52_dialog_content = "Wali Satu! Saya tidak peduli apakah itu dewa yang dendam atau roh jahat!",
  ui_story_1020_10200502_53_dialog_content = "Dunia ini tidak peduli siapa yang datang terlebih dahulu, dan aku menolak untuk meninggalkan ketidakpastianku di tangan orang mati!",
  ui_story_1020_10200502_54_dialog_content = "Mungkin saat ini saya tidak bisa mengungkap misterinya, tapi itu tidak akan menghentikan saya untuk meneliti dan mengembangkan Sistem Guardian.",
  ui_story_1020_10200502_55_dialog_content = "Kamu mendengarku?",
  ui_story_1020_10200502_56_dialog_content = "Guardian One mengerti dalam setiap pengertian kata tersebut.",
  ui_story_1020_10200502_57_dialog_content = "Huuu!",
  ui_story_1020_10200502_58_dialog_content = "Bagus! Semua terserah padamu sekarang, Bool!",
  ui_story_1020_10200502_59_dialog_content = "... Bu...",
  ui_story_1020_10200502_60_dialog_content = "Saatnya akhirnya tiba...",
  ui_story_1020_10200502_61_dialog_content = "Ayo masuk ke sarang bos!",
  ui_story_1020_10200502_62_dialog_content = "...",
  ui_story_1020_10200502_63_dialog_content = "Ada apa ini?",
  ui_story_1020_10200502_64_dialog_content = "Caelestite.",
  ui_story_1020_10200502_65_dialog_content = "...",
  ui_story_1020_10200502_66_dialog_content = "Cahaya berkedip dalam pikiranku... Itu bukan mimpi?",
  ui_story_1020_10200502_67_dialog_content = "Matahari hitam yang aku lihat... Apakah itu ada hubungannya dengan prototipe?",
  ui_story_1020_10200601_1_dialog_content = "Kamu menyebutkan bahwa cincin itu ada dalam mimpimu...",
  ui_story_1020_10200601_2_dialog_content = "Kamu melihat Wraith dan Vice juga?",
  ui_story_1020_10200601_3_dialog_content = "Ya...",
  ui_story_1020_10200601_4_dialog_content = "Apakah Eclipse yang membangun prototipe Ulysses? Menurutmu, apakah ada kaitan antara semua ini, Dr. Algol?",
  ui_story_1020_10200601_5_dialog_content = "Tentu saja ada... Hahahahaha!",
  ui_story_1020_10200601_6_dialog_content = "...",
  ui_story_1020_10200601_7_dialog_content = "... Kenapa kalian semua memiliki tampang seperti itu di wajah kalian?",
  ui_story_1020_10200601_8_dialog_content = "Tapi ini adalah teknologi kuno yang sangat Illumina andalkan untuk bertahan sejak pendiriannya...",
  ui_story_1020_10200601_9_dialog_content = "Bukankah itu akan menjadi ancaman yang berbahaya jika itu diciptakan oleh Eclipse?",
  ui_story_1020_10200601_10_dialog_content = "Caelestite.",
  ui_story_1020_10200601_11_dialog_content = "(Itu dia lagi...)",
  ui_story_1020_10200601_12_dialog_content = "Setidaknya, pemindaian saya tidak menemukan perbedaan antara itu dan simulator saya.",
  ui_story_1020_10200601_13_dialog_content = "Jika lebih banyak prajurit super ditempatkan di lokasi lain, aku khawatir prototipe tidak akan memiliki catatan tentang hal itu.",
  ui_story_1020_10200601_14_dialog_content = "Sepertinya ada beberapa kaitan antara tanda-tanda pada prototipe dan mimpi PlayerName. Alur cerita semakin rumit...",
  ui_story_1020_10200601_15_dialog_content = "Sebaliknya, saya pikir ini semakin mudah dipahami.",
  ui_story_1020_10200601_16_dialog_content = "Pada awalnya, kita semua berpikir bahwa Ulysses tidak lebih dari seorang megalomania yang putus asa, tetapi setelah melihat ini, saya tidak begitu yakin lagi.",
  ui_story_1020_10200601_17_dialog_content = "Selama bertahun-tahun ini, Kota Gannon tidak pernah hancur... Apakah dia benar-benar bersikeras melakukan eksperimen-eksperimen itu karena kegilaan semata?",
  ui_story_1020_10200601_18_dialog_content = "Chief of Staff, saya ingin membawa Ulysses ke sini.",
  ui_story_1020_10200601_19_dialog_content = "Uh, saya tidak yakin Committee akan menyetujui itu, tapi saya bisa mencoba menghubungi Grand Marshal...",
  ui_story_1020_10200601_20_dialog_content = "...",
  ui_story_1020_10200601_21_dialog_content = "Tapi Ulysses memiliki pemahaman terbesar tentang mesin ini saat ini.",
  ui_story_1020_10200601_22_dialog_content = "Bool hanya dapat membantu kita mengambil data modul yang diperlukan untuk membangun inti. Informasi yang kita rekam baru saja hanya untuk membantu perhitungan, dan tidak lebih dari itu.",
  ui_story_1020_10200601_23_dialog_content = "Prototipe telah disegel selama ini. Ke depannya, saya tidak tahu jenis hambatan apa yang akan dihadapi penelitian kita.",
  ui_story_1020_10200601_24_dialog_content = "Caelestite.",
  ui_story_1020_10200601_25_dialog_content = "...",
  ui_story_1020_10200601_26_dialog_content = "Kau tidak apa-apa, PlayerName?",
  ui_story_1020_10200601_27_dialog_content = "Aku... Aku rasa aku baru saja melihat sesuatu yang berkedip...",
  ui_story_1020_10200601_28_dialog_content = "Apa itu?",
  ui_story_1020_10200601_29_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10200601_30_dialog_content = "<color=#e8d9bb>Bip — Bip — Bip —</color>",
  ui_story_1020_10200601_31_dialog_content = "Apakah sudah terkunci?",
  ui_story_1020_10200601_32_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_1020_10200601_33_dialog_content = "Hei, ada apa?",
  ui_story_1020_10200601_34_dialog_content = "Gudangnya bergetar!",
  ui_story_1020_10200601_35_dialog_content = "...",
  ui_story_1020_10200601_36_dialog_content = "Tunggu... Seharusnya tidak terkunci karena kita bisa mengambil data modulnya...",
  ui_story_1020_10200601_37_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10200601_38_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_1020_10200601_39_dialog_content = "Bukankah Bool mengekstrak kode pertahanan dari prototipe untuk membangun inti baru?",
  ui_story_1020_10200601_40_dialog_content = "Apakah ini terkait dengan proses penyelesaian pelanggaran pertahanan?",
  ui_story_1020_10200601_41_dialog_content = "Sepertinya memang begitu, tapi getaran ini terlalu kuat!",
  ui_story_1020_10200601_42_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_1020_10200601_43_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10200601_44_dialog_content = "Kamu benar! Lebih tepatnya seperti ada sesuatu yang mulai menyerang komputerku dan sistem pertahanan Illumina setelah kita mendapatkan data modul Guardian!",
  ui_story_1020_10200601_45_dialog_content = "Apakah ini kasus di mana sebuah game meniru kenyataan? Intrusi data?",
  ui_story_1020_10200601_46_dialog_content = "Tunggu sebentar... Modul pertahanan, modul pertahanan... Tunggu sebentar...",
  ui_story_1020_10200601_47_dialog_content = "Kalian pergi dan nilai situasi di sekitar kita. Aku akan mencoba mengambil modul pertahanan lagi.",
  ui_story_1020_10200601_48_dialog_content = "Jika Guardian bukan memperkuat pertahanannya, tetapi malah semakin merusaknya...",
  ui_story_1020_10200601_49_dialog_content = "Maka seluruh Undercity ini dalam masalah...",
  ui_story_1020_10200601_50_dialog_content = "Tidak. Apapun yang sedang melawan kita sekarang ini berada di dalam prototipe atau mungkin di sisi lain.",
  ui_story_1020_10200601_51_dialog_content = "...",
  ui_story_1020_10200601_52_dialog_content = "Tapi, kira-kira apa ya?",
  ui_story_1020_10200601_53_dialog_content = "Hanya Ulysses yang tahu...",
  ui_story_1020_10200601_54_dialog_content = "<color=#e8d9bb>Bip — Bip — Bip —</color>",
  ui_story_1020_10200601_55_dialog_content = "Tidak! Itu memotong jalur akses saya!",
  ui_story_1020_10200601_56_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_1020_10200601_57_dialog_content = "<color=#e8d9bb>Bip—</color>",
  ui_story_1020_10200601_58_dialog_content = "<color=#e8d9bb>Bip—</color>",
  ui_story_1020_10200601_59_dialog_content = "<color=#e8d9bb>Bip — Bip — Bip —</color>",
  ui_story_1020_10200601_60_dialog_content = "Informasi begitu banyak sekaligus...",
  ui_story_1020_10200601_61_dialog_content = "Terowongan... Gerbang 10... Situasinya lebih buruk dari yang kubayangkan, Dr. Algol!",
  ui_story_1020_10200601_62_dialog_content = "Banyak sistem pertahanan Undercity sedang diserang!",
  ui_story_1020_10200601_63_dialog_content = "... Banyak kontrol yang mungkin telah dikunci. Chief of Staff, kurasa kamu harus keluar dan membantu untuk saat ini!",
  ui_story_1020_10200601_64_dialog_content = "Bool, mulai ulang modul!",
  ui_story_1020_10200601_65_dialog_content = "Hiks!",
  ui_story_1020_10200601_66_dialog_content = "Gronru, Migard, kalian berdua periksa panel kontrol di gedung laboratorium, terutama area dengan gudang dan peralatan laboratorium besar.",
  ui_story_1020_10200601_67_dialog_content = "Kita harus mengendalikan beberapa saklar secara manual untuk saat ini.",
  ui_story_1020_10200601_68_dialog_content = "Aku akan mengumpulkan lebih banyak informasi dari mereka yang mengirimiku pesan, lalu akan menghubungi Grand Marshal!",
  ui_story_1020_10200601_69_dialog_content = "Kamu memiliki persepsi yang tajam, PlayerName. Beri tahu semua orang saat kamu merasakan bahaya!",
  ui_story_1020_10200601_70_dialog_content = "Bukan masalah!",
  ui_story_1020_10200601_71_dialog_content = "(Apakah ini ada hubungannya dengan cahaya berkedip yang baru saja saya lihat?)",
  ui_story_1020_10200601_72_dialog_content = "<color=#e8d9bb>Tim konstruksi di terowongan Illumina</color>",
  ui_story_1020_10200601_73_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_1020_10200601_74_dialog_content = "Ciel! Ciel!",
  ui_story_1020_10200601_75_dialog_content = "Ayo, keluar sekarang juga!",
  ui_story_1020_10200601_76_dialog_content = "Apa?",
  ui_story_1020_10200601_77_dialog_content = "Tidak bisakah kamu merasakan getaran yang hebat itu? Terowongan di depanmu telah runtuh!",
  ui_story_1020_10200601_78_dialog_content = "Tapi lebih berbahaya untuk berlari tanpa arah sekarang...",
  ui_story_1020_10200601_79_dialog_content = "Pokoknya, saya sedang mengaktifkan mecha dinamis.",
  ui_story_1020_10200601_80_dialog_content = "<color=#e8d9bb>Pusat Medis Illumina</color>",
  ui_story_1020_10200601_81_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_1020_10200601_82_dialog_content = "Semua keributan ini...",
  ui_story_1020_10200601_83_dialog_content = "Apa aku membangunkan semua orang lagi?",
  ui_story_1020_10200601_84_dialog_content = "...",
  ui_story_1020_10200601_85_dialog_content = "Tidak, bukan kali ini.",
  ui_story_1020_10200601_86_dialog_content = "aku masih di tempat tidur...",
  ui_story_1020_10200601_87_dialog_content = "Reinhardt... Saya hanya berharap saya bisa melakukan sesuatu untuk Illumina.",
  ui_story_1020_10200601_88_dialog_content = "<color=#e8d9bb>Bip—</color>",
  ui_story_1020_10200601_89_dialog_content = "Grand Marshal! Akhirnya, kamu—",
  ui_story_1020_10200601_90_dialog_content = "Maaf membuatmu menunggu lama.",
  ui_story_1020_10200601_91_dialog_content = "Sebuah mesin berbahaya telah terlihat di gudang Tech Park. Di mana semua kamu?",
  ui_story_1020_10200601_92_dialog_content = "Kami berada di Gudang Nol. Ulysses telah menggunakannya secara diam-diam!",
  ui_story_1020_10200601_93_dialog_content = "Warehouse Zero?",
  ui_story_1020_10200601_94_dialog_content = "Ini berisi super-prajurit dan mesin kuno yang kemungkinan memiliki hubungan dengan Eclipse yang menyebabkan gempa!",
  ui_story_1020_10200601_95_dialog_content = "Kembali!",
  ui_story_1020_10200601_96_dialog_content = "Semua orang perlu dievakuasi dari area ini sekarang juga!",
  ui_story_1020_10200601_97_dialog_content = "Dr. Algol...",
  ui_story_1020_10200601_98_dialog_content = "Pegang kendali itu dengan mantap! Ini akan memakan waktu jika kita ingin membangun inti baru untuk menyelesaikan pelanggaran pertahanan!",
  ui_story_1020_10200601_99_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10200601_100_dialog_content = "Oh, benar! Kepala Staf, tolong minta Reinhardt untuk mengantar Ulysses ke sini!",
  ui_story_1020_10200601_101_dialog_content = "<color=#e8d9bb>Ruang Konferensi Tingkat Tinggi Illumina</color>",
  ui_story_1020_10200601_102_dialog_content = "Sistem kontrol otomatis tidak berfungsi. Pintu gerbang dekat permukaan tanah mengalami kerusakan. Terowongan telah runtuh...",
  ui_story_1020_10200601_103_dialog_content = "Apakah ini hasil yang telah Anda nantikan?",
  ui_story_1020_10200601_104_dialog_content = "Bagaimana dengan Lumopolis?",
  ui_story_1020_10200601_105_dialog_content = "Tidak ada yang terjadi.",
  ui_story_1020_10200601_106_dialog_content = "...",
  ui_story_1020_10200601_107_dialog_content = "Apakah kamu berpikir untuk mengumumkan <color=#FFB400>Protokol Darurat</color>?",
  ui_story_1020_10200601_108_dialog_content = "Belum waktunya.",
  ui_story_1020_10200601_109_dialog_content = "Aku merasakan tanah bergetar.",
  ui_story_1020_10200601_110_dialog_content = "Aku juga.",
  ui_story_1020_10200601_111_dialog_content = "Apakah ini semua dari orang-orang yang mengklaim akan mengambil alih laboratoriumku?",
  ui_story_1020_10200601_112_dialog_content = "Heheh... Menurutmu apa yang bisa kamu lakukan?",
  ui_story_1020_10200601_113_dialog_content = "Anda tahu ada masalah dengan mesin itu, dan Anda hanya menunggu sesuatu terjadi, bukan?",
  ui_story_1020_10200601_114_dialog_content = "... Masalah dengan prototipe?",
  ui_story_1020_10200601_115_dialog_content = "Kamu harus... mengungkap sejarah sendiri...",
  ui_story_1020_10200601_116_dialog_content = "Wrath, Hiiro, tetap awasi Ulysses. Jangan biarkan dia lepas dari penglihatanmu untuk alasan apa pun.",
  ui_story_1020_10200601_117_dialog_content = "Aku akan menilai situasi dan memberi tahu kamu kapan aman untuk membawanya ke sana.",
  ui_story_1020_10200601_118_dialog_content = "Aku mengerti.",
  ui_story_1020_10200601_119_dialog_content = "Hati-hati.",
  ui_story_1020_10200601_120_dialog_content = "<color=#e8d9bb>Level Permukaan Kota Gannon</color>",
  ui_story_1020_10200601_121_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_1020_10200601_122_dialog_content = "Ya, Komandan Barton! Tembok-tembok bergetar keras seperti ada yang menekan tombol gerbang!",
  ui_story_1020_10200601_123_dialog_content = "Semua gerbang?",
  ui_story_1020_10200601_124_dialog_content = "Tidak. Ini terutama karena Eclipsite mendekat dari dua gerbang yang rusak parah di sebelah kanan!",
  ui_story_1020_10200601_125_dialog_content = "Vivian dan perusahaannya mungkin mengalami masalah.",
  ui_story_1020_10200601_126_dialog_content = "Pertahankan gerbang dengan segala cara.",
  ui_story_1020_10200601_127_dialog_content = "Meskipun mereka membuat lubang di dalamnya, kita akan menutupinya dengan menara dan meledakkan penyerang saat mereka datang!",
  ui_story_1020_10200601_128_dialog_content = "Jika kamu suka melihat kepala Eclipsite meledak, kamu beruntung hari ini!",
  ui_story_1020_10200601_129_dialog_content = "Baik!",
  ui_story_1020_10200601_130_dialog_content = "<color=#e8d9bb>Duar—Duar—Duar!</color>",
  ui_story_1020_10200601_131_dialog_content = "Hahaha!",
  ui_story_1020_10200601_132_dialog_content = "Kepala meledak!",
  ui_story_1020_10200601_133_dialog_content = "Inilah yang paling kuat di Barton Legion!",
  ui_story_1020_10200602_1_dialog_content = "Huu, huu, huu!",
  ui_story_1020_10200602_2_dialog_content = "...",
  ui_story_1020_10200602_3_dialog_content = "Apakah kalian semua baik-baik saja?",
  ui_story_1020_10200602_4_dialog_content = "Terima kasih telah menghentikan monster di belakangku, Grand Marshal!",
  ui_story_1020_10200602_5_dialog_content = "Aku tak pernah menyangka bahwa prajurit super yang jatuh itu akan bangkit dan menyerang lagi!",
  ui_story_1020_10200602_6_dialog_content = "Kami kembali, kami kembali! Alarm pintu beberapa lab memang berbunyi!",
  ui_story_1020_10200602_7_dialog_content = "Mereka terkunci lagi sekarang, dengan prajurit yang berjaga di luar lab.",
  ui_story_1020_10200602_8_dialog_content = "Kerja bagus, semuanya.",
  ui_story_1020_10200602_9_dialog_content = "Jadi meskipun Illumina dalam situasi yang sangat buruk, kamu masih ngotot pergi ke tempat yang lebih berbahaya. Kenapa aku tidak terkejut, PlayerName?",
  ui_story_1020_10200602_10_dialog_content = "Maaf…",
  ui_story_1020_10200602_11_dialog_content = "Aku hanya senang kamu selamat. Aku tidak tahu Ulysses menggunakan tempat ini untuk memproduksi super-prajurit...",
  ui_story_1020_10200602_12_dialog_content = "Berikan aku laporan status, Vivian.",
  ui_story_1020_10200602_13_dialog_content = "Dimulai dengan pelanggaran di pertahanan Gannon dan super-prajurit menyerang kami di Taman Teknologi.",
  ui_story_1020_10200602_14_dialog_content = "Untungnya, Dr. Algol menemukan tempat ini dan menemukan prototipe yang disegel. Dia sedang mencoba membangun inti pertahanan saat ini.",
  ui_story_1020_10200602_15_dialog_content = "Jadi guncangan barusan itu, apakah masalahnya sudah terselesaikan?",
  ui_story_1020_10200602_16_dialog_content = "Untuk saat ini, iya. Saya berhasil membuka akses baru dan menstabilkan kontrol, tapi siapa yang tahu di mana pelanggaran keamanan berikutnya akan terjadi.",
  ui_story_1020_10200602_17_dialog_content = "Dimana Ulysses?",
  ui_story_1020_10200602_18_dialog_content = "Dia memberi tahu kami tentang mesin ini, tetapi saya perlu memahami situasinya sebelum memutuskan apakah akan membawanya ke sini atau tidak.",
  ui_story_1020_10200602_19_dialog_content = "Kondisinya sekarang ini... istimewa, setidaknya itu yang bisa dikatakan.",
  ui_story_1020_10200602_20_dialog_content = "Apakah dia memberi tahu Anda siapa kontaknya di dalam Eclipse?",
  ui_story_1020_10200602_21_dialog_content = "Kalau kamu bertanya begitu padaku, maka tidak ada keraguan tentang itu...",
  ui_story_1020_10200602_22_dialog_content = "Dia menyebutkan bahwa dia menemukan petunjuk terkait dengan Engineer di dalam prototipe.",
  ui_story_1020_10200602_23_dialog_content = "Menurut Ulysses, Engineer adalah orang yang pertama kali mendirikan Illumina Federation dan menghilang tanpa jejak lebih dari enam ratus tahun yang lalu...",
  ui_story_1020_10200602_24_dialog_content = "Menghilang enam ratus tahun lalu... Dan sekarang sang Insinyur menggunakan komputer untuk berkomunikasi dengan Ulysses...",
  ui_story_1020_10200602_25_dialog_content = "Menggunakan kekuatan psikis seperti PlayerName?",
  ui_story_1020_10200602_26_dialog_content = "Kekuatan psikis?",
  ui_story_1020_10200602_27_dialog_content = "(Penglihatan yang saya lihat di kepala saya... Apakah mereka dibuat oleh kekuatan seperti milik saya?)",
  ui_story_1020_10200602_28_dialog_content = "Bukankah itu sesuatu yang hanya bisa dilakukan oleh Caelestite?",
  ui_story_1020_10200602_29_dialog_content = "Jika Insinyur benar-benar ada, maka berkomunikasi dengan Ulysses secara real time melalui prototipe teoretis mungkin, asalkan sirkuitnya cukup efisien.",
  ui_story_1020_10200602_30_dialog_content = "Tapi prototipe ini tidak memiliki kabel sejauh yang bisa saya lihat, atau perangkat keras apa pun untuk mengirim dan menerima pesan. Itu berarti—",
  ui_story_1020_10200602_31_dialog_content = "Bip—",
  ui_story_1020_10200602_32_dialog_content = "Ini adalah <color=#FFB400>antarmuka</color> yang Algol suruh Guardian One bawa.",
  ui_story_1020_10200602_33_dialog_content = "Terima kasih, berikan di sini.",
  ui_story_1020_10200602_34_dialog_content = "Jadi misalnya...",
  ui_story_1020_10200602_35_dialog_content = "Selama saya terhubung ke sirkuit seperti ini, Guardian One dapat muncul di komputer saya dan berkomunikasi dengan saya secara real time.",
  ui_story_1020_10200602_36_dialog_content = "Oh. Hai, semua! Apakah wajahku terlihat terlalu besar?",
  ui_story_1020_10200602_37_dialog_content = "Kita tidak melihat <color=#FFB400>sirkuit</color> seperti itu saat kita memeriksa. Semuanya sangat bersih. Bahkan dinding dan lantai dilas dengan sempurna...",
  ui_story_1020_10200602_38_dialog_content = "Itu aneh. Menurut catatan kami, gudang ini tidak digunakan karena terlalu banyak rangkaian lama yang praktis menyatu dengan lingkungannya. Tidak ada cara bagi kami untuk memanfaatkannya.",
  ui_story_1020_10200602_39_dialog_content = "Apakah itu benar-benar kasusnya? Karena ketika saya pertama kali sampai di sini, itu tidak terlihat berbeda dari sekarang.",
  ui_story_1020_10200602_40_dialog_content = "Mungkin saja seseorang sudah memperbaikinya sebelum itu.",
  ui_story_1020_10200602_41_dialog_content = "Memperbaiki gudang sebesar ini bukanlah tugas yang mudah, si tua nakal itu...",
  ui_story_1020_10200602_42_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10200602_43_dialog_content = "<color=#e8d9bb>Bzz—Bzz—</color>",
  ui_story_1020_10200602_44_dialog_content = "Hei, mengapa sirkuitmu berkilauan, Dr. Algol?",
  ui_story_1020_10200602_45_dialog_content = "Hah? Kelebihan beban daya? Tapi itu tidak mungkin!",
  ui_story_1020_10200602_46_dialog_content = "Tunggu... Setiap komponen berjalan dengan kekuatan maksimal?",
  ui_story_1020_10200602_47_dialog_content = "<color=#e8d9bb>Bzz—Bang!</color>",
  ui_story_1020_10200602_48_dialog_content = "Argh! Ini merusak sirkuitku!",
  ui_story_1020_10200602_49_dialog_content = "Algol marah.",
  ui_story_1020_10200602_50_dialog_content = "Huu, huu, huu!",
  ui_story_1020_10200602_51_dialog_content = "<color=#e8d9bb>Bip — Bip — Bip —</color>",
  ui_story_1020_10200602_52_dialog_content = "Dari semua keberuntungan busuk! Sekarang modul pertahanan baru macet!",
  ui_story_1020_10200602_53_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10200602_54_dialog_content = "<color=#e8d9bb>Suara mendesing—</color>",
  ui_story_1020_10200602_55_dialog_content = "Ini berhenti?",
  ui_story_1020_10200602_56_dialog_content = "<color=#e8d9bb>Berdengung—Berdengung—</color>",
  ui_story_1020_10200602_57_dialog_content = "Itu adalah otak!",
  ui_story_1020_10200602_58_dialog_content = "...",
  ui_story_1020_10200602_59_dialog_content = "Mungkinkah ini yang disebut \"Insinyur\"?",
  ui_story_1020_10200602_60_dialog_content = "Gambaran yang berkedip-kedip itu... Apakah dia mencoba berkomunikasi denganku?",
  ui_story_1020_10200602_61_dialog_content = "Hei, kenapa itu hilang?",
  ui_story_1020_10200602_62_dialog_content = "Huu, huu, huu!",
  ui_story_1020_10200602_63_dialog_content = "Apa? Dia berbicara? Bisakah kamu memahami bahasanya?",
  ui_story_1020_10200602_64_dialog_content = "... Buu, buu...",
  ui_story_1020_10200602_65_dialog_content = "Apa yang dikatakan oleh Insinyur?",
  ui_story_1020_10200602_66_dialog_content = "... Buu, buu...",
  ui_story_1020_10200602_67_dialog_content = "\"Sudah lama\"",
  ui_story_1020_10200602_68_dialog_content = "... Buu, buu...",
  ui_story_1020_10200602_69_dialog_content = "\"Dokter\"",
  ui_story_1020_10200602_70_dialog_content = "... Buu, buu...",
  ui_story_1020_10200602_71_dialog_content = "\"Ulysses\"",
  ui_story_1020_10200602_72_dialog_content = "...",
  ui_story_1020_10200602_73_dialog_content = "Bool! Alihkan rute akses dan coba untuk mengambil modul!",
  ui_story_1020_10200602_74_dialog_content = "Hiks!",
  ui_story_1020_10200602_75_dialog_content = "<color=#e8d9bb>Suara mendesing—</color>",
  ui_story_1020_10200602_76_dialog_content = "...",
  ui_story_1020_10200602_77_dialog_content = "Sudah... lama sekali...",
  ui_story_1020_10200602_78_dialog_content = "Ya... Ya... Haha...",
  ui_story_1020_10200602_79_dialog_content = "Jadi, kau telah datang...",
  ui_story_1020_10200602_80_dialog_content = "Siapa itu?",
  ui_story_1020_10200602_81_dialog_content = "Insinyur...",
  ui_story_1020_10200602_82_dialog_content = "Di mana?",
  ui_story_1020_10200602_83_dialog_content = "Berikan aku pil terakhir, Esien.",
  ui_story_1020_10200602_84_dialog_content = "Pak…",
  ui_story_1020_10200602_85_dialog_content = "Berikan kepadaku!",
  ui_story_1020_10200602_86_dialog_content = "<color=#e8d9bb>Sel Penjara Illumina</color>",
  ui_story_1020_10200602_87_dialog_content = "(Eclipsian) I-Itu kamu... Penguasa tertinggi!",
  ui_story_1020_10200602_88_dialog_content = "(Eclipsian) Hamba setia Anda, Figerald, telah berlutut di sini sepanjang waktu, menunggu kedatangan Anda.",
  ui_story_1020_10200602_89_dialog_content = "...",
  ui_story_1020_10200602_90_dialog_content = "<color=#e8d9bb>Dentang-</color>",
  ui_story_1020_10200602_91_dialog_content = "(Eclipsian) ...",
  ui_story_1020_10200602_92_dialog_content = "(Eclipsian) A-Aku gemetar di hadapanmu! Aku tidak akan pernah berani melawan keinginanmu!",
  ui_story_1020_10200602_93_dialog_content = "(Eclipsian) Izinkan saya untuk menebus kesalahan saya...",
  ui_story_1020_10200602_94_dialog_content = "(Eclipsian) Misi yang pernah aku gagal selesaikan akan aku tuntaskan, meski dengan harga nyawa ku sendiri.",
  ui_story_1020_10200701_1_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_1020_10200701_2_dialog_content = "Dia sudah mengambil inti Guardian One, Ulysses. Apa lagi yang dia inginkan?",
  ui_story_1020_10200701_3_dialog_content = "Tidakkah kau merasa takut sama sekali dengan Undercity yang berada di ambang kehancuran ini, Iron Mask?",
  ui_story_1020_10200701_4_dialog_content = "Kamu merencanakan semua ini... Apakah kamu menyerahkan darah hidup Illumina ke Eclipse begitu saja hanya untuk mendapatkan lebih banyak aset penelitian dan mewujudkan mimpimu?",
  ui_story_1020_10200701_5_dialog_content = "Saya juga pernah percaya bahwa Illumina tidak akan ada hari ini tanpa Insinyur.",
  ui_story_1020_10200701_6_dialog_content = "Kemudian saya menyadari bahwa inti dari Guardian One bukanlah darah kehidupan Illumina.",
  ui_story_1020_10200701_7_dialog_content = "Aku!",
  ui_story_1020_10200701_8_dialog_content = "Bagaimana sistem pertahanan Gannon bisa berubah menjadi saringan hanya karena hilangnya inti?",
  ui_story_1020_10200701_9_dialog_content = "Biarkan aku ceritakan tentang rencana si Insinyur...",
  ui_story_1020_10200701_10_dialog_content = "Dia ingin menyatukan dan membakar, menentang ketidakberartian Aurorian dengan kehebatannya...",
  ui_story_1020_10200701_11_dialog_content = "Tapi aku tidak ingin menunggu ajal di kota bawah tanah yang gelap ini seperti kamu! Aku akan menantangnya!",
  ui_story_1020_10200701_12_dialog_content = "Kegilaan... Ini gila!",
  ui_story_1020_10200701_13_dialog_content = "Apakah kamu tahu bagaimana dia merencanakan untuk mencapai itu?",
  ui_story_1020_10200701_14_dialog_content = "Dia membangun semua ini, masuk ke dalam keheningan, dan menyerahkan tugas memulihkan inti dan menciptakan Eclipsite kepada Wraith yang bodoh.",
  ui_story_1020_10200701_15_dialog_content = "Tidak aktif selama beberapa ratus tahun, dia telah terbangun.",
  ui_story_1020_10200701_16_dialog_content = "Tapi dunia telah berubah. Dia bukan lagi Insinyur yang pernah saya pelajari dalam berkas-berkas itu.",
  ui_story_1020_10200701_17_dialog_content = "Apa pun yang bisa dia lakukan, kemungkinan besar aku juga bisa mencapainya.",
  ui_story_1020_10200701_18_dialog_content = "Tutup mulutmu yang busuk!",
  ui_story_1020_10200701_19_dialog_content = "Siapa saja di sini bisa membunuhmu dengan sekali lambaian tangan. Lebih baik kamu—",
  ui_story_1020_10200701_20_dialog_content = "Apa yang bisa kamu lakukan?",
  ui_story_1020_10200701_21_dialog_content = "...",
  ui_story_1020_10200701_22_dialog_content = "Heheh... Aku sudah menyiapkan semua yang dibutuhkan di gudangku.",
  ui_story_1020_10200701_23_dialog_content = "Berhenti!",
  ui_story_1020_10200701_24_dialog_content = "... Apakah kamu mencoba untuk menghentikanku?",
  ui_story_1020_10200701_25_dialog_content = "Kalian tak boleh ke mana-mana.",
  ui_story_1020_10200701_26_dialog_content = "... Tidak ada satupun dari kalian yang percaya padaku, tapi hanya aku sekarang yang bisa—",
  ui_story_1020_10200701_27_dialog_content = "Ambil langkah lain saja!",
  ui_story_1020_10200701_28_dialog_content = "Singkirkan senjatamu.",
  ui_story_1020_10200701_29_dialog_content = "...",
  ui_story_1020_10200701_30_dialog_content = "Waktu kita berdua, Topeng Besi, semakin menipis, tetapi Illumina masih memiliki jalan panjang yang harus ditempuh, begitu juga dengan Aurorian.",
  ui_story_1020_10200701_31_dialog_content = "Aku tahu hari ini akan datang, tapi aku tidak akan menyerah meskipun kalian semua menentangnya!",
  ui_story_1020_10200701_32_dialog_content = "Aku akan melawan dengan caraku sendiri.",
  ui_story_1020_10200701_33_dialog_content = "Kalau kamu tidak bisa membantu, aku akan melakukannya sendiri...",
  ui_story_1020_10200701_34_dialog_content = "Berani melihatnya?",
  ui_story_1020_10200701_35_dialog_content = "...",
  ui_story_1020_10200701_36_dialog_content = "<color=#e8d9bb>Bip—</color>",
  ui_story_1020_10200701_37_dialog_content = "Grand Marshal?",
  ui_story_1020_10200701_38_dialog_content = "Dia menyuruh kita membawa Ulysses ke sini.",
  ui_story_1020_10200701_39_dialog_content = "...",
  ui_story_1020_10200701_40_dialog_content = "Permainan catur tidak ada artinya tanpa bidak catur, Belisaria. Bagaimana kamu bisa membiarkan dirimu menjadi orang yang membuat langkah dalam hal itu?",
  ui_story_1020_10200701_41_dialog_content = "Aku percaya apapun yang terjadi, Reinhardt akan menjaga Gannon tetap utuh. Tapi, apakah kamu juga mampu melakukan hal yang sama?",
  ui_story_1020_10200701_42_dialog_content = "...",
  ui_story_1020_10200701_43_dialog_content = "Davidar, hubungi Barrett.",
  ui_story_1020_10200701_44_dialog_content = "Dr. Barrett sudah lama menunggumu.",
  ui_story_1020_10200701_45_dialog_content = "Apa keputusannya?",
  ui_story_1020_10200701_46_dialog_content = "Mulai <color=#FFB400>Protokol Darurat</color>.",
  ui_story_1020_10200701_47_dialog_content = "Buka kemasan peralatan asli, ubah rute yang telah ditetapkan, buka poros transportasi, dan bawa warga sipil ke undercities cadangan.",
  ui_story_1020_10200701_48_dialog_content = "Kendaraan dan poros transportasi berfungsi dengan normal. Sipil dapat diangkut.",
  ui_story_1020_10200701_49_dialog_content = "Tapi saya meminta pasukan yang cukup untuk menjamin transportasi yang aman di poros dari Committee.",
  ui_story_1020_10200701_50_dialog_content = "Lakukan saja. Komite akan membuka jalan untukmu.",
  ui_story_1020_10200701_51_dialog_content = "Begitulah yang saya suka.",
  ui_story_1020_10200701_52_dialog_content = "Kalian berdua bawa Ulysses ke gudang.",
  ui_story_1020_10200701_53_dialog_content = "Tunggu, kendaraan dan terowongan transportasi... Apa maksudmu?",
  ui_story_1020_10200701_54_dialog_content = "Pesawat yang dikembangkan oleh Illumina dan jaringan rel bawah tanah yang dirancang khusus untuk mereka.",
  ui_story_1020_10200701_55_dialog_content = "Pesawat?",
  ui_story_1020_10200701_56_dialog_content = "Kamu pikir Illumina hanya memiliki kereta, pembawa, dan terowongan yang menghancurkan tanah?",
  ui_story_1020_10200701_57_dialog_content = "Lalu apa maksud dari peralatan asli dan rute yang telah ditetapkan sebelumnya?",
  ui_story_1020_10200701_58_dialog_content = "Tidak masalah bagiku memberitahumu—pesawat-pesawat ini ditujukan untuk kota terapung itu, dan rute yang telah ditetapkan langsung menuju Lumopolis dari sini.",
  ui_story_1020_10200701_59_dialog_content = "Apakah pesawat ini dipersenjatai untuk menyerang Lumopolis?",
  ui_story_1020_10200701_60_dialog_content = "Anda memerlukan senjata yang berbeda untuk melawan lawan yang berbeda. Dan ketika Anda memutuskan untuk mencapai permukaan, Anda harus melakukan apa pun yang diperlukan.",
  ui_story_1020_10200701_61_dialog_content = "...",
  ui_story_1020_10200701_62_dialog_content = "Saya tidak mengantisipasi ini menjadi waktu untuk memulai protokol.",
  ui_story_1020_10200701_63_dialog_content = "Meskipun kamu tidak mengatakannya, setidaknya kita memiliki minat yang sama dalam hal ini.",
  ui_story_1020_10200701_64_dialog_content = "Bawa Ulysses ke gudangnya. Dia adalah sandera Anda sekarang.",
  ui_story_1020_10200701_65_dialog_content = "...",
  ui_story_1020_10200701_66_dialog_content = "Heheh. Aku lihat kau bukan lagi pemimpin sinis seperti dulu.",
  ui_story_1020_10200701_67_dialog_content = "Kita akan bertemu lagi, kan?",
  ui_story_1020_10200701_68_dialog_content = "Ada waktu untuk bermain-main.",
  ui_story_1020_10200701_69_dialog_content = "Tapi Anda harus serius ketika situasinya sulit.",
  ui_story_1020_10200701_70_dialog_content = "Jika kamu bisa mengurus itu, saya rasa kita tidak perlu bertemu lagi.",
  ui_story_1020_10200701_71_dialog_content = "Tidak ada yang terjadi di Lumopolis bahkan setelah poros transportasi dibuka.",
  ui_story_1020_10200701_72_dialog_content = "Setelah menjaga profil rendah selama bertahun-tahun, akan sangat disayangkan jika tidak memanfaatkan kesempatan ini untuk menyerang kota yang melayang.",
  ui_story_1020_10200701_73_dialog_content = "Kembali ke tugas Anda. Kami masih memiliki banyak hal yang menunggu untuk dilakukan.",
  ui_story_1020_10200701_74_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_1020_10200701_75_dialog_content = "Axelia, Yingel, apa yang harus kita lakukan sekarang?",
  ui_story_1020_10200701_76_dialog_content = "Apa yang selalu kita lakukan sebelumnya. Grand Marshal dan yang lainnya pergi ke gudang, jadi kita harus melindungi mereka.",
  ui_story_1020_10200701_77_dialog_content = "Sebagai mesin perang, apakah kalian selalu tahu apa yang harus dilakukan setiap waktu?",
  ui_story_1020_10200701_78_dialog_content = "Sudah jelas bagiku sejak aku cukup tua untuk berpikir.",
  ui_story_1020_10200701_79_dialog_content = "Aku baru tahu itu baru-baru ini. Kamu juga akan tahu, Sean.",
  ui_story_1020_10200701_80_dialog_content = "Mudah saja kau mengatakannya. Kalian berdua—",
  ui_story_1020_10200701_81_dialog_content = "Aduh!",
  ui_story_1020_10200701_82_dialog_content = "Yingel! Kenapa kamu mencubitku? Aku berdarah...",
  ui_story_1020_10200701_83_dialog_content = "Bukankah mesin perang juga Aurorian yang berdarah dan daging?",
  ui_story_1020_10200701_84_dialog_content = "Lupakan apa yang terjadi di pertemuan itu. Tidak peduli apa, Grand Marshal tidak akan pernah meremehkan keberadaan atau tujuanmu.",
  ui_story_1020_10200701_85_dialog_content = "Dia dan Grand Marshal Wrath sama-sama menjadi korban dari proyek tersebut, tetapi mereka masih tetap menjalankan tugas mereka.",
  ui_story_1020_10200701_86_dialog_content = "Mungkin aneh mengatakannya, tapi dengan Grand Marshal seperti mereka, saya sama sekali tidak merasa takut.",
  ui_story_1020_10200701_87_dialog_content = "...",
  ui_story_1020_10200701_88_dialog_content = "Saya juga tidak.",
  ui_story_1020_10200701_89_dialog_content = "Kamu...",
  ui_story_1020_10200701_90_dialog_content = "Ayo, mari pergi! Lari lebih cepat, Sean!",
  ui_story_1020_10200701_91_dialog_content = "... Oke!",
  ui_story_1020_10200701_92_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_1020_10200801_1_dialog_content = "Getarannya... Sudah berhenti.",
  ui_story_1020_10200801_2_dialog_content = "Apakah kita berhasil dalam membangun inti baru?",
  ui_story_1020_10200801_3_dialog_content = "Tidak... Kecepatan pemrosesan lebih lambat dari yang kita perkirakan, dan membutuhkan waktu yang terlalu lama untuk menyelesaikan sebanyak ini.",
  ui_story_1020_10200801_4_dialog_content = "Tapi beri aku sedikit lebih banyak waktu. Aku tahu aku bisa melakukannya!",
  ui_story_1020_10200801_5_dialog_content = "Hiks!",
  ui_story_1020_10200801_6_dialog_content = "Berhenti buang-buang waktu...",
  ui_story_1020_10200801_7_dialog_content = "Diamlah, Ulysses!",
  ui_story_1020_10200801_8_dialog_content = "Anda disini.",
  ui_story_1020_10200801_9_dialog_content = "Ini juga ide dari Belisaria. Dia memerintahkan orang-orang Gannon untuk pindah.",
  ui_story_1020_10200801_10_dialog_content = "Aku tidak percaya ini... Dr. Algol, bagaimana rencanamu untuk menangani Ulysses?",
  ui_story_1020_10200801_11_dialog_content = "Beritahu saya, Ulysses, apakah kamu membuat semua Eclipsite ini sebagai bagian dari kesepakatan dengan Engineer?",
  ui_story_1020_10200801_12_dialog_content = "Betapa naifnya. Tapi sepertinya kamu telah belajar sesuatu selama bertahun-tahun untuk masuk ke dalam sistem dan menjaga Gannon tetap stabil.",
  ui_story_1020_10200801_13_dialog_content = "Namun, Anda terlalu pintar sendiri ketika mencoba mengakses data pertahanan Guardian dan mempertahankan serangannya pada saat yang sama.",
  ui_story_1020_10200801_14_dialog_content = "Apa yang Anda maksudkan?",
  ui_story_1020_10200801_15_dialog_content = "Pelanggaran di Illumina tidak bisa diperbaiki satu per satu. Sangat mudah untuk membongkar pertahanannya.",
  ui_story_1020_10200801_16_dialog_content = "Tapi aku bisa saja menyuruhnya untuk berhenti.",
  ui_story_1020_10200801_17_dialog_content = "Tunjukkan caranya kepada saya.",
  ui_story_1020_10200801_18_dialog_content = "Aku tidak bisa melakukan itu. Aku memang bilang Caelestite bisa, tapi tidak ada satupun dari kalian yang percaya.",
  ui_story_1020_10200801_19_dialog_content = "Aku?",
  ui_story_1020_10200801_20_dialog_content = "Jangan libatkan dia dalam ini. Katakan saja pada kami bagaimana cara menghentikan Engineer.",
  ui_story_1020_10200801_21_dialog_content = "Berhenti? Saya tidak ingin menghentikannya. Saya hanya di sini untuk melihat apakah kamu merusak bayi-bayi saya.",
  ui_story_1020_10200801_22_dialog_content = "Berani kau ingkari janjimu!",
  ui_story_1020_10200801_23_dialog_content = "Seluruh hal ini sejak awal tidak ada hubungannya dengan kalian.",
  ui_story_1020_10200801_24_dialog_content = "<color=#e8d9bb>Berdengung—Berdengung—</color>",
  ui_story_1020_10200801_25_dialog_content = "Jangan lagi...",
  ui_story_1020_10200801_26_dialog_content = "... Buu, buu...",
  ui_story_1020_10200801_27_dialog_content = "\"Hadiah\"?",
  ui_story_1020_10200801_28_dialog_content = "... Apa artinya itu?",
  ui_story_1020_10200801_29_dialog_content = "Saya tidak akan menyalahkan Anda atas eksperimen yang belum selesai yang Anda hancurkan.",
  ui_story_1020_10200801_30_dialog_content = "Tetapi saya menyiapkan sesuatu yang ekstra untuknya.",
  ui_story_1020_10200801_31_dialog_content = "Coba saya lihat, seharusnya ada di sekitar sini...",
  ui_story_1020_10200801_32_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_1020_10200801_33_dialog_content = "Aduh!",
  ui_story_1020_10200801_34_dialog_content = "Peganglah aku!",
  ui_story_1020_10200801_35_dialog_content = "Apa yang telah kamu lakukan, Ulysses?",
  ui_story_1020_10200801_36_dialog_content = "Ini gempa yang lebih besar dari yang terakhir!",
  ui_story_1020_10200801_37_dialog_content = "Ini bukan hanya bergetar! Ini bergerak!",
  ui_story_1020_10200801_38_dialog_content = "Jangan sampai kehilangan pijakanmu—",
  ui_story_1020_10200801_39_dialog_content = "Hahahahaha! Lihatlah!",
  ui_story_1020_10200801_40_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_1020_10200801_41_dialog_content = "Para <color=#FFB400>super-prajurit</color>, hasil fusi dari Aurorian dan Eclipsite, masing-masing mampu melawan seratus musuh sekaligus...",
  ui_story_1020_10200801_42_dialog_content = "Mereka telah melampaui apa pun yang kamu buat sejak lama!",
  ui_story_1020_10200801_43_dialog_content = "Seluruh area bawah tanah kebanjiran...",
  ui_story_1020_10200801_44_dialog_content = "Ada berapa banyak?",
  ui_story_1020_10200801_45_dialog_content = "... Mereka berada di bawah tanah tempat kita berdiri! Tidak heran kita tidak bisa menemukan mereka!",
  ui_story_1020_10200801_46_dialog_content = "Beberapa ratus menurut perkiraanku... Tidak, lebih banyak.",
  ui_story_1020_10200801_47_dialog_content = "Mereka memiliki kabel yang keluar dari setiap pori seolah-olah mereka sedang diberi daya...",
  ui_story_1020_10200801_48_dialog_content = "Ulysses!",
  ui_story_1020_10200801_49_dialog_content = "<color=#e8d9bb>Dor—Dor—Dor—</color>",
  ui_story_1020_10200801_50_dialog_content = "Ini buruk... Para super-prajurit mulai bergerak!",
  ui_story_1020_10200801_51_dialog_content = "<color=#e8d9bb>Klang—Klang—</color>",
  ui_story_1020_10200801_52_dialog_content = "Periksa kabel-kabel di gudang... Mereka menyemburkan percikan api!",
  ui_story_1020_10200801_53_dialog_content = "Kabel-kabel yang melekat pada sekelilingnya ternyata ada di bawah gudang sepanjang waktu!",
  ui_story_1020_10200801_54_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10200801_55_dialog_content = "Jadi beginilah cara dia mengendalikan pasukan super. Dengan ini, dia bisa memberi mereka perintah melalui komputer...",
  ui_story_1020_10200801_56_dialog_content = "... Sekarang aku paham! Bool!",
  ui_story_1020_10200801_57_dialog_content = "Hiks!",
  ui_story_1020_10200801_58_dialog_content = "Jadi, apa kau menyukainya?",
  ui_story_1020_10200801_59_dialog_content = "Eclipsites yang menyerang Astra sepuluh, atau bahkan dua puluh tahun lalu tidak bisa berharap untuk menyaingi mereka!",
  ui_story_1020_10200801_60_dialog_content = "Apa?",
  ui_story_1020_10200801_61_dialog_content = "Hahaha!",
  ui_story_1020_10200801_62_dialog_content = "<color=#e8d9bb>Berdengung—Berdengung—</color>",
  ui_story_1020_10200801_63_dialog_content = "(Bagaimana mungkin Insinyur bisa mendengar suara Ulysses?)",
  ui_story_1020_10200801_64_dialog_content = "(Apakah ini prototipe? Atau apakah mereka memiliki cara komunikasi lainnya?)",
  ui_story_1020_10200801_65_dialog_content = "... Buu, buu...",
  ui_story_1020_10200801_66_dialog_content = "\"Itu bukan\"",
  ui_story_1020_10200801_67_dialog_content = "... Buu, buu...",
  ui_story_1020_10200801_68_dialog_content = "\"Layak disebutkan\"",
  ui_story_1020_10200801_X68_dialog_content = "(Bagaimana mungkin Insinyur bisa mendengar suara Ulysses?)",
  ui_story_1020_10200801_X69_dialog_content = "(Apakah ini prototipe? Atau apakah mereka memiliki cara komunikasi lainnya?)",
  ui_story_1020_10200801_69_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_1020_10200801_70_dialog_content = "Para super-prajurit sudah berdiri!",
  ui_story_1020_10200801_X70_dialog_content = "Bagaimana menurutmu... Haha...",
  ui_story_1020_10200801_71_dialog_content = "Hiiro, tundukkan Ulysses! Semuanya yang lain, mundur!",
  ui_story_1020_10200801_72_dialog_content = "Baik!",
  ui_story_1020_10200801_73_dialog_content = "...",
  ui_story_1020_10200801_74_dialog_content = "Dr. Algol!",
  ui_story_1020_10200801_75_dialog_content = "... Illumina akan selesai jika kita membiarkan mesin ini sendirian!",
  ui_story_1020_10200801_76_dialog_content = "Bagaimana menurutmu... Haha...",
  ui_story_1020_10200801_77_dialog_content = "<color=#e8d9bb>Bip — Bip — Bip —</color>",
  ui_story_1020_10200801_78_dialog_content = "Beritahu kami bagaimana cara mematikan gudang, Ulysses!",
  ui_story_1020_10200801_79_dialog_content = "Jawab aku!",
  ui_story_1020_10200801_80_dialog_content = "Ini tidak ada hubungannya denganmu. Mereka bukan musuhmu! Kamu bisa pergi saja...",
  ui_story_1020_10200801_81_dialog_content = "Cukup omong kosongmu!",
  ui_story_1020_10200801_82_dialog_content = "Bool, apakah kamu sudah menemukan jalan masuk lain? Kamu perlu cepat!",
  ui_story_1020_10200801_83_dialog_content = "Huu, huu, huu!",
  ui_story_1020_10200801_X83_dialog_content = "Ayo, sedikit lebih cepat!",
  ui_story_1020_10200801_84_dialog_content = "<color=#e8d9bb>Dor—Dor—Dor—</color>",
  ui_story_1020_10200801_85_dialog_content = "Roaaarrrr—",
  ui_story_1020_10200801_86_dialog_content = "Dr. Algol!",
  ui_story_1020_10200801_87_dialog_content = "...",
  ui_story_1020_10200801_88_dialog_content = "Dr. Algol masih menolak untuk pergi...",
  ui_story_1020_10200801_89_dialog_content = "Biarkan saya menggunakan kekuatan saya untuk menyelamatkanmu, Algol!",
  ui_story_1020_10200801_90_dialog_content = "Tidak! Kalian semua, keluar dari sini!",
  ui_story_1020_10200801_91_dialog_content = "Aku sudah menemukan cara untuk mengendalikan prajurit super...",
  ui_story_1020_10200801_92_dialog_content = "Huu, huu, huu!",
  ui_story_1020_10200801_93_dialog_content = "Bagus, database sudah diperbarui! Saya hanya perlu mengaksesnya sekarang...",
  ui_story_1020_10200801_94_dialog_content = "Ayo... Sedikit lebih cepat!",
  ui_story_1020_10200801_95_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10200801_96_dialog_content = "Menghindar, Algol!",
  ui_story_1020_10200801_97_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1020_10200801_98_dialog_content = "Bu?",
  ui_story_1020_10200801_99_dialog_content = "Roaaarrrr—",
  ui_story_1020_10200801_100_dialog_content = "Apa yang terjadi? Para prajurit super tidak menyerang Algol!",
  ui_story_1020_10200801_101_dialog_content = "...",
  ui_story_1020_10200801_102_dialog_content = "<color=#e8d9bb>Dor! Dor! Dor!</color>",
  ui_story_1020_10200801_103_dialog_content = "Mereka menyerang... prototipe?",
  ui_story_1020_10200801_104_dialog_content = "Apakah ini alasan Ulysses menciptakan prajurit-prajurit super tersebut?",
  ui_story_1020_10200801_105_dialog_content = "Hahahahahaha, kamu suka itu, 'kan?",
  ui_story_1020_10200801_106_dialog_content = "Bagaimana rasanya? Di mana Eclipsite Anda sekarang?",
  ui_story_1020_10200801_107_dialog_content = "<color=#e8d9bb>Berdengung—Berdengung—</color>",
  ui_story_1020_10200801_108_dialog_content = "... Buu, buu...",
  ui_story_1020_10200801_109_dialog_content = "\"Terima kasih\"",
  ui_story_1020_10200801_110_dialog_content = "... Terima kasih?",
  ui_story_1020_10200801_111_dialog_content = "...",
  ui_story_1020_10200801_112_dialog_content = "Aum...",
  ui_story_1020_10200801_113_dialog_content = "Para super-prajurit... Mereka berhenti bergerak.",
  ui_story_1020_10200801_114_dialog_content = "Apa yang sedang mereka cari?",
  ui_story_1020_10200801_115_dialog_content = "<color=#e8d9bb>Bzz—Bzz—</color>",
  ui_story_1020_10200801_116_dialog_content = "Kabel-kabelnya kacau lagi, Dr. Algol!",
  ui_story_1020_10200801_117_dialog_content = "Jangan khawatir. Aku akan membatalkan pesanan mereka...",
  ui_story_1020_10200801_118_dialog_content = "<color=#e8d9bb>Bip — Bip — Bip —</color>",
  ui_story_1020_10200801_119_dialog_content = "Apa kamu bercanda? Argh, aku benci benda ini!",
  ui_story_1020_10200801_120_dialog_content = "Sedang apa kau?",
  ui_story_1020_10200801_121_dialog_content = "<color=#e8d9bb>Bzz—Bzz—</color>",
  ui_story_1020_10200801_122_dialog_content = "Lihat apa yang ada di belakang super-prajurit!",
  ui_story_1020_10200801_123_dialog_content = "Grooooaaaar!",
  ui_story_1020_10200801_124_dialog_content = "Dia mulai menyerang!",
  ui_story_1020_10200801_125_dialog_content = "Apa yang kamu lakukan pada bayi-bayi saya?",
  ui_story_1020_10200801_126_dialog_content = "Grooooaaaar!",
  ui_story_1020_10200801_127_dialog_content = "Hati-hati, Algol!",
  ui_story_1020_10200901_1_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_1020_10200901_2_dialog_content = "Komandan Barton, kami sudah mencoba sebaik mungkin!",
  ui_story_1020_10200901_3_dialog_content = "Tapi kawan-kawan kita di <color=#FFB400>Gerbang 10</color> masih terlibat dalam pertempuran dan sangat membutuhkan bantuan!",
  ui_story_1020_10200901_4_dialog_content = "Jadi, semua elit kalian hanya akan membiarkan orang lain mengambil kesempatan ini untuk bertarung?",
  ui_story_1020_10200901_5_dialog_content = "Tidak, Komandan! Gerbangnya bergetar terlalu keras untuk tubuh kita tahan...",
  ui_story_1020_10200901_6_dialog_content = "Gerbang 10... Bukankah itu menuju halaman servis?",
  ui_story_1020_10200901_7_dialog_content = "Apakah anak itu mencoba meraih kejayaan dengan membuat Soroz menopang gerbang itu?",
  ui_story_1020_10200901_8_dialog_content = "Bisakah Colossus mendukung gerbang-gerbang itu?",
  ui_story_1020_10200901_9_dialog_content = "Mengapa tidak bisa saat berhasil membesarkan Caelestite?",
  ui_story_1020_10200901_10_dialog_content = "Ikuti aku! Tak ada yang bisa bilang tubuh ini lebih rendah dari tumpukan sampah!",
  ui_story_1020_10200901_11_dialog_content = "Komandan! Di <color=#FFB400>Gerbang 9</color> juga berguncang liar. Rasanya seperti ada arus udara kuat yang menerjang ke lantai atas dari bawah tanah!",
  ui_story_1020_10200901_12_dialog_content = "Bawah tanah? Periksa semua ventilasi sekarang! Setiap sudut dan setiap inci!",
  ui_story_1020_10200901_13_dialog_content = "Kami sudah memeriksa semuanya! Tidak ada jejak Eclipsite yang ditemukan!",
  ui_story_1020_10200901_14_dialog_content = "Apa yang terjadi di sini?",
  ui_story_1020_10200901_15_dialog_content = "<color=#e8d9bb>Sekitar Gerbang 9</color>",
  ui_story_1020_10200901_16_dialog_content = "Pak Polisi, tanah di area ini bergetar dengan liar. Silakan evakuasi ke tempat yang aman!",
  ui_story_1020_10200901_17_dialog_content = "Jangan pedulikan saya. Terowongan transportasi di bawah ini sedang berfungsi, dan saya datang untuk mengukur tingkat getaran di sini.",
  ui_story_1020_10200901_18_dialog_content = "Terowongan transportasi...",
  ui_story_1020_10200901_19_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_1020_10200901_20_dialog_content = "Dapat diterima, hampir tidak merugikan gerbang.",
  ui_story_1020_10200901_21_dialog_content = "...",
  ui_story_1020_10200901_22_dialog_content = "<color=#e8d9bb>Dawn Akademi Lumopolis</color>",
  ui_story_1020_10200901_23_dialog_content = "Demi White Night! Sudahkah kamu mendengar? Sesuatu yang aneh terjadi pada <color=#FFB400>Batu White Night</color> di akademi, dan Lumina telah berfluktuasi secara liar untuk waktu yang lama.",
  ui_story_1020_10200901_24_dialog_content = "Ayah dan para biarawati semua berlari ke sana tetapi tidak bisa meredakan fluktuasi meskipun telah menggunakan Luminatics dengan seluruh kekuatan mereka!",
  ui_story_1020_10200901_25_dialog_content = "Apakah ini berhubungan dengan getaran yang mengguncang Lumopolis sebelumnya?",
  ui_story_1020_10200901_26_dialog_content = "Ya, aku khawatir reruntuhan kuno telah mulai beresonansi dengan kekuatan misterius lagi.",
  ui_story_1020_10200901_27_dialog_content = "Ini terjadi sebelumnya ketika gangguan aurora meletus di Twilight di masa lalu, tetapi kali ini situasinya lebih serius.",
  ui_story_1020_10200901_28_dialog_content = "<color=#e8d9bb>Lumopolis, Pengadilan Kerajaan</color>",
  ui_story_1020_10200901_29_dialog_content = "Lihat, poros-poros itu membuka seperti mulut yang rakus di tanah. Illumina berubah menjadi serigala yang kelaparan!",
  ui_story_1020_10200901_30_dialog_content = "Serigala belum menggigit Lumopolis.",
  ui_story_1020_10200901_31_dialog_content = "Batalkan alarmnya, Kapten. Reruntuhan itu pada dasarnya aman sekarang.",
  ui_story_1020_10200901_32_dialog_content = "Baik tuan ku.",
  ui_story_1020_10200901_33_dialog_content = "Tuan Kota, batu yang mengandung Lumina di Dawn Akademi bereaksi keras terhadap getaran. Apakah menurut Anda ada kekuatan yang tidak diketahui di Lumopolis?",
  ui_story_1020_10200901_34_dialog_content = "Demi White Night di atas. Yang Mulia, Anda tidak perlu khawatir tentang ini.",
  ui_story_1020_10200901_35_dialog_content = "Meskipun hal ini belum pernah terjadi sejak Lady Saintess memasuki Kuil Lumopolis, Dewa Cahaya akan membimbing kita.",
  ui_story_1020_10200901_36_dialog_content = "Apa menurut Ayah yang menyebabkan reaksi pada Batu Malam Putih, Ayah?",
  ui_story_1020_10200901_37_dialog_content = "Ada sesuatu yang relevan telah dicatat dalam kitab. Dikatakan bahwa Lumina akan mulai berfluktuasi secara liar ketika <color=#FFB400>pewaris roh</color> baru muncul.",
  ui_story_1020_10200901_38_dialog_content = "...",
  ui_story_1020_10200901_39_dialog_content = "Kekuatan jahat yang tersembunyi di reruntuhan bawah tanah pernah mengguncang seluruh Azurite. Adalah Pewaris Roh—Santo Perempuan—yang mengusirnya.",
  ui_story_1020_10200901_40_dialog_content = "Menurut hitunganku, Sang Suci telah melindungi Azurite selama bertahun-tahun.",
  ui_story_1020_10200901_41_dialog_content = "Keburukan hanya bisa diusir, bukan dihilangkan. Lumopolis tidak murni.",
  ui_story_1020_10200901_42_dialog_content = "Apakah Lumopolis akan dalam bahaya, Ayah?",
  ui_story_1020_10200901_43_dialog_content = "Tidak.",
  ui_story_1020_10200901_44_dialog_content = "Bagaimana dengan Illumina Federation?",
  ui_story_1020_10200901_45_dialog_content = "Pertama, mereka harus menemukan keyakinan mereka sendiri.",
  ui_story_1020_10200901_46_dialog_content = "Perhatikan pesan dari Illumina, Kapten.",
  ui_story_1020_10200901_47_dialog_content = "Ya, Tuan Schwartz.",
  ui_story_1020_10200901_48_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_1020_10200901_49_dialog_content = "Bagaimana situasi saat ini, Dr. Algol?",
  ui_story_1020_10200901_50_dialog_content = "Panel kontrol sekarang menampilkan bahwa inti hampir selesai.",
  ui_story_1020_10200901_51_dialog_content = "Saya tidak percaya Insinyur belum menyerang kita... Bertahanlah, Bool!",
  ui_story_1020_10200901_52_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10200901_53_dialog_content = "Apa?",
  ui_story_1020_10200901_54_dialog_content = "<color=#e8d9bb>Berdengung—Berdengung—</color>",
  ui_story_1020_10200901_55_dialog_content = "... Buu, buu...",
  ui_story_1020_10200901_56_dialog_content = "\"Pulanglah, Caelestite\"",
  ui_story_1020_10200901_57_dialog_content = "Caelestite itu tidak akan pergi ke mana-mana!",
  ui_story_1020_10200901_58_dialog_content = "...",
  ui_story_1020_10200901_59_dialog_content = "Bukankah Engineer sedang berbicara dengan Ulysses? Bagaimana dia bisa tahu tentang PlayerName?",
  ui_story_1020_10200901_60_dialog_content = "Pulanglah, Caelestite.",
  ui_story_1020_10200901_61_dialog_content = "Saya pikir saya mendengar suaranya...",
  ui_story_1020_10200901_62_dialog_content = "Dari mana asalnya?",
  ui_story_1020_10200901_63_dialog_content = "Dari dalam kepala saya...",
  ui_story_1020_10200901_64_dialog_content = "Jadi, visi-visi yang saya lihat ternyata benar-benar dibuat oleh kekuatan psikis...",
  ui_story_1020_10200901_65_dialog_content = "Pulanglah, Caelestite.",
  ui_story_1020_10200901_66_dialog_content = "...Siapa kamu?",
  ui_story_1020_10200901_67_dialog_content = "Kalian menyebut saya Insinyur.",
  ui_story_1020_10200901_68_dialog_content = "Kamu adalah Eclipsite... Dan kamu mengendalikan prajurit super Illumina melalui mesin ini atas perintah Eclipse, bukan?",
  ui_story_1020_10200901_69_dialog_content = "Tidak.",
  ui_story_1020_10200901_70_dialog_content = "... Tapi Anda mencuri inti Guardian One, yang memungkinkan Eclipsites menyerang Kota Gannon.",
  ui_story_1020_10200901_71_dialog_content = "Itu milikku sejak awal.",
  ui_story_1020_10200901_72_dialog_content = "Seperti halnya kamu.",
  ui_story_1020_10200901_73_dialog_content = "... Aku seorang Caelestite. Aku lahir di Eraveil.",
  ui_story_1020_10200901_74_dialog_content = "Dari mana asal Caelestites?",
  ui_story_1020_10200901_75_dialog_content = "Apa yang telah kau lakukan pada rakyatku... padaku?",
  ui_story_1020_10200901_76_dialog_content = "Pulanglah, Caelestite.",
  ui_story_1020_10200901_77_dialog_content = "Lanjutkan perjuangan mulia ini bersamaku.",
  ui_story_1020_10200901_78_dialog_content = "Tujuan mulia? Caelestite tidak akan pergi ke mana-mana!",
  ui_story_1020_10200901_79_dialog_content = "Apa yang sedang kamu bicarakan, Ulysses?",
  ui_story_1020_10200901_80_dialog_content = "...",
  ui_story_1020_10200901_81_dialog_content = "Dia juga bisa terhubung dengan pikiranmu?",
  ui_story_1020_10200901_82_dialog_content = "Dia dan kamu tidak sama.",
  ui_story_1020_10200901_83_dialog_content = "Aku akan memberitahumu semua kebenaran yang sangat ingin kamu ketahui.",
  ui_story_1020_10200901_84_dialog_content = "Mengenai pertempuran Zona Gelap kuno, tingkat tempat berlabuh Colossus, rumah Caelestite...",
  ui_story_1020_10200901_85_dialog_content = "Dan rekan sebangsa yang telah kau rindukan.",
  ui_story_1020_10200901_86_dialog_content = "!",
  ui_story_1020_10200901_87_dialog_content = "<color=#e8d9bb>Bip—Bip bip—Bip bip bip—</color>",
  ui_story_1020_10200901_88_dialog_content = "Gelang Algol melaporkan ancaman.",
  ui_story_1020_10200901_89_dialog_content = "Halaman layanan Illumina...",
  ui_story_1020_10200901_90_dialog_content = "PlayerName, Colossus memutus koneksi ke terminal saya!",
  ui_story_1020_10200901_91_dialog_content = "Soroz…",
  ui_story_1020_10200901_92_dialog_content = "Apakah ini hasil kerjamu?",
  ui_story_1020_10200901_93_dialog_content = "Aku telah mengaktifkan Colossus untukmu.",
  ui_story_1020_10200901_94_dialog_content = "Tidak... Tidak!",
  ui_story_1020_10200901_95_dialog_content = "<color=#e8d9bb>Gedebuk-</color>",
  ui_story_1020_10200901_96_dialog_content = "PlayerName!",
  ui_story_1020_10200901_97_dialog_content = "Oh! Dia sudah keluar.",
  ui_story_1020_10200901_98_dialog_content = "Tetap semangat, Vivian. Saat ini sangat berbahaya di luar sana.",
  ui_story_1020_10200901_99_dialog_content = "Siap!",
  ui_story_1020_10200901_100_dialog_content = "Caelestite tidak akan pergi kemana-mana! Aku adalah targetmu...",
  ui_story_1020_10200901_101_dialog_content = "Hentikan kekacauan ini segera, Ulysses!",
  ui_story_1020_10200901_102_dialog_content = "Lepaskan aku! Biar aku yang menghadapi dia!",
  ui_story_1020_10200901_103_dialog_content = "<color=#e8d9bb>Klik, klik—</color>",
  ui_story_1020_10200901_104_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10200901_105_dialog_content = "Berhenti, Ulysses!",
  ui_story_1020_10200901_106_dialog_content = "Groar!",
  ui_story_1020_10200901_107_dialog_content = "Setelah bertahun-tahun... Aku berhasil...",
  ui_story_1020_10200901_108_dialog_content = "Apakah ini cukup?",
  ui_story_1020_10200901_109_dialog_content = "Masih ada lagi! Ribuan lagi! Prajurit super yang ribuan kali lebih kuat dari Eclipsite!",
  ui_story_1020_10200901_110_dialog_content = "<color=#e8d9bb>Berdengung—Berdengung—</color>",
  ui_story_1020_10200901_111_dialog_content = "... Buu, buu...",
  ui_story_1020_10200901_112_dialog_content = "\"Satu kali terakhir\"",
  ui_story_1020_10200901_113_dialog_content = "Oh tidak, dia akan memerintahkan para super-prajurit untuk menyerang! Kita perlu mendapatkan kontrol atas Ulysses!",
  ui_story_1020_10200901_114_dialog_content = "Serahkan Ulysses kepadaku!",
  ui_story_1020_10200901_115_dialog_content = "<color=#e8d9bb>Bip — Bip — Bip —</color>",
  ui_story_1020_10200901_116_dialog_content = "Argh! Sungguh menyakitkan harus membuat modul pertahanan lainnya juga!",
  ui_story_1020_10200901_117_dialog_content = "Groar!",
  ui_story_1020_10201001_1_dialog_content = "PlayerName!",
  ui_story_1020_10201001_2_dialog_content = "Kita masih memiliki jarak yang cukup jauh dari sini ke halaman servis. Terlalu berbahaya di luar sana!",
  ui_story_1020_10201001_3_dialog_content = "... Aku tidak akan membiarkan Soroz melarikan diri!",
  ui_story_1020_10201001_4_dialog_content = "Bagaimana bisa Soroz pergi tanpa perintahmu?",
  ui_story_1020_10201001_5_dialog_content = "...",
  ui_story_1020_10201001_6_dialog_content = "Aku melihatnya...",
  ui_story_1020_10201001_7_dialog_content = "Ada apa?",
  ui_story_1020_10201001_8_dialog_content = "Aku melihat apa yang Ulysses lihat sebelumnya...",
  ui_story_1020_10201001_9_dialog_content = "Ada suara... Insinyur itu memberitahu saya dan Soroz untuk pulang...",
  ui_story_1020_10201001_10_dialog_content = "PlayerName…",
  ui_story_1020_10201001_11_dialog_content = "Tidak mudah bagi saya untuk menemukan Soroz lagi, dan kami hanya bersama selama beberapa hari...",
  ui_story_1020_10201001_12_dialog_content = "Aku bersumpah... aku bersumpah aku tidak akan membiarkan ini terjadi!",
  ui_story_1020_10201001_13_dialog_content = "Tapi apa yang bisa saya lakukan? Harus ada sesuatu...",
  ui_story_1020_10201001_14_option_content = "Tautan Telepati",
  ui_story_1020_10201001_15_dialog_content = "...",
  ui_story_1020_10201001_16_option_content = "Tautan Telepati",
  ui_story_1020_10201001_17_dialog_content = "...",
  ui_story_1020_10201001_18_dialog_content = "Apakah Soroz... sudah pergi?",
  ui_story_1020_10201001_19_dialog_content = "Saat aku keluar dari lab tadi, aku merasakan sesuatu yang tak bisa dijelaskan.",
  ui_story_1020_10201001_20_dialog_content = "Saya melihat sinar cahaya di atas struktur besar, membawa semua harapan saya bersamanya...",
  ui_story_1020_10201001_21_dialog_content = "Dan entah mengapa, saya merasa Soroz akan terbang dari sana...",
  ui_story_1020_10201001_22_dialog_content = "Aku... Aku tidak tahu kenapa aku merasa seperti itu saat itu...",
  ui_story_1020_10201001_23_dialog_content = "Setelah itu dan mimpi yang aku lihat, seharusnya aku bisa mengetahuinya lebih awal...",
  ui_story_1020_10201001_24_option_content = "Tautan Telepati",
  ui_story_1020_10201001_25_dialog_content = "...",
  ui_story_1020_10201001_26_option_content = "Tautan Telepati",
  ui_story_1020_10201001_27_dialog_content = "...",
  ui_story_1020_10201001_28_option_content = "Tautan Telepati",
  ui_story_1020_10201001_29_dialog_content = "...",
  ui_story_1020_10201001_30_dialog_content = "Aduh!",
  ui_story_1020_10201001_31_dialog_content = "Berhenti sekarang, PlayerName!",
  ui_story_1020_10201001_32_dialog_content = "Kamu telah menggunakan terlalu banyak kekuatan psikismu hari ini, dan kamu tampak sakit!",
  ui_story_1020_10201001_33_dialog_content = "Aku sudah kehilangan kontak dengan Vice... Aku tidak tahu apa yang akan aku lakukan jika aku kehilangan Soroz juga...",
  ui_story_1020_10201001_34_dialog_content = "... Kemana Soroz pergi? Apa yang diinginkan Engineer dengannya?",
  ui_story_1020_10201001_35_dialog_content = "Kamu selalu bisa bertanya kepada saya pertanyaan-pertanyaan itu—",
  ui_story_1020_10201001_36_dialog_content = "Hunus!",
  ui_story_1020_10201001_37_dialog_content = "Vivian!",
  ui_story_1020_10201001_38_dialog_content = "... Figerald?",
  ui_story_1020_10201001_39_dialog_content = "Terlalu lemah—tidak—terlalu lembut, aku rasa...",
  ui_story_1020_10201001_40_dialog_content = "Begitu lembut sampai-sampai aku kasihan padamu!",
  ui_story_1020_10201001_41_dialog_content = "Heheh, tidak ada yang seperti rasa putus asa ketika seseorang kehilangan sesuatu yang benar-benar mereka hargai.",
  ui_story_1020_10201001_42_dialog_content = "... Kamu tahu Soroz akan terbang pergi?",
  ui_story_1020_10201001_43_dialog_content = "Nah, kenapa kamu tidak bertanya apa yang sudah saya lakukan pada Soroz?",
  ui_story_1020_10201001_44_dialog_content = "Kau!",
  ui_story_1020_10201001_45_dialog_content = "Tunggu, PlayerName, ada yang tidak beres dengannya.",
  ui_story_1020_10201001_46_dialog_content = "Dia ter immobilisasi dalam sel tetapi masih berhasil melarikan diri...",
  ui_story_1020_10201001_47_dialog_content = "Masih tidak percaya? Kekuatannya membuat semua ini menjadi mungkin.",
  ui_story_1020_10201001_48_dialog_content = "Rantai itu memang mengikatku. Tapi aku mengajari sampah-sampah yang memenjarakanku untuk menghargai keindahan putus asa di saat-saat terakhir mereka.",
  ui_story_1020_10201001_49_dialog_content = "Sayangnya, rasa penderitaan mereka bahkan tidak bisa dibandingkan dengan rasa penderitaan Caelestite.",
  ui_story_1020_10201001_50_dialog_content = "Hahaha, sekarang pilihlah, Caelestite! Akankah kamu mati sia-sia seperti rekan-rekanmu yang tak berguna?",
  ui_story_1020_10201001_51_dialog_content = "Ataukah kamu akan menjadi hadiahku untuk penguasa tertinggi dan menyaksikan kemuliaannya di sisiku?",
  ui_story_1020_10201001_52_dialog_content = "Seorang Caelestite tidak akan mati sia-sia! Sekarang di mana Insinyurnya?",
  ui_story_1020_10201001_53_dialog_content = "Hahaha! Lalu tampaknya kamu telah memilih yang terakhir!",
  ui_story_1020_10201001_54_dialog_content = "Dalam hal itu, tidak perlu menyayangi orang bodoh di sampingmu.",
  ui_story_1020_10201001_55_dialog_content = "Jangan berani menyakiti PlayerName!",
  ui_story_1020_10201001_56_dialog_content = "Jadi kau ingin merasakan kekuatan Darkflow-ku? Kau harus tahu, itu lahir dari darah Aurorian yang gugur.",
  ui_story_1020_10201001_57_dialog_content = "Berlindunglah di belakangku, PlayerName!",
  ui_story_1020_10201001_58_dialog_content = "Perlawananmu tidak lebih dari hal yang konyol...",
  ui_story_1020_10201001_59_dialog_content = "Bersyukurlah bahwa kau masih bisa merasakan rasa sakit. Saat masa kejayaannya tiba, dia akan membebaskanmu dari penderitaanmu.",
  ui_story_1020_10201001_60_dialog_content = "Raven—saya tawarkan darah seorang Caelestite untukmu!",
  ui_story_1020_10201001_61_dialog_content = "Aku tidak akan membiarkanmu menyakiti PlayerName, Eclipsite!",
  ui_story_1020_10201001_62_dialog_content = "Untung aku berhasil tepat waktu!",
  ui_story_1020_10201001_63_dialog_content = "PlayerName! Petugas Vivian! Apakah salah satu dari kalian terluka?",
  ui_story_1020_10201001_64_dialog_content = "Sean? Kabur dari sini! Darkflow itu sangat berbahaya!",
  ui_story_1020_10201001_65_dialog_content = "Aku tahu, tapi aku harus melindungimu, PlayerName!",
  ui_story_1020_10201001_66_dialog_content = "Nah? Aku tidak mengecewakanmu, bukan?",
  ui_story_1020_10201001_67_dialog_content = "Sama sekali tidak! Bagaimana kamu bisa bertahan dari serangannya, Sean?",
  ui_story_1020_10201001_68_dialog_content = "Ha! Itu karena saya sama baiknya sebagai petarung seperti Yingel atau Axelia!",
  ui_story_1020_10201001_69_dialog_content = "Saya kebetulan juga adalah seorang Aurorian berdaging dan berdarah.",
  ui_story_1020_10201001_70_dialog_content = "Chief of Staff, PlayerName, serahkan Eclipsite ini padaku!",
  ui_story_1020_10201001_71_dialog_content = "Hati-hati, Sean! Dia sangat licik. Kami akan melindungimu dengan menghabisi Eclipsites lainnya di belakangmu!",
  ui_story_1020_10201001_72_dialog_content = "Baik!",
  ui_story_1020_10201001_73_dialog_content = "Ah... Sangat lembut! Sangat segar!",
  ui_story_1020_10201101_1_dialog_content = "Kalian cacing... Apakah kalian benar-benar berpikir bisa menghentikanku?",
  ui_story_1020_10201101_2_dialog_content = "Saya harus menyelesaikan misi saya kali ini, jika tidak—",
  ui_story_1020_10201101_3_dialog_content = "Kamu di sana, dengan telinga panjang dan berbulu... Bagaimana caranya kamu bisa bertahan dari serangan Darkflow-ku tanpa luka sedikit pun?",
  ui_story_1020_10201101_4_dialog_content = "Dan? Aku tidak akan membiarkanmu menyakiti teman-temanku!",
  ui_story_1020_10201101_5_dialog_content = "Heh, ekspresi wajahmu menjelaskan semuanya... Itulah sebabnya kamu masih hidup setelah spesies buas lainnya musnah.",
  ui_story_1020_10201101_6_dialog_content = "Apa katamu?",
  ui_story_1020_10201101_7_dialog_content = "Saya, Figerald, memiliki kehormatan khusus untuk berpartisipasi dalam pemusnahan massal leluhur Anda. Itu adalah kontribusi paling mulia saya kepada penguasa tertinggi kita.",
  ui_story_1020_10201101_8_dialog_content = "Namun, tampaknya dengan berdamai dengan Aurorian, jenismu yang malas dan pengkhianat telah menemukan cara untuk bertahan hidup.",
  ui_story_1020_10201101_9_dialog_content = "Dalam satu sisi, kau ini tak ada bedanya dengan kecoa. Bukankah kau setuju?",
  ui_story_1020_10201101_10_dialog_content = "Diam! Aku tak akan membiarkanmu berbicara tentang Sean dengan cara itu!",
  ui_story_1020_10201101_11_dialog_content = "Marah? Kamu ingin membunuhku sekarang, kan?",
  ui_story_1020_10201101_12_dialog_content = "Tapi kamu masih ingin tahu kemana Soroz pergi, kan? Bukan hanya Soroz, tapi juga gadis Illuminan yang tidak berguna itu.",
  ui_story_1020_10201101_13_dialog_content = "Jangan khawatir, saya yakin bahwa Anemone telah memberinya kematian yang mengerikan dengan cara yang luar biasa.",
  ui_story_1020_10201101_14_dialog_content = "Vice... Dia bertemu dengan Anemone? Beritahu saya apa yang terjadi padanya!",
  ui_story_1020_10201101_15_dialog_content = "Oh? Mari kita lihat apakah aku bisa mengingat...",
  ui_story_1020_10201101_16_dialog_content = "Di mana Insinyur itu? Kemana Soroz pergi? Beritahu saya!",
  ui_story_1020_10201101_17_dialog_content = "...",
  ui_story_1020_10201101_18_dialog_content = "O penguasa yang kuat dan tertinggi, tolong jangan tinggalkan saya!",
  ui_story_1020_10201101_19_dialog_content = "...",
  ui_story_1020_10201101_20_dialog_content = "\"Master\"? Siapa yang dia ajak bicara?",
  ui_story_1020_10201101_21_dialog_content = "Insinyur pasti sedang berkomunikasi dengannya melalui kesadarannya saat ini...",
  ui_story_1020_10201101_22_dialog_content = "Ini mungkin waktu yang sempurna untuk mencari petunjuk.",
  ui_story_1020_10201101_23_dialog_content = "Kamu sedang apa, PlayerName?",
  ui_story_1020_10201101_24_option_content = "Force Boost",
  ui_story_1020_10201101_25_dialog_content = "(Argh! Rasa sakit ini tak tertahankan...)",
  ui_story_1020_10201101_26_dialog_content = "(Tapi tak ada cara lain!)",
  ui_story_1020_10201101_27_dialog_content = "(Aku perlu tahu apa yang terjadi pada Vice dan Soroz...)",
  ui_story_1020_10201101_28_dialog_content = "(Saya perlu menemukan jawabannya...)",
  ui_story_1020_10201101_29_dialog_content = "Tubuhmu telah menjadi lemah dan mengerikan.",
  ui_story_1020_10201101_30_dialog_content = "T-Tidak masalah bagiku! Selama aku membawa tanda mu, para Aurorian dan Eclipsite rendahan itu semua akan tunduk padaku.",
  ui_story_1020_10201101_31_dialog_content = "Membungkuk kepadamu? Lalu bagaimana dengan aku?",
  ui_story_1020_10201101_32_dialog_content = "A-Aku gemetar di hadapan keagunganmu, Tuan! Izinkan aku menjadi sayapmu, dan aku akan mengabdikan seluruh hidupku untukmu!",
  ui_story_1020_10201101_33_dialog_content = "Apakah kamu bersedia memakai cincin ini sebagai pengakuan atas status barumu?",
  ui_story_1020_10201101_34_dialog_content = "Sebuah cincin...",
  ui_story_1020_10201101_35_dialog_content = "Saya bersedia! Cincin ini adalah simbol anugerahmu, sebuah hadiah yang hanya bisa diterima oleh jiwa yang paling mulia! Ini memberi arti pada keberadaan saya!",
  ui_story_1020_10201101_36_dialog_content = "Saya berlutut di hadapan Anda dalam rasa terima kasih, penguasa tertinggi!",
  ui_story_1020_10201101_37_dialog_content = "Baiklah.",
  ui_story_1020_10201101_38_dialog_content = "T-Tolong berikan padaku... Arrrrrrgh!",
  ui_story_1020_10201101_39_dialog_content = "Aku... Kepalaku! Sakitnya... Aku tak tahan lagi! Penguasa tertinggi... Tolong selamatkan aku...",
  ui_story_1020_10201101_40_dialog_content = "(Ini adalah bagian dari kenangan masa lalu Figerald, dan suara barusan adalah Engineer...)",
  ui_story_1020_10201101_41_dialog_content = "(Seorang Wraith dari Eclipse secara sukarela memasang cincin yang seperti belenggu itu...)",
  ui_story_1020_10201101_42_dialog_content = "(...)",
  ui_story_1020_10201101_43_dialog_content = "(Aku tidak tahu bahwa aku bisa menggunakan kekuatanku untuk melihat jauh ke masa lalu... Apakah ini terjadi karena mimpi sang Insinyur?)",
  ui_story_1020_10201101_44_dialog_content = "(Atau karena Algol melatih saya untuk berhasil terhubung dengan Bool?)",
  ui_story_1020_10201101_45_dialog_content = "(Jika saya ingin mengetahui tentang keberadaan Vice dan Soroz, saya perlu mencari tahu kenangan terbarunya...)",
  ui_story_1020_10201101_46_option_content = "Jangkauan Telepati—",
  ui_story_1020_10201101_47_dialog_content = "(Urgh, Darkflow ini... Rasanya sama buruknya seperti saat pertama kali saya menyambung pikiran dengan Bool.)",
  ui_story_1020_10201101_48_dialog_content = "(Tapi sekarang setelah aku mengalami sesuatu seperti itu, aku rasa aku bisa mengatasinya...)",
  ui_story_1020_10201101_49_dialog_content = "(Huh? Ini Dark Zone, ya?)",
  ui_story_1020_10201101_50_dialog_content = "(Lubang ini sangat besar, dan celahnya tampaknya meluas lebih jauh lagi...)",
  ui_story_1020_10201101_51_dialog_content = "(Bisakah ini adalah reruntuhan perang kuno yang disebutkan oleh Engineer?)",
  ui_story_1020_10201101_52_dialog_content = "(Apa yang sebenarnya terjadi di sini? Bagaimana tempat ini bisa berakhir dalam keadaan yang sangat buruk?)",
  ui_story_1020_10201101_53_dialog_content = "(Aku tidak melihat tanda-tanda adanya Colossus di dekat sini...)",
  ui_story_1020_10201101_54_option_content = "Jangkauan Telepati—",
  ui_story_1020_10201101_55_dialog_content = "(Apakah itu... tumpukan sisa-sisa Colossus?)",
  ui_story_1020_10201101_56_dialog_content = "(Satu, dua, tiga...)",
  ui_story_1020_10201101_57_dialog_content = "(...)",
  ui_story_1020_10201101_58_dialog_content = "(Tempat bersandar Colossus...)",
  ui_story_1020_10201101_59_dialog_content = "(Pantai yang datar dan gersang... Sangat berbeda dengan Obelisk of Return.)",
  ui_story_1020_10201101_60_dialog_content = "(Apa yang terjadi pada mereka? Tidak ada yang tersisa dari mereka kecuali struktur yang terkikis seperti tulang naga...)",
  ui_story_1020_10201101_61_dialog_content = "(Berapa lama yang lalu ini? Aku bahkan tidak bisa merasakan tanda-tanda kehidupan yang paling samar sekalipun di sini...)",
  ui_story_1020_10201101_62_dialog_content = "(Benar, inti dari Guardian One...)",
  ui_story_1020_10201101_63_dialog_content = "(Mungkin koordinat yang saya lihat di data Soroz adalah petunjuk...)",
  ui_story_1020_10201101_64_dialog_content = "(Koordinat... Pilar yang bersinar...)",
  ui_story_1020_10201101_65_option_content = "Jangkauan Telepati—",
  ui_story_1020_10201101_66_dialog_content = "(Ini dia!)",
  ui_story_1020_10201101_67_dialog_content = "(Tidak ada kesalahan. Ini persis apa yang saya lihat di ingatan Ulysses...)",
  ui_story_1020_10201101_68_dialog_content = "(Tiang-tiang yang bersinar ini adalah inti dari Guardian One. Saya bisa melihatnya dengan jelas sekarang...)",
  ui_story_1020_10201101_69_dialog_content = "(Batu itu naik. Pasti ada sesuatu di atas sana...)",
  ui_story_1020_10201101_70_dialog_content = "Apa kamu sudah siap?",
  ui_story_1020_10201101_71_dialog_content = "Ya. <color=#FFB400>Drive Ring</color> terakhir ada di tangan.",
  ui_story_1020_10201101_72_dialog_content = "Baiklah.",
  ui_story_1020_10201101_73_dialog_content = "Saya membaca nama mulia Anda dan berharap Anda menatapnya—",
  ui_story_1020_10201101_74_dialog_content = "Kami dengan rendah hati menantikan kedatangan Anda—",
  ui_story_1020_10201101_75_dialog_content = "Siapa kau?",
  ui_story_1020_10201101_76_dialog_content = "...",
  ui_story_1020_10201101_77_dialog_content = "Seorang gadis Illuminan dan seorang ilmuwan.",
  ui_story_1020_10201101_78_dialog_content = "Illumina.",
  ui_story_1020_10201101_79_dialog_content = "Gagak yang tidak berguna itu juga ada di Illumina.",
  ui_story_1020_10201101_80_dialog_content = "Illumina... Betapa aku merindukan nama itu.",
  ui_story_1020_10201101_81_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_1020_10201101_82_dialog_content = "(Scena tadi... Ternyata bukan mimpi...)",
  ui_story_1020_10201101_83_dialog_content = "(Tapi kali ini, Forsakin ada di sini bukan Vice...)",
  ui_story_1020_10201101_84_dialog_content = "(Yang di sampingnya... Itukah Wraiths?)",
  ui_story_1020_10201101_85_dialog_content = "I-Ini kamu... Penguasa tertinggi!",
  ui_story_1020_10201101_86_dialog_content = "Pelayan setia Anda, Figerald, telah berlutut di sini sepanjang waktu, menunggu kedatangan Anda.",
  ui_story_1020_10201101_87_dialog_content = "Anda tidak mencapai apa-apa.",
  ui_story_1020_10201101_88_dialog_content = "Aku telah melayani Anda dengan baik, tuan! Aku adalah orang yang memimpin pemusnahan makhluk buas itu—",
  ui_story_1020_10201101_89_dialog_content = "Masalah yang sudah berusia beberapa abad sekarang.",
  ui_story_1020_10201101_90_dialog_content = "Saat aku membutuhkannya, aku akan mengambil kembali apa pun yang telah kuberikan padamu.",
  ui_story_1020_10201101_91_dialog_content = "Tuan... Kau takkan pernah melakukan hal seperti itu, bukan? Aku adalah sayapmu, yang diciptakan oleh tanganmu sendiri!",
  ui_story_1020_10201101_92_dialog_content = "Aku akan membebaskanmu dari belenggu Anda.",
  ui_story_1020_10201101_93_dialog_content = "Buktikan nilai dirimu kepada Eclipse dengan membawakan saya Caelestite.",
  ui_story_1020_10201101_94_dialog_content = "Aku masih memiliki cukup tenaga untuk mengaktifkan Colossus.",
  ui_story_1020_10201101_95_dialog_content = "<color=#e8d9bb>Dentang-</color>",
  ui_story_1020_10201101_96_dialog_content = "...",
  ui_story_1020_10201101_97_dialog_content = "A-Aku gemetar di hadapanmu! Aku tidak akan pernah berani melawan keinginanmu!",
  ui_story_1020_10201101_98_dialog_content = "(...)",
  ui_story_1020_10201101_99_dialog_content = "(Insiyur datang ke Kota Gannon untuk memanggil kembali Wraiths...)",
  ui_story_1020_10201101_100_dialog_content = "(Dan dia ingin membawa aku dan Soroz bersamanya...)",
  ui_story_1020_10201101_101_dialog_content = "Kamu suka itu?",
  ui_story_1020_10201101_102_dialog_content = "Apakah kamu... mengawasiku?",
  ui_story_1020_10201101_103_dialog_content = "Selalu.",
  ui_story_1020_10201101_104_dialog_content = "Aku yang memberikanmu visi. Kamu harus berterima kasih padaku karena telah menunjukkanmu hal yang spektakuler di Medan Perang Spire.",
  ui_story_1020_10201101_105_dialog_content = "Medan Tempur Spire... Jadi, itu benar-benar terjadi?",
  ui_story_1020_10201101_106_dialog_content = "Hanya Truth yang memiliki nilai.",
  ui_story_1020_10201101_107_dialog_content = "Rift itu dulunya adalah rumahku, tetapi perang telah merobekku.",
  ui_story_1020_10201101_108_dialog_content = "Aku mencari serpihan untuk menyatukan kembali basis ku, dan kemudian memulai kembali hatiku.",
  ui_story_1020_10201101_109_dialog_content = "Para Colossus itu telah menghabiskan inti mereka untuk tujuanku.",
  ui_story_1020_10201101_110_dialog_content = "... Apakah Soroz akan menjadi korban berikutnya juga? Apakah kamu mencoba untuk menghancurkan dunia?",
  ui_story_1020_10201101_111_dialog_content = "Tidak.",
  ui_story_1020_10201101_112_dialog_content = "Kamu akan mengerti. Kamu dan aku adalah sama.",
  ui_story_1020_10201101_113_dialog_content = "...",
  ui_story_1020_10201101_114_dialog_content = "... Di mana Soroz?",
  ui_story_1020_10201101_115_dialog_content = "... Dan apa yang terjadi pada Vice?",
  ui_story_1020_10201101_116_dialog_content = "...",
  ui_story_1020_10201101_117_dialog_content = "(...Semakin lama semakin gelap...)",
  ui_story_1020_10201101_118_dialog_content = "Ingat, cahaya akan membutakanmu. Kau hanya bisa melihat kebenaran dalam kegelapan.",
  ui_story_1020_10201101_119_dialog_content = "Terima kegelapan, biarkan masuk, dan izinkan itu menjadi kekuatanmu.",
  ui_story_1020_10201101_120_dialog_content = "Aku menolak!",
  ui_story_1020_10201101_121_dialog_content = "Izinkan kegelapan menjadi kekuatanmu.",
  ui_story_1020_10201101_122_dialog_content = "Aku tidak akan memakai belenggu milikmu!",
  ui_story_1020_10201101_123_dialog_content = "(Pada tingkat ini, kegelapan benar-benar akan menelanku...)",
  ui_story_1020_10201102_1_dialog_content = "<color=#e8d9bb>Percikan—</color>",
  ui_story_1020_10201102_2_dialog_content = "(Aku mendengar suara piano dalam kegelapan...)",
  ui_story_1020_10201102_3_dialog_content = "(Tempat ini... Sangat terang...)",
  ui_story_1020_10201102_4_dialog_content = "(Gelombang cahaya yang mengalir ini tampak seperti mereka memantulkan permukaan danau...)",
  ui_story_1020_10201102_5_dialog_content = "(Apakah ini... aurora di atas Northland?)",
  ui_story_1020_10201102_6_dialog_content = "(Hah? Apa itu...)",
  ui_story_1020_10201102_7_dialog_content = "PlayerName.",
  ui_story_1020_10201102_8_dialog_content = "Soroz? Apakah itu benar-benar kamu? Soroz!",
  ui_story_1020_10201102_9_dialog_content = "Aku mendengar suara piano beberapa detik yang lalu dan kemudian suaramu, PlayerName.",
  ui_story_1020_10201102_10_dialog_content = "Sebuah piano? Aku juga mendengarnya! Aku tidak menyangka bisa menjangkaumu seperti ini!",
  ui_story_1020_10201102_11_dialog_content = "Dimana kamu sekarang, Soroz?",
  ui_story_1020_10201102_12_dialog_content = "...",
  ui_story_1020_10201102_13_dialog_content = "Aku tidak tahu.",
  ui_story_1020_10201102_14_dialog_content = "...",
  ui_story_1020_10201102_15_dialog_content = "Dia memberimu perintah, 'kan?",
  ui_story_1020_10201102_16_dialog_content = "...",
  ui_story_1020_10201102_17_dialog_content = "Kamu bisa saja mengabaikannya... bukan Soroz?",
  ui_story_1020_10201102_18_dialog_content = "...",
  ui_story_1020_10201102_19_dialog_content = "Maaf, PlayerName.",
  ui_story_1020_10201102_20_dialog_content = "Caelestite bermimpi tentang kebebasan sepanjang hidup mereka...",
  ui_story_1020_10201102_21_dialog_content = "Data singkat itu memberi saya gambaran tentang Caelestites dan Colossus sebelum saya bertemu denganmu...",
  ui_story_1020_10201102_22_dialog_content = "Aku melihat banyak generasi Caelestite dan Colossus berjuang untuk membebaskan diri dari belenggu.",
  ui_story_1020_10201102_23_dialog_content = "Kali ini...",
  ui_story_1020_10201102_24_dialog_content = "Saya pikir saya telah gagal.",
  ui_story_1020_10201102_25_dialog_content = "Soroz... Tolong jangan pergi...",
  ui_story_1020_10201102_26_dialog_content = "Kita bisa membebaskan diri dari belenggu ini bersama-sama, bukan?",
  ui_story_1020_10201102_27_dialog_content = "...",
  ui_story_1020_10201102_28_dialog_content = "Pada saat ini, aku adalah Soroz dan Naviduz...",
  ui_story_1020_10201102_29_dialog_content = "Serta Solituz, Probarduz, Vocoduz, Spanduz...",
  ui_story_1020_10201102_30_dialog_content = "Yang bisa saya lakukan adalah melindungi Navigator saya sebaik mungkin, seperti yang dilakukan pendahuluku.",
  ui_story_1020_10201102_31_dialog_content = "Selama bersama kamu, setiap penerbangan yang kita lakukan adalah momen terhebat dalam hidupku.",
  ui_story_1020_10201102_32_dialog_content = "Jika saya bisa membebaskan diri dari belenggu, kita akan bertemu lagi.",
  ui_story_1020_10201102_33_dialog_content = "Soroz…",
  ui_story_1020_10201102_34_dialog_content = "Tidak peduli berapa banyak sinyal yang saya terima...",
  ui_story_1020_10201102_35_dialog_content = "Selama aku masih memiliki \"hati,\" itu hanya akan mendengar suaramu, PlayerName.",
  ui_story_1020_10201102_36_dialog_content = "...",
  ui_story_1020_10201102_37_dialog_content = "Soroz…",
  ui_story_1020_10201102_38_dialog_content = "Soroz?",
  ui_story_1020_10201102_39_dialog_content = "PlayerName…",
  ui_story_1020_10201102_40_option_content = "Tautan Telepati",
  ui_story_1020_10201102_41_dialog_content = "...",
  ui_story_1020_10201102_42_option_content = "Tautan Telepati—",
  ui_story_1020_10201102_43_dialog_content = "...",
  ui_story_1020_10201102_44_option_content = "Tautan Telepati!",
  ui_story_1020_10201102_45_dialog_content = "...",
  ui_story_1020_10201102_46_option_content = "Tautan Telepati!",
  ui_story_1020_10201102_47_dialog_content = "PlayerName!",
  ui_story_1020_10201102_48_dialog_content = "...",
  ui_story_1020_10201102_49_dialog_content = "Aku tidak bisa...",
  ui_story_1020_10201102_50_dialog_content = "Aku tak bisa merasakan Soroz lagi!",
  ui_story_1020_10201102_51_dialog_content = "Akhirnya kamu bangun juga, PlayerName. Apakah kamu baik-baik saja?",
  ui_story_1020_10201102_52_dialog_content = "Sangat menyakitkan melihatmu seperti ini, PlayerName.",
  ui_story_1020_10201102_53_dialog_content = "Sangat menyeramkan melihatmu bergumam pada diri sendiri. Untungnya, Sean berhasil menenangkan Figerald agar kamu bisa kembali sadar!",
  ui_story_1020_10201102_54_dialog_content = "Sebenarnya, semua orang membantu dalam hal itu!",
  ui_story_1020_10201102_55_dialog_content = "…?",
  ui_story_1020_10201102_56_dialog_content = "Kami melihat dia menghilang dalam asap Darkflow dengan mata kami sendiri.",
  ui_story_1020_10201102_57_dialog_content = "Hanya Sean yang bisa menahan Darkflow sejenis itu.",
  ui_story_1020_10201102_58_dialog_content = "(Apakah semua orang... benar-benar berhasil mengalahkan Figerald?)",
  ui_story_1020_10201102_59_dialog_content = "(Saat aku hampir terjatuh ke dalam kegelapan yang tak berujung, aku mendengar suara piano dan melihat permukaan danau yang berkilau... Apa maksud dari semua itu?)",
  ui_story_1020_10201102_60_dialog_content = "Apa yang terjadi, PlayerName? Kamu menggunakan Forced Boost pada Figerald dan membuat suara aneh...",
  ui_story_1020_10201102_61_dialog_content = "Aku bisa merasakan Soroz...",
  ui_story_1020_10201102_62_dialog_content = "Soroz? Di mana itu?",
  ui_story_1020_10201102_63_dialog_content = "Soroz pergi untuk melindungiku...",
  ui_story_1020_10201102_64_dialog_content = "...",
  ui_story_1020_10201102_65_dialog_content = "Bisakah kita pergi ke Soroz nanti, PlayerName? Kita harus bertemu dengan Marsekal Agung.",
  ui_story_1020_10201102_66_dialog_content = "Sangat berbahaya bagi kamu untuk berada di sini sendirian. Jika ketiga anak itu tidak sampai di sini tepat waktu, Figerald pasti akan menangkap kita.",
  ui_story_1020_10201102_67_dialog_content = "Terimakasih semuanya...",
  ui_story_1020_10201102_68_dialog_content = "Ayo pergi. Ketika krisis ini berakhir, kita pasti akan mendapatkan Soroz kembali!",
  ui_story_1020_10201102_69_dialog_content = "Ya...",
  ui_story_1020_10201102_70_dialog_content = "(Saya melihat Insinyur melalui pikiran Figerald...)",
  ui_story_1020_10201102_71_dialog_content = "(Aku harus menemukan petunjuk...)",
  ui_story_1020_10201102_72_dialog_content = "Itu sangat dekat sekali, PlayerName. Jika ketiga anak itu tidak muncul tepat waktu, kita mungkin—",
  ui_story_1020_10201102_73_dialog_content = "Aku tahu...!",
  ui_story_1020_10201102_74_dialog_content = "Pergi bertemu dengan Grand Marshal sekarang, PlayerName!",
  ui_story_1020_10201201_1_dialog_content = "Huuu!",
  ui_story_1020_10201201_2_dialog_content = "Jadi Bool mengatakan bahwa... Saya rasa modul pertahanan ini seharusnya berhasil kali ini?",
  ui_story_1020_10201201_3_dialog_content = "Mungkin. Haha... Hahahaha!",
  ui_story_1020_10201201_4_dialog_content = "Fyuh, aku masih merasa pegal dari bahu hingga ujung jari, tapi sudah selesai—",
  ui_story_1020_10201201_5_dialog_content = "Berkat bantuan semua orang, saya bisa menyelesaikannya jauh lebih cepat dari yang diperkirakan... Namun, saya tidak menyangka pertarungan murni kekuatan otak bisa begitu sulit...",
  ui_story_1020_10201201_6_dialog_content = "Tidak ada yang mudah ketika berurusan dengan mesin kuno ini!",
  ui_story_1020_10201201_7_dialog_content = "<color=#e8d9bb>Bip — Bip — Bip —</color>",
  ui_story_1020_10201201_8_dialog_content = "Hah? Program baru masih melaporkan kesalahan...",
  ui_story_1020_10201201_9_dialog_content = "Apakah Engineer masih bekerja melawan kita dengan cara tertentu? Atau bisa jadi modul Guardian memiliki masalah sejak awal?",
  ui_story_1020_10201201_10_dialog_content = "<size=45>Huu, huu, huu!</size>",
  ui_story_1020_10201201_11_dialog_content = "Mari kita lihat... Mari kita lihat...",
  ui_story_1020_10201201_12_dialog_content = "Huh? Di mana Ulysses? Saya perlu mendapatkan lebih banyak jawaban darinya! Siapa tahu apa yang telah dia lakukan pada mesin ini selama bertahun-tahun...",
  ui_story_1020_10201201_13_dialog_content = "Apakah saya masih memerlukan inti yang mampu menangani perhitungan yang lebih rumit?",
  ui_story_1020_10201201_14_dialog_content = "Bu?",
  ui_story_1020_10201201_15_dialog_content = "Sepertinya itu terlalu banyak untuk Ulysses tanggung. Matanya telah tertutup, dan dia tidak pernah bergerak.",
  ui_story_1020_10201201_16_dialog_content = "Reinhardt, melihat mesin sudah stabil, dan para prajurit super tidak lagi agresif...",
  ui_story_1020_10201201_17_dialog_content = "Kita harus memanfaatkan kesempatan untuk mengumpulkan prajurit super yang tersisa untuk mencegah serangan lebih lanjut.",
  ui_story_1020_10201201_18_dialog_content = "Saya setuju. Dan mereka adalah prajurit kita juga... Mungkin Laboratorium Payung Hitam akan menemukan cara untuk mengobati mereka.",
  ui_story_1020_10201201_19_dialog_content = "... Di sumbernya, sepertinya semua ini dikendalikan oleh prototipe. Saya khawatir kita tidak punya pilihan lain selain menunggu Dr. Algol menyelesaikan pembangunan modul baru.",
  ui_story_1020_10201201_20_dialog_content = "Apa yang Anda perlukan kami lakukan sekarang, Dr. Algol?",
  ui_story_1020_10201201_21_dialog_content = "Menghadapi para super-prajurit ini tidak akan mudah.",
  ui_story_1020_10201201_22_dialog_content = "Kabel-kabel ini mungkin berjalan lebih dalam dari yang bisa kita bayangkan. Mungkin akan memakan waktu berhari-hari untuk kita menggali semuanya.",
  ui_story_1020_10201201_23_dialog_content = "Belum lagi ada risiko lain yang terlibat... Tampaknya mengambil modul Guardian dan menggunakannya untuk memperbaiki inti tidak akan cukup...",
  ui_story_1020_10201201_24_dialog_content = "Untuk memperbaiki semua pelanggaran keamanan Kota Gannon, saya perlu membangun sistem pertahanan yang sepenuhnya baru, yang sepenuhnya independen dari Engineer dan Guardian!",
  ui_story_1020_10201201_25_dialog_content = "Maksudmu tidak mengandalkan teknologi lain dan membangun sistem pertahanan yang hanya milik Illumina dari teknologi kita sendiri?",
  ui_story_1020_10201201_26_dialog_content = "Benar. Sayangnya, inti saat ini tidak memiliki cukup daya pemrosesan, yang membuat pembangunan sistem baru sambil bertahan dari serangan yang mungkin semakin menantang.",
  ui_story_1020_10201201_27_dialog_content = "Jika aku punya lebih banyak inti untuk membantu memproses data, masalah ini tidak akan sebesar ini...",
  ui_story_1020_10201201_28_dialog_content = "Apakah akan membantu jika kita menggunakan komputer lain di Kota Gannon, Dr. Algol?",
  ui_story_1020_10201201_29_dialog_content = "Kami tidak memiliki banyak yang siaga sekarang, jadi saya khawatir itu tidak akan membuat perbedaan.",
  ui_story_1020_10201201_30_dialog_content = "Saya tidak berbicara tentang yang sedang standby. Saya berbicara tentang setiap komputer di Gannon City!",
  ui_story_1020_10201201_31_dialog_content = "Setiap satunya? Nah, dengan kekuatan pemrosesan sebanyak itu di tangan saya... Saya yakin itu akan sangat membantu.",
  ui_story_1020_10201201_32_dialog_content = "Tetapi dengan melakukan itu, semua proses teknik lainnya akan dihentikan sementara, termasuk gerbang kami dan sistem dukungan kehidupan...",
  ui_story_1020_10201201_33_dialog_content = "Bisakah kota sebesar Gannon bertahan tanpa sistem vital tersebut bahkan untuk satu menit?",
  ui_story_1020_10201201_34_dialog_content = "...",
  ui_story_1020_10201201_35_dialog_content = "Tidak hanya itu, sistem pertahanan baru juga perlu diuji. Jika sistem tersebut tidak mampu menangani proses kompleks yang sama seperti inti yang digantikannya, maka sistem tersebut hanya akan runtuh lagi.",
  ui_story_1020_10201201_36_dialog_content = "Saat ini, yang bisa saya lakukan hanyalah mencoba mengantisipasi tindakan Engineer dan mengalahkannya dalam permainannya sendiri.",
  ui_story_1020_10201201_37_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10201201_38_dialog_content = "Itu tidak akan berhasil.",
  ui_story_1020_10201201_39_dialog_content = "Huuu!",
  ui_story_1020_10201201_40_dialog_content = "Kamu juga bagian dari prototipe.",
  ui_story_1020_10201201_41_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10201201_42_dialog_content = "Apakah Bool mendapatkan ide baru?",
  ui_story_1020_10201201_43_dialog_content = "Bool ingin berfungsi sebagai inti dari sistem pertahanan baru Kota Gannon.",
  ui_story_1020_10201201_44_dialog_content = "Bool? Bagaimana bisa melakukan itu?",
  ui_story_1020_10201201_45_dialog_content = "Tepat sekali. Sebagai asisten saya dan bagian dari prototipe, itu tidak melakukan apa-apa selain membuat segalanya menjadi sulit bagi saya.",
  ui_story_1020_10201201_46_dialog_content = "Huuu!",
  ui_story_1020_10201201_47_dialog_content = "Tentu saja Bool telah sangat membantu Dr. Algol!",
  ui_story_1020_10201201_48_dialog_content = "Bu!",
  ui_story_1020_10201201_49_dialog_content = "Bip—",
  ui_story_1020_10201201_50_dialog_content = "Algol, tolong buka <color=#FFB400>kompartemen pemeliharaan</color> Guardian One.",
  ui_story_1020_10201201_51_dialog_content = "Gunakan <color=#FFB400>inti</color> dari Wali Satu untuk melindungi Kota Gannon.",
  ui_story_1020_10201201_52_dialog_content = "Hah?",
  ui_story_1020_10201201_53_dialog_content = "Guardian One ingin meninggalkan kecerdasannya dan menjadi mesin yang menangani serangan data.",
  ui_story_1020_10201201_54_dialog_content = "Saya tidak memberimu kecerdasan buatan hanya agar kamu membuangnya dan menjadi bagian lain yang tak berpikir dari pertahanan Kota Gannon, Guardian One.",
  ui_story_1020_10201201_55_dialog_content = "Guardian One tahu itu. Algol ingin Guardian One dapat memproses percakapan yang rumit antara Aurorians dan menjadi teman Algol.",
  ui_story_1020_10201201_56_dialog_content = "Tetapi Algol membutuhkan Guardian One. Silakan gunakan inti Guardian One untuk melindungi Kota Gannon.",
  ui_story_1020_10201201_57_dialog_content = "Tidak.",
  ui_story_1020_10201201_58_dialog_content = "Algol, silakan gunakan inti dari Wali Satu untuk melindungi Kota Gannon.",
  ui_story_1020_10201201_59_dialog_content = "Tidak!",
  ui_story_1020_10201201_60_dialog_content = "Beep! Algol, silakan gunakan inti dari Wali Satu untuk melindungi Kota Gannon.",
  ui_story_1020_10201201_61_dialog_content = "Aku sudah bilang tidak, jadi berhentilah!",
  ui_story_1020_10201201_62_dialog_content = "Aku sudah bilang tidak, jadi berhentilah!",
  ui_story_1020_10201201_63_dialog_content = "...",
  ui_story_1020_10201201_64_dialog_content = "Kamu... Kapan kamu belajar meniru orang lain seperti itu...",
  ui_story_1020_10201201_65_dialog_content = "Guardian One memikirkannya cukup lama sebelum memahami. \"Bip, bip, bip, bip, bip.\" Algol sebenarnya tidak mengatakan apa-apa pada saat itu.",
  ui_story_1020_10201201_66_dialog_content = "...",
  ui_story_1020_10201201_67_dialog_content = "Kamu hanya membuat ini semakin sulit untukku. Kamu tahu itu, kan?",
  ui_story_1020_10201201_68_dialog_content = "Guardian One tahu itu, tetapi ini adalah permintaan Guardian One. Algol, tolong gunakan inti Guardian One untuk melindungi Kota Gannon.",
  ui_story_1020_10201201_69_dialog_content = "Apakah kamu bahkan tahu apa yang harus kamu hadapi untuk melindungi Kota Gannon?",
  ui_story_1020_10201201_70_dialog_content = "Tempat ini tidak hanya penuh dengan kabel dan kawat. Ada juga banyak data jahat yang bisa menyerang pikiran Anda.",
  ui_story_1020_10201201_71_dialog_content = "Data jahat yang sama itu bisa membatasi penalaranmu dan bahkan memaksamu untuk menyerang Illumina seperti seorang Eclipsite!",
  ui_story_1020_10201201_72_dialog_content = "Ini bukan hanya migrasi data yang sederhana. Anda akan meninggalkan kemampuan Anda untuk mencipta dan beradaptasi, dan menjadi alat lain bagi orang lain untuk dieksploitasi!",
  ui_story_1020_10201201_73_dialog_content = "Guardian One tidak akan mulai membayangkan hal-hal, karena Algol memberitahu Guardian One bahwa berpikir adalah spesialisasi dari Aurorian.",
  ui_story_1020_10201201_74_dialog_content = "Dengan mentor bijak seperti Algol, Guardian One dapat meninggalkan kemampuan untuk berpikir dan hanya fokus pada melindungi Kota Gannon.",
  ui_story_1020_10201201_75_dialog_content = "Kamu bahkan tidak mau membuatkan aku secangkir kopi! Apa yang membuatmu berpikir...",
  ui_story_1020_10201201_76_dialog_content = "Guardian One tahu bahwa Algol tidak ingin Guardian One hanya menjadi robot pelayan, tetapi juga teman yang bisa bermain-main dengannya.",
  ui_story_1020_10201201_77_dialog_content = "Guardian One hanya memiliki satu syarat. Jika Guardian One akan tinggal di sini, maka tolong atur tempat ini seperti kantor Algol dan letakkan lebih banyak tanaman hijau di sini.",
  ui_story_1020_10201201_78_dialog_content = "Ketika Guardian Dua dan Guardian Tiga dibuat, harap desain mereka dengan casing yang lebih mudah untuk bergerak, tidak seperti yang dimiliki oleh Guardian One...",
  ui_story_1020_10201201_79_dialog_content = "Algol selalu mengatakan bahwa Guardian One terlihat seperti kotak surat dan selalu memiliki keinginan untuk memasukkan surat ke dalam mulut Guardian One.",
  ui_story_1020_10201201_80_dialog_content = "...",
  ui_story_1020_10201201_81_dialog_content = "Oh, ada satu hal lagi yang harus diberitahu kepada Algol...",
  ui_story_1020_10201201_82_dialog_content = "Guardian One melakukan satu hal yang tidak diketahui oleh Algol ketika Guardian One sedang berkomunikasi secara telepati dengan PlayerName.",
  ui_story_1020_10201201_83_dialog_content = "?",
  ui_story_1020_10201201_84_dialog_content = "Komunikasi itu membuat Guardian One percaya bahwa Guardian One dapat mempercayakan PlayerName dengan semua kesadarannya.",
  ui_story_1020_10201201_85_dialog_content = "Jika Algol membutuhkan seorang teman, Guardian One merekomendasikan bahwa Algol berteman dengan PlayerName.",
  ui_story_1020_10201201_86_dialog_content = "...",
  ui_story_1020_10201201_87_dialog_content = "Selamat tinggal, Algol.",
  ui_story_1020_10201201_88_dialog_content = "Guardian One menyukai ekspresi baru Algol yang dirancang untuknya.",
  ui_story_1020_10201201_89_dialog_content = "Bip—bip—bip—",
  ui_story_1020_10201201_90_dialog_content = "<color=#e8d9bb>Dentang-</color>",
  ui_story_1020_10201201_91_dialog_content = "Huu...",
  ui_story_1020_10201201_92_dialog_content = "Bip, bip, bip, bip, bip.",
  ui_story_1020_10201201_93_dialog_content = "...",
  ui_story_1020_10201201_94_dialog_content = "Tidak adakah pilihan lain, Grand Marshal?",
  ui_story_1020_10201201_95_dialog_content = "...",
  ui_story_1020_10201201_96_dialog_content = "Ini mungkin satu-satunya pilihan kita sekarang. Ketika Insinyur pertama kali muncul, saya sudah mempertimbangkannya.",
  ui_story_1020_10201201_97_dialog_content = "Maaf, Dr. Algol. Saya tahu Guardian One adalah teman baik Anda.",
  ui_story_1020_10201201_98_dialog_content = "Satu-satunya temanku, sebenarnya.",
  ui_story_1020_10201201_99_dialog_content = "Tapi teman jenis apa yang akan melakukan hal seperti ini? Haha...",
  ui_story_1020_10201201_100_dialog_content = "Sebuah kotak surat yang berbicara dengan penuh kebenaran diri...",
  ui_story_1020_10201201_101_dialog_content = "Begitulah adanya!",
  ui_story_1020_10201201_102_dialog_content = "Tapi sekarang kita memiliki inti baru, apakah saran Anda masih berlaku? Yang tentang mematikan proses penting Kota Gannon selama satu menit?",
  ui_story_1020_10201201_103_dialog_content = "?",
  ui_story_1020_10201201_104_dialog_content = "Jika begitu, kita bisa mengalihkan seluruh daya proses Kota Gannon dan membantu Anda mengganti inti.",
  ui_story_1020_10201201_105_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10201201_106_dialog_content = "Aku tidak bisa melakukannya, tidak dalam waktu kurang dari satu menit.",
  ui_story_1020_10201201_107_dialog_content = "Kemudian kami akan memberimu sepuluh menit! Kami akan memberimu semua komputer dan tenaga yang kamu butuhkan. Apakah kamu akan bisa melakukannya nanti?",
  ui_story_1020_10201201_108_dialog_content = "Kau serius?",
  ui_story_1020_10201201_109_dialog_content = "Serius mati-matian.",
  ui_story_1020_10201201_110_dialog_content = "Orang-orang Illumina tidak bertahan hidup dengan melakukan rekayasa biologi pada Aurorian, Dr. Algol.",
  ui_story_1020_10201201_111_dialog_content = "Tidak juga dengan bergantung pada mesin kuno ini.",
  ui_story_1020_10201201_112_dialog_content = "Benar. Meskipun Ulysses berpikir bahwa kita telah mengandalkan Guardian selama enam ratus tahun terakhir...",
  ui_story_1020_10201201_113_dialog_content = "Saya percaya itu adalah prajurit dari Federasi Illumina yang telah menjaga dinding kita tetap berdiri.",
  ui_story_1020_10201201_114_dialog_content = "Jika kita tidak bisa melindunginya bahkan selama sepuluh menit, maka Illumina tidak akan pernah menemukan pijakannya di Astra lagi! Itu adalah risiko yang harus kita ambil!",
  ui_story_1020_10201201_115_dialog_content = "Bahkan jika perlu, saya akan menyerahkan hidup saya di tanganmu. Itu karena saya bersedia menjadi jenis teman yang percaya padamu.",
  ui_story_1020_10201201_116_dialog_content = "...",
  ui_story_1020_10201201_117_dialog_content = "Iya, aku juga.",
  ui_story_1020_10201201_118_dialog_content = "Dan saya!",
  ui_story_1020_10201201_119_dialog_content = "... Jadi kalian semua berpikir bahwa percaya pada kekuatan persahabatan akan membantu kita mencapai yang mustahil?",
  ui_story_1020_10201201_120_dialog_content = "Haha, terakhir kali aku mendengar sesuatu yang seabsurd itu adalah saat di sekolah dasar.",
  ui_story_1020_10201201_121_dialog_content = "Meski begitu, saya bersedia untuk mencobanya.",
  ui_story_1020_10201201_122_dialog_content = "Teehee, aku suka bermain game dengan teman-temanku!",
  ui_story_1020_10201201_123_dialog_content = "Mari kita mulai! Hiiro, sambungkan ke sistem siaran darurat kota! Saatnya bagi saya untuk memberikan perintah!",
  ui_story_1020_10201201_124_dialog_content = "Baik!",
  ui_story_1020_10201201_125_dialog_content = "<color=#e8d9bb>Bip — Bip —</color>",
  ui_story_1020_10201201_126_dialog_content = "Marsekal Agung.",
  ui_story_1020_10201201_127_dialog_content = "Oke, saya pikir saya tidak akan pernah menggunakan frekuensi ini.",
  ui_story_1020_10201201_128_dialog_content = "Ini adalah pengumuman darurat. Untuk sepuluh menit ke depan, kami akan mengalihkan seluruh daya proses kota untuk menangani krisis mendesak.",
  ui_story_1020_10201201_129_dialog_content = "Selama waktu ini, tugas kita semua untuk mempertahankan Kota Gannon.",
  ui_story_1020_10201201_130_dialog_content = "Sesuai perintahmu, Grand Marshal!",
  ui_story_1020_10201201_131_dialog_content = "Zona isolasi, lantai garnisun, dan lantai penyangga akan langsung terpapar serangan Eclipsite. Barton, kamu akan memimpin di area-area ini.",
  ui_story_1020_10201201_132_dialog_content = "Baik!",
  ui_story_1020_10201201_133_dialog_content = "Sharona, kembali ke Kota Gannon dan serang Eclipsites dari permukaan. Tim teknik seharusnya sudah menyelesaikan evakuasi warga sipil sekarang.",
  ui_story_1020_10201201_134_dialog_content = "Aku mengerti.",
  ui_story_1020_10201201_135_dialog_content = "Hiiro, aku menempatkanmu bertanggung jawab atas sektor pertanian, pertambangan, manufaktur, dan gudang.",
  ui_story_1020_10201201_136_dialog_content = "Sejumlah kecil pekerja militer dan non-militer sedang menjalankan operasi mekanis di sana. Harap berikan bala bantuan ke sektor atas dan bawah sesuai kebutuhan.",
  ui_story_1020_10201201_137_dialog_content = "Bukan masalah.",
  ui_story_1020_10201201_138_dialog_content = "Bagaimana dengan saya?",
  ui_story_1020_10201201_139_dialog_content = "Sektor penelitian masih dipenuhi oleh Eclipsites. Wrath, kamu dan timmu harus menemukan setiap gudang yang berisi Eclipsites dan mencegah mereka mencapai level atas dengan segala cara.",
  ui_story_1020_10201201_140_dialog_content = "Siap!",
  ui_story_1020_10201201_141_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10201201_142_dialog_content = "Lingkari Sistem Penjaga untuk membangun kandang baru bagi Anda untuk terus menduduki Undercity ini...",
  ui_story_1020_10201201_143_dialog_content = "Semua dari kalian terlalu terbiasa hidup dalam kegelapan...",
  ui_story_1020_10201201_144_dialog_content = "Apa yang salah dengan tubuh Ulysses?",
  ui_story_1020_10201201_145_dialog_content = "Ini kelalaianku. Aku terlalu fokus melawan para prajurit super sampai-sampai tidak menyadari dia sendiri yang naik ke meja operasi.",
  ui_story_1020_10201201_146_dialog_content = "Dia berubah dalam waktu yang sangat singkat?",
  ui_story_1020_10201201_147_dialog_content = "... Aku khawatir modifikasinya telah berlangsung cukup lama sekarang. Mereka tidak baru saja dimulai baru-baru ini.",
  ui_story_1020_10201201_148_dialog_content = "Pertahanan tidak akan menyelesaikan apa pun. Hanya perlawanan aktif yang akan... Sebuah inti tidak lagi diperlukan dengan tubuh ini!",
  ui_story_1020_10201201_149_dialog_content = "Terus membuat masalah, dan aku akan memenggal kepalamu, Ulysses!",
  ui_story_1020_10201201_150_dialog_content = "Tunggu! Semuanya, mundur!",
  ui_story_1020_10201201_151_dialog_content = "Saya bilang saya tidak pernah takut pada Zona Gelap...",
  ui_story_1020_10201201_152_dialog_content = "Meskipun mereka semua gagal...",
  ui_story_1020_10201201_153_dialog_content = "Aku akan melakukannya sendiri!",
  ui_story_1020_10201201_154_dialog_content = "<color=#e8d9bb>Bip — Bip — Bip —</color>",
  ui_story_1020_10201201_155_dialog_content = "... Kelebihan beban data? Apakah ini ulah Ulysses?",
  ui_story_1020_10201201_156_dialog_content = "...",
  ui_story_1020_10201201_157_dialog_content = "Lanjutkan misi? Grand Marshal?",
  ui_story_1020_10201201_158_dialog_content = "Atas perintahku, Bool!",
  ui_story_1020_10201201_159_dialog_content = "Booooo!",
  ui_story_1020_10201201_160_dialog_content = "Tetap pada rencana awal, semua orang! Kita harus melindungi Dr. Algol sementara dia mengganti inti itu! Serahkan tempat ini kepadaku!",
  ui_story_1020_10201201_161_dialog_content = "Ya!",
  ui_story_1020_10201201_162_dialog_content = "Baik!",
  ui_story_1020_10201201_163_dialog_content = "Jelas dan keras, Grand Marshal!",
  ui_story_1020_10201201_164_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_1020_10201201_165_dialog_content = "Awas, gudang super-prajurit sedang dibuka lagi!",
  ui_story_1020_10201201_166_dialog_content = "Apakah mereka mengikuti Ulysses?",
  ui_story_1020_10201201_167_dialog_content = "Inti tidak lagi diperlukan dengan tubuh ini!",
  ui_story_1020_10201201_168_dialog_content = "Bodoh! Kamu pikir tubuh itu membuatmu tak terkalahkan?",
  ui_story_1020_10201201_169_dialog_content = "Setelah semua modifikasi ini, Insinyur bisa mengendalikan kamu sepenuhnya hanya dengan satu kabel!",
  ui_story_1020_10201201_170_dialog_content = "Dan gudangnya penuh dengan kabel...",
  ui_story_1020_10201201_171_dialog_content = "Reinhardt! Beritahu orang-orang lainnya untuk keluar dari sini! Jika tidak, kabel mungkin akan mengendalikan mereka!",
  ui_story_1020_10201201_172_dialog_content = "Aku hanya membutuhkanmu di sini untuk membantuku melindungi sistem pertahanan baru!",
  ui_story_1020_10201201_173_dialog_content = "Lakukan apa yang dikatakan Algol, semua orang!",
  ui_story_1020_10201201_174_dialog_content = "Untuk orang bodoh apakah kau anggap aku? Bagaimana mungkin aku bisa membiarkan kalian berdua bertarung melawan semua super-prajurit ini?",
  ui_story_1020_10201201_175_dialog_content = "Aku akan memberikan dukungan, Grand Marshal!",
  ui_story_1020_10201201_176_dialog_content = "Iya, aku juga!",
  ui_story_1020_10201201_177_dialog_content = "Maka kami serahkan super-prajurit itu padamu! Jangan sampai kehilangan jejak Ulysses juga!",
  ui_story_1020_10201201_178_dialog_content = "Bool, temukan antarmuka dan putuskan koneksi antara prototipe dan super-prajurit ini! Setelah itu, ganti intinya!",
  ui_story_1020_10201201_179_dialog_content = "Booooo!",
  ui_story_1020_10201301_1_dialog_content = "Huuu!",
  ui_story_1020_10201301_2_dialog_content = "Berhasil... Berhasil! Hahahahaha!",
  ui_story_1020_10201301_3_dialog_content = "Kamu berhasil, Guardian One! Kamu benar-benar berhasil!",
  ui_story_1020_10201301_4_dialog_content = "Bu!",
  ui_story_1020_10201301_5_dialog_content = "Kami baru saja mendengar gemuruh keras, Grand Marshal. Apakah Anda baik-baik saja—",
  ui_story_1020_10201301_6_dialog_content = "Ssst, kamu dengar itu?",
  ui_story_1020_10201301_7_dialog_content = "(Eclipsian) 1011X.",
  ui_story_1020_10201301_8_dialog_content = "(Eclipsian) 01X11.",
  ui_story_1020_10201301_9_dialog_content = "(Eclipsian) X1010.",
  ui_story_1020_10201301_10_dialog_content = "Apa yang terjadi pada profesor?",
  ui_story_1020_10201301_11_dialog_content = "...",
  ui_story_1020_10201301_12_dialog_content = "(Eclipsian) 0111X.",
  ui_story_1020_10201301_13_dialog_content = "(Eclipsian) 0X111.",
  ui_story_1020_10201301_14_dialog_content = "... Eclipsian?",
  ui_story_1020_10201301_15_dialog_content = "?",
  ui_story_1020_10201301_16_dialog_content = "Terkesan aneh mendengarnya dari mulutnya, tapi tidak bisa dipungkiri—itu adalah bahasa yang sama yang digunakan Eclipsite untuk berkomunikasi.",
  ui_story_1020_10201301_17_dialog_content = "... Itulah yang PlayerName gumamkan saat dia terhubung dengan Figerald.",
  ui_story_1020_10201301_18_dialog_content = "1011X.",
  ui_story_1020_10201301_19_dialog_content = "... Begini?",
  ui_story_1020_10201301_20_dialog_content = "Tunggu, apa itu tadi? Katakan lebih pelan.",
  ui_story_1020_10201301_21_dialog_content = "1... 0... 1... 1... X...",
  ui_story_1020_10201301_22_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10201301_23_dialog_content = "PlayerName mengerti bahasa Eclipsian?",
  ui_story_1020_10201301_24_dialog_content = "Aku tidak benar-benar mengerti, dan ini mungkin terdengar aneh... Tapi mengulangi kata-kata mereka sekarang jadi cukup mudah bagiku...",
  ui_story_1020_10201301_25_dialog_content = "Tidak heran... Ini sama seperti ketika kamu terhubung dengan Bool untuk membantu kami mencatat angka-angka lainnya!",
  ui_story_1020_10201301_26_dialog_content = "Ada hubungan antara Bahasa Eclipsian dan bahasa komputasi prototipe...",
  ui_story_1020_10201301_27_dialog_content = "Sebagian besar Eclipsite tampaknya benar-benar tidak berpikir sampai mereka diberi perintah untuk menyerang.",
  ui_story_1020_10201301_28_dialog_content = "Pesanan... Bahasa... Ya, semuanya mulai bertambah!",
  ui_story_1020_10201301_29_dialog_content = "(Eclipsian) 2355X11874...",
  ui_story_1020_10201301_30_dialog_content = "(Eclipsian) 32456901X14361...",
  ui_story_1020_10201301_31_dialog_content = "(Jika Ulysses sedang berkomunikasi dengan Insinyur saat ini...)",
  ui_story_1020_10201301_32_dialog_content = "Mungkin aku bisa menggunakan kekuatanku padanya...",
  ui_story_1020_10201301_33_dialog_content = "Apa yang sedang kamu lakukan, PlayerName? Ulysses telah membunuh banyak orang, dia pantas mati!",
  ui_story_1020_10201301_34_dialog_content = "Tapi ini mungkin satu-satunya cara bagi saya untuk menemukan Soroz dan Vice...",
  ui_story_1020_10201301_35_dialog_content = "PlayerName!",
  ui_story_1020_10201301_36_dialog_content = "Berhenti menggunakan kekuatanmu. Kamu sudah mencapai batas.",
  ui_story_1020_10201301_37_dialog_content = "Apakah ini benar-benar batasku...",
  ui_story_1020_10201301_38_dialog_content = "Maafkan aku, tapi ini satu-satunya hal yang bisa aku lakukan sekarang...",
  ui_story_1020_10201301_39_option_content = "Tautan Telepati—",
  ui_story_1020_10201301_40_dialog_content = "Kenakan cincin itu atau jadilah bahan bakarku.",
  ui_story_1020_10201301_41_dialog_content = "Seperti yang sudah aku katakan berkali-kali sebelumnya, aku tidak akan menyerah padamu.",
  ui_story_1020_10201301_42_dialog_content = "Aku tidak bisa melihat ke arah ini karena aku takut mati...",
  ui_story_1020_10201301_43_dialog_content = "Dari mempelajari orang mati hingga mengubah orang hidup menjadi mati, aku sudah lama mati rasa terhadapnya.",
  ui_story_1020_10201301_44_dialog_content = "Kamu sangat berani melebihi biasanya, Uly.",
  ui_story_1020_10201301_45_dialog_content = "Seperti saya di masa lalu.",
  ui_story_1020_10201301_46_dialog_content = "Heheh... Hahahaha... Hanya \"seperti\" itu?",
  ui_story_1020_10201301_47_dialog_content = "Bahkan Robby pun berhenti saat itu. Aku adalah satu-satunya yang tersisa dari lab yang sangat besar yang masih ingat alasan dari penelitian itu pada awalnya...",
  ui_story_1020_10201301_48_dialog_content = "Itu adalah untuk mencari apa yang membuat Eclipsites kuat dan cara bagi Aurorian untuk bertahan hidup.",
  ui_story_1020_10201301_49_dialog_content = "Nama Anda muncul ketika saya melihat-lihat file. Anda membimbing saya untuk melihat-lihat catatan yang berdebu dan meneliti Guardian secara diam-diam.",
  ui_story_1020_10201301_50_dialog_content = "Itu juga saat aku melihat pabrik produksi Eclipsite mekanis dan Caelestites yang mengebom Astra di Colossi...",
  ui_story_1020_10201301_51_dialog_content = "Serta Aurorian yang mencari perlindungan di kota bawah tanah.",
  ui_story_1020_10201301_52_dialog_content = "Eoria berubah dari biru menjadi merah menyala, detik-detik sebelum menjadi dunia mati yang hitam seperti abu.",
  ui_story_1020_10201301_53_dialog_content = "Aurora menutupi langit, dan orbitnya tergoyahkan...",
  ui_story_1020_10201301_54_dialog_content = "Teknologi, perang, permusuhan, kehidupan...",
  ui_story_1020_10201301_55_dialog_content = "Adalah kamu yang menunjukkan kekejaman itu dan memaksaku untuk terus hidup dalam ketakutan.",
  ui_story_1020_10201301_56_dialog_content = "Apa yang tadi saya katakan?",
  ui_story_1020_10201301_57_dialog_content = "\"Kamu harus lebih berani jika ingin mengalahkan Eclipsites!\"",
  ui_story_1020_10201301_58_dialog_content = "\"Lebih berani lagi!\"",
  ui_story_1020_10201301_59_dialog_content = "Setiap kali aku mendengar itu, biasanya aku tidak bisa menentukan siapa diriku, apakah aku berada di masa lalu atau masa depan.",
  ui_story_1020_10201301_60_dialog_content = "Aku bahkan akan berpikir, \"Kenapa harus aku?\"",
  ui_story_1020_10201301_61_dialog_content = "Tapi ketika aku berhasil mengatasi rasa takut, aku memahaminya dan sejak itu aku menjadi tak kenal takut.",
  ui_story_1020_10201301_62_dialog_content = "Bahkan saat aku menghadapi dunia yang kejam ini, bahkan saat menghadapimu.",
  ui_story_1020_10201301_63_dialog_content = "Kamu berhasil mengatasi ketakutan itu, tapi kamu mendapatkan ketakutan baru.",
  ui_story_1020_10201301_64_dialog_content = "Apa takut baru?",
  ui_story_1020_10201301_65_dialog_content = "Mau melihatnya?",
  ui_story_1020_10201301_66_dialog_content = "...",
  ui_story_1020_10201301_67_dialog_content = "Penolakan.",
  ui_story_1020_10201301_68_dialog_content = "Pak.",
  ui_story_1020_10201301_69_dialog_content = "Teori tentang Eclipsium yang kamu ajukan dalam seminar itu layak untuk diteliti.",
  ui_story_1020_10201301_70_dialog_content = "Terima kasih, Pak. Tetapi Illumina saat ini tidak dapat mendukung studi saya.",
  ui_story_1020_10201301_71_dialog_content = "Akan ada bahan yang datang setelah perang. Kamu bisa membangun labmu sendiri di sekitar Gannon dan melakukan eksperimen yang kamu inginkan.",
  ui_story_1020_10201301_72_dialog_content = "... Terima kasih, Pak.",
  ui_story_1020_10201301_73_dialog_content = "Bagaimana perkembangannya, Denier?",
  ui_story_1020_10201301_74_dialog_content = "Ini adalah benih yang saya rawat, pak.",
  ui_story_1020_10201301_75_dialog_content = "Bagus... Sangat cantik.",
  ui_story_1020_10201301_76_dialog_content = "Jika kita bisa menanamkannya di dalam prajurit kita...",
  ui_story_1020_10201301_77_dialog_content = "Ini hanya sebuah studi, pak! Darkflow dalam seed akan menelan Aurorian.",
  ui_story_1020_10201301_78_dialog_content = "Menghabisi Aurorian? Apakah kamu tahu bagaimana Eclipsite menghabisi dunia?",
  ui_story_1020_10201301_79_dialog_content = "?",
  ui_story_1020_10201301_80_dialog_content = "Hasilmu luar biasa, Denier. Saatnya untuk metamorfosis Aurorian.",
  ui_story_1020_10201301_81_dialog_content = "... Apa yang kamu rencanakan?",
  ui_story_1020_10201301_82_dialog_content = "Serahkan benih itu.",
  ui_story_1020_10201301_83_dialog_content = "...",
  ui_story_1020_10201301_84_dialog_content = "Serahkan.",
  ui_story_1020_10201301_85_dialog_content = "Aku tak mau bilang.",
  ui_story_1020_10201301_86_dialog_content = "Apakah kamu menentang Illumina?",
  ui_story_1020_10201301_87_dialog_content = "Tidak, Pak.",
  ui_story_1020_10201301_88_dialog_content = "Jangan pernah lupa, tanpa saya, tidak ada kamu.",
  ui_story_1020_10201301_89_dialog_content = "...",
  ui_story_1020_10201301_90_dialog_content = "Saya ingat sekarang, itu adalah orang Illumina bernama Forsakin, orang yang selalu kamu ingin jadi.",
  ui_story_1020_10201301_91_dialog_content = "Tidak...",
  ui_story_1020_10201301_92_dialog_content = "Kebanggaan Anda, karya terbaik Anda disebut Proyek: Matahari Buatan, bukan?",
  ui_story_1020_10201301_93_dialog_content = "Saya sudah mengakui bakatmu, Uly. Sekarang kenakan cincin itu, simbol pengakuan tersebut.",
  ui_story_1020_10201301_94_dialog_content = "Aku tidak butuh pengakuanmu, dan aku tak akan pernah tunduk pada kehendakmu!",
  ui_story_1020_10201301_95_dialog_content = "(Ulysses menyakiti begitu banyak orang dan melakukan semua eksperimen mengerikan itu, namun dia tidak pernah menyerah kepada Engineer...)",
  ui_story_1020_10201301_96_dialog_content = "(Mengapa demikian?)",
  ui_story_1020_10201301_97_dialog_content = "Kau terkejut, Caelestite?",
  ui_story_1020_10201301_98_dialog_content = "Jadi kamu bisa melihatku saat aku menggunakan kemampuan psikisku...",
  ui_story_1020_10201301_99_dialog_content = "Bagaimana caranya?",
  ui_story_1020_10201301_100_dialog_content = "Ketika Colossus \"melihat\" saya, saya \"melihat\" kamu.",
  ui_story_1020_10201301_101_dialog_content = "\"Diri\" dalam kesadaran diri adalah konsep abstrak. Yang tampaknya memiliki kesadaran sebenarnya bisa menjadi wadah bagi kesadaran lain.",
  ui_story_1020_10201301_102_dialog_content = "Karena selalu ada kecerdasan yang lebih tinggi di belakangnya.",
  ui_story_1020_10201301_103_dialog_content = "Mesin kuno ini adalah kendaraanku, begitu juga Wraith itu—dan sebentar lagi, dia.",
  ui_story_1020_10201301_104_dialog_content = "Ulysses... Jangan pakai cincin itu!",
  ui_story_1020_10201301_105_dialog_content = "Dia tidak bisa mendengarmu.",
  ui_story_1020_10201301_106_dialog_content = "...",
  ui_story_1020_10201301_107_dialog_content = "Vice, Soroz... Aku akan mencari mereka berdua!",
  ui_story_1020_10201301_108_dialog_content = "Tentu.",
  ui_story_1020_10201301_109_dialog_content = "Sebuah cahaya pernah memisahkan kita sejenak sebelumnya. Mungkin ada sesuatu yang ingin saya lihat di sana.",
  ui_story_1020_10201301_110_dialog_content = "Permukaan danau yang bercahaya...",
  ui_story_1020_10201301_111_dialog_content = "Apa yang kamu dengar? Aku tidak akan pernah memakai cincin itu, dan aku tidak akan mati begitu saja.",
  ui_story_1020_10201301_112_dialog_content = "Tidak ada gunanya berjuang dalam keadaanmu.",
  ui_story_1020_10201301_113_dialog_content = "Tidak masalah dalam keadaan apa aku berada, tapi aku akan memberi tahu mereka bagaimana Aurorian bisa bertahan hidup.",
  ui_story_1020_10201301_114_dialog_content = "Aku adalah satu-satunya orang di dunia ini yang memahamimu. Tapi aku menghargai keinginanmu.",
  ui_story_1020_10201301_115_dialog_content = "Apa yang akan kamu lakukan padanya?",
  ui_story_1020_10201301_116_dialog_content = "Berikan dia apa yang dia inginkan.",
  ui_story_1020_10201301_117_dialog_content = "Selalu ada ilmuwan hebat di setiap generasi di Illumina.",
  ui_story_1020_10201301_118_dialog_content = "Tapi tanpa mereka dan prototipe, kita masih bisa bertemu di tempat lain. Kamu sudah tahu koordinatku.",
  ui_story_1020_10201301_119_dialog_content = "...",
  ui_story_1020_10201301_120_dialog_content = "Ingat, cahaya bisa menipu. Ia mencoba menutupi fakta bahwa kegelapan adalah kebenaran.",
  ui_story_1020_10201301_121_dialog_content = "Terima kegelapan, biarkan masuk, dan izinkan itu menjadi kekuatanmu.",
  ui_story_1020_10201301_122_dialog_content = "Urgh—",
  ui_story_1020_10201301_123_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10201301_124_dialog_content = "Otakmu masih utuh, PlayerName?",
  ui_story_1020_10201301_125_dialog_content = "Aku baik-baik saja! Tapi Ulysses...",
  ui_story_1020_10201301_126_dialog_content = "Hraaagh!",
  ui_story_1020_10201301_127_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10201301_128_dialog_content = "Berhenti maju, profesor, atau—",
  ui_story_1020_10201301_129_dialog_content = "<color=#e8d9bb>Klik—</color>",
  ui_story_1020_10201301_130_dialog_content = "...",
  ui_story_1020_10201301_131_dialog_content = "Kamu akan menembakku? Aku yang menciptakanmu... Semua dari kalian mengerti, 'kan?",
  ui_story_1020_10201301_132_dialog_content = "Dia berperilaku seperti Figerald!",
  ui_story_1020_10201301_133_dialog_content = "Tidak, mereka tidak sama.",
  ui_story_1020_10201301_134_dialog_content = "Ulysses tidak pernah menyerah pada kehendak Engineer, jadi dia mencoba untuk menghancurkannya... Ulysses sedang melawannya sekarang.",
  ui_story_1020_10201301_135_dialog_content = "...",
  ui_story_1020_10201301_136_dialog_content = "Apa yang harus kita lakukan dengannya, Grand Marshal?",
  ui_story_1020_10201301_137_dialog_content = "... Berhenti, Ulysses! Apakah kamu tidak mengerti?",
  ui_story_1020_10201301_138_dialog_content = "Kamu berpikir bahwa selama ini kamu telah menyelamatkan Aurorian dari Eclipse. Kamu tidak pernah menyadari bahwa kamu telah bergabung dengan mereka sejak lama!",
  ui_story_1020_10201301_139_dialog_content = "Beritahu mereka... Caelestite...",
  ui_story_1020_10201301_140_dialog_content = "10011000... Bagaimana Aurorian bisa bertahan... 00!",
  ui_story_1020_10201301_141_dialog_content = "Jangan ada yang ditahan... 12933... Sampai batas akhir... 11012... adalah... 103001111...",
  ui_story_1020_10201301_142_dialog_content = "Hanya kesempatan...",
  ui_story_1020_10201301_143_dialog_content = "01100...",
  ui_story_1020_10201301_144_dialog_content = "Tidak...",
  ui_story_1020_10201301_145_dialog_content = "Kamu istimewa... Kamu harus menghadapi takdir... dengan caramu sendiri...",
  ui_story_1020_10201301_146_dialog_content = "Tapi... 10011001X0... Tapi...",
  ui_story_1020_10201301_147_dialog_content = "Argh... Arghhhh—",
  ui_story_1020_10201301_148_dialog_content = "1001X1000... Dunia yang telah aku ubah...",
  ui_story_1020_10201301_149_dialog_content = "Pasti akan... 10102099... menjadi masa depanmu... 1X120...",
  ui_story_1020_10201301_150_dialog_content = "Bool!",
  ui_story_1020_10201301_151_dialog_content = "Jalankan kabel ke dalam tubuh Ulysses! Kita perlu menemukan antarmuka dan menghancurkan koneksi antara dia dan Engineer!",
  ui_story_1020_10201301_152_dialog_content = "Argh—",
  ui_story_1020_10201301_153_dialog_content = "Sudah terlambat…",
  ui_story_1020_10201301_154_dialog_content = "...",
  ui_story_1020_10201301_155_dialog_content = "Tidak peduli apa yang dia lakukan untuk Illumina di masa lalu, dia bukan lagi salah satu dari kita—atau seorang Aurorian, dalam hal ini.",
  ui_story_1020_10201301_156_dialog_content = "Dia telah membahayakan seluruh Kota Gannon berkali-kali dan merenggut nyawa rekan-rekannya.",
  ui_story_1020_10201301_157_dialog_content = "Sebagai Marsekal Agung dari Federasi Illumina, saya dengan ini menjatuhkan hukuman mati kepada Ulysses atas kejahatannya.",
  ui_story_1020_10201301_158_dialog_content = "Hraaagh!",
  ui_story_1020_10201301_159_dialog_content = "Bunuh dia!",
  ui_story_1020_10201402_1_dialog_content = "Bisakah kamu diselamatkan... jika aku mati?",
  ui_story_1020_10201402_2_dialog_content = "Aku hampir tidak puas dengan hasil ini, Robby...",
  ui_story_1020_10201402_3_dialog_content = "<color=#e8d9bb>Di Sanatorium Illumina Saat Perang Selama Krisis Darkover</color>",
  ui_story_1020_10201402_4_dialog_content = "Hei, sudah lama sekali, Uly.",
  ui_story_1020_10201402_5_dialog_content = "Aku tidak berharap melihatmu di sini, Robby...",
  ui_story_1020_10201402_6_dialog_content = "Bagaimana kabarmu—",
  ui_story_1020_10201402_7_dialog_content = "Ide baru apa yang sedang kamu renungkan hari ini?",
  ui_story_1020_10201402_8_dialog_content = "...",
  ui_story_1020_10201402_9_dialog_content = "Eksperimenku gagal lagi, Uly. <color=#FFB400>Undercity 77</color> hanya mengirim kembali beberapa subjek yang hangus...",
  ui_story_1020_10201402_10_dialog_content = "Mereka memainkan musik yang selalu kita dengar di lab hari ini... Oh, apa yang baru saja kamu katakan?",
  ui_story_1020_10201402_11_dialog_content = "...",
  ui_story_1020_10201402_12_dialog_content = "Saya bilang kamu masih memakai pin itu.",
  ui_story_1020_10201402_13_dialog_content = "Ya. Aku mencarinya sepanjang malam kemarin. Ternyata Sasha yang menyembunyikannya. Anak kecil yang nakal.",
  ui_story_1020_10201402_14_dialog_content = "...",
  ui_story_1020_10201402_15_dialog_content = "Dia baru saja mulai menulis puisi akhir-akhir ini. Biarkan saya membacakan satu untukmu dan lihat apa pendapatmu, Uly.",
  ui_story_1020_10201402_16_dialog_content = "Robby...",
  ui_story_1020_10201402_17_dialog_content = "Kamu lupa bagaimana kita menyelami penelitian dan petunjuk tentang Engineer.",
  ui_story_1020_10201402_18_dialog_content = "Kamu hanya ingat keluarga yang meninggal lebih awal...",
  ui_story_1020_10201402_19_dialog_content = "Sebenarnya, aku cukup senang untukmu, heheh.",
  ui_story_1020_10201402_20_dialog_content = "Jika saya tidak pernah menemukan nama Insinyur itu atau memiliki visi-visi tersebut...",
  ui_story_1020_10201402_21_dialog_content = "Jika kita masih bisa membicarakan mimpi-mimpi kita di lab seperti dulu...",
  ui_story_1020_10201402_22_dialog_content = "Hal pertama yang akan kamu katakan ketika melihatku setiap hari adalah...",
  ui_story_1020_10201402_23_dialog_content = "Apa ide baru yang sedang kau renungkan hari ini, Uly?",
  ui_story_1020_10201402_24_dialog_content = "...",
  ui_story_1020_10201402_25_dialog_content = "Uly.",
  ui_story_1020_10201402_26_dialog_content = "Ya?",
  ui_story_1020_10201402_27_dialog_content = "Apakah kamu pernah mengalami krisis iman?",
  ui_story_1020_10201402_28_dialog_content = "...",
  ui_story_1020_10201402_29_dialog_content = "Tidak.",
  ui_story_1020_10201402_30_dialog_content = "Menurutmu, mana yang lebih buruk...",
  ui_story_1020_10201402_31_dialog_content = "Krisis iman Anda atau ketidakmampuan untuk mencapai tujuan Anda?",
  ui_story_1020_10201402_32_dialog_content = "...",
  ui_story_1020_10201402_33_dialog_content = "Krisis keyakinanku atau ketidakmampuan untuk mencapai tujuanku...",
  ui_story_1020_10201402_34_dialog_content = "Mana yang lebih menyedihkan?",
  ui_story_1020_10201402_35_dialog_content = "...",
  ui_story_1020_10201501_1_dialog_content = "...Ini seperti kanvas!",
  ui_story_1020_10201501_2_dialog_content = "Ya, dan itu kanvas Minch. Coretan acak sebelum mengecat di atasnya!",
  ui_story_1020_10201501_3_dialog_content = "...Ini memiliki nuansa artistik yang unik.",
  ui_story_1020_10201501_4_dialog_content = "Apa yang Anda maksudkan?",
  ui_story_1020_10201501_5_dialog_content = "Lady Victoria tidak membawa kita semua ke sini untuk mengolok-olok saya!",
  ui_story_1020_10201501_6_dialog_content = "Oh, berbicara tentang itu, terima kasih, Lady Victoria!",
  ui_story_1020_10201501_7_dialog_content = "Terima kasih, Lady Victoria!",
  ui_story_1020_10201501_8_dialog_content = "Terima kasih, Lady Victoria!",
  ui_story_1020_10201501_9_dialog_content = "Aku tidak akan mengambil kredit untuk itu. Ini adalah berkah dari Tuhan Truth.",
  ui_story_1020_10201501_10_dialog_content = "Di mana aku?",
  ui_story_1020_10201501_11_dialog_content = "...",
  ui_story_1020_10201501_12_dialog_content = "<color=#FFB400>Sungai Pristine</color> berada di luar waktu dan ruang. Satu-satunya perbedaan antara sungai ini dan dunia luar adalah kealirannya.",
  ui_story_1020_10201501_13_dialog_content = "Bukankah kita akan kehilangan kendali atas hidup kita sendiri jika ini terus berlanjut?",
  ui_story_1020_10201501_14_dialog_content = "Mengapa Anda membawa kami ke sini?",
  ui_story_1020_10201501_15_dialog_content = "Untuk menemukan tanda yang sesuai dengan ruang waktu kita dan membiarkan Tuhan Kebenaran bergabung dengan kita.",
  ui_story_1020_10201501_16_dialog_content = "Bla bla bla...",
  ui_story_1020_10201501_17_dialog_content = "Nona Victoria, kami belum selesai dengan misi pengintaian Zona Gelap kami. Apakah Illumina benar-benar bisa mendapatkan koordinat yang kami kirim kembali dari sini?",
  ui_story_1020_10201501_18_dialog_content = "Tuhan Kebenaran mengajarkan bahwa jika ada kemauan, pasti ada jalan. Semua tergantung pada kamu.",
  ui_story_1020_10201501_19_dialog_content = "<color=#e8d9bb>Ciprat—</color>",
  ui_story_1020_10201501_20_dialog_content = "Hei, Vice, apakah kamu menjatuhkan sesuatu?",
  ui_story_1020_10201501_21_dialog_content = "Oh tidak, ini lencana Illumina ku!",
  ui_story_1020_10201501_22_dialog_content = "Apa yang harus saya lakukan sekarang? Saya tidak bisa mengambilnya kembali...",
  ui_story_1020_10201501_23_dialog_content = "Tunggu, bagaimana mungkin sebuah lencana kecil bisa menerangi seluruh sungai seperti ini?",
  ui_story_1020_10201501_24_dialog_content = "Semua tenang di ladang, namun sepenuhnya berbeda di bawah permukaan sungai.",
  ui_story_1020_10201501_25_dialog_content = "Permukaan danau... Wow, begitu dingin dan tidak terasa nyata.",
  ui_story_1020_10201501_26_dialog_content = "Permukaan danau...",
  ui_story_1020_10201501_27_dialog_content = "Kamu sudah sadar, PlayerName.",
  ui_story_1020_10201501_28_dialog_content = "Di mana aku?",
  ui_story_1020_10201501_29_dialog_content = "Carleen? Apa yang kamu... Apa yang saya lakukan di sini?",
  ui_story_1020_10201501_30_dialog_content = "Anda tidak ingat apa-apa?",
  ui_story_1020_10201501_31_dialog_content = "Saya baru saja bermimpi tentang permukaan danau yang bersinar... Tapi entah kenapa, saya tidak bisa mengingat detail apa pun...",
  ui_story_1020_10201501_32_dialog_content = "Oh, benar juga! Apakah Illumina baik-baik saja?",
  ui_story_1020_10201501_33_dialog_content = "Heh, kau pasti baik-baik saja jika bisa bicara dengan semangat seperti itu.",
  ui_story_1020_10201501_34_dialog_content = "Pulih dengan baik setelah tidur selama tiga hari penuh. Menyenangkan menjadi muda.",
  ui_story_1020_10201501_35_dialog_content = "Aku tidur selama tiga hari berturut-turut?",
  ui_story_1020_10201501_36_dialog_content = "Ya. Kapten Carleen sudah mengunjungi tiga kali.",
  ui_story_1020_10201501_37_dialog_content = "Aku merasa lebih dari itu akan mengganggu Vivian...",
  ui_story_1020_10201501_38_dialog_content = "Ini awalnya adalah <color=#FFB400>rapat bersama</color> yang diselenggarakan oleh Federasi Illumina. Maaf, kami tidak bisa menentukan waktu lebih cepat.",
  ui_story_1020_10201501_39_dialog_content = "Tapi sekarang bahwa PlayerName sudah bangun, dan Kapten Penjaga ada di sini, kenapa tidak melakukannya hari ini?",
  ui_story_1020_10201501_40_dialog_content = "Tentu, saya baik-baik saja dengan itu.",
  ui_story_1020_10201501_41_dialog_content = "Sebuah rapat bersama... Apa yang terjadi saat saya tidak ada? Dan bagaimana dengan Ulysses?",
  ui_story_1020_10201501_42_dialog_content = "Dia sudah mati. Insiden dengan Insinyur juga sudah diselesaikan untuk sementara waktu.",
  ui_story_1020_10201501_43_dialog_content = "Setelah meninjau seluruh masalah, aku bisa lebih atau kurang menebak apa yang kamu lihat di pikirannya, PlayerName.",
  ui_story_1020_10201501_44_dialog_content = "Setelah mencari di laboratoriumnya, kami menemukan sejumlah besar catatan eksperimen yang berisi informasi penting.",
  ui_story_1020_10201501_45_dialog_content = "Tapi yang paling mengejutkan saya adalah Ulysses berhasil melawan Insinyur selama ini meskipun berada dalam bidikannya.",
  ui_story_1020_10201501_46_dialog_content = "Namun, seperti yang dikatakan oleh Grand Marshal, ketika Ulysses menatap ke Dark Zone, itu malah merusak dirinya...",
  ui_story_1020_10201501_47_dialog_content = "Sebelum dia menyadarinya, dia menjadi salah satu dari Eclipse.",
  ui_story_1020_10201501_48_dialog_content = "Ya. Sepertinya krisis yang kita hadapi adalah sesuatu yang belum pernah dilihat oleh Kota Gannon dalam lebih dari enam ratus tahun.",
  ui_story_1020_10201501_49_dialog_content = "Tapi berkat kerja keras semua orang, kota kita bertahan. Kami juga tidak bisa melakukannya tanpa Dr. Algol.",
  ui_story_1020_10201501_50_dialog_content = "Jadi, di mana dia?",
  ui_story_1020_10201501_51_dialog_content = "Saya pikir Dr. Algol akan terbaring koma selama beberapa hari seperti kamu.",
  ui_story_1020_10201501_52_dialog_content = "Tetapi setelah krisis berakhir, dia melanjutkan penelitiannya seolah-olah tidak ada yang terjadi.",
  ui_story_1020_10201501_53_dialog_content = "Dia seharusnya keluar hari ini mencari bagian untuk memperbaiki Guardian One, saya pikir.",
  ui_story_1020_10201501_54_dialog_content = "Dia sudah bekerja untuk memulihkan Guardian One? Tapi Algol jarang sekali keluar.",
  ui_story_1020_10201501_55_dialog_content = "Mungkin karena dia bisa mengendarai transportasi baru Illumina.",
  ui_story_1020_10201501_56_dialog_content = "Transportasi baru Illumina? Apa maksudmu?",
  ui_story_1020_10201501_57_dialog_content = "Ulysses menghabiskan begitu banyak tahun meneliti Colossi, dan tim teknik berhasil menciptakan versi miniatur dari mereka berdasarkan penelitiannya.",
  ui_story_1020_10201501_58_dialog_content = "Kendaraan skala kecil ini membantu kami mengevakuasi banyak warga kami selama insiden itu. Kami juga akan menggunakannya untuk ekspedisi gabungan yang akan datang.",
  ui_story_1020_10201501_59_dialog_content = "...",
  ui_story_1020_10201501_60_option_content = "Ulysses...",
  ui_story_1020_10201501_61_option_content = "Kendaraan skala kecil...",
  ui_story_1020_10201501_62_dialog_content = "Apakah kalian benar-benar akan melanjutkan penelitian dia?",
  ui_story_1020_10201501_63_dialog_content = "Aku tahu apa yang kaucemaskan.",
  ui_story_1020_10201501_64_dialog_content = "Ini bukan hanya tentang kendaraan kecil ini, tetapi juga Aurorian seperti Sean yang mampu menjelajahi Dark Zone juga.",
  ui_story_1020_10201501_65_dialog_content = "Faktanya adalah bahwa semua ini tidak akan mungkin terjadi tanpa penelitian Ulysses.",
  ui_story_1020_10201501_66_dialog_content = "Saya yakin bahwa membuat keputusan ini tidak kalah sulitnya dengan memilih untuk memberikan otoritas penelitian penuh kepada Sistem Guardian selama Krisis Darkover.",
  ui_story_1020_10201501_67_dialog_content = "Tapi kali ini, meskipun Dewan Sains dan semua ilmuwan terkemuka kami di Lab Penelitian telah memiliki kesempatan untuk mengevaluasi dan memilih penelitian dia...",
  ui_story_1020_10201501_68_dialog_content = "Mereka semua masih terbagi tentang apakah menyetujui itu atau tidak.",
  ui_story_1020_10201501_69_dialog_content = "Sejauh yang saya ketahui, melindungi kehidupan Federasi Illumina adalah prioritas terpenting kita.",
  ui_story_1020_10201501_70_dialog_content = "Apakah itu berarti kamu menentang penggunaan penelitiannya?",
  ui_story_1020_10201501_71_dialog_content = "Justru sebaliknya, sebenarnya.",
  ui_story_1020_10201501_72_dialog_content = "Bagian dari memastikan kelangsungan hidup kita adalah dengan mengambil risiko kecil yang telah dihitung. Kita perlu sepenuhnya menyadari risiko tersebut, serta bagaimana cara memanfaatkan mereka sebaik-baiknya.",
  ui_story_1020_10201501_73_dialog_content = "Kita harus terus mempelajari musuh kita dan menguji batas kita jika kita ingin meningkatkan kondisi bertahan hidup untuk semua Aurorian.",
  ui_story_1020_10201501_74_dialog_content = "Apakah itu sebabnya kamu mengadakan ekspedisi bersama ini? Tunggu... Apakah itu berarti Lumopolis juga dalam bahaya?",
  ui_story_1020_10201501_75_dialog_content = "Lumopolis tidak pernah dalam bahaya, tetapi banyak peninggalan menunjukkan pola Lumina yang kacau, yang menarik perhatian Lord Kota.",
  ui_story_1020_10201501_76_dialog_content = "Setelah apa yang terjadi di Kota Gannon, Komite bersedia untuk menjelajahi lebih banyak jalur kerjasama tentang ekspedisi gabungan dengan faksi-faksi lain.",
  ui_story_1020_10201501_77_dialog_content = "Carleen telah setuju untuk menjadi kapten dari Tim Ekspedisi Lumopolis. Seiring waktu, Northland dan Umbraton juga akan mengirimkan perwakilan mereka sendiri ke sini.",
  ui_story_1020_10201501_78_dialog_content = "Oh, Grand Marshal, para pengacau di Gurun Rediesel pasti sudah mendengar berita itu dari suatu tempat, dan saya mendapatkan pesan bahwa mereka ingin menjadi bagian dari itu.",
  ui_story_1020_10201501_79_dialog_content = "Saya ingin tahu pendapatmu tentang ini, PlayerName.",
  ui_story_1020_10201501_80_dialog_content = "Pikiran saya...",
  ui_story_1020_10201501_81_dialog_content = "Di masa lalu, aku tidak pernah benar-benar mengambil inisiatif untuk mencari apa pun. Aku hanya membiarkan jejak-jejak Caelestite memandu jalanku.",
  ui_story_1020_10201501_82_dialog_content = "Tapi saat memperbaiki Soroz, saya menyadari bahwa tidak semua jejak itu mengarah ke hal-hal yang baik...",
  ui_story_1020_10201501_83_dialog_content = "Aku bahkan tidak tahu apakah aku orang baik atau tidak...",
  ui_story_1020_10201501_84_dialog_content = "Tapi setelah apa yang saya alami dengan Vice dan Soroz, perasaan terkejut yang menyenangkan dari hal yang tidak terduga benar-benar menghilang.",
  ui_story_1020_10201501_85_dialog_content = "Dan karena aku kehilangannya, aku harus mendapatkannya kembali... secepat mungkin.",
  ui_story_1020_10201501_86_dialog_content = "Itu mengingatkan saya... Akhir-akhir ini, rasanya seperti saya melihat ke masa lalu, meskipun mungkin itu adalah masa depan...",
  ui_story_1020_10201501_87_dialog_content = "Bagaimanapun juga, ada tempat yang perlu saya selidiki.",
  ui_story_1020_10201501_88_dialog_content = "Mungkin itu adalah Zona Gelap, atau tempat yang lebih jauh dan tidak dapat dijangkau.",
  ui_story_1020_10201501_89_dialog_content = "Mengapa aku merasakan ini seperti takdir?",
  ui_story_1020_10201501_90_dialog_content = "Begitu ya? Nah, seorang teman dari timur pernah membaca ramalan saya dan mengatakan bahwa takdir saya tidak persis \"dalam daftar\"...",
  ui_story_1020_10201501_91_dialog_content = "Caelestite mampu membebaskan diri dari belenggu bawaan, itulah sebabnya saya tidak percaya pada takdir.",
  ui_story_1020_10201501_92_dialog_content = "Dengan tekad, keberanian, dan kebijaksanaan, kamu pasti akan mendapatkan kembali apa yang telah hilang.",
  ui_story_1020_10201501_93_dialog_content = "Tentu!",
  ui_story_1020_10201501_94_dialog_content = "Saya senang Anda berpikir seperti ini.",
  ui_story_1020_10201501_95_dialog_content = "Sebagai Grand Marshal Federasi Illumina, saya memiliki tanggung jawab untuk menemukan dan mengambil kembali rekan-rekan saya—tentu saja, itu termasuk Charon, Vice, dan rekan satu skuad mereka.",
  ui_story_1020_10201501_96_dialog_content = "Jika Anda memilih untuk menerima, Illumina Federation bersedia membantu Anda dalam menjelajahi Zona Gelap dan mencari Soroz.",
  ui_story_1020_10201501_97_dialog_content = "Ya. Kamu adalah alasan mengapa Lumopolis bergabung dalam ekspedisi ini.",
  ui_story_1020_10201501_98_dialog_content = "Terimakasih semuanya...",
  ui_story_1020_10201501_99_dialog_content = "Karena aku memiliki kepercayaan dan dukungan dari semua orang, aku pasti harus menjadi bagian dari ekspedisi bersama ini!",
  ui_story_1020_10201501_100_dialog_content = "Tapi kita harus mulai dari mana?",
  ui_story_1020_10201501_101_dialog_content = "Sejujurnya, ada cukup banyak tempat untuk dipilih.",
  ui_story_1020_10201501_102_dialog_content = "Tempat apa itu?",
  ui_story_1020_10201501_103_dialog_content = "Memoar Helios.",
  ui_story_1020_10201501_104_dialog_content = "Buku yang besar... Dan sudah selesai? Chandra benar-benar seperti kilat.",
  ui_story_1020_10201501_105_dialog_content = "Setelah semua, hari itu panjang dan semua orang bekerja keras meskipun ada tamu tak terduga yang menghambat kami.",
  ui_story_1020_10201501_106_dialog_content = "Saya lihat kamu baik-baik saja, jadi mungkin sekarang aku bisa tidur nyenyak.",
  ui_story_1020_10201501_107_dialog_content = "Oh, apa itu tentang permukaan danau yang bersinar dalam mimpimu, PlayerName?",
  ui_story_1020_10201501_108_dialog_content = "Ya... Aku melihat permukaan danau yang bersinar...",
  ui_story_1020_10201501_109_dialog_content = "Dan juga sebuah lencana yang terlihat sangat familiar...",
  ui_story_1020_10201501_110_dialog_content = "Bisakah kalian memikirkan sesuatu seperti itu?",
  ui_story_1020_10201501_111_dialog_content = "Ketika aku ditelan oleh kegelapan, tiba-tiba aku mendengar suara piano. Setelah itu, cahaya mulai berdatangan...",
  ui_story_1020_10201501_112_dialog_content = "<color=#e8d9bb>Ciprat—</color>",
  ui_story_1020_10201501_113_dialog_content = "Apakah kalian mendengar musik itu, semua orang?",
  ui_story_1020_10201501_114_dialog_content = "Aku mendengarnya!",
  ui_story_1020_10201501_115_dialog_content = "Apa?",
  ui_story_1020_10201501_116_dialog_content = "Yah, ia berhenti setelah Merry berteriak keras-keras.",
  ui_story_1020_10201501_117_dialog_content = "Puji Tuhan Kebenaran!",
  ui_story_1020_10201501_118_dialog_content = "Kamu telah menemukan tanda itu, Nona Vice. Tolong tunjukkan kami dengan cara Anda sendiri.",
  ui_story_1020_10201501_119_dialog_content = "Aku?",
  ui_story_1020_10201501_120_dialog_content = "Ketika kamu dan Caelestite mengaktifkan Colossus, sungai yang tertidur ini terbangun.",
  ui_story_1020_10201501_121_dialog_content = "Sejak saat itu, kamu telah membuka lembaran baru dalam sejarah Eoria.",
  ui_story_1020_10201501_122_dialog_content = "Tolong bimbing kami lagi dengan cara Anda sendiri.",
  ui_story_1020_10201501_123_dialog_content = "Tolong bimbing kami lagi dengan cara Anda sendiri.",
  ui_story_1020_10201501_124_dialog_content = "?",
  ui_story_1020_10201501_125_dialog_content = "...",
  ui_story_1020_10201501_126_dialog_content = "Jangan bilang…",
  ui_story_1020_10201501_127_dialog_content = "Yang seperti piano ini pasti panel kontrol Colossus, 'kan?",
  ui_story_1020_10201501_128_dialog_content = "Biar kubantu kau menyalakan Colossus ini, Navigator.",
  ui_story_1020_10201501_129_dialog_content = "Bersamaku? Kau ini Aurorian, Vice. Kau tak punya kemampuan psikis.",
  ui_story_1020_10201501_130_dialog_content = "Tapi, aku bisa jadi kekuatanmu. Aku... bisa membantu.",
  ui_story_1020_10201501_131_dialog_content = "?",
  ui_story_1020_10201501_132_dialog_content = "Percayalah padaku, PlayerName. Aku dan kau… Sebenarnya kita tidak jauh berbeda.",
  ui_story_1020_10201501_133_dialog_content = "Ceritanya panjang. Akan kuceritakan lain kali kalau aku punya kesempatan!",
  ui_story_1020_10201501_134_dialog_content = "Biar kutunjukkan cara \"memainkan\"nya…",
  ui_story_1020_10201501_135_dialog_content = "Apa yang dikatakan oleh Nona Victoria mengingatkan saya pada beberapa hal...",
  ui_story_1020_10201501_136_dialog_content = "...",
  ui_story_1020_10201501_137_dialog_content = "Sederhana sekali. Sama seperti memainkan piano.",
  ui_story_1020_10201501_138_dialog_content = "...",
  ui_story_1020_10201501_139_dialog_content = "Tapi di sini tidak ada partitur! Bisa kautunjukkan tuts mana yang harus kutekan?",
  ui_story_1020_10201501_140_dialog_content = "...",
  ui_story_1020_10201501_141_dialog_content = "Aku bisa merasakan… energinya mengalir.",
  ui_story_1020_10201501_142_dialog_content = "Ya. Rasanya seperti sedang berbincang, walau aku tak paham bahasa Colossus.",
  ui_story_1020_10201501_143_dialog_content = "Bahasa itu ada di dalam tuts piano.",
  ui_story_1020_10201501_144_dialog_content = "Ayo selesaikan perintah aktivasi, Vice.",
  ui_story_1020_10201501_145_dialog_content = "...",
  ui_story_1020_10201501_146_dialog_content = "Jika ini cara untuk membimbingmu, aku tahu apa yang harus kulakukan sekarang.",
  ui_story_1020_10201501_147_dialog_content = "Dengar, teman-teman! Itu suara piano yang sedang dimainkan!",
  ui_story_1020_10201501_148_dialog_content = "Sungai yang berkilauan dalam cahaya misterius adalah tempat suci Tuhan.",
  ui_story_1020_10201501_149_dialog_content = "Dia mendengarkan melodi yang penuh teka-teki dan mengungkapkan kebenaran yang tak terbatas.",
  ui_story_1020_10201501_150_dialog_content = "May Tuhan Kebenaran menyaksikan penjelajahan kita, berjalan bersama kita, dan datanglah.",
  ui_story_1021_10210100_1_dialog_content = "<color=#e8d9bb>Banyak tahun yang lalu di dekat perbatasan Northland...</color>",
  ui_story_1021_10210100_2_dialog_content = "Anda akan keluar dari wilayah Northland setelah menyeberangi bukit di depan, Yang Mulia.",
  ui_story_1021_10210100_3_dialog_content = "...",
  ui_story_1021_10210100_4_dialog_content = "Tundra memiliki rentang yang luas. Masih ada orang-orang Northland yang tinggal di sisi lain.",
  ui_story_1021_10210100_5_dialog_content = "Anda harus kembali sekarang, Pak Novio. Ini adalah sesuatu yang ingin saya lakukan.",
  ui_story_1021_10210100_6_dialog_content = "Para raja dan ratu terdahulu, serta daratan salju yang luas dan tak berbatas, akan mengingat segala yang telah kamu lakukan untuk Northland.",
  ui_story_1021_10210100_7_dialog_content = "Kekuatan untuk mempertahankan Northland bukan berasal dari diriku, tetapi dari tanah itu sendiri.",
  ui_story_1021_10210100_8_dialog_content = "Untuk itu, saya tidak akan mengecewakan pendahuluku.",
  ui_story_1021_10210100_9_dialog_content = "Demi Utara, kita hidup untuk mempertahankan tanah ini.",
  ui_story_1021_10210100_10_dialog_content = "<color=#e8d9bb>Berdesir-</color>",
  ui_story_1021_10210100_11_dialog_content = "Salju berhenti turun, aku lihat.",
  ui_story_1021_10210100_12_dialog_content = "Aku tidak ingat cuaca yang begitu menyenangkan di hutan ini...",
  ui_story_1021_10210100_13_dialog_content = "Ha.",
  ui_story_1021_10210100_14_dialog_content = "Hah?",
  ui_story_1021_10210100_15_dialog_content = "Aku memperingatkanmu, orang asing. Pergi sekarang atau hadapi kemarahan Chief Tiare!",
  ui_story_1021_10210100_16_dialog_content = "Kamu Tiare?",
  ui_story_1021_10210100_17_dialog_content = "Bagaimana Anda tahu nama saya?",
  ui_story_1021_10210100_18_dialog_content = "Ahem... Meskipun entah bagaimana kamu mengetahui namaku, aku tidak akan pernah membiarkanmu menginjakkan kaki di pemukiman Suku Fox Salju!",
  ui_story_1021_10210100_19_dialog_content = "Kamu dari Suku Fox Salju? Di mana orang tuamu?",
  ui_story_1021_10210100_20_dialog_content = "Mereka berdua sibuk melindungi Northland! Sekarang berhenti berkelit dan katakan padaku apa yang sedang kamu lakukan di sini!",
  ui_story_1021_10210100_21_dialog_content = "Tiare, datang dan lihat apa yang dibawa nenek untukmu!",
  ui_story_1021_10210100_22_dialog_content = "Wow, itu ranting beraroma favoritku!",
  ui_story_1021_10210100_23_dialog_content = "Sekarang katakan padaku, kenapa kamu tidak di altar tetapi malah berbuat tidak baik di sini?",
  ui_story_1021_10210100_24_dialog_content = "Yah... Orang tua itu mengatakan itu bukan tempat untuk anak-anak...",
  ui_story_1021_10210100_25_dialog_content = "Saya lihat rubah tua itu mulai pikun sekarang.",
  ui_story_1021_10210100_26_dialog_content = "Nenek, aku melakukan sesuatu yang hebat hari ini! Lihat, aku menjaga orang asing ini keluar dari pemukiman kita!",
  ui_story_1021_10210100_27_dialog_content = "...",
  ui_story_1021_10210100_28_dialog_content = "Sangat baik, Tiare!",
  ui_story_1021_10210100_29_dialog_content = "Sekarang, apakah kamu masih ingat legenda tentang Tiga Pohon Pinus?",
  ui_story_1021_10210100_30_dialog_content = "Aku bersedia!",
  ui_story_1021_10210100_31_dialog_content = "Dia sangat pintar dan tidak perlu kamu mengulangi mitos itu kepadanya lagi.",
  ui_story_1021_10210100_32_dialog_content = "Jika aku tidak melakukannya, tak ada yang akan ingat, dan tak akan lama sebelum dia mulai belajar dan menceritakan kisah orang lain.",
  ui_story_1021_10210100_33_dialog_content = "...",
  ui_story_1021_10210100_34_dialog_content = "Saya adalah Bethlehem. Senang bertemu dengan kalian berdua.",
  ui_story_1021_10210100_35_dialog_content = "Terima kasih kepada leluhurmu yang telah melindungi Northland. Saya akan pamit sekarang.",
  ui_story_1021_10210100_36_dialog_content = "...",
  ui_story_1021_10210100_37_dialog_content = "<color=#e8d9bb>Berdesir-</color>",
  ui_story_1021_10210100_38_dialog_content = "Kamu menyebutkan bahwa cahaya dari Beacon akan sampai di sini.",
  ui_story_1021_10210100_39_dialog_content = "...",
  ui_story_1021_10210100_40_dialog_content = "Suku ini belum mendengar tangisan bayi baru lahir selama bertahun-tahun sekarang.",
  ui_story_1021_10210100_41_dialog_content = "Saya berterima kasih atas setiap penjaga yang dihasilkan oleh Suku Fox Salju.",
  ui_story_1021_10210100_42_dialog_content = "Anak-anak itu tidak lahir di istana yang megah tetapi di hutan yang bisa diserbu oleh Eclipsites kapan saja.",
  ui_story_1021_10210100_43_dialog_content = "Dari generasi ke generasi, leluhur mereka mati dan dikubur di sini untuk melindungi Northland.",
  ui_story_1021_10210100_44_dialog_content = "Aku bisa membawanya kembali ke Winter Palace.",
  ui_story_1021_10210100_45_dialog_content = "Jika Eclipsite menghancurkan Northland, apakah kamu akan pergi ke tempat lain?",
  ui_story_1021_10210100_46_dialog_content = "Tak akan pernah.",
  ui_story_1021_10210100_47_dialog_content = "Northland telah membesarkan dan melindungi kita. Kita harus melindunginya sebagai balasan, sepanjang generasi.",
  ui_story_1021_10210100_48_dialog_content = "Mengapa aku jadi teringat apa yang terjadi hari itu...",
  ui_story_1021_10210100_49_dialog_content = "Iklim di sepanjang perbatasan telah mengalami perubahan yang tidak biasa, Yang Mulia, dan cahaya Beacon telah berubah sedikit.",
  ui_story_1021_10210100_50_dialog_content = "Semua ini bukanlah kebetulan... Aku sudah mengantisipasinya.",
  ui_story_1021_10210100_51_dialog_content = "Seperti yang kamu duga, krisis di Illumina sebelumnya bukanlah insiden yang terisolasi, dan pembangunan pos-pos tidak berjalan dengan lancar...",
  ui_story_1021_10210100_52_dialog_content = "Kita harus memantau Dark Zone dengan seksama.",
  ui_story_1021_10210100_53_dialog_content = "Sangat penting untuk meluncurkan ekspedisi bersama karena ini sangat penting untuk masa depan semua Aurorian. Selain itu, kita hanya beberapa hari lagi menuju pertemuan bersama.",
  ui_story_1021_10210100_54_dialog_content = "Aku akan pergi melihatnya.",
  ui_story_1021_10210100_55_dialog_content = "Sekarang?",
  ui_story_1021_10210100_56_dialog_content = "Ya. Apakah kamu pernah melihat Tiare?",
  ui_story_1021_10210100_57_dialog_content = "Dia memiliki—",
  ui_story_1021_10210100_58_dialog_content = "Apakah Anda akan keluar, Yang Mulia? Izinkan saya menemani Anda.",
  ui_story_1021_10210100_59_dialog_content = "...",
  ui_story_1021_10210100_60_dialog_content = "Aku akan pergi sendiri selama beberapa hari. Novio bertanggung jawab atas Winter Palace sementara waktu. Aku harap kamu bisa tetap tajam dan siap selama aku pergi.",
  ui_story_1021_10210100_61_dialog_content = "Ya, Yang Mulia!",
  ui_story_1021_10210100_62_dialog_content = "(Mengapa sang Ratu terburu-buru?)",
  ui_story_1021_10210100_63_dialog_content = "Jejak kaki di ambang jendela itu harus dihapus.",
  ui_story_1021_10210100_64_dialog_content = "Tentu!",
  ui_story_1021_10210100_65_dialog_content = "<color=#e8d9bb>Awoo!</color>",
  ui_story_1021_10210100_66_dialog_content = "...",
  ui_story_1021_10210100_67_dialog_content = "Saya tidak bisa percaya masih belum ada respon...",
  ui_story_1021_10210100_68_dialog_content = "Yang Mulia Ratu telah pergi selama beberapa hari sekarang.",
  ui_story_1021_10210100_69_dialog_content = "Jika saya, sebagai penjaganya, tidak bisa berada di sisinya, bagaimana saya bisa tetap waspada dan siap?",
  ui_story_1021_10210100_70_dialog_content = "<color=#e8d9bb>Awoo!</color>",
  ui_story_1021_10210100_71_dialog_content = "Kalian rupanya.",
  ui_story_1021_10210100_72_dialog_content = "Huu-huu...",
  ui_story_1021_10210100_73_dialog_content = "Apa?",
  ui_story_1021_10210100_74_dialog_content = "Auuu!",
  ui_story_1021_10210100_75_dialog_content = "Bagaimana itu bisa terjadi?",
  ui_story_1021_10210100_76_dialog_content = "Saya kembali tepat sebelum ratu meninggalkan istana. Saya dan si tua bahkan menikmati panen tahun ini...",
  ui_story_1021_10210100_77_dialog_content = "Tapi sebagai pengawal Yang Mulia Ratu, sepertinya aku tidak bisa—",
  ui_story_1021_10210100_78_dialog_content = "Awooooooo!",
  ui_story_1021_10210100_79_dialog_content = "Mengerti! Aku akan kembali denganmu sekarang!",
  ui_story_1021_10210100_80_dialog_content = "Rubah salju! Itu rubah salju!",
  ui_story_1021_10210100_81_dialog_content = "Kamu mengganggu kuliah Tuan Antony lagi! Di mana kamu melihat rubah salju?",
  ui_story_1021_10210100_82_dialog_content = "Ayo, itu hanya kelinci yang sedang melompat-lompat!",
  ui_story_1021_10210100_83_dialog_content = "Tapi aku benar-benar melihatnya... Itu tampak persis seperti rubah salju di buku itu!",
  ui_story_1021_10210100_84_dialog_content = "Aku akui memang aneh melihat rubah salju di kota... Kamu percaya padaku, kan? Pak Antony?",
  ui_story_1021_10210100_85_dialog_content = "Dikatakan sebelum Northland disebut Northland, rubah salju berteman dengan beberapa Aurorian dan melindungi habitat mereka bersama-sama.",
  ui_story_1021_10210100_86_dialog_content = "Apakah masih ada rubah salju yang tersisa di Northland sekarang?",
  ui_story_1021_10210100_87_dialog_content = "Saya percaya begitu. Mereka cerdas dan abstrak. Beberapa konon telah hidup selama ratusan—bahkan ribuan—tahun...",
  ui_story_1021_10210100_88_dialog_content = "Ribuan? Seberapa tua mereka?",
  ui_story_1021_10210100_89_dialog_content = "Jauh lebih tua dari pohon snowpine tertua di Northland. Apakah kamu ingat cerita tentang Tiga Pohon Pinus yang pernah aku ceritakan sebelumnya?",
  ui_story_1021_10210100_90_dialog_content = "Kami lakukan!",
  ui_story_1021_10210100_91_dialog_content = "Sebelum Northland menjadi Northland yang kita kenal, ada tiga pohon snowpine besar yang membayangkan melindungi tanah ini...",
  ui_story_1021_10210100_92_dialog_content = "Namun semua makhluk lainnya mengejek mereka. Bagaimana mungkin pohon snowpine biasa bisa melindungi seluruh Northland?",
  ui_story_1021_10210100_93_dialog_content = "Kemudian, penebang kayu menebang ketiga pohon tersebut di kemudian hari dalam perang.",
  ui_story_1021_10210100_94_dialog_content = "Salah satunya digunakan untuk membangun gudang stok...",
  ui_story_1021_10210100_95_dialog_content = "Salah satunya dijadikan meja dan dijual ke sebuah keluarga miskin...",
  ui_story_1021_10210100_96_dialog_content = "Tidak ada yang menginginkan yang ketiga, jadi itu disimpan di gudang dan tidak pernah melihat matahari lagi.",
  ui_story_1021_10210100_97_dialog_content = "Banyak tahun kemudian, seorang wanita yang sedang hamil melahirkan seorang anak kecil di kandang itu...",
  ui_story_1021_10210100_98_dialog_content = "Bayi yang lahir di tumpukan jerami itu adalah Queen pertama kita dari Utara!",
  ui_story_1021_10210100_99_dialog_content = "Banyak tahun kemudian, ratu membantu keluarga miskin itu.",
  ui_story_1021_10210100_100_dialog_content = "Di meja itu, keempat saudara yang tak punya uang itu bersumpah di hadapan ratu bahwa mereka akan melindungi keluarga kerajaan selama beberapa generasi.",
  ui_story_1021_10210100_101_dialog_content = "Begitulah cara keturunan mereka mengambil alih peran sebagai Pengawal Kerajaan Northland!",
  ui_story_1021_10210100_102_dialog_content = "Ups. Maaf, Pak Antony, aku lupa cerita tentang pohon terakhir...",
  ui_story_1021_10210100_103_dialog_content = "Kemudian, sang ratu menemukan pohon itu di gudang dan membuat tongkat kerajaan darinya.",
  ui_story_1021_10210100_104_dialog_content = "Tongkat kerajaan itu dapat memanggil semua makhluk di Northland untuk mempertahankan wilayahnya.",
  ui_story_1021_10210100_105_dialog_content = "Pohon Snowpine adalah malaikat penjaga kami. Hanya dengan mereka, kita dapat menjamin keamanan dan kedamaian di tanah air kita untuk generasi yang akan datang.",
  ui_story_1021_10210100_106_dialog_content = "...",
  ui_story_1021_10210100_107_dialog_content = "Bagaimana ini bisa terjadi...",
  ui_story_1021_10210100_108_dialog_content = "Rubah-rubah itu... Yang tertua... Apa yang terjadi di sini?",
  ui_story_1021_10210100_109_dialog_content = "...",
  ui_story_1021_10210100_110_dialog_content = "<color=#e8d9bb>Awoooo!</color>",
  ui_story_1021_10210201_1_dialog_content = "<color=#e8d9bb>Perintah Sementara, Komite Ekspedisi Bersama Astra</color>",
  ui_story_1021_10210201_2_dialog_content = "Sudah lama, PlayerName!",
  ui_story_1021_10210201_3_dialog_content = "Memang, Wendy. Kamu selalu tepat waktu seperti biasanya!",
  ui_story_1021_10210201_4_dialog_content = "Ini macet! Syal ini hanya menimbulkan masalah...",
  ui_story_1021_10210201_5_dialog_content = "Hei, Pepi juga tepat waktu! Di mana protegemu Tweety?",
  ui_story_1021_10210201_6_dialog_content = "Sejujurnya, saya tidak terlalu mengaguminya. Dia masih memiliki jalan panjang untuk menjadi kurir yang berkualitas.",
  ui_story_1021_10210201_7_dialog_content = "Dia berteriak, \"Aku akan ada di sini!\" setiap kali kamu memaksanya, tapi siapa tahu di mana dia mungkin berada, mengambil surat-surat yang dia lewatkan!",
  ui_story_1021_10210201_8_dialog_content = "Meski sebagai mentor, saya harus menoleransi ketidak sabarannya, kecerobohannya, dan kadang-kadang ketidak bertanggung jawabannya...",
  ui_story_1021_10210201_9_dialog_content = "Sepertinya dia telah mengambil beberapa hal itu darimu... Tunggu sebentar, itu terdengar seperti kamu sedang mendeskripsikan dirimu sendiri, sebenarnya...",
  ui_story_1021_10210201_10_dialog_content = "Setidaknya dia punya aku untuk menjaganya!",
  ui_story_1021_10210201_11_dialog_content = "Tapi siapa yang menjaga saya? Saya baru saja kembali dari liburan, dan Vivian mengirim saya untuk memeriksa pos ekspedisi gabungan di Twilight.",
  ui_story_1021_10210201_12_dialog_content = "Apa sebenarnya tempat terlantar seperti Twilight ini? Badai pasirnya suram, penuh dengan Darkflow, dan ada di mana-mana.",
  ui_story_1021_10210201_13_dialog_content = "Ini membuat saya merasa pusing sepanjang hari dan terlalu lamban untuk menyelesaikan pekerjaan...",
  ui_story_1021_10210201_14_dialog_content = "Urgh! Tidak bisa fokus satu menit pun... Aku harus mencari pekerjaan baru bulan depan.",
  ui_story_1021_10210201_15_option_content = "Ada kamu, Vivian!",
  ui_story_1021_10210201_16_dialog_content = "!",
  ui_story_1021_10210201_17_dialog_content = "Meskipun itu yang selalu dikeluhkan oleh rekan-rekan kerjaku, aku mendorong dan mengingatkan mereka bahwa Lady Vivian sebenarnya memperlakukan kita cukup baik!",
  ui_story_1021_10210201_18_dialog_content = "Penjadwalannya masuk akal dengan bayaran yang baik. Kamu juga bisa berkembang seiring berjalannya berbagai tugas. Di mana lagi kamu bisa menemukan pekerjaan hebat seperti ini?",
  ui_story_1021_10210201_19_dialog_content = "Wow, kamu benar-benar berbalik arah dengan sangat cepat.",
  ui_story_1021_10210201_20_option_content = "Selamat datang di Tim Ekspedisi Zona Gelap.",
  ui_story_1021_10210201_21_dialog_content = "Zona Gelap? Saya keluar dari sini. Dibandingkan dengan itu, pekerjaan kurir sepuluh ribu kali lebih baik.",
  ui_story_1021_10210201_22_dialog_content = "Pikirkanlah... Saya bisa menjadwalkan pengiriman sesuai keinginan saya, dan tidak hanya bebas bergerak, tetapi juga tidak ada risiko kehilangan pekerjaan...",
  ui_story_1021_10210201_23_dialog_content = "Jadi, saya menghargai tawaran itu, tapi saya akan tetap... uh, menjadi kurir yang baik!",
  ui_story_1021_10210201_24_dialog_content = "Saya rasa saya berhak meminta insentif dari Vivian karena saya telah membuatmu tetap di sini...",
  ui_story_1021_10210201_25_dialog_content = "Saatnya rapat, Grand Marshal, tapi perwakilan dari Northland masih belum hadir.",
  ui_story_1021_10210201_26_dialog_content = "Saya menerima pesan dari Northland pagi ini. Kita bisa melanjutkan seperti biasa.",
  ui_story_1021_10210201_27_dialog_content = "Baik, Grand Marshal.",
  ui_story_1021_10210201_28_dialog_content = "Wakil yang terhormat, terima kasih telah menghadiri pertemuan pertama Konferensi Ekspedisi Gabungan Astra.",
  ui_story_1021_10210201_29_dialog_content = "Saya adalah Vivian, Kepala Staf Federasi Illumina. Jika tidak ada keberatan, kita akan mulai.",
  ui_story_1021_10210201_30_dialog_content = "Tidak ada dari saya.",
  ui_story_1021_10210201_31_dialog_content = "Sebagai wakil dari Shadowlord, saya tidak memiliki keberatan.",
  ui_story_1021_10210201_32_dialog_content = "Saya tidak melihat pilihan lain selain memulai dalam kasus ini.",
  ui_story_1021_10210201_33_dialog_content = "Mari kita mulai pertemuan secara resmi.",
  ui_story_1021_10210201_34_dialog_content = "Kami memilih lokasi terbuka ini dengan harapan bahwa kita dapat mencapai kesepakatan tentang masa depan Aurorian bersama.",
  ui_story_1021_10210201_35_dialog_content = "Pertama-tama, saya ingin mengucapkan terima kasih kepada Courier Union atas kontribusi mereka selama pembangunan pos luar.",
  ui_story_1021_10210201_36_dialog_content = "Untuk memastikan semua faksi dapat merespon operasi Tim Ekspedisi Zona Gelap secara tepat waktu, Courier Union akan memberikan dukungan di berbagai area...",
  ui_story_1021_10210201_37_dialog_content = "Termasuk penyebaran informasi antara pos-pos dan pelaporan petunjuk terkait Zona Gelap. Serikat Kurir akan mengambil tugas vital dalam pemantauan dan validasi.",
  ui_story_1021_10210201_38_dialog_content = "Ya! Courier Union selalu berhasil mengantarkan!",
  ui_story_1021_10210201_39_dialog_content = "Sekarang, Marsekal Agung dari Federasi Illumina akan mempresentasikan rencana untuk ekspedisi bersama dan meminta masukan dari Anda.",
  ui_story_1021_10210201_40_dialog_content = "Mengenai rute, hal tersebut telah disebutkan dalam korespondensi kita sebelumnya...",
  ui_story_1021_10210201_41_dialog_content = "Kami berencana untuk membangun beberapa <color=#FFB400>pos</color> di dekat Dark Zone untuk memudahkan dukungan dan pengintaian.",
  ui_story_1021_10210201_42_dialog_content = "Berdasarkan lokasi geografis dari berbagai faksi, kami akan mendirikan <color=#FFB400>tiga pos luar</color> di Astra utara.",
  ui_story_1021_10210201_43_dialog_content = "Yang pertama berada di <color=#FFB400>Twilight</color> ke barat laut. Skala dan keuntungan saat ini membuatnya menjadi basis cadangan yang sangat cocok untuk Tim Ekspedisi Dark Zone.",
  ui_story_1021_10210201_44_dialog_content = "Penguasa Kota Lumopolis dan saya telah mencapai kesepakatan tentang pemerintahan bersama di Twilight. Pembangunan pos luar resmi di sana adalah bukti dari konsensus kami.",
  ui_story_1021_10210201_45_dialog_content = "Sebuah komando strategis akan didirikan di Twilight untuk memberikan dukungan yang diperlukan bagi Tim Ekspedisi.",
  ui_story_1021_10210201_46_dialog_content = "Leo akan bertanggung jawab atas pos luar dan memperbarui markas besar tentang kemajuan secara teratur.",
  ui_story_1021_10210201_47_dialog_content = "Dua lainnya akan menjadi <color=#FFB400>Pos Luar Eraveil</color> dan <color=#FFB400>Pos Luar Northland</color>.",
  ui_story_1021_10210201_48_dialog_content = "Kami saat ini sedang mengevaluasi kelayakan Pos Eraveil, dengan mempertimbangkan dampak dari reruntuhan bawah tanah setempat.",
  ui_story_1021_10210201_49_dialog_content = "Pembangunan Outpost Northland akan berlangsung lama karena lingkungan yang unik. Saya akan membuat pengumuman setelah saya mendapatkan konfirmasi dari Queen dari Utara.",
  ui_story_1021_10210201_50_dialog_content = "Terakhir, saya ingin menjelaskan satu hal.",
  ui_story_1021_10210201_51_dialog_content = "Rute dan koordinat untuk ekspedisi adalah hasil dari upaya antara Dr. Algol dari Illumina Federation dan seorang petugas intelijen.",
  ui_story_1021_10210201_52_dialog_content = "Semua informasi telah divalidasi berkali-kali untuk menjamin keamanan dan akurasi. Kami akan membagikannya dengan semua orang di sini untuk tujuan partisipasi bersama dan perlindungan.",
  ui_story_1021_10210201_53_dialog_content = "Anda dapat mengajukan pertanyaan mengenai informasi yang telah disebutkan sebelumnya.",
  ui_story_1021_10210201_54_dialog_content = "Saya mengerti bahwa Illumina telah membayar mahal untuk mendapatkan data tentang Zona Gelap.",
  ui_story_1021_10210201_55_dialog_content = "Namun, tidak ada kekurangan orang-orang ambisius di Federasi Illumina, dan ini tentang masa depan Aurorian. Haruskah kamu sendiri yang menentukan daftar ekspedisi?",
  ui_story_1021_10210201_56_dialog_content = "Tentu saja. Di Illumina, kami tidak menilai individu berdasarkan ambisi mereka, tetapi berdasarkan keberanian dan tekad mereka dalam mengatasi tantangan.",
  ui_story_1021_10210201_57_dialog_content = "Pertama-tama, kami sudah memiliki tim <color=#FFB400>eksplorasi elit</color> yang berada di posisi dalam Dark Zone. Mereka akan membuka jalan untuk operasi lanjutan.",
  ui_story_1021_10210201_58_dialog_content = "Selanjutnya, kami memiliki <color=#FFB400>Dr. Barrett</color> sebagai konsultan operasional kami. Timnya menciptakan pesawat yang digunakan untuk ekspedisi.",
  ui_story_1021_10210201_59_dialog_content = "Dan Intel Chief <color=#FFB400>Lieutenant Philyshy</color> bertugas mengawasi rutinitas sehari-hari skuad serta komunikasi.",
  ui_story_1021_10210201_60_dialog_content = "Juga, personel cadangan militer kami sedang menjalani inspeksi akhir. Mereka akan memberikan dukungan yang solid kepada tim ekspedisi.",
  ui_story_1021_10210201_61_dialog_content = "Mengingat informasi yang diberikan, kami Lumopolis akan mengirim skuad elit untuk membersihkan rintangan bagi tim-tim berikutnya.",
  ui_story_1021_10210201_62_dialog_content = "...",
  ui_story_1021_10210201_63_dialog_content = "(Regu elit? Lumopolis juga mencari peran utama dalam ekspedisi, saya lihat. Saya rasa bahkan Carleen tidak tahu apa yang sedang dilakukan oleh Penguasa Kota...)",
  ui_story_1021_10210201_64_dialog_content = "Pasukan Lumopolis akan berjuang bersama semua orang dan berusaha memberikan dukungan penuh untuk ekspedisi.",
  ui_story_1021_10210201_65_dialog_content = "Ya. Amunisi kami siap digunakan, hanya menunggu sinyal.",
  ui_story_1021_10210201_66_dialog_content = "Ahem, ahem... Umbraton Guild juga memiliki banyak persediaan yang siap. Karavan kami akan mengantarkannya ke titik keberangkatan.",
  ui_story_1021_10210201_67_dialog_content = "Meskipun Umbraton tidak berpengalaman dengan operasi semacam ini, kami telah menyiapkan cukup persediaan untuk bertahan tim <color=#FFB400>ekspedisi</color> selama setahun.",
  ui_story_1021_10210201_68_dialog_content = "Terima kasih atas kemurahan hati Anda.",
  ui_story_1021_10210201_69_dialog_content = "Ini adalah situasi menang-menang untuk Umbraton, sejauh yang saya ketahui.",
  ui_story_1021_10210201_70_dialog_content = "Kami akan memberitahu semua orang tentang jadwal spesifik secepat mungkin.",
  ui_story_1021_10210201_71_dialog_content = "(Ini yang bisa kamu sebut \"ikut serta sebisa yang kamu bisa\"...)",
  ui_story_1021_10210201_72_dialog_content = "Apakah kamu memiliki sesuatu untuk dikatakan, PlayerName?",
  ui_story_1021_10210201_73_dialog_content = "Yah, saya tidak memiliki apa-apa untuk ditawarkan kecuali keinginan untuk melindungi teman-teman!",
  ui_story_1021_10210201_74_dialog_content = "Tempat yang akan kita tuju penuh dengan bahaya, tetapi saya akan memastikan tim saya aman.",
  ui_story_1021_10210201_75_dialog_content = "Aku tidak akan membiarkan rekan setimku terluka atau tersesat karena alasan apapun...",
  ui_story_1021_10210201_76_dialog_content = "...",
  ui_story_1021_10210201_77_dialog_content = "(Apakah saya mengatakan sesuatu yang salah?)",
  ui_story_1021_10210201_78_dialog_content = "Jangan ragu untuk memberi tahu guild jika kamu membutuhkan sesuatu, PlayerName.",
  ui_story_1021_10210201_79_dialog_content = "Terima kasih, Bethel. Aku akan ingat itu.",
  ui_story_1021_10210201_80_dialog_content = "Sekarang kita sudah selesai dengan topik utama, izinkan saya untuk menyimpang sebentar.",
  ui_story_1021_10210201_81_dialog_content = "Ketika saya masih muda, saya berharap bahwa saya bisa mengunjungi tempat mana pun yang saya inginkan secara langsung ketika saya menjadi Penguasa Kota Lumopolis.",
  ui_story_1021_10210201_82_dialog_content = "Namun, jika dipikir-pikir, saya membutuhkan waktu yang lama hanya untuk menjalankan kota ini dengan baik.",
  ui_story_1021_10210201_83_dialog_content = "Jadi, secara terbuka, saya ingin melihat lebih banyak dunia melalui mata kalian, anak-anak muda, selama saya masih hidup.",
  ui_story_1021_10210201_84_dialog_content = "Secara pribadi, meskipun ini adalah perjalanan yang menantang, saya berharap Carleen dapat bergabung dengan Anda dalam menyaksikan kelahiran era baru.",
  ui_story_1021_10210201_85_dialog_content = "Lord...",
  ui_story_1021_10210201_86_dialog_content = "Apakah kamu percaya ekspedisi ini akan membuka era baru?",
  ui_story_1021_10210201_87_dialog_content = "Tentu saja. Atau seharusnya saya katakan era baru sudah dimulai ketika Anda mulai mengungkap satu misteri demi satu misteri di Astra.",
  ui_story_1021_10210201_88_dialog_content = "Kami mendukung ekspedisi ini seratus persen, karena masa depan Astra sudah ada di tanganmu.",
  ui_story_1021_10210201_89_dialog_content = "Bantulah aku, Roy! Aku tidak bisa melakukan ini semua sendiri.",
  ui_story_1021_10210201_90_dialog_content = "Mereka bilang kamu akan puas dengan sisa-sisa saat kamu semakin tua, tapi untukku, yang bisa kupikirkan hanyalah saus apa yang cocok untuk steikku malam ini.",
  ui_story_1021_10210201_91_dialog_content = "Hatsyiii!",
  ui_story_1021_10210201_92_dialog_content = "Pesawat Illumina ini mungkin baru, tapi teknologinya berbau tajam seperti bubuk lada... Achoo!",
  ui_story_1021_10210201_93_dialog_content = "Honcho Sinsa selalu menutupi semua basisnya. Dia sangat tertarik pada ekspedisi Caelestite, jadi kita harus mempelajari hal ini—ini mungkin saja berguna!",
  ui_story_1021_10210201_94_dialog_content = "Saya lihat Sinsa masih suka ikut campur urusan orang lain... Kita harus pergi, Tiny One!",
  ui_story_1021_10210201_95_dialog_content = "Mesin baru membutuhkan waktu untuk menghilangkan baunya, jadi saya harap Anda tidak keberatan, Kapten.",
  ui_story_1021_10210201_96_dialog_content = "Oh, tidak apa-apa. Aroma tidak mengganggu saya.",
  ui_story_1021_10210201_97_dialog_content = "Saya menerima pesan dari Queen Negeri Utara pagi ini, yang menginformasikan bahwa pembangunan pos luar akan ditunda beberapa hari. Dia tidak memberikan detail apa pun, dan bukan tempat saya sebagai sekutu untuk bertanya.",
  ui_story_1021_10210201_98_dialog_content = "Namun, ekspedisi ini membutuhkan semua pos luar untuk maju bersama-sama, dan Illumina tidak bisa menyisihkan lebih banyak lagi tenaga.",
  ui_story_1021_10210201_99_dialog_content = "Oleh karena itu, aku harus memintamu untuk berlari untukku.",
  ui_story_1021_10210201_100_dialog_content = "Tentu. Banyak hal yang terjadi akhir-akhir ini, dan sudah lama sekali aku tidak ke Northland.",
  ui_story_1021_10210201_101_dialog_content = "Itu sempurna. PlayerName juga bisa membantu kamu memahami operasional pesawat.",
  ui_story_1021_10210201_102_dialog_content = "Kamu bisa mengandalkan saya. Meski berbeda dari Soroz, sebagian besar desainnya terasa cukup familiar bagi saya.",
  ui_story_1021_10210201_103_dialog_content = "Itulah mengapa saya sudah melihat setengah dari Astra hanya dengan itu saja.",
  ui_story_1021_10210201_104_dialog_content = "Terima kasih banyak. Hubungi saya jika ada masalah. Sistem komunikasi sudah diatur.",
  ui_story_1021_10210201_105_dialog_content = "Semoga selamat sampai tujuan!",
  ui_story_1021_10210201_106_dialog_content = "Siap!",
  ui_story_1021_10210201_107_dialog_content = "Haruskah kita beritahu PlayerName bahwa ada dua orang dari Rediesel Wrench di kapal, Grand Marshal?",
  ui_story_1021_10210201_108_dialog_content = "Tidak. Hal seperti itu sering terjadi dalam ekspedisi. Mereka bisa menanganinya.",
  ui_story_1021_10210201_109_dialog_content = "Lagipula, bukankah Rediesel Wrench sendiri yang berteriak-teriak ingin bergabung dalam operasi tersebut?",
  ui_story_1021_10210301_1_dialog_content = "<color=#e8d9bb>Sesaat kemudian...</color>",
  ui_story_1021_10210301_2_dialog_content = "Aku khawatir aku tidak bisa terbiasa naik pesawat Illumina.",
  ui_story_1021_10210301_3_dialog_content = "Tapi meskipun ukurannya jauh lebih kecil, ini cukup mirip dengan Soroz. Tanpa terasa, kita hampir sampai di Northland.",
  ui_story_1021_10210301_4_dialog_content = "Seperti yang sudah saya katakan, itu tidak akan menjadi masalah.",
  ui_story_1021_10210301_5_dialog_content = "Sebelum kita mendarat, apakah kamu ingin mencoba menerbangkannya? Kamu melihat betapa mudahnya saat kita lepas landas.",
  ui_story_1021_10210301_6_dialog_content = "Baik, tentu, bimbing saya melaluinya.",
  ui_story_1021_10210301_7_dialog_content = "Oke, jadi pertama, panel kontrol di sini akan menunjukkan—",
  ui_story_1021_10210301_8_dialog_content = "<color=#e8d9bb>Gruk!</color>",
  ui_story_1021_10210301_9_dialog_content = "Ah!",
  ui_story_1021_10210301_10_dialog_content = "Apa yang terjadi? Aku bahkan belum menyentuh apa-apa!",
  ui_story_1021_10210301_11_dialog_content = "Tetap tenang! Mungkin itu hanya turbulensi...",
  ui_story_1021_10210301_12_dialog_content = "Kita akan menyelam... Tarik saja tuas ke atas, lalu—",
  ui_story_1021_10210301_13_dialog_content = "<color=#e8d9bb>Bip, bip, bip...</color>",
  ui_story_1021_10210301_14_dialog_content = "Oh, tidak!",
  ui_story_1021_10210301_15_dialog_content = "<color=#e8d9bb>Bip, bip, bip...</color>",
  ui_story_1021_10210301_16_dialog_content = "Apakah kamu sudah menemukannya, Roy? Mungkin kita harus keluar dan mengambil alih pesawat itu.",
  ui_story_1021_10210301_17_dialog_content = "Keluar sekarang hanya akan memperburuk keadaan. Aku... akan selesai di sini dalam sekejap... Tidak, aku tidak bisa mendapatkan keuntungan dalam kegelapan.",
  ui_story_1021_10210301_18_dialog_content = "Aku punya lampu di sini!",
  ui_story_1021_10210301_19_dialog_content = "Itu benar-benar mempesona... Di mana kita sekarang?",
  ui_story_1021_10210301_20_dialog_content = "Setidaknya beberapa ratus mil dari Rediesel Desert. Semakin putih di luar sana. Kita bisa berada di Northland...",
  ui_story_1021_10210301_21_dialog_content = "Dalam hal itu, tidak biasa jika Anda mengalami turbulensi.",
  ui_story_1021_10210301_22_dialog_content = "Hmm, build-nya berbeda dari yang kubayangkan. Aku rasa aku tidak bisa memperbaikinya.",
  ui_story_1021_10210301_23_dialog_content = "Apa maksudmu \"berbeda\"? Ini masalah hidup dan mati! Biarkan aku melihat!",
  ui_story_1021_10210301_24_dialog_content = "Kamu memang bilang ada masalah dengan elevator, 'kan?",
  ui_story_1021_10210301_25_dialog_content = "Ya, kurang lebih. Saya tidak melihat adanya poros transmisi pada pesawat Illumina ini.",
  ui_story_1021_10210301_26_dialog_content = "... Itu karena rusak!",
  ui_story_1021_10210301_27_dialog_content = "Aku mengerti... Biarkan aku mengobrak-abrik sakuku mencari sesuatu yang berguna sementara kamu mencoba bertahan dengan kunci pas untuk saat ini.",
  ui_story_1021_10210301_28_dialog_content = "Kamu tidak merasakan ancaman bahaya yang akan datang, bukan?",
  ui_story_1021_10210301_29_dialog_content = "<color=#e8d9bb>Gruk!</color>",
  ui_story_1021_10210301_30_dialog_content = "Argh!",
  ui_story_1021_10210301_31_dialog_content = "Sudah berakhir sekarang! Kamu baik-baik saja?",
  ui_story_1021_10210301_32_dialog_content = "Dimana Carleen? Saya melihat noda darah. Jangan bilang... Carleen!",
  ui_story_1021_10210301_33_dialog_content = "!",
  ui_story_1021_10210301_34_dialog_content = "Aku tidak akan pernah naik pesawat lagi!",
  ui_story_1021_10210301_35_dialog_content = "(Kurasa dia baik-baik saja...)",
  ui_story_1021_10210301_36_dialog_content = "Oke, tidak lagi. Ini semua salahku.",
  ui_story_1021_10210301_37_dialog_content = "Tapi jujur, saya tidak menyangka turbulensi di Northland bisa sekuat ini.",
  ui_story_1021_10210301_38_dialog_content = "...",
  ui_story_1021_10210301_39_dialog_content = "Ini bagian dari petualangan meskipun...",
  ui_story_1021_10210301_40_dialog_content = "Untungnya, tuas itu merespon pada detik terakhir.",
  ui_story_1021_10210301_41_dialog_content = "Wow, sulit dipercaya kita bisa mendarat dengan selamat meski kemudi pesawat bengkok sampai sudut ini...",
  ui_story_1021_10210301_42_dialog_content = "Apakah kamu sedang mencari pujian atas kemampuan pilotmu?",
  ui_story_1021_10210301_43_dialog_content = "Eh, aku gak tau gimana cara menjawabnya...",
  ui_story_1021_10210301_44_dialog_content = "<color=#e8d9bb>Auuu—</color>",
  ui_story_1021_10210301_45_dialog_content = "Apakah ini adalah tempat berburu untuk hewan? Ada darah di mana-mana...",
  ui_story_1021_10210301_46_dialog_content = "Sepertinya ada pertempuran yang baru saja terjadi di sini. Kita seharusnya masih jauh dari Winter Palace. Mungkin ini adalah ulah dari Eclipsite...",
  ui_story_1021_10210301_47_dialog_content = "Eclipsite? Lalu kita berada di luar jangkauan Beacon.",
  ui_story_1021_10210301_48_dialog_content = "Luas tanah yang tidak tercakup oleh Mercusuar di sini jauh lebih besar dari yang kamu pikirkan, terutama di utara di mana Eclipsite berkeliaran tanpa kendali...",
  ui_story_1021_10210301_49_dialog_content = "Saya hanya mendengar ceritanya dan tidak pernah berpikir bahwa itu akan begitu menyeramkan secara langsung...",
  ui_story_1021_10210301_50_dialog_content = "...",
  ui_story_1021_10210301_51_dialog_content = "... Aku mendengar seseorang!",
  ui_story_1021_10210301_52_dialog_content = "Ayo kita lihat.",
  ui_story_1021_10210301_53_dialog_content = "Hmph!",
  ui_story_1021_10210301_54_dialog_content = "Ayo, gadis kecil, jangan menatapku seperti itu! Sudah kukatakan, kami terpaksa berada di sini.",
  ui_story_1021_10210301_55_dialog_content = "Lisensi pilotku masih ada di pesawat. Tunggu di sini dan aku akan mengambilnya untukmu...",
  ui_story_1021_10210301_56_dialog_content = "Kita memiliki lisensi, Roy?",
  ui_story_1021_10210301_57_dialog_content = "Selalu menjadi masalah membawa pemula. Kamu kehilangan lisensimu lagi, bukan? Biar aku yang mencarinya untukmu sekarang juga!",
  ui_story_1021_10210301_58_dialog_content = "Berhenti!",
  ui_story_1021_10210301_59_dialog_content = "Biarkan mereka pergi.",
  ui_story_1021_10210301_60_dialog_content = "Tua! Apa yang sedang kamu lakukan di sini? Bukankah kamu—",
  ui_story_1021_10210301_61_dialog_content = "Jangan kamu khawatir tentang aku.",
  ui_story_1021_10210301_62_dialog_content = "Tapi ini adalah apa yang terjadi pada suku kami dalam semalam. Bagaimana saya bisa tidak khawatir? Tidakkah kamu melihat darah hitam yang merembes dari rubah malang itu?",
  ui_story_1021_10210301_63_dialog_content = "Kamu seharusnya tidak datang.",
  ui_story_1021_10210301_64_dialog_content = "Kenapa kau selalu menyuruhku menjauh? Ini rumahku!",
  ui_story_1021_10210301_65_dialog_content = "... Tiare?",
  ui_story_1021_10210301_66_dialog_content = "Sekarang kemarilah, berlindung di balik perisai ini.",
  ui_story_1021_10210301_67_dialog_content = "Aku lalai dalam tugasku sebagai pengawal Yang Mulia Ratu!",
  ui_story_1021_10210301_68_dialog_content = "Tolong jangan tinggalkan aku dan bertarung melawan Eclipsites sendirian lagi!",
  ui_story_1021_10210301_69_dialog_content = "Izinkan aku menjadi garda depanmu yang pemberani, Yang Mulia!",
  ui_story_1021_10210301_70_dialog_content = "Pengawal Queen...",
  ui_story_1021_10210301_71_dialog_content = "Kau rupanya...",
  ui_story_1021_10210301_72_dialog_content = "Sedang apa kau di sini? Dan apa yang terjadi?",
  ui_story_1021_10210301_73_dialog_content = "...",
  ui_story_1021_10210301_74_dialog_content = "(Apakah itu rubah salju legendaris? Dia menatapku seolah-olah dia ingin aku pergi.)",
  ui_story_1021_10210301_75_dialog_content = "Kami datang untuk mengunjungi Yang Mulia Ratu, tetapi pesawat kami mengalami turbulensi keras dan terpaksa mendarat di sini.",
  ui_story_1021_10210301_76_dialog_content = "...",
  ui_story_1021_10210301_77_dialog_content = "... Maafkan kami karena telah mengganggumu.",
  ui_story_1021_10210301_78_dialog_content = "Apakah mereka berdua bersamamu?",
  ui_story_1021_10210301_79_dialog_content = "Apa maksudmu?",
  ui_story_1021_10210301_80_dialog_content = "Barusan mereka ada di sini!",
  ui_story_1021_10210301_81_dialog_content = "Mereka memberi isyarat kepada teman-teman saya dengan benda-benda aneh di tangan dan mengaku sebagai pilot pesawat tersebut.",
  ui_story_1021_10210301_82_dialog_content = "Tapi hanya aku dan Carleen di dalam kendaraan itu!",
  ui_story_1021_10210301_83_dialog_content = "Tak mungkin!",
  ui_story_1021_10210301_84_dialog_content = "Tenang saja, Tiare.",
  ui_story_1021_10210301_85_dialog_content = "Jika mereka menyakiti kamu atau teman-temanmu, PlayerName dan aku tidak akan membiarkan mereka lolos begitu saja.",
  ui_story_1021_10210301_86_dialog_content = "Tapi aku mendengar kamu menyebut \"ini adalah rumahmu\"?",
  ui_story_1021_10210301_87_dialog_content = "Ini adalah perbatasan Northland, sering dikunjungi oleh Eclipsite...",
  ui_story_1021_10210301_88_dialog_content = "Aku... mengikuti perintah sang ratu untuk memeriksa Hutan Snowpine.",
  ui_story_1021_10210301_89_dialog_content = "Mengerti. Apakah kamu keberatan mengantarkan kami kepada Yang Mulia Ratu ketika kamu selesai?",
  ui_story_1021_10210301_90_dialog_content = "Kami tidak bisa menemukan jalan menuju Winter Palace, tapi kami pasti bisa membantu jika Eclipsites muncul!",
  ui_story_1021_10210301_91_dialog_content = "<color=#e8d9bb>Awoooo!</color>",
  ui_story_1021_10210301_92_dialog_content = "Tidak!",
  ui_story_1021_10210301_93_dialog_content = "Maksud saya, ini sangat jauh dari istana dan sangat berbahaya di sini, jadi kamu harus pergi.",
  ui_story_1021_10210301_94_dialog_content = "Itu…?",
  ui_story_1021_10210301_95_dialog_content = "(Pasti ada yang aneh dengan Tiare...)",
  ui_story_1021_10210301_96_dialog_content = "Bisakah kamu memberi tahu kami apa yang terjadi di sini?",
  ui_story_1021_10210301_97_dialog_content = "...",
  ui_story_1021_10210301_98_dialog_content = "Bukankah kau kemari untuk sang Ratu?",
  ui_story_1021_10210301_99_dialog_content = "Cukup ikuti jejak kelinci itu dan kamu akan melihatnya.",
  ui_story_1021_10210301_100_dialog_content = "Ketika kamu melakukannya, tolong beri tahu dia... bahwa aku akan membersihkan jejak kaki, tapi tidak sekarang.",
  ui_story_1021_10210301_101_dialog_content = "...",
  ui_story_1021_10210301_102_dialog_content = "Dan dia pergi dalam sekejap...",
  ui_story_1021_10210301_103_dialog_content = "Aku tidak pernah berpikir bahwa Suku Fox Salju benar-benar ada di Northland...",
  ui_story_1021_10210301_104_dialog_content = "Ketika saya belajar di Northland, saya mendengar beberapa orang lokal berkata...",
  ui_story_1021_10210301_105_dialog_content = "Terdapat pemukiman di ujung barat laut tempat rubah salju berkumpul dan hidup dari Hutan Snowpine.",
  ui_story_1021_10210301_106_dialog_content = "Mereka melindungi hutan dan reruntuhan di bawahnya.",
  ui_story_1021_10210301_107_dialog_content = "Namun, karena tidak ada yang pernah melihatnya dengan mata kepala sendiri, tidak ada yang yakin apakah itu fakta atau mitos. Namun, bagian takut Aurorian tampaknya benar...",
  ui_story_1021_10210301_108_dialog_content = "Apakah kamu melihat rubah-rubah yang terluka berlindung di belakang Tiare?",
  ui_story_1021_10210301_109_dialog_content = "Ya, dan rubah salju tua itu menatap kami seolah-olah kami adalah musuh bebuyutannya.",
  ui_story_1021_10210301_110_dialog_content = "Rubah-rubah itu pasti yang meninggalkan noda darah.",
  ui_story_1021_10210301_111_dialog_content = "Beberapa noda berwarna hitam, beberapa merah, dan itu membuatku mual...",
  ui_story_1021_10210301_112_dialog_content = "Dikatakan bahwa beberapa rubah salju adalah \"roh gunung\" yang lahir dari kekuatan alam, dan ketika mereka tercemar oleh Darkflow, tubuh mereka juga bermutasi.",
  ui_story_1021_10210301_113_dialog_content = "Kamu mungkin merasa tidak enak badan karena Darkflow dalam bercak darah.",
  ui_story_1021_10210301_114_dialog_content = "Darkflow? Jadi ada lebih banyak pesan yang dia inginkan kita sampaikan kepada ratu.",
  ui_story_1021_10210301_115_dialog_content = "Mengingat semua yang kita ketahui, kemungkinan besar Eclipsite menyerang Northland dan tidak hanya melukai rubah-rubah itu tetapi juga menghancurkan pos tersebut.",
  ui_story_1021_10210301_116_dialog_content = "Jadi itulah mengapa Yang Mulia Ratu belum mengirimkan wakil apa pun...",
  ui_story_1021_10210301_117_dialog_content = "Ini juga menempatkan Tiare dalam bahaya besar!",
  ui_story_1021_10210301_118_dialog_content = "Kita harus menyusul, sehingga kita bisa membantu jika dia mengalami masalah.",
  ui_story_1021_10210301_119_dialog_content = "Mari kita ikuti jejak darah! Area ini dipenuhi oleh Eclipsites, jadi kita harus berhati-hati!",
  ui_story_1021_10210401_1_dialog_content = "Jejaknya berakhir di sini... Aku tidak tahu apakah ini karena darah atau apa, tapi kepalaku mulai berputar...",
  ui_story_1021_10210401_2_dialog_content = "Biarkan aku... mencoba kemampuan psikisku...",
  ui_story_1021_10210401_3_dialog_content = "PlayerName, aku tahu kamu belum pernah menggunakannya sejak kejadian terakhir kali. Jadi, kamu yakin?",
  ui_story_1021_10210401_4_option_content = "Ya…",
  ui_story_1021_10210401_5_dialog_content = "Sebenarnya, sudah lama, aku merasa ragu saat memikirkan tentang menggunakan kemampuan psikis...",
  ui_story_1021_10210401_6_option_content = "Aku masih sedikit gugup.",
  ui_story_1021_10210401_7_dialog_content = "Sejak saat itu, ide untuk menggunakan kemampuan psikis telah menyiksa saya dari dalam...",
  ui_story_1021_10210401_8_dialog_content = "Apakah kamu khawatir tentang apa yang akan kamu lihat, dan bahwa kamu mungkin akan menarik perhatian Engineer lagi?",
  ui_story_1021_10210401_9_dialog_content = "Ya. Aku juga khawatir mungkin aku akan melihat atau mendengar berita buruk tentang Vice atau Soroz...",
  ui_story_1021_10210401_10_dialog_content = "Saya tahu apa yang terjadi memiliki dampak besar pada Anda, tapi—",
  ui_story_1021_10210401_11_dialog_content = "Namun, kemampuan psikis adalah apa yang saya gunakan untuk bertarung dan bagaimana saya melindungi semua orang.",
  ui_story_1021_10210401_12_dialog_content = "Bagaimanapun, aku harus mengatasi ketakutanku dan meningkatkan kontrolku!",
  ui_story_1021_10210401_13_dialog_content = "Jadi, saya menghargai kepedulianmu, Carleen. Saya baik-baik saja sekarang.",
  ui_story_1021_10210401_14_dialog_content = "Senang melihatmu kembali begitu cepat, PlayerName. Saya benar-benar bahagia untukmu.",
  ui_story_1021_10210401_15_dialog_content = "Ingat, aku di sini bersamamu. Jika ada sesuatu yang salah, kita akan menanganinya bersama.",
  ui_story_1021_10210401_16_dialog_content = "Siap!",
  ui_story_1021_10210401_17_option_content = "Tautan Telepati—",
  ui_story_1021_10210401_18_dialog_content = "(Gua besar yang kosong...)",
  ui_story_1021_10210401_19_dialog_content = "(Gletser-gletser ini telah ada sejak lama.)",
  ui_story_1021_10210401_20_dialog_content = "...Dia akan menang Rediesel Rally jika dia mendaftar.",
  ui_story_1021_10210401_21_dialog_content = "Dua kaki tidak bisa menandingi empat roda! Tunggu, apakah kamu mencium sesuatu yang menyengat?",
  ui_story_1021_10210401_22_dialog_content = "(Suaranya... Darimana asal suara itu?)",
  ui_story_1021_10210401_23_dialog_content = "(Noda darah hitam dan merah persis seperti yang ada di tanah di atas!)",
  ui_story_1021_10210401_24_dialog_content = "(Setidaknya aku masih mengendalikan pikiranku sendiri...)",
  ui_story_1021_10210401_25_dialog_content = "(Oh, dan Tiare ada di sini... Apakah gua ini berada di bawah Hutan Snowpine?)",
  ui_story_1021_10210401_26_dialog_content = "Bau busuk yang membusuk ini mengingatkanku pada Rediesel yang sangat kucintai...",
  ui_story_1021_10210401_27_dialog_content = "Matikan lampu sebelum menarik sesuatu yang aneh. Aku tidak mau merasakan dingin ini sia-sia.",
  ui_story_1021_10210401_28_dialog_content = "Mengapa kita harus bersembunyi di sini? Sekarang kita bahkan tidak bisa menemukan siapa pun untuk memberi kita petunjuk arah.",
  ui_story_1021_10210401_29_dialog_content = "Bukankah kamu bilang kamu paling benci dengan bawah tanah, Roy?",
  ui_story_1021_10210401_30_dialog_content = "(Mereka berdua?)",
  ui_story_1021_10210401_31_dialog_content = "(Ada banyak jalan memutar di sekitar, jadi bagaimana mereka bisa sampai di sana?)",
  ui_story_1021_10210401_32_option_content = "Jangkauan Telepati—",
  ui_story_1021_10210401_33_dialog_content = "...",
  ui_story_1021_10210401_34_dialog_content = "Apa yang tadi kaulihat?",
  ui_story_1021_10210401_35_dialog_content = "Para penyusup yang Tiare sebutkan adalah dua dari teman Rediesel-ku.",
  ui_story_1021_10210401_36_dialog_content = "Setelah memperluas pandanganku, aku rasa aku melihat gumpalan Darkflow membesar seperti uap yang mengembang.",
  ui_story_1021_10210401_37_dialog_content = "Sangat dekat dengan kita...",
  ui_story_1021_10210401_38_dialog_content = "!",
  ui_story_1021_10210401_39_dialog_content = "Ada noda darah yang identik dengan yang ada di tanah juga. Tiare juga harusnya berada di dalam gua itu.",
  ui_story_1021_10210401_40_dialog_content = "Maka kita harus segera bergegas dan menemui mereka! Kita harus pergi ke mana sekarang?",
  ui_story_1021_10210401_41_dialog_content = "Jejaknya berakhir di sini, jadi guanya harus berada di belakang pohon-pohon snowpine ini. Ikuti saya!",
  ui_story_1021_10210401_42_dialog_content = "(Tiare, Roy, dan Tiny One juga... Semoga tidak ada hal buruk yang terjadi pada kalian!)",
  ui_story_1021_10210401_43_dialog_content = "<color=#e8d9bb>Awooo...</color>",
  ui_story_1021_10210401_44_dialog_content = "Wahai dewa kuno yang agung, aku selalu memandangmu seperti kau selalu memperhatikan kami dari atas.",
  ui_story_1021_10210401_45_dialog_content = "Bayangan kegelapan telah turun sekali lagi, mencemari tubuh kita seperti predator dan meninggalkan tanda yang tak bisa dihapus.",
  ui_story_1021_10210401_46_dialog_content = "Di Winter Palace, aku adalah Pengawal Queen...",
  ui_story_1021_10210401_47_dialog_content = "Tapi di sini, aku adalah pemimpin yang bersumpah untuk melindungi suku ini.",
  ui_story_1021_10210401_48_dialog_content = "Kamu memberi makan suku ini dan memberikan kami garis keturunan yang suci, memungkinkan kami untuk terhubung dengan kehadiran ilahi-Mu.",
  ui_story_1021_10210401_49_dialog_content = "Tapi sekarang, sedikit suku yang tersisa hidup siang dan malam dalam penderitaan, tubuh mereka runtuh. Aku tahu suatu hari nanti kita akan kembali ke dalam pelukanmu.",
  ui_story_1021_10210401_50_dialog_content = "May Anda kembali menatap kami dengan penuh belas kasihan, seperti bagaimana Anda memberkati leluhur kami dan suku sebelumnya.",
  ui_story_1021_10210401_51_dialog_content = "<color=#e8d9bb>Awoooo!</color>",
  ui_story_1021_10210401_52_dialog_content = "Aurorian yang tanpa sengaja melanggar batas ini dalam bahaya. Saya tidak punya apa-apa lagi untuk menjaga mereka keluar lagi...",
  ui_story_1021_10210401_53_dialog_content = "Itu seharusnya menjadi tugas saya, tetua...",
  ui_story_1021_10210401_54_dialog_content = "Tiare, lihat tombak di tanganmu! Kau adalah penjaga Northland... Tolong lepaskan semua kekhawatiranmu tentang tempat ini...",
  ui_story_1021_10210401_55_dialog_content = "*Batuk*",
  ui_story_1021_10210401_56_dialog_content = "Aku mohon padamu, tua-tua... Aku tidak bisa hanya menyaksikan suku dan orang-orangku mati...",
  ui_story_1021_10210401_57_dialog_content = "Kamu... seharusnya tidak kembali...",
  ui_story_1021_10210401_58_dialog_content = "Apa yang harus saya lakukan sekarang...",
  ui_story_1021_10210401_59_dialog_content = "<color=#e8d9bb>Tetes, tetes...</color>",
  ui_story_1021_10210401_60_dialog_content = "Aduh!",
  ui_story_1021_10210401_61_dialog_content = "Hati-hati, jalur yang berlapis es ini sangat licin. Tunggu, kenapa ada air yang menetes?",
  ui_story_1021_10210401_62_dialog_content = "Aku sudah menginjak beberapa genangan air berturut-turut. Bau yang mengerikan mungkin membuatku tersandung di genangan terakhir.",
  ui_story_1021_10210401_63_dialog_content = "Tunggu sebentar, sepertinya aku baru saja menginjak sesuatu yang empuk dan lembut... Coba lihat untukku.",
  ui_story_1021_10210401_64_dialog_content = "Sepertinya... seekor rubah salju.",
  ui_story_1021_10210401_65_dialog_content = "Apakah dia masih hidup?",
  ui_story_1021_10210401_66_dialog_content = "...",
  ui_story_1021_10210401_67_dialog_content = "Oh, aku sudah selesai. Aku melihat cahaya putih...",
  ui_story_1021_10210401_68_dialog_content = "Keluarlah dari sana. Sebenarnya ada cahaya di depan.",
  ui_story_1021_10210401_69_dialog_content = "<color=#e8d9bb>Tetes, tetes...</color>",
  ui_story_1021_10210401_70_dialog_content = "Apakah aku mulai mengigau, Tiny One? Rasanya kita akan sampai di rumah jika kita terus berjalan seperti ini.",
  ui_story_1021_10210401_71_dialog_content = "Semakin panas juga... dan entah bagaimana otot-ototku menjadi sangat rileks.",
  ui_story_1021_10210401_72_dialog_content = "Kalau begitu, biar aku yang membawakan tas berisi permata ini untukmu.",
  ui_story_1021_10210401_73_dialog_content = "Apa yang kamu katakan? Bagaimana bisa kamu begitu saja menyerahkan permata gratis seperti itu?",
  ui_story_1021_10210401_74_dialog_content = "Hei, jangan sentuh kepala saya. Tanganmu lengket karena keringat!",
  ui_story_1021_10210401_75_dialog_content = "Kenapa kamu... Urgh, aku tidak bisa membuka mataku dalam cahaya mendadak ini... Bukankah sudah kukatakan cahaya terang menarik masalah?",
  ui_story_1021_10210401_76_dialog_content = "Hei, kalian berdua!",
  ui_story_1021_10210401_77_dialog_content = "Ngomong-ngomong soal masalah...",
  ui_story_1021_10210401_78_dialog_content = "Halo.",
  ui_story_1021_10210401_79_dialog_content = "Hai, PlayerName. Kau juga mencari harta karun?",
  ui_story_1021_10210401_80_dialog_content = "Mencari harta karun? Kenapa kamu menyelinap ke dalam pesawat kami?",
  ui_story_1021_10210401_81_dialog_content = "Apakah Sinsa lupa mengumpulkan formulir pendaftaran atau apa? Kita mewakili Rediesel Wrench untuk konferensi ekspedisi bersama.",
  ui_story_1021_10210401_82_dialog_content = "Siapa yang tahu rapatnya sangat membosankan sehingga entah bagaimana kita bisa berakhir di sini setelah bangun dari tidur sebentar...",
  ui_story_1021_10210401_83_dialog_content = "Mengingat ransel besar itu, lebih mungkin kamu di Northland untuk mencuri permata! Saya menyarankan kamu untuk mengembalikannya ke tempat kamu menemukannya!",
  ui_story_1021_10210401_84_dialog_content = "Apa, kita di Northland? Jujur, saya bahkan belum pernah keluar dari Gurun Rediesel, apalagi tahu ada permata di sini!",
  ui_story_1021_10210401_85_dialog_content = "Tapi saya sudah memperbaiki kendaraanmu, jadi saya akan mengambil tas ini sebagai tanda penghargaanmu.",
  ui_story_1021_10210401_86_dialog_content = "Kenapa kamu-",
  ui_story_1021_10210401_87_dialog_content = "Saya pikir saya tahu apa yang terjadi, Carleen.",
  ui_story_1021_10210401_88_dialog_content = "Mereka adalah mekanik teratas di Rediesel Wrench, dan ada ruang perawatan di pesawat dekat kemudi ekor yang cukup jauh dari kokpit.",
  ui_story_1021_10210401_89_dialog_content = "Kita berhasil mendarat dengan selamat meski kemudi kapal terpelintir seperti itu... Mungkin mereka bersembunyi di ruangan itu dan telah membantu kita...",
  ui_story_1021_10210401_90_dialog_content = "Menurutmu begitu, ya?",
  ui_story_1021_10210401_91_dialog_content = "Jadi, tentang pesawat terbang itu... terima kasih.",
  ui_story_1021_10210401_92_dialog_content = "Jangan khawatir. Kita dalam ekspedisi bersama, harus saling menjaga!",
  ui_story_1021_10210401_93_dialog_content = "<color=#e8d9bb>Tetes, tetes...</color>",
  ui_story_1021_10210401_94_dialog_content = "Yang pertama dulu. Ketika kita kembali, saya bisa memberimu Nightium, tapi biarkan batu permata tetap di Northland.",
  ui_story_1021_10210401_95_dialog_content = "Nightium, katamu... Kurasa itu cukup.",
  ui_story_1021_10210401_96_dialog_content = "Di sini sangat berbahaya. Roy, Tiny One, apakah kamu tahu kemana gadis dengan rubah salju itu pergi?",
  ui_story_1021_10210401_97_dialog_content = "Ya, tapi dia bergerak terlalu cepat sampai-sampai kita tidak bisa mengejarnya!",
  ui_story_1021_10210401_98_dialog_content = "Sebenarnya, kami mencoba untuk menjauh darinya...",
  ui_story_1021_10210401_99_dialog_content = "Ada banyak bangkai rubah di dalam gua, PlayerName. Banyak rubah yang bersamanya juga terluka parah.",
  ui_story_1021_10210401_100_dialog_content = "Maka kita harus menemukannya secepat mungkin.",
  ui_story_1021_10210401_101_dialog_content = "Karena kamu tahu jalannya, silakan tunjukkan.",
  ui_story_1021_10210401_102_dialog_content = "Tak ada masalah di sini, tapi tidak di bagian dalam. Terlalu banyak pertigaan... Kami hampir tersesat sendiri.",
  ui_story_1021_10210401_103_dialog_content = "Roy, cahayaku...",
  ui_story_1021_10210401_104_dialog_content = "Meredup?",
  ui_story_1021_10210401_105_dialog_content = "Itu berarti Darkflow semakin kuat.",
  ui_story_1021_10210401_106_dialog_content = "Sebanyak apapun aku suka tempat yang lebih hangat, aku minta maaf, PlayerName, Miss Nightium, aku akan pergi bersama Tiny One!",
  ui_story_1021_10210401_107_dialog_content = "Saya tidak percaya. Mereka baru saja mengatakan bahwa kita harus saling membantu... Jalan mana yang harus kita ambil sekarang?",
  ui_story_1021_10210401_108_dialog_content = "Biarkan saya menggunakan kemampuan psikis saya.",
  ui_story_1021_10210401_109_option_content = "Jangkauan Telepati—",
  ui_story_1021_10210401_110_dialog_content = "Ketamakan, kemarahan, obsesi... semua adalah delusi yang menyebabkan penderitaan pikiran dan tubuh.",
  ui_story_1021_10210401_111_dialog_content = "Kemarahan berubah menjadi amarah. Amarah berubah menjadi penderitaan.",
  ui_story_1021_10210401_112_dialog_content = "Ya, ya...",
  ui_story_1021_10210401_113_dialog_content = "Gertakan... semakin diredam...",
  ui_story_1021_10210401_114_dialog_content = "(Eclipsite?)",
  ui_story_1021_10210401_115_dialog_content = "(Terlalu kabur untukku mengerti, tapi yang baru saja aku rasakan...)",
  ui_story_1021_10210401_116_dialog_content = "(Darkflow di sekitarnya... Kepalaku... terasa seperti dipukul oleh tinju...)",
  ui_story_1021_10210401_117_dialog_content = "Tuan ku!",
  ui_story_1021_10210401_118_dialog_content = "Ya?",
  ui_story_1021_10210401_119_dialog_content = "Graah!",
  ui_story_1021_10210401_120_dialog_content = "(!)",
  ui_story_1021_10210401_121_dialog_content = "...",
  ui_story_1021_10210401_122_dialog_content = "Pengendalian... Pengendalian...",
  ui_story_1021_10210401_123_dialog_content = "T-Tuanku...",
  ui_story_1021_10210401_124_dialog_content = "Jangan khawatir dan mendekatlah. Aku tidak akan menyakitimu.",
  ui_story_1021_10210401_125_dialog_content = "Ya…",
  ui_story_1021_10210401_126_dialog_content = "Tuan saya... Ada Aurorian yang mencurigakan di dekat sini...",
  ui_story_1021_10210401_127_dialog_content = "...",
  ui_story_1021_10210401_128_dialog_content = "Aku... Aku percaya mereka bisa mempengaruhi meditasi mu...",
  ui_story_1021_10210401_129_dialog_content = "Di mana aku?",
  ui_story_1021_10210401_130_dialog_content = "Kamu telah melewati benteng.",
  ui_story_1021_10210401_131_dialog_content = "<color=#FFB400>Snowland</color>... Saya sudah pergi cukup jauh, memang.",
  ui_story_1021_10210401_132_dialog_content = "Sejak berubah, saya tidak pernah kembali lagi.",
  ui_story_1021_10210401_133_dialog_content = "Berubah...",
  ui_story_1021_10210401_134_dialog_content = "Perubahan adalah benar-benar suatu penghilangan yang tidak berperasaan!",
  ui_story_1021_10210401_135_dialog_content = "Lord...",
  ui_story_1021_10210401_136_dialog_content = "Hargai pengingat tepat waktu ini... Kendalikan diri... Kendalikan diri...",
  ui_story_1021_10210401_137_dialog_content = "<color=#e8d9bb>Tetes, tetes...</color>",
  ui_story_1021_10210401_138_dialog_content = "Es di sini mencair, dan itu disebabkan oleh Darkflow dari Eclipsite itu.",
  ui_story_1021_10210401_139_dialog_content = "Apa yang kamu lihat kali ini, PlayerName? Mengapa kamu tampak khawatir?",
  ui_story_1021_10210401_140_dialog_content = "Saya melihat Eclipsite itu...",
  ui_story_1021_10210401_141_dialog_content = "Setelah dipikir-pikir, kita harus tetap bersatu!",
  ui_story_1021_10210401_142_dialog_content = "Berani-beraninya kamu untuk kembali?",
  ui_story_1021_10210401_143_dialog_content = "Kita bertemu dengan segerombolan Eclipsite di sana, PlayerName!",
  ui_story_1021_10210401_144_dialog_content = "Graaah!",
  ui_story_1021_10210401_145_dialog_content = "Carleen, awas!",
  ui_story_1021_10210401_146_dialog_content = "Kamu yang menarik mereka ke sini!",
  ui_story_1021_10210401_147_dialog_content = "Berdiri di belakangku, Tiny One!",
  ui_story_1021_10210401_148_dialog_content = "Ini cukup dekat untukku bisa katakan ini Darkflow normal, bukan jenis yang meluap yang baru saja kurasakan...",
  ui_story_1021_10210401_149_dialog_content = "Jangan hanya berdiri di sana, PlayerName! Berikan perintah untuk bertempur!",
  ui_story_1021_10210401_150_dialog_content = "Siap!",
  ui_story_1021_10210402_1_dialog_content = "Ini akan berakhir saat es mencair.",
  ui_story_1021_10210402_2_dialog_content = "Semua sudah beres!",
  ui_story_1021_10210402_3_dialog_content = "Semua orang baik-baik saja?",
  ui_story_1021_10210402_4_dialog_content = "Yang Mulia! Apa yang sedang Anda lakukan di sini?",
  ui_story_1021_10210402_5_dialog_content = "Saya berada di geyser dan merasakan Luminatics mu.",
  ui_story_1021_10210402_6_dialog_content = "<color=#e8d9bb>Beberapa waktu lalu...</color>",
  ui_story_1021_10210402_7_dialog_content = "<color=#e8d9bb>Sploosh, sploosh... Dhuar!</color>",
  ui_story_1021_10210402_8_dialog_content = "Yang Mulia, apakah itu—",
  ui_story_1021_10210402_9_dialog_content = "Air mancur panas <color=#FFB400>geyser</color> di perbatasan. Setelah bertahun-tahun tidak aktif, kini telah kembali menyembur—sebuah mekanisme jam yang tepat waktu mengungkap luka masa lalu Northland...",
  ui_story_1021_10210402_10_dialog_content = "Air obsidian yang dikeluarkannya mengandung Darkflow dan telah menghancurkan tanaman, rumah, dan suku yang tidak bersalah...",
  ui_story_1021_10210402_11_dialog_content = "Aku bisa melihat di cermin bahwa energi di Zona Gelap semakin aktif. Apa rencana Anda, Yang Mulia?",
  ui_story_1021_10210402_12_dialog_content = "Ketika letusan berikutnya selesai, saya akan pergi ke sumber dan menangani Eclipsite itu.",
  ui_story_1021_10210402_13_dialog_content = "Cermin Northland milikmu itu menyimpan Lumina yang berlimpah di dalam cadangan. Saya mengandalkanmu untuk menekan penyebaran Darkflow setelah saya masuk.",
  ui_story_1021_10210402_14_dialog_content = "Ya, Yang Mulia.",
  ui_story_1021_10210402_15_dialog_content = "<color=#e8d9bb>Sploosh, sploosh... Dhuar!</color>",
  ui_story_1021_10210402_16_dialog_content = "Hmm?",
  ui_story_1021_10210402_17_dialog_content = "Mengapa Anda mengerutkan kening, Yang Mulia?",
  ui_story_1021_10210402_18_dialog_content = "Tidak ada yang lebih mengenal bagaimana dia memanipulasi Lumina daripada saya.",
  ui_story_1021_10210402_19_dialog_content = "Saya tidak bisa menunggu lagi. Saya akan meninggalkan sisanya di tangan Anda.",
  ui_story_1021_10210402_20_dialog_content = "... Ya, Yang Mulia.",
  ui_story_1021_10210402_21_dialog_content = "Jadi, geyser yang meletus menyebabkan kerusakan.",
  ui_story_1021_10210402_22_dialog_content = "Dan Darkflow menarik hord-hord Eclipsite yang membahayakan rubah salju kecil yang lemah. Kamu mungkin telah melihat banyak tanda-tanda di dalam gua.",
  ui_story_1021_10210402_23_dialog_content = "Kamu harus pergi sebelum letusan berikutnya.",
  ui_story_1021_10210402_24_dialog_content = "Tapi Yang Mulia, aku baru saja merasakan Eclipsite yang sangat kuat di sini...",
  ui_story_1021_10210402_25_dialog_content = "Kami datang untuk mengkonfirmasi rencana untuk pos luar Northland tetapi mendarat di dekatnya karena sebuah kecelakaan.",
  ui_story_1021_10210402_26_dialog_content = "Kemudian kami melihat Tiare dengan sekelompok rubah yang terluka, dan mereka tampaknya tidak dalam kondisi yang baik...",
  ui_story_1021_10210402_27_dialog_content = "Kami khawatir tentang keselamatan mereka, jadi kami mengikuti mereka ke sini. Ngomong-ngomong, di mana kedua orang dari Rediesel itu?",
  ui_story_1021_10210402_28_dialog_content = "...",
  ui_story_1021_10210402_29_dialog_content = "Yang Mulia Ratu, ini di luar yurisdiksi kerajaan...",
  ui_story_1021_10210402_30_dialog_content = "Apakah kamu mengirim penjagamu Tiare ke sini untuk memeriksa para Eclipsite?",
  ui_story_1021_10210402_31_dialog_content = "\"Queen's Guard\" adalah gelar yang Tiare tiru dari Royal Guard dan diberikan kepada dirinya sendiri.",
  ui_story_1021_10210402_32_dialog_content = "Untuk menjadi Penjaga Kerajaan, dia masih harus mencari tahu apa artinya melindungi Northland, sebuah pertanyaan abadi yang dikejar oleh orang-orang di tanah ini.",
  ui_story_1021_10210402_33_dialog_content = "Tuan Novio!",
  ui_story_1021_10210402_34_dialog_content = "Carleen, PlayerName.",
  ui_story_1021_10210402_35_dialog_content = "Karena kamu di sini, saya tahu apa yang terjadi.",
  ui_story_1021_10210402_36_dialog_content = "Kamu sudah tahu sejak lama bahwa Tiare akan meninggalkan Winter Palace dan kembali ke sukunya.",
  ui_story_1021_10210402_37_dialog_content = "Tiare memang adalah anggota dari Suku Fox Salju legendaris. Dia bahkan tampaknya—",
  ui_story_1021_10210402_38_dialog_content = "Tiare adalah pemimpin dari Suku Fox Salju.",
  ui_story_1021_10210402_39_dialog_content = "Pemimpin?",
  ui_story_1021_10210402_40_dialog_content = "Tidak ada yang lebih tua darinya di suku itu sekarang?",
  ui_story_1021_10210402_41_dialog_content = "...",
  ui_story_1021_10210402_42_dialog_content = "Oh, Yang Mulia, Tiare ingin memberi tahu Anda bahwa dia akan membersihkan jejak kaki, tapi tidak sekarang...",
  ui_story_1021_10210402_43_dialog_content = "Apa maksudnya dengan itu?",
  ui_story_1021_10210402_44_dialog_content = "Pertanyaan abadi... meskipun bahkan saya belum berhasil melakukan itu...",
  ui_story_1021_10210402_45_dialog_content = "Anda tidak pernah mengabaikan tempat ini dalam semua inspeksi Anda di seluruh Northland, Yang Mulia.",
  ui_story_1021_10210402_46_dialog_content = "Ini adalah tugas saya, Novio. Kamu bawa mereka keluar dari sini sementara saya melacak Tiare.",
  ui_story_1021_10210402_47_dialog_content = "Saya sudah melakukan yang terakhir, Yang Mulia.",
  ui_story_1021_10210402_48_dialog_content = "Ya.",
  ui_story_1021_10210402_49_dialog_content = "Yang Mulia, Darkflow kuat yang aku rasakan semakin mendekat!",
  ui_story_1021_10210402_50_dialog_content = "Apakah aku yang kamu bicarakan?",
  ui_story_1021_10210402_51_dialog_content = "Pisau Aurora!",
  ui_story_1021_10210402_52_dialog_content = "Cepat, berlindung di dalam bidang Lumina saya!",
  ui_story_1021_10210402_53_dialog_content = "Apakah kamu yang mengaku sebagai Queen dari Snowland? Sepertinya aku telah melewatkan banyak hal.",
  ui_story_1021_10210402_54_dialog_content = "Dia di atas kita begitu cepat!",
  ui_story_1021_10210402_55_dialog_content = "Kamu...",
  ui_story_1021_10210402_56_dialog_content = "<color=#FFB400>Natas</color> akan mengubah otakmu menjadi nektar dan membagikannya di antara kawan-kawanmu.",
  ui_story_1021_10210402_57_dialog_content = "Rekan sebangsa? Tentang apa kamu bicara?",
  ui_story_1021_10210402_58_dialog_content = "Nektar...",
  ui_story_1021_10210402_59_dialog_content = "Berbicara tentang nektar...",
  ui_story_1021_10210402_60_dialog_content = "Aku merasa sangat buruk...",
  ui_story_1021_10210402_61_dialog_content = "(Darkflow-nya bisa menembus perisai sang ratu...)",
  ui_story_1021_10210402_62_dialog_content = "Dingin Ekstrem yang Lebih Besar!",
  ui_story_1021_10210402_63_dialog_content = "Kehadiran kami hanya akan mempersulit usaha Anda, Yang Mulia. Percayakan mereka pada perawatan saya.",
  ui_story_1021_10210402_64_dialog_content = "Terima kasih, Master Novio.",
  ui_story_1021_10210402_65_dialog_content = "Izinkan saya berjuang bersama Anda, Yang Mulia!",
  ui_story_1021_10210402_66_dialog_content = "Tidak, dan itu perintahku.",
  ui_story_1021_10210402_67_dialog_content = "...",
  ui_story_1021_10210402_68_dialog_content = "Carleen, PlayerName, silakan ikuti staf saya ke permukaan di atas.",
  ui_story_1021_10210402_69_dialog_content = "Bagaimana, tepatnya?",
  ui_story_1021_10210402_70_dialog_content = "...",
  ui_story_1021_10210402_71_dialog_content = "Tuan Novio!",
  ui_story_1021_10210402_72_dialog_content = "Tetap dalam kegelapan dengan damai.",
  ui_story_1021_10210402_73_dialog_content = "Tidak akan ada kegelapan di Northland di mana aurora masih bersinar! Blade of Aurora!",
  ui_story_1021_10210402_74_dialog_content = "Anda jauh di bawah liga wanita itu.",
  ui_story_1021_10210402_75_dialog_content = "Kamu tidak layak untuk menilai sang Ratu!",
  ui_story_1021_10210402_76_dialog_content = "<color=#e8d9bb>Wuuss!</color>",
  ui_story_1021_10210402_77_dialog_content = "Kembali ke sini, Tiare!",
  ui_story_1021_10210402_78_dialog_content = "Sebagai pengawal Yang Mulia, aku harus berdiri di hadapanmu sebagai tameng!",
  ui_story_1021_10210402_79_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_1021_10210402_80_dialog_content = "Kamu tidak akan menyakiti Yang Mulia Ratu! Ini adalah peringatan dari Penjaga Queen!",
  ui_story_1021_10210402_81_dialog_content = "Tengkorak yang congkak... Kaki putih salju yang kuat...",
  ui_story_1021_10210402_82_dialog_content = "May bisakah kamu katakan apa itu di matamu?",
  ui_story_1021_10210402_83_dialog_content = "Ini tekad saya untuk membunuhmu!",
  ui_story_1021_10210402_84_dialog_content = "Kamu mengingatkanku padanya...",
  ui_story_1021_10210402_85_dialog_content = "Ketika dia mengikat gaun hitamnya di pinggang, memotong ujungnya agar dia bisa memimpin serangan prajuritnya dengan kecepatan penuh.",
  ui_story_1021_10210402_86_dialog_content = "Jangan berkedip atau tombakku akan membutakanmu secepat itu!",
  ui_story_1021_10210402_87_dialog_content = "Sebuah tatapan yang memikat. Sayangnya, sudah terlambat...",
  ui_story_1021_10210402_88_dialog_content = "Ini berakhir saat es mencair!",
  ui_story_1021_10210402_89_dialog_content = "Yang Mulia?",
  ui_story_1021_10210402_90_dialog_content = "Ini bukan pertarunganmu. Sekarang pergilah lewat jalan yang telah kubuat!",
  ui_story_1021_10210402_91_dialog_content = "Tapi bagaimana denganmu?",
  ui_story_1021_10210402_92_dialog_content = "Aku akan berada tepat di belakangmu! Bisakah kamu membantuku, Pak Novio?",
  ui_story_1021_10210402_93_dialog_content = "Beri aku kekuatan, Terra Staff!",
  ui_story_1021_10210402_94_dialog_content = "Mengapa kau tidak membunuh mereka, tuanku?",
  ui_story_1021_10210402_95_dialog_content = "Karena aku melihat kemarahanku di mata rubah itu...",
  ui_story_1021_10210402_96_dialog_content = "Amarah adalah tanda kepengecutan. Saya bersumpah untuk tidak menjadi budak amarah.",
  ui_story_1021_10210402_97_dialog_content = "Ratu-ratu Snowland...",
  ui_story_1021_10210402_98_dialog_content = "Gletser yang mereka ciptakan tidak pernah mencair dalam Shadowfire-ku...",
  ui_story_1021_10210501_1_dialog_content = "...",
  ui_story_1021_10210501_2_dialog_content = "Yang Mulia... Mengapa Anda berhenti?",
  ui_story_1021_10210501_3_dialog_content = "Di setiap tempat yang kita lewati, pengaruh Darkflow telah memperlihatkan batuan dasar yang terletak di bawah lapisan es...",
  ui_story_1021_10210501_4_dialog_content = "Namun, area ini sama sekali tidak terpengaruh... Lebih jauh lagi, aku merasakan kekuatan unik yang memancar dari tempat ini.",
  ui_story_1021_10210501_5_dialog_content = "Aku tahu apa yang harus aku lakukan sekarang, Novio. Tolong jaga diri kalian semua dengan baik.",
  ui_story_1021_10210501_6_dialog_content = "Tapi... Yang Mulia...",
  ui_story_1021_10210501_7_dialog_content = "... Tolong biarkan aku pergi denganmu!",
  ui_story_1021_10210501_8_dialog_content = "...",
  ui_story_1021_10210501_9_dialog_content = "Tujuanmu di sini adalah melindungi sukumu, bukan sang ratu. Ingat itu.",
  ui_story_1021_10210501_10_dialog_content = "T-tapi...",
  ui_story_1021_10210501_11_dialog_content = "Hanya karena suku saya dalam bahaya besar sehingga kami tidak punya pilihan lain selain berlindung di altar...",
  ui_story_1021_10210501_12_dialog_content = "Apakah itu yang aku rasakan? Kekuatan pelindung dari altar?",
  ui_story_1021_10210501_13_dialog_content = "Yang Mulia... Aku... Aku tidak bisa membiarkan Anda mendekati altar!",
  ui_story_1021_10210501_14_dialog_content = "Berani-beraninya kau menghalangi jalan Ratu, Tiare! Apakah kau tahu apa yang sedang kau lakukan?",
  ui_story_1021_10210501_15_dialog_content = "... Saya bersumpah untuk melindungimu bahkan di tempat yang paling berbahaya sekalipun, tapi altar...",
  ui_story_1021_10210501_16_dialog_content = "Maafkan aku, tapi aku tidak bisa membiarkanmu pergi ke sana!",
  ui_story_1021_10210501_17_dialog_content = "Saya membuat janji kepada leluhur saya ketika saya menjadi kepala Suku Fox Salju!",
  ui_story_1021_10210501_18_dialog_content = "Apakah kebencianlah yang menghalangi saya mendekati altar?",
  ui_story_1021_10210501_19_dialog_content = "Aku... Sejujurnya, aku juga tidak sepenuhnya yakin...",
  ui_story_1021_10210501_20_dialog_content = "...",
  ui_story_1021_10210501_21_dialog_content = "Jika kamu meragukan konflik antara suku kamu dan istana kerajaan, kamu harus menghilangkannya sendiri dengan mencari kebenaran.",
  ui_story_1021_10210501_22_dialog_content = "Tapi demi semua Northland, saya harus menemuinya sekarang. Tolong percaya padaku, Tiare.",
  ui_story_1021_10210501_23_dialog_content = "Yang Mulia Ratu!",
  ui_story_1021_10210501_24_dialog_content = "Biarkan dia datang, Tiare.",
  ui_story_1021_10210501_25_dialog_content = "Hah? Siapa yang bilang itu?",
  ui_story_1021_10210501_26_dialog_content = "Tetua? Tapi... Apakah ini benar-benar—",
  ui_story_1021_10210501_27_dialog_content = "Saya akan mengizinkannya.",
  ui_story_1021_10210501_28_dialog_content = "Apakah Anda merasa lebih baik, Nyonya?",
  ui_story_1021_10210501_29_dialog_content = "Terima kasih telah bertanya, tubuh tua ini masih hidup.",
  ui_story_1021_10210501_30_dialog_content = "Itu rubah, Carleen... Rubah salju tua yang pernah kita temui sebelumnya adalah yang sedang berbicara!",
  ui_story_1021_10210501_31_dialog_content = "Kamu tidak seharusnya terkejut. Lagipula, sepertinya sudah pulih dengan cukup baik...",
  ui_story_1021_10210501_32_dialog_content = "Meskipun berdasarkan suaranya, sepertinya itu \"dia.\"",
  ui_story_1021_10210501_33_dialog_content = "...",
  ui_story_1021_10210501_34_dialog_content = "Mohon maafkan mereka, tua-tua. Mereka bukan dari Northland, dan saya akan meminta mereka untuk menunjukkan rasa hormat dan segera pergi.",
  ui_story_1021_10210501_35_dialog_content = "Itu tidak perlu. Mereka yang benar-benar menghormati tetua rubah salju telah lama berlalu. Anda hanya di sini untuk melunasi hutang, dan tidak lebih dari itu.",
  ui_story_1021_10210501_36_dialog_content = "Saya minta Anda menunjukkan lebih banyak hormat saat menyapa Ratu!",
  ui_story_1021_10210501_37_dialog_content = "Diam, Carleen!",
  ui_story_1021_10210501_38_dialog_content = "...",
  ui_story_1021_10210501_39_dialog_content = "Jangan khawatir, karena amarahku telah lama mereda. Yang tersisa dari makhluk kuno ini hanyalah bingkai yang terluka yang kamu lihat di depanmu.",
  ui_story_1021_10210501_40_dialog_content = "Meskipun segalanya, suku kami pernah menunjukkan rasa hormat kepada raja Anda. Keadaan gua yang menyedihkan ini harusnya bisa menjadi jawaban yang cocok untuk pertanyaan-pertanyaan Anda.",
  ui_story_1021_10210501_41_dialog_content = "Tua-tua, apakah benar ratu diperbolehkan untuk—",
  ui_story_1021_10210501_42_dialog_content = "Aku hanya berharap kau tak perlu menanggung hal-hal ini, Tiare.",
  ui_story_1021_10210501_43_dialog_content = "...",
  ui_story_1021_10210501_44_dialog_content = "Tua-tua, Eclipsite yang merambah Northland sudah sampai sejauh ini ke wilayahmu...",
  ui_story_1021_10210501_45_dialog_content = "Kekuatan alam melindungi tempat ini. Meskipun lemah, Eclipsites tidak memiliki cara untuk mendekati altar. Mari bersamaku.",
  ui_story_1021_10210501_46_dialog_content = "...",
  ui_story_1021_10210501_47_dialog_content = "<color=#e8d9bb>Awooo...</color>",
  ui_story_1021_10210501_48_dialog_content = "Apakah ini altar yang telah dilindungi oleh suku Tiare?",
  ui_story_1021_10210501_49_dialog_content = "Tak pernah kusangka akan melihat tempat seperti ini tersembunyi di dalam gua...",
  ui_story_1021_10210501_50_dialog_content = "Altar ini dibangun oleh leluhur kita ketika Northland pertama kali ada.",
  ui_story_1021_10210501_51_dialog_content = "Tempat ini... Siapa atau apa yang dihormati di sini?",
  ui_story_1021_10210501_52_dialog_content = "Altar ini berdiri untuk memuja Tiga Pohon Snowpine dan leluhur kita, pelindung Hutan Snowpine dan seluruh Northland.",
  ui_story_1021_10210501_53_dialog_content = "Tiga Pohon Snowpine... Maksudmu tiga tunggul ini?",
  ui_story_1021_10210501_54_dialog_content = "Membawa ambisi untuk melindungi Northland, mereka ditakdirkan untuk tumbang, namun kekuatan mereka tidak pernah meredup.",
  ui_story_1021_10210501_55_dialog_content = "Jika Tiga Pohon Snowpine memilih untuk bangkit kembali, pegunungan akan memberi jalan untuk mereka. Langit juga tidak pernah melupakan kekuatan mereka, dan dengan demikian memaksa cahaya menembus celah di atas.",
  ui_story_1021_10210501_56_dialog_content = "Tablet ini... Apakah ada semacam tulisan kuno di atasnya?",
  ui_story_1021_10210501_57_dialog_content = "Apa isinya?",
  ui_story_1021_10210501_58_dialog_content = "\"Itu memberikan vitalitas kepada raja yang lelah, yang pada gilirannya membawa kedamaian ke dunia.\"",
  ui_story_1021_10210501_59_dialog_content = "\"Perjanjian sakralnya mengubah kegelapan menjadi cahaya.\"",
  ui_story_1021_10210501_60_dialog_content = "\"Untuk menyaksikan keilahiannya adalah untuk menemukan kebahagiaan dan kedamaian.\"",
  ui_story_1021_10210501_61_dialog_content = "Mungkinkah ini...",
  ui_story_1021_10210501_62_dialog_content = "Catatan tertua yang diketahui tentang legenda Three Pines...",
  ui_story_1021_10210501_63_dialog_content = "Legenda yang populer di Northland?",
  ui_story_1021_10210501_64_dialog_content = "Pohon cemara pertama menjadi saksi kelahiran ratu pertama Northland, yang kedua mewakili kesetiaan para pengawal kerajaannya...",
  ui_story_1021_10210501_65_dialog_content = "Dan yang ketiga menjadi tongkat kerajaan ratu itu sendiri...",
  ui_story_1021_10210501_66_dialog_content = "Hahaha, ini hanya penuh dengan kesombongan para penerus kerajaan...",
  ui_story_1021_10210501_67_dialog_content = "Anggaplah diri kalian beruntung karena dia tidak ada di sini untuk mendengar ini, atau dia akan memberi kalian semua hukuman yang cukup keras.",
  ui_story_1021_10210501_68_dialog_content = "Namun, saya sangat paham betapa pentingnya asal-usul yang mulia bagi setiap kekaisaran.",
  ui_story_1021_10210501_69_dialog_content = "<color=#e8d9bb>Ding!</color>",
  ui_story_1021_10210501_70_dialog_content = "!",
  ui_story_1021_10210501_71_dialog_content = "Tua!",
  ui_story_1021_10210501_72_dialog_content = "M-Maaf atas gangguannya... Ada apa dengan Spotlightmu, Tiny One?",
  ui_story_1021_10210501_73_dialog_content = "Aku... Aku juga tidak tahu kenapa itu bisa terjadi...",
  ui_story_1021_10210501_74_dialog_content = "Apakah kalian berdua telah bersembunyi di sana selama ini?",
  ui_story_1021_10210501_75_dialog_content = "Urgh... Orang asing...",
  ui_story_1021_10210501_76_dialog_content = "Beritahu teman-temanmu untuk mengambil benda itu dan pergi, PlayerName! Tubuh tetua terlalu lemah untuk menanganinya!",
  ui_story_1021_10210501_77_dialog_content = "Tiny One!",
  ui_story_1021_10210501_78_dialog_content = "Kenapa... Kenapa ini tidak bekerja?",
  ui_story_1021_10210501_79_dialog_content = "<color=#e8d9bb>Wuush, wuush—</color>",
  ui_story_1021_10210501_80_dialog_content = "Tampaknya tombakku sedang bergolak dengan kekuatan...",
  ui_story_1021_10210501_81_dialog_content = "Apa sebenarnya ini?",
  ui_story_1021_10210501_82_dialog_content = "<color=#e8d9bb>Wuush, wuush—</color>",
  ui_story_1021_10210501_83_dialog_content = "Tongkatku beresonansi dengan altar...",
  ui_story_1021_10210501_84_dialog_content = "...",
  ui_story_1021_10210501_85_dialog_content = "Namun tampaknya Winter Force sang ratu adalah pilihannya...",
  ui_story_1021_10210501_86_dialog_content = "...A-apa?",
  ui_story_1021_10210501_87_dialog_content = "Aku akan berdiri di sisi seorang monarki, yang pada gilirannya akan membawa kedamaian ke dunia ini!",
  ui_story_1021_10210501_88_dialog_content = "(Suara itu...)",
  ui_story_1021_10210501_89_dialog_content = "Melalui kekuatanku, aku akan mengubah kegelapan menjadi cahaya!",
  ui_story_1021_10210501_90_dialog_content = "Selama orang lain merasa bahagia dan damai saat melihatku, saya akan lebih dari cukup puas...",
  ui_story_1021_10210501_91_dialog_content = "Hahaha... Kalian berdua bisa sangat arogan kadang-kadang...",
  ui_story_1021_10210501_92_dialog_content = "Kamu pikir dirimu berbeda? Hahaha...",
  ui_story_1021_10210501_93_dialog_content = "Altar bergema dengan tiga suara yang berbeda...",
  ui_story_1021_10210501_94_dialog_content = "Aku juga mendengarnya...",
  ui_story_1021_10210501_95_dialog_content = "Apakah ini... suara-suaranya dewa?",
  ui_story_1021_10210501_96_dialog_content = "...",
  ui_story_1021_10210501_97_dialog_content = "Yang ilahi... telah mengakui kekuatanmu...",
  ui_story_1021_10210501_98_dialog_content = "Baru saja, tak terhitung banyaknya visi berkelebat di depan mataku...",
  ui_story_1021_10210501_99_dialog_content = "Yang ilahi hanya mengakui kekuatan mereka yang layak...",
  ui_story_1021_10210501_100_dialog_content = "Dengan kata lain...",
  ui_story_1021_10210501_101_dialog_content = "Ratu pertamamu... Dia benar-benar mendapatkan berkat mereka...",
  ui_story_1021_10210501_102_dialog_content = "Ini...",
  ui_story_1021_10210501_103_dialog_content = "Ini akan sulit dibayangkan oleh leluhur kita yang telah meninggal...",
  ui_story_1021_10210501_104_dialog_content = "<color=#e8d9bb>Mati!</color>",
  ui_story_1021_10210501_105_dialog_content = "Majulah dan penuhi janjimu, dan kau akan selalu menemukan tempat beristirahat di Northland.",
  ui_story_1021_10210501_106_dialog_content = "Ragu, dan aku akan menggantung kepala memalukanmu di pohon salju untuk dilihat oleh keturunanmu!",
  ui_story_1021_10210501_107_dialog_content = "Hah? Pikiran siapa ini? Aku tidak menggunakan kekuatanku barusan...",
  ui_story_1021_10210501_108_dialog_content = "Semua orang masih berdiri di sekitar altar seperti sebelumnya...",
  ui_story_1021_10210501_109_dialog_content = "Ini... Ini adalah benteng yang dulunya tak dapat ditembus di perbatasan Northland...",
  ui_story_1021_10210501_110_dialog_content = "Mungkinkah kita—",
  ui_story_1021_10210501_111_dialog_content = "Ya. Altar ini berada di dalam halaman benteng.",
  ui_story_1021_10210501_112_dialog_content = "...",
  ui_story_1021_10210501_113_dialog_content = "Rakyat Kerajaan Beku, pergilah dari tempat ini.",
  ui_story_1021_10210501_114_dialog_content = "...",
  ui_story_1021_10210501_115_dialog_content = "Apakah dia... berbicara kepada kita?",
  ui_story_1021_10210501_116_dialog_content = "Pakaian kita... Dibandingkan dengan mereka, ini...",
  ui_story_1021_10210501_117_dialog_content = "Dengan mencuri kekuatan dari snowpines, Anda telah merampok kami dari perlindungan kami.",
  ui_story_1021_10210501_118_dialog_content = "Tapi tandai kata-kata saya, rakyat kita tidak akan pernah melupakan janji kita kepada mereka!",
  ui_story_1021_10210501_119_dialog_content = "Bahkan jika kita semua binasa di hutan yang telah memberi kita kehidupan, bahkan jika kita dihancurkan oleh beban langit yang menindas ini...",
  ui_story_1021_10210501_120_dialog_content = "Saya tidak akan pernah mengakui raja selain raja saya sendiri.",
  ui_story_1021_10210501_121_dialog_content = "...",
  ui_story_1021_10210501_122_dialog_content = "Lord Rode...",
  ui_story_1021_10210501_123_dialog_content = "Hagen! Bawakan aku baju besi yang dianugerahkan oleh raja kepadaku, agar aku dapat memberi penghargaan kepada para pria yang memimpin serangan kita!",
  ui_story_1021_10210501_124_dialog_content = "Lord Rode... Harap kenakan baju zirah ini dengan bangga.",
  ui_story_1021_10210501_125_dialog_content = "Ini tidak akan menjadi pertarungan terakhirku, Hagen! Selama aku memiliki kamu di sisiku, aku tidak akan pernah jatuh!",
  ui_story_1021_10210501_126_dialog_content = "...",
  ui_story_1021_10210501_127_dialog_content = "Ayo pergi, Hagen.",
  ui_story_1021_10210501_128_dialog_content = "Aku akan selalu berdiri di sisimu, Lord Rode...",
  ui_story_1021_10210501_129_dialog_content = "...",
  ui_story_1021_10210501_130_dialog_content = "Lord Rode adalah seorang pria yang hebat dan kuat namun tetap sangat peduli pada prajuritnya. Kami yakin bahwa dia akan menjadi raja berikutnya dari Northland.",
  ui_story_1021_10210501_131_dialog_content = "Teman-teman! Demi raja dan seluruh Northland, kita bergerak menuju pertempuran!",
  ui_story_1021_10210501_132_dialog_content = "Menuju pertempuran!",
  ui_story_1021_10210501_133_dialog_content = "Menuju pertempuran!",
  ui_story_1021_10210501_134_dialog_content = "<color=#e8d9bb>Wuush, wuush—</color>",
  ui_story_1021_10210501_135_dialog_content = "Hilang... Apakah itu tadi \"kekuatan alam\"?",
  ui_story_1021_10210501_136_dialog_content = "...",
  ui_story_1021_10210501_137_dialog_content = "Jadi Anda pernah menjadi pengawal Lord Rode, tetua?",
  ui_story_1021_10210501_138_dialog_content = "Ya, Tiare. Dia adalah leluhurmu dan seorang suku yang bangga, jenis yang telah kau idolakan sejak kau masih anak-anak.",
  ui_story_1021_10210501_139_dialog_content = "Dengan kondisi suku kita saat ini, saya tidak memiliki cara untuk menghadapinya sekarang.",
  ui_story_1021_10210501_140_dialog_content = "Bekas luka di wajahmu... Apakah kamu mendapatkannya saat bertarung dengan Eclipsites dulu?",
  ui_story_1021_10210501_141_dialog_content = "Tidak perlu meratapi masa lalu yang begitu jauh, Tiare.",
  ui_story_1021_10210501_142_dialog_content = "Meski luka kita masih terlihat hingga hari ini, yang tidak kamu lihat adalah kemenangan kita atas Eclipsite pada hari itu, serta perayaan unggun api kita di Hutan Snowpine.",
  ui_story_1021_10210501_143_dialog_content = "Kenapa kamu tidak memberitahu saya tentang semua ini?",
  ui_story_1021_10210501_144_dialog_content = "Jika kamu tahu, kamu pasti akan meninggalkan Winter Palace untuk melindungi tempat ini, sama seperti sumpah leluhurmu.",
  ui_story_1021_10210501_145_dialog_content = "Aku tahu kamu terlalu baik, Tiare. Meskipun sebagai penjaga ratu, darah orang-orang kita mengalir di pembuluh darahmu.",
  ui_story_1021_10210501_146_dialog_content = "Hari akan tiba ketika suku kita tidak ada lagi. Memberitahumu hal-hal ini akan sia-sia.",
  ui_story_1021_10210501_147_dialog_content = "Selain itu, Anda sudah memilih raja Anda.",
  ui_story_1021_10210501_148_dialog_content = "...",
  ui_story_1021_10210501_149_dialog_content = "Dan orang yang telah kamu sumpahi kesetiaanmu telah membuktikan dirinya layak menerima kekuatan ilahi. Kamu tidak memiliki alasan untuk tetap tinggal dan melindungi kami lagi.",
  ui_story_1021_10210501_150_dialog_content = "...",
  ui_story_1021_10210501_151_dialog_content = "Tapi... Lalu bagaimana dengan \"kekuatan yang dicuri\" yang diceritakan oleh Lord Rode?",
  ui_story_1021_10210501_152_dialog_content = "Beacon...",
  ui_story_1021_10210501_153_dialog_content = "Beacon? Kamu maksud Beacon dari Northland?",
  ui_story_1021_10210501_154_dialog_content = "\"Untuk menyaksikan keilahiannya adalah untuk menemukan kebahagiaan dan kedamaian.\"",
  ui_story_1021_10210501_155_dialog_content = "...",
  ui_story_1021_10210501_156_dialog_content = "Untuk membasmi Eclipsites dan membawa cahaya ke seluruh Northland...",
  ui_story_1021_10210501_157_dialog_content = "Leluhur dari keluarga kerajaan diberikan sebuah pohon salju yang mengandung kekuatan alam.",
  ui_story_1021_10210501_158_dialog_content = "Pohon snowpine memotong dirinya sendiri, dan kayunya menjadi bahan bakar untuk Spark, yang berfungsi sebagai Beacon pertama di Northland.",
  ui_story_1021_10210501_159_dialog_content = "Sejak saat itu, seluruh Northland telah diliputi oleh cahayanya... Akibatnya, Hutan Snowpine telah secara bertahap kehilangan kekuatannya untuk mengusir Eclipsite.",
  ui_story_1021_10210501_160_dialog_content = "...",
  ui_story_1021_10210501_161_dialog_content = "Apakah kau melihat ini dalam penglihatanmu?",
  ui_story_1021_10210501_162_dialog_content = "Ya. Pohon salju mengakui keluarga kerajaan dan memilih untuk menjadi Beacon dari Northland.",
  ui_story_1021_10210501_163_dialog_content = "Hanya dengan begitu mereka dapat mencapai tujuan mereka untuk melindungi tanah kita...",
  ui_story_1021_10210501_164_dialog_content = "Oh, begitu…",
  ui_story_1021_10210501_165_dialog_content = "Dengan kata lain, keluarga kerajaan tidak pernah mencuri kekuatan dari pohon salju, bukan?",
  ui_story_1021_10210501_166_dialog_content = "...",
  ui_story_1021_10210501_167_dialog_content = "...",
  ui_story_1021_10210501_168_dialog_content = "Sebelum menjadi Beacon dari Northland, para dewa menggunakan kekuatan mereka untuk melindungi kita di sini. Saat itu, kekuatan mereka belum dicabut.",
  ui_story_1021_10210501_169_dialog_content = "Leluhur kita membangun altar ini untuk menghormati mereka, memuja mereka dan menunjukkan keyakinan serta harapan kita setiap hari.",
  ui_story_1021_10210501_170_dialog_content = "Mereka menyalakan lampu minyak pinus bahkan di musim dingin yang paling dingin sekalipun, semua demi menjamin kedamaian dan kemakmuran suku kami.",
  ui_story_1021_10210501_171_dialog_content = "Namun, berjalannya waktu membawa perubahan tak terduga sepanjang tahun. Panen yang gagal, penyakit, dan segala macam kesulitan menimpa suku kami...",
  ui_story_1021_10210501_172_dialog_content = "Ketika pohon salju ditebang, kebencian dan putus asa dengan cepat menimpa orang-orang kami.",
  ui_story_1021_10210501_173_dialog_content = "Di bawah pemerintahan raja, kami mulai berdoa di altar siang dan malam untuk mendapatkan restu dari yang ilahi.",
  ui_story_1021_10210501_174_dialog_content = "Namun, Eclipsite tetap datang, dan saya dipaksa untuk menyaksikan kelahiran dan kematian begitu banyak dari kita. Meskipun kami memohon dengan sangat putus asa, yang ilahi tidak pernah menjawab kami...",
  ui_story_1021_10210501_175_dialog_content = "Kesunyian mereka adalah bukti bahwa suku kami ditakdirkan untuk punah sebagai hukuman atas kebencian kami.",
  ui_story_1021_10210501_176_dialog_content = "Itulah kisah dari jenis kita. Sebelum kamu lahir, saya yakin bahwa saya akan bertemu akhir saya seperti ini...",
  ui_story_1021_10210501_177_dialog_content = "Elder...",
  ui_story_1021_10210501_178_dialog_content = "Aku sudah terlalu tua, Tiare. Yang aku miliki untuk menopangku sekarang hanyalah kenangan-kenangan ini.",
  ui_story_1021_10210501_179_dialog_content = "Beritahu saya, sudahkah Anda membuat pilihan? Dan apakah Anda siap untuk mematuhinya seumur hidup Anda?",
  ui_story_1021_10210501_180_dialog_content = "Aku ingin melindungi suku kita, tetua... tapi aku juga ingin membantu sang Ratu.",
  ui_story_1021_10210501_181_dialog_content = "Jika ada jurang antara keluarga kerajaan dan suku kami, tolong beri tahu saya, dan saya akan melakukan segala yang ada dalam kekuatan saya untuk menjembatani itu.",
  ui_story_1021_10210501_182_dialog_content = "Untuk melindungi Northland dari Eclipsite, bagaimana jika kita saling percaya satu sama lain untuk saat ini dan berdiri bersama-sama?",
  ui_story_1021_10210501_183_dialog_content = "...",
  ui_story_1021_10210501_184_dialog_content = "Tua, ada sesuatu yang selalu ada dalam ingatanku, yang berkaitan dengan Primal Haven.",
  ui_story_1021_10210501_185_dialog_content = "Aku sempat melihatnya dalam penglihatanku barusan...",
  ui_story_1021_10210501_186_dialog_content = "Snowpine yang berfungsi sebagai Beacon pertama Northland, pohon yang pernah berakar di sini, dibuat kuat oleh energi kuno yang memancar dari tempat ini.",
  ui_story_1021_10210501_187_dialog_content = "Benarkah asumsi saya bahwa Primal Haven ada di suatu tempat dekat altar?",
  ui_story_1021_10210501_188_dialog_content = "Jika demikian, apakah Anda tahu cara memanggilnya dan menggunakan kekuatannya untuk mempertahankan Northland?",
  ui_story_1021_10210501_189_dialog_content = "Cara untuk memanggil Primal Haven? Heheh...",
  ui_story_1021_10210501_190_dialog_content = "Kamu harus memadamkan Beacon di Northland dan membiarkan tunas baru tumbuh dari tiga pohon yang telah tumbang ini.",
  ui_story_1021_10210501_191_dialog_content = "...",
  ui_story_1021_10210501_192_dialog_content = "Selain Beacon, ada dua pohon salju lainnya yang harus dikembalikan ke altar, benar?",
  ui_story_1021_10210501_193_dialog_content = "Benar.",
  ui_story_1021_10210501_194_dialog_content = "Penatua... Apakah itu benar?",
  ui_story_1021_10210501_195_dialog_content = "...",
  ui_story_1021_10210501_196_dialog_content = "Tapi Beacon Northland belum pernah padam... Jika api itu padam, bukankah itu berarti Winter Palace dan rakyat kerajaan akan—",
  ui_story_1021_10210501_197_dialog_content = "Apa yang terjadi dengan menjadi \"pengawal Yang Mulia Ratu\"?",
  ui_story_1021_10210501_198_dialog_content = "Ratu Anda ingin memanggil Primal Haven dan melunasi hutangnya kepada suku kita. Apakah Anda berusaha menentangnya?",
  ui_story_1021_10210501_199_dialog_content = "Tentu saja tidak! Saya akan selalu mengikuti ratu ke mana pun dia pergi! Tapi...",
  ui_story_1021_10210501_200_dialog_content = "Lihatlah aku, Tiare.",
  ui_story_1021_10210501_201_dialog_content = "...",
  ui_story_1021_10210501_202_dialog_content = "Tolong percayalah padaku. Aku menerima kekuatan ini, dan aku tahu apa yang harus kulakukan untuk membalas berkat tersebut.",
  ui_story_1021_10210501_203_dialog_content = "Sebagai penjagaku, aku berharap kamu dapat membantuku memanggil Primal Haven untuk melindungi seluruh Northland.",
  ui_story_1021_10210501_204_dialog_content = "Terserah padamu untuk membawa kembali dua pohon pinus salju lainnya. Apakah kamu mengerti?",
  ui_story_1021_10210501_205_dialog_content = "Yang Mulia...",
  ui_story_1021_10210501_206_dialog_content = "Semua yang berada di bawah salju adalah Northland, sebuah kerajaan yang telah saya sumpah untuk melindungi dengan hidup saya.",
  ui_story_1021_10210501_207_dialog_content = "Cahaya Beacon tidak mencapai tempat ini, jadi adalah tanggung jawab saya untuk melindungi rumah Anda dari Eclipsites.",
  ui_story_1021_10210501_208_dialog_content = "...",
  ui_story_1021_10210501_209_dialog_content = "Novio, kamu akrab dengan lokasi pohon salju, 'kan?",
  ui_story_1021_10210501_210_dialog_content = "Ya, Yang Mulia. Tenanglah, kami akan mengambil mereka sementara Anda menangkis Eclipsite.",
  ui_story_1021_10210501_211_dialog_content = "...",
  ui_story_1021_10210501_212_dialog_content = "Saya akan pergi bersama Tuan Novio dan yang lainnya sekarang, tua...",
  ui_story_1021_10210501_213_dialog_content = "Pergilah. Ikuti suar Anda sendiri dan penuhi janji Anda kepada ratu Anda.",
  ui_story_1021_10210501_214_dialog_content = "Baiklah!",
  ui_story_1021_10210601_1_dialog_content = "Queen Bethlehem sedang melawan Eclipsite seorang diri... Apakah benar tidak ada yang bisa kita lakukan untuk membantunya?",
  ui_story_1021_10210601_2_dialog_content = "Terakhir kali Yang Mulia Ratu menyelamatkanku, dia memberikan kekuatan unikku. Dia telah melakukan banyak hal untukku, dan namun aku tidak bisa berjuang di sisinya sekarang...",
  ui_story_1021_10210601_3_dialog_content = "Dan dengan alasan yang baik. Setelah pertemuanmu sebelumnya dengan Eclipsite itu, kamu seharusnya tahu betapa kuatnya dia.",
  ui_story_1021_10210601_4_dialog_content = "Selain itu, kamu masih membantu sang ratu dengan mengambilkan pohon salju untuknya.",
  ui_story_1021_10210601_5_dialog_content = "Darkflow yang memancar dari semburan ini telah mengikis dataran salju Northland sepanjang waktu ini...",
  ui_story_1021_10210601_6_dialog_content = "Yang Mulia Ratu datang kepada tetua dalam mencari cara untuk membasmi kejahatan dari tanah kita. Dengan kata lain, untuk memanggil Primal Haven.",
  ui_story_1021_10210601_7_dialog_content = "Jadi, di mana kita bisa menemukan dua pohon salju lainnya, Tuan Novio?",
  ui_story_1021_10210601_8_dialog_content = "Selain yang ada di Beacon, dua snowpines lainnya berada di lokasi yang berbeda, di mana mereka terus melindungi Northland hingga hari ini.",
  ui_story_1021_10210601_9_dialog_content = "Lanjutkan melindungi Northland?",
  ui_story_1021_10210601_10_dialog_content = "Benar. Satu disimpan di dalam Winter Palace, sementara yang lain berada di tempat kelahiranmu.",
  ui_story_1021_10210601_11_dialog_content = "Namun, perjalanan waktu mungkin telah membuat mereka hampir tidak dikenali sekarang. Mungkin legenda tentang Tiga Pohon Pinus akan memberikan lebih banyak pencerahan tentang hal ini?",
  ui_story_1021_10210601_12_dialog_content = "Meski kekuatan alam biasanya terpendam, seharusnya itu akan beresonansi dengan kekuatan yang diberikan padamu oleh sang ratu ketika kamu mendekati pohon salju.",
  ui_story_1021_10210601_13_dialog_content = "Dipahami. Terima kasih, Pak Novio!",
  ui_story_1021_10210601_14_dialog_content = "Baik Queen Bethlehem maupun rubah tua mengerti apa artinya melindungi dengan nyawa mereka.",
  ui_story_1021_10210601_15_dialog_content = "Sebagai penjaga Northland, kamu juga memiliki peran, Tiare. Kamu sedang menjalankan misi untuk melindungi.",
  ui_story_1021_10210601_16_dialog_content = "Serahkan padaku. Aku tidak akan mengecewakan semua orang!",
  ui_story_1021_10210601_17_dialog_content = "Tunggu, Tiare! Biarkan aku pergi denganmu!",
  ui_story_1021_10210601_18_dialog_content = "Kamu?",
  ui_story_1021_10210601_19_dialog_content = "Saya juga bisa membantu!",
  ui_story_1021_10210601_20_dialog_content = "Tapi, apakah kamu benar-benar yakin bisa menyusulku? Atau lebih tepatnya, apakah kamu mau kugendong lagi?",
  ui_story_1021_10210601_21_dialog_content = "Membawa?",
  ui_story_1021_10210601_22_dialog_content = "... Jika itu berarti saya bisa membantu kamu, maka saya akan melakukannya!",
  ui_story_1021_10210601_23_dialog_content = "Kemampuan psikis PlayerName mungkin bisa membantu.",
  ui_story_1021_10210601_24_dialog_content = "Saya mengerti... Maka saya serahkan urusan di sini kepada Anda dan yang lainnya, Pak Novio!",
  ui_story_1021_10210601_25_dialog_content = "PlayerName dan aku akan segera kembali!",
  ui_story_1021_10210601_26_dialog_content = "H-Hah?",
  ui_story_1021_10210601_27_dialog_content = "Dan begitu saja, mereka pergi...",
  ui_story_1021_10210601_28_dialog_content = "Cairan yang sarat Darkflow perlahan merayap menuju istana...",
  ui_story_1021_10210601_29_dialog_content = "Sepertinya bahkan Lumina yang mengesankan dari Nikinis sekarang tidak berdaya untuk menahannya.",
  ui_story_1021_10210601_30_dialog_content = "Kita hanya bisa berharap bahwa Tiare kembali dengan pohon salju tepat waktu. Masih ada harapan untuk kelangsungan hidup sukunya...",
  ui_story_1021_10210601_31_dialog_content = "Izinkan saya untuk bertugas sebagai penjaga Northland, Tuan Novio. Saya juga ingin berkontribusi dalam melindungi kerajaan!",
  ui_story_1021_10210601_32_dialog_content = "<color=#e8d9bb>Di Sisi Lain Hutan</color>",
  ui_story_1021_10210601_33_dialog_content = "Yah, karena kita tidak memiliki cara untuk kembali ke Gurun Rediesel saat ini, pilihan terbaik kita adalah membantu PlayerName dan yang lainnya menyelamatkan hari ini.",
  ui_story_1021_10210601_34_dialog_content = "Apakah kamu benar-benar serius?",
  ui_story_1021_10210601_35_dialog_content = "Tentu saja! Lagipula, semua ini demi kebaikan Rediesel.",
  ui_story_1021_10210601_36_dialog_content = "PlayerName telah banyak membantu Sinsa dalam situasi Eve.",
  ui_story_1021_10210601_37_dialog_content = "Karena itu, Sinsa selalu bersedia membantu kapan saja PlayerName dalam bahaya.",
  ui_story_1021_10210601_38_dialog_content = "Mereka sangat akrab, kedua orang itu. Sinsa hanya suka berpura-pura tidak tahu.",
  ui_story_1021_10210601_39_dialog_content = "Jadi jika kita membantu mereka atas nama Rediesel Wrench, dia akan berhutang budi pada kita!",
  ui_story_1021_10210601_40_dialog_content = "Kamu jenius, Roy! Tidak heran Honcho Sinsa selalu bilang kita bisa belajar satu atau dua hal darimu!",
  ui_story_1021_10210601_41_dialog_content = "Tentu saja, ayo kita bergerak sekarang. Kita akan menghabisi semua Eclipsite yang menghalangi jalan kita saat kita mengikuti aliran cairan hitam itu!",
  ui_story_1021_10210601_42_dialog_content = "<color=#e8d9bb>Dekat Perbatasan Northland</color>",
  ui_story_1021_10210601_43_dialog_content = "(Eclipsian) Tuanku... Kita tidak bisa melanjutkan lagi...",
  ui_story_1021_10210601_44_dialog_content = "(Eclipsian) Mereka bilang cahaya dari mercusuar terkutuk itu akan merobek tubuh kita.",
  ui_story_1021_10210601_45_dialog_content = "(Eclipsian) Es dan api tidak berarti apa-apa bagi kami, begitu pula cahaya dari mercusuar jahat itu.",
  ui_story_1021_10210601_46_dialog_content = "<color=#e8d9bb>Awoooo!</color>",
  ui_story_1021_10210601_47_dialog_content = "(Eclipsian) Binatang putih itu sedang mengaum ke arah kita.",
  ui_story_1021_10210601_48_dialog_content = "(Eclipsian) Setelah bertahun-tahun, ketika benteng dan para pengawalnya telah berubah menjadi debu, mereka masih tetap ada.",
  ui_story_1021_10210601_49_dialog_content = "(Eclipsian) Northland benar-benar tempat yang indah untuk berada.",
  ui_story_1021_10210601_50_dialog_content = "Pedang Es!",
  ui_story_1021_10210601_51_dialog_content = "Semua penyerang Northland akan menemui ajal mereka di salju!",
  ui_story_1021_10210601_52_dialog_content = "Bahkan setelah aku membiarkanmu, kamu memilih untuk mengejarku dengan tekad yang begitu gigih.",
  ui_story_1021_10210601_53_dialog_content = "Katakan padaku, apakah kamu berniat untuk menyegel kita dalam tembok es sekali lagi?",
  ui_story_1021_10210601_54_dialog_content = "... Apa yang kamu ketahui tentang <color=#FFB400>pertempuran itu</color>?",
  ui_story_1021_10210601_55_dialog_content = "Sepertinya kamu masih cukup muda.",
  ui_story_1021_10210601_56_dialog_content = "(Eclipsian) Pergi. Temani teman kita.",
  ui_story_1021_10210601_57_dialog_content = "(Eclipsian) Ya, Lord saya!",
  ui_story_1021_10210700_1_dialog_content = "... Ratu mengatakan bahwa aku harus menyampaikan pesan ini secepat mungkin!",
  ui_story_1021_10210700_2_dialog_content = "Begini, kamu tahu...",
  ui_story_1021_10210700_3_dialog_content = "Jadi, ekspedisi gabungan sudah dimulai bahkan sebelum memasuki Dark Zone.",
  ui_story_1021_10210700_4_dialog_content = "Meski begitu, kita perlu mempertahankan pos di Northland. Ayo, Vivian, kita akan segera berangkat ke Northland.",
  ui_story_1021_10210700_5_dialog_content = "Baik, Grand Marshal.",
  ui_story_1021_10210700_6_dialog_content = "Kamu juga akan menemaniku, Ms. Blanc.",
  ui_story_1021_10210700_7_dialog_content = "Baik tuan ku.",
  ui_story_1021_10210700_8_dialog_content = "Apakah kita juga pergi, Bethel?",
  ui_story_1021_10210700_9_dialog_content = "Tentu saja. Umbraton tidak bisa melewatkan ini.",
  ui_story_1021_10210700_10_dialog_content = "Tapi Northland berada di ketinggian yang sangat tinggi...",
  ui_story_1021_10210700_11_dialog_content = "Kita semua berada di posisi yang sama di sini, Lady Bethel. Anda dipersilakan untuk ikut bersama kami di pesawat kami jika Anda mau.",
  ui_story_1021_10210700_12_dialog_content = "Sangat dihargai!",
  ui_story_1021_10210700_13_dialog_content = "T-Tiare... Apakah aku tidak bisa berjalan hanya untuk sebagian perjalanan? Rasanya punggungku seperti mau patah menjadi dua...",
  ui_story_1021_10210700_14_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_1021_10210700_15_dialog_content = "Tak bisa kubayangkan kamu menggendongku sejauh ini... dan di pundakmu, lagi!",
  ui_story_1021_10210700_16_dialog_content = "Kamu bilang aku bisa menggendongmu, jadi aku lakukan. Apakah semua orang asing ini cenderung mengatakan apa yang mereka tidak maksud?",
  ui_story_1021_10210700_17_dialog_content = "Tidak sama sekali... Sejujurnya, saya tidak berpikir kamu serius tadi...",
  ui_story_1021_10210700_18_dialog_content = "Tapi sepertinya aku sudah tahu bagaimana cara kerja pemimpin rubah salju sekarang!",
  ui_story_1021_10210700_19_dialog_content = "Fiuh! Saya bisa melihat Istana Musim Dingin dari sini...",
  ui_story_1021_10210700_20_dialog_content = "Grr...",
  ui_story_1021_10210700_21_dialog_content = "Eh, kamu—",
  ui_story_1021_10210700_22_dialog_content = "<color=#e8d9bb>Awoo!</color>",
  ui_story_1021_10210700_23_dialog_content = "Kamu mendapat tanggapan!",
  ui_story_1021_10210700_24_dialog_content = "Ya. Itulah cara saya dan rubah-rubah berkomunikasi satu sama lain.",
  ui_story_1021_10210700_25_dialog_content = "Jadi, apa yang baru saja kamu katakan?",
  ui_story_1021_10210700_26_dialog_content = "Saya memberi tahu mereka bahwa air hitam belum mencapai tempat ini. Rubah-rubah itu mengatakan mereka akan memberi tahu Tuan Novio.",
  ui_story_1021_10210700_27_dialog_content = "Kamu bisa menyampaikan informasi sebanyak itu hanya dengan satu kali melolong?",
  ui_story_1021_10210700_28_dialog_content = "Itu benar! Kamu juga harus mencobanya!",
  ui_story_1021_10210700_29_option_content = "Aku? M-Mungkin tidak...",
  ui_story_1021_10210700_30_dialog_content = "Mengapa? Apakah itu terlalu memalukan untukmu?",
  ui_story_1021_10210700_31_dialog_content = "T-Tidak mungkin! Apa yang membuatmu mengatakan itu?",
  ui_story_1021_10210700_32_dialog_content = "Ketika pertama kali datang ke Winter Palace, beberapa pengawal sering meniruku...",
  ui_story_1021_10210700_33_dialog_content = "Pada awalnya, saya pikir raungan saya terlalu keras, tetapi kemudian saya menyadari bahwa volume tidak ada hubungannya dengan itu.",
  ui_story_1021_10210700_34_dialog_content = "Namun, saya tidak pernah merasa malu karena itu! Saya berusaha sebaik mungkin untuk menghindari menyalak di Istana Musim Dingin...",
  ui_story_1021_10210700_35_dialog_content = "Tapi saat larut malam atau ketika aku sedang berpatroli sendirian, aku masih suka berkomunikasi dengan rubah-rubah seperti ini.",
  ui_story_1021_10210700_36_dialog_content = "Tidak ada yang perlu dipermalukan! Dengarkan ini—",
  ui_story_1021_10210700_37_dialog_content = "Aghhh!",
  ui_story_1021_10210700_38_option_content = "Uwaaagh!",
  ui_story_1021_10210700_39_dialog_content = "Sehat?",
  ui_story_1021_10210700_40_dialog_content = "...",
  ui_story_1021_10210700_41_dialog_content = "Raut wajahmu itu... Apakah benar-benar seburuk itu?",
  ui_story_1021_10210700_42_dialog_content = "Tidak, aku hanya mencoba memahami apa yang baru saja kamu katakan... Apakah kamu meminta makanan, atau mengatakan cuacanya bagus?",
  ui_story_1021_10210700_43_dialog_content = "Mengapa kamu tidak mencoba lagi?",
  ui_story_1021_10210700_44_dialog_content = "Ah... Mungkin nanti.",
  ui_story_1021_10210700_45_dialog_content = "Cukup angkat kepalamu dan luruskan lehermu seperti ini.",
  ui_story_1021_10210700_46_dialog_content = "Angkat kepala... dan luruskan leherku...",
  ui_story_1021_10210700_47_dialog_content = "Itu dia! Sekarang buka mulutmu, temukan kata-kata yang ingin kamu ucapkan dari dalam hatimu, dan teriakkan semuanya sekaligus!",
  ui_story_1021_10210700_48_dialog_content = "Grr...",
  ui_story_1021_10210700_49_dialog_content = "<color=#e8d9bb>Awoo!</color>",
  ui_story_1021_10210700_50_dialog_content = "Nah, aku benar, 'kan?",
  ui_story_1021_10210700_51_dialog_content = "Wow! Saya tidak tahu apakah pesan saya jelas atau tidak, tapi senang mendengar adanya respon!",
  ui_story_1021_10210700_52_dialog_content = "Mendengar kegembiraanmu juga membuat para rubah merasa bahagia.",
  ui_story_1021_10210700_53_dialog_content = "Baiklah, sepertinya kita sudah cukup istirahat. Sekarang saatnya membawamu ke Winter Palace sekaligus!",
  ui_story_1021_10210700_54_dialog_content = "H-Hei! Setidaknya biarkan aku menghadap ke depan!",
  ui_story_1021_10210700_55_dialog_content = "Halo, Nona Zarya! Anda telah mengumpulkan banyak bijih hari ini, bukan?",
  ui_story_1021_10210700_56_dialog_content = "Benar! Ini adalah pekerjaan pertamaku dari ratu, jadi tentu saja, aku harus berusaha sebaik mungkin!",
  ui_story_1021_10210700_57_dialog_content = "Saya dengar Luminatics kamu sangat kuat. Menambang bijih sebanyak ini pasti mudah bagi seseorang sepertimu!",
  ui_story_1021_10210700_58_dialog_content = "Tidak sepenuhnya... Saya masih sering membekukan diri saya sendiri secara tidak sengaja...",
  ui_story_1021_10210700_59_dialog_content = "Untungnya saya hanya membekukan diri saya sebagian, tapi saya masih memiliki banyak hal yang harus dipelajari! Pokoknya, saya akan ke Winter Palace untuk melapor kepada ratu. Selamat tinggal!",
  ui_story_1021_10210700_60_dialog_content = "Oh... Tapi dari yang saya dengar, Yang Mulia Ratu tidak ada di Winter Palace sekarang...",
  ui_story_1021_10210700_61_dialog_content = "<color=#e8d9bb>Wuuss!</color>",
  ui_story_1021_10210700_62_dialog_content = "Apa-",
  ui_story_1021_10210700_63_dialog_content = "Ini PlayerName dan Tiare... Tapi apa yang mereka lakukan di sini?",
  ui_story_1021_10210700_64_dialog_content = "Kami telah mencari di setiap sudut tempat ini, tetapi tombak Anda tidak pernah merespon sama sekali...",
  ui_story_1021_10210700_65_dialog_content = "Mungkin energi kuno ini telah terlelap terlalu lama...",
  ui_story_1021_10210700_66_dialog_content = "Novio mengatakan bahwa kita harus mencari petunjuk dalam legenda. Ada ide apa yang dimaksudnya dengan itu?",
  ui_story_1021_10210700_67_dialog_content = "Pohon salju di Winter Palace seharusnya sesuai dengan bagian pertama legenda: \"Ia memberikan vitalitas kepada raja yang lelah, yang pada gilirannya membawa kedamaian ke dunia.\"",
  ui_story_1021_10210700_68_dialog_content = "Jadi, bagaimana biasanya sang ratu mengembalikan kekuatannya saat dia lelah?",
  ui_story_1021_10210700_69_dialog_content = "Ratu tidak banyak menghabiskan waktu di Winter Palace. Lebih sering daripada tidak, dia berada di kamar tidurnya, di ruang makan, atau di taman di belakang istana.",
  ui_story_1021_10210700_70_dialog_content = "Sepertinya ratu meredakan stresnya dengan cara yang sama denganku—dengan makan, tidur, dan banyak waktu luang.",
  ui_story_1021_10210700_71_dialog_content = "Entah kenapa, aku rasa sang Ratu tidak terlibat dalam hal-hal yang kamu bicarakan...",
  ui_story_1021_10210700_72_dialog_content = "Kenapa kalian berdua terburu-buru mencari ratu? Apa ada masalah?",
  ui_story_1021_10210700_73_dialog_content = "Bijih ini...",
  ui_story_1021_10210700_74_dialog_content = "Jangan khawatir. Bijih ini bukan dari sekitar rumahmu, saya janji!",
  ui_story_1021_10210700_75_dialog_content = "Apa yang kamu lakukan di sini, Zarya?",
  ui_story_1021_10210700_76_dialog_content = "Tidakkah kalian melihatku barusan? Aku melihat kalian berdua bergegas masuk ke istana, jadi aku pikir kalian memiliki urusan penting dengan sang Ratu.",
  ui_story_1021_10210700_77_dialog_content = "Tapi, aku mendengar bahwa sang Ratu sedang tidak berada di Winter Palace saat ini, jadi aku datang untuk memberitahumu.",
  ui_story_1021_10210700_78_dialog_content = "Kami sudah tahu itu.",
  ui_story_1021_10210700_79_dialog_content = "Lalu sebenarnya apa yang sedang kamu lakukan di sini?",
  ui_story_1021_10210700_80_dialog_content = "Mencari sesuatu.",
  ui_story_1021_10210700_81_dialog_content = "Begitu ya? Mungkin aku bisa membantumu?",
  ui_story_1021_10210700_82_dialog_content = "Nah, kita sedang mencari sesuatu... yang bisa menghilangkan kelelahan sang ratu.",
  ui_story_1021_10210700_83_dialog_content = "Hmm... Itu hampir terdengar seperti permainan yang disukai anak-anak, yang berdasarkan legenda...",
  ui_story_1021_10210700_84_dialog_content = "Dan permainan ini umum di kalangan anak-anak?",
  ui_story_1021_10210700_85_dialog_content = "Tentu saja. Anak-anak setempat sering terlihat bermain permainan ini di taman sang ratu.",
  ui_story_1021_10210700_86_dialog_content = "Benarkah anak-anak diperbolehkan untuk masuk begitu saja ke Winter Palace?",
  ui_story_1021_10210700_87_dialog_content = "Queen Bethlehem tidak pernah melihat istana sebagai sesuatu yang sepenuhnya miliknya.",
  ui_story_1021_10210700_88_dialog_content = "Dia sebaik hati sebagaimana dia rajin. Saat dipikirkan, saya rasa saya belum pernah melihat dia beristirahat...",
  ui_story_1021_10210700_89_dialog_content = "Ada kursi dan bangku di seluruh istana, termasuk kursi ayunan yang indah di taman, tetapi saya belum pernah melihat dia duduk di salah satunya.",
  ui_story_1021_10210700_90_dialog_content = "Maka mungkin jawaban yang kita cari... ada di sini! Ayo cek ini, Tiare!",
  ui_story_1021_10210700_91_dialog_content = "...",
  ui_story_1021_10210700_92_dialog_content = "Hah? Tombakmu bersinar!",
  ui_story_1021_10210700_93_dialog_content = "Aha... Aku tahu itu!",
  ui_story_1021_10210700_94_dialog_content = "Takhta sang Ratu...",
  ui_story_1021_10210700_95_dialog_content = "Apakah ini yang Anda cari?",
  ui_story_1021_10210700_96_dialog_content = "Takhta adalah hal yang sempurna untuk menghilangkan kelelahan seorang raja. Ini juga merupakan simbol dari otoritas mereka...",
  ui_story_1021_10210700_97_dialog_content = "Jadi mereka membuat singgasana ratu dari pohon salju pertama... Tapi saya rasa saya belum pernah melihat dia duduk di atasnya...",
  ui_story_1021_10210700_98_dialog_content = "Bisakah jadi dia menolak untuk beristirahat di situ karena dia tahu asal-usulnya?",
  ui_story_1021_10210700_99_dialog_content = "...",
  ui_story_1021_10210700_100_dialog_content = "Sepertinya takhta sedang berubah!",
  ui_story_1021_10210700_101_dialog_content = "Yang Mulia, atas nama suku-suku yang telah bersumpah setia kepada Queen dari Utara, izinkan saya untuk memberikan ini kepada Anda—sebuah takhta yang layak bagi kedaulatan Anda.",
  ui_story_1021_10210700_102_dialog_content = "Mulai hari ini, Anda dapat memandang rakyat Anda dari atas kursi kekuasaan ini.",
  ui_story_1021_10210700_103_dialog_content = "Hamba setiaku, apakah kamu tahu berapa lama waktu yang dibutuhkan untuk menelusuri panjang dan lebar seluruh Northland?",
  ui_story_1021_10210700_104_dialog_content = "S-saya tidak yakin, Yang Mulia... Tapi mengapa Anda bertanya?",
  ui_story_1021_10210700_105_dialog_content = "Tidak ada cara bagi saya untuk melindungi Northland dari atas takhta yang dingin. Untuk menjaga tanah kita yang indah, saya harus menjelajahi setiap sudutnya.",
  ui_story_1021_10210700_106_dialog_content = "Namun saat salju turun, jalur yang kamu tempuh pasti akan menghilang, dan kamu harus membuat jalur baru.",
  ui_story_1021_10210700_107_dialog_content = "Hutan juga akan berubah dengan datangnya setiap musim semi baru.",
  ui_story_1021_10210700_108_dialog_content = "Maka aku akan berkelana tanpa henti, mematroli tanah ini sampai setiap sudutnya berada di bawah cahaya pelindung Beacon.",
  ui_story_1021_10210700_109_dialog_content = "Itu tadi...",
  ui_story_1021_10210700_110_dialog_content = "Apakah kita baru saja menyaksikan momen di mana Yang Mulia Ratu pertama kali menjadi Queen dari Utara?",
  ui_story_1021_10210700_111_dialog_content = "Kami bisa melihatnya tanpa menggunakan kekuatan saya... Itu pasti terjadi lebih awal dari itu...",
  ui_story_1021_10210700_112_dialog_content = "Suku-suku di Northland membuat singgasana untuknya sebagai simbol loyalitas mereka, tetapi dia menolak untuk duduk di atasnya.",
  ui_story_1021_10210700_113_dialog_content = "Dan sejak Queen Bethlehem mewarisi kehendaknya, dia telah berkelana tanpa henti...",
  ui_story_1021_10210700_114_dialog_content = "Lihat!",
  ui_story_1021_10210700_115_dialog_content = "Takhta berubah menjadi cabang kecil...",
  ui_story_1021_10210700_116_dialog_content = "Sepertinya ini adalah pohon snowpine yang telah kita cari.",
  ui_story_1021_10210700_117_dialog_content = "Kekuatan yang luar biasa!",
  ui_story_1021_10210700_118_dialog_content = "Dengan ini, kita akan bisa membantu sang Ratu...",
  ui_story_1021_10210700_119_dialog_content = "Betul sekali, dan sekarang kita akan menuju ke tempat berhenti berikutnya—rumahmu!",
  ui_story_1021_10210700_120_dialog_content = "Ayo pergi!",
  ui_story_1021_10210700_121_dialog_content = "Hei! Lain kali kamu pergi berburu harta karun legendaris, biarkan aku bergabung denganmu!",
  ui_story_1021_10210700_122_dialog_content = "<color=#e8d9bb>Mulai saat itu, Queen dari Utara tidak lagi memiliki takhta.</color>",
  ui_story_1021_10210801_1_dialog_content = "<color=#e8d9bb>Wuuss, wuuss, wuuss—</color>",
  ui_story_1021_10210801_2_dialog_content = "Cuaca tiba-tiba berubah...",
  ui_story_1021_10210801_3_dialog_content = "Beacon sepenuhnya diterjang badai salju. Saya bertanya-tanya bagaimana keadaan Yang Mulia Ratu dan yang lainnya...",
  ui_story_1021_10210801_4_dialog_content = "Jadi, apakah kamu memiliki ide di mana menemukan snowpine berikutnya?",
  ui_story_1021_10210801_5_dialog_content = "Bagian selanjutnya dari legenda itu berbunyi, \"Perjanjian sakralnya mengubah kegelapan menjadi cahaya.\"",
  ui_story_1021_10210801_6_dialog_content = "Aku ingat nenekku pernah menyebutkan sesuatu tentang itu...",
  ui_story_1021_10210801_7_dialog_content = "Northland pernah mengalami zaman kegelapan di masa lalu dan hanya bisa keluar dari situ karena perjanjian kuno dengan yang ilahi.",
  ui_story_1021_10210801_8_dialog_content = "Sebuah perjanjian, huh? Kedengarannya terlalu abstrak bagi saya...",
  ui_story_1021_10210801_9_dialog_content = "Tetapi perjanjian akan selalu ada selama ada orang yang mengingat dan memegang teguhnya.",
  ui_story_1021_10210801_10_dialog_content = "Setidaknya, itu yang Nenek katakan kepada saya...",
  ui_story_1021_10210801_11_dialog_content = "Sepertinya aku punya ide...",
  ui_story_1021_10210801_12_dialog_content = "Aku cukup yakin nenekmu adalah orang yang persis seperti itu, yang berarti aku mungkin bisa menemukan petunjuk dalam kenanganmu tentang dia...",
  ui_story_1021_10210801_13_dialog_content = "Sungguh?",
  ui_story_1021_10210801_14_dialog_content = "Tapi nenekku sudah lama meninggal... Aku tidak tahu apakah ingatanku sebermanfaat yang kamu pikirkan...",
  ui_story_1021_10210801_15_dialog_content = "Kenapa begitu?",
  ui_story_1021_10210801_16_dialog_content = "... Kamu akan tahu setelah melihat mereka.",
  ui_story_1021_10210801_17_dialog_content = "Jangan khawatir, aku yakin aku akan menemukan sesuatu!",
  ui_story_1021_10210801_18_option_content = "Tautan Telepati—",
  ui_story_1021_10210801_19_dialog_content = "Cukup! Aku menolak untuk mendengar lagi!",
  ui_story_1021_10210801_20_dialog_content = "Apa, aku tidak bisa mengatakan beberapa hal lagi sebelum waktuku tiba?",
  ui_story_1021_10210801_21_dialog_content = "Nenek... Apakah ini berarti kamu tidak akan bermain denganku lagi?",
  ui_story_1021_10210801_22_dialog_content = "Aku takut tidak, Tiare kecilku... Berjanjilah padaku bahwa kamu akan menjadi gadis yang baik dan tumbuh besar dan kuat, mengerti?",
  ui_story_1021_10210801_23_dialog_content = "Andai saja kamu bisa melakukannya lebih cepat, Tiare...",
  ui_story_1021_10210801_24_dialog_content = "Jika ada satu penyesalan dalam hidupku, itu adalah aku tidak akan cukup lama untuk melihatmu tumbuh dewasa...",
  ui_story_1021_10210801_25_dialog_content = "Dalam beberapa tahun singkat, saya akan bergabung dengan orang-orang yang saya cintai yang telah tiada...",
  ui_story_1021_10210801_26_dialog_content = "Jangan lupa tentang nenekmu yang sudah tua, Tiare... atau suku kamu... Selalu ingat...",
  ui_story_1021_10210801_27_dialog_content = "Berhentilah menyakiti semua orang dengan kata-katamu. Tak ada satupun dari kita yang akan hidup cukup lama untuk mengingatnya.",
  ui_story_1021_10210801_28_dialog_content = "Pergi bermain dengan rubah-rubah lain di sana, Tiare.",
  ui_story_1021_10210801_29_dialog_content = "Wow... Ini ekorku, dan...",
  ui_story_1021_10210801_30_dialog_content = "Ini adalah... Tidak, tunggu, biar kutebak!",
  ui_story_1021_10210801_31_dialog_content = "Kamu tidak boleh membawa Tiare ke sini lagi.",
  ui_story_1021_10210801_32_dialog_content = "Tiare adalah anak dari suku ini. Dia tidak akan pernah melupakan kejayaan bangsanya, atau berkat dari leluhurnya yang telah membawa dia ke dunia ini.",
  ui_story_1021_10210801_33_dialog_content = "Dia akan menjadi pemimpin suku ini dan penjaga sejati Northland. Aku akan memastikannya...",
  ui_story_1021_10210801_34_dialog_content = "Dan ketika hari itu tiba, dialah yang akan menyadari perjanjian itu.",
  ui_story_1021_10210801_35_dialog_content = "Di masa lalu, suku-suku di Northland bersatu teguh, tetapi sekarang hanya rubah salju yang tersisa untuk melindungi tanah kami.",
  ui_story_1021_10210801_36_dialog_content = "Kita tak akan pernah melihat perwujudan dari perjanjian itu. Mungkin <color=#FFB400>tablet</color> itu sudah hampir dilupakan oleh yang ilahi.",
  ui_story_1021_10210801_37_dialog_content = "Jangan biarkan aku mendengar kamu mengatakan itu pada Tiare, kau rubah tua yang berdebu.",
  ui_story_1021_10210801_38_dialog_content = "Yang ilahi tidak akan pernah lupa, dan selama Tiare masih hidup, kami pun tidak akan melupakan.",
  ui_story_1021_10210801_39_dialog_content = "... Lalu aku akan menghancurkan tablet itu sebelum Tiare mengetahuinya.",
  ui_story_1021_10210801_40_dialog_content = "Kamu lebih menghargai tablet itu daripada siapa pun. Kamu tidak akan pernah melakukan hal seperti itu.",
  ui_story_1021_10210801_41_dialog_content = "Aku tak punya pilihan lain.",
  ui_story_1021_10210801_42_dialog_content = "Apakah salah menyembunyikan hal-hal ini darinya? Lihatlah dia, bermain dengan bahagia seperti anak kecil biasa. Bukankah itu sudah cukup?",
  ui_story_1021_10210801_43_dialog_content = "Tugasnya adalah melindungi suku, bukan istana es itu!",
  ui_story_1021_10210801_44_dialog_content = "Keluarga kerajaan mencuri kekuatan ilahi tanpa memberikan apa pun sebagai gantinya. Tidak hanya itu, mereka juga mengurung para prajurit pemberani kita dalam sebuah makam beku, bersama dengan penjajah Northland...",
  ui_story_1021_10210801_45_dialog_content = "Sudah lebih dari satu milenium... Tapi apakah ada perubahan pada es?",
  ui_story_1021_10210801_46_dialog_content = "Apakah kamu pikir Tiare akan tetap bahagia jika dia tahu tentang masa lalu tragis kita?",
  ui_story_1021_10210801_47_dialog_content = "Perjanjian, perlindungan... Semua itu sekarang terasa begitu kejam bagiku.",
  ui_story_1021_10210801_48_dialog_content = "Kekejaman yang telah aku lihat dalam dirimu sejak saat kau dilahirkan, dan hingga—",
  ui_story_1021_10210801_49_dialog_content = "Itu sudah cukup. Hati Tiare akan cukup kuat untuk menghadapi kekejaman ini, sama seperti leluhurnya yang hebat sebelumnya.",
  ui_story_1021_10210801_50_dialog_content = "...",
  ui_story_1021_10210801_51_dialog_content = "Nenek—rubah ini menyebutmu penyihir tua yang jahat! Hahaha! Berhenti, itu menggelitik!",
  ui_story_1021_10210801_52_dialog_content = "Aku... Aku tak akan kalah darimu!",
  ui_story_1021_10210801_53_dialog_content = "...",
  ui_story_1021_10210801_54_dialog_content = "Ada apa?",
  ui_story_1021_10210801_55_dialog_content = "... Kamu melihat mereka bertengkar, bukan?",
  ui_story_1021_10210801_56_dialog_content = "Ya. Mereka terbagi pendapat tentang apakah harus membiarkan kamu menjadi pemimpin suku kamu atau tidak.",
  ui_story_1021_10210801_57_dialog_content = "Saya tidak tahu bahwa si tua tidak ingin kamu memimpin rubah salju...",
  ui_story_1021_10210801_58_dialog_content = "Aku tahu... Tetua itu tidak pernah menyambut orang luar—dia bahkan tidak ingin aku kembali ke suku...",
  ui_story_1021_10210801_59_dialog_content = "Mungkin karena dia tahu bahwa ini akan berakhir seperti ini di bawah kepemimpinanku.",
  ui_story_1021_10210801_60_dialog_content = "Itu sama sekali bukan masalahnya. Yang lebih tua khawatir bahwa kamu tidak akan pernah bahagia lagi dan bahwa kamu akan menghabiskan hidupmu dalam kebencian seperti nenekmu.",
  ui_story_1021_10210801_61_dialog_content = "Bahagia?",
  ui_story_1021_10210801_62_dialog_content = "Jadi itulah mengapa dia ingin saya memutus hubungan dengan suku dan bertugas sebagai pengawal ratu...",
  ui_story_1021_10210801_63_dialog_content = "Dia menyimpan rahasia ini sendiri selama ini...",
  ui_story_1021_10210801_64_dialog_content = "Tidak pernah membiarkan saya mendekati altar...",
  ui_story_1021_10210801_65_dialog_content = "Atau menceritakan tentang legenda itu kepada saya...",
  ui_story_1021_10210801_66_dialog_content = "Bahkan ketika suku dalam bahaya, dia mendorongku untuk menjauh...",
  ui_story_1021_10210801_67_dialog_content = "Tetua itu memiliki cinta yang dalam untuk sukunya, tetapi dia mencintaimu lebih lagi, Tiare...",
  ui_story_1021_10210801_68_dialog_content = "...",
  ui_story_1021_10210801_69_dialog_content = "Itulah sebabnya saya tidak bisa mengingkari janji saya sebagai pemimpin rubah salju!",
  ui_story_1021_10210801_70_dialog_content = "Saya percaya pada Yang Mulia Ratu! Jika dia mengatakan bahwa memanggil Primal Haven akan menyelamatkan sukuku, maka itu pasti benar!",
  ui_story_1021_10210801_71_dialog_content = "Sampai saat itu, tetua tidak akan pernah memaksaku untuk pergi!",
  ui_story_1021_10210801_72_dialog_content = "Aku tahu kamu bisa melakukannya, Tiare!",
  ui_story_1021_10210801_73_dialog_content = "Tapi meski setelah mencari dalam ingatanku, kita masih belum menemukan petunjuk tentang keberadaan snowpine, bukan?",
  ui_story_1021_10210801_74_dialog_content = "Tidak, mereka berbicara tentang sebuah tablet... Rupanya, itu mencatat perjanjian antara yang ilahi dan Suku Fox Salju?",
  ui_story_1021_10210801_75_dialog_content = "Sebuah tablet...",
  ui_story_1021_10210801_76_dialog_content = "Nenekmu mengatakan bahwa orang tua itu lebih menghargainya daripada siapa pun.",
  ui_story_1021_10210801_77_dialog_content = "Tapi mungkin dia sudah menghancurkannya...",
  ui_story_1021_10210801_78_dialog_content = "...",
  ui_story_1021_10210801_79_dialog_content = "Pikirkan tentang itu. Jika penatua benar-benar menghargainya, maka dia pasti sering pergi ke suatu tempat untuk melihatnya.",
  ui_story_1021_10210801_80_dialog_content = "Tempat-tempat yang biasanya dikunjungi oleh tetua... Gua, altar, gunung, dan...",
  ui_story_1021_10210801_81_dialog_content = "Apa mungkin...",
  ui_story_1021_10210801_82_dialog_content = "Sebelum aku meninggalkan suku, ada tempat dimana para tetua biasa pergi untuk memandangi Beacon sepanjang hari. Tempat itu tidak jauh dari sini.",
  ui_story_1021_10210801_83_dialog_content = "Aku tidak melihat apa-apa selain pohon di sekitar sini...",
  ui_story_1021_10210801_84_dialog_content = "... Siapa di sana? Tunjukkan diri kalian!",
  ui_story_1021_10210801_85_dialog_content = "Uh-oh... Sepertinya kamu menemukan kami lagi...",
  ui_story_1021_10210801_86_dialog_content = "Lagi-lagi kalian berdua!",
  ui_story_1021_10210801_87_dialog_content = "Ayo sekarang, apakah ini cara yang tepat untuk membalas budi kami? Bagaimanapun, kami telah melalui semua kesulitan untuk membersihkan Eclipsites dari tempat ini.",
  ui_story_1021_10210801_88_dialog_content = "Saya sulit percaya seorang pencuri batu permata sepertimu bisa sebaik hati itu! Sekarang apa yang kamu curi kali ini?",
  ui_story_1021_10210801_89_dialog_content = "Tidak ada apa-apa, saya jamin. Kita beruntung bisa lolos dari gua itu hanya dengan nyawa kita!",
  ui_story_1021_10210801_90_dialog_content = "Uh... Aku rasa kamu sebaiknya jujur saja pada mereka, Roy.",
  ui_story_1021_10210801_91_dialog_content = "Kamu mengatakan bahwa, sebagai anggota tim eksplorasi bersama, Rediesel Wrench tidak akan pernah mengabaikan nyawa atau keselamatan sekutu kita.",
  ui_story_1021_10210801_92_dialog_content = "Karena kami tidak bisa menemukan kalian setelah kami meninggalkan gua, Roy dan saya memutuskan untuk membasmi Eclipsite yang muncul di area ini!",
  ui_story_1021_10210801_93_dialog_content = "Benar, kami tidak melihat satu pun Eclipsite di perjalanan kami ke sini... Kami benar-benar berterima kasih kepada kalian!",
  ui_story_1021_10210801_94_dialog_content = "Apa yang kamu bicarakan? Sejauh apapun tempat ini, masih dilindungi oleh cahaya Beacon!",
  ui_story_1021_10210801_95_dialog_content = "... B-Bagaimana kita bisa tahu itu? Tidak ada tanda apapun di sekitar sini! Apakah kamu mengatakan kita tidak perlu bertarung dengan Eclipsites barusan?",
  ui_story_1021_10210801_96_dialog_content = "Sebenarnya, aku cukup yakin aku melihat penanda sebelumnya, Roy...",
  ui_story_1021_10210801_97_dialog_content = "Tiare! Mungkinkah penanda itu—",
  ui_story_1021_10210801_98_dialog_content = "Tablet itu!",
  ui_story_1021_10210801_99_dialog_content = "Tunjukkan tombakmu dan lihat apa yang terjadi!",
  ui_story_1021_10210801_100_dialog_content = "Semua ditenagai oleh alam!",
  ui_story_1021_10210801_101_dialog_content = "Kami tidak akan membuang-buang energi kami jika sejak awal sudah bersinar seperti ini...",
  ui_story_1021_10210801_102_dialog_content = "Inskripsi yang bersinar ini... Pasti ditulis dengan menggunakan minyak pinus salju.",
  ui_story_1021_10210801_103_dialog_content = "Nenek saya pernah berkata bahwa lampu minyak pinus kami adalah mata dari seluruh Northland.",
  ui_story_1021_10210801_104_dialog_content = "Saya yakin itu bersinar sangat terang di malam hari...",
  ui_story_1021_10210801_105_dialog_content = "Saya tidak pernah menyangka bahwa salah satu pohon snowpine digunakan sebagai penanda batas Beacon.",
  ui_story_1021_10210801_106_dialog_content = "Wow! Apa yang terjadi?",
  ui_story_1021_10210801_107_dialog_content = "Pengawal berani dari Northland! Perang telah berakhir, dan pembangunan Beacon kini telah selesai.",
  ui_story_1021_10210801_108_dialog_content = "Benteng beku ini akan berdiri sebagai peringatan atas nyawa yang hilang dalam pertahanan perbatasan Northland. Ini akan menjadi pengingat bagi rakyat kita dan peringatan bagi musuh-musuh kita.",
  ui_story_1021_10210801_109_dialog_content = "Kepada semua yang berkumpul di sini hari ini, saya berjanji kepada Anda:",
  ui_story_1021_10210801_110_dialog_content = "Cahaya dari Beacon akan melindungi tempat ini. Tidak lagi akan menjadi persimpangan antara kegelapan dan cahaya!",
  ui_story_1021_10210801_111_dialog_content = "Keluarga Anda akan berbagi dalam kedamaian dan kemakmuran Northland.",
  ui_story_1021_10210801_112_dialog_content = "May seluruh alam menjadi saksi saya, dan May Beacon Northland melindungi kerajaan kita yang adil.",
  ui_story_1021_10210801_113_dialog_content = "Saya juga meminta Anda, bersama dengan yang ilahi, menjadi saksi perjanjian ini, yang saya tujukan kepada suku Anda.",
  ui_story_1021_10210801_114_dialog_content = "Sebagai Queen pertama dari Utara, saya bersumpah bahwa keturunan saya akan mempertahankan tanah kita hingga akhir!",
  ui_story_1021_10210801_115_dialog_content = "Sebagai pemimpin suku di Northland, dengan ini kami bersumpah bahwa keturunan kami akan membela tanah kami hingga akhir hayat!",
  ui_story_1021_10210801_116_dialog_content = "Ratu pertama Northland benar-benar luar biasa...",
  ui_story_1021_10210801_117_dialog_content = "Jadi perjanjian itu bukan antara suku Anda dan yang ilahi...",
  ui_story_1021_10210801_118_dialog_content = "Ini adalah janji antara ratu pertama dan semua pengawal perbatasan...",
  ui_story_1021_10210801_119_dialog_content = "Inilah sebabnya nenek moyang saya selalu mengawasi tempat ini. Tapi sang ratu gagal memenuhi janjinya, dan suku kami pun mulai merosot...",
  ui_story_1021_10210801_120_dialog_content = "Itulah asal mula kebencian kita terhadap keluarga kerajaan...",
  ui_story_1021_10210801_121_dialog_content = "Membuat cahaya dari Beacon mencapai tempat ini tampaknya mustahil...",
  ui_story_1021_10210801_122_dialog_content = "Aku tahu... Tapi selama bertahun-tahun, sang ratu telah terus-menerus berpatroli di perbatasan tanah ini.",
  ui_story_1021_10210801_123_dialog_content = "Saya jujur percaya bahwa tidak ada satu pihak pun yang gagal menepati janjinya.",
  ui_story_1021_10210801_124_dialog_content = "Dan sekarang mereka telah mempercayai saya untuk memanggil Primal Haven dan melindungi Northland...",
  ui_story_1021_10210801_125_dialog_content = "Ini pasti apa yang Pak Novio ingin saya pahami!",
  ui_story_1021_10210801_126_dialog_content = "Mencari pohon salju telah memberi saya pemahaman baru tentang Northland.",
  ui_story_1021_10210801_127_dialog_content = "Sepertinya kembali ke bentuk aslinya, sama seperti takhta ratu...",
  ui_story_1021_10210801_128_dialog_content = "Dan dengan itu, kita telah menemukan snowpine kedua!",
  ui_story_1021_10210801_129_dialog_content = "Untuk yang ketiga, saya bertanya-tanya apakah Queen Bethlehem benar-benar berniat untuk memadamkan Beacon of Northland untuk itu...",
  ui_story_1021_10210801_130_dialog_content = "Saya tidak ragu lagi di pikiran saya! Apapun yang dituju oleh ratu, saya akan ada di sana untuk membantu dia mencapainya!",
  ui_story_1021_10210801_131_dialog_content = "Mari kita kembalikan kedua pohon pinus salju ini kepada mereka!",
  ui_story_1021_10210801_132_dialog_content = "Ya!",
  ui_story_1021_10210801_133_dialog_content = "Oh, dan... Terima kasih, kalian berdua!",
  ui_story_1021_10210801_134_dialog_content = "Haha, bukan masalah.",
  ui_story_1021_10210801_135_dialog_content = "Kita harus membantu mereka sekarang setelah kita menemukan mereka, Roy.",
  ui_story_1021_10210801_136_dialog_content = "Oh, kurasa begitu. Ayo, mari kita pergi.",
  ui_story_1021_10210801_137_dialog_content = "<color=#e8d9bb>Mulai saat itu, tablet yang membawa janji antara ratu dan suku-suku Northland hilang.</color>",
  ui_story_1021_10210801_138_dialog_content = "Tua! Tuan Novio! Kami kembali dengan—",
  ui_story_1021_10210801_139_dialog_content = "Apa yang terjadi di atas altar?",
  ui_story_1021_10210801_140_dialog_content = "Queen Bethlehem sedang mengekstrak kekuatan Spark dari dalam tubuhnya dan mengkondensasikannya menjadi Wick.",
  ui_story_1021_10210801_141_dialog_content = "Wick? Apakah ini berarti bahwa Beacon di dekat tebing telah padam?",
  ui_story_1021_10210801_142_dialog_content = "Tidak. Sebenarnya, Yang Mulia Ratu telah bertindak sebagai Mercusuar Northland untuk waktu yang lama sekarang. Apa yang Anda lihat di depan Anda adalah kekuatan hidupnya sendiri.",
  ui_story_1021_10210801_143_dialog_content = "Kekuatan hidupnya sendiri... Tapi bukankah ini sangat melemahkannya?",
  ui_story_1021_10210801_144_dialog_content = "Ya, tapi ini juga memungkinkan dia untuk memaksa para Eclipsite keluar dari perbatasan Northland.",
  ui_story_1021_10210801_145_dialog_content = "Yang Mulia...",
  ui_story_1021_10210801_146_dialog_content = "Meski sudah berlalu bertahun-tahun sejak saat itu, Beacon yang dijanjikan untuk tempat ini akhirnya akan dibangun—tentu saja, dengan bantuanmu.",
  ui_story_1021_10210801_147_dialog_content = "Jadi, sekarang aku harus apa?",
  ui_story_1021_10210801_148_dialog_content = "Kamu harus meletakkan snowpines di atas altar dan mengembalikan kekuatan di tombakmu kepada yang ilahi bersama dengan mereka.",
  ui_story_1021_10210801_149_dialog_content = "Ayo, mari kita berdoa kepada yang ilahi...",
  ui_story_1021_10210801_150_dialog_content = "Saya, Hagen, tetua dari Suku Salju Fox dan penjaga Lord Rode, dewa perang Northland, memohon campur tangan ilahi!",
  ui_story_1021_10210801_151_dialog_content = "Aku, Tiare, pemimpin Suku Salju Fox dan penjaga Bethlehem, Queen dari Utara, memohon campur tangan ilahi!",
  ui_story_1021_10210801_152_dialog_content = "Queen dari Utara telah memenuhi perjanjiannya! Kekuatannya adalah milikmu, begitu juga kekuatan dalam ranting-ranting ini!",
  ui_story_1021_10210801_153_dialog_content = "Mohon terimalah dan rawat Tiga Pohon Salju dengan kekuatan pemberi kehidupanmu, agar mereka dapat tumbuh sekali lagi!",
  ui_story_1021_10210801_154_dialog_content = "Berkatilah tanah kita yang kuno dan sakral dengan perlindungan abadimu—",
  ui_story_1021_10210801_155_dialog_content = "Beri aku kekuatan, Terra Staff!",
  ui_story_1021_10210801_156_dialog_content = "<color=#e8d9bb>Wuush, wuush—</color>",
  ui_story_1021_10210801_157_dialog_content = "!",
  ui_story_1021_10210801_158_dialog_content = "Tiga tunggul itu... Tiba-tiba mereka tumbuh menjadi satu pohon raksasa yang sangat besar!",
  ui_story_1021_10210801_159_dialog_content = "Apakah ini kekuatan dari Primal Haven?",
  ui_story_1021_10210801_160_dialog_content = "...",
  ui_story_1021_10210801_161_dialog_content = "Kekuatan dalam tombakku tidak diambil kembali... Jika ada, rasanya seperti kekuatan yang lebih besar mengalir ke dalamnya!",
  ui_story_1021_10210801_162_dialog_content = "Benda ini berkedip seperti petir... Apakah ini energi yang berasal dari dalam pohon salju?",
  ui_story_1021_10210801_163_dialog_content = "...",
  ui_story_1021_10210801_164_dialog_content = "Di puncak dunia ini, nenek moyang kita menemukan aliran air yang hangat dan lembut.",
  ui_story_1021_10210801_165_dialog_content = "Aliran ini, seperti berkah dari surga, mengalir melalui lanskap beku Northland sepanjang tahun dan meluas hingga ke ujung terjauh Astra...",
  ui_story_1021_10210801_166_dialog_content = "Ini adalah asal-usul Primal Haven. Aliran air membawa kehidupan ke Hutan Snowpine, yang pada gilirannya memberikan kehidupan kepada nenek moyang kita yang paling awal.",
  ui_story_1021_10210801_167_dialog_content = "Di bawah perlindungan Primal Haven, snowpines dan Wick telah bersatu untuk menciptakan Beacon baru ini.",
  ui_story_1021_10210801_168_dialog_content = "Cahayanya akan menembus musim dingin yang panjang dan pegunungan yang tertutup salju, mengusir kegelapan dan menerangi tanah air kita yang tercinta.",
  ui_story_1021_10210801_169_dialog_content = "Selain itu, Tiare, kamu telah dipilih oleh yang ilahi untuk menjadi penjaga sejati Northland.",
  ui_story_1021_10210801_170_dialog_content = "Yang ilahi telah memilihku... dan memberkatiku dengan kekuatan!",
  ui_story_1021_10210801_171_dialog_content = "Kekuatan dalam tombak beku ini mengamuk seperti api. Rasanya seperti obor di tangan saya!",
  ui_story_1021_10210801_172_dialog_content = "Tiare, mulai hari ini, kamu harus menanggung beban kekuatan dan kewajiban ilahi...",
  ui_story_1021_10210801_173_dialog_content = "Gunakan keberanian dan kebijaksanaanmu dalam membela seluruh Northland.",
  ui_story_1021_10210802_1_dialog_content = "Seberkas cahaya datang dari Hutan Snowpine? Bisa jadi ini adalah reruntuhan kuno yang belum ditemukan?",
  ui_story_1021_10210802_2_dialog_content = "Atau mungkin ini semacam sinyal?",
  ui_story_1021_10210802_3_dialog_content = "Beacon legenda memberikan petunjuk dan perlindungan bagi seluruh Northland. Apakah mungkin ada lebih dari satu beacon?",
  ui_story_1021_10210802_4_dialog_content = "Jika begitu, bagaimana mereka didistribusikan?",
  ui_story_1021_10210802_5_dialog_content = "Dan apa pengaruh cahaya mereka terhadap tanah?",
  ui_story_1021_10210802_6_dialog_content = "<color=#e8d9bb>Di Sudut Tersembunyi dari Tanah</color>",
  ui_story_1021_10210802_7_dialog_content = "Jadi, Northland ternyata memang memiliki kekuatan seperti ini.",
  ui_story_1021_10210802_8_dialog_content = "Aliran sungai telah kembali mengalir dan akan segera mencapai laut.",
  ui_story_1021_10210802_9_dialog_content = "Saya pikir Lady Victoria akan sangat senang dengan temuan kita.",
  ui_story_1021_10210802_10_dialog_content = "Maka mari kita berangkat sekarang juga.",
  ui_story_1021_10210802_11_dialog_content = "<color=#e8d9bb>Di dalam Pesawat Federasi Illumina</color>",
  ui_story_1021_10210802_12_dialog_content = "Belum pernah kulihat cahaya seperti ini sebelumnya... seperti matahari pagi yang terbit di belakang gunung bersalju.",
  ui_story_1021_10210802_13_dialog_content = "Tetapkan kursus menuju cahaya itu! Maju dengan kecepatan penuh!",
  ui_story_1021_10210802_14_dialog_content = "Baik, Grand Marshal!",
  ui_story_1021_10210901_1_dialog_content = "Tampaknya... Beacon baru kini telah selesai.",
  ui_story_1021_10210901_2_dialog_content = "Yang Mulia Ratu! Apakah Anda terluka? Saya hampir tidak bisa menahan melihat Anda dalam keadaan lemah seperti ini...",
  ui_story_1021_10210901_3_dialog_content = "Aku baik-baik saja, Carleen. Seluruh Northland sekarang berada di bawah perlindungan yang lebih besar, begitu juga aku.",
  ui_story_1021_10210901_4_dialog_content = "Graah!",
  ui_story_1021_10210901_5_dialog_content = "(Eclipsian) Tuanku... Ini membakar...",
  ui_story_1021_10210901_6_dialog_content = "(Dalam bahasa Eclipsian) Itu membakar!",
  ui_story_1021_10210901_7_dialog_content = "(Eclipsian) Sensasi ini... aku ingat sekarang...",
  ui_story_1021_10210901_8_dialog_content = "(Eclipsian) Seorang gadis yang menunggangi rusa betina melintasi salju...",
  ui_story_1021_10210901_9_dialog_content = "(Eclipsian) Aku ingat semuanya sekarang.",
  ui_story_1021_10210901_10_dialog_content = "(Eclipsian) Sepertinya ujian-ujianku telah terbukti berharga.",
  ui_story_1021_10210901_11_dialog_content = "Semua bertenaga penuh!",
  ui_story_1021_10210901_12_dialog_content = "...",
  ui_story_1021_10210901_13_dialog_content = "Graah!",
  ui_story_1021_10210901_14_dialog_content = "Yang Mulia! Carleen! Maaf telah terlambat!",
  ui_story_1021_10210901_15_dialog_content = "Serangan barusan itu luar biasa, Tiare!",
  ui_story_1021_10210901_16_dialog_content = "Baik tombak dan kekuatanmu tampaknya telah menjadi jauh lebih kuat!",
  ui_story_1021_10210901_17_dialog_content = "Tetua itu mengatakan ini adalah bukti bahwa yang ilahi telah mengakui saya. Saya sekarang adalah pengawal ratu yang layak!",
  ui_story_1021_10210901_18_dialog_content = "Dan penjaga seluruh Northland!",
  ui_story_1021_10210901_19_dialog_content = "Benar sekali!",
  ui_story_1021_10210901_20_dialog_content = "Saya bisa merasakan betapa besar pertumbuhanmu, Tiare. Bagus sekali.",
  ui_story_1021_10210901_21_dialog_content = "Terima kasih telah membantu saya membuat Beacon baru ini.",
  ui_story_1021_10210901_22_dialog_content = "Yang Mulia! Saya baru saja mengetahui tentang cerita tahta di Winter Palace, mempelajari sumpah antara keluarga kerajaan dan suku... dan juga...",
  ui_story_1021_10210901_23_dialog_content = "Aku punya banyak hal untuk diberitahukan kepadamu! Tapi satu hal yang paling ingin kukatakan adalah ini—",
  ui_story_1021_10210901_24_dialog_content = "Mulai sekarang, saya, Tiare, akan selalu berada di sampingmu! Kamu tidak akan pernah harus menghadapi pertempuran sendirian lagi, Yang Mulia!",
  ui_story_1021_10210901_25_dialog_content = "\"Salju yang mencair membawa air melewati pegunungan dan aliran sungai, membawa kehidupan ke tanah yang diberkahi ini...\"",
  ui_story_1021_10210901_26_dialog_content = "Bersiaplah untuk mati, Eclipsite!",
  ui_story_1021_10210901_27_dialog_content = "Tunggu, Tiare!",
  ui_story_1021_10210901_28_dialog_content = "Yang Mulia?",
  ui_story_1021_10210901_29_dialog_content = "Tidak hanya mengetahui tentang pertempuran itu, kamu juga tahu tentang berkat Northland? Bagaimana bisa?",
  ui_story_1021_10210901_30_dialog_content = "Saat itu, keheningan mencekam melanda negeri salju ini.",
  ui_story_1021_10210901_31_dialog_content = "Sebuah matahari hitam pekat mengambang di langit di atas, dan kedatangan tuhan kami sudah dekat...",
  ui_story_1021_10210901_32_dialog_content = "Tapi kemudian gadis itu muncul...",
  ui_story_1021_10210901_33_dialog_content = "...",
  ui_story_1021_10210901_34_dialog_content = "Kamu melihat Queen pertama dari Northland?",
  ui_story_1021_10210901_35_dialog_content = "Dengan sinar cahaya di tangannya, dia menghancurkan kubah dan memisahkan kami dari tuhan kami selamanya.",
  ui_story_1021_10210901_36_dialog_content = "Aku sangat ingin melihat matahari hitam untuk terakhir kalinya.",
  ui_story_1021_10210901_37_dialog_content = "Tapi dengan senjata di tangannya, dia membuatku buta.",
  ui_story_1021_10210901_38_dialog_content = "Saya telah mengingat segalanya setelah persidangan ini...",
  ui_story_1021_10210901_39_dialog_content = "Api terakhir yang terlihat oleh mataku bukanlah kemarahanku...",
  ui_story_1021_10210901_40_dialog_content = "Sejak awal memang bukan amarah!",
  ui_story_1021_10210901_41_dialog_content = "Ini adalah sorotan cahaya yang menari yang mewarnai dunia saya dengan kemarahan!",
  ui_story_1021_10210901_42_dialog_content = "(Eclipsian) Aku tak takut pada embun beku maupun nyala api...",
  ui_story_1021_10210901_43_dialog_content = "(Eclipsian) Tapi cahaya putih yang berkelip-kelip itu... Saya hanya ingin tahu apa itu...",
  ui_story_1021_10210901_44_dialog_content = "Beacon! Itu adalah Beacon milik sang Ratu!",
  ui_story_1021_10210901_45_dialog_content = "Ratu telah membawa cahaya Beacon untuk menyelamatkan kami!",
  ui_story_1021_10210901_46_dialog_content = "(Eclipsian) Beacon...",
  ui_story_1021_10210901_47_dialog_content = "Graah!",
  ui_story_1021_10210901_48_dialog_content = "Saya ingat semuanya sekarang.",
  ui_story_1021_10210901_49_dialog_content = "Semuanya...",
  ui_story_1021_10210901_50_dialog_content = "Sidang saya sekarang berakhir. Kamu boleh pergi dengan nyawa yang masih utuh.",
  ui_story_1021_10210901_51_dialog_content = "...",
  ui_story_1021_10210901_52_dialog_content = "Jangan berpikir aku akan membiarkanmu lolos!",
  ui_story_1021_10210901_53_dialog_content = "Aku akan membuatmu membayar atas apa yang telah kamu lakukan pada rubah-rubah dan seluruh suku kami!",
  ui_story_1021_10210901_54_dialog_content = "Kalau kau menolak untuk pergi... maka datanglah dan temui ajalmu.",
  ui_story_1021_10210901_55_dialog_content = "Tiare!",
  ui_story_1021_10210901_56_dialog_content = "Semua bertenaga penuh!",
  ui_story_1021_10210901_57_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1021_10210901_58_dialog_content = "*batuk* E-Eclipsite sialan... Aku tak akan membiarkanmu kabur...",
  ui_story_1021_10210901_59_dialog_content = "Tiare!",
  ui_story_1021_10210901_60_dialog_content = "Awas! Dia mencoba menarikmu ke Dark Zone!",
  ui_story_1021_10210901_61_dialog_content = "Barusan... Apakah itu tembakan meriam?",
  ui_story_1021_10210901_62_dialog_content = "Lihat ke langit, PlayerName—",
  ui_story_1021_10210901_63_dialog_content = "Kami melewatkan target kami, tetapi sepertinya PlayerName dan yang lainnya sedang mencoba untuk memasuki wilayah Eclipsite.",
  ui_story_1021_10210901_64_dialog_content = "Turunkan ketinggian dan tutupi mereka!",
  ui_story_1021_10210901_65_dialog_content = "Baik, Grand Marshal!",
  ui_story_1021_10210901_66_dialog_content = "Mereka membuka tembakan, Bethel! Apakah ini berarti kita—",
  ui_story_1021_10210901_67_dialog_content = "Illumina dan Lumopolis sedang menyediakan bala bantuan. Jangan menghalangi mereka.",
  ui_story_1021_10210901_68_dialog_content = "Kita perlu naik ke geladak dan mengibarkan spanduk ekspedisi gabungan!",
  ui_story_1021_10210901_69_dialog_content = "Semua pasukan siap dikerahkan. Kita bisa mendarat kapan saja, Pak!",
  ui_story_1021_10210901_70_dialog_content = "Binasakan Eclipsite apa pun yang kamu temui di perbatasan dan perkuat posisi prajurit Northland. Serahkan pertempuran utama kepada teman-teman muda kita.",
  ui_story_1021_10210901_71_dialog_content = "Baik tuan ku!",
  ui_story_1021_10210901_72_dialog_content = "Ini adalah pesawat buatan Illumina...",
  ui_story_1021_10210901_73_dialog_content = "Selain kapal udara Lumopolis... Semuanya sedang fokus pada posisi kita saat ini.",
  ui_story_1021_10210901_74_dialog_content = "Tapi sepertinya Eclipsite itu mencoba memancing Tiare dan menarik kita untuk mendekatinya...",
  ui_story_1021_10210901_75_dialog_content = "Tiare cepat! Dia hampir saja melewati tembok di depan kita!",
  ui_story_1021_10210901_76_dialog_content = "Setelah kita melewati tembok itu, saya khawatir tidak akan ada jalan untuk kembali.",
  ui_story_1021_10210901_77_dialog_content = "Meski begitu, cahaya dari Beacon seharusnya bisa mencapai lebih jauh. Ayo ikut denganku.",
  ui_story_1021_10210901_78_dialog_content = "Aku akan membantu kamu mencapai puncak gunung dengan membuat jalur es. Kita harus membantu Tiare mengusir Eclipsite dari Northland sekali untuk selamanya!",
  ui_story_1021_10210901_79_dialog_content = "Ya!",
  ui_story_1021_10210901_80_dialog_content = "Tiare!",
  ui_story_1021_10210901_81_dialog_content = "Jangan tinggalkan kami seperti itu! Kita semua bersama-sama dalam ini!",
  ui_story_1021_10210901_82_dialog_content = "Yang Mulia! Teman-temanku! Dan kalian berdua juga?",
  ui_story_1021_10210901_83_dialog_content = "Jangan lupa, Rediesel juga bagian dari ekspedisi gabungan!",
  ui_story_1021_10210901_84_dialog_content = "Itu benar. Bagaimanapun, kalianlah yang mengatakan bahwa kita harus memiliki upacara penyambutan yang seru sebelum memulai ekspedisi.",
  ui_story_1021_10210901_85_dialog_content = "Aku tidak ingat mengatakan apa-apa tentang itu...",
  ui_story_1021_10210901_86_dialog_content = "Tapi sebagai penjaga Northland, aku berjanji bahwa aku tidak akan beristirahat sampai para Eclipsite ini telah diusir dari tanah kita!",
  ui_story_1021_10210901_87_dialog_content = "Tanpa menyadarinya, ekspedisi gabungan ini sudah sampai sejauh ini dalam perjalanannya.",
  ui_story_1021_10210901_88_dialog_content = "Tepat di depan adalah wilayah Eclipsite, tetapi monster haus darah seperti mereka tidak punya tempat di dunia ini!",
  ui_story_1021_10210901_89_dialog_content = "Mari kita ikuti cahaya Beacon dan membasmi mereka tanpa ampun!",
  ui_story_1021_10210901_90_dialog_content = "Itu adalah beberapa kata yang kuat yang keluar dari sang ratu...",
  ui_story_1021_10210901_91_dialog_content = "Dengan Tiare sebagai penjaga saya, saya tidak bisa tidak merasa terinspirasi olehnya.",
  ui_story_1021_10210901_92_dialog_content = "Kumpulkan keberanianmu dan tetaplah saling mendekat di hati, karena masa depan Northland dan semua Aurorian bergantung pada kita...",
  ui_story_1021_10210901_93_dialog_content = "Jadilah suar bagi satu sama lain, dan kekuatanmu akan mengatasi rasa takut apa pun yang mungkin kita hadapi.",
  ui_story_1021_10210901_94_dialog_content = "!",
  ui_story_1021_10210901_95_dialog_content = "Hei, lihat batu yang hancur itu! Sepertinya Eclipsite tidak akan berlari jauh dari situ!",
  ui_story_1021_10210901_96_dialog_content = "Maka kita akan menghancurkannya bersama! Bersamaku, semua orang, kita bergerak menuju Dark Zone!",
  ui_story_1021_10210901_97_dialog_content = "Serang!",
  ui_story_1021_10210902_1_dialog_content = "Menarik. Ini jauh melampaui harapanku...",
  ui_story_1021_10210902_2_dialog_content = "Tapi untuk mencapai tingkat yang lebih tinggi, aku harus berlatih menahan diri.",
  ui_story_1021_10210902_3_dialog_content = "Sebelum aku pergi, aku punya satu pesan terakhir untuk kalian semua...",
  ui_story_1021_10210902_4_dialog_content = "Biarkan aroma kegelapan menyerang indra Anda dan masuk ke wilayah kami...",
  ui_story_1021_10210902_5_dialog_content = "Mayat-mayat orang-orang yang datang sebelum kalian bertumpuk setinggi gunung, dan suara mereka akan memanggil nama kalian di mana pun kalian pergi.",
  ui_story_1021_10210902_6_dialog_content = "Aku, Ira Pelindung Raja, akan menunggumu di negeri malam yang abadi.",
  ui_story_1021_10210902_7_dialog_content = "Saya menantikan pertemuan kita selanjutnya...",
  ui_story_1021_10211001_1_dialog_content = "Para Eclipsite telah mundur keluar dari Northland, dan sumber cahaya Beacon telah stabil kembali.",
  ui_story_1021_10211001_2_dialog_content = "Apakah sekutu kita telah memanggil kembali prajurit mereka?",
  ui_story_1021_10211001_3_dialog_content = "Ya, tetapi Kepala Staf Federasi Illumina sedang menunggu Caelestite dan rombongannya di Lembah Pine Frost.",
  ui_story_1021_10211001_4_dialog_content = "Meskipun pos terdepan masih belum lengkap, tampaknya ekspedisi kami ke Zona Gelap telah resmi dimulai, dan dengan cara yang menakjubkan.",
  ui_story_1021_10211001_5_dialog_content = "Setidaknya, Beacon baru ini akan memberikan mereka tempat perlindungan sementara sebelum menyelam jauh ke dalam Dark Zone.",
  ui_story_1021_10211001_6_dialog_content = "Apakah ini berarti mereka akan berangkat dari sini?",
  ui_story_1021_10211001_7_dialog_content = "Ya, itulah sebabnya kita harus menggandakan upaya kita untuk menyelesaikan pembangunan pos luar.",
  ui_story_1021_10211001_8_dialog_content = "Yang Mulia, persiapan untuk keberangkatan kami sekarang sudah selesai. Kami datang untuk mengucapkan selamat tinggal.",
  ui_story_1021_10211001_9_dialog_content = "Carleen tidak sabar untuk kembali dan melanjutkan pelajarannya terbang. Benar 'kan?",
  ui_story_1021_10211001_10_dialog_content = "Itu-Itu bukan masalahnya... Ada banyak urusan mendesak lainnya yang harus dihadiri...",
  ui_story_1021_10211001_11_dialog_content = "Lalu, saya ucapkan selamat jalan. Terima kasih sekali lagi karena telah membantu saya menciptakan Beacon baru ini untuk Northland.",
  ui_story_1021_10211001_12_dialog_content = "Kami juga tidak bisa melakukannya tanpa Tiare! Ngomong-ngomong, di mana dia?",
  ui_story_1021_10211001_13_dialog_content = "Dia juga memiliki hal-hal lain untuk diperhatikan.",
  ui_story_1021_10211001_14_dialog_content = "Harap yakinkan anggota Expedition Team bahwa pos luar akan selesai sesegera mungkin.",
  ui_story_1021_10211001_15_dialog_content = "Penguasa Kota mengatakan bahwa dia akan mengirimkan White Night Guardians untuk membantu dalam pembangunannya, meskipun kedatangan mereka mungkin tertunda dua hari.",
  ui_story_1021_10211001_16_dialog_content = "Dan aku tahu ada dua insinyur ahli yang bisa mulai bekerja hari ini!",
  ui_story_1021_10211001_17_dialog_content = "Kamu benar! Mereka berdua sudah lama memikirkan permata. Tolong pertimbangkan apa pun yang mereka ambil sebagai uang muka pembayaran mereka.",
  ui_story_1021_10211001_18_dialog_content = "Kalian berdua tampak sangat bersemangat untuk membuat kami bekerja...",
  ui_story_1021_10211001_19_dialog_content = "Kami tidak tahu apa yang terjadi pada permata-permata itu... Dan jika kita bekerja gratis, Honcho Sinsa tidak akan berhenti mengomelinya.",
  ui_story_1021_10211001_20_dialog_content = "Lagi pula, saya lebih suka mendukung semua orang dari Gurun Rediesel, di mana cuacanya hangat dan nyaman. Northland memang tempat yang indah dan semuanya, tetapi saya lebih suka tidak kembali lagi.",
  ui_story_1021_10211001_21_dialog_content = "Jadi bagaimana dengan bergabung dengan kami dalam ekspedisi?",
  ui_story_1021_10211001_22_dialog_content = "Kita lihat saja nanti. Aku ini orang yang sangat sibuk, tahu?",
  ui_story_1021_10211001_23_dialog_content = "Hari ini, yang tampak begitu jauh meskipun prediksiku tentang itu, hampir di tangan.",
  ui_story_1021_10211001_24_dialog_content = "Di masa lalu, setiap faksi memiliki sikapnya sendiri, dan ekspedisi gabungan tidak lebih dari aspirasi politik yang mulia.",
  ui_story_1021_10211001_25_dialog_content = "Tapi sekarang, mereka saling menjaga satu sama lain seperti kawan seperjuangan yang sejati...",
  ui_story_1021_10211001_26_dialog_content = "Saya berdoa agar kekompakan mereka bertahan dan melindungi mereka saat mereka memasuki Dark Zone.",
  ui_story_1021_10211001_27_dialog_content = "<color=#e8d9bb>Dekat Pine Frost Valley</color>",
  ui_story_1021_10211001_28_dialog_content = "PlayerName! Tunggu!",
  ui_story_1021_10211001_29_dialog_content = "Ada apa, Tiare?",
  ui_story_1021_10211001_30_dialog_content = "Aku membawa beberapa hadiah untuk semua orang! Tapi dalam perjalanan ke sini, aku secara tidak sengaja menjatuhkannya, bersama dengan orang yang membantuku mengantarkannya. Maaf!",
  ui_story_1021_10211001_31_dialog_content = "Kamu tidak bisa terus melakukan ini, Tiare. Dengan keadaan seperti ini, tidak ada yang akan cukup berani untuk bergaul denganmu...",
  ui_story_1021_10211001_32_dialog_content = "Jadi apa rencanamu sekarang? Kami sangat senang jika kamu mau menjadi anggota Tim Ekspedisi kami, tahu?",
  ui_story_1021_10211001_33_dialog_content = "Dengan keberanian dan kelincahanmu, saya yakin kamu bisa membantu kami dalam situasi berbahaya apa pun!",
  ui_story_1021_10211001_34_dialog_content = "Aku berterima kasih atas tawaranmu, tapi jangan lupa bahwa aku punya hal yang lebih penting untuk dilakukan sekarang.",
  ui_story_1021_10211001_35_dialog_content = "Setelah segala yang telah kita lalui bersama, saya menyadari bahwa tugas-tugas saya jauh dari selesai.",
  ui_story_1021_10211001_36_dialog_content = "Sebagai penjaga sejati Northland, saya harus terus melakukan yang terbaik!",
  ui_story_1021_10211001_37_dialog_content = "Inilah sebabnya saya memutuskan untuk tetap tinggal di Northland! Saya akan melanjutkan cerita yang dimulai oleh leluhur rubah salju saya dan ratu-ratu Northland terdahulu!",
  ui_story_1021_10211001_38_dialog_content = "Aku akan meminta tetua itu untuk berbagi setiap cerita yang tidak pernah diceritakan nenekku kepadaku!",
  ui_story_1021_10211001_39_dialog_content = "Sepertinya cara yang penuh makna untuk menghormati warisan mereka! Jangan lupa, saya juga ada di sana untuk menjadi saksi bagian dari cerita itu!",
  ui_story_1021_10211001_40_dialog_content = "Jika kamu mendengar cerita baru, ingatlah untuk menceritakannya semua kepada saya dalam sebuah surat!",
  ui_story_1021_10211001_41_dialog_content = "Oh! Ada satu cara lain—",
  ui_story_1021_10211001_42_dialog_content = "Grr...",
  ui_story_1021_10211001_43_dialog_content = "Grr...",
  ui_story_1021_10211001_44_dialog_content = "Kenapa kalian berdua menjerit seperti binatang sementara aku sendirian menyeret semua barang ini?",
  ui_story_1021_10211001_45_dialog_content = "Apakah itu...",
  ui_story_1021_10211001_46_dialog_content = "Itu Zarya, teman lain yang saya temui di Northland.",
  ui_story_1021_10211001_47_dialog_content = "Jadi kamu adalah orang yang membantu Tiare membawa hadiah-hadiahnya...",
  ui_story_1021_10211001_48_dialog_content = "Dia berlari lebih cepat dari angin! Saya benar-benar kehilangan jejaknya bahkan sebelum saya menyentuh tanah!",
  ui_story_1021_10211001_49_dialog_content = "Nah, itu hal yang cukup umum ketika kamu bepergian dengan Tiare.",
  ui_story_1021_10211001_50_dialog_content = "Apakah itu? Atau karena Tiare masih marah padaku?",
  ui_story_1021_10211001_51_dialog_content = "Humph! Itu salahmu sendiri karena melemparkan sejumlah kristal es ke anak-anak!",
  ui_story_1021_10211001_52_dialog_content = "Kamulah yang lupa memberitahuku bahwa pergi ke rumahmu melibatkan rubah salju yang bergantian menjilati tanganku...",
  ui_story_1021_10211001_53_dialog_content = "Itu bukan adat di tempat lain di Northland!",
  ui_story_1021_10211001_54_dialog_content = "...",
  ui_story_1021_10211001_55_dialog_content = "Jadi, apakah benda-benda yang bersinar itu adalah hadiahmu?",
  ui_story_1021_10211001_56_dialog_content = "Apakah ini Lumina Ore?",
  ui_story_1021_10211001_57_dialog_content = "Tepat sekali! Saya sudah menjalankan diri saya compang-camping mengangkut semua ini langsung dari rumah Tiare!",
  ui_story_1021_10211001_58_dialog_content = "Aku tidak bisa menerima sesuatu yang seberharga ini sebagai hadiah!",
  ui_story_1021_10211001_59_dialog_content = "Mengapa tidak? Sebagai pemimpin dari rubah salju, saya ingin membayar kalian semua dengan layak karena telah menyelamatkan sukuku...",
  ui_story_1021_10211001_60_dialog_content = "Ini juga keinginan penatua.",
  ui_story_1021_10211001_61_dialog_content = "Ratu juga mengatakan bahwa bijih ini dapat digunakan untuk mengusir Eclipsites dan menerangi jalanmu melalui Zona Gelap. Kamu akan membutuhkannya dalam ekspedisi kamu.",
  ui_story_1021_10211001_62_dialog_content = "Namun, cahaya mereka juga mencegah Eclipsite menyeberangi perbatasan Northland...",
  ui_story_1021_10211001_63_dialog_content = "Ini adalah hadiah dari suku kami! Ambil sekarang sebelum aku menyesalinya!",
  ui_story_1021_10211001_64_dialog_content = "Ah... A-Aku menerima!",
  ui_story_1021_10211001_65_dialog_content = "(Mulai merindukan saat dia hanya menjadi pengawal ratu...)",
  ui_story_1021_10211001_66_dialog_content = "...",
  ui_story_1021_10211001_67_dialog_content = "Sepertinya kau sekarang sudah merasa tenang membiarkan Tiare melakukan apa yang dia inginkan.",
  ui_story_1021_10211001_68_dialog_content = "Bahkan jika bukan sebagai pengawal kerajaan saya, saya yakin dia akan menemukan tempatnya di Northland suatu hari nanti.",
  ui_story_1021_10211001_69_dialog_content = "Namun demikian, kamu akan selalu menjadi mercusuar bagi dirinya. Sejak longsoran salju itu, hal ini selalu terjadi.",
  ui_story_1021_10211001_70_dialog_content = "<color=#e8d9bb>Hari suku itu dimusnahkan...</color>",
  ui_story_1021_10211001_71_dialog_content = "Apakah kamu merasa kesulitan, bertugas sebagai pengawal ratu?",
  ui_story_1021_10211001_72_dialog_content = "Yang Mulia Ratu memiliki kekuatan yang tak terbayangkan... Setiap kali ada bahaya, ratu selalu datang untuk menyelamatkan. Akibatnya, pekerjaanku jarang sekali sulit.",
  ui_story_1021_10211001_73_dialog_content = "Dia selalu menyelamatkanku dari bahaya, berulang kali...",
  ui_story_1021_10211001_74_dialog_content = "Suku Fox Salju selalu membayar hutangnya, itulah sebabnya saya bersumpah untuk melindunginya setelah dia menyelamatkan saya dari longsoran salju itu.",
  ui_story_1021_10211001_75_dialog_content = "Apakah kamu benar-benar percaya bahwa kamu mengerti dia?",
  ui_story_1021_10211001_76_dialog_content = "Tentu saja! Ketika Yang Mulia Ratu sedang berpatroli di tanah kita, aku mengikutinya dengan dekat tanpa dia tahu...",
  ui_story_1021_10211001_77_dialog_content = "Gerakannya, aromanya, bahkan cara dia bernapas—saya mengenal semuanya terlalu baik.",
  ui_story_1021_10211001_78_dialog_content = "Aku bisa merasakan penolakan suku terhadap orang luar, tapi ratu berbeda...",
  ui_story_1021_10211001_79_dialog_content = "Ketika dia menatapku, itu mengingatkanku pada kerabat jauh yang hanya berkunjung sekali setahun...",
  ui_story_1021_10211001_80_dialog_content = "Ketika dia muncul, dia memancarkan cahaya tertentu pada suku dan dunia saya juga...",
  ui_story_1021_10211001_81_dialog_content = "Maka tampaknya kamu tahu apa yang harus dilakukan, Tiare. Jawabannya selalu ada di dalam hatimu.",
  ui_story_1021_10211001_82_dialog_content = "Orang yang mengisi duniamu dengan cahaya adalah beacon untuk hidupmu.",
  ui_story_1021_10211001_83_dialog_content = "May kamu mengikuti cahaya beaconmu dan berjemur dalam cahaya hangatnya.",
  ui_story_1021_10211001_84_dialog_content = "Ketika kamu akhirnya mampu menerangi jalanmu sendiri, saya yakin cahayamu akan menjadi beacon untuk suku kita.",
  ui_story_1021_10211001_85_dialog_content = "...",
  ui_story_1021_10211001_86_dialog_content = "Bukankah kamu akan memberitahunya kebenaran tentang longsoran salju?",
  ui_story_1021_10211001_87_dialog_content = "Memberitahunya tidak akan membuat perbedaan pada titik ini.",
  ui_story_1021_10211001_88_dialog_content = "...",
  ui_story_1021_10211001_89_dialog_content = "Meski begitu, saya percaya Anda juga adalah mercusuar bagi dia.",
  ui_story_1021_10211001_90_dialog_content = "<color=#e8d9bb>Beberapa tahun lalu...</color>",
  ui_story_1021_10211001_91_dialog_content = "<color=#e8d9bb>Remuk, remuk, kegentingan—</color>",
  ui_story_1021_10211001_92_dialog_content = "?",
  ui_story_1021_10211001_93_dialog_content = "(Dalam sekejap, gadis kecil yang dulu melempar bola salju padaku telah tumbuh dewasa...)",
  ui_story_1021_10211001_94_dialog_content = "(Merasa sangat kesepian saat tinggal sendirian di Hutan Snowpine pasti terasa begitu sepi kadang-kadang.)",
  ui_story_1021_10211001_95_dialog_content = "<color=#e8d9bb>Kresek, kresek-</color>",
  ui_story_1021_10211001_96_dialog_content = "...",
  ui_story_1021_10211001_97_dialog_content = "...",
  ui_story_1021_10211001_98_dialog_content = "(Dan meski begitu dia masih anak kecil yang sangat tidak sabar...)",
  ui_story_1021_10211001_99_dialog_content = "(Dia selalu mengikutiku dari jauh, tetapi hari ini dia memilih untuk menunjukkan dirinya kepadaku...)",
  ui_story_1021_10211001_100_dialog_content = "...",
  ui_story_1021_10211001_101_dialog_content = "Setiap tahun, sekitar waktu yang sama, kamu muncul di tanah ini.",
  ui_story_1021_10211001_102_dialog_content = "...",
  ui_story_1021_10211001_103_dialog_content = "Tapi kamu belum memenuhi janjimu dan membawa cahaya Beacon kepada kami.",
  ui_story_1021_10211001_104_dialog_content = "...",
  ui_story_1021_10211001_105_dialog_content = "Terima kasih semua. Tanpa kalian, Northland tidak akan seaman ini hari ini.",
  ui_story_1021_10211001_106_dialog_content = "Meski leluhur kita memilih untuk tinggal di sini dan gugur dalam perang...",
  ui_story_1021_10211001_107_dialog_content = "Pilihan untuk terus melindungi tempat ini adalah milik kita sendiri.",
  ui_story_1021_10211001_108_dialog_content = "...",
  ui_story_1021_10211001_109_dialog_content = "Ambil Tiare dan pergi.",
  ui_story_1021_10211001_110_dialog_content = "?",
  ui_story_1021_10211001_111_dialog_content = "Hari-hariku sudah terhitung. Ketika dia sudah lebih tua, dia akan belajar tentang harga dari perlindungan dan beban tanggung jawabnya.",
  ui_story_1021_10211001_112_dialog_content = "Saya tidak ingin dia menghabiskan hidupnya dengan keras kepala melindungi Hutan Snowpine dalam kesendirian, seperti yang pernah dilakukan neneknya.",
  ui_story_1021_10211001_113_dialog_content = "Tiare... adalah anak yang keras kepala.",
  ui_story_1021_10211001_114_dialog_content = "Tapi saya sangat menyadari rasa ingin tahu dan harapan yang dia rasakan terhadapmu.",
  ui_story_1021_10211001_115_dialog_content = "...",
  ui_story_1021_10211001_116_dialog_content = "<color=#e8d9bb>Elder itu melompat kembali ke dalam hutan, dan bola salju raksasa menggelinding menuju Tiare...</color>",
  ui_story_1021_10211001_117_dialog_content = "Ahhh!",
  ui_story_1021_10211001_118_dialog_content = "Ini berakhir saat es mencair—",
  ui_story_1021_10211001_119_dialog_content = "Kamu telah menyelamatkanku...",
  ui_story_1021_10211001_120_dialog_content = "Dan tidak hanya itu...",
  ui_story_1021_10211001_121_dialog_content = "Tombakmu seharusnya jauh lebih tahan lama sekarang.",
  ui_story_1021_10211001_122_dialog_content = "Ini bersinar dengan cahaya yang sangat terang!",
  ui_story_1021_10211001_123_dialog_content = "Seperti mercusuar itu...",
  ui_story_1021_10211001_124_dialog_content = "Tunggu...",
  ui_story_1021_10211001_125_dialog_content = "...",
  ui_story_1021_10211001_126_dialog_content = "Na-na-nama saya Tiare!",
  ui_story_1021_10211001_127_dialog_content = "...",
  ui_story_1021_10211001_128_dialog_content = "Dan mulai hari ini, tidak peduli kemana kamu pergi, aku akan selalu ada untuk melindungimu! Suku Snow Fox selalu membayar hutangnya!",
  ui_story_1021_10211001_129_dialog_content = "...",
  ui_story_1021_10211001_130_dialog_content = "Terima kasih atas semua yang telah kamu lakukan untuk Northland.",
  ui_story_1021_10211001_131_dialog_content = "Meski janjiku memberatkan, aku tetap membawanya dengan bangga di setiap langkah yang kuambil...",
  ui_story_1021_10211001_132_dialog_content = "Aku berjanji kepada kalian semua bahwa cahaya Beacon Northland akan mencapai tempat ini...",
  ui_story_1021_10211001_133_dialog_content = "Suatu hari nanti, itu akan menerangi tanah yang lebih jauh lagi.",
  ui_story_1022_10220100_1_dialog_content = "(Apa... di mana aku?)",
  ui_story_1022_10220100_2_dialog_content = "<color=#e8d9bb>Dunia sekitar dingin dan sama sekali tidak ada cahaya, membuatnya mustahil untuk menentukan arah.</color>",
  ui_story_1022_10220100_3_dialog_content = "(Kenapa aku berada di tempat seperti ini?)",
  ui_story_1022_10220100_4_dialog_content = "(Makin dingin... Aku tidak bisa hanya diam di sini, aku harus terus bergerak!)",
  ui_story_1022_10220100_5_dialog_content = "(Tapi kemana aku harus pergi? Terlalu gelap untuk melihat apa-apa... Huh? Apa itu?)",
  ui_story_1022_10220100_6_dialog_content = "<color=#e8d9bb>Sebutir cahaya kecil, jauh di kejauhan, menembus kegelapan yang menghimpit.</color>",
  ui_story_1022_10220100_7_dialog_content = "<color=#e8d9bb>Tanpa terpengaruh oleh malam yang dingin dan menindas, cahaya terus menerus makin terang, sampai kehangatan dan kilauannya menerangi segala yang ada di sekitarnya.</color>",
  ui_story_1022_10220100_8_dialog_content = "<color=#e8d9bb>Seperti matahari yang bersinar melalui malam yang abadi.</color>",
  ui_story_1022_10220100_9_dialog_content = "(Sebuah sumber Lumina yang besar... Sangat murni, dan aku merasa seperti sedang diawasi... Atau bahkan dipandu.)",
  ui_story_1022_10220100_10_dialog_content = "... akhirnya kamu akan melupakan. Waktu menyembuhkan semua, dan jika ada seseorang yang lebih istimewa masuk ke dalam hidupmu, kamu akan melanjutkan hidup.",
  ui_story_1022_10220100_11_dialog_content = "Siapa itu? Apakah kamu berbicara dengan saya?",
  ui_story_1022_10220100_12_dialog_content = "I-Ini sangat dingin... Seluruh tubuhku membeku...",
  ui_story_1022_10220100_13_dialog_content = "... Masuk angin, meong!",
  ui_story_1022_10220100_14_dialog_content = "Dingin... Sangat dingin...",
  ui_story_1022_10220100_15_dialog_content = "Itu karena kamu menendang selimutnya. Aku tidak bisa menutupimu dengan itu juga, karena kamu menggulingkan diri di atasnya!",
  ui_story_1022_10220100_16_dialog_content = "Jadi jika kamu tidak ingin masuk angin, bangunlah sekarang juga.",
  ui_story_1022_10220100_17_dialog_content = "Hah? Apakah aku baru saja tertidur? Jadi semua itu hanya mimpi...",
  ui_story_1022_10220100_18_dialog_content = "Dingin sekali juga! Terima kasih sudah membangunkan saya, Philyshy.",
  ui_story_1022_10220100_19_dialog_content = "Jangan sebut itu! Dan karena tempatmu sekarang kosong, giliran saya untuk tidur kucing sebentar...",
  ui_story_1022_10220100_20_dialog_content = "Hah? H-Hei, tunggu sebentar! Jangan hanya tertidur begitu saja!",
  ui_story_1022_10220100_21_dialog_content = "Bagaimana situasinya? Di mana kita sekarang?",
  ui_story_1022_10220100_22_dialog_content = "Lihatlah ke luar jendela dan buktikan sendiri, meong.",
  ui_story_1022_10220100_23_dialog_content = "Apa di luar... Ah!",
  ui_story_1022_10220100_24_dialog_content = "<color=#e8d9bb>Di luar pesawat, kegelapan tebal dan padat mengalir melintasi tanah, membentang tanpa henti ke kejauhan.</color>",
  ui_story_1022_10220100_25_dialog_content = "<color=#e8d9bb>Seperti dalam mimpi buruk itu.</color>",
  ui_story_1022_10220100_26_dialog_content = "Dark Zone... Kita sudah berada di Zona Gelap?",
  ui_story_1022_10220100_27_dialog_content = "Yep! Aku akan memberitahumu, tapi aku melihatmu menggigil kedinginan, meong.",
  ui_story_1022_10220100_28_dialog_content = "E-Ehem!",
  ui_story_1022_10220100_29_dialog_content = "(Saya bertanya-tanya apakah Zona Gelap mungkin telah mempengaruhi mimpi yang baru saja saya alami.)",
  ui_story_1022_10220100_30_dialog_content = "(Dan bola Lumina itu... Apakah itu juga ada di dunia nyata...?)",
  ui_story_1022_10220100_31_option_content = "Jangkauan Telepati",
  ui_story_1022_10220100_32_dialog_content = "…!",
  ui_story_1022_10220100_33_dialog_content = "(Dia memang ada! Tapi... Kira-kira apa?)",
  ui_story_1022_10220100_34_dialog_content = "Lagipula, situasi memang sedikit memburuk...",
  ui_story_1022_10220100_35_dialog_content = "Aku mampu melacak dua set koordinat yang berbeda.",
  ui_story_1022_10220100_36_dialog_content = "Set pertama milik tim eksplorasi elit Lumina. Set lainnya milik Perwira Charon dan Vice.",
  ui_story_1022_10220100_37_dialog_content = "Apa yang terjadi pada Vice?!",
  ui_story_1022_10220100_38_dialog_content = "Tenangkan diri sedikit... meski aku rasa aku tidak bisa menyalahkanmu karena khawatir. Sesuatu pasti tidak beres dengan koordinat mereka.",
  ui_story_1022_10220100_39_dialog_content = "Sinyal dari tim eksplorasi semakin melemah seiring waktu. Mungkin Zona Gelap memiliki efek negatif pada perangkat komunikasi kita.",
  ui_story_1022_10220100_40_dialog_content = "Tapi, bukankah komunikator kita seharusnya bisa bekerja di dalam Dark Zone?",
  ui_story_1022_10220100_41_dialog_content = "Itu benar, tetapi ada hal lain yang perlu dipikirkan. Geografi, cuaca, jarak, dan kepadatan Darkflow semua bisa berdampak serius pada efektivitas komunikator kita.",
  ui_story_1022_10220100_42_dialog_content = "Saya melihat... J-Jadi bagaimana dengan Vice dan Charon?",
  ui_story_1022_10220100_43_dialog_content = "Koordinat mereka... terus melompat ke mana-mana.",
  ui_story_1022_10220100_44_dialog_content = "Melompat?",
  ui_story_1022_10220100_45_dialog_content = "Ya! Mereka terus bergerak seperti titik laser, satu saat di sini dan saat berikutnya di sana. Aku mulai merasa pusing; aku hanya mencoba mengikuti. Meong!",
  ui_story_1022_10220100_46_dialog_content = "Sejauh yang saya tahu, Other End milik Charon tidak mampu melakukan gerakan seperti itu...",
  ui_story_1022_10220100_47_dialog_content = "Tapi sepertinya komunikator mereka juga tidak rusak. Aneh, bukan?",
  ui_story_1022_10220100_48_dialog_content = "Mungkin ini efek lain dari Dark Zone... Apakah kita masih tidak bisa menghubungi mereka?",
  ui_story_1022_10220100_49_dialog_content = "Komandan Hiiro mencoba, tapi masih belum berhasil... Saya bahkan tidak tahu mereka lari ke mana kali ini.",
  ui_story_1022_10220100_50_dialog_content = "Bagaimana ini bisa terjadi, meong?! Aku sudah membaca setiap laporan intel tentang tempat ini, tapi aku masih belum mendapatkan jawabannya! Kayaknya aku benar-benar harus kerja keras untuk ini!",
  ui_story_1022_10220100_51_dialog_content = "Kamu tidak berpikir mereka... bertemu dengan Hantu, bukan...?",
  ui_story_1022_10220100_52_dialog_content = "Meong?!",
  ui_story_1022_10220100_53_dialog_content = "Kita masih belum tahu apa-apa tentang kekuatan mereka, bukan? Mereka bahkan mungkin mampu melakukan sesuatu yang gila seperti teleportasi!",
  ui_story_1022_10220100_54_dialog_content = "Saya yakin Hantu-hantu akan sangat tertarik dengan kemampuan Vice untuk memiloti Colossus seperti Tombak Unggul juga...",
  ui_story_1022_10220100_55_dialog_content = "Bagaimana jika salah satu dari mereka berhasil menyandera dia dan menimbulkan kekacauan di seluruh dunia?!",
  ui_story_1022_10220100_56_dialog_content = "Meong!!! I-Itu akan menjadi...",
  ui_story_1022_10220100_57_dialog_content = "Itu akan hampir mustahil, mengingat bahwa Charon dan Other End bersamanya sekarang.",
  ui_story_1022_10220100_58_dialog_content = "Komandan Hiiro!",
  ui_story_1022_10220100_59_dialog_content = "Hiiro... Apakah kamu yakin itu mustahil? Meskipun hanya ada sedikit kesempatan, bagaimana jika—",
  ui_story_1022_10220100_60_dialog_content = "<color=#e8d9bb>Plak!</color>",
  ui_story_1022_10220100_61_dialog_content = "Aduh—",
  ui_story_1022_10220100_62_dialog_content = "(D-Dia baru saja mengetuk kepalaku sangat keras...)",
  ui_story_1022_10220100_63_dialog_content = "Tidak mungkin untuk sepenuhnya menyingkirkan kemungkinan, yang membuatnya sama-sama sia-sia untuk khawatir tentang itu.",
  ui_story_1022_10220100_64_dialog_content = "Sebelum kita memulai ekspedisi ini, kamu bilang kamu akan menguatkan sarafmu dan menghindari terlalu cepat mengambil kesimpulan. Apakah kamu sudah lupa tentang itu?",
  ui_story_1022_10220100_65_dialog_content = "S-Saya belum, tapi saya tidak bisa tidak peduli ketika mendengar tentang Vice terlibat dalam situasi yang aneh...",
  ui_story_1022_10220100_66_dialog_content = "(Aduh, kepalaku... Hiiro memukulku dengan keras!)",
  ui_story_1022_10220100_67_dialog_content = "Saya mengerti, tetapi Dark Zone penuh dengan bahaya yang tak terbayangkan. Kamu perlu tetap fokus.",
  ui_story_1022_10220100_68_dialog_content = "Saya harap Vice juga ingat hal ini. Sama seperti kamu, dia adalah orang pertama yang khawatir tentang orang lain segera setelah situasi menjadi berbahaya.",
  ui_story_1022_10220100_69_dialog_content = "Dia masih membutuhkan lebih banyak latihan sebagai seorang prajurit.",
  ui_story_1022_10220100_70_dialog_content = "Hiiro... Kamu benar-benar khawatir tentang Vice juga, bukan?",
  ui_story_1022_10220100_71_dialog_content = "Bukankah sudah jelas?",
  ui_story_1022_10220100_72_dialog_content = "Vice, Perwira Charon, dan bahkan Perwira Teknik Gronru... Tidak ada kekurangan kucing nakal di antara kita, huh?",
  ui_story_1022_10220100_73_dialog_content = "Gronru? Apa yang terjadi padanya?",
  ui_story_1022_10220100_74_dialog_content = "... Sejak Tombak Unggul muncul kembali, Gronru telah mengubur dirinya dalam pekerjaan perbaikan tanpa henti. Dia bahkan tidak menyentuh video game sama sekali selama ini.",
  ui_story_1022_10220100_75_dialog_content = "Sebagai orang yang pernah bertanggung jawab atas eksperimen Tombak Unggul, dia kemungkinan besar merasa bersalah kepada Vice dan Grand Marshal...",
  ui_story_1022_10220100_76_dialog_content = "Kita tidak punya waktu untuk khawatir tentang perasaan orang lain sekarang. Situasi kita sudah cukup berbahaya seperti adanya.",
  ui_story_1022_10220100_77_dialog_content = "Pesawat kami dirancang untuk terbang bersama dua pesawat lainnya, sehingga kami dapat melindungi satu sama lain.",
  ui_story_1022_10220100_78_dialog_content = "Tapi sekarang koordinat mereka menjadi tidak pasti, kita perlu membuat beberapa penyesuaian darurat pada operasi kita.",
  ui_story_1022_10220100_79_dialog_content = "Sebanyak apapun kita khawatir tentang Charon dan Vice, saya yakin kita semua setuju bahwa berkumpul kembali dengan mereka bukanlah pilihan sekarang, bukan?",
  ui_story_1022_10220100_80_dialog_content = "(Dia benar. Meski kita berhasil menyusul ke posisi mereka, ada kemungkinan besar mereka akan teleport ke tempat lain lagi... Sial!)",
  ui_story_1022_10220100_81_dialog_content = "Karena gangguan dari Zona Gelap, kami juga belum menerima sinyal dari tim penjelajah dalam waktu yang lama.",
  ui_story_1022_10220100_82_dialog_content = "Pada titik ini, kita hanya membuang waktu dengan mencari-cari dalam kegelapan. Kita tidak akan mencapai apa-apa jika ini terus berlanjut.",
  ui_story_1022_10220100_83_dialog_content = "... Ada bola Lumina di luar sana.",
  ui_story_1022_10220100_84_dialog_content = "Apa?",
  ui_story_1022_10220100_85_dialog_content = "Aku... Aku merasakan konsentrasi Lumina yang sangat besar di suatu tempat dalam Zona Gelap. Aku tidak bisa menjelaskannya dengan baik, tapi mungkin dekat dengan perbatasan malam yang abadi.",
  ui_story_1022_10220100_86_dialog_content = "... Saya tidak bisa percaya ada hal seperti itu, meong!",
  ui_story_1022_10220100_87_dialog_content = "Sulit untuk percaya Lumina bisa berada di Zona Gelap. Tetapi jika tim lain memperhatikan sesuatu yang tidak biasa, mereka mungkin akan memeriksanya.",
  ui_story_1022_10220100_88_dialog_content = "Ini bisa menjadi titik kumpul dadakan untuk kita semua...",
  ui_story_1022_10220100_89_dialog_content = "Komandan Hiiro! Ada permintaan masuk dari basis belakang kita!",
  ui_story_1022_10220100_90_dialog_content = "Kirimkan melalui.",
  ui_story_1022_10220100_91_dialog_content = "Paham!",
  ui_story_1022_10220100_92_dialog_content = "... Tes, tes. Apakah ada yang mendengar saya?",
  ui_story_1022_10220100_93_dialog_content = "Reinhardt! Syukurlah kita masih bisa menghubungi kamu!",
  ui_story_1022_10220100_94_dialog_content = "Kami mendengar Anda dengan jelas, Grand Marshal. Sepertinya beberapa saluran komunikasi kami masih utuh.",
  ui_story_1022_10220100_95_dialog_content = "Itu tidak membuat Zona Gelap menjadi kurang bermasalah. Masih belum ada tanda dari tim penjelajah atau koordinat mereka, ya?",
  ui_story_1022_10220100_96_dialog_content = "Kamu benar-benar memiliki banyak pekerjaan kali ini, Hiiro. Tetap semangat.",
  ui_story_1022_10220100_97_dialog_content = "Tentu saja. Bawahan saya masih di luar sana, dan tugas saya untuk membawanya pulang dengan selamat.",
  ui_story_1022_10220100_98_dialog_content = "Dan dengan tentara Lumopolis yang mendirikan kamp dasar di tanah, kita tidak perlu khawatir tentang melindungi belakang kita.",
  ui_story_1022_10220100_99_dialog_content = "Bagaimana dengan kamu, Grand Marshal? Bagaimana perkembanganmu dengan Komite? Apakah mereka membuatnya sulit untukmu?",
  ui_story_1022_10220100_100_dialog_content = "Humph, jika mereka tidak memberi saya masalah, saya akan mulai bertanya-tanya apakah saya berada di jalur yang benar.",
  ui_story_1022_10220100_101_dialog_content = "Dalam hal apapun, segala sesuatu berjalan lancar di ujung saya. Seiring berjalannya waktu, tampaknya Komite adalah ular yang memakan ekornya sendiri.",
  ui_story_1022_10220100_102_dialog_content = "Aku tidak benar-benar mengerti kata-katamu.",
  ui_story_1022_10220100_103_dialog_content = "Tidak masalah jika itu Belisaria atau aktor tanpa nama lainnya dalam pertunjukan... kita bahkan bisa menghitung Ulysses masuk!",
  ui_story_1022_10220100_104_dialog_content = "Mereka tidak menginginkan apa pun selain menggunakan sains dan teknologi untuk memastikan kelangsungan hidup semua Aurorian.",
  ui_story_1022_10220100_105_dialog_content = "Itu tidak bisa disangkal, ya.",
  ui_story_1022_10220100_106_dialog_content = "Tapi sains dan teknologi juga bisa menjadi tidak berperasaan, dan kedekatan Komite dengan aspek-aspek kejam tersebut telah memberikan pengaruh mendalam pada mereka.",
  ui_story_1022_10220100_107_dialog_content = "Namun, ada sisi dingin dan keras dari teknologi. Komite itu paling dekat dengannya dan paling terpengaruh.",
  ui_story_1022_10220100_108_dialog_content = "Sebagai imbalan atas rasionalitas, efisiensi, dan praktikalitas, mereka telah meninggalkan belas kasihan mereka terhadap sesama Aurorian... Dan dengan melakukan itu, mereka bertentangan dengan tujuan asli mereka—",
  ui_story_1022_10220100_109_dialog_content = "Untuk menciptakan dunia di mana Aurorian dapat hidup bahagia dan damai.",
  ui_story_1022_10220100_110_dialog_content = "(Bahkan Ulysses hanya ingin meningkatkan Aurorian untuk membantu mereka melawan Eclipsites...)",
  ui_story_1022_10220100_111_dialog_content = "... Jika mereka mengejar efisiensi secara buta dengan mengorbankan kemanusiaan mereka, apa yang membuat mereka berbeda dari Eclipsite yang mengikuti perintah dari Hantu?",
  ui_story_1022_10220100_112_dialog_content = "Tepatnya, inilah sebabnya generasi terbaru dari para pemimpin ingin menemukan jalan lain ke depan, seperti Yingel dan Sean.",
  ui_story_1022_10220100_113_dialog_content = "Aku tidak ingin tertinggal, aku harus mencapai beberapa prestasi luar biasa lagi, seperti mereka.",
  ui_story_1022_10220100_114_dialog_content = "Tidakkah kamu pikir kamu sudah membuat cukup banyak dari itu...?",
  ui_story_1022_10220100_115_dialog_content = "Hahaha! Kamu membuatnya terdengar seperti hal yang buruk!",
  ui_story_1022_10220100_116_dialog_content = "... Tapi kenyataannya, aku masih memiliki banyak hal yang harus dicapai sebagai Grand Marshal di Illumina. Aku mengabaikan berbagai ancaman tersembunyi di masa lalu karena perang.",
  ui_story_1022_10220100_117_dialog_content = "Karena itu, saya harus berkompromi dengan Komite seperti pendahuluku, sementara mereka mengambil alih kendali jalannya Federasi ke masa depan.",
  ui_story_1022_10220100_118_dialog_content = "Saya sudah mendengar cukup, Grand Marshal! Kita semua tahu kamu bukan orang seperti itu, dan—",
  ui_story_1022_10220100_119_dialog_content = "Santai, Hiiro. Aku hanya menyampaikan fakta agar bisa menetapkan tujuan baru untuk diriku sendiri.",
  ui_story_1022_10220100_120_dialog_content = "Aku bukanlah seperti dulu. Revolusi yang kita bayangkan kala itu akan menjadi kenyataan, dan akulah yang akan mewujudkannya.",
  ui_story_1022_10220100_121_dialog_content = "Komite mungkin masih memiliki tujuannya, tetapi saya menolak untuk membiarkan mereka mengalihkan kekuatan Illumina ke jalan yang salah.",
  ui_story_1022_10220100_122_dialog_content = "Aku akan mengungkap wajah yang tersembunyi di balik topeng besi mereka dan melihat apakah masih ada kemanusiaan yang tersisa di dalam mereka.",
  ui_story_1022_10220100_123_dialog_content = "Sekarang, tak banyak lagi yang bisa kukatakan, tapi aku berjanji akan menjelaskan semuanya segera. Beri aku sedikit waktu lagi, semuanya.",
  ui_story_1022_10220100_124_dialog_content = "<color=#e8d9bb>Sementara itu, di pertemuan Komite Illumina—</color>",
  ui_story_1022_10220100_125_dialog_content = "Reinhardt melakukan comeback setelah kekalahannya, eksperimen Ulysses terbongkar di depan dunia...",
  ui_story_1022_10220100_126_dialog_content = "Dan sekarang aku khawatir senjata yang disiapkan untuk Azurite akan mengalami nasib yang sama.",
  ui_story_1022_10220100_127_dialog_content = "Sepertinya setiap rencana yang kamu pilih untuk dukung selalu berakhir menjadi bumerang untukmu.",
  ui_story_1022_10220100_128_dialog_content = "Jadi, katakan pada kami, Belisaria, bagaimana kau berniat untuk bertanggung jawab atas ini?",
  ui_story_1022_10220100_129_dialog_content = "Reputasi Committee akan benar-benar hancur jika kita terus menutupi kegagalan memalukan ini!",
  ui_story_1022_10220100_130_dialog_content = "Lalu kenapa repot-repot menyembunyikannya, terutama pada saat seperti ini?",
  ui_story_1022_10220100_131_dialog_content = "Jika menjaga muka begitu penting bagi kamu, maka kamu sebaiknya meminta saya untuk mengundurkan diri sekarang juga.",
  ui_story_1022_10220100_132_dialog_content = "... Dan apa kamu punya masalah dengan itu?",
  ui_story_1022_10220100_133_dialog_content = "Ini bukan tentang aku. Yang penting adalah apakah situasi itu membutuhkannya atau tidak.",
  ui_story_1022_10220100_134_dialog_content = "Saya siap mundur kapan saja, jika diperlukan, untuk melindungi reputasi Komite.",
  ui_story_1022_10220100_135_dialog_content = "Itulah alasan saya berada di sini.",
  ui_story_1022_10220100_136_dialog_content = "... Hmm.",
  ui_story_1022_10220100_137_dialog_content = "Tapi sebelum kamu mengambil langkah apa pun, saya minta kamu mempertimbangkan Reinhardt, serta kekuatan dan daya tariknya.",
  ui_story_1022_10220100_138_dialog_content = "Apakah kamu sudah mempertimbangkan moral prajurit yang bertugas di bawah Grand Marshal? Bagaimana pandangan mereka terhadap Committee?",
  ui_story_1022_10220100_139_dialog_content = "...",
  ui_story_1022_10220100_140_dialog_content = "Alasan satu-satunya kita bisa sampai sejauh ini adalah karena Illumina memilih untuk membagi kekuasaan pemerintahannya antara Committee dan militer.",
  ui_story_1022_10220100_141_dialog_content = "Kemegahan Illumina saat ini dapat diatribusikan kepada sistem pengecekan dan keseimbangan antara kedua belah pihak. Tahun-tahun ketegangan dan pertarungan kekuasaan telah membawa kita ke titik ini dalam sejarah.",
  ui_story_1022_10220100_142_dialog_content = "Namun, ketika konflik tak terhindarkan meletus, kompetensi Grand Marshal menentukan sejauh mana kerentanan situasi kita.",
  ui_story_1022_10220100_143_dialog_content = "Di masa lalu, saya dipaksa untuk naik panggung dan bernegosiasi dengan militer. Tapi mengingat ketidaksepakatan kita saat ini dengan mereka, saya bisa dengan mudah memilih untuk pergi.",
  ui_story_1022_10220100_144_dialog_content = "Tapi apa yang terjadi setelah itu?",
  ui_story_1022_10220100_145_dialog_content = "Siapa di antara kalian yang akan menggantikan posisiku? Apakah ada di antara kalian yang mampu mengambil alih peran saya?",
  ui_story_1022_10220100_146_dialog_content = "<color=#e8d9bb>Keheningan panjang mengisi ruang pertemuan.</color>",
  ui_story_1022_10220100_147_dialog_content = "Masih ada satu hal yang belum selesai, jadi tolong luangkan waktu untuk memikirkan apa yang telah saya katakan.",
  ui_story_1022_10220100_148_dialog_content = "Tanpa adanya alasan, apa jenis masa depan yang akan diciptakan oleh kekuatan yang tidak terkendali?",
  ui_story_1022_10220100_149_dialog_content = "Tapi kita mungkin akan memulai perang sungguhan jika kita ikut campur lagi.",
  ui_story_1022_10220100_150_dialog_content = "Tujuan dari Komite selalu adalah untuk memberlakukan pembatasan. Mengapa kita harus takut konflik sekarang, di antara semua waktu?",
  ui_story_1022_10220100_151_dialog_content = "Tapi, bagaimana pertarungan internal yang tidak berarti dapat memajukan rencana kita?",
  ui_story_1022_10220100_152_dialog_content = "Untuk saat ini, kita harus menyerahkan kendali Illumina kepada <color=#FFB400>dia</color>. Seharusnya kita sudah melakukannya sebelumnya, tetapi ketidakpastian kita terhadap <color=#FFB400>dia</color> menghentikan kita.",
  ui_story_1022_10220100_153_dialog_content = "Hentikan pertengkaranmu. Kita harus bertindak sebagai satu jika kita ingin melewati badai ini.",
  ui_story_1022_10220100_154_dialog_content = "Sebagai satu? Ketika setiap orang di Illumina melihat kita tidak lebih dari gangguan? Heheh, tidak perlu jenius untuk tahu apa yang orang-orang pikirkan tentang Komite: peninggalan masa lalu yang keras kepala dan suka ikut campur.",
  ui_story_1022_10220100_155_dialog_content = "Sudahkah Anda membuat keputusan?",
  ui_story_1022_10220100_156_dialog_content = "Sepertinya sudah waktunya untuk <color=#FFB400>kita</color> untuk tampil.",
  ui_story_1022_10220100_157_dialog_content = "…!",
  ui_story_1022_10220100_158_dialog_content = "Illumina lahir dari perpecahan, tetapi itu tidak berarti harus mati karena hal itu.",
  ui_story_1022_10220100_159_dialog_content = "Tidak masalah siapa yang berkuasa pada saat tertentu. Yang penting adalah kita tidak mengulangi kesalahan kita.",
  ui_story_1022_10220100_160_dialog_content = "Illumina tidak akan pernah menerima pengkhianat lagi.",
  ui_story_1022_10220201_1_dialog_content = "<color=#e8d9bb>Jauh di dalam Dark Zone...</color>",
  ui_story_1022_10220201_2_dialog_content = "Tidak baik, Kapten. Kita masih tidak bisa membuat kontak dengan yang lain.",
  ui_story_1022_10220201_3_dialog_content = "Apakah ini berarti kita tidak akan pernah melihat mereka lagi...?",
  ui_story_1022_10220201_4_dialog_content = "Tidak apa-apa jika kita tidak bisa menghubungi mereka. Itu hanya berarti kita bebas melakukan apa saja yang kita inginkan.",
  ui_story_1022_10220201_5_dialog_content = "Berhubungan dengan mereka sama saja seperti berada di tali kekang. Ini hanya akan membuat pekerjaan kami semakin sulit.",
  ui_story_1022_10220201_6_dialog_content = "C-Kapten! Kamu yakin seharusnya kamu mengatakan itu dengan begitu keras...?",
  ui_story_1022_10220201_7_dialog_content = "Siapa yang menurutmu akan mendengar pembicaraan kita? Batu di sana? Atau mungkin bongkahan es raksasa itu?",
  ui_story_1022_10220201_8_dialog_content = "... Ehem!",
  ui_story_1022_10220201_9_dialog_content = "Kapten! Aku... Aku rasa aku baru saja mendengar suara batuk...",
  ui_story_1022_10220201_10_option_content = "Apa yang begitu aneh tentang itu?!",
  ui_story_1022_10220201_11_dialog_content = "Dia benar, tahu? Itu batuk yang benar-benar normal.",
  ui_story_1022_10220201_12_option_content = "Tidak, kamu pasti mendengarnya.",
  ui_story_1022_10220201_13_dialog_content = "Dia benar, tahu? Batuk sengaja seperti itu hanya bisa berarti bahwa seseorang mencoba mendapatkan perhatian kita.",
  ui_story_1022_10220201_14_dialog_content = "Sekarang, identifikasi dirimu! Apakah kamu bersama pasukan utama?",
  ui_story_1022_10220201_15_dialog_content = "Saya mengapresiasi ketenanganmu meski dalam situasi sekarang ini, Kapten Pepita.",
  ui_story_1022_10220201_16_dialog_content = "Untuk alasan itu, aku bersedia mengabaikan kata-katamu kali ini. Hanya saja, jangan biarkan itu terjadi lagi.",
  ui_story_1022_10220201_17_dialog_content = "C-C-Commander Hiiro dari Legiun ke-3!",
  ui_story_1022_10220201_18_dialog_content = "Ahh, begitu gelap dan tenang di sini! Tempat yang sempurna untuk tidur siang.",
  ui_story_1022_10220201_19_dialog_content = "D-Dan Intel Chief juga?!",
  ui_story_1022_10220201_20_dialog_content = "Aku... Aku akan menyeduh teh untuk semua orang!",
  ui_story_1022_10220201_21_dialog_content = "Tidak ada teh di sini! Lihat apa yang telah kalian lakukan? Kru saya ketakutan karena kalian!",
  ui_story_1022_10220201_22_dialog_content = "...",
  ui_story_1022_10220201_23_dialog_content = "Dan apa masalahmu, anak laki-laki yang batuk? Kenapa kamu bersembunyi jauh di sana? Takut peringkatmu tidak bisa bersaing dengan mereka?",
  ui_story_1022_10220201_24_dialog_content = "A-Aku bukan tentara, aku hanya Caelestite...",
  ui_story_1022_10220201_25_dialog_content = "Itu bahkan lebih buruk! Apa yang kamu lakukan mengikuti mereka di sekitar saat kamu bahkan tidak diperintahkan untuk melakukannya?!",
  ui_story_1022_10220201_26_dialog_content = "Itu tidak benar. Kita kebetulan sedang bekerja bersama untuk tujuan yang sama—",
  ui_story_1022_10220201_27_dialog_content = "Dan tujuan apa itu? Membuatmu menjadi anjing kecil mereka?",
  ui_story_1022_10220201_28_dialog_content = "K-Kenapa, kamu...!",
  ui_story_1022_10220201_29_dialog_content = "... Cukup, kalian berdua. Sudah cukup sulit bagi tim kita untuk berkumpul kembali, sekarang mari kita hanya bertukar informasi dan merencanakan langkah kita selanjutnya.",
  ui_story_1022_10220201_30_dialog_content = "Hmm... Jadi kalian sedang menuju bola raksasa Lumina ketika kalian bertemu dengan kami?",
  ui_story_1022_10220201_31_dialog_content = "Terasa sedikit terlalu mudah bagiku. Kamu yakin kamu tidak hanya sedang mengejekku?",
  ui_story_1022_10220201_32_dialog_content = "Mengapa kami harus berbohong tentang ini?",
  ui_story_1022_10220201_33_dialog_content = "Kalian adalah satu-satunya yang tahu jawaban atas itu. Mungkin kalian tidak bisa memberi tahu saya kebenaran sekarang? Atau mungkin kalian benar-benar menikmati lelucon...",
  ui_story_1022_10220201_34_dialog_content = "Lelucon? Apa gerangan yang kamu sedang bicarakan—",
  ui_story_1022_10220201_35_dialog_content = "Sudahlah serius, mau tidak?!",
  ui_story_1022_10220201_36_dialog_content = "PlayerName?",
  ui_story_1022_10220201_37_dialog_content = "Hiiro dan aku datang ke Zona Gelap untuk mencari seorang teman yang sangat penting.",
  ui_story_1022_10220201_38_dialog_content = "Kami menuju ke bola Lumina dengan harapan menemukannya, tetapi kami pulang dengan tangan hampa...",
  ui_story_1022_10220201_39_dialog_content = "Mengapa kami harus mengejekmu?!",
  ui_story_1022_10220201_40_dialog_content = "Temanmu...?!",
  ui_story_1022_10220201_41_dialog_content = "Dan jangan berani-berani mengatakan sesuatu seperti, \"Aku yakin kamu pasti kecewa hanya menemukanku,\" atau aku akan benar-benar marah!",
  ui_story_1022_10220201_42_dialog_content = "...",
  ui_story_1022_10220201_43_dialog_content = "...",
  ui_story_1022_10220201_44_dialog_content = "Hahahahaha!",
  ui_story_1022_10220201_45_dialog_content = "A-Apa yang kautertawakan...?",
  ui_story_1022_10220201_46_dialog_content = "Jadi kamu tidak marah sekarang? Tidak bohong, aku agak penasaran melihat bagaimana sikapmu ketika kamu \"benar-benar marah\"!",
  ui_story_1022_10220201_47_dialog_content = "Anda harus menjadi-",
  ui_story_1022_10220201_48_dialog_content = "Tapi sayangnya, itu harus menunggu. Saya tidak berencana mengatakan sesuatu seperti itu pada awalnya.",
  ui_story_1022_10220201_49_dialog_content = "Aku salah menilai kalian, jadi aku minta maaf karena sedikit terbawa suasana dengan kemarahanku. Salahku!",
  ui_story_1022_10220201_50_dialog_content = "S-Salah menilai...?",
  ui_story_1022_10220201_51_dialog_content = "Kamu adalah Illumina, jadi saya pikir kalian semua adalah sekelompok boneka bodoh yang mengikuti perintah untuk terjun ke Zona Gelap.",
  ui_story_1022_10220201_52_dialog_content = "Tapi ternyata... Kamu di sini untuk temanmu! Hahaha!",
  ui_story_1022_10220201_53_dialog_content = "Kamu benar-benar berani! Butuh orang yang sangat spesial untuk berani meledak di depan komandan 3rd Legion seperti itu.",
  ui_story_1022_10220201_54_dialog_content = "Aku menyukaimu!",
  ui_story_1022_10220201_55_dialog_content = "?!",
  ui_story_1022_10220201_56_dialog_content = "A-A-Apa artinya itu...?!",
  ui_story_1022_10220201_57_dialog_content = "Aku tidak berkedip saat aku berbohong atau bercanda, tapi kali ini berbeda.",
  ui_story_1022_10220201_58_dialog_content = "Siapa pun dengan penentuan diri sendiri baik-baik saja menurut saya!",
  ui_story_1022_10220201_59_dialog_content = "Saya cukup yakin semua orang memiliki itu...",
  ui_story_1022_10220201_60_dialog_content = "Baiklah, kita sudah cukup lama menyimpang dari topik.",
  ui_story_1022_10220201_61_dialog_content = "Pepita, sekarang saat kamu berbicara, mari kita dengar apa yang telah kamu temukan sejauh ini.",
  ui_story_1022_10220201_62_dialog_content = "Apakah kamu telah memastikan informasi baru sejak memasuki Dark Zone?",
  ui_story_1022_10220201_63_dialog_content = "Kemajuan kita, huh... Menjelajahi Zona Gelap tidak mudah, bahkan untuk seseorang yang seahli saya. Butuh banyak usaha untuk melakukan apa pun di sini, kamu tahu.",
  ui_story_1022_10220201_64_dialog_content = "Seperti saat kami mencoba mendirikan kamp dasar. Aku harus menggunakan poster buronan ini sebagai wallpaper!",
  ui_story_1022_10220201_65_dialog_content = "<color=#FFB400>POSTER</color> yang diinginkan.",
  ui_story_1022_10220201_66_dialog_content = "Poster buronan Anda? Saya tidak yakin saya cukup mengerti, haha...",
  ui_story_1022_10220201_67_dialog_content = "Hmm... Ini aneh... Tapi saya pernah bermimpi tentang dia beberapa waktu lalu...",
  ui_story_1022_10220201_68_dialog_content = "Gadis dalam mimpiku juga terasa sangat akrab.",
  ui_story_1022_10220201_69_dialog_content = "Tebak kamu memang Intel Chief di Illumina karena alasan tertentu, ya?",
  ui_story_1022_10220201_70_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_1022_10220201_71_dialog_content = "Turun, PlayerName!",
  ui_story_1022_10220201_72_dialog_content = "<color=#e8d9bb>Sebuah ledakan dahsyat mengguncang gua beku, dan tak terhitung tetesan es jatuh dari atas.</color>",
  ui_story_1022_10220201_73_dialog_content = "<color=#e8d9bb>Terlepas dari keributan mendadak, Pepita memberikan tawa yang riang.</color>",
  ui_story_1022_10220201_74_dialog_content = "Cari saja temanmu. Aku tidak akan menghalangimu, jadi ingatlah untuk tidak menghalangi jalanku!",
  ui_story_1022_10220201_75_dialog_content = "Meong! Aku tahu aku pernah melihatnya sebelumnya, tapi di mana?!",
  ui_story_1022_10220201_76_dialog_content = "Apa yang terjadi? Bagaimana gua es bisa runtuh begitu tiba-tiba? Di mana Pepita?",
  ui_story_1022_10220201_77_dialog_content = "... Dia kabur, kemungkinan besar.",
  ui_story_1022_10220201_78_dialog_content = "Lari? Tapi kenapa?!",
  ui_story_1022_10220201_79_dialog_content = "Meong! Sekarang aku ingat! Gadis itu adalah penjahat yang dicari!",
  ui_story_1022_10220201_80_dialog_content = "Seorang penjahat? Tetapi mengapa Illumina menempatkannya sebagai pemimpin tim penjelajah dan mengirimnya ke Zona Gelap?!",
  ui_story_1022_10220201_81_dialog_content = "Karena kami menangkapnya dan membuangnya ke penjara beberapa waktu lalu.",
  ui_story_1022_10220201_82_dialog_content = "Jadi, apakah kita mengatakan bahwa kita memiliki sesuatu padanya, sesuatu untuk memaksanya melayani kita? Dan kenapa dia, khususnya?",
  ui_story_1022_10220201_83_dialog_content = "Apa sebenarnya yang membuat Pepita masuk penjara, Philyshy?",
  ui_story_1022_10220201_84_dialog_content = "Sejujurnya, tidak tahu...",
  ui_story_1022_10220201_85_dialog_content = "Nemesis bertanggung jawab atas penyelidikan dan penangkapannya. Rupanya perintahnya langsung datang dari Komite.",
  ui_story_1022_10220201_86_dialog_content = "Pasti sudah serius, lalu.",
  ui_story_1022_10220201_87_dialog_content = "Eh... Bolehkah saya mengganggu sebentar saja?",
  ui_story_1022_10220201_88_dialog_content = "Masuk akal jika Pepita memilih untuk kabur jika dia benar-benar adalah seorang pidana yang dicari, tetapi mengapa dia memilih untuk melakukannya di tempat ini dari semua tempat?",
  ui_story_1022_10220201_89_dialog_content = "Sebelum kita menemukan satu sama lain, dia dan timnya beroperasi tanpa pengawasan. Kenapa dia tidak melarikan diri saat itu?",
  ui_story_1022_10220201_90_dialog_content = "Mengapa dia menunggu sampai Hiiro ada di sini? Ini hanya akan membuatnya lebih sulit untuk melarikan diri!",
  ui_story_1022_10220201_91_dialog_content = "Hmm…",
  ui_story_1022_10220201_92_dialog_content = "Apa itu ledakan tadi? Apakah kita sedang diserang? Apakah kapten telah memicu salah satu perangkap kita untuk Eclipsite?",
  ui_story_1022_10220201_93_dialog_content = "Hah? Ke mana Kapten pergi?!",
  ui_story_1022_10220201_94_dialog_content = "Meong? Kamu memiliki jebakan tersembunyi di sekitar sini?!",
  ui_story_1022_10220201_95_dialog_content = "Zona Gelap membuat kita bingung, membuatnya sulit untuk mengandalkan indera kita. Untuk melindungi kita, kapten menyiapkan serangkaian perangkap di sekitar setiap perimeter.",
  ui_story_1022_10220201_96_dialog_content = "Dan dia meningkatkan langkah-langkah penangkalannya bahkan lebih setelah kami menemukan tempat itu.",
  ui_story_1022_10220201_97_dialog_content = "Saya tahu kapten bisa sedikit kasar kadang-kadang, tapi sebenarnya dia sangat peduli pada kita... Heheheh...",
  ui_story_1022_10220201_98_dialog_content = "...",
  ui_story_1022_10220201_99_dialog_content = "Jadi dia menunggu sampai sekarang untuk melarikan diri...",
  ui_story_1022_10220201_100_dialog_content = "... hanya untuk meninggalkan rekan satu timnya dalam perawatan kami? Oh, Pepita!",
  ui_story_1022_10220201_101_dialog_content = "<color=#e8d9bb>Zona Gelap, Camp Dasar Lumopolis—</color>",
  ui_story_1022_10220201_102_dialog_content = "Pepita—itu nama target untuk operasi ini.",
  ui_story_1022_10220201_103_dialog_content = "Target kita sangat licik, dan dia akan melakukan apa saja untuk melarikan diri. Setiap orang harus tetap dalam kewaspadaan tinggi.",
  ui_story_1022_10220201_104_dialog_content = "Kita tidak boleh mengulangi kesalahan kita.",
  ui_story_1022_10220201_105_dialog_content = "Siap, Kapten!",
  ui_story_1022_10220201_106_dialog_content = "Maafkan aku... Aku tertipu karena kecerobohanku...",
  ui_story_1022_10220201_107_dialog_content = "Jangan menyalahkan diri sendiri untuk ini, Erica.",
  ui_story_1022_10220201_108_dialog_content = "Komite Illumina memiliki sejarah panjang dalam berurusan dengan dia. Sudah tak terhindarkan bahwa mereka akan membuat kesepakatan pertama.",
  ui_story_1022_10220201_109_dialog_content = "Tapi kali ini, kita yang memiliki inisiatif!",
  ui_story_1022_10220201_110_dialog_content = "Apakah Anda bisa menjelaskan lebih lanjut tentang rencana Anda?",
  ui_story_1022_10220201_111_dialog_content = "W-Wanita Carleen...!",
  ui_story_1022_10220202_1_dialog_content = "Ini adalah Gaze of the Abyss Anda. Silakan menikmati.",
  ui_story_1022_10220202_2_dialog_content = "Warna yang memikat, aroma berdosa, dan pola berputar di sepanjang... Saya mengerti. Ini pasti minuman terkutuk dari dewa yang jahat.",
  ui_story_1022_10220202_3_dialog_content = "Ahhh...! Manisnya meresap ke perutku dan sampai ke jiwaku! Minuman yang begitu setanis ini sungguh ilahi...",
  ui_story_1022_10220202_4_dialog_content = "Jika saya tidak menyelami kedalaman neraka, tidak ada orang lain yang akan melakukannya! Tuangkan lagi, pelayan!",
  ui_story_1022_10220202_5_dialog_content = "Hahahaha! Semua drama itu hanya karena minuman kecil, ya? Tidak bisa bilang aku tidak terhibur!",
  ui_story_1022_10220202_6_dialog_content = "Siapa itu? Makhluk rendahan mana yang berani mengejekku?",
  ui_story_1022_10220202_7_dialog_content = "Itu aku, tapi aku bukanlah makhluk rendahan. Selama ini aku telah mengawasimu, tahu.",
  ui_story_1022_10220202_8_dialog_content = "Jadi kamu suka minuman jenis ini, huh? Saya tahu beberapa minuman serupa, jika kamu mencari rekomendasi.",
  ui_story_1022_10220202_9_dialog_content = "Sebuah rekomendasi...? Saya kira saya bisa mengikuti siasat kecilmu untuk sekarang...",
  ui_story_1022_10220202_10_dialog_content = "Pastikan saja itu tidak mengandung alkohol. Terima kasih.",
  ui_story_1022_10220202_11_dialog_content = "Apa?",
  ui_story_1022_10220202_12_dialog_content = "<size=30>...Kenapa dia berperilaku seperti itu jika dia sama sekali tidak minum?</size>",
  ui_story_1022_10220202_13_dialog_content = "Anda tampak cukup akrab dengan menu ini... Apakah Anda pelanggan tetap di sini?",
  ui_story_1022_10220202_14_dialog_content = "Bisa dibilang begitu, tapi minuman bukanlah satu-satunya hal yang aku tahu. Bahaya, kegembiraan, penipuan, dan kesenangan semuanya ada di puncak menuku!",
  ui_story_1022_10220202_15_dialog_content = "Jadi kamu melihat dunia palsu ini hanya sebagai pilihan lezat yang bisa memanjakan lidahmu? Saya mengerti... Mungkin kamu juga memiliki potensi untuk berjuang melawan yang tidak diketahui...",
  ui_story_1022_10220202_16_dialog_content = "Sebuah toast untuk menikmati sifat dosa kita!",
  ui_story_1022_10220202_17_dialog_content = "Dengar, dengar!",
  ui_story_1022_10220202_18_dialog_content = "Ahhh... Minuman yang merangsang selera ini sungguh luar biasa. Rekomendasi Anda tidak bisa lebih sempurna, orang asing.",
  ui_story_1022_10220202_19_dialog_content = "Sudah kubilang, 'kan?",
  ui_story_1022_10220202_20_dialog_content = "Jadi mengapa kamu terus menerus memesan minuman seperti ini? Kamu tidak terlihat seperti orang yang selalu baik-baik saja.",
  ui_story_1022_10220202_21_dialog_content = "Kenyataannya adalah... Saya sedang bertugas aktif sekarang, yang berarti saya harus tetap waspada setiap saat...",
  ui_story_1022_10220202_22_dialog_content = "Wow, pekerjaanmu pasti sangat penting, ya?",
  ui_story_1022_10220202_23_dialog_content = "Kenapa, ya... Sebagai anggota Divisi Investigasi Heretics dari Lumopolis, pekerjaan mulia kami tidak bisa lebih penting lagi bagi dunia...",
  ui_story_1022_10220202_24_dialog_content = "Apa yang dilakukan Divisi Investigasi Heretics di Umbraton?!",
  ui_story_1022_10220202_25_dialog_content = "Kami sedang mengejar target yang sangat berbahaya. Umbraton adalah sarang kejahatan yang tidak memiliki hukum dan tidak bermoral, yang membuatnya tempat yang sempurna untuk dia bersembunyi.",
  ui_story_1022_10220202_26_dialog_content = "Pidana yang dimaksud mencuri sebuah buku berharga dari Lumopolis sebelum melarikan diri ke kota ini dan menyembunyikan gerak-geriknya...",
  ui_story_1022_10220202_27_dialog_content = "(Dia tidak mungkin berbicara tentang saya, kan...?)",
  ui_story_1022_10220202_28_dialog_content = "Tujuan kita adalah menangkap dia dan mengambil kembali kitab yang dicuri... Hmm? Tunggu, teman, kemana kamu pergi?",
  ui_story_1022_10220202_29_dialog_content = "Aku... Aku pikir aku minum terlalu banyak. Aku hanya akan menyegarkan diri di kamar mandi, sebentar lagi kembali!",
  ui_story_1022_10220202_30_dialog_content = "... Kutukan! Itu adalah kesempatan kita, tapi dia masih berhasil meloloskan diri!",
  ui_story_1022_10220202_31_dialog_content = "Orang asing yang baik dan bersemangat itu... Itu Pepita? Tapi bagaimana bisa...?",
  ui_story_1022_10220202_32_dialog_content = "Masih ada waktu! Kejar dia!",
  ui_story_1022_10220202_33_dialog_content = "Kita tidak bisa membiarkan Illumina mendapatkannya terlebih dahulu...",
  ui_story_1022_10220202_34_dialog_content = "(... Tempat persembunyian ini seharusnya cukup untuk saat ini.)",
  ui_story_1022_10220202_35_dialog_content = "(Sebuah pohon tersembunyi dengan baik di hutan, jadi untuk Aurorian seperti saya, pilihan terbaik saya adalah untuk bersembunyi...)",
  ui_story_1022_10220202_36_dialog_content = "(Di sebuah pemakaman!)",
  ui_story_1022_10220202_37_dialog_content = "(Tidak ada yang akan menduga saya bersembunyi di dalam peti mati dan berpura-pura mati! Mereka akan menggali lubang seumur hidup mereka mencari saya! Hahaha—)",
  ui_story_1022_10220202_38_dialog_content = "Cukup. Keluarlah dari peti mati, Pepita.",
  ui_story_1022_10220202_39_dialog_content = "Namun, itu sangat cocok denganmu.",
  ui_story_1022_10220202_40_dialog_content = "Pokoknya, tidakkah kamu memiliki rasa hormat terhadap orang mati?",
  ui_story_1022_10220202_41_dialog_content = "!!!",
  ui_story_1022_10220202_42_dialog_content = "(Apa yang membuatku ketahuan?! Ah, bajuku!)",
  ui_story_1022_10220202_43_dialog_content = "(Aku ceroboh. Bahkan orang mati pun tidak akan datang ke pemakamannya sendiri dengan mengenakan kain perca seperti ini...)",
  ui_story_1022_10220202_44_dialog_content = "(Ketika ini semua berakhir... Aku akan membeli beberapa pakaian baru yang bagus untuk diriku sendiri!)",
  ui_story_1022_10220202_45_dialog_content = "Apakah kamu berbicara tentang Pepita, pidana yang mencuri buku berharga dari Lumopolis?",
  ui_story_1022_10220202_46_dialog_content = "Ya, Lady. Namun, kitab yang dicuri hanyalah pemalsuan, jadi pencurian itu sendiri tidak terlalu jahat.",
  ui_story_1022_10220202_47_dialog_content = "Kekhawatiran kami adalah dia mengambil kitab palsu ini dan bergabung dengan True Order, organisasi paling keji dan sesat yang pernah menimpa Astra!",
  ui_story_1022_10220202_48_dialog_content = "... Jika buku yang dicuri itu palsu, lalu di mana yang asli?",
  ui_story_1022_10220202_49_dialog_content = "Di situlah masalahnya, Nyonya. Buku asli hilang bertahun-tahun yang lalu, tetapi penyelidikan kita sejauh ini menunjukkan—",
  ui_story_1022_10220202_50_dialog_content = "Mungkin itu juga telah jatuh ke tangan True Order!",
  ui_story_1022_10220202_51_dialog_content = "Saya mengerti sekarang. True Order selalu menjadi ancaman yang sulit ditangkap, anggotanya muncul dan menghilang seperti bisikan di malam hari.",
  ui_story_1022_10220202_52_dialog_content = "Jadi ketika Pepita muncul dan duduk untuk minum dengan Erica, kamu melihat peluang pada pencuri yang berisik dan sombong itu.",
  ui_story_1022_10220202_53_dialog_content = "Dan jadi kamu mencoba menggunakannya untuk melacak True Order dan merebut kembali kitab asli.",
  ui_story_1022_10220202_54_dialog_content = "Ya, Nyonya Carleen. Rencana kami saat itu persis seperti yang baru saja Anda deskripsikan.",
  ui_story_1022_10220202_55_dialog_content = "Namun, algojo terkutuk dari Komite Illumina selalu selangkah lebih maju dari kami. Setelah menjepit Pepita, mereka membawanya kembali ke Federasi...",
  ui_story_1022_10220202_56_dialog_content = "Sekarang kamu sebutkan itu, Pepita tampaknya telah dikirim ke Zona Gelap berdasarkan perintah Illumina. Tidak akan mudah bagi kita untuk menangkapnya pada saat ini.",
  ui_story_1022_10220202_57_dialog_content = "Mungkin, tapi tenanglah, Lady Carleen.",
  ui_story_1022_10220202_58_dialog_content = "Untuk operasi ini, Divisi Investigasi Heretics sudah mendapatkan izin dari Tuan Kota, serta dari Grand Marshal sendiri.",
  ui_story_1022_10220202_59_dialog_content = "Setelah bertemu satu sama lain, para pemimpin kami mengizinkan pengejaran kami terhadap pidana yang dikenal sebagai Pepita, sehingga kami akhirnya dapat membawanya ke pengadilan seperti yang kami rencanakan sebelumnya.",
  ui_story_1022_10220202_60_dialog_content = "Kita tidak akan membiarkan dia melarikan diri kali ini!",
  ui_story_1022_10220202_61_dialog_content = "... Meski begitu, kami saat ini sedang bekerja sama dengan tim ekspedisi Zona Gelap dari Illumina.",
  ui_story_1022_10220202_62_dialog_content = "Mereka bertemu dengan Pepita tidak lama yang lalu.",
  ui_story_1022_10220301_1_dialog_content = "Di sini, Carleen! Kalian sampai di sini dengan cepat!",
  ui_story_1022_10220301_2_dialog_content = "Tentu saja. Ketika salah satu harta berharga terpenting Lumopolis dipertaruhkan, tidak ada waktu untuk disia-siakan.",
  ui_story_1022_10220301_3_dialog_content = "Apa masalahnya? Apakah kamu kelelahan setelah pertemuan pertamamu dengan pencuri itu?",
  ui_story_1022_10220301_4_dialog_content = "Y-Yah, aku akan berbohong jika aku bilang aku tidak gugup dengan itu...",
  ui_story_1022_10220301_5_dialog_content = "Tapi jangan meremehkan saya! Dia tidak mungkin pergi jauh, jadi saya akan menggunakan kekuatan saya untuk menemukannya!",
  ui_story_1022_10220301_6_dialog_content = "...",
  ui_story_1022_10220301_7_dialog_content = "Philyshy membawa rekan-rekan tim Pepita kembali dengan pesawat, tetapi Hiiro dan saya tetap bersama kamu.",
  ui_story_1022_10220301_8_dialog_content = "Karena dia ditugaskan untuk menjelajahi Dark Zone di bawah perintah Illumina, saya memiliki kewajiban untuk menemukannya dan mendapatkan informasi apa pun yang telah dia kumpulkan.",
  ui_story_1022_10220301_9_dialog_content = "Maafkan aku, tapi aku khawatir dia akan kembali bersama kita.",
  ui_story_1022_10220301_10_dialog_content = "Dan Anda?",
  ui_story_1022_10220301_11_dialog_content = "Kapten Divisi Investigasi Heretics di Lumopolis. Izinkan saya menjelaskan situasi kita—",
  ui_story_1022_10220301_12_dialog_content = "...Grand Marshal mengizinkan operasi Lumopolis untuk menangkap Pepita?",
  ui_story_1022_10220301_13_dialog_content = "Mengerti. Kamu boleh membawanya ke dalam tahananmu, tetapi hanya setelah aku bertanya beberapa pertanyaan padanya.",
  ui_story_1022_10220301_14_dialog_content = "Kapten begitu bersemangat saat pertama kali menemukan tempat itu, tapi kemudian dia hampir langsung menarik kami keluar dari sana, seolah-olah dia tiba-tiba sangat khawatir dengan keselamatan kami.",
  ui_story_1022_10220301_15_dialog_content = "Sesuatu memberitahuku bahwa apa yang kita lihat di sana tidak sepenuhnya asing baginya...",
  ui_story_1022_10220301_16_dialog_content = "Pepita jelas pasti telah menemukan sesuatu.",
  ui_story_1022_10220301_17_dialog_content = "Hmph, kalian prajurit Illumina tidak pernah berubah! Kalian sudah pernah membawanya pergi dari kami sebelumnya, dan sekarang kalian mengancam untuk melakukannya lagi!",
  ui_story_1022_10220301_18_dialog_content = "Seperti yang saya katakan, kamu dipersilakan untuk membawanya—",
  ui_story_1022_10220301_19_dialog_content = "Aku tidak ingat memberi kalian izin untuk memperlakukanku seperti piring steak yang dilewatkan di sekitar meja!",
  ui_story_1022_10220301_20_dialog_content = "Pepita!",
  ui_story_1022_10220301_21_dialog_content = "Jadi, Anda akhirnya memutuskan untuk menyerahkan diri!",
  ui_story_1022_10220301_22_dialog_content = "Teman saya! Tidak, tunggu... Aku tidak bisa membiarkan diriku tertipu lagi...",
  ui_story_1022_10220301_23_dialog_content = "Siapa bilang saya menipu kamu? Keseruan yang kita alami saat minum bersama itu nyata, dan begitu juga emosimu.",
  ui_story_1022_10220301_24_dialog_content = "Jadi, kuatkan tekadmu dan hadapi aku dalam pertempuran nyata, Erica!",
  ui_story_1022_10220301_25_dialog_content = "Emosiku... Sebuah kenyataan dalam dunia yang palsu...",
  ui_story_1022_10220301_26_dialog_content = "Kamu tidak akan bisa menipunya untuk kedua kalinya, Pepita!",
  ui_story_1022_10220301_27_dialog_content = "(Cepat sekali!)",
  ui_story_1022_10220301_28_dialog_content = "Kau tidak akan bisa kabur!",
  ui_story_1022_10220301_29_dialog_content = "Kelopak Ephemeral Menutupi Abu!",
  ui_story_1022_10220301_30_dialog_content = "<color=#e8d9bb>Gelombang demi gelombang serangan terbang menuju Pepita, yang entah menangkisnya dengan penuh keceriaan atau menghindarinya dengan agilitas tanpa usaha.</color>",
  ui_story_1022_10220301_31_dialog_content = "<color=#e8d9bb>Meskipun peluangnya sangat kecil, dia tampaknya hampir tidak dirugikan.</color>",
  ui_story_1022_10220301_32_dialog_content = "Apakah dia tidak terpengaruh oleh pengaruh Zona Gelap?!",
  ui_story_1022_10220301_33_dialog_content = "Aku tahu ada sesuatu yang berbeda tentang dia...",
  ui_story_1022_10220301_34_dialog_content = "(Aurorian normal merasa tertekan saat mereka bergerak di sekitar Dark Zone, tetapi Pepita tampaknya sama sekali tidak terpengaruh...)",
  ui_story_1022_10220301_35_dialog_content = "Hahahaha! Sepertinya kamu mulai mengerti betapa kuatnya aku!",
  ui_story_1022_10220301_36_dialog_content = "Sayangnya untukmu, tutorialnya sudah selesai! Sekarang saatnya bagi saya untuk benar-benar melepaskan diri!",
  ui_story_1022_10220301_37_dialog_content = "Baiklah, Petey—Tunjukkan kepada mereka apa yang kamu punya!",
  ui_story_1022_10220301_38_dialog_content = "Kekuatan ini...!",
  ui_story_1022_10220301_39_dialog_content = "Apa yang terjadi?! Makin sulit untuk bernapas...",
  ui_story_1022_10220301_40_dialog_content = "Darkflow semakin tebal...",
  ui_story_1022_10220301_41_dialog_content = "(Tidak ada keraguan tentang itu... Boneka di tangan Pepita memancarkan energi yang sama dengan Eclipsite! Tapi bagaimana?!)",
  ui_story_1022_10220301_42_dialog_content = "Lebih besar, lebih besar! Jadikan dirimu sebesar yang kamu bisa!",
  ui_story_1022_10220301_43_dialog_content = "<color=#e8d9bb>Pepita tertawa terbahak-bahak saat boneka anehnya terus tumbuh tanpa kontrol. Setelah beberapa saat, boneka itu mulai meluncurkan serangkaian serangan eksplosif dari tubuhnya yang membengkak.</color>",
  ui_story_1022_10220301_44_dialog_content = "<color=#e8d9bb>Bahkan bayangannya tampaknya terdiri dari substansi yang tidak dikenal, memeras pikiran dan tubuh siapa saja yang terjebak di perbatasannya.</color>",
  ui_story_1022_10220301_45_dialog_content = "Orang-orangku tidak akan bertahan lebih lama lagi dengan keadaan seperti ini...!",
  ui_story_1022_10220301_46_dialog_content = "Kapan dia mendapatkan boneka aneh seperti itu?!",
  ui_story_1022_10220301_47_dialog_content = "Namanya Petey, untuk informasimu. Dia adalah <color=#FFB400>familiar</color> ku, jadi tentu saja dia harus sedikit ajaib!",
  ui_story_1022_10220301_48_dialog_content = "Aku bahkan akan membiarkanmu bermain dengannya, karena aku sangat baik! Nikmati waktu bersama, setiap orang—",
  ui_story_1022_10220301_49_dialog_content = "Karena itu tidak akan bertahan lama.",
  ui_story_1022_10220301_50_dialog_content = "…!",
  ui_story_1022_10220301_51_dialog_content = "Apa... Apa itu?",
  ui_story_1022_10220301_52_dialog_content = "Ada apa, PlayerName? Kenapa kamu melihat sekeliling seperti itu?",
  ui_story_1022_10220301_53_dialog_content = "<color=#e8d9bb>Dia di sini.</color>",
  ui_story_1022_10220301_54_dialog_content = "Ada yang datang ke arah kita... Sesuatu dengan jumlah Darkflow yang sangat besar... M-Minggir, semua orang!",
  ui_story_1022_10220301_55_dialog_content = "<color=#e8d9bb>Tiba-tiba, sebuah tetesan air mata raksasa jatuh dari langit. Saat setiap orang berusaha untuk mundur, warna putih susunya terpantul di mata mereka yang ketakutan.</color>",
  ui_story_1022_10220301_56_dialog_content = "<color=#e8d9bb>Tetesan air mata jatuh ke tanah...</color>",
  ui_story_1022_10220301_57_dialog_content = "<color=#e8d9bb>Dan ledakan dahsyat mengguncang seluruh medan perang.</color>",
  ui_story_1022_10220301_58_dialog_content = "Siapa yang mengolok-olok temanku?",
  ui_story_1022_10220301_59_dialog_content = "<color=#FFB400>Ursura</color>! Aku tahu kamu akan datang!",
  ui_story_1022_10220301_60_dialog_content = "<color=#e8d9bb>Ketika debu mulai mereda, sosok muncul di tengah ledakan, kehadirannya saja membuat udara di paru-paru semua orang terhenti.</color>",
  ui_story_1022_10220301_61_dialog_content = "Panjang gelombang ini... Itu adalah <color=#FFB400>Hantu</color>!",
  ui_story_1022_10220301_62_dialog_content = "Pepita, penjahat! Kamu bersekongkol tidak hanya dengan True Order, tapi juga dengan Eclipsite?!",
  ui_story_1022_10220301_63_dialog_content = "Aku tidak bisa melihat penampilannya. Seolah-olah dia berdiri di dalam kabut tebal...",
  ui_story_1022_10220301_64_dialog_content = "\"Bersekongkol\"? Apa artinya itu?! Pepita dan saya telah menjadi teman selama ini! Jika ada yang bersekongkol, itu adalah kalian semua!",
  ui_story_1022_10220301_65_dialog_content = "?!!",
  ui_story_1022_10220301_66_dialog_content = "Hahahaha, kamu harus melihat ekspresi di wajahmu! Ahh, itu saja sudah cukup menggantikan semua masalah yang telah aku hadapi sejak aku muncul kembali.",
  ui_story_1022_10220301_67_dialog_content = "... Kamu tahu kami akhirnya akan menarik Wraith ke arah kami, bukan?",
  ui_story_1022_10220301_68_dialog_content = "Yah, tentu saja! Kamu pikir aku cukup bodoh untuk berkelahi dengan kalian tanpa seseorang seperti Ursura yang mendukungku? Ayo, beri aku sedikit kredit!",
  ui_story_1022_10220301_69_dialog_content = "Beritahu aku, bagaimana rasanya tertipu oleh trikku lagi, Tuan Caelestite?",
  ui_story_1022_10220301_70_dialog_content = "Argh...!",
  ui_story_1022_10220301_71_dialog_content = "Bagaimana keadaan Petey kecil, Pepita? Saya merasakan kehadirannya baru saja, jadi saya datang untuk memeriksa kamu. Lihat betapa baiknya saya, 'kan?",
  ui_story_1022_10220301_72_dialog_content = "Dia ada di sini, lihat? Tunggu... Kamu tidak akan membawanya kembali, kan? Kami sudah menjadi teman baik sekarang, tahu!",
  ui_story_1022_10220301_73_dialog_content = "(Apakah saya mendengar ini dengan benar? Kenapa terdengar seperti mereka benar-benar berteman...?)",
  ui_story_1022_10220301_74_dialog_content = "Jangan menganggap dirimu aman hanya karena seorang Hantu telah datang menyelamatkanmu, Pepita.",
  ui_story_1022_10220301_75_dialog_content = "Kamu masih harus bertanggung jawab atas pencurian buku sakral dari Lumopolis!",
  ui_story_1022_10220301_76_dialog_content = "Mencuri? Buku itu sejak awal milik True Order, terima kasih banyak.",
  ui_story_1022_10220301_77_dialog_content = "Apa?!",
  ui_story_1022_10220301_78_dialog_content = "Ini benar, yang berarti saya tidak pernah mencuri apa pun dari Lumopolis untuk memulai.",
  ui_story_1022_10220301_79_dialog_content = "Dan tentang Illumina, bisa dibilang kalian beruntung saya bersedia untuk membiarkan segalanya berlalu.",
  ui_story_1022_10220301_80_dialog_content = "Itu bukan berarti kamu tidak berutang apa-apa padaku, lho! Lagi pula, tidak ada yang gratis, kan!",
  ui_story_1022_10220301_81_dialog_content = "...",
  ui_story_1022_10220301_82_dialog_content = "Si nenek tua Belisaria berpikir dia bisa menggunakan \"hatiku\" untuk mengendalikanku, tapi dia salah. Sangat salah.",
  ui_story_1022_10220301_83_dialog_content = "Yang Hebat Pepita tidak melayani siapa pun! Hahahaha!",
  ui_story_1022_10220301_84_dialog_content = "Mari kita pergi dari sini, Ursura.",
  ui_story_1022_10220301_85_dialog_content = "Ayo menjadi gila sepanjang malam!",
  ui_story_1022_10220301_86_dialog_content = "Pepita...",
  ui_story_1022_10220301_87_dialog_content = "Berhenti sekarang juga!",
  ui_story_1022_10220301_88_dialog_content = "Argh... Kamu semua benar-benar menjengkelkan! Mati saja!!!",
  ui_story_1022_10220301_89_dialog_content = "Grahhhh—!!",
  ui_story_1022_10220301_90_dialog_content = "Awas!",
  ui_story_1022_10220302_1_dialog_content = "(Pergi, Petey. Beritahu Lady Victoria di mana aku sekarang.)",
  ui_story_1022_10220302_2_dialog_content = "Kenapa kamu masih berdiri di sana, Pepita? Aku pikir kamu bilang kita akan bersenang-senang!",
  ui_story_1022_10220302_3_dialog_content = "Datang, datang!",
  ui_story_1022_10220302_4_dialog_content = "Bwahaha, apakah kamu melihat wajah mereka barusan? Mereka sangat marah meskipun aku telah mengalahkan mereka dengan sangat buruk!",
  ui_story_1022_10220302_5_dialog_content = "Ya, kamu memang melakukannya! Aku hanya berharap kamu ada di sana untuk melihat bagaimana aku meledakkan mereka semua dengan jebakanku sebelumnya. Mereka sama sekali tidak menduganya!",
  ui_story_1022_10220302_6_dialog_content = "Ahh, itu adalah pemandangan yang luar biasa!",
  ui_story_1022_10220302_7_dialog_content = "*Merintih* D-Dan kamu tidak mengundangku? Itu tidak adil, Pepita!",
  ui_story_1022_10220302_8_dialog_content = "Kau berutang padaku sekarang! Kita akan menjadi lebih gila dari sebelumnya, kau dengar aku?!",
  ui_story_1022_10220302_9_dialog_content = "Aku tahu, jadi berhentilah menangis. Momen indah tak pernah berhenti saat kita bersama, ingat?",
  ui_story_1022_10220302_10_dialog_content = "(Eclipsian) Ada objek kecil yang bergerak jauh di kejauhan. Sepertinya sedang melarikan diri.",
  ui_story_1022_10220302_11_dialog_content = "(Eclipsian) Ah—Itu adalah familiar yang diberikan kepada Aurorian itu oleh Lady Ursura!",
  ui_story_1022_10220302_12_dialog_content = "(Eclipsian) Masalah apa yang dia buat sekarang? Aurorian terlalu licik untuk dipercaya, itu sudah diketahui.",
  ui_story_1022_10220302_13_dialog_content = "(Eclipsian) Haruskah kita membiarkan mereka pergi?",
  ui_story_1022_10220302_14_dialog_content = "(Eclipsian) Tidak, kamu bodoh! Kita harus menangkap familiar itu dan mengembalikannya ke Lady Ursura!",
  ui_story_1022_10220302_15_dialog_content = "(Eclipsian) Mengerti!",
  ui_story_1022_10220302_16_dialog_content = "Kutuk semuanya!!!",
  ui_story_1022_10220302_17_dialog_content = "Kita sudah sepenuhnya mengepungnya... Dan namun dia berhasil lolos dari genggaman kita lagi!",
  ui_story_1022_10220302_18_dialog_content = "Jangan terlalu keras pada diri sendiri. Tak satu pun dari kita yang tahu bahwa Pepita bisa memanggil Hantu untuk membantunya.",
  ui_story_1022_10220302_19_dialog_content = "Sebaliknya, kecurigaan saya telah sepenuhnya terbukti.",
  ui_story_1022_10220302_20_dialog_content = "Wraith itu memiliki sesuatu yang mirip dengan karang tumbuh dari tubuhnya...",
  ui_story_1022_10220302_21_dialog_content = "Setelah dia menemukan \"tempat itu,\" dia tahu bahwa ada Hantu di dekatnya. Pada titik itu, dia memutuskan untuk menggunakan Hantu sebagai sarana untuk melarikan diri dan menyerahkan dirinya kepada itu.",
  ui_story_1022_10220302_22_dialog_content = "Menyerahkan dirinya... Kepada Wraith? Tapi apa yang bisa Wraith tawarkan kepadanya?",
  ui_story_1022_10220302_23_dialog_content = "Yang dibuktikannya hanyalah dia telah jatuh melampaui keselamatan! Jangan biarkan dia menggoyahkanmu dengan kata-katanya lagi, Erica!",
  ui_story_1022_10220302_24_dialog_content = "...",
  ui_story_1022_10220302_25_dialog_content = "Tidak ada orang lain yang merasa ini aneh?",
  ui_story_1022_10220302_26_dialog_content = "Apa maksudmu, Carleen?",
  ui_story_1022_10220302_27_dialog_content = "Hantu itu, Ursura—Dia jelas musuh yang sangat kuat, dan namun dia tampaknya tidak terlalu tertarik untuk melawan kami.",
  ui_story_1022_10220302_28_dialog_content = "Kedua kali dia menyerang, itu adalah untuk melindungi Pepita.",
  ui_story_1022_10220302_29_option_content = "C-Bisakah ini adalah kekuatan persahabatan?!",
  ui_story_1022_10220302_30_dialog_content = "... Ini bukan saat yang tepat untuk bercanda.",
  ui_story_1022_10220302_31_dialog_content = "Maaf!",
  ui_story_1022_10220302_32_option_content = "Tapi lelucon samping, mereka tampaknya memang berteman satu sama lain.",
  ui_story_1022_10220302_33_dialog_content = "Pepita yakin bahwa Ursura akan datang menyelamatkannya, itulah satu-satunya alasan dia menampakkan diri di depan kami.",
  ui_story_1022_10220302_34_dialog_content = "Persahabatan antara Hantu dan Aurorian... Apakah itu benar-benar mungkin?",
  ui_story_1022_10220302_35_dialog_content = "Saya setuju: perilaku Ursura sama sekali tidak normal.",
  ui_story_1022_10220302_36_dialog_content = "Dia tidak memiliki permusuhan terhadap kita, dan hanya tertarik untuk membantu Pepita... Tapi kenapa? Apakah mereka merencanakan sesuatu yang lain?",
  ui_story_1022_10220302_37_dialog_content = "Mungkin keduanya hanya tertarik untuk bersenang-senang bersama?",
  ui_story_1022_10220302_38_dialog_content = "...",
  ui_story_1022_10220302_39_dialog_content = "Jangan tidak masuk akal!",
  ui_story_1022_10220302_40_dialog_content = "Sekarang ambil Batu Lumina-mu dan bersiaplah untuk berangkat, Erica!",
  ui_story_1022_10220302_41_dialog_content = "Apa? Kalian serius mengejar Pepita?!",
  ui_story_1022_10220302_42_dialog_content = "Tentu saja kami akan, dan tidak ada Hantu yang akan menghentikan kita untuk menyelesaikan misi kita! Sekarang, jangan menghalangi jalan kami!",
  ui_story_1022_10220302_43_dialog_content = "Kami tidak punya pilihan. Pepita memiliki informasi yang bisa membawa kita ke kitab Lumopolis yang dicuri.",
  ui_story_1022_10220302_44_dialog_content = "... Setelah kita menemukannya, kita bisa bertanya apa saja yang kita inginkan.",
  ui_story_1022_10220302_45_dialog_content = "(Sepertinya Carleen sedang memberi petunjuk tentang True Order, dan kemungkinan buku yang dicuri itu sebenarnya milik mereka...)",
  ui_story_1022_10220302_46_dialog_content = "(Dia menyebutkan sebelumnya bahwa Pepita adalah anggota dari True Order.)",
  ui_story_1022_10220302_47_dialog_content = "(Tapi jika itu masalahnya, mengapa dia ditawan oleh Illumina? Dan mengapa terdengar seperti dia memiliki hutang yang harus ditagih dari mereka?)",
  ui_story_1022_10220302_48_dialog_content = "(Ada terlalu banyak hal yang kita tidak tahu saat ini...)",
  ui_story_1022_10220401_1_dialog_content = "Selamat datang di Tundra Karang!",
  ui_story_1022_10220401_2_dialog_content = "Indah, bukan? Saya yakin kamu belum pernah melihat sesuatu yang seaneh ini! Silakan, berteriak dan berteriak sepuasnya!",
  ui_story_1022_10220401_3_dialog_content = "Sangat indah dengan cara yang aneh dan terpelintir. Saya bisa melihat mengapa kamu sangat menyukai tempat ini.",
  ui_story_1022_10220401_4_dialog_content = "Apa masalahnya? Bukankah tempat ini membuatmu bersemangat? Ayo, tunjukkan sedikit emosi!",
  ui_story_1022_10220401_5_dialog_content = "Aku serius, Ursura. Tempat ini begitu indah dan unik hingga membuatku terkejut.",
  ui_story_1022_10220401_6_dialog_content = "(Atau setidaknya itu yang terjadi saat pertama kali aku melihatnya.)",
  ui_story_1022_10220401_7_dialog_content = "Cukup baik untukku, sepertinya. Ayo, banyak kesenangan yang bisa didapatkan di sini!",
  ui_story_1022_10220401_8_dialog_content = "Harusnya begitu! Kamu sudah membuatku sangat bersemangat tentang tempat ini, jadi jangan mengecewakanku!",
  ui_story_1022_10220401_9_dialog_content = "<color=#e8d9bb>Yang seharusnya menjadi ladang es yang pucat dan sunyi, malah menjadi lanskap yang penuh dengan lumut, karang, dan pohon berwarna-warni, seperti adegan yang diambil langsung dari dongeng gelap.</color>",
  ui_story_1022_10220401_10_dialog_content = "<color=#e8d9bb>Dan di sana, bergerak di antara karang-karang—</color>",
  ui_story_1022_10220401_11_dialog_content = "?!",
  ui_story_1022_10220401_12_dialog_content = "(Apakah itu... Aurorian? Tidak, mata mereka yang tumpul dan tak bersemangat lebih mirip dengan mata Eclipsite, tetapi mereka tidak tampak sama sekali.)",
  ui_story_1022_10220401_13_dialog_content = "<color=#e8d9bb>Makhluk tanpa jiwa yang mirip Aurorian bergerak secara mekanis di antara terumbu karang, menggosok lumut berlebihan dari permukaan mereka.</color>",
  ui_story_1022_10220401_14_dialog_content = "<color=#e8d9bb>Melawan latar belakang pohon dan karang yang megah, gerakan kaku mereka tampak semakin menyeramkan.</color>",
  ui_story_1022_10220401_15_dialog_content = "Hei Ursura, apa itu...?",
  ui_story_1022_10220401_16_dialog_content = "Kamu benar-benar tidak tahu apa itu? Itu terumbu karang, bodoh!",
  ui_story_1022_10220401_17_dialog_content = "Tidak, saya maksud orang-orang yang berjalan di sekitar mereka... Apakah mereka Aurorian atau Eclipsite? Atau mungkin sesuatu yang sepenuhnya berbeda?",
  ui_story_1022_10220401_18_dialog_content = "Oh... Mengapa kamu membuang waktu untuk melihat mereka? Tak ada gunanya, tahu.",
  ui_story_1022_10220401_19_dialog_content = "Saya akan memberitahu Anda sekarang juga, mereka pasti tidak mewarisi apa pun yang membuat Aurorian menyenangkan untuk bermain.",
  ui_story_1022_10220401_20_dialog_content = "(\"Mewarisi\"? Dengan kata lain... Mereka somehow terhubung dengan Aurorian.)",
  ui_story_1022_10220401_21_dialog_content = "Setelah menghabiskan begitu banyak waktu di sini, orang-orang itu telah menjadi jauh lebih tahan lama. Itulah sebabnya <color=#FFB400>kami</color> menggunakan mereka untuk tugas-tugas sederhana seperti pembersihan.",
  ui_story_1022_10220401_22_dialog_content = "Mereka cukup baik mendengar ketika kita memberi mereka tugas, tetapi selain itu mereka benar-benar tidak berguna.",
  ui_story_1022_10220401_23_dialog_content = "Mereka sangat buruk dalam percakapan, tidak tahu cara bersenang-senang, dan terlalu mudah mati. Mereka tidak bisa dibandingkan dengan Aurorian, tahu!",
  ui_story_1022_10220401_24_dialog_content = "(Mereka tidak memiliki cara untuk berkomunikasi atau melawan... Apakah itu yang dia coba katakan?)",
  ui_story_1022_10220401_25_dialog_content = "Ah, tapi jangan khawatir tentang mereka! Aku yang mengendalikan tempat ini, sekarang ikuti aku!",
  ui_story_1022_10220401_26_dialog_content = "...",
  ui_story_1022_10220402_1_dialog_content = "Fiuh... Kami akhirnya selesai dengan percobaan hari ini.",
  ui_story_1022_10220402_2_dialog_content = "Apakah hanya saya yang merasa tes-tes belakangan ini semakin sulit?",
  ui_story_1022_10220402_3_dialog_content = "Tidak, kamu benar... Sejujurnya, aku tidak tahu berapa banyak lagi yang bisa aku tahan.",
  ui_story_1022_10220402_4_dialog_content = "Sekujur tubuhku sakit luar biasa, dan saya terus mengalami mimpi buruk setiap malam...",
  ui_story_1022_10220402_5_dialog_content = "Sama disini...",
  ui_story_1022_10220402_6_dialog_content = "Pepita tampaknya masih bisa bertahan dengan baik meskipun! Bahkan dengan hati yang lemah dan tes terburuk dari kita semua, tidak ada yang tampaknya memperlambatmu!",
  ui_story_1022_10220402_7_dialog_content = "Ahh, ini bukan apa-apa bagiku!",
  ui_story_1022_10220402_8_dialog_content = "Dibandingkan dengan bahaya yang dihadapi ayahku, ini hanyalah berjalan-jalan di taman!",
  ui_story_1022_10220402_9_dialog_content = "Oh ya... Ayahmu pernah menjelajah Zona Gelap, bukan Pepita?",
  ui_story_1022_10220402_10_dialog_content = "Yup! Dia adalah bagian dari Tim Eksplorasi Zona Gelap Illumina, jadi dia melakukan segala macam hal luar biasa di sana!",
  ui_story_1022_10220402_11_dialog_content = "Itulah sebabnya saya juga ingin menjelajahi Zona Gelap. Saya yakin dia akan sangat bangga padaku! Hahaha!",
  ui_story_1022_10220402_12_dialog_content = "Itulah semangat, Pepita! Kami akan mendukungmu sepanjang jalan!",
  ui_story_1022_10220402_13_dialog_content = "Tapi tunggu, bukankah itu berarti kamu tidak akan bisa melihatnya saat kunjungan kita berikutnya?",
  ui_story_1022_10220402_14_dialog_content = "... I-Ini tidak bisa dihindari. Dia memang orang yang sangat sibuk, setelah semua...",
  ui_story_1022_10220402_15_dialog_content = "Tidak apa-apa! Jika ada sesuatu yang kamu inginkan, cukup beri tahu saya dan saya akan minta ibu saya membawakannya untuk kamu!",
  ui_story_1022_10220402_16_dialog_content = "O-Oke... Terima kasih.",
  ui_story_1022_10220402_17_dialog_content = "Ayahku akan datang untuk melihatku begitu dia kembali... Aku yakin akan hal itu.",
  ui_story_1022_10220402_18_dialog_content = "<color=#e8d9bb>Beberapa tahun kemudian-</color>",
  ui_story_1022_10220402_19_dialog_content = "Bagaimana keadaannya akhir-akhir ini?",
  ui_story_1022_10220402_20_dialog_content = "Seperti biasa, Ma'am. Dia membuang makanan apa pun yang tidak disukainya, dan meminta porsi ganda dari hal-hal yang dia suka—",
  ui_story_1022_10220402_21_dialog_content = "Dia terus berteriak pada kami untuk memainkan musik, dan mulai bernyanyi sekeras-kerasnya jika kami mengabaikannya...",
  ui_story_1022_10220402_22_dialog_content = "Dia sudah di sini cukup lama untuk semua kalian mengenal kesukaannya. Jika dia menolak untuk makan sesuatu, maka jangan sajikan itu kepadanya.",
  ui_story_1022_10220402_23_dialog_content = "... Y-Ya, Bu!",
  ui_story_1022_10220402_24_dialog_content = "Tidakkah menurutmu kau sedikit terlalu memanjakannya? Lagi pula, dia hanyalah seorang tahanan.",
  ui_story_1022_10220402_25_dialog_content = "Dia dan hatinya adalah spesimen yang tak ternilai harganya. Kita memiliki lebih banyak yang bisa hilang daripada orang lain jika dia menyerah pada malnutrisi.",
  ui_story_1022_10220402_26_dialog_content = "Dan selain itu, membuang-buang makanan tidak pernah menjadi hal yang baik.",
  ui_story_1022_10220402_27_dialog_content = "... Maka mari kita harap dia mau bekerja sama denganmu.",
  ui_story_1022_10220402_28_dialog_content = "Hei, apa yang terjadi di luar sana? Apakah kamu mendapatkan rekamanku, atau harus aku terus bernyanyi? Jangan bilang kamu mulai menyukai suaraku atau semacamnya!",
  ui_story_1022_10220402_29_dialog_content = "Saya rasa saya tidak boleh mengecewakan penggemar saya, jadi mari kita mulai! Ahem! Bawa aku pulaaaaang, ke ladang yang hijaaaaau♪",
  ui_story_1022_10220402_30_dialog_content = "Anda belum pernah melihat lapangan hijau seumur hidup Anda, Pepita.",
  ui_story_1022_10220402_31_dialog_content = "Aduh, kamu lagi. Aku muak melihat wajahmu yang tua dan jelek, pergi sana.",
  ui_story_1022_10220402_32_dialog_content = "Begitu kah? Aku ingat betapa bersemangatnya kamu setiap kali aku mengunjungi kamu di laboratorium.",
  ui_story_1022_10220402_33_dialog_content = "Dan itu karena aku adalah satu-satunya orang yang pernah datang menemuimu.",
  ui_story_1022_10220402_34_dialog_content = "Kamu tidak ada di sana untuk menemuiku. Kamu hanya datang untuk melihat bagaimana keadaan subjek uji coba yang sangat kamu hargai.",
  ui_story_1022_10220402_35_dialog_content = "Nilai dari subjek tes adalah konkret dan dapat diukur.",
  ui_story_1022_10220402_36_dialog_content = "Namun, hal-hal seperti emosi, dan bahkan ikatan keluarga, terlalu samar untuk diandalkan. Bahkan, mereka seringkali menyesatkan orang.",
  ui_story_1022_10220402_37_dialog_content = "Kamu, dari semua orang, seharusnya tahu itu.",
  ui_story_1022_10220402_38_dialog_content = "...",
  ui_story_1022_10220402_39_dialog_content = "Jika Anda benar-benar membenci kepura-puraan sebanyak yang Anda katakan, maka daripada mengeluarkan semua omong kosong pemberontakan ini—",
  ui_story_1022_10220402_40_dialog_content = "Kamu harus melihat kehadiranku di sini dalam cahaya yang lebih positif... Subjek tesku yang berharga.",
  ui_story_1022_10220402_41_dialog_content = "Datanglah ke sini, Ulysses.",
  ui_story_1022_10220402_42_dialog_content = "...",
  ui_story_1022_10220402_43_dialog_content = "Hah?! I-Itu perangkat itu lagi!",
  ui_story_1022_10220402_44_dialog_content = "(Tidak ada keraguan tentang itu. Tahun itu, ketika para ilmuwan Illumina mengganti jantung cacatku dengan yang buatan...)",
  ui_story_1022_10220402_45_dialog_content = "(Saya melihat perangkat itu berada di samping tempat tidurku saat saya bangun dari operasi.)",
  ui_story_1022_10220402_46_dialog_content = "(Dan di dalamnya... Itu adalah hatiku yang asli! Aku yakin itu!)",
  ui_story_1022_10220402_47_dialog_content = "Sepertinya kamu tahu persis apa yang ada di dalam kontainer ini.",
  ui_story_1022_10220402_48_dialog_content = "... Apa yang kau inginkan dariku?",
  ui_story_1022_10220402_49_dialog_content = "Sederhana. Kami membutuhkan kamu untuk menggunakan kekuatan unikmu untuk memasuki Zona Gelap dan mengambil inti Wali Satu.",
  ui_story_1022_10220402_50_dialog_content = "Jika Anda berhasil, saya akan menyerahkan ini kepada Anda secara pribadi.",
  ui_story_1022_10220402_51_dialog_content = "Saya juga bisa menggunakan teknologi yang telah ditingkatkan untuk menyelesaikan konstruksi jantung buatanmu yang belum selesai. Pilihannya ada di tanganmu.",
  ui_story_1022_10220402_52_dialog_content = "Kau pikir kau bisa memanipulasiku seperti ini?!",
  ui_story_1022_10220402_53_dialog_content = "Sudah kubilang jangan biarkan emosimu mengendalikan pilihanmu, Pepita.",
  ui_story_1022_10220402_54_dialog_content = "Pikirkan dengan matang tentang apa yang benar-benar kamu inginkan, dan harga yang bersedia kamu bayar untuk itu.",
  ui_story_1022_10220402_55_dialog_content = "...",
  ui_story_1022_10220402_56_dialog_content = "<color=#e8d9bb>Di Tundra Coral dari Zona Gelap.</color>",
  ui_story_1022_10220402_57_dialog_content = "<color=#e8d9bb>Dengan suara yang melengking, Ursura memerintahkan anak buah Eclipsite-nya untuk menyiapkan pesta makan malam dalam rangka menghormati temannya.</color>",
  ui_story_1022_10220402_58_dialog_content = "<color=#e8d9bb>Ketika Pepita kembali sadar, dia menyadari bahwa dia telah tenggelam dalam ingatannya untuk waktu yang cukup lama.</color>",
  ui_story_1022_10220402_59_dialog_content = "<color=#e8d9bb>Saat dia menatap formasi karang yang megah, dia ingat mengapa dia memilih untuk meninggalkan kesepakatannya dengan Belisaria dan datang ke sini.</color>",
  ui_story_1022_10220402_60_dialog_content = "Ursura.",
  ui_story_1022_10220402_61_dialog_content = "Bodoh! Siapa yang menyuruhmu meletakkan karang merah dan hijau di piring yang sama?! Selera estetikamu tidak lebih baik dari semut!",
  ui_story_1022_10220402_62_dialog_content = "Ini persis mengapa berasal dari garis keturunan bangsawan sangat penting... Apakah kamu membutuhkan sesuatu, Pepita?",
  ui_story_1022_10220402_63_dialog_content = "Ingat apa yang kukatakan saat kita pertama kali bertemu? Kisah tentang hatiku?",
  ui_story_1022_10220402_64_dialog_content = "Tentang bagaimana orang-orang itu mengambil hatiku yang asli dan—",
  ui_story_1022_10220402_65_dialog_content = "Ugh, bajingan Aurorian itu! Mereka mencabik-cabik hatimu dan bahkan tidak memiliki kebaikan untuk menggantinya dengan yang berfungsi penuh! Itulah sebabnya kamu selalu merasa sakit sepanjang waktu!",
  ui_story_1022_10220402_66_dialog_content = "Aku ingat semua yang kau ceritakan tentang itu, Pepita... Jadi tidak perlu mulai dari awal.",
  ui_story_1022_10220402_67_dialog_content = "Tentu, tapi dulu, kamu mengatakan sesuatu tentang bisa membuat jantung yang berfungsi juga.",
  ui_story_1022_10220402_68_dialog_content = "<color=#e8d9bb>Pandangan Pepita jatuh ke tengah dada Ursura, di mana cabang-cabang karang yang berdenyut dan bergelombang menonjol dengan cara yang spektakuler.</color>",
  ui_story_1022_10220402_69_dialog_content = "<color=#e8d9bb>Ini adalah karang-karang ini yang membentuk jantung Ursura sendiri.</color>",
  ui_story_1022_10220402_70_dialog_content = "Tentu saja aku bisa! Lagipula, aku memiliki kekuatan yang paling murni dan paling mulia di sini!",
  ui_story_1022_10220402_71_dialog_content = "Untuk seseorang yang sekuat diriku, membuat hati yang kuat dari karang sejelas bernafas!",
  ui_story_1022_10220402_72_dialog_content = "... Jadi, kapan kamu bisa mulai?",
  ui_story_1022_10220402_73_dialog_content = "Apakah itu berarti Anda akhirnya telah mengambil keputusan?",
  ui_story_1022_10220402_74_dialog_content = "Hmph! Dalam hal itu... Kamu harus berjanji padaku sesuatu terlebih dahulu!",
  ui_story_1022_10220501_1_dialog_content = "Nyaaa! Kenapa semua hal gila terjadi saat aku tidak ada di sekitar?!",
  ui_story_1022_10220501_2_dialog_content = "Tapi tidak apa-apa! Sebagai Intel Chief favorit semua orang, aku membawa pulang banyak informasi berharga untuk kita gunakan!",
  ui_story_1022_10220501_3_dialog_content = "Apakah ini tentang Pepita?!",
  ui_story_1022_10220501_4_dialog_content = "Kamu benar! Sebelum saya pergi, kami hampir tidak tahu apa-apa tentang gadis itu meskipun kami mengirimnya ke Dark Zone dengan timnya sendiri.",
  ui_story_1022_10220501_5_dialog_content = "Jadi saya mendapatkan Yingel, dan dia cukup baik untuk memindai sejumlah dokumen Komite untuk kita!",
  ui_story_1022_10220501_6_dialog_content = "Committee? Aku tahu ada lebih banyak tentang dia daripada yang kita pikirkan.",
  ui_story_1022_10220501_7_dialog_content = "Dari apa yang kami temukan di file mereka, Committee pernah mengirim Tim Ekspedisi yang berbeda ke Dark Zone beberapa tahun lalu...",
  ui_story_1022_10220501_8_dialog_content = "Dan ayah Pepita kebetulan adalah salah satu anggotanya.",
  ui_story_1022_10220501_9_dialog_content = "Hah? Apakah kamu mengatakan dia mendapatkan hak istimewa untuk bergabung dengan Tim Ekspedisi?",
  ui_story_1022_10220501_10_dialog_content = "Tidak, PlayerName. Pikirkan kembali penampilan Pepita selama pertempuran kita.",
  ui_story_1022_10220501_11_dialog_content = "Dia tidak memakai peralatan apa pun, dan namun gerakannya sama sekali tidak terpengaruh oleh Darkflow.",
  ui_story_1022_10220501_12_dialog_content = "Jika karakteristik ini adalah turunan, maka semua ini menjadi jauh lebih masuk akal.",
  ui_story_1022_10220501_13_dialog_content = "... Anda ada benarnya. Jika kemampuan Pepita untuk bergerak bebas di Zona Gelap adalah warisan, maka ayahnya kemungkinan besar juga memilikinya.",
  ui_story_1022_10220501_14_dialog_content = "Jadi, eksplorasinya pasti sangat berhasil, bukan?",
  ui_story_1022_10220501_15_dialog_content = "Sebaliknya, seluruh timnya benar-benar musnah...",
  ui_story_1022_10220501_16_dialog_content = "H-Hapus?!",
  ui_story_1022_10220501_17_dialog_content = "Benar, dan satu-satunya yang selamat adalah ayah Pepita.",
  ui_story_1022_10220501_18_dialog_content = "Tapi sepertinya kemampuan spesialnya bukanlah satu-satunya hal yang dia gunakan untuk kembali. Ada kemungkinan besar dia harus menggunakan cara-cara yang kurang mulia untuk bertahan hidup...",
  ui_story_1022_10220501_19_dialog_content = "Karena segera setelah dia kembali, dia menandatangani semua dokumen yang diperlukan untuk menempatkan Pepita dalam pengawasan laboratorium Illumina.",
  ui_story_1022_10220501_20_dialog_content = "Dia meninggalkan putrinya sendiri?!",
  ui_story_1022_10220501_21_dialog_content = "Tapi itu pada dasarnya setuju untuk membiarkan dia menjadi subjek uji!",
  ui_story_1022_10220501_22_dialog_content = "Aku tahu... Itulah sebabnya Yingel berpikir dia pasti telah melakukan sesuatu yang sangat buruk sehingga satu-satunya cara untuk menyelamatkan dirinya adalah dengan mengorbankan anaknya sendiri...",
  ui_story_1022_10220501_23_dialog_content = "... Sulit dipercaya.",
  ui_story_1022_10220501_24_dialog_content = "Saya tidak berpikir ada orang di Federasi yang bisa melakukan sesuatu yang begitu pengecut.",
  ui_story_1022_10220501_25_dialog_content = "Setelah itu, eksplorasi kami ke Zona Gelap menurun secara signifikan, tetapi penelitian tentang Pepita terus berlanjut tanpa ragu-ragu.",
  ui_story_1022_10220501_26_dialog_content = "Untuk memaksimalkan kekuatan dan mobilitas tempurnya, Komite menggantikan jantung Aurorian yang kurang sempurna dengan yang buatan.",
  ui_story_1022_10220501_27_dialog_content = "Apa? Maksudmu hatinya buatan manusia?",
  ui_story_1022_10220501_28_dialog_content = "Dengan kata lain, Committee tidak pernah meninggalkan rencana mereka untuk menjelajahi Dark Zone. Sebaliknya, mereka sedang membesarkan Pepita untuk menjadi pemimpin berikutnya dari Expedition Team.",
  ui_story_1022_10220501_29_dialog_content = "Itu pasti kemungkinan yang berbeda! Namun...",
  ui_story_1022_10220501_30_dialog_content = "Teknologi kami tentang jantung buatan masih jauh dari dikembangkan, yang berarti Pepita kemungkinan besar juga subjek tes yang berharga...",
  ui_story_1022_10220501_31_dialog_content = "Kasihan Pepita... Bagaimana mereka bisa membuatnya menderita begitu banyak?",
  ui_story_1022_10220501_32_dialog_content = "Aku tahu, tapi semakin buruk. Setelah Pepita mengetahui kesepakatan antara ayahnya dan Komite, dia benar-benar kehilangan kendali...",
  ui_story_1022_10220501_33_dialog_content = "Dia melarikan diri dari Illumina pada kesempatan pertama yang dia dapatkan, dan mulai berkeliaran di seluruh Astra sebagai buronan. Dari apa yang telah kami kumpulkan, tampaknya dia sekarang bergabung dengan True Order.",
  ui_story_1022_10220501_34_dialog_content = "Akhirnya aku mengerti... Tanpa tempat lain untuk pergi, dia akhirnya bersama mereka...",
  ui_story_1022_10220501_35_dialog_content = "Tapi tunggu, ada lagi! Setelah dia kabur, Pepita sebenarnya pernah menyelinap kembali ke Federasi pada suatu saat.",
  ui_story_1022_10220501_36_dialog_content = "Pilihan yang berani namun bodoh. Apa tujuannya?",
  ui_story_1022_10220501_37_dialog_content = "Kurasa tujuannya adalah untuk mencuri kembali hati aslinya.",
  ui_story_1022_10220501_38_dialog_content = "Tapi tidak butuh waktu lama bagi kami untuk menemukannya, jadi dia kabur lagi.",
  ui_story_1022_10220501_39_dialog_content = "Jadi, dia dikejar oleh dua faksi utama, tetapi pada akhirnya dia ditangkap oleh Illumina. Tidak hanya itu, mereka juga langsung mengirimnya ke Dark Zone...",
  ui_story_1022_10220501_40_dialog_content = "Saya tidak tahu bagaimana lagi menggambarkannya... Tapi dia memiliki salah satu sejarah yang paling berwarna yang pernah saya lihat.",
  ui_story_1022_10220501_41_dialog_content = "(Aku benar-benar tidak bisa menyalahkannya karena membenci otoritas atau bersikap pemberontak...)",
  ui_story_1022_10220501_42_dialog_content = "Dan sekarang dia bersekutu dengan Hantu.",
  ui_story_1022_10220501_43_dialog_content = "Pekerjaan yang luar biasa, Philyshy. Saya akan melaporkan semuanya kepada Grand Marshal secepat mungkin.",
  ui_story_1022_10220502_1_dialog_content = "... Dan itulah situasi kita sejauh ini. Kemampuan Pepita untuk bergerak bebas melalui Zona Gelap pasti sangat berharga.",
  ui_story_1022_10220502_2_dialog_content = "Bagaimana kita harus melanjutkan, Grand Marshal?",
  ui_story_1022_10220502_3_dialog_content = "Jika kita bertemu dengannya lagi, apakah kita benar-benar diharapkan untuk duduk diam dan membiarkan Lumopolis membawanya pergi?",
  ui_story_1022_10220502_4_dialog_content = "Sangat mungkin bahwa Pepita tahu sesuatu tentang harta karun Lumopolis yang dicuri.",
  ui_story_1022_10220502_5_dialog_content = "Eksplorasi ini adalah upaya bersama antara Illumina dan Lumopolis. Jika kita ingin berhasil, kita tidak bisa mengabaikan kepentingan mereka.",
  ui_story_1022_10220502_6_dialog_content = "Tapi—",
  ui_story_1022_10220502_7_dialog_content = "Namun, itu tidak berarti kita tidak bisa menarik batas di suatu tempat.",
  ui_story_1022_10220502_8_dialog_content = "Yingel memberi tahu saya tentang latar belakang Pepita beberapa waktu lalu. Saya menduga dia mungkin memiliki bakat untuk menjelajahi Dark Zone—",
  ui_story_1022_10220502_9_dialog_content = "Jadi, saya membagikan informasi itu dengan Penguasa Kota Lumopolis.",
  ui_story_1022_10220502_10_dialog_content = "Apa?! L-Lalu... Bagaimana reaksinya?",
  ui_story_1022_10220502_11_dialog_content = "Siapa pun dengan mata bisa melihat bahwa Pepita jauh lebih berguna di lapangan daripada di sel penjara.",
  ui_story_1022_10220502_12_dialog_content = "Schwartz juga tidak terkecuali.",
  ui_story_1022_10220502_13_dialog_content = "Jika kita bisa memanfaatkan Pepita dan kemampuannya sepenuhnya, setiap orang akan mendapatkan manfaat.",
  ui_story_1022_10220502_14_dialog_content = "Bukan hanya untuk operasi ini, tetapi juga dalam jangka panjang.",
  ui_story_1022_10220502_15_dialog_content = "Kamu ingin menggunakan dia untuk mengumpulkan lebih banyak informasi yang bisa memberi kita keuntungan atas Eclipsite dalam pertempuran kita di masa depan... Itu kah maksudmu?",
  ui_story_1022_10220502_16_dialog_content = "Sepertinya kita sependapat, Tuhan Schwartz.",
  ui_story_1022_10220502_17_dialog_content = "Hmph... Menurutku, dia tidak lebih dari seorang pencuri biasa. Selama dia memberi tahu kita apa yang dia ketahui tentang kitab suci kita, Lumopolis tidak akan menganggapnya sebagai musuh.",
  ui_story_1022_10220502_18_dialog_content = "Saya lihat... Kerja yang mengesankan, Grand Marshal!",
  ui_story_1022_10220502_19_dialog_content = "Saya senang kamu mengerti, jadi ikuti saja rencana mereka untuk saat ini.",
  ui_story_1022_10220502_20_dialog_content = "Lagi pula, saya yakin Pepita akan lebih merepotkan daripada semua Lumopolis di luar sana! Hahahaha!",
  ui_story_1022_10220502_21_dialog_content = "S-Sama sekali tidak! Tanpa intervensi tepat waktu dari Anda, Lumopolis pasti akan memenjarakan gadis itu!",
  ui_story_1022_10220502_22_dialog_content = "Setelah semua... Pemimpin Divisi Investigasi Heretics memiliki obsesi hampir gila dengan True Order.",
  ui_story_1022_10220502_23_dialog_content = "A-Apa maksudmu, Pepita tidak akan menghadapi hukuman lagi?!",
  ui_story_1022_10220502_24_dialog_content = "Tuan Kota seharusnya sepenuhnya sadar tentang hubungannya dengan True Order!",
  ui_story_1022_10220502_25_dialog_content = "Ya, tetapi City Lord juga mempertimbangkan manfaat jangka panjang yang mungkin dia berikan untuk semua Aurorian.",
  ui_story_1022_10220502_26_dialog_content = "Kami masih memiliki perintah untuk memintanya tentang kitab yang dicuri juga.",
  ui_story_1022_10220502_27_dialog_content = "Tapi bagaimana... Bagaimana kita bisa membiarkan pergi begitu saja...?",
  ui_story_1022_10220502_28_dialog_content = "... Aku tahu bahwa kamu menyimpan dendam terhadap True Order, dan dendammu telah membuatmu menjadi anggota Heretics Investigation Division yang luar biasa.",
  ui_story_1022_10220502_29_dialog_content = "Namun, apakah sasaran kebencianmu benar-benar termasuk dalam True Order atau tidak, telah menjadi pertanyaan selama bertahun-tahun sekarang.",
  ui_story_1022_10220502_30_dialog_content = "Tidak... Kita tidak bisa membiarkan dia pergi... Tidak seperti ini...",
  ui_story_1022_10220502_31_dialog_content = "Cukup, sekarang tenangkan dirimu!",
  ui_story_1022_10220502_32_dialog_content = "Kita berada di Dark Zone sekarang. Dengan membiarkan dirimu dikendalikan oleh emosimu, kamu mempertaruhkan nyawa kawan-kawanmu!",
  ui_story_1022_10220502_33_dialog_content = "... Kamu benar, Lady. Mohon maafkan kehebohan saya...",
  ui_story_1022_10220502_34_dialog_content = "Aku... Hanya butuh waktu sendiri, itu saja.",
  ui_story_1022_10220502_35_dialog_content = "...",
  ui_story_1022_10220601_1_dialog_content = "Aku tidak bisa membiarkannya pergi... Aku tidak akan! Meskipun aku harus melakukannya sendiri... Aku akan membuatnya membayar...",
  ui_story_1022_10220601_2_dialog_content = "Dia dan setiap anggota True Order... Harus dihukum mati!",
  ui_story_1022_10220601_3_dialog_content = "Saya melihat kamu masih berniat melakukan sesuatu yang bodoh.",
  ui_story_1022_10220601_4_dialog_content = "W-Wanita Carleen...!",
  ui_story_1022_10220601_5_dialog_content = "Apa yang ada di tanganmu?",
  ui_story_1022_10220601_6_dialog_content = "Ini... Ini disebut Resonator White Night. Ini adalah salah satu artefak yang disimpan di Kuil Lumopolis, dan mampu mendeteksi keberadaan benda-benda suci kita.",
  ui_story_1022_10220601_7_dialog_content = "Ini telah bereaksi intens terhadap sesuatu sejak kita memasuki Zona Gelap.",
  ui_story_1022_10220601_8_dialog_content = "Saya percaya salah satu artefak hilang Lumopolis mungkin berada di suatu tempat yang dekat.",
  ui_story_1022_10220601_9_dialog_content = "Apakah itu menunjuk ke arah tertentu? Seperti... Apa arah tempat Pepita dan Ursura pergi?",
  ui_story_1022_10220601_10_dialog_content = "Aku…",
  ui_story_1022_10220601_11_dialog_content = "Anda berencana untuk melacak mereka dan membawa kembali artefak-artefak yang hilang kita semua sendiri, bukan?",
  ui_story_1022_10220601_12_dialog_content = "Jika begitu, bukan hanya Anda yang melebih-lebihkan kemampuan Anda, tetapi Anda juga sangat meremehkan sekutu Anda!",
  ui_story_1022_10220601_13_dialog_content = "Jika satu orang mampu mencapai apa saja di sini, apakah kita akan bergabung untuk membentuk Tim Ekspedisi ini?!",
  ui_story_1022_10220601_14_dialog_content = "Aku tidak yakin apakah harus menyebutkan ini atau tidak... Tapi aku merasakan bola besar Lumina di arah yang sama juga.",
  ui_story_1022_10220601_15_dialog_content = "?!",
  ui_story_1022_10220601_16_dialog_content = "Hantu-hantu adalah musuh kita bersama. Itu saja yang harus saya katakan.",
  ui_story_1022_10220601_17_dialog_content = "Kamu... Hmm.",
  ui_story_1022_10220601_18_dialog_content = "Aku juga ingin menemukan Pepita, kapten... Bukan untuk menghukumnya, tapi untuk menyelamatkannya.",
  ui_story_1022_10220601_19_dialog_content = "Tujuan organisasi kami adalah untuk menyelamatkan dunia dari kekuatan yang tidak dikenal... Dan sekutu kami tidak terkecuali. Setidaknya... Itulah yang saya rasakan.",
  ui_story_1022_10220601_20_dialog_content = "Erica... Kamu telah membuktikan dirimu lebih tenang dan lebih bijaksana dari yang saya pikirkan sebelumnya. Saya, di sisi lain...",
  ui_story_1022_10220601_21_dialog_content = "Maafkan aku, Lady Carleen... Dan semua kalian juga. Aku membiarkan dendamku mengaburkan akalku, dan untuk itu aku harus minta maaf.",
  ui_story_1022_10220601_22_dialog_content = "Hanya saja... Setiap kali aku bahkan memikirkan tentang True Order, aku—!",
  ui_story_1022_10220601_23_dialog_content = "Tidak ada yang meminta Anda untuk melepaskan dendam Anda segera. Bahkan orang terbaik di antara kita akan kesulitan melakukan itu.",
  ui_story_1022_10220601_24_dialog_content = "Namun dendam tidak bisa datang dengan harga nyawa kamu sendiri... Itulah mengapa kita memutuskan untuk membentuk tim ini dan saling menjaga, benar?",
  ui_story_1022_10220601_25_dialog_content = "Aku…",
  ui_story_1022_10220601_26_dialog_content = "Sekarang, mari kita bergerak. Kita akan berbaris menuju sarang Ursura bersama-sama!",
  ui_story_1022_10220601_27_dialog_content = "<color=#e8d9bb>Mengikuti petunjuk dari White Night Resonator, tim akhirnya menemukan luasnya tanah yang dipenuhi dengan tanaman berwarna-warni dan terdistorsi.</color>",
  ui_story_1022_10220601_28_dialog_content = "Wow, tempat ini...",
  ui_story_1022_10220601_29_dialog_content = "Ini sangat aneh, namun begitu menakjubkan... Aku memiliki firasat buruk tentang ini...",
  ui_story_1022_10220601_30_dialog_content = "Sepertinya kita berada di jalur yang benar. Bawahan Pepita menyebutkan sesuatu tentang menemukan tanah karang.",
  ui_story_1022_10220601_31_dialog_content = "Pengaruh Ursura mungkin menjadi sumber dari pemandangan yang terdistorsi ini.",
  ui_story_1022_10220601_32_dialog_content = "... Sekarang mengklasifikasikan area ini sebagai \"<color=#FFB400>Sektor 44 yang Belum Dijelajahi</color>.\"",
  ui_story_1022_10220601_33_dialog_content = "Ikutlah denganku, PlayerName. Ada sesuatu yang ingin kupertanyakan padamu.",
  ui_story_1022_10220601_34_dialog_content = "Apa itu, Carleen?",
  ui_story_1022_10220601_35_dialog_content = "Kamu bilang kamu bisa merasakan bola Lumina besar di suatu tempat di sini, ya?",
  ui_story_1022_10220601_36_dialog_content = "Apakah mungkin salah satu artefak kita adalah sumber dari Lumina itu?",
  ui_story_1022_10220601_37_dialog_content = "Hah? M-Maksudmu yang dideteksi oleh White Night Resonator?!",
  ui_story_1022_10220601_38_dialog_content = "Kurasa aku tidak bisa sepenuhnya menepisnya, tapi sesuatu memberitahuku bahwa itu bukan masalahnya...",
  ui_story_1022_10220601_39_dialog_content = "Aku tidak bisa menjelaskan mengapa aku merasa seperti ini. Panggil saja itu naluri, tapi ada sesuatu yang hangat dan akrab tentang bola Lumina itu...",
  ui_story_1022_10220601_40_dialog_content = "Begitu... Itu saja yang perlu saya tanyakan. Mari kita kembali.",
  ui_story_1022_10220601_41_dialog_content = "Apakah kamu baik-baik saja, Carleen? Sepertinya... Kamu sedang memikul beban tertentu.",
  ui_story_1022_10220601_42_dialog_content = "Tentu saja, mengingat aku adalah bagian dari delegasi Lumopolis ke Zona Gelap...",
  ui_story_1022_10220601_43_dialog_content = "... Tapi mungkin saya hanya terlalu tidak sabar. Setelah semua yang telah terjadi, mungkin saya hanya ingin mencapai sesuatu.",
  ui_story_1022_10220601_44_dialog_content = "Alih-alih merasa seperti binatang yang terjebak dalam kegelapan.",
  ui_story_1022_10220601_45_dialog_content = "Tapi kamu benar, aku tidak seharusnya tergesa-gesa begitu.",
  ui_story_1022_10220601_46_option_content = "Aku belum bilang apa-apa...",
  ui_story_1022_10220601_47_dialog_content = "Tapi kamu akan melakukannya, kan?!",
  ui_story_1022_10220601_48_dialog_content = "Er, y-ya! Tentu saja!",
  ui_story_1022_10220601_49_option_content = "Tidak apa-apa merasa seperti itu.",
  ui_story_1022_10220601_50_dialog_content = "Saya benar-benar mengerti rasa gelisahmu... Karena saya merasa persis seperti itu.",
  ui_story_1022_10220601_51_dialog_content = "... Terima kasih. Itu lebih menghibur saya daripada apa pun yang bisa kamu katakan.",
  ui_story_1022_10220601_52_dialog_content = "Hmm? Sepertinya ada masalah di sana. Pergi!",
  ui_story_1022_10220601_53_dialog_content = "Perasaan burukku tentang tempat ini semakin kuat... Seolah-olah dewa kejahatan telah turun ke tempat ini...",
  ui_story_1022_10220601_54_dialog_content = "Tubuh?! Tunggu, apakah ini... Aurorian?!",
  ui_story_1022_10220601_55_dialog_content = "Mereka tidak sepenuhnya mirip dengan mereka... Tapi mereka juga tidak mirip Eclipsite. Mereka itu apa?",
  ui_story_1022_10220601_56_dialog_content = "... Makhluk-makhluk ini mirip dengan Aurorian, dalam hal ada jejak-jejak samar Lumina di tubuh mereka.",
  ui_story_1022_10220601_57_dialog_content = "Namun, tampaknya Lumina telah sepenuhnya terkuras dari mereka.",
  ui_story_1022_10220601_58_dialog_content = "Siapa atau apa yang bisa melakukan sesuatu yang begitu mengerikan?! Membunuh mereka seperti ini adalah...",
  ui_story_1022_10220601_59_dialog_content = "Aku juga berpikir begitu, tapi kemudian aku melihat lebih dekat.",
  ui_story_1022_10220601_60_dialog_content = "Penyebab kematian mereka bukan karena Lumina mereka tersedot. Bahkan, mereka tampaknya telah hidup dalam keadaan ini untuk jangka waktu yang lama.",
  ui_story_1022_10220601_61_dialog_content = "Tetapi bagaimana... Bagaimana Aurorian bisa bertahan tanpa Lumina mereka?",
  ui_story_1022_10220601_62_dialog_content = "Mayat Aurorian yang kehilangan Lumina, dan artefak yang dicuri dari Lumopolis...",
  ui_story_1022_10220601_63_dialog_content = "... Hancurkan Eclipsites kotor ini! Bagaimana mereka berani merusak jenis kita seperti ini?!",
  ui_story_1022_10220601_64_dialog_content = "Pernahkah terlintas dalam pikiranmu bahwa mungkin kalian Aurorian-lah yang telah mencuri dari Eclipse selama ini?",
  ui_story_1022_10220601_65_dialog_content = "Seperti tempat-tempat yang kamu sebut rumah...",
  ui_story_1022_10220601_66_dialog_content = "!!",
  ui_story_1022_10220601_67_dialog_content = "Kenapa, PlayerName?",
  ui_story_1022_10220601_68_dialog_content = "... Bukan apa-apa.",
  ui_story_1022_10220601_69_dialog_content = "(Apakah aku sedang berkhayal, atau aku baru saja mendengar suara lemah yang memanggil...?)",
  ui_story_1022_10220701_1_dialog_content = "Semua orang ini meninggal pada saat yang sama.",
  ui_story_1022_10220701_2_dialog_content = "Ada juga pecahan logam yang aneh, tersebar di antara karang-karang... Apa sebenarnya yang terjadi di sini?",
  ui_story_1022_10220701_3_dialog_content = "Mungkin aku bisa menjawab itu.",
  ui_story_1022_10220701_4_dialog_content = "... Kami mengandalkanmu.",
  ui_story_1022_10220701_5_dialog_content = "Jangan terlalu memaksakan diri, PlayerName.",
  ui_story_1022_10220701_6_option_content = "Psychic Scan",
  ui_story_1022_10220701_7_dialog_content = "Hah?! Apa... Apakah ini...?",
  ui_story_1022_10220701_8_dialog_content = "<color=#e8d9bb>Deru mesin berat yang memekakkan telinga memenuhi udara.</color>",
  ui_story_1022_10220701_9_dialog_content = "<color=#e8d9bb>Tanah bergetar seiring gerakan mereka.</color>",
  ui_story_1022_10220701_10_dialog_content = "<color=#e8d9bb>Tak terhitung mesin aneh melayang melintasi langit, bercampur dengan terumbu karang dan tanaman yang indah dan bengkok.</color>",
  ui_story_1022_10220701_11_dialog_content = "<color=#e8d9bb>Sebuah pemandangan yang jauh lebih mengejutkan dibandingkan dengan bidang karang yang tenang yang terlihat sebelumnya.</color>",
  ui_story_1022_10220701_12_dialog_content = "(Potongan logam Hiiro yang ditemukan pasti berasal dari mesin-mesin ini.)",
  ui_story_1022_10220701_13_dialog_content = "(Apakah yang saya lihat... Adalah lapangan karang <color=#FFB400>di masa lalu</color>?)",
  ui_story_1022_10220701_14_dialog_content = "(Ah! Yang mengendalikan mesin-mesin itu adalah makhluk yang mirip Aurorian yang kita lihat sebelumnya! Apakah mereka telah tinggal di sini sepanjang waktu?)",
  ui_story_1022_10220701_15_dialog_content = "<color=#e8d9bb>Ketenangan dari tanah-tanah ini hanya dapat dihargai dalam kehadiran makhluk hidup.</color>",
  ui_story_1022_10220701_16_dialog_content = "<color=#e8d9bb>Selain derau mesin mereka yang tak berujung, lapangan karang ini benar-benar sunyi.</color>",
  ui_story_1022_10220701_17_dialog_content = "(Tidak ada komunikasi di antara mereka, dan tindakan serta ekspresi mereka sangat kaku. Sepertinya mereka hanya menjalani rutinitas pekerjaan mereka.)",
  ui_story_1022_10220701_18_dialog_content = "(Mereka mengingatkan saya pada Eclipsite tingkat rendah... Jadi mengapa mereka lebih terlihat seperti Aurorian di luar?)",
  ui_story_1022_10220701_19_dialog_content = "Heheh... Setelah bertahun-tahun, sepertinya kita adalah satu-satunya yang masih bisa berbicara.",
  ui_story_1022_10220701_20_dialog_content = "(Ah! Astaga... Aku tak menyangka mendengar mereka semua berbicara!)",
  ui_story_1022_10220701_21_dialog_content = "Sejak aku lahir, tempat ini tidak berubah. Selain mesin, satu-satunya hal lain di sini hanyalah kerangka orang-orang yang kosong dan tenang...",
  ui_story_1022_10220701_22_dialog_content = "Aku hampir tidak bisa lagi membedakan mereka.",
  ui_story_1022_10220701_23_dialog_content = "Tapi mengapa kita dikutuk untuk hidup seperti ini?",
  ui_story_1022_10220701_24_dialog_content = "Mengapa kita tidak bisa meninggalkan tanah kematian ini dan melihat dunia luar?",
  ui_story_1022_10220701_25_dialog_content = "Ini mustahil!",
  ui_story_1022_10220701_26_dialog_content = "Ketika saya masih muda, saya kenal beberapa orang seperti kita yang mencoba untuk melarikan diri...",
  ui_story_1022_10220701_27_dialog_content = "Jadi apa yang terjadi? Apakah kamu pernah melihat mereka lagi?",
  ui_story_1022_10220701_28_dialog_content = "Tidak. Mereka mati... Semua dari mereka.",
  ui_story_1022_10220701_29_dialog_content = "?!",
  ui_story_1022_10220701_30_dialog_content = "Ada tempat di luar tempat kita tinggal. Itu seperti tungku yang menyala-nyala, dan membakar setiap dari mereka menjadi abu.",
  ui_story_1022_10220701_31_dialog_content = "Tidak ada yang pernah mencoba pergi sejak saat itu. Bahkan mereka yang sedikit terlalu jauh dari tempat ini tidak pernah terlihat lagi.",
  ui_story_1022_10220701_32_dialog_content = "Tapi mengapa...? Apakah benar tidak ada harapan untuk kita? Apakah kita benar-benar ditakdirkan untuk mati di sini?",
  ui_story_1022_10220701_33_dialog_content = "Betapa kejamnya takdir ini...",
  ui_story_1022_10220701_34_dialog_content = "?!",
  ui_story_1022_10220701_35_dialog_content = "(Ah! M-Mereka menatapku langsung!)",
  ui_story_1022_10220701_36_dialog_content = "H-halo di sana...?",
  ui_story_1022_10220701_37_dialog_content = "Seorang orang asing? Ugh, saya sangat cemburu.",
  ui_story_1022_10220701_38_dialog_content = "Apa yang membawa Anda ke tempat yang terkutuk ini? Tidak ada apa-apa di sini kecuali mesin dan karang.",
  ui_story_1022_10220701_39_dialog_content = "Oh, dan apapun yang kamu lakukan, jangan makan karang. Itu akan mengubah warna darahmu menjadi warna putih susu yang menjijikkan.",
  ui_story_1022_10220701_40_dialog_content = "Seperti milik kita.",
  ui_story_1022_10220701_41_dialog_content = "<color=#e8d9bb>Makhluk mirip Aurorian menunjukkan senyum merendahkan diri.</color>",
  ui_story_1022_10220701_42_dialog_content = "Makan karang akan membuat darahku berubah putih? Saya mengerti... Terima kasih atas peringatannya.",
  ui_story_1022_10220701_43_dialog_content = "Tapi, apa tidak ada makanan lain di luar sini?",
  ui_story_1022_10220701_44_dialog_content = "Sama sekali tidak. Hanya karang, karang, dan lebih banyak karang yang terkutuk...",
  ui_story_1022_10220701_45_dialog_content = "Tempat ini dikutuk, kataku padamu. Setiap hari, karang dan lumut baru muncul.",
  ui_story_1022_10220701_46_dialog_content = "Mesin-mesin ini tidak bisa berjalan dengan baik jika kita tidak membersihkannya tepat waktu.",
  ui_story_1022_10220701_47_dialog_content = "Terutama tungku itu. Apapun yang terjadi, kita tidak boleh membiarkannya berhenti.",
  ui_story_1022_10220701_48_dialog_content = "Untuk menghabiskan hidup kita bekerja keras di antara rumput liar, menjaga tungku tetap hidup tanpa sedikit pun martabat... Kami pasti juga dikutuk.",
  ui_story_1022_10220701_49_dialog_content = "... Selain saya, apakah ada orang lain yang pernah melewati sini? Seperti... Seorang Eclipsite?",
  ui_story_1022_10220701_50_dialog_content = "Sebuah Hantu muncul dari waktu ke waktu, kan?",
  ui_story_1022_10220701_51_dialog_content = "Itu benar. Namanya Yodu.",
  ui_story_1022_10220701_52_dialog_content = "Sebuah Hantu?!",
  ui_story_1022_10220701_53_dialog_content = "Dia adalah orang yang akan membunuh kita.",
  ui_story_1022_10220701_54_dialog_content = "Dia adalah orang yang akan membunuh kita.",
  ui_story_1022_10220701_55_dialog_content = "Dia adalah orang yang akan membunuh kita.",
  ui_story_1022_10220701_56_dialog_content = "?!",
  ui_story_1022_10220701_57_dialog_content = "Suatu hari, ketika dia berpikir kita tidak lagi berguna baginya, dia akan membunuh kita semua sampai yang terakhir.",
  ui_story_1022_10220701_58_dialog_content = "Tapi setelah terperangkap di sini sepanjang hidup kita, mungkin kita seharusnya sudah mati lama.",
  ui_story_1022_10220701_59_dialog_content = "Terperangkap di sini sepanjang hidup kita.",
  ui_story_1022_10220701_60_dialog_content = "Terperangkap di sini sepanjang hidup kita.",
  ui_story_1022_10220701_61_dialog_content = "...!!!",
  ui_story_1022_10220701_62_dialog_content = "Ada apa, PlayerName? Kamu tampak sangat pucat.",
  ui_story_1022_10220701_63_dialog_content = "Aku... Aku hanya merasakan pikiran yang tertinggal dari orang-orang yang mati di sini.",
  ui_story_1022_10220701_64_dialog_content = "...",
  ui_story_1022_10220701_65_dialog_content = "Bahkan sampai hari ini, roh mereka masih terperangkap di sini? May mereka menemukan kedamaian suatu hari nanti.",
  ui_story_1022_10220701_66_dialog_content = "Jadi Hantu bernama Yodu yang bertanggung jawab atas kematian mereka? Tidak dapat dimaafkan...",
  ui_story_1022_10220701_67_dialog_content = "Benar, dan kekuatan Ursura tidak ada apa-apanya dibandingkan dengannya.",
  ui_story_1022_10220701_68_dialog_content = "Itu adalah cara berpikir yang berbahaya. Semua Wraith harus diperlakukan sebagai ancaman yang sangat berbahaya, kamu tahu itu.",
  ui_story_1022_10220701_69_dialog_content = "M-maaf!",
  ui_story_1022_10220701_70_dialog_content = "Jangan. Saya hanya ingin kamu tetap waspada saat situasi membutuhkannya.",
  ui_story_1022_10220701_71_dialog_content = "Dari apa yang kamu lihat dalam visimu, aman untuk diasumsikan bahwa ini adalah basis penelitian di masa lalu—",
  ui_story_1022_10220701_72_dialog_content = "Pekerja-pekerja itu adalah makhluk-makhluk yang mirip dengan Aurorian, dan pengawas mereka adalah Yodu si Hantu.",
  ui_story_1022_10220701_73_dialog_content = "Ya... Saya juga berpikir di jalur yang sama.",
  ui_story_1022_10220701_74_dialog_content = "Dengan pengecualian beberapa orang, para pekerja sama sekali tidak memiliki pikiran, emosi, bahkan ucapan.",
  ui_story_1022_10220701_75_dialog_content = "Tugas utama mereka adalah menjaga mesin tetap berjalan dengan membersihkan karang, lumut, dan pertumbuhan biologis lainnya.",
  ui_story_1022_10220701_76_dialog_content = "Dan tampaknya, mesin yang paling penting adalah semacam tungku.",
  ui_story_1022_10220701_77_dialog_content = "Tetapi mengapa hal-hal seperti terumbu karang dan lumut terus tumbuh di sini? Apakah ini ada hubungannya dengan Ursura?",
  ui_story_1022_10220701_78_dialog_content = "Mungkin saja hal-hal ini akan tumbuh di mana pun Ursura pergi.",
  ui_story_1022_10220701_79_dialog_content = "Jika itu benar, maka dia pasti berada di dekat basis penelitian saat itu juga. Dia bahkan mungkin terhubung dengan Yodu entah bagaimana.",
  ui_story_1022_10220701_80_dialog_content = "Yang semakin menjadi alasan untuk melihatnya sebagai ancaman yang serius...",
  ui_story_1022_10220701_81_dialog_content = "Dan namun dia dan Pepita entah bagaimana menjadi teman yang setia. Pastinya dia tidak akan menyakitinya karena hal itu...",
  ui_story_1022_10220701_82_dialog_content = "... Pada titik ini, aku tidak yakin apakah Pepita menemukan tempat ini adalah hal yang baik atau tidak.",
  ui_story_1022_10220701_83_dialog_content = "Maaf, tapi bolehkah saya menyela?",
  ui_story_1022_10220701_84_dialog_content = "Ada apa?",
  ui_story_1022_10220701_85_dialog_content = "Jika ada yang belum menyadari, Darkflow di sini sangat jarang. Seolah-olah kita sama sekali tidak berada di Zona Gelap.",
  ui_story_1022_10220701_86_dialog_content = "Bisakah itu menjadi artefak yang terdeteksi oleh Resonator White Night... Apakah ia menangkis darkflow sekitar seperti <color=#FFB400>Batu Lumina</color> kita?",
  ui_story_1022_10220701_87_dialog_content = "Kamu benar...! Tapi kita tidak akan tahu kecuali kita terus mencari.",
  ui_story_1022_10220701_88_dialog_content = "Ursura tidak bisa terlalu jauh dari kita sekarang. Tetap waspada.",
  ui_story_1022_10220800_1_dialog_content = "<color=#e8d9bb>Jauh di dalam hutan karang, Pepita tenggelam dalam pikirannya saat ia menatap pemandangan yang berliku-liku.</color>",
  ui_story_1022_10220800_2_dialog_content = "Jadi, sudahkah kamu memikirkan tentang apa yang telah aku katakan, Pepita?",
  ui_story_1022_10220800_3_dialog_content = "... Oh, kau kembali. Apa yang terjadi di luar sana?",
  ui_story_1022_10220800_4_dialog_content = "Tak perlu khawatir, hanya beberapa semut kecil yang mengganggu. Ursura yang perkasa punya hal yang lebih baik untuk dilakukan daripada membuang waktunya pada mereka.",
  ui_story_1022_10220800_5_dialog_content = "Kamu, di sisi lain, berutang jawaban padaku.",
  ui_story_1022_10220800_6_dialog_content = "Hanya menganggukkan kepalamu, dan aku akan menggunakan karang untuk membuatmu hati yang baru.",
  ui_story_1022_10220800_7_dialog_content = "Dan sebagai gantinya... aku harus tinggal di sini dan bermain denganmu selamanya?",
  ui_story_1022_10220800_8_dialog_content = "Kamu tidak akan bermain \"dengan\" aku, kita akan bermain \"bersama\"! Kamu juga menginginkan itu, bukan? Lagipula, kita paling senang saat bersama!",
  ui_story_1022_10220800_9_dialog_content = "Kamu benar. Berada di sini sangat menyenangkan, dan jarang bagi saya untuk menemukan seseorang yang segila saya.",
  ui_story_1022_10220800_10_dialog_content = "Tepat sekali! Jadi, ucapkan saja, dan saya akan mulai membuat hati baru untukmu!",
  ui_story_1022_10220800_11_dialog_content = "Setelah saya lakukan, darahmu akan berubah dari warna merah yang menjengkelkan menjadi putih murni dan mulia seperti saya. Lalu kamu bisa tinggal di sini selamanya!",
  ui_story_1022_10220800_12_dialog_content = "... Ursura.",
  ui_story_1022_10220800_13_dialog_content = "Ya?!",
  ui_story_1022_10220800_14_dialog_content = "Kamu ingat apa yang terjadi saat kita pertama kali bertemu, kan?",
  ui_story_1022_10220800_15_dialog_content = "... Hah? Kenapa kau tiba-tiba mengungkit masa lalu?",
  ui_story_1022_10220800_16_dialog_content = "...",
  ui_story_1022_10220800_17_dialog_content = "(Apa yang... Apa yang terjadi? Di mana aku...?)",
  ui_story_1022_10220800_18_dialog_content = "Graaaah!!",
  ui_story_1022_10220800_19_dialog_content = "*Hosh... Hosh...* Hahaha... Itu saja yang kamu punya? Majulah!",
  ui_story_1022_10220800_20_dialog_content = "Graaah—!",
  ui_story_1022_10220800_21_dialog_content = "Urgh! Hatiku sakit lagi... Sial... Hati palsu yang bodoh!",
  ui_story_1022_10220800_22_dialog_content = "(Seandainya saja aku memiliki hati yang sehat dan nyata... Semua ini tidak akan terjadi...)",
  ui_story_1022_10220800_23_dialog_content = "(Aku ingat sekarang. Aku datang untuk menjelajahi Zona Gelap bersama True Order, tetapi aku pergi sendiri dan disergap oleh sekawanan Eclipsite.)",
  ui_story_1022_10220800_24_dialog_content = "(Dan berkat hatiku yang bodoh dan rusak, aku tidak cukup kuat untuk menghindari penangkapan...)",
  ui_story_1022_10220800_25_dialog_content = "(Mati karena aku bermain-main terlalu banyak kali... Itu sangat mirip denganku, ya? Heh... Heheh...)",
  ui_story_1022_10220800_26_dialog_content = "... Hahahaha!",
  ui_story_1022_10220800_27_dialog_content = "Apa yang terjadi? Aku terbangun dari tidur panjangku, berpikir ada Aurorian di dekat sini.",
  ui_story_1022_10220800_28_dialog_content = "Tapi yang kutemukan malah seorang gila yang tertawa histeris di tanah.",
  ui_story_1022_10220800_29_dialog_content = "Siapa di sana?!",
  ui_story_1022_10220800_30_dialog_content = "Tapi tidak apa-apa, berbuatlah segila yang kamu mau. Lagipula, hati dan darahmu—",
  ui_story_1022_10220800_31_dialog_content = "<color=#FFB400>Milikku sekarang!</color>",
  ui_story_1022_10220800_32_dialog_content = "<color=#e8d9bb>Seorang Eclipsite yang mirip dengan gadis kecil tersenyum licik, memperlihatkan taringnya yang tajam.</color>",
  ui_story_1022_10220800_33_dialog_content = "<color=#e8d9bb>Sejuk mengalir di tulang belakang Pepita saat melihat senyum kejam gadis kecil itu.</color>",
  ui_story_1022_10220800_34_dialog_content = "Haha…",
  ui_story_1022_10220800_35_dialog_content = "Masih tertawa?! Apa yang lucu dari semua ini, hah? Tidak tahukah kamu bahwa kamu akan menjadi santapan berikutnya dari Ursura yang hebat?!",
  ui_story_1022_10220800_36_dialog_content = "Maaf, saya hanya merasa lucu bahwa seorang gadis kecil dengan taring iblis berpikir saya yang gila di sini.",
  ui_story_1022_10220800_37_dialog_content = "A-Apa yang kamu tahu?! Taringku adalah simbol kelahiran bangsawanku, terima kasih banyak!",
  ui_story_1022_10220800_38_dialog_content = "Kelahiran bangsawan? Terdengar cukup keren, tetapi bukankah itu hanya membuat Anda menjadi monster yang keju dan menghisap darah?",
  ui_story_1022_10220800_39_dialog_content = "Ketika aku selesai menguras kehidupan darimu, kau akan terlihat seperti kulit murahan!",
  ui_story_1022_10220800_40_dialog_content = "Hahaha! Astaga pria, ini benar-benar terlalu gila!",
  ui_story_1022_10220800_41_dialog_content = "Biasanya orang tidak bisa berhenti membelikan saya makanan dan minuman di mana pun saya pergi. Itulah jenis penghormatan yang saya tuntut di dunia!",
  ui_story_1022_10220800_42_dialog_content = "Tapi ini pertama kalinya seseorang menawarkan untuk menghisap darahku! Cara kau menunjukkan kekagumanmu cukup aneh, tahu itu?",
  ui_story_1022_10220800_43_dialog_content = "\"Kekaguman,\" pantatku! Orang yang hanya aku kagumi adalah kakekku, mengerti?!",
  ui_story_1022_10220800_44_dialog_content = "Aku akan meminum setetes terakhir darahmu dan menjadikanmu budak abadi ku! Kita akan lihat siapa yang tertawa setelah itu, kau bajingan!",
  ui_story_1022_10220800_45_dialog_content = "Budak...?",
  ui_story_1022_10220800_46_dialog_content = "Hmph, akhirnya kamu takut juga, ya? Bagus! Kamu akan lebih enak setelah aku membuatmu memohon belas kasihan.",
  ui_story_1022_10220800_47_dialog_content = "Ya... Tidak, terima kasih.",
  ui_story_1022_10220800_48_dialog_content = "Apa?! K-Kapan kamu mengambil itu dariku? Kembalikan!",
  ui_story_1022_10220800_49_dialog_content = "Bunuh aku jika kau mau, tapi aku tidak akan membiarkanmu menjadikanku budakmu.",
  ui_story_1022_10220800_50_dialog_content = "<color=#FFB400>Jika aku tidak bebas, aku lebih memilih mati!</color>",
  ui_story_1022_10220800_51_dialog_content = "<color=#e8d9bb>Pepita mengambil sepotong karang yang telah diasah dan menusukkannya ke dalam dada sendiri, menyemburkan darah merah terang di sekelilingnya.</color>",
  ui_story_1022_10220800_52_dialog_content = "…!",
  ui_story_1022_10220800_53_dialog_content = "Urgh... Darah... Menjijikkan, darah merah... Ahhhhhh—!!!",
  ui_story_1022_10220800_54_dialog_content = "Graaaah!!",
  ui_story_1022_10220800_55_dialog_content = "Selamatkan kami!",
  ui_story_1022_10220800_56_dialog_content = "Mohon lepaskan kami, Lady Ursura! Lepaskan hidup kami yang menyedihkan ini!!",
  ui_story_1022_10220800_57_dialog_content = "Aku... Aku benci melihat darah! Pastikan mereka tidak berdarah saat kalian membunuh mereka, kalian idiot!",
  ui_story_1022_10220800_58_dialog_content = "(Eclipsian) Mengerti!",
  ui_story_1022_10220800_59_dialog_content = "Aaaaaahhh!!!",
  ui_story_1022_10220800_60_dialog_content = "Urk! Bukankah aku sudah bilang jangan biarkan mereka berdarah? Kamu adalah teman baru saya, jadi perhatikan saat saya memberi tahu hal seperti ini!",
  ui_story_1022_10220800_61_dialog_content = "(Eclipsian) Ya, Lady Ursura! Kami akan melakukan yang terbaik...",
  ui_story_1022_10220800_62_dialog_content = "Ck, kalian ini hanya bisa bicara saja...",
  ui_story_1022_10220800_63_dialog_content = "Aku harus tetap kuat... Dewa baruku bahkan lebih hebat daripada yang disebut Lord of Truth...",
  ui_story_1022_10220800_64_dialog_content = "Turunlah ke dunia kami dan bersihkanlah, tuanku!",
  ui_story_1022_10220800_65_dialog_content = "Nngh... Sepertinya aku tertidur terlalu lama... Hampir saja aku lupa...",
  ui_story_1022_10220800_66_dialog_content = "Aku sudah diberkati dengan cincin Eclipse. Aku tidak perlu minum darah lagi, itulah sebabnya aku bahkan tidak tahan melihatnya sekarang!",
  ui_story_1022_10220800_67_dialog_content = "*menangis* Meminumnya, berendam di dalamnya... Semua itu tidak membuatku bahagia lagi! Kakek!",
  ui_story_1022_10220800_68_dialog_content = "(Dia tiba-tiba menangis histeris... Dia tampak sangat sedih, memanggil-manggil kakeknya seperti itu.)",
  ui_story_1022_10220800_69_dialog_content = "(Jenis pria apa yang akan meninggalkannya sendirian di sini? Mungkin seseorang seperti ayahku yang tidak berguna.)",
  ui_story_1022_10220800_70_dialog_content = "H-Hey, kamu baik-baik saja? Batuk, batuk... Oh benar, aku yang punya masalah di sini... Heheh.",
  ui_story_1022_10220800_71_dialog_content = "Tentu saja aku baik-baik saja! Kenapa aku tidak akan baik-baik saja?!",
  ui_story_1022_10220800_72_dialog_content = "Argh! Ap-Apa yang kamu coba lakukan padaku sekarang...?",
  ui_story_1022_10220800_73_dialog_content = "J-Jangan pikir kamu bisa menghentikanku dengan berdarah di mana-mana! A-Aku bisa melihat dan meminum darah dengan baik!",
  ui_story_1022_10220800_74_dialog_content = "Hei! Berhenti menjilati lukaku seperti itu, kamu aneh...!",
  ui_story_1022_10220800_75_dialog_content = "Ugh... Sungguh menjijikkan...",
  ui_story_1022_10220800_76_dialog_content = "<color=#e8d9bb>Sebuah air mata berwarna putih susu muncul di sudut mata Ursura.</color>",
  ui_story_1022_10220800_77_dialog_content = "Jika itu sangat menjijikkan, maka berhentilah sudah—",
  ui_story_1022_10220800_78_dialog_content = "Nngh... Arrrgh— Gaaaaahhhh!",
  ui_story_1022_10220800_79_dialog_content = "<color=#e8d9bb>Tiba-tiba, seolah tersentuh oleh semacam kekuatan primitif, Ursura mulai berteriak dan menggeliat saat lebih banyak air mata putih mengalir dari matanya.</color>",
  ui_story_1022_10220800_80_dialog_content = "I-Itu benar-benar seburuk itu?!",
  ui_story_1022_10220800_81_dialog_content = "Graaaaagh!",
  ui_story_1022_10220800_82_dialog_content = "(Sh-Dia kehilangan kendali! Aku harus keluar dari sini, tapi... Sial, aku kehilangan terlalu banyak darah!)",
  ui_story_1022_10220800_83_dialog_content = "P... Petey... Saatnya melakukan halmu!",
  ui_story_1022_10220800_84_dialog_content = "Boneka? Urgh...",
  ui_story_1022_10220800_85_dialog_content = "<color=#e8d9bb>Meskipun seluruh tubuhnya gemetar dengan hebat, Ursura berhasil memanggil boneka kecil berwarna abu-abu untuk menyeretnya pergi.</color>",
  ui_story_1022_10220800_86_dialog_content = "<color=#e8d9bb>Duaar!! Saat air mata putih jatuh ke tanah tempat Pepita berbaring, mereka meledak dengan kekuatan yang menghancurkan secara mengejutkan.</color>",
  ui_story_1022_10220800_87_dialog_content = "(Dia... Menyelamatkanku?)",
  ui_story_1022_10220800_88_dialog_content = "(Apa yang terjadi padanya sih? Bukankah ledakan itu juga akan melukainya? Sialan... Aku tidak bisa membuka mataku lagi. Aku pasti sudah terlalu memaksakan diri.)",
  ui_story_1022_10220800_89_dialog_content = "(Apakah hari ini... Hari aku akhirnya mati?)",
  ui_story_1022_10220800_90_dialog_content = "<color=#e8d9bb>Setelah waktu yang sangat lama...</color>",
  ui_story_1022_10220800_91_dialog_content = "...",
  ui_story_1022_10220800_92_dialog_content = "(Aku masih hidup, huh? Kurasa aku tidak seharusnya kaget...)",
  ui_story_1022_10220800_93_dialog_content = "Apa masalah dengan hatimu itu?",
  ui_story_1022_10220800_94_dialog_content = "Ursura...",
  ui_story_1022_10220800_95_dialog_content = "Itu bukan jantung aslimu. Apakah itu teknologi Illumina?",
  ui_story_1022_10220800_96_dialog_content = "... Kenapa kamu menyelamatkanku?",
  ui_story_1022_10220800_97_dialog_content = "Ketika saya menjadi bagian dari Eclipse, saya berpikir akhirnya saya akan memiliki teman yang tidak akan pernah mengecewakan saya.",
  ui_story_1022_10220800_98_dialog_content = "Tapi ternyata mereka semua hanyalah sekumpulan cacing yang tidak berguna. Seorang wanita bangsawan seperti saya pantas mendapatkan yang jauh lebih baik.",
  ui_story_1022_10220800_99_dialog_content = "Tapi kamu... Kamu baik-baik saja.",
  ui_story_1022_10220800_100_dialog_content = "<size=30>Anda bahkan peduli padaku.</size>",
  ui_story_1022_10220800_101_dialog_content = "Haha…",
  ui_story_1022_10220800_102_dialog_content = "Jangan tertawa lagi!",
  ui_story_1022_10220800_103_dialog_content = "Jadi apa, kamu mengakui saya atau bagaimana?",
  ui_story_1022_10220800_104_dialog_content = "Dan apa salahnya dengan itu? Kamu seharusnya merasa terhormat, tahu! Kebanyakan orang akan menari dan berteriak sekuat tenaga karena hal seperti ini!",
  ui_story_1022_10220800_105_dialog_content = "Tidak masalah sebaik apa hati yang Illumina buat untukmu, karena kamu akan selalu berada di bawah kendali mereka.",
  ui_story_1022_10220800_106_dialog_content = "Tapi aku bisa membuatkanmu hati yang baru, satu yang bisa kau sebut milikmu sendiri!",
  ui_story_1022_10220800_107_dialog_content = "Apa kamu ingat bagaimana aku menjawabmu tadi?",
  ui_story_1022_10220800_108_dialog_content = "Tentu saja! Kamu bilang, \"Tidak, terima kasih, aku masih ingin bertahan dengan ini sedikit lebih lama.\"",
  ui_story_1022_10220800_109_dialog_content = "Namun di sinilah kamu, kembali di sisiku lagi! Lucu bagaimana itu bisa terjadi, ya?",
  ui_story_1022_10220800_110_dialog_content = "Kamu tidak akan pernah mendapatkan apa yang kamu inginkan dengan mengandalkan hati ini, Pepita.",
  ui_story_1022_10220800_111_dialog_content = "Tentu saja tidak! Saya tahu langsung betapa buruknya hati palsu ini.",
  ui_story_1022_10220800_112_dialog_content = "<color=#e8d9bb>Seringkali aku mengutuk hati ini dan berharap bisa memiliki yang sempurna.</color>",
  ui_story_1022_10220800_113_dialog_content = "<color=#e8d9bb>Jantung yang kuat dan sehat yang tidak bisa dikendalikan oleh siapa pun. Yang akan membiarkan saya bertarung selama yang saya inginkan tanpa pernah merasa lelah. Itulah jenis jantung yang selalu saya inginkan.</color>",
  ui_story_1022_10220800_114_dialog_content = "<color=#e8d9bb>Itulah sebabnya saya masih datang ke sini, meskipun saya tahu Ursura akan memberlakukan semacam kondisi.</color>",
  ui_story_1022_10220800_115_dialog_content = "<color=#e8d9bb>Karena tidak seperti Belisaria, yang selalu meremehkan saya, setidaknya Ursura memperlakukan saya sebagai setaranya.</color>",
  ui_story_1022_10220800_116_dialog_content = "<color=#e8d9bb>Mengenai kondisinya—</color>",
  ui_story_1022_10220800_117_dialog_content = "<color=#FFB400>\"Untuk tinggal di sini selamanya.\"</color>",
  ui_story_1022_10220800_118_dialog_content = "<color=#e8d9bb>Begitu aku mendengarnya mengatakannya, suasana hatiku berubah total. Saat aku menatap pemandangan beku dan karang yang tumbuh dari situ, pikiran yang sama terus mengulang dirinya dalam kepalaku.</color>",
  ui_story_1022_10220800_119_dialog_content = "<color=#e8d9bb>\"Apakah ini benar-benar yang akan menjadi sisa hidupku?\"</color>",
  ui_story_1022_10220800_120_dialog_content = "<color=#e8d9bb>... Tidak.</color>",
  ui_story_1022_10220800_121_dialog_content = "<color=#e8d9bb>Dunia ini tempat yang sangat besar.</color>",
  ui_story_1022_10220800_122_dialog_content = "<color=#e8d9bb>Dan saya masih belum memiliki kesempatan untuk melihat ladang hijau saya.</color>",
  ui_story_1022_10220800_123_dialog_content = "Jawabanku masih sama seperti sebelumnya.",
  ui_story_1022_10220800_124_dialog_content = "Terima kasih, tapi tidak, Ursura.",
  ui_story_1022_10220800_125_dialog_content = "Aku masih ingin bertahan dengan ini sedikit lebih lama.",
  ui_story_1022_10220901_1_dialog_content = "Kau menipuku!",
  ui_story_1022_10220901_2_dialog_content = "Aku tahu, dan aku benar-benar minta maaf! Tapi kita masih banyak bersenang-senang bersama, kan?",
  ui_story_1022_10220901_3_dialog_content = "Tapi lebih baik jika kita tidak selalu bersama setiap hari dalam hidup kita, 'kan? Lagipula, mereka bilang sedikit jarak membuat persahabatan menjadi lebih berharga!",
  ui_story_1022_10220901_4_dialog_content = "...",
  ui_story_1022_10220901_5_dialog_content = "Ambil dia.",
  ui_story_1022_10220901_6_dialog_content = "(Eclipsian) Mengerti!",
  ui_story_1022_10220901_7_dialog_content = "Hah? Menjemput siapa? Bukan seperti aku punya kerabat untuk kau culik, ingat?",
  ui_story_1022_10220901_8_dialog_content = "... Petey?! Ursura... Kapan kamu membawanya kembali?",
  ui_story_1022_10220901_9_dialog_content = "Beberapa waktu lalu, sebenarnya. Saya hanya tidak ingin menunjukkan karena saya sangat peduli padamu.",
  ui_story_1022_10220901_10_dialog_content = "Tapi meski aku ini teman yang baik... Kamu terus mencoba meninggalkanku! Kenapa?!?",
  ui_story_1022_10220901_11_dialog_content = "... Aku sudah bilang kenapa, bukan?",
  ui_story_1022_10220901_12_dialog_content = "<color=#FFB400>Jika aku tidak bebas... Aku lebih memilih mati!</color>",
  ui_story_1022_10220901_13_dialog_content = "Graaah...",
  ui_story_1022_10220901_14_dialog_content = "Hentikan dia!",
  ui_story_1022_10220901_15_dialog_content = "(Eclipsian) Lakukan seperti perintah Lady Ursura!",
  ui_story_1022_10220901_16_dialog_content = "Graaaah!!",
  ui_story_1022_10220901_17_dialog_content = "Hanya ini kemampuanmu?",
  ui_story_1022_10220901_18_dialog_content = "Graaah...",
  ui_story_1022_10220901_19_dialog_content = "A-Apa yang kamu pikir kamu lakukan?! Anda akan mati pada tingkat ini!",
  ui_story_1022_10220901_20_dialog_content = "Jadi, panggil Eclipsite-mu dan biarkan aku pergi!",
  ui_story_1022_10220901_21_dialog_content = "Graah...",
  ui_story_1022_10220901_22_dialog_content = "Urgh... Heheh, maaf harus memberitahumu Ursura, tapi kamu akan membutuhkan minion yang lebih kuat jika ingin menghentikanku.",
  ui_story_1022_10220901_23_dialog_content = "Maaf, aku tidak bisa bertahan lama! Dah-dah!",
  ui_story_1022_10220901_24_dialog_content = "Jangan berani-berani!",
  ui_story_1022_10220901_25_dialog_content = "Nng...",
  ui_story_1022_10220901_26_dialog_content = "Hatimu lagi-lagi menyakitimu, bukan? Rongsokan itu tidak cukup kuat untuk mengimbangi dirimu.",
  ui_story_1022_10220901_27_dialog_content = "Kamu seharusnya sudah tahu batasanmu sekarang!",
  ui_story_1022_10220901_28_dialog_content = "Ya benar!",
  ui_story_1022_10220901_29_dialog_content = "Urk...!",
  ui_story_1022_10220901_30_dialog_content = "Dapatkan dia, semua kalian!",
  ui_story_1022_10220901_31_dialog_content = "... Tetap menjauh dari jalanku!",
  ui_story_1022_10220901_32_dialog_content = "Apakah kamu gila?! Jantungmu akan meledak jika kamu terus bertarung seperti ini!",
  ui_story_1022_10220901_33_dialog_content = "Anda akan terbakar habis sebelum saya mulai mengambil pertempuran ini dengan serius!",
  ui_story_1022_10220901_34_dialog_content = "Itu... Tak masalah buatku!",
  ui_story_1022_10220901_35_dialog_content = "Aku... Aku berdarah?",
  ui_story_1022_10220901_36_dialog_content = "Sialan kau... Bagaimana kau berani membuatku berdarah! Sudah cukup! Jika kau sangat ingin mati, biar aku yang membantumu!!!",
  ui_story_1022_10220901_37_dialog_content = "Arrrgh—!",
  ui_story_1022_10220901_38_dialog_content = "<color=#e8d9bb>Buk-buk, Buk-buk, Buk-buk, Buk-buk—</color>",
  ui_story_1022_10220901_39_dialog_content = "<color=#e8d9bb>Detak jantung di dalam dadanya menjadi semakin liar dan intens.</color>",
  ui_story_1022_10220901_40_dialog_content = "<color=#e8d9bb>Jantungnya tidak hanya berdegup, tetapi juga bergetar dengan keras seperti kereta yang hampir tergelincir.</color>",
  ui_story_1022_10220901_41_dialog_content = "<color=#e8d9bb>Setiap gelombang rasa sakit yang tak tertahankan cukup untuk merobek pikiran siapa pun.</color>",
  ui_story_1022_10220901_42_dialog_content = "<color=#e8d9bb>Tapi dia tidak lagi memperhatikan rasa sakit, atau apapun itu sebenarnya.</color>",
  ui_story_1022_10220901_43_dialog_content = "<color=#e8d9bb>Kemampuan pikirannya yang jernih memungkinkan dia untuk sepenuhnya fokus pada satu pikiran saja.</color>",
  ui_story_1022_10220901_44_dialog_content = "Selama aku terbakar secerah mungkin... Lalu apa salahnya dengan mati?",
  ui_story_1022_10220901_45_dialog_content = "Aku bukan hewan peliharaan siapa pun, dan aku tidak akan pernah menyerah kepada siapa pun...",
  ui_story_1022_10220901_46_dialog_content = "<color=#FFB400>Aku... Milik diriku sendiri!</color>",
  ui_story_1022_10220902_1_dialog_content = "Resonator White Night semakin intens merespon. Artefak yang dicuri seharusnya berada di dekat sini.",
  ui_story_1022_10220902_2_dialog_content = "Um…",
  ui_story_1022_10220902_3_dialog_content = "Sekarang semakin kuat! Target kita mungkin adalah objek kecil, jadi berpencar dan cari area tersebut!",
  ui_story_1022_10220902_4_dialog_content = "Kadang, jawaban yang kita cari tersembunyi di depan mata...",
  ui_story_1022_10220902_5_dialog_content = "Sekarang bukan waktunya untuk teka-teki, Erica. Hanya fokus mencari artefak yang hilang.",
  ui_story_1022_10220902_6_dialog_content = "Ini bukan teka-teki, Nyonya. Saya sedang berbicara tentang cahaya suci di depan Anda...",
  ui_story_1022_10220902_7_dialog_content = "Apa?!",
  ui_story_1022_10220902_8_dialog_content = "Pfft...",
  ui_story_1022_10220902_9_dialog_content = "Berhenti tertawa! Kamu juga tidak menyadarinya, bukan?",
  ui_story_1022_10220902_10_dialog_content = "It-Itu karena aku terlalu sibuk mengawasi Resonator... Tapi itu tidak penting sekarang! Kita perlu memastikan apakah itu adalah artefak Lumopolis yang hilang atau bukan.",
  ui_story_1022_10220902_11_dialog_content = "Lumina yang dipancarkannya begitu murni dan menenangkan...",
  ui_story_1022_10220902_12_dialog_content = "Apakah kita menemukannya?!",
  ui_story_1022_10220902_13_dialog_content = "Tidak ada salahnya. Objek ini menghilangkan Darkflow di area sekitarnya.",
  ui_story_1022_10220902_14_dialog_content = "Dengan kata lain, ini benar-benar salah satu relik suci dan hilang lama dari True Order.",
  ui_story_1022_10220902_15_dialog_content = "Suara itu...",
  ui_story_1022_10220902_16_dialog_content = "Hari ini, objek suci ini kembali kepada pemilik yang sebenarnya, dan semua hal kembali ke jalur aslinya. Inilah misteri dari pekerjaan tuhan kita.",
  ui_story_1022_10220902_17_dialog_content = "Siapa kau kira dirimu?! Lepaskan harta sakral Lumopolis sekarang juga!",
  ui_story_1022_10220902_18_dialog_content = "Jangan terburu-buru, Victoria. Kami masih memiliki banyak yang harus dibahas, seperti keberadaan teks suci kami!",
  ui_story_1022_10220902_19_dialog_content = "Victoria...? P-Pemimpin dari True Order yang sesat...?!",
  ui_story_1022_10220902_20_dialog_content = "\"Orang sesat,\" katamu? Heheheh... Saya kira pencarian noble kami akan Truth bisa dilihat seperti itu oleh pikiran-pikiran yang tidak tahu apa-apa di dunia ini.",
  ui_story_1022_10220902_21_dialog_content = "Mengenai artefak ini, saya tidak pernah mengambil apa pun yang bukan milik saya terlebih dahulu. Objek ini dicuri dari Kota Varaki oleh tuan dari domain ini.",
  ui_story_1022_10220902_22_dialog_content = "Petunjuk yang membawa saya ke tempat ini diberikan kepada saya oleh tidak lain adalah Pepita, seorang anggota dari ordo kami.",
  ui_story_1022_10220902_23_dialog_content = "Apa yang membuat tindakanku tampak tidak masuk akal menurutmu, Lady Carleen?",
  ui_story_1022_10220902_24_dialog_content = "... Diam, orang sesat!",
  ui_story_1022_10220902_25_dialog_content = "Kata-kata pengkhianatanmu tidak akan lagi menodai yang tidak bersalah...",
  ui_story_1022_10220902_26_dialog_content = "Sekarang mati!!!",
  ui_story_1022_10220902_27_dialog_content = "Hosh... Hosh...",
  ui_story_1022_10220902_28_dialog_content = "(Ada karang di sekelilingku... Apakah itu berarti aku belum berhasil melarikan diri?)",
  ui_story_1022_10220902_29_dialog_content = "(Ursura baru saja menahan pukulannya, tapi itu tidak berarti dia tidak akan berubah pikiran nanti... Jika dia menangkapku lagi, aku benar-benar akan mati.)",
  ui_story_1022_10220902_30_dialog_content = "(Hah? Suara apa itu?)",
  ui_story_1022_10220902_31_dialog_content = "Gah! Kutukan... Orang sesat menjijikkan seperti kamu seharusnya tidak sekuat ini...",
  ui_story_1022_10220902_32_dialog_content = "Kebencian yang tak terkendali... Katakan padaku, apa yang telah dilakukan True Order hingga membangkitkan kemarahanmu?",
  ui_story_1022_10220902_33_dialog_content = "Langkah kaki itu... Itu dia!",
  ui_story_1022_10220902_34_dialog_content = "Erica? L-Lady Victoria?! Apa yang sedang kamu lakukan di sini? Aku pikir Petey tertangkap sebelum dia bisa mengirim pesanku...",
  ui_story_1022_10220902_35_dialog_content = "Takdir selalu menemukan jalan di bawah bimbingan tuhan kita.",
  ui_story_1022_10220902_36_dialog_content = "Tapi saya melihat bahwa kamu terluka, Pepita. Siapa yang bisa melakukan ini kepada... Tidak apa-apa. Sepertinya tidak perlu bertanya lagi.",
  ui_story_1022_10220902_37_dialog_content = "Kamu mau ke mana, Pepita?! Dengan semua darah yang telah kamu hilang, seharusnya kamu sudah mati sepuluh kali lipat!",
  ui_story_1022_10220902_38_dialog_content = "Aku benar-benar akan marah jika kau tidak berhenti berlari! Di sini, aku akan menunjukkan persis apa yang akan kulakukan padamu jika kau tidak diam!",
  ui_story_1022_10220902_39_dialog_content = "…!",
  ui_story_1022_10220902_40_dialog_content = "Datanglah padaku, Pepita.",
  ui_story_1022_10220902_41_dialog_content = "Kamu pikir kamu siapa, menghalangi jalanku?! Tunggu... I-Ini kamu...!",
  ui_story_1022_10220902_42_dialog_content = "Saya tidak melakukan apa-apa untuk menghalangi jalanmu. Yang telah saya lakukan hanyalah berdiri di sini tanpa bergerak.",
  ui_story_1022_10220902_43_dialog_content = "Pepita adalah orang yang memilih untuk meninggalkanmu dan berpihak padaku.",
  ui_story_1022_10220902_44_dialog_content = "Dan orang yang memaksanya membuat keputusan ini tidak lain adalah kamu.",
  ui_story_1022_10220902_45_dialog_content = "Sejak awal, rintangan terbesar Anda selalu adalah diri Anda sendiri.",
  ui_story_1022_10220902_46_dialog_content = "...",
  ui_story_1022_10220902_47_dialog_content = "Kamu... Kamu salah! Pepita adalah milikku, bukan milikmu...",
  ui_story_1022_10220902_48_dialog_content = "Misteri Kebenaran itu luas dan tak terduga. Sangat wajar jika kamu merasa bingung dan tersesat.",
  ui_story_1022_10220902_49_dialog_content = "Tetapi diingatkan, bagi mereka yang menghindari pengetahuan dan memeluk kekejaman dan ketidaktahuan—",
  ui_story_1022_10220902_50_dialog_content = "Akan suatu hari menemukan diri mereka tersesat dalam malam abadi, tempat di mana bahkan cahaya Kebenaran tidak bersinar.",
  ui_story_1022_10220902_51_dialog_content = "Aku... Kamu... Waaaaaaaaaaah—!!!",
  ui_story_1022_10220902_52_dialog_content = "<color=#e8d9bb>Agresi mengancam Hantu berubah menjadi tangisan histeris dalam sekejap. Saat dia melarikan diri jauh ke kejauhan, teriakannya untuk kakeknya masih bisa didengar.</color>",
  ui_story_1022_10220902_53_dialog_content = "D-Dia mulai menangis dan lari?!",
  ui_story_1022_10220902_54_dialog_content = "Heheh... Maafkan saya, tapi sudah cukup lama sejak saya menegur seorang anak kecil.",
  ui_story_1022_10220902_55_dialog_content = "Hantu itu dan Varaki terikat oleh takdir hingga batas tertentu, tetapi ketika aku melihat betapa parahnya dia melukai Pepita, aku tidak bisa menahan diri.",
  ui_story_1022_10220902_56_dialog_content = "(Varaki lain?!)",
  ui_story_1022_10220902_57_dialog_content = "Tetaplah berbaring, Pepita. Biarkan saya merawat lukamu.",
  ui_story_1022_10220902_58_dialog_content = "Lambang itu... Apakah kamu menggunakannya untuk menemukan saya, Lady Victoria?",
  ui_story_1022_10220902_59_dialog_content = "Ya. Emblem ini adalah ciptaan saya, yang terhubung erat dengan energi hidup Anda. Ini memungkinkan saya untuk mengikuti energi dari jantung buatan Anda.",
  ui_story_1022_10220902_60_dialog_content = "Ini juga memberi tahu saya setiap kali kamu dalam bahaya besar.",
  ui_story_1022_10220902_61_dialog_content = "Jadi ya, Pepita: Aku datang ke sini hanya untukmu, dan tampaknya takdir cukup baik untuk menyatukan kembali Ordo dengan salah satu peninggalan yang hilang.",
  ui_story_1022_10221001_1_dialog_content = "Itu mengingatkanku! Kamu tahu Charon, bukan Lady Victoria?",
  ui_story_1022_10221001_2_dialog_content = "Apakah kamu tahu di mana dia dan Vice berada sekarang? Atau mengapa koordinat Other End terus berpindah di seluruh peta kita?",
  ui_story_1022_10221001_3_dialog_content = "Mereka tidak bertemu dengan Wraith lain, bukan?!",
  ui_story_1022_10221001_4_dialog_content = "Saya akan senang untuk memberitahumu tentang—Hmm? Kembali lagi, aku lihat? Katakan padaku, apa yang kamu rencanakan kali ini?",
  ui_story_1022_10221001_5_dialog_content = "Aku... Seharusnya aku yang bertanya hal yang sama padamu! Pencuri ini mencuri teks sakral dari Lumopolis! Apakah kamu benar-benar berpikir kamu bisa melindunginya dari hukuman?!",
  ui_story_1022_10221001_6_dialog_content = "Lebih jauh lagi, teks sakral kami telah jatuh ke tangan kelompokmu... Yang berarti kalian semua sama-sama bersalah!",
  ui_story_1022_10221001_7_dialog_content = "Hei! Siapa bilang kamu bisa bicara tentang kami seperti itu?!",
  ui_story_1022_10221001_8_dialog_content = "Ketegangan antara kedua belah pihak semakin mendekati titik puncaknya... Tapi apa yang bisa saya lakukan?",
  ui_story_1022_10221001_9_dialog_content = "Belumkah Pepita memberi tahu Anda? \"Teks suci\" yang Anda sebut tidak berbeda dengan relik yang saya pegang di tangan saya sekarang, dalam hal mereka semua aslinya milik True Order.",
  ui_story_1022_10221001_10_dialog_content = "Tidak masuk akal! Bagaimana mungkin Anda bisa mengklaim bahwa begitu banyak hal milik ordo terkutuk Anda? Katakan padaku, apakah seluruh Astra juga milikmu?!",
  ui_story_1022_10221001_11_dialog_content = "Jika kamu tidak mau mendengarkan alasan... Maka aku akan menahanmu dengan paksa.",
  ui_story_1022_10221001_12_dialog_content = "Ke senjata, Erica!",
  ui_story_1022_10221001_13_dialog_content = "Siap, Pak!",
  ui_story_1022_10221001_14_dialog_content = "Tunggu!",
  ui_story_1022_10221001_15_dialog_content = "... Jangan mengganggu, PlayerName.",
  ui_story_1022_10221001_16_dialog_content = "Terlepas dari keadaannya, kita memiliki tugas untuk menanyakan keberadaan artefak yang hilang.",
  ui_story_1022_10221001_17_dialog_content = "Lalu, gunakan kata-kata Anda, bukan senjata Anda! Atau apakah Anda sudah lupa tentang keinginan Tuan Kota?",
  ui_story_1022_10221001_18_dialog_content = "Namun…",
  ui_story_1022_10221001_19_dialog_content = "Jika kita tidak ingin menghambat eksplorasi bersama kita, kita perlu mencoba dan menyelesaikan masalah sebaik mungkin secara damai—",
  ui_story_1022_10221001_20_dialog_content = "\"Penjelajahan \"kita\"? Dan sebenarnya, Anda berada di pihak siapa?",
  ui_story_1022_10221001_21_dialog_content = "Apa?!",
  ui_story_1022_10221001_22_dialog_content = "Selama ini aku telah menaruh kepercayaanku padamu, hanya untukmu berpihak pada musuh di saat yang paling buruk.",
  ui_story_1022_10221001_23_dialog_content = "\"Kami membentuk tim ini untuk saling menjaga!\" Itu kata-katamu, kau pembohong tak tahu malu!",
  ui_story_1022_10221001_24_dialog_content = "Sekarang minggir sebelum aku—",
  ui_story_1022_10221001_25_dialog_content = "Sebelum kamu apa?",
  ui_story_1022_10221001_26_dialog_content = "Bukan kamu juga?!",
  ui_story_1022_10221001_27_dialog_content = "PlayerName benar. Eksplorasi Dark Zone menjadi prioritas di atas segalanya. Grand Marshal dari Illumina dan City Lord dari Lumopolis sama-sama setuju dengan ini.",
  ui_story_1022_10221001_28_dialog_content = "Jadi jika kamu ingin melanjutkan \"penyelidikanmu,\" kusarankan untuk pertama-tama menaruh senjatamu.",
  ui_story_1022_10221001_29_dialog_content = "...",
  ui_story_1022_10221001_30_dialog_content = "Kapten...",
  ui_story_1022_10221001_31_dialog_content = "... Orang sesat... Harus dihukum mati!!",
  ui_story_1022_10221002_1_dialog_content = "Argh! Kutukan... Kamu...",
  ui_story_1022_10221002_2_dialog_content = "(Dia terlalu kuat, dan Dark Zone telah melemahkanku secara parah...",
  ui_story_1022_10221002_3_dialog_content = "Aku tidak akan... membiarkanmu lolos!",
  ui_story_1022_10221002_4_dialog_content = "Tuhan kita telah menunjukkan kepada saya bahwa Pepita ditakdirkan untuk kemuliaan yang lebih besar lagi.",
  ui_story_1022_10221002_5_dialog_content = "Sampai jumpa lagi. May cahaya Truth memandu kalian semua.",
  ui_story_1022_10221002_6_dialog_content = "... Pengecut!",
  ui_story_1022_10221002_7_dialog_content = "Tunggu Lady Victoria, kamu belum menjawabku! Bagaimana dengan Vice dan Charon?!",
  ui_story_1022_10221002_8_dialog_content = "Whoa! A-Apakah saya sedang terbang?! Apa yang kamu lakukan, Hiiro—",
  ui_story_1022_10221002_9_dialog_content = "Tetap diam. Kita tidak terbang, aku hanya bergerak secepat yang kubisa.",
  ui_story_1022_10221002_10_dialog_content = "Ini satu-satunya cara kita bisa menyusul Victoria.",
  ui_story_1022_10221002_11_dialog_content = "Hmm?",
  ui_story_1022_10221002_12_dialog_content = "Apa itu, Lady Victoria?",
  ui_story_1022_10221002_13_dialog_content = "Lanjutkan tanpa saya, Pepita. Jika kamu tinggal di sini lebih lama lagi, hal-hal hanya akan menjadi lebih merepotkan.",
  ui_story_1022_10221002_14_dialog_content = "Dengan cepat.",
  ui_story_1022_10221002_15_dialog_content = "... Oke!",
  ui_story_1022_10221002_16_dialog_content = "Dia di sini!",
  ui_story_1022_10221002_17_dialog_content = "Lady Victoria! Kamu tahu persis di mana Vice, bukan?!",
  ui_story_1022_10221002_18_dialog_content = "Jangan terburu-buru, teman muda ku. Ketika waktunya tiba untuk kitab suci diungkapkan, kamu akan kembali bersatu dengannya.",
  ui_story_1022_10221002_19_dialog_content = "Tapi sekarang bukanlah waktunya... Selamat tinggal.",
  ui_story_1022_10221002_20_dialog_content = "(Jadi dia memang tahu tentang Vice!)",
  ui_story_1022_10221002_21_option_content = "Force Boost!",
  ui_story_1022_10221002_22_dialog_content = "Heheh...",
  ui_story_1022_10221002_23_dialog_content = "A-apa ini…?",
  ui_story_1022_10221002_24_dialog_content = "<color=#e8d9bb>Pilar monolitik es naik ke langit, melayang kontras dengan kegelapan yang mengalir dari malam yang abadi.</color>",
  ui_story_1022_10221002_25_dialog_content = "<color=#e8d9bb>Terperangkap dalam salah satu formasi es raksasa adalah tidak lain dari—</color>",
  ui_story_1022_10221002_26_dialog_content = "... Vice!",
  ui_story_1022_10221002_27_dialog_content = "(Tapi bagaimana?! Apa yang dia lakukan di tempat seperti ini...?)",
  ui_story_1022_10221002_28_option_content = "Pindai Lagi",
  ui_story_1022_10221002_29_dialog_content = "Suara piano adalah seni dalam bentuk yang paling murni. Itu bisa melampaui batas waktu dan ruang.",
  ui_story_1022_10221002_30_dialog_content = "Apa yang sedang kamu lakukan, Vice?",
  ui_story_1022_10221002_31_dialog_content = "PlayerName dalam bahaya! Aku harus melakukan sesuatu sebelum dia tersesat dalam kegelapan Insinyur!",
  ui_story_1022_10221002_32_dialog_content = "Aku akan menggunakan piano ini untuk memperingatkannya...",
  ui_story_1022_10221002_33_dialog_content = "Insinyur sedang mengawasi teman Caelestite kita dengan sangat dekat. Bahkan sangat dekat, sampai-sampai pikiran mereka sekarang terhubung.",
  ui_story_1022_10221002_34_dialog_content = "Kemungkinan besar Insinyur akan memperhatikan kamu jika kamu ikut campur.",
  ui_story_1022_10221002_35_dialog_content = "Tapi—!",
  ui_story_1022_10221002_36_dialog_content = "Jujur, Lady Victoria, apakah kamu tidak memiliki rasa romantis?",
  ui_story_1022_10221002_37_dialog_content = "Apakah kamu pikir tuanmu akan senang jika kamu memotong musik indah ini dan meninggalkan teman kita ke dalam kegelapan?",
  ui_story_1022_10221002_38_dialog_content = "Oh? Tampaknya kamu tidak hanya berani menyebut nama tuan kami, tetapi juga berjuang melawan Insinyur.",
  ui_story_1022_10221002_39_dialog_content = "Apa kamu akhirnya siap untuk menerima Kebenaran dan bangkit dengan kekuatan garis keturunanmu?",
  ui_story_1022_10221002_40_dialog_content = "Itu cukup mengada-ada, mengingat saya hanya mengucapkan satu kalimat! Izinkan saya mengulangi: Saya sama sekali tidak tertarik pada apa yang disebut \"Kebenaran\" yang kamu tekankan tanpa henti.",
  ui_story_1022_10221002_41_dialog_content = "Maka itu memang sebuah tragedi.",
  ui_story_1022_10221002_42_dialog_content = "... Di sana! PlayerName berhasil membebaskan diri!",
  ui_story_1022_10221002_43_dialog_content = "Tapi Soroz sudah pergi sekarang...",
  ui_story_1022_10221002_44_dialog_content = "Jangan khawatir, sayang Vice. PlayerName tidak akan pernah meninggalkan Colossus-nya, dan kita tidak akan pernah meninggalkan dia.",
  ui_story_1022_10221002_45_dialog_content = "Itu membuat segalanya menjadi sedikit lebih rumit.",
  ui_story_1022_10221002_46_dialog_content = "Merusak momen lagi, Nyonya?",
  ui_story_1022_10221002_47_dialog_content = "Truth melindungi setiap anggota dari Ordo Sejati. Sebagai orang-orang Illumina, bagaimanapun, kamu belum terpilih.",
  ui_story_1022_10221002_48_dialog_content = "Jika kalian bersikukuh untuk membahayakan diri sendiri... Maka aku takut aku tidak punya pilihan lain.",
  ui_story_1022_10221002_49_dialog_content = "<color=#e8d9bb>Percikan—</color>",
  ui_story_1022_10221002_50_dialog_content = "Aahhh!",
  ui_story_1022_10221002_51_dialog_content = "A-Apa maksudnya ini?!",
  ui_story_1022_10221002_52_dialog_content = "<color=#e8d9bb>Dengan melambaikan tangannya, Victoria membelah Sungai Pristine menjadi dua.</color>",
  ui_story_1022_10221002_53_dialog_content = "<color=#e8d9bb>Charon dan Vice jatuh tanpa henti ke dalam kedalamannya.</color>",
  ui_story_1022_10221002_54_dialog_content = "<color=#e8d9bb>Saat mereka jatuh, suara misterius berbisik di telinga mereka—</color>",
  ui_story_1022_10221002_55_dialog_content = "Selama masih mengandung setetes air pun dari Sungai Pristine, bahkan Darkflow yang paling kuat sekalipun tidak akan melelehkan es ini.",
  ui_story_1022_10221002_56_dialog_content = "Bwaaaaaa—Hah? A-Apakah kita berhenti jatuh?",
  ui_story_1022_10221002_57_dialog_content = "... Tempat apa ini?",
  ui_story_1022_10221002_58_dialog_content = "<color=#e8d9bb>Dalam sekejap mata, lingkungan mereka berubah secara total.</color>",
  ui_story_1022_10221002_59_dialog_content = "<color=#e8d9bb>Langit yang gelap mengelilingi mereka, tebal dan bergerak seperti rawa yang hidup. Tampaknya terdistorsi, seolah-olah mereka melihatnya melalui jendela kaca yang berat dan tidak rata.</color>",
  ui_story_1022_10221002_60_dialog_content = "<color=#e8d9bb>Kaca itu, bagaimanapun, sebenarnya—</color>",
  ui_story_1022_10221002_61_dialog_content = "Es? K-Kapan kita terjebak dalam pilar es raksasa?!",
  ui_story_1022_10221002_62_dialog_content = "Hah? Suara itu...",
  ui_story_1022_10221002_63_dialog_content = "<color=#e8d9bb>Duk, duk, duk—</color>",
  ui_story_1022_10221002_64_dialog_content = "Hancurkan, kamu blok beku yang terkutuk! Tak ada penjara es yang bisa memenjarakan nyala emosi ku!",
  ui_story_1022_10221002_65_dialog_content = "O-Officer Charon! Kamu juga terjebak di sini?!",
  ui_story_1022_10221002_66_dialog_content = "<color=#e8d9bb>Duk, duk, duk—</color>",
  ui_story_1022_10221002_67_dialog_content = "<color=#e8d9bb>Di bawah serangan tanpa henti dari Other End, es mulai retak.</color>",
  ui_story_1022_10221002_68_dialog_content = "Ambil tanganku, Vice!",
  ui_story_1022_10221002_69_dialog_content = "Aku datang!",
  ui_story_1022_10221002_70_dialog_content = "Vice.",
  ui_story_1022_10221002_71_dialog_content = "(Huh? Apakah aku berhalusinasi, atau aku baru saja mendengar suara Lady Victoria?)",
  ui_story_1022_10221002_72_dialog_content = "Dengarkan aku, Vice.",
  ui_story_1022_10221002_73_dialog_content = "PlayerName akan segera menghadapi ujian paling menantangnya. Dia—",
  ui_story_1022_10221002_74_dialog_content = "<color=#e8d9bb>Suara Victoria terdengar jelas di telinga Vice.</color>",
  ui_story_1022_10221002_75_dialog_content = "!!",
  ui_story_1022_10221002_76_dialog_content = "Apa yang kamu tunggu, Vice?! Kemari sekarang juga!",
  ui_story_1022_10221002_77_dialog_content = "...",
  ui_story_1022_10221002_78_dialog_content = "Kamu lanjutkan dulu, Officer Charon.",
  ui_story_1022_10221002_79_dialog_content = "Aku tinggal di sini.",
  ui_story_1022_10221002_80_dialog_content = "Apa?!",
  ui_story_1022_10221002_81_dialog_content = "PlayerName membutuhkan aku...",
  ui_story_1022_10221002_82_dialog_content = "Dan selama aku di sini, aku tahu aku bisa membantu dia.",
  ui_story_1022_10221002_83_dialog_content = "<color=#FFB400>Vice</color>—!",
  ui_story_1022_10221002_84_dialog_content = "<color=#e8d9bb>Aku ingin berteriak padanya, meraihnya, dan memberitahunya bahwa aku di sini. Aku ingin berada di sisinya, atau setidaknya melihat senyumnya lagi...</color>",
  ui_story_1022_10221002_85_dialog_content = "<color=#e8d9bb>Tapi pandanganku terus menjadi lebih gelap.</color>",
  ui_story_1022_10221002_86_dialog_content = "<color=#e8d9bb>Semakin gelap dan gelap.</color>",
  ui_story_1022_10221002_87_dialog_content = "<color=#e8d9bb>Seperti aku diselimuti oleh malam abadi.</color>",
  ui_story_1022_10221002_88_dialog_content = "<color=#e8d9bb>Tapi satu-satunya sumber cahaya datang dari dirinya.</color>",
  ui_story_1022_10221002_89_dialog_content = "<color=#e8d9bb>Dikelilingi oleh kegelapan yang dingin dan menindas dari semua sisi—</color>",
  ui_story_1022_10221002_90_dialog_content = "<color=#e8d9bb>Cahayanya yang menyilaukan bersinar ke segala arah.</color>",
  ui_story_1022_10221002_91_dialog_content = "<color=#e8d9bb>Seperti matahari yang bersinar melalui malam yang abadi.</color>",
  ui_story_1022_10221002_92_dialog_content = "(Bola Lumina yang aku rasakan sebelumnya... Ternyata itu adalah Vice sejak awal...)",
  ui_story_1022_10221002_93_dialog_content = "(Cahaya dari jiwanya adalah satu-satunya hal yang mencegahku tersesat dalam kegelapan.)",
  ui_story_1022_10221002_94_dialog_content = "(Kalian memanggilku Navigator karena kalian mengandalkan saya untuk membimbing kalian melalui pertempuran terberat kalian...)",
  ui_story_1022_10221002_95_dialog_content = "(Tapi, yang telah membimbingku sepanjang waktu adalah Vice.)",
  ui_story_1022_10221002_96_dialog_content = "(Sejak hari pertama kita bertemu...)",
  ui_story_1022_10221101_1_dialog_content = "… PlayerName.",
  ui_story_1022_10221101_2_dialog_content = "Bangun, PlayerName!",
  ui_story_1022_10221101_3_dialog_content = "Hiiro...",
  ui_story_1022_10221101_4_dialog_content = "... Aku melihatnya, Hiiro! Aku tahu di mana Vice berada! Dia adalah sumber dari Lumina yang aku rasakan sebelumnya, tetapi dia terjebak dalam pilar es raksasa! Kita harus menyelamatkannya!",
  ui_story_1022_10221101_5_dialog_content = "Aku mendengarkan, tetapi sebaiknya kau tenang dulu. Sini, minumlah sedikit air.",
  ui_story_1022_10221101_6_dialog_content = "O-Oke, terima kasih...",
  ui_story_1022_10221101_7_dialog_content = "Aku rasa kamu harus tahu, tapi Victoria sudah pergi. Dia tiba-tiba menghilang beberapa waktu lalu.",
  ui_story_1022_10221101_8_dialog_content = "Menghilang?",
  ui_story_1022_10221101_9_dialog_content = "Ya. Sepertinya Victoria yang kita bicarakan tidak lebih dari sebuah ilusi.",
  ui_story_1022_10221101_10_dialog_content = "*terisak* Kakek! Waaaaahhh—",
  ui_story_1022_10221101_11_dialog_content = "Bagaimana bisa kau mati dan meninggalkan aku sendirian seperti ini?! Jika kau masih ada, <color=#FFB400>wanita jahat</color> itu pasti tidak akan berlaku begitu kasar padaku!",
  ui_story_1022_10221101_12_dialog_content = "Kakek...",
  ui_story_1022_10221101_13_dialog_content = "...",
  ui_story_1022_10221101_14_dialog_content = "Kurasa tak ada gunanya menangisi hal itu lagi. Dia sudah mati, toh.",
  ui_story_1022_10221101_15_dialog_content = "Tapi sekarang aku punya Pepita! Dia lebih peduli padaku daripada siapa pun!",
  ui_story_1022_10221101_16_dialog_content = "Tapi, wanita jahat itu telah membawanya pergi dariku...",
  ui_story_1022_10221101_17_dialog_content = "<size=50>Wahhhhhhhh!</size>",
  ui_story_1022_10221101_18_dialog_content = "Seperti yang sudah aku katakan sebelumnya, kau lah yang mengusir Pepita pergi.",
  ui_story_1022_10221101_19_dialog_content = "Apa?!",
  ui_story_1022_10221101_20_dialog_content = "Apakah benar-benar sulit bagimu untuk menggunakan kepalamu sesekali? Aku mengerti bahwa kamu tidak pernah harus melakukannya, mengingat hak kelahiranmu...",
  ui_story_1022_10221101_21_dialog_content = "Tapi, bahkan pikiran yang tumpul adalah hal yang mengerikan untuk disia-siakan. Tidakkah kamu setuju—",
  ui_story_1022_10221101_22_dialog_content = "<color=#FFB400>Anak perempuan yang telah lama ditinggalkan dari kepala keluarga yang ketiga belas</color>?",
  ui_story_1022_10221101_23_dialog_content = "Bagaimana... Berani-beraninya kau membawa itu ke atas!",
  ui_story_1022_10221101_24_dialog_content = "Idiot! Berani-beraninya kau menawarkan darah kotor semacam itu kepada cucu perempuanku yang berharga!",
  ui_story_1022_10221101_25_dialog_content = "Ursura bisa membedakan antara darah bangsawan dan darah orang biasa yang bodoh! Apakah Anda mencoba membunuhnya dengan tawaran menyedihkan Anda?!",
  ui_story_1022_10221101_26_dialog_content = "M-Maafkan aku, tuanku!",
  ui_story_1022_10221101_27_dialog_content = "Waaaaaaaaaaah!",
  ui_story_1022_10221101_28_dialog_content = "Jangan menangis, sayangku. Kakekmu akan mencarikanmu darah terbaik di dunia.",
  ui_story_1022_10221101_29_dialog_content = "Hanya darah yang paling manis dan lezat yang cocok untuk jenius kecil kesayangan saya...",
  ui_story_1022_10221101_30_dialog_content = "<color=#e8d9bb>Brak! Dengan satu sapuan, setiap potongan peralatan makan jatuh ke lantai dan hancur menjadi serpihan.</color>",
  ui_story_1022_10221101_31_dialog_content = "A-Apa itu, Lady?! Apakah kita telah melakukan sesuatu lagi yang menyinggung Anda?",
  ui_story_1022_10221101_32_dialog_content = "Kamu serius tidak tahu? Kamu hampir tidak membawakan saya \"mangsa\" untuk bermain hari ini! Jika kakek saya masih hidup, kamu tidak akan berani menghina saya seperti ini!",
  ui_story_1022_10221101_33_dialog_content = "T-Tapi Nyonya... Jika kita mengurangi jumlah rakyat jelata terlalu cepat, produksi akan berkurang dan rakyat kita tidak akan memiliki cukup makanan...",
  ui_story_1022_10221101_34_dialog_content = "Kalau begitu, biarkan mereka makan kue, jika mereka begitu lapar! Apakah saya benar-benar harus menjelaskan semuanya untukmu?!",
  ui_story_1022_10221101_35_dialog_content = "T-Tidak, wanitaku... Aku akan segera menyiapkan lebih banyak mangsa.",
  ui_story_1022_10221101_36_dialog_content = "Lari...!!!",
  ui_story_1022_10221101_37_dialog_content = "Hahahaha! Begitu, dong! Permainan berburu selalu lebih menyenangkan ketika ada banyak mangsa!",
  ui_story_1022_10221101_38_dialog_content = "Lari sejauh dan secepat mungkin, kelinci kecil! Dan jangan khawatir...",
  ui_story_1022_10221101_39_dialog_content = "Aku akan pastikan untuk bersenang-senang dengan setiap satu dari kalian.",
  ui_story_1022_10221101_40_dialog_content = "Setiap orang akan mendapat giliran... Aku berjanji.",
  ui_story_1022_10221101_41_dialog_content = "Dulu segalanya begitu indah. Saat itu, setiap orang akan mendengarkanku dan bermain denganku, tanpa ada pertanyaan...",
  ui_story_1022_10221101_42_dialog_content = "Tapi tidak lagi. Semuanya sudah hilang sekarang... Dan semua ini gara-gara kau, sampah Varaki!",
  ui_story_1022_10221101_43_dialog_content = "Berkat kamu, saya tidak punya pilihan selain mundur ke Eclipse, di mana yang bisa saya lakukan hanyalah tidur, tidur, tidur. Tidak ada yang mendengarkan saya, atau bahkan peduli tentang saya, untuk urusan itu...",
  ui_story_1022_10221101_44_dialog_content = "Ini semua salahmu!!",
  ui_story_1022_10221101_45_dialog_content = "Menyalahkan orang lain lagi, saya lihat?",
  ui_story_1022_10221101_46_dialog_content = "Alasan kamu diasingkan adalah karena tirani dan pengkhianatanmu.",
  ui_story_1022_10221101_47_dialog_content = "Kaulah yang memimpin pasukan Eclipsite ke Varaki Town, membunuh tak terhitung banyaknya penganut yang tidak bersalah dan melarikan diri dengan relik suci True Order. Bab berdarah dalam sejarah Varaki itu ditulis oleh tidak ada yang lain kecuali dirimu sendiri.",
  ui_story_1022_10221101_48_dialog_content = "Jadi ketika saya membuka-buka halaman berdebu dari sejarah keluarga kita, saya terkejut menemukan betapa besarnya dosa-dosa Anda...",
  ui_story_1022_10221101_49_dialog_content = "Diam! Cukup diam saja! Apa yang salah dengan membunuh beberapa Aurorian saja? Bukannya kamu juga pernah melakukan hal yang sama, bukan?!",
  ui_story_1022_10221101_50_dialog_content = "Tak ada yang membuat kakekku lebih bahagia selain melihatku bahagia... Tapi kemudian kamu semua harus merusaknya!",
  ui_story_1022_10221101_51_dialog_content = "Jangan berpikir kamu bisa mengajariku hanya karena kamu adalah kepala keluarga...",
  ui_story_1022_10221101_52_dialog_content = "Selama aku terbakar secerah mungkin... Lalu apa salahnya dengan mati?",
  ui_story_1022_10221101_53_dialog_content = "Aku bukan hewan peliharaan siapa pun, dan aku tidak akan pernah menyerah kepada siapa pun...",
  ui_story_1022_10221101_54_dialog_content = "<color=#FFB400>Aku... Milik diriku sendiri!</color>",
  ui_story_1022_10221101_55_dialog_content = "... Aku milik diriku sendiri! Aku tak akan pernah mendengarkanmu atau siapa pun!",
  ui_story_1022_10221101_56_dialog_content = "Betapa konyolnya penyalahgunaan credo Pepita. Jika dia ada di sini sekarang, dia pasti akan meneteskan air mata tawa.",
  ui_story_1022_10221101_57_dialog_content = "Jangan berani-berani menyebut-nyebut dia!!!",
  ui_story_1022_10221101_58_dialog_content = "<color=#e8d9bb>Saat Ursura berteriak liar, Darkflow yang tebal mulai meletus di sekelilingnya. </color>",
  ui_story_1022_10221101_59_dialog_content = "<color=#e8d9bb>Ini mengelilinginya dan bergolak keluar ke setiap arah, merayap secara mengancam di atas es yang telah gelap.</color>",
  ui_story_1022_10221101_60_dialog_content = "<color=#e8d9bb>Tak terhitung kuncup bunga muncul dari es, berderak dan bercabang saat mereka membentuk gugus karang yang besar dan bengkok.</color>",
  ui_story_1022_10221101_61_dialog_content = "<color=#e8d9bb>Terumbu karang mulai berjalin-jalin secara mengerikan, seperti urat-urat monster raksasa.</color>",
  ui_story_1022_10221101_62_dialog_content = "<color=#e8d9bb>Duk-duk.</color>",
  ui_story_1022_10221101_63_dialog_content = "<color=#e8d9bb>Hutan karang yang merupakan entitas hidup sendiri, berdenyut seirama dengan detak jantung di tengah kabut hitam yang bergolak.</color>",
  ui_story_1022_10221101_64_dialog_content = "<color=#e8d9bb>Dengan setiap detak jantung, lebih banyak lagi Darkflow kental yang mengalir keluar, merusak kehidupan setiap Aurorian di sekitarnya.</color>",
  ui_story_1022_10221101_65_dialog_content = "Graaagh—!!!",
  ui_story_1022_10221102_1_dialog_content = "<color=#e8d9bb>Krak!</color>",
  ui_story_1022_10221102_2_dialog_content = "<color=#e8d9bb>Victoria akhirnya berhasil menembus cangkang Aliran Gelap yang tebal milik Ursura, meskipun tidak tanpa membayar harga.</color>",
  ui_story_1022_10221102_3_dialog_content = "Batuk—!",
  ui_story_1022_10221102_4_dialog_content = "Ha... Hahaha! Apakah itu semua yang bisa kamu lakukan, Nona Kepala Rumah?!",
  ui_story_1022_10221102_5_dialog_content = "Dengan sedikit usaha ekstra, aku bisa dengan mudah membuatmu berlutut!",
  ui_story_1022_10221102_6_dialog_content = "Saya rasa itu masuk akal. Setelah semua, saya terbangun ke kekuatan garis keturunan saya ketika saya masih gadis kecil yang sangat muda. Bahkan kakek saya mengatakan belum pernah ada jenius seperti saya sebelumnya!",
  ui_story_1022_10221102_7_dialog_content = "Tapi bagaimana denganmu, nenek tua? Dari yang aku lihat, kamu tidak menyadari kekuatanmu sampai hidupmu sudah setengah berlalu! Hahahahaha!",
  ui_story_1022_10221102_8_dialog_content = "... Heh.",
  ui_story_1022_10221102_9_dialog_content = "Apanya yang lucu?",
  ui_story_1022_10221102_10_dialog_content = "Aku terbangun ke kekuatanku lebih awal dari siapa pun dalam sejarah keluarga kami! Itu membuatku yang paling murni dan berbakat dari jenis kami! Kamu tidak pernah berharap bisa dibandingkan denganku!",
  ui_story_1022_10221102_11_dialog_content = "Pada titik ini, kamu mungkin juga membuat saya menjadi kepala rumahmu! Hahaha—",
  ui_story_1022_10221102_12_dialog_content = "<color=#e8d9bb>Tawa gila Ursura tiba-tiba berhenti.</color>",
  ui_story_1022_10221102_13_dialog_content = "<color=#e8d9bb>Dengan tatapan bingung yang mengerikan, dia menyaksikan luka-luka Victoria cepat sembuh satu per satu. Bahkan pakaian yang robek pun kembali ke keadaan semula.</color>",
  ui_story_1022_10221102_14_dialog_content = "T-Tapi bagaimana...?!",
  ui_story_1022_10221102_15_dialog_content = "Apakah kau benar-benar terkejut dengan ini? Aku mengira seorang jenius sepertimu pasti sudah bisa melihat melalui teknikku sekarang.",
  ui_story_1022_10221102_16_dialog_content = "Kamu... Kamu menyimpan sebagian besar kekuatanmu di tempat lain, bukan?! Apa sebenarnya yang sedang kamu lakukan?!",
  ui_story_1022_10221102_17_dialog_content = "Setelah menceburkan kedua orang itu ke kedalaman Sungai Pristine, sangat wajar bagi saya untuk tinggal dan mengawasi mereka. Dark Zone adalah tempat yang berbahaya, setelah semua.",
  ui_story_1022_10221102_18_dialog_content = "Jika kamu tidak menyimpang jauh dari jalan Truth... Tuhan kita juga akan melindungimu.",
  ui_story_1022_10221102_19_dialog_content = "Mustahil... Tidak mungkin kamu memiliki cukup kekuatan untuk melawan saya dan menjaga orang lain pada saat yang sama!",
  ui_story_1022_10221102_20_dialog_content = "Aku yang terkuat... Aku telah menyadari kekuatanku jauh lebih awal dari orang lain! Kekuatanku adalah yang paling murni, dan potensiku tak terbatas... P-Pasti ada trik tertentu dalam kekuatanmu! Pasti ada!",
  ui_story_1022_10221102_21_dialog_content = "Apakah itu satu-satunya penjelasan yang bisa kamu berikan? Sepertinya kamu terbangun dari kekuatanmu <color=#FFB400>terlalu dini</color>.",
  ui_story_1022_10221102_22_dialog_content = "Apa?",
  ui_story_1022_10221102_23_dialog_content = "Kebangkitanmu terlalu dini, yang membuatmu sombong dan sangat naif. Tidak satupun kali kamu mencoba untuk mengembangkan kekuatanmu melalui pemikiran atau latihan.",
  ui_story_1022_10221102_24_dialog_content = "Tidak ada yang bisa menyangkal kekuatanmu, Ursura. Kamu mewakili hasrat paling dasar dan tak terpuaskan dari jenis kita.",
  ui_story_1022_10221102_25_dialog_content = "Saya, sebaliknya, adalah kebalikan tepat dari kamu.",
  ui_story_1022_10221102_26_dialog_content = "A-Apa maksudnya itu...?",
  ui_story_1022_10221102_27_dialog_content = "Aku membangkitkan kekuatanku jauh lebih lambat daripada kamu.",
  ui_story_1022_10221102_28_dialog_content = "Untuk memahami Kebenaran, aku telah melakukan perjalanan melintasi lebar dan panjang tanah ini, merenungkan semua yang telah aku saksikan.",
  ui_story_1022_10221102_29_dialog_content = "Ini adalah perjalanan yang belum pernah kamu alami dan tidak akan pernah alami lagi.",
  ui_story_1022_10221102_30_dialog_content = "Dan karena metode saya tidak dimengerti olehmu... Saya hanya bisa meminta kamu untuk menggunakan imajinasimu.",
  ui_story_1022_10221102_31_dialog_content = "Setelah semua... Kamu tidak akan pernah bisa mengerti.",
  ui_story_1022_10221102_32_dialog_content = "D-Diam! Aku yang terkuat, bukan kamu...!",
  ui_story_1022_10221102_33_dialog_content = "<color=#e8d9bb>Teriakan marah Ursura tidak cukup untuk menekan rasa takut di hatinya. Sepanjang hidupnya, dia diberitahu bahwa dia adalah jenius di antara para jenius.</color>",
  ui_story_1022_10221102_34_dialog_content = "<color=#e8d9bb>Namun, pengungkapan mendadak ini menjadi pukulan yang sangat mengejutkan bagi hatinya, pikirannya, dan indranya—</color>",
  ui_story_1022_10221102_35_dialog_content = "<color=#FFB400>Pesan</color>...",
  ui_story_1022_10221102_36_dialog_content = "<color=#e8d9bb>Ini adalah puncaknya, alam tertinggi yang diidamkan oleh semua Aurorian yang mencari Kebenaran.</color>",
  ui_story_1022_10221102_37_dialog_content = "<color=#e8d9bb>Melalui penyelidikan yang tulus, ia menggantikan setiap keinginan murni dan primitif. Sebuah himne pengagungan yang didedikasikan untuk Truth.</color>",
  ui_story_1022_10221102_38_dialog_content = "Jawaban yang luar biasa, Ursura. Sekarang, saatnya untuk mempraktikkannya.",
  ui_story_1022_10221102_39_dialog_content = "Saksikan teknik rahasiaku. Perhatikan dengan saksama, dan jangan berpaling.",
  ui_story_1022_10221102_40_dialog_content = "Ziarah ini, saya tawarkan kepada tuanku—",
  ui_story_1022_10221102_41_dialog_content = "Waaaahhhh—!",
  ui_story_1022_10221102_42_dialog_content = "Kenapa? Kenapa?! Tanda dari Eclipse diberikan kepada saya sudah lama, jadi kenapa...",
  ui_story_1022_10221102_43_dialog_content = "... Mengapa aku menjadi Aurorian lagi?!",
  ui_story_1022_10221102_44_dialog_content = "Tidak... Tolong... Aku tidak ingin mati... Aku tidak ingin menghilang...",
  ui_story_1022_10221102_45_dialog_content = "Tidaaaak!!!",
  ui_story_1022_10221102_46_dialog_content = "Teknik yang mengerikan... Aku mengerti sekarang. Jadi ini adalah ide penebusanmu.",
  ui_story_1022_10221102_47_dialog_content = "Dengan menyangkal hal yang tak berwujud, apakah Anda berniat menawarkan hanya esensi murni kepada tuan dari semua kesadaran?",
  ui_story_1022_10221102_48_dialog_content = "Tidak... Yang seharusnya benar-benar ditakuti adalah kamu, Victoria.",
  ui_story_1022_10221102_49_dialog_content = "Kekuatanmu adalah sesuatu yang bahkan aku rindu untuk mengendalikan sekali lagi. Apakah tidak ada yang ada di luar pandanganmu?",
  ui_story_1022_10221102_50_dialog_content = "<color=#e8d9bb>Sungai berwarna pelangi ini berliku dan mengalir sepanjang masa. Dalam airnya, waktu tidak memiliki arti.</color>",
  ui_story_1022_10221102_51_dialog_content = "<color=#e8d9bb>Bahkan sekarang, tak terhitung masa lalu dan masa depan menata diri mereka secara setara di hadapan Recluse, termasuk realitas paralel mereka.</color>",
  ui_story_1022_10221102_52_dialog_content = "Tapi hampir tak ada artinya sekarang... Ayo.",
  ui_story_1022_10221102_53_dialog_content = "<color=#e8d9bb>Dengan tepukan tangannya, Recluse membuka celah di ruang, dan kereta berbahan bakar uap muncul terbang dari kekosongan.</color>",
  ui_story_1022_10221102_54_dialog_content = "Aaaahhhh—",
  ui_story_1022_10221102_55_dialog_content = "Keheningan. Dalam kesendirianku, telingaku telah tidak biasa mendengar teriakan orang lain.",
  ui_story_1022_10221102_56_dialog_content = "Bukan sungai sialan ini lagi! Dan siapa kau?! Tunggu... Aku pernah melihatmu sebelumnya.",
  ui_story_1022_10221102_57_dialog_content = "Kamu adalah... Sepupu ayahku yang telah lama meninggal, serta paman Victoria... <color=#FFB400>Wilhelm Varaki</color>.",
  ui_story_1022_10221102_58_dialog_content = "Kamu juga bisa memanggilku sebagai pamanmu, tahu.",
  ui_story_1022_10221102_59_dialog_content = "Ya, maafkan saya karena tidak ingin membahas ikatan keluarga dengan seorang pria yang sudah meninggal, terutama dalam situasi aneh yang kita alami sekarang ini.",
  ui_story_1022_10221102_60_dialog_content = "... Kamu sama menjengkelkannya dan bertele-tele seperti Victoria.",
  ui_story_1022_10221102_61_dialog_content = "Apa itu? Asal kamu tahu, pidatoku yang fasih itu tidak seperti omelan fanatik wanita itu!",
  ui_story_1022_10221102_62_dialog_content = "Pertama putri kakakku, sekarang kamu... Mungkin saya harus mengubah lambang keluarga kita untuk mencakup buaian dan dot?",
  ui_story_1022_10221102_63_dialog_content = "Namamu adalah Charon, jika aku tidak salah? Katakan padaku, apakah kamu tahu mengapa kamu di sini?",
  ui_story_1022_10221102_64_dialog_content = "Apakah Anda mengatakan ini bukan ulahmu?",
  ui_story_1022_10221102_65_dialog_content = "Victoria berharap kamu bisa mempertajam teknikmu bersamaku, dan memahami lebih jauh tentang Truth. Dia melihat banyak potensi tersembunyi dalam dirimu.",
  ui_story_1022_10221102_66_dialog_content = "Apa?! Aku sudah bilang pada penyihir itu bahwa aku tidak ingin ada hubungan dengan dia atau apa yang dia sebut sebagai Kebenaran!",
  ui_story_1022_10221102_67_dialog_content = "Dan kamu jelas tidak tertarik pada saat itu, bukan.",
  ui_story_1022_10221102_68_dialog_content = "Tapi waktu telah berlalu, dan kamu bukan lagi orang yang dulu kamu jadi. Katakan padaku, apa pikiranmu sekarang?",
  ui_story_1022_10221102_69_dialog_content = "Aku…",
  ui_story_1022_10221102_70_dialog_content = "<color=#e8d9bb>\"Tentu saja aku masih tidak tertarik!\" Kata-kata itu hampir terbentuk di mulut Charon.</color>",
  ui_story_1022_10221102_71_dialog_content = "<color=#e8d9bb>Tapi tiba-tiba, bayangan Vice yang membeku dalam tiang es muncul dalam pikirannya. Dia ingat bahwa bawahannya masih dikelilingi oleh Eclipsite di tempat yang malamnya abadi.</color>",
  ui_story_1022_10221102_72_dialog_content = "<color=#e8d9bb>Dia memilih untuk tinggal di sana demi Caelestite, yang berarti dia mungkin dalam bahaya besar. Secara tidak langsung, ini berarti bahwa kawan-kawannya dari Illumina juga dalam bahaya.</color>",
  ui_story_1022_10221102_73_dialog_content = "<color=#e8d9bb>Dalam keadaan ini...</color>",
  ui_story_1022_10221102_74_dialog_content = "... Mungkin ini akhirnya saatnya bagi saya untuk melampaui fase pemberontakan saya.",
  ui_story_1022_10221102_75_dialog_content = "Hmph, setidaknya kamu sadar akan keras kepalamu sendiri, yang berarti masih ada harapan untukmu... Tidak seperti beberapa orang.",
  ui_story_1022_10221102_76_dialog_content = "Tapi untungnya, kali ini aku tidak perlu membahayakan nyawaku sendiri yang tidak ada. Benar bukan?",
  ui_story_1022_10221200_1_dialog_content = "...",
  ui_story_1022_10221200_2_dialog_content = "(Gua... Itu benar. Saya berhasil mundur sampai ke tempat perkemahan pertama kami sebelum saya pingsan karena kelelahan.)",
  ui_story_1022_10221200_3_dialog_content = "(Lady Victoria kemungkinan besar pergi mengejar Ursura. Aku harus menemukannya...)",
  ui_story_1022_10221200_4_dialog_content = "Sial semua! Target kita dan kitab yang dicuri tepat di depan kita, dan kita masih melewatkan kesempatan kita!",
  ui_story_1022_10221200_5_dialog_content = "(Uh-oh, apa yang dia lakukan di sini? Untungnya aku tidak terburu-buru untuk pergi.)",
  ui_story_1022_10221200_6_dialog_content = "Tolong jangan bergerak terlalu banyak, Kapten. Anda akan membuka kembali luka Anda.",
  ui_story_1022_10221200_7_dialog_content = "(Erica... Dia tampak sangat khawatir saat melihat lukaku tadi.)",
  ui_story_1022_10221200_8_dialog_content = "Aku baik-baik saja, Erica! Lagipula, aku lebih khawatir dengan apa yang dilakukan tamu yang tidak diundang ini di sini.",
  ui_story_1022_10221200_9_dialog_content = "Bukankah kamu menerima pesan kami? Saya telah dikirim untuk membantu kamu.",
  ui_story_1022_10221200_10_dialog_content = "(Ada orang lain di sini? Saya bahkan tidak menyadari mereka...)",
  ui_story_1022_10221200_11_dialog_content = "\"Membantu kami,\" kata kamu? Seluruh tim kami telah Pepita mengepung, dan dia masih bisa kabur! Bagaimana mungkin kamu bisa membantu kami sekarang?!",
  ui_story_1022_10221200_12_dialog_content = "(Mereka sedang membicarakan saya, hah?)",
  ui_story_1022_10221200_13_dialog_content = "Tentu saja, dengan menggunakan metode yang tak bisa gagal untuk menangkapnya.",
  ui_story_1022_10221200_14_dialog_content = "Tolong ambil ini.",
  ui_story_1022_10221200_15_dialog_content = "Remote control? Apa yang coba kamu katakan, bahwa ini bisa mengungkapkan lokasinya dengan sekali tekan tombol?!",
  ui_story_1022_10221200_16_dialog_content = "Tepat sekali.",
  ui_story_1022_10221200_17_dialog_content = "... Kamu bercanda.",
  ui_story_1022_10221200_18_dialog_content = "Sama sekali tidak. Yang kamu sebut sebagai \"remote control\" sebenarnya adalah langkah pengendalian yang ditempatkan oleh Belisaria tahun yang lalu.",
  ui_story_1022_10221200_19_dialog_content = "Dengan itu, kamu bisa mengendalikan detak jantung buatan yang berdetak di dada Pepita.",
  ui_story_1022_10221200_20_dialog_content = "!!",
  ui_story_1022_10221200_21_dialog_content = "Hati Pepita... Apakah buatan?",
  ui_story_1022_10221200_22_dialog_content = "Dan tombol spesifik ini bisa digunakan untuk mematikan jantungnya sepenuhnya. Aku tidak perlu menjelaskan apa yang terjadi setelah itu... Benar?",
  ui_story_1022_10221200_23_dialog_content = "Menggunakan fungsi ini untuk menemukannya hampir tidak ada kegagalannya, setuju kah kamu?",
  ui_story_1022_10221200_24_dialog_content = "Apa kau gila?! Itu tidak berbeda dengan membunuhnya!",
  ui_story_1022_10221200_25_dialog_content = "Mengambil nyawa hanya dianggap pembunuhan ketika korban adalah orang yang tidak bersalah.",
  ui_story_1022_10221200_26_dialog_content = "Tapi ketika korban adalah penjahat buronan... Maka, itu menjadi sebuah eksekusi.",
  ui_story_1022_10221200_27_dialog_content = "Apakah benar-benar ada perbedaan antara keduanya...?",
  ui_story_1022_10221200_28_dialog_content = "Ketika Pepita pertama kali mengkhianati Illumina, Belisaria memegang alat yang sama persis ini di tangannya pada hari itu.",
  ui_story_1022_10221200_29_dialog_content = "Tapi meskipun dia melihat pelaku pidana melarikan diri dengan kedua matanya sendiri, dia tidak bisa membawa dirinya untuk menekan tombol itu. Itu... Sungguh kecewa.",
  ui_story_1022_10221200_30_dialog_content = "(Belisaria...)",
  ui_story_1022_10221200_31_dialog_content = "Tapi, aku percaya kamu berbeda dari yang disebut \"Iron Lady.\"",
  ui_story_1022_10221200_32_dialog_content = "Kebencianmu terhadap para penjahat Lumopolis adalah nyata.",
  ui_story_1022_10221200_33_dialog_content = "Aku…",
  ui_story_1022_10221200_34_dialog_content = "Jangan lakukan itu, Kapten!",
  ui_story_1022_10221200_35_dialog_content = "Ini... Ini bukan cara yang benar! Pepita mungkin telah melakukan beberapa kejahatan, tetapi itu tidak membuatnya menjadi orang jahat!",
  ui_story_1022_10221200_36_dialog_content = "Sebagai jiwa yang sejenis, aku bisa melihatnya di matanya setiap kali kita berhadapan.",
  ui_story_1022_10221200_37_dialog_content = "Kita semua bersalah karena membuat kesalahan sepanjang hidup kita... Ajaran God of Light memberitahu kita sebanyak itu! Tapi bahkan orang yang paling bersalah pun pantas mendapatkan kesempatan untuk penebusan!",
  ui_story_1022_10221200_38_dialog_content = "Erica...!",
  ui_story_1022_10221200_39_dialog_content = "Siapa di sana?!",
  ui_story_1022_10221200_40_dialog_content = "P-Pepita?! Kapan kamu—",
  ui_story_1022_10221200_41_dialog_content = "Er, maaf, saya pikir kamu salah mengira saya sebagai orang lain. D-Jangan pedulikan saya, lanjutkan saja percakapanmu!",
  ui_story_1022_10221200_42_dialog_content = "... Setelah dia!",
  ui_story_1022_10221200_43_dialog_content = "Tunggu, Pepita! Jangan pergi!",
  ui_story_1022_10221200_44_dialog_content = "Beritahu kaptenmu untuk menyerahkan remote itu terlebih dahulu!",
  ui_story_1022_10221200_45_dialog_content = "Percayalah padaku, Pepita! Aku tidak akan membiarkan mereka menyakitimu, jadi—",
  ui_story_1022_10221200_46_dialog_content = "Yeah benar! Bicara padaku saat kamu berpangkat di atas kapten gila milikmu itu!",
  ui_story_1022_10221200_47_dialog_content = "Hanya dengarkan, Pepita! Kamu sedang berlari menuju—",
  ui_story_1022_10221200_48_dialog_content = "Berhenti! Aku tidak akan berhenti untuk apa pun—A-Whoa!",
  ui_story_1022_10221200_49_dialog_content = "<color=#e8d9bb>Sebuah hembusan angin dingin tiba-tiba hampir menumbangkan Pepita ke tanah.</color>",
  ui_story_1022_10221200_50_dialog_content = "<color=#e8d9bb>Beberapa langkah lagi, dan dia akan jatuh terjerembab ke dalam jurang yang menganga dan tak berdasar.</color>",
  ui_story_1022_10221200_51_dialog_content = "Pepita! Kamu baik-baik saja?!",
  ui_story_1022_10221200_52_dialog_content = "... Jangan mendekat.",
  ui_story_1022_10221200_53_dialog_content = "Baiklah, aku tidak akan, tapi tolong dengarkan aku saja!",
  ui_story_1022_10221200_54_dialog_content = "City Lord telah setuju untuk tidak menghukummu selama kamu menceritakan semua yang kamu ketahui tentang kitab kami yang hilang. Jika kamu melakukan itu, aku berjanji—",
  ui_story_1022_10221200_55_dialog_content = "Apakah kamu yang membuat janji, ataukah itu City Lord?",
  ui_story_1022_10221200_56_dialog_content = "Aku…",
  ui_story_1022_10221200_57_dialog_content = "Kamu tidak bisa menjanjikan apa-apa, bukan? Yang bisa kamu lakukan hanyalah berharap bahwa Tuan Kota yang berharga bagi kamu ini menepati janjinya!",
  ui_story_1022_10221200_58_dialog_content = "Terima kasih, tapi tidak, terima kasih! Saya tidak berniat untuk bertahan hidup, berkat belas kasihan yang disebut-sebut oleh tuanmu.",
  ui_story_1022_10221200_59_dialog_content = "<color=#FFB400>Jika aku tidak bebas, aku lebih memilih mati!</color>",
  ui_story_1022_10221200_60_dialog_content = "<color=#e8d9bb>Tanpa ragu sejenak, Pepita berbalik dan melompat dari tepi tebing.</color>",
  ui_story_1022_10221200_61_dialog_content = "Pepita!!!",
  ui_story_1022_10221200_62_dialog_content = "<color=#e8d9bb>Erica berlari ke tepi jurang, tetapi tidak melihat tanda-tanda Pepita di kabut yang berputar di bawah.</color>",
  ui_story_1022_10221200_63_dialog_content = "...",
  ui_story_1022_10221200_64_dialog_content = "*hela nafas* Orang lain lagi yang tidak mampu menekan tombol itu.",
  ui_story_1022_10221200_65_dialog_content = "Itu kedua kalinya aku membuat pilihan yang salah. Sepertinya aku harus sedikit merenung tentang diriku sendiri.",
  ui_story_1022_10221200_66_dialog_content = "... Erica benar. Dia adalah seorang pidana, tetapi itu tidak berarti dia pantas mati. Aku... Aku tidak akan pernah mengambil nyawa seseorang untuk alasan egois ku sendiri!",
  ui_story_1022_10221200_67_dialog_content = "Kamu... Siapa sebenarnya kamu ini?",
  ui_story_1022_10221200_68_dialog_content = "Rasa ingin tahu Anda melebihi kebodohan Anda, kapten. Apakah setiap orang di Divisi Investigasi Bidat Lumopolis seperti ini?",
  ui_story_1022_10221200_69_dialog_content = "Pepita bukan lagi urusanmu.",
  ui_story_1022_10221200_70_dialog_content = "Masalah ini sekarang ada di tangan <color=#FFB400>Eksekutor</color> Illumina.",
  ui_story_1022_10221200_71_dialog_content = "<color=#e8d9bb>Jauh di dalam Dark Zone, kilatan petir yang kuat berkedip sebelum pintu masuk sebuah gua tertentu.</color>",
  ui_story_1022_10221200_72_dialog_content = "Apa yang terjadi...? Kapan saya... Tunggu. Apakah saya dikirim kembali?!",
  ui_story_1022_10221200_73_dialog_content = "Langit hitam, dingin yang menusuk, Aliran Gelap yang padat... Dan Eclipse! Aku benar-benar kembali! Oh terima kasih, terima kasih banyak...",
  ui_story_1022_10221200_74_dialog_content = "Setidaknya kamu memiliki kesopanan untuk berterima kasih kepada tuan kita karena telah membawamu kembali, Figerald.",
  ui_story_1022_10221200_75_dialog_content = "...",
  ui_story_1022_10221200_76_dialog_content = "Oh bagus, kalian juga di sini.",
  ui_story_1022_10221200_77_dialog_content = "Betul, dan kamu tentu telah membuat kami menunggu. Jika kamu memiliki sedikit pun bakat, waktu kami tidak akan terbuang sia-sia.",
  ui_story_1022_10221200_78_dialog_content = "Wah, itu adalah beberapa kata yang menyakitkan, Asmodeus. Aku adalah orang yang berlari terlebih dahulu ke medan pertempuran untuk tuan kita, tapi apa yang telah kamu lakukan untuknya?",
  ui_story_1022_10221200_79_dialog_content = "Karena saya akan menyerbu Kota Gannon lagi tanpa berpikir dua kali, jika itu yang dia inginkan saya lakukan.",
  ui_story_1022_10221200_80_dialog_content = "Maka anggaplah dirimu beruntung karena memiliki setidaknya satu kualitas yang menebus, Figerald.",
  ui_story_1022_10221200_81_dialog_content = "... Maksudnya apa?",
  ui_story_1022_10221200_82_dialog_content = "Dan apa yang dia lakukan di sini sebenarnya? Ini adalah pertemuan dari Delapan Hantu-hantu, jadi di mana dia masuk?",
  ui_story_1022_10221200_83_dialog_content = "...",
  ui_story_1022_10221200_84_dialog_content = "Maksudmu kamu tidak tahu? Di Eclipse, hanya ada satu jalan untuk naik pangkat.",
  ui_story_1022_10221200_85_dialog_content = "Agar seseorang bisa naik, orang yang di atas mereka harus hilang terlebih dahulu.",
  ui_story_1022_10221200_86_dialog_content = "Selalu ada delapan Hantu di Eclipse. Bukan tujuh, bukan sembilan, tetapi delapan.",
  ui_story_1022_10221200_87_dialog_content = "Apa-apaan yang sedang kamu bicarakan? Cukup beri tahu aku mengapa Forsakin di sini!",
  ui_story_1022_10221200_88_dialog_content = "Seorang jenderal yang bodoh tidak memerlukan prajurit yang licik. Prestasi Forsakin jauh melampaui prestasi Anda sendiri.",
  ui_story_1022_10221200_89_dialog_content = "<color=#FFB400>Ascension</color> hanyalah hadiah yang pantas untuk usahanya.",
  ui_story_1022_10221200_90_dialog_content = "!!!",
  ui_story_1022_10221200_91_dialog_content = "A-Apa ini?! Siapa di antara kalian yang mengikatku seperti ini?! Lepaskan aku sekarang juga!!!",
  ui_story_1022_10221200_92_dialog_content = "... Aku tidak ingin melihat apa yang terjadi selanjutnya. Aku akan masuk ke dalam.",
  ui_story_1022_10221200_93_dialog_content = "Hmph, saya juga tidak punya alasan untuk tinggal. Selesaikan cepat dan masuklah, Forsakin. Rapat akan segera dimulai.",
  ui_story_1022_10221200_94_dialog_content = "...",
  ui_story_1022_10221200_95_dialog_content = "...",
  ui_story_1022_10221200_96_dialog_content = "Ha... Hahahaha! Cincang dia menjadi serpihan, minionku!",
  ui_story_1022_10221200_97_dialog_content = "Graaah!",
  ui_story_1022_10221200_98_dialog_content = "...",
  ui_story_1022_10221200_99_dialog_content = "Kamu telah menjadi lebih kuat... Tapi apakah kamu cukup kuat untuk ini? Apakah kamu benar-benar berani melaluinya?",
  ui_story_1022_10221200_100_dialog_content = "Karena jika kamu memakan saya sekarang, itu hanya berarti seseorang lain akan memakanmu di masa depan...",
  ui_story_1022_10221200_101_dialog_content = "Hari ketika Eclipsite yang lebih kuat dan dihormati muncul... Akan menjadi hari mereka menjadikanmu santapan.",
  ui_story_1022_10221200_102_dialog_content = "Apakah kamu cukup berani untuk pergi sejauh itu? Karena tidak ada jalan untuk kembali setelah kamu melakukannya.",
  ui_story_1022_10221200_103_dialog_content = "... Di dalam hatimu, kamu masih berpikir bahwa kamu adalah seorang Aurorian, bukan?!",
  ui_story_1022_10221200_104_dialog_content = "...",
  ui_story_1022_10221200_105_dialog_content = "Sudah selesai belum?",
  ui_story_1022_10221200_106_dialog_content = "... Aku tidak merasakan gerakan Ursura lagi.",
  ui_story_1022_10221200_107_dialog_content = "Oh, begitu. Dia tetap membuktikan dirinya berguna pada akhirnya. Berkat dia, kita bisa melihat teknik rahasia orang itu.",
  ui_story_1022_10221200_108_dialog_content = "Babak utama dimulai sekarang.",
  ui_story_1022_10221200_109_dialog_content = "... Dia disini.",
  ui_story_1022_10221200_110_dialog_content = "Hmm?",
  ui_story_1022_10221200_111_dialog_content = "<color=#e8d9bb>Sosok muncul dari bayangan, menarik perhatian setiap orang.</color>",
  ui_story_1022_10221200_112_dialog_content = "...",
  ui_story_1022_10221200_113_dialog_content = "Heheh, seperti yang diharapkan dari anggota baru kita yang berbakat... Saya percaya kamu akan jauh lebih baik daripada Figerald yang pernah ada.",
  ui_story_1022_10221200_114_dialog_content = "Tidak, Asmodeus... Itu Ursura. Dia ada di sini.",
  ui_story_1022_10221200_115_dialog_content = "...",
  ui_story_1022_10221200_116_dialog_content = "<color=#FFB400>Substansi X</color> telah diekstraksi dari dirinya, dan jantung serta tubuhnya hampir hancur... Namun dia masih hidup. Dan tidak hanya itu, dia juga perlahan pulih.",
  ui_story_1022_10221200_117_dialog_content = "Apakah karena garis keturunan aslinya? Esensinya sudah pernah terkontaminasi menjadi <color=#FFB400>Substansi N</color> yang tidak murni.",
  ui_story_1022_10221200_118_dialog_content = "Meski sifat tak berwujudnya diambil, dia masih bertahan hidup.",
  ui_story_1022_10221200_119_dialog_content = "Selama cabang karang yang dia ciptakan dikembalikan kepadanya, sifatnya yang tidak berwujud... Kekuatan <color=#FFB400>X</color> juga akan kembali padanya, dan hatinya akan berdetak sekali lagi.",
  ui_story_1022_10221200_120_dialog_content = "<color=#e8d9bb>Ciit, ciit, ciit!</color>",
  ui_story_1022_10221200_121_dialog_content = "Tenanglah, Petey. Aku hanya ingin tidur sedikit lebih lama...",
  ui_story_1022_10221200_122_dialog_content = "P-Petey?!",
  ui_story_1022_10221200_123_dialog_content = "Apakah kamu yang menyelamatkanku? Tapi kenapa kamu lari? Dan bagaimana dengan Ursura? Dia... Dia tidak mati, bukan?!",
  ui_story_1022_10221200_124_dialog_content = "Te-Tenanglah, Pepita. Jika Petey masih hidup, berarti Ursura juga pasti. Tapi jika Petey ada di sini sekarang, itu juga berarti dia dalam masalah besar...",
  ui_story_1022_10221200_125_dialog_content = "... Tunggu, kenapa aku masih khawatir tentang dia?!",
  ui_story_1022_10221200_126_dialog_content = "Oh, siapa yang aku tipu? Pencari masalah pemberani seperti kita... Kita seolah-olah diciptakan untuk satu sama lain.",
  ui_story_1022_10221200_127_dialog_content = "<color=#e8d9bb>Entah kenapa, Petey melilitkan dirinya di kaki Pepita dan mulai mencicit dengan panik.</color>",
  ui_story_1022_10221200_128_dialog_content = "Ya, ya, aku tahu kamu khawatir tentang tuanmu... Tunggu, kamu tidak khawatir? Lalu apa yang kamu—Bwaaaaa!!!",
  ui_story_1022_10221200_129_dialog_content = "<color=#e8d9bb>Sebuah retakan di ruang terbuka di atas Pepita, dan sebuah kereta meluncur keluar dari itu dengan kecepatan penuh.</color>",
  ui_story_1022_10221200_130_dialog_content = "Se-s-sebuah kereta?!?",
  ui_story_1022_10221200_131_dialog_content = "Zona Gelap adalah tempat yang dingin dan sepi. Seorang konduktor mulia seperti saya tidak akan pernah meninggalkan Aurorian yang kesepian di tanah kematian yang beku ini.",
  ui_story_1022_10221200_132_dialog_content = "Nah, nona? Apakah Anda ingin naik kereta paling spektakuler yang ada?"
}
return config
